--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


ALTER FUNCTION extensions.grant_pg_cron_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


ALTER FUNCTION extensions.grant_pg_graphql_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
    ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

    ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
    ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

    REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
    REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

    GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
  END IF;
END;
$$;


ALTER FUNCTION extensions.grant_pg_net_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_ddl_watch() OWNER TO supabase_admin;

--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_drop_watch() OWNER TO supabase_admin;

--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


ALTER FUNCTION extensions.set_graphql_placeholder() OWNER TO supabase_admin;

--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: activate_whatsapp_webhook_session_cutover(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.activate_whatsapp_webhook_session_cutover(p_organization_id uuid, p_session_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cutover_at timestamptz;
begin
  if p_organization_id is null or p_session_id is null then
    raise exception using errcode = '22023', message = 'whatsapp_cutover_scope_required';
  end if;

  perform 1
  from public.whatsapp_sessions as session
  where session.id = p_session_id
    and session.organization_id = p_organization_id
    and session.provider = 'evolution_go'
    and lower(btrim(coalesce(session.status, ''))) <> 'deleted'
  for update;
  if not found then
    raise exception using errcode = '23503', message = 'whatsapp_cutover_session_not_found';
  end if;

  select cutover.cutover_at into v_cutover_at
  from private.whatsapp_webhook_session_cutovers as cutover
  where cutover.session_id = p_session_id;
  -- Check even on an idempotent call. A retained terminal inbox row with an
  -- orphan token is an inconsistent execution state, not a successful reentry.
  if exists (
    select 1 from public.whatsapp_webhook_inbox as inbox
    where inbox.organization_id = p_organization_id
      and inbox.session_id = p_session_id
      and inbox.processing_epoch = 0
      and inbox.edge_execution_id is not null
  ) then
    raise exception using errcode = '55000', message = 'whatsapp_cutover_edge_execution_inflight';
  end if;
  if v_cutover_at is not null then
    return v_cutover_at;
  end if;

  if exists (
    select 1 from public.whatsapp_webhook_inbox as inbox
    where inbox.organization_id = p_organization_id
      and inbox.session_id = p_session_id
      and inbox.processing_epoch = 0
      and inbox.status = 'processing'
  ) then
    raise exception using errcode = '55000', message = 'whatsapp_cutover_legacy_inflight';
  end if;

  if exists (
    select 1 from public.whatsapp_webhook_inbox as inbox
    where inbox.organization_id = p_organization_id
      and inbox.session_id = p_session_id
      and inbox.processing_epoch = 0
      and inbox.status in ('pending', 'retry')
  ) then
    raise exception using errcode = '55000', message = 'whatsapp_cutover_legacy_pending';
  end if;

  v_cutover_at := clock_timestamp();
  insert into private.whatsapp_webhook_session_cutovers (
    session_id, active_epoch, cutover_at, activated_at
  ) values (p_session_id, 1, v_cutover_at, v_cutover_at);
  return v_cutover_at;
end;
$$;


ALTER FUNCTION private.activate_whatsapp_webhook_session_cutover(p_organization_id uuid, p_session_id uuid) OWNER TO postgres;

--
-- Name: advance_management_queue_child_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.advance_management_queue_child_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare queue_ids uuid[]; target_id uuid;
begin
  if tg_op = 'UPDATE' and
     (to_jsonb(new) - array['updated_at','created_at','leads_count']) =
     (to_jsonb(old) - array['updated_at','created_at','leads_count']) then
    return new;
  end if;
  if tg_op = 'INSERT' then queue_ids := array[new.round_robin_id];
  elsif tg_op = 'DELETE' then queue_ids := array[old.round_robin_id];
  else queue_ids := array[old.round_robin_id, new.round_robin_id]; end if;
  for target_id in select distinct id from unnest(queue_ids) id order by id loop
    update public.round_robins set revision = revision + 1
    where id = target_id;
  end loop;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end
$$;


ALTER FUNCTION private.advance_management_queue_child_revision() OWNER TO postgres;

--
-- Name: advance_management_queue_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.advance_management_queue_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (to_jsonb(new) - array['revision','updated_at','last_assigned_index','current_position','leads_distributed'])
     is distinct from
     (to_jsonb(old) - array['revision','updated_at','last_assigned_index','current_position','leads_distributed']) then
    new.revision := old.revision + 1;
  elsif new.revision is distinct from old.revision then
    new.revision := old.revision + 1;
  end if;
  return new;
end
$$;


ALTER FUNCTION private.advance_management_queue_revision() OWNER TO postgres;

--
-- Name: advance_management_tag_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.advance_management_tag_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (new.name, new.color, new.description) is distinct from (old.name, old.color, old.description) then
    new.updated_at := greatest(clock_timestamp(), old.updated_at + interval '1 microsecond');
  else
    new.updated_at := old.updated_at;
  end if;
  return new;
end
$$;


ALTER FUNCTION private.advance_management_tag_revision() OWNER TO postgres;

--
-- Name: annotate_legacy_property_offer_price(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.annotate_legacy_property_offer_price() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  legacy_sale_price numeric;
  legacy_rental_price numeric;
begin
  if coalesce(new.metadata ->> 'legacy_backfill', 'false') <> 'true'
     and coalesce(new.metadata ->> 'compatibility_source', '') <> 'properties'
  then
    return new;
  end if;

  select property.preco, property.valor_locacao
  into legacy_sale_price, legacy_rental_price
  from public.properties as property
  where property.organization_id = new.organization_id
    and property.id = new.property_id;

  new.metadata := new.metadata
    || private.legacy_property_offer_price_metadata(
      legacy_sale_price,
      legacy_rental_price
    );

  return new;
end;
$$;


ALTER FUNCTION private.annotate_legacy_property_offer_price() OWNER TO postgres;

--
-- Name: apply_asaas_billing_snapshot(uuid, text, text, text, text, date, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_asaas_billing_snapshot(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_status text, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org public.organizations%rowtype;
  v_provider_status text := upper(btrim(coalesce(p_provider_subscription_status, '')));
  v_payment_status text := upper(btrim(coalesce(p_latest_payment_status, '')));
  v_current_payment_status text;
  v_new_status text;
  v_cursor timestamptz;
  v_observed_at timestamptz := least(coalesce(p_observed_at, now()), now());
  v_source text := left(coalesce(nullif(btrim(p_source), ''), 'reconciliation'), 80);
begin
  select organization_row.*
  into v_org
  from public.organizations as organization_row
  where organization_row.id = p_organization_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;
  if nullif(btrim(v_org.asaas_customer_id), '') is not null
     and nullif(btrim(p_provider_customer_id), '') is not null
     and btrim(v_org.asaas_customer_id) <> btrim(p_provider_customer_id) then
    return jsonb_build_object('outcome', 'identifier_mismatch', 'field', 'customer');
  end if;
  if nullif(btrim(v_org.asaas_subscription_id), '') is not null
     and nullif(btrim(p_provider_subscription_id), '') is not null
     and btrim(v_org.asaas_subscription_id) <> btrim(p_provider_subscription_id) then
    return jsonb_build_object('outcome', 'identifier_mismatch', 'field', 'subscription');
  end if;

  select payment.status
  into v_current_payment_status
  from public.asaas_payments as payment
  where payment.organization_id = p_organization_id
    and (
      nullif(btrim(coalesce(p_provider_subscription_id, '')), '') is null
      or payment.asaas_subscription_id
        = nullif(btrim(p_provider_subscription_id), '')
    )
  order by coalesce(
    greatest(
      payment.last_webhook_received_at,
      payment.last_webhook_event_at,
      payment.last_provider_observed_at
    ),
    payment.updated_at,
    payment.created_at
  ) desc, payment.id desc
  limit 1;

  v_cursor := greatest(
    v_org.billing_last_reconciled_at,
    v_org.asaas_last_event_received_at,
    v_org.asaas_last_event_at
  );
  if v_cursor > v_observed_at
     or (
       v_cursor = v_observed_at
       and private.asaas_payment_status_precedence(v_payment_status)
         <= private.asaas_payment_status_precedence(v_current_payment_status)
     ) then
    return jsonb_build_object(
      'outcome', 'stale',
      'status', v_org.subscription_status
    );
  elsif v_cursor = v_observed_at then
    v_observed_at := least(v_cursor, now());
  end if;

  v_new_status := v_org.subscription_status;
  if v_provider_status in ('INACTIVE', 'CANCELLED', 'CANCELED', 'DELETED', 'EXPIRED') then
    v_new_status := 'cancelled';
  elsif lower(btrim(coalesce(v_org.subscription_status, ''))) in ('cancelled', 'canceled') then
    v_new_status := v_org.subscription_status;
  else
    v_new_status := private.asaas_organization_status_from_payment(
      v_org.subscription_status,
      v_payment_status
    );
  end if;

  update public.organizations
  set
    subscription_status = v_new_status,
    asaas_customer_id = coalesce(nullif(btrim(p_provider_customer_id), ''), asaas_customer_id),
    asaas_subscription_id = coalesce(nullif(btrim(p_provider_subscription_id), ''), asaas_subscription_id),
    next_billing_date = coalesce(p_next_billing_date, next_billing_date),
    billing_last_reconciled_at = v_observed_at,
    updated_at = now()
  where id = p_organization_id;

  update private.asaas_reconciliation_jobs
  set
    status = 'pending',
    attempts = 0,
    next_attempt_at = now() + interval '5 minutes',
    locked_at = null,
    locked_by = null,
    last_succeeded_at = now(),
    last_error = null,
    last_provider_status = nullif(v_provider_status, ''),
    last_payment_status = nullif(v_payment_status, ''),
    updated_at = now()
  where organization_id = p_organization_id;

  insert into public.subscription_logs (organization_id, event_type, status, metadata)
  values (
    p_organization_id,
    'asaas_reconciled',
    v_new_status,
    jsonb_build_object(
      'source', v_source,
      'provider_subscription_status', nullif(v_provider_status, ''),
      'latest_payment_status', nullif(v_payment_status, ''),
      'observed_at', v_observed_at
    )
  );

  return jsonb_build_object(
    'outcome', 'applied',
    'previous_status', v_org.subscription_status,
    'status', v_new_status,
    'observed_at', v_observed_at
  );
end
$$;


ALTER FUNCTION private.apply_asaas_billing_snapshot(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_status text, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION apply_asaas_billing_snapshot(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_status text, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.apply_asaas_billing_snapshot(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_status text, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) IS 'Applies periodic Asaas billing state; refunds, cash receipt undo and chargebacks suspend access.';


--
-- Name: apply_asaas_billing_snapshot_with_payment(uuid, text, text, text, text, text, numeric, date, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_asaas_billing_snapshot_with_payment(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.apply_asaas_billing_snapshot_with_payment(
    p_organization_id,
    p_provider_customer_id,
    p_provider_subscription_id,
    p_provider_subscription_status,
    p_latest_payment_id,
    p_latest_payment_status,
    p_latest_payment_amount,
    null::date,
    p_next_billing_date,
