  );
$$;


ALTER FUNCTION private.apply_asaas_billing_snapshot_with_payment(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION apply_asaas_billing_snapshot_with_payment(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.apply_asaas_billing_snapshot_with_payment(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) IS 'Compatibility overload for billing snapshots that do not carry a payment due date.';


--
-- Name: apply_asaas_billing_snapshot_with_payment(uuid, text, text, text, text, text, numeric, date, date, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_asaas_billing_snapshot_with_payment(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_latest_payment_due_date date, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_payment_id text := nullif(btrim(coalesce(p_latest_payment_id, '')), '');
  v_customer_id text := nullif(btrim(coalesce(p_provider_customer_id, '')), '');
  v_subscription_id text := nullif(
    btrim(coalesce(p_provider_subscription_id, '')),
    ''
  );
  v_payment_status text := upper(nullif(
    btrim(coalesce(p_latest_payment_status, '')),
    ''
  ));
  v_source text := lower(nullif(btrim(coalesce(p_source, '')), ''));
  v_payment public.asaas_payments%rowtype;
  v_intent private.billing_checkout_intents%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_plan public.admin_subscription_plans%rowtype;
  v_plan_change private.billing_plan_changes%rowtype;
  v_expected_amount numeric;
  v_period integer;
  v_result jsonb;
  v_organization_status text;
begin
  if p_organization_id is null
     or v_payment_id is null
     or v_customer_id is null
     or char_length(v_payment_id) > 255
     or char_length(v_customer_id) > 255
     or char_length(coalesce(v_subscription_id, '')) > 255 then
    return jsonb_build_object('outcome', 'invalid_identity');
  end if;
  if v_payment_status is null
     or p_latest_payment_amount is null
     or p_latest_payment_amount::text in ('NaN', 'Infinity', '-Infinity')
     or p_latest_payment_amount <= 0
     or p_latest_payment_due_date is null then
    return jsonb_build_object('outcome', 'invalid_payment_snapshot');
  end if;
  if p_observed_at is null or p_observed_at > now() + interval '5 minutes' then
    return jsonb_build_object('outcome', 'invalid_observed_at');
  end if;
  if v_source is null
     or char_length(v_source) > 80
     or v_source !~ '^[a-z0-9][a-z0-9_:-]*$' then
    return jsonb_build_object('outcome', 'invalid_source');
  end if;

  perform private.lock_asaas_billing_resources(
    v_payment_id,
    v_subscription_id
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.asaas_payment_id = v_payment_id
  for update;

  if not found then
    -- Periodic reconciliation is the recovery path when the invoice webhook
    -- was lost. Bootstrap only an exact, already-linked recurring tuple. A
    -- customer-only match, a hidden/uncommitted catalog price, or a fuzzy
    -- organization inference remains fail-closed.
    if v_subscription_id is null then
      return jsonb_build_object('outcome', 'payment_not_found');
    end if;

    select organization_row.*
    into v_org
    from public.organizations as organization_row
    where organization_row.id = p_organization_id
      and nullif(btrim(coalesce(organization_row.asaas_customer_id, '')), '')
        = v_customer_id
      and nullif(btrim(coalesce(organization_row.asaas_subscription_id, '')), '')
        = v_subscription_id
    for update;
    if not found then
      return jsonb_build_object(
        'outcome', 'identifier_mismatch',
        'field', 'recurring_organization'
      );
    end if;
    select subscription.*
    into v_subscription
    from public.subscriptions as subscription
    where subscription.organization_id = p_organization_id
      and lower(btrim(coalesce(subscription.provider, ''))) = 'asaas'
      and subscription.provider_customer_id = v_customer_id
      and subscription.provider_subscription_id = v_subscription_id
      and lower(btrim(coalesce(subscription.status, ''))) not in (
        'cancelled', 'canceled', 'inactive', 'expired'
      )
    for update;
    if not found
       or v_subscription.plan_id is null
       or v_org.plan_id is distinct from v_subscription.plan_id then
      return jsonb_build_object(
        'outcome', 'identifier_mismatch',
        'field', 'recurring_subscription'
      );
    end if;

    select plan_change.*
    into v_plan_change
    from private.billing_plan_changes as plan_change
    where plan_change.organization_id = p_organization_id
      and plan_change.provider_subscription_id = v_subscription_id
      and plan_change.status in ('scheduled', 'provider_updating', 'applying')
      and plan_change.from_plan_id = v_org.plan_id
      and plan_change.amount = p_latest_payment_amount
      and (
        plan_change.effective_on is null
        or p_latest_payment_due_date >= plan_change.effective_on
      )
    order by plan_change.created_at desc, plan_change.id desc
    limit 1
    for update;

    if found then
      v_period := v_plan_change.billing_period_months;
      v_expected_amount := v_plan_change.amount;
      select plan.*
      into v_plan
      from public.admin_subscription_plans as plan
      where plan.id = v_plan_change.target_plan_id
      for share;
    else
      v_period := coalesce(
        v_subscription.billing_period_months,
        v_org.subscription_billing_period_months
      );
      if v_period not in (1, 6, 12) then
        return jsonb_build_object('outcome', 'invalid_billing_period');
      end if;

      select plan.*
      into v_plan
      from public.admin_subscription_plans as plan
      where plan.id = v_subscription.plan_id
        and plan.is_active
      for share;
      if found then
        v_expected_amount := round(v_plan.price * v_period, 2);
      end if;
    end if;

    if v_plan.id is null then
      return jsonb_build_object('outcome', 'plan_not_found');
    end if;
    if v_expected_amount is distinct from p_latest_payment_amount then
      return jsonb_build_object('outcome', 'amount_mismatch');
    end if;

    insert into public.asaas_payments (
      organization_id,
      asaas_payment_id,
      asaas_customer_id,
      asaas_subscription_id,
      status,
      value,
      due_date,
      raw_event
    ) values (
      p_organization_id,
      v_payment_id,
      v_customer_id,
      v_subscription_id,
      'PENDING',
      p_latest_payment_amount,
      p_latest_payment_due_date,
      jsonb_build_object(
        'vimob_recurring_invoice_bootstrap', jsonb_build_object(
          'source', v_source,
          'observed_at', p_observed_at,
          'plan_id', v_plan.id,
          'billing_period_months', v_period,
          'billing_plan_change_id', v_plan_change.id
        )
      )
    )
    on conflict (asaas_payment_id) do nothing
    returning * into v_payment;

    if not found then
      select payment.*
      into v_payment
      from public.asaas_payments as payment
      where payment.asaas_payment_id = v_payment_id
      for update;
    end if;
    if not found then
      return jsonb_build_object('outcome', 'bootstrap_race_lost');
    end if;
  end if;
  if v_payment.organization_id is distinct from p_organization_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'organization'
    );
  end if;
  if nullif(btrim(coalesce(v_payment.asaas_customer_id, '')), '')
       is distinct from v_customer_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'customer'
    );
  end if;
  if nullif(btrim(coalesce(v_payment.asaas_subscription_id, '')), '')
       is distinct from v_subscription_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'subscription'
    );
  end if;

  -- Numeric is exact in Postgres. Do not use a floating tolerance here: a
  -- provider amount must equal the immutable local payment and intent tuple.
  if v_payment.value is null
     or v_payment.value is distinct from p_latest_payment_amount then
    return jsonb_build_object(
      'outcome', 'amount_mismatch',
      'field', 'payment'
    );
  end if;

  if v_payment.billing_intent_id is not null then
    select intent.*
    into v_intent
    from private.billing_checkout_intents as intent
    where intent.id = v_payment.billing_intent_id
      and intent.organization_id = v_payment.organization_id
    for update;

    if not found
       or v_intent.provider_payment_id is distinct from v_payment_id
       or v_intent.provider_customer_id is distinct from v_customer_id then
      return jsonb_build_object(
        'outcome', 'identifier_mismatch',
        'field', 'billing_intent_snapshot'
      );
    end if;
    if v_intent.amount is distinct from p_latest_payment_amount then
      return jsonb_build_object(
        'outcome', 'amount_mismatch',
        'field', 'billing_intent'
      );
    end if;
  end if;

  -- Inbound confirmation must survive concurrent deactivation. Hold the
  -- tenant tombstone row through persistence so cleanup observes the complete
  -- payment evidence; this function never reactivates organizations.is_active.
  select organization_row.*
  into v_org
  from public.organizations as organization_row
  where organization_row.id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;

  v_result := private.persist_asaas_billing_snapshot_after_exact_validation(
    p_organization_id,
    v_customer_id,
    v_subscription_id,
    p_provider_subscription_status,
    v_payment_id,
    v_payment_status,
    p_latest_payment_amount,
    p_latest_payment_due_date,
    p_next_billing_date,
    p_observed_at,
    v_source
  );

  if coalesce(v_result ->> 'outcome', '') = 'applied' then
    select organization_row.subscription_status
    into v_organization_status
    from public.organizations as organization_row
    where organization_row.id = p_organization_id;

    if private.billing_payment_checkout_is_paid(v_payment_status) then
      v_organization_status := private.reconcile_billing_payment_access_proof(
        p_organization_id,
        v_payment_id,
        v_organization_status,
        v_payment_status
      );
      update public.organizations
      set subscription_status = v_organization_status, updated_at = now()
      where id = p_organization_id
        and lower(btrim(coalesce(subscription_status, ''))) not in (
          'cancelled', 'canceled'
        );
      update public.subscriptions
      set status = v_organization_status, updated_at = now()
      where organization_id = p_organization_id
        and provider_subscription_id is not distinct from v_subscription_id
        and lower(btrim(coalesce(status, ''))) not in ('cancelled', 'canceled');
      v_result := v_result || jsonb_build_object('status', v_organization_status);
    end if;

    if lower(btrim(coalesce(v_organization_status, ''))) in (
         'pending_payment', 'overdue', 'past_due', 'blocked', 'suspended'
       )
       and not private.billing_payment_checkout_is_paid(v_payment_status) then
      insert into private.billing_organization_access_causes (
        organization_id,
        provider_payment_id,
        payment_status,
        observed_at,
        source
      ) values (
        p_organization_id,
        v_payment_id,
        v_payment_status,
        least(p_observed_at, now()),
        v_source
      )
      on conflict (organization_id, provider_payment_id) do update
      set
        provider_payment_id = excluded.provider_payment_id,
        payment_status = excluded.payment_status,
        observed_at = excluded.observed_at,
        source = excluded.source,
        updated_at = now()
      where excluded.observed_at > private.billing_organization_access_causes.observed_at
         or (
           excluded.observed_at = private.billing_organization_access_causes.observed_at
           and private.asaas_payment_status_precedence(excluded.payment_status)
             > private.asaas_payment_status_precedence(
               private.billing_organization_access_causes.payment_status
             )
         );
    end if;
  end if;

  -- Stale/duplicate polling evidence is intentionally ignored, but callers
  -- still need the authoritative access state. Never return a status-less
  -- response that can be mistaken for an unknown transition.
  if not (coalesce(v_result, '{}'::jsonb) ? 'status') then
    select organization_row.subscription_status
    into v_organization_status
    from public.organizations as organization_row
    where organization_row.id = p_organization_id;
    if found then
      v_result := coalesce(v_result, '{}'::jsonb)
        || jsonb_build_object('status', v_organization_status);
    end if;
  end if;

  return v_result;
end
$_$;


ALTER FUNCTION private.apply_asaas_billing_snapshot_with_payment(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_latest_payment_due_date date, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION apply_asaas_billing_snapshot_with_payment(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_latest_payment_due_date date, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.apply_asaas_billing_snapshot_with_payment(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_latest_payment_due_date date, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) IS 'Private exact-payment reconciliation gate shared by settings and periodic reconciliation; activation cannot precede immutable identity and amount validation.';


--
-- Name: apply_lead_action_fact(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_lead_action_fact() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  cycle_assigned_at timestamptz;
begin
  if new.qualifies_first_outreach and not new.is_automated and new.assignment_cycle_id is not null then
    update public.lead_assignment_cycles
    set first_human_outreach_at = coalesce(first_human_outreach_at, new.occurred_at)
    where id = new.assignment_cycle_id
    returning assigned_at into cycle_assigned_at;

    update public.leads
    set first_response_at = new.occurred_at,
        first_response_seconds = greatest(0, extract(epoch from (new.occurred_at - coalesce(cycle_assigned_at, created_at)))::integer),
        first_response_channel = new.channel,
        first_response_is_automation = false,
        first_response_actor_user_id = new.actor_user_id,
        last_contact_at = greatest(coalesce(last_contact_at, new.occurred_at), new.occurred_at),
        updated_at = now()
    where id = new.lead_id
      and organization_id = new.organization_id
      and first_response_at is null;
  elsif new.qualifies_stage_inactivity then
    update public.leads
    set last_contact_at = greatest(coalesce(last_contact_at, new.occurred_at), new.occurred_at),
        updated_at = now()
    where id = new.lead_id and organization_id = new.organization_id;
  end if;

  if new.is_effective_contact and new.assignment_cycle_id is not null then
    update public.lead_assignment_cycles
    set first_effective_contact_at = coalesce(first_effective_contact_at, new.occurred_at)
    where id = new.assignment_cycle_id;
  end if;

  return null;
end;
$$;


ALTER FUNCTION private.apply_lead_action_fact() OWNER TO postgres;

--
-- Name: apply_notification_delivery_receipt(uuid, text, text, text, text, boolean, boolean, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_notification_delivery_receipt(p_notification_id uuid, p_channel text, p_provider text, p_provider_message_id text, p_provider_status text, p_delivered boolean, p_permanent_failure boolean, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_delivery private.notification_deliveries%rowtype;
  v_target_status text;
  v_next_attempt_at timestamptz;
  v_prior_receipt_at timestamptz;
begin
  if p_notification_id is null
     or p_channel not in ('whatsapp', 'email')
     or nullif(btrim(coalesce(p_provider, '')), '') is null
     or nullif(btrim(coalesce(p_provider_message_id, '')), '') is null
     or nullif(btrim(coalesce(p_provider_status, '')), '') is null
     or char_length(p_provider) > 100
     or char_length(p_provider_message_id) > 500
     or char_length(p_provider_status) > 255
     or p_occurred_at is null
     or p_occurred_at > now() + interval '5 minutes' then
    return jsonb_build_object('outcome', 'invalid_receipt');
  end if;

  select delivery.*
    into v_delivery
  from private.notification_deliveries as delivery
  where delivery.notification_id = p_notification_id
    and delivery.channel = p_channel
    and (
      delivery.provider_message_id = btrim(p_provider_message_id)
      or delivery.provider_message_id is null
      or delivery.metadata ->> 'expected_message_id' = btrim(p_provider_message_id)
    )
  order by
    case
      when delivery.provider_message_id = btrim(p_provider_message_id) then 0
      when delivery.metadata ->> 'expected_message_id' = btrim(p_provider_message_id) then 1
      else 2
    end,
    delivery.created_at,
    delivery.id
  limit 1
  for update;

  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  v_prior_receipt_at := private.notification_safe_timestamptz(
    v_delivery.metadata ->> 'last_receipt_at'
  );
  if v_prior_receipt_at is not null and p_occurred_at < v_prior_receipt_at then
    return jsonb_build_object(
      'outcome', 'stale',
      'delivery_id', v_delivery.id,
      'status', v_delivery.status
    );
  end if;

  if v_delivery.status = 'delivered' and not p_delivered then
    return jsonb_build_object(
      'outcome', 'stale',
      'delivery_id', v_delivery.id,
      'status', v_delivery.status
    );
  end if;
  if not p_delivered
     and v_delivery.status in ('permanent_failed', 'dead_letter', 'cancelled') then
    return jsonb_build_object(
      'outcome', 'stale',
      'delivery_id', v_delivery.id,
      'status', v_delivery.status
    );
  end if;

  if p_delivered then
    v_target_status := 'delivered';
    v_next_attempt_at := null;
  elsif p_permanent_failure then
    v_target_status := 'permanent_failed';
    v_next_attempt_at := null;
  elsif v_delivery.expires_at <= p_occurred_at
        or v_delivery.attempt_count >= v_delivery.max_attempts then
    v_target_status := 'dead_letter';
    v_next_attempt_at := null;
  else
    v_target_status := 'retry_wait';
    v_next_attempt_at := greatest(
      now(),
      p_occurred_at + private.notification_delivery_retry_delay(
        greatest(v_delivery.attempt_count, 1)
      )
    );
  end if;

  if v_delivery.status = v_target_status
     and v_prior_receipt_at is not null
     and p_occurred_at = v_prior_receipt_at then
    return jsonb_build_object(
      'outcome', 'already_applied',
      'delivery_id', v_delivery.id,
      'status', v_delivery.status,
      'next_attempt_at', v_delivery.next_attempt_at
    );
  end if;

  update private.notification_deliveries as delivery
  set status = v_target_status,
      next_attempt_at = v_next_attempt_at,
      lease_token = null,
      leased_by = null,
      lease_expires_at = null,
      dependency_key = null,
      provider = btrim(p_provider),
      provider_message_id = btrim(p_provider_message_id),
      provider_status = lower(btrim(p_provider_status)),
      accepted_at = case
        when p_delivered then coalesce(delivery.accepted_at, p_occurred_at)
        else delivery.accepted_at
      end,
      delivered_at = case
        when p_delivered then coalesce(delivery.delivered_at, p_occurred_at)
        else delivery.delivered_at
      end,
      blocked_at = null,
      terminal_at = case
        when v_target_status in ('delivered', 'permanent_failed', 'dead_letter')
          then p_occurred_at
        else null
      end,
      last_error_code = case
        when p_delivered then null
        else 'provider_' || lower(btrim(p_provider_status))
      end,
      last_error_message = case
        when p_delivered then null
        else 'Provider reported a delivery failure.'
      end,
      last_error_at = case when p_delivered then null else p_occurred_at end,
      metadata = delivery.metadata || jsonb_build_object(
        'last_receipt_at', p_occurred_at,
        'last_receipt_status', lower(btrim(p_provider_status)),
        'last_receipt_permanent', coalesce(p_permanent_failure, false)
      ),
      updated_at = now()
  where delivery.id = v_delivery.id;

  update private.notification_delivery_attempts as attempt
  set outcome = v_target_status,
      provider = btrim(p_provider),
      provider_message_id = btrim(p_provider_message_id),
      provider_status = lower(btrim(p_provider_status)),
      completed_at = greatest(coalesce(attempt.completed_at, p_occurred_at), p_occurred_at),
      error_code = case
        when p_delivered then null
        else 'provider_' || lower(btrim(p_provider_status))
      end,
      error_message = case
        when p_delivered then null
        else 'Provider reported a delivery failure.'
      end,
      metadata = attempt.metadata || jsonb_build_object(
        'receipt_at', p_occurred_at,
        'receipt_permanent', coalesce(p_permanent_failure, false)
      )
  where attempt.id = (
    select latest.id
    from private.notification_delivery_attempts as latest
    where latest.delivery_id = v_delivery.id
      and latest.event_type = 'send_attempt'
    order by latest.attempt_number desc
    limit 1
  );

  insert into private.notification_delivery_attempts (
    delivery_id,
    event_type,
    attempt_number,
    from_status,
    outcome,
    provider,
    provider_message_id,
    provider_status,
    completed_at,
    error_code,
    metadata
  )
  values (
    v_delivery.id,
    'receipt',
    null,
    v_delivery.status,
    v_target_status,
    btrim(p_provider),
    btrim(p_provider_message_id),
    lower(btrim(p_provider_status)),
    p_occurred_at,
    case
      when p_delivered then null
      else 'provider_' || lower(btrim(p_provider_status))
    end,
    jsonb_build_object(
      'permanent_failure', coalesce(p_permanent_failure, false)
    )
  );

  return jsonb_build_object(
    'outcome', 'applied',
    'delivery_id', v_delivery.id,
    'status', v_target_status,
    'next_attempt_at', v_next_attempt_at
  );
end
$$;


ALTER FUNCTION private.apply_notification_delivery_receipt(p_notification_id uuid, p_channel text, p_provider text, p_provider_message_id text, p_provider_status text, p_delivered boolean, p_permanent_failure boolean, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: apply_organization_billing_transition(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_organization_billing_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_grace_days integer := 3;
begin
  new.subscription_status := case
    when new.subscription_status = 'canceled' then 'cancelled'
    else new.subscription_status
  end;

  if tg_op = 'UPDATE'
     and old.pending_plan_id is not null
     and new.subscription_status = 'active'
     and not exists (
       select 1
       from private.billing_checkout_intents intent
       where intent.organization_id = old.id
         and intent.pending_plan_id = old.pending_plan_id
         and intent.status = 'confirmed'
     )
     and not exists (
       select 1
       from private.billing_plan_changes plan_change
       where plan_change.organization_id = old.id
         and plan_change.target_plan_id = old.pending_plan_id
         and plan_change.provider_subscription_id = old.asaas_subscription_id
         and plan_change.status = 'applying'
     ) then
    new.subscription_status := old.subscription_status;
    new.subscription_type := old.subscription_type;
    new.plan_id := old.plan_id;
    new.pending_plan_id := old.pending_plan_id;
    new.subscription_value := old.subscription_value;
    new.max_users := old.max_users;
    new.trial_ends_at := old.trial_ends_at;
  end if;

  if new.pending_plan_id is null
     and new.subscription_status <> 'trial'
     and (
       nullif(btrim(new.asaas_customer_id), '') is not null
       or nullif(btrim(new.asaas_subscription_id), '') is not null
     ) then
    new.subscription_type := 'paid';
  end if;

  if tg_op = 'INSERT'
     or new.subscription_status is distinct from old.subscription_status then
    new.billing_status_changed_at := now();

    select coalesce(p.payment_grace_days, 3)
    into v_grace_days
    from public.admin_subscription_plans p
    where p.id = new.plan_id;

    v_grace_days := coalesce(v_grace_days, 3);

    case new.subscription_status
      when 'active' then
        new.billing_delinquent_at := null;
        new.billing_grace_until := null;
        new.billing_blocked_at := null;
      when 'trial' then
        new.billing_delinquent_at := null;
        new.billing_grace_until := null;
        new.billing_blocked_at := case
          when new.trial_ends_at is null or new.trial_ends_at <= now()
            then coalesce(new.billing_blocked_at, now())
          else null
        end;
      when 'overdue' then
        new.billing_delinquent_at := case
          when tg_op = 'UPDATE'
               and old.subscription_status in ('overdue', 'past_due')
            then coalesce(old.billing_delinquent_at, now())
          else now()
        end;
        new.billing_grace_until := case
          when tg_op = 'UPDATE'
               and old.subscription_status in ('overdue', 'past_due')
            then coalesce(
              old.billing_grace_until,
              coalesce(old.billing_delinquent_at, now())
                + make_interval(days => v_grace_days)
            )
          else now() + make_interval(days => v_grace_days)
        end;
        new.billing_blocked_at := case
          when new.billing_grace_until <= now()
            then coalesce(new.billing_blocked_at, now())
          else null
        end;
      when 'past_due' then
        new.billing_delinquent_at := case
          when tg_op = 'UPDATE'
               and old.subscription_status in ('overdue', 'past_due')
            then coalesce(old.billing_delinquent_at, now())
          else now()
        end;
        new.billing_grace_until := case
          when tg_op = 'UPDATE'
               and old.subscription_status in ('overdue', 'past_due')
            then coalesce(
              old.billing_grace_until,
              coalesce(old.billing_delinquent_at, now())
                + make_interval(days => v_grace_days)
            )
          else now() + make_interval(days => v_grace_days)
        end;
        new.billing_blocked_at := case
          when new.billing_grace_until <= now()
            then coalesce(new.billing_blocked_at, now())
          else null
        end;
      when 'pending_payment' then
        new.billing_delinquent_at := coalesce(new.billing_delinquent_at, now());
        new.billing_grace_until := null;
        new.billing_blocked_at := coalesce(new.billing_blocked_at, now());
      when 'blocked' then
        new.billing_delinquent_at := coalesce(new.billing_delinquent_at, now());
        new.billing_grace_until := null;
        new.billing_blocked_at := coalesce(new.billing_blocked_at, now());
      when 'suspended' then
        new.billing_grace_until := null;
        new.billing_blocked_at := coalesce(new.billing_blocked_at, now());
      when 'cancelled' then
        new.billing_grace_until := null;
        new.billing_blocked_at := coalesce(new.billing_blocked_at, now());
      else
        raise exception 'unsupported billing status: %', new.subscription_status
          using errcode = '22023';
    end case;
  elsif new.subscription_status in ('overdue', 'past_due')
        and new.billing_grace_until is not null
        and new.billing_grace_until <= now() then
    new.billing_blocked_at := coalesce(new.billing_blocked_at, now());
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.apply_organization_billing_transition() OWNER TO postgres;

--
-- Name: apply_property_development_reservation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_property_development_reservation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_unit_status text;
  has_active_unit_price boolean;
begin
  if tg_op = 'INSERT' then
    if new.status <> 'active' then
      return new;
    end if;

    if new.expires_at is null
       or new.expires_at <= clock_timestamp()
       or new.expires_at > clock_timestamp() + interval '30 days' then
      raise exception using
        errcode = '23514',
        message = 'property_development_reservation_expiration_invalid';
    end if;

    select unit.status
    into current_unit_status
    from public.property_development_units as unit
    where unit.id = new.unit_id
      and unit.organization_id = new.organization_id
      and unit.development_id = new.development_id
    for update;

    -- Publication is a public-channel concern. Internal availability is
    -- governed by inventory status and active commercial pricing only.
    if current_unit_status not in ('available', 'negotiation') then
      raise exception using
        errcode = '23514',
        message = 'property_development_unit_not_commercially_available_for_reservation';
    end if;

    select exists (
      select 1
      from public.property_development_unit_prices as unit_price
      join public.property_development_price_tables as price_table
        on price_table.id = unit_price.price_table_id
       and price_table.organization_id = unit_price.organization_id
       and price_table.development_id = unit_price.development_id
      where unit_price.organization_id = new.organization_id
        and unit_price.development_id = new.development_id
        and unit_price.unit_id = new.unit_id
        and unit_price.price_table_id = new.price_table_id
        and price_table.status = 'active'
    )
    into has_active_unit_price;

    if not has_active_unit_price then
      raise exception using
        errcode = '23514',
        message = 'property_development_reservation_requires_active_unit_price';
    end if;

    perform set_config(
      'vimob.property_development_reservation_unit_id',
      new.unit_id::text,
      true
    );

    update public.property_development_units
    set status = 'reserved',
        updated_by = coalesce(new.updated_by, new.reserved_by),
        updated_at = clock_timestamp()
    where id = new.unit_id
      and organization_id = new.organization_id
      and development_id = new.development_id;

    perform set_config(
      'vimob.property_development_reservation_unit_id',
      '',
      true
    );

    return new;
  end if;

  if old.status <> 'active' and new.status = 'active' then
    raise exception using
      errcode = '23514',
      message = 'property_development_reservation_cannot_reactivate';
  end if;

  if old.status = 'active' and new.status = 'converted' then
    perform set_config(
      'vimob.property_development_reservation_unit_id',
      new.unit_id::text,
      true
    );

    update public.property_development_units
    set status = 'sold',
        published = false,
        publication_pending = false,
        updated_by = coalesce(new.updated_by, new.reserved_by),
        updated_at = clock_timestamp()
    where id = new.unit_id
      and organization_id = new.organization_id
      and development_id = new.development_id
      and status = 'reserved';

    if not found then
      raise exception using
        errcode = '23514',
        message = 'property_development_reserved_unit_state_invalid';
    end if;

    perform set_config(
      'vimob.property_development_reservation_unit_id',
      '',
      true
    );
  elsif old.status = 'active' and new.status in ('cancelled', 'expired') then
    perform set_config(
      'vimob.property_development_reservation_unit_id',
      new.unit_id::text,
      true
    );

    update public.property_development_units
    set status = 'available',
        -- Expiration is a system transition. Keeping an inactive historical
        -- actor here would violate the tenant-reference trigger and poison the
        -- entire worker batch forever.
        updated_by = case
          when new.status = 'expired' then null
          else coalesce(new.updated_by, new.reserved_by)
        end,
        updated_at = clock_timestamp()
    where id = new.unit_id
      and organization_id = new.organization_id
      and development_id = new.development_id
      and status = 'reserved';

    if not found then
      raise exception using
        errcode = '23514',
        message = 'property_development_reserved_unit_state_invalid';
    end if;

    perform set_config(
      'vimob.property_development_reservation_unit_id',
      '',
      true
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.apply_property_development_reservation() OWNER TO postgres;

--
-- Name: apply_property_key_movement(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_property_key_movement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_key public.property_keys%rowtype;
begin
  select property_key.*
  into current_key
  from public.property_keys as property_key
  where property_key.id = new.property_key_id
    and property_key.organization_id = new.organization_id
  for update;

  if not found then
    return new;
  end if;

  if new.movement_type = 'checkout' then
    if current_key.status <> 'available' then
      raise exception using
        errcode = '23514',
        message = 'property_key_not_available';
    end if;

    update public.property_keys
    set status = 'checked_out',
        holder_user_id = new.holder_user_id,
        holder_name = nullif(btrim(new.holder_name), ''),
        checked_out_at = new.occurred_at,
        expected_return_at = new.expected_return_at
    where id = new.property_key_id;
  elsif new.movement_type = 'transfer' then
    if current_key.status <> 'checked_out' then
      raise exception using
        errcode = '23514',
        message = 'property_key_not_checked_out';
    end if;

    update public.property_keys
    set holder_user_id = new.holder_user_id,
        holder_name = nullif(btrim(new.holder_name), ''),
        expected_return_at = new.expected_return_at
    where id = new.property_key_id;
  elsif new.movement_type = 'return' then
    if current_key.status <> 'checked_out' then
      raise exception using
        errcode = '23514',
        message = 'property_key_not_checked_out';
    end if;

    update public.property_keys
    set status = 'available',
        current_location = coalesce(
          nullif(btrim(new.to_location), ''),
          current_location
        ),
        holder_user_id = null,
        holder_name = null,
        checked_out_at = null,
        expected_return_at = null
    where id = new.property_key_id;
  elsif new.movement_type = 'location_change' then
    if current_key.status <> 'available'
       or nullif(btrim(new.to_location), '') is null then
      raise exception using
        errcode = '23514',
        message = 'property_key_location_change_invalid';
    end if;

    update public.property_keys
    set current_location = btrim(new.to_location)
    where id = new.property_key_id;
  elsif new.movement_type = 'mark_lost' then
    if current_key.status = 'inactive' then
      raise exception using
        errcode = '23514',
        message = 'property_key_inactive';
    end if;

    update public.property_keys
    set status = 'lost'
    where id = new.property_key_id;
  elsif new.movement_type = 'mark_found' then
    if current_key.status <> 'lost' then
      raise exception using
        errcode = '23514',
        message = 'property_key_not_lost';
    end if;

    update public.property_keys
    set status = 'available',
        current_location = coalesce(
          nullif(btrim(new.to_location), ''),
          current_location
        ),
        holder_user_id = null,
        holder_name = null,
        checked_out_at = null,
        expected_return_at = null
    where id = new.property_key_id;
  elsif new.movement_type = 'deactivate' then
    update public.property_keys
    set status = 'inactive',
        holder_user_id = null,
        holder_name = null,
        checked_out_at = null,
        expected_return_at = null
    where id = new.property_key_id;
  elsif new.movement_type = 'reactivate' then
    if current_key.status <> 'inactive' then
      raise exception using
        errcode = '23514',
        message = 'property_key_not_inactive';
    end if;

    update public.property_keys
    set status = 'available',
        current_location = coalesce(
          nullif(btrim(new.to_location), ''),
          current_location
        )
    where id = new.property_key_id;
  elsif new.movement_type = 'registration' then
    if current_key.status <> 'available'
       or exists (
         select 1
         from public.property_key_movements as prior_movement
         where prior_movement.property_key_id = new.property_key_id
           and prior_movement.id <> new.id
       ) then
      raise exception using
        errcode = '23514',
        message = 'property_key_registration_not_initial';
    end if;

    update public.property_keys
    set status = 'available',
        current_location = coalesce(
          nullif(btrim(new.to_location), ''),
          current_location
        )
    where id = new.property_key_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.apply_property_key_movement() OWNER TO postgres;

--
-- Name: apply_round_robin_auto_tags(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_round_robin_auto_tags(p_organization_id uuid, p_round_robin_id uuid, p_lead_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_applied integer := 0;
begin
  if p_organization_id is null
     or p_round_robin_id is null
     or p_lead_id is null then
    return 0;
  end if;

  insert into public.lead_tags (organization_id, lead_id, tag_id)
  select
    p_organization_id,
    p_lead_id,
    valid_tag.id
  from public.round_robins as queue
  cross join lateral jsonb_array_elements_text(
    case
      when jsonb_typeof(queue.settings->'auto_tag_ids') = 'array'
        then queue.settings->'auto_tag_ids'
      else '[]'::jsonb
    end
  ) with ordinality as requested_tag(value, ordinality)
  join public.tags as valid_tag
    on valid_tag.organization_id = queue.organization_id
   and lower(valid_tag.id::text) = lower(btrim(requested_tag.value))
  where queue.organization_id = p_organization_id
    and queue.id = p_round_robin_id
    and coalesce(queue.is_active, true) = true
    and requested_tag.ordinality <= 50
    and exists (
      select 1
      from public.leads as lead
      where lead.organization_id = p_organization_id
        and lead.id = p_lead_id
    )
  group by valid_tag.id
  on conflict (lead_id, tag_id) do nothing;

  select count(distinct valid_tag.id)::integer
    into v_applied
    from public.round_robins as queue
    cross join lateral jsonb_array_elements_text(
      case
        when jsonb_typeof(queue.settings->'auto_tag_ids') = 'array'
          then queue.settings->'auto_tag_ids'
        else '[]'::jsonb
      end
    ) with ordinality as requested_tag(value, ordinality)
    join public.tags as valid_tag
      on valid_tag.organization_id = queue.organization_id
     and lower(valid_tag.id::text) = lower(btrim(requested_tag.value))
    join public.lead_tags as attached_tag
      on attached_tag.lead_id = p_lead_id
     and attached_tag.tag_id = valid_tag.id
     and attached_tag.organization_id = p_organization_id
   where queue.organization_id = p_organization_id
     and queue.id = p_round_robin_id
     and coalesce(queue.is_active, true) = true
     and requested_tag.ordinality <= 50;

  return v_applied;
end;
$$;


ALTER FUNCTION private.apply_round_robin_auto_tags(p_organization_id uuid, p_round_robin_id uuid, p_lead_id uuid) OWNER TO postgres;

--
-- Name: apply_round_robin_auto_tags_from_log(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_round_robin_auto_tags_from_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.organization_id is not null
     and new.round_robin_id is not null
     and new.lead_id is not null
     and (
       new.assigned_user_id is not null
       or coalesce(new.reason, '') = 'no_available_members'
     ) then
    perform private.apply_round_robin_auto_tags(
      new.organization_id,
      new.round_robin_id,
      new.lead_id
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.apply_round_robin_auto_tags_from_log() OWNER TO postgres;

--
-- Name: apply_scheduled_billing_plan_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.apply_scheduled_billing_plan_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_change private.billing_plan_changes%rowtype;
  v_plan public.admin_subscription_plans%rowtype;
  v_organization_status text;
  v_organization_cursor timestamptz;
  v_payment_cursor timestamptz := greatest(
    new.last_webhook_event_at,
    new.last_provider_observed_at
  );
  v_period_end date;
begin
  if upper(btrim(coalesce(new.status, ''))) not in (
    'CONFIRMED',
    'RECEIVED',
    'RECEIVED_IN_CASH'
  )
     or new.value is null
     or new.due_date is null
     or nullif(btrim(coalesce(new.asaas_subscription_id, '')), '') is null then
    return new;
  end if;

  select plan_change.*
  into v_change
  from private.billing_plan_changes plan_change
  where plan_change.organization_id = new.organization_id
    and plan_change.provider_subscription_id = btrim(new.asaas_subscription_id)
    and plan_change.status in ('provider_updating', 'scheduled')
    and (
      (
        plan_change.status = 'scheduled'
        and plan_change.effective_on is not null
        and new.due_date >= plan_change.effective_on
      )
      or (
        plan_change.status = 'provider_updating'
        and new.due_date >= plan_change.provider_request_started_at::date
      )
    )
    and abs(new.value - plan_change.amount) <= 0.01
  order by plan_change.effective_on, plan_change.created_at, plan_change.id
  limit 1
  for update;

  if not found then
    return new;
  end if;

  -- Payment triggers run before the outer webhook can reject an old event.
  -- Lock and validate both terminal state and ordering here so a T0 payment
  -- cannot apply a scheduled plan after reconciliation already advanced the
  -- organization to T1. Equality is intentional for the current webhook/poll.
  select
    organization.subscription_status,
    greatest(
      organization.asaas_last_event_at,
      organization.billing_last_reconciled_at
    )
    into v_organization_status, v_organization_cursor
  from public.organizations organization
  where organization.id = v_change.organization_id
    and organization.asaas_subscription_id = v_change.provider_subscription_id
  for update;

  if not found then
    raise exception 'scheduled billing plan change lost its organization identity: %', v_change.id
      using errcode = '40001';
  end if;

  if v_organization_status in ('suspended', 'cancelled', 'canceled') then
    return new;
  end if;

  if v_payment_cursor is null
     or (
       v_organization_cursor is not null
       and v_organization_cursor > v_payment_cursor
     ) then
    return new;
  end if;

  select plan.*
  into v_plan
  from public.admin_subscription_plans plan
  where plan.id = v_change.target_plan_id;

  if not found then
    raise exception 'scheduled billing target plan no longer exists: %', v_change.target_plan_id
      using errcode = '23503';
  end if;

  update private.billing_plan_changes
  set status = 'applying',
      updated_at = now()
  where id = v_change.id
    and status in ('provider_updating', 'scheduled');

  if not found then
    return new;
  end if;

  v_period_end := (
    new.due_date + make_interval(months => v_change.billing_period_months)
  )::date;

  update public.organizations
  set
    plan_id = v_change.target_plan_id,
    pending_plan_id = null,
    subscription_value = round(
      v_change.amount / v_change.billing_period_months,
      2
    ),
    subscription_billing_period_months = v_change.billing_period_months,
    subscription_type = 'paid',
    subscription_status = 'active',
    trial_ends_at = null,
    next_billing_date = greatest(
      coalesce(next_billing_date, '-infinity'::date),
      v_period_end
    ),
    max_users = coalesce(v_plan.max_users, max_users),
    updated_at = now()
  where id = v_change.organization_id
    and plan_id = v_change.from_plan_id
    and pending_plan_id = v_change.target_plan_id
    and asaas_subscription_id = v_change.provider_subscription_id
    and subscription_status not in ('suspended', 'cancelled', 'canceled');

  if not found then
    raise exception 'scheduled billing plan change lost its organization guard: %', v_change.id
      using errcode = '40001';
  end if;

  update public.subscriptions
  set
    plan_id = v_change.target_plan_id,
    status = 'active',
    billing_period_months = v_change.billing_period_months,
    current_period_start = new.due_date::timestamptz,
    current_period_end = v_period_end::timestamptz,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'managed_plan_change_id', v_change.id,
      'billing_period_months', v_change.billing_period_months,
      'billing_cycle', v_change.provider_cycle,
      'charged_amount', new.value,
      'period_anchor', new.due_date
    ),
    updated_at = now()
  where organization_id = v_change.organization_id
    and provider_subscription_id = v_change.provider_subscription_id;

  update private.billing_plan_changes
  set
    status = 'applied',
    applied_at = now(),
    last_error = null,
    updated_at = now()
  where id = v_change.id
    and status = 'applying';

  insert into public.subscription_logs (
    organization_id,
    event_type,
    status,
    metadata
  )
  values (
    v_change.organization_id,
    'managed_plan_change_applied',
    'active',
    jsonb_build_object(
      'plan_change_id', v_change.id,
      'from_plan_id', v_change.from_plan_id,
      'target_plan_id', v_change.target_plan_id,
      'provider_subscription_id', v_change.provider_subscription_id,
      'provider_payment_id', new.asaas_payment_id,
      'amount', new.value,
      'due_date', new.due_date,
      'billing_period_months', v_change.billing_period_months
    )
  );

  return new;
end;
$$;


ALTER FUNCTION private.apply_scheduled_billing_plan_change() OWNER TO postgres;

--
-- Name: asaas_organization_status_from_payment(text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.asaas_organization_status_from_payment(p_current_status text, p_payment_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when lower(btrim(coalesce(p_current_status, ''))) in (
      'cancelled',
      'canceled'
    ) then lower(btrim(p_current_status))
    when upper(btrim(coalesce(p_payment_status, ''))) = 'REFUND_DENIED'
      then case
        when lower(btrim(coalesce(p_current_status, ''))) in ('active', 'trial')
          then p_current_status
        else coalesce(nullif(lower(btrim(p_current_status)), ''), 'pending_payment')
      end
    when private.billing_payment_checkout_is_reversal(p_payment_status)
      or upper(btrim(coalesce(p_payment_status, ''))) = 'CHARGEBACK'
      then 'suspended'
    when upper(btrim(coalesce(p_payment_status, ''))) in (
      'OVERDUE',
      'DUNNING_REQUESTED',
      'DUNNING_RECEIVED',
      'CREDIT_CARD_CAPTURE_REFUSED',
      'REPROVED_BY_RISK_ANALYSIS'
    ) then 'overdue'
    when private.billing_payment_checkout_is_paid(p_payment_status)
      then case
        when lower(btrim(coalesce(p_current_status, ''))) in ('active', 'trial')
          then p_current_status
        else coalesce(nullif(lower(btrim(p_current_status)), ''), 'pending_payment')
      end
    when upper(btrim(coalesce(p_payment_status, ''))) in (
      'DELETED',
      'CANCELED',
      'CANCELLED'
    ) then case
      when lower(btrim(coalesce(p_current_status, ''))) in ('active', 'trial')
        then p_current_status
      else 'pending_payment'
    end
    when lower(btrim(coalesce(p_current_status, ''))) in ('active', 'trial')
      then p_current_status
    else 'pending_payment'
  end;
$$;


ALTER FUNCTION private.asaas_organization_status_from_payment(p_current_status text, p_payment_status text) OWNER TO postgres;

--
-- Name: asaas_payment_status_from_event(text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.asaas_payment_status_from_event(p_event_type text, p_payload_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case upper(btrim(coalesce(p_event_type, '')))
    when 'PAYMENT_CONFIRMED' then 'CONFIRMED'
    when 'PAYMENT_RECEIVED' then 'RECEIVED'
    when 'PAYMENT_RECEIVED_IN_CASH' then 'RECEIVED_IN_CASH'
    when 'PAYMENT_OVERDUE' then 'OVERDUE'
    when 'PAYMENT_DELETED' then 'DELETED'
    when 'PAYMENT_REFUNDED' then 'REFUNDED'
    when 'PAYMENT_REFUND_REQUESTED' then 'REFUND_REQUESTED'
    when 'PAYMENT_REFUND_IN_PROGRESS' then 'REFUND_IN_PROGRESS'
    when 'PAYMENT_REFUND_DENIED' then 'REFUND_DENIED'
    when 'PAYMENT_PARTIALLY_REFUNDED' then 'PARTIALLY_REFUNDED'
    when 'PAYMENT_RECEIVED_IN_CASH_UNDONE' then 'RECEIVED_IN_CASH_UNDONE'
    when 'PAYMENT_CHARGEBACK' then 'CHARGEBACK'
    when 'PAYMENT_CHARGEBACK_REQUESTED' then 'CHARGEBACK_REQUESTED'
    when 'PAYMENT_CHARGEBACK_DISPUTE' then 'CHARGEBACK_DISPUTE'
    when 'PAYMENT_AWAITING_CHARGEBACK_REVERSAL' then 'AWAITING_CHARGEBACK_REVERSAL'
    when 'PAYMENT_CREDIT_CARD_CAPTURE_REFUSED' then 'CREDIT_CARD_CAPTURE_REFUSED'
    when 'PAYMENT_REPROVED_BY_RISK_ANALYSIS' then 'REPROVED_BY_RISK_ANALYSIS'
    else coalesce(
      nullif(upper(btrim(coalesce(p_payload_status, ''))), ''),
      nullif(replace(upper(btrim(coalesce(p_event_type, ''))), 'PAYMENT_', ''), '')
    )
  end;
$$;


ALTER FUNCTION private.asaas_payment_status_from_event(p_event_type text, p_payload_status text) OWNER TO postgres;

--
-- Name: asaas_payment_status_precedence(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.asaas_payment_status_precedence(p_status text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when private.billing_payment_checkout_is_reversal(p_status) then 500
    when upper(btrim(coalesce(p_status, ''))) in (
      'CHARGEBACK',
      'DELETED',
      'CANCELED',
      'CANCELLED',
      'CREDIT_CARD_CAPTURE_REFUSED',
      'REPROVED_BY_RISK_ANALYSIS'
    ) then 450
    when private.billing_payment_checkout_is_paid(p_status) then 300
    when private.billing_payment_checkout_is_processing(p_status) then 200
    when private.billing_payment_checkout_is_actionable(p_status) then 100
    else 50
  end;
$$;


ALTER FUNCTION private.asaas_payment_status_precedence(p_status text) OWNER TO postgres;

--
-- Name: attention_metadata_is_automated(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.attention_metadata_is_automated(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select
    lower(coalesce(value->>'is_automation', value->>'is_automated', value->>'automated', 'false')) in ('true', '1', 'yes')
    or lower(btrim(coalesce(value->>'origin', ''))) in (
      'ai', 'openai', 'automation', 'bot', 'ai_autoreply', 'ai_followup'
    )
    or lower(btrim(coalesce(value->>'origin', ''))) ~ '^(ai|automation)[_.]'
    or lower(coalesce(value->>'sender_type', '')) in ('ai', 'automation', 'bot');
$$;


ALTER FUNCTION private.attention_metadata_is_automated(value jsonb) OWNER TO postgres;

--
-- Name: audit_jsonb_diff(jsonb, jsonb, text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.audit_jsonb_diff(p_old jsonb, p_new jsonb, p_excluded_columns text[] DEFAULT ARRAY[]::text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with keys(key) as (
    select jsonb_object_keys(coalesce(p_old, '{}'::jsonb))
    union
    select jsonb_object_keys(coalesce(p_new, '{}'::jsonb))
  )
  select coalesce(
    jsonb_object_agg(
      key,
      jsonb_build_object('old', p_old -> key, 'new', p_new -> key)
      order by key
    ),
    '{}'::jsonb
  )
  from keys
  where not (key = any(p_excluded_columns))
    and (p_old -> key) is distinct from (p_new -> key);
$$;


ALTER FUNCTION private.audit_jsonb_diff(p_old jsonb, p_new jsonb, p_excluded_columns text[]) OWNER TO postgres;

--
-- Name: automation_assign_lead_user(uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.automation_assign_lead_user(p_organization_id uuid, p_lead_id uuid, p_user_id uuid, p_actor_user_id uuid, p_execution_id uuid, p_node_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  previous_user_id uuid;
  lead_team_id uuid;
  lead_name text;
  target_user_name text;
begin
  if p_user_id is null then
    raise exception 'automation_assignee_required';
  end if;

  select l.assigned_user_id, l.team_id, coalesce(nullif(l.name, ''), 'Lead')
  into previous_user_id, lead_team_id, lead_name
  from public.leads l
  where l.organization_id = p_organization_id and l.id = p_lead_id
  for update;
  if not found then
    raise exception 'automation_target_lead_not_found';
  end if;

  select coalesce(nullif(u.name, ''), nullif(u.email, ''), 'Usuario')
  into target_user_name
  from public.organization_members om
  join public.users u on u.id = om.user_id and coalesce(u.is_active, true) = true
  where om.organization_id = p_organization_id
    and om.user_id = p_user_id
    and coalesce(om.is_active, true) = true
    and om.deleted_at is null;
  if target_user_name is null then
    raise exception 'automation_assignee_not_active_in_organization';
  end if;

  if lead_team_id is not null and not exists (
    select 1 from public.team_members tm
    join public.organization_members team_membership
      on team_membership.organization_id = tm.organization_id
     and team_membership.user_id = tm.user_id
     and team_membership.is_active = true
     and team_membership.deleted_at is null
     and team_membership.membership_generation = tm.membership_generation
    where tm.organization_id = p_organization_id
      and tm.team_id = lead_team_id
      and tm.user_id = p_user_id
      and coalesce(tm.is_active, true) = true
  ) then
    raise exception 'automation_assignee_not_in_lead_team';
  end if;

  if previous_user_id is distinct from p_user_id then
    update public.leads
    set assigned_user_id = p_user_id,
        assigned_at = now(),
        updated_at = now()
    where organization_id = p_organization_id and id = p_lead_id;

    insert into public.assignments_log (
      organization_id, lead_id, old_user_id, new_user_id, reason, created_by
    ) values (
      p_organization_id, p_lead_id, previous_user_id, p_user_id,
      'automation_assignment', p_actor_user_id
    );

    perform private.notify_automation_attention(
      p_organization_id,
      p_lead_id,
      p_user_id,
      'Lead atribuido para voce',
      lead_name || ' foi atribuido por uma automacao.',
      'automation_lead_assigned',
      'automation-assignment:' || p_execution_id::text || ':' || p_node_key,
      jsonb_build_object(
        'execution_id', p_execution_id,
        'node_key', p_node_key,
        'previous_user_id', previous_user_id,
        'assigned_user_id', p_user_id
      )
    );
  end if;

  return jsonb_build_object(
    'assignment_changed', previous_user_id is distinct from p_user_id,
    'previous_user_id', previous_user_id,
    'assigned_user_id', p_user_id,
    'assigned_user_name', target_user_name
  );
end;
$$;


