--
-- Name: backfill_real_estate_foundation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.backfill_real_estate_foundation() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  with normalized as (
    select
      property.*,
      lower(
        concat_ws(
          ' ',
          nullif(btrim(property.finalidade), ''),
          nullif(btrim(property.tipo_de_negocio), '')
        )
      ) as deal_text,
      lower(coalesce(property.status, '')) as legacy_status
    from public.properties as property
  ),
  classified as (
    select
      normalized.*,
      (
        deal_text like '%venda%'
        or deal_text like '%sale%'
        or deal_text like '%lanc%'
      ) as has_sale,
      (
        deal_text like '%alug%'
        or deal_text like '%loca%'
        or deal_text like '%rent%'
      ) as has_rent,
      (
        deal_text like '%temporada%'
        or deal_text like '%season%'
      ) as has_seasonal
    from normalized
  ),
  offer_candidates as (
    select
      classified.*,
      candidate.offer_type,
      candidate.price,
      candidate.price_period
    from classified
    cross join lateral (
      values
        (
          'sale'::text,
          private.safe_legacy_property_offer_price(classified.preco),
          'total'::text,
          classified.has_sale
          or (
            not classified.has_sale
            and not classified.has_rent
            and not classified.has_seasonal
            and classified.preco is not null
          )
        ),
        (
          'rent'::text,
          coalesce(
            private.safe_legacy_property_offer_price(classified.valor_locacao),
            private.safe_legacy_property_offer_price(classified.preco)
          ),
          'monthly'::text,
          classified.has_rent and not classified.has_seasonal
        ),
        (
          'seasonal'::text,
          coalesce(
            private.safe_legacy_property_offer_price(classified.valor_locacao),
            private.safe_legacy_property_offer_price(classified.preco)
          ),
          'daily'::text,
          classified.has_seasonal
        )
    ) as candidate(offer_type, price, price_period, eligible)
    where candidate.eligible
  )
  insert into public.property_offers (
    organization_id,
    property_id,
    offer_type,
    status,
    price,
    currency,
    price_period,
    terms,
    created_by,
    metadata,
    created_at,
    updated_at
  )
  select
    candidate.organization_id,
    candidate.id,
    candidate.offer_type,
    case
      when candidate.offer_type = 'sale'
           and candidate.legacy_status in ('sold', 'vendido')
        then 'completed'
      when candidate.offer_type in ('rent', 'seasonal')
           and candidate.legacy_status in (
             'rented',
             'alugado',
             'locado'
           )
        then 'completed'
      when candidate.legacy_status in ('reserved', 'reservado')
        then 'reserved'
      when candidate.legacy_status in (
        'active',
        'available',
        'ativo',
        'disponivel'
      ) then 'active'
      when candidate.legacy_status in ('draft', 'rascunho')
        then 'draft'
      when candidate.legacy_status in (
        'inactive',
        'archived',
        'inativo',
        'arquivado'
      ) then 'withdrawn'
      else 'paused'
    end,
    candidate.price,
    'BRL',
    candidate.price_period,
    case
      when candidate.offer_type = 'sale' then
        jsonb_strip_nulls(
          jsonb_build_object(
            'payment_condition',
            nullif(btrim(candidate.condicao_pagamento), '')
          )
        )
      else
        jsonb_strip_nulls(
          jsonb_build_object(
            'condominium_fee', candidate.condominio,
            'property_tax', candidate.iptu,
            'fire_insurance', candidate.seguro_incendio,
            'service_fee', candidate.taxa_de_servico,
            'guarantee_insurance', candidate.valor_seguro_fianca
          )
        )
    end,
    case
      when private.property_user_belongs_to_organization(
        candidate.organization_id,
        candidate.created_by
      ) then candidate.created_by
    end,
    jsonb_build_object(
      'legacy_backfill', true,
      'legacy_deal_text', candidate.deal_text
    ),
    candidate.created_at,
    candidate.updated_at
  from offer_candidates as candidate
  on conflict do nothing;

  insert into public.property_ownerships (
    organization_id,
    property_id,
    owner_id,
    ownership_percentage,
    is_primary,
    valid_from,
    created_by,
    created_at,
    updated_at
  )
  select
    property.organization_id,
    property.id,
    property.owner_id,
    100,
    true,
    property.created_at::date,
    case
      when private.property_user_belongs_to_organization(
        property.organization_id,
        property.created_by
      ) then property.created_by
    end,
    property.created_at,
    property.updated_at
  from public.properties as property
  join public.property_owners as owner
    on owner.id = property.owner_id
   and owner.organization_id = property.organization_id
  where property.owner_id is not null
    and not exists (
      select 1
      from public.property_ownerships as existing
      where existing.property_id = property.id
    )
  on conflict do nothing;

  with raw_media as (
    select
      property.organization_id,
      property.id as property_id,
      'photo'::text as asset_type,
      nullif(btrim(property.imagem_principal), '') as locator,
      0 as sort_order,
      true as is_primary,
      'public'::text as visibility,
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end as created_by,
      property.created_at,
      property.updated_at
    from public.properties as property
    union all
    select
      property.organization_id,
      property.id,
      'photo',
      nullif(btrim(image.url), ''),
      10 + image.position::integer,
      false,
      'public',
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end as created_by,
      property.created_at,
      property.updated_at
    from public.properties as property
    cross join lateral unnest(
      coalesce(property.image_urls, '{}'::text[])
    ) with ordinality as image(url, position)
    union all
    select
      property.organization_id,
      property.id,
      'photo',
      nullif(
        btrim(
          case
            when jsonb_typeof(image.node) = 'string'
              then image.node #>> '{}'
            when jsonb_typeof(image.node) = 'object' then
              coalesce(
                image.node ->> 'url',
                image.node ->> 'src',
                image.node ->> 'path',
                image.node ->> 'storage_path'
              )
          end
        ),
        ''
      ),
      1000 + image.position::integer,
      false,
      'public',
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end,
      property.created_at,
      property.updated_at
    from public.properties as property
    cross join lateral jsonb_array_elements(
      case
        when jsonb_typeof(property.fotos) = 'array'
          then property.fotos
        else '[]'::jsonb
      end
    ) with ordinality as image(node, position)
    union all
    select
      property.organization_id,
      property.id,
      'video',
      nullif(btrim(property.video_imovel), ''),
      0,
      false,
      'public',
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end,
      property.created_at,
      property.updated_at
    from public.properties as property
    union all
    select
      property.organization_id,
      property.id,
      'virtual_tour',
      nullif(btrim(property.tour_virtual), ''),
      0,
      false,
      'public',
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end,
      property.created_at,
      property.updated_at
    from public.properties as property
  ),
  ranked_media as (
    select
      media.*,
      row_number() over (
        partition by media.property_id, media.asset_type, media.locator
        order by media.is_primary desc, media.sort_order
      ) as locator_rank
    from raw_media as media
    where media.locator is not null
  )
  insert into public.property_assets (
    organization_id,
    property_id,
    asset_type,
    visibility,
    storage_path,
    external_url,
    sort_order,
    is_primary,
    metadata,
    created_by,
    created_at,
    updated_at
  )
  select
    media.organization_id,
    media.property_id,
    media.asset_type,
    media.visibility,
    case
      when media.locator ~* '^[a-z][a-z0-9+.-]*://'
        then null
      else media.locator
    end,
    case
      when media.locator ~* '^[a-z][a-z0-9+.-]*://'
        then media.locator
      else null
    end,
    greatest(media.sort_order, 0),
    media.is_primary,
    jsonb_build_object('legacy_backfill', true),
    media.created_by,
    media.created_at,
    media.updated_at
  from ranked_media as media
  where media.locator_rank = 1
  on conflict do nothing;

  with document_nodes as (
    select
      property.organization_id,
      property.id as property_id,
      document.node,
      null::text as source_key,
      document.position::integer as position,
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end as created_by,
      property.created_at,
      property.updated_at
    from public.properties as property
    cross join lateral jsonb_array_elements(
      case
        when jsonb_typeof(property.documents) = 'array'
          then property.documents
        else '[]'::jsonb
      end
    ) with ordinality as document(node, position)
    union all
    select
      property.organization_id,
      property.id,
      document.node,
      null,
      1000 + document.position::integer,
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end,
      property.created_at,
      property.updated_at
    from public.properties as property
    cross join lateral jsonb_array_elements(
      case
        when jsonb_typeof(property.arquivos) = 'array'
          then property.arquivos
        else '[]'::jsonb
      end
    ) with ordinality as document(node, position)
    union all
    select
      property.organization_id,
      property.id,
      document.node,
      document.source_key,
      2000 + row_number() over (order by document.source_key)::integer,
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end,
      property.created_at,
      property.updated_at
    from public.properties as property
    cross join lateral jsonb_each(
      case
        when jsonb_typeof(property.documents) = 'object'
          and not (
            property.documents
            ?| array['url', 'href', 'path', 'storage_path']
          ) then property.documents
        else '{}'::jsonb
      end
    ) as document(source_key, node)
    union all
    select
      property.organization_id,
      property.id,
      property.documents,
      null,
      3000,
      case
        when private.property_user_belongs_to_organization(
          property.organization_id,
          property.created_by
        ) then property.created_by
      end,
      property.created_at,
      property.updated_at
    from public.properties as property
    where jsonb_typeof(property.documents) = 'object'
      and property.documents
        ?| array['url', 'href', 'path', 'storage_path']
  ),
  normalized_documents as (
    select
      document.*,
      nullif(
        btrim(
          case
            when jsonb_typeof(document.node) = 'string'
              then document.node #>> '{}'
            when jsonb_typeof(document.node) = 'object' then
              coalesce(
                document.node ->> 'url',
                document.node ->> 'href',
                document.node ->> 'path',
                document.node ->> 'storage_path'
              )
          end
        ),
        ''
      ) as locator,
      case
        when jsonb_typeof(document.node) = 'object' then
          coalesce(
            nullif(document.node ->> 'title', ''),
            nullif(document.node ->> 'name', ''),
            nullif(document.node ->> 'file_name', ''),
            document.source_key
          )
        else document.source_key
      end as title
    from document_nodes as document
  ),
  ranked_documents as (
    select
      document.*,
      row_number() over (
        partition by document.property_id, document.locator
        order by document.position
      ) as locator_rank
    from normalized_documents as document
    where document.locator is not null
  )
  insert into public.property_assets (
    organization_id,
    property_id,
    asset_type,
    visibility,
    storage_path,
    external_url,
    title,
    file_name,
    sort_order,
    is_primary,
    metadata,
    created_by,
    created_at,
    updated_at
  )
  select
    document.organization_id,
    document.property_id,
    'document',
    'internal',
    case
      when document.locator ~* '^[a-z][a-z0-9+.-]*://'
        then null
      else document.locator
    end,
    case
      when document.locator ~* '^[a-z][a-z0-9+.-]*://'
        then document.locator
      else null
    end,
    document.title,
    document.title,
    greatest(document.position, 0),
    false,
    jsonb_build_object('legacy_backfill', true),
    document.created_by,
    document.created_at,
    document.updated_at
  from ranked_documents as document
  where document.locator_rank = 1
  on conflict do nothing;

  insert into public.property_keys (
    organization_id,
    property_id,
    label,
    status,
    current_location,
    metadata,
    created_by,
    created_at,
    updated_at
  )
  select
    property.organization_id,
    property.id,
    'Chave principal',
    'available',
    btrim(property.local_chaves),
    jsonb_build_object('legacy_backfill', true),
    case
      when private.property_user_belongs_to_organization(
        property.organization_id,
        property.created_by
      ) then property.created_by
    end,
    property.created_at,
    property.updated_at
  from public.properties as property
  where nullif(btrim(property.local_chaves), '') is not null
  on conflict do nothing;
end;
$$;


ALTER FUNCTION private.backfill_real_estate_foundation() OWNER TO postgres;

--
-- Name: backfill_unambiguous_pipeline_default_round_robins(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.backfill_unambiguous_pipeline_default_round_robins() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  updated_count integer;
  ambiguous_count integer;
begin
  select count(*)
  into ambiguous_count
  from (
    select pipeline.id
    from public.pipelines as pipeline
    join public.round_robins as queue
      on queue.organization_id = pipeline.organization_id
     and queue.pipeline_id = pipeline.id
     and coalesce(queue.is_active, true) = true
    where pipeline.default_round_robin_id is null
    group by pipeline.id
    having count(*) > 1
  ) as ambiguous_pipeline;

  if ambiguous_count > 0 then
    raise warning
      'pipeline default round-robin backfill skipped % ambiguous pipeline(s)',
      ambiguous_count;
  end if;

  with unambiguous_candidates as (
    select
      pipeline.id as pipeline_id,
      (array_agg(queue.id order by queue.updated_at desc nulls last, queue.id))[1] as queue_id
    from public.pipelines as pipeline
    join public.round_robins as queue
      on queue.organization_id = pipeline.organization_id
     and queue.pipeline_id = pipeline.id
     and coalesce(queue.is_active, true) = true
    where pipeline.default_round_robin_id is null
    group by pipeline.id
    having count(*) = 1
  )
  update public.pipelines as pipeline
  set default_round_robin_id = candidate.queue_id,
      updated_at = clock_timestamp()
  from unambiguous_candidates as candidate
  where pipeline.id = candidate.pipeline_id
    and pipeline.default_round_robin_id is null;

  get diagnostics updated_count = row_count;
  return updated_count;
end;
$$;


ALTER FUNCTION private.backfill_unambiguous_pipeline_default_round_robins() OWNER TO postgres;

--
-- Name: FUNCTION backfill_unambiguous_pipeline_default_round_robins(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.backfill_unambiguous_pipeline_default_round_robins() IS 'Idempotently copies a legacy queue.pipeline_id fallback only when exactly one active candidate exists.';


--
-- Name: billing_card_recurrence_cancel_state(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_card_recurrence_cancel_state(p_organization_id uuid, p_provider_subscription_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case provision.job_status
    when 'processing' then 'processing'
    when 'dead' then 'manual_review'
    else 'queued'
  end
  from private.billing_card_recurrence_provisions as provision
  where provision.organization_id = p_organization_id
    and provision.provider_subscription_id = p_provider_subscription_id
    and provision.job_action = 'cancel'
    and provision.status = 'completed'
    and provision.job_status in ('pending', 'retry', 'processing', 'dead')
  order by case provision.job_status
    when 'processing' then 1
    when 'dead' then 2
    else 3
  end
  limit 1;
$$;


ALTER FUNCTION private.billing_card_recurrence_cancel_state(p_organization_id uuid, p_provider_subscription_id text) OWNER TO postgres;

--
-- Name: billing_card_recurrence_external_reference(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_card_recurrence_external_reference(p_payment_id uuid) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select 'vimob:billing-card-recurrence:' || p_payment_id::text;
$$;


ALTER FUNCTION private.billing_card_recurrence_external_reference(p_payment_id uuid) OWNER TO postgres;

--
-- Name: billing_checkout_organization_from_reference(text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_checkout_organization_from_reference(p_external_reference text, p_customer_id text, p_subscription_id text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select intent.organization_id
  from private.billing_checkout_intents intent
  where intent.external_reference = nullif(
      btrim(coalesce(p_external_reference, '')),
      ''
    )
    and (
      intent.provider_customer_id is null
      or nullif(btrim(coalesce(p_customer_id, '')), '') is null
      or intent.provider_customer_id = nullif(
        btrim(coalesce(p_customer_id, '')),
        ''
      )
    )
    and (
      intent.provider_subscription_id is null
      or nullif(btrim(coalesce(p_subscription_id, '')), '') is null
      or intent.provider_subscription_id = nullif(
        btrim(coalesce(p_subscription_id, '')),
        ''
      )
    )
  limit 1
$$;


ALTER FUNCTION private.billing_checkout_organization_from_reference(p_external_reference text, p_customer_id text, p_subscription_id text) OWNER TO postgres;

--
-- Name: billing_organization_cleanup_inventory_issue(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_organization_cleanup_inventory_issue(p_organization_id uuid, p_claim_token uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_claim private.billing_organization_asaas_cleanup_claims%rowtype;
  v_organization_active boolean;
  v_payment_ids text[] := '{}'::text[];
  v_subscription_ids text[] := '{}'::text[];
  v_customer_ids text[] := '{}'::text[];
  v_resource_payment_ids text[] := '{}'::text[];
  v_resource_subscription_ids text[] := '{}'::text[];
  v_resource_customer_ids text[] := '{}'::text[];
  v_expected_subscription_ids text[] := '{}'::text[];
  v_expected_customer_ids text[] := '{}'::text[];
  v_ownership_issue text;
begin
  select cleanup.*
  into v_claim
  from private.billing_organization_asaas_cleanup_claims as cleanup
  where cleanup.organization_id = p_organization_id
    and cleanup.claim_token = p_claim_token;
  if not found then
    return 'cleanup_claim_not_found';
  end if;
  if v_claim.last_error_code is not null then
    return v_claim.last_error_code;
  end if;

  select organization_row.is_active
  into v_organization_active
  from public.organizations as organization_row
  where organization_row.id = p_organization_id;
  if not found then
    return 'organization_not_found';
  end if;
  if v_organization_active then
    return 'organization_reactivated';
  end if;
  if private.billing_organization_has_unmaterialized_provider_payment(
    p_organization_id
  ) then
    return 'provider_payment_not_materialized';
  end if;
  if private.billing_subscription_delete_proof_has_live_conflict(
    p_organization_id
  ) then
    return 'provider_subscription_liveness_conflict';
  end if;

  select coalesce(
    array_agg(candidate.provider_id order by candidate.provider_id),
    '{}'::text[]
  )
  into v_subscription_ids
  from (
    select btrim(organization_row.asaas_subscription_id) as provider_id
    from public.organizations as organization_row
    where organization_row.id = p_organization_id
    union
    select btrim(subscription.provider_subscription_id)
    from public.subscriptions as subscription
    where subscription.organization_id = p_organization_id
    union
    select btrim(payment.asaas_subscription_id)
    from public.asaas_payments as payment
    where payment.organization_id = p_organization_id
    union
    select btrim(intent.provider_subscription_id)
    from private.billing_checkout_intents as intent
    where intent.organization_id = p_organization_id
    union
    select btrim(provision.provider_subscription_id)
    from private.billing_card_recurrence_provisions as provision
    where provision.organization_id = p_organization_id
    union
    select btrim(job.provider_subscription_id)
    from private.billing_subscription_card_update_jobs as job
    where job.organization_id = p_organization_id
    union
    select btrim(plan_change.provider_subscription_id)
    from private.billing_plan_changes as plan_change
    where plan_change.organization_id = p_organization_id
    union
    select btrim(job.provider_subscription_id)
    from private.asaas_reconciliation_jobs as job
    where job.organization_id = p_organization_id
    union
    select btrim(cancellation.provider_subscription_id)
    from private.billing_subscription_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
    union
    select btrim(cleanup.provider_subscription_id)
    from private.billing_organization_asaas_cleanup_claims as cleanup
    where cleanup.organization_id = p_organization_id
  ) as candidate
  where nullif(btrim(coalesce(candidate.provider_id, '')), '') is not null
    and (
      exists (
        select 1
        from private.billing_organization_asaas_cleanup_claims as cleanup
        where cleanup.organization_id = p_organization_id
          and cleanup.provider_subscription_id = candidate.provider_id
      )
      or not private.billing_subscription_provider_delete_is_proven(
        p_organization_id,
        candidate.provider_id
      )
    );

  select coalesce(
    array_agg(candidate.provider_id order by candidate.provider_id),
    '{}'::text[]
  )
  into v_customer_ids
  from (
    select btrim(organization_row.asaas_customer_id) as provider_id
    from public.organizations as organization_row
    where organization_row.id = p_organization_id
    union
    select btrim(subscription.provider_customer_id)
    from public.subscriptions as subscription
    where subscription.organization_id = p_organization_id
    union
    select btrim(payment.asaas_customer_id)
    from public.asaas_payments as payment
    where payment.organization_id = p_organization_id
    union
    select btrim(intent.provider_customer_id)
    from private.billing_checkout_intents as intent
    where intent.organization_id = p_organization_id
    union
    select btrim(provision.provider_customer_id)
    from private.billing_card_recurrence_provisions as provision
    where provision.organization_id = p_organization_id
    union
    select btrim(job.provider_customer_id)
    from private.billing_subscription_card_update_jobs as job
    where job.organization_id = p_organization_id
    union
    select btrim(cancellation.provider_customer_id)
    from private.billing_payment_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
    union
    select btrim(cancellation.provider_customer_id)
    from private.billing_subscription_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
    union
    select btrim(cleanup.provider_customer_id)
    from private.billing_organization_asaas_cleanup_claims as cleanup
    where cleanup.organization_id = p_organization_id
  ) as candidate
  where nullif(btrim(coalesce(candidate.provider_id, '')), '') is not null;

  select coalesce(
    array_agg(candidate.provider_payment_id order by candidate.provider_payment_id),
    '{}'::text[]
  )
  into v_payment_ids
  from (
    select distinct btrim(payment.asaas_payment_id) as provider_payment_id
    from public.asaas_payments as payment
    where payment.organization_id = p_organization_id
      and nullif(btrim(coalesce(payment.asaas_payment_id, '')), '') is not null
      and (
        private.billing_payment_checkout_is_actionable(payment.status)
        or private.billing_payment_checkout_is_processing(payment.status)
        or upper(btrim(coalesce(payment.status, ''))) = 'DELETED'
        or payment.raw_event #>>
          '{vimob_restore,provider_request_started_at}' is not null
      )
      and not private.billing_provider_payment_delete_is_proven(
        p_organization_id,
        payment.asaas_payment_id
      )
    union
    select provider_ref.provider_payment_id
    from private.billing_organization_provider_payment_references(
      p_organization_id
    ) as provider_ref
    where not private.billing_provider_payment_delete_is_proven(
      p_organization_id,
      provider_ref.provider_payment_id
    )
      and not exists (
        select 1
        from public.asaas_payments as payment
        where payment.organization_id = p_organization_id
          and payment.asaas_payment_id = provider_ref.provider_payment_id
      )
  ) as candidate;

  select
    coalesce(array_agg(resource.resource_id order by resource.resource_id)
      filter (where resource.resource_kind = 'payment'), '{}'::text[]),
    coalesce(array_agg(resource.resource_id order by resource.resource_id)
      filter (where resource.resource_kind = 'subscription'), '{}'::text[]),
    coalesce(array_agg(resource.resource_id order by resource.resource_id)
      filter (where resource.resource_kind = 'customer'), '{}'::text[])
  into
    v_resource_payment_ids,
    v_resource_subscription_ids,
    v_resource_customer_ids
  from private.billing_organization_asaas_cleanup_resources as resource
  where resource.organization_id = p_organization_id
    and resource.claim_token = p_claim_token;

  v_expected_subscription_ids := case
    when v_claim.provider_subscription_id is null then '{}'::text[]
    else array[v_claim.provider_subscription_id]
  end;
  v_expected_customer_ids := case
    when v_claim.provider_customer_id is null then '{}'::text[]
    else array[v_claim.provider_customer_id]
  end;

  if cardinality(v_payment_ids) > 10000
     or cardinality(v_payment_ids)
          + cardinality(v_subscription_ids)
          + cardinality(v_customer_ids) > 10002 then
    return 'resource_limit_exceeded';
  end if;
  if cardinality(v_subscription_ids) > 1 then
    return 'multiple_provider_subscriptions';
  end if;
  if cardinality(v_customer_ids) > 1 then
    return 'multiple_provider_customers';
  end if;
  if cardinality(v_customer_ids) = 0
     and (
       cardinality(v_subscription_ids) > 0
       or cardinality(v_payment_ids) > 0
     ) then
    return 'incomplete_provider_identity';
  end if;

  if not (v_payment_ids <@ v_claim.provider_payment_ids)
     or v_subscription_ids is distinct from v_expected_subscription_ids
     or v_customer_ids is distinct from v_expected_customer_ids
     or v_resource_payment_ids is distinct from v_claim.provider_payment_ids
     or v_resource_subscription_ids is distinct from v_expected_subscription_ids
     or v_resource_customer_ids is distinct from v_expected_customer_ids then
    return 'inventory_drift';
  end if;

  v_ownership_issue := private.billing_provider_identity_ownership_issue(
    p_organization_id,
    v_claim.provider_customer_id,
    v_claim.provider_subscription_id
  );
  if v_ownership_issue is not null then
    return v_ownership_issue;
  end if;

  if exists (
    select 1
    from private.asaas_reconciliation_jobs as job
    where job.organization_id = p_organization_id
      and (
        job.status <> 'dead'
        or job.last_error is distinct from 'organization_cleanup_won'
      )
  ) then
    return 'billing_reconciliation_not_terminal';
  end if;
  if exists (
    select 1
    from public.billing_payment_checkout_capabilities as capability
    where capability.organization_id = p_organization_id
      and (
        capability.revoked_at is null
        or capability.attempt_lease_id is not null
        or capability.attempt_lease_expires_at is not null
      )
  ) then
    return 'checkout_capability_not_terminal';
  end if;
  if exists (
    select 1
    from private.billing_payment_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
      and cancellation.finalized_at is null
  ) or exists (
    select 1
    from private.billing_subscription_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
      and cancellation.finalized_at is null
  ) then
    return 'checkout_cancellation_not_terminal';
  end if;

  return null;
end
$$;


ALTER FUNCTION private.billing_organization_cleanup_inventory_issue(p_organization_id uuid, p_claim_token uuid) OWNER TO postgres;

--
-- Name: billing_organization_cleanup_is_active(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_organization_cleanup_is_active(p_organization_id uuid, p_provider_subscription_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    exists (
      select 1
      from public.organizations as organization_row
      where organization_row.id = p_organization_id
        and organization_row.is_active = false
    )
    or exists (
      select 1
      from private.billing_organization_asaas_cleanup_claims as cleanup
      where cleanup.organization_id = p_organization_id
        -- A completed provider cleanup remains a permanent, organization-wide
        -- fence until the tenant row is physically purged. A stale/different
        -- subscription id must never bypass the destructive tenant tombstone.
    );
$$;


ALTER FUNCTION private.billing_organization_cleanup_is_active(p_organization_id uuid, p_provider_subscription_id text) OWNER TO postgres;

--
-- Name: billing_organization_has_unmaterialized_provider_payment(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_organization_has_unmaterialized_provider_payment(p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from private.billing_organization_provider_payment_references(
      p_organization_id
    ) as provider_ref
    where not exists (
        select 1
        from public.asaas_payments as payment
        where payment.organization_id = p_organization_id
          and payment.asaas_payment_id = btrim(provider_ref.provider_payment_id)
      )
      and not private.billing_provider_payment_delete_is_proven(
        p_organization_id,
        provider_ref.provider_payment_id
      )
  );
$$;


ALTER FUNCTION private.billing_organization_has_unmaterialized_provider_payment(p_organization_id uuid) OWNER TO postgres;

--
-- Name: billing_organization_provider_payment_references(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_organization_provider_payment_references(p_organization_id uuid) RETURNS TABLE(provider_payment_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select distinct btrim(candidate.provider_payment_id)
  from (
    select intent.provider_payment_id
    from private.billing_checkout_intents as intent
    where intent.organization_id = p_organization_id
    union all
    select cause.provider_payment_id
    from private.billing_organization_access_causes as cause
    where cause.organization_id = p_organization_id
    union all
    select provision.provider_payment_id
    from private.billing_card_recurrence_provisions as provision
    where provision.organization_id = p_organization_id
    union all
    select job.provider_payment_id
    from private.billing_subscription_card_update_jobs as job
    where job.organization_id = p_organization_id
    union all
    select cancellation.provider_payment_id
    from private.billing_payment_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
    union all
    select cancellation.provider_payment_id
    from private.billing_subscription_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
  ) as candidate
  where nullif(btrim(coalesce(candidate.provider_payment_id, '')), '') is not null;
$$;


ALTER FUNCTION private.billing_organization_provider_payment_references(p_organization_id uuid) OWNER TO postgres;

--
-- Name: billing_payment_checkout_is_actionable(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_payment_checkout_is_actionable(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select upper(btrim(coalesce(p_status, ''))) in (
    'CREATED',
    'PENDING',
    'OVERDUE',
    'DUNNING_REQUESTED',
    'DUNNING_RECEIVED',
    'BANK_SLIP_CANCELLED',
    'CREDIT_CARD_CAPTURE_REFUSED'
  );
$$;


ALTER FUNCTION private.billing_payment_checkout_is_actionable(p_status text) OWNER TO postgres;

--
-- Name: billing_payment_checkout_is_paid(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_payment_checkout_is_paid(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select upper(btrim(coalesce(p_status, ''))) in (
    'CONFIRMED',
    'RECEIVED',
    'RECEIVED_IN_CASH',
    'REFUND_DENIED'
  );
$$;


ALTER FUNCTION private.billing_payment_checkout_is_paid(p_status text) OWNER TO postgres;

--
-- Name: billing_payment_checkout_is_processing(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_payment_checkout_is_processing(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select upper(btrim(coalesce(p_status, ''))) in (
    'AWAITING_RISK_ANALYSIS',
    'AUTHORIZED',
    'PROCESSING'
  );
$$;


ALTER FUNCTION private.billing_payment_checkout_is_processing(p_status text) OWNER TO postgres;

--
-- Name: billing_payment_checkout_is_resolvable(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_payment_checkout_is_resolvable(p_payment_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.billing_payment_checkout_capabilities as capability
    join public.asaas_payments as payment
      on payment.id = capability.payment_id
      and payment.asaas_payment_id = capability.asaas_payment_id
      and payment.organization_id = capability.organization_id
      and payment.billing_intent_id is not distinct from capability.billing_intent_id
    where capability.payment_id = p_payment_id
      and capability.plan_id is not null
      and capability.billing_period_months in (1, 6, 12)
      and capability.amount > 0
      and payment.value is not null
      and abs(capability.amount - payment.value) <= 0.01
  );
$$;


ALTER FUNCTION private.billing_payment_checkout_is_resolvable(p_payment_id uuid) OWNER TO postgres;

--
-- Name: billing_payment_checkout_is_reversal(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_payment_checkout_is_reversal(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select upper(btrim(coalesce(p_status, ''))) in (
    'REFUNDED',
    'REFUND_REQUESTED',
    'REFUND_IN_PROGRESS',
    'PARTIALLY_REFUNDED',
    'RECEIVED_IN_CASH_UNDONE',
    'CHARGEBACK',
    'CHARGEBACK_REQUESTED',
    'CHARGEBACK_DISPUTE',
    'AWAITING_CHARGEBACK_REVERSAL'
  );
$$;


ALTER FUNCTION private.billing_payment_checkout_is_reversal(p_status text) OWNER TO postgres;

--
-- Name: billing_payment_checkout_is_terminal(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_payment_checkout_is_terminal(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select upper(btrim(coalesce(p_status, ''))) in (
    'CANCELED',
    'CANCELLED',
    'DELETED',
    'REFUNDED',
    'REFUND_REQUESTED',
    'REFUND_IN_PROGRESS',
    'PARTIALLY_REFUNDED',
    'RECEIVED_IN_CASH_UNDONE',
    'REPROVED_BY_RISK_ANALYSIS',
    'CHARGEBACK',
    'CHARGEBACK_REQUESTED',
    'CHARGEBACK_DISPUTE',
    'AWAITING_CHARGEBACK_REVERSAL'
  );
$$;


ALTER FUNCTION private.billing_payment_checkout_is_terminal(p_status text) OWNER TO postgres;

--
-- Name: billing_provider_identity_ownership_issue(uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_provider_identity_ownership_issue(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_customer_id text := nullif(btrim(coalesce(p_provider_customer_id, '')), '');
  v_subscription_id text := nullif(
    btrim(coalesce(p_provider_subscription_id, '')),
    ''
  );
begin
  if v_customer_id is not null and (
    exists (
      select 1 from public.organizations as owner
      where owner.id <> p_organization_id
        and btrim(coalesce(owner.asaas_customer_id, '')) = v_customer_id
    )
    or exists (
      select 1 from public.subscriptions as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_customer_id, '')) = v_customer_id
    )
    or exists (
      select 1 from public.asaas_payments as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.asaas_customer_id, '')) = v_customer_id
    )
    or exists (
      select 1 from private.billing_checkout_intents as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_customer_id, '')) = v_customer_id
    )
    or exists (
      select 1 from private.billing_card_recurrence_provisions as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_customer_id, '')) = v_customer_id
    )
    or exists (
      select 1 from private.billing_subscription_card_update_jobs as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_customer_id, '')) = v_customer_id
    )
    or exists (
      select 1 from private.billing_payment_checkout_cancellations as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_customer_id, '')) = v_customer_id
    )
    or exists (
      select 1 from private.billing_subscription_checkout_cancellations as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_customer_id, '')) = v_customer_id
    )
    or exists (
      select 1 from private.billing_organization_asaas_cleanup_claims as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_customer_id, '')) = v_customer_id
    )
  ) then
    return 'provider_customer_shared_across_organizations';
  end if;

  if v_subscription_id is not null and (
    exists (
      select 1 from public.organizations as owner
      where owner.id <> p_organization_id
        and btrim(coalesce(owner.asaas_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from public.subscriptions as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from public.asaas_payments as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.asaas_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from private.billing_checkout_intents as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from private.billing_card_recurrence_provisions as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from private.billing_subscription_card_update_jobs as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from private.billing_plan_changes as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from private.asaas_reconciliation_jobs as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from private.billing_subscription_checkout_cancellations as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_subscription_id, '')) = v_subscription_id
    )
    or exists (
      select 1 from private.billing_organization_asaas_cleanup_claims as owner
      where owner.organization_id <> p_organization_id
        and btrim(coalesce(owner.provider_subscription_id, '')) = v_subscription_id
    )
  ) then
    return 'provider_subscription_shared_across_organizations';
  end if;

  return null;
end
$$;


ALTER FUNCTION private.billing_provider_identity_ownership_issue(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text) OWNER TO postgres;

--
-- Name: billing_provider_payment_delete_is_proven(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_provider_payment_delete_is_proven(p_organization_id uuid, p_provider_payment_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(nullif(btrim(p_provider_payment_id), ''), '') <> ''
    and (
      exists (
        select 1
        from private.billing_payment_checkout_cancellations as cancellation
        where cancellation.organization_id = p_organization_id
          and cancellation.provider_payment_id = btrim(p_provider_payment_id)
          and cancellation.provider_delete_started_at is not null
          and cancellation.provider_deleted_at is not null
          and cancellation.provider_delete_result = 'deleted'
          and cancellation.finalized_at is not null
          and cancellation.final_outcome in ('cancelled', 'paid_after_delete')
      )
      or exists (
        select 1
        from private.billing_organization_asaas_cleanup_resources as resource
        where resource.organization_id = p_organization_id
          and resource.resource_kind = 'payment'
          and resource.resource_id = btrim(p_provider_payment_id)
          and resource.status = 'succeeded'
          and resource.provider_http_status = 200
          and jsonb_typeof(resource.provider_response -> 'id') = 'string'
          and resource.provider_response ->> 'id' = resource.resource_id
          and jsonb_typeof(resource.provider_response -> 'deleted') = 'boolean'
          and resource.provider_response -> 'deleted' = 'true'::jsonb
      )
    );
$$;


ALTER FUNCTION private.billing_provider_payment_delete_is_proven(p_organization_id uuid, p_provider_payment_id text) OWNER TO postgres;

--
-- Name: billing_subscription_delete_proof_has_live_conflict(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_subscription_delete_proof_has_live_conflict(p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with delete_proof(provider_subscription_id) as (
    select distinct cancellation.provider_subscription_id
    from private.billing_subscription_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
      and cancellation.provider_deleted_at is not null
      and cancellation.finalized_at is not null
      and cancellation.final_outcome in ('cancelled', 'paid_without_recurrence')
    union
    select distinct provision.provider_subscription_id
    from private.billing_card_recurrence_provisions as provision
    where provision.organization_id = p_organization_id
      and provision.provider_subscription_id is not null
      and provision.provider_cancelled_at is not null
      and provision.status = 'cancelled'
      and provision.job_action = 'cancel'
      and provision.job_status = 'succeeded'
  ),
  live_reference(provider_subscription_id) as (
    select organization_row.asaas_subscription_id
    from public.organizations as organization_row
    where organization_row.id = p_organization_id
      and nullif(btrim(coalesce(organization_row.asaas_subscription_id, '')), '')
        is not null
    union
    select subscription.provider_subscription_id
    from public.subscriptions as subscription
    where subscription.organization_id = p_organization_id
      and nullif(btrim(coalesce(subscription.provider_subscription_id, '')), '')
        is not null
      and lower(btrim(coalesce(subscription.status, '')))
        not in ('cancelled', 'canceled', 'inactive', 'expired', 'deleted')
    union
    select intent.provider_subscription_id
    from private.billing_checkout_intents as intent
    where intent.organization_id = p_organization_id
      and intent.status in ('creating', 'pending')
      and intent.provider_subscription_id is not null
    union
    select provision.provider_subscription_id
    from private.billing_card_recurrence_provisions as provision
    where provision.organization_id = p_organization_id
      and provision.provider_subscription_id is not null
      and provision.status = 'completed'
    union
    select job.provider_subscription_id
    from private.billing_subscription_card_update_jobs as job
    where job.organization_id = p_organization_id
      and job.status in (
        'prepared', 'awaiting_payment', 'pending_update', 'processing', 'retry'
      )
    union
    select plan_change.provider_subscription_id
    from private.billing_plan_changes as plan_change
    where plan_change.organization_id = p_organization_id
      and plan_change.status in ('provider_updating', 'scheduled', 'applying')
    union
    select job.provider_subscription_id
    from private.asaas_reconciliation_jobs as job
    where job.organization_id = p_organization_id
      and job.status in ('pending', 'retry', 'processing')
    union
    select cancellation.provider_subscription_id
    from private.billing_subscription_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
      and cancellation.finalized_at is null
  )
  select exists (
    select 1
    from delete_proof
    join live_reference using (provider_subscription_id)
  );
$$;


ALTER FUNCTION private.billing_subscription_delete_proof_has_live_conflict(p_organization_id uuid) OWNER TO postgres;

--
-- Name: billing_subscription_provider_delete_is_proven(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.billing_subscription_provider_delete_is_proven(p_organization_id uuid, p_provider_subscription_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from private.billing_subscription_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
      and cancellation.provider_subscription_id = p_provider_subscription_id
      and cancellation.provider_deleted_at is not null
      and cancellation.finalized_at is not null
      and cancellation.final_outcome in ('cancelled', 'paid_without_recurrence')
  ) or exists (
    select 1
    from private.billing_card_recurrence_provisions as provision
    where provision.organization_id = p_organization_id
      and provision.provider_subscription_id = p_provider_subscription_id
      and provision.provider_cancelled_at is not null
      and provision.status = 'cancelled'
      and provision.job_action = 'cancel'
      and provision.job_status = 'succeeded'
  );
$$;


ALTER FUNCTION private.billing_subscription_provider_delete_is_proven(p_organization_id uuid, p_provider_subscription_id text) OWNER TO postgres;

--
-- Name: bind_participant_membership_generation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.bind_participant_membership_generation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_generation bigint;
begin
  if tg_op = 'UPDATE'
     and coalesce(new.is_active, false) = false then
    return new;
  end if;

  if new.user_id is null then
    new.membership_generation := 1;
    return new;
  end if;

  select membership.membership_generation
  into current_generation
  from public.organization_members as membership
  where membership.organization_id = new.organization_id
    and membership.user_id = new.user_id
    and membership.is_active = true
    and membership.deleted_at is null
  for key share;

  if current_generation is null then
    raise exception using
      errcode = '23514',
      message = 'participant_requires_active_organization_membership';
  end if;

  new.membership_generation := current_generation;
  return new;
end;
$$;


ALTER FUNCTION private.bind_participant_membership_generation() OWNER TO postgres;

--
-- Name: block_notification_delivery(uuid, uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.block_notification_delivery(p_delivery_id uuid, p_lease_token uuid, p_dependency_key text, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_delivery private.notification_deliveries%rowtype;
  v_was_sending boolean;
begin
  if p_delivery_id is null
     or p_lease_token is null
     or nullif(btrim(coalesce(p_dependency_key, '')), '') is null
     or char_length(p_dependency_key) > 255
     or char_length(coalesce(p_error_code, '')) > 255
     or char_length(coalesce(p_error_message, '')) > 2000 then
    return false;
  end if;

  select delivery.*
    into v_delivery
  from private.notification_deliveries as delivery
  where delivery.id = p_delivery_id
    and delivery.status in ('leased', 'sending')
    and delivery.lease_token = p_lease_token
  for update;

  if not found then
    return false;
  end if;
  v_was_sending := v_delivery.status = 'sending';

  update private.notification_deliveries as delivery
  set status = 'blocked_dependency',
      attempt_count = case
        when v_was_sending then greatest(delivery.attempt_count - 1, 0)
        else delivery.attempt_count
      end,
      next_attempt_at = null,
      lease_token = null,
      leased_by = null,
      lease_expires_at = null,
      dependency_key = btrim(p_dependency_key),
      blocked_at = now(),
      terminal_at = null,
      last_error_code = nullif(left(btrim(coalesce(p_error_code, '')), 255), ''),
      last_error_message = nullif(left(btrim(coalesce(p_error_message, '')), 2000), ''),
      last_error_at = now(),
      updated_at = now()
  where delivery.id = p_delivery_id
    and delivery.lease_token = p_lease_token;

  if v_was_sending then
    update private.notification_delivery_attempts as attempt
    set outcome = 'blocked_dependency',
        completed_at = now(),
        error_code = nullif(left(btrim(coalesce(p_error_code, '')), 255), ''),
        error_message = nullif(left(btrim(coalesce(p_error_message, '')), 2000), ''),
        metadata = attempt.metadata || jsonb_build_object(
          'dependency_key', btrim(p_dependency_key),
          'budget_restored', true
        )
    where attempt.delivery_id = p_delivery_id
      and attempt.event_type = 'send_attempt'
      and attempt.lease_token = p_lease_token
      and attempt.outcome = 'sending';
  end if;

  return true;
end
$$;


ALTER FUNCTION private.block_notification_delivery(p_delivery_id uuid, p_lease_token uuid, p_dependency_key text, p_error_code text, p_error_message text) OWNER TO postgres;

--
-- Name: broadcast_audit_log_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.broadcast_audit_log_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.organization_id is null then
    return null;
  end if;

  begin
    perform realtime.send(
      jsonb_build_object('organizationId', new.organization_id),
      'audit.log.created',
      'audit:' || new.organization_id::text || ':feed',
      true
    );
  exception when others then
    return null;
  end;

  return null;
end;
$$;


ALTER FUNCTION private.broadcast_audit_log_change() OWNER TO postgres;

--
-- Name: broadcast_whatsapp_message_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.broadcast_whatsapp_message_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare message_row public.whatsapp_messages; v_attendant uuid;
begin
  message_row := case when tg_op = 'DELETE' then old else new end;
  if tg_op = 'INSERT' then
    select user_id into v_attendant from public.notifications
    where organization_id = message_row.organization_id
      and metadata->>'event_key' = 'whatsapp_inbound_attendant'
      and metadata->>'whatsapp_message_id' = message_row.id::text limit 1;
  end if;
  begin
    perform realtime.send(jsonb_build_object('scope', 'conversations'),
      'whatsapp.inbox.changed', 'whatsapp:' || message_row.organization_id::text || ':inbox', true);
  exception when others then null; end;
  if message_row.lead_id is not null then
    begin
      perform realtime.send(jsonb_build_object(
        'operation', tg_op, 'messageId', message_row.id,
        'conversationId', message_row.conversation_id,
        'clientMessageId', message_row.client_message_id, 'status', message_row.status,
        'sentAt', message_row.sent_at, 'createdAt', message_row.created_at,
        'organizationId', message_row.organization_id, 'fromMe', message_row.from_me,
        'direction', message_row.direction, 'captureState', message_row.capture_state,
        'attendantUserId', v_attendant),
        'whatsapp.message.changed',
        'whatsapp:' || message_row.organization_id::text || ':lead:' || message_row.lead_id::text, true);
    exception when others then null; end;
  end if;
  if tg_op = 'UPDATE' and old.lead_id is not null and old.lead_id is distinct from new.lead_id then
    begin
      perform realtime.send(jsonb_build_object(
        'operation', tg_op, 'messageId', old.id, 'conversationId', old.conversation_id,
        'clientMessageId', old.client_message_id, 'status', old.status, 'sentAt', old.sent_at),
        'whatsapp.message.changed', 'whatsapp:' || old.organization_id::text || ':lead:' || old.lead_id::text, true);
    exception when others then null; end;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION private.broadcast_whatsapp_message_change() OWNER TO postgres;

--
-- Name: can_access_lead(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_access_lead(target_organization_id uuid, assigned_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  select private.is_super_admin()
    or (
      private.is_org_member(target_organization_id)
      and (
        private.has_permission(target_organization_id, 'lead_view_all')
        or assigned_user_id = (select auth.uid())
        or private.has_org_role(target_organization_id, array['owner', 'admin', 'manager'])
        or (
          assigned_user_id is not null
          and private.has_permission(target_organization_id, 'lead_view_team')
          and exists (
            select 1
            from public.team_members leader
            join public.team_members member
              on member.organization_id = leader.organization_id
             and member.team_id = leader.team_id
             and coalesce(member.is_active, false) = true
            join public.organization_members leader_membership
              on leader_membership.organization_id = leader.organization_id
             and leader_membership.user_id = leader.user_id
             and leader_membership.is_active = true
             and leader_membership.deleted_at is null
             and leader_membership.membership_generation = leader.membership_generation
            join public.organization_members member_membership
              on member_membership.organization_id = member.organization_id
             and member_membership.user_id = member.user_id
             and member_membership.is_active = true
             and member_membership.deleted_at is null
             and member_membership.membership_generation = member.membership_generation
            where leader.organization_id = target_organization_id
              and leader.user_id = (select auth.uid())
              and coalesce(leader.is_active, false) = true
              and coalesce(leader.is_leader, false) = true
              and member.user_id = assigned_user_id
          )
        )
      )
    );
$$;


ALTER FUNCTION private.can_access_lead(target_organization_id uuid, assigned_user_id uuid) OWNER TO postgres;

--
-- Name: can_access_lead_by_id(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_access_lead_by_id(p_lead_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_lead_org_id uuid;
  v_lead_assigned_to uuid;
  v_user_org_id uuid;
BEGIN
  SELECT l.organization_id, l.assigned_user_id
  INTO v_lead_org_id, v_lead_assigned_to
  FROM public.leads l
  WHERE l.id = p_lead_id;

  IF p_user_id IS DISTINCT FROM (SELECT auth.uid()) THEN
    RETURN FALSE;
  END IF;

  IF v_lead_org_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT u.organization_id INTO v_user_org_id
  FROM public.users u
  WHERE u.id = p_user_id;

  IF v_user_org_id IS NULL OR v_user_org_id != v_lead_org_id THEN
    RETURN FALSE;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members actor_membership
    JOIN public.users actor_profile ON actor_profile.id = actor_membership.user_id
    WHERE actor_membership.organization_id = v_lead_org_id
      AND actor_membership.user_id = p_user_id
      AND actor_membership.is_active = true
      AND actor_membership.deleted_at is null
      AND actor_profile.is_active = true
  ) THEN
    RETURN FALSE;
  END IF;

  IF public.is_super_admin()
     OR public.is_admin()
     OR public.user_has_permission('lead_view_all', p_user_id)
     OR public.user_has_permission('lead_edit_all', p_user_id) THEN
    RETURN TRUE;
  END IF;

  IF v_lead_assigned_to = p_user_id THEN
    RETURN TRUE;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.team_members tm_leader
    JOIN public.team_members tm_assigned ON tm_assigned.team_id = tm_leader.team_id
    JOIN public.organization_members leader_membership
      ON leader_membership.organization_id = v_lead_org_id
     AND leader_membership.organization_id = tm_leader.organization_id
     AND leader_membership.user_id = tm_leader.user_id
     AND leader_membership.is_active = true
     AND leader_membership.deleted_at is null
     AND leader_membership.membership_generation = tm_leader.membership_generation
    JOIN public.organization_members assignee_membership
      ON assignee_membership.organization_id = v_lead_org_id
     AND assignee_membership.organization_id = tm_assigned.organization_id
     AND assignee_membership.user_id = tm_assigned.user_id
     AND assignee_membership.is_active = true
     AND assignee_membership.deleted_at is null
     AND assignee_membership.membership_generation = tm_assigned.membership_generation
    WHERE tm_leader.user_id = p_user_id
      AND tm_leader.is_leader = true
      AND coalesce(tm_leader.is_active, false) = true
      AND coalesce(tm_assigned.is_active, false) = true
      AND tm_assigned.user_id = v_lead_assigned_to
  ) THEN
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION private.can_access_lead_by_id(p_lead_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: can_access_schedule_event(uuid, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_access_schedule_event(p_event_id uuid, p_require_full_details boolean DEFAULT true) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  with ctx as (
    select
      auth.uid() as user_id,
      public.get_user_organization_id() as organization_id,
      public.is_admin() as is_admin,
      public.is_super_admin() as is_super_admin
  )
  select exists (
    select 1
    from public.schedule_events e
    cross join ctx
    where e.id = p_event_id
      and ctx.user_id is not null
      and (
        ctx.is_super_admin
        or (
          e.organization_id = ctx.organization_id
          and (
            case
              when p_require_full_details then
                coalesce(e.visibility, 'default') = 'default'
                or e.user_id = ctx.user_id
                or ctx.is_admin
                or public.is_schedule_event_assignee(e.id, ctx.user_id)
              else
                coalesce(e.visibility, 'default') in ('default', 'public')
                or e.user_id = ctx.user_id
                or ctx.is_admin
                or public.is_schedule_event_assignee(e.id, ctx.user_id)
            end
          )
        )
      )
  );
$$;


ALTER FUNCTION private.can_access_schedule_event(p_event_id uuid, p_require_full_details boolean) OWNER TO postgres;

--
-- Name: can_manage_round_robin_as_leader(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_manage_round_robin_as_leader(p_round_robin_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.round_robins rr
    where rr.id = p_round_robin_id
      and rr.organization_id = public.get_user_organization_id()
      and rr.target_pipeline_id is not null
      and (
        (rr.created_by = p_user_id and public.is_team_leader(p_user_id))
        or public.is_pipeline_in_led_team(rr.target_pipeline_id, p_user_id)
        or exists (
          select 1
          from public.round_robin_members rrm
          where rrm.round_robin_id = rr.id
            and (
              (rrm.team_id is not null and public.is_user_leader_of_team(rrm.team_id, p_user_id))
              or (rrm.team_id is null and public.is_user_in_led_team(rrm.user_id, p_user_id))
            )
        )
      )
  );
$$;


ALTER FUNCTION private.can_manage_round_robin_as_leader(p_round_robin_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: can_manage_whatsapp_session(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_manage_whatsapp_session(p_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.whatsapp_sessions ws
    where ws.id = p_session_id
      and (
        exists (
          select 1
          from public.users u
          where u.id = auth.uid()
            and u.role = 'super_admin'
            and coalesce(u.is_active, true) = true
        )
        or (
          private.is_org_member(ws.organization_id)
          and ws.owner_user_id = auth.uid()
        )
      )
  );
$$;


ALTER FUNCTION private.can_manage_whatsapp_session(p_session_id uuid) OWNER TO postgres;

--
-- Name: can_read_lead(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_read_lead(target_organization_id uuid, target_assigned_user_id uuid, target_team_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select private.is_super_admin()
    or (
      private.is_org_member(target_organization_id)
      and (
        private.lead_view_all_granted(target_organization_id)
        or (
          target_assigned_user_id = (select auth.uid())
          and not exists (
            select 1
            from public.user_permission_overrides as denied_own_permission
            where denied_own_permission.organization_id = target_organization_id
              and denied_own_permission.user_id = (select auth.uid())
              and pg_catalog.lower(pg_catalog.btrim(denied_own_permission.permission_key)) = 'lead_view_own'
              and denied_own_permission.allowed = false
          )
        )
        or exists (
          select 1
          from public.team_members as leader
          join public.organization_members as leader_membership
            on leader_membership.organization_id = leader.organization_id
           and leader_membership.user_id = leader.user_id
           and leader_membership.is_active = true
           and leader_membership.deleted_at is null
           and leader_membership.membership_generation = leader.membership_generation
          join public.teams as led_team
            on led_team.id = leader.team_id
           and led_team.organization_id = leader.organization_id
           and coalesce(led_team.is_active, true) = true
          where leader.organization_id = target_organization_id
            and leader.user_id = (select auth.uid())
            and coalesce(leader.is_active, false) = true
            and coalesce(leader.is_leader, false) = true
            and not exists (
              select 1
              from public.user_permission_overrides as denied_permission
              where denied_permission.organization_id = target_organization_id
                and denied_permission.user_id = leader.user_id
                and lower(btrim(denied_permission.permission_key)) = 'lead_view_team'
                and denied_permission.allowed = false
            )
            and (
              (target_assigned_user_id is null and led_team.id = target_team_id)
              or (
                target_assigned_user_id is not null
                and exists (
                  select 1
                  from public.team_members as broker_member
                  join public.users as broker
                    on broker.id = broker_member.user_id
                   and coalesce(broker.is_active, false) = true
                  join public.organization_members as broker_organization_member
                    on broker_organization_member.organization_id = broker_member.organization_id
                   and broker_organization_member.user_id = broker_member.user_id
                   and coalesce(broker_organization_member.is_active, false) = true
                   and broker_organization_member.deleted_at is null
                   and broker_organization_member.membership_generation = broker_member.membership_generation
                  where broker_member.organization_id = target_organization_id
                    and broker_member.team_id = led_team.id
                    and broker_member.user_id = target_assigned_user_id
                    and coalesce(broker_member.is_active, false) = true
                )
              )
            )
        )
      )
    );
$$;


ALTER FUNCTION private.can_read_lead(target_organization_id uuid, target_assigned_user_id uuid, target_team_id uuid) OWNER TO postgres;

--
-- Name: can_read_lead_by_id(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_read_lead_by_id(p_lead_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$select (
    select exists (
      select 1
      from public.leads as lead
      where lead.id = p_lead_id
        and private.can_read_lead(
          lead.organization_id,
          lead.assigned_user_id,
          lead.team_id
        )
    )) and coalesce(private.queue_pool_related_read_access(p_lead_id,(select auth.uid())),true)$$;


ALTER FUNCTION private.can_read_lead_by_id(p_lead_id uuid) OWNER TO postgres;

--
-- Name: can_read_management_distribution(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_read_management_distribution(p_organization_id uuid, p_queue_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  actor_role text;
  member_role text;
  queue_creator uuid;
  queue_pipeline uuid;
  led_teams uuid[];
  led_users uuid[];
  led_pipelines uuid[];
  effective_keys text[];
  override_allowed boolean;
begin
  if actor_id is null or p_organization_id is null or p_queue_id is null
     or not private.has_active_lead_read_session() then return false; end if;
  select queue.created_by, queue.pipeline_id into queue_creator, queue_pipeline
  from public.round_robins queue
  where queue.id = p_queue_id and queue.organization_id = p_organization_id and queue.deleted_at is null;
  if not found then return false; end if;

  select lower(btrim(account.role)) into actor_role from public.users account
  where account.id = actor_id and coalesce(account.is_active, false);
  if not found then return false; end if;
  if actor_role = 'super_admin' then return true; end if;
  if private.get_user_organization_id() is distinct from p_organization_id then return false; end if;
  select lower(btrim(coalesce(nullif(member.role, ''), 'user'))) into member_role
  from public.organization_members member
  join public.organizations organization on organization.id = member.organization_id
  where member.organization_id = p_organization_id and member.user_id = actor_id
    and coalesce(member.is_active, false) and member.deleted_at is null
    and coalesce(organization.is_active, true);
  if not found then return false; end if;
  if member_role in ('owner', 'admin') then return true; end if;

  -- No built-in manager/leader default implies DistributionManage. Go Expand
  -- has no alias or composite expansion that grants this permission.
  select coalesce(array_agg(distinct lower(btrim(permission.key))), array[]::text[]) into effective_keys
  from public.user_organization_roles assignment
  join public.organization_roles role
    on role.id = assignment.role_id and role.organization_id = assignment.organization_id
  join public.organization_role_permissions grant_row
    on grant_row.role_id = role.id and grant_row.organization_id = role.organization_id
  join public.available_permissions permission on permission.id = grant_row.permission_id
  where assignment.user_id = actor_id and assignment.organization_id = p_organization_id
    and coalesce(assignment.is_active, false) and coalesce(role.is_active, false);
  if not ('*' = any(effective_keys)) then
    -- Contradictory legacy spellings are ambiguous in Go's override map;
    -- deny this additional Data API path until the ambiguity is repaired.
    if exists (
      select 1 from public.user_permission_overrides override
      where override.organization_id = p_organization_id and override.user_id = actor_id
        and lower(btrim(override.permission_key)) = 'distribution_manage'
      having bool_or(coalesce(override.allowed, false)) and bool_or(not coalesce(override.allowed, false))
    ) then return false; end if;
    select override.allowed into override_allowed from public.user_permission_overrides override
    where override.organization_id = p_organization_id and override.user_id = actor_id
      and lower(btrim(override.permission_key)) = 'distribution_manage' limit 1;
    if found then
      if not coalesce(override_allowed, false) then return false; end if;
    elsif not ('distribution_manage' = any(effective_keys)) then return false;
    end if;
  end if;

  -- Generation-aware leadership matches tenant.Repository.RefreshLeadership.
  select coalesce(array_agg(distinct team.id), array[]::uuid[]) into led_teams
  from public.team_members leader
  join public.teams team on team.id = leader.team_id and team.organization_id = leader.organization_id
  join public.organization_members membership
    on membership.organization_id = leader.organization_id and membership.user_id = leader.user_id
   and membership.is_active = true and membership.deleted_at is null
   and membership.membership_generation = leader.membership_generation
  where leader.organization_id = p_organization_id and leader.user_id = actor_id
    and coalesce(leader.is_active, true) and coalesce(leader.is_leader, false) and coalesce(team.is_active, true);
  if cardinality(led_teams) = 0 then return true; end if;
  select coalesce(array_agg(distinct member.user_id), array[]::uuid[]) || array[actor_id] into led_users
  from public.team_members member
  join public.users account on account.id = member.user_id
  join public.organization_members membership
    on membership.organization_id = member.organization_id and membership.user_id = member.user_id
   and membership.is_active = true and membership.deleted_at is null
   and membership.membership_generation = member.membership_generation
  where member.organization_id = p_organization_id and member.team_id = any(led_teams)
    and coalesce(member.is_active, true) and coalesce(account.is_active, false);
  select coalesce(array_agg(distinct link.pipeline_id), array[]::uuid[]) into led_pipelines
  from public.team_pipelines link
  join public.pipelines pipeline on pipeline.id = link.pipeline_id and pipeline.organization_id = link.organization_id
  where link.organization_id = p_organization_id and link.team_id = any(led_teams) and coalesce(pipeline.is_active, true);
  return coalesce(queue_creator = actor_id, false) or coalesce(queue_pipeline = any(led_pipelines), false) or exists (
    select 1 from public.round_robin_members member
    where member.organization_id = p_organization_id and member.round_robin_id = p_queue_id
      and coalesce(member.is_active, true)
      and (member.team_id = any(led_teams) or member.user_id = any(led_users))
  );
end;
$$;


ALTER FUNCTION private.can_read_management_distribution(p_organization_id uuid, p_queue_id uuid) OWNER TO postgres;

--
-- Name: can_read_management_team(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_read_management_team(p_organization_id uuid, p_team_id uuid, p_pipeline_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  actor_role text;
  member_role text;
  is_leader boolean;
  target_is_led boolean;
  effective_keys text[];
  required_permission_key text;
  override_allowed boolean;
begin
  if actor_id is null or p_organization_id is null or p_team_id is null
     or not private.has_active_lead_read_session()
     or not exists (select 1 from public.teams team
                    where team.id = p_team_id and team.organization_id = p_organization_id)
     or (p_pipeline_id is not null and not exists (
       select 1 from public.pipelines pipeline
       where pipeline.id = p_pipeline_id and pipeline.organization_id = p_organization_id
     )) then return false; end if;

  select pg_catalog.lower(pg_catalog.btrim(account.role)) into actor_role
  from public.users account
  where account.id = actor_id and coalesce(account.is_active, false);
  if not found then return false; end if;
  -- Existing permissive policies retain their selected-org/global-superadmin
  -- boundary. No JWT role or user_metadata claim can grant this bypass.
  if actor_role = 'super_admin' then return true; end if;
  if private.get_user_organization_id() is distinct from p_organization_id then return false; end if;

  select pg_catalog.lower(pg_catalog.btrim(coalesce(nullif(member.role, ''), 'user'))) into member_role
  from public.organization_members member
  join public.organizations organization on organization.id = member.organization_id
  where member.organization_id = p_organization_id and member.user_id = actor_id
    and coalesce(member.is_active, false) and member.deleted_at is null
    and coalesce(organization.is_active, true);
  if not found then return false; end if;
  if member_role in ('owner', 'admin') then return true; end if;

  select count(*) > 0, coalesce(bool_or(team.id = p_team_id), false)
  into is_leader, target_is_led
  from public.team_members leader
  join public.teams team on team.id = leader.team_id and team.organization_id = leader.organization_id
  join public.organization_members membership
    on membership.organization_id = leader.organization_id and membership.user_id = leader.user_id
   and membership.is_active = true and membership.deleted_at is null
   and membership.membership_generation = leader.membership_generation
  where leader.organization_id = p_organization_id and leader.user_id = actor_id
    and coalesce(leader.is_active, true) and coalesce(leader.is_leader, false)
    and coalesce(team.is_active, true);

  -- Match permissions.Expand for only the four keys relevant to TeamView.
  -- The gateway loads role grants through available_permissions.id/key; a
  -- stale permission_key text alone must not create a grant absent in Go.
  select coalesce(array_agg(distinct expanded.key), array[]::text[]) into effective_keys
  from public.user_organization_roles assignment
  join public.organization_roles role
    on role.id = assignment.role_id and role.organization_id = assignment.organization_id
  join public.organization_role_permissions grant_row
    on grant_row.role_id = role.id and grant_row.organization_id = role.organization_id
  join public.available_permissions permission on permission.id = grant_row.permission_id
  cross join lateral unnest(case pg_catalog.lower(pg_catalog.btrim(permission.key))
    when 'settings_manage' then array['team_manage', 'pipeline_manage']
    when 'settings_teams' then array['team_manage']
    when 'teams_manage' then array['team_manage']
    when 'pipeline_edit' then array['pipeline_manage']
    when 'settings_pipelines' then array['pipeline_manage']
    when 'cadences_manage' then array['pipeline_manage']
    else array[pg_catalog.lower(pg_catalog.btrim(permission.key))]
  end) expanded(key)
  where assignment.user_id = actor_id and assignment.organization_id = p_organization_id
    and coalesce(assignment.is_active, false) and coalesce(role.is_active, false);

  if not ('*' = any(effective_keys)) then
    -- Canonical writes never create contradictory alias rows. If legacy data
    -- does, do not pick an arbitrary grant: Go iterates its override map without
    -- a stable alias order. This actor needs that ambiguity repaired first.
    if exists (
      select 1 from public.user_permission_overrides denied
      cross join lateral (select case pg_catalog.lower(pg_catalog.btrim(denied.permission_key))
        when 'settings_teams' then 'team_manage' when 'teams_manage' then 'team_manage'
        when 'pipeline_edit' then 'pipeline_manage' when 'settings_pipelines' then 'pipeline_manage'
        when 'cadences_manage' then 'pipeline_manage'
        else pg_catalog.lower(pg_catalog.btrim(denied.permission_key)) end as key) canonical
      where denied.organization_id = p_organization_id and denied.user_id = actor_id
        and canonical.key in ('team_view','team_manage','pipeline_manage','distribution_manage')
      group by canonical.key
      having bool_or(coalesce(denied.allowed,false)) and bool_or(not coalesce(denied.allowed,false))
    ) then return false; end if;
    if member_role = 'manager' or is_leader then effective_keys := effective_keys || array['team_view']; end if;
    if is_leader then effective_keys := effective_keys || array['team_manage']; end if;
    -- Unlike grants above, current Resolve only accepts canonical/simple alias
    -- overrides. Composite settings_manage overrides are ignored in Go and SQL.
    foreach required_permission_key in array array['team_view', 'team_manage', 'pipeline_manage', 'distribution_manage'] loop
      select override.allowed into override_allowed
      from public.user_permission_overrides override
      where override.organization_id = p_organization_id and override.user_id = actor_id
        and (case pg_catalog.lower(pg_catalog.btrim(override.permission_key))
          when 'settings_teams' then 'team_manage' when 'teams_manage' then 'team_manage'
          when 'pipeline_edit' then 'pipeline_manage' when 'settings_pipelines' then 'pipeline_manage'
          when 'cadences_manage' then 'pipeline_manage'
          else pg_catalog.lower(pg_catalog.btrim(override.permission_key)) end) = required_permission_key
      limit 1;
      if found then
        effective_keys := array_remove(effective_keys, required_permission_key);
        if override_allowed then effective_keys := effective_keys || array[required_permission_key]; end if;
      end if;
    end loop;
    -- Resolve reapplies implications AFTER overrides. A denied TeamView is
    -- implied again by any effective management permission, exactly as in Go.
    if not ('team_view' = any(effective_keys) or 'team_manage' = any(effective_keys)
            or 'pipeline_manage' = any(effective_keys) or 'distribution_manage' = any(effective_keys)) then
      return false;
    end if;
  end if;
  return member_role = 'manager' or not is_leader or target_is_led;
end;
$$;


ALTER FUNCTION private.can_read_management_team(p_organization_id uuid, p_team_id uuid, p_pipeline_id uuid) OWNER TO postgres;

--
-- Name: can_read_management_team_member(uuid, uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_read_management_team_member(p_organization_id uuid, p_team_id uuid, p_user_id uuid, p_membership_generation bigint, p_is_active boolean) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(p_is_active, true)
    and private.can_read_management_team(p_organization_id, p_team_id, null)
    and exists (
      select 1 from public.users account
      join public.organization_members membership on membership.user_id = account.id
       and membership.organization_id = p_organization_id
       and membership.is_active = true and membership.deleted_at is null
       and membership.membership_generation = p_membership_generation
      where account.id = p_user_id and coalesce(account.is_active, false)
    );
$$;


ALTER FUNCTION private.can_read_management_team_member(p_organization_id uuid, p_team_id uuid, p_user_id uuid, p_membership_generation bigint, p_is_active boolean) OWNER TO postgres;

--
-- Name: can_receive_audit_broadcast(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_receive_audit_broadcast(p_topic text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  topic_organization_id uuid;
  token_session_id uuid;
begin
  if split_part(p_topic, ':', 1) <> 'audit' then
    return false;
  end if;

  topic_organization_id := private.safe_uuid(split_part(p_topic, ':', 2));
  token_session_id := private.safe_uuid(auth.jwt() ->> 'session_id');
  if topic_organization_id is null or token_session_id is null then
    return false;
  end if;

  return p_topic = 'audit:' || topic_organization_id::text || ':feed'
    and exists (
      select 1
      from auth.sessions session
      where session.id = token_session_id
        and session.user_id = auth.uid()
    )
    and private.has_org_role(topic_organization_id, array['owner', 'admin', 'manager']);
end;
$$;


ALTER FUNCTION private.can_receive_audit_broadcast(p_topic text) OWNER TO postgres;

--
-- Name: can_receive_whatsapp_broadcast(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_receive_whatsapp_broadcast(p_topic text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  topic_organization_id uuid;
  topic_lead_id uuid;
begin
  if auth.uid() is null then
    return false;
  end if;

  if split_part(p_topic, ':', 1) = 'audit' then
    return private.can_receive_audit_broadcast(p_topic);
  end if;

  if split_part(p_topic, ':', 1) <> 'whatsapp' then
    return false;
  end if;

  topic_organization_id := private.safe_uuid(split_part(p_topic, ':', 2));
  if topic_organization_id is null
     or not private.has_effective_whatsapp_view(topic_organization_id) then
    return false;
  end if;

  if split_part(p_topic, ':', 3) = 'inbox' then
    return p_topic = 'whatsapp:' || topic_organization_id::text || ':inbox';
  end if;

  if split_part(p_topic, ':', 3) <> 'lead' then
    return false;
  end if;

  topic_lead_id := private.safe_uuid(split_part(p_topic, ':', 4));
  if topic_lead_id is null
     or p_topic <> 'whatsapp:' || topic_organization_id::text || ':lead:' || topic_lead_id::text then
    return false;
  end if;

  return exists (
    select 1
    from public.leads as lead
    where lead.id = topic_lead_id
      and lead.organization_id = topic_organization_id
      and private.whatsapp_actor_can_read_lead(lead.organization_id, lead.id, (select auth.uid()))
  );
end;
$$;


ALTER FUNCTION private.can_receive_whatsapp_broadcast(p_topic text) OWNER TO postgres;

--
-- Name: can_track_public_site(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_track_public_site(target_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select target_organization_id is not null
    and exists (
      select 1
      from public.organization_sites site
      join public.organizations organization
        on organization.id = site.organization_id
      where site.organization_id = target_organization_id
        and site.is_active = true
        and coalesce(organization.is_active, true) = true
    );
$$;


ALTER FUNCTION private.can_track_public_site(target_organization_id uuid) OWNER TO postgres;

--
-- Name: can_use_organization_presence(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_use_organization_presence(p_topic text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  topic_organization_id uuid;
begin
  if split_part(p_topic, ':', 1) <> 'presence' then
    return false;
  end if;

  topic_organization_id := private.safe_uuid(split_part(p_topic, ':', 2));
  if topic_organization_id is null then
    return false;
  end if;

  return p_topic = 'presence:' || topic_organization_id::text || ':online'
    and private.is_org_member(topic_organization_id);
end;
$$;


ALTER FUNCTION private.can_use_organization_presence(p_topic text) OWNER TO postgres;

--
-- Name: can_view_property_owner_record(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_view_property_owner_record(target_organization_id uuid, target_owner_id uuid, target_created_by uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    target_organization_id is not null
    and target_owner_id is not null
    and (select auth.uid()) is not null
    and (
      private.has_permission(target_organization_id, 'property_manage')
      or (
        private.has_permission(target_organization_id, 'property_view')
        and (
          target_created_by = (select auth.uid())
          or exists (
            select 1
            from public.properties as property
            where property.organization_id = target_organization_id
              and property.owner_id = target_owner_id
              and private.can_view_property_record(
                property.organization_id,
                property.created_by,
                property.responsible_user_id
              )
          )
          or exists (
            select 1
            from public.property_ownerships as ownership
            join public.properties as property
              on property.organization_id = ownership.organization_id
             and property.id = ownership.property_id
            where ownership.organization_id = target_organization_id
              and ownership.owner_id = target_owner_id
              and ownership.valid_from <= current_date
              and (
                ownership.valid_to is null
                or current_date < ownership.valid_to
              )
              and private.can_view_property_record(
                property.organization_id,
                property.created_by,
                property.responsible_user_id
              )
          )
        )
      )
    );
$$;


ALTER FUNCTION private.can_view_property_owner_record(target_organization_id uuid, target_owner_id uuid, target_created_by uuid) OWNER TO postgres;

--
-- Name: FUNCTION can_view_property_owner_record(target_organization_id uuid, target_owner_id uuid, target_created_by uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.can_view_property_owner_record(target_organization_id uuid, target_owner_id uuid, target_created_by uuid) IS 'Restricts owner rows to managers or owners currently linked to properties visible in own/team scope.';


--
-- Name: can_view_property_record(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_view_property_record(target_organization_id uuid, target_created_by uuid, target_responsible_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    target_organization_id is not null
    and (select auth.uid()) is not null
    and (
      private.has_permission(target_organization_id, 'property_manage')
      or (
        private.has_permission(target_organization_id, 'property_view')
        and (
          coalesce(target_created_by = (select auth.uid()), false)
          or coalesce(target_responsible_user_id = (select auth.uid()), false)
          or exists (
            select 1
            from public.team_members as leader_member
            join public.teams as team
              on team.id = leader_member.team_id
             and team.organization_id = target_organization_id
             and coalesce(team.is_active, true) = true
            join public.organization_members as leader_membership
              on leader_membership.organization_id = target_organization_id
             and leader_membership.user_id = leader_member.user_id
             and leader_membership.is_active = true
             and leader_membership.deleted_at is null
             and leader_membership.membership_generation = leader_member.membership_generation
            join public.team_members as scoped_member
              on scoped_member.team_id = leader_member.team_id
             and scoped_member.organization_id = target_organization_id
             and coalesce(scoped_member.is_active, true) = true
            join public.organization_members as scoped_membership
              on scoped_membership.organization_id = target_organization_id
             and scoped_membership.user_id = scoped_member.user_id
             and scoped_membership.is_active = true
             and scoped_membership.deleted_at is null
             and scoped_membership.membership_generation = scoped_member.membership_generation
            where leader_member.organization_id = target_organization_id
              and leader_member.user_id = (select auth.uid())
              and coalesce(leader_member.is_leader, false) = true
              and coalesce(leader_member.is_active, true) = true
              and scoped_member.user_id in (
                target_created_by,
                target_responsible_user_id
              )
          )
        )
      )
    );
$$;


ALTER FUNCTION private.can_view_property_record(target_organization_id uuid, target_created_by uuid, target_responsible_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION can_view_property_record(target_organization_id uuid, target_created_by uuid, target_responsible_user_id uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.can_view_property_record(target_organization_id uuid, target_created_by uuid, target_responsible_user_id uuid) IS 'RLS helper for property_view own/team scope and property_manage organization-wide scope.';


--
-- Name: can_view_real_estate_record(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_view_real_estate_record(target_organization_id uuid, target_property_id uuid, target_property_key_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    target_organization_id is not null
    and (select auth.uid()) is not null
    and exists (
      select 1
      from public.properties as property
      where property.organization_id = target_organization_id
        and (
          property.id = target_property_id
          or exists (
            select 1
            from public.property_keys as property_key
            where property_key.id = target_property_key_id
              and property_key.organization_id = target_organization_id
              and property_key.property_id = property.id
          )
        )
        and private.can_view_property_record(
          property.organization_id,
          property.created_by,
          property.responsible_user_id
        )
    );
$$;


ALTER FUNCTION private.can_view_real_estate_record(target_organization_id uuid, target_property_id uuid, target_property_key_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION can_view_real_estate_record(target_organization_id uuid, target_property_id uuid, target_property_key_id uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.can_view_real_estate_record(target_organization_id uuid, target_property_id uuid, target_property_key_id uuid) IS 'Delegates normalized property rows to the canonical own/team/all visibility contract.';


--
-- Name: can_view_whatsapp_conversation(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.can_view_whatsapp_conversation(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select exists (
    select 1
    from public.whatsapp_conversations as conversation
    join public.whatsapp_sessions as session
      on session.id = conversation.session_id
     and session.organization_id = conversation.organization_id
    join public.leads as lead
      on lead.id = conversation.lead_id
     and lead.organization_id = conversation.organization_id
    where conversation.id = p_conversation_id
      and conversation.deleted_at is null
      and coalesce(session.is_active, true) = true
      and coalesce(session.status, '') <> 'deleted'
      and session.provider = 'evolution_go'
      and (select auth.uid()) is not null
      and private.can_access_lead(
        lead.organization_id,
        lead.assigned_user_id
      )
  );
$$;


ALTER FUNCTION private.can_view_whatsapp_conversation(p_conversation_id uuid) OWNER TO postgres;

--
-- Name: cancel_billing_payment_receipt_delivery(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cancel_billing_payment_receipt_delivery(p_notification_id uuid, p_payment_status text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment_status text := upper(btrim(coalesce(p_payment_status, 'UNKNOWN')));
begin
  if private.billing_payment_checkout_is_paid(v_payment_status) then
    return false;
  end if;

  update public.notifications notification
  set metadata = coalesce(notification.metadata, '{}'::jsonb) || jsonb_build_object(
    'receipt_delivery_cancelled_at', now(),
    'receipt_delivery_cancel_reason', lower(v_payment_status),
    'dispatch', coalesce(notification.metadata -> 'dispatch', '{}'::jsonb) || jsonb_build_object(
      'whatsapp', coalesce(notification.metadata -> 'dispatch' -> 'whatsapp', '{}'::jsonb) || jsonb_build_object(
        'required', lower(coalesce(
          notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status', ''
        )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
        'status', case
          when lower(coalesce(
            notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status', ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
            'permanent_failed'
          ) then lower(notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status')
          else 'skipped'
        end,
        'error', case
          when lower(coalesce(
            notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status', ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
            'permanent_failed'
          )
            then notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'error'
          else 'payment_not_confirmed:' || lower(v_payment_status)
        end,
        'updated_at', now()
      ),
      'email', coalesce(notification.metadata -> 'dispatch' -> 'email', '{}'::jsonb) || jsonb_build_object(
        'required', lower(coalesce(
          notification.metadata -> 'dispatch' -> 'email' ->> 'status', ''
        )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
        'status', case
          when lower(coalesce(
            notification.metadata -> 'dispatch' -> 'email' ->> 'status', ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
            'permanent_failed'
          ) then lower(notification.metadata -> 'dispatch' -> 'email' ->> 'status')
          else 'skipped'
        end,
        'error', case
          when lower(coalesce(
            notification.metadata -> 'dispatch' -> 'email' ->> 'status', ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
            'permanent_failed'
          )
            then notification.metadata -> 'dispatch' -> 'email' ->> 'error'
          else 'payment_not_confirmed:' || lower(v_payment_status)
        end,
        'updated_at', now()
      )
    ),
    'whatsapp_dispatch_required', lower(coalesce(
      notification.metadata -> 'whatsapp_dispatch' ->> 'status',
      notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
      ''
    )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
    'whatsapp_dispatch', coalesce(notification.metadata -> 'whatsapp_dispatch', '{}'::jsonb) || jsonb_build_object(
      'required', lower(coalesce(
        notification.metadata -> 'whatsapp_dispatch' ->> 'status',
        notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
        ''
      )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
      'status', case
        when lower(coalesce(
          notification.metadata -> 'whatsapp_dispatch' ->> 'status',
          notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
          ''
        )) in (
          'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
          'permanent_failed'
        ) then lower(coalesce(
          notification.metadata -> 'whatsapp_dispatch' ->> 'status',
          notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status'
        ))
        else 'skipped'
      end,
      'error', case
        when lower(coalesce(
          notification.metadata -> 'whatsapp_dispatch' ->> 'status',
          notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
          ''
        )) in (
          'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
          'permanent_failed'
        ) then coalesce(
          notification.metadata -> 'whatsapp_dispatch' ->> 'error',
          notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'error'
        )
        else 'payment_not_confirmed:' || lower(v_payment_status)
      end,
      'updated_at', now()
    )
  )
  where notification.id = p_notification_id
    and notification.metadata ->> 'event_key' = 'billing_payment_receipt';

  return found;
end;
$$;


ALTER FUNCTION private.cancel_billing_payment_receipt_delivery(p_notification_id uuid, p_payment_status text) OWNER TO postgres;

--
-- Name: cancel_lead_automation_executions(uuid, uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cancel_lead_automation_executions(p_organization_id uuid, p_lead_id uuid, p_reason text, p_conversation_id uuid DEFAULT NULL::uuid) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cancelled_ids uuid[] := array[]::uuid[];
begin
  with cancelled as (
    update public.automation_executions e
    set status = 'cancelled',
        cancellation_requested_at = now(),
        completed_at = now(),
        error_message = left(coalesce(nullif(p_reason, ''), 'automation_handoff'), 4000),
        next_execution_at = null,
        locked_at = null,
        locked_by = null,
        updated_at = now()
    where e.organization_id = p_organization_id
      and e.lead_id = p_lead_id
      and e.status in ('queued', 'running', 'waiting')
      and (
        p_conversation_id is null
        or e.conversation_id is null
        or e.conversation_id = p_conversation_id
      )
    returning e.id
  ), closed_steps as (
    update public.automation_execution_steps s
    set status = 'cancelled',
        completed_at = now(),
        error_message = left(coalesce(nullif(p_reason, ''), 'automation_handoff'), 4000)
    where s.organization_id = p_organization_id
      and s.execution_id in (select id from cancelled)
      and s.status in ('running', 'waiting')
    returning s.id
  )
  select coalesce(array_agg(c.id), array[]::uuid[])
  into cancelled_ids
  from cancelled c;

  return cancelled_ids;
end;
$$;


ALTER FUNCTION private.cancel_lead_automation_executions(p_organization_id uuid, p_lead_id uuid, p_reason text, p_conversation_id uuid) OWNER TO postgres;

--
-- Name: canonical_jsonb_sha256(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.canonical_jsonb_sha256(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(private.canonical_jsonb_text(p_value), 'UTF8'),
      'sha256'
    ),
    'hex'
  )
$$;


ALTER FUNCTION private.canonical_jsonb_sha256(p_value jsonb) OWNER TO postgres;

--
-- Name: canonical_jsonb_text(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.canonical_jsonb_text(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
declare
  v_result text;
begin
  case pg_catalog.jsonb_typeof(p_value)
    when 'object' then
      select '{' || coalesce(
        pg_catalog.string_agg(
          pg_catalog.to_jsonb(member.key)::text
          || ':'
          || private.canonical_jsonb_text(member.value),
          ',' order by member.key
        ),
        ''
      ) || '}'
      into v_result
      from pg_catalog.jsonb_each(p_value) as member(key, value);
    when 'array' then
      select '[' || coalesce(
        pg_catalog.string_agg(
          private.canonical_jsonb_text(member.value),
          ',' order by member.ordinality
        ),
        ''
      ) || ']'
      into v_result
      from pg_catalog.jsonb_array_elements(p_value)
        with ordinality as member(value, ordinality);
    else
      v_result := p_value::text;
  end case;

  return v_result;
end;
$$;


ALTER FUNCTION private.canonical_jsonb_text(p_value jsonb) OWNER TO postgres;

--
-- Name: canonical_linked_property_status(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.canonical_linked_property_status(source_status text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select case lower(btrim(source_status))
    when 'ativo' then 'active'
    when 'available' then 'active'
    when 'disponivel' then 'active'
    when 'reservado' then 'reserved'
    when 'vendido' then 'sold'
    when 'alugado' then 'rented'
    when 'locado' then 'rented'
    when 'inativo' then 'inactive'
    when 'arquivado' then 'archived'
    when 'rascunho' then 'draft'
    else lower(btrim(source_status))
  end
$$;


ALTER FUNCTION private.canonical_linked_property_status(source_status text) OWNER TO postgres;

--
-- Name: canonical_property_deal_type(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.canonical_property_deal_type(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select case translate(
    lower(btrim(p_value)),
    'áàâãäéèêëíìîïóòôõöúùûüç',
    'aaaaaeeeeiiiiooooouuuuc'
  )
    when 'venda' then 'venda'
    when 'sale' then 'venda'
    when 'aluguel' then 'locacao'
    when 'locacao' then 'locacao'
    when 'locacao anual' then 'locacao'
    when 'rent' then 'locacao'
    when 'temporada' then 'temporada'
    when 'season' then 'temporada'
    when 'lancamento' then 'lancamento'
    when 'launch' then 'lancamento'
    when 'release' then 'lancamento'
    when 'venda e aluguel' then 'venda_locacao'
    when 'venda e locacao' then 'venda_locacao'
    when 'venda locacao' then 'venda_locacao'
    when 'venda/locacao' then 'venda_locacao'
    when 'venda/aluguel' then 'venda_locacao'
    when 'venda_locacao' then 'venda_locacao'
    else null
  end
$$;


ALTER FUNCTION private.canonical_property_deal_type(p_value text) OWNER TO postgres;

--
-- Name: capture_activity_attention_fact(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_activity_attention_fact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_type text := lower(btrim(coalesce(new.type, '')));
  normalized_task_type text := lower(btrim(coalesce(new.metadata->>'task_type', '')));
  automated boolean := private.attention_metadata_is_automated(new.metadata);
  outcome text := lower(btrim(coalesce(new.metadata->>'outcome', '')));
  qualifies_outreach boolean;
  qualifies_inactivity boolean;
  effective boolean;
  action_channel text;
begin
  qualifies_outreach := not automated and (
    normalized_type in ('call', 'email', 'email_sent', 'message', 'whatsapp')
    or (
      normalized_type = 'task_completed'
      and normalized_task_type in ('call', 'message', 'email')
    )
  );
  qualifies_inactivity := not automated and normalized_type in (
    'call',
    'email',
    'email_sent',
    'message',
    'whatsapp',
    'task_completed',
    'feedback',
    'feedback_added',
    'note'
  );
  effective := outcome in (
    'efetivo',
    'contato efetivo',
    'connected',
    'answered',
    'atendeu',
    'respondeu',
    'replied',
    'scheduled'
  );
  action_channel := coalesce(
    nullif(new.metadata->>'channel', ''),
    case
      when normalized_type like 'email%' then 'email'
      when normalized_type = 'call' then 'phone'
      when normalized_type in ('message', 'whatsapp') then normalized_type
      when normalized_type = 'task_completed' and normalized_task_type = 'call' then 'phone'
      when normalized_type = 'task_completed' then nullif(normalized_task_type, '')
      else null
    end
  );

  perform private.record_lead_action_fact(
    new.organization_id,
    new.lead_id,
    new.user_id,
    normalized_type,
    action_channel,
    new.created_at,
    automated,
    false,
    qualifies_outreach,
    qualifies_inactivity,
    effective,
    'activity',
    new.id::text,
    new.metadata || jsonb_build_object('content', new.content)
  );
  return null;
end;
$$;


ALTER FUNCTION private.capture_activity_attention_fact() OWNER TO postgres;

--
-- Name: capture_automation_human_outbound_handoff(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_automation_human_outbound_handoff() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cancelled_ids uuid[];
  target_user_id uuid;
  target_lead_name text;
begin
  if coalesce(new.from_me, false) = false
     or new.direction <> 'outbound'
     or new.lead_id is null
     or coalesce(new.metadata->>'origin', '') = 'automation' then
    return new;
  end if;

  cancelled_ids := private.cancel_lead_automation_executions(
    new.organization_id,
    new.lead_id,
    'automation_handoff_human_outbound',
    null
  );

  if cardinality(cancelled_ids) > 0 then
    select l.assigned_user_id, l.name
    into target_user_id, target_lead_name
    from public.leads l
    where l.organization_id = new.organization_id and l.id = new.lead_id;

    perform private.notify_automation_attention(
      new.organization_id,
      new.lead_id,
      coalesce(target_user_id, new.sender_user_id),
      'Automacao interrompida pelo atendimento humano',
      coalesce(nullif(target_lead_name, ''), 'Lead') || ' agora esta em atendimento manual.',
      'automation_human_outbound',
      'automation_human_outbound:' || new.id::text || ':' || coalesce(target_user_id, new.sender_user_id)::text,
      jsonb_build_object(
        'message_id', new.id,
        'conversation_id', new.conversation_id,
        'execution_ids', to_jsonb(cancelled_ids)
      )
    );

    insert into public.lead_timeline_events (
      organization_id, lead_id, event_type, title, description,
      user_id, actor_user_id, metadata, event_at
    ) values (
      new.organization_id, new.lead_id,
      'automation_human_outbound',
      'Automacao interrompida por mensagem humana',
      left(coalesce(new.content, '[midia]'), 500),
      coalesce(new.sender_user_id, target_user_id),
      coalesce(new.sender_user_id, target_user_id),
      jsonb_build_object(
        'message_id', new.id,
        'conversation_id', new.conversation_id,
        'execution_ids', to_jsonb(cancelled_ids)
      ),
      coalesce(new.sent_at, new.created_at, now())
    );
  end if;

  return new;
exception when others then
  raise warning 'automation human outbound handoff failed: %', sqlerrm;
  return new;
end;
$$;


ALTER FUNCTION private.capture_automation_human_outbound_handoff() OWNER TO postgres;

--
-- Name: capture_automation_inbound_message_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_automation_inbound_message_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_binding public.whatsapp_conversation_lead_bindings%rowtype;
begin
  if coalesce(new.from_me, false) is distinct from false
     or new.direction is distinct from 'inbound'
     or new.lead_id is null
     or coalesce(new.metadata->>'whatsapp_event_binding_is_current', 'false') <> 'true'
     or private.is_terminal_whatsapp_lead_resolution_quarantine(
       new.metadata,
       new.from_me,
       new.provider_message_id,
       new.message_id
     ) then
    return new;
  end if;

  select conversation.*
  into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = new.conversation_id
  for share;

  if not found
     or v_conversation.organization_id is distinct from new.organization_id
     or v_conversation.session_id is distinct from new.session_id
     or v_conversation.lead_id is distinct from new.lead_id then
    return new;
  end if;

  select binding.*
  into v_binding
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.organization_id = new.organization_id
    and binding.conversation_id = new.conversation_id
    and binding.active_to is null
  for share;

  if not found
     or v_binding.session_id is distinct from v_conversation.session_id
     or v_binding.lead_id is distinct from v_conversation.lead_id
     or v_binding.lead_id is distinct from new.lead_id then
    return new;
  end if;

  perform private.enqueue_automation_event(
    new.organization_id, 'message_received', 'whatsapp_message', new.id,
    new.lead_id, new.conversation_id,
    'message_received:' || new.id::text,
    pg_catalog.jsonb_build_object(
      'message_id', new.id,
      'lead_id', new.lead_id,
      'conversation_id', new.conversation_id,
      'session_id', new.session_id,
      'whatsapp_binding_id', v_binding.id,
      'message_type', coalesce(nullif(new.message_type, ''), 'text'),
      'content', new.content,
      'occurred_at', coalesce(new.received_at, new.created_at, now())
    )
  );

  return new;
exception when others then
  raise warning 'automation message event enqueue failed: %', sqlerrm;
  return new;
end;
$$;


ALTER FUNCTION private.capture_automation_inbound_message_event() OWNER TO postgres;

--
-- Name: capture_automation_lead_events(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_automation_lead_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  origin_execution_id uuid := private.safe_uuid(nullif(current_setting('vimob.automation_execution_id', true), ''));
  causal_depth integer := 0;
begin
  if origin_execution_id is not null then
    select least(coalesce((e.execution_data->>'causal_depth')::integer, 0) + 1, 100)
    into causal_depth
    from public.automation_executions e
    where e.id = origin_execution_id;
  end if;
  if tg_op = 'INSERT' then
    perform private.enqueue_automation_event(
      new.organization_id, 'lead_created', 'lead', new.id, new.id, null,
      'lead_created:' || new.id::text,
      jsonb_build_object(
        'lead_id', new.id,
        'source', new.source,
        'meta_form_id', new.meta_form_id,
        'assigned_user_id', new.assigned_user_id,
        'occurred_at', coalesce(new.created_at, now()),
        'origin_execution_id', origin_execution_id,
        'causal_depth', causal_depth
      )
    );
  elsif new.stage_id is distinct from old.stage_id then
    perform private.enqueue_automation_event(
      new.organization_id, 'lead_stage_changed', 'lead', new.id, new.id, null,
      'lead_stage_changed:' || new.id::text || ':' || txid_current()::text || ':' || coalesce(new.updated_at, now())::text,
      jsonb_build_object(
        'lead_id', new.id,
        'pipeline_id', new.pipeline_id,
        'from_stage_id', old.stage_id,
        'to_stage_id', new.stage_id,
        'assigned_user_id', new.assigned_user_id,
        'occurred_at', coalesce(new.updated_at, now()),
        'origin_execution_id', origin_execution_id,
        'causal_depth', causal_depth
      )
    );
  end if;
  return new;
exception when others then
  raise warning 'automation lead event enqueue failed: %', sqlerrm;
  return new;
end;
$$;


ALTER FUNCTION private.capture_automation_lead_events() OWNER TO postgres;

