--
-- Name: capture_lead_cycles(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_lead_cycles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  next_cycle integer;
  old_assignment_cycle_id uuid;
  old_stage_cycle_id uuid;
  reopened boolean := false;
  terminal_transition boolean := false;
  assignment_cycle_needed boolean;
  stage_cycle_needed boolean;
begin
  if tg_op = 'INSERT' then
    assignment_cycle_needed := true;
    stage_cycle_needed := true;
  else
    reopened := old.deal_status in ('won', 'lost')
      and new.deal_status = 'open';
    terminal_transition := new.deal_status in ('won', 'lost')
      and new.deal_status is distinct from old.deal_status;
    assignment_cycle_needed := reopened
      or new.assigned_user_id is distinct from old.assigned_user_id
      or (
        new.deal_status = 'open'
        and new.assigned_user_id is not null
        and (
          new.stage_id is distinct from old.stage_id
          or new.pipeline_id is distinct from old.pipeline_id
        )
        and not exists (
          select 1
          from public.lead_assignment_cycles current_assignment
          where current_assignment.organization_id = new.organization_id
            and current_assignment.lead_id = new.id
            and current_assignment.ended_at is null
        )
      );
    stage_cycle_needed := reopened
      or new.stage_id is distinct from old.stage_id
      or new.pipeline_id is distinct from old.pipeline_id;
  end if;

  if assignment_cycle_needed then
    if tg_op = 'UPDATE' then
      update public.lead_assignment_cycles
      set ended_at = now(),
          ended_reason = case
            when terminal_transition then new.deal_status
            when reopened then 'deal_reopened'
            when new.assigned_user_id is null then 'unassigned'
            else 'reassigned'
          end
      where lead_id = new.id
        and ended_at is null
      returning id into old_assignment_cycle_id;

      if old_assignment_cycle_id is not null then
        with redistributed as (
          update public.lead_attention_instances instance
          set status = 'redistributed',
              redistributed_at = now(),
              resolved_at = now(),
              resolved_reason = 'auto_redistributed',
              next_evaluation_at = now()
          where instance.assignment_cycle_id = old_assignment_cycle_id
            and instance.status not in ('resolved', 'redistributed', 'cancelled')
            and exists (
              select 1
              from public.lead_redistribution_jobs job
              where job.organization_id = new.organization_id
                and job.lead_id = new.id
                and job.status in ('pending', 'warning_sent')
                and job.metadata->>'attention_instance_id' = instance.id::text
            )
          returning instance.organization_id, instance.id, instance.lead_id
        )
        insert into public.lead_attention_events (
          organization_id,
          instance_id,
          lead_id,
          event_type,
          metadata
        )
        select
          organization_id,
          id,
          lead_id,
          'redistributed',
          jsonb_build_object('source', 'assignment_cycle_trigger')
        from redistributed;

        update public.lead_attention_instances
        set status = 'cancelled',
            resolved_at = now(),
            resolved_reason = case
              when terminal_transition then new.deal_status
              when reopened then 'deal_reopened'
              when new.assigned_user_id is null then 'unassigned'
              else 'reassigned'
            end,
            next_evaluation_at = now()
        where assignment_cycle_id = old_assignment_cycle_id
          and status not in ('resolved', 'redistributed', 'cancelled');
      end if;
    end if;

    if new.deal_status = 'open' and new.assigned_user_id is not null then
      select coalesce(max(cycle_number), 0) + 1
      into next_cycle
      from public.lead_assignment_cycles
      where lead_id = new.id;

      insert into public.lead_assignment_cycles (
        organization_id,
        lead_id,
        assigned_user_id,
        cycle_number,
        assigned_at,
        metadata
      ) values (
        new.organization_id,
        new.id,
        new.assigned_user_id,
        next_cycle,
        case
          when reopened then now()
          else coalesce(new.assigned_at, now())
        end,
        jsonb_build_object(
          'source',
          case when reopened then 'deal_reopened' else 'lead_change' end
        )
      );
    end if;

  end if;

  if stage_cycle_needed then
    if tg_op = 'UPDATE' then
      update public.lead_stage_cycles
      set exited_at = now(),
          exited_reason = case
            when terminal_transition then new.deal_status
            when reopened then 'deal_reopened'
            else 'stage_changed'
          end
      where lead_id = new.id
        and exited_at is null
      returning id into old_stage_cycle_id;

      if old_stage_cycle_id is not null then
        update public.lead_attention_instances
        set status = 'resolved',
            resolved_at = now(),
            resolved_reason = case
              when terminal_transition then new.deal_status
              when reopened then 'deal_reopened'
              else 'stage_changed'
            end,
            next_evaluation_at = now()
        where stage_cycle_id = old_stage_cycle_id
          and status not in ('resolved', 'redistributed', 'cancelled');
      end if;
    end if;

    if new.deal_status = 'open'
       and new.pipeline_id is not null
       and new.stage_id is not null then
      select coalesce(max(cycle_number), 0) + 1
      into next_cycle
      from public.lead_stage_cycles
      where lead_id = new.id;

      insert into public.lead_stage_cycles (
        organization_id,
        lead_id,
        pipeline_id,
        stage_id,
        cycle_number,
        entered_at,
        baseline_confidence,
        metadata
      ) values (
        new.organization_id,
        new.id,
        new.pipeline_id,
        new.stage_id,
        next_cycle,
        case
          when reopened then now()
          else coalesce(new.stage_entered_at, now())
        end,
        'observed',
        jsonb_build_object(
          'source',
          case when reopened then 'deal_reopened' else 'lead_change' end
        )
      );
    end if;
  end if;

  if new.deal_status in ('won', 'lost')
     and (tg_op = 'INSERT' or terminal_transition) then
    update public.lead_assignment_cycles
    set ended_at = coalesce(ended_at, now()),
        ended_reason = new.deal_status
    where lead_id = new.id
      and ended_at is null;

    update public.lead_stage_cycles
    set exited_at = coalesce(exited_at, now()),
        exited_reason = new.deal_status
    where lead_id = new.id
      and exited_at is null;

    update public.lead_attention_instances
    set status = 'resolved',
        resolved_at = now(),
        resolved_reason = new.deal_status,
        next_evaluation_at = now()
    where lead_id = new.id
      and status not in ('resolved', 'redistributed', 'cancelled');
  end if;

  return null;
end;
$$;


ALTER FUNCTION private.capture_lead_cycles() OWNER TO postgres;

--
-- Name: capture_lead_funnel_transition(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_lead_funnel_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  entry_id uuid;
  qualified_stage boolean := false;
  qualified_transition boolean := false;
  converted_transition boolean := false;
  transition_time timestamptz := clock_timestamp();
begin
  if new.stage_id is not null then
    select coalesce(stage.is_qualified, false)
    into qualified_stage
    from public.stages as stage
    where stage.id = new.stage_id
      and stage.pipeline_id = new.pipeline_id
      and stage.organization_id = new.organization_id;
  end if;

  if tg_op = 'INSERT' then
    qualified_transition := qualified_stage and new.deal_status = 'open';
    converted_transition := new.deal_status = 'won';
  else
    qualified_transition := qualified_stage
      and new.deal_status = 'open'
      and (
        new.stage_id is distinct from old.stage_id
        or new.pipeline_id is distinct from old.pipeline_id
      );
    converted_transition := new.deal_status = 'won'
      and new.deal_status is distinct from old.deal_status;
  end if;

  if not qualified_transition and not converted_transition then
    return new;
  end if;

  select entry.id
  into entry_id
  from public.lead_entry_events as entry
  where entry.organization_id = new.organization_id
    and entry.lead_id = new.id
    and coalesce(entry.is_countable, true) = true
    and entry.occurred_at <= transition_time
  order by
    case
      when lower(coalesce(entry.provider, '')) = 'meta'
        or lower(coalesce(entry.source, '')) in (
          'meta', 'meta_ads', 'facebook', 'instagram'
        ) then 0
      else 1
    end,
    entry.occurred_at desc,
    entry.created_at desc,
    entry.id desc
  limit 1;

  if entry_id is null then
    return new;
  end if;

  if qualified_transition or converted_transition then
    insert into public.lead_funnel_events (
      organization_id,
      lead_id,
      lead_entry_event_id,
      event_kind,
      pipeline_id,
      stage_id,
      occurred_at,
      metadata
    )
    values (
      new.organization_id,
      new.id,
      entry_id,
      'qualified',
      new.pipeline_id,
      case when qualified_stage then new.stage_id else null end,
      case
        when qualified_transition
          then coalesce(new.stage_entered_at, transition_time)
        else coalesce(new.won_at, transition_time)
      end,
      case
        when converted_transition and not qualified_transition
          then jsonb_build_object('implicit_from_conversion', true)
        else '{}'::jsonb
      end
    )
    on conflict (organization_id, lead_entry_event_id, event_kind)
      do nothing;
  end if;

  if converted_transition then
    insert into public.lead_funnel_events (
      organization_id,
      lead_id,
      lead_entry_event_id,
      event_kind,
      pipeline_id,
      stage_id,
      occurred_at,
      metadata
    )
    values (
      new.organization_id,
      new.id,
      entry_id,
      'converted',
      new.pipeline_id,
      new.stage_id,
      coalesce(new.won_at, transition_time),
      jsonb_build_object('value_snapshot', new.valor_interesse)
    )
    on conflict (organization_id, lead_entry_event_id, event_kind)
      do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.capture_lead_funnel_transition() OWNER TO postgres;

--
-- Name: capture_meta_entry_funnel(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_meta_entry_funnel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  funnel_id uuid;
  lead_snapshot record;
begin
  if new.provider <> 'meta'
     or coalesce(new.is_countable, true) = false
     or new.provider_event_id is null
     or new.provider_event_id !~ '^[0-9]{15,17}$' then
    return new;
  end if;

  insert into public.lead_funnel_events (
    organization_id,
    lead_id,
    lead_entry_event_id,
    event_kind,
    pipeline_id,
    stage_id,
    occurred_at,
    metadata
  )
  values (
    new.organization_id,
    new.lead_id,
    new.id,
    'initial',
    new.pipeline_id,
    new.stage_id,
    new.occurred_at,
    '{}'::jsonb
  )
  on conflict (organization_id, lead_entry_event_id, event_kind)
    do update set lead_entry_event_id = excluded.lead_entry_event_id
  returning id into funnel_id;

  perform private.enqueue_meta_crm_funnel_event(funnel_id);

  select
    lead.pipeline_id,
    lead.stage_id,
    lead.stage_entered_at,
    lead.deal_status,
    coalesce(stage.is_qualified, false) as is_qualified
  into lead_snapshot
  from public.leads as lead
  left join public.stages as stage
    on stage.id = lead.stage_id
   and stage.pipeline_id = lead.pipeline_id
   and stage.organization_id = lead.organization_id
  where lead.id = new.lead_id
    and lead.organization_id = new.organization_id;

  if lead_snapshot.deal_status = 'open'
     and lead_snapshot.is_qualified = true then
    insert into public.lead_funnel_events (
      organization_id,
      lead_id,
      lead_entry_event_id,
      event_kind,
      pipeline_id,
      stage_id,
      occurred_at,
      metadata
    )
    values (
      new.organization_id,
      new.lead_id,
      new.id,
      'qualified',
      lead_snapshot.pipeline_id,
      lead_snapshot.stage_id,
      greatest(
        new.occurred_at,
        coalesce(lead_snapshot.stage_entered_at, new.occurred_at)
      ),
      jsonb_build_object('qualified_at_meta_entry', true)
    )
    on conflict (organization_id, lead_entry_event_id, event_kind)
      do nothing;
  end if;

  -- Hydration may add the leadgen id after a qualification/converted fact was
  -- captured. Retry every fact for this exact entry; the outbox unique key is
  -- the idempotency guard.
  for funnel_id in
    select event.id
    from public.lead_funnel_events as event
    where event.organization_id = new.organization_id
      and event.lead_entry_event_id = new.id
    order by event.occurred_at, event.id
  loop
    perform private.enqueue_meta_crm_funnel_event(funnel_id);
  end loop;

  return new;
end;
$_$;


ALTER FUNCTION private.capture_meta_entry_funnel() OWNER TO postgres;

--
-- Name: capture_property_creation_receipt(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_property_creation_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare ledger jsonb := new.metadata -> '_creation_idempotency';
begin
  if not private.property_creation_ledger_is_valid(ledger) then
    raise exception using errcode = '23514', message = 'property creation ledger is invalid';
  end if;
  insert into public.property_creation_receipts
    (organization_id, actor_id, key_hash, request_hash, property_id, state, created_at)
  values (new.organization_id, (ledger ->> 'actor_id')::uuid,
    ledger ->> 'key_hash', ledger ->> 'request_hash', new.id, 'created', new.created_at);
  return new;
end;
$$;


ALTER FUNCTION private.capture_property_creation_receipt() OWNER TO postgres;

--
-- Name: capture_property_development_reservation_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_property_development_reservation_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_name text;
  event_metadata jsonb;
  event_reason text;
begin
  if tg_op = 'INSERT' then
    event_name := 'reservation_created';
  elsif new.status is not distinct from old.status then
	if new.status = 'active'
	   and new.expires_at is distinct from old.expires_at
	   and new.expires_at > old.expires_at then
	  event_name := 'reservation_extended';
	else
	  return new;
	end if;
  elsif old.status = 'active' and new.status = 'cancelled' then
    event_name := 'reservation_cancelled';
  elsif old.status = 'active' and new.status = 'converted' then
    event_name := 'reservation_converted';
  elsif old.status = 'active' and new.status = 'expired' then
    event_name := 'reservation_expired';
  else
    return new;
  end if;

  if new.status = 'expired' then
    event_reason := nullif(btrim(new.cancellation_reason), '');
  end if;

  event_metadata := jsonb_build_object(
    'reservation_id', new.id,
    'old_status', case when tg_op = 'INSERT' then null else old.status end,
    'new_status', new.status,
    'expires_at', new.expires_at
  );

  if event_name = 'reservation_extended' then
	event_metadata := event_metadata || jsonb_build_object(
	  'previous_expires_at', old.expires_at
	);
  end if;

  if event_reason is not null then
    event_metadata := event_metadata || jsonb_build_object('reason', event_reason);
  end if;

  insert into public.property_development_unit_events (
    organization_id,
    development_id,
    unit_id,
    event_type,
    before_data,
    after_data,
    metadata,
    created_by
  ) values (
    new.organization_id,
    new.development_id,
    new.unit_id,
    event_name,
    null,
    null,
    event_metadata,
    case
      -- Expiration cannot be performed early, so this lifecycle event is
      -- always system-authored. NULL is the explicit system actor and remains
      -- valid even after the reserving user is deactivated.
      when event_name = 'reservation_expired' then null
      else coalesce(new.updated_by, new.reserved_by)
    end
  )
  on conflict (
    organization_id,
    (metadata ->> 'reservation_id'),
    event_type
  ) where event_type in (
    'reservation_created',
    'reservation_cancelled',
    'reservation_converted',
    'reservation_expired'
  ) and metadata ? 'reservation_id'
  do nothing;

  return new;
end;
$$;


ALTER FUNCTION private.capture_property_development_reservation_event() OWNER TO postgres;

--
-- Name: capture_property_development_unit_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_property_development_unit_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_name text;
  reservation_unit_id text;
begin
  reservation_unit_id := nullif(
    current_setting('vimob.property_development_reservation_unit_id', true),
    ''
  );

  -- The reservation lifecycle emits its own, safer event. Suppress only the
  -- nested status update made by the private reservation state trigger; direct
  -- unit updates continue to produce the normal status_changed audit entry.
  if tg_op = 'UPDATE'
     and new.status is distinct from old.status
     and pg_trigger_depth() > 1
     and reservation_unit_id = new.id::text then
    return new;
  end if;

  if tg_op = 'INSERT' then
    event_name := 'created';
  elsif new.status is distinct from old.status then
    event_name := 'status_changed';
  elsif new.property_id is distinct from old.property_id then
    event_name := 'property_linked';
  else
    event_name := 'updated';
  end if;

  insert into public.property_development_unit_events (
    organization_id,
    development_id,
    unit_id,
    event_type,
    before_data,
    after_data,
    created_by
  ) values (
    new.organization_id,
    new.development_id,
    new.id,
    event_name,
    case when tg_op = 'INSERT' then null else to_jsonb(old) end,
    to_jsonb(new),
    coalesce(new.updated_by, new.created_by)
  );

  return new;
end;
$$;


ALTER FUNCTION private.capture_property_development_unit_event() OWNER TO postgres;

--
-- Name: capture_property_development_unit_price_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_property_development_unit_price_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  source_row public.property_development_unit_prices%rowtype;
  cloning_active_price boolean;
begin
  cloning_active_price := coalesce(
    current_setting('vimob.property_development_price_clone', true),
    ''
  ) = 'true';

  -- Creating a draft version copies every active price as implementation
  -- detail. Those unchanged copies are not human price changes and would bury
  -- the one unit actually edited in the bounded event feed.
  if tg_op = 'INSERT'
     and cloning_active_price
     and new.metadata ? 'cloned_from_price_table_id' then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.id is not distinct from old.id
       and new.organization_id is not distinct from old.organization_id
       and new.development_id is not distinct from old.development_id
       and new.price_table_id is not distinct from old.price_table_id
       and new.unit_id is not distinct from old.unit_id
       and new.list_price is not distinct from old.list_price
       and new.minimum_price is not distinct from old.minimum_price
       and new.price_per_sqm is not distinct from old.price_per_sqm
       and new.payment_terms is not distinct from old.payment_terms
       and new.metadata is not distinct from old.metadata then
      return new;
    end if;
  end if;

  source_row := new;

  insert into public.property_development_unit_events (
    organization_id,
    development_id,
    unit_id,
    event_type,
    before_data,
    after_data,
    created_by,
    metadata
  ) values (
    source_row.organization_id,
    source_row.development_id,
    source_row.unit_id,
    'price_changed',
    case when tg_op = 'INSERT' then null else to_jsonb(old) end,
    to_jsonb(new),
    coalesce(source_row.updated_by, source_row.created_by),
    jsonb_build_object('price_table_id', source_row.price_table_id)
  );

  return new;
end;
$$;


ALTER FUNCTION private.capture_property_development_unit_price_event() OWNER TO postgres;

--
-- Name: capture_round_robin_rotation_assignment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_round_robin_rotation_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.assigned_user_id is distinct from old.assigned_user_id then
    insert into private.round_robin_rotation_assignment_context
      (organization_id,lead_id,assignment_xid,previous_user_id,previous_team_id,assigned_user_id)
    values (old.organization_id,old.id,pg_current_xact_id(),old.assigned_user_id,old.team_id,new.assigned_user_id)
    on conflict (organization_id,lead_id) do update set
      assignment_xid=excluded.assignment_xid,previous_user_id=excluded.previous_user_id,
      previous_team_id=excluded.previous_team_id,assigned_user_id=excluded.assigned_user_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.capture_round_robin_rotation_assignment() OWNER TO postgres;

--
-- Name: capture_simple_stage_inactivity_scope(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_simple_stage_inactivity_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if private.historical_import_effects_suppressed()
     or coalesce(new.operational_effects_suppressed, false) then
    return null;
  end if;
  if tg_op = 'UPDATE'
     and new.stage_id is not distinct from old.stage_id
     and new.pipeline_id is not distinct from old.pipeline_id
     and new.stage_entered_at is not distinct from old.stage_entered_at
     and new.deal_status is not distinct from old.deal_status then
    return null;
  end if;

  if new.stage_id is null or new.deal_status is distinct from 'open' then
    update private.stage_inactivity_lead_scopes
    set is_open = false
    where organization_id = new.organization_id and lead_id = new.id;
    return null;
  end if;

  if not exists (
    select 1 from private.stage_inactivity_policies policy
    join public.stage_automations automation
      on automation.id = policy.automation_id
     and automation.organization_id = policy.organization_id
     and automation.stage_id = policy.stage_id
     and automation.updated_at = policy.automation_updated_at
     and automation.trigger_type = 'inactivity'
     and automation.is_active = true
    where policy.organization_id = new.organization_id
      and policy.stage_id = new.stage_id and policy.is_enabled = true
  ) and not exists (
    select 1 from private.stage_inactivity_lead_scopes existing_scope
    where existing_scope.organization_id = new.organization_id
      and existing_scope.lead_id = new.id
  ) then
    return null;
  end if;

  insert into private.stage_inactivity_lead_scopes (
    organization_id, lead_id, stage_id, stage_entered_at, cycle_id, started_at, is_open
  ) values (
    new.organization_id, new.id, new.stage_id,
    coalesce(new.stage_entered_at, new.created_at, now()), gen_random_uuid(),
    case when tg_op = 'UPDATE' and old.deal_status is distinct from 'open' then now()
         else coalesce(new.stage_entered_at, new.created_at, now()) end,
    true
  ) on conflict (organization_id, lead_id) do update set
    stage_id = excluded.stage_id, stage_entered_at = excluded.stage_entered_at,
    cycle_id = excluded.cycle_id, started_at = excluded.started_at, is_open = true;
  return null;
end;
$$;


ALTER FUNCTION private.capture_simple_stage_inactivity_scope() OWNER TO postgres;

--
-- Name: capture_team_distribution_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_team_distribution_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_metadata_member_id uuid;
  v_metadata_team_id uuid;
  v_member_team_id uuid;
  v_lead_team_id uuid;
  v_team_id uuid;
  v_event_kind text;
begin
  -- Success is established from relational state at insertion time, never
  -- from reason strings. Failure/diagnostic logs have no assigned recipient.
  if new.organization_id is null
     or new.round_robin_id is null
     or new.lead_id is null
     or new.assigned_user_id is null then
    return new;
  end if;

  perform 1
    from public.round_robins as queue
   where queue.id = new.round_robin_id
     and queue.organization_id = new.organization_id;
  if not found then
    return new;
  end if;

  select lead.team_id
    into v_lead_team_id
    from public.leads as lead
   where lead.id = new.lead_id
     and lead.organization_id = new.organization_id
     and lead.assigned_user_id = new.assigned_user_id;
  if not found then
    return new;
  end if;

  perform 1
    from public.organization_members as assigned_membership
    join public.users as assigned_user
      on assigned_user.id = assigned_membership.user_id
     and assigned_user.is_active = true
   where assigned_membership.organization_id = new.organization_id
     and assigned_membership.user_id = new.assigned_user_id
     and assigned_membership.is_active = true
     and assigned_membership.deleted_at is null;
  if not found then
    return new;
  end if;

  v_metadata_member_id := private.try_team_distribution_uuid(
    nullif(new.metadata->>'member_id', '')
  );
  v_metadata_team_id := private.try_team_distribution_uuid(
    nullif(new.metadata->>'team_id', '')
  );

  select member.team_id
    into v_member_team_id
    from public.round_robin_members as member
   where member.id = coalesce(new.member_id, v_metadata_member_id)
     and member.organization_id = new.organization_id
     and member.round_robin_id = new.round_robin_id
     and (member.user_id is null or member.user_id = new.assigned_user_id)
   limit 1;

  if v_metadata_team_id is not null then
    perform 1
      from public.teams as metadata_team
     where metadata_team.id = v_metadata_team_id
       and metadata_team.organization_id = new.organization_id;
    if not found then
      v_metadata_team_id := null;
    end if;
  end if;

  if v_member_team_id is not null and v_metadata_team_id is not null
     and v_member_team_id <> v_metadata_team_id then
    return new;
  end if;
  if v_lead_team_id is not null and v_metadata_team_id is not null
     and v_lead_team_id <> v_metadata_team_id then
    return new;
  end if;
  if v_lead_team_id is not null and v_member_team_id is not null
     and v_lead_team_id <> v_member_team_id then
    return new;
  end if;

  v_team_id := coalesce(v_metadata_team_id, v_member_team_id, v_lead_team_id);
  if v_team_id is null then
    return new;
  end if;

  perform 1
    from public.teams as resolved_team
   where resolved_team.id = v_team_id
     and resolved_team.organization_id = new.organization_id;
  if not found then
    return new;
  end if;

  -- Reason classifies an already-proven success; it never establishes one.
  v_event_kind := case
    when lower(btrim(coalesce(new.reason, ''))) in (
      'auto_redistribution',
      'round_robin'
    ) or nullif(btrim(new.metadata->>'previous_user_id'), '') is not null
      then 'redistribution'
    else 'distribution'
  end;

  insert into private.team_distribution_events (
    round_robin_log_id,
    organization_id,
    team_id,
    round_robin_id,
    lead_id,
    assigned_user_id,
    event_kind,
    reason,
    occurred_at
  )
  values (
    new.id,
    new.organization_id,
    v_team_id,
    new.round_robin_id,
    new.lead_id,
    new.assigned_user_id,
    v_event_kind,
    new.reason,
    coalesce(new.created_at, clock_timestamp())
  )
  on conflict (round_robin_log_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION private.capture_team_distribution_event() OWNER TO postgres;

--
-- Name: capture_whatsapp_attention_fact(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_whatsapp_attention_fact() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  outgoing boolean := coalesce(new.from_me, lower(coalesce(new.direction, '')) = 'outgoing');
  automated boolean;
  happened_at timestamptz;
begin
  if new.lead_id is null then
    return null;
  end if;

  automated := private.attention_metadata_is_automated(new.metadata)
    or lower(coalesce(new.client_message_id, '')) like 'ai-%';
  happened_at := coalesce(new.sent_at, new.received_at, new.created_at, now());

  perform private.record_lead_action_fact(
    new.organization_id,
    new.lead_id,
    new.sender_user_id,
    case when outgoing then 'whatsapp_outbound' else 'whatsapp_inbound' end,
    'whatsapp',
    happened_at,
    case when outgoing then automated else false end,
    not outgoing,
    outgoing and not automated,
    (not outgoing) or (outgoing and not automated),
    not outgoing,
    'whatsapp_message',
    new.id::text,
    coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(
      'message_id', coalesce(new.message_id, new.client_message_id),
      'message_type', new.message_type,
      'direction', case when outgoing then 'outgoing' else 'incoming' end
    )
  );
  return null;
end;
$$;


ALTER FUNCTION private.capture_whatsapp_attention_fact() OWNER TO postgres;

--
-- Name: capture_whatsapp_webhook_routing_snapshot(uuid, uuid, text, text, text, text, boolean, text[], text, text, text, boolean, boolean, boolean, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_whatsapp_webhook_routing_snapshot(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_inbox_event_key text, p_processing_lane text, p_routing_key text, p_binding_eligible boolean, p_identity_aliases text[], p_contact_phone text, p_context_kind text, p_context_proof text, p_managed_message_distribution boolean, p_managed_event_pending boolean, p_managed_event_handled boolean, p_rule_id uuid, p_origin_round_robin_id uuid, p_provider_event_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_message_id text := nullif(pg_catalog.btrim(p_provider_message_id), '');
  v_inbox_event_key text := nullif(pg_catalog.btrim(p_inbox_event_key), '');
  v_processing_lane text := lower(pg_catalog.btrim(coalesce(p_processing_lane, '')));
  v_routing_key text := nullif(pg_catalog.btrim(p_routing_key), '');
  v_aliases text[];
  v_primary_alias text := nullif(lower(pg_catalog.btrim(coalesce(p_identity_aliases[1], ''))), '');
  v_phone_key text := coalesce(public.normalize_phone(p_contact_phone), '');
  v_context_kind text := lower(pg_catalog.btrim(coalesce(p_context_kind, 'organic')));
  v_context_proof text := nullif(pg_catalog.btrim(p_context_proof), '');
  v_managed_message_distribution boolean := coalesce(p_managed_message_distribution, false);
  v_managed_event_pending boolean := coalesce(p_managed_event_pending, false);
  v_managed_event_handled boolean := coalesce(p_managed_event_handled, false);
  v_conversation public.whatsapp_conversations%rowtype;
  v_active public.whatsapp_conversation_lead_bindings%rowtype;
  v_event_binding public.whatsapp_conversation_lead_bindings%rowtype;
  v_message_conversation_id uuid;
  v_message_lead_id uuid;
  v_message_quarantine_reason text;
  v_target_lead_id uuid;
  v_candidate_conversation_ids uuid[] := '{}'::uuid[];
  v_candidate_lead_ids uuid[] := '{}'::uuid[];
  v_locked_alias_canonical_conversation_ids uuid[] := '{}'::uuid[];
  v_match_count integer := 0;
  v_state text := 'unlinked';
  v_quarantine_reason text;
  v_binding_eligible boolean := coalesce(p_binding_eligible, false);
  v_predecessor_provider_message_id text;
  v_predecessor public.whatsapp_webhook_routing_snapshots%rowtype;
  v_target_mode text := 'snapshot';
  v_ingress_sequence bigint;
  v_snapshot jsonb;
  v_existing_snapshot public.whatsapp_webhook_routing_snapshots%rowtype;
begin
  if p_organization_id is null or p_session_id is null then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_tenant_required';
  end if;
  if v_provider_message_id is null
     or pg_catalog.octet_length(v_provider_message_id) > 512 then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_provider_message_required';
  end if;
  if v_inbox_event_key is null or pg_catalog.octet_length(v_inbox_event_key) > 1024 then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_event_key_required';
  end if;
  if v_processing_lane not in ('live', 'backlog') then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_lane_invalid';
  end if;
  if v_routing_key is null or pg_catalog.octet_length(v_routing_key) > 256 then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_routing_key_required';
  end if;
  if v_context_kind not in ('organic', 'contextual_intake') then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_context_invalid';
  end if;
  if v_managed_message_distribution is distinct from coalesce(v_context_proof = 'managed_rule', false) then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_managed_context_invalid';
  end if;
  if v_managed_message_distribution
     and (v_context_kind <> 'contextual_intake'
       or p_rule_id is null
       or p_origin_round_robin_id is null) then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_managed_rule_invalid';
  end if;
  if v_managed_event_pending and v_managed_event_handled then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_managed_state_invalid';
  end if;
  if not exists (
    select 1
    from public.whatsapp_sessions as session
    where session.id = p_session_id
      and session.organization_id = p_organization_id
      and session.provider = 'evolution_go'
      and coalesce(session.is_active, true) = true
      and lower(pg_catalog.btrim(coalesce(session.status, ''))) not in ('deleted', 'disabled')
  ) then
    raise exception using errcode = '23503', message = 'whatsapp_ingress_snapshot_session_mismatch';
  end if;

  -- The route lock precedes even the replay lookup. Besides serializing two
  -- callbacks for the same provider id, this is the barrier used by the
  -- conservative provenance cleanup: a replay can never observe a row that is
  -- concurrently being retired and then persist an inbox without its ledger.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_organization_id::text || ':' || p_session_id::text || ':' || v_routing_key,
      0
    )
  );

  -- Lookup after the route lock is authoritative. Two concurrent callbacks
  -- cannot select each other as predecessors, and exact provider replay always
  -- returns the original immutable snapshot (including its managed context).
  select routing_snapshot.*
  into v_existing_snapshot
  from public.whatsapp_webhook_routing_snapshots as routing_snapshot
  where routing_snapshot.organization_id = p_organization_id
    and routing_snapshot.session_id = p_session_id
    and routing_snapshot.provider_message_id = v_provider_message_id;

  if found then
    if v_existing_snapshot.routing_key is distinct from v_routing_key then
      raise exception using
        errcode = '23505',
        message = 'whatsapp_ingress_snapshot_provider_identity_conflict';
    end if;
    return v_existing_snapshot.snapshot;
  end if;

  select coalesce(pg_catalog.array_agg(distinct alias_value order by alias_value), '{}'::text[])
  into v_aliases
  from (
    select nullif(lower(pg_catalog.btrim(alias_value)), '') as alias_value
    from pg_catalog.unnest(coalesce(p_identity_aliases, '{}'::text[])) as supplied(alias_value)
  ) as normalized
  where alias_value is not null;

  select binding.*
  into v_event_binding
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.session_id = p_session_id
    and binding.provider_message_id = v_provider_message_id
  limit 1;

  if v_event_binding.id is not null then
    v_target_lead_id := v_event_binding.lead_id;
    v_candidate_conversation_ids := array[v_event_binding.conversation_id];
    v_state := 'provider_replay';
  else
    select
      message.conversation_id,
      message.lead_id,
      case
        when coalesce(message.metadata, '{}'::jsonb) @>
             '{"lead_resolution_quarantine":{"terminal":true,"retryable":false}}'::jsonb
          then coalesce(
            nullif(message.metadata #>> '{lead_resolution_quarantine,reason}', ''),
            'whatsapp_lead_resolution_ambiguous'
          )
        else null
      end
    into v_message_conversation_id, v_message_lead_id, v_message_quarantine_reason
    from public.whatsapp_messages as message
    where message.organization_id = p_organization_id
      and message.session_id = p_session_id
      and (
        message.provider_message_id = v_provider_message_id
        or (message.provider_message_id is null and message.message_id = v_provider_message_id)
      )
    order by message.id
    limit 1;

    select pg_catalog.count(*)::integer
    into v_match_count
    from (
      select message.id
      from public.whatsapp_messages as message
      where message.organization_id = p_organization_id
        and message.session_id = p_session_id
        and (
          message.provider_message_id = v_provider_message_id
          or (message.provider_message_id is null and message.message_id = v_provider_message_id)
        )
      limit 2
    ) as message_matches;
    if v_match_count > 1 then
      v_quarantine_reason := 'whatsapp_provider_message_identity_ambiguous';
    elsif v_message_conversation_id is not null then
      v_candidate_conversation_ids := array[v_message_conversation_id];
      v_target_lead_id := v_message_lead_id;
      v_state := 'provider_replay';
      v_quarantine_reason := v_message_quarantine_reason;
    end if;
  end if;

  if v_quarantine_reason is null
     and pg_catalog.cardinality(v_candidate_conversation_ids) = 0 then
    -- A known opaque provider alias routes to its active canonical conversation
    -- before an exact legacy LID row. Edge may leave that source row active,
    -- while native processing retires it; both paths must therefore resolve the
    -- same card without merging or moving the source history.
    if v_primary_alias like '%@lid' then
      select coalesce(pg_catalog.array_agg(candidate.id order by candidate.id), '{}'::uuid[])
      into v_candidate_conversation_ids
      from (
        select distinct conversation.id
        from public.whatsapp_contact_identity_aliases as identity_alias
        join public.whatsapp_conversations as conversation
          on conversation.organization_id = identity_alias.organization_id
         and conversation.session_id = identity_alias.session_id
         and lower(conversation.remote_jid) = lower(identity_alias.canonical_jid)
        where identity_alias.organization_id = p_organization_id
          and identity_alias.session_id = p_session_id
          and lower(identity_alias.alias_jid) = v_primary_alias
          and lower(identity_alias.canonical_jid) <> v_primary_alias
          and conversation.deleted_at is null
        limit 2
      ) as candidate;

      if pg_catalog.cardinality(v_candidate_conversation_ids) > 1 then
        v_quarantine_reason := 'whatsapp_conversation_identity_ambiguous_at_ingress';
        v_candidate_conversation_ids := '{}'::uuid[];
      end if;
    end if;

    -- Otherwise prefer the provider's primary exact JID. Retired rows are
    -- immutable history and never become a fresh event destination.
    if v_quarantine_reason is null
       and pg_catalog.cardinality(v_candidate_conversation_ids) = 0 then
    select coalesce(pg_catalog.array_agg(conversation.id order by conversation.id), '{}'::uuid[])
    into v_candidate_conversation_ids
    from public.whatsapp_conversations as conversation
    where conversation.organization_id = p_organization_id
      and conversation.session_id = p_session_id
      and conversation.deleted_at is null
      and v_primary_alias is not null
      and lower(conversation.remote_jid) = v_primary_alias;
    end if;

    if v_quarantine_reason is null
       and pg_catalog.cardinality(v_candidate_conversation_ids) = 0 then
      select coalesce(pg_catalog.array_agg(candidate.id order by candidate.id), '{}'::uuid[])
      into v_candidate_conversation_ids
      from (
        select distinct conversation.id
        from public.whatsapp_conversations as conversation
        where conversation.organization_id = p_organization_id
          and conversation.session_id = p_session_id
          and conversation.deleted_at is null
          and (
            lower(conversation.remote_jid) = any(v_aliases)
            or (
              v_phone_key <> ''
              and public.normalize_phone(conversation.contact_phone) = v_phone_key
            )
            or exists (
              select 1
              from public.whatsapp_contact_identity_aliases as identity_alias
              where identity_alias.organization_id = p_organization_id
                and identity_alias.session_id = p_session_id
                and lower(identity_alias.alias_jid) = any(v_aliases)
                and lower(identity_alias.canonical_jid) = lower(conversation.remote_jid)
            )
          )
        limit 2
      ) as candidate;
    end if;

    if pg_catalog.cardinality(v_candidate_conversation_ids) > 1 then
      v_quarantine_reason := 'whatsapp_conversation_identity_ambiguous_at_ingress';
      v_candidate_conversation_ids := '{}'::uuid[];
    end if;
  end if;

  if v_quarantine_reason is null
     and pg_catalog.cardinality(v_candidate_conversation_ids) = 1 then
    select conversation.*
    into v_conversation
    from public.whatsapp_conversations as conversation
    where conversation.id = v_candidate_conversation_ids[1]
      and conversation.organization_id = p_organization_id
      and conversation.session_id = p_session_id
      and (
        v_state = 'provider_replay'
        or conversation.deleted_at is null
      )
    for share;

    if not found then
      if v_state <> 'provider_replay' then
        -- Discovery is deliberately non-locking. If an identity reconciler
        -- retired the selected route while this statement waited for its
        -- conversation lock, retry from a fresh snapshot instead of freezing
        -- the now-deleted physical conversation into durable provenance.
        raise exception using
          errcode = '40001',
          message = 'whatsapp_conversation_identity_changed_at_ingress';
      end if;
      v_candidate_conversation_ids := '{}'::uuid[];
    else
      select binding.*
      into v_active
      from public.whatsapp_conversation_lead_bindings as binding
      where binding.organization_id = p_organization_id
        and binding.conversation_id = v_conversation.id
        and binding.active_to is null
      limit 1
      for share;

      -- Binding writers and native identity reconciliation both lock aliases
      -- only after their conversation/binding locks. Keep that global order and
      -- retain every matching alias row in deterministic UUID order until the
      -- immutable routing snapshot is inserted below.
      perform identity_alias.id
      from public.whatsapp_contact_identity_aliases as identity_alias
      where identity_alias.organization_id = p_organization_id
        and identity_alias.session_id = p_session_id
        and lower(identity_alias.alias_jid) = any(v_aliases)
      order by identity_alias.id
      for share of identity_alias;

      if v_state <> 'provider_replay' and v_primary_alias like '%@lid' then
        select coalesce(pg_catalog.array_agg(candidate.id order by candidate.id), '{}'::uuid[])
        into v_locked_alias_canonical_conversation_ids
        from (
          select distinct conversation.id
          from public.whatsapp_contact_identity_aliases as identity_alias
          join public.whatsapp_conversations as conversation
            on conversation.organization_id = identity_alias.organization_id
           and conversation.session_id = identity_alias.session_id
           and lower(conversation.remote_jid) = lower(identity_alias.canonical_jid)
          where identity_alias.organization_id = p_organization_id
            and identity_alias.session_id = p_session_id
            and lower(identity_alias.alias_jid) = v_primary_alias
            and lower(identity_alias.canonical_jid) <> v_primary_alias
            and conversation.deleted_at is null
          limit 2
        ) as candidate;

        if pg_catalog.cardinality(v_locked_alias_canonical_conversation_ids) > 1 then
          v_quarantine_reason := 'whatsapp_conversation_identity_ambiguous_at_ingress';
        elsif pg_catalog.cardinality(v_locked_alias_canonical_conversation_ids) = 1
              and v_locked_alias_canonical_conversation_ids[1] is distinct from v_conversation.id then
          -- The alias changed after discovery but before its row lock. Retrying
          -- is safe because no inbox/snapshot row from this transaction commits.
          raise exception using
            errcode = '40001',
            message = 'whatsapp_conversation_identity_changed_at_ingress';
        end if;
      end if;

      if (v_active.id is null and v_conversation.lead_id is not null)
         or (v_active.id is not null and v_active.lead_id is distinct from v_conversation.lead_id) then
        v_quarantine_reason := 'whatsapp_conversation_binding_inconsistent_at_ingress';
      elsif v_conversation.lead_id is not null and exists (
        select 1
        from public.whatsapp_contact_identity_aliases as identity_alias
        where identity_alias.organization_id = p_organization_id
          and identity_alias.session_id = p_session_id
          and lower(identity_alias.alias_jid) = any(v_aliases)
          and lower(identity_alias.canonical_jid) = lower(v_conversation.remote_jid)
          and identity_alias.lead_id is not null
          and identity_alias.lead_id is distinct from v_conversation.lead_id
      ) then
        v_quarantine_reason := 'whatsapp_identity_alias_lead_conflict_at_ingress';
      end if;
    end if;
  end if;

  if v_quarantine_reason is null and v_state <> 'provider_replay' then
    if v_context_kind = 'contextual_intake' then
      if v_context_proof is null then
        v_quarantine_reason := 'whatsapp_contextual_intake_proof_required';
      elsif p_origin_round_robin_id is not null and not exists (
        select 1
        from public.round_robins as queue
        where queue.id = p_origin_round_robin_id
          and queue.organization_id = p_organization_id
          and coalesce(queue.is_active, true) = true
      ) then
        v_quarantine_reason := 'whatsapp_contextual_intake_queue_invalid';
      elsif p_rule_id is not null and p_origin_round_robin_id is null then
        v_quarantine_reason := 'whatsapp_contextual_intake_queue_required';
      end if;

      if v_quarantine_reason is null and p_provider_event_lead_id is not null then
        if not exists (
          select 1 from public.leads as lead
          where lead.id = p_provider_event_lead_id
            and lead.organization_id = p_organization_id
        ) then
          v_quarantine_reason := 'whatsapp_contextual_intake_event_lead_invalid';
        else
          v_target_lead_id := p_provider_event_lead_id;
        end if;
      end if;

      if v_quarantine_reason is null
         and v_target_lead_id is null
         and v_phone_key <> '' then
        select coalesce(pg_catalog.array_agg(match.id order by match.id), '{}'::uuid[])
        into v_candidate_lead_ids
        from (
          select lead.id
          from public.leads as lead
          where lead.organization_id = p_organization_id
            and public.normalize_phone(lead.phone) = v_phone_key
            and (
              (
                p_origin_round_robin_id is not null
                and lead.intake_scope_key = 'queue:' || p_origin_round_robin_id::text
              )
              or (
                p_origin_round_robin_id is null
                and (
                  v_context_proof not like 'canonical_intake_v1:%'
                  or lead.intake_scope_key = 'unscoped'
                )
              )
            )
          limit 2
        ) as match;
        if pg_catalog.cardinality(v_candidate_lead_ids) > 1 then
          v_quarantine_reason := 'whatsapp_lead_phone_ambiguous_at_ingress';
        elsif pg_catalog.cardinality(v_candidate_lead_ids) = 1 then
          v_target_lead_id := v_candidate_lead_ids[1];
        end if;
      end if;
      v_state := 'contextual_intake';
    elsif v_conversation.id is not null and v_conversation.lead_id is not null then
      v_target_lead_id := v_conversation.lead_id;
      v_state := 'bound';
    else
      select coalesce(pg_catalog.array_agg(distinct identity_alias.lead_id order by identity_alias.lead_id), '{}'::uuid[])
      into v_candidate_lead_ids
      from public.whatsapp_contact_identity_aliases as identity_alias
      where identity_alias.organization_id = p_organization_id
        and identity_alias.session_id = p_session_id
        and lower(identity_alias.alias_jid) = any(v_aliases)
        and identity_alias.lead_id is not null;

      if pg_catalog.cardinality(v_candidate_lead_ids) > 1 then
        v_quarantine_reason := 'whatsapp_identity_alias_lead_ambiguous_at_ingress';
      elsif pg_catalog.cardinality(v_candidate_lead_ids) = 1 then
        v_target_lead_id := v_candidate_lead_ids[1];
        v_state := 'lead_match';
      elsif v_phone_key <> '' then
        select coalesce(pg_catalog.array_agg(match.id order by match.id), '{}'::uuid[])
        into v_candidate_lead_ids
        from (
          select lead.id
          from public.leads as lead
          where lead.organization_id = p_organization_id
            and public.normalize_phone(lead.phone) = v_phone_key
          limit 2
        ) as match;
        if pg_catalog.cardinality(v_candidate_lead_ids) > 1 then
          v_quarantine_reason := 'whatsapp_lead_phone_ambiguous_at_ingress';
        elsif pg_catalog.cardinality(v_candidate_lead_ids) = 1 then
          v_target_lead_id := v_candidate_lead_ids[1];
          v_state := 'lead_match';
        end if;
      end if;
    end if;
  end if;

  if v_quarantine_reason is not null then
    v_state := 'quarantine';
    v_target_lead_id := null;
  end if;

  v_binding_eligible := v_binding_eligible
    and v_routing_key <> '__session__'
    and v_state <> 'quarantine';
  if v_binding_eligible then
    select routing_snapshot.*
    into v_predecessor
    from public.whatsapp_webhook_routing_snapshots as routing_snapshot
    where routing_snapshot.organization_id = p_organization_id
      and routing_snapshot.session_id = p_session_id
      and routing_snapshot.routing_key = v_routing_key
      and routing_snapshot.binding_eligible = true
      and not exists (
        select 1
        from public.whatsapp_webhook_routing_outcomes as routing_outcome
        where routing_outcome.organization_id = routing_snapshot.organization_id
          and routing_outcome.session_id = routing_snapshot.session_id
          and routing_outcome.provider_message_id = routing_snapshot.provider_message_id
          and routing_outcome.ingress_sequence = routing_snapshot.ingress_sequence
      )
    order by routing_snapshot.ingress_sequence desc
    limit 1;
    v_predecessor_provider_message_id := v_predecessor.provider_message_id;
  end if;

  v_binding_eligible := v_binding_eligible and (
    v_context_kind = 'contextual_intake'
    or v_target_lead_id is not null
    or (
      v_context_kind = 'organic'
      and v_predecessor_provider_message_id is not null
    )
  );

  if v_binding_eligible
     and v_predecessor_provider_message_id is not null
     and v_context_kind = 'organic'
     and v_state <> 'provider_replay' then
    -- The predecessor may create or select a queue-scoped card that does not
    -- exist yet. Freeze the dependency, not the old lead visible before it ran.
    v_target_mode := 'inherit_predecessor';
    v_state := 'predecessor_inherit';
    v_target_lead_id := null;
  end if;
  v_ingress_sequence := nextval('public.whatsapp_webhook_routing_ingress_sequence');

  v_snapshot := pg_catalog.jsonb_build_object(
    'version', 1,
    'organization_id', p_organization_id,
    'session_id', p_session_id,
    'provider_message_id', v_provider_message_id,
    'inbox_event_key', v_inbox_event_key,
    'processing_lane', v_processing_lane,
    'state', v_state,
    'conversation_id', v_conversation.id,
    'event_lead_id', v_target_lead_id,
    'current_lead_id', v_conversation.lead_id,
    'active_binding_id', v_active.id,
    'quarantine_reason', v_quarantine_reason,
    'context_kind', v_context_kind,
    'context_proof', v_context_proof,
    'rule_id', p_rule_id,
    'origin_round_robin_id', p_origin_round_robin_id,
    'managed_message_distribution', v_managed_message_distribution,
    'managed_event_pending', v_managed_event_pending,
    'managed_event_handled', v_managed_event_handled,
    'routing_key', v_routing_key,
    'binding_eligible', v_binding_eligible,
    'target_mode', v_target_mode,
    'ingress_sequence', v_ingress_sequence,
    'predecessor_provider_message_id', v_predecessor_provider_message_id,
    'predecessor_inbox_event_key', v_predecessor.inbox_event_key,
    'predecessor_processing_lane', v_predecessor.processing_lane,
    'captured_at', clock_timestamp()
  );

  insert into public.whatsapp_webhook_routing_snapshots (
    organization_id,
    session_id,
    provider_message_id,
    inbox_event_key,
    processing_lane,
    routing_key,
    ingress_sequence,
    predecessor_provider_message_id,
    binding_eligible,
    target_mode,
    snapshot
  ) values (
    p_organization_id,
    p_session_id,
    v_provider_message_id,
    v_inbox_event_key,
    v_processing_lane,
    v_routing_key,
    v_ingress_sequence,
    v_predecessor_provider_message_id,
    v_binding_eligible,
    v_target_mode,
    v_snapshot
  )
  on conflict (organization_id, session_id, provider_message_id) do nothing;

  if not found then
    select routing_snapshot.*
    into v_existing_snapshot
    from public.whatsapp_webhook_routing_snapshots as routing_snapshot
    where routing_snapshot.organization_id = p_organization_id
      and routing_snapshot.session_id = p_session_id
      and routing_snapshot.provider_message_id = v_provider_message_id;
    if v_existing_snapshot.routing_key is distinct from v_routing_key then
      raise exception using
        errcode = '23505',
        message = 'whatsapp_ingress_snapshot_provider_identity_conflict';
    end if;
    return v_existing_snapshot.snapshot;
  end if;

  return v_snapshot;
end;
$$;


ALTER FUNCTION private.capture_whatsapp_webhook_routing_snapshot(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_inbox_event_key text, p_processing_lane text, p_routing_key text, p_binding_eligible boolean, p_identity_aliases text[], p_contact_phone text, p_context_kind text, p_context_proof text, p_managed_message_distribution boolean, p_managed_event_pending boolean, p_managed_event_handled boolean, p_rule_id uuid, p_origin_round_robin_id uuid, p_provider_event_lead_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION capture_whatsapp_webhook_routing_snapshot(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_inbox_event_key text, p_processing_lane text, p_routing_key text, p_binding_eligible boolean, p_identity_aliases text[], p_contact_phone text, p_context_kind text, p_context_proof text, p_managed_message_distribution boolean, p_managed_event_pending boolean, p_managed_event_handled boolean, p_rule_id uuid, p_origin_round_robin_id uuid, p_provider_event_lead_id uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.capture_whatsapp_webhook_routing_snapshot(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_inbox_event_key text, p_processing_lane text, p_routing_key text, p_binding_eligible boolean, p_identity_aliases text[], p_contact_phone text, p_context_kind text, p_context_proof text, p_managed_message_distribution boolean, p_managed_event_pending boolean, p_managed_event_handled boolean, p_rule_id uuid, p_origin_round_robin_id uuid, p_provider_event_lead_id uuid) IS 'Captures immutable tenant/session/provider routing provenance under conversation/binding locks before the durable webhook ACK.';


--
-- Name: capture_whatsapp_webhook_routing_snapshot_v2(uuid, uuid, text, text, text, text, boolean, text[], text, text, text, boolean, boolean, boolean, uuid, uuid, uuid, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.capture_whatsapp_webhook_routing_snapshot_v2(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_inbox_event_key text, p_processing_lane text, p_routing_key text, p_binding_eligible boolean, p_identity_aliases text[], p_contact_phone text, p_context_kind text, p_context_proof text, p_managed_message_distribution boolean, p_managed_event_pending boolean, p_managed_event_handled boolean, p_rule_id uuid, p_origin_round_robin_id uuid, p_provider_event_lead_id uuid, p_processing_epoch integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_message_id text := nullif(pg_catalog.btrim(p_provider_message_id), '');
  v_inbox_event_key text := nullif(pg_catalog.btrim(p_inbox_event_key), '');
  v_processing_lane text := lower(pg_catalog.btrim(coalesce(p_processing_lane, '')));
  v_routing_key text := nullif(pg_catalog.btrim(p_routing_key), '');
  v_aliases text[];
  v_primary_alias text := nullif(lower(pg_catalog.btrim(coalesce(p_identity_aliases[1], ''))), '');
  v_phone_key text := coalesce(private.whatsapp_contact_pn_reference(p_identity_aliases), public.normalize_phone(p_contact_phone), '');
  v_context_kind text := lower(pg_catalog.btrim(coalesce(p_context_kind, 'organic')));
  v_context_proof text := nullif(pg_catalog.btrim(p_context_proof), '');
  v_managed_message_distribution boolean := coalesce(p_managed_message_distribution, false);
  v_managed_event_pending boolean := coalesce(p_managed_event_pending, false);
  v_managed_event_handled boolean := coalesce(p_managed_event_handled, false);
  v_conversation public.whatsapp_conversations%rowtype;
  v_active public.whatsapp_conversation_lead_bindings%rowtype;
  v_event_binding public.whatsapp_conversation_lead_bindings%rowtype;
  v_message_conversation_id uuid;
  v_message_lead_id uuid;
  v_message_quarantine_reason text;
  v_target_lead_id uuid;
  v_candidate_conversation_ids uuid[] := '{}'::uuid[];
  v_candidate_lead_ids uuid[] := '{}'::uuid[];
  v_locked_alias_canonical_conversation_ids uuid[] := '{}'::uuid[];
  v_match_count integer := 0;
  v_state text := 'unlinked';
  v_quarantine_reason text;
  v_binding_eligible boolean := coalesce(p_binding_eligible, false);
  v_predecessor_provider_message_id text;
  v_predecessor public.whatsapp_webhook_routing_snapshots%rowtype;
  v_target_mode text := 'snapshot';
  v_ingress_sequence bigint;
  v_snapshot jsonb;
  v_existing_snapshot public.whatsapp_webhook_routing_snapshots%rowtype;
  v_active_epoch integer;
begin
  if p_processing_epoch not in (0, 1) or p_processing_epoch is null then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_epoch_invalid';
  end if;
  if p_organization_id is null or p_session_id is null then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_tenant_required';
  end if;
  if private.whatsapp_contact_pns_conflict(coalesce(p_identity_aliases, '{}'::text[]) ||
       array[case when nullif(p_contact_phone, '') is not null then '+' || p_contact_phone end]) then
    raise exception using errcode = '23514', message = 'whatsapp_contact_pn_conflict';
  end if;
  if v_provider_message_id is null
     or pg_catalog.octet_length(v_provider_message_id) > 512 then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_provider_message_required';
  end if;
  if v_inbox_event_key is null or pg_catalog.octet_length(v_inbox_event_key) > 1024 then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_event_key_required';
  end if;
  if v_processing_lane not in ('live', 'backlog') then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_lane_invalid';
  end if;
  if v_routing_key is null or pg_catalog.octet_length(v_routing_key) > 256 then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_routing_key_required';
  end if;
  if v_context_kind not in ('organic', 'contextual_intake') then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_context_invalid';
  end if;
  if v_managed_message_distribution is distinct from coalesce(v_context_proof = 'managed_rule', false) then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_managed_context_invalid';
  end if;
  if v_managed_message_distribution
     and (v_context_kind <> 'contextual_intake'
       or p_rule_id is null
       or p_origin_round_robin_id is null) then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_managed_rule_invalid';
  end if;
  if v_managed_event_pending and v_managed_event_handled then
    raise exception using errcode = '22023', message = 'whatsapp_ingress_snapshot_managed_state_invalid';
  end if;
  if not exists (
    select 1
    from public.whatsapp_sessions as session
    where session.id = p_session_id
      and session.organization_id = p_organization_id
      and session.provider = 'evolution_go'
      and coalesce(session.is_active, true) = true
      and lower(pg_catalog.btrim(coalesce(session.status, ''))) not in ('deleted', 'disabled')
  ) then
    raise exception using errcode = '23503', message = 'whatsapp_ingress_snapshot_session_mismatch';
  end if;

  -- Hold the session against activation until the immutable snapshot and
  -- its inbox row commit in the same ingress transaction.
  perform 1 from public.whatsapp_sessions as epoch_session
  where epoch_session.id = p_session_id
    and epoch_session.organization_id = p_organization_id
  for key share;
  if not found then
    raise exception using errcode = '23503', message = 'whatsapp_ingress_epoch_session_mismatch';
  end if;
  select coalesce((
    select cutover.active_epoch
    from private.whatsapp_webhook_session_cutovers as cutover
    where cutover.session_id = p_session_id
  ), 0) into v_active_epoch;
  if p_processing_epoch > v_active_epoch then
    raise exception using errcode = '23514', message = 'whatsapp_ingress_epoch_not_active';
  end if;

  -- The route lock precedes even the replay lookup. Besides serializing two
  -- callbacks for the same provider id, this is the barrier used by the
  -- conservative provenance cleanup: a replay can never observe a row that is
  -- concurrently being retired and then persist an inbox without its ledger.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_organization_id::text || ':' || p_session_id::text || ':' || v_routing_key,
      0
    )
  );

  -- Lookup after the route lock is authoritative. Two concurrent callbacks
  -- cannot select each other as predecessors, and exact provider replay always
  -- returns the original immutable snapshot (including its managed context).
  select routing_snapshot.*
  into v_existing_snapshot
  from public.whatsapp_webhook_routing_snapshots as routing_snapshot
  where routing_snapshot.organization_id = p_organization_id
    and routing_snapshot.session_id = p_session_id
    and routing_snapshot.provider_message_id = v_provider_message_id;

  if found then
    if v_existing_snapshot.routing_key is distinct from v_routing_key then
      raise exception using
        errcode = '23505',
        message = 'whatsapp_ingress_snapshot_provider_identity_conflict';
    end if;
    return v_existing_snapshot.snapshot;
  end if;

  select coalesce(pg_catalog.array_agg(distinct alias_value order by alias_value), '{}'::text[])
  into v_aliases
  from (
    select nullif(lower(pg_catalog.btrim(alias_value)), '') as alias_value
    from pg_catalog.unnest(coalesce(p_identity_aliases, '{}'::text[])) as supplied(alias_value)
  ) as normalized
  where alias_value is not null;

  select binding.*
  into v_event_binding
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.session_id = p_session_id
    and binding.provider_message_id = v_provider_message_id
  limit 1;

  if v_event_binding.id is not null then
    v_target_lead_id := v_event_binding.lead_id;
    v_candidate_conversation_ids := array[v_event_binding.conversation_id];
    v_state := 'provider_replay';
  else
    select
      message.conversation_id,
      message.lead_id,
      case
        when coalesce(message.metadata, '{}'::jsonb) @>
             '{"lead_resolution_quarantine":{"terminal":true,"retryable":false}}'::jsonb
          then coalesce(
            nullif(message.metadata #>> '{lead_resolution_quarantine,reason}', ''),
            'whatsapp_lead_resolution_ambiguous'
          )
        else null
      end
    into v_message_conversation_id, v_message_lead_id, v_message_quarantine_reason
    from public.whatsapp_messages as message
    where message.organization_id = p_organization_id
      and message.session_id = p_session_id
      and (
        message.provider_message_id = v_provider_message_id
        or (message.provider_message_id is null and message.message_id = v_provider_message_id)
      )
    order by message.id
    limit 1;

    select pg_catalog.count(*)::integer
    into v_match_count
    from (
      select message.id
      from public.whatsapp_messages as message
      where message.organization_id = p_organization_id
        and message.session_id = p_session_id
        and (
          message.provider_message_id = v_provider_message_id
          or (message.provider_message_id is null and message.message_id = v_provider_message_id)
        )
      limit 2
    ) as message_matches;
    if v_match_count > 1 then
      v_quarantine_reason := 'whatsapp_provider_message_identity_ambiguous';
    elsif v_message_conversation_id is not null then
      v_candidate_conversation_ids := array[v_message_conversation_id];
      v_target_lead_id := v_message_lead_id;
      v_state := 'provider_replay';
      v_quarantine_reason := v_message_quarantine_reason;
    end if;
  end if;

  if v_quarantine_reason is null
     and pg_catalog.cardinality(v_candidate_conversation_ids) = 0 then
    -- A known opaque provider alias routes to its active canonical conversation
    -- before an exact legacy LID row. Edge may leave that source row active,
    -- while native processing retires it; both paths must therefore resolve the
    -- same card without merging or moving the source history.
    if v_primary_alias like '%@lid' then
      select coalesce(pg_catalog.array_agg(candidate.id order by candidate.id), '{}'::uuid[])
      into v_candidate_conversation_ids
      from (
        select distinct conversation.id
        from public.whatsapp_contact_identity_aliases as identity_alias
        join public.whatsapp_conversations as conversation
          on conversation.organization_id = identity_alias.organization_id
         and conversation.session_id = identity_alias.session_id
         and lower(conversation.remote_jid) = lower(identity_alias.canonical_jid)
        where identity_alias.organization_id = p_organization_id
          and identity_alias.session_id = p_session_id
          and lower(identity_alias.alias_jid) = v_primary_alias
          and lower(identity_alias.canonical_jid) <> v_primary_alias
          and conversation.deleted_at is null
        limit 2
      ) as candidate;

      if pg_catalog.cardinality(v_candidate_conversation_ids) > 1 then
        v_quarantine_reason := 'whatsapp_conversation_identity_ambiguous_at_ingress';
        v_candidate_conversation_ids := '{}'::uuid[];
      end if;
    end if;

    -- Otherwise prefer the provider's primary exact JID. Retired rows are
    -- immutable history and never become a fresh event destination.
    if v_quarantine_reason is null
       and pg_catalog.cardinality(v_candidate_conversation_ids) = 0 then
    select coalesce(pg_catalog.array_agg(conversation.id order by conversation.id), '{}'::uuid[])
    into v_candidate_conversation_ids
    from public.whatsapp_conversations as conversation
    where conversation.organization_id = p_organization_id
      and conversation.session_id = p_session_id
      and conversation.deleted_at is null
      and v_primary_alias is not null
      and lower(conversation.remote_jid) = v_primary_alias;
    end if;

    if v_quarantine_reason is null
       and pg_catalog.cardinality(v_candidate_conversation_ids) = 0 then
      select coalesce(pg_catalog.array_agg(candidate.id order by candidate.id), '{}'::uuid[])
      into v_candidate_conversation_ids
      from (
        select distinct conversation.id
        from public.whatsapp_conversations as conversation
        where conversation.organization_id = p_organization_id
          and conversation.session_id = p_session_id
          and conversation.deleted_at is null
          and (
            lower(conversation.remote_jid) = any(v_aliases)
            or (
              v_phone_key <> ''
              and public.normalize_phone(conversation.contact_phone) = v_phone_key
            )
            or exists (
              select 1
              from public.whatsapp_contact_identity_aliases as identity_alias
              where identity_alias.organization_id = p_organization_id
                and identity_alias.session_id = p_session_id
                and lower(identity_alias.alias_jid) = any(v_aliases)
                and lower(identity_alias.canonical_jid) = lower(conversation.remote_jid)
            )
          )
        limit 2
      ) as candidate;
    end if;

    if pg_catalog.cardinality(v_candidate_conversation_ids) > 1 then
      v_quarantine_reason := 'whatsapp_conversation_identity_ambiguous_at_ingress';
      v_candidate_conversation_ids := '{}'::uuid[];
    end if;
  end if;

  if v_quarantine_reason is null
     and pg_catalog.cardinality(v_candidate_conversation_ids) = 1 then
    select conversation.*
    into v_conversation
    from public.whatsapp_conversations as conversation
    where conversation.id = v_candidate_conversation_ids[1]
      and conversation.organization_id = p_organization_id
      and conversation.session_id = p_session_id
      and (
        v_state = 'provider_replay'
        or conversation.deleted_at is null
      )
    for share;

    if not found then
      if v_state <> 'provider_replay' then
        -- Discovery is deliberately non-locking. If an identity reconciler
        -- retired the selected route while this statement waited for its
        -- conversation lock, retry from a fresh snapshot instead of freezing
        -- the now-deleted physical conversation into durable provenance.
        raise exception using
          errcode = '40001',
          message = 'whatsapp_conversation_identity_changed_at_ingress';
      end if;
      v_candidate_conversation_ids := '{}'::uuid[];
    else
      if private.whatsapp_contact_pns_conflict(coalesce(p_identity_aliases, '{}'::text[]) || private.whatsapp_conversation_contact_pn_evidence(p_organization_id, p_session_id, v_conversation.id)) then
        raise exception using errcode = '23514', message = 'whatsapp_contact_pn_conflict';
      end if;
      select binding.*
      into v_active
      from public.whatsapp_conversation_lead_bindings as binding
      where binding.organization_id = p_organization_id
        and binding.conversation_id = v_conversation.id
        and binding.active_to is null
      limit 1
      for share;

      -- Binding writers and native identity reconciliation both lock aliases
      -- only after their conversation/binding locks. Keep that global order and
      -- retain every matching alias row in deterministic UUID order until the
      -- immutable routing snapshot is inserted below.
      perform identity_alias.id
      from public.whatsapp_contact_identity_aliases as identity_alias
      where identity_alias.organization_id = p_organization_id
        and identity_alias.session_id = p_session_id
        and lower(identity_alias.alias_jid) = any(v_aliases)
      order by identity_alias.id
      for share of identity_alias;

      if v_state <> 'provider_replay' and v_primary_alias like '%@lid' then
        select coalesce(pg_catalog.array_agg(candidate.id order by candidate.id), '{}'::uuid[])
        into v_locked_alias_canonical_conversation_ids
        from (
          select distinct conversation.id
          from public.whatsapp_contact_identity_aliases as identity_alias
          join public.whatsapp_conversations as conversation
            on conversation.organization_id = identity_alias.organization_id
           and conversation.session_id = identity_alias.session_id
           and lower(conversation.remote_jid) = lower(identity_alias.canonical_jid)
          where identity_alias.organization_id = p_organization_id
            and identity_alias.session_id = p_session_id
            and lower(identity_alias.alias_jid) = v_primary_alias
            and lower(identity_alias.canonical_jid) <> v_primary_alias
            and conversation.deleted_at is null
          limit 2
        ) as candidate;

        if pg_catalog.cardinality(v_locked_alias_canonical_conversation_ids) > 1 then
          v_quarantine_reason := 'whatsapp_conversation_identity_ambiguous_at_ingress';
        elsif pg_catalog.cardinality(v_locked_alias_canonical_conversation_ids) = 1
              and v_locked_alias_canonical_conversation_ids[1] is distinct from v_conversation.id then
          -- The alias changed after discovery but before its row lock. Retrying
          -- is safe because no inbox/snapshot row from this transaction commits.
          raise exception using
            errcode = '40001',
            message = 'whatsapp_conversation_identity_changed_at_ingress';
        end if;
      end if;

      if (v_active.id is null and v_conversation.lead_id is not null)
         or (v_active.id is not null and v_active.lead_id is distinct from v_conversation.lead_id) then
        v_quarantine_reason := 'whatsapp_conversation_binding_inconsistent_at_ingress';
      elsif v_conversation.lead_id is not null and exists (
        select 1
        from public.whatsapp_contact_identity_aliases as identity_alias
        where identity_alias.organization_id = p_organization_id
          and identity_alias.session_id = p_session_id
          and lower(identity_alias.alias_jid) = any(v_aliases)
          and lower(identity_alias.canonical_jid) = lower(v_conversation.remote_jid)
          and identity_alias.lead_id is not null
          and identity_alias.lead_id is distinct from v_conversation.lead_id
      ) then
        v_quarantine_reason := 'whatsapp_identity_alias_lead_conflict_at_ingress';
      end if;
    end if;
  end if;

  if v_quarantine_reason is null and v_state <> 'provider_replay' then
    if v_context_kind = 'contextual_intake' then
      if v_context_proof is null then
        v_quarantine_reason := 'whatsapp_contextual_intake_proof_required';
      elsif p_origin_round_robin_id is not null and not exists (
        select 1
        from public.round_robins as queue
        where queue.id = p_origin_round_robin_id
          and queue.organization_id = p_organization_id
          and coalesce(queue.is_active, true) = true
      ) then
        v_quarantine_reason := 'whatsapp_contextual_intake_queue_invalid';
      elsif p_rule_id is not null and p_origin_round_robin_id is null then
        v_quarantine_reason := 'whatsapp_contextual_intake_queue_required';
      end if;

      if v_quarantine_reason is null and p_provider_event_lead_id is not null then
        if not exists (
          select 1 from public.leads as lead
          where lead.id = p_provider_event_lead_id
            and lead.organization_id = p_organization_id
        ) then
          v_quarantine_reason := 'whatsapp_contextual_intake_event_lead_invalid';
        else
          v_target_lead_id := p_provider_event_lead_id;
        end if;
      end if;

      if v_quarantine_reason is null
         and v_target_lead_id is null
         and v_phone_key <> '' then
        select coalesce(pg_catalog.array_agg(match.id order by match.id), '{}'::uuid[])
        into v_candidate_lead_ids
        from (
          select lead.id
          from public.leads as lead
          where lead.organization_id = p_organization_id
            and public.normalize_phone(lead.phone) = v_phone_key
            and (
              (
                p_origin_round_robin_id is not null
                and lead.intake_scope_key = 'queue:' || p_origin_round_robin_id::text
              )
              or (
                p_origin_round_robin_id is null
                and (
                  v_context_proof not like 'canonical_intake_v1:%'
                  or lead.intake_scope_key = 'unscoped'
                )
              )
            )
          limit 2
        ) as match;
        if pg_catalog.cardinality(v_candidate_lead_ids) > 1 then
          v_quarantine_reason := 'whatsapp_lead_phone_ambiguous_at_ingress';
        elsif pg_catalog.cardinality(v_candidate_lead_ids) = 1 then
          v_target_lead_id := v_candidate_lead_ids[1];
        end if;
      end if;
      v_state := 'contextual_intake';
    elsif v_conversation.id is not null and v_conversation.lead_id is not null then
      v_target_lead_id := v_conversation.lead_id;
      v_state := 'bound';
    else
      select coalesce(pg_catalog.array_agg(distinct identity_alias.lead_id order by identity_alias.lead_id), '{}'::uuid[])
      into v_candidate_lead_ids
      from public.whatsapp_contact_identity_aliases as identity_alias
      where identity_alias.organization_id = p_organization_id
        and identity_alias.session_id = p_session_id
        and lower(identity_alias.alias_jid) = any(v_aliases)
        and identity_alias.lead_id is not null;

      if pg_catalog.cardinality(v_candidate_lead_ids) > 1 then
        v_quarantine_reason := 'whatsapp_identity_alias_lead_ambiguous_at_ingress';
      elsif pg_catalog.cardinality(v_candidate_lead_ids) = 1 then
        v_target_lead_id := v_candidate_lead_ids[1];
        v_state := 'lead_match';
      elsif v_phone_key <> '' then
        select coalesce(pg_catalog.array_agg(match.id order by match.id), '{}'::uuid[])
        into v_candidate_lead_ids
        from (
          select lead.id
          from public.leads as lead
          where lead.organization_id = p_organization_id
            and public.normalize_phone(lead.phone) = v_phone_key
          limit 2
        ) as match;
        if pg_catalog.cardinality(v_candidate_lead_ids) > 1 then
          v_quarantine_reason := 'whatsapp_lead_phone_ambiguous_at_ingress';
        elsif pg_catalog.cardinality(v_candidate_lead_ids) = 1 then
          v_target_lead_id := v_candidate_lead_ids[1];
          v_state := 'lead_match';
        end if;
      end if;
    end if;
  end if;

  if v_quarantine_reason is not null then
    v_state := 'quarantine';
    v_target_lead_id := null;
  end if;

  v_binding_eligible := v_binding_eligible
    and v_routing_key <> '__session__'
    and v_state <> 'quarantine';
  if v_binding_eligible then
    select routing_snapshot.*
    into v_predecessor
    from public.whatsapp_webhook_routing_snapshots as routing_snapshot
    where routing_snapshot.organization_id = p_organization_id
      and routing_snapshot.session_id = p_session_id
      and routing_snapshot.routing_key = v_routing_key
      and routing_snapshot.processing_epoch = p_processing_epoch
      and routing_snapshot.binding_eligible = true
      and not exists (
        select 1
        from public.whatsapp_webhook_routing_outcomes as routing_outcome
        where routing_outcome.organization_id = routing_snapshot.organization_id
          and routing_outcome.session_id = routing_snapshot.session_id
          and routing_outcome.provider_message_id = routing_snapshot.provider_message_id
          and routing_outcome.ingress_sequence = routing_snapshot.ingress_sequence
      )
    order by routing_snapshot.ingress_sequence desc
    limit 1;
    v_predecessor_provider_message_id := v_predecessor.provider_message_id;
  end if;

  v_binding_eligible := v_binding_eligible and (
    v_context_kind = 'contextual_intake'
    or v_target_lead_id is not null
    or (
      v_context_kind = 'organic'
      and v_predecessor_provider_message_id is not null
    )
  );

  if v_binding_eligible
     and v_predecessor_provider_message_id is not null
     and v_context_kind = 'organic'
     and v_state <> 'provider_replay' then
    -- The predecessor may create or select a queue-scoped card that does not
    -- exist yet. Freeze the dependency, not the old lead visible before it ran.
    v_target_mode := 'inherit_predecessor';
    v_state := 'predecessor_inherit';
    v_target_lead_id := null;
  end if;
  v_ingress_sequence := nextval('public.whatsapp_webhook_routing_ingress_sequence');

  v_snapshot := pg_catalog.jsonb_build_object(
    'version', 1,
    'processing_epoch', p_processing_epoch,
    'organization_id', p_organization_id,
    'session_id', p_session_id,
    'provider_message_id', v_provider_message_id,
    'inbox_event_key', v_inbox_event_key,
    'processing_lane', v_processing_lane,
    'state', v_state,
    'conversation_id', v_conversation.id,
    'event_lead_id', v_target_lead_id,
    'current_lead_id', v_conversation.lead_id,
    'active_binding_id', v_active.id,
    'quarantine_reason', v_quarantine_reason,
    'context_kind', v_context_kind,
    'context_proof', v_context_proof,
    'rule_id', p_rule_id,
    'origin_round_robin_id', p_origin_round_robin_id,
    'managed_message_distribution', v_managed_message_distribution,
    'managed_event_pending', v_managed_event_pending,
    'managed_event_handled', v_managed_event_handled,
    'routing_key', v_routing_key,
    'binding_eligible', v_binding_eligible,
    'target_mode', v_target_mode,
    'ingress_sequence', v_ingress_sequence,
    'predecessor_provider_message_id', v_predecessor_provider_message_id,
    'predecessor_inbox_event_key', v_predecessor.inbox_event_key,
    'predecessor_processing_lane', v_predecessor.processing_lane,
    'captured_at', clock_timestamp()
  );

  insert into public.whatsapp_webhook_routing_snapshots (
    organization_id,
    session_id,
    provider_message_id,
    inbox_event_key,
    processing_lane,
    routing_key,
    ingress_sequence,
    predecessor_provider_message_id,
    binding_eligible,
    target_mode,
    processing_epoch,
    snapshot
  ) values (
    p_organization_id,
    p_session_id,
    v_provider_message_id,
    v_inbox_event_key,
    v_processing_lane,
    v_routing_key,
    v_ingress_sequence,
    v_predecessor_provider_message_id,
    v_binding_eligible,
    v_target_mode,
    p_processing_epoch,
    v_snapshot
  )
  on conflict (organization_id, session_id, provider_message_id) do nothing;

  if not found then
    select routing_snapshot.*
    into v_existing_snapshot
    from public.whatsapp_webhook_routing_snapshots as routing_snapshot
    where routing_snapshot.organization_id = p_organization_id
      and routing_snapshot.session_id = p_session_id
      and routing_snapshot.provider_message_id = v_provider_message_id;
    if v_existing_snapshot.routing_key is distinct from v_routing_key then
      raise exception using
        errcode = '23505',
        message = 'whatsapp_ingress_snapshot_provider_identity_conflict';
    end if;
    return v_existing_snapshot.snapshot;
  end if;

  return v_snapshot;
end;
$$;


ALTER FUNCTION private.capture_whatsapp_webhook_routing_snapshot_v2(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_inbox_event_key text, p_processing_lane text, p_routing_key text, p_binding_eligible boolean, p_identity_aliases text[], p_contact_phone text, p_context_kind text, p_context_proof text, p_managed_message_distribution boolean, p_managed_event_pending boolean, p_managed_event_handled boolean, p_rule_id uuid, p_origin_round_robin_id uuid, p_provider_event_lead_id uuid, p_processing_epoch integer) OWNER TO postgres;

--
-- Name: cascade_property_city_projection(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cascade_property_city_projection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.properties
  set cidade = new.name, uf = new.uf, updated_at = now()
  where organization_id = new.organization_id
    and city_id = new.id
    and (cidade, uf) is distinct from (new.name, new.uf);
  return new;
end
$$;


ALTER FUNCTION private.cascade_property_city_projection() OWNER TO postgres;

--
-- Name: cascade_property_condominium_projection(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cascade_property_condominium_projection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.properties
  set city_id = coalesce(new.city_id, properties.city_id),
      neighborhood_id = coalesce(new.neighborhood_id, properties.neighborhood_id),
      cidade = coalesce(city.name, properties.cidade),
      uf = coalesce(city.uf, properties.uf),
      bairro = coalesce(neighborhood.name, properties.bairro),
      updated_at = now()
  from (select 1) marker
  left join public.property_cities city
    on city.organization_id = new.organization_id and city.id = new.city_id
  left join public.property_neighborhoods neighborhood
    on neighborhood.organization_id = new.organization_id and neighborhood.id = new.neighborhood_id
  where properties.organization_id = new.organization_id
    and properties.condominium_id = new.id
    and (
      (new.city_id is not null and properties.city_id is distinct from new.city_id)
      or (new.neighborhood_id is not null and properties.neighborhood_id is distinct from new.neighborhood_id)
      or (city.id is not null and (properties.cidade, properties.uf) is distinct from (city.name, city.uf))
      or (neighborhood.id is not null and properties.bairro is distinct from neighborhood.name)
    );
  return new;
end
$$;


ALTER FUNCTION private.cascade_property_condominium_projection() OWNER TO postgres;

--
-- Name: cascade_property_neighborhood_projection(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cascade_property_neighborhood_projection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.property_condominiums
  set city_id = new.city_id, updated_at = now()
  where organization_id = new.organization_id
    and neighborhood_id = new.id
    and city_id is distinct from new.city_id;

  update public.properties
  set city_id = new.city_id,
      bairro = new.name,
      cidade = city.name,
      uf = city.uf,
      updated_at = now()
  from (select 1) marker
  left join public.property_cities city
    on city.organization_id = new.organization_id and city.id = new.city_id
  where properties.organization_id = new.organization_id
    and properties.neighborhood_id = new.id
    and (properties.city_id, properties.bairro, properties.cidade, properties.uf)
      is distinct from (new.city_id, new.name, city.name, city.uf);
  return new;
end
$$;


ALTER FUNCTION private.cascade_property_neighborhood_projection() OWNER TO postgres;

--
-- Name: check_public_ingress_rate_limit(text, text, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.check_public_ingress_rate_limit(p_scope text, p_subject_hash text, p_limit integer, p_window_seconds integer, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_window_started_at timestamptz;
  v_request_count integer;
begin
  p_scope := btrim(coalesce(p_scope, ''));
  p_subject_hash := lower(btrim(coalesce(p_subject_hash, '')));
  p_now := coalesce(p_now, clock_timestamp());

  if length(p_scope) not between 1 and 100
     or p_subject_hash !~ '^[0-9a-f]{64}$'
     or p_limit not between 1 and 100000
     or p_window_seconds not between 1 and 86400 then
    raise exception using
      errcode = '22023',
      message = 'invalid_public_ingress_rate_limit';
  end if;

  v_window_started_at := pg_catalog.to_timestamp(
    pg_catalog.floor(
      extract(epoch from p_now) / p_window_seconds
    ) * p_window_seconds
  );

  insert into private.public_ingress_rate_limits (
    scope,
    subject_hash,
    window_started_at,
    request_count,
    updated_at
  )
  values (
    p_scope,
    p_subject_hash,
    v_window_started_at,
    1,
    p_now
  )
  on conflict (scope, subject_hash, window_started_at)
  do update
  set request_count = least(
        private.public_ingress_rate_limits.request_count + 1,
        p_limit + 1
      ),
      updated_at = excluded.updated_at
  returning request_count
  into v_request_count;

  return v_request_count <= p_limit;
end
$_$;


ALTER FUNCTION private.check_public_ingress_rate_limit(p_scope text, p_subject_hash text, p_limit integer, p_window_seconds integer, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION check_public_ingress_rate_limit(p_scope text, p_subject_hash text, p_limit integer, p_window_seconds integer, p_now timestamp with time zone); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.check_public_ingress_rate_limit(p_scope text, p_subject_hash text, p_limit integer, p_window_seconds integer, p_now timestamp with time zone) IS 'Replica-safe fixed-window limiter for server-derived, SHA-256 ingress identities.';


--
-- Name: check_queue_pool_owner_invariant(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.check_queue_pool_owner_invariant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists(select 1 from private.queue_lead_runtime r join public.leads l on l.organization_id=r.organization_id and l.id=r.lead_id
    where r.organization_id=new.organization_id and r.lead_id=new.lead_id and r.state in ('pool_waiting','pool_ready','limit_exhausted') and l.assigned_user_id is not null) then
    raise exception using errcode='23514',message='queue_pool_requires_unassigned_owner'; end if;
  return null;
end;
$$;


ALTER FUNCTION private.check_queue_pool_owner_invariant() OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: notification_deliveries; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.notification_deliveries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    notification_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid,
    channel text NOT NULL,
    recipient_key text NOT NULL,
    push_token_id uuid,
    idempotency_key text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    priority smallint DEFAULT 100 NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 24 NOT NULL,
    next_attempt_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    lease_token uuid,
    leased_by text,
    lease_expires_at timestamp with time zone,
    dependency_key text,
    provider text,
    provider_message_id text,
    provider_status text,
    accepted_at timestamp with time zone,
    delivered_at timestamp with time zone,
    blocked_at timestamp with time zone,
    terminal_at timestamp with time zone,
    last_error_code text,
    last_error_message text,
    last_error_at timestamp with time zone,
    last_attempt_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notification_deliveries_attempt_budget_check CHECK (((attempt_count >= 0) AND ((max_attempts >= 1) AND (max_attempts <= 100)) AND (attempt_count <= max_attempts))),
    CONSTRAINT notification_deliveries_blocked_at_check CHECK ((((status = 'blocked_dependency'::text) AND (blocked_at IS NOT NULL)) OR ((status <> 'blocked_dependency'::text) AND (blocked_at IS NULL)))),
    CONSTRAINT notification_deliveries_channel_check CHECK ((channel = ANY (ARRAY['whatsapp'::text, 'push'::text, 'email'::text]))),
    CONSTRAINT notification_deliveries_dependency_check CHECK ((((status = 'blocked_dependency'::text) AND (NULLIF(btrim(dependency_key), ''::text) IS NOT NULL)) OR ((status <> 'blocked_dependency'::text) AND (dependency_key IS NULL)))),
    CONSTRAINT notification_deliveries_expiry_check CHECK ((expires_at >= created_at)),
    CONSTRAINT notification_deliveries_idempotency_key_check CHECK (((NULLIF(btrim(idempotency_key), ''::text) IS NOT NULL) AND (char_length(idempotency_key) <= 255))),
    CONSTRAINT notification_deliveries_lease_check CHECK ((((status = ANY (ARRAY['leased'::text, 'sending'::text])) AND (lease_token IS NOT NULL) AND (NULLIF(btrim(leased_by), ''::text) IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((status <> ALL (ARRAY['leased'::text, 'sending'::text])) AND (lease_token IS NULL) AND (leased_by IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT notification_deliveries_metadata_object_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT notification_deliveries_priority_check CHECK (((priority >= 0) AND (priority <= 1000))),
    CONSTRAINT notification_deliveries_provider_fields_check CHECK ((((provider IS NULL) OR (char_length(provider) <= 100)) AND ((provider_message_id IS NULL) OR (char_length(provider_message_id) <= 500)) AND ((provider_status IS NULL) OR (char_length(provider_status) <= 255)) AND ((leased_by IS NULL) OR (char_length(leased_by) <= 255)) AND ((dependency_key IS NULL) OR (char_length(dependency_key) <= 255)) AND ((last_error_code IS NULL) OR (char_length(last_error_code) <= 255)) AND ((last_error_message IS NULL) OR (char_length(last_error_message) <= 2000)))),
    CONSTRAINT notification_deliveries_push_target_check CHECK ((((channel = 'push'::text) AND (push_token_id IS NOT NULL)) OR ((channel <> 'push'::text) AND (push_token_id IS NULL)))),
    CONSTRAINT notification_deliveries_recipient_key_check CHECK (((NULLIF(btrim(recipient_key), ''::text) IS NOT NULL) AND (char_length(recipient_key) <= 255))),
    CONSTRAINT notification_deliveries_schedule_check CHECK ((((status = ANY (ARRAY['queued'::text, 'retry_wait'::text])) AND (next_attempt_at IS NOT NULL)) OR ((status <> ALL (ARRAY['queued'::text, 'retry_wait'::text])) AND (next_attempt_at IS NULL)))),
    CONSTRAINT notification_deliveries_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'leased'::text, 'sending'::text, 'accepted'::text, 'delivered'::text, 'retry_wait'::text, 'blocked_dependency'::text, 'dead_letter'::text, 'cancelled'::text, 'permanent_failed'::text]))),
    CONSTRAINT notification_deliveries_terminal_at_check CHECK ((((status = ANY (ARRAY['delivered'::text, 'dead_letter'::text, 'cancelled'::text, 'permanent_failed'::text])) AND (terminal_at IS NOT NULL)) OR ((status <> ALL (ARRAY['delivered'::text, 'dead_letter'::text, 'cancelled'::text, 'permanent_failed'::text])) AND (terminal_at IS NULL))))
);


ALTER TABLE private.notification_deliveries OWNER TO postgres;

--
-- Name: TABLE notification_deliveries; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON TABLE private.notification_deliveries IS 'Durable backend-owned delivery jobs. One logical delivery per notification, channel and non-PII recipient key.';


--
-- Name: claim_notification_deliveries(text, integer, interval, text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_notification_deliveries(p_worker_id text, p_batch_size integer DEFAULT 25, p_lease_for interval DEFAULT '00:02:00'::interval, p_channels text[] DEFAULT NULL::text[]) RETURNS SETOF private.notification_deliveries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch_size integer := least(greatest(coalesce(p_batch_size, 25), 1), 100);
  v_lease_for interval := greatest(
    interval '15 seconds',
    least(coalesce(p_lease_for, interval '2 minutes'), interval '15 minutes')
  );
  v_delivery private.notification_deliveries%rowtype;
begin
  if nullif(btrim(coalesce(p_worker_id, '')), '') is null
     or char_length(p_worker_id) > 255 then
    raise exception 'invalid notification delivery worker id';
  end if;
  if p_channels is not null and (
    cardinality(p_channels) = 0
    or exists (
      select 1
      from unnest(p_channels) as requested(channel)
      where requested.channel is null
         or requested.channel not in ('whatsapp', 'push', 'email')
    )
  ) then
    raise exception 'invalid notification delivery channels';
  end if;

  if right(p_worker_id,11)='|wa_push_v2' and (p_channels is null or 'push'=any(p_channels)) then
    perform private.seed_whatsapp_inbound_push_waiting(100);
    perform private.recover_whatsapp_inbound_push_waiting(v_batch_size);
  end if;
  for v_delivery in
    with candidates as (
      select delivery.id
      from private.notification_deliveries as delivery
      where ((delivery.status in ('queued', 'retry_wait') and delivery.next_attempt_at <= now())
          or (right(p_worker_id,11)='|wa_push_v2' and delivery.status='blocked_dependency' and private.whatsapp_inbound_push_needs_reassignment(delivery)))
        and delivery.expires_at > now()
        and delivery.attempt_count < delivery.max_attempts
        and (p_channels is null or delivery.channel = any(p_channels))
        and (delivery.channel<>'push' or right(p_worker_id,26)='|push_device_v3|wa_push_v2' or exists(
          select 1 from public.push_tokens legacy_token where legacy_token.id=delivery.push_token_id
            and legacy_token.organization_id=delivery.organization_id
        ))
        and (right(p_worker_id,11)='|wa_push_v2' or delivery.channel<>'push' or not exists (
          select 1 from public.notifications notification where notification.id=delivery.notification_id
            and notification.organization_id=delivery.organization_id
            and notification.metadata->>'event_key'='whatsapp_inbound_attendant'
        ))
        and (
          delivery.channel <> 'push'
          or (right(p_worker_id,11)='|wa_push_v2' and private.whatsapp_inbound_push_is_unstarted(delivery))
          or exists (
            select 1
            from public.push_tokens as token
            where token.id = delivery.push_token_id
              and private.push_notification_recipient_is_active(delivery.organization_id,delivery.user_id)
              and token.user_id = delivery.user_id
              and token.is_active is true
          )
        )
      order by
        delivery.priority desc,
        delivery.next_attempt_at asc,
        delivery.created_at asc,
        delivery.id asc
      limit v_batch_size
      for update skip locked
    )
    update private.notification_deliveries as delivery
    set status = 'leased',
        next_attempt_at = null,
        lease_token = gen_random_uuid(),
        leased_by = btrim(p_worker_id),
        lease_expires_at = now() + v_lease_for,
        dependency_key = null,
        blocked_at = null,
        updated_at = now()
    from candidates
    where delivery.id = candidates.id
    returning delivery.*
  loop
    return next v_delivery;
  end loop;

  return;
end
$$;


ALTER FUNCTION private.claim_notification_deliveries(p_worker_id text, p_batch_size integer, p_lease_for interval, p_channels text[]) OWNER TO postgres;

--
-- Name: property_channel_publication_jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.property_channel_publication_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    publication_id uuid NOT NULL,
    version_id uuid,
    organization_id uuid NOT NULL,
    property_id uuid NOT NULL,
    channel text NOT NULL,
    channel_account_key text DEFAULT 'default'::text NOT NULL,
    action text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 12 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    lease_token uuid,
    last_error_code text,
    last_error_message text,
    requested_by uuid,
    completed_at timestamp with time zone,
    dead_lettered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT property_channel_jobs_account_check CHECK (((channel_account_key = btrim(channel_account_key)) AND ((char_length(channel_account_key) >= 1) AND (char_length(channel_account_key) <= 160)) AND (channel_account_key ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]*$'::text))),
    CONSTRAINT property_channel_jobs_action_check CHECK ((action = ANY (ARRAY['publish'::text, 'update'::text, 'unpublish'::text, 'revalidate'::text]))),
    CONSTRAINT property_channel_jobs_attempts_check CHECK (((attempts >= 0) AND ((max_attempts >= 1) AND (max_attempts <= 50)) AND (attempts <= max_attempts))),
    CONSTRAINT property_channel_jobs_channel_check CHECK (((channel = lower(channel)) AND ((char_length(channel) >= 1) AND (char_length(channel) <= 64)) AND (channel ~ '^[a-z][a-z0-9_.-]*$'::text))),
    CONSTRAINT property_channel_jobs_dead_letter_check CHECK ((((status = 'dead'::text) AND (dead_lettered_at IS NOT NULL)) OR ((status <> 'dead'::text) AND (dead_lettered_at IS NULL)))),
    CONSTRAINT property_channel_jobs_error_code_check CHECK (((last_error_code IS NULL) OR ((char_length(last_error_code) >= 1) AND (char_length(last_error_code) <= 160)))),
    CONSTRAINT property_channel_jobs_error_message_check CHECK (((last_error_message IS NULL) OR ((char_length(last_error_message) >= 1) AND (char_length(last_error_message) <= 4000)))),
    CONSTRAINT property_channel_jobs_idempotency_check CHECK (((idempotency_key = btrim(idempotency_key)) AND ((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 200)))),
    CONSTRAINT property_channel_jobs_lock_check CHECK ((((status = 'processing'::text) AND (locked_at IS NOT NULL) AND (NULLIF(btrim(locked_by), ''::text) IS NOT NULL) AND (lease_token IS NOT NULL)) OR ((status <> 'processing'::text) AND (locked_at IS NULL) AND (locked_by IS NULL) AND (lease_token IS NULL)))),
    CONSTRAINT property_channel_jobs_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT property_channel_jobs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'retry'::text, 'succeeded'::text, 'superseded'::text, 'dead'::text]))),
    CONSTRAINT property_channel_jobs_terminal_check CHECK ((((status = ANY (ARRAY['succeeded'::text, 'superseded'::text, 'dead'::text])) AND (completed_at IS NOT NULL)) OR ((status <> ALL (ARRAY['succeeded'::text, 'superseded'::text, 'dead'::text])) AND (completed_at IS NULL)))),
    CONSTRAINT property_channel_jobs_version_required_check CHECK (((action <> ALL (ARRAY['publish'::text, 'update'::text, 'revalidate'::text])) OR (version_id IS NOT NULL)))
);

ALTER TABLE ONLY public.property_channel_publication_jobs FORCE ROW LEVEL SECURITY;


ALTER TABLE public.property_channel_publication_jobs OWNER TO postgres;

--
-- Name: TABLE property_channel_publication_jobs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.property_channel_publication_jobs IS 'Backend-only durable publication work with retry, lease and fencing state.';


--
-- Name: claim_property_channel_publication_jobs(text, integer, interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_property_channel_publication_jobs(p_worker_id text, p_limit integer DEFAULT 50, p_lease interval DEFAULT '00:05:00'::interval) RETURNS SETOF public.property_channel_publication_jobs
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  claim_time timestamptz := clock_timestamp();
begin
  if nullif(btrim(p_worker_id), '') is null then
    raise exception using
      errcode = '22023',
      message = 'property_publication_worker_id_required';
  end if;
  if coalesce(p_limit, 0) < 1 then
    raise exception using
      errcode = '22023',
      message = 'property_publication_claim_limit_invalid';
  end if;
  if p_lease is null or p_lease <= interval '0 seconds' then
    raise exception using
      errcode = '22023',
      message = 'property_publication_lease_invalid';
  end if;

  update public.property_channel_publication_jobs as exhausted
  set status = 'dead',
      locked_at = null,
      locked_by = null,
      lease_token = null,
      completed_at = claim_time,
      dead_lettered_at = claim_time,
      last_error_code = coalesce(
        exhausted.last_error_code,
        'retry_exhausted'
      ),
      last_error_message = coalesce(
        exhausted.last_error_message,
        'Publication retry limit exhausted.'
      ),
      updated_at = claim_time
  where exhausted.attempts >= exhausted.max_attempts
    and (
      (
        exhausted.status in ('pending', 'retry')
        and exhausted.next_attempt_at <= claim_time
      )
      or (
        exhausted.status = 'processing'
        and exhausted.locked_at < claim_time - p_lease
      )
    );

  return query
  with candidates as (
    select queued.id
    from public.property_channel_publication_jobs as queued
    where queued.attempts < queued.max_attempts
      and (
        (
          queued.status in ('pending', 'retry')
          and queued.next_attempt_at <= claim_time
        )
        or (
          queued.status = 'processing'
          and queued.locked_at < claim_time - p_lease
        )
      )
    order by
      case
        when queued.status = 'processing' then queued.locked_at
        else queued.next_attempt_at
      end,
      queued.created_at,
      queued.id
    for update skip locked
    limit greatest(1, least(p_limit, 500))
  )
  update public.property_channel_publication_jobs as claimed
  set status = 'processing',
      attempts = claimed.attempts + 1,
      locked_at = claim_time,
      locked_by = btrim(p_worker_id),
      lease_token = gen_random_uuid(),
      last_error_code = null,
      last_error_message = null,
      completed_at = null,
      dead_lettered_at = null,
      updated_at = claim_time
  from candidates
  where claimed.id = candidates.id
  returning claimed.*;
end;
$$;


ALTER FUNCTION private.claim_property_channel_publication_jobs(p_worker_id text, p_limit integer, p_lease interval) OWNER TO postgres;

--
-- Name: claim_queue_pool(uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_queue_pool(p_organization_id uuid, p_lead_id uuid, p_actor_id uuid, p_round_robin_id uuid, p_episode_id uuid, p_expected_revision bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_organization_id is null or p_round_robin_id is null then
    return jsonb_build_object('success',false,'reason','not_found');
  end if;
  if not exists(select 1 from public.round_robins where organization_id=p_organization_id and id=p_round_robin_id) then
    return jsonb_build_object('success',false,'reason','not_found');
  end if;

  perform 1 from public.round_robins where organization_id=p_organization_id and id=p_round_robin_id for share skip locked;
  if not found then
    -- A concurrent delete or tenant change can commit between the existence
    -- read and lock attempt. Preserve not-found after that race as well.
    if not exists(select 1 from public.round_robins where organization_id=p_organization_id and id=p_round_robin_id) then
      return jsonb_build_object('success',false,'reason','not_found');
    end if;
    return jsonb_build_object('success',false,'reason','queue_busy');
  end if;

  return private.claim_queue_pool_before_concurrency_guard(p_organization_id,p_lead_id,p_actor_id,p_round_robin_id,p_episode_id,p_expected_revision,p_idempotency_key);
end;
$$;


ALTER FUNCTION private.claim_queue_pool(p_organization_id uuid, p_lead_id uuid, p_actor_id uuid, p_round_robin_id uuid, p_episode_id uuid, p_expected_revision bigint, p_idempotency_key text) OWNER TO postgres;

--
-- Name: claim_queue_pool_before_concurrency_guard(uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_queue_pool_before_concurrency_guard(p_organization_id uuid, p_lead_id uuid, p_actor_id uuid, p_round_robin_id uuid, p_episode_id uuid, p_expected_revision bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r private.queue_lead_runtime%rowtype; receipt private.queue_pool_claim_receipts%rowtype;
  result jsonb; actual_owner uuid; now_at timestamptz:=clock_timestamp();
begin
  if p_organization_id is null or p_lead_id is null or p_actor_id is null or p_round_robin_id is null or p_episode_id is null
    or p_expected_revision is null or p_expected_revision<1 then return jsonb_build_object('success',false,'reason','not_found'); end if;
  if not private.queue_runtime_actor_can_claim(p_organization_id,p_actor_id) then return jsonb_build_object('success',false,'reason','forbidden'); end if;
  if not private.queue_pool_audience(p_organization_id,p_round_robin_id,p_actor_id) then return jsonb_build_object('success',false,'reason','forbidden'); end if;
  if length(btrim(coalesce(p_idempotency_key,''))) not between 1 and 200 or p_idempotency_key<>btrim(p_idempotency_key) then
    return jsonb_build_object('success',false,'reason','invalid_idempotency_key'); end if;
  if not pg_try_advisory_xact_lock(hashtextextended('queue-claim:'||p_organization_id::text||':'||p_actor_id::text||':'||p_idempotency_key,0)) then
    return jsonb_build_object('success',false,'reason','queue_busy'); end if;
  select * into receipt from private.queue_pool_claim_receipts where organization_id=p_organization_id and actor_id=p_actor_id and idempotency_key=p_idempotency_key;
  if found then
    if receipt.lead_id<>p_lead_id or receipt.round_robin_id<>p_round_robin_id or receipt.episode_id<>p_episode_id or receipt.expected_revision<>p_expected_revision then
      return jsonb_build_object('success',false,'reason','idempotency_key_conflict'); end if;
    if not exists(select 1 from public.leads l join private.queue_lead_runtime runtime on runtime.organization_id=l.organization_id and runtime.lead_id=l.id
      where l.organization_id=p_organization_id and l.id=p_lead_id and l.assigned_user_id=p_actor_id
        and runtime.episode_id=p_episode_id and runtime.state='manual_protected' and runtime.protected_actor_id=p_actor_id) then
      return jsonb_build_object('success',false,'reason','revision_conflict'); end if;
    return receipt.result||jsonb_build_object('reason','already_claimed');
  end if;
  if not private.queue_pool_audience(p_organization_id,p_round_robin_id,p_actor_id) then return jsonb_build_object('success',false,'reason','forbidden'); end if;
  perform 1 from public.round_robins where organization_id=p_organization_id and id=p_round_robin_id for share skip locked;
  if not found then return jsonb_build_object('success',false,'reason','queue_busy'); end if;
  select assigned_user_id into actual_owner from public.leads where organization_id=p_organization_id and id=p_lead_id for no key update skip locked;
  if not found then return jsonb_build_object('success',false,'reason','not_found'); end if;
  select * into r from private.queue_lead_runtime where organization_id=p_organization_id and lead_id=p_lead_id for update;
  if not found or r.round_robin_id<>p_round_robin_id or r.episode_id<>p_episode_id then return jsonb_build_object('success',false,'reason','not_found'); end if;
  if r.revision<>p_expected_revision then return jsonb_build_object('success',false,'reason','revision_conflict'); end if;
  if r.state not in ('pool_waiting','pool_ready','limit_exhausted') or actual_owner is not null then return jsonb_build_object('success',false,'reason','not_in_pool'); end if;
  insert into private.queue_runtime_commands values(txid_current(),p_organization_id,p_lead_id,'claim',p_actor_id);
  update private.queue_lead_runtime set state='manual_protected',reason='manual_claim',protected_actor_id=p_actor_id,revision=revision+1,
    next_action_at=null,due_at=null,entered_pool_at=null,last_user_id=p_actor_id,assigned_at=now_at,retry_count=0,quarantined_at=null,last_error_code=null,last_distribution_event_id=null,updated_at=now_at
    where organization_id=p_organization_id and lead_id=p_lead_id returning * into r;
  update public.leads set assigned_user_id=p_actor_id,assigned_at=now_at,updated_at=now_at where organization_id=p_organization_id and id=p_lead_id;
  insert into private.queue_runtime_events(organization_id,lead_id,round_robin_id,episode_id,round_number,event_type,to_user_id,actor_id,metadata,created_at)
    values(p_organization_id,p_lead_id,p_round_robin_id,p_episode_id,r.round_number,'manual_claim',p_actor_id,p_actor_id,jsonb_build_object('revision',r.revision),now_at);
  insert into public.assignments_log(organization_id,lead_id,round_robin_id,assigned_user_id,old_user_id,new_user_id,reason,assigned_at)
    values(p_organization_id,p_lead_id,p_round_robin_id,p_actor_id,null,p_actor_id,'queue_pool_claim',now_at);
  result:=jsonb_build_object('success',true,'reason','claimed','lead_id',p_lead_id,'assigned_user_id',p_actor_id,'episode_id',p_episode_id,'revision',r.revision);
  insert into private.queue_pool_claim_receipts values(p_organization_id,p_actor_id,p_idempotency_key,p_lead_id,p_round_robin_id,p_episode_id,p_expected_revision,result,now_at);
  delete from private.queue_runtime_commands where transaction_id=txid_current() and organization_id=p_organization_id and lead_id=p_lead_id;
  return result;
end;
$$;


ALTER FUNCTION private.claim_queue_pool_before_concurrency_guard(p_organization_id uuid, p_lead_id uuid, p_actor_id uuid, p_round_robin_id uuid, p_episode_id uuid, p_expected_revision bigint, p_idempotency_key text) OWNER TO postgres;

--
-- Name: claim_whatsapp_avatar_job(text, interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_whatsapp_avatar_job(p_worker_id text, p_lease interval DEFAULT '00:01:00'::interval) RETURNS TABLE(id uuid, organization_id uuid, lead_id uuid, session_id uuid, conversation_id uuid, binding_id uuid, source_message_id uuid, remote_jid text, attempts smallint, lease_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if nullif(btrim(p_worker_id), '') is null then
    raise exception 'avatar worker id is required' using errcode = '22023';
  end if;
  if p_lease is null
     or p_lease < interval '30 seconds'
     or p_lease > interval '5 minutes' then
    raise exception 'avatar worker lease must be between 30 seconds and 5 minutes'
      using errcode = '22023';
  end if;

  -- Claims are serialized only while a row and its per-session slot are chosen.
  -- Provider and Storage I/O always happen after this transaction commits.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('vimob:whatsapp-avatar:claim', 0)
  );

  update private.whatsapp_avatar_jobs as stale
  set
    status = case
      when stale.attempts >= stale.max_attempts then 'not_available'
      when stale.last_contact_message_id is distinct from stale.last_attempt_message_id
        then 'pending'
      when stale.eligible_contact_count >= stale.max_attempts
        then 'not_available'
      else 'awaiting_next_contact'
    end,
    next_attempt_at = now(),
    locked_at = null,
    lease_expires_at = null,
    locked_by = null,
    lease_token = null,
    last_error = 'avatar_worker_lease_expired',
    updated_at = now()
  where stale.status = 'processing'
    and stale.lease_expires_at < now();

  -- A recorded second contact is the final eligibility slot. If neither the
  -- still-unclaimed first contact nor that exact second binding can ever be
  -- claimed, terminate the job instead of polling a permanently empty join.
  -- Session connectivity and the per-session slot are deliberately excluded:
  -- both are temporary and must only delay a claim.
  update private.whatsapp_avatar_jobs as invalid
  set
    status = 'not_available',
    next_attempt_at = now(),
    last_error = 'avatar_contact_no_longer_current',
    updated_at = now()
  where invalid.status = 'pending'
    and invalid.eligible_contact_count >= 2
    and invalid.attempts < invalid.max_attempts
    and not (
      invalid.attempts = 0
      and exists (
        select 1
        from public.whatsapp_messages as source_message
        join public.whatsapp_conversations as source_conversation
          on source_conversation.organization_id = source_message.organization_id
         and source_conversation.id = source_message.conversation_id
         and source_conversation.session_id = source_message.session_id
         and source_conversation.lead_id = source_message.lead_id
         and source_conversation.deleted_at is null
         and coalesce(source_conversation.is_group, false) = false
        join public.whatsapp_conversation_lead_bindings as source_binding
          on source_binding.organization_id = source_conversation.organization_id
         and source_binding.id = invalid.binding_id
         and source_binding.conversation_id = source_conversation.id
         and source_binding.session_id = source_conversation.session_id
         and source_binding.lead_id = source_conversation.lead_id
         and source_binding.active_to is null
         and source_binding.stale = false
        where source_message.organization_id = invalid.organization_id
          and source_message.id = invalid.source_message_id
          and source_message.lead_id = invalid.lead_id
      )
    )
    and not exists (
      select 1
      from public.whatsapp_messages as remaining_message
      join public.whatsapp_conversations as remaining_conversation
        on remaining_conversation.organization_id = remaining_message.organization_id
       and remaining_conversation.id = remaining_message.conversation_id
       and remaining_conversation.session_id = remaining_message.session_id
       and remaining_conversation.lead_id = remaining_message.lead_id
       and remaining_conversation.deleted_at is null
       and coalesce(remaining_conversation.is_group, false) = false
      join public.whatsapp_conversation_lead_bindings as remaining_binding
        on remaining_binding.organization_id = remaining_conversation.organization_id
       and remaining_binding.id = invalid.last_contact_binding_id
       and remaining_binding.conversation_id = remaining_conversation.id
       and remaining_binding.session_id = remaining_conversation.session_id
       and remaining_binding.lead_id = remaining_conversation.lead_id
       and remaining_binding.active_to is null
       and remaining_binding.stale = false
      where remaining_message.organization_id = invalid.organization_id
        and remaining_message.id = invalid.last_contact_message_id
        and remaining_message.id is distinct from invalid.source_message_id
        and remaining_message.lead_id = invalid.lead_id
    );

  return query
  with candidate as materialized (
    select
      job.id,
      contact.organization_id,
      contact.lead_id,
      contact.session_id,
      contact.conversation_id,
      contact.binding_id,
      contact.message_id as source_message_id,
      case
        -- Contact one became unusable before its first claim. Contact two is
        -- the final eligible opportunity, so claiming it consumes both slots.
        when job.attempts = 0
          and contact.message_id is distinct from job.source_message_id
          then job.max_attempts
        else (job.attempts + 1)::smallint
      end as claimed_attempts,
      contact.remote_jid
    from private.whatsapp_avatar_jobs as job
    cross join lateral (
      -- Resolve validity and first/second preference before considering the
      -- per-session processing slot. A busy first-contact session must delay
      -- this job, never make contact two look like the fallback.
      select
        message.organization_id,
        message.lead_id,
        message.session_id,
        message.conversation_id,
        binding.id as binding_id,
        message.id as message_id,
        coalesce(
          nullif(btrim(message.remote_jid), ''),
          nullif(btrim(conversation.remote_jid), '')
        ) as remote_jid
      from public.whatsapp_messages as message
      join public.whatsapp_conversations as conversation
        on conversation.organization_id = message.organization_id
       and conversation.id = message.conversation_id
       and conversation.session_id = message.session_id
       and conversation.lead_id = message.lead_id
       and conversation.deleted_at is null
       and coalesce(conversation.is_group, false) = false
      join public.whatsapp_conversation_lead_bindings as binding
        on binding.organization_id = conversation.organization_id
       and binding.conversation_id = conversation.id
       and binding.session_id = conversation.session_id
       and binding.lead_id = conversation.lead_id
       and binding.active_to is null
       and binding.stale = false
      join public.whatsapp_sessions as session
        on session.organization_id = message.organization_id
       and session.id = message.session_id
       and session.provider = 'evolution_go'
      join public.leads as lead
        on lead.organization_id = message.organization_id
       and lead.id = message.lead_id
       and nullif(btrim(lead.whatsapp_avatar_storage_path), '') is null
      where message.organization_id = job.organization_id
        and message.lead_id = job.lead_id
        and (
          (
            job.attempts = 0
            and message.id = job.source_message_id
            -- A same-card relink rotates the binding row. Contact one remains
            -- valid only under the exact binding captured when it was queued.
            and binding.id = job.binding_id
          )
          or (
            message.id = job.last_contact_message_id
            and message.id is distinct from job.source_message_id
            and binding.id = job.last_contact_binding_id
            and (
              job.attempts > 0
              or (job.attempts = 0 and job.eligible_contact_count = 2)
            )
          )
        )
        and coalesce(
          nullif(btrim(message.remote_jid), ''),
          nullif(btrim(conversation.remote_jid), '')
        ) ~ '^[^[:space:]@]+@(s[.]whatsapp[.]net|lid)$'
      order by case when message.id = job.source_message_id then 0 else 1 end
      limit 1
    ) as contact
    join public.whatsapp_sessions as claim_session
      on claim_session.organization_id = contact.organization_id
     and claim_session.id = contact.session_id
     and claim_session.provider = 'evolution_go'
     and claim_session.status = 'connected'
     and coalesce(claim_session.is_active, true) = true
    where job.status = 'pending'
      and job.attempts < job.max_attempts
      and job.next_attempt_at <= now()
      and not exists (
        select 1
        from private.whatsapp_avatar_jobs as active
        where active.session_id = contact.session_id
          and active.status = 'processing'
      )
    order by
      job.next_attempt_at,
      job.created_at,
      job.id
    limit 1
    for update of job skip locked
  ), claimed as (
    update private.whatsapp_avatar_jobs as job
    set
      organization_id = candidate.organization_id,
      session_id = candidate.session_id,
      conversation_id = candidate.conversation_id,
      binding_id = candidate.binding_id,
      last_attempt_message_id = candidate.source_message_id,
      remote_jid = candidate.remote_jid,
      status = 'processing',
      attempts = candidate.claimed_attempts,
      locked_at = now(),
      lease_expires_at = now() + p_lease,
      locked_by = btrim(p_worker_id),
      lease_token = gen_random_uuid(),
      last_error = null,
      updated_at = now()
    from candidate
    where job.id = candidate.id
    returning job.*
  )
  select
    claimed.id,
    claimed.organization_id,
    claimed.lead_id,
    claimed.session_id,
    claimed.conversation_id,
    claimed.binding_id,
    claimed.last_attempt_message_id,
    claimed.remote_jid,
    claimed.attempts,
    claimed.lease_token
  from claimed;
end;
$_$;


