--
-- Name: FUNCTION claim_whatsapp_media_job(p_worker_id text, p_lease interval, p_max_concurrency integer, p_session_ids uuid[], p_all_sessions boolean); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.claim_whatsapp_media_job(p_worker_id text, p_lease interval, p_max_concurrency integer, p_session_ids uuid[], p_all_sessions boolean) IS 'Claims WhatsApp media with globally bounded slots, one active job per session, tenant fairness, rollout scoping, lease fencing, and delayed isolated recovery.';


--
-- Name: whatsapp_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.whatsapp_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    session_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    message_id uuid NOT NULL,
    client_message_id text NOT NULL,
    recipient_jid text NOT NULL,
    message_type text DEFAULT 'text'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    provider_message_id text,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 12 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    last_error text,
    sent_at timestamp with time zone,
    delivered_at timestamp with time zone,
    read_at timestamp with time zone,
    failed_at timestamp with time zone,
    dead_lettered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT whatsapp_outbox_attempts_check CHECK (((attempts >= 0) AND ((max_attempts >= 1) AND (max_attempts <= 100)))),
    CONSTRAINT whatsapp_outbox_client_message_id_check CHECK (((length(btrim(client_message_id)) >= 1) AND (length(btrim(client_message_id)) <= 512))),
    CONSTRAINT whatsapp_outbox_lock_check CHECK ((((status = 'processing'::text) AND (locked_at IS NOT NULL) AND (locked_by IS NOT NULL)) OR (status <> 'processing'::text))),
    CONSTRAINT whatsapp_outbox_recipient_jid_check CHECK (((length(btrim(recipient_jid)) >= 1) AND (length(btrim(recipient_jid)) <= 320))),
    CONSTRAINT whatsapp_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'retry'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'failed'::text, 'dead'::text])))
);


ALTER TABLE public.whatsapp_outbox OWNER TO postgres;

--
-- Name: TABLE whatsapp_outbox; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.whatsapp_outbox IS 'Backend-only durable WhatsApp delivery queue containing destination and payload data.';


--
-- Name: claim_whatsapp_outbox(text, integer, interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_whatsapp_outbox(p_worker_id text, p_limit integer DEFAULT 50, p_lease interval DEFAULT '00:05:00'::interval) RETURNS SETOF public.whatsapp_outbox
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if nullif(btrim(p_worker_id), '') is null then
    raise exception 'worker id is required';
  end if;

  update public.whatsapp_outbox as exhausted
  set status = 'dead',
      dead_lettered_at = coalesce(exhausted.dead_lettered_at, now()),
      locked_at = null,
      locked_by = null,
      last_error = coalesce(exhausted.last_error, 'retry_exhausted')
  where exhausted.attempts >= exhausted.max_attempts
    and (
      (exhausted.status in ('pending', 'retry') and exhausted.next_attempt_at <= now())
      or (exhausted.status = 'processing' and exhausted.locked_at < now() - p_lease)
    );

  return query
  with candidates as (
    select queued.id
    from public.whatsapp_outbox as queued
    where queued.attempts < queued.max_attempts
      and (
        (queued.status in ('pending', 'retry') and queued.next_attempt_at <= now())
        or (queued.status = 'processing' and queued.locked_at < now() - p_lease)
      )
    order by queued.next_attempt_at, queued.created_at, queued.id
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 50), 500))
  )
  update public.whatsapp_outbox as claimed
  set status = 'processing',
      attempts = claimed.attempts + 1,
      locked_at = now(),
      locked_by = btrim(p_worker_id),
      last_error = null
  from candidates
  where claimed.id = candidates.id
  returning claimed.*;
end;
$$;


ALTER FUNCTION private.claim_whatsapp_outbox(p_worker_id text, p_limit integer, p_lease interval) OWNER TO postgres;

--
-- Name: claim_whatsapp_sessions_for_supervision(text, integer, interval, interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_whatsapp_sessions_for_supervision(p_claim_token text, p_limit integer DEFAULT 50, p_minimum_age interval DEFAULT '00:01:00'::interval, p_lease interval DEFAULT '00:05:00'::interval) RETURNS TABLE(session_id uuid, organization_id uuid, claim_token text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
#variable_conflict use_column
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_claim_token text := pg_catalog.btrim(p_claim_token);
begin
  if v_claim_token is null or pg_catalog.length(v_claim_token) < 16 or pg_catalog.length(v_claim_token) > 256 then
    raise exception 'invalid WhatsApp supervisor claim token' using errcode = '22023';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception 'WhatsApp supervisor claim limit must be between 1 and 100' using errcode = '22023';
  end if;
  if p_minimum_age is null or p_minimum_age < interval '30 seconds' or p_minimum_age > interval '1 hour' then
    raise exception 'WhatsApp supervisor minimum age must be between 30 seconds and 1 hour' using errcode = '22023';
  end if;
  if p_lease is null or p_lease < interval '1 minute' or p_lease > interval '30 minutes' then
    raise exception 'WhatsApp supervisor lease must be between 1 and 30 minutes' using errcode = '22023';
  end if;

  -- Retire operational rows as soon as their source session leaves the
  -- supervision domain. Keeping tombstones would reserve a provider instance
  -- key forever and could make a legitimate replacement session fail every
  -- future claim on the global uniqueness fence.
  delete from private.whatsapp_session_supervisor_state as state
  where not exists (
    select 1
    from public.whatsapp_sessions as session
    where session.id = state.session_id
      and session.organization_id = state.organization_id
      and pg_catalog.lower(pg_catalog.btrim(coalesce(session.provider, ''))) = 'evolution_go'
      and coalesce(session.is_active, true) = true
      and pg_catalog.lower(pg_catalog.btrim(coalesce(session.status, ''))) not in ('deleted', 'disabled')
      and pg_catalog.lower(coalesce(session.advanced_settings->>'auto_reconnect_enabled', 'true')) <> 'false'
  );

  -- Register newly-created sessions without touching the user-facing session
  -- row. DO NOTHING is deliberate: a no-op DO UPDATE would still lock every
  -- existing state row and serialize otherwise independent claimers.
  insert into private.whatsapp_session_supervisor_state as state (
    session_id,
    organization_id,
    provider_instance_key,
    created_at,
    updated_at
  )
  select
    session.id,
    session.organization_id,
    coalesce(
      nullif(pg_catalog.btrim(session.advanced_settings->>'evolution_go_resolved_instance_key'), ''),
      nullif(pg_catalog.btrim(session.instance_id), ''),
      nullif(pg_catalog.btrim(session.instance_name), ''),
      'missing:' || session.id::text
    ),
    v_now,
    v_now
  from public.whatsapp_sessions session
  where pg_catalog.lower(pg_catalog.btrim(coalesce(session.provider, ''))) = 'evolution_go'
    and coalesce(session.is_active, true) = true
    and pg_catalog.lower(pg_catalog.btrim(coalesce(session.status, ''))) not in ('deleted', 'disabled')
    and pg_catalog.lower(coalesce(session.advanced_settings->>'auto_reconnect_enabled', 'true')) <> 'false'
  on conflict (session_id) do nothing;

  -- A recreate changes provider_instance_key and atomically invalidates every
  -- old lease/backoff before the replacement instance is inspected. This
  -- update locks only identities which actually changed.
  update private.whatsapp_session_supervisor_state state
  set organization_id = session.organization_id,
      provider_instance_key = coalesce(
        nullif(pg_catalog.btrim(session.advanced_settings->>'evolution_go_resolved_instance_key'), ''),
        nullif(pg_catalog.btrim(session.instance_id), ''),
        nullif(pg_catalog.btrim(session.instance_name), ''),
        'missing:' || session.id::text
      ),
      last_claimed_at = null,
      claim_token = null,
      lease_expires_at = null,
      probe_failure_count = 0,
      retry_at = null,
      last_error_code = null,
      last_provider_observed_at = null,
      last_provider_status = null,
      updated_at = v_now
  from public.whatsapp_sessions session
  where session.id = state.session_id
    and (
      state.organization_id is distinct from session.organization_id
      or state.provider_instance_key is distinct from coalesce(
        nullif(pg_catalog.btrim(session.advanced_settings->>'evolution_go_resolved_instance_key'), ''),
        nullif(pg_catalog.btrim(session.instance_id), ''),
        nullif(pg_catalog.btrim(session.instance_name), ''),
        'missing:' || session.id::text
      )
    );

  return query
  with eligible as materialized (
    select
      state.session_id,
      state.organization_id,
      state.last_claimed_at,
      row_number() over (
        partition by state.organization_id
        order by state.last_claimed_at asc nulls first, state.session_id asc
      ) as tenant_position
    from private.whatsapp_session_supervisor_state state
    join public.whatsapp_sessions session
      on session.id = state.session_id
     and session.organization_id = state.organization_id
    where pg_catalog.lower(pg_catalog.btrim(coalesce(session.provider, ''))) = 'evolution_go'
      and coalesce(session.is_active, true) = true
      and pg_catalog.lower(pg_catalog.btrim(coalesce(session.status, ''))) not in ('deleted', 'disabled')
      and pg_catalog.lower(coalesce(session.advanced_settings->>'auto_reconnect_enabled', 'true')) <> 'false'
      and (state.retry_at is null or state.retry_at <= v_now)
      and (state.lease_expires_at is null or state.lease_expires_at <= v_now)
      and (state.last_claimed_at is null or state.last_claimed_at <= v_now - p_minimum_age)
  ), candidates as (
    select state.session_id
    from private.whatsapp_session_supervisor_state state
    join eligible on eligible.session_id = state.session_id
    order by
      eligible.tenant_position asc,
      eligible.last_claimed_at asc nulls first,
      eligible.organization_id asc,
      eligible.session_id asc
    limit p_limit
    for update of state skip locked
  ), claimed as (
    update private.whatsapp_session_supervisor_state state
    set claim_token = v_claim_token,
        last_claimed_at = v_now,
        lease_expires_at = v_now + p_lease,
        updated_at = v_now
    from candidates
    where state.session_id = candidates.session_id
    returning state.session_id, state.organization_id, state.claim_token
  )
  select claimed.session_id, claimed.organization_id, claimed.claim_token
  from claimed;
end;
$$;


