--
-- Name: FUNCTION claim_whatsapp_sessions_for_supervision(p_claim_token text, p_limit integer, p_minimum_age interval, p_lease interval); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.claim_whatsapp_sessions_for_supervision(p_claim_token text, p_limit integer, p_minimum_age interval, p_lease interval) IS 'Atomically claims a fair, tenant-interleaved page of active Evolution Go sessions. Locks are held only for this statement; provider IO occurs after commit.';


--
-- Name: whatsapp_unlinked_media_gc; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.whatsapp_unlinked_media_gc (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    bucket_id text DEFAULT 'whatsapp-media'::text NOT NULL,
    object_path text NOT NULL,
    source_conversation_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    last_error text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT whatsapp_unlinked_media_gc_attempts_check CHECK (((attempts >= 0) AND (attempts <= 100))),
    CONSTRAINT whatsapp_unlinked_media_gc_bucket_id_check CHECK ((bucket_id = 'whatsapp-media'::text)),
    CONSTRAINT whatsapp_unlinked_media_gc_lease_check CHECK ((((status = 'processing'::text) AND (locked_at IS NOT NULL) AND (locked_by IS NOT NULL)) OR ((status <> 'processing'::text) AND (locked_at IS NULL) AND (locked_by IS NULL)))),
    CONSTRAINT whatsapp_unlinked_media_gc_path_check CHECK (((object_path ~~ (('orgs/'::text || (organization_id)::text) || '/%'::text)) AND ((length(object_path) >= 44) AND (length(object_path) <= 1024)) AND (POSITION(('..'::text) IN (object_path)) = 0) AND (POSITION(('\'::text) IN (object_path)) = 0))),
    CONSTRAINT whatsapp_unlinked_media_gc_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'retry'::text, 'completed'::text, 'failed'::text])))
);

ALTER TABLE ONLY private.whatsapp_unlinked_media_gc FORCE ROW LEVEL SECURITY;


ALTER TABLE private.whatsapp_unlinked_media_gc OWNER TO postgres;

--
-- Name: claim_whatsapp_unlinked_media_gc(text, integer, interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_whatsapp_unlinked_media_gc(p_worker_id text, p_limit integer DEFAULT 50, p_lease interval DEFAULT '00:05:00'::interval) RETURNS SETOF private.whatsapp_unlinked_media_gc
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if nullif(pg_catalog.btrim(p_worker_id), '') is null
     or p_lease <= interval '0 seconds' then
    raise exception using errcode = '22023',
      message = 'whatsapp_unlinked_media_gc_worker_invalid';
  end if;

  return query
  with candidates as (
    select gc.id
    from private.whatsapp_unlinked_media_gc as gc
    where (
      (gc.status in ('pending', 'retry') and gc.next_attempt_at <= pg_catalog.clock_timestamp())
      or (gc.status = 'processing' and gc.locked_at < pg_catalog.clock_timestamp() - p_lease)
    )
      and gc.attempts < 12
      and not exists (
        select 1
        from public.whatsapp_messages as message
        join public.whatsapp_conversations as conversation
          on conversation.id = message.conversation_id
         and conversation.organization_id = message.organization_id
        where message.organization_id = gc.organization_id
          and message.media_storage_path = gc.object_path
          and (
        conversation.retired_at is null
        or private.whatsapp_conversation_has_protected_history(conversation.id)
        or exists (
          select 1 from private.whatsapp_unlinked_history_links as link
          where link.conversation_id = conversation.id
            and link.organization_id = conversation.organization_id
        )
      )
      )
      and not exists (
        select 1
        from public.media_jobs as job
        join public.whatsapp_conversations as conversation
          on conversation.id = job.conversation_id
         and conversation.organization_id = job.organization_id
        where job.organization_id = gc.organization_id
          and (
            job.storage_path = gc.object_path
            or job.message_key->>'upload_intent_path' = gc.object_path
            or job.message_key->>'repair_storage_path' = gc.object_path
          )
          and (
        conversation.retired_at is null
        or private.whatsapp_conversation_has_protected_history(conversation.id)
        or exists (
          select 1 from private.whatsapp_unlinked_history_links as link
          where link.conversation_id = conversation.id
            and link.organization_id = conversation.organization_id
        )
      )
      )
      and not exists (
        select 1 from public.leads as lead
        where lead.organization_id = gc.organization_id
          and lead.whatsapp_avatar_storage_path = gc.object_path
      )
    order by gc.next_attempt_at, gc.created_at, gc.id
    for update of gc skip locked
    limit least(greatest(coalesce(p_limit, 50), 1), 500)
  )
  update private.whatsapp_unlinked_media_gc as gc
  set status = 'processing',
      attempts = gc.attempts + 1,
      locked_at = pg_catalog.clock_timestamp(),
      locked_by = p_worker_id,
      updated_at = pg_catalog.clock_timestamp()
  from candidates
  where gc.id = candidates.id
  returning gc.*;
end;
$$;


ALTER FUNCTION private.claim_whatsapp_unlinked_media_gc(p_worker_id text, p_limit integer, p_lease interval) OWNER TO postgres;

--
-- Name: whatsapp_webhook_inbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.whatsapp_webhook_inbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    session_id uuid NOT NULL,
    provider text DEFAULT 'evolution_go'::text NOT NULL,
    provider_instance_id text,
    event_key text NOT NULL,
    event_type text NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 12 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    last_error text,
    processed_at timestamp with time zone,
    dead_lettered_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '30 days'::interval) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    processing_lane text DEFAULT 'backlog'::text NOT NULL,
    provider_occurred_at timestamp with time zone,
    processing_epoch integer DEFAULT 0 NOT NULL,
    edge_execution_id uuid,
    edge_execution_state text,
    edge_execution_reserved_at timestamp with time zone,
    edge_execution_started_at timestamp with time zone,
    CONSTRAINT whatsapp_webhook_inbox_attempts_check CHECK (((attempts >= 0) AND ((max_attempts >= 1) AND (max_attempts <= 100)))),
    CONSTRAINT whatsapp_webhook_inbox_event_key_check CHECK (((length(btrim(event_key)) >= 1) AND (length(btrim(event_key)) <= 512))),
    CONSTRAINT whatsapp_webhook_inbox_event_type_check CHECK (((length(btrim(event_type)) >= 1) AND (length(btrim(event_type)) <= 160))),
    CONSTRAINT whatsapp_webhook_inbox_lock_check CHECK ((((status = 'processing'::text) AND (locked_at IS NOT NULL) AND (locked_by IS NOT NULL)) OR (status <> 'processing'::text))),
    CONSTRAINT whatsapp_webhook_inbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'retry'::text, 'processed'::text, 'dead'::text])))
);


ALTER TABLE public.whatsapp_webhook_inbox OWNER TO postgres;

--
-- Name: TABLE whatsapp_webhook_inbox; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.whatsapp_webhook_inbox IS 'Backend-only durable WhatsApp webhook queue containing raw provider payloads.';


--
-- Name: COLUMN whatsapp_webhook_inbox.processing_epoch; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_webhook_inbox.processing_epoch IS '0 is pre-cutover or retained delivery; 1 is the explicitly activated session generation.';


--
-- Name: COLUMN whatsapp_webhook_inbox.edge_execution_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_webhook_inbox.edge_execution_id IS 'Opaque Go-to-Edge execution token. A non-null token fences session cutover even after an HTTP timeout.';


--
-- Name: COLUMN whatsapp_webhook_inbox.edge_execution_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_webhook_inbox.edge_execution_state IS 'Reserved before HTTP; active only after Edge begins and before its last awaited effect. No clock-only expiry for active.';


--
-- Name: claim_whatsapp_webhook_inbox(text, integer, interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.claim_whatsapp_webhook_inbox(p_worker_id text, p_limit integer DEFAULT 50, p_lease interval DEFAULT '00:05:00'::interval) RETURNS SETOF public.whatsapp_webhook_inbox
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if nullif(btrim(p_worker_id), '') is null then
    raise exception 'worker id is required';
  end if;

  update public.whatsapp_webhook_inbox as exhausted
  set status = 'dead',
      dead_lettered_at = coalesce(exhausted.dead_lettered_at, now()),
      locked_at = null,
      locked_by = null,
      last_error = coalesce(exhausted.last_error, 'retry_exhausted')
  where exhausted.attempts >= exhausted.max_attempts
    and (
      (exhausted.status in ('pending', 'retry') and exhausted.next_attempt_at <= now())
      or (exhausted.status = 'processing' and exhausted.locked_at < now() - p_lease)
    );

  return query
  with candidates as (
    select inbox.id
    from public.whatsapp_webhook_inbox as inbox
    where inbox.attempts < inbox.max_attempts
      and (
        (inbox.status in ('pending', 'retry') and inbox.next_attempt_at <= now())
        or (inbox.status = 'processing' and inbox.locked_at < now() - p_lease)
      )
    order by inbox.next_attempt_at, inbox.created_at, inbox.id
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 50), 500))
  )
  update public.whatsapp_webhook_inbox as claimed
  set status = 'processing',
      attempts = claimed.attempts + 1,
      locked_at = now(),
      locked_by = btrim(p_worker_id),
      last_error = null
  from candidates
  where claimed.id = candidates.id
  returning claimed.*;
end;
$$;


ALTER FUNCTION private.claim_whatsapp_webhook_inbox(p_worker_id text, p_limit integer, p_lease interval) OWNER TO postgres;

--
-- Name: cleanup_orphan_round_robin_ticket_sequences(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cleanup_orphan_round_robin_ticket_sequences() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_sequence record;
  v_removed integer := 0;
begin
  for v_sequence in
    select relation.relname
    from pg_catalog.pg_class as relation
    join pg_catalog.pg_namespace as namespace
      on namespace.oid = relation.relnamespace
    where namespace.nspname = 'private'
      and relation.relkind = 'S'
      and relation.relname like 'lead_distribution_ticket_%'
      and relation.relname
        ~ '^lead_distribution_ticket_[0-9a-f]{32}$'
      and not exists (
        select 1
        from public.round_robins as queue
        where private.round_robin_ticket_sequence_name(queue.id)
          = relation.relname::name
      )
    order by relation.relname
    limit 100
  loop
    execute pg_catalog.format(
      'drop sequence if exists private.%I',
      v_sequence.relname
    );
    v_removed := v_removed + 1;
  end loop;

  return v_removed;
end;
$_$;


ALTER FUNCTION private.cleanup_orphan_round_robin_ticket_sequences() OWNER TO postgres;

--
-- Name: cleanup_public_ingress_rate_limits(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cleanup_public_ingress_rate_limits() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_removed integer;
begin
  with removed as (
    delete from private.public_ingress_rate_limits
    where updated_at < clock_timestamp() - interval '2 days'
    returning 1
  )
  select count(*)::integer
  into v_removed
  from removed;

  return v_removed;
end
$$;


