--
-- Name: cleanup_whatsapp_webhook_routing_provenance(integer, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cleanup_whatsapp_webhook_routing_provenance(p_limit integer DEFAULT 1000, p_before timestamp with time zone DEFAULT (clock_timestamp() - '90 days'::interval)) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 1000), 1), 10000);
  v_candidate public.whatsapp_webhook_routing_snapshots%rowtype;
  v_deleted bigint := 0;
begin
  if p_before is null or p_before > clock_timestamp() - interval '30 days' then
    raise exception using
      errcode = '22023',
      message = 'whatsapp_routing_provenance_retention_too_short';
  end if;

  for v_candidate in
    select routing_snapshot.*
    from public.whatsapp_webhook_routing_snapshots as routing_snapshot
    left join public.whatsapp_webhook_routing_outcomes as routing_outcome
      on routing_outcome.organization_id = routing_snapshot.organization_id
     and routing_outcome.session_id = routing_snapshot.session_id
     and routing_outcome.provider_message_id = routing_snapshot.provider_message_id
     and routing_outcome.ingress_sequence = routing_snapshot.ingress_sequence
    where routing_snapshot.created_at < p_before
      and (
        (routing_snapshot.binding_eligible = false)
        or routing_outcome.completed_at < p_before
      )
      and not exists (
        select 1
        from public.whatsapp_conversation_routing_heads as routing_head
        where routing_head.organization_id = routing_snapshot.organization_id
          and routing_head.session_id = routing_snapshot.session_id
          and routing_head.provider_message_id = routing_snapshot.provider_message_id
          and routing_head.ingress_sequence = routing_snapshot.ingress_sequence
      )
      and not exists (
        select 1
        from public.whatsapp_webhook_routing_snapshots as successor
        where successor.organization_id = routing_snapshot.organization_id
          and successor.session_id = routing_snapshot.session_id
          and successor.routing_key = routing_snapshot.routing_key
          and successor.predecessor_provider_message_id = routing_snapshot.provider_message_id
      )
      and not exists (
        select 1
        from public.whatsapp_webhook_inbox as inbox
        where inbox.organization_id = routing_snapshot.organization_id
          and inbox.session_id = routing_snapshot.session_id
          and exists (
            select 1
            from pg_catalog.jsonb_array_elements(
              case
                when pg_catalog.jsonb_typeof(
                  inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
                ) = 'array'
                  then inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
                else '[]'::jsonb
              end
            ) as inbox_route(snapshot)
            where inbox_route.snapshot->>'provider_message_id' =
              routing_snapshot.provider_message_id
          )
      )
      and not exists (
        select 1
        from public.whatsapp_conversation_lead_bindings as binding
        where binding.organization_id = routing_snapshot.organization_id
          and binding.session_id = routing_snapshot.session_id
          and binding.provider_message_id = routing_snapshot.provider_message_id
      )
      and not exists (
        select 1
        from public.whatsapp_messages as message
        where message.organization_id = routing_snapshot.organization_id
          and message.session_id = routing_snapshot.session_id
          and (
            message.provider_message_id = routing_snapshot.provider_message_id
            or (
              message.provider_message_id is null
              and message.message_id = routing_snapshot.provider_message_id
            )
          )
      )
      and not exists (
        select 1
        from public.lead_entry_events as entry
        where entry.organization_id = routing_snapshot.organization_id
          and entry.provider = 'whatsapp'
          and entry.provider_event_id =
            routing_snapshot.session_id::text || ':' || routing_snapshot.provider_message_id
      )
      and not exists (
        select 1
        from private.whatsapp_meta_creative_event_ledger as creative
        where creative.organization_id = routing_snapshot.organization_id
          and creative.whatsapp_session_id = routing_snapshot.session_id
          and creative.provider_message_id = routing_snapshot.provider_message_id
      )
    order by routing_snapshot.routing_key, routing_snapshot.ingress_sequence
    limit v_limit
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        v_candidate.organization_id::text || ':' ||
        v_candidate.session_id::text || ':' || v_candidate.routing_key,
        0
      )
    );

    delete from public.whatsapp_webhook_routing_snapshots as routing_snapshot
    where routing_snapshot.organization_id = v_candidate.organization_id
      and routing_snapshot.session_id = v_candidate.session_id
      and routing_snapshot.provider_message_id = v_candidate.provider_message_id
      and routing_snapshot.ingress_sequence = v_candidate.ingress_sequence
      and not exists (
        select 1
        from public.whatsapp_conversation_routing_heads as routing_head
        where routing_head.organization_id = routing_snapshot.organization_id
          and routing_head.session_id = routing_snapshot.session_id
          and routing_head.provider_message_id = routing_snapshot.provider_message_id
          and routing_head.ingress_sequence = routing_snapshot.ingress_sequence
      )
      and not exists (
        select 1
        from public.whatsapp_webhook_routing_snapshots as successor
        where successor.organization_id = routing_snapshot.organization_id
          and successor.session_id = routing_snapshot.session_id
          and successor.routing_key = routing_snapshot.routing_key
          and successor.predecessor_provider_message_id = routing_snapshot.provider_message_id
      )
      and not exists (
        select 1
        from public.whatsapp_webhook_inbox as inbox
        where inbox.organization_id = routing_snapshot.organization_id
          and inbox.session_id = routing_snapshot.session_id
          and exists (
            select 1
            from pg_catalog.jsonb_array_elements(
              case
                when pg_catalog.jsonb_typeof(
                  inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
                ) = 'array'
                  then inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
                else '[]'::jsonb
              end
            ) as inbox_route(snapshot)
            where inbox_route.snapshot->>'provider_message_id' =
              routing_snapshot.provider_message_id
          )
      )
      and not exists (
        select 1
        from public.whatsapp_conversation_lead_bindings as binding
        where binding.organization_id = routing_snapshot.organization_id
          and binding.session_id = routing_snapshot.session_id
          and binding.provider_message_id = routing_snapshot.provider_message_id
      )
      and not exists (
        select 1
        from public.whatsapp_messages as message
        where message.organization_id = routing_snapshot.organization_id
          and message.session_id = routing_snapshot.session_id
          and (
            message.provider_message_id = routing_snapshot.provider_message_id
            or (
              message.provider_message_id is null
              and message.message_id = routing_snapshot.provider_message_id
            )
          )
      )
      and not exists (
        select 1
        from public.lead_entry_events as entry
        where entry.organization_id = routing_snapshot.organization_id
          and entry.provider = 'whatsapp'
          and entry.provider_event_id =
            routing_snapshot.session_id::text || ':' || routing_snapshot.provider_message_id
      )
      and not exists (
        select 1
        from private.whatsapp_meta_creative_event_ledger as creative
        where creative.organization_id = routing_snapshot.organization_id
          and creative.whatsapp_session_id = routing_snapshot.session_id
          and creative.provider_message_id = routing_snapshot.provider_message_id
      );

    if found then
      v_deleted := v_deleted + 1;
    end if;
  end loop;

  return v_deleted;
end;
$$;


ALTER FUNCTION private.cleanup_whatsapp_webhook_routing_provenance(p_limit integer, p_before timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION cleanup_whatsapp_webhook_routing_provenance(p_limit integer, p_before timestamp with time zone); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.cleanup_whatsapp_webhook_routing_provenance(p_limit integer, p_before timestamp with time zone) IS 'Conservative route-locked retention: removes only old, completed or non-binding provenance with no head, successor, inbox replay, message, binding, entry event, or creative ledger reference.';


--
-- Name: clear_billing_card_recurrence_credential_on_failure(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.clear_billing_card_recurrence_credential_on_failure() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text := upper(btrim(coalesce(new.status, '')));
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  if private.billing_payment_checkout_is_paid(v_status)
     and upper(btrim(coalesce(new.billing_type, ''))) = 'CREDIT_CARD' then
    -- Card data can be sealed before an asynchronous payment settles. The
    -- webhook transaction only makes the durable job visible; no provider
    -- request or decryption happens on the webhook path.
    update private.billing_card_recurrence_provisions as provision
    set
      status = case
        when provision.status = 'failed' then 'prepared'
        else provision.status
      end,
      job_action = 'create',
      job_status = 'pending',
      job_attempts = 0,
      job_next_attempt_at = clock_timestamp(),
      job_locked_at = null,
      job_lock_expires_at = null,
      job_locked_by = null,
      job_lease_id = null,
      job_dead_lettered_at = null,
      job_last_error_code = null,
      updated_at = clock_timestamp()
    where provision.payment_id = new.id
      and provision.provider_payment_id = new.asaas_payment_id
      and provision.status in ('prepared', 'failed')
      and provision.provider_card_credential is not null;
  elsif private.billing_payment_checkout_is_reversal(v_status) then
    -- A completed future subscription is a provider mutation target. Queue
    -- its exact cancellation tuple and let the worker validate GET + DELETE.
    update private.billing_card_recurrence_provisions as provision
    set
      job_action = 'cancel',
      job_status = case
        when provision.job_action = 'cancel'
          and provision.job_status = 'processing'
        then 'processing'
        else 'pending'
      end,
      job_attempts = case
        when provision.job_action = 'cancel' then provision.job_attempts
        else 0
      end,
      job_next_attempt_at = least(
        provision.job_next_attempt_at,
        clock_timestamp()
      ),
      job_locked_at = case
        when provision.job_action = 'cancel'
          and provision.job_status = 'processing'
        then provision.job_locked_at
        else null
      end,
      job_lock_expires_at = case
        when provision.job_action = 'cancel'
          and provision.job_status = 'processing'
        then provision.job_lock_expires_at
        else null
      end,
      job_locked_by = case
        when provision.job_action = 'cancel'
          and provision.job_status = 'processing'
        then provision.job_locked_by
        else null
      end,
      job_lease_id = case
        when provision.job_action = 'cancel'
          and provision.job_status = 'processing'
        then provision.job_lease_id
        else null
      end,
      job_dead_lettered_at = null,
      job_last_error_code = null,
      updated_at = clock_timestamp()
    where provision.payment_id = new.id
      and provision.provider_payment_id = new.asaas_payment_id
      and provision.status = 'completed';

    -- No subscription exists for a prepared/failed job. The same is provably
    -- true when a worker only claimed the create job but has not crossed the
    -- durable provider-request marker. Closing that lease atomically makes a
    -- concurrent mark CAS fail, so no subscription is created after reversal.
    update private.billing_card_recurrence_provisions as provision
    set
      status = 'failed',
      provider_card_credential = null,
      card_last4 = null,
      credential_attempt_lease_id = null,
      capture_request_started_at = null,
      capture_attempt_lease_id = null,
      capture_manual_review_at = null,
      lease_id = null,
      lease_expires_at = null,
      failed_at = coalesce(provision.failed_at, clock_timestamp()),
      last_error = 'payment_not_paid_terminal',
      job_status = 'cancelled',
      job_locked_at = null,
      job_lock_expires_at = null,
      job_locked_by = null,
      job_lease_id = null,
      job_last_error_code = 'payment_not_paid_terminal',
      updated_at = clock_timestamp()
    where provision.payment_id = new.id
      and provision.provider_payment_id = new.asaas_payment_id
      and (
        provision.status in ('prepared', 'failed')
        or (
          provision.status = 'creating'
          and provision.provider_request_started_at is null
        )
      );
  elsif private.billing_payment_checkout_is_terminal(v_status)
     or v_status = 'CREDIT_CARD_CAPTURE_REFUSED' then
    -- A sealed credential belongs to exactly one provider charge attempt.
    -- Clear it on refusal/terminal non-payment before any later retry can use
    -- stale card authorization. Creating/completed rows already consumed it.
    update private.billing_card_recurrence_provisions as provision
    set
      status = 'failed',
      provider_card_credential = null,
      card_last4 = null,
      credential_attempt_lease_id = null,
      capture_request_started_at = null,
      capture_attempt_lease_id = null,
      capture_manual_review_at = null,
      lease_id = null,
      lease_expires_at = null,
      failed_at = coalesce(provision.failed_at, clock_timestamp()),
      last_error = 'payment_not_paid_terminal',
      job_status = 'cancelled',
      job_locked_at = null,
      job_lock_expires_at = null,
      job_locked_by = null,
      job_lease_id = null,
      job_last_error_code = 'payment_not_paid_terminal',
      updated_at = clock_timestamp()
    where provision.payment_id = new.id
      and provision.provider_payment_id = new.asaas_payment_id
      and (
        provision.status in ('prepared', 'failed')
        or (
          provision.status = 'creating'
          and provision.provider_request_started_at is null
        )
      );
  end if;

  return new;
end
$$;


ALTER FUNCTION private.clear_billing_card_recurrence_credential_on_failure() OWNER TO postgres;

--
-- Name: clear_membership_grants_on_lifecycle_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.clear_membership_grants_on_lifecycle_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    delete from public.user_organization_roles as assignment
    where assignment.user_id = new.user_id
      and (
        assignment.organization_id = new.organization_id
        or exists (
          select 1 from public.organization_roles as legacy_role
          where legacy_role.id = assignment.organization_role_id
            and legacy_role.organization_id = new.organization_id
        )
      );
    delete from public.user_permission_overrides as override
    where override.organization_id = new.organization_id
      and override.user_id = new.user_id;
    return new;
  end if;

  if tg_op = 'DELETE' then
    delete from public.user_organization_roles as assignment
    where assignment.user_id = old.user_id
      and (
        assignment.organization_id = old.organization_id
        or exists (
          select 1 from public.organization_roles as legacy_role
          where legacy_role.id = assignment.organization_role_id
            and legacy_role.organization_id = old.organization_id
        )
      );
    delete from public.user_permission_overrides as override
    where override.organization_id = old.organization_id
      and override.user_id = old.user_id;
    return old;
  end if;

  if old.organization_id is distinct from new.organization_id
     or old.user_id is distinct from new.user_id then
    delete from public.user_organization_roles as assignment
    where assignment.user_id = old.user_id
      and (
        assignment.organization_id = old.organization_id
        or exists (
          select 1 from public.organization_roles as legacy_role
          where legacy_role.id = assignment.organization_role_id
            and legacy_role.organization_id = old.organization_id
        )
      );
    delete from public.user_permission_overrides as override
    where override.organization_id = old.organization_id
      and override.user_id = old.user_id;
  elsif (old.deleted_at is null) = (new.deleted_at is null) then
    return new;
  end if;

  delete from public.user_organization_roles as assignment
  where assignment.user_id = new.user_id
    and (
      assignment.organization_id = new.organization_id
      or exists (
        select 1 from public.organization_roles as legacy_role
        where legacy_role.id = assignment.organization_role_id
          and legacy_role.organization_id = new.organization_id
      )
    );
  delete from public.user_permission_overrides as override
  where override.organization_id = new.organization_id
    and override.user_id = new.user_id;
  return new;
end;
$$;


ALTER FUNCTION private.clear_membership_grants_on_lifecycle_change() OWNER TO postgres;

--
-- Name: clear_removed_subscription_after_late_payment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.clear_removed_subscription_after_late_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_subscription_id text;
begin
  if new.billing_intent_id is null
     or not private.billing_payment_checkout_is_paid(new.status) then
    return null;
  end if;

  select cancellation.provider_subscription_id
  into v_subscription_id
  from private.billing_subscription_checkout_cancellations as cancellation
  where cancellation.intent_id = new.billing_intent_id
    and cancellation.organization_id = new.organization_id
    and (
      cancellation.provider_payment_id = new.asaas_payment_id
      or (
        cancellation.provider_payment_id is null
        and cancellation.provider_subscription_id = new.asaas_subscription_id
      )
    )
    and cancellation.final_outcome = 'paid_without_recurrence'
    and cancellation.needs_payment_method_update
    and cancellation.provider_deleted_at is not null;
  if not found then
    return null;
  end if;

  update public.organizations
  set asaas_subscription_id = null, updated_at = now()
  where id = new.organization_id
    and asaas_subscription_id = v_subscription_id;

  update public.subscriptions
  set
    provider_subscription_id = null,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'recurrence', jsonb_build_object(
        'status', 'provider_subscription_removed',
        'needs_payment_method_update', true,
        'billing_intent_id', new.billing_intent_id
      )
    ),
    updated_at = now()
  where organization_id = new.organization_id
    and provider_subscription_id = v_subscription_id;

  return null;
end
$$;


ALTER FUNCTION private.clear_removed_subscription_after_late_payment() OWNER TO postgres;

--
-- Name: clear_whatsapp_notification_sender_after_admin_loss(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.clear_whatsapp_notification_sender_after_admin_loss() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_organization_id uuid;
  target_user_id uuid;
begin
  if tg_op = 'DELETE' then
    target_organization_id := old.organization_id;
    target_user_id := old.user_id;
  else
    target_organization_id := new.organization_id;
    target_user_id := new.user_id;
  end if;

  if private.is_whatsapp_notification_admin(
    target_organization_id,
    target_user_id
  ) then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  update public.whatsapp_sessions
  set is_notification_session = false,
      updated_at = now()
  where organization_id = target_organization_id
    and owner_user_id = target_user_id
    and is_notification_session = true;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.clear_whatsapp_notification_sender_after_admin_loss() OWNER TO postgres;

--
-- Name: close_whatsapp_bindings_before_lead_delete(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.close_whatsapp_bindings_before_lead_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_closed_at timestamptz := clock_timestamp();
begin
  update public.whatsapp_conversation_lead_bindings as binding
  set active_to = greatest(
    v_closed_at,
    binding.active_from + interval '1 microsecond'
  )
  where binding.lead_id = old.id
    and binding.active_to is null;

  return old;
end;
$$;


ALTER FUNCTION private.close_whatsapp_bindings_before_lead_delete() OWNER TO postgres;

--
-- Name: complete_billing_card_recurrence_locked(uuid, text, uuid, jsonb, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.complete_billing_card_recurrence_locked(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_subscription jsonb, p_require_lease boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_subscription_id text;
  v_customer_id text;
  v_external_reference text;
  v_value_text text;
  v_amount numeric;
  v_cycle text;
  v_expected_cycle text;
  v_next_due_date_text text;
  v_next_due_date date;
  v_billing_type text;
  v_provider_status text;
  v_payment public.asaas_payments%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_intent private.billing_checkout_intents%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_subscription_count integer;
  v_subscription_row_id uuid;
  v_snapshot jsonb;
  v_now timestamptz := clock_timestamp();
  v_payment_reversed boolean := false;
begin
  if p_payment_id is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255
     or p_subscription is null
     or jsonb_typeof(p_subscription) <> 'object'
     or (p_require_lease and p_lease_id is null) then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  v_subscription_id := nullif(btrim(coalesce(p_subscription ->> 'id', '')), '');
  v_customer_id := nullif(btrim(coalesce(p_subscription ->> 'customer', '')), '');
  v_external_reference := p_subscription ->> 'externalReference';
  v_value_text := nullif(btrim(coalesce(p_subscription ->> 'value', '')), '');
  v_cycle := upper(nullif(btrim(coalesce(p_subscription ->> 'cycle', '')), ''));
  v_next_due_date_text := nullif(
    btrim(coalesce(p_subscription ->> 'nextDueDate', '')),
    ''
  );
  v_provider_status := upper(nullif(
    btrim(coalesce(p_subscription ->> 'status', '')),
    ''
  ));
  v_billing_type := upper(nullif(
    btrim(coalesce(p_subscription ->> 'billingType', '')),
    ''
  ));

  if v_subscription_id is null
     or v_customer_id is null
     or v_external_reference is null
     or v_value_text is null
     or v_cycle is null
     or v_next_due_date_text is null
     or char_length(v_subscription_id) > 255
     or char_length(v_customer_id) > 255
     or char_length(v_external_reference) > 160
     or v_value_text !~ '^[0-9]+([.][0-9]{1,2})?$'
     or v_next_due_date_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or lower(coalesce(p_subscription ->> 'deleted', 'false')) = 'true'
     or v_billing_type is distinct from 'CREDIT_CARD'
     or v_provider_status is distinct from 'ACTIVE' then
    return jsonb_build_object('outcome', 'invalid_subscription_snapshot');
  end if;

  begin
    v_amount := v_value_text::numeric;
    v_next_due_date := v_next_due_date_text::date;
  exception
    when invalid_text_representation or datetime_field_overflow then
      return jsonb_build_object('outcome', 'invalid_subscription_snapshot');
  end;

  -- Every billing writer takes the shared provider advisory locks before any
  -- row lock. private.lock_asaas_billing_resources uses
  -- pg_catalog.pg_advisory_xact_lock for both payment and subscription keys.
  perform private.lock_asaas_billing_resources(
    v_provider_payment_id,
    v_subscription_id
  );

  -- The later organization lock serializes the single public subscription row
  -- for this tenant.
  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  v_payment_reversed := private.billing_payment_checkout_is_reversal(
    v_payment.status
  );
  if not private.billing_payment_checkout_is_paid(v_payment.status)
     and not v_payment_reversed then
    return jsonb_build_object(
      'outcome', 'payment_not_paid',
      'payment_status', upper(btrim(coalesce(v_payment.status, '')))
    );
  end if;

  -- This is the paid one-off invoice. Its provider payment must never be
  -- rewritten as if it belonged to the newly-created future subscription.
  if v_payment.asaas_subscription_id is not null then
    return jsonb_build_object('outcome', 'payment_already_recurring');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
    and provision.provider_payment_id = v_payment.asaas_payment_id
    and provision.organization_id = v_payment.organization_id
    and provision.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  v_expected_cycle := case v_provision.billing_period_months
    when 1 then 'MONTHLY'
    when 6 then 'SEMIANNUALLY'
    when 12 then 'YEARLY'
    else null
  end;

  if v_external_reference is distinct from v_provision.external_reference
     or v_customer_id is distinct from v_provision.provider_customer_id
     or abs(v_amount - v_provision.amount) > 0.01
     or v_cycle is distinct from v_expected_cycle
     or v_next_due_date is distinct from v_provision.next_due_date then
    return jsonb_build_object('outcome', 'immutable_tuple_mismatch');
  end if;

  if v_provision.status = 'completed' then
    if v_provision.provider_subscription_id is distinct from v_subscription_id then
      return jsonb_build_object('outcome', 'provider_subscription_conflict');
    end if;

    return jsonb_build_object(
      'outcome', 'already_completed',
      'subscription_id', v_provision.provider_subscription_id
    );
  end if;

  if p_require_lease and (
    v_provision.status <> 'creating'
    or v_provision.lease_id is distinct from p_lease_id
  ) then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  if exists (
    select 1
    from private.billing_card_recurrence_provisions as other_provision
    where other_provision.provider_subscription_id = v_subscription_id
      and other_provision.payment_id <> v_provision.payment_id
  ) or exists (
    select 1
    from private.billing_checkout_intents as other_intent
    where other_intent.provider_subscription_id = v_subscription_id
      and other_intent.id <> v_provision.billing_intent_id
  ) or exists (
    select 1
    from public.organizations as other_organization
    where other_organization.asaas_subscription_id = v_subscription_id
      and other_organization.id <> v_provision.organization_id
  ) or exists (
    select 1
    from public.subscriptions as other_subscription
    where other_subscription.provider_subscription_id = v_subscription_id
      and other_subscription.organization_id <> v_provision.organization_id
  ) then
    return jsonb_build_object('outcome', 'provider_subscription_conflict');
  end if;

  select intent.*
  into v_intent
  from private.billing_checkout_intents as intent
  where intent.id = v_provision.billing_intent_id
    and intent.organization_id = v_provision.organization_id
  for update;

  if not found
     or v_intent.provider_payment_id is distinct from v_provision.provider_payment_id
     or v_intent.provider_customer_id is distinct from v_provision.provider_customer_id
     or v_intent.pending_plan_id is distinct from v_provision.plan_id
     or v_intent.billing_period_months is distinct from v_provision.billing_period_months
     or abs(v_intent.amount - v_provision.amount) > 0.01 then
    return jsonb_build_object('outcome', 'immutable_tuple_mismatch');
  end if;

  if v_intent.provider_subscription_id is not null
     and v_intent.provider_subscription_id <> v_subscription_id then
    return jsonb_build_object('outcome', 'provider_subscription_conflict');
  end if;

  select organization_row.*
  into v_org
  from public.organizations as organization_row
  where organization_row.id = v_provision.organization_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;

  if not (
    v_org.plan_id = v_provision.plan_id
    or v_org.pending_plan_id = v_provision.plan_id
  ) then
    return jsonb_build_object('outcome', 'organization_plan_mismatch');
  end if;

  if v_org.asaas_customer_id is not null
     and v_org.asaas_customer_id <> v_provision.provider_customer_id then
    return jsonb_build_object('outcome', 'organization_customer_mismatch');
  end if;

  if v_org.asaas_subscription_id is not null
     and v_org.asaas_subscription_id <> v_subscription_id then
    return jsonb_build_object('outcome', 'provider_subscription_conflict');
  end if;

  -- The organization row above serializes creation/update of its public
  -- subscription. Existing duplicate rows are considered corrupt and fail
  -- closed instead of being updated en masse.
  perform subscription_row.id
  from public.subscriptions as subscription_row
  where subscription_row.organization_id = v_provision.organization_id
  for update;

  select count(*)
  into v_subscription_count
  from public.subscriptions as subscription_row
  where subscription_row.organization_id = v_provision.organization_id;

  if v_subscription_count > 1 then
    return jsonb_build_object('outcome', 'subscription_row_ambiguous');
  end if;

  if v_subscription_count = 1 then
    select subscription_row.id
    into v_subscription_row_id
    from public.subscriptions as subscription_row
    where subscription_row.organization_id = v_provision.organization_id;

    select subscription_row.*
    into v_subscription
    from public.subscriptions as subscription_row
    where subscription_row.id = v_subscription_row_id;

    if (v_subscription.plan_id is not null and v_subscription.plan_id <> v_provision.plan_id)
       or (
         v_subscription.provider_customer_id is not null
         and v_subscription.provider_customer_id <> v_provision.provider_customer_id
       )
       or (
         v_subscription.provider_subscription_id is not null
         and v_subscription.provider_subscription_id <> v_subscription_id
       ) then
      return jsonb_build_object('outcome', 'subscription_row_mismatch');
    end if;
  end if;

  -- Store only the fields needed to prove the immutable tuple. Never persist
  -- a card number, CVV, provider credit-card token or raw provider payload.
  v_snapshot := jsonb_build_object(
    'id', v_subscription_id,
    'customer', v_customer_id,
    'externalReference', v_external_reference,
    'value', v_amount,
    'cycle', v_cycle,
    'nextDueDate', v_next_due_date,
    'billingType', v_billing_type,
    'status', v_provider_status
  );

  update private.billing_checkout_intents
  set
    provider_subscription_id = v_subscription_id,
    provider_response = coalesce(provider_response, '{}'::jsonb)
      || jsonb_build_object('card_recurrence', v_snapshot),
    updated_at = v_now
  where id = v_intent.id;

  -- Do not change subscription_status here. In particular, an active account
  -- remains active; payment confirmation remains the sole activation path.
  update public.organizations
  set
    asaas_customer_id = coalesce(asaas_customer_id, v_provision.provider_customer_id),
    asaas_subscription_id = v_subscription_id,
    subscription_billing_period_months = v_provision.billing_period_months,
    next_billing_date = v_provision.next_due_date,
    updated_at = v_now
  where id = v_provision.organization_id;

  if v_subscription_count = 0 then
    insert into public.subscriptions (
      organization_id,
      plan_id,
      status,
      provider,
      provider_customer_id,
      provider_subscription_id,
      billing_period_months,
      current_period_end,
      metadata,
      created_at,
      updated_at
    )
    values (
      v_provision.organization_id,
      v_provision.plan_id,
      case
        when v_org.subscription_status in (
          'trial',
          'pending_payment',
          'active',
          'blocked',
          'overdue',
          'past_due',
          'suspended',
          'cancelled'
        ) then v_org.subscription_status
        else 'active'
      end,
      'asaas',
      v_provision.provider_customer_id,
      v_subscription_id,
      v_provision.billing_period_months,
      v_provision.next_due_date::timestamp at time zone 'UTC',
      jsonb_build_object('card_recurrence', v_snapshot),
      v_now,
      v_now
    );
  else
    update public.subscriptions
    set
      plan_id = coalesce(plan_id, v_provision.plan_id),
      provider = 'asaas',
      provider_customer_id = coalesce(
        provider_customer_id,
        v_provision.provider_customer_id
      ),
      provider_subscription_id = v_subscription_id,
      billing_period_months = v_provision.billing_period_months,
      current_period_end = v_provision.next_due_date::timestamp at time zone 'UTC',
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('card_recurrence', v_snapshot),
      updated_at = v_now
    where id = v_subscription_row_id;
  end if;

  update private.billing_card_recurrence_provisions
  set
    status = 'completed',
    provider_subscription_id = v_subscription_id,
    provider_subscription_snapshot = v_snapshot,
    provider_card_credential = null,
    card_last4 = null,
    lease_id = null,
    lease_expires_at = null,
    completed_at = coalesce(completed_at, v_now),
    recovering_at = null,
    failed_at = null,
    last_error = null,
    job_action = case
      when v_payment_reversed then 'cancel'
      else 'create'
    end,
    job_status = case
      when v_payment_reversed then 'pending'
      else 'succeeded'
    end,
    job_attempts = case
      when v_payment_reversed then 0
      else job_attempts
    end,
    job_next_attempt_at = case
      when v_payment_reversed then v_now
      else job_next_attempt_at
    end,
    job_locked_at = null,
    job_lock_expires_at = null,
    job_locked_by = null,
    job_lease_id = null,
    job_dead_lettered_at = null,
    job_last_error_code = null,
    updated_at = v_now
  where payment_id = v_provision.payment_id;

  insert into public.subscription_logs (
    organization_id,
    event_type,
    status,
    metadata
  )
  values (
    v_provision.organization_id,
    'billing_card_recurrence_linked',
    coalesce(v_org.subscription_status, 'logged'),
    jsonb_build_object(
      'payment_id', v_provision.payment_id,
      'billing_intent_id', v_provision.billing_intent_id,
      'plan_id', v_provision.plan_id,
      'billing_period_months', v_provision.billing_period_months,
      'amount', v_provision.amount,
      'next_due_date', v_provision.next_due_date,
      'external_reference', v_provision.external_reference,
      'provider_subscription_id', v_subscription_id
    )
  );

  return jsonb_build_object(
    'outcome', 'completed',
    'payment_id', v_provision.payment_id,
    'subscription_id', v_subscription_id,
    'next_due_date', v_provision.next_due_date,
    'cancellation_queued', v_payment_reversed
  );
exception
  when unique_violation then
    return jsonb_build_object('outcome', 'provider_subscription_conflict');
end
$_$;


ALTER FUNCTION private.complete_billing_card_recurrence_locked(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_subscription jsonb, p_require_lease boolean) OWNER TO postgres;

--
-- Name: complete_notification_delivery(uuid, uuid, text, text, text, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.complete_notification_delivery(p_delivery_id uuid, p_lease_token uuid, p_status text, p_provider text DEFAULT NULL::text, p_provider_message_id text DEFAULT NULL::text, p_provider_status text DEFAULT NULL::text, p_attempt_metadata jsonb DEFAULT '{}'::jsonb, p_occurred_at timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text := lower(btrim(coalesce(p_status, '')));
  v_occurred_at timestamptz := coalesce(p_occurred_at, now());
  v_delivery private.notification_deliveries%rowtype;
begin
  if p_delivery_id is null
     or p_lease_token is null
     or v_status not in (
       'accepted', 'delivered', 'cancelled', 'permanent_failed', 'dead_letter'
     )
     or jsonb_typeof(coalesce(p_attempt_metadata, '{}'::jsonb)) <> 'object'
     or char_length(coalesce(p_provider, '')) > 100
     or char_length(coalesce(p_provider_message_id, '')) > 500
     or char_length(coalesce(p_provider_status, '')) > 255
     or v_occurred_at > now() + interval '5 minutes' then
    return false;
  end if;

  update private.notification_deliveries as delivery
  set status = v_status,
      next_attempt_at = null,
      lease_token = null,
      leased_by = null,
      lease_expires_at = null,
      dependency_key = null,
      provider = coalesce(nullif(btrim(p_provider), ''), delivery.provider),
      provider_message_id = coalesce(
        nullif(btrim(p_provider_message_id), ''),
        delivery.provider_message_id
      ),
      provider_status = coalesce(
        nullif(btrim(p_provider_status), ''),
        delivery.provider_status
      ),
      accepted_at = case
        when v_status in ('accepted', 'delivered')
          then coalesce(delivery.accepted_at, v_occurred_at)
        else delivery.accepted_at
      end,
      delivered_at = case
        when v_status = 'delivered'
          then coalesce(delivery.delivered_at, v_occurred_at)
        else delivery.delivered_at
      end,
      blocked_at = null,
      terminal_at = case
        when v_status in ('delivered', 'cancelled', 'permanent_failed', 'dead_letter')
          then v_occurred_at
        else null
      end,
      last_error_code = case
        when v_status in ('accepted', 'delivered') then null
        else coalesce(
          nullif(left(btrim(coalesce(p_attempt_metadata ->> 'error_code', '')), 255), ''),
          delivery.last_error_code,
          'delivery_' || v_status
        )
      end,
      last_error_message = case
        when v_status in ('accepted', 'delivered') then null
        else coalesce(
          nullif(left(btrim(coalesce(p_attempt_metadata ->> 'error_message', '')), 2000), ''),
          delivery.last_error_message
        )
      end,
      last_error_at = case
        when v_status in ('accepted', 'delivered') then null
        else v_occurred_at
      end,
      metadata = delivery.metadata || coalesce(p_attempt_metadata, '{}'::jsonb),
      updated_at = now()
  where delivery.id = p_delivery_id
    and delivery.status = 'sending'
    and delivery.lease_token = p_lease_token
  returning delivery.* into v_delivery;

  if not found then
    return false;
  end if;

  update private.notification_delivery_attempts as attempt
  set outcome = v_status,
      provider = v_delivery.provider,
      provider_message_id = v_delivery.provider_message_id,
      provider_status = v_delivery.provider_status,
      completed_at = v_occurred_at,
      error_code = case
        when v_status in ('accepted', 'delivered') then null
        else coalesce(
          nullif(left(btrim(coalesce(p_attempt_metadata ->> 'error_code', '')), 255), ''),
          'delivery_' || v_status
        )
      end,
      error_message = case
        when v_status in ('accepted', 'delivered') then null
        else nullif(left(btrim(coalesce(p_attempt_metadata ->> 'error_message', '')), 2000), '')
      end,
      metadata = attempt.metadata || coalesce(p_attempt_metadata, '{}'::jsonb)
  where attempt.delivery_id = p_delivery_id
    and attempt.event_type = 'send_attempt'
    and attempt.lease_token = p_lease_token
    and attempt.outcome = 'sending';

  return true;
end
$$;


ALTER FUNCTION private.complete_notification_delivery(p_delivery_id uuid, p_lease_token uuid, p_status text, p_provider text, p_provider_message_id text, p_provider_status text, p_attempt_metadata jsonb, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: complete_property_channel_publication_job(uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.complete_property_channel_publication_job(p_job_id uuid, p_worker_id text, p_lease_token uuid, p_completed_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  with completed as (
    update public.property_channel_publication_jobs
    set status = 'succeeded',
        locked_at = null,
        locked_by = null,
        lease_token = null,
        last_error_code = null,
        last_error_message = null,
        completed_at = coalesce(p_completed_at, clock_timestamp()),
        dead_lettered_at = null,
        updated_at = clock_timestamp()
    where id = p_job_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
      and lease_token = p_lease_token
    returning id
  )
  select exists(select 1 from completed);
$$;


ALTER FUNCTION private.complete_property_channel_publication_job(p_job_id uuid, p_worker_id text, p_lease_token uuid, p_completed_at timestamp with time zone) OWNER TO postgres;

--
-- Name: complete_whatsapp_unlinked_media_gc(uuid, text, boolean, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.complete_whatsapp_unlinked_media_gc(p_id uuid, p_worker_id text, p_deleted boolean, p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_updated boolean := false;
begin
  if p_id is null or nullif(pg_catalog.btrim(p_worker_id), '') is null
     or p_deleted is null then
    raise exception using errcode = '22023',
      message = 'whatsapp_unlinked_media_gc_result_invalid';
  end if;

  update private.whatsapp_unlinked_media_gc as gc
  set status = case
        when p_deleted then 'completed'
        when p_error = 'live_reference' then 'pending'
        when p_error = 'invalid_path' then 'failed'
        when gc.attempts >= 12 then 'failed'
        else 'retry'
      end,
      next_attempt_at = case
        when p_deleted then gc.next_attempt_at
        when p_error = 'live_reference' then pg_catalog.clock_timestamp() + interval '24 hours'
        else pg_catalog.clock_timestamp()
          + pg_catalog.make_interval(secs => least(3600, 30 * gc.attempts * gc.attempts))
      end,
      attempts = case
        when p_error = 'live_reference' then greatest(gc.attempts - 1, 0)
        else gc.attempts
      end,
      locked_at = null,
      locked_by = null,
      completed_at = case when p_deleted then pg_catalog.clock_timestamp() else null end,
      last_error = case when p_deleted then null else left(coalesce(p_error, 'storage_delete_failed'), 512) end,
      updated_at = pg_catalog.clock_timestamp()
  where gc.id = p_id
    and gc.status = 'processing'
    and gc.locked_by = p_worker_id
  returning true into v_updated;

  return coalesce(v_updated, false);
end;
$$;


ALTER FUNCTION private.complete_whatsapp_unlinked_media_gc(p_id uuid, p_worker_id text, p_deleted boolean, p_error text) OWNER TO postgres;

--
-- Name: complete_whatsapp_webhook_event(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.complete_whatsapp_webhook_event(p_event_id uuid, p_worker_id text) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
  with completed as (
    update public.whatsapp_webhook_inbox
    set status = 'processed',
        processed_at = now(),
        locked_at = null,
        locked_by = null,
        last_error = null
    where id = p_event_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
    returning id
  )
  select exists(select 1 from completed);
$$;


ALTER FUNCTION private.complete_whatsapp_webhook_event(p_event_id uuid, p_worker_id text) OWNER TO postgres;

--
-- Name: confirm_billing_checkout_from_payment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.confirm_billing_checkout_from_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_intent private.billing_checkout_intents%rowtype;
  v_intent_found boolean := false;
  v_organization_cursor timestamptz;
  v_organization_customer_id text;
  v_organization_subscription_id text;
  v_payment_cursor timestamptz := greatest(
    new.last_webhook_event_at,
    new.last_provider_observed_at
  );
begin
  if v_payment_cursor is null then
    return null;
  end if;

  perform private.lock_asaas_billing_resources(
    new.asaas_payment_id,
    new.asaas_subscription_id
  );

  -- An explicit ledger link has precedence. Any mismatch fails closed instead
  -- of falling back to another identifier supplied on the payment row.
  if new.billing_intent_id is not null then
    select intent.*
    into v_intent
    from private.billing_checkout_intents intent
    where intent.id = new.billing_intent_id
    for update;

    if not found
       or v_intent.organization_id is distinct from new.organization_id
       or (
         v_intent.provider_payment_id is not null
         and btrim(v_intent.provider_payment_id) is distinct from btrim(new.asaas_payment_id)
       )
       or (
         v_intent.provider_subscription_id is not null
         and new.asaas_subscription_id is not null
         and btrim(v_intent.provider_subscription_id)
           is distinct from btrim(new.asaas_subscription_id)
       ) then
      return null;
    end if;

    v_intent_found := true;
  end if;

  -- A provider payment id is globally unique and must never be allowed to
  -- fall through to a subscription belonging to a different organization.
  if not v_intent_found
     and nullif(btrim(coalesce(new.asaas_payment_id, '')), '') is not null then
    select intent.*
    into v_intent
    from private.billing_checkout_intents intent
    where intent.provider_payment_id = btrim(new.asaas_payment_id)
    order by intent.created_at desc, intent.id desc
    limit 1
    for update;

    if found then
      if v_intent.organization_id is distinct from new.organization_id
         or (
           v_intent.provider_subscription_id is not null
           and new.asaas_subscription_id is not null
           and btrim(v_intent.provider_subscription_id)
             is distinct from btrim(new.asaas_subscription_id)
         ) then
        return null;
      end if;

      v_intent_found := true;
    end if;
  end if;

  if not v_intent_found
     and nullif(btrim(coalesce(new.asaas_subscription_id, '')), '') is not null then
    select intent.*
    into v_intent
    from private.billing_checkout_intents intent
    where intent.provider_subscription_id = btrim(new.asaas_subscription_id)
    order by intent.created_at desc, intent.id desc
    limit 1
    for update;

    if found then
      if v_intent.organization_id is distinct from new.organization_id
         or (
           v_intent.status <> 'confirmed'
           and v_intent.provider_payment_id is not null
           and btrim(v_intent.provider_payment_id)
             is distinct from btrim(new.asaas_payment_id)
         ) then
        return null;
      end if;

      v_intent_found := true;
    end if;
  end if;

  if not v_intent_found then
    return null;
  end if;

  select
    greatest(
      organization.asaas_last_event_at,
      organization.billing_last_reconciled_at
    ),
    organization.asaas_customer_id,
    organization.asaas_subscription_id
  into
    v_organization_cursor,
    v_organization_customer_id,
    v_organization_subscription_id
  from public.organizations organization
  where organization.id = v_intent.organization_id
  for update;

  if not found
     or v_intent.organization_id is distinct from new.organization_id
     or (
       nullif(btrim(coalesce(v_organization_customer_id, '')), '') is not null
       and nullif(btrim(coalesce(new.asaas_customer_id, '')), '') is not null
       and btrim(v_organization_customer_id)
         is distinct from btrim(new.asaas_customer_id)
     )
     or (
       nullif(btrim(coalesce(v_organization_subscription_id, '')), '') is not null
       and nullif(btrim(coalesce(new.asaas_subscription_id, '')), '') is not null
       and btrim(v_organization_subscription_id)
         is distinct from btrim(new.asaas_subscription_id)
     )
     or (
       v_organization_cursor is not null
       and v_organization_cursor > v_payment_cursor
     ) then
    return null;
  end if;

  if upper(btrim(coalesce(new.status, ''))) in (
    'CANCELED',
    'CANCELLED',
    'DELETED'
  ) then
    update private.billing_checkout_intents
    set
      status = 'cancelled',
      cancelled_at = coalesce(cancelled_at, now()),
      last_error = lower(btrim(new.status)),
      updated_at = now()
    where id = v_intent.id
      and organization_id = new.organization_id
      and billing_method in ('PIX', 'BOLETO')
      and status in ('creating', 'pending');
  elsif upper(btrim(coalesce(new.status, ''))) = 'OVERDUE' then
    update private.billing_checkout_intents
    set
      last_error = 'overdue',
      updated_at = now()
    where id = v_intent.id
      and organization_id = new.organization_id
      and billing_method in ('PIX', 'BOLETO')
      and status in ('creating', 'pending');
  end if;

  if upper(btrim(coalesce(new.status, ''))) in (
    'CREDIT_CARD_CAPTURE_REFUSED',
    'OVERDUE',
    'CANCELED',
    'CANCELLED',
    'DELETED'
  ) then
    update private.billing_checkout_intents
    set
      last_error = lower(btrim(new.status)),
      updated_at = now()
    where id = v_intent.id
      and organization_id = new.organization_id
      and billing_method = 'CREDIT_CARD'
      and status in ('creating', 'pending');
  end if;

  perform private.confirm_billing_checkout_intent(
    new.asaas_payment_id,
    new.asaas_subscription_id,
    new.status,
    new.value
  );

  return null;
end;
$$;


ALTER FUNCTION private.confirm_billing_checkout_from_payment() OWNER TO postgres;

--
-- Name: confirm_billing_checkout_intent(text, text, text, numeric); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.confirm_billing_checkout_intent(p_payment_id text, p_subscription_id text, p_payment_status text, p_paid_amount numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment_id text := nullif(btrim(coalesce(p_payment_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_subscription_id, '')), '');
  v_payment_status text := upper(btrim(coalesce(p_payment_status, '')));
  v_intent private.billing_checkout_intents%rowtype;
  v_org public.organizations%rowtype;
  v_plan public.admin_subscription_plans%rowtype;
  v_period_end timestamptz;
  v_intent_found boolean := false;
  v_found_by_payment boolean := false;
  v_original_payment boolean := false;
  v_payment_observed_at timestamptz;
begin
  if v_payment_status not in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH') then
    return jsonb_build_object('outcome', 'not_paid');
  end if;

  if v_payment_id is null and v_subscription_id is null then
    return jsonb_build_object('outcome', 'provider_resource_missing');
  end if;

  if v_payment_id is null then
    return jsonb_build_object('outcome', 'payment_id_missing');
  end if;

  if char_length(v_payment_id) > 255
     or char_length(coalesce(v_subscription_id, '')) > 255 then
    return jsonb_build_object('outcome', 'identifier_invalid');
  end if;

  perform private.lock_asaas_billing_resources(
    v_payment_id,
    v_subscription_id
  );

  -- A payment id is globally unique and therefore has precedence. This also
  -- makes a replay with a forged subscription fail instead of matching some
  -- other intent through the subscription side of an OR predicate.
  select intent.*
  into v_intent
  from private.billing_checkout_intents intent
  where intent.status in ('creating', 'pending', 'confirmed')
    and intent.provider_payment_id = v_payment_id
  order by intent.created_at desc, intent.id desc
  limit 1
  for update;

  if found then
    v_intent_found := true;
    v_found_by_payment := true;
  elsif v_subscription_id is not null then
    select intent.*
    into v_intent
    from private.billing_checkout_intents intent
    where intent.status in ('creating', 'pending', 'confirmed')
      and intent.provider_subscription_id = v_subscription_id
    order by intent.created_at desc, intent.id desc
    limit 1
    for update;

    v_intent_found := found;
  end if;

  if not v_intent_found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  if v_subscription_id is not null
     and (
       v_intent.provider_subscription_id is null
       or btrim(v_intent.provider_subscription_id) <> v_subscription_id
     ) then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'subscription',
      'intent_id', v_intent.id
    );
  end if;

  if not v_found_by_payment
     and v_intent.provider_payment_id is not null
     and btrim(v_intent.provider_payment_id) <> v_payment_id
     and v_intent.status <> 'confirmed' then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'payment',
      'intent_id', v_intent.id
    );
  end if;

  v_original_payment := v_intent.provider_payment_id is not null
    and btrim(v_intent.provider_payment_id) = v_payment_id;

  if v_intent.status = 'confirmed' then
    -- Only a different payment id on the exact stored subscription is a
    -- renewal. Its amount belongs to the new billing cycle and must not be
    -- compared with the immutable amount of the original checkout.
    if not v_original_payment then
      if v_subscription_id is null
         or v_intent.provider_subscription_id is null
         or btrim(v_intent.provider_subscription_id) <> v_subscription_id then
        return jsonb_build_object(
          'outcome', 'identifier_mismatch',
          'field', 'renewal',
          'intent_id', v_intent.id
        );
      end if;

      return jsonb_build_object(
        'outcome', 'already_confirmed',
        'intent_id', v_intent.id,
        'billing_period_months', v_intent.billing_period_months,
        'renewal', true,
        'payment_id', v_payment_id
      );
    end if;

    -- A replay of the original charge remains subject to the frozen quote.
    if p_paid_amount is null then
      return jsonb_build_object(
        'outcome', 'amount_missing',
        'intent_id', v_intent.id
      );
    end if;

    if abs(v_intent.amount - p_paid_amount) > 0.01 then
      update private.billing_checkout_intents
      set
        last_error = format(
          'amount_mismatch expected=%s received=%s',
          v_intent.amount,
          p_paid_amount
        ),
        updated_at = now()
      where id = v_intent.id;

      return jsonb_build_object(
        'outcome', 'amount_mismatch',
        'intent_id', v_intent.id
      );
    end if;

    return jsonb_build_object(
      'outcome', 'already_confirmed',
      'intent_id', v_intent.id,
      'billing_period_months', v_intent.billing_period_months,
      'renewal', false
    );
  end if;

  select organization.*
  into v_org
  from public.organizations organization
  where organization.id = v_intent.organization_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;

  -- A legitimate checkout has already moved the organization to
  -- pending_payment. A historical intent must never reactivate terminal
  -- access when called indirectly by the payment-row confirmation trigger.
  if lower(btrim(coalesce(v_org.subscription_status, ''))) in (
    'suspended',
    'cancelled',
    'canceled'
  ) then
    return jsonb_build_object(
      'outcome', 'terminal_state',
      'intent_id', v_intent.id,
      'status', lower(btrim(v_org.subscription_status))
    );
  end if;

  -- The payment-row trigger executes before the outer webhook wrapper can
  -- reject an out-of-order event. Keep that trigger fail-closed against both
  -- the webhook and periodic-reconciliation organization cursors.
  select greatest(
    payment.last_webhook_event_at,
    payment.last_provider_observed_at
  )
  into v_payment_observed_at
  from public.asaas_payments payment
  where payment.asaas_payment_id = v_payment_id
    and payment.organization_id = v_intent.organization_id;

  if v_payment_observed_at is not null
     and greatest(
       v_org.asaas_last_event_at,
       v_org.billing_last_reconciled_at
     ) > v_payment_observed_at then
    return jsonb_build_object(
      'outcome', 'stale_observation',
      'intent_id', v_intent.id,
      'observed_at', v_payment_observed_at
    );
  end if;

  if p_paid_amount is null then
    update private.billing_checkout_intents
    set
      last_error = 'amount_missing',
      updated_at = now()
    where id = v_intent.id;

    return jsonb_build_object(
      'outcome', 'amount_missing',
      'intent_id', v_intent.id
    );
  end if;

  if abs(v_intent.amount - p_paid_amount) > 0.01 then
    update private.billing_checkout_intents
    set
      last_error = format(
        'amount_mismatch expected=%s received=%s',
        v_intent.amount,
        p_paid_amount
      ),
      updated_at = now()
    where id = v_intent.id;

    return jsonb_build_object(
      'outcome', 'amount_mismatch',
      'intent_id', v_intent.id
    );
  end if;

  if not (
    v_org.pending_plan_id = v_intent.pending_plan_id
    or (
      v_org.pending_plan_id is null
      and v_org.subscription_status = 'pending_payment'
      and v_org.plan_id = v_intent.pending_plan_id
    )
  ) then
    update private.billing_checkout_intents
    set
      last_error = 'pending_plan_mismatch',
      updated_at = now()
    where id = v_intent.id;

    return jsonb_build_object(
      'outcome', 'pending_plan_mismatch',
      'intent_id', v_intent.id
    );
  end if;

  select plan.*
  into v_plan
  from public.admin_subscription_plans plan
  where plan.id = v_intent.pending_plan_id;

  if not found then
    return jsonb_build_object('outcome', 'plan_not_found');
  end if;

  v_period_end := now() + make_interval(months => v_intent.billing_period_months);

  update private.billing_checkout_intents
  set
    status = 'confirmed',
    provider_payment_id = coalesce(provider_payment_id, v_payment_id),
    provider_subscription_id = coalesce(provider_subscription_id, v_subscription_id),
    confirmed_at = coalesce(confirmed_at, now()),
    last_error = null,
    updated_at = now()
  where id = v_intent.id;

  update public.organizations
  set
    plan_id = v_intent.pending_plan_id,
    pending_plan_id = null,
    subscription_value = v_plan.price,
    subscription_billing_period_months = v_intent.billing_period_months,
    subscription_type = 'paid',
    subscription_status = 'active',
    trial_ends_at = null,
    next_billing_date = v_period_end::date,
    max_users = coalesce(v_plan.max_users, max_users),
    asaas_customer_id = coalesce(asaas_customer_id, v_intent.provider_customer_id),
    asaas_subscription_id = coalesce(
      asaas_subscription_id,
      v_intent.provider_subscription_id,
      v_subscription_id
    ),
    updated_at = now()
  where id = v_intent.organization_id;

  update public.subscriptions
  set
    plan_id = v_intent.pending_plan_id,
    status = 'active',
    provider = 'asaas',
    billing_period_months = v_intent.billing_period_months,
    current_period_start = now(),
    current_period_end = v_period_end,
    provider_customer_id = coalesce(
      provider_customer_id,
      v_intent.provider_customer_id
    ),
    provider_subscription_id = coalesce(
      provider_subscription_id,
      v_intent.provider_subscription_id,
      v_subscription_id
    ),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'billing_period_months', v_intent.billing_period_months,
      'billing_cycle', v_intent.billing_cycle,
      'charged_amount', v_intent.amount
    ),
    updated_at = now()
  where organization_id = v_intent.organization_id;

  insert into public.subscription_logs (
    organization_id,
    event_type,
    status,
    metadata
  )
  values (
    v_intent.organization_id,
    'billing_intent_confirmed',
    'active',
    jsonb_build_object(
      'intent_id', v_intent.id,
      'plan_id', v_intent.pending_plan_id,
      'monthly_value', v_plan.price,
      'amount', v_intent.amount,
      'billing_cycle', v_intent.billing_cycle,
      'billing_period_months', v_intent.billing_period_months,
      'period_end', v_period_end,
      'billing_method', v_intent.billing_method,
      'provider_payment_id', coalesce(v_intent.provider_payment_id, v_payment_id),
      'provider_subscription_id', coalesce(
        v_intent.provider_subscription_id,
        v_subscription_id
      )
    )
  );

  return jsonb_build_object(
    'outcome', 'confirmed',
    'intent_id', v_intent.id,
    'organization_id', v_intent.organization_id,
    'plan_id', v_intent.pending_plan_id,
    'billing_period_months', v_intent.billing_period_months,
    'period_end', v_period_end
  );
end;
$$;


ALTER FUNCTION private.confirm_billing_checkout_intent(p_payment_id text, p_subscription_id text, p_payment_status text, p_paid_amount numeric) OWNER TO postgres;

--
-- Name: correct_asaas_naive_event_timestamp(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.correct_asaas_naive_event_timestamp(p_payload jsonb) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_value text := nullif(btrim(coalesce(p_payload ->> 'dateCreated', '')), '');
begin
  if v_value is null
     or v_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}$' then
    return null;
  end if;
  return replace(v_value, 'T', ' ')::timestamp
    at time zone 'America/Sao_Paulo';
exception
  when datetime_field_overflow or invalid_datetime_format then
    return null;
end
$_$;


ALTER FUNCTION private.correct_asaas_naive_event_timestamp(p_payload jsonb) OWNER TO postgres;

--
-- Name: create_billing_payment_receipt_from_payment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.create_billing_payment_receipt_from_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_organization record;
  v_plan_id uuid;
  v_plan_name text;
  v_billing_period_months integer;
  v_issuer jsonb;
  v_receipt_number text;
  v_snapshot jsonb;
  v_receipt_id uuid;
  v_verification_token uuid;
  v_receipt_issued_at timestamptz;
  v_recipient record;
begin
  if not private.billing_payment_checkout_is_paid(new.status) then
    return new;
  end if;

  if exists (
    select 1
    from public.billing_payment_receipts receipt
    where receipt.payment_id = new.id
  ) then
    return new;
  end if;

  select
    organization.name,
    coalesce(nullif(btrim(organization.billing_legal_name), ''), nullif(btrim(organization.razao_social), ''), organization.name) as payer_name,
    coalesce(nullif(btrim(organization.billing_tax_id), ''), nullif(btrim(organization.cnpj), '')) as payer_tax_id,
    coalesce(nullif(btrim(organization.billing_email), ''), nullif(btrim(organization.email), '')) as billing_email,
    coalesce(nullif(btrim(organization.billing_phone), ''), nullif(btrim(organization.whatsapp), ''), nullif(btrim(organization.telefone), '')) as billing_phone,
    coalesce(intent.pending_plan_id, organization.pending_plan_id, organization.plan_id) as receipt_plan_id,
    coalesce(intent.billing_period_months, organization.subscription_billing_period_months, 1) as receipt_period_months,
    coalesce(
      intent.confirmed_at,
      new.last_webhook_event_at,
      new.payment_date::timestamp at time zone 'America/Sao_Paulo',
      new.updated_at,
      now()
    ) as receipt_paid_at
    into v_organization
  from public.organizations organization
  left join private.billing_checkout_intents intent
    on intent.id = new.billing_intent_id
  where organization.id = new.organization_id;

  v_plan_id := v_organization.receipt_plan_id;
  v_billing_period_months := case
    when v_organization.receipt_period_months in (1, 6, 12) then v_organization.receipt_period_months
    else 1
  end;

  select plan.name
    into v_plan_name
  from public.admin_subscription_plans plan
  where plan.id = v_plan_id;
  v_plan_name := coalesce(nullif(btrim(v_plan_name), ''), 'Plano Vimob');

  select settings.value
    into v_issuer
  from public.system_settings settings
  where settings.key = 'billing_issuer'
  order by settings.updated_at desc nulls last, settings.created_at desc nulls last
  limit 1;
  v_issuer := coalesce(v_issuer, jsonb_build_object(
    'name', 'Vimob CRM',
    'support_email', 'contato@vimobcrm.com.br'
  ));

  v_receipt_number := 'VIMOB-'
    || to_char(v_organization.receipt_paid_at at time zone 'America/Sao_Paulo', 'YYYYMM')
    || '-'
    || upper(substr(replace(new.id::text, '-', ''), 1, 12));

  v_snapshot := jsonb_build_object(
    'version', 1,
    'receipt_number', v_receipt_number,
    'issuer', v_issuer,
    'organization_id', new.organization_id,
    'organization_name', v_organization.name,
    'payer_name', v_organization.payer_name,
    'payer_tax_id', v_organization.payer_tax_id,
    'billing_email', v_organization.billing_email,
    'plan_id', v_plan_id,
    'plan_name', v_plan_name,
    'billing_period_months', v_billing_period_months,
    'payment_provider', 'asaas',
    'provider_payment_reference', new.asaas_payment_id,
    'billing_type', coalesce(nullif(upper(btrim(new.billing_type)), ''), 'UNKNOWN'),
    'amount', coalesce(new.value, 0),
    'currency', 'BRL',
    'paid_at', v_organization.receipt_paid_at
  );

  insert into public.billing_payment_receipts (
    payment_id,
    organization_id,
    plan_id,
    receipt_number,
    issuer_name,
    payer_name,
    payer_tax_id,
    billing_email,
    plan_name,
    billing_period_months,
    provider_payment_reference,
    billing_type,
    amount,
    paid_at,
    snapshot,
    snapshot_hash
  )
  values (
    new.id,
    new.organization_id,
    v_plan_id,
    v_receipt_number,
    coalesce(nullif(btrim(v_issuer ->> 'name'), ''), 'Vimob CRM'),
    v_organization.payer_name,
    v_organization.payer_tax_id,
    v_organization.billing_email,
    v_plan_name,
    v_billing_period_months,
    new.asaas_payment_id,
    coalesce(nullif(upper(btrim(new.billing_type)), ''), 'UNKNOWN'),
    coalesce(new.value, 0),
    v_organization.receipt_paid_at,
    v_snapshot,
    encode(extensions.digest(v_snapshot::text, 'sha256'), 'hex')
  )
  on conflict (payment_id) do nothing
  returning id, verification_token, issued_at
    into v_receipt_id, v_verification_token, v_receipt_issued_at;

  if v_receipt_id is null then
    select receipt.id, receipt.verification_token, receipt.issued_at
      into v_receipt_id, v_verification_token, v_receipt_issued_at
    from public.billing_payment_receipts receipt
    where receipt.payment_id = new.id;
  end if;

  -- Exactly one external receipt delivery is produced transactionally with the
  -- immutable snapshot. Other billing administrators still see the in-app
  -- payment history, without receiving duplicate copies of the same receipt.
  select
    account.id as user_id,
    account.name as recipient_name,
    coalesce(v_organization.billing_email, nullif(btrim(account.email), '')) as recipient_email,
    coalesce(v_organization.billing_phone, nullif(btrim(account.whatsapp), ''), nullif(btrim(account.phone), '')) as recipient_whatsapp
    into v_recipient
  from public.organization_members membership
  join public.users account on account.id = membership.user_id
  where membership.organization_id = new.organization_id
    and membership.is_active = true
    and coalesce(account.is_active, true) = true
  order by
    case
      when v_organization.billing_email is not null
       and lower(account.email) = lower(v_organization.billing_email) then 0
      when lower(coalesce(membership.role, '')) = 'owner' then 1
      when lower(coalesce(membership.role, '')) = 'admin' then 2
      else 3
    end,
    membership.created_at asc
  limit 1;

  if v_recipient.user_id is not null then
    insert into public.notifications (
      organization_id,
      user_id,
      title,
      content,
      body,
      type,
      channel,
      target_url,
      metadata
    )
    values (
      new.organization_id,
      v_recipient.user_id,
      'Comprovante de pagamento Vimob',
      'Seu pagamento foi confirmado e o comprovante Vimob esta disponivel.',
      'Seu pagamento foi confirmado e o comprovante Vimob esta disponivel.',
      'billing',
      'in_app',
      '/settings?tab=subscription&billing=payments&payment=' || new.id::text,
      jsonb_build_object(
        'event_key', 'billing_payment_receipt',
        'dedupe_key', 'billing:payment_receipt:' || new.id::text,
        'payment_id', new.id::text,
        'receipt_id', v_receipt_id::text,
        'receipt_number', v_receipt_number,
        'receipt_version', 1,
        'verification_path', '/comprovantes/' || v_verification_token::text,
        'recipient_name', v_recipient.recipient_name,
        'recipient_email', v_recipient.recipient_email,
        'recipient_whatsapp', v_recipient.recipient_whatsapp,
        'variables', jsonb_build_object(
          'receipt_number', v_receipt_number,
          'organization_name', v_organization.name,
          'payer_name', v_organization.payer_name,
          'payer_tax_id', v_organization.payer_tax_id,
          'plan_name', v_plan_name,
          'billing_period_months', v_billing_period_months,
          'billing_type', coalesce(nullif(upper(btrim(new.billing_type)), ''), 'UNKNOWN'),
          'amount', 'R$ ' || replace(to_char(coalesce(new.value, 0), 'FM999999990D00'), '.', ','),
          'paid_at', to_char(v_organization.receipt_paid_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
          'provider_payment_reference', new.asaas_payment_id,
          'verification_path', '/comprovantes/' || v_verification_token::text,
          'issuer_name', coalesce(nullif(btrim(v_issuer ->> 'name'), ''), 'Vimob CRM'),
          'issued_at', to_char(v_receipt_issued_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI')
        ),
        'dispatch', jsonb_build_object(
          'whatsapp', jsonb_build_object('required', true, 'status', 'pending'),
          'email', jsonb_build_object('required', true, 'status', 'pending')
        ),
        'whatsapp_dispatch_required', true,
        'whatsapp_dispatch', jsonb_build_object('status', 'pending')
      )
    )
    on conflict do nothing;
  end if;

  return new;
end;
$_$;


