-- Name: current_audit_actor_id(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_audit_actor_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    private.safe_uuid(nullif(current_setting('app.current_user_id', true), '')),
    private.safe_uuid(nullif(current_setting('request.jwt.claim.sub', true), '')),
    (select auth.uid())
  );
$$;


ALTER FUNCTION private.current_audit_actor_id() OWNER TO postgres;

--
-- Name: dedupe_whatsapp_meta_creative_activity(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dedupe_whatsapp_meta_creative_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_role text := coalesce(auth.role(), '');
  v_trusted_writer boolean := false;
  v_message_id text;
  v_session_text text;
  v_session_id uuid;
  v_historical_activity_id uuid;
  v_historical_found boolean := false;
  v_registered_lead_id uuid;
begin
  v_trusted_writer := v_actor_role = 'service_role'
    or (
      v_actor_role = ''
      and session_user not in ('anon', 'authenticated', 'authenticator')
    );

  if tg_op = 'DELETE' then
    if old.type <> 'meta_creative' or v_trusted_writer then
      return old;
    end if;

    -- Preserve existing lead/organization deletion behavior. Referential
    -- cascades run after the parent row is no longer visible in this transaction;
    -- a direct activity deletion still sees both parents and is rejected.
    if (
      old.lead_id is not null
      and not exists (
        select 1
        from public.leads as lead
        where lead.organization_id = old.organization_id
          and lead.id = old.lead_id
      )
    ) or (
      old.organization_id is not null
      and not exists (
        select 1
        from public.organizations as organization
        where organization.id = old.organization_id
      )
    ) then
      return old;
    end if;

    raise exception using
      errcode = '42501',
      message = 'trusted_whatsapp_meta_creative_activity_required';
  end if;

  if tg_op = 'UPDATE'
     and (old.type = 'meta_creative' or new.type = 'meta_creative') then
    if not v_trusted_writer then
      raise exception using
        errcode = '42501',
        message = 'trusted_whatsapp_meta_creative_activity_required';
    end if;

    if old.type is distinct from new.type
       or old.organization_id is distinct from new.organization_id
       or old.lead_id is distinct from new.lead_id
       or (old.metadata->>'whatsapp_session_id') is distinct from (new.metadata->>'whatsapp_session_id')
       or (old.metadata->>'message_id') is distinct from (new.metadata->>'message_id') then
      raise exception using
        errcode = '23514',
        message = 'whatsapp_meta_creative_provider_identity_immutable';
    end if;
    return new;
  end if;

  if new.type <> 'meta_creative' then
    return new;
  end if;

  if not v_trusted_writer then
    raise exception using
      errcode = '42501',
      message = 'trusted_whatsapp_meta_creative_activity_required';
  end if;

  v_message_id := btrim(coalesce(new.metadata->>'message_id', ''));
  v_session_text := btrim(coalesce(new.metadata->>'whatsapp_session_id', ''));
  begin
    v_session_id := nullif(v_session_text, '')::uuid;
  exception
    when invalid_text_representation then
      v_session_id := null;
  end;

  if new.organization_id is null
     or new.lead_id is null
     or v_session_id is null
     or length(v_message_id) not between 1 and 500
     or new.metadata->>'message_id' is distinct from v_message_id
     or not exists (
       select 1
       from public.whatsapp_messages as message
       where message.organization_id = new.organization_id
         and message.session_id = v_session_id
         and message.lead_id = new.lead_id
         and coalesce(message.from_me, false) = false
         and lower(coalesce(message.direction, 'inbound')) <> 'outbound'
         and (
           message.provider_message_id = v_message_id
           or (
             message.provider_message_id is null
             and message.message_id = v_message_id
           )
         )
     ) then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_meta_creative_provider_identity_required';
  end if;

  select activity.id
    into v_historical_activity_id
    from public.activities as activity
   where activity.organization_id = new.organization_id
     and activity.lead_id = new.lead_id
     and activity.type = 'meta_creative'
     and activity.metadata->>'whatsapp_session_id' = v_session_id::text
     and activity.metadata->>'message_id' = v_message_id
   order by activity.created_at desc, activity.id desc
   limit 1;
  v_historical_found := found;

  insert into private.whatsapp_meta_creative_event_ledger (
    organization_id,
    whatsapp_session_id,
    provider_message_id,
    lead_id,
    activity_id
  ) values (
    new.organization_id,
    v_session_id,
    v_message_id,
    new.lead_id,
    case when v_historical_found then v_historical_activity_id else new.id end
  )
  on conflict (organization_id, whatsapp_session_id, provider_message_id)
  do nothing
  returning lead_id into v_registered_lead_id;

  if found then
    if v_historical_found then
      -- Only the transaction that wins the immutable ledger key may promote
      -- old history. Later exact retries are true no-ops rather than
      -- last-writer-wins mutations of trusted content or creative URLs.
      delete from public.activities as activity
       where activity.organization_id = new.organization_id
         and activity.lead_id = new.lead_id
         and activity.type = 'meta_creative'
         and activity.metadata->>'whatsapp_session_id' = v_session_id::text
         and activity.metadata->>'message_id' = v_message_id
         and activity.id <> v_historical_activity_id;

      update public.activities as activity
         set user_id = new.user_id,
             content = new.content,
             metadata = new.metadata
       where activity.organization_id = new.organization_id
         and activity.lead_id = new.lead_id
         and activity.id = v_historical_activity_id;
      return null;
    end if;
    return new;
  end if;

  select ledger.lead_id
    into v_registered_lead_id
    from private.whatsapp_meta_creative_event_ledger as ledger
   where ledger.organization_id = new.organization_id
     and ledger.whatsapp_session_id = v_session_id
     and ledger.provider_message_id = v_message_id;

  if v_registered_lead_id is distinct from new.lead_id then
    raise exception using
      errcode = '23505',
      message = 'whatsapp_meta_creative_provider_event_lead_collision';
  end if;

  if v_registered_lead_id is not null then
    return null;
  end if;

  raise exception using
    errcode = '40001',
    message = 'whatsapp_meta_creative_provider_event_registration_failed';
end;
$$;


ALTER FUNCTION private.dedupe_whatsapp_meta_creative_activity() OWNER TO postgres;

--
-- Name: development_unit_property_status(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.development_unit_property_status(source_status text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select case lower(btrim(source_status))
    when 'reserved' then 'reserved'
    when 'sold' then 'sold'
    when 'blocked' then 'inactive'
    when 'unavailable' then 'inactive'
    when 'withdrawn' then 'inactive'
    else 'active'
  end
$$;


ALTER FUNCTION private.development_unit_property_status(source_status text) OWNER TO postgres;

--
-- Name: distribute_lead(uuid, uuid, text, uuid, boolean, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.distribute_lead(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid DEFAULT NULL::uuid, p_preserve_assignee boolean DEFAULT true, p_source text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare qid uuid; l public.leads%rowtype; r private.queue_lead_runtime%rowtype; w jsonb; result jsonb; existing private.lead_distribution_events%rowtype;
  event_id uuid; now_at timestamptz:=clock_timestamp(); candidate record; timeout_minutes integer;
begin
  if p_organization_id is null or p_lead_id is null or length(btrim(coalesce(p_idempotency_key,''))) not between 1 and 200 or p_idempotency_key<>btrim(p_idempotency_key) then
    raise exception using errcode='22023',message='invalid_distribution_request'; end if;
  select * into l from public.leads where organization_id=p_organization_id and id=p_lead_id;
  if not found then return jsonb_build_object('success',false,'reason','lead_not_found','lead_id',p_lead_id); end if;
  select * into r from private.queue_lead_runtime where organization_id=p_organization_id and lead_id=p_lead_id;
  qid:=coalesce(r.round_robin_id,p_round_robin_id,l.origin_round_robin_id,public.pick_round_robin_for_lead(p_lead_id),
    (select p.default_round_robin_id from public.pipelines p where p.organization_id=p_organization_id and p.id=l.pipeline_id));
  if not private.queue_runtime_is_managed(p_organization_id,qid) then
    return private.distribute_lead_legacy_before_queue_runtime(p_organization_id,p_lead_id,p_idempotency_key,p_round_robin_id,p_preserve_assignee,p_source,p_now); end if;
  perform 1 from public.round_robins where organization_id=p_organization_id and id=qid for share skip locked;
  if not found then raise exception using errcode='55P03',message='queue_configuration_busy'; end if;
  select * into l from public.leads where organization_id=p_organization_id and id=p_lead_id for no key update;
  select * into r from private.queue_lead_runtime where organization_id=p_organization_id and lead_id=p_lead_id;
  select * into existing from private.lead_distribution_events where organization_id=p_organization_id and idempotency_key=p_idempotency_key;
  if found then
    if existing.lead_id<>p_lead_id then return jsonb_build_object('success',false,'reason','idempotency_key_conflict','lead_id',p_lead_id); end if;
    return existing.result;
  end if;
  if r.lead_id is not null and r.state in ('manual_protected','human_protected','closed') then
    result:=jsonb_build_object('success',false,'reason','queue_protected','lead_id',p_lead_id,'round_robin_id',qid,'assigned_user_id',l.assigned_user_id);
  elsif l.assigned_user_id is not null and coalesce(p_preserve_assignee,true) then
    return private.distribute_lead_legacy_before_queue_runtime(p_organization_id,p_lead_id,p_idempotency_key,qid,true,p_source,now_at);
  elsif r.lead_id is null and l.assigned_user_id is not null then
    -- A pre-calendar owner needs evidence-based adoption by the batch. An old
    -- background RPC cannot turn an unknown/manual owner into a new episode.
    result:=jsonb_build_object('success',false,'reason','queue_protected','lead_id',p_lead_id,'round_robin_id',qid,'assigned_user_id',l.assigned_user_id);
  else
    w:=private.queue_window(p_organization_id,qid,now_at);
    if not coalesce((w->>'open')::boolean,false) then
      if r.lead_id is null and l.assigned_user_id is not null then
        -- A calendar activation cannot retroactively seize a manually owned card.
        result:=jsonb_build_object('success',false,'reason','queue_protected','lead_id',p_lead_id,'assigned_user_id',l.assigned_user_id,'round_robin_id',qid);
      else
        perform private.queue_runtime_enroll(p_organization_id,p_lead_id,qid,now_at);
        result:=private.queue_runtime_pool(p_organization_id,p_lead_id,'queue_closed',now_at,w);
      end if;
    elsif r.last_user_id is not null then
      result:=private.queue_runtime_step(p_organization_id,p_lead_id,now_at,
        lower(coalesce(p_source,'')) in ('meta','meta_lead_ads','whatsapp','webhook','site','manual','portal','portals','grupoolx'),null);
    elsif not exists(select 1 from private.queue_runtime_members(p_organization_id,qid,now_at) m where m.is_available) then
      perform private.queue_runtime_enroll(p_organization_id,p_lead_id,qid,now_at);
      result:=private.queue_runtime_pool(p_organization_id,p_lead_id,'no_available_members',now_at,w);
      result:=result||jsonb_build_object('reason','no_available_members');
    else
      insert into private.queue_runtime_commands values(txid_current(),p_organization_id,p_lead_id,'canonical',null)
        on conflict(transaction_id,organization_id,lead_id) do update set mode='canonical',actor_id=null;
      result:=private.distribute_lead_legacy_before_queue_runtime(p_organization_id,p_lead_id,p_idempotency_key,qid,false,p_source,now_at);
      delete from private.queue_runtime_commands where transaction_id=txid_current() and organization_id=p_organization_id and lead_id=p_lead_id;
      if result->>'reason'='assigned' then
        perform private.queue_runtime_enroll(p_organization_id,p_lead_id,qid,now_at);
        select * into candidate from private.queue_runtime_members(p_organization_id,qid,now_at) m where m.user_id=(result->>'assigned_user_id')::uuid;
        select least(10080,greatest(1,coalesce((q.settings->>'redistribution_timeout_minutes')::integer,20))) into timeout_minutes from public.round_robins q where q.organization_id=p_organization_id and q.id=qid;
        update private.queue_lead_runtime set state='auto_assigned',reason='initial_assignment',last_user_id=(result->>'assigned_user_id')::uuid,
          baseline_at=now_at,assigned_at=now_at,due_at=now_at+make_interval(mins=>timeout_minutes),
          next_action_at=least(now_at+interval '30 seconds',(w->>'closesAt')::timestamptz,candidate.available_until),entered_pool_at=null,
          last_position=coalesce(candidate.position,0),last_window_key=candidate.window_key,last_member_close_at=candidate.available_until,
          last_queue_close_at=(w->>'closesAt')::timestamptz,last_distribution_event_id=(result->>'distribution_event_id')::uuid,revision=revision+1 where organization_id=p_organization_id and lead_id=p_lead_id;
        insert into private.queue_round_visits select p_organization_id,p_lead_id,episode_id,round_number,(result->>'assigned_user_id')::uuid,now_at
          from private.queue_lead_runtime where organization_id=p_organization_id and lead_id=p_lead_id on conflict do nothing;
      end if;
      return result;
    end if;
  end if;
  event_id:=gen_random_uuid();
  result:=result||jsonb_build_object('distribution_event_id',event_id);
  insert into private.lead_distribution_events(id,organization_id,lead_id,idempotency_key,requested_round_robin_id,round_robin_id,source,outcome,result,completed_at)
    values(event_id,p_organization_id,p_lead_id,p_idempotency_key,qid,qid,coalesce(p_source,'queue_runtime'),result->>'reason',result,now_at);
  return result;
end;
$$;


ALTER FUNCTION private.distribute_lead(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid, p_preserve_assignee boolean, p_source text, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: distribute_lead_legacy_before_queue_runtime(uuid, uuid, text, uuid, boolean, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.distribute_lead_legacy_before_queue_runtime(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid DEFAULT NULL::uuid, p_preserve_assignee boolean DEFAULT true, p_source text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lead public.leads%rowtype;
  v_queue public.round_robins%rowtype;
  v_existing_event private.lead_distribution_events%rowtype;
  v_event_id uuid;
  v_queue_id uuid;
  v_source text;
  v_source_label text;
  v_timezone text;
  v_local_now timestamp without time zone;
  v_current_day integer;
  v_current_time time without time zone;
  v_ignore_availability boolean;
  v_candidate record;
  v_previous_assigned_user_id uuid;
  v_target_pipeline_id uuid;
  v_target_stage_id uuid;
  v_ticket bigint;
  v_result jsonb;
begin
  p_now := coalesce(p_now, clock_timestamp());

  if p_organization_id is null
     or p_lead_id is null
     or p_idempotency_key is null
     or length(btrim(p_idempotency_key)) not between 1 and 200
     or p_idempotency_key <> btrim(p_idempotency_key) then
    raise exception using
      errcode = '22023',
      message = 'invalid_distribution_request';
  end if;

  -- Tenant predicate is part of the lock acquisition so a caller cannot use
  -- this routine to probe or mutate a lead from a different organization.
  select lead.*
  into v_lead
  from public.leads as lead
  where lead.id = p_lead_id
    and lead.organization_id = p_organization_id
  for no key update;

  if not found then
    return jsonb_build_object(
      'success', false,
      'reason', 'lead_not_found',
      'lead_id', p_lead_id
    );
  end if;

  select event.*
  into v_existing_event
  from private.lead_distribution_events as event
  where event.organization_id = p_organization_id
    and event.idempotency_key = p_idempotency_key;

  if found then
    if v_existing_event.lead_id <> p_lead_id then
      return jsonb_build_object(
        'success', false,
        'reason', 'idempotency_key_conflict',
        'lead_id', p_lead_id
      );
    end if;

    update public.leads
    set metadata = coalesce(metadata, '{}'::jsonb) - 'distribution_deferred'
    where id = p_lead_id
      and organization_id = p_organization_id
      and metadata ? 'distribution_deferred';

    return v_existing_event.result;
  end if;

  v_source := private.normalize_lead_distribution_source(
    coalesce(p_source, v_lead.source)
  );

  v_source_label := case v_source
    when 'meta' then 'Meta Ads'
    when 'whatsapp' then 'WhatsApp'
    when 'webhook' then 'Webhook'
    when 'site' then 'Site'
    when 'manual' then 'Manual'
    else initcap(replace(v_source, '_', ' '))
  end;

  insert into private.lead_distribution_events (
    organization_id,
    lead_id,
    idempotency_key,
    requested_round_robin_id,
    source
  )
  values (
    p_organization_id,
    p_lead_id,
    p_idempotency_key,
    case
      when exists (
        select 1
        from public.round_robins as requested_queue
        where requested_queue.id = p_round_robin_id
          and requested_queue.organization_id = p_organization_id
      ) then p_round_robin_id
      else null
    end,
    v_source
  )
  on conflict (organization_id, idempotency_key) do nothing
  returning id into v_event_id;

  -- This branch is reachable when two trusted backend requests reuse a key for
  -- different leads concurrently. The unique key remains the source of truth.
  if v_event_id is null then
    select event.*
    into v_existing_event
    from private.lead_distribution_events as event
    where event.organization_id = p_organization_id
      and event.idempotency_key = p_idempotency_key;

    if v_existing_event.lead_id <> p_lead_id then
      return jsonb_build_object(
        'success', false,
        'reason', 'idempotency_key_conflict',
        'lead_id', p_lead_id
      );
    end if;

    return v_existing_event.result;
  end if;

  -- The marker is removed only inside the successful canonical transaction.
  -- Any unexpected exception rolls this update back, leaving the lead visibly
  -- deferred and safe to retry instead of falling back to legacy distribution.
  update public.leads
  set metadata = coalesce(metadata, '{}'::jsonb) - 'distribution_deferred'
  where id = p_lead_id
    and organization_id = p_organization_id
    and metadata ? 'distribution_deferred';

  insert into public.lead_timeline_events (
    organization_id,
    lead_id,
    event_type,
    title,
    description,
    metadata,
    event_at
  )
  select
    p_organization_id,
    p_lead_id,
    'lead_created',
    'Lead criado',
    'Lead recebido no sistema',
    jsonb_build_object(
      'source', v_source,
      'source_label', v_source_label,
      'distribution_event_id', v_event_id
    ),
    p_now
  where not exists (
    select 1
    from public.lead_timeline_events as timeline
    where timeline.organization_id = p_organization_id
      and timeline.lead_id = p_lead_id
      and timeline.event_type = 'lead_created'
  );

  if coalesce(p_preserve_assignee, true)
     and v_lead.assigned_user_id is not null then
    v_result := jsonb_build_object(
      'success', true,
      'reason', 'already_assigned',
      'lead_id', p_lead_id,
      'assigned_user_id', v_lead.assigned_user_id,
      'team_id', v_lead.team_id,
      'pipeline_id', v_lead.pipeline_id,
      'stage_id', v_lead.stage_id,
      'source', v_source,
      'distribution_event_id', v_event_id
    );

    update private.lead_distribution_events
    set assigned_user_id = v_lead.assigned_user_id,
        team_id = v_lead.team_id,
        outcome = 'already_assigned',
        result = v_result,
        completed_at = p_now
    where id = v_event_id;

    return v_result;
  end if;

  if p_round_robin_id is not null then
    v_queue_id := p_round_robin_id;
  else
    -- Preserve the intake contract: explicit rules win, including campaign,
    -- source, form, property, tag and channel conditions. The pipeline default
    -- is only a fallback when no queue rule (or legacy ruleless queue) matches.
    v_queue_id := public.pick_round_robin_for_lead(p_lead_id);

    if v_queue_id is null then
      select pipeline.default_round_robin_id
      into v_queue_id
      from public.pipelines as pipeline
      where pipeline.id = v_lead.pipeline_id
        and pipeline.organization_id = p_organization_id
        and coalesce(pipeline.is_active, true) = true;
    end if;
  end if;

  -- Queue configuration is read without an exclusive row lock. A queue-local
  -- sequence below reserves the assignment slot without serializing unrelated
  -- lead writes or holding a hot lock through WAL flush at commit.
  select queue.*
  into v_queue
  from public.round_robins as queue
  where queue.id = v_queue_id
    and queue.organization_id = p_organization_id
    and coalesce(queue.is_active, true) = true;

  if not found then
    insert into public.round_robin_logs (
      organization_id,
      lead_id,
      reason,
      metadata
    )
    values (
      p_organization_id,
      p_lead_id,
      'no_matching_queue',
      jsonb_build_object(
        'source', v_source,
        'distribution_event_id', v_event_id
      )
    );

    insert into public.lead_timeline_events (
      organization_id,
      lead_id,
      event_type,
      title,
      description,
      metadata,
      event_at
    )
    values (
      p_organization_id,
      p_lead_id,
      'lead_distribution_pending',
      'Aguardando distribuição',
      'Nenhuma fila de distribuição ativa foi encontrada.',
      jsonb_build_object(
        'destination', 'pool',
        'reason', 'no_matching_queue',
        'source', v_source,
        'distribution_event_id', v_event_id
      ),
      p_now
    );

    v_result := jsonb_build_object(
      'success', false,
      'reason', 'no_matching_queue',
      'lead_id', p_lead_id,
      'source', v_source,
      'distribution_event_id', v_event_id
    );

    update private.lead_distribution_events
    set outcome = 'no_matching_queue',
        result = v_result,
        completed_at = p_now
    where id = v_event_id;

    return v_result;
  end if;

  update private.lead_distribution_events
  set round_robin_id = v_queue.id
  where id = v_event_id;

  v_ignore_availability :=
    lower(coalesce(v_queue.settings->>'ignore_availability', 'false'))
      in ('1', 'true', 'yes');

  v_timezone := coalesce(
    nullif(btrim(v_queue.settings->>'timezone'), ''),
    (
      select nullif(btrim(settings.timezone), '')
      from public.organization_attention_settings as settings
      where settings.organization_id = p_organization_id
    ),
    'America/Sao_Paulo'
  );

  -- pg_timezone_names expands the entire timezone catalog and cost about 57 ms
  -- per local call in the intake profile. PostgreSQL already validates IANA
  -- names in AT TIME ZONE, so validate by performing the actual conversion and
  -- keep the defensive fallback for stale/manual data.
  begin
    v_local_now := p_now at time zone v_timezone;
  exception
    when invalid_parameter_value then
      v_timezone := 'America/Sao_Paulo';
      v_local_now := p_now at time zone v_timezone;
  end;

  v_current_day := extract(dow from v_local_now)::integer;
  v_current_time := v_local_now::time;
  if (
    v_lead.assigned_user_id is not null or exists (
      select 1 from private.round_robin_rotation_state rotation
      where rotation.organization_id=p_organization_id and rotation.lead_id=p_lead_id
        and rotation.round_robin_id=v_queue.id and cardinality(rotation.visited_user_ids)>0
    ) or exists (
      select 1 from public.round_robin_logs prior
      where prior.organization_id=p_organization_id and prior.lead_id=p_lead_id
        and prior.round_robin_id=v_queue.id and prior.assigned_user_id is not null
        and private.is_round_robin_rotation_assignment_reason(prior.reason)
    )
  ) then
    v_ticket := null;
    -- p_now is the original intake event time, including delayed Meta or
    -- WhatsApp events. Transfer availability uses the processing clock,
    -- like the confirmed-log guard; the historical event stays intact.
    select candidate.* into v_candidate
    from private.preview_round_robin_redistribution_candidate(
      p_organization_id, p_lead_id, v_queue.id,
      v_lead.assigned_user_id, null
    ) as candidate;
  else
  v_ticket := private.next_round_robin_ticket(v_queue.id);

  select candidate.*
  into v_candidate
  from private.pick_round_robin_ticket_candidate(
    p_organization_id,
    v_queue.id,
    v_queue.strategy,
    v_ignore_availability,
    v_current_day,
    v_current_time,
    v_ticket
  ) as candidate;
  end if;

  if v_candidate.user_id is null then
    insert into public.round_robin_logs (
      organization_id,
      round_robin_id,
      lead_id,
      reason,
      metadata
    )
    values (
      p_organization_id,
      v_queue.id,
      p_lead_id,
      'no_available_members',
      jsonb_build_object(
        'source', v_source,
        'queue_name', v_queue.name,
        'distribution_ticket', v_ticket,
        'algorithm_version', (case when v_ticket is null then 'lead_queue_rotation_v1' else 'queue_ticket_iwrr_v1' end),
        'distribution_event_id', v_event_id
      )
    );

    insert into public.lead_timeline_events (
      organization_id,
      lead_id,
      event_type,
      title,
      description,
      metadata,
      event_at
    )
    values (
      p_organization_id,
      p_lead_id,
      'lead_distribution_pending',
      'Aguardando distribuição',
      'Fila "' || v_queue.name || '" sem membros disponíveis no momento.',
      jsonb_build_object(
        'destination', 'pool',
        'reason', 'no_available_members',
        'source', v_source,
        'queue_id', v_queue.id,
        'queue_name', v_queue.name,
        'distribution_event_id', v_event_id
      ),
      p_now
    );

    v_result := jsonb_build_object(
      'success', false,
      'reason', 'no_available_members',
      'lead_id', p_lead_id,
      'round_robin_id', v_queue.id,
      'round_robin_name', v_queue.name,
      'source', v_source,
      'distribution_ticket', v_ticket,
      'algorithm_version', (case when v_ticket is null then 'lead_queue_rotation_v1' else 'queue_ticket_iwrr_v1' end),
      'distribution_event_id', v_event_id
    );

    update private.lead_distribution_events
    set distribution_ticket = v_ticket,
        algorithm_version = (case when v_ticket is null then 'lead_queue_rotation_v1' else 'queue_ticket_iwrr_v1' end),
        outcome = 'no_available_members',
        result = v_result,
        completed_at = p_now
    where id = v_event_id;

    return v_result;
  end if;

  v_target_pipeline_id := coalesce(
    v_queue.target_pipeline_id,
    v_lead.pipeline_id
  );

  if v_target_pipeline_id is not null
     and not exists (
       select 1
       from public.pipelines as pipeline
       where pipeline.id = v_target_pipeline_id
         and pipeline.organization_id = p_organization_id
         and coalesce(pipeline.is_active, true) = true
     ) then
    raise exception using
      errcode = '23514',
      message = 'invalid_distribution_target_pipeline';
  end if;

  if v_queue.target_stage_id is not null then
    select stage.id
    into v_target_stage_id
    from public.stages as stage
    where stage.id = v_queue.target_stage_id
      and stage.organization_id = p_organization_id
      and stage.pipeline_id = v_target_pipeline_id
      and coalesce(stage.is_active, true) = true;

    if not found then
      raise exception using
        errcode = '23514',
        message = 'invalid_distribution_target_stage';
    end if;
  elsif exists (
    select 1
    from public.stages as stage
    where stage.id = v_lead.stage_id
      and stage.organization_id = p_organization_id
      and stage.pipeline_id = v_target_pipeline_id
      and coalesce(stage.is_active, true) = true
  ) then
    v_target_stage_id := v_lead.stage_id;
  else
    select stage.id
    into v_target_stage_id
    from public.stages as stage
    where stage.organization_id = p_organization_id
      and stage.pipeline_id = v_target_pipeline_id
      and coalesce(stage.is_active, true) = true
    order by stage.position, stage.id
    limit 1;
  end if;

  v_previous_assigned_user_id := v_lead.assigned_user_id;

  update public.leads
  set assigned_user_id = v_candidate.user_id,
      team_id = v_candidate.team_id,
      pipeline_id = v_target_pipeline_id,
      stage_id = v_target_stage_id,
      assigned_at = p_now,
      updated_at = p_now
  where id = p_lead_id
    and organization_id = p_organization_id;

  insert into public.assignments_log (
    organization_id,
    lead_id,
    round_robin_id,
    assigned_user_id,
    old_user_id,
    new_user_id,
    reason,
    assigned_at
  )
  values (
    p_organization_id,
    p_lead_id,
    v_queue.id,
    v_candidate.user_id,
    v_previous_assigned_user_id,
    v_candidate.user_id,
    'canonical_round_robin',
    p_now
  );

  insert into public.round_robin_logs (
    organization_id,
    round_robin_id,
    lead_id,
    assigned_user_id,
    member_id,
    reason,
    metadata
  )
  values (
    p_organization_id,
    v_queue.id,
    p_lead_id,
    v_candidate.user_id,
    v_candidate.member_id,
    'canonical_round_robin',
    jsonb_build_object(
      'source', v_source,
      'queue_name', v_queue.name,
      'strategy', lower(coalesce(v_queue.strategy, 'simple')),
      'member_id', v_candidate.member_id,
      'team_id', v_candidate.team_id,
      'team_member_id', v_candidate.team_member_id,
      'availability_check', v_candidate.availability_reason,
      'distribution_ticket', v_ticket,
      'algorithm_version', (case when v_ticket is null then 'lead_queue_rotation_v1' else 'queue_ticket_iwrr_v1' end),
      'slot_count', v_candidate.slot_count,
      'candidate_position', v_candidate.slot_position,
      'recipient_count', v_candidate.recipient_count,
      'recipient_position', v_candidate.recipient_position,
      'distribution_event_id', v_event_id
    )
  );

  insert into public.lead_timeline_events (
    organization_id,
    lead_id,
    user_id,
    event_type,
    title,
    description,
    metadata,
    event_at
  )
  values (
    p_organization_id,
    p_lead_id,
    v_candidate.user_id,
    'lead_assigned',
    'Distribuído via "' || v_queue.name || '"',
    'Atribuído a ' || coalesce(v_candidate.user_name, 'usuário')
      || ' pela fila "' || v_queue.name || '"',
    jsonb_build_object(
      'source', v_source,
      'source_label', v_source_label,
      'queue_id', v_queue.id,
      'queue_name', v_queue.name,
      'assigned_user_id', v_candidate.user_id,
      'assigned_user_name', v_candidate.user_name,
      'team_id', v_candidate.team_id,
      'pipeline_id', v_target_pipeline_id,
      'stage_id', v_target_stage_id,
      'distribution_type', 'canonical_round_robin',
      'distribution_ticket', v_ticket,
      'algorithm_version', (case when v_ticket is null then 'lead_queue_rotation_v1' else 'queue_ticket_iwrr_v1' end),
      'slot_count', v_candidate.slot_count,
      'candidate_position', v_candidate.slot_position,
      'distribution_event_id', v_event_id
    ),
    p_now
  );

  insert into public.notifications (
    organization_id,
    user_id,
    lead_id,
    type,
    title,
    content,
    body,
    metadata,
    channel,
    target_url,
    created_at
  )
  values (
    p_organization_id,
    v_candidate.user_id,
    p_lead_id,
    'lead_assigned',
    'Novo lead atribuído',
    'O lead "' || v_lead.name || '" foi atribuído a você.',
    'O lead "' || v_lead.name || '" foi atribuído a você.',
    jsonb_build_object(
      'source', v_source,
      'source_label', v_source_label,
      'lead_name', v_lead.name,
      'round_robin_id', v_queue.id,
      'round_robin_name', v_queue.name,
      'assigned_user_id', v_candidate.user_id,
      'assigned_user_name', v_candidate.user_name,
      'pipeline_id', v_target_pipeline_id,
      'stage_id', v_target_stage_id,
      'event_key', 'new_lead_received',
      'dedupe_key', concat_ws(
        ':',
        'new_lead_received',
        p_lead_id::text,
        v_candidate.user_id::text,
        case when v_ticket is null then v_event_id::text end
      ),
      'distribution_event_id', v_event_id,
      'whatsapp_dispatch_required', true,
      'whatsapp_dispatch', jsonb_build_object('status', 'pending'),
      'dispatch', jsonb_build_object(
        'whatsapp', jsonb_build_object(
          'required', true,
          'status', 'pending'
        ),
        'push', jsonb_build_object(
          'required', true,
          'status', 'pending'
        )
      )
    ),
    'in_app',
    '/crm/pipelines?lead=' || p_lead_id::text,
    p_now
  );

  v_result := jsonb_build_object(
    'success', true,
    'reason', 'assigned',
    'lead_id', p_lead_id,
    'assigned_user_id', v_candidate.user_id,
    'assigned_user_name', v_candidate.user_name,
    'team_id', v_candidate.team_id,
    'pipeline_id', v_target_pipeline_id,
    'stage_id', v_target_stage_id,
    'round_robin_id', v_queue.id,
    'round_robin_name', v_queue.name,
    'member_id', v_candidate.member_id,
    'source', v_source,
    'distribution_ticket', v_ticket,
    'algorithm_version', (case when v_ticket is null then 'lead_queue_rotation_v1' else 'queue_ticket_iwrr_v1' end),
    'slot_count', v_candidate.slot_count,
    'candidate_position', v_candidate.slot_position,
    'recipient_count', v_candidate.recipient_count,
    'recipient_position', v_candidate.recipient_position,
    'distribution_event_id', v_event_id
  );

  update private.lead_distribution_events
  set distribution_ticket = v_ticket,
      algorithm_version = (case when v_ticket is null then 'lead_queue_rotation_v1' else 'queue_ticket_iwrr_v1' end),
      slot_count = v_candidate.slot_count,
      candidate_position = v_candidate.slot_position,
      assigned_user_id = v_candidate.user_id,
      team_id = v_candidate.team_id,
      outcome = 'assigned',
      result = v_result,
      completed_at = p_now
  where id = v_event_id;

  return v_result;
end;
$$;


ALTER FUNCTION private.distribute_lead_legacy_before_queue_runtime(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid, p_preserve_assignee boolean, p_source text, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION distribute_lead_legacy_before_queue_runtime(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid, p_preserve_assignee boolean, p_source text, p_now timestamp with time zone); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.distribute_lead_legacy_before_queue_runtime(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid, p_preserve_assignee boolean, p_source text, p_now timestamp with time zone) IS 'Backend-only, tenant-scoped, idempotent and atomic lead distribution.';


--
-- Name: enforce_active_org_member_reference(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_active_org_member_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  referenced_user_id uuid;
  locked_user_id uuid;
  locked_membership_id uuid;
begin
  if tg_op = 'UPDATE'
     and new.organization_id is not distinct from old.organization_id
     and (to_jsonb(new) ->> tg_argv[0]) is not distinct from (to_jsonb(old) ->> tg_argv[0]) then
    return new;
  end if;

  referenced_user_id := nullif(to_jsonb(new) ->> tg_argv[0], '')::uuid;
  if referenced_user_id is null then
    return new;
  end if;

  select app_user.id
  into locked_user_id
  from public.users as app_user
  where app_user.id = referenced_user_id
    and coalesce(app_user.is_active, false) = true
  for key share;

  if locked_user_id is null then
    raise exception using
      errcode = '23514',
      message = format(
        'Usuario de %s nao e membro ativo da organizacao.',
        tg_argv[0]
      );
  end if;

  select membership.id
  into locked_membership_id
  from public.organization_members as membership
  where membership.organization_id = new.organization_id
    and membership.user_id = referenced_user_id
    and coalesce(membership.is_active, false) = true
    and membership.deleted_at is null
  for key share;

  if locked_membership_id is null then
    raise exception using
      errcode = '23514',
      message = format(
        'Usuario de %s nao e membro ativo da organizacao.',
        tg_argv[0]
      );
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_active_org_member_reference() OWNER TO postgres;

