-- Name: enforce_core_organization_module_enabled(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_core_organization_module_enabled() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if lower(btrim(new.module_name)) = any(
    array['crm', 'whatsapp', 'round_robin']::text[]
  ) then
    new.is_enabled := true;
  end if;

  return new;
end;
$$;


