--
-- Name: enforce_lead_intake_identity(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_lead_intake_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_expected_scope text;
  v_is_pending_meta_phone_claim boolean := false;
  v_import_token text := pg_catalog.current_setting(
    'vimob.historical_import_token',
    true
  );
begin
  if tg_op = 'UPDATE' then
    if new.organization_id is not distinct from old.organization_id
       and new.origin_round_robin_id is not distinct from old.origin_round_robin_id
       and new.intake_scope_key is not distinct from old.intake_scope_key
       and new.external_source is not distinct from old.external_source
       and new.external_source_id is not distinct from old.external_source_id
       and new.operational_effects_suppressed
         is not distinct from old.operational_effects_suppressed
       and new.historical_imported_at
         is not distinct from old.historical_imported_at then
      -- Do not revalidate immutable provenance after a queue is hard-deleted.
      return new;
    end if;

    v_is_pending_meta_phone_claim :=
      new.organization_id is not distinct from old.organization_id
      and old.origin_round_robin_id is null
      and old.intake_scope_key = 'unscoped'
      and old.external_source is null
      and old.external_source_id is null
      and new.operational_effects_suppressed
        is not distinct from old.operational_effects_suppressed
      and new.historical_imported_at
        is not distinct from old.historical_imported_at
      and new.external_source is null
      and new.external_source_id is null
      and coalesce(public.normalize_phone(old.phone), '') = ''
      and coalesce(public.normalize_phone(new.phone), '') <> ''
      and new.origin_round_robin_id is not null
      and old.meta_lead_id is not null
      and pg_catalog.lower(coalesce(old.metadata->>'meta_details_status', '')) = 'pending';

    if not v_is_pending_meta_phone_claim then
      raise exception using
        errcode = '23514',
        message = 'lead_intake_identity_immutable';
    end if;
  end if;

  new.external_source := nullif(
    pg_catalog.lower(pg_catalog.btrim(coalesce(new.external_source, ''))),
    ''
  );
  new.external_source_id := nullif(
    pg_catalog.btrim(coalesce(new.external_source_id, '')),
    ''
  );

  if (new.external_source is null) <> (new.external_source_id is null) then
    raise exception using
      errcode = '23514',
      message = 'lead_external_identity_incomplete';
  end if;

  if tg_op = 'INSERT'
     and (
       new.external_source is not null
       or coalesce(new.operational_effects_suppressed, false)
       or new.historical_imported_at is not null
     )
     and not exists (
       select 1
       from private.historical_lead_import_contexts as context
       where context.transaction_id = pg_catalog.pg_current_xact_id()::text
         and context.organization_id = new.organization_id
         and context.token_sha256 = pg_catalog.encode(
           extensions.digest(coalesce(v_import_token, ''), 'sha256'),
           'hex'
         )
     ) then
    raise exception using
      errcode = '42501',
      message = 'lead_external_identity_requires_import_capability';
  end if;

  if new.external_source is not null then
    if new.origin_round_robin_id is not null then
      raise exception using
        errcode = '23514',
        message = 'lead_external_identity_queue_conflict';
    end if;

    v_expected_scope := private.lead_intake_scope_for_external(
      new.organization_id,
      new.external_source,
      new.external_source_id
    );
  else
    v_expected_scope := private.lead_intake_scope_for_queue(
      new.organization_id,
      new.origin_round_robin_id
    );
  end if;

  if tg_op = 'INSERT'
     and coalesce(new.intake_scope_key, 'unscoped') = 'unscoped'
     and v_expected_scope <> 'unscoped' then
    new.intake_scope_key := v_expected_scope;
  elsif new.intake_scope_key is distinct from v_expected_scope then
    raise exception using
      errcode = '23514',
      message = 'lead_intake_scope_mismatch';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_lead_intake_identity() OWNER TO postgres;

--
-- Name: enforce_portal_tenant_scope(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_portal_tenant_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'portal_integrations' then
    if new.default_pipeline_id is not null and not exists (
      select 1 from public.pipelines p
      where p.id = new.default_pipeline_id and p.organization_id = new.organization_id
    ) then
      raise exception using errcode = '23514', message = 'portal pipeline must belong to the integration organization';
    end if;
    if new.default_stage_id is not null and not exists (
      select 1 from public.stages s
      where s.id = new.default_stage_id
        and s.organization_id = new.organization_id
        and (new.default_pipeline_id is null or s.pipeline_id = new.default_pipeline_id)
    ) then
      raise exception using errcode = '23514', message = 'portal stage must belong to the integration organization and pipeline';
    end if;
    if new.default_assigned_user_id is not null and not exists (
      select 1 from public.organization_members om
      where om.organization_id = new.organization_id and om.user_id = new.default_assigned_user_id
    ) then
      raise exception using errcode = '23514', message = 'portal assignee must belong to the integration organization';
    end if;
    if new.default_round_robin_id is not null and not exists (
      select 1 from public.round_robins rr
      where rr.id = new.default_round_robin_id and rr.organization_id = new.organization_id
    ) then
      raise exception using errcode = '23514', message = 'portal round robin must belong to the integration organization';
    end if;
  elsif tg_table_name = 'portal_listing_publications' then
    if not exists (
      select 1 from public.portal_integrations pi
      where pi.id = new.integration_id
        and pi.organization_id = new.organization_id
        and pi.portal = new.portal
    ) or not exists (
      select 1 from public.properties p
      where p.id = new.property_id and p.organization_id = new.organization_id
    ) then
      raise exception using errcode = '23514', message = 'portal publication references must belong to one organization';
    end if;
  elsif tg_table_name in ('portal_import_reports', 'portal_webhook_events') then
    if not exists (
      select 1 from public.portal_integrations pi
      where pi.id = new.integration_id
        and pi.organization_id = new.organization_id
        and pi.portal = new.portal
    ) then
      raise exception using errcode = '23514', message = 'portal event integration must belong to the event organization';
    end if;
    if tg_table_name = 'portal_webhook_events' then
      if new.lead_id is not null and not exists (
        select 1 from public.leads l where l.id = new.lead_id and l.organization_id = new.organization_id
      ) then
        raise exception using errcode = '23514', message = 'portal event lead must belong to the event organization';
      end if;
      if new.property_id is not null and not exists (
        select 1 from public.properties p where p.id = new.property_id and p.organization_id = new.organization_id
      ) then
        raise exception using errcode = '23514', message = 'portal event property must belong to the event organization';
      end if;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.enforce_portal_tenant_scope() OWNER TO postgres;

--
-- Name: enforce_property_asset_storage_path(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_asset_storage_path() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  expected_prefix text;
  safe_file_name text;
begin
  if new.storage_path is null then
    return new;
  end if;

  new.storage_path := btrim(new.storage_path);

  if current_user = 'postgres'
     and coalesce(new.metadata ->> 'legacy_backfill', 'false') = 'true' then
    return new;
  end if;

  expected_prefix := pg_catalog.format(
    'orgs/%s/properties/%s/%s/',
    new.organization_id,
    new.property_id,
    new.id
  );
  safe_file_name := pg_catalog.substr(
    new.storage_path,
    pg_catalog.length(expected_prefix) + 1
  );

  if pg_catalog.left(new.storage_path, pg_catalog.length(expected_prefix))
       <> expected_prefix
     or safe_file_name !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,239}$' then
    raise exception using
      errcode = '23514',
      message = 'property_asset_storage_path_invalid';
  end if;

  return new;
end;
$_$;


ALTER FUNCTION private.enforce_property_asset_storage_path() OWNER TO postgres;

--
-- Name: enforce_property_condominium_location_chain(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_condominium_location_chain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_neighborhood_city_id uuid;
begin
  if new.neighborhood_id is not null then
    select neighborhood.city_id
      into v_neighborhood_city_id
    from public.property_neighborhoods as neighborhood
    where neighborhood.organization_id = new.organization_id
      and neighborhood.id = new.neighborhood_id
      and coalesce(neighborhood.is_active, true)
    for key share;
    if not found then
      raise exception 'invalid or inactive condominium neighborhood'
        using errcode = '23514', constraint = 'property_condominium_location_hierarchy';
    end if;
    if v_neighborhood_city_id is null then
      raise exception 'condominium neighborhood has no city'
        using errcode = '23514', constraint = 'property_neighborhood_city_required';
    end if;
    if new.city_id is null then
      new.city_id := v_neighborhood_city_id;
    elsif new.city_id <> v_neighborhood_city_id then
      raise exception 'condominium neighborhood does not belong to city'
        using errcode = '23514', constraint = 'property_condominium_location_hierarchy';
    end if;
  end if;

  if new.city_id is not null then
    perform 1
    from public.property_cities as city
    where city.organization_id = new.organization_id
      and city.id = new.city_id
      and coalesce(city.is_active, true)
    for key share;
    if not found then
      raise exception 'invalid or inactive condominium city'
        using errcode = '23514', constraint = 'property_condominium_location_hierarchy';
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION private.enforce_property_condominium_location_chain() OWNER TO postgres;

--
-- Name: enforce_property_development_tenant_scope(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_development_tenant_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  user_column text;
  user_text text;
  user_id uuid;
begin
  foreach user_column in array array[
    'created_by',
    'updated_by',
    'responsible_user_id',
    'approved_by',
    'reserved_by'
  ]::text[]
  loop
	if tg_op = 'UPDATE' then
	  if new.organization_id is not distinct from old.organization_id
	     and (to_jsonb(new) ->> user_column) is not distinct from (to_jsonb(old) ->> user_column) then
	    continue;
	  end if;
	end if;

    user_text := nullif(btrim(to_jsonb(new) ->> user_column), '');
    if user_text is null then
      continue;
    end if;

    user_id := private.safe_uuid(user_text);
    if user_id is null
       or not private.property_user_belongs_to_organization(
         new.organization_id,
         user_id
       ) then
      raise exception using
        errcode = '23514',
        message = format(
          'property_development_user_cross_tenant_reference:%s',
          user_column
        );
    end if;
  end loop;

  -- PL/pgSQL resolves fields on a generic trigger record before SQL boolean
  -- short-circuiting. Keep the table guard in its own block so tables without
  -- lead_id never attempt to dereference that field.
  if tg_table_name = 'property_development_reservations' then
	if tg_op = 'UPDATE' then
	  if new.organization_id is not distinct from old.organization_id
	     and new.lead_id is not distinct from old.lead_id then
	    return new;
	  end if;
	end if;

    if new.lead_id is not null
       and not exists (
         select 1
         from public.leads as lead
         where lead.id = new.lead_id
           and lead.organization_id = new.organization_id
       ) then
      raise exception using
        errcode = '23514',
        message = 'property_development_lead_cross_tenant_reference';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_property_development_tenant_scope() OWNER TO postgres;

--
-- Name: enforce_property_location_chain(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_location_chain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_city_name text;
  v_city_uf text;
  v_neighborhood_name text;
  v_neighborhood_city_id uuid;
  v_condominium_city_id uuid;
  v_condominium_neighborhood_id uuid;
  v_ids_changed boolean := true;
begin
  if tg_op = 'UPDATE' then
    v_ids_changed := new.organization_id is distinct from old.organization_id
      or new.city_id is distinct from old.city_id
      or new.neighborhood_id is distinct from old.neighborhood_id
      or new.condominium_id is distinct from old.condominium_id;
  end if;

  if new.condominium_id is not null then
    select condominium.city_id, condominium.neighborhood_id
      into v_condominium_city_id, v_condominium_neighborhood_id
    from public.property_condominiums as condominium
    where condominium.organization_id = new.organization_id
      and condominium.id = new.condominium_id
      and coalesce(condominium.is_active, true)
    for key share;
    if not found then
      raise exception 'invalid or inactive property condominium'
        using errcode = '23514', constraint = 'property_location_hierarchy';
    end if;
    if v_condominium_city_id is not null then
      if new.city_id is null then
        new.city_id := v_condominium_city_id;
      elsif new.city_id <> v_condominium_city_id then
        raise exception 'property condominium does not belong to city'
          using errcode = '23514', constraint = 'property_location_hierarchy';
      end if;
    end if;
    if v_condominium_neighborhood_id is not null then
      if new.neighborhood_id is null then
        new.neighborhood_id := v_condominium_neighborhood_id;
      elsif new.neighborhood_id <> v_condominium_neighborhood_id then
        raise exception 'property condominium does not belong to neighborhood'
          using errcode = '23514', constraint = 'property_location_hierarchy';
      end if;
    end if;
  end if;

  if new.neighborhood_id is not null then
    select neighborhood.city_id, neighborhood.name
      into v_neighborhood_city_id, v_neighborhood_name
    from public.property_neighborhoods as neighborhood
    where neighborhood.organization_id = new.organization_id
      and neighborhood.id = new.neighborhood_id
      and coalesce(neighborhood.is_active, true)
    for key share;
    if not found then
      raise exception 'invalid or inactive property neighborhood'
        using errcode = '23514', constraint = 'property_location_hierarchy';
    end if;
    if v_neighborhood_city_id is null then
      raise exception 'property neighborhood has no city'
        using errcode = '23514', constraint = 'property_neighborhood_city_required';
    end if;
    if new.city_id is null then
      new.city_id := v_neighborhood_city_id;
    elsif new.city_id <> v_neighborhood_city_id then
      raise exception 'property neighborhood does not belong to city'
        using errcode = '23514', constraint = 'property_location_hierarchy';
    end if;
    new.bairro := v_neighborhood_name;
  elsif v_ids_changed then
    -- Clearing a catalog link without a replacement must not keep its old
    -- projected name. A new manual value (including one from CEP) is retained.
    if tg_op = 'UPDATE'
      and old.neighborhood_id is not null
      and new.bairro is not distinct from old.bairro then
      new.bairro := null;
    else
      new.bairro := nullif(btrim(new.bairro), '');
    end if;
  end if;

  if new.city_id is not null then
    select city.name, city.uf
      into v_city_name, v_city_uf
    from public.property_cities as city
    where city.organization_id = new.organization_id
      and city.id = new.city_id
      and coalesce(city.is_active, true)
    for key share;
    if not found then
      raise exception 'invalid or inactive property city'
        using errcode = '23514', constraint = 'property_location_hierarchy';
    end if;
    new.cidade := v_city_name;
    new.uf := v_city_uf;
  elsif v_ids_changed then
    if tg_op = 'UPDATE'
      and old.city_id is not null
      and new.cidade is not distinct from old.cidade
      and new.uf is not distinct from old.uf then
      new.cidade := null;
      new.uf := null;
    else
      new.cidade := nullif(btrim(new.cidade), '');
      new.uf := nullif(upper(btrim(new.uf)), '');
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION private.enforce_property_location_chain() OWNER TO postgres;

--
-- Name: enforce_property_photo_asset_capacity(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_photo_asset_capacity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  excluded_asset_id uuid;
  current_photo_count integer;
  old_is_active_photo boolean := false;
  new_is_active_photo boolean := false;
begin
  new_is_active_photo := new.asset_type = 'photo'
    and coalesce(new.metadata->>'integration_retired', 'false') <> 'true';

  if not new_is_active_photo then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    old_is_active_photo := old.asset_type = 'photo'
      and coalesce(old.metadata->>'integration_retired', 'false') <> 'true';
    excluded_asset_id := old.id;

    if old_is_active_photo
       and (old.organization_id, old.property_id)
         is not distinct from (new.organization_id, new.property_id) then
      return new;
    end if;
  end if;

  perform 1
  from public.properties as property
  where property.organization_id = new.organization_id
    and property.id = new.property_id
  for update;
  if not found then
    raise exception 'property asset parent does not exist'
      using errcode = '23503', constraint = 'property_assets_property_fkey';
  end if;

  -- Serialize before checking the unique locator. Once a concurrent insertion
  -- releases the parent lock, this branch sees its committed row and lets an
  -- idempotent INSERT ... ON CONFLICT reach the locator constraint even when
  -- the active gallery is now full.
  if tg_op = 'INSERT'
     and new.external_url is not null
     and exists (
       select 1
       from public.property_assets as existing_asset
       where existing_asset.property_id = new.property_id
         and existing_asset.asset_type = 'photo'
         and existing_asset.external_url = new.external_url
     ) then
    return new;
  end if;

  select pg_catalog.count(*)::integer
    into current_photo_count
  from public.property_assets as asset
  where asset.organization_id = new.organization_id
    and asset.property_id = new.property_id
    and asset.asset_type = 'photo'
    and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true'
    and (excluded_asset_id is null or asset.id <> excluded_asset_id);

  if current_photo_count >= 20 then
    raise exception 'a property can have at most 20 active photos'
      using errcode = '23514', constraint = 'property_assets_photo_capacity';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_property_photo_asset_capacity() OWNER TO postgres;

--
-- Name: enforce_property_publication_actor_scope(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_publication_actor_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_column text;
  actor_text text;
  actor_id uuid;
begin
  foreach actor_column in array array[
    'created_by',
    'updated_by',
    'requested_by'
  ]::text[]
  loop
    actor_text := nullif(btrim(to_jsonb(new) ->> actor_column), '');
    if actor_text is null then
      continue;
    end if;

    actor_id := private.safe_uuid(actor_text);
    if actor_id is null
       or not private.property_user_belongs_to_organization(
         new.organization_id,
         actor_id
       ) then
      raise exception using
        errcode = '23514',
        message = format(
          'property_publication_user_cross_tenant_reference:%s',
          actor_column
        );
    end if;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_property_publication_actor_scope() OWNER TO postgres;

--
-- Name: enforce_property_publication_current_version(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_publication_current_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.current_version > 0
     and not exists (
       select 1
       from public.property_channel_publication_versions as version
       where version.organization_id = new.organization_id
         and version.publication_id = new.id
         and version.version = new.current_version
     ) then
    raise exception using
      errcode = '23503',
      message = 'property_publication_current_version_missing';
  end if;

  return new;
end;
$$;


