--
-- Name: enforce_property_publication_revision_monotonic(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_publication_revision_monotonic() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.updated_at := greatest(
    old.updated_at + interval '1 microsecond',
    new.updated_at,
    clock_timestamp()
  );
  return new;
end;
$$;


