--
-- Name: enforce_property_user_tenant_scope(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_property_user_tenant_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  reference_text text;
  reference_id uuid;
  locked_user_organization_id uuid;
  locked_user_role text;
  locked_membership_id uuid;
  allow_legacy_text boolean := tg_nargs > 1 and tg_argv[1] = 'allow_legacy_text';
begin
  if tg_op = 'UPDATE'
     and new.organization_id is not distinct from old.organization_id
     and (to_jsonb(new) ->> tg_argv[0]) is not distinct from (to_jsonb(old) ->> tg_argv[0]) then
    return new;
  end if;

  reference_text := nullif(btrim(to_jsonb(new) ->> tg_argv[0]), '');
  if reference_text is null then
    return new;
  end if;

  reference_id := private.safe_uuid(reference_text);
  if reference_id is null and allow_legacy_text then
    return new;
  end if;

  if reference_id is null then
    raise exception using
      errcode = '23514',
      message = format(
        'Referencia de usuario %s pertence a outra organizacao ou nao existe.',
        tg_argv[0]
      );
  end if;

  select app_user.organization_id, coalesce(app_user.role, '')
  into locked_user_organization_id, locked_user_role
  from public.users as app_user
  where app_user.id = reference_id
    and coalesce(app_user.is_active, true) = true
  for key share;

  if not found then
    raise exception using
      errcode = '23514',
      message = format(
        'Referencia de usuario %s pertence a outra organizacao ou nao existe.',
        tg_argv[0]
      );
  end if;

  if locked_user_organization_id = new.organization_id
     or locked_user_role = 'super_admin'
     or exists (
       select 1
       from public.user_roles as global_role
       where global_role.user_id = reference_id
         and global_role.role = 'super_admin'
     ) then
    return new;
  end if;

  select membership.id
  into locked_membership_id
  from public.organization_members as membership
  where membership.organization_id = new.organization_id
    and membership.user_id = reference_id
    and coalesce(membership.is_active, false) = true
    and membership.deleted_at is null
  for key share;

  if locked_membership_id is null then
    raise exception using
      errcode = '23514',
      message = format(
        'Referencia de usuario %s pertence a outra organizacao ou nao existe.',
        tg_argv[0]
      );
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_property_user_tenant_scope() OWNER TO postgres;

--
-- Name: enforce_provider_property_asset_archive(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_provider_property_asset_archive() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(old.metadata->>'integration_managed', 'false') <> 'true' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if exists (
      select 1
      from public.organizations as organization
      where organization.id = old.organization_id
    ) and exists (
      select 1
      from public.properties as property
      where property.organization_id = old.organization_id
        and property.id = old.property_id
    ) then
      raise exception 'integration-managed property assets require logical retirement'
        using errcode = '23514',
          constraint = 'property_assets_integration_archive_guard';
    end if;
    return old;
  end if;

  if new.id is distinct from old.id
     or new.organization_id is distinct from old.organization_id
     or new.property_id is distinct from old.property_id
     or new.asset_type is distinct from old.asset_type
     or new.visibility is distinct from old.visibility
     or new.storage_path is distinct from old.storage_path
     or new.external_url is distinct from old.external_url
     or new.checksum_sha256 is distinct from old.checksum_sha256
     or coalesce(new.metadata->>'integration_managed', 'false') <> 'true' then
    raise exception 'integration-managed property asset source is immutable'
      using errcode = '23514',
        constraint = 'property_assets_integration_archive_guard';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_provider_property_asset_archive() OWNER TO postgres;

--
-- Name: enforce_real_estate_tenant_scope(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_real_estate_tenant_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  referenced_organization_id uuid;
  referenced_user_column text;
  referenced_user_text text;
  referenced_user_id uuid;
begin
  if tg_table_name in (
    'property_offers',
    'property_ownerships',
    'property_assets',
    'property_keys'
  ) then
    select property.organization_id
    into referenced_organization_id
    from public.properties as property
    where property.id = new.property_id;

    if referenced_organization_id is not null
       and referenced_organization_id is distinct from new.organization_id then
      raise exception using
        errcode = '23514',
        message = 'real_estate_property_cross_tenant_reference';
    end if;
  end if;

  if tg_table_name = 'property_ownerships' then
    select owner.organization_id
    into referenced_organization_id
    from public.property_owners as owner
    where owner.id = new.owner_id;

    if referenced_organization_id is not null
       and referenced_organization_id is distinct from new.organization_id then
      raise exception using
        errcode = '23514',
        message = 'real_estate_owner_cross_tenant_reference';
    end if;
  end if;

  if tg_table_name = 'property_key_movements' then
    select property_key.organization_id
    into referenced_organization_id
    from public.property_keys as property_key
    where property_key.id = new.property_key_id;

    if referenced_organization_id is not null
       and referenced_organization_id is distinct from new.organization_id then
      raise exception using
        errcode = '23514',
        message = 'real_estate_key_cross_tenant_reference';
    end if;
  end if;

  foreach referenced_user_column in array array[
    'created_by',
    'updated_by',
    'holder_user_id'
  ]::text[]
  loop
    referenced_user_text := nullif(
      btrim(to_jsonb(new) ->> referenced_user_column),
      ''
    );

    if referenced_user_text is null then
      continue;
    end if;

    referenced_user_id := private.safe_uuid(referenced_user_text);
    if referenced_user_id is null
       or not private.property_user_belongs_to_organization(
         new.organization_id,
         referenced_user_id
       ) then
      raise exception using
        errcode = '23514',
        message = format(
          'real_estate_user_cross_tenant_reference:%s',
          referenced_user_column
        );
    end if;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION private.enforce_real_estate_tenant_scope() OWNER TO postgres;

--
-- Name: enforce_tenant_reference(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_tenant_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  reference_id uuid;
  reference_organization_id uuid;
begin
  if tg_op = 'UPDATE'
     and new.organization_id is not distinct from old.organization_id
     and (to_jsonb(new) ->> tg_argv[1]) is not distinct from (to_jsonb(old) ->> tg_argv[1]) then
    return new;
  end if;

  reference_id := nullif(to_jsonb(new) ->> tg_argv[1], '')::uuid;
  if reference_id is null then
    return new;
  end if;

  execute format(
    'select organization_id from public.%I where id = $1',
    tg_argv[0]
  )
  into reference_organization_id
  using reference_id;

  if reference_organization_id is not null
     and new.organization_id is distinct from reference_organization_id then
    raise exception using
      errcode = '23514',
      message = format(
        'Referencia %s.%s pertence a outra organizacao.',
        tg_argv[0],
        tg_argv[1]
      );
  end if;

  return new;
end;
$_$;


ALTER FUNCTION private.enforce_tenant_reference() OWNER TO postgres;

--
-- Name: enforce_whatsapp_conversation_active_binding_consistency(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_whatsapp_conversation_active_binding_consistency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from public.whatsapp_conversations as conversation
    join public.whatsapp_conversation_lead_bindings as binding
      on binding.conversation_id = conversation.id
     and binding.active_to is null
    where conversation.id = new.id
      and (
        conversation.organization_id is distinct from binding.organization_id
        or conversation.session_id is distinct from binding.session_id
        or conversation.lead_id is distinct from binding.lead_id
      )
  ) then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_conversation_active_binding_mismatch';
  end if;

  return null;
end;
$$;


ALTER FUNCTION private.enforce_whatsapp_conversation_active_binding_consistency() OWNER TO postgres;

--
-- Name: enforce_whatsapp_conversation_lead_binding(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_whatsapp_conversation_lead_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
begin
  if tg_op = 'UPDATE' then
    if new.organization_id is distinct from old.organization_id
       or new.conversation_id is distinct from old.conversation_id
       or not (
         new.session_id is not distinct from old.session_id
         or (old.session_id is not null and new.session_id is null)
       )
       or new.lead_id is distinct from old.lead_id
       or not (
         new.previous_lead_id is not distinct from old.previous_lead_id
         or (old.previous_lead_id is not null and new.previous_lead_id is null)
       )
       or not (
         new.assigned_user_id is not distinct from old.assigned_user_id
         or (old.assigned_user_id is not null and new.assigned_user_id is null)
       )
       or new.provider_message_id is distinct from old.provider_message_id
       or new.changed is distinct from old.changed
       or new.stale is distinct from old.stale
       or new.active_from is distinct from old.active_from
       or new.created_at is distinct from old.created_at
       or not (
         new.active_to is not distinct from old.active_to
         or (
           old.active_to is null
           and new.active_to is not null
           and new.active_to >= old.active_from
         )
       ) then
      raise exception using
        errcode = '23514',
        message = 'whatsapp_conversation_lead_binding_immutable';
    end if;
    return new;
  end if;

  select conversation.*
  into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = new.conversation_id;

  if not found or v_conversation.organization_id is distinct from new.organization_id then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_conversation_tenant_mismatch';
  end if;

  if v_conversation.session_id is distinct from new.session_id then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_session_mismatch';
  end if;

  if not exists (
    select 1
    from public.leads as lead
    where lead.id = new.lead_id
      and lead.organization_id = new.organization_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_lead_tenant_mismatch';
  end if;

  if new.previous_lead_id is not null
     and not exists (
       select 1
       from public.leads as lead
       where lead.id = new.previous_lead_id
         and lead.organization_id = new.organization_id
     ) then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_previous_lead_tenant_mismatch';
  end if;

  if new.assigned_user_id is not null
     and not exists (
       select 1
       from public.organization_members as membership
       join public.users as app_user
         on app_user.id = membership.user_id
        and app_user.is_active = true
       where membership.organization_id = new.organization_id
         and membership.user_id = new.assigned_user_id
         and membership.is_active = true
         and membership.deleted_at is null
     ) then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_assignee_tenant_mismatch';
  end if;

  new.provider_message_id := nullif(btrim(new.provider_message_id), '');
  return new;
end;
$$;


ALTER FUNCTION private.enforce_whatsapp_conversation_lead_binding() OWNER TO postgres;

--
-- Name: enforce_whatsapp_media_processing_slot(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_whatsapp_media_processing_slot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.status is distinct from 'processing' then
    -- Rolling replicas from the serialized worker do not know this column.
    -- Clear it on their completion/retry writes so they remain compatible.
    new.processing_slot := null;
  elsif new.processing_slot is null or new.processing_slot not between 1 and 16 then
    raise exception using
      errcode = '23514',
      constraint = 'media_jobs_processing_slot_check',
      message = 'processing WhatsApp media jobs require a slot between 1 and 16';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.enforce_whatsapp_media_processing_slot() OWNER TO postgres;

