--
-- Name: enqueue_lead_gamification(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_lead_gamification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  beneficiary_id uuid;
  action_key text;
begin
  if tg_op = 'INSERT' then
    if lower(coalesce(new.source, 'manual')) = 'manual' then
      action_key := 'lead_created_manual';
      beneficiary_id := coalesce(new.created_by, new.assigned_user_id);
    else
      action_key := 'lead_created';
      beneficiary_id := coalesce(new.assigned_user_id, new.created_by);
    end if;

    perform private.enqueue_gamification_outbox(
      new.organization_id,
      beneficiary_id,
      action_key,
      1,
      new.id::text,
      'leads',
      jsonb_build_object('lead_id', new.id::text, 'producer', 'leads_insert')
    );
  elsif tg_op = 'UPDATE' and old.deal_status is distinct from new.deal_status then
    beneficiary_id := new.assigned_user_id;
    if new.deal_status = 'won' then
      perform private.enqueue_gamification_outbox(
        new.organization_id,
        beneficiary_id,
        'sale_closed',
        1,
        new.id::text,
        'leads',
        jsonb_build_object('lead_id', new.id::text, 'producer', 'leads_deal_status')
      );
    elsif old.deal_status = 'lost' and new.deal_status = 'open' then
      perform private.enqueue_gamification_outbox(
        new.organization_id,
        beneficiary_id,
        'lost_lead_recovered',
        1,
        new.id::text,
        'leads',
        jsonb_build_object('lead_id', new.id::text, 'producer', 'leads_deal_status')
      );
    end if;
  end if;

  return new;
exception
  when others then
    raise warning 'gamification producer % skipped: [%] %', tg_name, sqlstate, sqlerrm;
    return new;
end;
$$;


ALTER FUNCTION private.enqueue_lead_gamification() OWNER TO postgres;

--
-- Name: enqueue_managed_whatsapp_auto_reply_from_entry(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_managed_whatsapp_auto_reply_from_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_assigned_user_id uuid;
  v_assigned_user_id_text text;
  v_distribution_event_id text;
begin
  -- Attribution enrichment and unrelated metadata repairs may update the same
  -- historical entry later. Only the intake-result transition produced by the
  -- canonical managed intake is allowed to create a new acknowledgement.
  if old.metadata->'intake_result' is not distinct from new.metadata->'intake_result'
     or new.entry_type <> 'initial'
     or new.provider <> 'whatsapp'
     or lower(btrim(coalesce(
       new.metadata->>'managed_whatsapp_message_distribution',
       'false'
     ))) not in ('true', '1', 'yes')
     or lower(coalesce(
       new.metadata->'intake_result'->>'handled',
       'false'
      )) not in ('true', '1', 'yes')
     or lower(coalesce(
       new.metadata->'intake_result'->>'success',
       'false'
     )) not in ('true', '1', 'yes')
     or lower(coalesce(
       new.metadata->'intake_result'->>'distribution_pending',
       'false'
     )) in ('true', '1', 'yes')
     or lower(coalesce(
       new.metadata->'intake_result'->>'applied_to_current_state',
       'true'
     )) not in ('true', '1', 'yes') then
    return new;
  end if;

  v_assigned_user_id_text := btrim(coalesce(
    new.metadata->'intake_result'->>'assigned_user_id',
    ''
  ));
  if v_assigned_user_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return new;
  end if;
  v_assigned_user_id := v_assigned_user_id_text::uuid;
  v_distribution_event_id := btrim(coalesce(
    new.metadata->'intake_result'->>'distribution_event_id',
    ''
  ));
  if v_distribution_event_id = '' then
    return new;
  end if;

  perform public.enqueue_managed_whatsapp_distribution_auto_reply(
    new.organization_id,
    new.id,
    v_assigned_user_id,
    v_distribution_event_id
  );
  return new;
end;
$_$;


ALTER FUNCTION private.enqueue_managed_whatsapp_auto_reply_from_entry() OWNER TO postgres;

--
-- Name: enqueue_managed_whatsapp_initial_distribution(uuid, uuid, uuid, uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_managed_whatsapp_initial_distribution(p_organization_id uuid, p_round_robin_id uuid, p_lead_id uuid, p_entry_event_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp(), p_allow_assigned_redistribution boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_settings jsonb;
  v_timeout_minutes integer;
  v_warning_minutes integer;
  v_max_attempts integer;
  v_job_id uuid;
  v_job_assigned_user_id uuid;
  v_allow_assigned_redistribution boolean := false;
begin
  select lead.assigned_user_id
    into v_job_assigned_user_id
    from public.leads as lead
   where lead.organization_id = p_organization_id
     and lead.id = p_lead_id
   for no key update;

  if not found then
    return null;
  end if;

  v_allow_assigned_redistribution :=
    coalesce(p_allow_assigned_redistribution, false)
    and v_job_assigned_user_id is not null;

  select coalesce(queue.settings, '{}'::jsonb)
    into v_settings
    from public.round_robins as queue
   where queue.organization_id = p_organization_id
     and queue.id = p_round_robin_id
     and coalesce(queue.is_active, true) = true;

  if not found then
    return null;
  end if;

  v_timeout_minutes := least(10080, greatest(1, coalesce(
    case when coalesce(v_settings->>'redistribution_timeout_minutes', '') ~ '^[0-9]{1,9}$'
      then (v_settings->>'redistribution_timeout_minutes')::integer end,
    20
  )));
  v_warning_minutes := greatest(0, coalesce(
    case when coalesce(v_settings->>'redistribution_warning_minutes', '') ~ '^[0-9]{1,9}$'
      then (v_settings->>'redistribution_warning_minutes')::integer end,
    5
  ));
  v_warning_minutes := least(v_warning_minutes, v_timeout_minutes - 1);
  v_max_attempts := least(1000, greatest(0, coalesce(
    case when coalesce(v_settings->>'redistribution_max_attempts', '') ~ '^[0-9]{1,9}$'
      then (v_settings->>'redistribution_max_attempts')::integer end,
    10
  )));

  insert into public.lead_redistribution_jobs (
    organization_id,
    lead_id,
    round_robin_id,
    original_assigned_user_id,
    current_assigned_user_id,
    max_attempts,
    timeout_minutes,
    warning_minutes,
    enrolled_at,
    due_at,
    warning_due_at,
    metadata
  )
  values (
    p_organization_id,
    p_lead_id,
    p_round_robin_id,
    case when v_allow_assigned_redistribution then v_job_assigned_user_id else null end,
    case when v_allow_assigned_redistribution then v_job_assigned_user_id else null end,
    v_max_attempts,
    v_timeout_minutes,
    v_warning_minutes,
    coalesce(p_now, clock_timestamp()),
    coalesce(p_now, clock_timestamp()),
    null,
    jsonb_build_object(
      'source', 'managed_whatsapp',
      'initial_distribution_pending', true,
      'allow_assigned_redistribution', v_allow_assigned_redistribution,
      'entry_event_id', p_entry_event_id
    )
  )
  on conflict do nothing
  returning id into v_job_id;

  if v_job_id is null then
    select job.id
      into v_job_id
      from public.lead_redistribution_jobs as job
     where job.organization_id = p_organization_id
       and job.lead_id = p_lead_id
       and job.status in ('pending', 'warning_sent')
     order by job.created_at, job.id
     limit 1;
  end if;

  return v_job_id;
end;
$_$;


ALTER FUNCTION private.enqueue_managed_whatsapp_initial_distribution(p_organization_id uuid, p_round_robin_id uuid, p_lead_id uuid, p_entry_event_id uuid, p_now timestamp with time zone, p_allow_assigned_redistribution boolean) OWNER TO postgres;

--
-- Name: enqueue_meta_crm_funnel_event(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_meta_crm_funnel_event(p_funnel_event_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  target record;
begin
  select
    funnel.id as funnel_event_id,
    funnel.organization_id,
    funnel.lead_id,
    funnel.lead_entry_event_id,
    funnel.event_kind,
    case funnel.event_kind
      when 'initial' then 1
      when 'qualified' then 2
      when 'converted' then 3
    end as event_sequence,
    funnel.occurred_at,
    entry.provider_event_id as leadgen_id,
    integration.id as integration_id,
    integration.crm_dataset_id as dataset_id
  into target
  from public.lead_funnel_events as funnel
  join public.lead_entry_events as entry
    on entry.id = funnel.lead_entry_event_id
   and entry.organization_id = funnel.organization_id
   and entry.lead_id = funnel.lead_id
  join public.meta_integrations as integration
    on integration.organization_id = funnel.organization_id
   and coalesce(integration.is_connected, false) = true
   and coalesce(integration.conversion_feedback_enabled, false) = true
   and integration.conversion_feedback_status = 'active'
   and integration.conversion_feedback_activated_at is not null
   and integration.crm_dataset_id is not null
   and integration.crm_dataset_access_token_secret_ref is not null
   and (
     nullif(entry.metadata->>'integration_id', '') = integration.id::text
     or (
       nullif(entry.metadata->>'integration_id', '') is null
       and nullif(entry.page_id, '') = integration.page_id
     )
     )
  join private.meta_feedback_module_activations as module_activation
    on module_activation.organization_id = funnel.organization_id
  where funnel.id = p_funnel_event_id
    and funnel.created_at >= integration.conversion_feedback_activated_at
    and funnel.occurred_at >= clock_timestamp() - interval '7 days'
    and funnel.metadata->>'historical_cutover' is distinct from 'true'
    and nullif(funnel.metadata->>'meta_feedback_activation_id', '')
      = module_activation.activation_id::text
    and entry.provider = 'meta'
    and coalesce(entry.is_countable, true) = true
    and entry.provider_event_id ~ '^[0-9]{15,17}$'
  order by
    case
      when nullif(entry.metadata->>'integration_id', '') = integration.id::text
        then 0
      else 1
    end,
    integration.created_at,
    integration.id
  limit 1;

  if target.funnel_event_id is null then
    return;
  end if;

  -- Never create a later delivery without the complete earlier delivery
  -- chain for this exact tenant and destination. A dead predecessor is kept
  -- in the chain so the worker can cascade a visible terminal reason.
  if (
    select count(*)
    from public.meta_crm_event_outbox as predecessor
    where predecessor.organization_id = target.organization_id
      and predecessor.lead_entry_event_id = target.lead_entry_event_id
      and predecessor.integration_id is not distinct from target.integration_id
      and predecessor.dataset_id = target.dataset_id
      and predecessor.event_sequence < target.event_sequence
  ) <> (target.event_sequence - 1)::bigint then
    return;
  end if;

  insert into public.meta_crm_event_outbox (
    organization_id,
    funnel_event_id,
    lead_id,
    lead_entry_event_id,
    integration_id,
    dataset_id,
    leadgen_id,
    event_kind,
    event_name,
    event_id,
    event_time
  )
  values (
    target.organization_id,
    target.funnel_event_id,
    target.lead_id,
    target.lead_entry_event_id,
    target.integration_id,
    target.dataset_id,
    target.leadgen_id,
    target.event_kind,
    case target.event_kind
      when 'initial' then 'VimobInitialLead'
      when 'qualified' then 'VimobQualifiedLead'
      else 'VimobConvertedLead'
    end,
    format(
      'vimob:%s:%s:%s',
      target.organization_id::text,
      target.lead_entry_event_id::text,
      target.event_kind
    ),
    target.occurred_at
  )
  on conflict (funnel_event_id) do nothing;
end;
$_$;


ALTER FUNCTION private.enqueue_meta_crm_funnel_event(p_funnel_event_id uuid) OWNER TO postgres;

--
-- Name: enqueue_outgoing_lead_webhooks(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_outgoing_lead_webhooks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  v_event_type text;
  v_occurred_at timestamptz;
begin
  v_event_type := case new.entry_type
    when 'initial' then 'lead.created'
    when 'reentry' then 'lead.reentered'
    else null
  end;

  if v_event_type is null or not coalesce(new.is_countable, true) then
    delete from private.webhook_delivery_outbox delivery
    where delivery.event_key = 'lead-entry:' || new.id::text
      and delivery.organization_id = new.organization_id
      and delivery.status = 'pending'
      and delivery.attempts = 0;
    return new;
  end if;

  v_occurred_at := coalesce(new.occurred_at, new.created_at, clock_timestamp());

  insert into private.webhook_delivery_outbox (
    organization_id,
    webhook_id,
    lead_id,
    event_type,
    event_key,
    payload
  )
  select
    new.organization_id,
    webhook.id,
    new.lead_id,
    v_event_type,
    'lead-entry:' || new.id::text,
    jsonb_build_object(
      'id', 'lead-entry:' || new.id::text,
      'type', v_event_type,
      'occurred_at', to_char(
        v_occurred_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ),
      'data', jsonb_build_object(
        'lead', jsonb_strip_nulls(jsonb_build_object(
          'id', lead.id,
          'name', left(lead.name, 180),
          'email', left(lead.email, 320),
          'phone', left(lead.phone, 32),
          'message', left(lead.message, 10000),
          'property_id', coalesce(lead.interest_property_id, lead.property_id),
          'source', left(lead.source, 100)
        )),
        'entry', jsonb_strip_nulls(jsonb_build_object(
          'id', new.id,
          'entry_type', new.entry_type,
          'provider', left(new.provider, 100),
          'provider_event_id', left(new.provider_event_id, 512),
          'source_detail', left(new.source_detail, 500)
        ))
      )
    )
  from public.webhooks_integrations webhook
  join public.organizations organization
    on organization.id = webhook.organization_id
   and coalesce(organization.is_active, true) = true
  join public.leads lead
    on lead.id = new.lead_id
   and lead.organization_id = new.organization_id
  where webhook.organization_id = new.organization_id
    and webhook.type = 'outgoing'
    and webhook.is_active = true
    and webhook.webhook_url is not null
    and v_event_type = any(webhook.trigger_events)
    and exists (
      select 1
      from public.organization_modules module
      where module.organization_id = new.organization_id
        and lower(trim(module.module_name)) = 'webhooks'
        and coalesce(module.is_enabled, false) = true
    )
    and (
      (lower(trim(organization.subscription_type)) = 'free'
        and lower(trim(organization.subscription_status)) = 'active')
      or (lower(trim(organization.subscription_type)) = 'trial'
        and lower(trim(organization.subscription_status)) = 'trial'
        and organization.trial_ends_at > clock_timestamp())
      or (lower(trim(organization.subscription_type)) = 'paid' and (
        lower(trim(organization.subscription_status)) = 'active'
        or (lower(trim(organization.subscription_status)) in ('overdue', 'past_due')
          and organization.billing_grace_until > clock_timestamp())
      ))
    )
  on conflict (webhook_id, event_key) do update
  set event_type = excluded.event_type,
      lead_id = excluded.lead_id,
      payload = excluded.payload,
      updated_at = clock_timestamp()
  where webhook_delivery_outbox.status = 'pending'
    and webhook_delivery_outbox.attempts = 0;

  return new;
end;
$$;


ALTER FUNCTION private.enqueue_outgoing_lead_webhooks() OWNER TO postgres;

--
-- Name: FUNCTION enqueue_outgoing_lead_webhooks(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.enqueue_outgoing_lead_webhooks() IS 'Transactionally fans canonical lead-entry events into the tenant webhook outbox.';


--
-- Name: enqueue_property_gamification(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_property_gamification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.enqueue_gamification_outbox(
    new.organization_id,
    coalesce(new.created_by, new.responsible_user_id),
    'property_created',
    1,
    new.id::text,
    'properties',
    jsonb_build_object('property_id', new.id::text, 'producer', 'properties_insert')
  );
  return new;
exception
  when others then
    raise warning 'gamification producer % skipped: [%] %', tg_name, sqlstate, sqlerrm;
    return new;
end;
$$;


ALTER FUNCTION private.enqueue_property_gamification() OWNER TO postgres;

--
-- Name: enqueue_prospecting_report_gamification(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_prospecting_report_gamification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payload jsonb := to_jsonb(new);
  organization_id uuid;
  beneficiary_id uuid;
  report_reference text;
begin
  begin
    organization_id := nullif(payload->>'organization_id', '')::uuid;
    beneficiary_id := coalesce(
      nullif(payload->>'user_id', '')::uuid,
      nullif(payload->>'reported_by', '')::uuid,
      nullif(payload->>'created_by', '')::uuid,
      nullif(payload->>'actor_user_id', '')::uuid
    );
  exception when invalid_text_representation then
    return new;
  end;

  report_reference := nullif(payload->>'id', '');
  perform private.enqueue_gamification_outbox(
    organization_id,
    beneficiary_id,
    'prospecting_report',
    1,
    report_reference,
    'prospecting',
    jsonb_build_object('report_id', report_reference, 'producer', tg_table_name)
  );
  return new;
exception
  when others then
    raise warning 'gamification producer % skipped: [%] %', tg_name, sqlstate, sqlerrm;
    return new;
end;
$$;


ALTER FUNCTION private.enqueue_prospecting_report_gamification() OWNER TO postgres;

--
-- Name: enqueue_queue_pool_alert(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_queue_pool_alert(p_org uuid, p_lead uuid, p_episode uuid, p_revision bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r private.queue_lead_runtime%rowtype; inserted integer;
begin
  select * into r from private.queue_lead_runtime where organization_id=p_org and lead_id=p_lead
    and episode_id=p_episode and revision=p_revision and state in ('pool_waiting','pool_ready','limit_exhausted');
  if not found or not exists(select 1 from public.round_robins q where q.organization_id=p_org and q.id=r.round_robin_id
    and q.settings->'pool_notifications'->'enabled'='true'::jsonb) then return 0; end if;
  with recipients as (
    insert into private.queue_pool_alert_throttle as throttle(organization_id,round_robin_id,user_id,last_alerted_at)
      select p_org,r.round_robin_id,om.user_id,clock_timestamp() from public.organization_members om
      where om.organization_id=p_org and om.is_active and om.deleted_at is null
        and private.queue_pool_alert_audience(p_org,r.round_robin_id,om.user_id)
      on conflict(organization_id,round_robin_id,user_id) do update set last_alerted_at=excluded.last_alerted_at
        where throttle.last_alerted_at<=excluded.last_alerted_at-interval '5 minutes'
      returning user_id
  ) insert into public.notifications(organization_id,user_id,lead_id,type,title,content,body,metadata,channel,target_url)
  select p_org,om.user_id,p_lead,'queue_pool_available','Lead disponível na fila','Um lead está disponível no bolsão da fila.',
    'Um lead está disponível no bolsão da fila.',private.queue_runtime_dispatch_metadata(jsonb_build_object('event_key','queue_pool_available','round_robin_id',r.round_robin_id,
      'episode_id',p_episode,'revision',p_revision,'dedupe_key','queue_pool_available:'||p_episode::text||':'||p_revision::text||':'||om.user_id::text)),
    'in_app','/crm/pipelines?lead='||p_lead::text
  from recipients om where true
    and not exists(select 1 from public.notifications n where n.organization_id=p_org and n.user_id=om.user_id
      and n.metadata->>'dedupe_key'='queue_pool_available:'||p_episode::text||':'||p_revision::text||':'||om.user_id::text);
  get diagnostics inserted=row_count; return inserted;
end;
$$;


ALTER FUNCTION private.enqueue_queue_pool_alert(p_org uuid, p_lead uuid, p_episode uuid, p_revision bigint) OWNER TO postgres;

--
-- Name: enqueue_recent_meta_crm_facts(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_recent_meta_crm_facts(p_organization_id uuid, p_integration_id uuid, p_test_event_code text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  replay_now timestamptz := clock_timestamp();
  normalized_test_event_code text := nullif(btrim(p_test_event_code), '');
  queued_count integer := 0;
begin
  if p_organization_id is null or p_integration_id is null then
    raise exception using
      errcode = '22023',
      message = 'Organization and Meta integration are required';
  end if;

  if normalized_test_event_code is not null
     and (
       length(normalized_test_event_code) > 255
       or normalized_test_event_code ~ '[[:cntrl:]]'
     ) then
    raise exception using
      errcode = '22023',
      message = 'Meta test event code is invalid';
  end if;

  if not exists (
    select 1
    from public.meta_integrations as integration
    join private.meta_feedback_module_activations as module_activation
      on module_activation.organization_id = integration.organization_id
    where integration.id = p_integration_id
      and integration.organization_id = p_organization_id
      and coalesce(integration.is_connected, false) = true
      and coalesce(integration.conversion_feedback_enabled, false) = true
      and integration.conversion_feedback_status = 'active'
      and integration.conversion_feedback_activated_at is not null
      and integration.crm_dataset_id is not null
      and integration.crm_dataset_access_token_secret_ref is not null
  ) then
    raise exception using
      errcode = '23514',
      message = 'Meta conversion feedback must be active before replaying recent facts';
  end if;

  with target_integration as (
    select
      integration.id,
      integration.organization_id,
      integration.page_id,
      integration.crm_dataset_id
    from public.meta_integrations as integration
    join private.meta_feedback_module_activations as module_activation
      on module_activation.organization_id = integration.organization_id
    where integration.id = p_integration_id
      and integration.organization_id = p_organization_id
      and coalesce(integration.is_connected, false) = true
      and coalesce(integration.conversion_feedback_enabled, false) = true
      and integration.conversion_feedback_status = 'active'
      and integration.conversion_feedback_activated_at is not null
      and integration.crm_dataset_id is not null
      and integration.crm_dataset_access_token_secret_ref is not null
  ),
  valid_facts as (
    select
      funnel.id as funnel_event_id,
      funnel.organization_id,
      funnel.lead_id,
      funnel.lead_entry_event_id,
      funnel.event_kind,
      case funnel.event_kind
        when 'initial' then 1
        when 'qualified' then 2
        when 'converted' then 3
      end as event_sequence,
      funnel.occurred_at,
      entry.provider_event_id as leadgen_id,
      integration.id as integration_id,
      integration.crm_dataset_id as dataset_id
    from target_integration as integration
    join public.lead_entry_events as entry
      on entry.organization_id = integration.organization_id
     and entry.provider = 'meta'
     and coalesce(entry.is_countable, true) = true
     and entry.provider_event_id ~ '^[0-9]{15,17}$'
     and entry.occurred_at >= replay_now - interval '7 days'
     and entry.occurred_at <= replay_now
     and (
       nullif(entry.metadata->>'integration_id', '') = integration.id::text
       or (
         nullif(entry.metadata->>'integration_id', '') is null
         and nullif(entry.page_id, '') = integration.page_id
       )
     )
    join public.lead_funnel_events as funnel
      on funnel.organization_id = entry.organization_id
     and funnel.lead_id = entry.lead_id
     and funnel.lead_entry_event_id = entry.id
     and funnel.occurred_at >= entry.occurred_at
     and funnel.occurred_at <= replay_now
  ),
  contiguous_facts as (
    select fact.*
    from valid_facts as fact
    where fact.event_sequence = 1
       or (
         fact.event_sequence = 2
         and exists (
           select 1
           from valid_facts as initial_fact
           where initial_fact.organization_id = fact.organization_id
             and initial_fact.lead_entry_event_id = fact.lead_entry_event_id
             and initial_fact.event_sequence = 1
             and initial_fact.occurred_at <= fact.occurred_at
         )
       )
       or (
         fact.event_sequence = 3
         and exists (
           select 1
           from valid_facts as qualified_fact
           where qualified_fact.organization_id = fact.organization_id
             and qualified_fact.lead_entry_event_id = fact.lead_entry_event_id
             and qualified_fact.event_sequence = 2
             and qualified_fact.occurred_at <= fact.occurred_at
             and exists (
               select 1
               from valid_facts as initial_fact
               where initial_fact.organization_id = qualified_fact.organization_id
                 and initial_fact.lead_entry_event_id = qualified_fact.lead_entry_event_id
                 and initial_fact.event_sequence = 1
                 and initial_fact.occurred_at <= qualified_fact.occurred_at
             )
         )
       )
  )
  insert into public.meta_crm_event_outbox (
    organization_id,
    funnel_event_id,
    lead_id,
    lead_entry_event_id,
    integration_id,
    dataset_id,
    leadgen_id,
    event_kind,
    event_name,
    event_id,
    event_time,
    test_event_code
  )
  select
    fact.organization_id,
    fact.funnel_event_id,
    fact.lead_id,
    fact.lead_entry_event_id,
    fact.integration_id,
    fact.dataset_id,
    fact.leadgen_id,
    fact.event_kind,
    case fact.event_kind
      when 'initial' then 'VimobInitialLead'
      when 'qualified' then 'VimobQualifiedLead'
      else 'VimobConvertedLead'
    end,
    format(
      'vimob:%s:%s:%s',
      fact.organization_id::text,
      fact.lead_entry_event_id::text,
      fact.event_kind
    ),
    fact.occurred_at,
    normalized_test_event_code
  from contiguous_facts as fact
  order by
    fact.organization_id,
    fact.lead_entry_event_id,
    fact.event_sequence
  on conflict (funnel_event_id) do nothing;

  get diagnostics queued_count = row_count;
  return queued_count;
end;
$_$;


ALTER FUNCTION private.enqueue_recent_meta_crm_facts(p_organization_id uuid, p_integration_id uuid, p_test_event_code text) OWNER TO postgres;

--
-- Name: enqueue_schedule_gamification(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_schedule_gamification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  action_key text;
  beneficiary_id uuid;
begin
  if tg_op = 'INSERT' and new.status = 'scheduled' then
    action_key := case new.event_type
      when 'visit' then 'visit_scheduled'
      when 'meeting' then 'meeting_scheduled'
      else null
    end;
    beneficiary_id := new.user_id;
  elsif tg_op = 'UPDATE'
    and old.status is distinct from new.status
    and new.status = 'completed'
  then
    action_key := case new.event_type
      when 'visit' then 'visit_confirmed'
      when 'meeting' then 'meeting_held'
      else null
    end;
    beneficiary_id := coalesce(new.completed_by, new.user_id);
  end if;

  if action_key is not null then
    perform private.enqueue_gamification_outbox(
      new.organization_id,
      beneficiary_id,
      action_key,
      1,
      new.id::text,
      'schedule',
      jsonb_build_object('schedule_event_id', new.id::text, 'producer', 'schedule_event')
    );
  end if;

  return new;
exception
  when others then
    raise warning 'gamification producer % skipped: [%] %', tg_name, sqlstate, sqlerrm;
    return new;
end;
$$;


ALTER FUNCTION private.enqueue_schedule_gamification() OWNER TO postgres;

--
-- Name: enqueue_whatsapp_avatar_from_message(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_whatsapp_avatar_from_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_remote_jid text;
  v_binding_id uuid;
  v_is_eligible boolean;
begin
  if new.organization_id is null
     or new.session_id is null
     or new.conversation_id is null
     or new.lead_id is null then
    return new;
  end if;

  v_is_eligible := case
    when coalesce(new.from_me, false)
      or lower(coalesce(new.direction, 'inbound')) = 'outbound'
      then lower(coalesce(new.status, '')) in ('sent', 'delivered', 'read')
    else lower(coalesce(new.status, '')) in ('received', 'delivered', 'read')
  end;

  if not v_is_eligible
     or lower(coalesce(new.message_type, 'text')) in (
       'reaction', 'receipt', 'protocol', 'revoked', 'deleted'
     ) then
    return new;
  end if;

  -- Terminal cards and receipts/replays of the same row pay only one indexed
  -- lookup and never re-enter the conversation/binding join.
  if exists (
    select 1
    from private.whatsapp_avatar_jobs as existing
    where existing.organization_id = new.organization_id
      and existing.lead_id = new.lead_id
      and (
        existing.status in ('completed', 'not_available')
        or (
          existing.status <> 'stale'
          and existing.last_contact_message_id = new.id
        )
      )
  ) then
    return new;
  end if;

  select
    coalesce(nullif(btrim(new.remote_jid), ''), nullif(btrim(conversation.remote_jid), '')),
    binding.id
  into v_remote_jid, v_binding_id
  from public.whatsapp_conversations as conversation
  join public.whatsapp_conversation_lead_bindings as binding
    on binding.organization_id = conversation.organization_id
   and binding.conversation_id = conversation.id
   and binding.session_id = new.session_id
   and binding.lead_id = new.lead_id
   and binding.active_to is null
   and binding.stale = false
  join public.leads as lead
    on lead.organization_id = conversation.organization_id
   and lead.id = binding.lead_id
  where conversation.organization_id = new.organization_id
    and conversation.id = new.conversation_id
    and conversation.session_id = new.session_id
    and conversation.lead_id = new.lead_id
    and conversation.deleted_at is null
    and coalesce(conversation.is_group, false) = false
    and nullif(btrim(lead.whatsapp_avatar_storage_path), '') is null
  limit 1;

  if v_binding_id is null
     or v_remote_jid is null
     or v_remote_jid !~ '^[^[:space:]@]+@(s[.]whatsapp[.]net|lid)$' then
    return new;
  end if;

  insert into private.whatsapp_avatar_jobs as job (
    organization_id,
    lead_id,
    session_id,
    conversation_id,
    binding_id,
    source_message_id,
    last_contact_message_id,
    last_contact_binding_id,
    last_contact_eligible_at,
    eligible_contact_count,
    remote_jid,
    status,
    attempts,
    max_attempts,
    next_attempt_at,
    created_at,
    updated_at
  ) values (
    new.organization_id,
    new.lead_id,
    new.session_id,
    new.conversation_id,
    v_binding_id,
    new.id,
    new.id,
    v_binding_id,
    clock_timestamp(),
    1,
    v_remote_jid,
    'pending',
    0,
    2,
    now(),
    now(),
    now()
  )
  on conflict (organization_id, lead_id) do update
  set
    session_id = case
      when job.status = 'stale' then excluded.session_id
      else job.session_id
    end,
    conversation_id = case
      when job.status = 'stale' then excluded.conversation_id
      else job.conversation_id
    end,
    binding_id = case
      when job.status = 'stale' then excluded.binding_id
      else job.binding_id
    end,
    -- Preserve contact one permanently. The claim function can fall back to
    -- contact two when contact one's exact binding is no longer current.
    source_message_id = job.source_message_id,
    last_contact_message_id = excluded.last_contact_message_id,
    last_contact_binding_id = excluded.last_contact_binding_id,
    last_contact_eligible_at = excluded.last_contact_eligible_at,
    eligible_contact_count = least(2, job.eligible_contact_count + 1)::smallint,
    last_attempt_message_id = case
      when job.status = 'stale' then null
      else job.last_attempt_message_id
    end,
    remote_jid = excluded.remote_jid,
    status = case
      when job.status = 'stale' then 'pending'
      when job.status = 'awaiting_next_contact'
        and job.last_contact_message_id is distinct from excluded.last_contact_message_id
        and job.attempts < job.max_attempts
        then 'pending'
      else job.status
    end,
    attempts = job.attempts,
    max_attempts = 2,
    next_attempt_at = case
      when job.status = 'stale' then now()
      when job.status = 'awaiting_next_contact'
        and job.last_contact_message_id is distinct from excluded.last_contact_message_id
        and job.attempts < job.max_attempts
        then now()
      else job.next_attempt_at
    end,
    last_error = case
      when job.status = 'stale' then null
      when job.status = 'awaiting_next_contact'
        and job.last_contact_message_id is distinct from excluded.last_contact_message_id
        and job.attempts < job.max_attempts
        then null
      else job.last_error
    end,
    provider_avatar_id = case when job.status = 'stale' then null else job.provider_avatar_id end,
    storage_path = case when job.status = 'stale' then null else job.storage_path end,
    completed_at = case when job.status = 'stale' then null else job.completed_at end,
    created_at = case when job.status = 'stale' then now() else job.created_at end,
    updated_at = now()
  where (
      job.status = 'stale'
      and job.last_contact_message_id is distinct from excluded.last_contact_message_id
      and job.attempts < job.max_attempts
      and job.eligible_contact_count < 2
      and excluded.last_contact_eligible_at >= job.last_contact_eligible_at
    )
    or (
      job.status not in ('completed', 'not_available', 'stale')
      and job.last_contact_message_id is distinct from excluded.last_contact_message_id
      and job.eligible_contact_count < 2
      and excluded.last_contact_eligible_at >= job.last_contact_eligible_at
    );

  return new;
end;
$_$;


ALTER FUNCTION private.enqueue_whatsapp_avatar_from_message() OWNER TO postgres;

--
-- Name: enqueue_whatsapp_inbound_attendant_push(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_whatsapp_inbound_attendant_push() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_recipient record;
begin
  if new.capture_state is distinct from 'captured' or new.from_me is distinct from false
     or new.direction is distinct from 'inbound' or new.lead_id is null
     or new.message_type in ('reaction', 'system', 'deleted') then return new; end if;

  select recipient.* into v_recipient
  from private.whatsapp_inbound_push_recipient(new.organization_id, new.id) recipient
  join public.whatsapp_attendance_entries entry on entry.id = recipient.attendance_entry_id
  join public.whatsapp_conversation_lead_bindings binding on binding.id = recipient.binding_id
  join public.whatsapp_webhook_routing_snapshots route
    on route.organization_id = new.organization_id and route.session_id = new.session_id
   and route.provider_message_id = coalesce(nullif(new.provider_message_id, ''), new.message_id)
  join public.whatsapp_webhook_inbox inbox
    on inbox.organization_id = route.organization_id and inbox.session_id = route.session_id
   and inbox.event_key = route.inbox_event_key and inbox.processing_epoch = route.processing_epoch
  left join private.whatsapp_webhook_session_cutovers cutover on cutover.session_id = route.session_id
  where route.processing_lane = 'live' and inbox.processing_lane = 'live'
    and route.processing_epoch = coalesce(cutover.active_epoch, 0)
    and coalesce(route.snapshot->>'processing_epoch', '0') = route.processing_epoch::text
    and coalesce(route.snapshot->>'state', '') <> 'provider_replay'
    and (
      (route.snapshot->>'conversation_id' = new.conversation_id::text
       and route.snapshot->>'active_binding_id' = binding.id::text
       and route.snapshot->>'context_kind' = 'organic'
       and route.snapshot->>'state' in ('bound', 'lead_match')
       and coalesce(route.snapshot->>'event_lead_id', route.snapshot->>'current_lead_id') = new.lead_id::text)
      or
      (entry.entry_source = 'ctwa_auto' and route.binding_eligible
       and route.snapshot->>'state' = 'contextual_intake'
       and route.snapshot->>'context_kind' = 'contextual_intake'
       and entry.bootstrap_provider_message_id = route.provider_message_id
       and entry.bootstrap_ingress_sequence = route.ingress_sequence
       and binding.provider_message_id = route.provider_message_id)
      or
      (route.binding_eligible and route.target_mode = 'inherit_predecessor'
       and route.snapshot->>'state' = 'predecessor_inherit'
       and route.snapshot->>'context_kind' = 'organic'
       and exists (
         select 1 from public.whatsapp_conversation_routing_heads head
         join public.whatsapp_webhook_routing_snapshots head_route
           on head_route.organization_id = head.organization_id and head_route.session_id = head.session_id
          and head_route.provider_message_id = head.provider_message_id
          and head_route.ingress_sequence = head.ingress_sequence
          and head_route.processing_epoch = route.processing_epoch
          and head_route.routing_key = route.routing_key and head_route.binding_eligible
         join public.whatsapp_webhook_routing_snapshots predecessor
           on predecessor.organization_id = route.organization_id
          and predecessor.session_id = route.session_id
          and predecessor.provider_message_id = route.predecessor_provider_message_id
         where head.organization_id = route.organization_id and head.session_id = route.session_id
           and head.conversation_id = new.conversation_id and head.lead_id = new.lead_id
           and head.routing_key = route.routing_key and head.ingress_sequence >= route.ingress_sequence
           and predecessor.binding_eligible and predecessor.routing_key = route.routing_key
           and predecessor.ingress_sequence < route.ingress_sequence
           and private.whatsapp_inherited_predecessor_provenance_matches(route, predecessor)
           and (predecessor.inbox_event_key = route.inbox_event_key
             or exists (select 1 from public.whatsapp_webhook_routing_outcomes outcome
               where outcome.organization_id = predecessor.organization_id and outcome.session_id = predecessor.session_id
                 and outcome.provider_message_id = predecessor.provider_message_id and outcome.ingress_sequence = predecessor.ingress_sequence)
             or exists (select 1 from public.whatsapp_webhook_inbox previous_inbox
               where previous_inbox.organization_id = predecessor.organization_id and previous_inbox.session_id = predecessor.session_id
                 and previous_inbox.event_key = predecessor.inbox_event_key and previous_inbox.status = 'processed'))
       ))
    )
    and inbox.provider_occurred_at is not null and inbox.provider_occurred_at <= inbox.created_at
    and (
      (entry.entry_source = 'manual'
       and entry.joined_at <= inbox.provider_occurred_at and entry.joined_at <= inbox.created_at
       and entry.ingress_sequence_cutoff < route.ingress_sequence)
      or
      (entry.entry_source = 'ctwa_auto' and (
        (entry.bootstrap_provider_message_id = route.provider_message_id
         and entry.bootstrap_ingress_sequence = route.ingress_sequence
         and binding.provider_message_id = route.provider_message_id)
        or
        (entry.bootstrap_ingress_sequence < route.ingress_sequence
         and entry.bootstrap_provider_occurred_at <= inbox.provider_occurred_at
         and entry.bootstrap_inbox_created_at <= inbox.created_at)
      ))
    );
  if found then
    perform private.create_whatsapp_inbound_attendant_notification(new.organization_id, new.id,
      v_recipient.user_id, v_recipient.attendance_entry_id, v_recipient.binding_id, v_recipient.grant_id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.enqueue_whatsapp_inbound_attendant_push() OWNER TO postgres;

--
-- Name: enqueue_whatsapp_message_gamification(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_whatsapp_message_gamification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  was_awardable boolean := false;
  is_awardable boolean := false;
  message_reference text;
begin
  is_awardable := (
    (new.direction = 'outbound' or new.from_me = true)
    and new.sender_user_id is not null
    and new.status in ('sent', 'delivered', 'read')
    and coalesce(new.client_message_id, '') not like 'ai-%'
    and lower(coalesce(new.metadata->>'is_automation', 'false')) not in ('true', '1', 'yes')
    and coalesce(new.metadata->>'automation_execution_id', '') = ''
  );

  if tg_op = 'UPDATE' then
    was_awardable := (
      (old.direction = 'outbound' or old.from_me = true)
      and old.sender_user_id is not null
      and old.status in ('sent', 'delivered', 'read')
    );
  end if;

  if is_awardable and not was_awardable then
    message_reference := coalesce(
      nullif(new.message_id, ''),
      nullif(new.client_message_id, ''),
      new.id::text
    );
    message_reference := new.conversation_id::text || ':' || message_reference;
    perform private.enqueue_gamification_outbox(
      new.organization_id,
      new.sender_user_id,
      'message_sent',
      1,
      message_reference,
      'whatsapp',
      jsonb_build_object(
        'message_id', new.id::text,
        'conversation_id', new.conversation_id::text,
        'producer', 'whatsapp_message_status'
      )
    );
  end if;

  return new;
exception
  when others then
    raise warning 'gamification producer % skipped: [%] %', tg_name, sqlstate, sqlerrm;
    return new;
end;
$$;


ALTER FUNCTION private.enqueue_whatsapp_message_gamification() OWNER TO postgres;

--
-- Name: enqueue_whatsapp_outbox(uuid, uuid, uuid, uuid, text, text, text, jsonb, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_whatsapp_outbox(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_message_id uuid, p_client_message_id text, p_recipient_jid text, p_message_type text, p_payload jsonb, p_max_attempts integer DEFAULT 12) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare
  outbox_id uuid;
  existing_row public.whatsapp_outbox%rowtype;
begin
  insert into public.whatsapp_outbox (
    organization_id,
    session_id,
    conversation_id,
    message_id,
    client_message_id,
    recipient_jid,
    message_type,
    payload,
    max_attempts
  ) values (
    p_organization_id,
    p_session_id,
    p_conversation_id,
    p_message_id,
    btrim(p_client_message_id),
    btrim(p_recipient_jid),
    coalesce(nullif(btrim(p_message_type), ''), 'text'),
    coalesce(p_payload, '{}'::jsonb),
    p_max_attempts
  )
  on conflict (organization_id, session_id, client_message_id) do nothing
  returning id into outbox_id;

  if outbox_id is not null then
    return outbox_id;
  end if;

  select queued.*
    into existing_row
  from public.whatsapp_outbox as queued
  where queued.organization_id = p_organization_id
    and queued.session_id = p_session_id
    and queued.client_message_id = btrim(p_client_message_id);

  if existing_row.id is null
     or existing_row.conversation_id <> p_conversation_id
     or existing_row.message_id <> p_message_id
     or existing_row.recipient_jid <> btrim(p_recipient_jid) then
    raise exception using
      errcode = '23505',
      message = 'whatsapp client_message_id collision with a different message';
  end if;

  return existing_row.id;
end;
$$;


ALTER FUNCTION private.enqueue_whatsapp_outbox(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_message_id uuid, p_client_message_id text, p_recipient_jid text, p_message_type text, p_payload jsonb, p_max_attempts integer) OWNER TO postgres;

--
-- Name: enqueue_whatsapp_webhook_event(uuid, uuid, text, text, text, text, jsonb, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_whatsapp_webhook_event(p_organization_id uuid, p_session_id uuid, p_provider text, p_provider_instance_id text, p_event_key text, p_event_type text, p_payload jsonb, p_max_attempts integer DEFAULT 12) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare
  event_id uuid;
  existing_row public.whatsapp_webhook_inbox%rowtype;
begin
  insert into public.whatsapp_webhook_inbox (
    organization_id,
    session_id,
    provider,
    provider_instance_id,
    event_key,
    event_type,
    payload,
    max_attempts
  ) values (
    p_organization_id,
    p_session_id,
    coalesce(nullif(btrim(p_provider), ''), 'evolution_go'),
    nullif(btrim(p_provider_instance_id), ''),
    btrim(p_event_key),
    btrim(p_event_type),
    coalesce(p_payload, '{}'::jsonb),
    p_max_attempts
  )
  on conflict (event_key) do nothing
  returning id into event_id;

  if event_id is not null then
    return event_id;
  end if;

  select inbox.*
    into existing_row
  from public.whatsapp_webhook_inbox as inbox
  where inbox.event_key = btrim(p_event_key);

  if existing_row.id is null
     or existing_row.organization_id <> p_organization_id
     or existing_row.session_id <> p_session_id
     or existing_row.provider <> coalesce(nullif(btrim(p_provider), ''), 'evolution_go') then
    raise exception using
      errcode = '23505',
      message = 'whatsapp webhook event_key collision across provider or tenant';
  end if;

  return existing_row.id;
end;
$$;


ALTER FUNCTION private.enqueue_whatsapp_webhook_event(p_organization_id uuid, p_session_id uuid, p_provider text, p_provider_instance_id text, p_event_key text, p_event_type text, p_payload jsonb, p_max_attempts integer) OWNER TO postgres;

--
-- Name: enroll_round_robin_redistribution(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enroll_round_robin_redistribution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  queue_settings jsonb;
  queue_enabled boolean;
  timeout_minutes integer;
  warning_minutes integer;
  max_attempts integer;
  eligible_users integer;
  current_user_id uuid;
begin
  if new.round_robin_id is null
     or new.lead_id is null
     or new.assigned_user_id is null
     or coalesce(new.reason, '') = 'auto_redistribution' then
    return new;
  end if;

  select coalesce(rr.settings, '{}'::jsonb), coalesce(rr.is_active, true)
  into queue_settings, queue_enabled
  from public.round_robins rr
  where rr.id = new.round_robin_id
    and rr.organization_id = new.organization_id;

  if not found or not queue_enabled
     or lower(coalesce(queue_settings->>'enable_redistribution', 'false')) not in ('true', '1', 'yes') then
    return new;
  end if;

  timeout_minutes := least(10080, greatest(1, coalesce(
    case when coalesce(queue_settings->>'redistribution_timeout_minutes', '') ~ '^[0-9]+$'
      then (queue_settings->>'redistribution_timeout_minutes')::integer end,
    20
  )));
  warning_minutes := greatest(0, coalesce(
    case when coalesce(queue_settings->>'redistribution_warning_minutes', '') ~ '^[0-9]+$'
      then (queue_settings->>'redistribution_warning_minutes')::integer end,
    5
  ));
  warning_minutes := least(warning_minutes, timeout_minutes - 1);
  max_attempts := least(1000, greatest(0, coalesce(
    case when coalesce(queue_settings->>'redistribution_max_attempts', '') ~ '^[0-9]+$'
      then (queue_settings->>'redistribution_max_attempts')::integer end,
    10
  )));

  with entries as (
    select rrm.organization_id, rrm.user_id, rrm.team_id, rrm.membership_generation
    from public.round_robin_members rrm
    where rrm.organization_id = new.organization_id
      and rrm.round_robin_id = new.round_robin_id
      and coalesce(rrm.is_active, true) = true
  ), candidate_users as (
    select e.organization_id, e.user_id, e.membership_generation
    from entries e
    where e.user_id is not null
      and (e.team_id is null or exists (
        select 1 from public.teams required_team
        join public.team_members required_member
          on required_member.team_id = required_team.id
         and required_member.organization_id = required_team.organization_id
        where required_team.id = e.team_id
          and required_team.organization_id = e.organization_id
          and coalesce(required_team.is_active, true) = true
          and required_member.user_id = e.user_id
          and required_member.membership_generation = e.membership_generation
          and coalesce(required_member.is_active, true) = true
      ))
    union
    select e.organization_id, tm.user_id, tm.membership_generation
    from entries e
    join public.teams t
      on t.id = e.team_id and t.organization_id = e.organization_id and coalesce(t.is_active, true) = true
    join public.team_members tm
      on tm.team_id = e.team_id and tm.organization_id = e.organization_id and coalesce(tm.is_active, true) = true
    where e.user_id is null and e.team_id is not null
  )
  select count(distinct c.user_id)::integer
  into eligible_users
  from candidate_users c
  join public.organization_members om
    on om.organization_id = c.organization_id and om.user_id = c.user_id and coalesce(om.is_active, true) = true and om.deleted_at is null and om.membership_generation = c.membership_generation
  join public.users u on u.id = c.user_id and coalesce(u.is_active, true) = true;

  -- A queue with no alternative assignee can never redistribute safely.
  if coalesce(eligible_users, 0) < 2 then
    return new;
  end if;

  select l.assigned_user_id
  into current_user_id
  from public.leads l
  where l.id = new.lead_id
    and l.organization_id = new.organization_id;
  if current_user_id is distinct from new.assigned_user_id then
    return new;
  end if;

  insert into public.lead_redistribution_jobs (
    organization_id, lead_id, round_robin_id,
    original_assigned_user_id, current_assigned_user_id,
    max_attempts, timeout_minutes, warning_minutes,
    enrolled_at, due_at, warning_due_at, metadata
  ) values (
    new.organization_id, new.lead_id, new.round_robin_id,
    new.assigned_user_id, new.assigned_user_id,
    max_attempts, timeout_minutes, warning_minutes,
    new.created_at,
    new.created_at + make_interval(mins => timeout_minutes),
    case when warning_minutes > 0
      then new.created_at + make_interval(mins => timeout_minutes - warning_minutes)
      else null end,
    jsonb_build_object(
      'source', coalesce(nullif(new.reason, ''), 'round_robin'),
      'round_robin_log_id', new.id,
      'member_id', new.metadata->>'member_id'
    )
  ) on conflict do nothing;

  return new;
end;
$_$;


ALTER FUNCTION private.enroll_round_robin_redistribution() OWNER TO postgres;

--
-- Name: ensure_billing_payment_receipt_delivery_from_payment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.ensure_billing_payment_receipt_delivery_from_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_receipt public.billing_payment_receipts%rowtype;
  v_organization record;
  v_fallback_name text;
  v_fallback_email text;
  v_fallback_whatsapp text;
  v_recipient_name text;
  v_recipient_email text;
  v_recipient_whatsapp text;
  v_email_required boolean;
  v_whatsapp_required boolean;
  v_payment_is_paid boolean;
  v_canonicalized_count integer := 0;
begin
  v_payment_is_paid := private.billing_payment_checkout_is_paid(new.status);

  select receipt.*
    into v_receipt
  from public.billing_payment_receipts receipt
  where receipt.payment_id = new.id
    and receipt.organization_id = new.organization_id
  limit 1;

  -- Delivery belongs to the organization's immutable financial contact, never
  -- to whichever CRM member happens to sort first. Resolve this before every
  -- early return so a legacy user-backed row cannot survive a state change.
  select
    organization.name,
    coalesce(
      nullif(btrim(organization.billing_legal_name), ''),
      nullif(btrim(organization.razao_social), ''),
      nullif(btrim(v_receipt.payer_name), ''),
      nullif(btrim(organization.name), ''),
      'Cliente Vimob'
    ) as billing_contact_name,
    coalesce(
      nullif(btrim(organization.billing_email), ''),
      nullif(btrim(organization.email), ''),
      nullif(btrim(v_receipt.billing_email), '')
    ) as billing_email,
    coalesce(
      nullif(btrim(organization.billing_phone), ''),
      nullif(btrim(organization.whatsapp), ''),
      nullif(btrim(organization.telefone), '')
    ) as billing_phone
    into v_organization
  from public.organizations organization
  where organization.id = new.organization_id;

  -- Only an active owner/admin may fill a missing organization-level contact.
  -- This is recipient fallback data, not notification ownership: user_id stays
  -- null even when this fallback is used.
  select
    nullif(btrim(account.name), ''),
    nullif(btrim(account.email), ''),
    coalesce(
      nullif(btrim(account.whatsapp), ''),
      nullif(btrim(account.phone), '')
    )
    into v_fallback_name, v_fallback_email, v_fallback_whatsapp
  from public.organization_members membership
  join public.users account on account.id = membership.user_id
  where membership.organization_id = new.organization_id
    and membership.is_active = true
    and coalesce(account.is_active, true) = true
    and lower(coalesce(membership.role, '')) in ('owner', 'admin')
  order by
    case
      when v_organization.billing_email is not null
       and lower(account.email) = lower(v_organization.billing_email) then 0
      when lower(coalesce(membership.role, '')) = 'owner' then 1
      else 2
    end,
    membership.created_at asc,
    account.id asc
  limit 1;

  v_recipient_name := coalesce(
    v_organization.billing_contact_name,
    v_fallback_name,
    nullif(v_receipt.snapshot ->> 'payer_name', ''),
    nullif(v_receipt.snapshot ->> 'organization_name', ''),
    'Cliente Vimob'
  );
  v_recipient_email := coalesce(
    v_organization.billing_email,
    v_fallback_email
  );
  v_recipient_whatsapp := coalesce(
    v_organization.billing_phone,
    v_fallback_whatsapp
  );
  v_email_required := v_recipient_email is not null;
  v_whatsapp_required := v_recipient_whatsapp is not null;

  -- The older receipt trigger can insert a member-owned row earlier in the
  -- same transaction. Canonicalize ownership, target and financial recipient
  -- before checking payment state or returning for a missing delivery.
  update public.notifications notification
  set
    user_id = null,
    channel = 'external',
    target_url = '/comprovantes/' || v_receipt.verification_token::text,
    is_read = true,
    metadata = (
      coalesce(notification.metadata, '{}'::jsonb)
        - 'receipt_delivery_cancelled_at'
        - 'receipt_delivery_cancel_reason'
    ) || jsonb_build_object(
      'event_key', 'billing_payment_receipt',
      'dedupe_key', coalesce(
        nullif(notification.metadata ->> 'dedupe_key', ''),
        'billing:payment_receipt:' || new.id::text
      ),
      'payment_id', new.id::text,
      'receipt_id', v_receipt.id::text,
      'receipt_number', v_receipt.receipt_number,
      'receipt_version', v_receipt.version,
      'verification_path', '/comprovantes/' || v_receipt.verification_token::text,
      'recipient_name', v_recipient_name,
      'recipient_email', v_recipient_email,
      'recipient_whatsapp', v_recipient_whatsapp,
      'delivery_contact_missing', not (v_email_required or v_whatsapp_required),
      'variables', coalesce(notification.metadata -> 'variables', '{}'::jsonb) || jsonb_build_object(
        'receipt_number', v_receipt.receipt_number,
        'organization_name', v_receipt.snapshot ->> 'organization_name',
        'payer_name', v_receipt.payer_name,
        'payer_tax_id', v_receipt.payer_tax_id,
        'plan_name', v_receipt.plan_name,
        'billing_period_months', v_receipt.billing_period_months,
        'billing_type', v_receipt.billing_type,
        'amount', 'R$ ' || replace(to_char(v_receipt.amount, 'FM999999990D00'), '.', ','),
        'paid_at', to_char(v_receipt.paid_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
        'provider_payment_reference', v_receipt.provider_payment_reference,
        'verification_path', '/comprovantes/' || v_receipt.verification_token::text,
        'issuer_name', v_receipt.issuer_name,
        'issued_at', to_char(v_receipt.issued_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI')
      ),
      'dispatch', coalesce(notification.metadata -> 'dispatch', '{}'::jsonb) || jsonb_build_object(
        'whatsapp', (case
          when lower(coalesce(
            notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status', ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent',
            'permanent_failed'
          ) then coalesce(
            notification.metadata -> 'dispatch' -> 'whatsapp', '{}'::jsonb
          )
          else coalesce(
            notification.metadata -> 'dispatch' -> 'whatsapp', '{}'::jsonb
          ) - 'error' - 'next_retry_at'
        end) || jsonb_build_object(
          'required', v_whatsapp_required or lower(coalesce(
            notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status', ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent',
            'permanent_failed'
          ),
          'status', case
            when lower(coalesce(
              notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status', ''
            )) in (
              'accepted', 'delivered', 'delivery_failed', 'sent',
              'permanent_failed'
            ) then lower(notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status')
            when not v_whatsapp_required then 'skipped'
            else 'pending'
          end,
          'updated_at', now()
        ),
        'email', (case
          when lower(coalesce(
            notification.metadata -> 'dispatch' -> 'email' ->> 'status', ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent',
            'permanent_failed'
          ) then coalesce(
            notification.metadata -> 'dispatch' -> 'email', '{}'::jsonb
          )
          else coalesce(
            notification.metadata -> 'dispatch' -> 'email', '{}'::jsonb
          ) - 'error' - 'next_retry_at'
        end) || jsonb_build_object(
          'required', v_email_required or lower(coalesce(
            notification.metadata -> 'dispatch' -> 'email' ->> 'status', ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent',
            'permanent_failed'
          ),
          'status', case
            when lower(coalesce(
              notification.metadata -> 'dispatch' -> 'email' ->> 'status', ''
            )) in (
              'accepted', 'delivered', 'delivery_failed', 'sent',
              'permanent_failed'
            ) then lower(notification.metadata -> 'dispatch' -> 'email' ->> 'status')
            when not v_email_required then 'skipped'
            else 'pending'
          end,
          'updated_at', now()
        )
      ),
      'whatsapp_dispatch_required', v_whatsapp_required or lower(coalesce(
        notification.metadata -> 'whatsapp_dispatch' ->> 'status',
        notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
        ''
      )) in (
        'accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'
      ),
      'whatsapp_dispatch', (case
        when lower(coalesce(
          notification.metadata -> 'whatsapp_dispatch' ->> 'status',
          notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
          ''
        )) in (
          'accepted', 'delivered', 'delivery_failed', 'sent',
          'permanent_failed'
        ) then coalesce(
          notification.metadata -> 'whatsapp_dispatch',
          notification.metadata -> 'dispatch' -> 'whatsapp',
          '{}'::jsonb
        )
        else coalesce(
          notification.metadata -> 'whatsapp_dispatch',
          notification.metadata -> 'dispatch' -> 'whatsapp',
          '{}'::jsonb
        ) - 'error' - 'next_retry_at'
      end) || jsonb_build_object(
        'required', v_whatsapp_required or lower(coalesce(
          notification.metadata -> 'whatsapp_dispatch' ->> 'status',
          notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
          ''
        )) in (
          'accepted', 'delivered', 'delivery_failed', 'sent',
          'permanent_failed'
        ),
        'status', case
          when lower(coalesce(
            notification.metadata -> 'whatsapp_dispatch' ->> 'status',
            notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
            ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent',
            'permanent_failed'
          ) then lower(coalesce(
            notification.metadata -> 'whatsapp_dispatch' ->> 'status',
            notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status'
          ))
          when not v_whatsapp_required then 'skipped'
          else 'pending'
        end,
        'updated_at', now()
      )
    )
  where v_receipt.id is not null
    and notification.organization_id = new.organization_id
    and notification.metadata ->> 'event_key' = 'billing_payment_receipt'
    and notification.metadata ->> 'payment_id' = new.id::text;
  get diagnostics v_canonicalized_count = row_count;

  if not v_payment_is_paid then
    perform private.cancel_billing_payment_receipt_delivery(
      notification.id,
      new.status
    )
    from public.notifications notification
    where notification.organization_id = new.organization_id
      and notification.metadata ->> 'event_key' = 'billing_payment_receipt'
      and notification.metadata ->> 'payment_id' = new.id::text;
    return new;
  end if;

  -- Receipt creation is an earlier same-timing trigger. Never enqueue a paid
  -- message without its immutable verification record.
  if v_receipt.id is null then
    return new;
  end if;

  if v_canonicalized_count > 0 then
    return new;
  end if;

  insert into public.notifications (
    organization_id,
    user_id,
    title,
    content,
    body,
    type,
    channel,
    target_url,
    is_read,
    metadata
  )
  values (
    new.organization_id,
    null,
    'Comprovante de pagamento Vimob',
    'Seu pagamento foi confirmado e o comprovante Vimob esta disponivel.',
    'Seu pagamento foi confirmado e o comprovante Vimob esta disponivel.',
    'billing',
    'external',
    '/comprovantes/' || v_receipt.verification_token::text,
    true,
    jsonb_build_object(
      'event_key', 'billing_payment_receipt',
      'dedupe_key', 'billing:payment_receipt:' || new.id::text,
      'payment_id', new.id::text,
      'receipt_id', v_receipt.id::text,
      'receipt_number', v_receipt.receipt_number,
      'receipt_version', v_receipt.version,
      'verification_path', '/comprovantes/' || v_receipt.verification_token::text,
      'recipient_name', v_recipient_name,
      'recipient_email', v_recipient_email,
      'recipient_whatsapp', v_recipient_whatsapp,
      'delivery_contact_missing', not (v_email_required or v_whatsapp_required),
      'variables', jsonb_build_object(
        'receipt_number', v_receipt.receipt_number,
        'organization_name', v_receipt.snapshot ->> 'organization_name',
        'payer_name', v_receipt.payer_name,
        'payer_tax_id', v_receipt.payer_tax_id,
        'plan_name', v_receipt.plan_name,
        'billing_period_months', v_receipt.billing_period_months,
        'billing_type', v_receipt.billing_type,
        'amount', 'R$ ' || replace(to_char(v_receipt.amount, 'FM999999990D00'), '.', ','),
        'paid_at', to_char(v_receipt.paid_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
        'provider_payment_reference', v_receipt.provider_payment_reference,
        'verification_path', '/comprovantes/' || v_receipt.verification_token::text,
        'issuer_name', v_receipt.issuer_name,
        'issued_at', to_char(v_receipt.issued_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI')
      ),
      'dispatch', jsonb_build_object(
        'whatsapp', jsonb_build_object(
          'required', v_whatsapp_required,
          'status', case when v_whatsapp_required then 'pending' else 'skipped' end,
          'updated_at', now()
        ),
        'email', jsonb_build_object(
          'required', v_email_required,
          'status', case when v_email_required then 'pending' else 'skipped' end,
          'updated_at', now()
        )
      ),
      'whatsapp_dispatch_required', v_whatsapp_required,
      'whatsapp_dispatch', jsonb_build_object(
        'required', v_whatsapp_required,
        'status', case when v_whatsapp_required then 'pending' else 'skipped' end,
        'updated_at', now()
      )
    )
  )
  on conflict do nothing;

  return new;
end;
$_$;


ALTER FUNCTION private.ensure_billing_payment_receipt_delivery_from_payment() OWNER TO postgres;

--
-- Name: ensure_cadence_default_task(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.ensure_cadence_default_task(p_enrollment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target record;
begin
  select ce.*, ct.name as template_name, l.stage_id
  into target
  from public.cadence_enrollments ce
  join public.cadence_templates ct
    on ct.id = ce.cadence_template_id and ct.organization_id = ce.organization_id
  join public.leads l
    on l.id = ce.lead_id and l.organization_id = ce.organization_id
  where ce.id = p_enrollment_id
  for update of ce;
  if not found or target.status <> 'completed' then return; end if;

  if exists (select 1 from public.lead_tasks lt where lt.cadence_enrollment_id = target.id) then
    return;
  end if;

  insert into public.lead_tasks (
    organization_id, lead_id, assigned_user_id, title, description, type,
    day_offset, due_at, due_date, is_done, status, sequence,
    cadence_enrollment_id, metadata
  ) values (
    target.organization_id, target.lead_id, target.assigned_user_id,
    'Executar cadencia: ' || target.template_name,
    'O lead entrou em uma etapa de cadencia sem tarefas explicitas. Registre o contato ou conclua esta obrigacao.',
    'call', 0, target.started_at, target.started_at, false, 'pending', 1,
    target.id,
    jsonb_build_object(
      'source', 'cadence_default',
      'cadence_template_id', target.cadence_template_id,
      'historical_backfill', coalesce((target.metadata->>'historical_backfill')::boolean, false)
    )
  )
  on conflict (cadence_enrollment_id)
    where cadence_enrollment_id is not null and metadata->>'source' = 'cadence_default'
  do nothing;

  update public.cadence_enrollments
  set status = 'active', completed_at = null, updated_at = now()
  where id = target.id
    and exists (select 1 from public.lead_tasks lt where lt.cadence_enrollment_id = target.id);
end;
$$;


ALTER FUNCTION private.ensure_cadence_default_task(p_enrollment_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ensure_cadence_default_task(p_enrollment_id uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.ensure_cadence_default_task(p_enrollment_id uuid) IS 'Deprecated compatibility function. Stage operational rules never create artificial default tasks.';


--
-- Name: ensure_completed_cadence_has_obligation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.ensure_completed_cadence_has_obligation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'completed' then
    perform private.ensure_cadence_default_task(new.id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.ensure_completed_cadence_has_obligation() OWNER TO postgres;

--
-- Name: ensure_gamification_season_on_module_enable(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.ensure_gamification_season_on_module_enable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.module_name = 'gamification' and new.is_enabled = true then
    insert into public.gamification_seasons (
      organization_id,
      name,
      reset_reason,
      is_active,
      started_at
    )
    values (
      new.organization_id,
      'Temporada Inicial',
      'gamification_module_enabled',
      true,
      now()
    )
    on conflict (organization_id) where is_active = true do nothing;
  end if;
  return new;
exception
  when others then
    raise warning 'gamification season bootstrap skipped: [%] %', sqlstate, sqlerrm;
    return new;
end;
$$;


