--
-- Name: ensure_round_robin_ticket_sequence(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.ensure_round_robin_ticket_sequence(p_round_robin_id uuid) RETURNS regclass
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_name name;
  v_sequence regclass;
  v_relkind text;
  v_start bigint;
begin
  if p_round_robin_id is null then
    raise exception using errcode = '22023', message = 'round_robin_id_required';
  end if;

  v_name := private.round_robin_ticket_sequence_name(p_round_robin_id);
  v_sequence := pg_catalog.to_regclass(pg_catalog.format('private.%I', v_name));
  if v_sequence is not null then
    perform 1 from pg_catalog.pg_class as relation
      where relation.oid = v_sequence and relation.relkind = 'S';
    if not found then
      raise exception using errcode = '42809', message = 'round_robin_ticket_object_is_not_sequence';
    end if;
    return v_sequence;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'lead-distribution-ticket:' || p_round_robin_id::text, 0
  ));

  -- This lookup must run after the wait, not reuse the pre-wait resolution.
  select relation.oid::regclass, relation.relkind::text
    into v_sequence, v_relkind
  from pg_catalog.pg_class as relation
  join pg_catalog.pg_namespace as relation_namespace
    on relation_namespace.oid = relation.relnamespace
  where relation_namespace.nspname = 'private' and relation.relname = v_name;
  if found then
    if v_relkind <> 'S' then
      raise exception using errcode = '42809', message = 'round_robin_ticket_object_is_not_sequence';
    end if;
    return v_sequence;
  end if;

  select greatest(
    coalesce(queue.leads_distributed, 0)::bigint,
    coalesce((select sum(coalesce(member.leads_count, 0))::bigint
      from public.round_robin_members as member where member.round_robin_id = p_round_robin_id), 0),
    (select count(*)::bigint from public.round_robin_logs as distribution_log
      where distribution_log.round_robin_id = p_round_robin_id and distribution_log.reason = 'canonical_round_robin'),
    coalesce((select max((distribution_log.metadata->>'distribution_ticket')::bigint)
      from public.round_robin_logs as distribution_log
      where distribution_log.round_robin_id = p_round_robin_id
        and distribution_log.metadata->>'distribution_ticket' ~ '^[0-9]+$'), 0),
    coalesce((select max(distribution_event.distribution_ticket)
      from private.lead_distribution_events as distribution_event
      where distribution_event.round_robin_id = p_round_robin_id), 0)
  ) + 1 into v_start
  from public.round_robins as queue where queue.id = p_round_robin_id;
  if not found then
    raise exception using errcode = '23503', message = 'round_robin_not_found';
  end if;

  -- IF NOT EXISTS is a final defensive check, never a counter reset. Legitimate
  -- allocator callers still serialize initialization using the advisory above.
  execute pg_catalog.format('create sequence if not exists private.%I as bigint start with %s', v_name, v_start);
  select relation.oid::regclass, relation.relkind::text
    into v_sequence, v_relkind
  from pg_catalog.pg_class as relation
  join pg_catalog.pg_namespace as relation_namespace
    on relation_namespace.oid = relation.relnamespace
  where relation_namespace.nspname = 'private' and relation.relname = v_name;
  if not found or v_relkind <> 'S' then
    raise exception using errcode = '42809', message = 'round_robin_ticket_object_is_not_sequence';
  end if;
  -- Cold path only, under the same advisory lock and transaction as creation.
  execute pg_catalog.format(
    'revoke all on sequence private.%I from public, anon, authenticated, service_role', v_name
  );
  return v_sequence;
end;
$_$;


ALTER FUNCTION private.ensure_round_robin_ticket_sequence(p_round_robin_id uuid) OWNER TO postgres;

--
-- Name: ensure_whatsapp_outbox_provider_request_id(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.ensure_whatsapp_outbox_provider_request_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  action_name text := btrim(coalesce(new.payload->>'action', ''));
  request_id text;
begin
  if action_name not in ('send.text', 'send.media', 'send.audio') then
    return new;
  end if;

  if jsonb_typeof(new.payload->'body') is distinct from 'object' then
    raise exception using
      errcode = '23514',
      message = 'invalid_whatsapp_outbox_send_body';
  end if;

  request_id := upper(substr(
    encode(extensions.digest(btrim(new.client_message_id), 'sha256'), 'hex'),
    1,
    32
  ));

  if nullif(btrim(coalesce(new.payload->'body'->>'id', '')), '') is null then
    new.payload := jsonb_set(
      coalesce(new.payload, '{}'::jsonb),
      '{body,id}',
      to_jsonb(request_id),
      true
    );
  elsif new.payload->'body'->>'id' is distinct from request_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_provider_request_id_mismatch';
  end if;

  if new.payload->'body'->>'id' is distinct from request_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_provider_request_id_missing_after_guard';
  end if;

  if new.provider_message_id is null then
    new.provider_message_id := request_id;
  elsif new.provider_message_id is distinct from request_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_provider_message_id_mismatch';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.ensure_whatsapp_outbox_provider_request_id() OWNER TO postgres;

--
-- Name: expire_whatsapp_inbound_push_waiting(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.expire_whatsapp_inbound_push_waiting(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  if p_limit is null or p_limit<1 or p_limit>100 then raise exception 'invalid WhatsApp waiting expiry batch'; end if;
  with expired as (
    select notification_id from private.whatsapp_inbound_push_waiting
    where expires_at<=now() order by expires_at,notification_id limit p_limit for update skip locked
  ) delete from private.whatsapp_inbound_push_waiting waiting using expired
    where waiting.notification_id=expired.notification_id;
  get diagnostics v_count=row_count;
  return v_count;
end;
$$;


ALTER FUNCTION private.expire_whatsapp_inbound_push_waiting(p_limit integer) OWNER TO postgres;

--
-- Name: fail_property_channel_publication_job(uuid, text, uuid, text, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.fail_property_channel_publication_job(p_job_id uuid, p_worker_id text, p_lease_token uuid, p_error_code text, p_error_message text, p_retry_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_permanent boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  with failed as (
    update public.property_channel_publication_jobs
    set status = case
          when p_permanent or attempts >= max_attempts then 'dead'
          else 'retry'
        end,
        next_attempt_at = case
          when p_permanent or attempts >= max_attempts then next_attempt_at
          else coalesce(
            p_retry_at,
            clock_timestamp() + make_interval(
              secs => least(
                3600,
                5 * power(2, least(attempts, 9))::integer
              )
            )
          )
        end,
        locked_at = null,
        locked_by = null,
        lease_token = null,
        last_error_code = left(
          coalesce(nullif(btrim(p_error_code), ''), 'unknown_error'),
          160
        ),
        last_error_message = left(
          coalesce(nullif(p_error_message, ''), 'Unknown publication error.'),
          4000
        ),
        completed_at = case
          when p_permanent or attempts >= max_attempts
            then clock_timestamp()
          else null
        end,
        dead_lettered_at = case
          when p_permanent or attempts >= max_attempts
            then clock_timestamp()
          else null
        end,
        updated_at = clock_timestamp()
    where id = p_job_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
      and lease_token = p_lease_token
    returning id
  )
  select exists(select 1 from failed);
$$;


ALTER FUNCTION private.fail_property_channel_publication_job(p_job_id uuid, p_worker_id text, p_lease_token uuid, p_error_code text, p_error_message text, p_retry_at timestamp with time zone, p_permanent boolean) OWNER TO postgres;

--
-- Name: fail_whatsapp_outbox(uuid, text, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.fail_whatsapp_outbox(p_outbox_id uuid, p_worker_id text, p_error text, p_retry_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_permanent boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
  with failed as (
    update public.whatsapp_outbox
    set status = case
          when p_permanent then 'failed'
          when attempts >= max_attempts then 'dead'
          else 'retry'
        end,
        next_attempt_at = case
          when p_permanent or attempts >= max_attempts then next_attempt_at
          else coalesce(p_retry_at, now() + make_interval(secs => least(3600, 5 * power(2, least(attempts, 9))::integer)))
        end,
        failed_at = case when p_permanent then now() else failed_at end,
        dead_lettered_at = case when not p_permanent and attempts >= max_attempts then now() else null end,
        locked_at = null,
        locked_by = null,
        last_error = left(coalesce(nullif(p_error, ''), 'unknown_error'), 4000)
    where id = p_outbox_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
    returning id
  )
  select exists(select 1 from failed);
$$;


ALTER FUNCTION private.fail_whatsapp_outbox(p_outbox_id uuid, p_worker_id text, p_error text, p_retry_at timestamp with time zone, p_permanent boolean) OWNER TO postgres;

--
-- Name: fail_whatsapp_webhook_event(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.fail_whatsapp_webhook_event(p_event_id uuid, p_worker_id text, p_error text, p_retry_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
