--
-- Name: google_calendar_cancel_obsolete_jobs(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.google_calendar_cancel_obsolete_jobs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
begin
  update public.google_calendar_sync_jobs job
  set status = 'succeeded', terminal_reason = 'CANONICAL_EVENT_REMOVED_OR_TRANSFERRED',
      last_error = null, locked_at = null, locked_by = null
  where job.action = 'push_upsert'
    and (job.status in ('queued', 'failed', 'dead')
      or (job.status = 'running' and job.locked_at < now() - interval '2 minutes'))
    and job.payload->>'event_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and exists (select 1 from public.google_calendar_tokens token
      where token.id = job.connection_id and token.organization_id = job.organization_id
        and token.user_id::text = job.payload->>'owner_user_id')
    and not exists (select 1 from public.schedule_events event
      where event.id::text = coalesce(job.schedule_event_id::text, job.payload->>'event_id')
        and event.organization_id = job.organization_id
        and event.user_id::text = job.payload->>'owner_user_id');
end
$_$;


ALTER FUNCTION private.google_calendar_cancel_obsolete_jobs() OWNER TO postgres;

--
-- Name: google_calendar_guard_outbound_insert(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.google_calendar_guard_outbound_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare connection public.google_calendar_tokens;
begin
  if new.action not in ('push_upsert', 'push_delete') then return new; end if;
  select token.* into connection from public.google_calendar_tokens token
  where token.organization_id = new.organization_id
    and token.user_id::text = new.payload->>'owner_user_id'
    and token.disconnected_at is null
    and (new.payload->>'connection_id' is null or token.id::text = new.payload->>'connection_id')
  order by token.created_at desc limit 1 for update;
  if connection.disconnecting_at is not null then
    raise exception 'google_calendar_connection_disconnecting' using errcode = '55P03';
  end if;
  if connection.id is null or connection.token_secret_ref is null then
    return null;
  end if;
  new.connection_id := connection.id;
  return new;
end
$$;


ALTER FUNCTION private.google_calendar_guard_outbound_insert() OWNER TO postgres;

--
-- Name: google_calendar_refresh_connection_status(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.google_calendar_refresh_connection_status(p_connection_id uuid, p_organization_id uuid, p_owner_user_id uuid, p_synced_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare connection public.google_calendar_tokens; unresolved_error text;
begin
  select * into connection from public.google_calendar_tokens token where token.id = p_connection_id
    and token.organization_id = p_organization_id and token.user_id = p_owner_user_id for update;
  if connection.id is null or connection.disconnected_at is not null or connection.disconnecting_at is not null then return false; end if;
  select coalesce(nullif(job.last_error,''),'Envio Google pendente de revisao.') into unresolved_error
  from public.google_calendar_sync_jobs job where job.organization_id = p_organization_id
    and job.connection_id = p_connection_id and job.payload->>'owner_user_id' = p_owner_user_id::text
    and job.action in ('push_upsert','push_delete') and job.status in ('failed','dead')
  order by job.updated_at desc, job.id desc limit 1;
  update public.google_calendar_tokens token set
    sync_status = case when unresolved_error is null then 'connected' else 'error' end,
    last_error = left(unresolved_error,2000),
    last_synced_at = case when p_synced_at is null then token.last_synced_at
      else greatest(coalesce(token.last_synced_at,p_synced_at),p_synced_at) end
  where token.id = connection.id;
  return true;
end
$$;


ALTER FUNCTION private.google_calendar_refresh_connection_status(p_connection_id uuid, p_organization_id uuid, p_owner_user_id uuid, p_synced_at timestamp with time zone) OWNER TO postgres;

--
-- Name: google_calendar_require_backend(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.google_calendar_require_backend() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if session_user not in ('postgres', 'supabase_admin')
    and coalesce(current_setting('role', true), '') <> 'service_role' then
    raise exception 'Google Calendar backend role required' using errcode = '42501';
  end if;
end
$$;


ALTER FUNCTION private.google_calendar_require_backend() OWNER TO postgres;

--
-- Name: google_calendar_stamp_credential_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.google_calendar_stamp_credential_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if (new.token_secret_ref, new.disconnected_at, new.disconnecting_at)
     is distinct from (old.token_secret_ref, old.disconnected_at, old.disconnecting_at) then
    new.credential_revision := old.credential_revision + 1;
  elsif new.credential_revision is distinct from old.credential_revision then
    new.credential_revision := old.credential_revision + 1;
  end if;
  return new;
end
$$;


ALTER FUNCTION private.google_calendar_stamp_credential_revision() OWNER TO postgres;

--
-- Name: google_calendar_validate_oauth_token(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.google_calendar_validate_oauth_token(p_token jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if jsonb_typeof(p_token) is distinct from 'object' or octet_length(p_token::text) > 65536
     or jsonb_typeof(p_token->'access_token') is distinct from 'string'
     or nullif(btrim(p_token->>'access_token'), '') is null
     or jsonb_typeof(p_token->'refresh_token') is distinct from 'string'
     or nullif(btrim(p_token->>'refresh_token'), '') is null
     or not (regexp_split_to_array(coalesce(p_token->>'scope', ''), '\s+') && array[
       'https://www.googleapis.com/auth/calendar.events.owned',
       'https://www.googleapis.com/auth/calendar.events',
       'https://www.googleapis.com/auth/calendar']) then
    raise exception 'Google Calendar offline authorization and scope required' using errcode = '22023';
  end if;
end
$$;


ALTER FUNCTION private.google_calendar_validate_oauth_token(p_token jsonb) OWNER TO postgres;

--
-- Name: guard_active_property_location_references(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_active_property_location_references() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'property_neighborhoods' then
    if tg_op = 'UPDATE'
       and new.organization_id is not distinct from old.organization_id
       and new.city_id is not distinct from old.city_id then
      return new;
    end if;
    if new.city_id is not null then
      perform 1
      from public.property_cities city
      where city.organization_id = new.organization_id
        and city.id = new.city_id
        and coalesce(city.is_active, true)
      for share nowait;
      if not found then
        raise exception 'invalid or inactive neighborhood city'
          using errcode = '23514', constraint = 'property_location_hierarchy';
      end if;
    end if;
    return new;
  end if;

  if tg_table_name = 'property_condominiums' then
    if tg_op = 'UPDATE'
       and (new.organization_id, new.city_id, new.neighborhood_id)
           is not distinct from
           (old.organization_id, old.city_id, old.neighborhood_id) then
      return new;
    end if;
    if new.neighborhood_id is not null then
      perform 1
      from public.property_neighborhoods neighborhood
      where neighborhood.organization_id = new.organization_id
        and neighborhood.id = new.neighborhood_id
        and coalesce(neighborhood.is_active, true)
      for share nowait;
      if not found then
        raise exception 'invalid or inactive condominium neighborhood'
          using errcode = '23514', constraint = 'property_location_hierarchy';
      end if;
    end if;
    if new.city_id is not null then
      perform 1
      from public.property_cities city
      where city.organization_id = new.organization_id
        and city.id = new.city_id
        and coalesce(city.is_active, true)
      for share nowait;
      if not found then
        raise exception 'invalid or inactive condominium city'
          using errcode = '23514', constraint = 'property_location_hierarchy';
      end if;
    end if;
    return new;
  end if;

  if tg_table_name = 'properties' then
    if tg_op = 'UPDATE'
       and (new.organization_id, new.city_id, new.neighborhood_id, new.condominium_id)
           is not distinct from
           (old.organization_id, old.city_id, old.neighborhood_id, old.condominium_id) then
      return new;
    end if;

    -- Lock from the most specific reference to its parents. Catalog mutations
    -- that already own one of these rows make this statement fail immediately,
    -- allowing the API to return a retryable 409 instead of deadlocking.
    if new.condominium_id is not null then
      perform 1
      from public.property_condominiums condominium
      where condominium.organization_id = new.organization_id
        and condominium.id = new.condominium_id
        and coalesce(condominium.is_active, true)
      for share nowait;
      if not found then
        raise exception 'invalid or inactive property condominium'
          using errcode = '23514', constraint = 'property_location_hierarchy';
      end if;
    end if;
    if new.neighborhood_id is not null then
      perform 1
      from public.property_neighborhoods neighborhood
      where neighborhood.organization_id = new.organization_id
        and neighborhood.id = new.neighborhood_id
        and coalesce(neighborhood.is_active, true)
      for share nowait;
      if not found then
        raise exception 'invalid or inactive property neighborhood'
          using errcode = '23514', constraint = 'property_location_hierarchy';
      end if;
    end if;
    if new.city_id is not null then
      perform 1
      from public.property_cities city
      where city.organization_id = new.organization_id
        and city.id = new.city_id
        and coalesce(city.is_active, true)
      for share nowait;
      if not found then
        raise exception 'invalid or inactive property city'
          using errcode = '23514', constraint = 'property_location_hierarchy';
      end if;
    end if;
  end if;
  return new;
exception
  when lock_not_available then
    raise exception 'property location catalog changed concurrently; retry the mutation'
      using errcode = '40001', constraint = 'property_location_assignment_busy';
end
$$;


ALTER FUNCTION private.guard_active_property_location_references() OWNER TO postgres;

--
-- Name: FUNCTION guard_active_property_location_references(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.guard_active_property_location_references() IS 'Serializes changed property location references with catalog deactivation and rejects inactive or cross-tenant rows.';


--
-- Name: guard_active_property_owner_assignment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_active_property_owner_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_active boolean;
  v_match_count integer := 0;
  v_active_match_count integer := 0;
  v_owner record;
begin
  if tg_table_name = 'properties' then
    if tg_op = 'UPDATE'
       and new.organization_id is not distinct from old.organization_id
       and new.owner_id is not distinct from old.owner_id
       and (
         new.owner_id is not null
         or lower(btrim(coalesce(new.owner_name, '')))
            = lower(btrim(coalesce(old.owner_name, '')))
       ) then
      return new;
    end if;

    if new.owner_id is not null then
      select coalesce(owner.is_active, true)
        into v_active
      from public.property_owners owner
      where owner.organization_id = new.organization_id
        and owner.id = new.owner_id
      for share nowait;

      if not found or not v_active then
        raise exception 'property owner is inactive or outside the organization'
          using errcode = '23514', constraint = 'property_owner_assignment_invalid';
      end if;
      return new;
    end if;

    -- Trusted legacy importers may still send a name-only owner. If that name
    -- identifies a catalog owner, serialize with the owner row and reject an
    -- inactive or ambiguous match. A name with no catalog row stays compatible.
    if nullif(btrim(new.owner_name), '') is not null then
      if not pg_catalog.pg_try_advisory_xact_lock_shared(
        pg_catalog.hashtext(new.organization_id::text),
        pg_catalog.hashtext('property-owner-name:' || lower(btrim(new.owner_name)))
      ) then
        raise exception 'property owner name changed concurrently; retry the mutation'
          using errcode = '40001', constraint = 'property_owner_assignment_busy';
      end if;

      for v_owner in
        select owner.id, coalesce(owner.is_active, true) as is_active
        from public.property_owners owner
        where owner.organization_id = new.organization_id
          and lower(btrim(owner.name)) = lower(btrim(new.owner_name))
        order by owner.id
        for share nowait
      loop
        v_match_count := v_match_count + 1;
        if v_owner.is_active then
          v_active_match_count := v_active_match_count + 1;
        end if;
      end loop;

      if v_match_count > 0
         and (v_match_count <> 1 or v_active_match_count <> 1) then
        raise exception 'legacy property owner is inactive or ambiguous'
          using errcode = '23514', constraint = 'property_owner_assignment_invalid';
      end if;
    end if;
    return new;
  end if;

  if tg_table_name = 'property_ownerships' then
    select coalesce(owner.is_active, true)
      into v_active
    from public.property_owners owner
    where owner.organization_id = new.organization_id
      and owner.id = new.owner_id
    for share nowait;

    if not found
       or (
         (new.valid_to is null or current_date < new.valid_to)
         and not v_active
       ) then
      raise exception 'property ownership owner is missing, outside the organization, or inactive for a non-ended period'
        using errcode = '23514', constraint = 'property_owner_assignment_invalid';
    end if;
  end if;
  return new;
exception
  when lock_not_available then
    raise exception 'property owner catalog changed concurrently; retry the mutation'
      using errcode = '40001', constraint = 'property_owner_assignment_busy';
end
$$;


ALTER FUNCTION private.guard_active_property_owner_assignment() OWNER TO postgres;

--
-- Name: FUNCTION guard_active_property_owner_assignment(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.guard_active_property_owner_assignment() IS 'Serializes changed canonical and legacy owner assignments with owner lifecycle mutations and rejects inactive or ambiguous references.';


--
-- Name: guard_asaas_reconciliation_job_cleanup(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_asaas_reconciliation_job_cleanup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if private.billing_organization_cleanup_is_active(
    new.organization_id,
    new.provider_subscription_id
  ) then
    new.status := 'dead';
    new.attempts := greatest(new.attempts, new.max_attempts);
    new.locked_at := null;
    new.locked_by := null;
    new.last_error := 'organization_cleanup_won';
    new.updated_at := clock_timestamp();
  end if;
  return new;
end
$$;


ALTER FUNCTION private.guard_asaas_reconciliation_job_cleanup() OWNER TO postgres;

--
-- Name: guard_automation_publish_state(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_automation_publish_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.is_active and new.active_flow_version_id is null then
    raise exception using errcode = '23514', message = 'Active automation requires a published flow version.';
  end if;
  if new.active_flow_version_id is not null and not exists (
    select 1
    from public.automation_flow_versions fv
    where fv.id = new.active_flow_version_id
      and fv.automation_id = new.id
      and fv.organization_id = new.organization_id
      and fv.requires_review = false
  ) then
    raise exception using errcode = '23514', message = 'Published flow version belongs to another automation.';
  end if;
  return new;
end;
$$;


