--
-- Name: guard_billing_plan_change_card_update(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_billing_plan_change_card_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status in ('provider_updating', 'scheduled', 'applying') then
    perform private.lock_asaas_billing_resources(
      null,
      new.provider_subscription_id
    );
  end if;

  if new.status in ('provider_updating', 'scheduled', 'applying')
     and (
       tg_op = 'INSERT'
       or old.status is distinct from new.status
       or old.provider_subscription_id
         is distinct from new.provider_subscription_id
     )
     and private.billing_organization_cleanup_is_active(
       new.organization_id,
       new.provider_subscription_id
     ) then
    raise exception 'organization billing cleanup is in progress'
      using errcode = '55P03';
  end if;

  if new.status in ('provider_updating', 'scheduled', 'applying')
     and (
       tg_op = 'INSERT'
       or old.status is distinct from new.status
       or old.provider_subscription_id
         is distinct from new.provider_subscription_id
     )
     and exists (
       select 1
       from private.billing_subscription_card_update_jobs as job
       where job.organization_id = new.organization_id
         and job.provider_subscription_id = new.provider_subscription_id
         and (
           job.status in (
             'prepared', 'awaiting_payment', 'pending_update', 'processing', 'retry'
           )
           or (
             job.status = 'dead'
             and job.manual_review_at is not null
           )
         )
     ) then
    raise exception 'subscription card update is in progress'
      using errcode = '55P03';
  end if;
  return new;
end
$$;


ALTER FUNCTION private.guard_billing_plan_change_card_update() OWNER TO postgres;

--
-- Name: guard_card_recurrence_cancel_card_update(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_card_recurrence_cancel_card_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_card_job private.billing_subscription_card_update_jobs%rowtype;
  v_now timestamptz := clock_timestamp();
  v_card_boundary_crossed boolean := false;
begin
  if new.job_action <> 'cancel'
     or new.status <> 'completed'
     or new.provider_subscription_id is null
     or new.job_status not in ('pending', 'retry', 'processing')
     or (
       old.job_action is not distinct from new.job_action
       and old.job_status is not distinct from new.job_status
       and old.provider_subscription_id
         is not distinct from new.provider_subscription_id
     ) then
    return new;
  end if;

  perform private.lock_asaas_billing_resources(
    null,
    new.provider_subscription_id
  );

  select job.*
  into v_card_job
  from private.billing_subscription_card_update_jobs as job
  where job.organization_id = new.organization_id
    and job.provider_subscription_id = new.provider_subscription_id
    and (
      job.status in (
        'prepared', 'awaiting_payment', 'pending_update', 'processing', 'retry'
      )
      or (job.status = 'dead' and job.manual_review_at is not null)
    )
  order by job.generation desc
  limit 1
  for update;

  if not found then
    return new;
  end if;

  v_card_boundary_crossed :=
    v_card_job.manual_review_at is not null
    or v_card_job.provider_outcome_ambiguous_at is not null
    or (
      v_card_job.status = 'awaiting_payment'
      and v_card_job.capture_request_started_at is not null
    )
    or (
      v_card_job.status = 'processing'
      and v_card_job.provider_request_started_at is not null
      and v_card_job.provider_request_lease_id = v_card_job.lease_id
    );

  if not v_card_boundary_crossed then
    update private.billing_subscription_card_update_jobs
    set
      status = 'cancelled',
      provider_card_credential = null,
      card_last4 = null,
      credential_attempt_lease_id = null,
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      last_error_code = 'legacy_recurrence_cancellation_won',
      manual_review_at = null,
      cancelled_at = v_now,
      updated_at = v_now
    where id = v_card_job.id
      and status in (
        'prepared', 'awaiting_payment', 'pending_update', 'processing', 'retry'
      );
    return new;
  end if;

  if new.job_status = 'processing' then
    -- RETURN NULL skips only this worker claim. The recurrence row remains
    -- pending/retry and will be reconsidered after the card boundary resolves.
    return null;
  end if;

  return new;
end
$$;


ALTER FUNCTION private.guard_card_recurrence_cancel_card_update() OWNER TO postgres;

--
-- Name: guard_development_unit_property_deal_type(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_development_unit_property_deal_type() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_finalidade text;
  v_legacy text;
begin
  if new.property_id is null then
    return new;
  end if;

  select property.finalidade, property.tipo_de_negocio
    into v_finalidade, v_legacy
  from public.properties as property
  where property.organization_id = new.organization_id
    and property.id = new.property_id
  for key share;

  if not found
     or private.canonical_property_deal_type(v_finalidade) is distinct from 'lancamento'
     or private.canonical_property_deal_type(v_legacy) is distinct from 'lancamento' then
    raise exception 'development units can only link to launch properties'
      using errcode = '23514', constraint = 'property_development_unit_deal_type_sync';
  end if;
  return new;
end
$$;


ALTER FUNCTION private.guard_development_unit_property_deal_type() OWNER TO postgres;

--
-- Name: guard_expired_whatsapp_unlinked_message_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_expired_whatsapp_unlinked_message_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_snapshot public.whatsapp_webhook_routing_snapshots%rowtype;
  v_resolution jsonb;
begin
  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = new.conversation_id
    and conversation.organization_id = new.organization_id;
  if not found or not v_conversation.unlinked_retention_v1
     or v_conversation.lead_id is not null
     or coalesce(v_conversation.is_group, false) then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and old.capture_state = 'unlinked_ephemeral'
     and new.capture_state = 'promoted_unlinked'
     and private.whatsapp_unlinked_promotion_is_authorized(old, new)
     and exists (
       select 1 from private.whatsapp_unlinked_history_links as link
       where link.conversation_id = v_conversation.id
         and link.organization_id = v_conversation.organization_id
         and link.lead_id = new.lead_id
         and link.binding_mode = 'history_only'
         and link.confirmed_at < v_conversation.created_at + interval '7 days'
     ) then
    return new;
  end if;
  if v_conversation.retired_at is null
     and v_conversation.created_at > pg_catalog.clock_timestamp() - interval '7 days' then
    return new;
  end if;

  if v_conversation.retired_at is not null
     and v_conversation.created_at > pg_catalog.clock_timestamp() - interval '7 days'
     and new.capture_state = 'unlinked_ephemeral' then
    select snapshot.* into v_snapshot
    from public.whatsapp_webhook_routing_snapshots as snapshot
    where snapshot.organization_id = new.organization_id
      and snapshot.session_id = new.session_id
      and snapshot.provider_message_id = new.provider_message_id;
    v_resolution := private.whatsapp_unlinked_capture_resolution(
      new.organization_id, new.session_id, new.conversation_id,
      new.provider_message_id, v_snapshot.inbox_event_key
    );
    if v_resolution->>'capture_state' = 'unlinked_ephemeral'
       and new.sent_at <= v_conversation.retired_at then
      return new;
    end if;
  end if;

  if new.capture_state is distinct from 'suppressed'
     or new.content is not null
     or new.media_url is not null
     or new.media_storage_path is not null
     or new.media_mime_type is not null
     or new.media_error is not null
     or new.sender_jid is not null
     or new.sender_name is not null
     or new.reaction_sender_jid is not null
     or new.reaction_sender_name is not null
     or coalesce(new.metadata, '{}'::jsonb)
          not in ('{}'::jsonb, '{"unlinked_retention_v1":"expired"}'::jsonb) then
    raise exception using errcode = '23514',
      message = 'expired_unlinked_message_content_forbidden';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_expired_whatsapp_unlinked_message_write() OWNER TO postgres;

--
-- Name: guard_lead_clocks(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_lead_clocks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment_event boolean;
  v_board_event_at timestamptz;
  v_reentry_event boolean;
begin
  if tg_op = 'INSERT' then
    new.attention_eligible := true;
    new.attention_enrolled_at := coalesce(new.attention_enrolled_at, now());
    if new.stage_id is not null then
      new.stage_entered_at := coalesce(
        new.stage_entered_at,
        new.created_at,
        now()
      );
    end if;
    if new.assigned_user_id is not null then
      new.assigned_at := coalesce(new.assigned_at, new.created_at, now());
    end if;
    new.board_order_at := coalesce(
      new.board_order_at,
      new.last_entry_at,
      new.stage_entered_at,
      new.created_at,
      now()
    );
    return new;
  end if;

  v_assignment_event :=
    new.assigned_user_id is distinct from old.assigned_user_id
    or new.team_id is distinct from old.team_id
    or new.assigned_at is distinct from old.assigned_at;
  v_reentry_event :=
    coalesce(new.reentry_count, 0) > coalesce(old.reentry_count, 0);

  new.attention_eligible := old.attention_eligible;
  new.attention_enrolled_at := old.attention_enrolled_at;

  if new.stage_id is not distinct from old.stage_id
     and new.pipeline_id is not distinct from old.pipeline_id then
    new.stage_entered_at := old.stage_entered_at;
  elsif new.stage_id is null then
    new.stage_entered_at := null;
    new.board_order_at := null;
  else
    new.stage_entered_at := now();
    if new.board_order_at is not distinct from old.board_order_at then
      new.board_order_at := new.stage_entered_at;
    end if;
  end if;

  if new.assigned_user_id is distinct from old.assigned_user_id then
    new.assigned_at := case
      when new.assigned_user_id is null then null
      else now()
    end;
  end if;

  if new.stage_id is not null
     and (v_assignment_event or v_reentry_event) then
    v_board_event_at := clock_timestamp();
    new.board_order_at := greatest(
      coalesce(
        new.board_order_at,
        old.board_order_at,
        new.stage_entered_at,
        new.created_at,
        v_board_event_at
      ),
      v_board_event_at
    );
  end if;

  new.board_order_at := coalesce(
    new.board_order_at,
    old.board_order_at,
    new.stage_entered_at,
    new.created_at,
    now()
  );
  return new;
end;
$$;


ALTER FUNCTION private.guard_lead_clocks() OWNER TO postgres;

--
-- Name: FUNCTION guard_lead_clocks(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.guard_lead_clocks() IS 'Preserves real stage-entry time while advancing the independent pipeline order for stage moves, reentries and assignment events.';


--
-- Name: guard_linked_development_property_consistency(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_linked_development_property_consistency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  unit_status text;
  expected_status text;
  active_list_price numeric;
begin
  select unit.status
    into unit_status
  from public.property_development_units as unit
  where unit.organization_id = new.organization_id
    and unit.property_id = new.id
  limit 1;

  if not found then
    return new;
  end if;

  if private.canonical_property_deal_type(new.finalidade) is distinct from 'lancamento'
     or private.canonical_property_deal_type(new.tipo_de_negocio) is distinct from 'lancamento' then
    raise exception 'linked property deal type is managed by its development unit'
      using errcode = '23514', constraint = 'property_development_unit_deal_type_sync';
  end if;

  expected_status := private.development_unit_property_status(unit_status);
  if private.canonical_linked_property_status(coalesce(new.status, 'active'))
      is distinct from expected_status then
    raise exception 'linked property status is managed by its development unit'
      using errcode = '23514', constraint = 'property_development_unit_status_sync';
  end if;

  select unit_price.list_price
    into active_list_price
  from public.property_development_units as unit
  join public.property_development_price_tables as price_table
    on price_table.organization_id = unit.organization_id
   and price_table.development_id = unit.development_id
   and price_table.status = 'active'
  join public.property_development_unit_prices as unit_price
    on unit_price.organization_id = unit.organization_id
   and unit_price.development_id = unit.development_id
   and unit_price.price_table_id = price_table.id
   and unit_price.unit_id = unit.id
  where unit.organization_id = new.organization_id
    and unit.property_id = new.id
  order by price_table.version desc, price_table.id desc
  limit 1;

  if active_list_price is not null and new.preco is distinct from active_list_price then
    raise exception 'linked property price is managed by the active development price table'
      using errcode = '23514', constraint = 'property_development_unit_price_sync';
  end if;

  if expected_status in ('reserved', 'sold', 'inactive') and new.published_on_site then
    raise exception 'terminal linked properties cannot be published'
      using errcode = '23514', constraint = 'property_development_unit_publication_sync';
  end if;

  return new;
end
$$;


ALTER FUNCTION private.guard_linked_development_property_consistency() OWNER TO postgres;

--
-- Name: guard_live_round_robin_reference(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_live_round_robin_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_organization_id uuid;
  v_round_robin_id uuid;
begin
  v_round_robin_id := nullif(
    pg_catalog.to_jsonb(new)->>tg_argv[0],
    ''
  )::uuid;
  if v_round_robin_id is null then
    return new;
  end if;

  v_organization_id := nullif(
    pg_catalog.to_jsonb(new)->>'organization_id',
    ''
  )::uuid;

  perform 1
  from public.round_robins as queue
  where queue.id = v_round_robin_id
    and (
      v_organization_id is null
      or queue.organization_id = v_organization_id
    )
    and queue.deleted_at is null
  for key share;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'round_robin_reference_not_live';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.guard_live_round_robin_reference() OWNER TO postgres;

--
-- Name: guard_managed_schedule_removal(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_managed_schedule_removal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.settings ? 'operating_schedule' and not(new.settings ? 'operating_schedule') then
    raise exception using errcode='23514',message='queue_managed_schedule_cannot_be_removed'; end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_managed_schedule_removal() OWNER TO postgres;

--
-- Name: guard_managed_whatsapp_snapshot_queue(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_managed_whatsapp_snapshot_queue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_round_robin_id uuid;
  v_rule_id uuid;
  v_rule_match_value text;
begin
  if new.snapshot->>'managed_message_distribution' is distinct from 'true' then
    return new;
  end if;

  begin
    v_round_robin_id := nullif(
      pg_catalog.btrim(new.snapshot->>'origin_round_robin_id'),
      ''
    )::uuid;
    v_rule_id := nullif(
      pg_catalog.btrim(new.snapshot->>'rule_id'),
      ''
    )::uuid;
  exception
    when invalid_text_representation then
      raise exception using
        errcode = '23514',
        message = 'managed_whatsapp_snapshot_queue_invalid';
  end;

  if v_round_robin_id is null or v_rule_id is null then
    raise exception using
      errcode = '23514',
      message = 'managed_whatsapp_snapshot_context_required';
  end if;

  perform 1
  from public.round_robins as queue
  where queue.organization_id = new.organization_id
    and queue.id = v_round_robin_id
    and queue.deleted_at is null
    and coalesce(queue.is_active, true) = true
    and lower(pg_catalog.btrim(coalesce(
      queue.settings->>'require_checkin',
      'false'
    ))) not in ('true', '1', 'yes')
  for share;

  if found then
    select lower(pg_catalog.btrim(coalesce(
      nullif(rule.match_value, ''),
      rule.conditions->>'match_value',
      ''
    )))
    into v_rule_match_value
    from public.round_robin_rules as rule
    where rule.organization_id = new.organization_id
      and rule.id = v_rule_id
      and rule.round_robin_id = v_round_robin_id
      and coalesce(rule.is_active, true) = true
      and coalesce(
        nullif(rule.match_type, ''),
        rule.conditions->>'match_type',
        rule.name,
        ''
      ) = 'whatsapp_message_contains'
      and coalesce(
        nullif(pg_catalog.btrim(rule.match->>'whatsapp_session_id'), ''),
        nullif(pg_catalog.btrim(
          rule.conditions->'match'->>'whatsapp_session_id'
        ), '')
      ) = new.session_id::text
    for share;

    if found then
      perform 1
      from public.whatsapp_inbound_rules as inbound_rule
      where inbound_rule.organization_id = new.organization_id
        and inbound_rule.id = v_rule_id
        and inbound_rule.session_id = new.session_id
        and inbound_rule.target_round_robin_id = v_round_robin_id
        and coalesce(inbound_rule.is_active, true) = true
        and lower(pg_catalog.btrim(coalesce(
          inbound_rule.match_type,
          ''
        ))) = 'contains'
        and lower(pg_catalog.btrim(coalesce(
          inbound_rule.match_field,
          'message'
        ))) = 'message'
        and pg_catalog.btrim(coalesce(inbound_rule.match_value, '')) <> ''
        and lower(pg_catalog.btrim(inbound_rule.match_value)) =
          v_rule_match_value
      for share;
    end if;

    if found then
      return new;
    end if;
  end if;

  -- BEFORE INSERT also runs ahead of ON CONFLICT.  Permit the exact immutable
  -- provider replay that the uniqueness constraint will turn into a no-op,
  -- but never let a different route reuse that exception after tombstoning.
  if exists (
    select 1
    from public.whatsapp_webhook_routing_snapshots as existing
    where existing.organization_id = new.organization_id
      and existing.session_id = new.session_id
      and existing.provider_message_id = new.provider_message_id
      and existing.inbox_event_key = new.inbox_event_key
      and existing.processing_lane = new.processing_lane
      and existing.routing_key = new.routing_key
      and existing.predecessor_provider_message_id is not distinct from
        new.predecessor_provider_message_id
      and existing.binding_eligible = new.binding_eligible
      and existing.target_mode = new.target_mode
      and existing.snapshot = new.snapshot
  ) then
    return new;
  end if;

  raise exception using
    errcode = '23503',
    message = 'managed_whatsapp_snapshot_queue_not_live';
end;
$$;


ALTER FUNCTION private.guard_managed_whatsapp_snapshot_queue() OWNER TO postgres;

--
-- Name: guard_management_tag_deletion(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_management_tag_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Organization removal cascades configuration and tags together. Do not
  -- block that existing administrative lifecycle while the parent is gone.
  if not exists (select 1 from public.organizations where id = old.organization_id) then return old; end if;
  if exists (select 1 from private.management_tag_usages(old.organization_id, old.id)) then
    raise exception 'The tag is referenced by management configuration'
    using errcode = '23503', constraint = 'tags_management_dependency_guard';
  end if;
  return old;
end
$$;


ALTER FUNCTION private.guard_management_tag_deletion() OWNER TO postgres;

--
-- Name: guard_management_tag_references(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_management_tag_references() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  tenant_id uuid;
  old_tenant_id uuid;
  new_payload jsonb := to_jsonb(new);
  old_payload jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  new_ids uuid[];
  old_ids uuid[];
  tag_id uuid;
  flow_payload jsonb;
  version_id uuid;
begin
  tenant_id := private.safe_uuid(new_payload->>'organization_id');
  if tenant_id is null and tg_table_name = 'automation_nodes' then
    select organization_id into tenant_id from public.automations
    where id = private.safe_uuid(new_payload->>'automation_id');
  end if;
  old_tenant_id := private.safe_uuid(old_payload->>'organization_id');
  if old_tenant_id is null and tg_table_name = 'automation_nodes' and tg_op = 'UPDATE' then
    select organization_id into old_tenant_id from public.automations
    where id = private.safe_uuid(old_payload->>'automation_id');
  end if;
  new_ids := private.management_tag_configuration_ids(tg_table_name, new_payload);
  old_ids := private.management_tag_configuration_ids(tg_table_name, old_payload);
  -- Restoration or a tenant move must also revalidate dormant child records.
  if tg_op = 'UPDATE' and (old_tenant_id is distinct from tenant_id or
      (old_payload->>'deleted_at' is not null and new_payload->>'deleted_at' is null)) then
    if tg_table_name = 'round_robins' then
      select coalesce(array_agg(distinct tag), '{}'::uuid[]) into old_ids
      from public.round_robin_rules rule
      cross join lateral unnest(private.management_tag_configuration_ids('round_robin_rules', to_jsonb(rule))) tag
      where rule.round_robin_id = private.safe_uuid(new_payload->>'id');
      new_ids := new_ids || old_ids;
    elsif tg_table_name = 'automations' then
      select coalesce(array_agg(distinct tag), '{}'::uuid[]) into old_ids
      from public.automation_nodes node
      cross join lateral unnest(private.management_tag_configuration_ids('automation_nodes', to_jsonb(node))) tag
      where node.automation_id = private.safe_uuid(new_payload->>'id');
      new_ids := new_ids || old_ids;
    end if;
    old_ids := '{}'::uuid[];
  end if;
  -- Published and in-flight versions must be checked when they become usable,
  -- even if the tag was removed while that version was an inactive draft.
  if tg_table_name = 'automations' or
     (tg_table_name = 'automation_executions' and new_payload->>'status' in ('queued','running','waiting')) then
    version_id := private.safe_uuid(coalesce(new_payload->>'active_flow_version_id', new_payload->>'flow_version_id'));
    select to_jsonb(version) into flow_payload
    from public.automation_flow_versions version where id = version_id and organization_id = tenant_id;
    new_ids := new_ids || private.management_tag_configuration_ids('automation_flow_versions', flow_payload);
    if tg_op = 'UPDATE' and (tg_table_name = 'automations' or old_payload->>'status' in ('queued','running','waiting')) then
      version_id := private.safe_uuid(coalesce(old_payload->>'active_flow_version_id', old_payload->>'flow_version_id'));
      select to_jsonb(version) into flow_payload
      from public.automation_flow_versions version where id = version_id and organization_id = old_tenant_id;
      old_ids := old_ids || private.management_tag_configuration_ids('automation_flow_versions', flow_payload);
    end if;
  end if;
  -- Moving a configuration to another tenant requires validating every tag,
  -- even if its JSON reference set did not change.
  if old_tenant_id is distinct from tenant_id then old_ids := '{}'::uuid[]; end if;
  if tg_op = 'UPDATE' and (
    (tg_table_name in ('round_robins','automations') and old_payload->>'deleted_at' is not null and new_payload->>'deleted_at' is null)
    or (tg_table_name = 'automation_executions' and new_payload->>'status' in ('queued','running','waiting')
      and coalesce(old_payload->>'status', '') not in ('queued','running','waiting'))
  ) then old_ids := '{}'::uuid[]; end if;
  -- Unchanged IDs are not grandfathered across a same-tenant parent move.
  if tg_op = 'UPDATE' and (
    (tg_table_name in ('automation_nodes','automation_flow_versions','automation_executions')
      and old_payload->>'automation_id' is distinct from new_payload->>'automation_id')
    or (tg_table_name = 'round_robin_rules'
      and old_payload->>'round_robin_id' is distinct from new_payload->>'round_robin_id')
  ) then old_ids := '{}'::uuid[]; end if;
  for tag_id in select distinct id from unnest(new_ids) id where not id = any(old_ids) order by id loop
    perform id from public.tags where id = tag_id and organization_id = tenant_id for key share;
    if not found then
      raise exception 'A referenced tag is unavailable in this organization'
      using errcode = '23503', constraint = 'tags_management_reference_guard';
    end if;
  end loop;
  return new;
end
$$;


ALTER FUNCTION private.guard_management_tag_references() OWNER TO postgres;

--
-- Name: guard_meta_crm_feedback_backend_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_meta_crm_feedback_backend_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  restricted_write boolean := false;
begin
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    restricted_write :=
      new.crm_dataset_id is not null
      or new.crm_dataset_name is not null
      or new.crm_dataset_access_token is not null
      or new.crm_dataset_access_token_secret_ref is not null
      or new.conversion_feedback_enabled
      or new.conversion_feedback_status <> 'not_configured'
      or new.conversion_feedback_activated_at is not null
      or new.conversion_feedback_last_sent_at is not null
      or new.conversion_feedback_last_validated_at is not null
      or new.conversion_feedback_last_error is not null;
  else
    restricted_write :=
      new.crm_dataset_id is distinct from old.crm_dataset_id
      or new.crm_dataset_name is distinct from old.crm_dataset_name
      or new.crm_dataset_access_token is distinct from old.crm_dataset_access_token
      or new.crm_dataset_access_token_secret_ref is distinct from old.crm_dataset_access_token_secret_ref
      or new.conversion_feedback_enabled is distinct from old.conversion_feedback_enabled
      or new.conversion_feedback_status is distinct from old.conversion_feedback_status
      or new.conversion_feedback_activated_at is distinct from old.conversion_feedback_activated_at
      or new.conversion_feedback_last_sent_at is distinct from old.conversion_feedback_last_sent_at
      or new.conversion_feedback_last_validated_at is distinct from old.conversion_feedback_last_validated_at
      or new.conversion_feedback_last_error is distinct from old.conversion_feedback_last_error;
  end if;

  if restricted_write then
    raise exception using
      errcode = '42501',
      message = 'Meta CRM feedback configuration must be changed through the Vimob backend';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.guard_meta_crm_feedback_backend_write() OWNER TO postgres;

--
-- Name: guard_pending_managed_whatsapp_child_mutation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_pending_managed_whatsapp_child_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old jsonb;
  v_new jsonb;
  v_old_organization_id uuid;
  v_new_organization_id uuid;
  v_old_round_robin_id uuid;
  v_new_round_robin_id uuid;
  v_reference record;
  v_queue_column text := case
    when tg_table_name = 'whatsapp_inbound_rules'
      then 'target_round_robin_id'
    else 'round_robin_id'
  end;
begin
  if tg_op <> 'INSERT' then
    v_old := pg_catalog.to_jsonb(old);
  end if;
  if tg_op <> 'DELETE' then
    v_new := pg_catalog.to_jsonb(new);
  end if;

  if tg_table_name = 'round_robin_members'
     and tg_op = 'UPDATE'
     and (v_new - array['leads_count', 'updated_at']) is not distinct from
         (v_old - array['leads_count', 'updated_at']) then
    return new;
  end if;

  if v_old is not null then
    v_old_organization_id := nullif(
      v_old->>'organization_id',
      ''
    )::uuid;
    v_old_round_robin_id := nullif(
      v_old->>v_queue_column,
      ''
    )::uuid;
  end if;
  if v_new is not null then
    v_new_organization_id := nullif(
      v_new->>'organization_id',
      ''
    )::uuid;
    v_new_round_robin_id := nullif(
      v_new->>v_queue_column,
      ''
    )::uuid;
  end if;

  -- Organization deletion owns the entire tenant namespace. Its FK cascades
  -- may reach queue children before the pending routing snapshot itself, so a
  -- terminal child DELETE must not be mistaken for a live queue mutation.
  -- Ordinary queue/rule deletion still sees its organization and remains
  -- fenced until the managed snapshot has a real terminal outcome.
  if tg_op = 'DELETE'
     and v_old_organization_id is not null
     and not exists (
       select 1
       from public.organizations as organization
       where organization.id = v_old_organization_id
     ) then
    return old;
  end if;

  for v_reference in
    select distinct reference.organization_id, reference.round_robin_id
    from (
      values
        (v_old_organization_id, v_old_round_robin_id),
        (v_new_organization_id, v_new_round_robin_id)
    ) as reference(organization_id, round_robin_id)
    where reference.organization_id is not null
      and reference.round_robin_id is not null
    order by reference.organization_id, reference.round_robin_id
  loop
    perform 1
    from public.round_robins as queue
    where queue.organization_id = v_reference.organization_id
      and queue.id = v_reference.round_robin_id
    for update;

    if found and private.round_robin_has_pending_whatsapp_intake(
      v_reference.organization_id,
      v_reference.round_robin_id
    ) then
      raise exception using
        errcode = '55000',
        message = 'round_robin_pending_whatsapp_intake';
    end if;
  end loop;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_pending_managed_whatsapp_child_mutation() OWNER TO postgres;

--
-- Name: FUNCTION guard_pending_managed_whatsapp_child_mutation(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.guard_pending_managed_whatsapp_child_mutation() IS 'round_robin_pending_intake_org_cascade_v2';


--
-- Name: guard_property_creation_ledger(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_creation_ledger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.metadata ? '_creation_idempotency' then
    if not coalesce(new.metadata ? '_creation_idempotency', false) then
      new.metadata := coalesce(new.metadata, '{}'::jsonb)
        || jsonb_build_object('_creation_idempotency', old.metadata -> '_creation_idempotency');
    elsif old.metadata -> '_creation_idempotency' is distinct from new.metadata -> '_creation_idempotency' then
      raise exception using errcode = '23514', message = 'property creation reservation is immutable';
    end if;
  elsif new.metadata ? '_creation_idempotency' then
    raise exception using errcode = '23514', message = 'property creation reservation cannot be assigned after creation';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_property_creation_ledger() OWNER TO postgres;

--
-- Name: guard_property_creation_receipt(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_creation_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if row(new.organization_id, new.actor_id, new.key_hash, new.request_hash, new.created_at)
    is distinct from row(old.organization_id, old.actor_id, old.key_hash, old.request_hash, old.created_at) then
    raise exception using errcode = '23514', message = 'property creation receipt identity is immutable';
  end if;
  if old.state = 'removed' and row(new.property_id, new.state) is distinct from row(old.property_id, old.state) then
    raise exception using errcode = '23514', message = 'removed property creation receipt cannot be revived';
  end if;
  if new.property_id is distinct from old.property_id then
    if new.property_id is not null or exists (
      select 1 from public.properties property
      where property.organization_id = old.organization_id and property.id = old.property_id
    ) then
      raise exception using errcode = '23514', message = 'property creation receipt cannot be reassigned or detached';
    end if;
  end if;
  -- FK ON DELETE SET NULL retains the receipt and becomes a durable tombstone.
  new.state := case when new.property_id is null then 'removed' else 'created' end;
  return new;
end;
$$;


ALTER FUNCTION private.guard_property_creation_receipt() OWNER TO postgres;

--
-- Name: guard_property_development_price_table(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_development_price_table() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.status in ('active', 'expired', 'archived')
     and (
       new.id is distinct from old.id
       or new.organization_id is distinct from old.organization_id
       or new.development_id is distinct from old.development_id
       or new.name is distinct from old.name
       or new.version is distinct from old.version
       or new.currency is distinct from old.currency
       or new.valid_from is distinct from old.valid_from
       or (
         new.valid_until is distinct from old.valid_until
         and not (
           old.status = 'active'
           and new.status = 'expired'
           and old.valid_until is null
         )
       )
       or new.notes is distinct from old.notes
       or new.approved_at is distinct from old.approved_at
       or new.metadata is distinct from old.metadata
       or new.created_at is distinct from old.created_at
     ) then
    raise exception using
      errcode = '23514',
      message = 'property_development_price_table_is_immutable';
  end if;

  if new.status is distinct from old.status
     and not (
       (old.status = 'draft' and new.status in ('approved', 'active', 'archived'))
       or (old.status = 'approved' and new.status in ('draft', 'active', 'archived'))
       or (old.status = 'active' and new.status in ('expired', 'archived'))
       or (old.status = 'expired' and new.status = 'archived')
     ) then
    raise exception using
      errcode = '23514',
      message = 'property_development_price_table_transition_invalid';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.guard_property_development_price_table() OWNER TO postgres;

--
-- Name: guard_property_development_reservation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_development_reservation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.organization_id is distinct from old.organization_id
     or new.development_id is distinct from old.development_id
     or new.unit_id is distinct from old.unit_id
     or (
       new.lead_id is distinct from old.lead_id
       and not (old.lead_id is not null and new.lead_id is null)
     )
     or new.price_table_id is distinct from old.price_table_id
     or new.reserved_by is distinct from old.reserved_by
     or new.list_price_snapshot is distinct from old.list_price_snapshot
     or new.currency is distinct from old.currency
     or new.payment_snapshot is distinct from old.payment_snapshot
     or new.idempotency_key is distinct from old.idempotency_key
     or new.created_at is distinct from old.created_at then
    raise exception using
      errcode = '23514',
      message = 'property_development_reservation_identity_is_immutable';
  end if;

  -- Once the TTL has elapsed, extending it or choosing a business outcome can
  -- race with the expiration worker. Only the canonical active -> expired
  -- transition is allowed. Incidental updates that do not touch status or TTL
  -- remain valid for audit/enrichment compatibility.
  if old.status = 'active'
     and old.expires_at <= clock_timestamp()
     and (
       new.status is distinct from old.status
       or new.expires_at is distinct from old.expires_at
     )
     and not (
       new.status = 'expired'
       and new.expires_at is not distinct from old.expires_at
     ) then
    raise exception using
      errcode = '23514',
      message = 'property_development_elapsed_reservation_requires_expired';
  end if;

  if new.status is distinct from old.status
     and not (
       old.status = 'active'
       and new.status in ('converted', 'cancelled', 'expired')
     ) then
    raise exception using
      errcode = '23514',
      message = 'property_development_reservation_transition_invalid';
  end if;

  if old.status = 'active'
     and new.status = 'expired'
     and old.expires_at > clock_timestamp() then
    raise exception using
      errcode = '23514',
      message = 'property_development_reservation_not_due';
  end if;

  if new.status = 'active'
     and new.expires_at is distinct from old.expires_at
     and (
       new.expires_at <= clock_timestamp()
       or new.expires_at > clock_timestamp() + interval '30 days'
     ) then
    raise exception using
      errcode = '23514',
      message = 'property_development_reservation_expiration_invalid';
  end if;

  if old.status = 'active' and new.status = 'converted' then
    new.converted_at := clock_timestamp();
    new.cancelled_at := null;
  elsif old.status = 'active' and new.status = 'cancelled' then
    new.cancelled_at := clock_timestamp();
    new.converted_at := null;
  elsif old.status = 'active' and new.status = 'expired' then
    new.converted_at := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.guard_property_development_reservation() OWNER TO postgres;

--
-- Name: guard_property_development_unit_price(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_development_unit_price() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_price_table_id uuid;
  target_status text;
begin
  target_price_table_id := new.price_table_id;

  select price_table.status
  into target_status
  from public.property_development_price_tables as price_table
  where price_table.id = target_price_table_id;

  if target_status is distinct from 'draft' then
    if tg_op = 'INSERT' then
      raise exception using
        errcode = '23514',
        message = 'property_development_unit_price_requires_draft_table';
    end if;

    if new.id is distinct from old.id
       or new.organization_id is distinct from old.organization_id
       or new.development_id is distinct from old.development_id
       or new.price_table_id is distinct from old.price_table_id
       or new.unit_id is distinct from old.unit_id
       or new.list_price is distinct from old.list_price
       or new.minimum_price is distinct from old.minimum_price
       or new.price_per_sqm is distinct from old.price_per_sqm
       or new.payment_terms is distinct from old.payment_terms
       or new.metadata is distinct from old.metadata
       or new.created_at is distinct from old.created_at
       or (
         new.created_by is distinct from old.created_by
         and new.created_by is not null
       )
       or (
         new.updated_by is distinct from old.updated_by
         and new.updated_by is not null
       ) then
      raise exception using
        errcode = '23514',
        message = 'property_development_unit_price_requires_draft_table';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.guard_property_development_unit_price() OWNER TO postgres;

--
-- Name: guard_property_legacy_location_catalog_mutation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_legacy_location_catalog_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_in_use boolean := false;
begin
  if tg_table_name = 'property_cities' then
    if tg_op = 'INSERT' then
      perform private.lock_property_legacy_location_name(
        new.organization_id,
        'city',
        new.name
      );
      return new;
    end if;

    if new.organization_id is not distinct from old.organization_id
       and lower(btrim(new.name)) = lower(btrim(old.name))
       and upper(btrim(coalesce(new.uf, ''))) = upper(btrim(coalesce(old.uf, ''))) then
      return new;
    end if;

    perform private.lock_property_legacy_location_name(
      old.organization_id,
      'city',
      old.name
    );
    perform private.lock_property_legacy_location_name(
      new.organization_id,
      'city',
      new.name
    );

    select exists (
      select 1
      from public.properties property
      where property.city_id is null
        and nullif(btrim(property.cidade), '') is not null
        and (
          (
            property.organization_id = old.organization_id
            and lower(btrim(property.cidade)) = lower(btrim(old.name))
            and (
              nullif(btrim(coalesce(old.uf, '')), '') is null
              or upper(btrim(coalesce(property.uf, ''))) = upper(btrim(old.uf))
            )
          )
          or (
            property.organization_id = new.organization_id
            and lower(btrim(property.cidade)) = lower(btrim(new.name))
            and (
              nullif(btrim(coalesce(new.uf, '')), '') is null
              or upper(btrim(coalesce(property.uf, ''))) = upper(btrim(new.uf))
            )
          )
        )
    ) into v_in_use;

  elsif tg_table_name = 'property_neighborhoods' then
    if tg_op = 'INSERT' then
      perform private.lock_property_legacy_location_name(
        new.organization_id,
        'neighborhood',
        new.name
      );
      return new;
    end if;

    if new.organization_id is not distinct from old.organization_id
       and new.city_id is not distinct from old.city_id
       and lower(btrim(new.name)) = lower(btrim(old.name)) then
      return new;
    end if;

    perform private.lock_property_legacy_location_name(
      old.organization_id,
      'neighborhood',
      old.name
    );
    perform private.lock_property_legacy_location_name(
      new.organization_id,
      'neighborhood',
      new.name
    );

    select exists (
      select 1
      from public.properties property
      left join public.property_cities old_city
        on old_city.organization_id = old.organization_id
       and old_city.id = old.city_id
      left join public.property_cities new_city
        on new_city.organization_id = new.organization_id
       and new_city.id = new.city_id
      where property.neighborhood_id is null
        and nullif(btrim(property.bairro), '') is not null
        and (
          (
            property.organization_id = old.organization_id
            and lower(btrim(property.bairro)) = lower(btrim(old.name))
            and (
              old.city_id is null
              or property.city_id = old.city_id
              or (
                property.city_id is null
                and lower(btrim(coalesce(property.cidade, '')))
                    = lower(btrim(coalesce(old_city.name, '')))
              )
            )
          )
          or (
            property.organization_id = new.organization_id
            and lower(btrim(property.bairro)) = lower(btrim(new.name))
            and (
              new.city_id is null
              or property.city_id = new.city_id
              or (
                property.city_id is null
                and lower(btrim(coalesce(property.cidade, '')))
                    = lower(btrim(coalesce(new_city.name, '')))
              )
            )
          )
        )
    ) into v_in_use;
  end if;

  if v_in_use then
    raise exception 'legacy property location must be attached before catalog rename or move'
      using errcode = '23503', constraint = 'property_location_in_use';
  end if;
  return new;
end
$$;


ALTER FUNCTION private.guard_property_legacy_location_catalog_mutation() OWNER TO postgres;

--
-- Name: guard_property_location_deactivation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_location_deactivation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_in_use boolean := false;
  v_id uuid := old.id;
  v_organization_id uuid := old.organization_id;
begin
  if tg_op = 'UPDATE'
     and (not coalesce(old.is_active, true) or coalesce(new.is_active, true)) then
    return new;
  end if;

  if tg_table_name = 'property_cities' then
    perform private.lock_property_legacy_location_name(
      v_organization_id,
      'city',
      old.name
    );
    select exists (
      select 1 from public.properties property
      where property.organization_id = v_organization_id
        and property.city_id = v_id
    ) or exists (
      select 1 from public.property_neighborhoods neighborhood
      where neighborhood.organization_id = v_organization_id
        and neighborhood.city_id = v_id
        and coalesce(neighborhood.is_active, true)
    ) or exists (
      select 1 from public.property_condominiums condominium
      where condominium.organization_id = v_organization_id
        and condominium.city_id = v_id
        and coalesce(condominium.is_active, true)
    ) or exists (
      select 1 from public.properties property
      where property.organization_id = v_organization_id
        and property.city_id is null
        and nullif(btrim(property.cidade), '') is not null
        and lower(btrim(property.cidade)) = lower(btrim(old.name))
        and (
          nullif(btrim(coalesce(old.uf, '')), '') is null
          or upper(btrim(coalesce(property.uf, ''))) = upper(btrim(old.uf))
        )
    ) into v_in_use;

  elsif tg_table_name = 'property_neighborhoods' then
    perform private.lock_property_legacy_location_name(
      v_organization_id,
      'neighborhood',
      old.name
    );
    select exists (
      select 1 from public.properties property
      where property.organization_id = v_organization_id
        and property.neighborhood_id = v_id
    ) or exists (
      select 1 from public.property_condominiums condominium
      where condominium.organization_id = v_organization_id
        and condominium.neighborhood_id = v_id
        and coalesce(condominium.is_active, true)
    ) or exists (
      select 1
      from public.properties property
      left join public.property_cities city
        on city.organization_id = v_organization_id
       and city.id = old.city_id
      where property.organization_id = v_organization_id
        and property.neighborhood_id is null
        and nullif(btrim(property.bairro), '') is not null
        and lower(btrim(property.bairro)) = lower(btrim(old.name))
        and (
          old.city_id is null
          or property.city_id = old.city_id
          or (
            property.city_id is null
            and lower(btrim(coalesce(property.cidade, '')))
                = lower(btrim(coalesce(city.name, '')))
          )
        )
    ) into v_in_use;

  elsif tg_table_name = 'property_condominiums' then
    select exists (
      select 1 from public.properties property
      where property.organization_id = v_organization_id
        and property.condominium_id = v_id
    ) into v_in_use;
  end if;

  if v_in_use then
    raise exception 'property location is still in use'
      using errcode = '23503', constraint = 'property_location_in_use';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;


ALTER FUNCTION private.guard_property_location_deactivation() OWNER TO postgres;

--
-- Name: FUNCTION guard_property_location_deactivation(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.guard_property_location_deactivation() IS 'Prevents city, neighborhood or condominium deactivation while canonical or compatible legacy property associations remain.';


--
-- Name: guard_property_owner_deactivation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_owner_deactivation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner_id uuid := old.id;
  v_organization_id uuid := old.organization_id;
begin
  if tg_op = 'UPDATE'
     and (not coalesce(old.is_active, true) or coalesce(new.is_active, true)) then
    return new;
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext(v_organization_id::text),
    pg_catalog.hashtext('property-owner-name:' || lower(btrim(old.name)))
  ) then
    raise exception 'property owner name changed concurrently; retry the mutation'
      using errcode = '40001', constraint = 'property_owner_assignment_busy';
  end if;

  if exists (
    select 1
    from public.properties property
    where property.organization_id = v_organization_id
      and property.owner_id = v_owner_id
  ) or exists (
    select 1
    from public.property_ownerships ownership
    where ownership.organization_id = v_organization_id
      and ownership.owner_id = v_owner_id
      and (ownership.valid_to is null or current_date < ownership.valid_to)
  ) or exists (
    select 1
    from public.properties property
    where property.organization_id = v_organization_id
      and property.owner_id is null
      and nullif(btrim(property.owner_name), '') is not null
      and lower(btrim(property.owner_name)) = lower(btrim(old.name))
  ) then
    raise exception 'property owner is still in use'
      using errcode = '23503', constraint = 'property_owner_active_reference';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;


ALTER FUNCTION private.guard_property_owner_deactivation() OWNER TO postgres;

--
-- Name: FUNCTION guard_property_owner_deactivation(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.guard_property_owner_deactivation() IS 'Serializes owner deactivation or deletion with canonical, normalized, and legacy name-only property assignments.';


--
-- Name: guard_property_owner_legacy_rename(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_property_owner_legacy_rename() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old_name text;
  v_new_name text := lower(btrim(new.name));
  v_legacy_name_in_use boolean := false;
  v_existing_name_matches integer := 0;
begin
  if tg_op = 'INSERT' then
    if not pg_catalog.pg_try_advisory_xact_lock(
      pg_catalog.hashtext(new.organization_id::text),
      pg_catalog.hashtext('property-owner-name:' || v_new_name)
    ) then
      raise exception 'property owner name changed concurrently; retry the mutation'
        using errcode = '40001', constraint = 'property_owner_assignment_busy';
    end if;

    select exists (
      select 1
      from public.properties property
      where property.organization_id = new.organization_id
        and property.owner_id is null
        and nullif(btrim(property.owner_name), '') is not null
        and lower(btrim(property.owner_name)) = v_new_name
    ) into v_legacy_name_in_use;

    if v_legacy_name_in_use then
      -- A name-only legacy property may resolve to the first catalog owner only
      -- when that owner is active. Further same-name owners would make the
      -- compatibility association ambiguous and must wait until materialization.
      if not coalesce(new.is_active, true) then
        raise exception 'legacy property owner must be active when first cataloged'
          using errcode = '23514', constraint = 'property_owner_assignment_invalid';
      end if;

      select count(*)::integer
        into v_existing_name_matches
      from public.property_owners owner
      where owner.organization_id = new.organization_id
        and lower(btrim(owner.name)) = v_new_name;

      if v_existing_name_matches > 0 then
        raise exception 'legacy property owner name is already resolved; attach legacy properties before adding another same-name owner'
          using errcode = '23514', constraint = 'property_owner_assignment_invalid';
      end if;
    end if;
    return new;
  end if;

  v_old_name := lower(btrim(old.name));
  if new.organization_id is not distinct from old.organization_id
     and v_new_name = v_old_name then
    return new;
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext(old.organization_id::text),
    pg_catalog.hashtext('property-owner-name:' || v_old_name)
  ) then
    raise exception 'property owner name changed concurrently; retry the mutation'
      using errcode = '40001', constraint = 'property_owner_assignment_busy';
  end if;
  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext(new.organization_id::text),
    pg_catalog.hashtext('property-owner-name:' || v_new_name)
  ) then
    raise exception 'property owner name changed concurrently; retry the mutation'
      using errcode = '40001', constraint = 'property_owner_assignment_busy';
  end if;

  if exists (
    select 1
    from public.properties property
    where property.owner_id is null
      and nullif(btrim(property.owner_name), '') is not null
      and (
        (
          property.organization_id = old.organization_id
          and lower(btrim(property.owner_name)) = v_old_name
        )
        or (
          property.organization_id = new.organization_id
          and lower(btrim(property.owner_name)) = v_new_name
        )
      )
  ) then
    raise exception 'legacy property owner association must be attached or detached before owner rename'
      using errcode = '23503', constraint = 'property_owner_active_reference';
  end if;
  return new;
end
$$;


ALTER FUNCTION private.guard_property_owner_legacy_rename() OWNER TO postgres;

--
-- Name: FUNCTION guard_property_owner_legacy_rename(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.guard_property_owner_legacy_rename() IS 'Prevents a catalog rename from orphaning legacy properties associated only through owner_name.';


--
-- Name: guard_queue_pool_notification_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_queue_pool_notification_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if current_setting('role',true) in ('authenticated','anon') and (
    lower(coalesce(new.metadata->>'event_key',''))='queue_pool_available'
    or lower(coalesce(new.type,''))='queue_pool_available'
    or (tg_op='UPDATE' and (lower(coalesce(old.metadata->>'event_key',''))='queue_pool_available'
      or lower(coalesce(old.type,''))='queue_pool_available'))
  ) then raise exception using errcode='42501',message='queue_pool_notification_backend_owned'; end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_queue_pool_notification_write() OWNER TO postgres;

--
-- Name: guard_queue_runtime_capability_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_queue_runtime_capability_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare previous jsonb; incoming jsonb; org_ids uuid[]; queue_id uuid;
begin
  if tg_op<>'INSERT' then previous:=to_jsonb(old); end if;
  if tg_op<>'DELETE' then incoming:=to_jsonb(new); end if;
  if tg_table_name='users' then
    select array_agg(distinct m.organization_id) into org_ids from public.organization_members m
      where m.user_id in ((previous->>'id')::uuid,(incoming->>'id')::uuid);
  elsif tg_table_name='available_permissions' then
    select array_agg(distinct coalesce(p.organization_id,r.organization_id)) into org_ids
      from public.organization_role_permissions p left join public.organization_roles r
        on r.id=coalesce(p.role_id,p.organization_role_id)
      where p.permission_id in ((previous->>'id')::uuid,(incoming->>'id')::uuid);
  elsif tg_table_name='organizations' then
    org_ids:=array[(previous->>'id')::uuid,(incoming->>'id')::uuid];
  else
    org_ids:=array[(previous->>'organization_id')::uuid,(incoming->>'organization_id')::uuid];
    if tg_table_name in ('user_organization_roles','organization_role_permissions') then
      -- Support historical role assignments that still lack their own tenant.
      select org_ids||coalesce(array_agg(distinct r.organization_id),'{}'::uuid[]) into org_ids
        from public.organization_roles r where r.id in (
          coalesce(previous->>'role_id',previous->>'organization_role_id')::uuid,
          coalesce(incoming->>'role_id',incoming->>'organization_role_id')::uuid);
    end if;
  end if;
  for queue_id in select q.id from public.round_robins q
    where q.organization_id=any(org_ids) and q.settings ? 'operating_schedule' order by q.id
  loop
    begin
      perform 1 from public.round_robins q where q.id=queue_id for update nowait;
    exception when lock_not_available then
      raise exception using errcode='55P03',message='queue_membership_busy_retry';
    end;
  end loop;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_queue_runtime_capability_write() OWNER TO postgres;

--
-- Name: guard_queue_runtime_human_fact_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_queue_runtime_human_fact_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare previous jsonb; incoming jsonb; item record;
begin
  if tg_op<>'INSERT' then previous:=to_jsonb(old); end if;
  if tg_op<>'DELETE' then incoming:=to_jsonb(new); end if;
  for item in select l.organization_id,l.id from public.leads l
    where l.id in ((previous->>'lead_id')::uuid,(incoming->>'lead_id')::uuid)
      and exists(select 1 from private.queue_lead_runtime r where r.organization_id=l.organization_id and r.lead_id=l.id)
    order by l.organization_id,l.id
  loop
    perform 1 from public.leads where organization_id=item.organization_id and id=item.id for no key update;
  end loop;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_queue_runtime_human_fact_write() OWNER TO postgres;

--
-- Name: guard_queue_runtime_ownership(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_queue_runtime_ownership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare qid uuid; r private.queue_lead_runtime%rowtype; command private.queue_runtime_commands%rowtype;
begin
  if new.assigned_user_id is not distinct from old.assigned_user_id and new.assigned_at is not distinct from old.assigned_at then return new; end if;
  select * into r from private.queue_lead_runtime where organization_id=new.organization_id and lead_id=new.id;
  qid:=coalesce(r.round_robin_id,new.origin_round_robin_id);
  if qid is null or (r.lead_id is null and not private.queue_runtime_is_managed(new.organization_id,qid)) then return new; end if;
  select * into command from private.queue_runtime_commands where transaction_id=txid_current() and organization_id=new.organization_id and lead_id=new.id;
  if not found then raise exception using errcode='42501',message='managed_queue_ownership_requires_command'; end if;
  if command.mode in ('automatic','canonical') and r.state in ('manual_protected','human_protected','closed') then
    raise exception using errcode='42501',message='managed_queue_owner_protected'; end if;
  if new.assigned_user_id is not null and not private.queue_runtime_actor_active(new.organization_id,new.assigned_user_id) then
    raise exception using errcode='23514',message='managed_queue_inactive_recipient'; end if;
  if command.mode in ('automatic','canonical') and new.assigned_user_id is not null then
    if not coalesce((private.queue_window(new.organization_id,qid,clock_timestamp())->>'open')::boolean,false)
      or not exists(select 1 from private.queue_runtime_members(new.organization_id,qid,clock_timestamp()) m where m.user_id=new.assigned_user_id and m.is_available) then
      raise exception using errcode='23514',message='managed_queue_window_or_recipient_closed'; end if;
  end if;
  if r.state in ('pool_waiting','pool_ready','limit_exhausted') and command.mode='manual' then
    raise exception using errcode='42501',message='managed_queue_pool_requires_claim'; end if;
  if command.mode='manual' and new.assigned_user_id is null then
    raise exception using errcode='23514',message='managed_queue_manual_release_requires_pool'; end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_queue_runtime_ownership() OWNER TO postgres;

--
-- Name: guard_queue_runtime_roster_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_queue_runtime_roster_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare previous_queue uuid; incoming_queue uuid; queue_id uuid;
begin
  if tg_op<>'INSERT' then previous_queue:=old.round_robin_id; end if;
  if tg_op<>'DELETE' then incoming_queue:=new.round_robin_id; end if;
  for queue_id in select q.id from public.round_robins q
    where q.id in (previous_queue,incoming_queue) and q.settings ? 'operating_schedule' order by q.id
  loop
    begin
      perform 1 from public.round_robins where id=queue_id for update nowait;
    exception when lock_not_available then
      raise exception using errcode='55P03',message='queue_membership_busy_retry';
    end;
  end loop;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_queue_runtime_roster_write() OWNER TO postgres;

--
-- Name: guard_round_robin_hard_delete(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_round_robin_hard_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- An organization delete legitimately owns the whole identity namespace and
  -- reaches this row through ON DELETE CASCADE after the parent disappeared.
  if not exists (
    select 1
    from public.organizations as organization
    where organization.id = old.organization_id
  ) then
    return old;
  end if;

  raise exception using
    errcode = '55000',
    message = 'round_robin_hard_delete_forbidden';
end;
$$;


ALTER FUNCTION private.guard_round_robin_hard_delete() OWNER TO postgres;

--
-- Name: guard_round_robin_tombstone_state(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_round_robin_tombstone_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.deleted_at is not null then
    -- ON DELETE SET NULL is still allowed to retire references owned by rows
    -- outside this tombstone.  Everything that defines the immutable queue
    -- identity or frozen destination remains byte-for-byte unchanged.
    if (pg_catalog.to_jsonb(new) - array[
          'target_pipeline_id',
          'target_stage_id',
          'ai_agent_id',
          'created_by'
        ]) is distinct from
       (pg_catalog.to_jsonb(old) - array[
          'target_pipeline_id',
          'target_stage_id',
          'ai_agent_id',
          'created_by'
        ])
       or (
         new.target_pipeline_id is distinct from old.target_pipeline_id
         and new.target_pipeline_id is not null
       )
       or (
         new.target_stage_id is distinct from old.target_stage_id
         and new.target_stage_id is not null
       )
       or (
         new.ai_agent_id is distinct from old.ai_agent_id
         and new.ai_agent_id is not null
       )
       or (
         new.created_by is distinct from old.created_by
         and new.created_by is not null
       ) then
      raise exception using
        errcode = '23514',
        message = 'round_robin_tombstone_immutable';
    end if;
    return new;
  end if;

  if (
    new.deleted_at is distinct from old.deleted_at
    or new.is_active is distinct from old.is_active
    or new.pipeline_id is distinct from old.pipeline_id
    or new.target_pipeline_id is distinct from old.target_pipeline_id
    or new.target_stage_id is distinct from old.target_stage_id
    or new.strategy is distinct from old.strategy
    or new.settings is distinct from old.settings
    or new.reentry_behavior is distinct from old.reentry_behavior
    or new.rules is distinct from old.rules
  ) and private.round_robin_has_pending_whatsapp_intake(
    old.organization_id,
    old.id
  ) then
    raise exception using
      errcode = '55000',
      message = 'round_robin_pending_whatsapp_intake';
  end if;

  if new.deleted_at is null then
    if new.tombstone_pipeline_id is distinct from old.tombstone_pipeline_id
       or new.tombstone_stage_id is distinct from old.tombstone_stage_id then
      raise exception using
        errcode = '23514',
        message = 'round_robin_tombstone_snapshot_managed';
    end if;
    return new;
  end if;

  if new.is_active is not false then
    raise exception using
      errcode = '23514',
      message = 'round_robin_tombstone_must_be_inactive';
  end if;

  new.tombstone_pipeline_id := coalesce(
    old.target_pipeline_id,
    old.pipeline_id
  );
  new.tombstone_stage_id := old.target_stage_id;

  return new;
end;
$$;


ALTER FUNCTION private.guard_round_robin_tombstone_state() OWNER TO postgres;

