--
-- Name: guard_unconfirmed_whatsapp_attendance_marker(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_unconfirmed_whatsapp_attendance_marker() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.event_type <> 'whatsapp_attendance_joined' then
    return new;
  end if;

  if not exists (
    select 1
    from public.whatsapp_attendance_marker_confirmations as proof
    where proof.entry_id::text = new.metadata->>'attendance_entry_id'
      and proof.organization_id = new.organization_id
      and proof.lead_id = new.lead_id
      and proof.user_id = new.user_id
      and proof.user_id = new.actor_user_id
      and proof.message_id::text = new.metadata->>'confirmed_message_id'
      and proof.marker_kind = new.metadata->>'marker_kind'
      and proof.confirmed_at = new.event_at
  ) then
    return null;
  end if;

  if exists (
    select 1
    from public.lead_timeline_events as existing
    where existing.organization_id = new.organization_id
      and existing.lead_id = new.lead_id
      and existing.event_type = 'whatsapp_attendance_joined'
      and existing.metadata->>'attendance_entry_id' =
          new.metadata->>'attendance_entry_id'
  ) then
    return null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.guard_unconfirmed_whatsapp_attendance_marker() OWNER TO postgres;

--
-- Name: guard_whatsapp_avatar_storage_path_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_avatar_storage_path_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_request_role text := pg_catalog.lower(coalesce(
    nullif(pg_catalog.current_setting('request.jwt.claim.role', true), ''),
    current_user
  ));
  v_path_changed boolean := case
    when tg_op = 'INSERT' then new.whatsapp_avatar_storage_path is not null
    else new.whatsapp_avatar_storage_path is distinct from old.whatsapp_avatar_storage_path
  end;
begin
  if v_path_changed
     and (
       current_user in ('anon', 'authenticated', 'service_role')
       or v_request_role in ('anon', 'authenticated', 'service_role')
     ) then
    raise exception 'whatsapp_avatar_storage_path is backend-owned'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_avatar_storage_path_write() OWNER TO postgres;

--
-- Name: guard_whatsapp_contact_identity_pn(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_contact_identity_pn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_values text[]; v_conversation_id uuid;
begin
  v_values:=array[new.alias_jid,new.canonical_jid,new.contact_phone];
  if tg_op='UPDATE' then
    v_values:=v_values || array[old.alias_jid,old.canonical_jid,old.contact_phone];
  end if;
  for v_conversation_id in
    select conversation.id from public.whatsapp_conversations conversation
    where conversation.organization_id=new.organization_id and conversation.session_id=new.session_id
      and conversation.deleted_at is null and conversation.retired_at is null
      and conversation.remote_jid in (new.alias_jid,new.canonical_jid)
    order by conversation.id
  loop
    v_values:=v_values || private.whatsapp_conversation_contact_pn_evidence(
      new.organization_id,new.session_id,v_conversation_id);
  end loop;
  if private.whatsapp_contact_pns_conflict(v_values) then
    raise exception using errcode='23514',message='whatsapp_contact_pn_conflict';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_contact_identity_pn() OWNER TO postgres;

--
-- Name: guard_whatsapp_conversation_contact_pn(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_conversation_contact_pn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_values text[];
begin
  if tg_op='UPDATE' and new.remote_jid is not distinct from old.remote_jid
    and (nullif(pg_catalog.btrim(new.contact_phone),'') is null
      or new.contact_phone is not distinct from old.contact_phone) then return new; end if;
  v_values:=array[new.remote_jid,new.contact_phone];
  if tg_op='UPDATE' then
    -- OLD is the row after PostgreSQL's concurrent UPDATE recheck. A STABLE
    -- helper can still see the statement's older snapshot after a row-lock
    -- wait, so retain this authoritative tuple explicitly as well.
    v_values:=v_values || array[old.remote_jid,old.contact_phone] || private.whatsapp_conversation_contact_pn_evidence(
      old.organization_id,old.session_id,old.id);
  end if;
  if private.whatsapp_contact_pns_conflict(v_values) then
    raise exception using errcode='23514',message='whatsapp_contact_pn_conflict';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_conversation_contact_pn() OWNER TO postgres;

--
-- Name: guard_whatsapp_media_job_epoch_insert(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_media_job_epoch_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_message public.whatsapp_messages%rowtype;
begin
  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = new.conversation_id
    and conversation.organization_id = new.organization_id
  for share;
  if not found or not v_conversation.unlinked_retention_v1
     or v_conversation.lead_id is not null
     or coalesce(v_conversation.is_group, false) then
    return new;
  end if;
  if v_conversation.created_at <= pg_catalog.clock_timestamp() - interval '7 days' then
    raise exception using errcode = '23514',
      message = 'expired_unlinked_media_job_forbidden';
  end if;
  if v_conversation.retired_at is not null then
    select message.* into v_message
    from public.whatsapp_messages as message
    where message.id = new.message_id
      and message.organization_id = new.organization_id
      and message.session_id = new.session_id
      and message.conversation_id = new.conversation_id;
    if not found or v_message.capture_state <> 'unlinked_ephemeral'
       or v_message.sent_at > v_conversation.retired_at then
      raise exception using errcode = '23514',
        message = 'retired_unlinked_media_job_requires_prior_message';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_media_job_epoch_insert() OWNER TO postgres;

--
-- Name: guard_whatsapp_media_job_gc_attach(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_media_job_gc_attach() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_path text;
  v_status text;
begin
  for v_path in
    select distinct path_value
    from pg_catalog.unnest(array[
      new.storage_path,
      new.message_key->>'upload_intent_path',
      new.message_key->>'repair_storage_path'
    ]) as path_value
    where path_value is not null
    order by path_value
  loop
    if tg_op = 'UPDATE' then
      if v_path is not distinct from old.storage_path
         or v_path is not distinct from old.message_key->>'upload_intent_path'
         or v_path is not distinct from old.message_key->>'repair_storage_path' then
        continue;
      end if;
    end if;
    select gc.status into v_status
    from private.whatsapp_unlinked_media_gc as gc
    where gc.organization_id = new.organization_id
      and gc.bucket_id = 'whatsapp-media'
      and gc.object_path = v_path
    for share;
    if v_status = 'processing' then
      raise exception using errcode = '40001',
        message = 'whatsapp_media_gc_path_unavailable';
    end if;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_media_job_gc_attach() OWNER TO postgres;

--
-- Name: guard_whatsapp_message_media_gc_attach(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_message_media_gc_attach() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text;
begin
  if new.media_storage_path is null then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.media_storage_path is not distinct from old.media_storage_path then
      return new;
    end if;
  end if;
  select gc.status into v_status
  from private.whatsapp_unlinked_media_gc as gc
  where gc.organization_id = new.organization_id
    and gc.bucket_id = 'whatsapp-media'
    and gc.object_path = new.media_storage_path
  for share;
  if v_status = 'processing' then
    raise exception using errcode = '40001',
      message = 'whatsapp_media_gc_path_unavailable';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_message_media_gc_attach() OWNER TO postgres;

--
-- Name: guard_whatsapp_observed_unattended(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_observed_unattended() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.capture_state is distinct from 'observed_unattended' then
    return new;
  end if;
  if not exists (
    select 1 from public.whatsapp_conversations as conversation
    join public.whatsapp_conversation_lead_bindings as binding
      on binding.conversation_id = conversation.id
     and binding.organization_id = conversation.organization_id
     and binding.active_to is null
    where conversation.id = new.conversation_id
      and conversation.organization_id = new.organization_id
      and conversation.session_id = new.session_id
      and conversation.lead_id = new.lead_id
      and binding.lead_id = new.lead_id
      and conversation.retired_at is null
  ) then
    raise exception using errcode = '23514',
      message = 'observed_unattended_requires_current_lead_binding';
  end if;
  if new.from_me and (
    exists (
      select 1 from public.whatsapp_outbox as outbox
      where outbox.organization_id = new.organization_id
        and outbox.session_id = new.session_id
        and (
          outbox.provider_message_id = new.provider_message_id
          or outbox.client_message_id = new.client_message_id
        )
    ) or exists (
      select 1 from public.outbox_messages as outbox
      where outbox.organization_id = new.organization_id
        and outbox.session_id = new.session_id
        and outbox.conversation_id = new.conversation_id
        and (
          outbox.sent_message_id = new.provider_message_id
          or outbox.client_message_id = new.client_message_id
        )
    )
  ) then
    raise exception using errcode = '23514',
      message = 'managed_outbound_cannot_be_observed_unattended';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_observed_unattended() OWNER TO postgres;

--
-- Name: guard_whatsapp_unlinked_message_attribution(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_unlinked_message_attribution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.capture_state = 'unlinked_ephemeral' then
    if new.capture_state = 'unlinked_ephemeral' and new.lead_id is null then
      return new;
    end if;
    if new.capture_state = 'suppressed' and new.lead_id is null then
      return new;
    end if;
    if private.whatsapp_unlinked_promotion_is_authorized(old, new) then
      return new;
    end if;
    raise exception using errcode = '23514',
      message = 'whatsapp_unlinked_message_attribution_immutable';
  end if;

  if old.capture_state = 'promoted_unlinked'
     and (
       new.lead_id is distinct from old.lead_id
       or new.capture_state is distinct from old.capture_state
     ) then
    raise exception using errcode = '23514',
      message = 'whatsapp_promoted_unlinked_attribution_immutable';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_unlinked_message_attribution() OWNER TO postgres;

