--
-- Name: guard_whatsapp_webhook_inbox_epoch(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_webhook_inbox_epoch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_active_epoch integer;
  v_route jsonb;
begin
  if tg_op = 'UPDATE' then
    if new.processing_epoch is distinct from old.processing_epoch then
      raise exception using errcode = '23514', message = 'whatsapp_inbox_epoch_immutable';
    end if;
  end if;

  -- Also serializes a direct insert/update with activation. The normal claim
  -- already owns a compatible lock on the session row.
  perform 1
  from public.whatsapp_sessions as session
  where session.id = new.session_id
    and session.organization_id = new.organization_id
  for key share;
  if not found then
    raise exception using errcode = '23503', message = 'whatsapp_inbox_epoch_session_mismatch';
  end if;

  select coalesce((
    select cutover.active_epoch
    from private.whatsapp_webhook_session_cutovers as cutover
    where cutover.session_id = new.session_id
  ), 0) into v_active_epoch;

  if new.processing_epoch not in (0, 1) or new.processing_epoch > v_active_epoch then
    raise exception using errcode = '23514', message = 'whatsapp_inbox_epoch_invalid';
  end if;

  -- A replica running the pre-cutover ingress has no epoch marker. Reject a
  -- brand-new event instead of acknowledging it into the retained epoch. A
  -- duplicate of an already stored key must still reach ON CONFLICT.
  if tg_op = 'INSERT' and v_active_epoch = 1 and new.processing_epoch = 0
    and (new.payload #> '{__vimob_ingress,epoch_capable}') is distinct from 'true'::jsonb
    and not exists (
      select 1 from public.whatsapp_webhook_inbox as existing
      where existing.event_key = new.event_key
        and existing.organization_id = new.organization_id
        and existing.session_id = new.session_id
    )
  then
    raise exception using errcode = '55000', message = 'whatsapp_inbox_epoch_legacy_ingress';
  end if;

  if tg_op = 'UPDATE' and v_active_epoch = 1 and new.processing_epoch = 0 then
    if new.status is distinct from old.status or new.attempts is distinct from old.attempts then
      raise exception using errcode = '55000', message = 'whatsapp_inbox_epoch_retained';
    end if;
  end if;

  if new.status = 'processing' and new.processing_epoch <> v_active_epoch then
    if tg_op = 'INSERT' then
      raise exception using errcode = '55000', message = 'whatsapp_inbox_epoch_retained';
    end if;
    if old.status is distinct from 'processing' then
      raise exception using errcode = '55000', message = 'whatsapp_inbox_epoch_retained';
    end if;
  end if;

  -- Old workers know neither the epoch claim predicate nor this worker ID.
  -- During a rolling deploy they must fail before processing a new epoch row.
  if new.processing_epoch = 1 and new.status = 'processing'
    and coalesce(new.locked_by, '') not like 'vimob-api-evolution-webhook-epoch1-%'
  then
    raise exception using errcode = '55000', message = 'whatsapp_inbox_epoch_legacy_worker';
  end if;

  if tg_op = 'INSERT' then
    for v_route in
      select value
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(new.payload #> '{__vimob_ingress,routing_snapshot,messages}') = 'array'
            then new.payload #> '{__vimob_ingress,routing_snapshot,messages}'
          else '[]'::jsonb
        end
      )
    loop
      if coalesce((v_route->>'processing_epoch')::integer, 0) <> new.processing_epoch then
        raise exception using errcode = '23514', message = 'whatsapp_inbox_snapshot_epoch_mismatch';
      end if;
    end loop;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_webhook_inbox_epoch() OWNER TO postgres;

--
-- Name: guard_whatsapp_webhook_legacy_routing_freeze(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_webhook_legacy_routing_freeze() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old_frozen boolean := false;
  v_new_snapshot_version text;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    v_old_frozen := private.is_frozen_legacy_whatsapp_ingress(
      old.id,
      old.organization_id,
      old.session_id,
      old.event_key,
      old.processing_lane
    );
  end if;

  if tg_op = 'DELETE' then
    if v_old_frozen then
      raise exception using
        errcode = '55000',
        message = 'frozen_legacy_whatsapp_ingress_delete_forbidden',
        hint = 'Use a separately audited recovery procedure; do not delete preserved pre-v1 ingress.';
    end if;
    return old;
  end if;

  if v_old_frozen then
    if new.organization_id is distinct from old.organization_id
       or new.session_id is distinct from old.session_id
       or new.event_key is distinct from old.event_key
       or new.event_type is distinct from old.event_type
       or new.provider_instance_id is distinct from old.provider_instance_id
       or new.processing_lane is distinct from old.processing_lane
       or new.payload is distinct from old.payload
       or new.status is distinct from old.status then
      raise exception using
        errcode = '55000',
        message = 'frozen_legacy_whatsapp_ingress_mutation_forbidden',
        hint = 'The legacy row is intentionally preserved and excluded from claims until an audited recovery exists.';
    end if;
    return new;
  end if;

  v_new_snapshot_version := coalesce(
    new.payload #>> '{__vimob_ingress,routing_snapshot,version}',
    ''
  );

  if new.status in ('pending', 'retry', 'processing')
     and v_new_snapshot_version <> '1' then
    raise exception using
      errcode = '23514',
      message = 'active_whatsapp_ingress_requires_routing_snapshot_v1';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_webhook_legacy_routing_freeze() OWNER TO postgres;

--
-- Name: FUNCTION guard_whatsapp_webhook_legacy_routing_freeze(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.guard_whatsapp_webhook_legacy_routing_freeze() IS 'vimob.whatsapp_legacy_routing_freeze.v1: freezes ledgered pre-v1 rows and rejects every new active inbox row without an immutable routing snapshot v1.';


--
-- Name: guard_whatsapp_webhook_routing_snapshot_epoch(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_whatsapp_webhook_routing_snapshot_epoch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_active_epoch integer;
begin
  perform 1
  from public.whatsapp_sessions as session
  where session.id = new.session_id
    and session.organization_id = new.organization_id
  for key share;
  if not found then
    raise exception using errcode = '23503', message = 'whatsapp_snapshot_epoch_session_mismatch';
  end if;

  select coalesce((
    select cutover.active_epoch
    from private.whatsapp_webhook_session_cutovers as cutover
    where cutover.session_id = new.session_id
  ), 0) into v_active_epoch;

  if new.processing_epoch is distinct from v_active_epoch then
    raise exception using errcode = '55000', message = 'whatsapp_snapshot_epoch_inactive';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.guard_whatsapp_webhook_routing_snapshot_epoch() OWNER TO postgres;

--
-- Name: has_active_lead_read_session(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.has_active_lead_read_session() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor_user_id uuid;
  actor_session_id uuid;
  raw_session_id text;
  token_claims jsonb;
begin
  actor_user_id := auth.uid();
  token_claims := auth.jwt();
  raw_session_id := nullif(pg_catalog.btrim(token_claims ->> 'session_id'), '');
  if actor_user_id is null or raw_session_id is null
     or raw_session_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return false;
  end if;
  -- The Go/browser boundary isolates password-recovery sessions from CRM
  -- reads. A live session alone must not reopen that route through the API.
  if coalesce(pg_catalog.jsonb_typeof(token_claims -> 'amr'), 'array') <> 'array'
     or exists (
       select 1 from pg_catalog.jsonb_array_elements(
         coalesce(token_claims -> 'amr', '[]'::jsonb)
       ) as method(value)
       where pg_catalog.jsonb_typeof(method.value) <> 'object'
          or pg_catalog.jsonb_typeof(method.value -> 'method') is distinct from 'string'
          or pg_catalog.lower(pg_catalog.btrim(method.value ->> 'method')) = 'recovery'
     )
  then
    return false;
  end if;
  actor_session_id := raw_session_id::uuid;
  return exists (
    select 1 from auth.sessions as session
    where session.id = actor_session_id and session.user_id = actor_user_id
  );
exception when others then
  return false;
end;
$_$;


ALTER FUNCTION private.has_active_lead_read_session() OWNER TO postgres;

--
-- Name: has_effective_whatsapp_view(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.has_effective_whatsapp_view(target_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select target_organization_id is not null
    and auth.uid() is not null
    and (
      private.is_super_admin()
      or exists (
        select 1
        from public.organization_members as membership
        where membership.organization_id = target_organization_id
          and membership.user_id = auth.uid()
          and coalesce(membership.is_active, false) = true
          and (
            lower(btrim(membership.role)) in ('owner', 'admin')
            or not exists (
              select 1
              from public.user_permission_overrides as permission_override
              where permission_override.organization_id = target_organization_id
                and permission_override.user_id = auth.uid()
                and lower(btrim(permission_override.permission_key)) = 'whatsapp_view'
                and permission_override.allowed = false
            )
            or not exists (
              select 1
              from public.user_permission_overrides as permission_override
              where permission_override.organization_id = target_organization_id
                and permission_override.user_id = auth.uid()
                and lower(btrim(permission_override.permission_key)) = 'whatsapp_operate'
                and permission_override.allowed = false
            )
            or not exists (
              select 1
              from public.user_permission_overrides as permission_override
              where permission_override.organization_id = target_organization_id
                and permission_override.user_id = auth.uid()
                and lower(btrim(permission_override.permission_key)) = 'whatsapp_manage'
                and permission_override.allowed = false
            )
          )
      )
    )
    and coalesce(
      (
        select bool_or(coalesce(module_access.is_enabled, false))
        from public.organization_modules as module_access
        where module_access.organization_id = target_organization_id
          and lower(btrim(module_access.module_name)) = 'whatsapp'
      ),
      true
    );
$$;


ALTER FUNCTION private.has_effective_whatsapp_view(target_organization_id uuid) OWNER TO postgres;

--
-- Name: has_org_role(uuid, text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.has_org_role(target_organization_id uuid, allowed_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_super_admin()
    or (
      private.is_org_member(target_organization_id)
      and exists (
        select 1
        from public.organization_members om
        where om.user_id = (select auth.uid())
          and om.organization_id = target_organization_id
          and coalesce(om.is_active, false) = true
          and om.role = any(allowed_roles)
      )
    );
$$;


ALTER FUNCTION private.has_org_role(target_organization_id uuid, allowed_roles text[]) OWNER TO postgres;

--
-- Name: has_permission(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.has_permission(target_organization_id uuid, permission_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select private.is_super_admin()
    or (
      private.is_org_member(target_organization_id)
      and (
        exists (
          select 1
          from public.organization_members om
          where om.user_id = (select auth.uid())
            and om.organization_id = target_organization_id
            and coalesce(om.is_active, false) = true
            and om.role in ('owner', 'admin')
        )
        or exists (
          select 1
          from public.user_organization_roles uor
          join public.organization_roles role
            on role.id = uor.role_id
           and role.organization_id = uor.organization_id
          join public.organization_role_permissions orp
            on orp.role_id = uor.role_id
           and orp.organization_id = uor.organization_id
          join public.available_permissions permission
            on permission.id = orp.permission_id
          where uor.user_id = (select auth.uid())
            and uor.organization_id = target_organization_id
            and coalesce(uor.is_active, false) = true
            and coalesce(role.is_active, false) = true
            and permission.key = $2
        )
      )
    );
$_$;


ALTER FUNCTION private.has_permission(target_organization_id uuid, permission_key text) OWNER TO postgres;

--
-- Name: historical_import_effect_counts(uuid, uuid[], uuid[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.historical_import_effect_counts(p_organization_id uuid, p_lead_ids uuid[], p_entity_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lead_ids uuid[] := coalesce(p_lead_ids, '{}'::uuid[]);
  v_lead_id_texts text[];
  v_entity_ids uuid[] := coalesce(p_entity_ids, '{}'::uuid[]);
  v_entity_id_texts text[];
begin
  select coalesce(
    pg_catalog.array_agg(lead_id::text),
    '{}'::text[]
  )
  into v_lead_id_texts
  from pg_catalog.unnest(v_lead_ids) as item(lead_id);

  select coalesce(
    pg_catalog.array_agg(distinct entity_id::text),
    '{}'::text[]
  )
  into v_entity_id_texts
  from pg_catalog.unnest(v_lead_ids || v_entity_ids) as item(entity_id);

  return pg_catalog.jsonb_build_object(
    'notifications', (
      select pg_catalog.count(*)
      from public.notifications as notification
      where notification.organization_id = p_organization_id
        and notification.lead_id = any(v_lead_ids)
    ),
    'notification_deliveries', (
      select pg_catalog.count(*)
      from private.notification_deliveries as delivery
      join public.notifications as notification
        on notification.id = delivery.notification_id
      where delivery.organization_id = p_organization_id
        and notification.organization_id = p_organization_id
        and notification.lead_id = any(v_lead_ids)
    ),
    'automation_event_outbox', (
      select pg_catalog.count(*)
      from public.automation_event_outbox as event_outbox
      where event_outbox.organization_id = p_organization_id
        and event_outbox.lead_id = any(v_lead_ids)
    ),
    'automation_executions', (
      select pg_catalog.count(*)
      from public.automation_executions as execution
      where execution.organization_id = p_organization_id
        and execution.lead_id = any(v_lead_ids)
    ),
    'automation_effect_dispatches', (
      select pg_catalog.count(*)
      from public.automation_effect_dispatches as dispatch
      join public.automation_executions as execution
        on execution.id = dispatch.execution_id
      where dispatch.organization_id = p_organization_id
        and execution.organization_id = p_organization_id
        and execution.lead_id = any(v_lead_ids)
    ),
    'automation_execution_steps', (
      select pg_catalog.count(*)
      from public.automation_execution_steps as step
      join public.automation_executions as execution
        on execution.id = step.execution_id
      where step.organization_id = p_organization_id
        and execution.organization_id = p_organization_id
        and execution.lead_id = any(v_lead_ids)
    ),
    'gamification_outbox', (
      select pg_catalog.count(*)
      from public.gamification_outbox as gamification
      where gamification.organization_id = p_organization_id
        and (
          gamification.reference_id = any(v_lead_id_texts)
          or gamification.metadata->>'lead_id' = any(v_lead_id_texts)
        )
    ),
    'webhook_delivery_outbox', (
      select pg_catalog.count(*)
      from private.webhook_delivery_outbox as webhook
      where webhook.organization_id = p_organization_id
        and webhook.lead_id = any(v_lead_ids)
    ),
    'lead_funnel_events', (
      select pg_catalog.count(*)
      from public.lead_funnel_events as funnel_event
      where funnel_event.organization_id = p_organization_id
        and funnel_event.lead_id = any(v_lead_ids)
    ),
    'meta_crm_event_outbox', (
      select pg_catalog.count(*)
      from public.meta_crm_event_outbox as meta_outbox
      where meta_outbox.organization_id = p_organization_id
        and meta_outbox.lead_id = any(v_lead_ids)
    ),
    'operational_requests', (
      select pg_catalog.count(*)
      from public.operational_requests as request
      where request.organization_id = p_organization_id
        and request.lead_id = any(v_lead_ids)
    ),
    'operational_timelines', (
      select pg_catalog.count(*)
      from public.operational_timelines as timeline
      where timeline.organization_id = p_organization_id
        and timeline.lead_id = any(v_lead_ids)
    ),
    'lead_tasks', (
      select pg_catalog.count(*)
      from public.lead_tasks as task
      where task.organization_id = p_organization_id
        and task.lead_id = any(v_lead_ids)
    ),
    'schedule_events', (
      select pg_catalog.count(*)
      from public.schedule_events as schedule
      where schedule.organization_id = p_organization_id
        and schedule.lead_id = any(v_lead_ids)
    ),
    'cadence_enrollments', (
      select pg_catalog.count(*)
      from public.cadence_enrollments as enrollment
      where enrollment.organization_id = p_organization_id
        and enrollment.lead_id = any(v_lead_ids)
    ),
    'lead_action_facts', (
      select pg_catalog.count(*)
      from public.lead_action_facts as action_fact
      where action_fact.organization_id = p_organization_id
        and action_fact.lead_id = any(v_lead_ids)
    ),
    'lead_assignment_cycles', (
      select pg_catalog.count(*)
      from public.lead_assignment_cycles as assignment_cycle
      where assignment_cycle.organization_id = p_organization_id
        and assignment_cycle.lead_id = any(v_lead_ids)
    ),
    'lead_stage_cycles', (
      select pg_catalog.count(*)
      from public.lead_stage_cycles as stage_cycle
      where stage_cycle.organization_id = p_organization_id
        and stage_cycle.lead_id = any(v_lead_ids)
    ),
    'lead_attention_instances', (
      select pg_catalog.count(*)
      from public.lead_attention_instances as attention
      where attention.organization_id = p_organization_id
        and attention.lead_id = any(v_lead_ids)
    ),
    'lead_timeline_events', (
      select pg_catalog.count(*)
      from public.lead_timeline_events as timeline_event
      where timeline_event.organization_id = p_organization_id
        and timeline_event.lead_id = any(v_lead_ids)
    ),
    'assignments_log', (
      select pg_catalog.count(*)
      from public.assignments_log as assignment
      where assignment.organization_id = p_organization_id
        and assignment.lead_id = any(v_lead_ids)
    ),
    'lead_assignment_history', (
      select pg_catalog.count(*)
      from public.lead_assignment_history as assignment_history
      join public.leads as lead
        on lead.id = assignment_history.lead_id
      where lead.organization_id = p_organization_id
        and assignment_history.lead_id = any(v_lead_ids)
    ),
    'lead_stage_history', (
      select pg_catalog.count(*)
      from public.lead_stage_history as stage_history
      join public.leads as lead
        on lead.id = stage_history.lead_id
      where lead.organization_id = p_organization_id
        and stage_history.lead_id = any(v_lead_ids)
    ),
    'commissions', (
      select pg_catalog.count(*)
      from public.commissions as commission
      where commission.organization_id = p_organization_id
        and commission.lead_id = any(v_lead_ids)
    ),
    'financial_entries', (
      select pg_catalog.count(*)
      from public.financial_entries as financial_entry
      where financial_entry.organization_id = p_organization_id
        and financial_entry.lead_id = any(v_lead_ids)
    ),
    'round_robin_logs', (
      select pg_catalog.count(*)
      from public.round_robin_logs as round_robin_log
      where round_robin_log.organization_id = p_organization_id
        and round_robin_log.lead_id = any(v_lead_ids)
    ),
    'lead_redistribution_jobs', (
      select pg_catalog.count(*)
      from public.lead_redistribution_jobs as redistribution_job
      where redistribution_job.organization_id = p_organization_id
        and redistribution_job.lead_id = any(v_lead_ids)
    ),
    'lead_distribution_events', (
      select pg_catalog.count(*)
      from private.lead_distribution_events as distribution_event
      where distribution_event.organization_id = p_organization_id
        and distribution_event.lead_id = any(v_lead_ids)
    ),
    'team_distribution_events', (
      select pg_catalog.count(*)
      from private.team_distribution_events as distribution_event
      where distribution_event.organization_id = p_organization_id
        and distribution_event.lead_id = any(v_lead_ids)
    ),
    'whatsapp_messages', (
      select pg_catalog.count(*)
      from public.whatsapp_messages as message
      where message.organization_id = p_organization_id
        and message.lead_id = any(v_lead_ids)
    ),
    'whatsapp_outbox', (
      select pg_catalog.count(*)
      from public.whatsapp_outbox as outbox
      join public.whatsapp_messages as message
        on message.id = outbox.message_id
      where outbox.organization_id = p_organization_id
        and message.organization_id = p_organization_id
        and message.lead_id = any(v_lead_ids)
    ),
    'outbox_messages', (
      select pg_catalog.count(*)
      from public.outbox_messages as outbox_message
      where outbox_message.organization_id = p_organization_id
        and outbox_message.lead_id = any(v_lead_ids)
    ),
    'audit_logs', (
      select pg_catalog.count(*)
      from public.audit_logs as audit_log
      where audit_log.organization_id = p_organization_id
        and audit_log.entity_id = any(v_entity_id_texts)
    )
  );
end;
$$;


ALTER FUNCTION private.historical_import_effect_counts(p_organization_id uuid, p_lead_ids uuid[], p_entity_ids uuid[]) OWNER TO postgres;

--
-- Name: historical_import_effect_delta(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.historical_import_effect_delta(p_before jsonb, p_after jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select coalesce(
    pg_catalog.jsonb_object_agg(
      key,
      coalesce((p_after->>key)::bigint, 0)
        - coalesce((p_before->>key)::bigint, 0)
      order by key
    ),
    '{}'::jsonb
  )
  from (
    select key
    from pg_catalog.jsonb_object_keys(p_before) as before_key(key)
    union
    select key
    from pg_catalog.jsonb_object_keys(p_after) as after_key(key)
  ) as keys
$$;


ALTER FUNCTION private.historical_import_effect_delta(p_before jsonb, p_after jsonb) OWNER TO postgres;

--
-- Name: historical_import_effects_suppressed(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.historical_import_effects_suppressed() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_token text := pg_catalog.current_setting(
    'vimob.historical_import_token',
    true
  );
begin
  if coalesce(v_token, '') = '' then
    return false;
  end if;

  return exists (
    select 1
    from private.historical_lead_import_contexts as context
    where context.transaction_id = pg_catalog.pg_current_xact_id()::text
      and context.token_sha256 = pg_catalog.encode(
        extensions.digest(v_token, 'sha256'),
        'hex'
      )
  );
end;
$$;


ALTER FUNCTION private.historical_import_effects_suppressed() OWNER TO postgres;

--
-- Name: FUNCTION historical_import_effects_suppressed(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.historical_import_effects_suppressed() IS 'True only for an unforgeable private capability in the current transaction; used by effect-producing trigger WHEN clauses.';


--
-- Name: hydrate_lead_destination_from_intake_queue(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.hydrate_lead_destination_from_intake_queue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_destination_fallback boolean := false;
  v_candidate_pipeline_id uuid;
  v_candidate_stage_id uuid;
  v_pipeline_id uuid;
  v_stage_id uuid;
begin
  if new.origin_round_robin_id is null
     or new.pipeline_id is not null
     or new.stage_id is not null then
    return new;
  end if;

  select
    case
      when queue.deleted_at is not null then queue.tombstone_pipeline_id
      else coalesce(queue.target_pipeline_id, queue.pipeline_id)
    end,
    case
      when queue.deleted_at is not null then queue.tombstone_stage_id
      else queue.target_stage_id
    end
  into v_candidate_pipeline_id, v_candidate_stage_id
  from public.round_robins as queue
  where queue.organization_id = new.organization_id
    and queue.id = new.origin_round_robin_id;

  select pipeline.id
  into v_pipeline_id
  from public.pipelines as pipeline
  where pipeline.organization_id = new.organization_id
    and pipeline.id = v_candidate_pipeline_id
    and coalesce(pipeline.is_active, true) = true;

  if v_pipeline_id is not null then
    select stage.id
    into v_stage_id
    from public.stages as stage
    where stage.organization_id = new.organization_id
      and stage.pipeline_id = v_pipeline_id
      and stage.id = v_candidate_stage_id
      and coalesce(stage.is_active, true) = true
    ;

    if v_stage_id is null then
      select stage.id
      into v_stage_id
      from public.stages as stage
      where stage.organization_id = new.organization_id
        and stage.pipeline_id = v_pipeline_id
        and coalesce(stage.is_active, true) = true
      order by stage.position asc, stage.created_at asc, stage.id asc
      limit 1;
    end if;
  end if;

  if v_pipeline_id is null or v_stage_id is null then
    v_destination_fallback := true;
    select pipeline.id, first_stage.id
    into v_pipeline_id, v_stage_id
    from public.pipelines as pipeline
    join lateral (
      select stage.id
      from public.stages as stage
      where stage.organization_id = pipeline.organization_id
        and stage.pipeline_id = pipeline.id
        and coalesce(stage.is_active, true) = true
      order by stage.position asc, stage.created_at asc, stage.id asc
      limit 1
    ) as first_stage on true
    where pipeline.organization_id = new.organization_id
      and coalesce(pipeline.is_active, true) = true
    order by
      coalesce(pipeline.is_default, false) desc,
      coalesce(pipeline.position, 0) asc,
      pipeline.created_at asc,
      pipeline.id asc
    limit 1;

    if v_pipeline_id is null or v_stage_id is null then
      raise exception using
        errcode = '23514',
        message = 'round_robin_tombstone_destination_unavailable';
    end if;
  end if;

  new.pipeline_id := v_pipeline_id;
  new.stage_id := v_stage_id;
  if v_destination_fallback then
    new.metadata := coalesce(new.metadata, '{}'::jsonb)
      || pg_catalog.jsonb_build_object(
        'round_robin_tombstone_destination_fallback',
        pg_catalog.jsonb_build_object(
          'round_robin_id', new.origin_round_robin_id,
          'snapshot_pipeline_id', v_candidate_pipeline_id,
          'snapshot_stage_id', v_candidate_stage_id,
          'pipeline_id', v_pipeline_id,
          'stage_id', v_stage_id,
          'recorded_at', pg_catalog.clock_timestamp()
        )
      );
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.hydrate_lead_destination_from_intake_queue() OWNER TO postgres;

