-- Name: imoview_delete_api_key(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.imoview_delete_api_key() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'vault', 'private'
    AS $$
begin
  if old.api_key_secret_ref is not null then
    delete from vault.secrets where id = old.api_key_secret_ref;
  end if;
  return old;
end;
$$;


