--
-- Name: imoview_store_api_key(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.imoview_store_api_key() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'vault', 'private'
    AS $$
declare
  secret_value text := nullif(btrim(new.api_key), '');
  secret_id uuid := new.api_key_secret_ref;
  secret_name text := 'vimob_imoview_api_key_' || new.organization_id::text;
begin
  perform pg_advisory_xact_lock(hashtextextended('imoview_api_key:' || new.organization_id::text, 0));

  if secret_id is null then
    select i.api_key_secret_ref into secret_id
    from public.imoview_integrations i
    where i.organization_id = new.organization_id
    limit 1;
  end if;

  if secret_id is null then
    select s.id into secret_id
    from vault.secrets s
    where s.name = secret_name;
  end if;

  if secret_value is not null then
    if secret_id is null then
      secret_id := vault.create_secret(
        secret_value,
        secret_name,
        'Imoview API key for organization ' || new.organization_id::text
      );
    else
      perform vault.update_secret(
        secret_id,
        secret_value,
        secret_name,
        'Imoview API key for organization ' || new.organization_id::text
      );
    end if;
  end if;

  if secret_id is null then
    raise exception 'Imoview API key is required';
  end if;

  new.api_key_secret_ref := secret_id;
  new.api_key := null;
  return new;
end;
$$;


ALTER FUNCTION private.imoview_store_api_key() OWNER TO postgres;

--
-- Name: import_historical_lead_batch(uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.import_historical_lead_batch(p_organization_id uuid, p_actor_user_id uuid, p_batch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_request_role text := coalesce(
    nullif(pg_catalog.current_setting('request.jwt.claim.role', true), ''),
    nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb
      ->>'role',
    ''
  );
  v_entity_type text;
  v_batch_index integer;
  v_declared_count integer;
  v_actual_count integer;
  v_records jsonb;
  v_declared_records_sha256 text;
  v_batch_sha256 text;
  v_batch_lead_ids uuid[] := '{}'::uuid[];
  v_batch_target_ids uuid[] := '{}'::uuid[];
  v_proof_lead_id uuid;
  v_proof_target_id uuid;
  v_effect_before jsonb;
  v_effect_after jsonb;
  v_effect_delta jsonb;
  v_effect_sinks jsonb;
  v_effect_all_zero boolean := false;
  v_suppression_active boolean := false;
  v_token text;
  v_transaction_id text;
  v_record jsonb;
  v_payload jsonb;
  v_provenance jsonb;
  v_action text;
  v_external_key text;
  v_payload_sha256 text;
  v_computed_sha256 text;
  v_source_system text;
  v_source_id text;
  v_source_lead_id text;
  v_target_id uuid;
  v_expected_target_id uuid;
  v_lead_id uuid;
  v_entry_id uuid;
  v_pipeline_id uuid;
  v_stage_id uuid;
  v_assigned_user_id uuid;
  v_team_id uuid;
  v_name text;
  v_phone text;
  v_email text;
  v_message text;
  v_created_at timestamptz;
  v_updated_at timestamptz;
  v_stage_entered_at timestamptz;
  v_assigned_at timestamptz;
  v_won_at timestamptz;
  v_lost_at timestamptz;
  v_deal_status text;
  v_event_at timestamptz;
  v_event_type text;
  v_direction text;
  v_metadata jsonb;
  v_tags jsonb;
  v_tag_value jsonb;
  v_tag_name text;
  v_tag_id uuid;
  v_existing private.historical_lead_import_ledger%rowtype;
  v_results jsonb := '[]'::jsonb;
  v_created_count integer := 0;
  v_noop_count integer := 0;
  v_scoped_phone_index_ready boolean := false;
begin
  if v_request_role <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'historical_import_service_role_required';
  end if;

  if not private.user_can_import_historical_leads(
    p_organization_id,
    p_actor_user_id
  ) then
    raise exception using
      errcode = '42501',
      message = 'historical_import_lead_import_permission_required';
  end if;

  if p_batch is null
     or pg_catalog.jsonb_typeof(p_batch) <> 'object'
     or p_batch->>'schema_version' <> '1'
     or pg_catalog.jsonb_typeof(p_batch->'batch') <> 'object'
     or pg_catalog.jsonb_typeof(p_batch->'records') <> 'array' then
    raise exception using
      errcode = '22023',
      message = 'historical_import_batch_shape_invalid';
  end if;

  if pg_catalog.octet_length(pg_catalog.convert_to(
       private.canonical_jsonb_text(p_batch),
       'UTF8'
     ))
     > 5 * 1024 * 1024 then
    raise exception using
      errcode = '54000',
      message = 'historical_import_batch_payload_too_large';
  end if;

  v_entity_type := pg_catalog.lower(
    pg_catalog.btrim(coalesce(p_batch #>> '{batch,entity_type}', ''))
  );
  if v_entity_type not in ('lead', 'event', 'chat') then
    raise exception using
      errcode = '22023',
      message = 'historical_import_batch_entity_invalid';
  end if;

  begin
    v_batch_index := (p_batch #>> '{batch,index}')::integer;
    v_declared_count := (p_batch #>> '{batch,record_count}')::integer;
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      raise exception using
        errcode = '22023',
        message = 'historical_import_batch_counters_invalid';
  end;

  v_records := p_batch->'records';
  v_actual_count := pg_catalog.jsonb_array_length(v_records);
  if v_batch_index is null
     or v_batch_index < 0
     or v_actual_count < 1
     or v_actual_count > 250
     or v_declared_count is distinct from v_actual_count then
    raise exception using
      errcode = '22023',
      message = 'historical_import_batch_count_invalid';
  end if;

  v_declared_records_sha256 := pg_catalog.lower(pg_catalog.btrim(coalesce(
    p_batch #>> '{batch,records_sha256}',
    ''
  )));
  if v_declared_records_sha256 !~ '^[0-9a-f]{64}$'
     or v_declared_records_sha256 is distinct from
       private.canonical_jsonb_sha256(v_records) then
    raise exception using
      errcode = '22023',
      message = 'historical_import_records_hash_mismatch';
  end if;

  for v_record in
    select record.value
    from pg_catalog.jsonb_array_elements(v_records) as record(value)
  loop
    begin
      v_proof_target_id := (v_record->>'target_id')::uuid;
      v_proof_lead_id := case
        when v_entity_type = 'lead' then (v_record->>'target_id')::uuid
        else (v_record #>> '{payload,lead_id}')::uuid
      end;
    exception
      when invalid_text_representation then
        raise exception using
          errcode = '22023',
          message = 'historical_import_proof_lead_id_invalid';
    end;

    if v_proof_lead_id is null or v_proof_target_id is null then
      raise exception using
        errcode = '22023',
        message = 'historical_import_proof_scope_id_required';
    end if;

    if not v_proof_lead_id = any(v_batch_lead_ids) then
      v_batch_lead_ids := pg_catalog.array_append(
        v_batch_lead_ids,
        v_proof_lead_id
      );
    end if;

    if not v_proof_target_id = any(v_batch_target_ids) then
      v_batch_target_ids := pg_catalog.array_append(
        v_batch_target_ids,
        v_proof_target_id
      );
    end if;
  end loop;

  if v_entity_type = 'lead' then
    if pg_catalog.to_regclass('public.leads_org_phone_unique') is not null then
      raise exception using
        errcode = '55000',
        message = 'historical_import_legacy_global_phone_identity_active',
        hint = 'Complete and verify the reviewed queue-scoped phone identity cutover before importing external cards.';
    end if;

    select exists (
      select 1
      from pg_catalog.pg_index as index_state
      where index_state.indexrelid =
        pg_catalog.to_regclass('public.leads_org_scope_phone_unique')
        and index_state.indrelid = 'public.leads'::regclass
        and index_state.indisunique
        and index_state.indisready
        and index_state.indisvalid
    )
    into v_scoped_phone_index_ready;

    if not v_scoped_phone_index_ready then
      raise exception using
        errcode = '55000',
        message = 'historical_import_scoped_phone_identity_not_ready';
    end if;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'historical_lead_import:' || p_organization_id::text,
      0
    )
  );

  v_batch_sha256 := private.canonical_jsonb_sha256(p_batch);
  v_effect_before := private.historical_import_effect_counts(
    p_organization_id,
    v_batch_lead_ids,
    v_batch_target_ids
  );
  v_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  v_transaction_id := pg_catalog.pg_current_xact_id()::text;

  insert into private.historical_lead_import_contexts (
    transaction_id,
    token_sha256,
    organization_id,
    actor_user_id
  ) values (
    v_transaction_id,
    pg_catalog.encode(extensions.digest(v_token, 'sha256'), 'hex'),
    p_organization_id,
    p_actor_user_id
  );

  perform pg_catalog.set_config(
    'vimob.historical_import_token',
    v_token,
    true
  );

  v_suppression_active := private.historical_import_effects_suppressed();
  if not v_suppression_active then
    raise exception using
      errcode = '55000',
      message = 'historical_import_transaction_capability_not_active';
  end if;

  begin
    for v_record in
      select record.value
      from pg_catalog.jsonb_array_elements(v_records) as record(value)
    loop
      if pg_catalog.jsonb_typeof(v_record) <> 'object'
         or pg_catalog.jsonb_typeof(v_record->'payload') <> 'object'
         or coalesce(v_record #>> '{validation,ok}', 'false') <> 'true' then
        raise exception using
          errcode = '22023',
          message = 'historical_import_record_shape_invalid';
      end if;

      v_payload := v_record->'payload';
      v_provenance := coalesce(v_record->'provenance', '{}'::jsonb);
      if pg_catalog.jsonb_typeof(v_provenance) <> 'object' then
        raise exception using
          errcode = '22023',
          message = 'historical_import_record_provenance_invalid';
      end if;

      if pg_catalog.octet_length(
        pg_catalog.convert_to(
          private.canonical_jsonb_text(v_payload),
          'UTF8'
        )
      ) > 512 * 1024 then
        raise exception using
          errcode = '54000',
          message = 'historical_import_record_payload_too_large';
      end if;

      v_action := pg_catalog.upper(
        pg_catalog.btrim(coalesce(v_record->>'action', ''))
      );
      if v_action not in ('CREATE', 'NOOP') then
        raise exception using
          errcode = '22023',
          message = 'historical_import_record_action_invalid';
      end if;

      if pg_catalog.lower(pg_catalog.btrim(coalesce(
        v_record->>'entity_type',
        v_entity_type
      ))) <> v_entity_type then
        raise exception using
          errcode = '22023',
          message = 'historical_import_record_entity_mismatch';
      end if;

      if nullif(v_record->>'organization_id', '')::uuid
         is distinct from p_organization_id then
        raise exception using
          errcode = '22023',
          message = 'historical_import_record_tenant_mismatch';
      end if;

      v_external_key := pg_catalog.btrim(coalesce(
        v_record->>'external_key',
        ''
      ));
      if pg_catalog.length(v_external_key) not between 1 and 700
         or v_external_key ~ '[[:cntrl:]]' then
        raise exception using
          errcode = '22023',
          message = 'historical_import_external_key_invalid';
      end if;

      v_payload_sha256 := pg_catalog.lower(pg_catalog.btrim(coalesce(
        v_record->>'payload_sha256',
        ''
      )));
      v_computed_sha256 := private.canonical_jsonb_sha256(v_payload);
      if v_payload_sha256 !~ '^[0-9a-f]{64}$'
         or v_payload_sha256 is distinct from v_computed_sha256 then
        raise exception using
          errcode = '22023',
          message = 'historical_import_payload_hash_mismatch';
      end if;

      v_source_system := pg_catalog.lower(pg_catalog.btrim(coalesce(
        v_payload->>'source_system',
        v_provenance->>'source_system',
        ''
      )));
      if v_source_system !~ '^[a-z0-9][a-z0-9._-]{0,63}$' then
        raise exception using
          errcode = '22023',
          message = 'historical_import_source_system_invalid';
      end if;

      v_source_lead_id := pg_catalog.btrim(coalesce(
        v_payload->>'source_lead_id',
        ''
      ));
      if pg_catalog.length(v_source_lead_id) not between 1 and 256
         or v_source_lead_id ~ '[[:cntrl:]]' then
        raise exception using
          errcode = '22023',
          message = 'historical_import_source_lead_id_invalid';
      end if;

      v_source_id := case
        when v_entity_type = 'lead' then v_source_lead_id
        else pg_catalog.btrim(coalesce(
          v_payload->>'source_event_id',
          v_external_key
        ))
      end;
      if pg_catalog.length(v_source_id) not between 1 and 512
         or v_source_id ~ '[[:cntrl:]]' then
        raise exception using
          errcode = '22023',
          message = 'historical_import_source_id_invalid';
      end if;

      if coalesce(v_payload->>'historical_import', 'false') <> 'true'
         or v_payload->>'notification_policy' <> 'suppress_all' then
        raise exception using
          errcode = '22023',
          message = 'historical_import_suppression_contract_required';
      end if;

      begin
        v_target_id := (v_record->>'target_id')::uuid;
      exception
        when invalid_text_representation then
          raise exception using
            errcode = '22023',
            message = 'historical_import_target_id_invalid';
      end;

      v_expected_target_id := extensions.uuid_generate_v5(
        extensions.uuid_ns_url(),
        p_organization_id::text || ':' || v_external_key
      );
      if v_target_id is distinct from v_expected_target_id then
        raise exception using
          errcode = '22023',
          message = 'historical_import_target_id_not_deterministic';
      end if;

      select ledger.*
      into v_existing
      from private.historical_lead_import_ledger as ledger
      where ledger.organization_id = p_organization_id
        and ledger.source_system = v_source_system
        and ledger.entity_type = v_entity_type
        and ledger.source_id = v_source_id
      for update;

      if found then
        if v_existing.external_key is distinct from v_external_key
           or v_existing.target_id is distinct from v_target_id
           or v_existing.payload_sha256 is distinct from v_payload_sha256
           or v_existing.payload is distinct from v_payload then
          raise exception using
            errcode = '23514',
            message = 'historical_import_ledger_drift';
        end if;

        if (
          v_entity_type = 'lead'
          and not exists (
            select 1
            from public.leads as lead
            where lead.organization_id = p_organization_id
              and lead.id = v_target_id
              and lead.external_source = v_source_system
              and lead.external_source_id = v_source_lead_id
          )
        ) or (
          v_entity_type = 'event'
          and not exists (
            select 1
            from public.activities as activity
            where activity.organization_id = p_organization_id
              and activity.id = v_target_id
          )
        ) or (
          v_entity_type = 'chat'
          and not exists (
            select 1
            from public.activities as activity
            where activity.organization_id = p_organization_id
              and activity.id = v_target_id
          )
        ) then
          raise exception using
            errcode = '23514',
            message = 'historical_import_ledger_target_missing';
        end if;

        v_noop_count := v_noop_count + 1;
        v_results := v_results || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'external_key', v_external_key,
            'target_id', v_target_id,
            'action', 'NOOP'
          )
        );
        continue;
      end if;

      if v_action = 'NOOP' then
        raise exception using
          errcode = '23514',
          message = 'historical_import_noop_without_ledger';
      end if;

      if exists (
        select 1
        from private.historical_lead_import_ledger as ledger
        where ledger.organization_id = p_organization_id
          and ledger.external_key = v_external_key
      ) then
        raise exception using
          errcode = '23505',
          message = 'historical_import_external_key_collision';
      end if;

      if (
        v_entity_type = 'lead'
        and exists (
          select 1 from public.leads as lead
          where lead.id = v_target_id
        )
      ) or (
        v_entity_type = 'event'
        and exists (
          select 1 from public.activities as activity
          where activity.id = v_target_id
        )
      ) or (
        v_entity_type = 'chat'
        and exists (
          select 1 from public.activities as activity
          where activity.id = v_target_id
        )
      ) then
        raise exception using
          errcode = '23505',
          message = 'historical_import_target_exists_without_ledger';
      end if;

      if v_entity_type = 'lead' then
        v_name := pg_catalog.btrim(coalesce(v_payload->>'name', ''));
        if pg_catalog.length(v_name) not between 1 and 255 then
          raise exception using
            errcode = '22023',
            message = 'historical_import_lead_name_invalid';
        end if;

        begin
          v_pipeline_id := (v_payload->>'pipeline_id')::uuid;
          v_stage_id := (v_payload->>'stage_id')::uuid;
          v_assigned_user_id := (v_payload->>'assigned_user_id')::uuid;
          v_team_id := nullif(v_payload->>'team_id', '')::uuid;
          v_created_at := (v_payload->>'created_at')::timestamptz;
          v_updated_at := coalesce(
            nullif(v_payload->>'updated_at', '')::timestamptz,
            v_created_at
          );
          v_stage_entered_at :=
            nullif(v_payload->>'stage_entered_at', '')::timestamptz;
          v_assigned_at :=
            nullif(v_payload->>'assigned_at', '')::timestamptz;
        exception
          when invalid_text_representation or datetime_field_overflow then
            raise exception using
              errcode = '22023',
              message = 'historical_import_lead_reference_or_timestamp_invalid';
        end;

        if v_created_at is null
           or v_created_at > pg_catalog.clock_timestamp() + interval '1 day'
           or v_updated_at < v_created_at
           or v_updated_at > pg_catalog.clock_timestamp() + interval '1 day'
           or (
             v_stage_entered_at is not null
             and (
               v_stage_entered_at < v_created_at
               or v_stage_entered_at >
                 pg_catalog.clock_timestamp() + interval '1 day'
             )
           )
           or (
             v_assigned_at is not null
             and (
               v_assigned_at < v_created_at
               or v_assigned_at >
                 pg_catalog.clock_timestamp() + interval '1 day'
             )
           ) then
          raise exception using
            errcode = '22023',
            message = 'historical_import_lead_timestamp_invalid';
        end if;

        if not exists (
          select 1
          from public.pipelines as pipeline
          join public.stages as stage
            on stage.organization_id = pipeline.organization_id
           and stage.pipeline_id = pipeline.id
          where pipeline.organization_id = p_organization_id
            and pipeline.id = v_pipeline_id
            and stage.id = v_stage_id
            and coalesce(pipeline.is_active, true) = true
            and coalesce(stage.is_active, true) = true
        ) then
          raise exception using
            errcode = '23503',
            message = 'historical_import_pipeline_stage_tenant_mismatch';
        end if;

        if not exists (
          select 1
          from public.organization_members as member
          where member.organization_id = p_organization_id
            and member.user_id = v_assigned_user_id
            and coalesce(member.is_active, false) = true
        ) then
          raise exception using
            errcode = '23503',
            message = 'historical_import_owner_not_active_member';
        end if;

        if v_team_id is not null
           and not exists (
             select 1
             from public.teams as team
             where team.organization_id = p_organization_id
               and team.id = v_team_id
           ) then
          raise exception using
            errcode = '23503',
            message = 'historical_import_team_tenant_mismatch';
        end if;

        v_deal_status := pg_catalog.lower(pg_catalog.btrim(coalesce(
          v_payload->>'deal_status',
          ''
        )));
        if v_deal_status not in ('open', 'won', 'lost') then
          raise exception using
            errcode = '22023',
            message = 'historical_import_deal_status_invalid';
        end if;

        begin
          v_won_at := case
            when v_deal_status = 'won'
              then nullif(v_payload->>'won_at', '')::timestamptz
            else null
          end;
          v_lost_at := case
            when v_deal_status = 'lost'
              then nullif(v_payload->>'lost_at', '')::timestamptz
            else null
          end;
        exception
          when invalid_text_representation or datetime_field_overflow then
            raise exception using
              errcode = '22023',
              message = 'historical_import_deal_timestamp_invalid';
        end;

        if (
          v_won_at is not null
          and (
            v_won_at < v_created_at
            or v_won_at > pg_catalog.clock_timestamp() + interval '1 day'
          )
        ) or (
          v_lost_at is not null
          and (
            v_lost_at < v_created_at
            or v_lost_at > pg_catalog.clock_timestamp() + interval '1 day'
          )
        ) then
          raise exception using
            errcode = '22023',
            message = 'historical_import_deal_timestamp_out_of_range';
        end if;

        v_phone := nullif(pg_catalog.btrim(coalesce(v_payload->>'phone', '')), '');
        v_email := nullif(pg_catalog.btrim(coalesce(v_payload->>'email', '')), '');
        v_message := nullif(v_payload->>'message', '');
        if pg_catalog.length(coalesce(v_phone, '')) > 80
           or pg_catalog.length(coalesce(v_email, '')) > 320 then
          raise exception using
            errcode = '22023',
            message = 'historical_import_lead_contact_invalid';
        end if;

        v_metadata := coalesce(v_payload->'metadata', '{}'::jsonb);
        if pg_catalog.jsonb_typeof(v_metadata) <> 'object'
           or pg_catalog.octet_length(
             pg_catalog.convert_to(v_metadata::text, 'UTF8')
           ) > 256 * 1024 then
          raise exception using
            errcode = '22023',
              message = 'historical_import_lead_metadata_invalid';
        end if;

        if pg_catalog.jsonb_typeof(
             v_metadata->'timestamp_provenance'
           ) is distinct from 'object'
           or v_metadata->'timestamp_provenance' = '{}'::jsonb
           or exists (
             select 1
             from pg_catalog.unnest(array[
               'created_at',
               'updated_at',
               'stage_entered_at',
               'assigned_at',
               'won_at',
               'lost_at'
             ]) as required(field_name)
             where pg_catalog.jsonb_typeof(
               v_metadata->'timestamp_provenance'->required.field_name
             ) is distinct from 'object'
               or not (
                 v_metadata->'timestamp_provenance'->required.field_name
                   ?& array[
                     'value',
                     'source_field',
                     'confidence',
                     'is_inferred',
                     'rule',
                     'parse_method'
                   ]
               )
           ) then
          raise exception using
            errcode = '22023',
            message = 'historical_import_timestamp_provenance_required';
        end if;

        v_metadata := v_metadata || pg_catalog.jsonb_build_object(
          'historical_import', true,
          'notification_policy', 'suppress_all',
          'external_identity', pg_catalog.jsonb_build_object(
            'source_system', v_source_system,
            'source_id', v_source_lead_id,
            'external_key', v_external_key,
            'payload_sha256', v_payload_sha256
          ),
          'imported_by', p_actor_user_id,
          'imported_at', pg_catalog.clock_timestamp()
        );

        insert into public.leads (
          id,
          organization_id,
          pipeline_id,
          stage_id,
          assigned_user_id,
          team_id,
          name,
          email,
          phone,
          message,
          source,
          source_detail,
          deal_status,
          status,
          priority,
          lost_reason,
          won_at,
          lost_at,
          created_at,
          updated_at,
          stage_entered_at,
          board_order_at,
          assigned_at,
          last_entry_at,
          created_by,
          attention_eligible,
          attention_enrolled_at,
          metadata,
          external_source,
          external_source_id,
          intake_scope_key,
          origin_round_robin_id,
          operational_effects_suppressed,
          historical_imported_at
        ) values (
          v_target_id,
          p_organization_id,
          v_pipeline_id,
          v_stage_id,
          v_assigned_user_id,
          v_team_id,
          v_name,
          v_email,
          v_phone,
          v_message,
          coalesce(nullif(pg_catalog.btrim(v_payload->>'source'), ''), v_source_system),
          'historical_import',
          v_deal_status,
          coalesce(nullif(pg_catalog.btrim(v_payload->>'status'), ''), 'new'),
          coalesce(nullif(pg_catalog.btrim(v_payload->>'priority'), ''), 'normal'),
          nullif(v_payload->>'lost_reason', ''),
          v_won_at,
          v_lost_at,
          v_created_at,
          v_updated_at,
          v_stage_entered_at,
          coalesce(
            nullif(v_payload->>'board_order_at', '')::timestamptz,
            v_updated_at,
            v_created_at
          ),
          v_assigned_at,
          coalesce(
            nullif(v_payload->>'last_entry_at', '')::timestamptz,
            v_updated_at,
            v_created_at
          ),
          p_actor_user_id,
          false,
          null,
          v_metadata,
          v_source_system,
          v_source_lead_id,
          private.lead_intake_scope_for_external(
            p_organization_id,
            v_source_system,
            v_source_lead_id
          ),
          null,
          true,
          pg_catalog.clock_timestamp()
        );

        v_entry_id := extensions.uuid_generate_v5(
          extensions.uuid_ns_url(),
          p_organization_id::text || ':' || v_external_key || ':initial-entry'
        );

        insert into public.lead_entry_events (
          id,
          lead_id,
          organization_id,
          entry_type,
          source,
          provider,
          provider_event_id,
          occurred_at,
          created_at,
          is_countable,
          source_detail,
          pipeline_id,
          stage_id,
          metadata,
          payload
        ) values (
          v_entry_id,
          v_target_id,
          p_organization_id,
          'initial',
          v_source_system,
          v_source_system,
          v_source_lead_id,
          v_created_at,
          v_created_at,
          false,
          'historical_import_non_countable',
          v_pipeline_id,
          v_stage_id,
          pg_catalog.jsonb_build_object(
            'historical_import', true,
            'notification_policy', 'suppress_all',
            'external_key', v_external_key,
            'payload_sha256', v_payload_sha256
          ),
          pg_catalog.jsonb_build_object(
            'source_system', v_source_system,
            'source_lead_id', v_source_lead_id
          )
        );

        v_tags := coalesce(v_payload->'tags', '[]'::jsonb);
        if pg_catalog.jsonb_typeof(v_tags) <> 'array'
           or pg_catalog.jsonb_array_length(v_tags) > 50 then
          raise exception using
            errcode = '22023',
            message = 'historical_import_lead_tags_invalid';
        end if;

        for v_tag_value in
          select tag.value
          from pg_catalog.jsonb_array_elements(v_tags) as tag(value)
        loop
          if pg_catalog.jsonb_typeof(v_tag_value) <> 'string' then
            raise exception using
              errcode = '22023',
              message = 'historical_import_tag_name_invalid';
          end if;

          v_tag_name := pg_catalog.btrim(v_tag_value #>> '{}');
          if pg_catalog.length(v_tag_name) not between 1 and 100
             or v_tag_name ~ '[[:cntrl:]]' then
            raise exception using
              errcode = '22023',
              message = 'historical_import_tag_name_invalid';
          end if;

          insert into public.tags (
            organization_id,
            name,
            color,
            description,
            created_at
          ) values (
            p_organization_id,
            v_tag_name,
            '#6B7280',
            'Importada do histórico C2S',
            v_created_at
          )
          on conflict do nothing;

          select tag.id
          into v_tag_id
          from public.tags as tag
          where tag.organization_id = p_organization_id
            and pg_catalog.lower(pg_catalog.btrim(tag.name)) =
              pg_catalog.lower(v_tag_name)
          order by
            (tag.name = v_tag_name) desc,
            tag.created_at,
            tag.id
          limit 1;

          if v_tag_id is null then
            raise exception using
              errcode = '23514',
              message = 'historical_import_tag_upsert_failed';
          end if;

          insert into public.lead_tags (
            id,
            lead_id,
            tag_id,
            organization_id,
            created_at
          ) values (
            extensions.uuid_generate_v5(
              extensions.uuid_ns_url(),
              p_organization_id::text || ':' || v_external_key
                || ':tag:' || pg_catalog.lower(v_tag_name)
            ),
            v_target_id,
            v_tag_id,
            p_organization_id,
            v_created_at
          )
          on conflict (lead_id, tag_id) do nothing;
        end loop;

        v_lead_id := v_target_id;
      else
        begin
          v_lead_id := (v_payload->>'lead_id')::uuid;
          v_event_at := (v_payload->>'event_at')::timestamptz;
        exception
          when invalid_text_representation or datetime_field_overflow then
            raise exception using
              errcode = '22023',
              message = 'historical_import_history_reference_or_timestamp_invalid';
        end;

        if v_event_at is null
           or v_event_at > pg_catalog.clock_timestamp() + interval '1 day'
           or not exists (
             select 1
             from public.leads as lead
             where lead.organization_id = p_organization_id
               and lead.id = v_lead_id
               and lead.external_source = v_source_system
               and lead.external_source_id = v_source_lead_id
           ) then
          raise exception using
            errcode = '23503',
            message = 'historical_import_history_lead_tenant_mismatch';
        end if;

        v_message := coalesce(v_payload->>'message', '');
        if pg_catalog.length(v_message) > 500000 then
          raise exception using
            errcode = '22023',
            message = 'historical_import_history_message_too_large';
        end if;

        v_metadata := coalesce(v_payload->'metadata', '{}'::jsonb);
        if pg_catalog.jsonb_typeof(v_metadata) <> 'object' then
          raise exception using
            errcode = '22023',
            message = 'historical_import_history_metadata_invalid';
        end if;

        v_metadata := v_metadata || pg_catalog.jsonb_build_object(
          'source_system', v_source_system,
          'historical_import', true,
          'notification_policy', 'suppress_all',
          'external_key', v_external_key,
          'source_lead_id', v_source_lead_id,
          'sequence', v_payload->'sequence',
          'author_source', v_payload->'author_source',
          'time_raw', v_payload->'time_raw',
          'payload_sha256', v_payload_sha256,
          'message', v_message
        );

        if v_entity_type = 'event' then
          if nullif(pg_catalog.btrim(v_message), '') is null then
            raise exception using
              errcode = '22023',
              message = 'historical_import_event_content_required';
          end if;

          insert into public.activities (
            id,
            organization_id,
            lead_id,
            user_id,
            type,
            content,
            metadata,
            created_at
          ) values (
            v_target_id,
            p_organization_id,
            v_lead_id,
            null,
            'note',
            v_message,
            v_metadata || pg_catalog.jsonb_build_object(
              'kind', v_source_system || ':event:' || v_source_id,
              'event_kind', coalesce(
                nullif(v_payload->>'event_kind', ''),
                nullif(v_payload->>'event_type', ''),
                'history'
              ),
              'raw_text', v_payload->'raw_text',
              'title', v_payload->'title',
              'description', v_payload->'description',
              'timestamp_confidence', v_payload->'timestamp_confidence'
            ),
            v_event_at
          );
        else
          v_direction := pg_catalog.lower(pg_catalog.btrim(coalesce(
            v_payload->>'direction',
            ''
          )));
          if v_direction not in ('inbound', 'outbound') then
            raise exception using
              errcode = '22023',
              message = 'historical_import_chat_direction_invalid';
          end if;

          v_event_type := case
            when v_direction = 'inbound' then 'whatsapp_message_received'
            else 'whatsapp_message_sent'
          end;

          if v_payload->'media' is not null
             and pg_catalog.jsonb_typeof(v_payload->'media') <> 'array' then
            raise exception using
              errcode = '22023',
              message = 'historical_import_chat_media_invalid';
          end if;

          if v_message = ''
             and coalesce(pg_catalog.jsonb_array_length(
               coalesce(v_payload->'media', '[]'::jsonb)
             ), 0) = 0 then
            raise exception using
              errcode = '22023',
              message = 'historical_import_chat_content_required';
          end if;

          insert into public.activities (
            id,
            organization_id,
            lead_id,
            user_id,
            type,
            content,
            metadata,
            created_at
          ) values (
            v_target_id,
            p_organization_id,
            v_lead_id,
            null,
            v_event_type,
            nullif(v_message, ''),
            v_metadata || pg_catalog.jsonb_build_object(
              'kind', v_source_system || ':chat:' || v_source_id,
              'direction', v_direction,
              'media', coalesce(v_payload->'media', '[]'::jsonb)
            ),
            v_event_at
          );
        end if;
      end if;

      insert into private.historical_lead_import_ledger (
        organization_id,
        source_system,
        entity_type,
        source_id,
        external_key,
        target_id,
        lead_id,
        payload_sha256,
        payload,
        provenance,
        imported_by,
        batch_index
      ) values (
        p_organization_id,
        v_source_system,
        v_entity_type,
        v_source_id,
        v_external_key,
        v_target_id,
        v_lead_id,
        v_payload_sha256,
        v_payload,
        v_provenance,
        p_actor_user_id,
        v_batch_index
      );

      v_created_count := v_created_count + 1;
      v_results := v_results || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'external_key', v_external_key,
          'target_id', v_target_id,
          'action', 'CREATE'
        )
      );
    end loop;

    v_effect_after := private.historical_import_effect_counts(
      p_organization_id,
      v_batch_lead_ids,
      v_batch_target_ids
    );
    v_effect_delta := private.historical_import_effect_delta(
      v_effect_before,
      v_effect_after
    );

    select coalesce(
      pg_catalog.bool_and(effect.value::bigint = 0),
      true
    )
    into v_effect_all_zero
    from pg_catalog.jsonb_each_text(v_effect_delta) as effect(key, value);

    select coalesce(
      pg_catalog.jsonb_object_agg(
        sink.key,
        pg_catalog.jsonb_build_object(
          'before', (v_effect_before->>sink.key)::bigint,
          'after', (v_effect_after->>sink.key)::bigint,
          'delta', (v_effect_delta->>sink.key)::bigint
        )
        order by sink.key
      ),
      '{}'::jsonb
    )
    into v_effect_sinks
    from pg_catalog.jsonb_object_keys(v_effect_delta) as sink(key);

    if not v_effect_all_zero then
      raise exception using
        errcode = '23514',
        message = 'historical_import_side_effect_detected',
        detail = v_effect_delta::text;
    end if;

    delete from private.historical_lead_import_contexts as context
    where context.transaction_id = v_transaction_id;
    perform pg_catalog.set_config(
      'vimob.historical_import_token',
      '',
      true
    );
  exception
    when others then
      delete from private.historical_lead_import_contexts as context
      where context.transaction_id = v_transaction_id;
      perform pg_catalog.set_config(
        'vimob.historical_import_token',
        '',
        true
      );
      raise;
  end;

  return pg_catalog.jsonb_build_object(
    'schema_version', 1,
    'organization_id', p_organization_id,
    'entity_type', v_entity_type,
    'batch_index', v_batch_index,
    'batch_sha256', v_batch_sha256,
    'records_sha256', v_declared_records_sha256,
    'record_count', v_actual_count,
    'created_count', v_created_count,
    'noop_count', v_noop_count,
    'notification_policy', 'suppress_all',
    'effect_proof', pg_catalog.jsonb_build_object(
      'suppression_active', v_suppression_active,
      'durable_marker_enforced', true,
      'sinks', v_effect_sinks,
      'all_zero', v_effect_all_zero
    ),
    'results', v_results
  );
end;
$_$;


ALTER FUNCTION private.import_historical_lead_batch(p_organization_id uuid, p_actor_user_id uuid, p_batch jsonb) OWNER TO postgres;

--
-- Name: FUNCTION import_historical_lead_batch(p_organization_id uuid, p_actor_user_id uuid, p_batch jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.import_historical_lead_batch(p_organization_id uuid, p_actor_user_id uuid, p_batch jsonb) IS 'Atomic/idempotent historical lead import. Service-role entrypoint still requires an active actor with lead_import in the target tenant.';


--
-- Name: billing_ip_card_attempt_limits; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.billing_ip_card_attempt_limits (
    ip_fingerprint text NOT NULL,
    short_window_started_at timestamp with time zone NOT NULL,
    short_window_count integer NOT NULL,
    daily_window_started_at timestamp with time zone NOT NULL,
    daily_window_count integer NOT NULL,
    last_attempt_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_ip_card_attempt_counts_check CHECK (((short_window_count >= 1) AND (daily_window_count >= 1))),
    CONSTRAINT billing_ip_card_attempt_fingerprint_check CHECK ((ip_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT billing_ip_card_attempt_timestamps_check CHECK (((short_window_started_at <= last_attempt_at) AND (daily_window_started_at <= last_attempt_at) AND (expires_at > last_attempt_at)))
);


ALTER TABLE private.billing_ip_card_attempt_limits OWNER TO postgres;

--
-- Name: TABLE billing_ip_card_attempt_limits; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON TABLE private.billing_ip_card_attempt_limits IS 'Private cross-tenant card-attempt counters keyed only by Edge-generated HMAC-SHA256 IP fingerprints; raw IPs are forbidden.';


--
-- Name: increment_billing_ip_card_attempt_limit(text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.increment_billing_ip_card_attempt_limit(p_ip_fingerprint text, p_now timestamp with time zone) RETURNS private.billing_ip_card_attempt_limits
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_limit private.billing_ip_card_attempt_limits%rowtype;
begin
  if p_ip_fingerprint !~ '^[0-9a-f]{64}$' or p_now is null then
    raise exception 'invalid HMAC-IP limiter input' using errcode = '22023';
  end if;

  with expired as (
    select limit_row.ip_fingerprint
    from private.billing_ip_card_attempt_limits as limit_row
    where limit_row.expires_at <= p_now
    order by limit_row.expires_at
    limit 100
    for update skip locked
  )
  delete from private.billing_ip_card_attempt_limits as limit_row
  using expired
  where limit_row.ip_fingerprint = expired.ip_fingerprint;

  insert into private.billing_ip_card_attempt_limits (
    ip_fingerprint,
    short_window_started_at,
    short_window_count,
    daily_window_started_at,
    daily_window_count,
    last_attempt_at,
    expires_at
  )
  values (
    p_ip_fingerprint,
    p_now,
    1,
    p_now,
    1,
    p_now,
    p_now + interval '48 hours'
  )
  on conflict (ip_fingerprint) do update
  set
    short_window_started_at = case
      when private.billing_ip_card_attempt_limits.short_window_started_at
        <= p_now - interval '15 minutes'
      then p_now
      else private.billing_ip_card_attempt_limits.short_window_started_at
    end,
    short_window_count = case
      when private.billing_ip_card_attempt_limits.short_window_started_at
        <= p_now - interval '15 minutes'
      then 1
      else least(
        private.billing_ip_card_attempt_limits.short_window_count::bigint + 1,
        2147483647
      )::integer
    end,
    daily_window_started_at = case
      when private.billing_ip_card_attempt_limits.daily_window_started_at
        <= p_now - interval '24 hours'
      then p_now
      else private.billing_ip_card_attempt_limits.daily_window_started_at
    end,
    daily_window_count = case
      when private.billing_ip_card_attempt_limits.daily_window_started_at
        <= p_now - interval '24 hours'
      then 1
      else least(
        private.billing_ip_card_attempt_limits.daily_window_count::bigint + 1,
        2147483647
      )::integer
    end,
    last_attempt_at = p_now,
    expires_at = p_now + interval '48 hours'
  returning * into v_limit;

  return v_limit;
end
$_$;


ALTER FUNCTION private.increment_billing_ip_card_attempt_limit(p_ip_fingerprint text, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: infer_lead_intake_origin_queue(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.infer_lead_intake_origin_queue(p_lead_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with queue_evidence as (
    select
      queue.id as round_robin_id,
      coalesce(entry.occurred_at, entry.created_at) as evidence_at,
      10 as evidence_rank
    from public.lead_entry_events as entry
    join public.leads as lead
      on lead.id = entry.lead_id
     and lead.organization_id = entry.organization_id
    cross join lateral (
      values
        (nullif(pg_catalog.btrim(entry.metadata->>'target_round_robin_id'), '')),
        (nullif(pg_catalog.btrim(entry.metadata->>'round_robin_id'), '')),
        (nullif(pg_catalog.btrim(entry.metadata #>> '{intake_result,round_robin_id}'), '')),
        (nullif(pg_catalog.btrim(entry.payload->>'target_round_robin_id'), '')),
        (nullif(pg_catalog.btrim(entry.payload->>'round_robin_id'), ''))
    ) as evidence(queue_id_text)
    join public.round_robins as queue
      on queue.organization_id = entry.organization_id
     and queue.id::text = evidence.queue_id_text
    where entry.lead_id = p_lead_id
      and entry.entry_type = 'initial'
      and entry.is_countable = true

    union all

    select
      queue.id,
      lead.created_at,
      20
    from public.leads as lead
    cross join lateral (
      values
        (nullif(pg_catalog.btrim(lead.metadata->>'target_round_robin_id'), '')),
        (nullif(pg_catalog.btrim(lead.metadata #>> '{intake_result,round_robin_id}'), ''))
    ) as evidence(queue_id_text)
    join public.round_robins as queue
      on queue.organization_id = lead.organization_id
     and queue.id::text = evidence.queue_id_text
    where lead.id = p_lead_id
  ), ranked_evidence as (
    select
      evidence.*,
      pg_catalog.dense_rank() over (
        order by
          evidence.evidence_rank asc,
          evidence.evidence_at asc nulls last
      ) as evidence_position
    from queue_evidence as evidence
  ), first_evidence as (
    select distinct evidence.round_robin_id
    from ranked_evidence as evidence
    where evidence.evidence_position = 1
  )
  select case
    when pg_catalog.count(*) = 1
      then (pg_catalog.array_agg(first_evidence.round_robin_id))[1]
    else null::uuid
  end
  from first_evidence
$$;


ALTER FUNCTION private.infer_lead_intake_origin_queue(p_lead_id uuid) OWNER TO postgres;

--
-- Name: invalidate_billing_receipt_delivery_from_payment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.invalidate_billing_receipt_delivery_from_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text := upper(btrim(coalesce(new.status, '')));
  v_invalidated_at timestamptz := now();
begin
  if private.billing_payment_checkout_is_paid(v_status)
     or not private.billing_payment_checkout_is_reversal(v_status) then
    return new;
  end if;

  update public.notifications notification
  set metadata = coalesce(notification.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'receipt_invalidated', true,
      'receipt_invalidated_at', v_invalidated_at,
      'receipt_invalidation_status', v_status,
      'whatsapp_dispatch_required', lower(coalesce(
        notification.metadata -> 'whatsapp_dispatch' ->> 'status',
        notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
        ''
      )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
      'dispatch', coalesce(notification.metadata -> 'dispatch', '{}'::jsonb)
        || jsonb_build_object(
          'whatsapp', coalesce(
            notification.metadata -> 'dispatch' -> 'whatsapp',
            '{}'::jsonb
          ) || jsonb_build_object(
            'required', lower(coalesce(
              notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status', ''
            )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
            'status', case
              when lower(coalesce(
                notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status', ''
              )) in (
                'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
                'permanent_failed'
              ) then lower(notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status')
              else 'skipped'
            end,
            'invalidated_at', v_invalidated_at,
            'invalidation_status', v_status
          ),
          'email', coalesce(
            notification.metadata -> 'dispatch' -> 'email',
            '{}'::jsonb
          ) || jsonb_build_object(
            'required', lower(coalesce(
              notification.metadata -> 'dispatch' -> 'email' ->> 'status', ''
            )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
            'status', case
              when lower(coalesce(
                notification.metadata -> 'dispatch' -> 'email' ->> 'status', ''
              )) in (
                'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
                'permanent_failed'
              ) then lower(notification.metadata -> 'dispatch' -> 'email' ->> 'status')
              else 'skipped'
            end,
            'invalidated_at', v_invalidated_at,
            'invalidation_status', v_status
          ),
          'push', coalesce(
            notification.metadata -> 'dispatch' -> 'push',
            '{}'::jsonb
          ) || jsonb_build_object(
            'required', lower(coalesce(
              notification.metadata -> 'dispatch' -> 'push' ->> 'status', ''
            )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
            'status', case
              when lower(coalesce(
                notification.metadata -> 'dispatch' -> 'push' ->> 'status', ''
              )) in (
                'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
                'permanent_failed'
              ) then lower(notification.metadata -> 'dispatch' -> 'push' ->> 'status')
              else 'skipped'
            end,
            'invalidated_at', v_invalidated_at,
            'invalidation_status', v_status
          )
        ),
      'whatsapp_dispatch', coalesce(
        notification.metadata -> 'whatsapp_dispatch',
        notification.metadata -> 'dispatch' -> 'whatsapp',
        '{}'::jsonb
      ) || jsonb_build_object(
        'required', lower(coalesce(
          notification.metadata -> 'whatsapp_dispatch' ->> 'status',
          notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
          ''
        )) in ('accepted', 'delivered', 'delivery_failed', 'sent', 'permanent_failed'),
        'status', case
          when lower(coalesce(
            notification.metadata -> 'whatsapp_dispatch' ->> 'status',
            notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status',
            ''
          )) in (
            'accepted', 'delivered', 'delivery_failed', 'sent', 'skipped',
            'permanent_failed'
          ) then lower(coalesce(
            notification.metadata -> 'whatsapp_dispatch' ->> 'status',
            notification.metadata -> 'dispatch' -> 'whatsapp' ->> 'status'
          ))
          else 'skipped'
        end,
        'invalidated_at', v_invalidated_at,
        'invalidation_status', v_status
      )
    )
  where notification.organization_id = new.organization_id
    and notification.metadata ->> 'event_key' = 'billing_payment_receipt'
    and notification.metadata ->> 'payment_id' = new.id::text;

  return new;
end;
$$;


ALTER FUNCTION private.invalidate_billing_receipt_delivery_from_payment() OWNER TO postgres;

--
-- Name: invoke_google_calendar_worker(text, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.invoke_google_calendar_worker(p_action text, p_limit integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'vault', 'net'
    AS $$
declare
  cron_secret text;
  request_body jsonb;
  supabase_url text;
begin
  select decrypted_secret
  into cron_secret
  from vault.decrypted_secrets
  where name = 'google_calendar_cron_secret'
  limit 1;

  select nullif(btrim(decrypted_secret), '')
  into supabase_url
  from vault.decrypted_secrets
  where name = 'google_calendar_sync_base_url'
  limit 1;

  if cron_secret is null then
    raise exception 'Google Agenda cron secret is missing';
  end if;

  if supabase_url is null then
    raise exception 'Google Agenda sync base URL is missing';
  end if;

  request_body := jsonb_build_object('action', p_action);
  if p_limit is not null then
    request_body := request_body || jsonb_build_object('limit', p_limit);
  end if;

  return net.http_post(
    url := rtrim(supabase_url, '/')
      || '/functions/v1/google-calendar-sync',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-vimob-cron-secret', cron_secret
    ),
    body := request_body,
    timeout_milliseconds := 55000
  );
end
$$;


ALTER FUNCTION private.invoke_google_calendar_worker(p_action text, p_limit integer) OWNER TO postgres;

--
-- Name: is_admin(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_super_admin()
    or exists (
      select 1
      from public.users app_user
      join public.organization_members membership
        on membership.user_id = app_user.id
       and membership.organization_id = app_user.organization_id
      join public.organizations organization
        on organization.id = membership.organization_id
      where app_user.id = (select auth.uid())
        and coalesce(app_user.is_active, false) = true
        and coalesce(membership.is_active, false) = true
        and membership.deleted_at is null
        and membership.role in ('owner', 'admin')
        and coalesce(organization.is_active, true) = true
    );
$$;


ALTER FUNCTION private.is_admin() OWNER TO postgres;

