    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    p_from_me is false
    and coalesce(p_metadata, '{}'::jsonb) @>
      '{"lead_resolution_quarantine":{"terminal":true,"retryable":false}}'::jsonb
    and nullif(pg_catalog.btrim(coalesce(
