    and coalesce(p_metadata->>'source', '') = 'evolution_go_webhook'
    and coalesce(
      nullif(pg_catalog.btrim(p_provider_message_id), ''),
      nullif(pg_catalog.btrim(p_message_id), '')
    ) is not null
$$;


