--
-- Name: lead_intake_scope_for_external(uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lead_intake_scope_for_external(p_organization_id uuid, p_external_source text, p_external_source_id text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_source text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_external_source, '')));
  v_source_id text := pg_catalog.btrim(coalesce(p_external_source_id, ''));
begin
  if p_organization_id is null then
    raise exception using
      errcode = '22023',
      message = 'lead_intake_organization_required';
  end if;

  if v_source !~ '^[a-z0-9][a-z0-9._-]{0,63}$' then
    raise exception using
      errcode = '22023',
      message = 'lead_external_source_invalid';
  end if;

  if pg_catalog.length(v_source_id) not between 1 and 256
     or v_source_id ~ '[[:cntrl:]]' then
    raise exception using
      errcode = '22023',
      message = 'lead_external_source_id_invalid';
  end if;

  return 'external:' || v_source || ':' || v_source_id;
end;
$_$;


ALTER FUNCTION private.lead_intake_scope_for_external(p_organization_id uuid, p_external_source text, p_external_source_id text) OWNER TO postgres;

--
-- Name: lead_intake_scope_for_queue(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lead_intake_scope_for_queue(p_organization_id uuid, p_origin_round_robin_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_organization_id is null then
    raise exception using
      errcode = '22023',
      message = 'lead_intake_organization_required';
  end if;

  if p_origin_round_robin_id is null then
    return 'unscoped';
  end if;

  if not exists (
    select 1
    from public.round_robins as queue
    where queue.id = p_origin_round_robin_id
      and queue.organization_id = p_organization_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'lead_origin_round_robin_tenant_mismatch';
  end if;

  return 'queue:' || p_origin_round_robin_id::text;
end;
$$;


ALTER FUNCTION private.lead_intake_scope_for_queue(p_organization_id uuid, p_origin_round_robin_id uuid) OWNER TO postgres;

