-- Name: lead_shape_is_valid(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lead_shape_is_valid(target_organization_id uuid, target_assigned_user_id uuid, target_pipeline_id uuid, target_stage_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    target_organization_id is not null
    and (
      target_assigned_user_id is null
      or exists (
        select 1
        from public.organization_members om
        where om.organization_id = target_organization_id
          and om.user_id = target_assigned_user_id
          and coalesce(om.is_active, false) = true
      )
    )
    and (
      target_pipeline_id is null
      or exists (
        select 1
        from public.pipelines p
        where p.id = target_pipeline_id
          and p.organization_id = target_organization_id
      )
    )
    and (
      target_stage_id is null
      or exists (
        select 1
        from public.stages s
        where s.id = target_stage_id
          and s.organization_id = target_organization_id
          and (
            target_pipeline_id is null
            or s.pipeline_id = target_pipeline_id
          )
      )
    );
$$;


