--
-- Name: lead_view_all_granted(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lead_view_all_granted(p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_org_role(p_organization_id, array['owner', 'admin']::text[])
    or (
      not exists (
        select 1
        from public.user_permission_overrides as denied
        where denied.organization_id = p_organization_id
          and denied.user_id = (select auth.uid())
          and pg_catalog.lower(pg_catalog.btrim(denied.permission_key)) = 'lead_view_all'
          and denied.allowed = false
      )
      and (
        private.has_org_role(p_organization_id, array['manager']::text[])
        or private.has_permission(p_organization_id, 'lead_view_all')
        or private.user_has_permission_in_organization(
          'lead_edit_all', (select auth.uid()), p_organization_id
        )
      )
    );
$$;


ALTER FUNCTION private.lead_view_all_granted(p_organization_id uuid) OWNER TO postgres;

--
-- Name: legacy_property_offer_price_metadata(numeric, numeric); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.legacy_property_offer_price_metadata(legacy_sale_price numeric, legacy_rental_price numeric) RETURNS jsonb
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select case
    when (
      legacy_sale_price is not null
      and private.safe_legacy_property_offer_price(legacy_sale_price) is null
    ) or (
      legacy_rental_price is not null
      and private.safe_legacy_property_offer_price(legacy_rental_price) is null
    ) then jsonb_strip_nulls(jsonb_build_object(
      'legacy_price_out_of_range', true,
      'legacy_sale_price_raw', case
        when legacy_sale_price is not null
         and private.safe_legacy_property_offer_price(legacy_sale_price) is null
          then legacy_sale_price::text
      end,
      'legacy_rental_price_raw', case
        when legacy_rental_price is not null
         and private.safe_legacy_property_offer_price(legacy_rental_price) is null
          then legacy_rental_price::text
      end
    ))
    else '{}'::jsonb
  end;
$$;


ALTER FUNCTION private.legacy_property_offer_price_metadata(legacy_sale_price numeric, legacy_rental_price numeric) OWNER TO postgres;

--
-- Name: lock_asaas_billing_resources(text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lock_asaas_billing_resources(p_payment_id text, p_subscription_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_resource text;
begin
  for v_resource in
    select distinct resource
    from unnest(
      array[
        case
          when nullif(btrim(coalesce(p_payment_id, '')), '') is not null
            then 'payment:' || btrim(p_payment_id)
        end,
        case
          when nullif(btrim(coalesce(p_subscription_id, '')), '') is not null
            then 'subscription:' || btrim(p_subscription_id)
        end
      ]
    ) as resources(resource)
    where resource is not null
    order by resource
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_resource, 734621)
    );
  end loop;
end;
$$;


ALTER FUNCTION private.lock_asaas_billing_resources(p_payment_id text, p_subscription_id text) OWNER TO postgres;

--
-- Name: lock_asaas_cleanup_inventory(text[], text[], text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lock_asaas_cleanup_inventory(p_payment_ids text[], p_subscription_ids text[], p_customer_ids text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_resource text;
begin
  for v_resource in
    select distinct candidate.resource
    from (
      select 'payment:' || btrim(resource_id) as resource
      from unnest(coalesce(p_payment_ids, '{}'::text[])) as item(resource_id)
      where nullif(btrim(coalesce(resource_id, '')), '') is not null
      union all
      select 'subscription:' || btrim(resource_id)
      from unnest(coalesce(p_subscription_ids, '{}'::text[])) as item(resource_id)
      where nullif(btrim(coalesce(resource_id, '')), '') is not null
      union all
      select 'customer:' || btrim(resource_id)
      from unnest(coalesce(p_customer_ids, '{}'::text[])) as item(resource_id)
      where nullif(btrim(coalesce(resource_id, '')), '') is not null
    ) as candidate
    order by candidate.resource
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_resource, 734621)
    );
  end loop;
end
$$;


ALTER FUNCTION private.lock_asaas_cleanup_inventory(p_payment_ids text[], p_subscription_ids text[], p_customer_ids text[]) OWNER TO postgres;

--
-- Name: lock_property_legacy_location_assignment_name(uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lock_property_legacy_location_assignment_name(p_organization_id uuid, p_kind text, p_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_kind not in ('city', 'neighborhood') then
    raise exception 'unsupported property location lock kind'
      using errcode = '22023';
  end if;
  if nullif(btrim(p_name), '') is null then
    return;
  end if;
  if not pg_catalog.pg_try_advisory_xact_lock_shared(
    pg_catalog.hashtext(p_organization_id::text),
    pg_catalog.hashtext('property-location-' || p_kind || ':' || lower(btrim(p_name)))
  ) then
    raise exception 'property location catalog changed concurrently; retry the mutation'
      using errcode = '40001', constraint = 'property_location_assignment_busy';
  end if;
end
$$;


ALTER FUNCTION private.lock_property_legacy_location_assignment_name(p_organization_id uuid, p_kind text, p_name text) OWNER TO postgres;

