--
-- Name: lock_push_notification_recipient(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lock_push_notification_recipient(p_organization_id uuid, p_user_id uuid, p_token_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
begin
  -- Match account/membership/token writers; no row locks survive the durable
  -- provider-start COMMIT and none are held while waiting for provider HTTP.
  perform 1 from public.users where id=p_user_id for share;
  if not found then return false; end if;
  perform 1 from public.organization_members
    where organization_id=p_organization_id and user_id=p_user_id for share;
  if not found or not private.push_notification_recipient_is_active(p_organization_id,p_user_id) then return false; end if;
  perform 1 from public.push_tokens where id=p_token_id and user_id=p_user_id and is_active is true for share;
  return found;
end;
$$;


ALTER FUNCTION private.lock_push_notification_recipient(p_organization_id uuid, p_user_id uuid, p_token_id uuid) OWNER TO postgres;

--
-- Name: maintain_authenticated_user_activity_timestamps(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.maintain_authenticated_user_activity_timestamps() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_now timestamptz;
begin
  if current_user <> 'authenticated' then
    return new;
  end if;

  v_now := pg_catalog.clock_timestamp();

  if tg_op = 'INSERT' then
    new.connected_at := v_now;
  else
    new.connected_at := old.connected_at;
  end if;

  new.last_seen_at := v_now;
  if new.status = 'offline' then
    new.disconnected_at := v_now;
  else
    new.disconnected_at := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.maintain_authenticated_user_activity_timestamps() OWNER TO postgres;

--
-- Name: FUNCTION maintain_authenticated_user_activity_timestamps(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.maintain_authenticated_user_activity_timestamps() IS 'Uses the database clock for authenticated session lifecycle writes while allowing trusted retention to preserve historical timestamps.';


--
-- Name: maintain_user_activity_idle_since(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.maintain_user_activity_idle_since() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status <> 'idle' then
    new.idle_since_at := null;
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.idle_since_at := pg_catalog.clock_timestamp();
  elsif old.status is distinct from 'idle'
    or old.idle_since_at is null then
    new.idle_since_at := pg_catalog.clock_timestamp();
  else
    new.idle_since_at := old.idle_since_at;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.maintain_user_activity_idle_since() OWNER TO postgres;

--
-- Name: FUNCTION maintain_user_activity_idle_since(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.maintain_user_activity_idle_since() IS 'Computes and protects idle_since_at, starts legacy null states at their first reliable server observation, and preserves the value across idle heartbeats.';


--
-- Name: managed_whatsapp_message_fingerprint(uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.managed_whatsapp_message_fingerprint(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_message text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.encode(
    extensions.digest(
      coalesce(p_organization_id::text, '') || chr(31)
        || coalesce(p_session_id::text, '') || chr(31)
        || coalesce(p_provider_message_id, '') || chr(31)
        || coalesce(p_message, ''),
      'sha256'
    ),
    'hex'
  );
$$;


ALTER FUNCTION private.managed_whatsapp_message_fingerprint(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_message text) OWNER TO postgres;

--
-- Name: management_automation_graph_tag_ids(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.management_automation_graph_tag_ids(graph jsonb) RETURNS uuid[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with nodes as (
    select item.value node from jsonb_array_elements(case when jsonb_typeof(graph->'nodes') = 'array'
      then graph->'nodes' else '[]'::jsonb end) item
  ), references_to_tags as (
    select unnest(private.management_tag_value_ids(node->'config'->'tag_id')) id
    from nodes where node->>'type' = 'trigger' or
      (node->>'type' = 'action' and node->>'action_type' in ('add_tag','remove_tag'))
    union
    -- Older visual drafts use ReactFlow tag nodes; published Go graphs above
    -- use action nodes with the same tag_id in their config.
    select unnest(private.management_tag_value_ids(node->'data'->'tag_id')) id
    from nodes where node->>'type' = 'tag'
  )
  select coalesce(array_agg(distinct id order by id), '{}'::uuid[]) from references_to_tags;
$$;


ALTER FUNCTION private.management_automation_graph_tag_ids(graph jsonb) OWNER TO postgres;

--
-- Name: management_campaign_match_values(jsonb, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.management_campaign_match_values(p_match jsonb, p_legacy_value text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when coalesce(p_match ? 'campaign_name_contains_literals', false) then
      case when jsonb_typeof(p_match->'campaign_name_contains_literals') = 'array'
        and not exists (
          select 1 from jsonb_array_elements(
            case when jsonb_typeof(p_match->'campaign_name_contains_literals') = 'array'
              then p_match->'campaign_name_contains_literals' else '[]'::jsonb end
          ) item
          where jsonb_typeof(item) <> 'string' or btrim(item #>> '{}') = ''
        )
      then array(
        select lower(btrim(item.value #>> '{}'))
        from jsonb_array_elements(p_match->'campaign_name_contains_literals') with ordinality item(value, position)
        order by item.position
      )
      else '{}'::text[] end
    else array(
      select lower(btrim(value)) from unnest(string_to_array(coalesce(p_legacy_value, ''), ',')) value
      where btrim(value) <> ''
    )
  end;
$$;


ALTER FUNCTION private.management_campaign_match_values(p_match jsonb, p_legacy_value text) OWNER TO postgres;

