--
-- Name: management_meta_default_tag_ids(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.management_meta_default_tag_ids(payload jsonb) RETURNS uuid[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare values_payload jsonb := payload;
begin
  if jsonb_typeof(values_payload) = 'string' then
    begin
      values_payload := (values_payload #>> '{}')::jsonb;
    exception when invalid_text_representation then return '{}'::uuid[];
    end;
  end if;
  if jsonb_typeof(values_payload) is distinct from 'array' then return '{}'::uuid[]; end if;
  return private.management_tag_value_ids(values_payload);
end
$$;


ALTER FUNCTION private.management_meta_default_tag_ids(payload jsonb) OWNER TO postgres;

--
-- Name: management_tag_configuration_ids(text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.management_tag_configuration_ids(table_name text, payload jsonb) RETURNS uuid[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with references_to_tags as (
    select unnest(case table_name
      when 'round_robin_rules' then case when lower(coalesce(nullif(payload->>'match_type',''),
        payload->'conditions'->>'match_type',payload->>'name','')) = 'tag'
        then private.management_tag_value_ids(to_jsonb(string_to_array(coalesce(nullif(payload->>'match_value',''),
          payload->'conditions'->>'match_value',''),','))) else '{}'::uuid[] end
      when 'round_robins' then private.management_tag_value_ids(payload->'settings'->'auto_tag_ids')
      when 'webhooks_integrations' then private.management_tag_value_ids(payload->'target_tag_ids')
      when 'meta_form_configs' then private.management_tag_value_ids(payload->'auto_tags') ||
        private.management_meta_default_tag_ids(payload->'default_values'->'auto_tags')
      when 'automation_nodes' then case when payload->>'node_type' = 'trigger' or
        (payload->>'node_type' = 'action' and payload->>'action_type' in ('add_tag','remove_tag'))
        then private.management_tag_value_ids(payload->'node_config'->'tag_id') else '{}'::uuid[] end
      when 'automations' then private.management_automation_graph_tag_ids(payload->'flow_definition') ||
        case when payload->>'trigger_type' = 'tag_added' then
          private.management_tag_value_ids(payload->'trigger_config'->'tag_id') else '{}'::uuid[] end
      when 'automation_flow_versions' then private.management_automation_graph_tag_ids(payload->'graph') ||
        case when payload->>'trigger_type' = 'tag_added' then
          private.management_tag_value_ids(payload->'trigger_config'->'tag_id') else '{}'::uuid[] end
      -- Stage actions currently support assignee/status/alerts, not tags.
      -- Execution runtime data is also opaque; its pinned flow is read below.
      else '{}'::uuid[] end) id
  )
  select coalesce(array_agg(distinct id order by id), '{}'::uuid[]) from references_to_tags;
$$;


ALTER FUNCTION private.management_tag_configuration_ids(table_name text, payload jsonb) OWNER TO postgres;

--
-- Name: management_tag_reference_ids(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.management_tag_reference_ids(payload jsonb) RETURNS uuid[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$

  with recursive nodes(value) as (
    select coalesce(payload, '{}'::jsonb)
    union all
    select child.value from nodes node cross join lateral (
      select item.value from jsonb_each(case when jsonb_typeof(node.value) = 'object' then node.value else '{}'::jsonb end) item
      union all
      select item.value from jsonb_array_elements(case when jsonb_typeof(node.value) = 'array' then node.value else '[]'::jsonb end) item
    ) child
  ), candidates(value) as (
    -- Legacy rule columns and conditions may each contain half of the matcher.
    -- Read them together using the same fallback as the distribution selector.
    select entry from nodes node
    cross join lateral unnest(string_to_array(coalesce(nullif(node.value->>'match_value', ''),
      node.value->'conditions'->>'match_value', ''), ',')) entry
    where node.value ? 'round_robin_id' and lower(coalesce(nullif(node.value->>'match_type', ''),
      node.value->'conditions'->>'match_type', node.value->>'name', '')) = 'tag'
    union all
    select reference.value #>> '{}' from nodes node
    cross join lateral jsonb_each(case when jsonb_typeof(node.value) = 'object' then node.value else '{}'::jsonb end) field
    cross join lateral jsonb_path_query(field.value, '$.** ? (@.type() == "string")') reference(value)
    where lower(replace(field.key, '_', '')) in ('tag', 'tags', 'tagid', 'tagids', 'autotags', 'autotagids', 'targettagids')
    union all
    select entry from nodes node
    cross join lateral unnest(string_to_array(coalesce(node.value->>'match_value', node.value->>'matchValue', ''), ',')) entry
    where lower(coalesce(nullif(node.value->>'match_type', ''), node.value->>'matchType',
      case when node.value ? 'round_robin_id' then node.value->>'name' end, '')) = 'tag'
    union all
    select reference.value #>> '{}' from nodes node
    cross join lateral jsonb_path_query(coalesce(node.value->'values', '[]'::jsonb), '$.** ? (@.type() == "string")') reference(value)
    where lower(coalesce(node.value->>'type', '')) = 'tag'
  ), ids as (
    select distinct private.safe_uuid(btrim(value)) id from candidates
  )
  select coalesce(array_agg(id order by id) filter (where id is not null), '{}'::uuid[]) from ids;

$_$;


ALTER FUNCTION private.management_tag_reference_ids(payload jsonb) OWNER TO postgres;

--
-- Name: management_tag_usages(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.management_tag_usages(uuid, uuid) RETURNS TABLE(kind text, count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $_$

  with references_to_tag as (
    select 'distribution_rule'::text kind, rule.id::text id
    from public.round_robin_rules rule
    join public.round_robins queue on queue.id = rule.round_robin_id and queue.organization_id = $1
    where rule.organization_id = $1 and queue.deleted_at is null
      and $2 = any(private.management_tag_configuration_ids('round_robin_rules', to_jsonb(rule)))
    union
    select 'distribution_auto_tags', queue.id::text from public.round_robins queue
    where queue.organization_id = $1 and queue.deleted_at is null
      and $2 = any(private.management_tag_configuration_ids('round_robins', to_jsonb(queue)))
    union
    select 'automation', automation.id::text from public.automations automation
    where automation.organization_id = $1 and automation.deleted_at is null and (
      $2 = any(private.management_tag_configuration_ids('automations', to_jsonb(automation)))
      or exists (select 1 from public.automation_nodes node where node.automation_id = automation.id
        and $2 = any(private.management_tag_configuration_ids('automation_nodes', to_jsonb(node))))
      or exists (select 1 from public.automation_flow_versions version
        where version.id = automation.active_flow_version_id and version.organization_id = $1
          and $2 = any(private.management_tag_configuration_ids('automation_flow_versions', to_jsonb(version))))
    )
    union
    select 'automation_execution', execution.id::text from public.automation_executions execution
    join public.automation_flow_versions version on version.id = execution.flow_version_id
      and version.organization_id = execution.organization_id
    where execution.organization_id = $1 and execution.status in ('queued','running','waiting')
      and $2 = any(private.management_tag_configuration_ids('automation_flow_versions', to_jsonb(version)))
    union
    select 'stage_automation', automation.id::text from public.stage_automations automation
    where automation.organization_id = $1
      and $2 = any(private.management_tag_configuration_ids('stage_automations', to_jsonb(automation)))
    union
    select 'meta_form', form.id::text from public.meta_form_configs form
    where form.organization_id = $1
      and $2 = any(private.management_tag_configuration_ids('meta_form_configs', to_jsonb(form)))
    union
    select 'webhook', webhook.id::text from public.webhooks_integrations webhook
    where webhook.organization_id = $1
      and $2 = any(private.management_tag_configuration_ids('webhooks_integrations', to_jsonb(webhook)))
  )
  select kind, count(distinct id)::bigint from references_to_tag group by kind order by kind

$_$;


ALTER FUNCTION private.management_tag_usages(uuid, uuid) OWNER TO postgres;

--
-- Name: management_tag_value_ids(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.management_tag_value_ids(payload jsonb) RETURNS uuid[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with ids as (
    select distinct private.safe_uuid(btrim(item.value #>> '{}')) id
    from jsonb_array_elements(case jsonb_typeof(payload)
      when 'array' then payload when 'string' then jsonb_build_array(payload) else '[]'::jsonb end) item
    where jsonb_typeof(item.value) = 'string'
  )
  select coalesce(array_agg(id order by id) filter (where id is not null), '{}'::uuid[]) from ids;
$$;


ALTER FUNCTION private.management_tag_value_ids(payload jsonb) OWNER TO postgres;

--
-- Name: mark_billing_cleanup_late_payment_event(uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.mark_billing_cleanup_late_payment_event(p_organization_id uuid, p_provider_payment_id text, p_error_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_provider_payment_id text := nullif(
    btrim(coalesce(p_provider_payment_id, '')),
    ''
  );
  v_error_code text := nullif(btrim(coalesce(p_error_code, '')), '');
begin
  if p_organization_id is null
     or v_provider_payment_id is null
     or v_error_code is null
     or v_error_code !~ '^[a-z0-9_]{1,80}$' then
    raise exception 'invalid late billing cleanup event'
      using errcode = '22023';
  end if;

  perform private.lock_asaas_cleanup_inventory(
    array[v_provider_payment_id],
    '{}'::text[],
    '{}'::text[]
  );

  -- All cleanup paths use provider advisory -> organization -> claim. This
  -- also closes the race where the cleanup claim is inserted while an inbound
  -- event is being persisted.
  perform organization_row.id
  from public.organizations as organization_row
  where organization_row.id = p_organization_id
  for update;
  if not found then
    return;
  end if;

  update private.billing_organization_asaas_cleanup_claims as cleanup
  set
    last_error_code = coalesce(cleanup.last_error_code, v_error_code),
    updated_at = clock_timestamp()
  where cleanup.organization_id = p_organization_id;
end
$_$;


ALTER FUNCTION private.mark_billing_cleanup_late_payment_event(p_organization_id uuid, p_provider_payment_id text, p_error_code text) OWNER TO postgres;

--
-- Name: mark_whatsapp_outbox_sent(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.mark_whatsapp_outbox_sent(p_outbox_id uuid, p_worker_id text, p_provider_message_id text, p_sent_at timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
  with sent as (
    update public.whatsapp_outbox
    set status = 'sent',
        provider_message_id = nullif(btrim(p_provider_message_id), ''),
        sent_at = coalesce(p_sent_at, now()),
        locked_at = null,
        locked_by = null,
        last_error = null
    where id = p_outbox_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
    returning id
  )
  select exists(select 1 from sent);
$$;


ALTER FUNCTION private.mark_whatsapp_outbox_sent(p_outbox_id uuid, p_worker_id text, p_provider_message_id text, p_sent_at timestamp with time zone) OWNER TO postgres;

--
-- Name: mark_whatsapp_unlinked_retention_v1(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.mark_whatsapp_unlinked_retention_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_snapshot public.whatsapp_webhook_routing_snapshots%rowtype;
  v_resolution jsonb;
begin
  if new.capture_state not in ('unlinked_ephemeral', 'promoted_unlinked') then
    return new;
  end if;

  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = new.conversation_id
    and conversation.organization_id = new.organization_id
    and conversation.session_id = new.session_id
  for no key update;
  if not found or coalesce(v_conversation.is_group, false)
     or v_conversation.deleted_at is not null
     or v_conversation.unlinked_retention_scrubbed_at is not null then
    raise exception using errcode = '23514',
      message = 'unlinked_message_requires_proven_epoch';
  end if;

  if new.capture_state = 'promoted_unlinked' then
      if new.message_type = 'reaction' and exists (
        select 1 from public.whatsapp_messages target
        where target.id::text = pg_catalog.current_setting('vimob.whatsapp_reaction_target_id', true)
          and target.organization_id = new.organization_id and target.session_id = new.session_id
          and target.conversation_id = new.conversation_id and target.lead_id = new.lead_id
          and target.capture_state = 'promoted_unlinked'
          and target.unlinked_retention_scrubbed_at is null
          and coalesce(nullif(target.provider_message_id, ''), target.message_id) = new.reaction_to_message_id
      ) then return new; end if;
    select snapshot.* into v_snapshot
    from public.whatsapp_webhook_routing_snapshots as snapshot
    where snapshot.organization_id = new.organization_id
      and snapshot.session_id = new.session_id
      and snapshot.provider_message_id = new.provider_message_id;
    v_resolution := private.whatsapp_unlinked_capture_resolution(
      new.organization_id, new.session_id, new.conversation_id,
      new.provider_message_id, v_snapshot.inbox_event_key
    );
    if v_resolution->>'capture_state' <> 'promoted_unlinked'
       or (v_resolution->>'lead_id')::uuid is distinct from new.lead_id
       or new.sent_at > pg_catalog.clock_timestamp() + interval '5 minutes'
       or new.sent_at > (
         select link.confirmed_at
         from private.whatsapp_unlinked_history_links as link
         where link.conversation_id = new.conversation_id
       ) then
      raise exception using errcode = '23514',
        message = 'promoted_unlinked_requires_human_history_proof';
    end if;
    return new;
  end if;

  if v_conversation.lead_id is not null
     or v_conversation.created_at <= pg_catalog.clock_timestamp() - interval '7 days'
     or private.whatsapp_conversation_has_protected_history(v_conversation.id) then
    raise exception using errcode = '23514',
      message = 'unlinked_message_requires_active_unbound_conversation';
  end if;
  if v_conversation.retired_at is not null then
    select snapshot.* into v_snapshot
    from public.whatsapp_webhook_routing_snapshots as snapshot
    where snapshot.organization_id = new.organization_id
      and snapshot.session_id = new.session_id
      and snapshot.provider_message_id = new.provider_message_id;
    v_resolution := private.whatsapp_unlinked_capture_resolution(
      new.organization_id, new.session_id, new.conversation_id,
      new.provider_message_id, v_snapshot.inbox_event_key
    );
    if v_resolution->>'capture_state' <> 'unlinked_ephemeral'
       or new.sent_at > v_conversation.retired_at then
      raise exception using errcode = '23514',
        message = 'unlinked_retired_epoch_requires_prior_snapshot';
    end if;
  end if;
  if new.from_me and (
    exists (
      select 1 from public.whatsapp_outbox as outbox
      where outbox.organization_id = new.organization_id
        and outbox.session_id = new.session_id
        and outbox.provider_message_id = new.provider_message_id
    ) or exists (
      select 1 from public.outbox_messages as outbox
      where outbox.organization_id = new.organization_id
        and outbox.session_id = new.session_id
        and outbox.conversation_id = new.conversation_id
        and (
          outbox.sent_message_id = new.provider_message_id
          or outbox.client_message_id = new.client_message_id
        )
    )
  ) then
    raise exception using errcode = '23514',
      message = 'managed_outbound_cannot_be_unlinked_observation';
  end if;
  if not v_conversation.unlinked_retention_v1 then
    update public.whatsapp_conversations
    set unlinked_retention_v1 = true
    where id = v_conversation.id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.mark_whatsapp_unlinked_retention_v1() OWNER TO postgres;

--
-- Name: materialize_cadence_for_stage_cycle(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.materialize_cadence_for_stage_cycle(p_stage_cycle_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  target_cycle record;
  target_template record;
  enrollment_id uuid;
  task_snapshot jsonb;
begin
  select
    sc.id as stage_cycle_id,
    sc.organization_id,
    sc.lead_id,
    sc.pipeline_id,
    sc.stage_id,
    sc.entered_at,
    sc.metadata as stage_cycle_metadata,
    l.assigned_user_id,
    l.deal_status,
    stage.stage_key,
    stage.name as stage_name,
    rule.id as operational_rule_id,
    rule.config as operational_rule_config,
    rule.attention_mode,
    rule.first_outreach_minutes,
    rule.first_effective_contact_minutes,
    rule.stage_inactivity_minutes,
    rule.stage_max_age_minutes,
    rule.warning_minutes as stage_warning_minutes,
    rule.escalation_minutes,
    rule.business_hours_only
  into target_cycle
  from public.lead_stage_cycles sc
  join public.leads l
    on l.id = sc.lead_id
   and l.organization_id = sc.organization_id
  join public.stages stage
    on stage.id = sc.stage_id
   and stage.organization_id = sc.organization_id
  join public.stage_operational_configs rule
    on rule.organization_id = sc.organization_id
   and rule.stage_id = sc.stage_id
   and rule.cadence_enabled = true
  where sc.id = p_stage_cycle_id
    and sc.exited_at is null
    and l.deal_status = 'open'
  for share of stage, rule;

  if not found then
    return null;
  end if;

  -- A reconstructed historical baseline exists to make the timeline coherent,
  -- not to create a backlog of retroactive broker obligations.
  if coalesce(
    case lower(nullif(target_cycle.stage_cycle_metadata->>'historical_backfill', ''))
      when 'true' then true
      when 'false' then false
      else null
    end,
    false
  ) then
    return null;
  end if;

  select enrollment.id
  into enrollment_id
  from public.cadence_enrollments enrollment
  where enrollment.organization_id = target_cycle.organization_id
    and enrollment.lead_id = target_cycle.lead_id
    and enrollment.stage_cycle_id = target_cycle.stage_cycle_id
    and (
      enrollment.status = 'active'
      or (
        enrollment.status = 'completed'
        and (
          case
            when jsonb_typeof(enrollment.template_snapshot->'tasks') = 'array'
              then jsonb_array_length(enrollment.template_snapshot->'tasks') > 0
            else false
          end
          or coalesce(
            enrollment.metadata->>'has_materialized_obligations',
            'false'
          ) = 'true'
          or exists (
            select 1
            from public.lead_tasks completed_task
            where completed_task.cadence_enrollment_id = enrollment.id
              and (
                completed_task.metadata ? 'template_task_snapshot'
                or completed_task.metadata->>'source' = 'cadence'
              )
          )
        )
      )
    )
  order by
    case enrollment.status when 'active' then 0 else 1 end,
    enrollment.started_at desc,
    enrollment.id desc
  limit 1;

  if found then
    return enrollment_id;
  end if;

  select template.*
  into target_template
  from public.cadence_templates template
  where template.organization_id = target_cycle.organization_id
    and template.is_active = true
    and (
      (
        coalesce(target_cycle.operational_rule_config->>'operational_rules_version', '') = '1'
        and template.id = case
          when coalesce(target_cycle.operational_rule_config->>'cadence_template_id', '') ~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            then (target_cycle.operational_rule_config->>'cadence_template_id')::uuid
          else null
        end
        and template.stage_id = target_cycle.stage_id
      )
      or (
        coalesce(target_cycle.operational_rule_config->>'operational_rules_version', '') <> '1'
        and (
          template.stage_id = target_cycle.stage_id
          or (
            template.stage_id is null
            and template.pipeline_id = target_cycle.pipeline_id
            and template.stage_key = target_cycle.stage_key
          )
          or (
            template.pipeline_id is null
            and template.stage_id is null
            and template.stage_key = target_cycle.stage_key
          )
        )
      )
    )
    and exists (
      select 1
      from public.cadence_tasks_template task
      where task.organization_id = target_cycle.organization_id
        and task.cadence_template_id = template.id
    )
  order by
    (
      template.id::text =
      nullif(target_cycle.operational_rule_config->>'cadence_template_id', '')
    ) desc,
    case
      when template.stage_id = target_cycle.stage_id then 3
      when template.pipeline_id = target_cycle.pipeline_id then 2
      else 1
    end desc,
    template.updated_at desc,
    template.id
  limit 1;

  if not found then
    return null;
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'id', task.id,
      'position', task.position,
      'title', task.title,
      'description', task.description,
      'type', task.type,
      'observation', task.observation,
      'recommended_message', task.recommended_message,
      'message_template', task.message_template,
      'due_minutes', task.due_minutes,
      'warning_minutes', task.warning_minutes,
      'is_required', task.is_required,
      'outcome_required', task.outcome_required,
      'metadata', task.metadata
    )
    order by task.position, task.id
  )
  into task_snapshot
  from public.cadence_tasks_template task
  where task.organization_id = target_cycle.organization_id
    and task.cadence_template_id = target_template.id;

  update public.cadence_enrollments
  set status = 'cancelled',
      cancelled_at = now(),
      cancel_reason = 'cadence_replaced',
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'cancel_reason', 'cadence_replaced',
        'cancelled_at', now()
      )
  where lead_id = target_cycle.lead_id
    and status = 'active';

  insert into public.cadence_enrollments (
    organization_id,
    lead_id,
    cadence_template_id,
    stage_cycle_id,
    assigned_user_id,
    started_at,
    template_snapshot,
    metadata
  ) values (
    target_cycle.organization_id,
    target_cycle.lead_id,
    target_template.id,
    target_cycle.stage_cycle_id,
    target_cycle.assigned_user_id,
    target_cycle.entered_at,
    jsonb_build_object(
      'schema_version', 2,
      'captured_at', now(),
      'template', jsonb_build_object(
        'id', target_template.id,
        'name', target_template.name,
        'description', target_template.description,
        'pipeline_id', target_template.pipeline_id,
        'stage_id', target_template.stage_id,
        'stage_key', target_template.stage_key,
        'is_active', target_template.is_active
      ),
      'operational_rule', jsonb_build_object(
        'id', target_cycle.operational_rule_id,
        'stage_id', target_cycle.stage_id,
        'cadence_enabled', true,
        'attention_mode', target_cycle.attention_mode,
        'first_outreach_minutes', target_cycle.first_outreach_minutes,
        'first_effective_contact_minutes', target_cycle.first_effective_contact_minutes,
        'stage_inactivity_minutes', target_cycle.stage_inactivity_minutes,
        'stage_max_age_minutes', target_cycle.stage_max_age_minutes,
        'warning_minutes', target_cycle.stage_warning_minutes,
        'escalation_minutes', target_cycle.escalation_minutes,
        'business_hours_only', target_cycle.business_hours_only
      ),
      'tasks', task_snapshot
    ),
    jsonb_build_object(
      'source', 'stage_cycle',
      'stage_name', target_cycle.stage_name,
      'operational_rule_id', target_cycle.operational_rule_id,
      'historical_backfill', coalesce(
        target_cycle.stage_cycle_metadata->'historical_backfill',
        'false'::jsonb
      ),
      'has_materialized_obligations', true,
      'materialized_task_count', jsonb_array_length(task_snapshot)
    )
  )
  on conflict (stage_cycle_id)
    where stage_cycle_id is not null and status = 'active'
  do update
    set assigned_user_id = excluded.assigned_user_id,
        updated_at = now()
  returning id into enrollment_id;

  insert into public.lead_tasks (
    organization_id,
    lead_id,
    assigned_user_id,
    title,
    description,
    type,
    day_offset,
    due_at,
    due_date,
    is_done,
    status,
    sequence,
    cadence_enrollment_id,
    cadence_template_task_id,
    metadata
  )
  select
    target_cycle.organization_id,
    target_cycle.lead_id,
    target_cycle.assigned_user_id,
    task.title,
    coalesce(nullif(task.description, ''), nullif(task.metadata->>'description', '')),
    coalesce(nullif(task.type, ''), 'call'),
    task.due_minutes / 1440,
    target_cycle.entered_at + make_interval(mins => task.due_minutes),
    (target_cycle.entered_at + make_interval(mins => task.due_minutes))::date,
    false,
    'pending',
    task.position,
    enrollment_id,
    task.id,
    coalesce(task.metadata, '{}'::jsonb) || jsonb_build_object(
      'source', 'cadence',
      'cadence_template_id', target_template.id,
      'due_minutes', task.due_minutes,
      'warning_minutes', task.warning_minutes,
      'is_required', task.is_required,
      'outcome_required', task.outcome_required,
      'warning_at', case
        when task.warning_minutes > 0
          then target_cycle.entered_at
            + make_interval(mins => task.due_minutes - task.warning_minutes)
        else null
      end,
      'message_template', coalesce(task.message_template, task.recommended_message),
      'template_task_snapshot', jsonb_build_object(
        'id', task.id,
        'position', task.position,
        'title', task.title,
        'description', task.description,
        'type', task.type,
        'observation', task.observation,
        'recommended_message', task.recommended_message,
        'message_template', task.message_template,
        'due_minutes', task.due_minutes,
        'warning_minutes', task.warning_minutes,
        'is_required', task.is_required,
        'outcome_required', task.outcome_required
      )
    )
  from public.cadence_tasks_template task
  where task.organization_id = target_cycle.organization_id
    and task.cadence_template_id = target_template.id
  on conflict (cadence_enrollment_id, cadence_template_task_id)
    where cadence_enrollment_id is not null
      and cadence_template_task_id is not null
  do nothing;

  return enrollment_id;
end;
$_$;


ALTER FUNCTION private.materialize_cadence_for_stage_cycle(p_stage_cycle_id uuid) OWNER TO postgres;

--
-- Name: materialize_notification_deliveries(uuid, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.materialize_notification_deliveries(p_notification_id uuid, p_backfill boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_notification public.notifications%rowtype;
  v_channel text;
  v_channel_metadata jsonb;
  v_required boolean;
  v_legacy_status text;
  v_status text;
  v_dependency_key text;
  v_recipient_key text;
  v_push_token_id uuid;
  v_source_dedupe_key text;
  v_idempotency_key text;
  v_attempt_count integer;
  v_max_attempts integer;
  v_priority integer;
  v_next_attempt_at timestamptz;
  v_expires_at timestamptz;
  v_provider text;
  v_provider_message_id text;
  v_accepted_at timestamptz;
  v_delivered_at timestamptz;
  v_terminal_at timestamptz;
  v_inserted integer := 0;
  v_affected integer := 0;
begin
  if p_notification_id is null then
    return 0;
  end if;

  select notification.*
    into v_notification
  from public.notifications as notification
  where notification.id = p_notification_id;

  if not found then
    return 0;
  end if;

  v_source_dedupe_key := nullif(btrim(v_notification.metadata ->> 'dedupe_key'), '');

  foreach v_channel in array array['whatsapp'::text, 'email'::text, 'push'::text]
  loop
    v_channel_metadata := case
      when v_channel = 'whatsapp' then coalesce(
        v_notification.metadata #> '{dispatch,whatsapp}',
        v_notification.metadata -> 'whatsapp_dispatch',
        '{}'::jsonb
      )
      else coalesce(
        v_notification.metadata #> array['dispatch', v_channel],
        '{}'::jsonb
      )
    end;

    v_required := private.notification_dispatch_required(
      v_channel_metadata -> 'required'
    );
    if v_channel = 'whatsapp' then
      v_required := v_required
        or private.notification_dispatch_required(
          v_notification.metadata -> 'whatsapp_dispatch_required'
        );
    end if;

    if not v_required then
      update private.notification_deliveries as delivery
      set status = 'cancelled',
          next_attempt_at = null,
          lease_token = null,
          leased_by = null,
          lease_expires_at = null,
          dependency_key = null,
          terminal_at = now(),
          last_error_code = 'delivery_not_required',
          last_error_message = 'Delivery requirement was removed from the notification.',
          last_error_at = now(),
          updated_at = now()
      where delivery.notification_id = v_notification.id
        and delivery.channel = v_channel
        and delivery.status in (
          'queued', 'leased', 'sending', 'retry_wait', 'blocked_dependency'
        );
      continue;
    end if;

    v_legacy_status := lower(btrim(coalesce(
      v_channel_metadata ->> 'status',
      case
        when v_channel = 'whatsapp'
          then v_notification.metadata #>> '{whatsapp_dispatch,status}'
        else null
      end,
      'pending'
    )));
    v_max_attempts := private.notification_safe_integer(
      v_channel_metadata ->> 'max_attempts',
      24,
      1,
      100
    );
    v_attempt_count := private.notification_safe_integer(
      coalesce(
        v_channel_metadata ->> 'attempts',
        v_channel_metadata ->> 'attempt_count'
      ),
      0,
      0,
      v_max_attempts
    );
    v_priority := private.notification_safe_integer(
      coalesce(
        v_channel_metadata ->> 'priority',
        v_notification.metadata ->> 'priority'
      ),
      case
        when lower(coalesce(v_notification.metadata ->> 'event_key', '')) like 'billing_%' then 300
        when lower(coalesce(v_notification.metadata ->> 'event_key', '')) in (
          'new_lead_received', 'lead_reentry', 'lead_transferred',
          'lead_auto_redistributed', 'whatsapp_disconnected'
        ) then 250
        when lower(coalesce(v_notification.metadata ->> 'event_key', '')) in (
          'update_phone_reminder', 'gamification_update', 'announcement'
        ) then 50
        else 100
      end,
      0,
      1000
    );
    v_expires_at := private.notification_delivery_expiry(
      v_notification.created_at,
      v_notification.metadata,
      v_channel_metadata
    );
    v_next_attempt_at := coalesce(
      private.notification_safe_timestamptz(v_channel_metadata ->> 'next_attempt_at'),
      private.notification_safe_timestamptz(v_channel_metadata ->> 'next_retry_at'),
      now()
    );
    v_provider := nullif(left(btrim(v_channel_metadata ->> 'provider'), 100), '');
    if v_provider is null and v_channel = 'email' then
      v_provider := 'resend';
    end if;
    v_provider_message_id := case
      when v_channel = 'push' then null
      when v_channel = 'whatsapp' then nullif(left(btrim(coalesce(
        v_channel_metadata ->> 'expected_message_id',
        v_channel_metadata ->> 'message_id'
      )), 500), '')
      else nullif(left(btrim(v_channel_metadata ->> 'message_id'), 500), '')
    end;

    v_accepted_at := coalesce(
      private.notification_safe_timestamptz(v_channel_metadata ->> 'accepted_at'),
      private.notification_safe_timestamptz(v_channel_metadata ->> 'sent_at')
    );
    v_delivered_at := coalesce(
      private.notification_safe_timestamptz(v_channel_metadata ->> 'delivered_at'),
      private.notification_safe_timestamptz(v_channel_metadata ->> 'delivery_occurred_at')
    );
    v_dependency_key := null;
    v_terminal_at := null;

    if v_expires_at <= now() or v_attempt_count >= v_max_attempts then
      v_status := 'dead_letter';
      v_terminal_at := now();
    elsif v_legacy_status = 'delivered' then
      v_status := 'delivered';
      v_delivered_at := coalesce(v_delivered_at, now());
      v_terminal_at := v_delivered_at;
    elsif v_legacy_status in ('accepted', 'sent') then
      v_status := 'accepted';
      v_accepted_at := coalesce(v_accepted_at, now());
    elsif v_legacy_status = 'permanent_failed' then
      v_status := 'permanent_failed';
      v_terminal_at := coalesce(
        private.notification_safe_timestamptz(v_channel_metadata ->> 'failed_at'),
        now()
      );
    elsif v_legacy_status = 'skipped' then
      v_status := 'cancelled';
      v_terminal_at := now();
    elsif p_backfill then
      v_status := 'blocked_dependency';
      v_dependency_key := 'legacy_backfill_cutover';
    elsif v_legacy_status in ('failed', 'delivery_failed', 'retry_wait') then
      v_status := 'retry_wait';
    else
      v_status := 'queued';
    end if;

    if v_status not in ('queued', 'retry_wait') then
      v_next_attempt_at := null;
    end if;

    if v_channel in ('whatsapp', 'email') then
      v_push_token_id := null;
      v_recipient_key := case
        when v_notification.user_id is not null
          then 'user:' || v_notification.user_id::text
        else 'notification:' || v_notification.id::text
      end;

      -- A recipient change never mutates or duplicates a terminal delivery.
      -- It fences only work that has not reached a provider-terminal state.
      update private.notification_deliveries as delivery
      set status = 'cancelled',
          next_attempt_at = null,
          lease_token = null,
          leased_by = null,
          lease_expires_at = null,
          dependency_key = null,
          terminal_at = now(),
          last_error_code = 'recipient_changed',
          last_error_message = 'The notification recipient identity changed before delivery.',
          last_error_at = now(),
          updated_at = now()
      where delivery.notification_id = v_notification.id
        and delivery.channel = v_channel
        and delivery.recipient_key <> v_recipient_key
        and delivery.status in (
          'queued', 'leased', 'sending', 'retry_wait', 'blocked_dependency'
        );

      v_idempotency_key := private.notification_delivery_idempotency_key(
        v_notification.organization_id,
        v_notification.id,
        v_source_dedupe_key,
        v_channel,
        v_recipient_key
      );

      insert into private.notification_deliveries (
        notification_id,
        organization_id,
        user_id,
        channel,
        recipient_key,
        push_token_id,
        idempotency_key,
        status,
        priority,
        attempt_count,
        max_attempts,
        next_attempt_at,
        expires_at,
        dependency_key,
        provider,
        provider_message_id,
        provider_status,
        accepted_at,
        delivered_at,
        blocked_at,
        terminal_at,
        last_error_code,
        last_error_message,
        last_error_at,
        metadata,
        created_at,
        updated_at
      )
      values (
        v_notification.id,
        v_notification.organization_id,
        v_notification.user_id,
        v_channel,
        v_recipient_key,
        null,
        v_idempotency_key,
        v_status,
        v_priority,
        v_attempt_count,
        v_max_attempts,
        v_next_attempt_at,
        v_expires_at,
        v_dependency_key,
        v_provider,
        v_provider_message_id,
        nullif(left(btrim(v_channel_metadata ->> 'delivery_status'), 255), ''),
        v_accepted_at,
        v_delivered_at,
        case when v_status = 'blocked_dependency' then now() else null end,
        v_terminal_at,
        nullif(btrim(v_channel_metadata ->> 'error_code'), ''),
        nullif(left(btrim(v_channel_metadata ->> 'error'), 2000), ''),
        case
          when nullif(btrim(v_channel_metadata ->> 'error'), '') is not null then now()
          else null
        end,
        jsonb_strip_nulls(jsonb_build_object(
          'source', case when p_backfill then 'legacy_backfill' else 'notification_trigger' end,
          'legacy_status', v_legacy_status,
          'event_key', nullif(v_notification.metadata ->> 'event_key', ''),
          'expected_message_id', case
            when v_channel = 'whatsapp'
              then private.notification_delivery_expected_message_id(v_idempotency_key)
            else null
          end
        )),
        v_notification.created_at,
        now()
      )
      on conflict do nothing;
      get diagnostics v_affected = row_count;
      v_inserted := v_inserted + v_affected;
    else
      -- Push delivery is tracked per active token. A user with no active token
      -- gets no external job; the in-app notification remains authoritative.
      update private.notification_deliveries as delivery
      set status = 'cancelled',
          next_attempt_at = null,
          lease_token = null,
          leased_by = null,
          lease_expires_at = null,
          dependency_key = null,
          terminal_at = now(),
          last_error_code = 'push_token_inactive',
          last_error_message = 'The target push token is no longer active.',
          last_error_at = now(),
          updated_at = now()
      where delivery.notification_id = v_notification.id
        and delivery.channel = 'push'
        and not private.whatsapp_inbound_push_is_unstarted(delivery)
        and delivery.status in (
          'queued', 'leased', 'sending', 'retry_wait', 'blocked_dependency'
        )
        and not exists (
          select 1
          from public.push_tokens as token
          where token.id = delivery.push_token_id
            and private.push_notification_recipient_is_active(v_notification.organization_id,v_notification.user_id)
            and token.user_id = v_notification.user_id
            and token.is_active is true
        );

      for v_push_token_id in
        select token.id
        from public.push_tokens as token
        where private.push_notification_recipient_is_active(v_notification.organization_id,v_notification.user_id)
          and token.user_id = v_notification.user_id
          and token.is_active is true
        order by token.id
      loop
        v_recipient_key := 'push_token:' || v_push_token_id::text;
        v_idempotency_key := private.notification_delivery_idempotency_key(
          v_notification.organization_id,
          v_notification.id,
          v_source_dedupe_key,
          v_channel,
          v_recipient_key
        );

        insert into private.notification_deliveries (
          notification_id,
          organization_id,
          user_id,
          channel,
          recipient_key,
          push_token_id,
          idempotency_key,
          status,
          priority,
          attempt_count,
          max_attempts,
          next_attempt_at,
          expires_at,
          dependency_key,
          provider,
          accepted_at,
          delivered_at,
          blocked_at,
          terminal_at,
          last_error_code,
          last_error_message,
          last_error_at,
          metadata,
          created_at,
          updated_at
        )
        values (
          v_notification.id,
          v_notification.organization_id,
          v_notification.user_id,
          v_channel,
          v_recipient_key,
          v_push_token_id,
          v_idempotency_key,
          v_status,
          v_priority,
          v_attempt_count,
          v_max_attempts,
          v_next_attempt_at,
          v_expires_at,
          v_dependency_key,
          v_provider,
          v_accepted_at,
          v_delivered_at,
          case when v_status = 'blocked_dependency' then now() else null end,
          v_terminal_at,
          nullif(btrim(v_channel_metadata ->> 'error_code'), ''),
          nullif(left(btrim(v_channel_metadata ->> 'error'), 2000), ''),
          case
            when nullif(btrim(v_channel_metadata ->> 'error'), '') is not null then now()
            else null
          end,
          jsonb_strip_nulls(jsonb_build_object(
            'source', case when p_backfill then 'legacy_backfill' else 'notification_trigger' end,
            'legacy_status', v_legacy_status,
            'event_key', nullif(v_notification.metadata ->> 'event_key', '')
          )),
          v_notification.created_at,
          now()
        )
        on conflict do nothing;
        get diagnostics v_affected = row_count;
        v_inserted := v_inserted + v_affected;
      end loop;
    end if;
  end loop;

  -- If a producer removed a channel or changed its recipient while an old
  -- worker held a lease, fence that worker and close the corresponding ledger
  -- row instead of leaving a permanent `sending` diagnostic.
  update private.notification_delivery_attempts as attempt
  set outcome = 'cancelled',
      completed_at = coalesce(attempt.completed_at, now()),
      error_code = coalesce(attempt.error_code, 'delivery_materialization_cancelled'),
      error_message = coalesce(
        attempt.error_message,
        'Notification requirements or recipient changed during delivery.'
      )
  from private.notification_deliveries as delivery
  where delivery.notification_id = v_notification.id
    and delivery.status = 'cancelled'
    and attempt.delivery_id = delivery.id
    and attempt.event_type = 'send_attempt'
    and attempt.outcome = 'sending';

  if not p_backfill then perform private.register_whatsapp_inbound_push_waiting(p_notification_id); end if;
  return v_inserted;
end
$$;


ALTER FUNCTION private.materialize_notification_deliveries(p_notification_id uuid, p_backfill boolean) OWNER TO postgres;

--
-- Name: meta_delete_access_token(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.meta_delete_access_token() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'vault'
    AS $$
begin
  if old.access_token_secret_ref is not null then
    delete from vault.secrets where id = old.access_token_secret_ref;
  end if;
  if old.user_access_token_secret_ref is not null
     and old.user_access_token_secret_ref is distinct from old.access_token_secret_ref then
    delete from vault.secrets where id = old.user_access_token_secret_ref;
  end if;
  if old.crm_dataset_access_token_secret_ref is not null
     and old.crm_dataset_access_token_secret_ref is distinct from old.access_token_secret_ref
     and old.crm_dataset_access_token_secret_ref is distinct from old.user_access_token_secret_ref then
    delete from vault.secrets where id = old.crm_dataset_access_token_secret_ref;
  end if;
  return old;
end;
$$;


ALTER FUNCTION private.meta_delete_access_token() OWNER TO postgres;

--
-- Name: meta_delete_oauth_flow_transient_secret(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.meta_delete_oauth_flow_transient_secret() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'vault'
    AS $$
declare
  old_secret_id uuid;
  new_secret_id uuid;
begin
  old_secret_id := private.meta_oauth_flow_transient_secret_id(old.payload);
  if tg_op = 'UPDATE' then
    new_secret_id := private.meta_oauth_flow_transient_secret_id(new.payload);
  end if;

  if old_secret_id is not null
     and old_secret_id is distinct from new_secret_id then
    delete from vault.secrets as secret
    where secret.id = old_secret_id
      and secret.name = 'meta-oauth-flow:' || old.id::text;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.meta_delete_oauth_flow_transient_secret() OWNER TO postgres;

--
-- Name: meta_legacy_plaintext_token(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.meta_legacy_plaintext_token(p_secret_ref text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select case
    when left(btrim(p_secret_ref), 6) = 'plain:'
      then nullif(btrim(substr(btrim(p_secret_ref), 7)), '')
    else null
  end;
$$;


ALTER FUNCTION private.meta_legacy_plaintext_token(p_secret_ref text) OWNER TO postgres;

--
-- Name: meta_legacy_vault_secret_id(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.meta_legacy_vault_secret_id(p_secret_ref text) RETURNS uuid
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog', 'vault'
    AS $_$
  select secret.id
  from vault.secrets as secret
  where secret.id = case
    when btrim(p_secret_ref)
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then btrim(p_secret_ref)::uuid
    else null
  end;
$_$;


ALTER FUNCTION private.meta_legacy_vault_secret_id(p_secret_ref text) OWNER TO postgres;

--
-- Name: meta_oauth_flow_transient_secret_id(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.meta_oauth_flow_transient_secret_id(p_payload jsonb) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
  select case
    when jsonb_typeof(p_payload) = 'object'
      and nullif(p_payload->>'user_token_secret_ref', '')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then (p_payload->>'user_token_secret_ref')::uuid
    else null
  end;
$_$;


ALTER FUNCTION private.meta_oauth_flow_transient_secret_id(p_payload jsonb) OWNER TO postgres;

--
-- Name: meta_store_access_token(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.meta_store_access_token() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'vault'
    AS $$
declare
  secret_id uuid;
  secret_name text;
  token_value text;
begin
  token_value := nullif(btrim(new.access_token), '');

  if token_value is null then
    -- The reference is server-managed. A browser role that may update its own
    -- integration row cannot swap in another tenant's Vault UUID.
    if tg_op = 'UPDATE' then
      new.access_token_secret_ref := old.access_token_secret_ref;
    else
      new.access_token_secret_ref := null;
    end if;
    new.access_token := null;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    secret_id := old.access_token_secret_ref;
  end if;

  secret_name := format(
    'meta:%s:%s',
    new.organization_id::text,
    coalesce(nullif(new.page_id, ''), new.id::text)
  );

  if secret_id is null then
    secret_id := vault.create_secret(
      token_value,
      secret_name,
      'Meta access token managed by Vimob CRM'
    );
  else
    perform vault.update_secret(
      secret_id,
      token_value,
      secret_name,
      'Meta access token managed by Vimob CRM'
    );
  end if;

  new.access_token_secret_ref := secret_id;
  new.access_token := null;
  return new;
end;
$$;


ALTER FUNCTION private.meta_store_access_token() OWNER TO postgres;

--
-- Name: FUNCTION meta_store_access_token(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.meta_store_access_token() IS 'Trigger-only: stores the Meta Page token in Vault and clears plaintext before persistence.';


--
-- Name: meta_store_crm_dataset_access_token(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.meta_store_crm_dataset_access_token() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'vault'
    AS $$
declare
  secret_id uuid;
  secret_name text;
  token_value text;
begin
  new.crm_dataset_id := nullif(btrim(new.crm_dataset_id), '');
  new.crm_dataset_name := nullif(btrim(new.crm_dataset_name), '');
  token_value := nullif(btrim(new.crm_dataset_access_token), '');

  if tg_op = 'UPDATE'
     and new.crm_dataset_id is distinct from old.crm_dataset_id
     and new.crm_dataset_id is not null
     and token_value is null then
    raise exception using
      errcode = '23514',
      message = 'Changing the CRM Dataset requires a new access token';
  end if;

  if token_value is null then
    if tg_op = 'UPDATE' then
      new.crm_dataset_access_token_secret_ref := old.crm_dataset_access_token_secret_ref;
    else
      new.crm_dataset_access_token_secret_ref := null;
    end if;
    new.crm_dataset_access_token := null;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    secret_id := old.crm_dataset_access_token_secret_ref;
  end if;

  secret_name := format(
    'meta-crm-dataset:%s:%s:%s',
    new.organization_id::text,
    coalesce(nullif(btrim(new.crm_dataset_id), ''), 'unassigned'),
    coalesce(nullif(new.page_id, ''), new.id::text)
  );

  if secret_id is null then
    secret_id := vault.create_secret(
      token_value,
      secret_name,
      'Meta CRM Dataset access token managed by Vimob CRM'
    );
  else
    perform vault.update_secret(
      secret_id,
      token_value,
      secret_name,
      'Meta CRM Dataset access token managed by Vimob CRM'
    );
  end if;

  new.crm_dataset_access_token_secret_ref := secret_id;
  new.crm_dataset_access_token := null;
  return new;
end;
$$;


ALTER FUNCTION private.meta_store_crm_dataset_access_token() OWNER TO postgres;

--
-- Name: meta_store_user_access_token(); Type: FUNCTION; Schema: private; Owner: postgres
--

