--
-- Name: normalize_lead_distribution_source(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_lead_distribution_source(p_source text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select case
    when normalized = any (
      array[
        'facebook',
        'facebook_ads',
        'facebook_lead_ads',
        'meta',
        'meta_ads'
      ]::text[]
    ) then 'meta'
    when normalized = any (
      array[
        'wa',
        'whats_app',
        'whatsapp',
        'wpp'
      ]::text[]
    ) then 'whatsapp'
    when normalized = any (
      array[
        'form',
        'landing_page',
        'site',
        'website'
      ]::text[]
    ) then 'site'
    when normalized = any (
      array[
        'api',
        'hook',
        'web_hook',
        'webhook',
        'zapier'
      ]::text[]
    ) then 'webhook'
    when normalized = '' then 'manual'
    else normalized
  end
  from (
    select regexp_replace(
      lower(btrim(coalesce(p_source, ''))),
      '[^a-z0-9]+',
      '_',
      'g'
    ) as normalized
  ) as source_value;
$$;


ALTER FUNCTION private.normalize_lead_distribution_source(p_source text) OWNER TO postgres;

--
-- Name: normalize_legacy_property_offer_before_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_legacy_property_offer_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(new.metadata ->> 'legacy_backfill', 'false') = 'true' then
    if new.price_period is null then
      new.price_period := case new.offer_type
        when 'sale' then 'total'
        when 'rent' then 'monthly'
        else 'daily'
      end;
    end if;

    if new.status = 'active' and (new.price is null or new.price <= 0) then
      new.status := 'paused';
      new.metadata := new.metadata || jsonb_build_object(
        'hardening_reason',
        'active_offer_without_positive_price'
      );
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.normalize_legacy_property_offer_before_write() OWNER TO postgres;

--
-- Name: normalize_property_deal_type(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_property_deal_type() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_finalidade text := private.canonical_property_deal_type(new.finalidade);
  v_legacy text := private.canonical_property_deal_type(new.tipo_de_negocio);
  v_old text;
  v_deal_type text;
  v_finalidade_changed boolean := true;
  v_legacy_changed boolean := true;
begin
  if tg_op = 'UPDATE' then
    v_finalidade_changed := new.finalidade is distinct from old.finalidade;
    v_legacy_changed := new.tipo_de_negocio is distinct from old.tipo_de_negocio;
    v_old := coalesce(
      private.canonical_property_deal_type(old.finalidade),
      private.canonical_property_deal_type(old.tipo_de_negocio)
    );
  end if;

  -- Backward-compatible purpose writes are moved out of `finalidade` instead
  -- of being mistaken for a deal type.
  if nullif(btrim(coalesce(new.finalidade, '')), '') is not null
     and v_finalidade is null then
    new.finalidade_uso := btrim(new.finalidade);
  end if;

  if v_legacy_changed
     and nullif(btrim(coalesce(new.tipo_de_negocio, '')), '') is not null
     and v_legacy is null then
    raise exception 'invalid property deal type'
      using errcode = '23514', constraint = 'properties_deal_type_check';
  end if;

  if tg_op = 'UPDATE'
     and v_finalidade_changed and v_legacy_changed
     and v_finalidade is not null and v_legacy is not null
     and v_finalidade <> v_legacy then
    raise exception 'conflicting property deal types'
      using errcode = '23514', constraint = 'properties_deal_type_sync_check';
  end if;

  if tg_op = 'INSERT' then
    -- Legacy clients explicitly write tipo_de_negocio while finalidade still
    -- receives its historical default. Prefer the explicit legacy value.
    v_deal_type := coalesce(v_legacy, v_finalidade);
  elsif v_legacy_changed and v_legacy is not null then
    v_deal_type := v_legacy;
  elsif v_finalidade_changed and v_finalidade is not null then
    v_deal_type := v_finalidade;
  else
    v_deal_type := coalesce(v_old, v_finalidade, v_legacy);
  end if;

  if v_deal_type is null then
    v_deal_type := case
      when coalesce(new.preco, 0) > 0
       and coalesce(new.valor_locacao, 0) > 0 then 'venda_locacao'
      when coalesce(new.valor_locacao, 0) > 0 then 'locacao'
      else 'venda'
    end;
  end if;

  new.finalidade := v_deal_type;
  new.tipo_de_negocio := v_deal_type;
  return new;
end
$$;


ALTER FUNCTION private.normalize_property_deal_type() OWNER TO postgres;

--
-- Name: notification_delivery_expected_message_id(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notification_delivery_expected_message_id(p_idempotency_key text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select upper(substr(
    pg_catalog.encode(
      extensions.digest(coalesce(p_idempotency_key, ''), 'sha256'),
      'hex'
    ),
    1,
    32
  ));
$$;


ALTER FUNCTION private.notification_delivery_expected_message_id(p_idempotency_key text) OWNER TO postgres;

--
-- Name: notification_delivery_expiry(timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notification_delivery_expiry(p_created_at timestamp with time zone, p_metadata jsonb, p_channel_metadata jsonb) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_event_key text := lower(btrim(coalesce(p_metadata ->> 'event_key', '')));
  v_explicit timestamptz;
  v_schedule_time timestamptz;
begin
  v_explicit := coalesce(
    private.notification_safe_timestamptz(p_channel_metadata ->> 'expires_at'),
    private.notification_safe_timestamptz(p_metadata ->> 'expires_at')
  );
  if v_explicit is not null then
    return greatest(v_explicit, p_created_at);
  end if;

  if v_event_key in ('schedule_reminder', 'appointment_reminder') then
    v_schedule_time := coalesce(
      private.notification_safe_timestamptz(p_metadata ->> 'start_time'),
      private.notification_safe_timestamptz(p_metadata ->> 'reminder_due_at'),
      private.notification_safe_timestamptz(p_metadata #>> '{variables,start_time}'),
      private.notification_safe_timestamptz(p_metadata #>> '{variables,reminder_due_at}')
    );
    return greatest(
      p_created_at,
      coalesce(v_schedule_time + interval '15 minutes', p_created_at + interval '6 hours')
    );
  end if;

  if v_event_key in (
    'new_lead_received', 'lead_reentry', 'lead_duplicate_existing',
    'lead_transferred', 'lead_stage_changed', 'deal_won',
    'lead_auto_redistributed', 'lead_auto_redistribution_failed'
  ) or v_event_key like 'billing_%'
    or v_event_key like 'onboarding_%' then
    return p_created_at + interval '7 days';
  end if;

  if v_event_key in (
    'update_phone_reminder', 'gamification_update', 'announcement',
    'whatsapp_disconnected'
  ) then
    return p_created_at + interval '1 day';
  end if;

  return p_created_at + interval '3 days';
end
$$;


ALTER FUNCTION private.notification_delivery_expiry(p_created_at timestamp with time zone, p_metadata jsonb, p_channel_metadata jsonb) OWNER TO postgres;

--
-- Name: notification_delivery_idempotency_key(uuid, uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notification_delivery_idempotency_key(p_organization_id uuid, p_notification_id uuid, p_source_dedupe_key text, p_channel text, p_recipient_key text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select 'notification-delivery:v1:' || pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        p_organization_id::text || '|' ||
        coalesce(nullif(btrim(p_source_dedupe_key), ''), 'notification:' || p_notification_id::text) || '|' ||
        lower(btrim(p_channel)) || '|' ||
        btrim(p_recipient_key),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


ALTER FUNCTION private.notification_delivery_idempotency_key(p_organization_id uuid, p_notification_id uuid, p_source_dedupe_key text, p_channel text, p_recipient_key text) OWNER TO postgres;

--
-- Name: notification_delivery_metrics(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notification_delivery_metrics() RETURNS TABLE(organization_id uuid, channel text, status text, delivery_count bigint, due_count bigint, oldest_created_at timestamp with time zone, oldest_next_attempt_at timestamp with time zone, oldest_lease_expires_at timestamp with time zone, max_attempt_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    delivery.organization_id,
    delivery.channel,
    delivery.status,
    count(*)::bigint as delivery_count,
    count(*) filter (
      where (
        delivery.status in ('queued', 'retry_wait')
        and delivery.next_attempt_at <= now()
      ) or (
        delivery.status in ('leased', 'sending')
        and delivery.lease_expires_at <= now()
      )
    )::bigint as due_count,
    min(delivery.created_at) as oldest_created_at,
    min(delivery.next_attempt_at) as oldest_next_attempt_at,
    min(delivery.lease_expires_at) as oldest_lease_expires_at,
    max(delivery.attempt_count)::integer as max_attempt_count
  from private.notification_deliveries as delivery
  group by delivery.organization_id, delivery.channel, delivery.status;
$$;


ALTER FUNCTION private.notification_delivery_metrics() OWNER TO postgres;

--
-- Name: notification_delivery_retry_delay(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notification_delivery_retry_delay(p_attempt_count integer) RETURNS interval
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select pg_catalog.make_interval(
    secs => least(
      3600,
      (30 * power(2::numeric, least(greatest(coalesce(p_attempt_count, 1) - 1, 0), 7)))::integer
    )
  );
$$;


ALTER FUNCTION private.notification_delivery_retry_delay(p_attempt_count integer) OWNER TO postgres;

--
-- Name: notification_dispatch_required(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notification_dispatch_required(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select lower(coalesce(p_value #>> '{}', 'false')) in ('true', '1', 'yes', 'on');
$$;


ALTER FUNCTION private.notification_dispatch_required(p_value jsonb) OWNER TO postgres;

--
-- Name: notification_safe_integer(text, integer, integer, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notification_safe_integer(p_value text, p_default integer, p_minimum integer, p_maximum integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
declare
  v_value numeric;
begin
  if nullif(btrim(coalesce(p_value, '')), '') is null then
    return least(greatest(p_default, p_minimum), p_maximum);
  end if;

  begin
    v_value := btrim(p_value)::numeric;
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      return least(greatest(p_default, p_minimum), p_maximum);
  end;

  if trunc(v_value) <> v_value then
    return least(greatest(p_default, p_minimum), p_maximum);
  end if;

  return least(greatest(v_value::integer, p_minimum), p_maximum);
exception
  when numeric_value_out_of_range then
    return least(greatest(p_default, p_minimum), p_maximum);
end
$$;


ALTER FUNCTION private.notification_safe_integer(p_value text, p_default integer, p_minimum integer, p_maximum integer) OWNER TO postgres;

--
-- Name: notification_safe_timestamptz(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notification_safe_timestamptz(p_value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
begin
  if nullif(btrim(coalesce(p_value, '')), '') is null then
    return null;
  end if;

  begin
    return btrim(p_value)::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      return null;
  end;
end
$$;


ALTER FUNCTION private.notification_safe_timestamptz(p_value text) OWNER TO postgres;

--
-- Name: notify_automation_attention(uuid, uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notify_automation_attention(p_organization_id uuid, p_lead_id uuid, p_user_id uuid, p_title text, p_content text, p_event_key text, p_dedupe_key text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_user_id is null or nullif(trim(coalesce(p_dedupe_key, '')), '') is null then
    return;
  end if;

  insert into public.notifications (
    organization_id, user_id, title, content, body, type, channel,
    lead_id, target_url, is_read, metadata
  ) values (
    p_organization_id,
    p_user_id,
    left(coalesce(nullif(trim(p_title), ''), 'Automacao requer atencao'), 200),
    left(coalesce(p_content, ''), 2000),
    left(coalesce(p_content, ''), 2000),
    'lead',
    'in_app',
    p_lead_id,
    '/crm/conversas?lead=' || p_lead_id::text,
    false,
    jsonb_build_object(
      'event_key', p_event_key,
      'dedupe_key', p_dedupe_key,
      'whatsapp_dispatch_required', false,
      'dispatch', jsonb_build_object(
        'whatsapp', jsonb_build_object('required', false, 'status', 'skipped'),
        'push', jsonb_build_object('required', true, 'status', 'pending')
      )
    ) || coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict do nothing;
end;
$$;


ALTER FUNCTION private.notify_automation_attention(p_organization_id uuid, p_lead_id uuid, p_user_id uuid, p_title text, p_content text, p_event_key text, p_dedupe_key text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: persist_asaas_billing_snapshot_after_exact_validation(uuid, text, text, text, text, text, numeric, date, date, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.persist_asaas_billing_snapshot_after_exact_validation(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_latest_payment_due_date date, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment_id text := nullif(btrim(coalesce(p_latest_payment_id, '')), '');
  v_payment_status text := upper(nullif(btrim(coalesce(p_latest_payment_status, '')), ''));
  v_customer_id text := nullif(btrim(coalesce(p_provider_customer_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_provider_subscription_id, '')), '');
  v_observed_at timestamptz := least(coalesce(p_observed_at, now()), now());
  v_existing public.asaas_payments%rowtype;
  v_org public.organizations%rowtype;
  v_existing_cursor timestamptz;
  v_result jsonb;
  v_confirmation jsonb;
  v_persisted integer := 0;
begin
  if v_payment_id is not null and char_length(v_payment_id) > 255 then
    raise exception 'invalid provider payment id'
      using errcode = '22023';
  end if;

  if v_payment_status in (
    'CONFIRMED',
    'RECEIVED',
    'RECEIVED_IN_CASH',
    'REFUNDED',
    'REFUND_REQUESTED',
    'REFUND_IN_PROGRESS',
    'PARTIALLY_REFUNDED',
    'RECEIVED_IN_CASH_UNDONE',
    'CHARGEBACK_REQUESTED',
    'CHARGEBACK_DISPUTE',
    'AWAITING_CHARGEBACK_REVERSAL'
  ) and v_payment_id is null then
    raise exception 'provider payment id is required for a paid or reversal snapshot'
      using errcode = '22023';
  end if;

  if v_payment_id is not null then
    perform private.lock_asaas_billing_resources(
      v_payment_id,
      v_subscription_id
    );

    select payment.*
      into v_existing
    from public.asaas_payments payment
    where payment.asaas_payment_id = v_payment_id
    for update;

    if found then
      if v_existing.organization_id is distinct from p_organization_id then
        raise exception 'provider payment belongs to a different organization'
          using errcode = '22023';
      end if;

      if v_existing.asaas_customer_id is not null
         and v_customer_id is not null
         and v_existing.asaas_customer_id <> v_customer_id then
        raise exception 'provider payment belongs to a different customer'
          using errcode = '22023';
      end if;

      if v_existing.asaas_subscription_id is not null
         and v_subscription_id is not null
         and v_existing.asaas_subscription_id <> v_subscription_id then
        raise exception 'provider payment belongs to a different subscription'
          using errcode = '22023';
      end if;

      v_existing_cursor := greatest(
        v_existing.last_webhook_event_at,
        v_existing.last_provider_observed_at
      );

      if v_existing_cursor is not null and v_existing_cursor > v_observed_at then
        return jsonb_build_object(
          'outcome', 'stale',
          'status', v_existing.status,
          'field', 'payment',
          'observed_at', v_observed_at
        );
      end if;
    end if;
  end if;

  -- Lock and validate the organization cursor before any confirmation can
  -- mutate an intent or plan. Together with the payment lock above this makes
  -- the later apply/confirm/persist sequence atomic and immune to a newer
  -- webhook for another payment.
  select organization.*
    into v_org
  from public.organizations organization
  where organization.id = p_organization_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;

  if nullif(btrim(v_org.asaas_customer_id), '') is not null
     and v_customer_id is not null
     and btrim(v_org.asaas_customer_id) <> v_customer_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'customer'
    );
  end if;

  if nullif(btrim(v_org.asaas_subscription_id), '') is not null
     and v_subscription_id is not null
     and btrim(v_org.asaas_subscription_id) <> v_subscription_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'subscription'
    );
  end if;

  if greatest(
       v_org.billing_last_reconciled_at,
       v_org.asaas_last_event_at
     ) > v_observed_at then
    return jsonb_build_object(
      'outcome', 'stale',
      'status', v_org.subscription_status,
      'field', 'organization',
      'observed_at', v_observed_at
    );
  end if;

  -- Keep the payment and organization cursors on the same observation before
  -- apply_asaas_billing_snapshot advances the organization cursor. The
  -- confirmation primitive compares both cursors and would otherwise reject
  -- an existing T0 payment while this atomic poll is applying T1. Updating
  -- only the provider cursor avoids firing status-driven payment triggers;
  -- every later failure still rolls this change back with the transaction.
  if v_existing.asaas_payment_id is not null then
    update public.asaas_payments
    set last_provider_observed_at = v_observed_at
    where asaas_payment_id = v_payment_id
      and organization_id = p_organization_id
      and (
        asaas_customer_id is null
        or v_customer_id is null
        or asaas_customer_id = v_customer_id
      )
      and (
        asaas_subscription_id is null
        or v_subscription_id is null
        or asaas_subscription_id = v_subscription_id
      )
      and v_observed_at >= coalesce(
        greatest(last_webhook_event_at, last_provider_observed_at),
        '-infinity'::timestamptz
      );

    get diagnostics v_persisted = row_count;
    if v_persisted <> 1 then
      raise exception 'provider payment snapshot lost its identity or ordering race'
        using errcode = '40001';
    end if;
  end if;

  v_result := private.apply_asaas_billing_snapshot(
    p_organization_id,
    v_customer_id,
    v_subscription_id,
    p_provider_subscription_status,
    v_payment_status,
    p_next_billing_date,
    v_observed_at,
    p_source
  );

  if coalesce(v_result ->> 'outcome', '') <> 'applied' then
    return v_result;
  end if;

  if v_payment_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH')
     and v_org.subscription_status not in (
       'suspended',
       'cancelled',
       'canceled'
     ) then
    v_confirmation := private.confirm_billing_checkout_intent(
      v_payment_id,
      v_subscription_id,
      v_payment_status,
      p_latest_payment_amount
    );

    if coalesce(v_confirmation ->> 'outcome', '') not in (
      'confirmed',
      'already_confirmed',
      'intent_not_found',
      'terminal_state'
    ) then
      raise exception 'billing intent confirmation failed: %', v_confirmation
        using errcode = '23514';
    end if;
  end if;

  if v_payment_id is null or v_payment_status is null then
    return v_result;
  end if;

  insert into public.asaas_payments (
    organization_id,
    asaas_payment_id,
    asaas_customer_id,
    asaas_subscription_id,
    status,
    value,
    due_date,
    raw_event,
    last_provider_observed_at,
    updated_at
  )
  values (
    p_organization_id,
    v_payment_id,
    v_customer_id,
    v_subscription_id,
    v_payment_status,
    p_latest_payment_amount,
    p_latest_payment_due_date,
    jsonb_build_object(
      'last_provider_snapshot', jsonb_build_object(
        'source', left(coalesce(nullif(btrim(p_source), ''), 'reconciliation'), 80),
        'status', v_payment_status,
        'due_date', p_latest_payment_due_date,
        'observed_at', v_observed_at
      )
    ),
    v_observed_at,
    now()
  )
  on conflict (asaas_payment_id) do update
  set
    asaas_customer_id = coalesce(
      public.asaas_payments.asaas_customer_id,
      excluded.asaas_customer_id
    ),
    asaas_subscription_id = coalesce(
      public.asaas_payments.asaas_subscription_id,
      excluded.asaas_subscription_id
    ),
    status = excluded.status,
    value = coalesce(excluded.value, public.asaas_payments.value),
    due_date = coalesce(excluded.due_date, public.asaas_payments.due_date),
    raw_event = coalesce(public.asaas_payments.raw_event, '{}'::jsonb)
      || excluded.raw_event,
    last_provider_observed_at = excluded.last_provider_observed_at,
    updated_at = now()
  where public.asaas_payments.organization_id = excluded.organization_id
    and (
      public.asaas_payments.asaas_customer_id is null
      or excluded.asaas_customer_id is null
      or public.asaas_payments.asaas_customer_id = excluded.asaas_customer_id
    )
    and (
      public.asaas_payments.asaas_subscription_id is null
      or excluded.asaas_subscription_id is null
      or public.asaas_payments.asaas_subscription_id = excluded.asaas_subscription_id
    )
    and excluded.last_provider_observed_at >= coalesce(
      greatest(
        public.asaas_payments.last_webhook_event_at,
        public.asaas_payments.last_provider_observed_at
      ),
      '-infinity'::timestamptz
    );

  get diagnostics v_persisted = row_count;
  if v_persisted <> 1 then
    raise exception 'provider payment snapshot lost its identity or ordering race'
      using errcode = '40001';
  end if;

  return v_result || jsonb_build_object(
    'payment_id', v_payment_id,
    'payment_status', v_payment_status,
    'payment_observed_at', v_observed_at
  );
end;
$$;


ALTER FUNCTION private.persist_asaas_billing_snapshot_after_exact_validation(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_latest_payment_due_date date, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION persist_asaas_billing_snapshot_after_exact_validation(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_latest_payment_due_date date, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.persist_asaas_billing_snapshot_after_exact_validation(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_id text, p_latest_payment_status text, p_latest_payment_amount numeric, p_latest_payment_due_date date, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) IS 'Atomically applies an Asaas snapshot and persists the exact payment state used to derive access.';


--
-- Name: pick_queue_runtime_ticket_candidate(uuid, uuid, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pick_queue_runtime_ticket_candidate(p_org uuid, p_queue uuid, p_strategy text, p_ticket bigint, p_now timestamp with time zone) RETURNS TABLE(member_id uuid, user_id uuid, team_id uuid, team_member_id uuid, user_name text, slot_position bigint, slot_count bigint, recipient_position bigint, recipient_count bigint, availability_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recipients as (
    select m.*,u.name as user_name,row_number() over(partition by m.member_id order by coalesce(tm.created_at,entry.created_at),m.user_id)::bigint as recipient_position,
      count(*) over(partition by m.member_id)::bigint as recipient_count
    from private.queue_runtime_members(p_org,p_queue,p_now) m join public.users u on u.id=m.user_id
    join public.round_robin_members entry on entry.id=m.member_id and entry.organization_id=p_org
    left join public.team_members tm on tm.id=m.team_member_id and tm.organization_id=p_org where m.is_available
  ), entries as (
    select r.member_id,min(r.position)::integer as position,
      max(case when p_strategy='weighted' then least(1000,greatest(1,r.weight)) else 1 end)::bigint as weight from recipients r group by r.member_id
  ), ticket as (
    select sum(weight)::bigint as total,(mod(p_ticket-1,sum(weight))+1)::bigint as slot,((p_ticket-1)/sum(weight))::bigint as cycles
    from entries having sum(weight)>0
  ), groups as (select weight,count(*)::bigint as count from entries group by weight), intervals as (
    select g.*,lag(weight,1,0::bigint) over(order by weight) as previous,
      coalesce(sum(weight*count) over(order by weight rows between unbounded preceding and 1 preceding),0)::bigint as saturated,
      sum(count) over(order by weight rows between current row and unbounded following)::bigint as active from groups g
  ), chosen as (
    select i.*,t.*, (previous+(slot-saturated-previous*active+active-1)/active)::bigint as round
    from intervals i cross join ticket t where slot>saturated+previous*active and slot<=saturated+weight*active
  ), ranked_entries as (
    select e.*,c.total,c.slot,c.cycles,c.round,c.slot-(c.saturated+(c.round-1)*c.active) as rank_in_round,
      row_number() over(order by e.position,e.member_id)::bigint as rank from entries e cross join chosen c where e.weight>=c.round
  ) select r.member_id,r.user_id,r.team_id,r.team_member_id,r.user_name,e.slot,e.total,r.recipient_position,r.recipient_count,
      case when r.team_member_id is null then 'no_team_schedule' else 'available' end
    from ranked_entries e join recipients r on r.member_id=e.member_id
      and r.recipient_position=mod(e.cycles*e.weight+e.round-1,r.recipient_count)+1 where e.rank=e.rank_in_round limit 1;
$$;


ALTER FUNCTION private.pick_queue_runtime_ticket_candidate(p_org uuid, p_queue uuid, p_strategy text, p_ticket bigint, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: pick_round_robin_rotation_candidate(uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pick_round_robin_rotation_candidate(p_organization_id uuid, p_lead_id uuid, p_round_robin_id uuid, p_current_user_id uuid, p_required_team_id uuid, p_now timestamp with time zone) RETURNS TABLE(member_id uuid, user_id uuid, team_id uuid, team_member_id uuid, user_name text, slot_position bigint, slot_count bigint, recipient_position bigint, recipient_count bigint, availability_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  q public.round_robins%rowtype;
  s private.round_robin_rotation_state%rowtype;
  zone text;
  local_now timestamp without time zone;
  cursor_position integer; cursor_member uuid; cursor_kind integer; cursor_created timestamptz; cursor_user uuid;
begin
  select queue.* into q from public.round_robins queue
  where queue.organization_id=p_organization_id and queue.id=p_round_robin_id
    and coalesce(queue.is_active,true) and queue.deleted_at is null
    and not (coalesce(queue.settings,'{}'::jsonb) ? 'operating_schedule');
  if not found then return; end if;
  insert into private.round_robin_rotation_state
    (organization_id,lead_id,round_robin_id,visited_user_ids,last_user_id)
  values (p_organization_id,p_lead_id,p_round_robin_id,
    case when p_current_user_id is null then '{}'::uuid[] else array[p_current_user_id] end,p_current_user_id)
  on conflict do nothing;
  select state.* into s from private.round_robin_rotation_state state
  where state.organization_id=p_organization_id and state.lead_id=p_lead_id
    and state.round_robin_id=p_round_robin_id for update;
  if p_current_user_id is not null and not (p_current_user_id=any(s.visited_user_ids)) then
    s.visited_user_ids:=array_append(s.visited_user_ids,p_current_user_id);
    update private.round_robin_rotation_state state set visited_user_ids=s.visited_user_ids
    where state.organization_id=p_organization_id and state.lead_id=p_lead_id
      and state.round_robin_id=p_round_robin_id;
  end if;
  zone:=coalesce(nullif(btrim(q.settings->>'timezone'),''),
    (select nullif(btrim(attention.timezone),'') from public.organization_attention_settings attention
      where attention.organization_id=p_organization_id),'America/Sao_Paulo');
  begin local_now:=coalesce(p_now,clock_timestamp()) at time zone zone;
  exception when invalid_parameter_value then
    local_now:=coalesce(p_now,clock_timestamp()) at time zone 'America/Sao_Paulo';
  end;
  cursor_user:=coalesce(p_current_user_id,s.last_user_id);
  -- The current recipient may be off shift. Recover their stable queue order
  -- without availability filtering; if removed, keep the last confirmed key.
  select c.position,c.member_id,c.candidate_kind,c.candidate_created_at
  into cursor_position,cursor_member,cursor_kind,cursor_created
  from private.round_robin_rotation_candidates(p_organization_id,p_round_robin_id,true,
    extract(dow from local_now)::integer,local_now::time,p_required_team_id) c
  where c.user_id=cursor_user;
  if not found then
    cursor_position:=s.last_position; cursor_member:=s.last_member_id;
    cursor_kind:=s.last_candidate_kind; cursor_created:=s.last_candidate_created_at;
    cursor_user:=s.last_user_id;
  end if;
  return query
  with candidates as materialized (
    select candidate.*,row_number() over(order by candidate.position,candidate.member_id,
      candidate.candidate_kind,candidate.candidate_created_at,candidate.user_id,
      candidate.team_member_id nulls last)::bigint as candidate_position,
      count(*) over()::bigint as candidate_count
    from private.round_robin_rotation_candidates(p_organization_id,p_round_robin_id,
      lower(coalesce(q.settings->>'ignore_availability','false')) in ('true','1','yes'),
      extract(dow from local_now)::integer,local_now::time,p_required_team_id) candidate
  )
  select c.member_id,c.user_id,c.team_id,c.team_member_id,c.user_name,
    c.candidate_position,c.candidate_count,1::bigint,1::bigint,'lead_rotation'::text
  from candidates c where c.user_id is distinct from p_current_user_id
    and (p_current_user_id is not null or c.user_id is distinct from s.last_user_id
      or c.candidate_count=1)
  order by (c.user_id=any(s.visited_user_ids)),
    case when row(c.position,c.member_id,c.candidate_kind,c.candidate_created_at,c.user_id)
      > row(cursor_position,cursor_member,cursor_kind,cursor_created,cursor_user) then 0 else 1 end,
    c.candidate_position limit 1;
end;
$$;


ALTER FUNCTION private.pick_round_robin_rotation_candidate(p_organization_id uuid, p_lead_id uuid, p_round_robin_id uuid, p_current_user_id uuid, p_required_team_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: pick_round_robin_ticket_candidate(uuid, uuid, text, boolean, integer, time without time zone, bigint); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pick_round_robin_ticket_candidate(p_organization_id uuid, p_round_robin_id uuid, p_strategy text, p_ignore_availability boolean, p_current_day integer, p_current_time time without time zone, p_ticket bigint) RETURNS TABLE(member_id uuid, user_id uuid, team_id uuid, team_member_id uuid, user_name text, slot_position bigint, slot_count bigint, recipient_position bigint, recipient_count bigint, availability_reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if private.queue_runtime_is_managed(p_organization_id,p_round_robin_id) then
    return query select * from private.pick_queue_runtime_ticket_candidate(p_organization_id,p_round_robin_id,p_strategy,p_ticket,clock_timestamp());
  else return query select * from private.pick_round_robin_ticket_candidate_before_queue_runtime(p_organization_id,p_round_robin_id,p_strategy,
    p_ignore_availability,p_current_day,p_current_time,p_ticket); end if;
end;
$$;


ALTER FUNCTION private.pick_round_robin_ticket_candidate(p_organization_id uuid, p_round_robin_id uuid, p_strategy text, p_ignore_availability boolean, p_current_day integer, p_current_time time without time zone, p_ticket bigint) OWNER TO postgres;

--
-- Name: pick_round_robin_ticket_candidate_before_queue_runtime(uuid, uuid, text, boolean, integer, time without time zone, bigint); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pick_round_robin_ticket_candidate_before_queue_runtime(p_organization_id uuid, p_round_robin_id uuid, p_strategy text, p_ignore_availability boolean, p_current_day integer, p_current_time time without time zone, p_ticket bigint) RETURNS TABLE(member_id uuid, user_id uuid, team_id uuid, team_member_id uuid, user_name text, slot_position bigint, slot_count bigint, recipient_position bigint, recipient_count bigint, availability_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with expanded_candidates as (
    -- Direct queue entries. When a team is explicitly attached to the direct
    -- user, membership in that exact team remains mandatory.
    select
      member.id as member_id,
      member.user_id,
      member.team_id,
      team_member.id as team_member_id,
      member.position,
      least(greatest(member.weight, 1), 1000) as weight,
      account.name as user_name,
      0 as candidate_kind,
      coalesce(
        team_member.created_at,
        member.created_at
      ) as candidate_created_at
    from public.round_robin_members as member
    join public.users as account
      on account.id = member.user_id
     and account.is_active is true
    join public.organization_members as organization_member
      on organization_member.organization_id = p_organization_id
     and organization_member.user_id = member.user_id
     and organization_member.is_active = true
     and organization_member.deleted_at is null
     and organization_member.membership_generation = member.membership_generation
    left join public.teams as team
      on team.id = member.team_id
     and team.organization_id = p_organization_id
     and coalesce(team.is_active, true) = true
    left join public.team_members as team_member
      on team_member.team_id = member.team_id
     and team_member.user_id = member.user_id
     and team_member.organization_id = p_organization_id
     and coalesce(team_member.is_active, true) = true
     and team_member.membership_generation = organization_member.membership_generation
    where member.round_robin_id = p_round_robin_id
      and member.organization_id = p_organization_id
      and member.user_id is not null
      and coalesce(member.is_active, true) = true
      and (
        member.team_id is null
        or (team.id is not null and team_member.id is not null)
      )

    union all

    -- Team entries expand only to choose the recipient inside the entry. The
    -- queue-entry weight is applied once after this expansion.
    select
      member.id as member_id,
      team_member.user_id,
      member.team_id,
      team_member.id as team_member_id,
      member.position,
      least(greatest(member.weight, 1), 1000) as weight,
      account.name as user_name,
      1 as candidate_kind,
      team_member.created_at as candidate_created_at
    from public.round_robin_members as member
    join public.teams as team
      on team.id = member.team_id
     and team.organization_id = p_organization_id
     and coalesce(team.is_active, true) = true
    join public.team_members as team_member
      on team_member.team_id = team.id
     and team_member.organization_id = p_organization_id
     and coalesce(team_member.is_active, true) = true
    join public.users as account
      on account.id = team_member.user_id
     and account.is_active is true
    join public.organization_members as organization_member
      on organization_member.organization_id = p_organization_id
     and organization_member.user_id = team_member.user_id
     and organization_member.is_active = true
     and organization_member.deleted_at is null
     and organization_member.membership_generation = team_member.membership_generation
    where member.round_robin_id = p_round_robin_id
      and member.organization_id = p_organization_id
      and member.user_id is null
      and member.team_id is not null
      and coalesce(member.is_active, true) = true
  ),
  availability_filtered_candidates as (
    select candidate.*
    from expanded_candidates as candidate
    where p_ignore_availability
       -- A participant added directly to the queue has no team_member_id and
       -- therefore has no team schedule to enforce, even if that user belongs
       -- to other teams in the organization.
       or candidate.team_member_id is null
       or not exists (
         -- A configured schedule remains configured even when every row is
         -- disabled. Omitting is_active here prevents a silent 24-hour
         -- fail-open for team-bound candidates.
         select 1
         from public.member_availability as availability_any
         where availability_any.organization_id = p_organization_id
           and availability_any.team_member_id = candidate.team_member_id
       )
       or exists (
         select 1
         from public.member_availability as availability
         where availability.organization_id = p_organization_id
           and availability.team_member_id = candidate.team_member_id
           and coalesce(availability.is_active, true) = true
           and (
             (
               availability.day_of_week = p_current_day
               and (
                 coalesce(availability.is_all_day, false) = true
                 or (
                   availability.start_time is not null
                   and availability.end_time is not null
                   and availability.start_time < availability.end_time
                   and p_current_time >= availability.start_time
                   and p_current_time <= availability.end_time
                 )
               )
             )
             or (
               coalesce(availability.is_all_day, false) = false
               and availability.start_time is not null
               and availability.end_time is not null
               and availability.start_time > availability.end_time
               and (
                 (
                   availability.day_of_week = p_current_day
                   and p_current_time >= availability.start_time
                 )
                 or (
                   availability.day_of_week = (p_current_day + 6) % 7
                   and p_current_time <= availability.end_time
                 )
               )
             )
           )
       )
  ),
  deduplicated_candidates as (
    select candidate.*
    from (
      select
        available.*,
        row_number() over (
          partition by available.user_id
          order by
            available.candidate_kind,
            available.position,
            available.candidate_created_at,
            available.member_id,
            available.team_member_id nulls last
        ) as duplicate_rank
      from availability_filtered_candidates as available
    ) as candidate
    where candidate.duplicate_rank = 1
  ),
  ranked_recipients as (
    select
      candidate.*,
      row_number() over (
        partition by candidate.member_id
        order by
          candidate.candidate_kind,
          candidate.candidate_created_at,
          candidate.user_id,
          candidate.team_member_id nulls last
      )::bigint as recipient_position,
      count(*) over (
        partition by candidate.member_id
      )::bigint as recipient_count
    from deduplicated_candidates as candidate
  ),
  entries as (
    select
      recipient.member_id,
      min(recipient.position)::integer as position,
      max(
        case
          when lower(coalesce(p_strategy, 'simple')) = 'weighted'
            then recipient.weight
          else 1
        end
      )::bigint as effective_weight
    from ranked_recipients as recipient
    group by recipient.member_id
  ),
  ticket_state as (
    select
      total.total_weight as slot_count,
      (
        pg_catalog.mod(p_ticket - 1, total.total_weight) + 1
      )::bigint as slot_position,
      ((p_ticket - 1) / total.total_weight)::bigint as completed_cycles
    from (
      select sum(entry.effective_weight)::bigint as total_weight
      from entries as entry
    ) as total
    where total.total_weight > 0
  ),
  weight_groups as (
    select
      entry.effective_weight,
      count(*)::bigint as entry_count
    from entries as entry
    group by entry.effective_weight
  ),
  interval_seed as (
    select
      weight_group.*,
      lag(
        weight_group.effective_weight,
        1,
        0::bigint
      ) over (
        order by weight_group.effective_weight
      ) as previous_round,
      coalesce(
        sum(
          weight_group.effective_weight * weight_group.entry_count
        ) over (
          order by weight_group.effective_weight
          rows between unbounded preceding and 1 preceding
        ),
        0
      )::bigint as saturated_slots,
      sum(weight_group.entry_count) over (
        order by weight_group.effective_weight
        rows between current row and unbounded following
      )::bigint as active_entries
    from weight_groups as weight_group
  ),
  intervals as (
    select
      seed.*,
      ticket.*,
      (
        seed.saturated_slots
        + seed.previous_round * seed.active_entries
      )::bigint as slots_before,
      (
        seed.saturated_slots
        + seed.effective_weight * seed.active_entries
      )::bigint as slots_through
    from interval_seed as seed
    cross join ticket_state as ticket
  ),
  chosen_interval as (
    select
      interval.*,
      (
        interval.previous_round
        + (
          interval.slot_position
          - interval.slots_before
          + interval.active_entries
          - 1
        ) / interval.active_entries
      )::bigint as selected_round
    from intervals as interval
    where interval.slot_position > interval.slots_before
      and interval.slot_position <= interval.slots_through
  ),
  round_state as (
    select
      interval.*,
      (
        interval.slot_position
        - (
          interval.saturated_slots
          + (
            interval.selected_round - 1
          ) * interval.active_entries
        )
      )::bigint as rank_in_round
    from chosen_interval as interval
  ),
  round_entries as (
    select
      entry.*,
      state.slot_position,
      state.slot_count,
      state.completed_cycles,
      state.selected_round,
      state.rank_in_round,
      row_number() over (
        order by entry.position, entry.member_id
      )::bigint as entry_rank
    from entries as entry
    cross join round_state as state
    where entry.effective_weight >= state.selected_round
  ),
  selected_entry as (
    select
      entry.*,
      (
        entry.completed_cycles * entry.effective_weight
        + entry.selected_round
        - 1
      )::bigint as prior_entry_occurrences
    from round_entries as entry
    where entry.entry_rank = entry.rank_in_round
  )
  select
    recipient.member_id,
    recipient.user_id,
    recipient.team_id,
    recipient.team_member_id,
    recipient.user_name,
    entry.slot_position,
    entry.slot_count,
    recipient.recipient_position,
    recipient.recipient_count,
    case
      when p_ignore_availability
        then 'queue_ignores_availability'
      when recipient.team_member_id is null
        then 'no_team_schedule'
      else 'available'
    end as availability_reason
  from selected_entry as entry
  join ranked_recipients as recipient
    on recipient.member_id = entry.member_id
   and recipient.recipient_position =
     pg_catalog.mod(
       entry.prior_entry_occurrences,
       recipient.recipient_count
     ) + 1
  limit 1
$$;


ALTER FUNCTION private.pick_round_robin_ticket_candidate_before_queue_runtime(p_organization_id uuid, p_round_robin_id uuid, p_strategy text, p_ignore_availability boolean, p_current_day integer, p_current_time time without time zone, p_ticket bigint) OWNER TO postgres;

--
-- Name: prepare_queue_manual_transfer(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.prepare_queue_manual_transfer(p_org uuid, p_lead uuid, p_actor uuid, p_target_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare queue_id uuid;
begin
  select coalesce(r.round_robin_id,l.origin_round_robin_id) into queue_id from public.leads l
    left join private.queue_lead_runtime r on r.organization_id=l.organization_id and r.lead_id=l.id
    where l.organization_id=p_org and l.id=p_lead;
  if private.queue_runtime_is_managed(p_org,queue_id) then
    perform 1 from public.round_robins where organization_id=p_org and id=queue_id for share skip locked;
    if not found then raise exception using errcode='55P03',message='queue_configuration_busy'; end if;
  end if;
  return private.prepare_queue_manual_transfer_before_concurrency_guard(p_org,p_lead,p_actor,p_target_user);
end;
$$;


ALTER FUNCTION private.prepare_queue_manual_transfer(p_org uuid, p_lead uuid, p_actor uuid, p_target_user uuid) OWNER TO postgres;

--
-- Name: prepare_queue_manual_transfer_before_concurrency_guard(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.prepare_queue_manual_transfer_before_concurrency_guard(p_org uuid, p_lead uuid, p_actor uuid, p_target_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r private.queue_lead_runtime%rowtype; qid uuid;
begin
  select coalesce((select rr.round_robin_id from private.queue_lead_runtime rr where rr.organization_id=p_org and rr.lead_id=l.id),l.origin_round_robin_id)
    into qid from public.leads l where l.organization_id=p_org and l.id=p_lead;
  if qid is null or not private.queue_runtime_is_managed(p_org,qid) then return true; end if;
  if p_target_user is null then return false; end if;
  if not private.queue_runtime_actor_can_claim(p_org,p_actor) then raise exception using errcode='42501',message='queue_manual_actor_forbidden'; end if;
  perform 1 from public.round_robins where organization_id=p_org and id=qid for share skip locked;
  if not found then raise exception using errcode='55P03',message='queue_configuration_busy'; end if;
  select * into r from private.queue_lead_runtime where organization_id=p_org and lead_id=p_lead for update;
  if r.state in ('pool_waiting','pool_ready','limit_exhausted') then return false; end if;
  if r.lead_id is null then perform private.queue_runtime_enroll(p_org,p_lead,qid,clock_timestamp()); end if;
  update private.queue_lead_runtime set state='manual_protected',reason='manual_transfer',protected_actor_id=p_actor,
    revision=revision+1,next_action_at=null,retry_count=0,quarantined_at=null,last_error_code=null,last_distribution_event_id=null,updated_at=clock_timestamp() where organization_id=p_org and lead_id=p_lead;
  if r.quarantined_at is not null then
    insert into private.queue_runtime_events(organization_id,lead_id,round_robin_id,episode_id,round_number,event_type,actor_id,metadata)
      values(p_org,p_lead,r.round_robin_id,r.episode_id,r.round_number,'manual_recovery',p_actor,jsonb_build_object('prior_error',r.last_error_code,'retry_count',r.retry_count)); end if;
  insert into private.queue_runtime_commands values(txid_current(),p_org,p_lead,'manual',p_actor)
    on conflict(transaction_id,organization_id,lead_id) do update set mode='manual',actor_id=p_actor;
  return true;
end;
$$;


ALTER FUNCTION private.prepare_queue_manual_transfer_before_concurrency_guard(p_org uuid, p_lead uuid, p_actor uuid, p_target_user uuid) OWNER TO postgres;

--
-- Name: prepare_whatsapp_confirmed_phone_route_retirement(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.prepare_whatsapp_confirmed_phone_route_retirement(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_expected_lead_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.whatsapp_sessions%rowtype;
  v_conversation public.whatsapp_conversations%rowtype;
  v_canceled_ids uuid[] := '{}'::uuid[];
  v_now timestamptz := clock_timestamp();
begin
  if p_organization_id is null or p_session_id is null
     or p_conversation_id is null or p_expected_lead_id is null
     or p_actor_user_id is null then
    raise exception using errcode='22023', message='whatsapp_phone_retirement_arguments_invalid';
  end if;
  if auth.uid() is not null and auth.uid() is distinct from p_actor_user_id then
    raise exception using errcode='42501', message='whatsapp_phone_retirement_actor_denied';
  end if;

  select session.* into v_session from public.whatsapp_sessions session
  where session.organization_id=p_organization_id and session.id=p_session_id
    and session.provider='evolution_go' and coalesce(session.is_active,true)
    and session.status='connected'
  for share;
  if not found then
    raise exception using errcode='40001', message='whatsapp_phone_retirement_session_changed';
  end if;
  select conversation.* into v_conversation from public.whatsapp_conversations conversation
  where conversation.organization_id=p_organization_id and conversation.id=p_conversation_id
    and conversation.session_id=p_session_id and conversation.lead_id=p_expected_lead_id
    and conversation.deleted_at is null and conversation.retired_at is null
    and not conversation.is_group
  for update;
  if not found then
    raise exception using errcode='40001', message='whatsapp_phone_retirement_binding_changed';
  end if;

  perform lead.id from public.leads lead
  where lead.organization_id=p_organization_id and lead.id=p_expected_lead_id
  for share;
  if not found then
    raise exception using errcode='40001', message='whatsapp_phone_retirement_lead_changed';
  end if;
  perform actor.id from public.users actor
  join public.organization_members member on member.user_id=actor.id and member.organization_id=actor.organization_id
  where actor.id=p_actor_user_id and actor.organization_id=p_organization_id
    and coalesce(actor.is_active,false) and member.is_active and member.deleted_at is null
  for share of actor,member;
  if not found or not private.whatsapp_actor_can_read_lead(p_organization_id,p_expected_lead_id,p_actor_user_id)
     or not (
       v_session.owner_user_id=p_actor_user_id
       or exists (
         select 1 from public.whatsapp_session_access access
         join public.users owner_user on owner_user.id=v_session.owner_user_id
           and owner_user.organization_id=p_organization_id and coalesce(owner_user.is_active,false)
         join public.organization_members owner_member on owner_member.user_id=owner_user.id
           and owner_member.organization_id=p_organization_id and owner_member.is_active and owner_member.deleted_at is null
         join public.leads lead on lead.id=p_expected_lead_id and lead.organization_id=p_organization_id
           and lead.assigned_user_id=p_actor_user_id
         where access.organization_id=p_organization_id and access.session_id=p_session_id
           and access.user_id=p_actor_user_id and access.granted_by=v_session.owner_user_id
           and access.can_view and access.can_read and access.can_send and access.only_leads_access
           and access.access_mode='assigned_leads_only' and access.grant_scope='organization'
           and access.grant_team_id is null and owner_member.role in ('owner','admin')
       )
     ) then
    raise exception using errcode='42501', message='whatsapp_phone_retirement_actor_denied';
  end if;

  -- Preserve the core binding-switch lock and in-flight fences across all
  -- seven durable work families. One conversation is the outer writer lock.
  perform queued.id from public.whatsapp_outbox queued
  where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id
    and queued.status in ('pending','retry','processing','failed') for update;
  perform queued.id from public.outbox_messages queued
  where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id
    and queued.status in ('pending','processing') for update;
  perform job.id from public.ai_jobs job
  where job.organization_id=p_organization_id and job.conversation_id=p_conversation_id
    and job.status in ('pending','processing') for update;
  perform job.id from public.jobs job
  where job.organization_id=p_organization_id and job.job_type='whatsapp_ai_autoreply'
    and job.payload->>'conversationId'=p_conversation_id::text and job.status in ('queued','processing') for update;
  perform queued.id from public.ai_outbox_messages queued
  where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id
    and queued.status in ('draft','pending_approval','approved','sending') for update;
  perform queued.id from public.automation_event_outbox queued
  where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id
    and queued.status in ('pending','failed','processing') for update;
  perform execution.id from public.automation_executions execution
  where execution.organization_id=p_organization_id and execution.conversation_id=p_conversation_id
    and execution.status in ('queued','waiting','running') for update;
  perform step.id from public.automation_execution_steps step
  join public.automation_executions execution on execution.id=step.execution_id and execution.organization_id=step.organization_id
  where execution.organization_id=p_organization_id and execution.conversation_id=p_conversation_id
    and step.status in ('running','waiting') for update of step;
  perform dispatch.id from public.automation_effect_dispatches dispatch
  join public.automation_executions execution on execution.id=dispatch.execution_id and execution.organization_id=dispatch.organization_id
  where execution.organization_id=p_organization_id and execution.conversation_id=p_conversation_id
    and dispatch.status='sending' for update of dispatch;

  if exists (select 1 from public.whatsapp_outbox queued
       where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id
       and (queued.status='processing' or (queued.status in ('pending','retry') and queued.last_error in
         ('provider_accepted_finalization_pending','provider_delivery_started','provider_delivery_outcome_unknown'))))
     or exists (select 1 from public.outbox_messages queued where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id and queued.status='processing')
     or exists (select 1 from public.ai_jobs job where job.organization_id=p_organization_id and job.conversation_id=p_conversation_id and job.status='processing')
     or exists (select 1 from public.jobs job where job.organization_id=p_organization_id and job.job_type='whatsapp_ai_autoreply' and job.payload->>'conversationId'=p_conversation_id::text and job.status='processing')
     or exists (select 1 from public.ai_outbox_messages queued where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id and queued.status='sending')
     or exists (select 1 from public.automation_event_outbox queued where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id and queued.status='processing')
     or exists (select 1 from public.automation_executions execution where execution.organization_id=p_organization_id and execution.conversation_id=p_conversation_id and execution.status='running')
     or exists (select 1 from public.automation_effect_dispatches dispatch
       join public.automation_executions execution on execution.id=dispatch.execution_id and execution.organization_id=dispatch.organization_id
       where execution.organization_id=p_organization_id and execution.conversation_id=p_conversation_id and dispatch.status='sending') then
    raise exception using errcode='55000', message='whatsapp_phone_retirement_delivery_in_flight';
  end if;

  with canceled as (
    update public.whatsapp_outbox queued
    set status='failed',failed_at=coalesce(failed_at,v_now),locked_at=null,locked_by=null,
        last_error='conversation_phone_changed',updated_at=v_now
    where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id
      and queued.status in ('pending','retry') and coalesce(queued.last_error,'') not in
        ('provider_accepted_finalization_pending','provider_delivery_started','provider_delivery_outcome_unknown')
    returning queued.id
  ) select coalesce(array_agg(id),'{}'::uuid[]) into v_canceled_ids from canceled;
  update public.outbox_messages queued set status='failed',processed_at=coalesce(processed_at,v_now),error_message='conversation_phone_changed'
  where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id and queued.status='pending';
  update public.ai_jobs job set status='cancelled',error_message='conversation_phone_changed',completed_at=coalesce(completed_at,v_now)
  where job.organization_id=p_organization_id and job.conversation_id=p_conversation_id and job.status='pending';
  update public.jobs job set status='cancelled',locked_at=null,last_error='conversation_phone_changed',updated_at=v_now
  where job.organization_id=p_organization_id and job.job_type='whatsapp_ai_autoreply'
    and job.payload->>'conversationId'=p_conversation_id::text and job.status='queued';
  update public.ai_outbox_messages queued set status='cancelled',failure_reason='conversation_phone_changed',updated_at=v_now
  where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id and queued.status in ('draft','pending_approval','approved');
  update public.automation_event_outbox queued set status='dead_letter',dead_lettered_at=coalesce(dead_lettered_at,v_now),
    locked_at=null,locked_by=null,last_error='conversation_phone_changed',updated_at=v_now
  where queued.organization_id=p_organization_id and queued.conversation_id=p_conversation_id and queued.status in ('pending','failed');
  update public.automation_executions execution set status='cancelled',
    cancellation_requested_at=coalesce(cancellation_requested_at,v_now),completed_at=coalesce(completed_at,v_now),
    error_message='conversation_phone_changed',locked_at=null,locked_by=null,updated_at=v_now
  where execution.organization_id=p_organization_id and execution.conversation_id=p_conversation_id and execution.status in ('queued','waiting');
  update public.automation_execution_steps step set status='cancelled',
    completed_at=coalesce(step.completed_at,v_now),error_message='conversation_phone_changed'
  from public.automation_executions execution
  where execution.id=step.execution_id and execution.organization_id=step.organization_id
    and execution.organization_id=p_organization_id and execution.conversation_id=p_conversation_id
    and execution.status='cancelled' and execution.error_message='conversation_phone_changed'
    and step.status in ('running','waiting');
  delete from public.conversation_ai_state state
  where state.organization_id=p_organization_id and state.conversation_id=p_conversation_id;
  delete from public.ai_agent_conversations state where state.conversation_id=p_conversation_id;
  delete from public.ai_conversation_states state
  where state.organization_id=p_organization_id and state.conversation_id=p_conversation_id;
  delete from public.chatbot_conversation_state state
  where state.organization_id=p_organization_id and state.conversation_id=p_conversation_id::text;

  return jsonb_build_object('prepared',true,'conversation_id',p_conversation_id,
    'canceled_outbox_ids',v_canceled_ids);
end;
$$;


ALTER FUNCTION private.prepare_whatsapp_confirmed_phone_route_retirement(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_expected_lead_id uuid, p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION prepare_whatsapp_confirmed_phone_route_retirement(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_expected_lead_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.prepare_whatsapp_confirmed_phone_route_retirement(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_expected_lead_id uuid, p_actor_user_id uuid) IS 'Backend-only confirmed phone change preparation. Guards/cancels old durable work; caller projects failures, closes binding and retires/opens routes in the same transaction. Does not send, replay or rewrite history.';


--
-- Name: prepare_whatsapp_inbound_attendant_push(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.prepare_whatsapp_inbound_attendant_push(p_notification_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_notification public.notifications%rowtype; v_message public.whatsapp_messages%rowtype;
  v_recipient record; v_session public.whatsapp_sessions%rowtype;
  v_session_owner_user_id uuid; v_assigned_user_id uuid;
begin
  select * into v_notification from public.notifications where id = p_notification_id
    and metadata->>'event_key' = 'whatsapp_inbound_attendant';
  if not found then return 'revoked'; end if;
  select * into v_message from public.whatsapp_messages
    where organization_id = v_notification.organization_id
      and id = nullif(v_notification.metadata->>'whatsapp_message_id', '')::uuid;
  if not found then return 'revoked'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'whatsapp-inbound-push:' || v_message.organization_id::text || ':' || v_message.id::text, 0));
  select owner_user_id into v_session_owner_user_id from public.whatsapp_sessions
    where id=v_message.session_id and organization_id=v_message.organization_id;
  select assigned_user_id into v_assigned_user_id from public.leads
    where id=v_message.lead_id and organization_id=v_message.organization_id;
  perform 1 from public.users where id in(v_session_owner_user_id,v_assigned_user_id) order by id for share;
  perform 1 from public.organization_members where organization_id=v_message.organization_id
    and user_id in(v_session_owner_user_id,v_assigned_user_id) order by user_id for share;
  select * into v_session from public.whatsapp_sessions
    where id=v_message.session_id and organization_id=v_message.organization_id for share;
  perform 1 from public.whatsapp_conversations where id=v_message.conversation_id
    and organization_id=v_message.organization_id for share;
  perform 1 from public.leads where id=v_message.lead_id and organization_id=v_message.organization_id for share;
  if v_session.owner_user_id is distinct from v_session_owner_user_id
    or (select assigned_user_id from public.leads where id=v_message.lead_id and organization_id=v_message.organization_id)
      is distinct from v_assigned_user_id then
    raise exception using errcode='40001',message='whatsapp_push_actor_changed_during_lock';
  end if;
  perform 1 from public.whatsapp_conversation_lead_bindings where conversation_id = v_message.conversation_id
    and organization_id = v_message.organization_id and active_to is null for share;
  select * into v_recipient from private.whatsapp_inbound_push_recipient(v_message.organization_id, v_message.id);
  if found then
    perform 1 from public.whatsapp_attendance_entries where id = v_recipient.attendance_entry_id for share;
    if v_recipient.grant_id is not null then
      perform 1 from public.whatsapp_session_access where id = v_recipient.grant_id for share;
    end if;
    -- Recheck after locking the grant: an UPDATE may have committed while we waited.
    select * into v_recipient from private.whatsapp_inbound_push_recipient(v_message.organization_id, v_message.id);
    if found and v_recipient.user_id = v_notification.user_id
       and v_recipient.attendance_entry_id::text = v_notification.metadata->>'attendance_entry_id'
       and v_recipient.binding_id::text = v_notification.metadata->>'binding_id'
       and coalesce(v_recipient.grant_id::text, '') = coalesce(v_notification.metadata->>'grant_id', '') then
      return 'authorized';
    end if;
  end if;

  -- A provider-started attempt is ambiguous even after worker crash. Never
  -- redirect it, or a different device could have already shown the old alert.
  if exists (select 1 from public.notifications notification
    where notification.organization_id = v_message.organization_id
      and notification.metadata->>'event_key' = 'whatsapp_inbound_attendant'
      and notification.metadata->>'whatsapp_message_id' = v_message.id::text
      and notification.metadata->>'whatsapp_inbound_provider_started' = 'true')
    or exists (select 1 from private.notification_deliveries delivery
    join public.notifications notification on notification.id = delivery.notification_id
    where notification.organization_id = v_message.organization_id
      and notification.metadata->>'event_key' = 'whatsapp_inbound_attendant'
      and notification.metadata->>'whatsapp_message_id' = v_message.id::text
      and delivery.channel = 'push'
      and (delivery.attempt_count > 0 or delivery.status in ('sending', 'accepted', 'delivered'))) then
    return 'revoked';
  end if;
  if not exists (select 1 from private.notification_deliveries delivery
    join public.notifications notification on notification.id=delivery.notification_id
    where notification.organization_id=v_message.organization_id
      and notification.metadata->>'event_key'='whatsapp_inbound_attendant'
      and notification.metadata->>'whatsapp_message_id'=v_message.id::text and delivery.channel='push'
      and delivery.status in ('queued','leased','retry_wait','blocked_dependency')
      and delivery.attempt_count=0 and delivery.expires_at>now())
    and not exists(select 1 from private.whatsapp_inbound_push_waiting waiting
      where waiting.notification_id=v_notification.id and waiting.organization_id=v_message.organization_id and waiting.expires_at>now()) then
    return 'revoked';
  end if;
  update private.notification_deliveries set status = 'cancelled', terminal_at = now(),
    next_attempt_at = null, lease_token = null, leased_by = null, lease_expires_at = null,
    dependency_key = null, blocked_at = null, last_error_code = 'whatsapp_attendant_changed',
    last_error_message = 'Current attendance no longer authorizes the original recipient.', updated_at = now()
  where notification_id = v_notification.id and channel = 'push'
    and status in ('queued', 'leased', 'retry_wait', 'blocked_dependency');
  if v_recipient.user_id is not null and v_recipient.user_id <> v_notification.user_id then
    perform private.create_whatsapp_inbound_attendant_notification(v_message.organization_id, v_message.id,
      v_recipient.user_id, v_recipient.attendance_entry_id, v_recipient.binding_id, v_recipient.grant_id,
      coalesce(nullif(v_notification.metadata->>'origin_notification_id', '')::uuid, v_notification.id));
    return 'redirected';
  end if;
  return 'cancelled';
end;
$$;


ALTER FUNCTION private.prepare_whatsapp_inbound_attendant_push(p_notification_id uuid) OWNER TO postgres;

--
-- Name: preserve_managed_whatsapp_lead_intake(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.preserve_managed_whatsapp_lead_intake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old_metadata jsonb := coalesce(old.metadata, '{}'::jsonb);
  v_new_metadata jsonb := coalesce(new.metadata, '{}'::jsonb);
  v_old_marker boolean;
  v_new_marker boolean;
  v_key text;
begin
  v_old_marker := lower(btrim(coalesce(
    v_old_metadata->>'managed_whatsapp_message_distribution',
    'false'
  ))) in ('true', '1', 'yes');
  v_new_marker := lower(btrim(coalesce(
    v_new_metadata->>'managed_whatsapp_message_distribution',
    'false'
  ))) in ('true', '1', 'yes');

  if not v_old_marker and not v_new_marker then
    return new;
  end if;

  if jsonb_typeof(v_old_metadata) <> 'object'
     or jsonb_typeof(v_new_metadata) <> 'object' then
    raise exception using
      errcode = '23514',
      message = 'managed_whatsapp_metadata_must_be_object';
  end if;

  if new.organization_id is distinct from old.organization_id then
    raise exception using
      errcode = '23514',
      message = 'managed_whatsapp_organization_immutable';
  end if;

  foreach v_key in array array[
    'managed_whatsapp_message_distribution',
    'managed_whatsapp_initial_provider_event_id',
    'matched_rule_id',
    'whatsapp_session_id',
    'target_round_robin_id',
    'target_team_id'
  ]
  loop
    v_new_metadata := v_new_metadata - v_key;
    if v_old_metadata ? v_key then
      v_new_metadata := v_new_metadata
        || jsonb_build_object(v_key, v_old_metadata->v_key);
    end if;
  end loop;

  new.metadata := v_new_metadata;
  new.source := old.source;
  new.source_session_id := old.source_session_id;
  new.initial_message := old.initial_message;
  return new;
end;
$$;


ALTER FUNCTION private.preserve_managed_whatsapp_lead_intake() OWNER TO postgres;

--
-- Name: preserve_whatsapp_webhook_routing_snapshot(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.preserve_whatsapp_webhook_routing_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.payload #> '{__vimob_ingress,routing_snapshot}'
     is distinct from old.payload #> '{__vimob_ingress,routing_snapshot}' then
    if new.payload = '{"__vimob_retention":"expired_unlinked_v1"}'::jsonb
       and new.status in ('dead', 'processed')
       and exists (
         select 1 from public.whatsapp_conversations as conversation
         where conversation.organization_id = old.organization_id
           and conversation.session_id = old.session_id
           and conversation.unlinked_retention_v1
           and conversation.lead_id is null
           and conversation.created_at <= pg_catalog.clock_timestamp() - interval '7 days'
           and conversation.unlinked_retention_scrubbed_at is null
           and not private.whatsapp_conversation_has_protected_history(conversation.id)
           and private.whatsapp_unlinked_inbox_batch_exclusive(old.id, conversation.id)
       ) then
      return new;
    end if;
    if exists (
      select 1 from public.whatsapp_conversations as conversation
      cross join lateral private.whatsapp_unlinked_mixed_inbox_plan(
        old.id, conversation.id
      ) as plan(result)
      where conversation.organization_id = old.organization_id
        and conversation.session_id = old.session_id
        and plan.result->'payload' = new.payload
        and new.status = case when plan.result->>'terminal' = 'true'
          and old.status in ('pending', 'retry') then 'dead'
          else old.status end
    ) then
      return new;
    end if;
    raise exception using errcode = '23514',
      message = 'whatsapp_webhook_routing_snapshot_immutable';
  end if;
  return new;
end;
$$;


