-- Name: prevent_property_publication_version_update(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.prevent_property_publication_version_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.created_by is not null
     and new.created_by is null
     and (to_jsonb(new) - 'created_by') = (to_jsonb(old) - 'created_by') then
    return new;
  end if;

  raise exception using
    errcode = '23514',
    message = 'property_publication_version_immutable';
end;
$$;


