--
-- Name: preview_round_robin_redistribution_candidate(uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.preview_round_robin_redistribution_candidate(p_organization_id uuid, p_lead_id uuid, p_round_robin_id uuid, p_excluded_user_id uuid DEFAULT NULL::uuid, p_required_team_id uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS TABLE(member_id uuid, user_id uuid, team_id uuid, team_member_id uuid, user_name text, slot_position bigint, slot_count bigint, recipient_position bigint, recipient_count bigint, availability_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare current_owner uuid; baseline_owner uuid;
begin
  select lead.assigned_user_id into current_owner from public.leads lead
  where lead.organization_id=p_organization_id and lead.id=p_lead_id for no key update;
  if not found then return; end if;
  perform 1 from public.round_robins queue where queue.organization_id=p_organization_id
    and queue.id=p_round_robin_id and coalesce(queue.is_active,true) and queue.deleted_at is null
    and not (coalesce(queue.settings,'{}'::jsonb) ? 'operating_schedule');
  if not found then return; end if;
  if p_excluded_user_id is not null and p_excluded_user_id is distinct from current_owner then
    raise exception using errcode='40001',message='round_robin_rotation_stale_owner';
  end if;
  if current_owner is null then
    -- Resume an unowned old lead from its last confirmed assignment only.
    select log.assigned_user_id into baseline_owner from public.round_robin_logs log
    where log.organization_id=p_organization_id and log.lead_id=p_lead_id
      and log.round_robin_id=p_round_robin_id and log.assigned_user_id is not null
      and private.is_round_robin_rotation_assignment_reason(log.reason)
    order by log.created_at desc,log.id desc limit 1;
    if baseline_owner is not null then
      insert into private.round_robin_rotation_state
        (organization_id,lead_id,round_robin_id,visited_user_ids,last_user_id)
      values (p_organization_id,p_lead_id,p_round_robin_id,array[baseline_owner],baseline_owner)
      on conflict do nothing;
    end if;
  end if;
  return query select candidate.* from private.pick_round_robin_rotation_candidate(
    p_organization_id,p_lead_id,p_round_robin_id,current_owner,p_required_team_id,p_now) candidate;
end;
$$;


ALTER FUNCTION private.preview_round_robin_redistribution_candidate(p_organization_id uuid, p_lead_id uuid, p_round_robin_id uuid, p_excluded_user_id uuid, p_required_team_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: process_queue_runtime_batch(integer, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.process_queue_runtime_batch(p_limit integer DEFAULT 50, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  item record; candidate private.queue_lead_runtime%rowtype; adoption_job public.lead_redistribution_jobs%rowtype;
  result jsonb; mode text; adoption_at timestamptz;
  processed integer:=0; failed integer:=0; busy integer:=0; adopted integer:=0;
  scanned integer; completed integer; scan_limit integer; batch_limit integer; pass integer;
  start_sort timestamptz; start_id uuid; start_pool timestamptz;
  last_sort timestamptz; last_key_id uuid; last_pool timestamptz;
  changed jsonb:='[]'::jsonb; change jsonb; failure_code text; retry integer;
begin
  p_now:=coalesce(p_now,clock_timestamp());
  batch_limit:=least(greatest(coalesce(p_limit,50),1),500);
  scan_limit:=least(greatest(batch_limit*10,200),5000);
  if not pg_try_advisory_xact_lock(hashtextextended('lead_queue_runtime_worker',0)) then
    return jsonb_build_object('processed',0,'failed',0,'busy',0,'adopted',0,'changed',changed,'workerBusy',true);
  end if;

  select c.sort_at,c.last_id into start_sort,start_id from private.queue_runtime_worker_cursors c where c.lane='adoption' for update;
  last_sort:=start_sort;last_key_id:=start_id;scanned:=0;completed:=0;
  for pass in 0..1 loop
    exit when scanned>=scan_limit or completed>=batch_limit or (pass=1 and start_id is null);
    for item in select j.organization_id,j.lead_id,j.round_robin_id,j.enrolled_at,j.attempt_count,j.id
      from public.lead_redistribution_jobs j
      join public.round_robins q on q.organization_id=j.organization_id and q.id=j.round_robin_id
        and coalesce(q.is_active,true) and q.deleted_at is null and q.settings ? 'operating_schedule'
      where j.status in ('pending','warning_sent') and coalesce(j.redistribution_retry_at,'-infinity'::timestamptz)<=p_now
        and j.metadata->>'attention_instance_id' is null
        and not exists(select 1 from private.queue_lead_runtime existing where existing.organization_id=j.organization_id and existing.lead_id=j.lead_id)
        and case when pass=0 then start_id is null or row(j.enrolled_at,j.id)>row(start_sort,start_id)
          else row(j.enrolled_at,j.id)<=row(start_sort,start_id) end
      order by j.enrolled_at,j.id limit scan_limit-scanned
    loop
      scanned:=scanned+1;last_sort:=item.enrolled_at;last_key_id:=item.id;
      -- Bound expensive provenance checks by the raw page size too. Filtering
      -- by this helper before LIMIT could scan an unbounded invalid prefix.
      mode:=private.queue_runtime_legacy_adoption_kind(item.organization_id,item.lead_id,item.round_robin_id,item.id);
      if mode is null then continue;end if;
      -- Parent order is always queue -> lead -> job -> runtime. Busy candidates
      -- advance only the traversal cursor, never clocks, attempts or visits.
      perform 1 from public.round_robins q where q.organization_id=item.organization_id and q.id=item.round_robin_id for share skip locked;
      if not found then busy:=busy+1;continue;end if;
      perform 1 from public.leads l where l.organization_id=item.organization_id and l.id=item.lead_id for no key update skip locked;
      if not found then busy:=busy+1;continue;end if;
      select j.* into adoption_job from public.lead_redistribution_jobs j
        where j.organization_id=item.organization_id and j.lead_id=item.lead_id and j.round_robin_id=item.round_robin_id and j.id=item.id
          and j.status in ('pending','warning_sent') and coalesce(j.redistribution_retry_at,'-infinity'::timestamptz)<=p_now for update skip locked;
      if not found then busy:=busy+1;continue;end if;
      mode:=private.queue_runtime_legacy_adoption_kind(item.organization_id,item.lead_id,item.round_robin_id,item.id);
      if mode is null then continue;end if;
      completed:=completed+1;
      begin
        adoption_at:=greatest(adoption_job.enrolled_at,coalesce(adoption_job.last_redistributed_at,adoption_job.enrolled_at),
          coalesce((select l.assigned_at from public.leads l where l.organization_id=item.organization_id and l.id=item.lead_id),adoption_job.enrolled_at));
        perform private.queue_runtime_enroll(item.organization_id,item.lead_id,item.round_robin_id,adoption_at);
        -- enrolled_at survives legacy transfers. The current assignment anchor,
        -- deadline and delivered warning must survive the handoff unchanged.
        -- Pending reentry polling is not a successful redistribution count.
        update private.queue_lead_runtime r set assignment_count=case when mode='assigned' then adoption_job.attempt_count else 0 end,
          baseline_at=adoption_at,due_at=case when mode='initial' then r.due_at else adoption_job.due_at end,
          warning_sent_at=case when mode='initial' then null else adoption_job.warning_sent_at end
          where r.organization_id=item.organization_id and r.lead_id=item.lead_id;
        insert into private.queue_runtime_events(organization_id,lead_id,round_robin_id,episode_id,round_number,event_type,metadata,created_at)
          select r.organization_id,r.lead_id,r.round_robin_id,r.episode_id,r.round_number,
            case when mode='initial' then 'legacy_initial_handoff' else 'legacy_assignment_handoff' end,
            jsonb_build_object('job_id',item.id,'legacy_attempt_count',adoption_job.attempt_count,'adoption_kind',mode),p_now
          from private.queue_lead_runtime r where r.organization_id=item.organization_id and r.lead_id=item.lead_id;
        adopted:=adopted+1;change:=jsonb_build_object('organizationId',item.organization_id,'leadId',item.lead_id);
        if not changed @> jsonb_build_array(change) then changed:=changed||jsonb_build_array(change);end if;
      exception when others then
        failure_code:=sqlstate;failed:=failed+1;
        -- Outer lead/job locks survive this subtransaction rollback. Retry is
        -- technical and bounded; the legacy business attempt remains intact.
        select least(5,case when coalesce(j.metadata->>'queue_runtime_adoption_retry_count','') ~ '^[0-5]$'
          then (j.metadata->>'queue_runtime_adoption_retry_count')::integer+1 else 1 end) into retry
          from public.lead_redistribution_jobs j where j.id=item.id;
        update public.lead_redistribution_jobs j set redistribution_retry_at=case when retry<5 then p_now+interval '1 minute' end,
          status=case when retry>=5 then 'stopped' else j.status end,
          stopped_reason=case when retry>=5 then 'managed_queue_adoption_quarantined' else j.stopped_reason end,
          stopped_at=case when retry>=5 then p_now else j.stopped_at end,
          metadata=coalesce(j.metadata,'{}'::jsonb)||jsonb_build_object('queue_runtime_adoption_retry_count',retry,
            'queue_runtime_adoption_error_code',failure_code,'queue_runtime_adoption_quarantined',retry>=5),updated_at=p_now
          where j.organization_id=item.organization_id and j.lead_id=item.lead_id and j.id=item.id;
      end;
      exit when completed>=batch_limit;
    end loop;
  end loop;
  update private.queue_runtime_worker_cursors set sort_at=last_sort,last_id=last_key_id,updated_at=clock_timestamp() where lane='adoption';

  select c.sort_at,c.last_id,c.pool_at into start_sort,start_id,start_pool from private.queue_runtime_worker_cursors c where c.lane='runtime' for update;
  last_sort:=start_sort;last_key_id:=start_id;last_pool:=start_pool;scanned:=0;completed:=0;
  for pass in 0..1 loop
    exit when scanned>=scan_limit or completed>=batch_limit or (pass=1 and start_id is null);
    for item in select r.organization_id,r.lead_id,r.round_robin_id,r.next_action_at,r.entered_pool_at
      from private.queue_lead_runtime r where r.state in ('auto_assigned','pool_waiting','pool_ready')
        and r.quarantined_at is null and r.next_action_at<=p_now
        and case when pass=0 then start_id is null or row(r.next_action_at,coalesce(r.entered_pool_at,'infinity'::timestamptz),r.lead_id)
          >row(start_sort,coalesce(start_pool,'infinity'::timestamptz),start_id)
          else row(r.next_action_at,coalesce(r.entered_pool_at,'infinity'::timestamptz),r.lead_id)
          <=row(start_sort,coalesce(start_pool,'infinity'::timestamptz),start_id) end
      order by r.next_action_at,r.entered_pool_at nulls last,r.lead_id limit scan_limit-scanned
    loop
      scanned:=scanned+1;last_sort:=item.next_action_at;last_pool:=item.entered_pool_at;last_key_id:=item.lead_id;
      perform 1 from public.round_robins q where q.organization_id=item.organization_id and q.id=item.round_robin_id for share skip locked;
      if not found then busy:=busy+1;continue;end if;
      perform 1 from public.leads l where l.organization_id=item.organization_id and l.id=item.lead_id for no key update skip locked;
      if not found then busy:=busy+1;continue;end if;
      select r.* into candidate from private.queue_lead_runtime r where r.organization_id=item.organization_id and r.lead_id=item.lead_id
        and r.state in ('auto_assigned','pool_waiting','pool_ready') and r.quarantined_at is null and r.next_action_at<=p_now for update skip locked;
      if not found then busy:=busy+1;continue;end if;
      begin
        if candidate.last_user_id is null and coalesce((private.queue_window(item.organization_id,candidate.round_robin_id,p_now)->>'open')::boolean,false)
          and exists(select 1 from private.queue_runtime_members(item.organization_id,candidate.round_robin_id,p_now) m where m.is_available) then
          result:=private.distribute_lead(item.organization_id,item.lead_id,
            'queue-initial:'||candidate.episode_id::text||':'||extract(epoch from p_now)::text,candidate.round_robin_id,false,'queue_runtime',p_now);
        else result:=private.queue_runtime_step(item.organization_id,item.lead_id,p_now);end if;
        if result->>'reason'='queue_busy' then busy:=busy+1;continue;end if;
        completed:=completed+1;processed:=processed+1;
        update private.queue_lead_runtime r set retry_count=0,last_error_code=null where r.organization_id=item.organization_id and r.lead_id=item.lead_id;
        if exists(select 1 from private.queue_lead_runtime r where r.organization_id=item.organization_id and r.lead_id=item.lead_id and r.revision<>candidate.revision) then
          change:=jsonb_build_object('organizationId',item.organization_id,'leadId',item.lead_id);
          if not changed @> jsonb_build_array(change) then changed:=changed||jsonb_build_array(change);end if;
        end if;
      exception when others then
        failure_code:=sqlstate;failed:=failed+1;completed:=completed+1;
        -- Queue/lead/runtime locks were obtained outside the failed subtransaction.
        update private.queue_lead_runtime r set retry_count=least(r.retry_count+1,5),last_error_code=failure_code,
          quarantined_at=case when r.retry_count>=4 then p_now end,
          next_action_at=case when r.retry_count<4 then p_now+interval '1 minute' end
          where r.organization_id=item.organization_id and r.lead_id=item.lead_id;
        insert into private.queue_runtime_events(organization_id,lead_id,round_robin_id,episode_id,round_number,event_type,metadata,created_at)
          select r.organization_id,r.lead_id,r.round_robin_id,r.episode_id,r.round_number,
            case when r.quarantined_at is null then 'runtime_error' else 'runtime_quarantined' end,
            jsonb_build_object('sqlstate',failure_code,'retry_count',r.retry_count),p_now
          from private.queue_lead_runtime r where r.organization_id=item.organization_id and r.lead_id=item.lead_id;
      end;
      exit when completed>=batch_limit;
    end loop;
  end loop;
  update private.queue_runtime_worker_cursors set sort_at=last_sort,last_id=last_key_id,pool_at=last_pool,updated_at=clock_timestamp() where lane='runtime';
  return jsonb_build_object('processed',processed,'failed',failed,'busy',busy,'adopted',adopted,'changed',changed);
end;
$_$;


ALTER FUNCTION private.process_queue_runtime_batch(p_limit integer, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: project_property_offer_prices(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.project_property_offer_prices(target_organization_id uuid, target_property_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  projected_sale_price numeric;
  projected_rental_price numeric;
begin
  select
    max(offer.price) filter (
      where offer.offer_type = 'sale'
        and offer.status = 'active'
    ),
    coalesce(
      max(offer.price) filter (
        where offer.offer_type = 'rent'
          and offer.status = 'active'
      ),
      max(offer.price) filter (
        where offer.offer_type = 'seasonal'
          and offer.status = 'active'
      )
    )
  into projected_sale_price, projected_rental_price
  from public.property_offers as offer
  where offer.organization_id = target_organization_id
    and offer.property_id = target_property_id;

  update public.properties as property
  set preco = projected_sale_price,
      valor_locacao = projected_rental_price,
      updated_at = now()
  where property.organization_id = target_organization_id
    and property.id = target_property_id
    and (
      property.preco is distinct from projected_sale_price
      or property.valor_locacao is distinct from projected_rental_price
    );
end;
$$;


ALTER FUNCTION private.project_property_offer_prices(target_organization_id uuid, target_property_id uuid) OWNER TO postgres;

--
-- Name: project_property_offer_prices_trigger(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.project_property_offer_prices_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  previous_sync text := current_setting(
    'vimob.property_offer_compatibility_sync',
    true
  );
begin
  if previous_sync = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.organization_id is not distinct from old.organization_id
     and new.property_id is not distinct from old.property_id
     and new.offer_type is not distinct from old.offer_type
     and new.status is not distinct from old.status
     and new.price is not distinct from old.price then
    return new;
  end if;

  perform set_config('vimob.property_offer_compatibility_sync', 'on', true);

  if tg_op = 'DELETE' then
    perform private.project_property_offer_prices(
      old.organization_id,
      old.property_id
    );
  else
    if tg_op = 'UPDATE'
       and (
         new.organization_id is distinct from old.organization_id
         or new.property_id is distinct from old.property_id
         or new.offer_type is distinct from old.offer_type
       ) then
      perform private.project_property_offer_prices(
        old.organization_id,
        old.property_id
      );
    end if;

    perform private.project_property_offer_prices(
      new.organization_id,
      new.property_id
    );
  end if;

  perform set_config(
    'vimob.property_offer_compatibility_sync',
    coalesce(previous_sync, ''),
    true
  );
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
exception
  when others then
    perform set_config(
      'vimob.property_offer_compatibility_sync',
      coalesce(previous_sync, ''),
      true
    );
    raise;
end;
$$;


ALTER FUNCTION private.project_property_offer_prices_trigger() OWNER TO postgres;

--
-- Name: project_property_owner_from_ownership(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.project_property_owner_from_ownership(p_organization_id uuid, p_property_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  with selected_owner as (
    select owner.id, owner.name, owner.phone_residential, owner.phone_commercial,
           owner.cellphone, owner.email, owner.media_source, owner.notify_email
    from public.property_ownerships as ownership
    join public.property_owners as owner
      on owner.organization_id = ownership.organization_id
     and owner.id = ownership.owner_id
     and coalesce(owner.is_active, true)
    where ownership.organization_id = p_organization_id
      and ownership.property_id = p_property_id
      and ownership.valid_from <= current_date
      and (ownership.valid_to is null or current_date < ownership.valid_to)
    order by ownership.is_primary desc, ownership.valid_from desc,
             ownership.updated_at desc, ownership.id
    limit 1
  ), projection as (
    select * from selected_owner
    union all
    select null::uuid, null::text, null::text, null::text, null::text,
           null::text, null::text, false
    where not exists (select 1 from selected_owner)
  )
  update public.properties as property
  set owner_id = projection.id,
      owner_name = projection.name,
      owner_phone_residential = projection.phone_residential,
      owner_phone_commercial = projection.phone_commercial,
      owner_cellphone = projection.cellphone,
      owner_email = projection.email,
      owner_media_source = projection.media_source,
      origin_media = projection.media_source,
      owner_notify_email = projection.notify_email,
      updated_at = now()
  from projection
  where property.organization_id = p_organization_id
    and property.id = p_property_id
    and (property.owner_id, property.owner_name, property.owner_phone_residential,
         property.owner_phone_commercial, property.owner_cellphone, property.owner_email,
         property.owner_media_source, property.origin_media, property.owner_notify_email)
        is distinct from
        (projection.id, projection.name, projection.phone_residential,
         projection.phone_commercial, projection.cellphone, projection.email,
         projection.media_source, projection.media_source, projection.notify_email);
end
$$;


ALTER FUNCTION private.project_property_owner_from_ownership(p_organization_id uuid, p_property_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION project_property_owner_from_ownership(p_organization_id uuid, p_property_id uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.project_property_owner_from_ownership(p_organization_id uuid, p_property_id uuid) IS 'P1 invariant: normalized active ownership is projected to legacy property owner fields.';


--
-- Name: promote_whatsapp_unlinked_retention_v1(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.promote_whatsapp_unlinked_retention_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.unlinked_retention_v1 and old.lead_id is null
     and new.lead_id is not null then
    if old.retired_at is not null
       or old.created_at <= pg_catalog.clock_timestamp() - interval '7 days'
       or old.unlinked_retention_scrubbed_at is not null then
      raise exception using errcode = '23514',
        message = 'expired_unlinked_conversation_cannot_be_promoted';
    end if;
    update private.whatsapp_unlinked_promotion_authorizations as authz
    set promotion_active = true
    where authz.backend_pid = pg_catalog.pg_backend_pid()
      and authz.transaction_id = pg_catalog.txid_current()
      and authz.organization_id = old.organization_id
      and authz.conversation_id = old.id
      and authz.lead_id = new.lead_id
      and not authz.promotion_active
      and exists (
        select 1 from private.whatsapp_unlinked_history_links as link
        where link.organization_id = old.organization_id
          and link.conversation_id = old.id
          and link.session_id = old.session_id
          and link.lead_id = new.lead_id
          and link.binding_mode = 'active'
      );
    if not found then
      raise exception using errcode = '23514',
        message = 'unlinked_promotion_requires_human_confirmation';
    end if;

    update public.whatsapp_messages as message
    set lead_id = new.lead_id,
        capture_state = 'promoted_unlinked'
    where message.organization_id = old.organization_id
      and message.conversation_id = old.id
      and message.session_id = old.session_id
      and message.lead_id is null
      and message.capture_state = 'unlinked_ephemeral'
      and message.unlinked_retention_scrubbed_at is null;

    delete from private.whatsapp_unlinked_promotion_authorizations as authz
    where authz.backend_pid = pg_catalog.pg_backend_pid()
      and authz.transaction_id = pg_catalog.txid_current()
      and authz.organization_id = old.organization_id
      and authz.conversation_id = old.id
      and authz.lead_id = new.lead_id
      and authz.promotion_active;
    new.unlinked_retention_v1 := false;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.promote_whatsapp_unlinked_retention_v1() OWNER TO postgres;

--
-- Name: property_asset_integration_providers(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.property_asset_integration_providers(p_metadata jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with provider_values as (
    select distinct pg_catalog.lower(pg_catalog.btrim(source.value)) as provider
    from pg_catalog.jsonb_array_elements_text(
      case
        when pg_catalog.jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)->'integration_providers') = 'array'
          then coalesce(p_metadata, '{}'::jsonb)->'integration_providers'
        when pg_catalog.lower(pg_catalog.btrim(coalesce(p_metadata, '{}'::jsonb)->>'integration_provider'))
          in ('imoview', 'vista')
          then pg_catalog.jsonb_build_array(
            pg_catalog.lower(pg_catalog.btrim(coalesce(p_metadata, '{}'::jsonb)->>'integration_provider'))
          )
        else '[]'::jsonb
      end
    ) as source(value)
  )
  select coalesce(
    pg_catalog.jsonb_agg(provider_values.provider order by provider_values.provider),
    '[]'::jsonb
  )
  from provider_values
  where provider_values.provider in ('imoview', 'vista');
$$;


ALTER FUNCTION private.property_asset_integration_providers(p_metadata jsonb) OWNER TO postgres;

--
-- Name: property_creation_ledger_is_valid(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.property_creation_ledger_is_valid(ledger jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select coalesce(
    jsonb_typeof(ledger) = 'object'
    and jsonb_typeof(ledger -> 'actor_id') = 'string'
    and jsonb_typeof(ledger -> 'key_hash') = 'string'
    and jsonb_typeof(ledger -> 'request_hash') = 'string'
    and (ledger ->> 'actor_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and (ledger ->> 'key_hash') ~ '^[0-9a-f]{64}$'
    and (ledger ->> 'request_hash') ~ '^[0-9a-f]{64}$', false
  );
$_$;


ALTER FUNCTION private.property_creation_ledger_is_valid(ledger jsonb) OWNER TO postgres;

--
-- Name: property_user_belongs_to_organization(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.property_user_belongs_to_organization(target_organization_id uuid, target_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    target_user_id is null
    or exists (
      select 1
      from public.users as app_user
      where app_user.id = target_user_id
        and coalesce(app_user.is_active, true) = true
        and (
          app_user.organization_id = target_organization_id
          or app_user.role = 'super_admin'
          or exists (
            select 1
            from public.user_roles as global_role
            where global_role.user_id = app_user.id
              and global_role.role = 'super_admin'
          )
          or exists (
            select 1
            from public.organization_members as member
            where member.organization_id = target_organization_id
              and member.user_id = app_user.id
              and coalesce(member.is_active, false) = true
          )
        )
    );
$$;


ALTER FUNCTION private.property_user_belongs_to_organization(target_organization_id uuid, target_user_id uuid) OWNER TO postgres;

--
-- Name: protect_dead_whatsapp_message_webhook_expiry(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.protect_dead_whatsapp_message_webhook_expiry() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_event_type text := pg_catalog.lower(pg_catalog.btrim(new.event_type));
begin
  if pg_catalog.strpos(v_event_type, 'message') > 0
     and pg_catalog.strpos(v_event_type, 'receipt') = 0
     and pg_catalog.strpos(v_event_type, 'ack') = 0
     and pg_catalog.strpos(v_event_type, 'status') = 0 then
    new.expires_at := 'infinity'::pg_catalog.timestamptz;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.protect_dead_whatsapp_message_webhook_expiry() OWNER TO postgres;

--
-- Name: FUNCTION protect_dead_whatsapp_message_webhook_expiry(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.protect_dead_whatsapp_message_webhook_expiry() IS 'Keeps dead inbound message-shaped webhook payloads until explicit replay or reconciliation; receipts, acknowledgements, and status events retain normal expiry.';


--
-- Name: protect_whatsapp_provider_attribution(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.protect_whatsapp_provider_attribution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_role text := coalesce(auth.role(), '');
  v_trusted_writer boolean := false;
  v_old_attribution jsonb;
  v_new_attribution jsonb;
begin
  v_trusted_writer := v_actor_role = 'service_role'
    or (
      v_actor_role = ''
      and session_user not in ('anon', 'authenticated', 'authenticator')
    );
  if v_trusted_writer then
    return new;
  end if;

  v_new_attribution := jsonb_build_object(
    'attribution', new.metadata->'whatsapp_attribution',
    'referral', new.metadata->'whatsapp_referral'
  );
  if tg_op = 'INSERT' then
    if new.metadata ? 'whatsapp_attribution' or new.metadata ? 'whatsapp_referral' then
      raise exception using
        errcode = '42501',
        message = 'trusted_whatsapp_provider_attribution_required';
    end if;
    return new;
  end if;

  v_old_attribution := jsonb_build_object(
    'attribution', old.metadata->'whatsapp_attribution',
    'referral', old.metadata->'whatsapp_referral'
  );
  if v_new_attribution is distinct from v_old_attribution then
    raise exception using
      errcode = '42501',
      message = 'trusted_whatsapp_provider_attribution_required';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.protect_whatsapp_provider_attribution() OWNER TO postgres;

--
-- Name: prune_user_activity_sessions(uuid, interval, integer, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.prune_user_activity_sessions(p_organization_id uuid DEFAULT NULL::uuid, p_retention interval DEFAULT '30 days'::interval, p_batch_size integer DEFAULT 10000, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_deleted integer := 0;
begin
  if p_now is null then
    raise exception using
      errcode = '22004',
      message = 'user_activity_prune_now_required';
  end if;

  if p_retention is null
     or p_retention < interval '1 day'
     or p_retention > interval '365 days' then
    raise exception using
      errcode = '22023',
      message = 'user_activity_prune_retention_out_of_range';
  end if;

  if p_batch_size is null
     or p_batch_size < 1
     or p_batch_size > 50000 then
    raise exception using
      errcode = '22023',
      message = 'user_activity_prune_batch_size_out_of_range';
  end if;

  with candidates as materialized (
    select stale.id
    from public.user_activity_sessions as stale
    where (p_organization_id is null
           or stale.organization_id = p_organization_id)
      and stale.last_seen_at < p_now - p_retention
      and exists (
        select 1
        from public.user_activity_sessions as newer
        where newer.organization_id = stale.organization_id
          and newer.user_id = stale.user_id
          and (
            newer.last_seen_at > stale.last_seen_at
            or (
              newer.last_seen_at = stale.last_seen_at
              and newer.id > stale.id
            )
          )
      )
    order by
      stale.organization_id,
      stale.user_id,
      stale.last_seen_at,
      stale.id
    for update of stale skip locked
    limit p_batch_size
  )
  delete from public.user_activity_sessions as stale
  using candidates
  where stale.id = candidates.id;

  get diagnostics v_deleted = row_count;

  with candidates as materialized (
    select stale.id
    from public.user_activity_sessions as stale
    where (p_organization_id is null
           or stale.organization_id = p_organization_id)
      and stale.last_seen_at < p_now - p_retention
      and not exists (
        select 1
        from public.user_activity_sessions as newer
        where newer.organization_id = stale.organization_id
          and newer.user_id = stale.user_id
          and (
            newer.last_seen_at > stale.last_seen_at
            or (
              newer.last_seen_at = stale.last_seen_at
              and newer.id > stale.id
            )
          )
      )
      and (
        stale.status <> 'offline'
        or stale.disconnected_at is null
        or stale.current_path is not null
        or stale.current_page_title is not null
        or stale.user_agent is not null
        or stale.metadata <> '{}'::jsonb
      )
    order by
      stale.organization_id,
      stale.user_id,
      stale.last_seen_at,
      stale.id
    for update of stale skip locked
    limit p_batch_size
  )
  update public.user_activity_sessions as stale
  set status = 'offline',
      disconnected_at = coalesce(stale.disconnected_at, stale.last_seen_at),
      current_path = null,
      current_page_title = null,
      user_agent = null,
      metadata = '{}'::jsonb,
      updated_at = p_now
  from candidates
  where stale.id = candidates.id;

  return v_deleted;
end;
$$;


ALTER FUNCTION private.prune_user_activity_sessions(p_organization_id uuid, p_retention interval, p_batch_size integer, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION prune_user_activity_sessions(p_organization_id uuid, p_retention interval, p_batch_size integer, p_now timestamp with time zone); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.prune_user_activity_sessions(p_organization_id uuid, p_retention interval, p_batch_size integer, p_now timestamp with time zone) IS 'Deletes stale superseded activity sessions in bounded batches and sanitizes each inactive user latest retained row.';


--
-- Name: publish_automation_tag_association(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.publish_automation_tag_association() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  association jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_execution_id uuid := private.safe_uuid(nullif(current_setting('vimob.automation_execution_id', true), ''));
  v_tenant_id uuid := private.safe_uuid(association->>'organization_id');
  v_lead_id uuid := private.safe_uuid(association->>'lead_id');
  v_tag_id uuid := private.safe_uuid(association->>'tag_id');
  v_effect_type text := case when tg_op = 'DELETE' then 'remove_tag' else 'add_tag' end;
begin
  -- The canonical RPC locks the execution/lead and reserves its effect first.
  -- Derive scope from the association, never from a client event payload.
  if v_execution_id is not null and exists (
    select 1 from public.automation_executions execution
    join public.automation_effect_dispatches dispatch
      on dispatch.execution_id = execution.id and dispatch.organization_id = execution.organization_id
    where execution.id = v_execution_id and execution.organization_id = v_tenant_id
      and execution.lead_id = v_lead_id and execution.status = 'running'
      and execution.cancellation_requested_at is null
      and dispatch.node_key = execution.current_node_key and dispatch.status = 'sending'
      and dispatch.effect_type = v_effect_type
      and private.safe_uuid(dispatch.request->>'tag_id') = v_tag_id
  ) then
    insert into private.realtime_events (organization_id, user_id, audience_user_id, event_type, data)
    values (v_tenant_id, null, null,
      case when tg_op = 'DELETE' then 'lead.untagged' else 'lead.tagged' end,
      jsonb_build_object('leadId', v_lead_id, 'tagId', v_tag_id));
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION private.publish_automation_tag_association() OWNER TO postgres;

--
-- Name: purge_expired_meta_oauth_flows(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.purge_expired_meta_oauth_flows(p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'vault'
    AS $$
declare
  cleared_count integer := 0;
  deleted_count integer := 0;
begin
  with cleared as (
    update public.meta_oauth_flows as flow
    set payload = null,
        status = case
          when flow.status in ('pending', 'success') then 'error'
          else flow.status
        end,
        error_message = case
          when flow.status in ('pending', 'success') then 'oauth_flow_expired'
          else flow.error_message
        end,
        updated_at = p_now
    where flow.expires_at <= p_now
      and flow.payload is not null
    returning 1
  )
  select count(*)::integer into cleared_count from cleared;

  with removed as (
    delete from public.meta_oauth_flows as flow
    where flow.expires_at < p_now - interval '24 hours'
    returning 1
  )
  select count(*)::integer into deleted_count from removed;

  return cleared_count + deleted_count;
end;
$$;


ALTER FUNCTION private.purge_expired_meta_oauth_flows(p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: purge_meta_webhook_events(timestamp with time zone, interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.purge_meta_webhook_events(p_now timestamp with time zone DEFAULT clock_timestamp(), p_retention interval DEFAULT '30 days'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  deleted_count integer := 0;
begin
  if p_retention < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'meta_webhook_retention_too_short';
  end if;

  delete from public.meta_webhook_events as event
  where coalesce(event.received_at, event.created_at) < p_now - p_retention;
  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;


ALTER FUNCTION private.purge_meta_webhook_events(p_now timestamp with time zone, p_retention interval) OWNER TO postgres;

--
-- Name: push_device_endpoint_key(text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.push_device_endpoint_key(p_endpoint text, p_platform text, p_token text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $_$
  select case when lower(btrim(coalesce(p_platform,''))) in ('android','ios')
    and nullif(btrim(p_token),'') is not null then 'native:'||btrim(p_token)
    when btrim(coalesce(p_endpoint,'')) like 'native:%' then
      'native:'||coalesce(nullif(btrim(p_token),''),substring(btrim(p_endpoint) from '^native:[^:]+:(.*)$'))
    else coalesce(nullif(btrim(p_endpoint),''),nullif(btrim(p_token),'')) end;
$_$;


ALTER FUNCTION private.push_device_endpoint_key(p_endpoint text, p_platform text, p_token text) OWNER TO postgres;

