--
-- Name: queue_notification_delivery_allowed(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_notification_delivery_allowed(p_org uuid, p_lead uuid, p_actor uuid, p_event text, p_metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  l public.leads%rowtype;
  r private.queue_lead_runtime%rowtype;
  q public.round_robins%rowtype;
  j public.lead_redistribution_jobs%rowtype;
  t integer; warning integer; now_at timestamptz := statement_timestamp();
begin
  if not private.queue_runtime_actor_active(p_org,p_actor) then return false; end if;
  select * into l from public.leads where organization_id=p_org and id=p_lead;
  if not found then return false; end if;
  if private.queue_pool_read_access(p_org,p_lead,p_actor) is false then return false; end if;
  select * into r from private.queue_lead_runtime where organization_id=p_org and lead_id=p_lead;

  if p_event='queue_pool_available' then
    return l.assigned_user_id is null and r.state in ('pool_waiting','pool_ready','limit_exhausted')
      and r.episode_id::text=p_metadata->>'episode_id' and r.revision::text=p_metadata->>'revision'
      and private.queue_pool_read_access(p_org,p_lead,p_actor) is true
      and private.queue_pool_alert_audience(p_org,r.round_robin_id,p_actor)
      and exists(select 1 from public.round_robins queue where queue.organization_id=p_org
        and queue.id=r.round_robin_id and queue.deleted_at is null
        and queue.settings->'pool_notifications'->'enabled'='true'::jsonb);
  end if;

  if p_event in ('new_lead_received','lead_redistributed_received','lead_redistribution_warning') then
    if l.assigned_user_id is distinct from p_actor then return false; end if;
    if r.lead_id is not null and p_event in ('new_lead_received','lead_redistributed_received') then
      if r.state<>'auto_assigned' or r.last_distribution_event_id is null
        or r.last_distribution_event_id::text is distinct from p_metadata->>'distribution_event_id' then return false; end if;
    end if;
    if r.state='auto_assigned' and not coalesce((private.queue_window(p_org,r.round_robin_id,now_at)->>'open')::boolean,false) then
      return false;
    end if;
  end if;
  if p_event<>'lead_redistribution_warning' then return true; end if;
  if coalesce(l.deal_status,'open')<>'open' then return false; end if;
  if r.lead_id is not null and r.state<>'auto_assigned' then return false; end if;

  if p_metadata->>'episode_id' is not null then
    if r.state is distinct from 'auto_assigned' or r.episode_id::text is distinct from p_metadata->>'episode_id'
      or r.revision::text is distinct from p_metadata->>'revision' or r.last_user_id is distinct from p_actor
      or r.due_at is null or r.due_at<=now_at
      or private.queue_runtime_has_human_activity(p_org,p_lead,r.baseline_at) then return false; end if;
    if not exists(select 1 from private.queue_runtime_members(p_org,r.round_robin_id,now_at) member
      where member.user_id=p_actor and member.is_available) then return false; end if;
    select * into q from public.round_robins where organization_id=p_org and id=r.round_robin_id;
  else
    select * into j from public.lead_redistribution_jobs where organization_id=p_org and lead_id=p_lead
      and id::text=p_metadata->>'job_id' and current_assigned_user_id=p_actor
      and status in ('pending','warning_sent') and due_at>now_at;
    if not found or j.timeout_minutes<=5 or j.warning_minutes<=0 or j.warning_minutes>=j.timeout_minutes
      or private.queue_runtime_has_human_activity(p_org,p_lead,j.enrolled_at) then return false; end if;
    select * into q from public.round_robins where organization_id=p_org and id=j.round_robin_id;
  end if;
  if q.id is null or q.deleted_at is not null or not coalesce(q.is_active,true)
    or q.settings->'enable_redistribution' is distinct from 'true'::jsonb
    or coalesce(q.settings->>'redistribution_timeout_minutes','')!~'^[0-9]+$'
    or coalesce(q.settings->>'redistribution_warning_minutes','')!~'^[0-9]+$' then return false; end if;
  t:=(q.settings->>'redistribution_timeout_minutes')::integer;
  warning:=(q.settings->>'redistribution_warning_minutes')::integer;
  if t<=5 or warning<=0 or warning>=t then return false; end if;
  if j.id is not null and (t<>j.timeout_minutes or warning<>j.warning_minutes) then return false; end if;
  if now_at<coalesce(r.due_at,j.due_at)-make_interval(mins=>warning) then return false; end if;
  return coalesce((private.queue_window(p_org,q.id,now_at)->>'open')::boolean,false);
exception when invalid_text_representation or numeric_value_out_of_range then
  return false;
end;
$_$;


ALTER FUNCTION private.queue_notification_delivery_allowed(p_org uuid, p_lead uuid, p_actor uuid, p_event text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: queue_pool_alert_audience(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_pool_alert_audience(p_org uuid, p_queue uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.queue_runtime_actor_active(p_org,p_actor) and (
    exists(select 1 from private.queue_runtime_members(p_org,p_queue,clock_timestamp()) m where m.user_id=p_actor)
    or exists(select 1 from private.queue_runtime_members(p_org,p_queue,clock_timestamp()) m
      join public.team_members target on target.organization_id=p_org and target.user_id=m.user_id and coalesce(target.is_active,true)
      join public.organization_members target_org on target_org.organization_id=p_org and target_org.user_id=target.user_id
        and target_org.is_active and target_org.deleted_at is null and target_org.membership_generation=target.membership_generation
      join public.teams t on t.id=target.team_id and t.organization_id=p_org and coalesce(t.is_active,true)
      join public.team_members leader on leader.organization_id=p_org and leader.team_id=target.team_id and leader.user_id=p_actor
        and coalesce(leader.is_active,true) and coalesce(leader.is_leader,false)
      join public.organization_members leader_org on leader_org.organization_id=p_org and leader_org.user_id=p_actor
        and leader_org.is_active and leader_org.deleted_at is null and leader_org.membership_generation=leader.membership_generation));
$$;


ALTER FUNCTION private.queue_pool_alert_audience(p_org uuid, p_queue uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_pool_audience(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_pool_audience(p_org uuid, p_queue uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.queue_runtime_actor_active(p_org,p_actor) and (
    private.queue_runtime_actor_admin(p_org,p_actor)
    or exists(select 1 from private.queue_runtime_members(p_org,p_queue,clock_timestamp()) m where m.user_id=p_actor)
    or exists(select 1 from private.queue_runtime_members(p_org,p_queue,clock_timestamp()) m
      join public.team_members target on target.organization_id=p_org and target.user_id=m.user_id and coalesce(target.is_active,true)
      join public.organization_members target_org on target_org.organization_id=p_org and target_org.user_id=target.user_id
        and target_org.is_active and target_org.deleted_at is null and target_org.membership_generation=target.membership_generation
      join public.teams t on t.id=target.team_id and t.organization_id=p_org and coalesce(t.is_active,true)
      join public.team_members leader on leader.organization_id=p_org and leader.team_id=target.team_id and leader.user_id=p_actor
        and coalesce(leader.is_active,true) and coalesce(leader.is_leader,false)
      join public.organization_members leader_org on leader_org.organization_id=p_org and leader_org.user_id=p_actor
        and leader_org.is_active and leader_org.deleted_at is null and leader_org.membership_generation=leader.membership_generation));
$$;


ALTER FUNCTION private.queue_pool_audience(p_org uuid, p_queue uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_pool_metadata(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_pool_metadata(p_organization_id uuid, p_lead_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r private.queue_lead_runtime%rowtype;
begin
  if private.queue_pool_read_access(p_organization_id,p_lead_id,p_actor_id) is distinct from true then return null; end if;
  select * into r from private.queue_lead_runtime where organization_id=p_organization_id and lead_id=p_lead_id;
  return jsonb_build_object('roundRobinId',r.round_robin_id,'episodeId',r.episode_id,'revision',r.revision,'state',r.state,
    'reason',r.reason,'enteredAt',r.entered_pool_at,'nextActionAt',r.next_action_at,
    'canClaim',private.queue_runtime_actor_can_claim(p_organization_id,p_actor_id));
end;
$$;


ALTER FUNCTION private.queue_pool_metadata(p_organization_id uuid, p_lead_id uuid, p_actor_id uuid) OWNER TO postgres;

--
-- Name: queue_pool_read_access(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_pool_read_access(p_organization_id uuid, p_lead_id uuid, p_actor_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r private.queue_lead_runtime%rowtype;
begin
  select * into r from private.queue_lead_runtime where organization_id=p_organization_id and lead_id=p_lead_id
    and state in ('pool_waiting','pool_ready','limit_exhausted');
  if not found then return null; end if;
  if current_setting('role',true) not in ('none','postgres','service_role') and p_actor_id is distinct from auth.uid() then return false; end if;
  return private.queue_pool_audience(p_organization_id,r.round_robin_id,p_actor_id);
end;
$$;


ALTER FUNCTION private.queue_pool_read_access(p_organization_id uuid, p_lead_id uuid, p_actor_id uuid) OWNER TO postgres;

