--
-- Name: queue_property_asset_storage_cleanup(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_property_asset_storage_cleanup() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  expected_property_prefix text;
  expected_asset_prefix text;
  cleanup_asset_id uuid;
  cleanup_not_before timestamptz;
begin
  if old.storage_path is null
     or (tg_op = 'UPDATE' and old.storage_path is not distinct from new.storage_path) then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  expected_property_prefix := pg_catalog.format(
    'orgs/%s/properties/%s/',
    old.organization_id,
    old.property_id
  );
  expected_asset_prefix := pg_catalog.format(
    'orgs/%s/properties/%s/%s/',
    old.organization_id,
    old.property_id,
    old.id
  );

  if pg_catalog.left(
       old.storage_path,
       pg_catalog.length(expected_property_prefix)
     ) = expected_property_prefix then
    cleanup_asset_id := case
      when pg_catalog.left(
        old.storage_path,
        pg_catalog.length(expected_asset_prefix)
      ) = expected_asset_prefix then old.id
      else null
    end;

    select greatest(now(), coalesce(max(intent.expires_at) + interval '5 minutes', now()))
      into cleanup_not_before
    from public.property_asset_upload_intents as intent
    where intent.organization_id = old.organization_id
      and intent.property_id = old.property_id
      and intent.storage_path = old.storage_path;

    insert into public.property_asset_storage_cleanup_queue (
      organization_id,
      property_id,
      asset_id,
      storage_path,
      available_at
    )
    values (
      old.organization_id,
      old.property_id,
      cleanup_asset_id,
      old.storage_path,
      cleanup_not_before
    )
    on conflict (storage_path) do update
    set available_at = greatest(
          public.property_asset_storage_cleanup_queue.available_at,
          excluded.available_at
        ),
        asset_id = coalesce(
          public.property_asset_storage_cleanup_queue.asset_id,
          excluded.asset_id
        ),
        updated_at = now();
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION private.queue_property_asset_storage_cleanup() OWNER TO postgres;

--
-- Name: queue_property_asset_upload_cleanup_on_cascade(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_property_asset_upload_cleanup_on_cascade() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from public.properties as property
    where property.organization_id = old.organization_id
      and property.id = old.property_id
  ) or exists (
    select 1
    from public.property_assets as asset
    where asset.organization_id = old.organization_id
      and asset.property_id = old.property_id
      and asset.storage_path = old.storage_path
  ) then
    return old;
  end if;

  insert into public.property_asset_storage_cleanup_queue (
    organization_id,
    property_id,
    asset_id,
    storage_path,
    available_at
  )
  values (
    old.organization_id,
    old.property_id,
    null,
    old.storage_path,
    greatest(now(), old.expires_at + interval '5 minutes')
  )
  on conflict (storage_path) do update
  set available_at = greatest(
        public.property_asset_storage_cleanup_queue.available_at,
        excluded.available_at
      ),
      updated_at = now();

  return old;
end;
$$;


ALTER FUNCTION private.queue_property_asset_upload_cleanup_on_cascade() OWNER TO postgres;

--
-- Name: queue_runtime_actor_active(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_actor_active(p_org uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.organization_members om join public.users u on u.id=om.user_id
    join public.organizations o on o.id=om.organization_id
    where om.organization_id=p_org and om.user_id=p_actor and om.is_active and om.deleted_at is null
      and u.is_active and coalesce(o.is_active,true));
$$;


ALTER FUNCTION private.queue_runtime_actor_active(p_org uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_runtime_actor_admin(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_actor_admin(p_org uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.queue_runtime_actor_active(p_org,p_actor) and (
    exists(select 1 from public.organization_members om where om.organization_id=p_org and om.user_id=p_actor and om.role in ('owner','admin'))
    or exists(select 1 from public.organizations o where o.id=p_org and o.created_by=p_actor));
$$;


ALTER FUNCTION private.queue_runtime_actor_admin(p_org uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_runtime_actor_can_claim(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_actor_can_claim(p_org uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with effective as (select private.queue_runtime_claim_permissions(p_org,p_actor) as keys)
  select keys @> array['*']::text[] or (
    keys @> array['lead_operate']::text[]
    and keys && array['lead_view_own','lead_view_team','lead_view_all']::text[]
  ) from effective;
$$;


ALTER FUNCTION private.queue_runtime_actor_can_claim(p_org uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_runtime_assign(uuid, uuid, uuid, uuid, uuid, integer, text, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_assign(p_org uuid, p_lead uuid, p_user uuid, p_team uuid, p_member uuid, p_position integer, p_window_key text, p_round integer, p_now timestamp with time zone, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r private.queue_lead_runtime%rowtype; previous_user uuid; timeout_minutes integer; result jsonb; event_id uuid:=gen_random_uuid();
begin
  select * into r from private.queue_lead_runtime where organization_id=p_org and lead_id=p_lead for update;
  select assigned_user_id into previous_user from public.leads where organization_id=p_org and id=p_lead;
  if previous_user is not distinct from p_user then return jsonb_build_object('success',false,'reason','queue_waiting','lead_id',p_lead); end if;
  select least(10080,greatest(1,coalesce((q.settings->>'redistribution_timeout_minutes')::integer,20))) into timeout_minutes
    from public.round_robins q where q.organization_id=p_org and q.id=r.round_robin_id;
  insert into private.queue_runtime_commands values(txid_current(),p_org,p_lead,'automatic',p_actor)
    on conflict(transaction_id,organization_id,lead_id) do update set mode='automatic',actor_id=p_actor;
  update public.leads set assigned_user_id=p_user,team_id=p_team,assigned_at=p_now,updated_at=p_now
    where organization_id=p_org and id=p_lead;
  update private.queue_lead_runtime set state=case when p_actor is null then 'auto_assigned' else 'manual_protected' end,
    reason=case when p_actor is null then 'round_assignment' else 'manual_assignment' end,revision=revision+1,
    round_number=p_round,assignment_count=assignment_count+1,last_user_id=p_user,last_position=p_position,last_window_key=p_window_key,last_distribution_event_id=event_id,
    last_queue_close_at=(private.queue_window(p_org,r.round_robin_id,p_now)->>'closesAt')::timestamptz,
    last_member_close_at=(select m.available_until from private.queue_runtime_members(p_org,r.round_robin_id,p_now)m where m.user_id=p_user),
    baseline_at=p_now,assigned_at=p_now,due_at=p_now+make_interval(mins=>timeout_minutes),next_action_at=case when p_actor is null then
      least(p_now+interval '30 seconds',(private.queue_window(p_org,r.round_robin_id,p_now)->>'closesAt')::timestamptz,
        (select m.available_until from private.queue_runtime_members(p_org,r.round_robin_id,p_now)m where m.user_id=p_user)) else null end,
    entered_pool_at=null,protected_actor_id=p_actor,warning_sent_at=null,retry_count=0,quarantined_at=null,last_error_code=null,updated_at=p_now where organization_id=p_org and lead_id=p_lead returning * into r;
  insert into private.queue_round_visits values(p_org,p_lead,r.episode_id,p_round,p_user,p_now);
  insert into private.queue_runtime_events(id,organization_id,lead_id,round_robin_id,episode_id,round_number,event_type,from_user_id,to_user_id,actor_id,metadata,created_at)
    values(event_id,p_org,p_lead,r.round_robin_id,r.episode_id,p_round,'assigned',previous_user,p_user,p_actor,
      jsonb_build_object('algorithm','lead_unique_round_v1','position',p_position,'windowKey',p_window_key,'revision',r.revision),p_now);
  insert into public.assignments_log(organization_id,lead_id,round_robin_id,assigned_user_id,old_user_id,new_user_id,reason,assigned_at)
    values(p_org,p_lead,r.round_robin_id,p_user,previous_user,p_user,'auto_redistribution',p_now);
  insert into public.round_robin_logs(organization_id,round_robin_id,lead_id,assigned_user_id,member_id,reason,metadata)
    values(p_org,r.round_robin_id,p_lead,p_user,p_member,'auto_redistribution',jsonb_build_object('algorithm_version','lead_unique_round_v1',
      'episode_id',r.episode_id,'round_number',p_round,'distribution_event_id',event_id,'member_id',p_member));
  insert into public.lead_timeline_events(organization_id,lead_id,event_type,title,description,metadata,event_at)
    values(p_org,p_lead,'lead_assigned','Lead distribuído','Lead atribuído pela fila.',
      jsonb_build_object('distribution_type','queue_round','distribution_event_id',event_id,'queue_id',r.round_robin_id,'assigned_user_id',p_user),p_now);
  insert into public.notifications(organization_id,user_id,lead_id,type,title,content,body,metadata,channel,target_url,created_at)
    values(p_org,p_user,p_lead,'lead_assigned','Novo lead atribuído','Você recebeu um lead da fila.','Você recebeu um lead da fila.',
      private.queue_runtime_dispatch_metadata(jsonb_build_object('event_key','new_lead_received','round_robin_id',r.round_robin_id,'distribution_event_id',event_id,'episode_id',r.episode_id,'revision',r.revision,
        'dedupe_key','queue_assignment:'||event_id::text)),'in_app','/crm/pipelines?lead='||p_lead::text,p_now);
  if previous_user is not null then
    insert into public.notifications(organization_id,user_id,lead_id,type,title,content,body,metadata,channel,target_url,created_at)
      values(p_org,previous_user,p_lead,'lead_redistributed_away','Lead redistribuído','O lead foi redistribuído para outro participante da fila.',
        'O lead foi redistribuído para outro participante da fila.',private.queue_runtime_dispatch_metadata(jsonb_build_object('event_key','lead_redistributed_away',
          'round_robin_id',r.round_robin_id,'distribution_event_id',event_id,'dedupe_key','queue_away:'||event_id::text)),
        'in_app','/crm/pipelines?lead='||p_lead::text,p_now);
  end if;
  update public.lead_redistribution_jobs set status='stopped',stopped_reason='managed_queue_runtime',stopped_at=p_now,updated_at=p_now
    where organization_id=p_org and lead_id=p_lead and status in ('pending','warning_sent');
  delete from private.queue_runtime_commands where transaction_id=txid_current() and organization_id=p_org and lead_id=p_lead;
  select jsonb_build_object('success',true,'reason','assigned','lead_id',l.id,'assigned_user_id',l.assigned_user_id,
    'team_id',l.team_id,'pipeline_id',l.pipeline_id,'stage_id',l.stage_id,'round_robin_id',r.round_robin_id,
    'member_id',p_member,'distribution_event_id',event_id) into result from public.leads l where l.organization_id=p_org and l.id=p_lead;
  return result;
end;
$$;


ALTER FUNCTION private.queue_runtime_assign(p_org uuid, p_lead uuid, p_user uuid, p_team uuid, p_member uuid, p_position integer, p_window_key text, p_round integer, p_now timestamp with time zone, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_runtime_claim_permissions(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_claim_permissions(p_org uuid, p_actor uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with actor as (
    select lower(btrim(coalesce(m.role,'user'))) as member_role,u.role as profile_role
    from public.organization_members m
    join public.users u on u.id=m.user_id
    join public.organizations o on o.id=m.organization_id
    where m.organization_id=p_org and m.user_id=p_actor and m.is_active
      and m.deleted_at is null and u.is_active and coalesce(o.is_active,true)
  ), role_grants as (
    -- Match the canonical tenant repository joins. Historical role columns
    -- alone are not accepted when the canonical schema is present.
    select lower(btrim(ap.key)) as permission_key
    from public.user_organization_roles a
    join public.organization_roles r on r.id=a.role_id and r.organization_id=a.organization_id and r.is_active
    join public.organization_role_permissions rp on rp.role_id=r.id and rp.organization_id=r.organization_id
    join public.available_permissions ap on ap.id=rp.permission_id
    where a.organization_id=p_org and a.user_id=p_actor and a.is_active
  ), leader as (
    select exists(
      select 1 from public.team_members tm
      join public.teams t on t.id=tm.team_id and t.organization_id=tm.organization_id and coalesce(t.is_active,true)
      join public.organization_members m on m.organization_id=tm.organization_id and m.user_id=tm.user_id
        and m.is_active and m.deleted_at is null and m.membership_generation=tm.membership_generation
      where tm.organization_id=p_org and tm.user_id=p_actor and coalesce(tm.is_active,true) and coalesce(tm.is_leader,false)
    ) as is_leader
  ), normalized_overrides as (
    select case lower(btrim(o.permission_key))
      when 'lead_edit' then 'lead_operate'
      when 'lead_edit_own' then 'lead_operate'
      when 'lead_edit_all' then 'lead_operate'
      when 'lead_manage' then 'lead_operate'
      when 'lead_assign' then 'lead_operate'
      when 'lead_transfer' then 'lead_operate'
      else lower(btrim(o.permission_key)) end as permission_key,o.allowed
    from public.user_permission_overrides o where o.organization_id=p_org and o.user_id=p_actor
  ), overrides as (
    -- Current writers persist canonical keys. If conflicting historical
    -- aliases coexist, a denial must not become an additional claim grant.
    select permission_key,bool_and(allowed) as allowed from normalized_overrides group by permission_key
  ), inherited as (
    select 'lead_operate'::text as permission_key,true as allowed
    union all select 'lead_view_own',true
    union all select 'lead_view_team',
      (select is_leader from leader) or exists(select 1 from role_grants where permission_key='lead_view_team')
    union all select 'lead_view_all',
      exists(select 1 from actor where member_role='manager')
      or exists(select 1 from role_grants where permission_key in ('lead_view_all','lead_edit_all','lead_manage'))
  )
  select case
    when not exists(select 1 from actor) then '{}'::text[]
    when exists(select 1 from actor where member_role in ('owner','admin') or profile_role='super_admin')
      or exists(select 1 from role_grants where permission_key='*') then array['*']::text[]
    else coalesce((select array_agg(i.permission_key order by i.permission_key) from inherited i
      left join overrides o using(permission_key) where coalesce(o.allowed,i.allowed)), '{}'::text[])
    end;
$$;


ALTER FUNCTION private.queue_runtime_claim_permissions(p_org uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_runtime_dispatch_metadata(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_dispatch_metadata(p_data jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(p_data,'{}'::jsonb)||jsonb_build_object('dispatch',jsonb_build_object(
    'whatsapp',jsonb_build_object('required',true,'status','pending'),'push',jsonb_build_object('required',true,'status','pending'),
    'email',jsonb_build_object('required',false,'status','not_required')));
$$;


ALTER FUNCTION private.queue_runtime_dispatch_metadata(p_data jsonb) OWNER TO postgres;

--
-- Name: queue_runtime_enroll(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_enroll(p_org uuid, p_lead uuid, p_queue uuid, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare l public.leads%rowtype; q public.round_robins%rowtype; budget integer; timeout_minutes integer; w jsonb; m record;
begin
  select * into l from public.leads where organization_id=p_org and id=p_lead;
  select * into q from public.round_robins where organization_id=p_org and id=p_queue;
  if not found or not (q.settings ? 'operating_schedule') then return; end if;
  budget:=least(1000,greatest(0,coalesce((q.settings->>'redistribution_max_attempts')::integer,10)));
  timeout_minutes:=least(10080,greatest(1,coalesce((q.settings->>'redistribution_timeout_minutes')::integer,20)));
  w:=private.queue_window(p_org,p_queue,p_now);
  insert into private.queue_lead_runtime(organization_id,lead_id,round_robin_id,state,reason,max_assignments,last_user_id,
    baseline_at,assigned_at,due_at,next_action_at,entered_pool_at)
  values(p_org,p_lead,p_queue,case when l.assigned_user_id is null then 'pool_waiting' else 'auto_assigned' end,
    case when l.assigned_user_id is null then 'no_available_members' else 'initial_assignment' end,budget,l.assigned_user_id,
    p_now,case when l.assigned_user_id is null then null else p_now end,
    case when l.assigned_user_id is null then null else p_now+make_interval(mins=>timeout_minutes) end,p_now,
    null) on conflict do nothing;
  if l.assigned_user_id is not null then
    select * into m from private.queue_runtime_members(p_org,p_queue,p_now) where user_id=l.assigned_user_id;
    update private.queue_lead_runtime set last_window_key=m.window_key,last_position=coalesce(m.position,0),last_member_close_at=m.available_until,
      last_queue_close_at=(w->>'closesAt')::timestamptz
      where organization_id=p_org and lead_id=p_lead and assigned_at=p_now;
    insert into private.queue_round_visits(organization_id,lead_id,episode_id,round_number,user_id,assigned_at)
      select p_org,p_lead,episode_id,round_number,l.assigned_user_id,p_now from private.queue_lead_runtime
      where organization_id=p_org and lead_id=p_lead on conflict do nothing;
  end if;
  update public.lead_redistribution_jobs set status='stopped',stopped_reason='managed_queue_runtime',stopped_at=p_now,updated_at=p_now
    where organization_id=p_org and lead_id=p_lead and status in ('pending','warning_sent');
end;
$$;


ALTER FUNCTION private.queue_runtime_enroll(p_org uuid, p_lead uuid, p_queue uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: queue_runtime_has_human_activity(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_has_human_activity(p_org uuid, p_lead uuid, p_baseline timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.lead_action_facts f where f.organization_id=p_org and f.lead_id=p_lead
    and f.occurred_at>=p_baseline and not f.is_automated and not f.is_inbound
    and (f.actor_user_id is not null or f.action_type='whatsapp_outbound')
    and (f.qualifies_first_outreach or f.is_effective_contact or f.action_type in ('feedback','feedback_added','note','task_completed'))
    and ((f.source_type<>'whatsapp_message' and f.action_type not in ('whatsapp','message','whatsapp_outbound'))
      or exists(select 1 from public.whatsapp_messages confirmed where confirmed.organization_id=p_org and confirmed.lead_id=p_lead
        and confirmed.id::text=f.source_id and lower(coalesce(confirmed.status,'')) in ('sent','delivered','read')
        and confirmed.sender_user_id=f.actor_user_id and (coalesce(confirmed.from_me,false) or confirmed.direction='outbound')
        and lower(coalesce(confirmed.metadata->>'is_automated',confirmed.metadata->>'is_automation',confirmed.metadata->>'automated','false')) not in ('true','1','yes')
        and lower(coalesce(confirmed.metadata->>'sender_type','')) not in ('ai','automation','bot')
        and lower(coalesce(confirmed.metadata->>'origin','')) !~ '^(ai|openai|automation|bot)' and coalesce(confirmed.client_message_id,'') not like 'ai-%'))
    and exists(select 1 from public.leads l where l.organization_id=p_org and l.id=p_lead
      and f.occurred_at>=coalesce(l.assigned_at,p_baseline)
      and (f.action_type<>'whatsapp_outbound' or f.actor_user_id=l.assigned_user_id)
      and (exists(select 1 from public.lead_assignment_cycles c where c.id=f.assignment_cycle_id and c.organization_id=p_org
          and c.lead_id=p_lead and c.ended_at is null and c.assigned_user_id=l.assigned_user_id)
        or (f.assignment_cycle_id is null and f.actor_user_id=l.assigned_user_id)))
    and not (f.source_type='activity' and exists(
      select 1 from public.activities a join public.round_robin_logs r on r.organization_id=a.organization_id and r.lead_id=a.lead_id
        and r.created_at between a.created_at-interval '1 second' and a.created_at+interval '1 second'
      where a.organization_id=p_org and a.lead_id=p_lead and a.id::text=f.source_id and a.type in ('assignee_changed','stage_change'))))
  or exists(select 1 from public.activities a where a.organization_id=p_org and a.lead_id=p_lead and a.created_at>=p_baseline
    and a.user_id is not null and a.type in ('feedback','feedback_added','note','task_completed')
    and exists(select 1 from public.leads l where l.organization_id=p_org and l.id=p_lead and a.user_id=l.assigned_user_id and a.created_at>=coalesce(l.assigned_at,p_baseline))
    and lower(coalesce(a.metadata->>'is_automated',a.metadata->>'is_automation',a.metadata->>'automated','false')) not in ('true','1','yes')
    and lower(coalesce(a.metadata->>'origin','')) !~ '^(ai|openai|automation|bot)'
    and not (a.type in ('assignee_changed','stage_change') and exists(select 1 from public.round_robin_logs r
      where r.organization_id=p_org and r.lead_id=p_lead and r.created_at between a.created_at-interval '1 second' and a.created_at+interval '1 second')))
  or exists(select 1 from public.whatsapp_messages m where m.organization_id=p_org and m.lead_id=p_lead
    and coalesce(m.sent_at,m.received_at,m.created_at)>=p_baseline and (coalesce(m.from_me,false) or m.direction='outbound')
    and lower(coalesce(m.status,'')) in ('sent','delivered','read')
    and exists(select 1 from public.leads l where l.organization_id=p_org and l.id=p_lead and m.sender_user_id=l.assigned_user_id
      and coalesce(m.sent_at,m.received_at,m.created_at)>=coalesce(l.assigned_at,p_baseline))
    and lower(coalesce(m.metadata->>'is_automated',m.metadata->>'is_automation',m.metadata->>'automated','false')) not in ('true','1','yes')
    and lower(coalesce(m.metadata->>'origin','')) !~ '^(ai|openai|automation|bot)'
    and lower(coalesce(m.metadata->>'sender_type','')) not in ('ai','automation','bot') and coalesce(m.client_message_id,'') not like 'ai-%')
  or exists(select 1 from public.lead_timeline_events t join public.leads l on l.organization_id=t.organization_id and l.id=t.lead_id
    where t.organization_id=p_org and t.lead_id=p_lead and t.event_type='first_response'
      and coalesce(t.actor_user_id,t.user_id)=l.assigned_user_id and coalesce(t.event_at,t.created_at)>=greatest(p_baseline,l.assigned_at)
      and lower(coalesce(t.metadata->>'is_automation',t.metadata->>'is_automated',t.metadata->>'automated','false')) not in ('true','1','yes')
      and lower(coalesce(t.metadata->>'origin','')) !~ '^(ai|openai|automation|bot)');
$$;


ALTER FUNCTION private.queue_runtime_has_human_activity(p_org uuid, p_lead uuid, p_baseline timestamp with time zone) OWNER TO postgres;

--
-- Name: queue_runtime_is_managed(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_is_managed(p_organization_id uuid, p_round_robin_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.round_robins q where q.organization_id=p_organization_id
    and q.id=p_round_robin_id and q.settings ? 'operating_schedule');
$$;


ALTER FUNCTION private.queue_runtime_is_managed(p_organization_id uuid, p_round_robin_id uuid) OWNER TO postgres;

--
-- Name: queue_runtime_legacy_adoption_kind(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_legacy_adoption_kind(p_org uuid, p_lead uuid, p_queue uuid, p_job uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when (lower(coalesce(j.metadata->>'initial_distribution_pending','false')) not in ('true','1','yes')
        or lower(coalesce(j.metadata->>'allow_assigned_redistribution','false')) in ('true','1','yes'))
      and l.assigned_user_id is not null and j.current_assigned_user_id=l.assigned_user_id
      and exists(select 1 from public.assignments_log a where a.organization_id=p_org and a.lead_id=p_lead
        and a.id=(select latest.id from public.assignments_log latest where latest.organization_id=p_org and latest.lead_id=p_lead
          order by latest.created_at desc,latest.id desc limit 1)
        and a.reason in ('canonical_round_robin','auto_redistribution') and a.new_user_id=l.assigned_user_id)
      then case when lower(coalesce(j.metadata->>'initial_distribution_pending','false')) in ('true','1','yes')
        then 'assigned_pending' else 'assigned' end
    when lower(coalesce(j.metadata->>'initial_distribution_pending','false')) in ('true','1','yes')
      and lower(coalesce(j.metadata->>'allow_assigned_redistribution','false')) not in ('true','1','yes')
      and l.assigned_user_id is null and j.current_assigned_user_id is null and j.original_assigned_user_id is null
      and j.last_redistributed_at is null
      and not exists(select 1 from public.assignments_log a where a.organization_id=p_org and a.lead_id=p_lead)
      and (l.first_response_at is null or coalesce(l.first_response_is_automation,false))
      and not exists(select 1 from public.lead_action_facts f where f.organization_id=p_org and f.lead_id=p_lead
        and f.actor_user_id is not null and not coalesce(f.is_automated,false) and not coalesce(f.is_inbound,false))
      and not exists(select 1 from public.activities a where a.organization_id=p_org and a.lead_id=p_lead and a.user_id is not null
        and a.type in ('feedback','feedback_added','note','task_completed','assignee_changed','stage_change')
        and lower(coalesce(a.metadata->>'is_automated',a.metadata->>'is_automation',a.metadata->>'automated','false')) not in ('true','1','yes')
        and lower(coalesce(a.metadata->>'origin','')) !~ '^(ai|openai|automation|bot)')
      and not exists(select 1 from public.whatsapp_messages m where m.organization_id=p_org and m.lead_id=p_lead
        and m.sender_user_id is not null and (coalesce(m.from_me,false) or m.direction='outbound')
        and lower(coalesce(m.status,'')) in ('sent','delivered','read')
        and lower(coalesce(m.metadata->>'is_automated',m.metadata->>'is_automation',m.metadata->>'automated','false')) not in ('true','1','yes')
        and lower(coalesce(m.metadata->>'sender_type','')) not in ('ai','automation','bot'))
      and ((j.metadata->>'source'='managed_whatsapp' and exists(select 1 from public.lead_entry_events entry where entry.organization_id=p_org and entry.lead_id=p_lead
        and entry.id::text=j.metadata->>'entry_event_id' and entry.entry_type in ('initial','reentry')
        and entry.source='whatsapp' and entry.provider='whatsapp' and entry.is_countable
        and entry.metadata->>'managed_whatsapp_message_distribution'='true'
        and entry.metadata->>'target_round_robin_id'=p_queue::text
        and entry.metadata#>>'{intake_result,round_robin_id}'=p_queue::text
        and entry.metadata#>>'{intake_result,distribution_pending}'='true'
        and entry.metadata#>>'{intake_result,pending_distribution_job_id}'=j.id::text
        and entry.metadata#>>'{intake_result,applied_to_current_state}'='true'
        and entry.metadata#>>'{intake_result,success}'='false'
        and entry.metadata#>>'{intake_result,reason}'='no_available_members'
        and coalesce(entry.metadata#>>'{intake_result,assigned_user_id}','')=''
        and entry.id=(select latest.id from public.lead_entry_events latest where latest.organization_id=p_org
          and latest.lead_id=p_lead and latest.is_countable
          order by coalesce(latest.occurred_at,latest.created_at) desc,latest.provider_event_id desc nulls last,latest.created_at desc,latest.id desc limit 1)
        and exists(select 1 from private.lead_distribution_events e where e.organization_id=p_org and e.lead_id=p_lead
          and e.round_robin_id=p_queue and e.outcome='no_available_members'
          and e.id::text=entry.metadata#>>'{intake_result,distribution_event_id}')))
        or (j.metadata->>'source'='meta_lead_ads' and private.queue_runtime_meta_initial_pending_proven(p_org,p_lead,p_queue,p_job)))
      then 'initial'
    end
  from public.lead_redistribution_jobs j
  join public.leads l on l.organization_id=p_org and l.id=p_lead
  join public.round_robins q on q.organization_id=p_org and q.id=p_queue
  join public.organizations o on o.id=p_org and coalesce(o.is_active,true)
  where j.organization_id=p_org and j.lead_id=p_lead and j.round_robin_id=p_queue and j.id=p_job
    and j.status in ('pending','warning_sent') and j.metadata->>'attention_instance_id' is null
    and lower(coalesce(j.metadata->>'queue_runtime_adoption_quarantined','false')) not in ('true','1','yes')
    and coalesce(q.is_active,true) and q.deleted_at is null and q.settings ? 'operating_schedule'
    and coalesce(l.deal_status,'open')='open'
    and not exists(select 1 from private.queue_lead_runtime r where r.organization_id=p_org and r.lead_id=p_lead);
$$;


ALTER FUNCTION private.queue_runtime_legacy_adoption_kind(p_org uuid, p_lead uuid, p_queue uuid, p_job uuid) OWNER TO postgres;

--
-- Name: queue_runtime_members(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_members(p_org uuid, p_queue uuid, p_now timestamp with time zone) RETURNS TABLE(member_id uuid, user_id uuid, team_id uuid, team_member_id uuid, "position" integer, weight integer, is_available boolean, window_key text, available_until timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with queue_window_context as materialized (
    select q.*,private.queue_window(p_org,p_queue,p_now) as operating_window
    from public.round_robins q where q.organization_id=p_org and q.id=p_queue
  ), queue as (
    select q.*,coalesce(q.operating_window->>'timezone','America/Sao_Paulo') as tz
    from queue_window_context q
  ), expanded as (
    select m.id as member_id,m.user_id,m.team_id,tm.id as team_member_id,m.position,m.weight,0 as kind,m.created_at
    from public.round_robin_members m join public.organization_members om on om.organization_id=m.organization_id and om.user_id=m.user_id
      and om.is_active and om.deleted_at is null and om.membership_generation=m.membership_generation
    join public.users u on u.id=m.user_id and u.is_active
    left join public.teams t on t.id=m.team_id and t.organization_id=m.organization_id and coalesce(t.is_active,true)
    left join public.team_members tm on tm.team_id=m.team_id and tm.organization_id=m.organization_id and tm.user_id=m.user_id
      and coalesce(tm.is_active,true) and tm.membership_generation=om.membership_generation
    where m.organization_id=p_org and m.round_robin_id=p_queue and coalesce(m.is_active,true) and m.user_id is not null
      and (m.team_id is null or (t.id is not null and tm.id is not null))
    union all
    select m.id,tm.user_id,m.team_id,tm.id,m.position,m.weight,1,tm.created_at
    from public.round_robin_members m join public.teams t on t.id=m.team_id and t.organization_id=m.organization_id and coalesce(t.is_active,true)
    join public.team_members tm on tm.team_id=m.team_id and tm.organization_id=m.organization_id and coalesce(tm.is_active,true)
    join public.organization_members om on om.organization_id=tm.organization_id and om.user_id=tm.user_id and om.is_active
      and om.deleted_at is null and om.membership_generation=tm.membership_generation
    join public.users u on u.id=tm.user_id and u.is_active
    where m.organization_id=p_org and m.round_robin_id=p_queue and coalesce(m.is_active,true) and m.user_id is null
  ), availability as (
    select e.*,w.starts_at,w.ends_at,
      coalesce((q.operating_window->>'valid')::boolean,false)
        and (e.team_member_id is null or w.starts_at is not null) as is_available,
      coalesce(q.operating_window->>'windowKey','closed') as queue_window_key
    from expanded e cross join queue q
    left join lateral (
      select min(v.starts_at) as starts_at,max(v.ends_at) as ends_at from (
        select ((p_now at time zone q.tz)::date+offset_day + case when coalesce(a.is_all_day,false) then time '00:00' else a.start_time end) at time zone q.tz as starts_at,
          ((p_now at time zone q.tz)::date+offset_day+case when coalesce(a.is_all_day,false) or a.start_time>a.end_time then 1 else 0 end
            +case when coalesce(a.is_all_day,false) then time '00:00' else a.end_time end) at time zone q.tz as ends_at
        from public.member_availability a cross join generate_series(-1,0) offset_day
        where a.organization_id=p_org and a.team_member_id=e.team_member_id and coalesce(a.is_active,true)
          and a.day_of_week=extract(dow from (p_now at time zone q.tz)::date+offset_day)::integer
      ) v where v.starts_at<=p_now and v.ends_at>p_now
    ) w on true
  ), ranked as (
    select a.*,row_number() over(partition by a.user_id order by a.is_available desc,a.kind,a.position,a.created_at,a.member_id,a.team_member_id) as rank
    from availability a
  ) select r.member_id,r.user_id,r.team_id,r.team_member_id,r.position,r.weight,r.is_available,
      r.queue_window_key||':'||coalesce(r.starts_at::text,'direct'),r.ends_at
    from ranked r where r.rank=1;
$$;


ALTER FUNCTION private.queue_runtime_members(p_org uuid, p_queue uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: queue_runtime_meta_initial_pending_proven(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_meta_initial_pending_proven(p_org uuid, p_lead uuid, p_queue uuid, p_job uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.lead_redistribution_jobs j
    join public.leads l on l.organization_id=p_org and l.id=p_lead
    join public.lead_entry_events entry on entry.organization_id=p_org and entry.lead_id=p_lead
      and entry.provider='meta' and entry.source='meta' and entry.entry_type='initial' and entry.is_countable
      and entry.provider_event_id=j.metadata->>'leadgen_id'
      and entry.form_id=j.metadata->>'form_id' and entry.page_id=j.metadata->>'page_id'
    where j.organization_id=p_org and j.lead_id=p_lead and j.round_robin_id=p_queue and j.id=p_job
      and nullif(btrim(j.metadata->>'leadgen_id'),'') is not null
      and nullif(btrim(j.metadata->>'form_id'),'') is not null and nullif(btrim(j.metadata->>'page_id'),'') is not null
      and (l.origin_round_robin_id is null or l.origin_round_robin_id=p_queue)
      and nullif(btrim(entry.metadata->>'integration_id'),'') is not null
      and exists(select 1 from private.lead_distribution_events e where e.organization_id=p_org and e.lead_id=p_lead
        and e.round_robin_id=p_queue and e.outcome='no_available_members'
        and e.idempotency_key='meta:'||encode(sha256(convert_to(format('[%s,%s]',
          to_json(entry.metadata->>'integration_id'),to_json(entry.provider_event_id)),'UTF8')),'hex'))
      and exists(select 1 from public.lead_entry_events current_entry where current_entry.organization_id=p_org
        and current_entry.lead_id=p_lead and current_entry.provider='meta' and current_entry.is_countable
        and current_entry.id=(select latest.id from public.lead_entry_events latest where latest.organization_id=p_org
          and latest.lead_id=p_lead and latest.is_countable
          order by coalesce(latest.occurred_at,latest.created_at) desc,latest.provider_event_id desc nulls last,latest.created_at desc,latest.id desc limit 1)
        and nullif(btrim(current_entry.metadata->>'integration_id'),'') is not null
        and exists(select 1 from private.lead_distribution_events e where e.organization_id=p_org and e.lead_id=p_lead
          and e.round_robin_id=p_queue and e.outcome='no_available_members'
          and e.idempotency_key='meta:'||encode(sha256(convert_to(format('[%s,%s]',
            to_json(current_entry.metadata->>'integration_id'),to_json(current_entry.provider_event_id)),'UTF8')),'hex'))));
$$;


ALTER FUNCTION private.queue_runtime_meta_initial_pending_proven(p_org uuid, p_lead uuid, p_queue uuid, p_job uuid) OWNER TO postgres;

--
-- Name: queue_runtime_pool(uuid, uuid, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_pool(p_org uuid, p_lead uuid, p_reason text, p_now timestamp with time zone, p_window jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r private.queue_lead_runtime%rowtype; previous_user uuid; real_entry boolean;
begin
  select * into r from private.queue_lead_runtime where organization_id=p_org and lead_id=p_lead for update;
  select assigned_user_id into previous_user from public.leads where organization_id=p_org and id=p_lead;
  real_entry := previous_user is not null or r.entered_pool_at is null;
  insert into private.queue_runtime_commands values(txid_current(),p_org,p_lead,'automatic',null)
    on conflict(transaction_id,organization_id,lead_id) do update set mode='automatic',actor_id=null;
  update public.leads set assigned_user_id=null,assigned_at=null,updated_at=p_now
    where organization_id=p_org and id=p_lead and assigned_user_id is not null;
  update private.queue_lead_runtime set state=case when p_reason='queue_limit_reached' then 'limit_exhausted'
      when coalesce((p_window->>'open')::boolean,false) then 'pool_ready' else 'pool_waiting' end,
    reason=p_reason,revision=revision+case when real_entry then 1 else 0 end,
    entered_pool_at=coalesce(entered_pool_at,p_now),released_at=case when real_entry then p_now else released_at end,
    due_at=null,next_action_at=case when p_reason='queue_limit_reached' then null
      when p_window->>'nextOpensAt' is not null and not coalesce((p_window->>'open')::boolean,false)
        then least((p_window->>'nextOpensAt')::timestamptz,p_now+interval '30 seconds') else p_now+interval '30 seconds' end,updated_at=p_now
    where organization_id=p_org and lead_id=p_lead returning * into r;
  delete from private.queue_runtime_commands where transaction_id=txid_current() and organization_id=p_org and lead_id=p_lead;
  if real_entry then
    insert into private.queue_runtime_events(organization_id,lead_id,round_robin_id,episode_id,round_number,event_type,from_user_id,metadata,created_at)
      values(p_org,p_lead,r.round_robin_id,r.episode_id,r.round_number,'entered_pool',previous_user,jsonb_build_object('reason',p_reason,'revision',r.revision),p_now);
    perform private.enqueue_queue_pool_alert(p_org,p_lead,r.episode_id,r.revision);
  end if;
  return jsonb_build_object('success',false,'reason',case when p_reason='queue_closed' then 'queue_closed'
    when p_reason='queue_limit_reached' then 'queue_limit_reached' else 'pooled' end,'lead_id',p_lead,'round_robin_id',r.round_robin_id);
end;
$$;


ALTER FUNCTION private.queue_runtime_pool(p_org uuid, p_lead uuid, p_reason text, p_now timestamp with time zone, p_window jsonb) OWNER TO postgres;

--
-- Name: queue_runtime_redistribute(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_redistribute(p_org uuid, p_lead uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare queue_id uuid;
begin
  select coalesce(r.round_robin_id,l.origin_round_robin_id) into queue_id from public.leads l
    left join private.queue_lead_runtime r on r.organization_id=l.organization_id and r.lead_id=l.id
    where l.organization_id=p_org and l.id=p_lead;
  if private.queue_runtime_is_managed(p_org,queue_id) then
    perform 1 from public.round_robins where organization_id=p_org and id=queue_id for share skip locked;
    if not found then return jsonb_build_object('success',false,'reason','queue_busy'); end if;
  end if;
  return private.queue_runtime_redistribute_before_concurrency_guard(p_org,p_lead,p_actor);
end;
$$;


ALTER FUNCTION private.queue_runtime_redistribute(p_org uuid, p_lead uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_runtime_redistribute_before_concurrency_guard(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_redistribute_before_concurrency_guard(p_org uuid, p_lead uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare qid uuid;
begin
  select coalesce((select r.round_robin_id from private.queue_lead_runtime r where r.organization_id=p_org and r.lead_id=l.id),l.origin_round_robin_id)
    into qid from public.leads l where l.organization_id=p_org and l.id=p_lead;
  if qid is null or not private.queue_runtime_is_managed(p_org,qid) then return jsonb_build_object('success',false,'reason','legacy_queue'); end if;
  if not private.queue_runtime_actor_can_claim(p_org,p_actor) then return jsonb_build_object('success',false,'reason','forbidden'); end if;
  if private.queue_pool_read_access(p_org,p_lead,p_actor) is not null then return jsonb_build_object('success',false,'reason','queue_protected','lead_id',p_lead); end if;
  if not exists(select 1 from private.queue_lead_runtime where organization_id=p_org and lead_id=p_lead) then
    perform private.queue_runtime_enroll(p_org,p_lead,qid,clock_timestamp()); end if;
  return private.queue_runtime_step(p_org,p_lead,clock_timestamp(),true,p_actor);
end;
$$;


ALTER FUNCTION private.queue_runtime_redistribute_before_concurrency_guard(p_org uuid, p_lead uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_runtime_step(uuid, uuid, timestamp with time zone, boolean, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_step(p_org uuid, p_lead uuid, p_now timestamp with time zone, p_force boolean DEFAULT false, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r private.queue_lead_runtime%rowtype; l public.leads%rowtype; w jsonb; c record; qid uuid; next_round integer;
  current_available boolean; current_available_until timestamptz; settings jsonb; warning_minutes integer; timeout_minutes integer; timeout_enabled boolean;
begin
  select round_robin_id into qid from private.queue_lead_runtime where organization_id=p_org and lead_id=p_lead;
  if not found then return jsonb_build_object('success',false,'reason','not_found'); end if;
  perform 1 from public.round_robins where organization_id=p_org and id=qid for share skip locked;
  if not found then return jsonb_build_object('success',false,'reason','queue_busy'); end if;
  select * into l from public.leads where organization_id=p_org and id=p_lead for no key update skip locked;
  if not found then return jsonb_build_object('success',false,'reason','queue_busy'); end if;
  select * into r from private.queue_lead_runtime where organization_id=p_org and lead_id=p_lead for update;
  if r.quarantined_at is not null and p_actor is null then return jsonb_build_object('success',false,'reason','queue_protected','lead_id',p_lead); end if;
  if r.state in ('manual_protected','human_protected','closed') then return jsonb_build_object('success',false,'reason','queue_protected','lead_id',p_lead); end if;
  if coalesce(l.deal_status,'open')<>'open' then
    update private.queue_lead_runtime set state='closed',reason='deal_closed',next_action_at=null,revision=revision+1 where organization_id=p_org and lead_id=p_lead;
    return jsonb_build_object('success',false,'reason','queue_protected','lead_id',p_lead); end if;
  if private.queue_runtime_has_human_activity(p_org,p_lead,r.baseline_at) then
    update private.queue_lead_runtime set state='human_protected',reason='human_action',next_action_at=null,revision=revision+1 where organization_id=p_org and lead_id=p_lead;
    return jsonb_build_object('success',false,'reason','queue_protected','lead_id',p_lead); end if;
  w:=private.queue_window(p_org,qid,p_now);
  if not coalesce((w->>'open')::boolean,false) then return private.queue_runtime_pool(p_org,p_lead,'queue_closed',p_now,w); end if;
  -- Reconcile a closing boundary missed during worker downtime before resuming
  -- the current open window. Adjacent all-day windows have no closed gap.
  if l.assigned_user_id is not null and r.last_queue_close_at<p_now
    and not coalesce((private.queue_window(p_org,qid,r.last_queue_close_at)->>'open')::boolean,false) then
    return private.queue_runtime_pool(p_org,p_lead,'queue_closed',p_now,w); end if;
  if l.assigned_user_id is not null and r.last_member_close_at<p_now and not exists(
    select 1 from private.queue_runtime_members(p_org,qid,r.last_member_close_at)m where m.user_id=l.assigned_user_id and m.is_available) then
    return private.queue_runtime_pool(p_org,p_lead,'member_unavailable',p_now,w); end if;
  if r.state='limit_exhausted' then return jsonb_build_object('success',false,'reason','queue_limit_reached','lead_id',p_lead); end if;
  select count(*)>0,max(m.available_until) into current_available,current_available_until from private.queue_runtime_members(p_org,qid,p_now) m where m.user_id=l.assigned_user_id and m.is_available;
  select q.settings into settings from public.round_robins q where q.organization_id=p_org and q.id=qid;
  timeout_enabled:=coalesce((settings->>'enable_redistribution')::boolean,false);
  timeout_minutes:=coalesce((settings->>'redistribution_timeout_minutes')::integer,20);
  warning_minutes:=coalesce((settings->>'redistribution_warning_minutes')::integer,0);
  if l.assigned_user_id is not null and current_available and not p_force and (r.due_at>p_now or not timeout_enabled) then
    if timeout_enabled and timeout_minutes>5 and warning_minutes>0 and warning_minutes<timeout_minutes
      and r.warning_sent_at is null and r.due_at>p_now and p_now>=r.due_at-make_interval(mins=>warning_minutes) then
      insert into public.notifications(organization_id,user_id,lead_id,type,title,content,body,metadata,channel,target_url)
        values(p_org,l.assigned_user_id,p_lead,'lead_redistribution_warning','Prazo de atendimento','O prazo de atendimento está próximo.',
          'O prazo de atendimento está próximo.',private.queue_runtime_dispatch_metadata(jsonb_build_object('event_key','lead_redistribution_warning','round_robin_id',qid,
            'episode_id',r.episode_id,'revision',r.revision,'assigned_at',r.assigned_at,'due_at',r.due_at,
            'dedupe_key','queue_warning:'||r.episode_id::text||':'||r.revision::text)),'in_app','/crm/pipelines?lead='||p_lead::text);
      update private.queue_lead_runtime set warning_sent_at=p_now where organization_id=p_org and lead_id=p_lead;
    end if;
    update private.queue_lead_runtime set last_queue_close_at=(w->>'closesAt')::timestamptz,last_member_close_at=current_available_until,
      next_action_at=least(case when timeout_enabled and r.due_at>p_now then r.due_at end,(w->>'closesAt')::timestamptz,current_available_until,
      case when timeout_enabled and timeout_minutes>5 and warning_minutes>0 and r.warning_sent_at is null and p_now<r.due_at-make_interval(mins=>warning_minutes)
        then r.due_at-make_interval(mins=>warning_minutes) else p_now+interval '30 seconds' end) where organization_id=p_org and lead_id=p_lead;
    return jsonb_build_object('success',false,'reason','queue_waiting','lead_id',p_lead); end if;
  next_round:=r.round_number;
  select m.* into c from private.queue_runtime_members(p_org,qid,p_now) m
    where m.is_available and m.user_id is distinct from r.last_user_id and not exists(select 1 from private.queue_round_visits v
      where v.organization_id=p_org and v.lead_id=p_lead and v.episode_id=r.episode_id and v.round_number=r.round_number and v.user_id=m.user_id)
    order by (m.position>r.last_position or (m.position=r.last_position and m.user_id>r.last_user_id)) desc,m.position,m.user_id limit 1;
  if not found then
    select m.* into c from private.queue_runtime_members(p_org,qid,p_now) m where m.is_available and m.user_id is distinct from r.last_user_id
      order by (m.position>r.last_position or (m.position=r.last_position and m.user_id>r.last_user_id)) desc,m.position,m.user_id limit 1;
    if found then next_round:=r.round_number+1;
    elsif l.assigned_user_id is null and r.released_at is not null and r.reason in ('queue_closed','member_unavailable','no_available_members') then
      select m.* into c from private.queue_runtime_members(p_org,qid,p_now) m where m.is_available and m.user_id=r.last_user_id
        and m.window_key is distinct from r.last_window_key limit 1;
      if found then next_round:=r.round_number+1; end if;
    end if;
  end if;
  if c.user_id is null then
    if l.assigned_user_id is not null and current_available then
      update private.queue_lead_runtime set next_action_at=least(p_now+interval '30 seconds',(w->>'closesAt')::timestamptz,current_available_until),reason='waiting_for_alternative' where organization_id=p_org and lead_id=p_lead;
      return jsonb_build_object('success',false,'reason','queue_waiting','lead_id',p_lead);
    end if;
    return private.queue_runtime_pool(p_org,p_lead,case when l.assigned_user_id is null then r.reason else 'member_unavailable' end,p_now,w);
  end if;
  if r.max_assignments>0 and r.assignment_count>=r.max_assignments then return private.queue_runtime_pool(p_org,p_lead,'queue_limit_reached',p_now,w); end if;
  return private.queue_runtime_assign(p_org,p_lead,c.user_id,c.team_id,c.member_id,c.position,c.window_key,next_round,p_now,p_actor);
end;
$$;


ALTER FUNCTION private.queue_runtime_step(p_org uuid, p_lead uuid, p_now timestamp with time zone, p_force boolean, p_actor uuid) OWNER TO postgres;

--
-- Name: queue_runtime_warning_guard(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_runtime_warning_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.timeout_minutes<=5 then new.warning_minutes:=0; new.warning_due_at:=null; end if;
  if new.warning_minutes>0 and new.warning_minutes>=new.timeout_minutes then raise exception using errcode='23514',message='invalid_queue_redistribution_warning'; end if;
  if new.status in ('pending','warning_sent') and exists(select 1 from private.queue_lead_runtime r
    where r.organization_id=new.organization_id and r.lead_id=new.lead_id) then
    new.status:='stopped';new.stopped_reason:='managed_queue_runtime';new.stopped_at:=clock_timestamp();new.warning_due_at:=null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.queue_runtime_warning_guard() OWNER TO postgres;

--
-- Name: queue_schedule_valid(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_schedule_valid(p_schedule jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare d jsonb; seen integer[] := '{}'; active_days integer := 0; n integer;
begin
  if jsonb_typeof(p_schedule) is distinct from 'object'
    or p_schedule->'version' is distinct from '1'::jsonb
    or jsonb_typeof(p_schedule->'timezone') is distinct from 'string'
    or not private.queue_timezone_name_valid(p_schedule->>'timezone')
    or jsonb_typeof(p_schedule->'days') is distinct from 'array'
    or jsonb_array_length(p_schedule->'days') <> 7 then return false; end if;
  for d in select value from jsonb_array_elements(p_schedule->'days') loop
    if jsonb_typeof(d) <> 'object' or coalesce(d->>'day_of_week','') !~ '^[0-6]$'
      or jsonb_typeof(d->'is_active') is distinct from 'boolean'
      or jsonb_typeof(d->'is_all_day') is distinct from 'boolean' then return false; end if;
    n := (d->>'day_of_week')::integer;
    if n = any(seen) then return false; end if;
    seen := array_append(seen,n);
    if (d->>'is_active')::boolean then active_days := active_days + 1; end if;
    if not (d->>'is_all_day')::boolean then
      if (d->>'is_active')::boolean and (
        coalesce(d->>'start_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
        or coalesce(d->>'end_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
      ) then return false; end if;
      if d->>'start_time' is not null and d->>'start_time' !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
        or d->>'end_time' is not null and d->>'end_time' !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' then return false; end if;
      if (d->>'is_active')::boolean and (d->>'start_time')::time = (d->>'end_time')::time then return false; end if;
    end if;
  end loop;
  return true;
exception when others then return false;
end;
$_$;


ALTER FUNCTION private.queue_schedule_valid(p_schedule jsonb) OWNER TO postgres;

--
-- Name: queue_timezone_name_valid(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_timezone_name_valid(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from private.queue_timezone_catalog where name=p_name);
$$;


ALTER FUNCTION private.queue_timezone_name_valid(p_name text) OWNER TO postgres;

--
-- Name: queue_window(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.queue_window(p_organization_id uuid, p_round_robin_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare q public.round_robins%rowtype; s jsonb; tz text; local_date date;
  opens timestamptz; closes timestamptz; next_opens timestamptz;
begin
  select * into q from public.round_robins where organization_id=p_organization_id and id=p_round_robin_id;
  if not found then return jsonb_build_object('managed',false,'open',false,'valid',false,'reason','queue_not_found'); end if;
  if not (q.settings ? 'operating_schedule') then
    return jsonb_build_object('managed',false,'open',coalesce(q.is_active,true),'valid',true,'reason','legacy');
  end if;
  s := q.settings->'operating_schedule';
  if not private.queue_schedule_valid(s) then
    return jsonb_build_object('managed',true,'open',false,'valid',false,'reason','invalid_schedule');
  end if;
  tz := s->>'timezone'; local_date := (p_now at time zone tz)::date;
  with windows as (
    select ((local_date + offset_day) + case when (d->>'is_all_day')::boolean then time '00:00' else (d->>'start_time')::time end) at time zone tz as starts_at,
      ((local_date + offset_day + case when (d->>'is_all_day')::boolean or (d->>'start_time')::time > (d->>'end_time')::time then 1 else 0 end)
        + case when (d->>'is_all_day')::boolean then time '00:00' else (d->>'end_time')::time end) at time zone tz as ends_at
    from generate_series(-1,8) offset_day cross join jsonb_array_elements(s->'days') d
    where (d->>'is_active')::boolean and extract(dow from local_date + offset_day)::integer=(d->>'day_of_week')::integer
  ) select min(starts_at) filter(where starts_at<=p_now and ends_at>p_now),
    max(ends_at) filter(where starts_at<=p_now and ends_at>p_now), min(starts_at) filter(where starts_at>p_now)
    into opens,closes,next_opens from windows;
  return jsonb_build_object('managed',true,'valid',true,
    'open',coalesce(q.is_active,true) and q.deleted_at is null and opens is not null,
    'reason',case when not coalesce(q.is_active,true) or q.deleted_at is not null then 'queue_inactive' when opens is null then 'queue_closed' else 'queue_open' end,
    'timezone',tz,'opensAt',opens,'closesAt',closes,'nextOpensAt',next_opens,
    'windowKey',case when opens is null then null else p_round_robin_id::text||':'||opens::text end);
end;
$$;


ALTER FUNCTION private.queue_window(p_organization_id uuid, p_round_robin_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: read_whatsapp_webhook_pn_route_quarantine(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.read_whatsapp_webhook_pn_route_quarantine(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select inbox.payload #> '{__vimob_ingress,identity_quarantined_provider_message_ids}'
  from public.whatsapp_webhook_inbox inbox
  join private.whatsapp_webhook_ignored_events ignored
    on ignored.organization_id=inbox.organization_id and ignored.session_id=inbox.session_id
   and ignored.event_key=inbox.event_key and ignored.reason='whatsapp_contact_pn_route_conflict'
  where inbox.id=p_inbox_id and inbox.organization_id=p_organization_id and inbox.session_id=p_session_id
    and inbox.provider='evolution_go' and inbox.status='processing'
    and inbox.edge_execution_id=p_execution_id and inbox.edge_execution_state='active'
    and inbox.payload #>> '{__vimob_ingress,identity_quarantine_reason}'='whatsapp_contact_pn_route_conflict'
    and jsonb_typeof(inbox.payload #> '{__vimob_ingress,identity_quarantined_provider_message_ids}')='array'
    and not exists(select 1 from jsonb_array_elements(case when jsonb_typeof(inbox.payload #> '{__vimob_ingress,identity_quarantined_provider_message_ids}')='array'
      then inbox.payload #> '{__vimob_ingress,identity_quarantined_provider_message_ids}' else '[]'::jsonb end) candidate(value)
      where jsonb_typeof(candidate.value)<>'string' or octet_length(candidate.value #>> '{}') not between 1 and 200
        or (candidate.value #>> '{}') ~ '[[:cntrl:]]');
$$;


ALTER FUNCTION private.read_whatsapp_webhook_pn_route_quarantine(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid) OWNER TO postgres;

--
-- Name: reconcile_asaas_payment_webhook_unordered_legacy(text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reconcile_asaas_payment_webhook_unordered_legacy(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_event_id text := btrim(coalesce(p_event_id, ''));
  v_event_type text := upper(btrim(coalesce(p_event_type, '')));
  v_event_at timestamptz := coalesce(p_event_at, now());
  v_payment_id text := btrim(coalesce(p_payment ->> 'id', ''));
  v_customer_id text := nullif(btrim(coalesce(p_payment ->> 'customer', '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_payment ->> 'subscription', '')), '');
  v_external_reference text := nullif(btrim(coalesce(p_payment ->> 'externalReference', '')), '');
  v_payment_status text := upper(nullif(btrim(coalesce(p_payment ->> 'status', '')), ''));
  v_billing_type text := upper(nullif(btrim(coalesce(p_payment ->> 'billingType', '')), ''));
  v_due_date date;
  v_payment_date date;
  v_value numeric;
  v_net_value numeric;
  v_invoice_url text := nullif(btrim(coalesce(p_payment ->> 'invoiceUrl', '')), '');
  v_organization_id uuid;
  v_existing_organization_id uuid;
  v_existing_customer_id text;
  v_existing_subscription_id text;
  v_existing_event_at timestamptz;
  v_current_organization_status text;
  v_current_org_customer_id text;
  v_current_org_subscription_id text;
  v_new_organization_status text;
  v_org_event_is_stale boolean := false;
  v_payment_event_is_stale boolean := false;
  v_should_advance_org_event boolean := false;
  v_inserted integer := 0;
begin
  if char_length(v_event_id) not between 1 and 512 then
    raise exception using
      errcode = '22023',
      message = 'Invalid Asaas webhook event id';
  end if;

  if left(v_event_type, 8) <> 'PAYMENT_' then
    raise exception using
      errcode = '22023',
      message = 'Unsupported Asaas webhook event type';
  end if;

  if jsonb_typeof(p_payment) is distinct from 'object' or char_length(v_payment_id) not between 1 and 255 then
    raise exception using
      errcode = '22023',
      message = 'Invalid Asaas webhook payment payload';
  end if;

  if jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception using
      errcode = '22023',
      message = 'Invalid Asaas webhook payload';
  end if;

  if coalesce(p_payment ->> 'dueDate', '') ~ '^\d{4}-\d{2}-\d{2}$' then
    v_due_date := (p_payment ->> 'dueDate')::date;
  end if;

  if coalesce(p_payment ->> 'paymentDate', '') ~ '^\d{4}-\d{2}-\d{2}$' then
    v_payment_date := (p_payment ->> 'paymentDate')::date;
  end if;

  if jsonb_typeof(p_payment -> 'value') = 'number' then
    v_value := (p_payment ->> 'value')::numeric;
  end if;

  if jsonb_typeof(p_payment -> 'netValue') = 'number' then
    v_net_value := (p_payment ->> 'netValue')::numeric;
  end if;

  select
    organization_id,
    asaas_customer_id,
    asaas_subscription_id,
    greatest(last_webhook_event_at, last_provider_observed_at)
  into
    v_existing_organization_id,
    v_existing_customer_id,
    v_existing_subscription_id,
    v_existing_event_at
  from public.asaas_payments
  where asaas_payment_id = v_payment_id
  for update;

  if found then
    if v_customer_id is not null
      and v_existing_customer_id is not null
      and v_customer_id <> v_existing_customer_id
    then
      raise exception using
        errcode = '22023',
        message = 'Asaas customer does not match the existing payment';
    end if;

    if v_subscription_id is not null
      and v_existing_subscription_id is not null
      and v_subscription_id <> v_existing_subscription_id
    then
      raise exception using
        errcode = '22023',
        message = 'Asaas subscription does not match the existing payment';
    end if;

    v_organization_id := v_existing_organization_id;
  end if;

  if v_organization_id is null
    and v_external_reference ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    select id
    into v_organization_id
    from public.organizations
    where id = v_external_reference::uuid
      and (asaas_customer_id is null or v_customer_id is null or asaas_customer_id = v_customer_id)
      and (asaas_subscription_id is null or v_subscription_id is null or asaas_subscription_id = v_subscription_id);
  end if;

  if v_organization_id is null and v_subscription_id is not null then
    select case when count(*) = 1 then min(id::text)::uuid end
    into v_organization_id
    from public.organizations
    where asaas_subscription_id = v_subscription_id;
  end if;

  if v_organization_id is null and v_subscription_id is null and v_customer_id is not null then
    select case when count(*) = 1 then min(id::text)::uuid end
    into v_organization_id
    from public.organizations
    where asaas_customer_id = v_customer_id;
  end if;

  if v_organization_id is null then
    insert into private.asaas_webhook_events (
      event_id,
      event_type,
      resource_type,
      resource_id,
      organization_id,
      provider_event_at,
      outcome,
      payload
    )
    values (
      v_event_id,
      v_event_type,
      'payment',
      v_payment_id,
      null,
      v_event_at,
      'unmatched',
      p_payload
    )
    on conflict (event_id) do nothing;

    get diagnostics v_inserted = row_count;

    return jsonb_build_object(
      'outcome', case when v_inserted = 0 then 'duplicate' else 'unmatched' end,
      'event_id', v_event_id,
      'payment_id', v_payment_id
    );
  end if;

  insert into private.asaas_webhook_events (
    event_id,
    event_type,
    resource_type,
    resource_id,
    organization_id,
    provider_event_at,
    outcome,
    payload
  )
  values (
    v_event_id,
    v_event_type,
    'payment',
    v_payment_id,
    v_organization_id,
    v_event_at,
    'processed',
    p_payload
  )
  on conflict (event_id) do nothing;

  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    return jsonb_build_object(
      'outcome', 'duplicate',
      'event_id', v_event_id,
      'payment_id', v_payment_id,
      'organization_id', v_organization_id
    );
  end if;

  v_payment_event_is_stale :=
    v_existing_event_at is not null
    and v_event_at < v_existing_event_at;

  if v_event_type = 'PAYMENT_CONFIRMED' then
    v_payment_status := 'CONFIRMED';
  elsif v_event_type = 'PAYMENT_RECEIVED' then
    v_payment_status := 'RECEIVED';
  elsif v_event_type = 'PAYMENT_OVERDUE' then
    v_payment_status := 'OVERDUE';
  elsif v_event_type = 'PAYMENT_DELETED' then
    v_payment_status := 'DELETED';
  elsif v_event_type = 'PAYMENT_REFUNDED' then
    v_payment_status := 'REFUNDED';
  elsif v_event_type = 'PAYMENT_REFUND_REQUESTED' then
    v_payment_status := 'REFUND_REQUESTED';
  elsif v_event_type = 'PAYMENT_REFUND_IN_PROGRESS' then
    v_payment_status := 'REFUND_IN_PROGRESS';
  elsif v_event_type = 'PAYMENT_PARTIALLY_REFUNDED' then
    v_payment_status := 'PARTIALLY_REFUNDED';
  elsif v_event_type = 'PAYMENT_RECEIVED_IN_CASH_UNDONE' then
    v_payment_status := 'RECEIVED_IN_CASH_UNDONE';
  elsif v_event_type = 'PAYMENT_CHARGEBACK_REQUESTED' then
    v_payment_status := 'CHARGEBACK_REQUESTED';
  elsif v_event_type = 'PAYMENT_CHARGEBACK_DISPUTE' then
    v_payment_status := 'CHARGEBACK_DISPUTE';
  elsif v_event_type = 'PAYMENT_AWAITING_CHARGEBACK_REVERSAL' then
    v_payment_status := 'AWAITING_CHARGEBACK_REVERSAL';
  elsif v_event_type = 'PAYMENT_CREDIT_CARD_CAPTURE_REFUSED' then
    v_payment_status := 'CREDIT_CARD_CAPTURE_REFUSED';
  elsif v_payment_status is null then
    v_payment_status := replace(v_event_type, 'PAYMENT_', '');
  end if;

  if not v_payment_event_is_stale then
    insert into public.asaas_payments (
      organization_id,
      asaas_payment_id,
      asaas_customer_id,
      asaas_subscription_id,
      status,
      billing_type,
      value,
      net_value,
      due_date,
      payment_date,
      invoice_url,
      raw_event,
      last_webhook_event_id,
      last_webhook_event_at
    )
    values (
      v_organization_id,
      v_payment_id,
      v_customer_id,
      v_subscription_id,
      v_payment_status,
      v_billing_type,
      v_value,
      v_net_value,
      v_due_date,
      v_payment_date,
      v_invoice_url,
      p_payload,
      v_event_id,
      v_event_at
    )
    on conflict (asaas_payment_id) do update
    set
      asaas_customer_id = coalesce(excluded.asaas_customer_id, public.asaas_payments.asaas_customer_id),
      asaas_subscription_id = coalesce(excluded.asaas_subscription_id, public.asaas_payments.asaas_subscription_id),
      status = excluded.status,
      billing_type = coalesce(excluded.billing_type, public.asaas_payments.billing_type),
      value = coalesce(excluded.value, public.asaas_payments.value),
      net_value = coalesce(excluded.net_value, public.asaas_payments.net_value),
      due_date = coalesce(excluded.due_date, public.asaas_payments.due_date),
      payment_date = coalesce(excluded.payment_date, public.asaas_payments.payment_date),
      invoice_url = coalesce(excluded.invoice_url, public.asaas_payments.invoice_url),
      raw_event = excluded.raw_event,
      last_webhook_event_id = excluded.last_webhook_event_id,
      last_webhook_event_at = excluded.last_webhook_event_at,
      updated_at = now()
    where excluded.last_webhook_event_at >= coalesce(
      greatest(
        public.asaas_payments.last_webhook_event_at,
        public.asaas_payments.last_provider_observed_at
      ),
      '-infinity'::timestamptz
    );

    get diagnostics v_inserted = row_count;
    if v_inserted = 0 then
      v_payment_event_is_stale := true;
      update private.asaas_webhook_events
      set outcome = 'stale'
      where event_id = v_event_id;
    end if;
  else
    update private.asaas_webhook_events
    set outcome = 'stale'
    where event_id = v_event_id;
  end if;

  select
    subscription_status,
    asaas_customer_id,
    asaas_subscription_id,
    greatest(
      asaas_last_event_at,
      billing_last_reconciled_at
    ) > v_event_at
  into
    v_current_organization_status,
    v_current_org_customer_id,
    v_current_org_subscription_id,
    v_org_event_is_stale
  from public.organizations
  where id = v_organization_id
  for update;

  v_org_event_is_stale := coalesce(v_org_event_is_stale, false);
  if (
    v_subscription_id is not null
    and v_current_org_subscription_id is not null
    and v_subscription_id <> v_current_org_subscription_id
  ) or (
    v_customer_id is not null
    and v_current_org_customer_id is not null
    and v_customer_id <> v_current_org_customer_id
  ) then
    v_org_event_is_stale := true;
  end if;

  -- The outer period-intent wrapper only confirms checkout intents for a
  -- processed event. Treat a payment observed after explicit cancellation as
  -- non-applicable to the organization so an orphaned intent cannot revive it.
  if v_current_organization_status in (
    'suspended',
    'cancelled',
    'canceled'
  ) then
    v_org_event_is_stale := true;
  end if;

  v_new_organization_status := v_current_organization_status;

  if v_org_event_is_stale then
    update private.asaas_webhook_events
    set outcome = 'stale'
    where event_id = v_event_id;
  end if;

  if not v_org_event_is_stale and not v_payment_event_is_stale then
    if v_current_organization_status in (
      'suspended',
      'cancelled',
      'canceled'
    ) then
      -- A new checkout first moves an eligible tenant to pending_payment.
      -- Provider payment events cannot revive a terminal tenant by themselves.
      v_new_organization_status := v_current_organization_status;
    elsif v_payment_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH') then
      v_new_organization_status := 'active';
    elsif v_payment_status in ('OVERDUE', 'CREDIT_CARD_CAPTURE_REFUSED') then
      v_new_organization_status := 'overdue';
    elsif v_payment_status in (
      'REFUNDED',
      'REFUND_REQUESTED',
      'REFUND_IN_PROGRESS',
      'PARTIALLY_REFUNDED',
      'RECEIVED_IN_CASH_UNDONE',
      'CHARGEBACK_REQUESTED',
      'CHARGEBACK_DISPUTE',
      'AWAITING_CHARGEBACK_REVERSAL'
    ) then
      v_new_organization_status := 'suspended';
    elsif v_payment_status in ('DELETED', 'CANCELED', 'CANCELLED') then
      if v_current_organization_status not in ('active', 'trial') then
        v_new_organization_status := 'pending_payment';
      end if;
    elsif v_current_organization_status not in ('active', 'trial') then
      v_new_organization_status := 'pending_payment';
    end if;
  end if;

  v_should_advance_org_event :=
    not v_org_event_is_stale
    and not v_payment_event_is_stale
    and (
      v_new_organization_status is distinct from v_current_organization_status
      or v_payment_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH')
    );

  update public.organizations
  set
    asaas_customer_id = case
      when not v_org_event_is_stale then coalesce(asaas_customer_id, v_customer_id)
      else asaas_customer_id
    end,
    asaas_subscription_id = case
      when not v_org_event_is_stale then coalesce(asaas_subscription_id, v_subscription_id)
      else asaas_subscription_id
    end,
    subscription_status = v_new_organization_status,
    next_billing_date = case
      when v_org_event_is_stale or v_payment_event_is_stale then next_billing_date
      else case
        when v_payment_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH')
          then (
            coalesce(v_due_date, current_date)
            + case
                when exists (
                  select 1
                  from public.organizations billing_org
                  join public.admin_subscription_plans billing_plan
                    on billing_plan.id = billing_org.plan_id
                  where billing_org.id = v_organization_id
                    and billing_plan.billing_cycle = 'yearly'
                ) then interval '1 year'
                else interval '1 month'
              end
          )::date
        when v_payment_status = 'OVERDUE'
          then coalesce(v_due_date, next_billing_date)
        when v_payment_status in ('CREATED', 'PENDING')
          and v_due_date is not null
          then v_due_date
        else next_billing_date
      end
    end,
    asaas_last_event_id = case
      when v_should_advance_org_event then v_event_id
      else asaas_last_event_id
    end,
    asaas_last_event_at = case
      when v_should_advance_org_event then v_event_at
      else asaas_last_event_at
    end,
    updated_at = now()
  where id = v_organization_id;

  update public.subscriptions
  set
    status = case
      when not v_org_event_is_stale and not v_payment_event_is_stale
        then v_new_organization_status
      else status
    end,
    provider = 'asaas',
    provider_customer_id = case
      when not v_org_event_is_stale
        then coalesce(provider_customer_id, v_customer_id)
      else provider_customer_id
    end,
    provider_subscription_id = case
      when not v_org_event_is_stale
        then coalesce(provider_subscription_id, v_subscription_id)
      else provider_subscription_id
    end,
    current_period_start = case
      when not v_org_event_is_stale
        and not v_payment_event_is_stale
        and v_payment_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH')
        then coalesce(v_payment_date::timestamptz, current_period_start, now())
      else current_period_start
    end,
    current_period_end = case
      when not v_org_event_is_stale
        and not v_payment_event_is_stale
        and v_payment_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH')
        then coalesce(v_due_date::timestamptz, now())
          + case
              when exists (
                select 1
                from public.organizations billing_org
                join public.admin_subscription_plans billing_plan
                  on billing_plan.id = billing_org.plan_id
                where billing_org.id = v_organization_id
                  and billing_plan.billing_cycle = 'yearly'
              ) then interval '1 year'
              else interval '1 month'
            end
      else current_period_end
    end,
    canceled_at = case
      when not v_org_event_is_stale
        and not v_payment_event_is_stale
        and v_new_organization_status in ('cancelled', 'canceled')
        then now()
      else canceled_at
    end,
    metadata = case
      when not v_org_event_is_stale and not v_payment_event_is_stale
        then coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'asaas_last_event_id', v_event_id,
          'asaas_last_event_type', v_event_type,
          'asaas_last_event_at', v_event_at
        )
      else metadata
    end,
    updated_at = now()
  where organization_id = v_organization_id
    and (
      v_subscription_id is null
      or provider_subscription_id is null
      or provider_subscription_id = v_subscription_id
    );

  return jsonb_build_object(
    'outcome', case
      when v_payment_event_is_stale or v_org_event_is_stale then 'stale'
      else 'processed'
    end,
    'event_id', v_event_id,
    'payment_id', v_payment_id,
    'payment_status', v_payment_status,
    'organization_id', v_organization_id,
    'subscription_status', v_new_organization_status
  );
end;
$_$;


ALTER FUNCTION private.reconcile_asaas_payment_webhook_unordered_legacy(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_asaas_payment_webhook_unordered_legacy(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.reconcile_asaas_payment_webhook_unordered_legacy(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) IS 'Idempotently reconciles Asaas payment events; reversal states suspend access without reviving cancelled tenants.';


--
-- Name: reconcile_billing_payment_access_proof(uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reconcile_billing_payment_access_proof(p_organization_id uuid, p_provider_payment_id text, p_current_status text, p_proof_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment public.asaas_payments%rowtype;
  v_payment_cursor timestamptz;
  v_had_causes boolean := false;
  v_resolved integer := 0;
  v_current_status text := lower(btrim(coalesce(p_current_status, '')));
  v_proof_status text := upper(btrim(coalesce(p_proof_status, '')));
begin
  if p_organization_id is null
     or nullif(btrim(coalesce(p_provider_payment_id, '')), '') is null
     or not private.billing_payment_checkout_is_paid(v_proof_status) then
    return coalesce(nullif(v_current_status, ''), 'pending_payment');
  end if;
  if v_current_status in ('cancelled', 'canceled') then
    return v_current_status;
  end if;

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.organization_id = p_organization_id
    and payment.asaas_payment_id = btrim(p_provider_payment_id);
  if not found then
    return coalesce(nullif(v_current_status, ''), 'pending_payment');
  end if;

  select exists (
    select 1
    from private.billing_organization_access_causes as cause
    where cause.organization_id = p_organization_id
  ) into v_had_causes;

  if v_had_causes then
    delete from private.billing_organization_access_causes as cause
    using public.asaas_payments as cause_payment
    where cause.organization_id = p_organization_id
      and cause_payment.organization_id = cause.organization_id
      and cause_payment.asaas_payment_id = cause.provider_payment_id
      and (
        cause.provider_payment_id = v_payment.asaas_payment_id
        or (
          v_payment.billing_intent_id is not null
          and cause_payment.billing_intent_id = v_payment.billing_intent_id
        )
      )
      and cause.payment_status in (
        'CREATED',
        'PENDING',
        'AWAITING_RISK_ANALYSIS',
        'AUTHORIZED',
        'PROCESSING',
        'OVERDUE',
        'DUNNING_REQUESTED',
        'DUNNING_RECEIVED',
        'BANK_SLIP_CANCELLED',
        'CREDIT_CARD_CAPTURE_REFUSED',
        'REFUND_REQUESTED',
        'REFUND_IN_PROGRESS'
      );
    get diagnostics v_resolved = row_count;

    if v_resolved = 0 then
      return coalesce(nullif(v_current_status, ''), 'pending_payment');
    end if;

    if exists (
      select 1
      from private.billing_organization_access_causes as cause
      where cause.organization_id = p_organization_id
        and (
          private.billing_payment_checkout_is_reversal(cause.payment_status)
          or cause.payment_status in ('CHARGEBACK', 'REPROVED_BY_RISK_ANALYSIS')
        )
    ) then
      return 'suspended';
    end if;
    if exists (
      select 1
      from private.billing_organization_access_causes as cause
      where cause.organization_id = p_organization_id
        and cause.payment_status in (
          'OVERDUE',
          'DUNNING_REQUESTED',
          'DUNNING_RECEIVED',
          'CREDIT_CARD_CAPTURE_REFUSED'
        )
    ) then
      return 'overdue';
    end if;
    if exists (
      select 1
      from private.billing_organization_access_causes as cause
      where cause.organization_id = p_organization_id
    ) then
      return 'pending_payment';
    end if;

    return 'active';
  end if;

  if v_current_status in ('active', 'trial') then
    return v_current_status;
  end if;

  if v_current_status not in ('pending_payment', 'overdue', 'past_due') then
    return coalesce(nullif(v_current_status, ''), 'pending_payment');
  end if;

  v_payment_cursor := greatest(
    v_payment.last_webhook_event_at,
    v_payment.last_provider_observed_at
  );
  if v_payment_cursor is null then
    return coalesce(nullif(v_current_status, ''), 'pending_payment');
  end if;

  if not exists (
    select 1
    from public.asaas_payments as other_payment
    where other_payment.organization_id = p_organization_id
      and other_payment.id <> v_payment.id
      and (
        greatest(
          other_payment.last_webhook_event_at,
          other_payment.last_provider_observed_at
        ) > v_payment_cursor
        or (
          greatest(
            other_payment.last_webhook_event_at,
            other_payment.last_provider_observed_at
          ) = v_payment_cursor
          and private.asaas_payment_status_precedence(other_payment.status)
            > private.asaas_payment_status_precedence(v_proof_status)
        )
      )
  ) then
    return 'active';
  end if;

  return coalesce(nullif(v_current_status, ''), 'pending_payment');
end
$$;


ALTER FUNCTION private.reconcile_billing_payment_access_proof(p_organization_id uuid, p_provider_payment_id text, p_current_status text, p_proof_status text) OWNER TO postgres;

--
-- Name: reconcile_google_calendar_cron_jobs(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reconcile_google_calendar_cron_jobs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'vault', 'cron'
    AS $_$
declare
  existing_job_id bigint;
  sync_base_url text;
begin
  for existing_job_id in
    select jobid
    from cron.job
    where jobname in (
      'google-calendar-sync-jobs',
      'google-calendar-renew-watches',
      'google-calendar-enqueue-due-pulls'
    )
  loop
    perform cron.unschedule(existing_job_id);
  end loop;

  select nullif(btrim(decrypted_secret), '')
  into sync_base_url
  from vault.decrypted_secrets
  where name = 'google_calendar_sync_base_url'
  limit 1;

  if sync_base_url is null then
    return;
  end if;

  perform cron.schedule(
    'google-calendar-enqueue-due-pulls',
    '* * * * *',
    $cron$select private.invoke_google_calendar_worker('enqueue_due_pulls', 20);$cron$
  );

  perform cron.schedule(
    'google-calendar-sync-jobs',
    '* * * * *',
    $cron$select private.invoke_google_calendar_worker('run_due_jobs', 20);$cron$
  );

  perform cron.schedule(
    'google-calendar-renew-watches',
    '17 3 * * *',
    $cron$select private.invoke_google_calendar_worker('renew_watches');$cron$
  );
end
$_$;


ALTER FUNCTION private.reconcile_google_calendar_cron_jobs() OWNER TO postgres;

--
-- Name: reconcile_meta_feedback_module_activation(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reconcile_meta_feedback_module_activation(p_organization_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
begin
  if p_organization_id is null then
    return;
  end if;

  if exists (
    select 1
    from public.organization_modules as module_access
    where module_access.organization_id = p_organization_id
      and lower(btrim(module_access.module_name)) = 'campaigns'
      and coalesce(module_access.is_enabled, false) = true
  ) then
    insert into private.meta_feedback_module_activations (
      organization_id,
      activation_id,
      activated_at
    )
    values (p_organization_id, gen_random_uuid(), clock_timestamp())
    on conflict (organization_id) do nothing;
  else
    delete from private.meta_feedback_module_activations
    where organization_id = p_organization_id;
  end if;
end;
$$;


ALTER FUNCTION private.reconcile_meta_feedback_module_activation(p_organization_id uuid) OWNER TO postgres;

--
-- Name: reconcile_notification_whatsapp_delivery(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reconcile_notification_whatsapp_delivery(p_organization_id uuid, p_expected_message_id text, p_status text, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_expected_message_id text := nullif(btrim(coalesce(p_expected_message_id, '')), '');
  v_provider_status text := lower(btrim(coalesce(p_status, '')));
  v_ids uuid[];
  v_notification_id uuid;
  v_metadata jsonb;
  v_channel jsonb;
  v_current_status text;
  v_current_event_at timestamptz;
  v_delivery_result jsonb;
  v_normalized_status text;
  v_legacy_status text;
  v_next_attempt_at text;
  v_new_channel jsonb;
begin
  if p_organization_id is null
     or v_expected_message_id is null
     or char_length(v_expected_message_id) > 500
     or p_occurred_at is null
     or p_occurred_at > now() + interval '5 minutes'
     or v_provider_status not in ('delivered', 'read', 'failed') then
    return jsonb_build_object('outcome', 'invalid_status');
  end if;

  select array_agg(candidate.notification_id order by candidate.notification_id)
    into v_ids
  from (
    select delivery.notification_id
    from private.notification_deliveries as delivery
    where delivery.organization_id = p_organization_id
      and delivery.channel = 'whatsapp'
      and (
        delivery.provider_message_id = v_expected_message_id
        or delivery.metadata ->> 'expected_message_id' = v_expected_message_id
      )
    order by delivery.notification_id
    limit 2
  ) as candidate;

  if coalesce(cardinality(v_ids), 0) = 0 then
    select array_agg(candidate.id order by candidate.id)
      into v_ids
    from (
      select notification.id
      from public.notifications as notification
      where notification.organization_id = p_organization_id
        and notification.metadata #>> '{dispatch,whatsapp,expected_message_id}'
          = v_expected_message_id
      order by notification.id
      limit 2
    ) as candidate;
  end if;

  if coalesce(cardinality(v_ids), 0) = 0 then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if cardinality(v_ids) <> 1 then
    return jsonb_build_object('outcome', 'ambiguous');
  end if;

  v_notification_id := v_ids[1];
  select coalesce(notification.metadata, '{}'::jsonb)
    into v_metadata
  from public.notifications as notification
  where notification.id = v_notification_id
    and notification.organization_id = p_organization_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  v_channel := coalesce(v_metadata #> '{dispatch,whatsapp}', '{}'::jsonb);
  v_current_status := lower(btrim(coalesce(v_channel ->> 'status', '')));
  v_current_event_at := coalesce(
    private.notification_safe_timestamptz(v_channel ->> 'delivery_occurred_at'),
    private.notification_safe_timestamptz(v_channel ->> 'delivered_at'),
    private.notification_safe_timestamptz(v_channel ->> 'failed_at')
  );

  if v_current_status = 'delivered' and v_provider_status = 'failed' then
    return jsonb_build_object(
      'outcome', 'stale',
      'notification_id', v_notification_id,
      'status', v_current_status,
      'occurred_at', v_current_event_at
    );
  end if;
  if v_current_event_at is not null and p_occurred_at < v_current_event_at then
    return jsonb_build_object(
      'outcome', 'stale',
      'notification_id', v_notification_id,
      'status', v_current_status,
      'occurred_at', v_current_event_at
    );
  end if;

  v_delivery_result := private.apply_notification_delivery_receipt(
    v_notification_id,
    'whatsapp',
    coalesce(nullif(v_channel ->> 'provider', ''), 'evolution'),
    v_expected_message_id,
    v_provider_status,
    v_provider_status in ('delivered', 'read'),
    false,
    p_occurred_at
  );

  if v_delivery_result ->> 'outcome' = 'stale' then
    return jsonb_build_object(
      'outcome', 'stale',
      'notification_id', v_notification_id,
      'status', v_delivery_result ->> 'status',
      'occurred_at', p_occurred_at
    );
  end if;

  v_normalized_status := coalesce(v_delivery_result ->> 'status', '');
  v_legacy_status := case
    when v_provider_status in ('delivered', 'read') then 'delivered'
    when v_normalized_status in ('permanent_failed', 'dead_letter') then 'permanent_failed'
    else 'failed'
  end;
  v_next_attempt_at := case
    when v_legacy_status = 'failed'
      then coalesce(v_delivery_result ->> 'next_attempt_at', now()::text)
    else ''
  end;

  if v_current_status = v_legacy_status
     and v_current_event_at is not null
     and p_occurred_at = v_current_event_at then
    return jsonb_build_object(
      'outcome', 'already_applied',
      'notification_id', v_notification_id,
      'status', v_normalized_status,
      'occurred_at', p_occurred_at
    );
  end if;

  v_new_channel := (
    v_channel
      - 'claim_token'
      - 'claimed_at'
  ) || jsonb_build_object(
    'required', true,
    'status', v_legacy_status,
    'delivery_status', v_provider_status,
    'delivery_occurred_at', p_occurred_at,
    'delivered_at', case
      when v_legacy_status = 'delivered' then to_jsonb(p_occurred_at)
      else v_channel -> 'delivered_at'
    end,
    'failed_at', case
      when v_legacy_status in ('failed', 'permanent_failed') then to_jsonb(p_occurred_at)
      else v_channel -> 'failed_at'
    end,
    'next_attempt_at', v_next_attempt_at,
    'error', case
      when v_legacy_status in ('failed', 'permanent_failed')
        then 'provider_delivery_failed'
      else ''
    end,
    'updated_at', now()
  );

  update public.notifications as notification
  set metadata = v_metadata || jsonb_build_object(
    'dispatch', coalesce(v_metadata -> 'dispatch', '{}'::jsonb)
      || jsonb_build_object('whatsapp', v_new_channel),
    'whatsapp_dispatch_required', true,
    'whatsapp_dispatch', v_new_channel,
    'whatsapp_delivery_reconciled_at', p_occurred_at
  )
  where notification.id = v_notification_id
    and notification.organization_id = p_organization_id;

  if not found then
    return jsonb_build_object('outcome', 'stale');
  end if;

  return jsonb_build_object(
    'outcome', 'applied',
    'notification_id', v_notification_id,
    'delivery_id', v_delivery_result ->> 'delivery_id',
    'status', v_normalized_status,
    'legacy_status', v_legacy_status,
    'occurred_at', p_occurred_at,
    'next_attempt_at', nullif(v_next_attempt_at, '')
  );
end
$$;


ALTER FUNCTION private.reconcile_notification_whatsapp_delivery(p_organization_id uuid, p_expected_message_id text, p_status text, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_notification_whatsapp_delivery(p_organization_id uuid, p_expected_message_id text, p_status text, p_occurred_at timestamp with time zone); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.reconcile_notification_whatsapp_delivery(p_organization_id uuid, p_expected_message_id text, p_status text, p_occurred_at timestamp with time zone) IS 'Reconciles one verified Evolution receipt against normalized and legacy state; a transient failed receipt is requeued with backoff instead of becoming terminal.';


--
-- Name: reconcile_resend_email_events_after_log(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reconcile_resend_email_events_after_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.provider = 'resend'
     and nullif(btrim(new.provider_message_id), '') is not null then
    perform private.reconcile_resend_email_events_for_log(new.id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.reconcile_resend_email_events_after_log() OWNER TO postgres;

--
-- Name: reconcile_resend_email_events_for_log(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reconcile_resend_email_events_for_log(p_email_log_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_organization_id uuid;
  v_user_id uuid;
  v_provider_message_id text;
  v_current_status text;
  v_current_error text;
  v_current_status_event_at timestamptz;
  v_current_delivered_at timestamptz;
  v_current_last_event_at timestamptz;
  v_current_rank integer;
  v_candidate_status text;
  v_candidate_rank integer;
  v_candidate_error text;
  v_event record;
begin
  select
    logs.organization_id,
    logs.user_id,
    logs.provider_message_id,
    logs.status,
    logs.error_message,
    logs.status_event_at,
    logs.delivered_at,
    logs.last_event_at
    into
      v_organization_id,
      v_user_id,
      v_provider_message_id,
      v_current_status,
      v_current_error,
      v_current_status_event_at,
      v_current_delivered_at,
      v_current_last_event_at
  from public.email_logs logs
  where logs.id = p_email_log_id
    and logs.provider = 'resend'
    and nullif(btrim(logs.provider_message_id), '') is not null
  for update;

  if not found then
    return false;
  end if;

  update public.email_delivery_events events
  set email_log_id = p_email_log_id,
      organization_id = v_organization_id,
      user_id = v_user_id,
      reconciled_at = now()
  where events.provider = 'resend'
    and events.provider_message_id = v_provider_message_id;

  -- A local HTTP failure also uses the text `failed`, but has no provider
  -- event timestamp. It must remain retryable and must not outrank a later
  -- verified provider event.
  v_current_rank := case
    when v_current_status_event_at is null then 0
    else private.resend_email_status_rank(v_current_status)
  end;

  for v_event in
    select
      events.event_type,
      events.occurred_at,
      events.payload,
      events.provider_event_id,
      events.created_at
    from public.email_delivery_events events
    where events.provider = 'resend'
      and events.provider_message_id = v_provider_message_id
    order by
      events.occurred_at asc,
      events.created_at asc,
      events.provider_event_id asc
  loop
    v_current_last_event_at := greatest(
      coalesce(v_current_last_event_at, '-infinity'::timestamptz),
      v_event.occurred_at
    );

    if v_event.event_type = 'email.delivered' then
      v_current_delivered_at := case
        when v_current_delivered_at is null then v_event.occurred_at
        else least(v_current_delivered_at, v_event.occurred_at)
      end;
    end if;

    v_candidate_status := private.resend_email_event_status(v_event.event_type);
    if v_candidate_status is null then
      continue;
    end if;

    v_candidate_rank := private.resend_email_status_rank(v_candidate_status);
    if v_candidate_rank > v_current_rank
       or (
         v_candidate_rank = v_current_rank
         and v_event.occurred_at >= coalesce(v_current_status_event_at, '-infinity'::timestamptz)
       ) then
      v_current_status := v_candidate_status;
      v_current_status_event_at := v_event.occurred_at;
      v_current_rank := v_candidate_rank;

      if v_candidate_status in ('failed', 'suppressed', 'bounced', 'complained') then
        v_candidate_error := coalesce(
          v_event.payload #>> '{bounce,message}',
          v_event.payload #>> '{failed,reason}',
          v_event.payload #>> '{suppressed,message}',
          v_event.payload #>> '{complaint,message}',
          v_event.event_type
        );
        v_current_error := nullif(left(v_candidate_error, 1000), '');
      else
        v_current_error := null;
      end if;
    end if;
  end loop;

  update public.email_logs
  set status = v_current_status,
      error_message = v_current_error,
      status_event_at = v_current_status_event_at,
      delivered_at = v_current_delivered_at,
      last_event_at = nullif(v_current_last_event_at, '-infinity'::timestamptz),
      updated_at = now()
  where id = p_email_log_id;

  return true;
end;
$$;


ALTER FUNCTION private.reconcile_resend_email_events_for_log(p_email_log_id uuid) OWNER TO postgres;

--
-- Name: record_billing_cleanup_access_cause_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.record_billing_cleanup_access_cause_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT'
     or (new.organization_id, new.provider_payment_id, new.payment_status,
         new.observed_at)
        is distinct from
        (old.organization_id, old.provider_payment_id, old.payment_status,
         old.observed_at) then
    perform private.mark_billing_cleanup_late_payment_event(
      new.organization_id,
      new.provider_payment_id,
      'late_billing_access_event'
    );
  end if;
  return new;
end
$$;


ALTER FUNCTION private.record_billing_cleanup_access_cause_event() OWNER TO postgres;

--
-- Name: record_billing_cleanup_payment_event(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.record_billing_cleanup_payment_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT'
     or (new.status, new.payment_date, new.confirmed_date,
         new.last_webhook_event_id, new.last_webhook_event_at,
         new.last_webhook_received_at, new.last_provider_observed_at,
         new.raw_event)
        is distinct from
        (old.status, old.payment_date, old.confirmed_date,
         old.last_webhook_event_id, old.last_webhook_event_at,
         old.last_webhook_received_at, old.last_provider_observed_at,
         old.raw_event) then
    perform private.mark_billing_cleanup_late_payment_event(
      new.organization_id,
      new.asaas_payment_id,
      'late_billing_payment_event'
    );
  end if;
  return new;
end
$$;


ALTER FUNCTION private.record_billing_cleanup_payment_event() OWNER TO postgres;

--
-- Name: record_lead_action_fact(uuid, uuid, uuid, text, text, timestamp with time zone, boolean, boolean, boolean, boolean, boolean, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.record_lead_action_fact(p_organization_id uuid, p_lead_id uuid, p_actor_user_id uuid, p_action_type text, p_channel text, p_occurred_at timestamp with time zone, p_is_automated boolean, p_is_inbound boolean, p_qualifies_first_outreach boolean, p_qualifies_stage_inactivity boolean, p_is_effective_contact boolean, p_source_type text, p_source_id text, p_metadata jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  current_assignment_cycle_id uuid;
  current_stage_cycle_id uuid;
begin
  if private.historical_import_effects_suppressed() then return; end if;
  perform 1 from public.leads lead
  left join public.stage_operational_configs rule
    on rule.organization_id = lead.organization_id and rule.stage_id = lead.stage_id
  where lead.id = p_lead_id and lead.organization_id = p_organization_id
    and lead.operational_effects_suppressed = false
    and (
      lead.attention_eligible = true
      or (lead.deal_status = 'open'
        and coalesce(rule.config->>'operational_rules_version', '') = '1'
        and (coalesce(rule.cadence_enabled, false)
          or (coalesce(nullif(rule.config->>'attention_source_mode', ''),
                case when rule.attention_mode = 'disabled' then 'inherit' else 'local' end) = 'local'
            and rule.attention_mode in ('shadow', 'enabled'))))
      or (lead.deal_status = 'open' and exists (
        select 1 from private.stage_inactivity_policies policy
        where policy.organization_id = lead.organization_id and policy.stage_id = lead.stage_id
          and policy.clock = 'last_interaction'
      ))
    ) for share of lead;
  if not found then return; end if;

  select id into current_assignment_cycle_id from public.lead_assignment_cycles
    where organization_id = p_organization_id and lead_id = p_lead_id and ended_at is null
    order by assigned_at desc, id desc limit 1;
  select id into current_stage_cycle_id from public.lead_stage_cycles
    where organization_id = p_organization_id and lead_id = p_lead_id and exited_at is null
    order by entered_at desc, id desc limit 1;

  insert into public.lead_action_facts (
    organization_id, lead_id, actor_user_id, assignment_cycle_id, stage_cycle_id,
    action_type, channel, occurred_at, is_automated, is_inbound,
    qualifies_first_outreach, qualifies_stage_inactivity, is_effective_contact,
    source_type, source_id, metadata
  ) values (
    p_organization_id, p_lead_id, p_actor_user_id, current_assignment_cycle_id, current_stage_cycle_id,
    btrim(p_action_type), nullif(btrim(coalesce(p_channel, '')), ''), coalesce(p_occurred_at, now()),
    coalesce(p_is_automated, false), coalesce(p_is_inbound, false),
    coalesce(p_qualifies_first_outreach, false), coalesce(p_qualifies_stage_inactivity, false),
    coalesce(p_is_effective_contact, false), btrim(p_source_type), nullif(btrim(coalesce(p_source_id, '')), ''),
    coalesce(p_metadata, '{}'::jsonb)
  ) on conflict (organization_id, source_type, source_id) where source_id is not null do nothing;
end;
$$;


ALTER FUNCTION private.record_lead_action_fact(p_organization_id uuid, p_lead_id uuid, p_actor_user_id uuid, p_action_type text, p_channel text, p_occurred_at timestamp with time zone, p_is_automated boolean, p_is_inbound boolean, p_qualifies_first_outreach boolean, p_qualifies_stage_inactivity boolean, p_is_effective_contact boolean, p_source_type text, p_source_id text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: record_round_robin_rotation_assignment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.record_round_robin_rotation_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  owner_id uuid;
  assignment private.round_robin_rotation_assignment_context%rowtype;
  state private.round_robin_rotation_state%rowtype;
  expected record;
  confirmed_cursor record;
  required_team uuid;
begin
  if new.organization_id is null or new.lead_id is null or new.round_robin_id is null
    or new.assigned_user_id is null then return new; end if;
  -- Managed queues have their own episode/visits ledger and write guard.
  -- Running both ledgers would reject a legitimate new-window resume or claim.
  if private.queue_runtime_is_managed(new.organization_id,new.round_robin_id)
    then return new; end if;
  -- A keep-assignee/reentry diagnostic is not a new assignment. In particular,
  -- it must not begin another round merely because it repeats the same user.
  if not private.is_round_robin_rotation_assignment_reason(new.reason)
    then return new; end if;
  select lead.assigned_user_id into owner_id from public.leads lead
  where lead.organization_id=new.organization_id and lead.id=new.lead_id for no key update;
  if not found or owner_id is distinct from new.assigned_user_id then
    raise exception using errcode='40001',message='round_robin_rotation_unconfirmed_assignment';
  end if;
  if not exists (select 1 from public.round_robins queue
    where queue.organization_id=new.organization_id and queue.id=new.round_robin_id
      and coalesce(queue.is_active,true)) then
    raise exception using errcode='40001',message='round_robin_rotation_invalid_queue';
  end if;
  select context.* into assignment from private.round_robin_rotation_assignment_context context
  where context.organization_id=new.organization_id and context.lead_id=new.lead_id
    and context.assignment_xid=pg_current_xact_id()
    and context.assigned_user_id=new.assigned_user_id;
  if (assignment.previous_user_id is not null or new.reason in ('auto_redistribution','round_robin')
      or exists (select 1 from private.round_robin_rotation_state prior
        where prior.organization_id=new.organization_id and prior.lead_id=new.lead_id
          and prior.round_robin_id=new.round_robin_id and cardinality(prior.visited_user_ids)>0)) then
    if assignment.assignment_xid is null then
      raise exception using errcode='40001',message='round_robin_rotation_missing_transfer';
    end if;
    required_team:=case when new.reason in ('auto_redistribution','round_robin')
      then assignment.previous_team_id else null end;
    -- Revalidate current availability at confirmation. A real shift/config
    -- change since preview rejects the whole transfer; a retry selects anew.
    select candidate.* into expected from private.pick_round_robin_rotation_candidate(
      new.organization_id,new.lead_id,new.round_robin_id,assignment.previous_user_id,
      required_team,clock_timestamp()) candidate;
    if expected.user_id is null or expected.user_id is distinct from new.assigned_user_id then
      raise exception using errcode='40001',message='round_robin_rotation_candidate_changed';
    end if;
  end if;
  insert into private.round_robin_rotation_state
    (organization_id,lead_id,round_robin_id,visited_user_ids,last_user_id,last_log_id)
  values (new.organization_id,new.lead_id,new.round_robin_id,'{}',null,null)
  on conflict do nothing;
  select rotation.* into state from private.round_robin_rotation_state rotation
  where rotation.organization_id=new.organization_id and rotation.lead_id=new.lead_id
    and rotation.round_robin_id=new.round_robin_id for update;
  if state.last_log_id=new.id then return new; end if;
  select candidate.* into confirmed_cursor
  from private.round_robin_rotation_candidates(new.organization_id,new.round_robin_id,true,
    0,'00:00'::time,null) candidate where candidate.user_id=new.assigned_user_id;
  if confirmed_cursor.user_id is null then
    raise exception using errcode='40001',message='round_robin_rotation_recipient_revoked';
  end if;
  update private.round_robin_rotation_state rotation set
    round_no=state.round_no+case when new.assigned_user_id=any(state.visited_user_ids) then 1 else 0 end,
    visited_user_ids=case when new.assigned_user_id=any(state.visited_user_ids)
      then array[new.assigned_user_id] else array_append(state.visited_user_ids,new.assigned_user_id) end,
    last_user_id=new.assigned_user_id,last_log_id=new.id,updated_at=clock_timestamp()
    ,last_position=confirmed_cursor.position,last_member_id=confirmed_cursor.member_id,
    last_candidate_kind=confirmed_cursor.candidate_kind,
    last_candidate_created_at=confirmed_cursor.candidate_created_at
  where rotation.organization_id=new.organization_id and rotation.lead_id=new.lead_id
    and rotation.round_robin_id=new.round_robin_id;
  return new;
end;
$$;


ALTER FUNCTION private.record_round_robin_rotation_assignment() OWNER TO postgres;

--
-- Name: recover_paid_checkout_after_payment_delete(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.recover_paid_checkout_after_payment_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_changed integer := 0;
begin
  if new.billing_intent_id is null
     or not private.billing_payment_checkout_is_paid(new.status) then
    return null;
  end if;

  update private.billing_payment_checkout_cancellations as cancellation
  set
    finalized_at = coalesce(cancellation.finalized_at, now()),
    final_outcome = case
      when cancellation.provider_deleted_at is null then 'paid_before_delete'
      else 'paid_after_delete'
    end,
    paid_won_at = coalesce(cancellation.paid_won_at, now()),
    manual_review_at = null,
    updated_at = now()
  where cancellation.intent_id = new.billing_intent_id
    and cancellation.payment_id = new.id
    and cancellation.organization_id = new.organization_id
    and cancellation.provider_payment_id = new.asaas_payment_id
    and (
      cancellation.finalized_at is null
      or cancellation.final_outcome in ('cancelled', 'manual_review')
    );
  get diagnostics v_changed = row_count;

  if v_changed = 1 then
    update private.billing_checkout_intents
    set
      status = 'pending',
      cancelled_at = null,
      last_error = 'provider_payment_removed_before_late_payment',
      updated_at = now()
    where id = new.billing_intent_id
      and organization_id = new.organization_id
      and status = 'cancelled';
  end if;

  return null;
end
$$;


ALTER FUNCTION private.recover_paid_checkout_after_payment_delete() OWNER TO postgres;

--
-- Name: recover_paid_checkout_after_subscription_delete(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.recover_paid_checkout_after_subscription_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_changed integer := 0;
begin
  if new.billing_intent_id is null
     or not private.billing_payment_checkout_is_paid(new.status) then
    return null;
  end if;

  update private.billing_subscription_checkout_cancellations as cancellation
  set
    final_outcome = 'paid_without_recurrence',
    needs_payment_method_update = true,
    paid_won_at = coalesce(cancellation.paid_won_at, now()),
    updated_at = now()
  where cancellation.intent_id = new.billing_intent_id
    and cancellation.organization_id = new.organization_id
    and (
      cancellation.provider_payment_id = new.asaas_payment_id
      or (
        cancellation.provider_payment_id is null
        and cancellation.provider_subscription_id = new.asaas_subscription_id
      )
    )
    and cancellation.finalized_at is not null
    and cancellation.provider_deleted_at is not null
    and cancellation.final_outcome = 'cancelled';
  get diagnostics v_changed = row_count;

  if v_changed = 1 then
    update private.billing_checkout_intents
    set
      status = 'pending',
      cancelled_at = null,
      last_error = 'provider_subscription_removed_before_late_payment',
      updated_at = now()
    where id = new.billing_intent_id
      and organization_id = new.organization_id
      and status = 'cancelled';

    update private.billing_card_recurrence_provisions
    set
      status = 'failed',
      provider_card_credential = null,
      card_last4 = null,
      lease_id = null,
      lease_expires_at = null,
      failed_at = coalesce(failed_at, now()),
      last_error = 'provider_subscription_removed_before_late_payment',
      job_status = 'cancelled',
      job_locked_at = null,
      job_lock_expires_at = null,
      job_locked_by = null,
      job_lease_id = null,
      updated_at = now()
    where payment_id = new.id
      and organization_id = new.organization_id
      and status <> 'cancelled';
  end if;

  return null;
end
$$;


ALTER FUNCTION private.recover_paid_checkout_after_subscription_delete() OWNER TO postgres;

--
-- Name: recover_whatsapp_inbound_push_waiting(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.recover_whatsapp_inbound_push_waiting(p_limit integer DEFAULT 25) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_candidate record; v_waiting private.whatsapp_inbound_push_waiting%rowtype;
  v_outcome text; v_count integer:=0;
begin
  if p_limit is null or p_limit<1 or p_limit>100 then raise exception 'invalid WhatsApp waiting batch'; end if;
  for v_candidate in
    select waiting.notification_id,message.organization_id,message.id as message_id
    from private.whatsapp_inbound_push_waiting waiting
    join public.notifications notification on notification.id=waiting.notification_id and notification.organization_id=waiting.organization_id
    join public.whatsapp_messages message on message.organization_id=waiting.organization_id
      and message.id=private.safe_uuid(notification.metadata->>'whatsapp_message_id')
    where waiting.next_check_at<=now() or waiting.expires_at<=now()
    order by waiting.next_check_at,waiting.notification_id limit p_limit
  loop
    -- Match the dispatcher's message-advisory -> parent -> attendance order.
    -- Queue writes come afterwards, avoiding a notification-trigger inversion
    -- when two old/new recipient queue entries coexist for the same message.
    if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
      'whatsapp-inbound-push:'||v_candidate.organization_id::text||':'||v_candidate.message_id::text,0)) then continue; end if;
    -- Do not hold a queue lock before parent authorization locks: notification
    -- UPDATE triggers register this row while already holding the notification.
    select * into v_waiting from private.whatsapp_inbound_push_waiting
      where notification_id=v_candidate.notification_id;
    if not found then continue; end if;
    if v_waiting.expires_at<=now() then
      delete from private.whatsapp_inbound_push_waiting where notification_id=v_waiting.notification_id;
      continue;
    end if;
    if exists(select 1 from public.notifications sibling where sibling.organization_id=v_candidate.organization_id
      and sibling.metadata->>'event_key'='whatsapp_inbound_attendant'
      and sibling.metadata->>'whatsapp_message_id'=v_candidate.message_id::text
      and (sibling.metadata->>'whatsapp_inbound_provider_started'='true'
        or exists(select 1 from private.notification_deliveries attempted where attempted.notification_id=sibling.id
          and attempted.channel='push' and (attempted.attempt_count>0 or attempted.status in ('sending','accepted','delivered'))))) then
      delete from private.whatsapp_inbound_push_waiting where notification_id=v_waiting.notification_id;
      continue;
    end if;
    v_outcome:=private.prepare_whatsapp_inbound_attendant_push(v_waiting.notification_id);
    if v_outcome='authorized' then
      perform private.materialize_notification_deliveries(v_waiting.notification_id,false);
      update private.whatsapp_inbound_push_waiting set next_check_at=now()+interval '1 minute'
        where notification_id=v_waiting.notification_id;
    else
      delete from private.whatsapp_inbound_push_waiting where notification_id=v_waiting.notification_id;
    end if;
    v_count:=v_count+1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION private.recover_whatsapp_inbound_push_waiting(p_limit integer) OWNER TO postgres;

--
-- Name: refresh_queue_timezone_catalog(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.refresh_queue_timezone_catalog() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare refreshed integer;
begin
  if session_user <> 'postgres' or current_setting('role',true) not in ('none','postgres') then
    raise exception using errcode='42501',message='queue_timezone_refresh_postgres_only';
  end if;
  lock table private.queue_timezone_catalog in share row exclusive mode;
  with names as materialized (select name from pg_catalog.pg_timezone_names),
    retired as (delete from private.queue_timezone_catalog old
      where not exists(select 1 from names n where n.name=old.name))
  insert into private.queue_timezone_catalog(name) select name from names
    on conflict(name) do nothing;
  select count(*)::integer into refreshed from private.queue_timezone_catalog;
  return refreshed;
end;
$$;


ALTER FUNCTION private.refresh_queue_timezone_catalog() OWNER TO postgres;

--
-- Name: register_whatsapp_inbound_push_waiting(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.register_whatsapp_inbound_push_waiting(p_notification_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_notification public.notifications%rowtype; v_expiry timestamptz;
begin
  select * into v_notification from public.notifications where id=p_notification_id;
  if not found or v_notification.metadata->>'event_key' is distinct from 'whatsapp_inbound_attendant'
    or not private.notification_dispatch_required(v_notification.metadata#>'{dispatch,push,required}')
    or v_notification.metadata->>'whatsapp_inbound_provider_started'='true'
    or exists(select 1 from private.notification_deliveries where notification_id=p_notification_id and channel='push') then
    delete from private.whatsapp_inbound_push_waiting where notification_id=p_notification_id;
    return;
  end if;
  v_expiry:=private.notification_delivery_expiry(v_notification.created_at,v_notification.metadata,
    coalesce(v_notification.metadata#>'{dispatch,push}','{}'::jsonb));
  if v_expiry<=now() then
    delete from private.whatsapp_inbound_push_waiting where notification_id=p_notification_id;
    return;
  end if;
  if exists(select 1 from public.notifications sibling where sibling.organization_id=v_notification.organization_id
    and sibling.metadata->>'event_key'='whatsapp_inbound_attendant'
    and sibling.metadata->>'whatsapp_message_id'=v_notification.metadata->>'whatsapp_message_id'
    and (sibling.metadata->>'whatsapp_inbound_provider_started'='true'
      or exists(select 1 from private.notification_deliveries attempted where attempted.notification_id=sibling.id
        and attempted.channel='push' and (attempted.attempt_count>0 or attempted.status in ('sending','accepted','delivered'))))) then
    delete from private.whatsapp_inbound_push_waiting where notification_id=p_notification_id;
    return;
  end if;
  insert into private.whatsapp_inbound_push_waiting(notification_id,organization_id,expires_at)
  select v_notification.id,v_notification.organization_id,v_expiry
  from public.whatsapp_messages message where message.id=private.safe_uuid(v_notification.metadata->>'whatsapp_message_id')
    and message.organization_id=v_notification.organization_id and message.capture_state='captured'
    and message.lead_id is not null and message.direction='inbound' and message.from_me is false
    and message.message_type not in ('reaction','system','deleted')
  on conflict(notification_id) do update set expires_at=least(whatsapp_inbound_push_waiting.expires_at,excluded.expires_at);
end;
$$;


ALTER FUNCTION private.register_whatsapp_inbound_push_waiting(p_notification_id uuid) OWNER TO postgres;

