--
-- Name: renew_whatsapp_media_job(uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.renew_whatsapp_media_job(p_job_id uuid, p_worker_id text, p_lease_token uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  with renewed as (
    update public.media_jobs
    set locked_at = now(),
        lease_expires_at = now() + lease_duration,
        updated_at = now()
    where id = p_job_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
      and lease_token = p_lease_token
    returning 1
  )
  select exists(select 1 from renewed);
$$;


