--
-- Name: replay_notification_delivery(uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.replay_notification_delivery(p_delivery_id uuid, p_reason text, p_requested_by text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_delivery private.notification_deliveries%rowtype;
begin
  if p_delivery_id is null
     or nullif(btrim(coalesce(p_reason, '')), '') is null
     or nullif(btrim(coalesce(p_requested_by, '')), '') is null
     or char_length(p_reason) > 1000
     or char_length(p_requested_by) > 255 then
    return false;
  end if;

  update private.notification_deliveries as delivery
  set status = 'queued',
      attempt_count = 0,
      next_attempt_at = now(),
      expires_at = greatest(delivery.expires_at, now() + interval '1 day'),
      lease_token = null,
      leased_by = null,
      lease_expires_at = null,
      dependency_key = null,
      provider_status = null,
      accepted_at = null,
      delivered_at = null,
      blocked_at = null,
      terminal_at = null,
      last_error_code = null,
      last_error_message = null,
      last_error_at = null,
      metadata = delivery.metadata || jsonb_build_object(
        'last_replay_at', now(),
        'last_replay_by', btrim(p_requested_by),
        'last_replay_reason', btrim(p_reason),
        'replay_count', private.notification_safe_integer(
          delivery.metadata ->> 'replay_count',
          0,
          0,
          2147483646
        ) + 1
      ),
      updated_at = now()
  where delivery.id = p_delivery_id
    and delivery.status in (
      'blocked_dependency', 'dead_letter', 'cancelled', 'permanent_failed'
    )
  returning delivery.* into v_delivery;

  if not found then
    return false;
  end if;

  insert into private.notification_delivery_attempts (
    delivery_id,
    event_type,
    attempt_number,
    lease_token,
    worker_id,
    from_status,
    outcome,
    completed_at,
    metadata
  )
  values (
    v_delivery.id,
    'replay',
    null,
    null,
    null,
    null,
    'replayed',
    now(),
    jsonb_build_object(
      'reason', btrim(p_reason),
      'requested_by', btrim(p_requested_by)
    )
  );

  return true;
end
$$;


ALTER FUNCTION private.replay_notification_delivery(p_delivery_id uuid, p_reason text, p_requested_by text) OWNER TO postgres;

--
-- Name: reschedule_notification_delivery(uuid, uuid, timestamp with time zone, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reschedule_notification_delivery(p_delivery_id uuid, p_lease_token uuid, p_next_attempt_at timestamp with time zone, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_provider_status text DEFAULT NULL::text, p_attempt_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_delivery private.notification_deliveries%rowtype;
  v_status text;
  v_next_attempt_at timestamptz;
begin
  if p_delivery_id is null
     or p_lease_token is null
     or jsonb_typeof(coalesce(p_attempt_metadata, '{}'::jsonb)) <> 'object'
     or char_length(coalesce(p_error_code, '')) > 255
     or char_length(coalesce(p_error_message, '')) > 2000
     or char_length(coalesce(p_provider_status, '')) > 255 then
    return false;
  end if;

  select delivery.*
    into v_delivery
  from private.notification_deliveries as delivery
  where delivery.id = p_delivery_id
    and delivery.status in ('leased', 'sending')
    and delivery.lease_token = p_lease_token
  for update;

  if not found then
    return false;
  end if;

  if v_delivery.expires_at <= now()
     or v_delivery.attempt_count >= v_delivery.max_attempts
     or coalesce(p_next_attempt_at, now()) >= v_delivery.expires_at then
    v_status := 'dead_letter';
    v_next_attempt_at := null;
  else
    v_status := 'retry_wait';
    v_next_attempt_at := greatest(coalesce(p_next_attempt_at, now()), now());
  end if;

  update private.notification_deliveries as delivery
  set status = v_status,
      next_attempt_at = v_next_attempt_at,
      lease_token = null,
      leased_by = null,
      lease_expires_at = null,
      dependency_key = null,
      provider_status = coalesce(
        nullif(btrim(p_provider_status), ''),
        delivery.provider_status
      ),
      blocked_at = null,
      terminal_at = case when v_status = 'dead_letter' then now() else null end,
      last_error_code = nullif(left(btrim(coalesce(p_error_code, '')), 255), ''),
      last_error_message = nullif(left(btrim(coalesce(p_error_message, '')), 2000), ''),
      last_error_at = now(),
      metadata = delivery.metadata || coalesce(p_attempt_metadata, '{}'::jsonb),
      updated_at = now()
  where delivery.id = p_delivery_id
    and delivery.lease_token = p_lease_token;

  update private.notification_delivery_attempts as attempt
  set outcome = v_status,
      provider = v_delivery.provider,
      provider_message_id = v_delivery.provider_message_id,
      provider_status = coalesce(
        nullif(btrim(p_provider_status), ''),
        attempt.provider_status
      ),
      completed_at = now(),
      error_code = nullif(left(btrim(coalesce(p_error_code, '')), 255), ''),
      error_message = nullif(left(btrim(coalesce(p_error_message, '')), 2000), ''),
      metadata = attempt.metadata || coalesce(p_attempt_metadata, '{}'::jsonb)
  where attempt.delivery_id = p_delivery_id
    and attempt.event_type = 'send_attempt'
    and attempt.lease_token = p_lease_token
    and attempt.outcome = 'sending';

  return true;
end
$$;


ALTER FUNCTION private.reschedule_notification_delivery(p_delivery_id uuid, p_lease_token uuid, p_next_attempt_at timestamp with time zone, p_error_code text, p_error_message text, p_provider_status text, p_attempt_metadata jsonb) OWNER TO postgres;

--
-- Name: resend_email_event_status(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.resend_email_event_status(p_event_type text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select case lower(btrim(p_event_type))
    when 'email.sent' then 'accepted'
    when 'email.delivery_delayed' then 'delayed'
    when 'email.delivered' then 'delivered'
    when 'email.failed' then 'failed'
    when 'email.suppressed' then 'suppressed'
    when 'email.bounced' then 'bounced'
    when 'email.complained' then 'complained'
    else null
  end;
$$;


ALTER FUNCTION private.resend_email_event_status(p_event_type text) OWNER TO postgres;

--
-- Name: resend_email_status_rank(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.resend_email_status_rank(p_status text) RETURNS integer
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  -- A confirmed delivery cannot be downgraded by a contradictory late
  -- failed/suppressed/bounced event. A complaint is a post-delivery escalation
  -- and therefore remains the only provider state above delivered.
  select case lower(btrim(p_status))
    when 'processing' then 10
    when 'accepted' then 20
    when 'sent' then 20
    when 'delayed' then 30
    when 'failed' then 50
    when 'suppressed' then 60
    when 'bounced' then 70
    when 'delivered' then 90
    when 'complained' then 100
    else 0
  end;
$$;


ALTER FUNCTION private.resend_email_status_rank(p_status text) OWNER TO postgres;

--
-- Name: reserve_managed_whatsapp_distribution_auto_reply_from_entry(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.reserve_managed_whatsapp_distribution_auto_reply_from_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_round_robin_id uuid;
  v_session_id uuid;
  v_rule_id uuid;
  v_provider_message_id text;
  v_settings jsonb;
  v_reply_message text;
  v_delay_seconds integer;
begin
  -- Only the first real intake transition may reserve a reply. Later metadata
  -- enrichment/repair of historical entries must remain side-effect free.
  if old.metadata ? 'intake_result'
     or new.created_at < pg_catalog.statement_timestamp() - interval '1 hour'
     or new.entry_type <> 'initial'
     or new.provider <> 'whatsapp'
     or lower(btrim(coalesce(
       new.metadata->>'managed_whatsapp_message_distribution',
       'false'
     ))) not in ('true', '1', 'yes')
     or lower(coalesce(
       new.metadata->'intake_result'->>'handled',
       'false'
     )) not in ('true', '1', 'yes')
     or coalesce(new.metadata->'intake_result'->>'entry_type', '') <> 'initial' then
    return new;
  end if;

  begin
    v_round_robin_id := nullif(btrim(coalesce(
      new.metadata->>'target_round_robin_id',
      new.metadata->'intake_result'->>'round_robin_id',
      ''
    )), '')::uuid;
    v_session_id := nullif(btrim(coalesce(
      new.metadata->>'whatsapp_session_id',
      ''
    )), '')::uuid;
    v_rule_id := nullif(btrim(coalesce(
      new.metadata->>'matched_rule_id',
      ''
    )), '')::uuid;
  exception
    when invalid_text_representation then
      return new;
  end;

  v_provider_message_id := btrim(coalesce(
    new.metadata->>'provider_message_id',
    ''
  ));
  if v_round_robin_id is null
     or v_session_id is null
     or v_rule_id is null
     or v_provider_message_id = ''
     or new.provider_event_id is distinct from (
       v_session_id::text || ':' || v_provider_message_id
     ) then
    return new;
  end if;

  select queue.settings
    into v_settings
    from public.round_robins as queue
    join public.round_robin_rules as round_robin_rule
      on round_robin_rule.organization_id = queue.organization_id
     and round_robin_rule.round_robin_id = queue.id
     and round_robin_rule.id = v_rule_id
    join public.whatsapp_inbound_rules as inbound_rule
      on inbound_rule.organization_id = round_robin_rule.organization_id
     and inbound_rule.id = round_robin_rule.id
     and inbound_rule.target_round_robin_id = round_robin_rule.round_robin_id
     and inbound_rule.session_id = v_session_id
    join public.whatsapp_sessions as whatsapp_session
      on whatsapp_session.organization_id = queue.organization_id
     and whatsapp_session.id = v_session_id
   where queue.organization_id = new.organization_id
     and queue.id = v_round_robin_id
     and coalesce(queue.is_active, true) = true
     and coalesce(round_robin_rule.is_active, true) = true
     and coalesce(inbound_rule.is_active, true) = true
     and whatsapp_session.provider = 'evolution_go'
     and coalesce(whatsapp_session.is_active, true) = true
     and lower(btrim(coalesce(whatsapp_session.status, '')))
       not in ('deleted', 'disabled')
   limit 1
   for share of queue, round_robin_rule, inbound_rule, whatsapp_session;

  if not found
     or jsonb_typeof(v_settings) <> 'object'
     or jsonb_typeof(
       v_settings->'whatsapp_distribution_auto_reply_enabled'
     ) <> 'boolean'
     or coalesce((
       v_settings->>'whatsapp_distribution_auto_reply_enabled'
     )::boolean, false) = false
     or jsonb_typeof(
       v_settings->'whatsapp_distribution_auto_reply_message'
     ) <> 'string' then
    return new;
  end if;

  v_reply_message := btrim(coalesce(
    v_settings->>'whatsapp_distribution_auto_reply_message',
    ''
  ));
  if char_length(v_reply_message) not between 1 and 4000
     or octet_length(v_reply_message) > 16000 then
    return new;
  end if;

  if not (v_settings ? 'whatsapp_distribution_auto_reply_delay_seconds') then
    v_delay_seconds := 30;
  elsif jsonb_typeof(
      v_settings->'whatsapp_distribution_auto_reply_delay_seconds'
    ) = 'number'
    and (v_settings->>'whatsapp_distribution_auto_reply_delay_seconds')
      ~ '^[0-9]{1,4}$' then
    v_delay_seconds := (
      v_settings->>'whatsapp_distribution_auto_reply_delay_seconds'
    )::integer;
  else
    return new;
  end if;
  if v_delay_seconds not between 1 and 3600 then
    return new;
  end if;

  with exact_inbound as (
    select inbound_message.id
    from public.whatsapp_messages as inbound_message
    where inbound_message.organization_id = new.organization_id
      and inbound_message.session_id = v_session_id
      and inbound_message.lead_id = new.lead_id
      and coalesce(inbound_message.from_me, false) = false
      and lower(coalesce(inbound_message.direction, 'inbound')) <> 'outbound'
      and (
        inbound_message.provider_message_id = v_provider_message_id
        or (
          inbound_message.provider_message_id is null
          and inbound_message.message_id = v_provider_message_id
        )
      )
    order by
      case when inbound_message.provider_message_id = v_provider_message_id then 0 else 1 end,
      inbound_message.created_at,
      inbound_message.id
    limit 1
    for update
  )
  update public.whatsapp_messages as inbound_message
     set metadata = case
       when pg_catalog.jsonb_typeof(inbound_message.metadata) = 'object'
         then inbound_message.metadata
       else '{}'::jsonb
     end
       || jsonb_build_object(
         'managed_whatsapp_distribution_auto_reply_reservation',
         jsonb_build_object(
           'version', 'v1',
           'entry_event_id', new.id,
           'round_robin_id', v_round_robin_id,
           'rule_id', v_rule_id,
           'session_id', v_session_id,
           'message', v_reply_message,
           'delay_seconds', v_delay_seconds,
           'reserved_at', pg_catalog.clock_timestamp()
         )
       ),
       updated_at = pg_catalog.clock_timestamp()
    from exact_inbound
   where inbound_message.id = exact_inbound.id;

  return new;
exception
  when others then
    -- This optional acknowledgement must never block lead creation or its
    -- canonical assignment. Invalid/unavailable reservation fails open.
    return new;
end;
$_$;


ALTER FUNCTION private.reserve_managed_whatsapp_distribution_auto_reply_from_entry() OWNER TO postgres;

