--
-- Name: resolve_billing_payment_checkout_snapshot(uuid, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.resolve_billing_payment_checkout_snapshot(p_payment_id uuid, p_allow_legacy_catalog boolean) RETURNS TABLE(snapshot_plan_id uuid, snapshot_billing_period_months integer, snapshot_amount numeric, snapshot_source text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment public.asaas_payments%rowtype;
  v_subscription_count integer;
begin
  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id;

  if not found or v_payment.value is null or v_payment.value <= 0 then
    return;
  end if;

  -- A token already issued for this exact ledger identity keeps its frozen
  -- tuple. Token rotation may change the secret, never the historical price.
  return query
  select
    capability.plan_id,
    capability.billing_period_months,
    capability.amount,
    capability.snapshot_source
  from public.billing_payment_checkout_capabilities as capability
  where capability.payment_id = v_payment.id
    and capability.asaas_payment_id = v_payment.asaas_payment_id
    and capability.organization_id = v_payment.organization_id
    and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
    and capability.plan_id is not null
    and capability.billing_period_months in (1, 6, 12)
    and capability.amount > 0
    and abs(capability.amount - v_payment.value) <= 0.01
  limit 1;

  if found then
    return;
  end if;

  if v_payment.billing_intent_id is not null then
    return query
    select
      intent.pending_plan_id,
      intent.billing_period_months,
      intent.amount,
      'intent'::text
    from private.billing_checkout_intents as intent
    where intent.id = v_payment.billing_intent_id
      and intent.organization_id = v_payment.organization_id
      and intent.pending_plan_id is not null
      and intent.billing_period_months in (1, 6, 12)
      and intent.amount > 0
      and abs(v_payment.value - intent.amount) <= 0.01
    limit 1;

    -- An explicit but corrupt/mismatched intent must never fall through to a
    -- mutable organization snapshot.
    return;
  end if;

  if v_payment.asaas_subscription_id is not null then
    select count(*)
    into v_subscription_count
    from public.subscriptions as subscription
    where subscription.organization_id = v_payment.organization_id
      and subscription.provider_subscription_id = v_payment.asaas_subscription_id;

    if v_subscription_count = 1 then
      return query
      select
        subscription.plan_id,
        subscription.billing_period_months,
        v_payment.value,
        'subscription'::text
      from public.subscriptions as subscription
      where subscription.organization_id = v_payment.organization_id
        and subscription.provider_subscription_id = v_payment.asaas_subscription_id
        and subscription.plan_id is not null
        and subscription.billing_period_months in (1, 6, 12)
      limit 1;

      return;
    elsif v_subscription_count > 1 then
      -- Duplicate subscription ownership is ambiguous and fails closed.
      return;
    end if;
  end if;

  if not coalesce(p_allow_legacy_catalog, false) then
    return;
  end if;

  return query
  select
    organization_row.plan_id,
    organization_row.subscription_billing_period_months,
    round(
      plan.price * organization_row.subscription_billing_period_months,
      2
    ),
    'legacy_catalog'::text
  from public.organizations as organization_row
  join public.admin_subscription_plans as plan
    on plan.id = organization_row.plan_id
  where organization_row.id = v_payment.organization_id
    and organization_row.pending_plan_id is null
    and organization_row.plan_id is not null
    and organization_row.subscription_billing_period_months in (1, 6, 12)
    and plan.price > 0
    and abs(
      v_payment.value - round(
        plan.price * organization_row.subscription_billing_period_months,
        2
      )
    ) <= 0.01
  limit 1;
end
$$;


ALTER FUNCTION private.resolve_billing_payment_checkout_snapshot(p_payment_id uuid, p_allow_legacy_catalog boolean) OWNER TO postgres;

--
-- Name: revoke_whatsapp_grants_on_org_member_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.revoke_whatsapp_grants_on_org_member_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    delete from public.whatsapp_session_access access
    where access.organization_id = old.organization_id
      and (access.user_id = old.user_id or access.granted_by = old.user_id);
    return old;
  end if;

  if old.organization_id is distinct from new.organization_id
    or old.user_id is distinct from new.user_id
    or (coalesce(old.is_active, false) and not coalesce(new.is_active, false))
    or (old.deleted_at is null and new.deleted_at is not null)
  then
    delete from public.whatsapp_session_access access
    where access.organization_id = old.organization_id
      and (access.user_id = old.user_id or access.granted_by = old.user_id);
  elsif lower(btrim(old.role)) in ('owner', 'admin')
    and lower(btrim(new.role)) not in ('owner', 'admin')
  then
    delete from public.whatsapp_session_access access
    where access.organization_id = old.organization_id
      and access.grant_scope = 'organization'
      and access.granted_by = old.user_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.revoke_whatsapp_grants_on_org_member_change() OWNER TO postgres;

--
-- Name: revoke_whatsapp_grants_on_user_deactivation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.revoke_whatsapp_grants_on_user_deactivation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(old.is_active, false) and not coalesce(new.is_active, false) then
    delete from public.whatsapp_session_access access
    where access.user_id = old.id or access.granted_by = old.id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.revoke_whatsapp_grants_on_user_deactivation() OWNER TO postgres;

--
-- Name: revoke_whatsapp_team_grants_on_member_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.revoke_whatsapp_team_grants_on_member_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    delete from public.whatsapp_session_access access
    where access.grant_scope = 'team'
      and access.grant_team_id = old.team_id
      and (access.user_id = old.user_id or access.granted_by = old.user_id);
    return old;
  end if;

  if old.team_id is distinct from new.team_id
    or old.user_id is distinct from new.user_id
    or old.organization_id is distinct from new.organization_id
    or (coalesce(old.is_active, false) and not coalesce(new.is_active, false))
  then
    delete from public.whatsapp_session_access access
    where access.grant_scope = 'team'
      and access.grant_team_id = old.team_id
      and (access.user_id = old.user_id or access.granted_by = old.user_id);
  elsif coalesce(old.is_leader, false) and not coalesce(new.is_leader, false) then
    delete from public.whatsapp_session_access access
    where access.grant_scope = 'team'
      and access.grant_team_id = old.team_id
      and access.granted_by = old.user_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.revoke_whatsapp_team_grants_on_member_change() OWNER TO postgres;

--
-- Name: revoke_whatsapp_team_grants_on_team_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.revoke_whatsapp_team_grants_on_team_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(old.is_active, false) and not coalesce(new.is_active, false)
    or old.organization_id is distinct from new.organization_id
  then
    delete from public.whatsapp_session_access access
    where access.grant_scope = 'team'
      and access.grant_team_id = old.id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.revoke_whatsapp_team_grants_on_team_change() OWNER TO postgres;

--
-- Name: round_robin_has_pending_whatsapp_intake(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.round_robin_has_pending_whatsapp_intake(p_organization_id uuid, p_round_robin_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.whatsapp_webhook_routing_snapshots as routing_snapshot
    left join public.whatsapp_webhook_routing_outcomes as routing_outcome
      on routing_outcome.organization_id = routing_snapshot.organization_id
     and routing_outcome.session_id = routing_snapshot.session_id
     and routing_outcome.provider_message_id =
       routing_snapshot.provider_message_id
     and routing_outcome.ingress_sequence = routing_snapshot.ingress_sequence
    where routing_snapshot.organization_id = p_organization_id
      and routing_snapshot.snapshot @>
        '{"managed_message_distribution":true}'::jsonb
      and routing_snapshot.snapshot->>'origin_round_robin_id' =
        p_round_robin_id::text
      and routing_outcome.provider_message_id is null
      and (
        routing_snapshot.binding_eligible
        or exists (
          select 1
          from public.whatsapp_webhook_inbox as inbox
          where inbox.organization_id = routing_snapshot.organization_id
            and inbox.session_id = routing_snapshot.session_id
            and inbox.event_key = routing_snapshot.inbox_event_key
            and inbox.status in ('pending', 'retry', 'processing', 'dead')
        )
      )
  );
$$;


ALTER FUNCTION private.round_robin_has_pending_whatsapp_intake(p_organization_id uuid, p_round_robin_id uuid) OWNER TO postgres;

--
-- Name: round_robin_rotation_candidates(uuid, uuid, boolean, integer, time without time zone, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.round_robin_rotation_candidates(p_organization_id uuid, p_round_robin_id uuid, p_ignore_availability boolean, p_current_day integer, p_current_time time without time zone, p_required_team_id uuid) RETURNS TABLE(member_id uuid, user_id uuid, team_id uuid, team_member_id uuid, user_name text, "position" integer, candidate_kind integer, candidate_created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with expanded_candidates as (
    -- Direct queue entries. When a team is explicitly attached to the direct
    -- user, membership in that exact team remains mandatory.
    select
      member.id as member_id,
      member.user_id,
      member.team_id,
      team_member.id as team_member_id,
      member.position,
      least(greatest(member.weight, 1), 1000) as weight,
      account.name as user_name,
      0 as candidate_kind,
      coalesce(
        team_member.created_at,
        member.created_at
      ) as candidate_created_at
    from public.round_robin_members as member
    join public.users as account
      on account.id = member.user_id
     and account.is_active is true
    join public.organization_members as organization_member
      on organization_member.organization_id = p_organization_id
     and organization_member.user_id = member.user_id
     and organization_member.is_active = true
     and organization_member.deleted_at is null
     and organization_member.membership_generation = member.membership_generation
    left join public.teams as team
      on team.id = member.team_id
     and team.organization_id = p_organization_id
     and coalesce(team.is_active, true) = true
    left join public.team_members as team_member
      on team_member.team_id = member.team_id
     and team_member.user_id = member.user_id
     and team_member.organization_id = p_organization_id
     and coalesce(team_member.is_active, true) = true
     and team_member.membership_generation = organization_member.membership_generation
    where member.round_robin_id = p_round_robin_id
      and member.organization_id = p_organization_id
      and member.user_id is not null
      and coalesce(member.is_active, true) = true
      and (
        member.team_id is null
        or (team.id is not null and team_member.id is not null)
      )

    union all

    -- Team entries expand only to choose the recipient inside the entry. The
    -- queue-entry weight is applied once after this expansion.
    select
      member.id as member_id,
      team_member.user_id,
      member.team_id,
      team_member.id as team_member_id,
      member.position,
      least(greatest(member.weight, 1), 1000) as weight,
      account.name as user_name,
      1 as candidate_kind,
      team_member.created_at as candidate_created_at
    from public.round_robin_members as member
    join public.teams as team
      on team.id = member.team_id
     and team.organization_id = p_organization_id
     and coalesce(team.is_active, true) = true
    join public.team_members as team_member
      on team_member.team_id = team.id
     and team_member.organization_id = p_organization_id
     and coalesce(team_member.is_active, true) = true
    join public.users as account
      on account.id = team_member.user_id
     and account.is_active is true
    join public.organization_members as organization_member
      on organization_member.organization_id = p_organization_id
     and organization_member.user_id = team_member.user_id
     and organization_member.is_active = true
     and organization_member.deleted_at is null
     and organization_member.membership_generation = team_member.membership_generation
    where member.round_robin_id = p_round_robin_id
      and member.organization_id = p_organization_id
      and member.user_id is null
      and member.team_id is not null
      and coalesce(member.is_active, true) = true
  ),
  availability_filtered_candidates as (
    select candidate.*
    from expanded_candidates as candidate
    where p_ignore_availability
       -- A participant added directly to the queue has no team_member_id and
       -- therefore has no team schedule to enforce, even if that user belongs
       -- to other teams in the organization.
       or candidate.team_member_id is null
       or not exists (
         -- A configured schedule remains configured even when every row is
         -- disabled. Omitting is_active here prevents a silent 24-hour
         -- fail-open for team-bound candidates.
         select 1
         from public.member_availability as availability_any
         where availability_any.organization_id = p_organization_id
           and availability_any.team_member_id = candidate.team_member_id
       )
       or exists (
         select 1
         from public.member_availability as availability
         where availability.organization_id = p_organization_id
           and availability.team_member_id = candidate.team_member_id
           and coalesce(availability.is_active, true) = true
           and (
             (
               availability.day_of_week = p_current_day
               and (
                 coalesce(availability.is_all_day, false) = true
                 or (
                   availability.start_time is not null
                   and availability.end_time is not null
                   and availability.start_time < availability.end_time
                   and p_current_time >= availability.start_time
                   and p_current_time <= availability.end_time
                 )
               )
             )
             or (
               coalesce(availability.is_all_day, false) = false
               and availability.start_time is not null
               and availability.end_time is not null
               and availability.start_time > availability.end_time
               and (
                 (
                   availability.day_of_week = p_current_day
                   and p_current_time >= availability.start_time
                 )
                 or (
                   availability.day_of_week = (p_current_day + 6) % 7
                   and p_current_time <= availability.end_time
                 )
               )
             )
           )
       )
  ),
  deduplicated_candidates as (
    select candidate.*
    from (
      select
        available.*,
        row_number() over (
          partition by available.user_id
          order by
            available.candidate_kind,
            available.position,
            available.candidate_created_at,
            available.member_id,
            available.team_member_id nulls last
        ) as duplicate_rank
      from availability_filtered_candidates as available
    ) as candidate
    where candidate.duplicate_rank = 1
  )
  select candidate.member_id,candidate.user_id,candidate.team_id,candidate.team_member_id,
    candidate.user_name,candidate.position,candidate.candidate_kind,candidate.candidate_created_at
  from deduplicated_candidates candidate
  where exists (select 1 from public.round_robins queue
    where queue.organization_id=p_organization_id and queue.id=p_round_robin_id
      and coalesce(queue.is_active,true) and queue.deleted_at is null
      and not (coalesce(queue.settings,'{}'::jsonb) ? 'operating_schedule'))
    and (p_required_team_id is null or exists (
      select 1 from public.team_members required_member
      join public.teams required_team on required_team.id=required_member.team_id
        and required_team.organization_id=p_organization_id and coalesce(required_team.is_active,true)
      join public.organization_members membership on membership.organization_id=p_organization_id
        and membership.user_id=required_member.user_id and membership.is_active
        and membership.deleted_at is null and membership.membership_generation=required_member.membership_generation
      where required_member.organization_id=p_organization_id and required_member.team_id=p_required_team_id
        and required_member.user_id=candidate.user_id and coalesce(required_member.is_active,true)))
  order by candidate.position,candidate.member_id,candidate.candidate_kind,
    candidate.candidate_created_at,candidate.user_id,candidate.team_member_id nulls last
$$;


ALTER FUNCTION private.round_robin_rotation_candidates(p_organization_id uuid, p_round_robin_id uuid, p_ignore_availability boolean, p_current_day integer, p_current_time time without time zone, p_required_team_id uuid) OWNER TO postgres;

