--
-- Name: safe_legacy_property_offer_price(numeric); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.safe_legacy_property_offer_price(legacy_price numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select case
    when legacy_price >= 0
     and round(legacy_price, 2) <= 99999999999999.99::numeric
      then legacy_price
  end;
$$;


