--
-- Name: safe_uuid(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.safe_uuid(value text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if value is null or value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return null;
  end if;

  return value::uuid;
exception when others then
  return null;
end;
$_$;


ALTER FUNCTION private.safe_uuid(value text) OWNER TO postgres;

--
-- Name: sanitize_whatsapp_attendance_lead_insert(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sanitize_whatsapp_attendance_lead_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_metadata jsonb := coalesce(new.metadata, '{}'::jsonb);
  v_provider_event_id text := btrim(coalesce(
    v_metadata->>'whatsapp_initial_provider_event_id',
    ''
  ));
  v_managed boolean := lower(btrim(coalesce(
    v_metadata->>'managed_whatsapp_message_distribution',
    'false'
  ))) in ('true', '1', 'yes');
  v_ctwa boolean := lower(btrim(coalesce(
    v_metadata->>'ctwa_ad_confirmed',
    'false'
  ))) in ('true', '1', 'yes')
    and v_metadata->>'whatsapp_lead_creation_contract' = 'ctwa_ad_v2';
  v_session_id uuid;
  v_rule_id uuid;
  v_target_round_robin_id uuid;
  v_ctwa_owner_user_id uuid;
  v_ctwa_auto_eligible boolean;
  v_provider_message_id text;
  v_message text;
begin
  -- Never retain a caller-supplied proof in the public lead document.
  new.metadata := v_metadata - 'whatsapp_attendance_initial_message_proof';

  if v_provider_event_id <> '' then
    if v_ctwa then
      begin
        v_session_id := nullif(
          btrim(v_metadata->>'whatsapp_session_id'),
          ''
        )::uuid;
      exception
        when invalid_text_representation then
          raise exception using
            errcode = '23514',
            message = 'whatsapp_ctwa_auto_origin_invalid';
      end;

      if new.id is null
         or new.organization_id is null
         or v_session_id is null
         or new.source_session_id is distinct from v_session_id
         or v_metadata->>'source' is distinct from 'whatsapp'
         or new.first_touch_channel is distinct from 'whatsapp'
         or btrim(coalesce(v_metadata->>'ctwa_confirmation_method', '')) = ''
         or left(
           v_provider_event_id,
           length(v_session_id::text) + 1
         ) <> (v_session_id::text || ':') then
        raise exception using
          errcode = '23514',
          message = 'whatsapp_ctwa_auto_origin_invalid';
      end if;

      v_provider_message_id := substr(
        v_provider_event_id,
        length(v_session_id::text) + 2
      );
      -- Pre-migration inbox rows may lack the durable routing snapshot. Keep
      -- their lead creation intact, but do not mint automatic attendance.
      if btrim(v_provider_message_id) <> ''
         and exists (
           select 1
           from public.whatsapp_webhook_routing_snapshots as route
           join public.whatsapp_webhook_inbox as inbox
             on inbox.organization_id = route.organization_id
            and inbox.session_id = route.session_id
            and inbox.event_key = route.inbox_event_key
           where route.organization_id = new.organization_id
             and route.session_id = v_session_id
             and route.provider_message_id = v_provider_message_id
             and route.binding_eligible = true
             and route.snapshot->>'context_kind' = 'contextual_intake'
             and (
               (v_managed and route.snapshot->>'context_proof' = 'managed_rule')
               or (
                 not v_managed
                 and route.snapshot->>'context_proof' like 'canonical_intake_v1:%'
               )
             )
         ) then
        select session.owner_user_id,
               session.status = 'connected'
                 and coalesce(session.is_active, true) = true
                 and exists (
                   select 1
                   from public.users as owner
                   join public.organization_members as member
                     on member.user_id = owner.id
                    and member.organization_id = session.organization_id
                    and coalesce(member.is_active, true) = true
                   where owner.id = session.owner_user_id
                     and owner.organization_id = session.organization_id
                     and coalesce(owner.is_active, false) = true
                 )
        into v_ctwa_owner_user_id, v_ctwa_auto_eligible
        from public.whatsapp_sessions as session
        where session.id = v_session_id
          and session.organization_id = new.organization_id
          and session.provider = 'evolution_go';
        if v_ctwa_owner_user_id is not null then
          insert into private.whatsapp_ctwa_auto_origins (
            organization_id,
            lead_id,
            session_id,
            owner_user_id,
            auto_entry_eligible,
            provider_event_id,
            provider_message_id
          ) values (
            new.organization_id,
            new.id,
            v_session_id,
            v_ctwa_owner_user_id,
            v_ctwa_auto_eligible,
            v_provider_event_id,
            v_provider_message_id
          );
        end if;
      end if;
    end if;

    if v_managed then
      begin
        v_session_id := nullif(
          btrim(v_metadata->>'whatsapp_session_id'),
          ''
        )::uuid;
        v_rule_id := nullif(
          btrim(v_metadata->>'matched_rule_id'),
          ''
        )::uuid;
        v_target_round_robin_id := nullif(
          btrim(v_metadata->>'target_round_robin_id'),
          ''
        )::uuid;
      exception
        when invalid_text_representation then
          raise exception using
            errcode = '23514',
            message = 'managed_whatsapp_attendance_proof_invalid';
      end;

      if new.id is null
         or new.organization_id is null
         or v_session_id is null
         or new.source_session_id is distinct from v_session_id
         or v_rule_id is null
         or v_target_round_robin_id is null
         or btrim(coalesce(
           v_metadata->>'managed_whatsapp_initial_provider_event_id',
           ''
         )) <> v_provider_event_id
         or left(
           v_provider_event_id,
           length(v_session_id::text) + 1
         ) <> (v_session_id::text || ':') then
        raise exception using
          errcode = '23514',
          message = 'managed_whatsapp_attendance_proof_invalid';
      end if;

      v_provider_message_id := substr(
        v_provider_event_id,
        length(v_session_id::text) + 2
      );
      v_message := coalesce(
        nullif(new.initial_message, ''),
        new.message,
        ''
      );
      if btrim(v_provider_message_id) = '' or btrim(v_message) = '' then
        raise exception using
          errcode = '23514',
          message = 'managed_whatsapp_attendance_proof_invalid';
      end if;

      insert into private.whatsapp_managed_message_proofs (
        organization_id,
        lead_id,
        session_id,
        rule_id,
        target_round_robin_id,
        provider_event_id,
        provider_message_id,
        message_fingerprint
      ) values (
        new.organization_id,
        new.id,
        v_session_id,
        v_rule_id,
        v_target_round_robin_id,
        v_provider_event_id,
        v_provider_message_id,
        private.managed_whatsapp_message_fingerprint(
          new.organization_id,
          v_session_id,
          v_provider_message_id,
          v_message
        )
      );
    end if;

    new.initial_message := null;
    new.message := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.sanitize_whatsapp_attendance_lead_insert() OWNER TO postgres;

--
-- Name: FUNCTION sanitize_whatsapp_attendance_lead_insert(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.sanitize_whatsapp_attendance_lead_insert() IS 'Records immutable CTWA creation and managed validation proofs privately, then removes automatic WhatsApp lead plaintext before persistence and downstream insert effects.';


--
-- Name: scope_distribution_notification_dedupe(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.scope_distribution_notification_dedupe() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_distribution_event_id text;
begin
  v_distribution_event_id := btrim(coalesce(
    new.metadata->>'distribution_event_id',
    ''
  ));

  if coalesce(new.metadata->>'event_key', '') = 'new_lead_received'
     and v_distribution_event_id <> '' then
    new.metadata := jsonb_set(
      coalesce(new.metadata, '{}'::jsonb),
      '{dedupe_key}',
      to_jsonb(
        concat_ws(
          ':',
          'new_lead_received',
          new.lead_id::text,
          new.user_id::text,
          v_distribution_event_id
        )
      ),
      true
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.scope_distribution_notification_dedupe() OWNER TO postgres;

--
-- Name: scrub_expired_whatsapp_normalized_reactions(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.scrub_expired_whatsapp_normalized_reactions(p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_deleted integer;
begin
  if p_limit is null or p_limit < 1 or p_limit > 2000 then
    raise exception using errcode='22023',message='whatsapp_unlinked_retention_limit_invalid';
  end if;
  with candidates as (
    select reaction.id from public.whatsapp_message_reactions reaction
    where exists (
      select 1 from public.whatsapp_messages target
      where target.organization_id=reaction.organization_id and target.session_id=reaction.session_id
        and target.conversation_id=reaction.conversation_id
        and target.capture_state='suppressed' and target.unlinked_retention_scrubbed_at is not null
        and target.metadata->>'unlinked_retention_v1'='expired'
        and (target.id=reaction.target_message_id or (reaction.target_message_id is null
          and coalesce(nullif(target.provider_message_id,''),target.message_id)=reaction.target_provider_message_id
          and not exists (
            select 1 from public.whatsapp_messages protected
            where protected.organization_id=reaction.organization_id and protected.session_id=reaction.session_id
              and coalesce(nullif(protected.provider_message_id,''),protected.message_id)=reaction.target_provider_message_id
              and (protected.capture_state is distinct from 'suppressed'
                or protected.unlinked_retention_scrubbed_at is null
                or protected.metadata->>'unlinked_retention_v1' is distinct from 'expired')
          )))
    )
    order by reaction.id limit p_limit for update of reaction skip locked
  )
  delete from public.whatsapp_message_reactions reaction using candidates
  where reaction.id=candidates.id;
  get diagnostics v_deleted=row_count;
  return v_deleted;
end;
$$;


ALTER FUNCTION private.scrub_expired_whatsapp_normalized_reactions(p_limit integer) OWNER TO postgres;

--
-- Name: scrub_expired_whatsapp_unlinked_conversations(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.scrub_expired_whatsapp_unlinked_conversations(p_message_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_base jsonb; v_inbox jsonb; v_reactions integer;
begin
  v_inbox := private.scrub_expired_whatsapp_unlinked_inbox(p_message_limit);
  v_base := private.scrub_expired_whatsapp_unlinked_conversations_base(p_message_limit);
  if v_base->>'status'='cutover_required' then return v_base; end if;
  v_reactions := private.scrub_expired_whatsapp_normalized_reactions(p_message_limit);
  return v_base || v_inbox || pg_catalog.jsonb_build_object(
    'normalized_reactions_scrubbed',v_reactions,
    'status',case when v_base->>'status'='idle'
      and (coalesce((v_inbox->>'inbox_scrubbed')::integer,0)>0 or v_reactions>0)
      then 'processed' else v_base->>'status' end);
end;
$$;


ALTER FUNCTION private.scrub_expired_whatsapp_unlinked_conversations(p_message_limit integer) OWNER TO postgres;

--
-- Name: scrub_expired_whatsapp_unlinked_conversations_base(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.scrub_expired_whatsapp_unlinked_conversations_base(p_message_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_messages_scrubbed integer := 0;
  v_media_queued integer := 0;
  v_completed integer := 0;
  v_retired integer := 0;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_message_limit is null or p_message_limit < 1 or p_message_limit > 2000 then
    raise exception using errcode = '22023',
      message = 'whatsapp_unlinked_retention_limit_invalid';
  end if;
  if exists (
    select 1 from pg_catalog.pg_constraint as constraint_state
    where constraint_state.conrelid = 'public.whatsapp_conversations'::regclass
      and constraint_state.conname = 'whatsapp_conversations_session_id_remote_jid_key'
  ) then
    return pg_catalog.jsonb_build_object(
      'status', 'cutover_required', 'conversation_id', null,
      'conversations_retired', 0, 'messages_scrubbed', 0,
      'conversations_completed', 0, 'media_queued', 0
    );
  end if;

  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.unlinked_retention_v1
    and conversation.lead_id is null
    and coalesce(conversation.is_group, false) = false
    and conversation.created_at <= v_now - interval '7 days'
    and conversation.unlinked_retention_scrubbed_at is null
    and not private.whatsapp_conversation_has_protected_history(conversation.id)
    and not exists (
      select 1 from public.media_jobs as job
      where job.conversation_id = conversation.id
        and job.status = 'processing'
    )
  order by conversation.created_at, conversation.id
  for update of conversation skip locked
  limit 1;

  if not found then
    return pg_catalog.jsonb_build_object(
      'status', 'idle', 'conversation_id', null,
      'conversations_retired', 0, 'messages_scrubbed', 0,
      'conversations_completed', 0, 'media_queued', 0
    );
  end if;

  -- The existing media claim uses FOR UPDATE SKIP LOCKED on job rows. If a
  -- claim wins, wait for its transaction, then refuse to scrub a processing
  -- job. If this lock wins, the claim skips these jobs and cannot upload a
  -- Storage object after our path snapshot. New INSERTs wait on the parent
  -- conversation lock above and are rejected by the epoch guard after commit.
  perform job.id
  from public.media_jobs as job
  where job.organization_id = v_conversation.organization_id
    and job.conversation_id = v_conversation.id
  order by job.id
  for update of job;

  if exists (
    select 1 from public.media_jobs as job
    where job.organization_id = v_conversation.organization_id
      and job.conversation_id = v_conversation.id
      and job.status = 'processing'
  ) then
    return pg_catalog.jsonb_build_object(
      'status', 'media_processing', 'conversation_id', v_conversation.id,
      'conversations_retired', 0, 'messages_scrubbed', 0,
      'conversations_completed', 0, 'media_queued', 0
    );
  end if;

  if v_conversation.retired_at is null then
    update public.whatsapp_conversations
    set retired_at = v_now,
        updated_at = v_now
    where id = v_conversation.id;
    v_retired := 1;
  end if;

  -- Collect every known Storage object reference before deleting media jobs
  -- or nulling message paths. Upsert requeues an object if it was reused after
  -- an earlier completed GC attempt; claim checks live references again.
  with paths as (
    select distinct path.object_path
    from (
      select message.media_storage_path as object_path
      from public.whatsapp_messages as message
      where message.conversation_id = v_conversation.id
      union all
      select job.storage_path
      from public.media_jobs as job
      where job.conversation_id = v_conversation.id
      union all
      select job.message_key->>'upload_intent_path'
      from public.media_jobs as job
      where job.conversation_id = v_conversation.id
      union all
      select job.message_key->>'repair_storage_path'
      from public.media_jobs as job
      where job.conversation_id = v_conversation.id
    ) as path
    where nullif(pg_catalog.btrim(path.object_path), '') is not null
  )
  insert into private.whatsapp_unlinked_media_gc as gc (
    organization_id, bucket_id, object_path, source_conversation_id
  )
  select v_conversation.organization_id, 'whatsapp-media', path.object_path,
    v_conversation.id
  from paths as path
  on conflict (organization_id, bucket_id, object_path)
  do update set
    source_conversation_id = excluded.source_conversation_id,
    status = case when gc.status in ('completed', 'failed') then 'pending' else gc.status end,
    next_attempt_at = case when gc.status in ('completed', 'failed') then v_now else gc.next_attempt_at end,
    completed_at = case when gc.status in ('completed', 'failed') then null else gc.completed_at end,
    updated_at = v_now;
  get diagnostics v_media_queued = row_count;

  delete from public.media_jobs as job
  where job.conversation_id = v_conversation.id
    and job.organization_id = v_conversation.organization_id;

  with candidates as (
    select message.id
    from public.whatsapp_messages as message
    where message.conversation_id = v_conversation.id
      and message.organization_id = v_conversation.organization_id
      and message.unlinked_retention_scrubbed_at is null
    order by message.id
    for update of message skip locked
    limit p_message_limit
  )
  update public.whatsapp_messages as message
  set capture_state = 'suppressed',
      content = null,
      media_url = null,
      media_mime_type = null,
      media_status = null,
      media_storage_path = null,
      media_error = null,
      media_size = null,
      sender_jid = null,
      sender_name = null,
      reaction_sender_jid = null,
      reaction_sender_name = null,
      reaction_emoji = null,
      metadata = '{"unlinked_retention_v1":"expired"}'::jsonb,
      unlinked_retention_scrubbed_at = v_now
  from candidates
  where message.id = candidates.id;
  get diagnostics v_messages_scrubbed = row_count;

  if not exists (
    select 1 from public.whatsapp_messages as message
    where message.conversation_id = v_conversation.id
      and message.unlinked_retention_scrubbed_at is null
  ) and not private.whatsapp_unlinked_has_unscrubbed_inbox(
    v_conversation.id
  ) then
    delete from public.whatsapp_inbound_logs as log
    where log.conversation_id = v_conversation.id
      and log.organization_id = v_conversation.organization_id;

    update public.whatsapp_conversations
    set contact_name = null,
        contact_phone = null,
        contact_picture = null,
        last_message = null,
        last_message_preview = null,
        last_message_at = null,
        last_message_received_at = null,
        unread_count = 0,
        assigned_user_id = null,
        metadata = '{}'::jsonb,
        unlinked_retention_scrubbed_at = v_now,
        updated_at = v_now
    where id = v_conversation.id;
    v_completed := 1;
  end if;

  return pg_catalog.jsonb_build_object(
    'status', 'processed',
    'conversation_id', v_conversation.id,
    'conversations_retired', v_retired,
    'messages_scrubbed', v_messages_scrubbed,
    'conversations_completed', v_completed,
    'media_queued', v_media_queued
  );
end;
$$;


ALTER FUNCTION private.scrub_expired_whatsapp_unlinked_conversations_base(p_message_limit integer) OWNER TO postgres;

--
-- Name: scrub_expired_whatsapp_unlinked_inbox(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.scrub_expired_whatsapp_unlinked_inbox(p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_exclusive jsonb;
  v_conversation public.whatsapp_conversations%rowtype;
  v_inbox public.whatsapp_webhook_inbox%rowtype;
  v_plan jsonb;
  v_payload jsonb;
  v_provider_id text;
  v_route public.whatsapp_webhook_routing_snapshots%rowtype;
  v_partial_count integer := 0;
  v_partial_terminal integer := 0;
  v_new_terminal integer := 0;
begin
  if p_limit is null or p_limit < 1 or p_limit > 2000 then
    raise exception using errcode = '22023',
      message = 'whatsapp_unlinked_inbox_scrub_limit_invalid';
  end if;
  v_exclusive := private.scrub_expired_whatsapp_unlinked_inbox_exclusive(p_limit);
  if coalesce((v_exclusive->>'inbox_scrubbed')::integer, 0) >= p_limit then
    return v_exclusive || pg_catalog.jsonb_build_object('inbox_partial', 0);
  end if;

  for v_conversation in
    select conversation.*
    from public.whatsapp_conversations as conversation
    where conversation.unlinked_retention_v1
      and conversation.lead_id is null
      and conversation.created_at <= pg_catalog.clock_timestamp() - interval '7 days'
      and conversation.unlinked_retention_scrubbed_at is null
      and coalesce(conversation.is_group, false) = false
      and not private.whatsapp_conversation_has_protected_history(conversation.id)
      and private.whatsapp_unlinked_has_unscrubbed_inbox(conversation.id)
      and exists (
        select 1 from public.whatsapp_webhook_inbox as candidate
        where candidate.organization_id = conversation.organization_id
          and candidate.session_id = conversation.session_id
          and candidate.status in ('pending', 'retry', 'dead', 'processed')
          and private.whatsapp_unlinked_mixed_inbox_plan(
            candidate.id, conversation.id
          ) is not null
      )
    order by conversation.created_at, conversation.id
    limit p_limit
    for update of conversation skip locked
  loop
    for v_inbox in
      select inbox.*
      from public.whatsapp_webhook_inbox as inbox
      where inbox.organization_id = v_conversation.organization_id
        and inbox.session_id = v_conversation.session_id
        and inbox.status in ('pending', 'retry', 'dead', 'processed')
        and inbox.payload <> '{"__vimob_retention":"expired_unlinked_v1"}'::jsonb
        and exists (
          select 1 from public.whatsapp_webhook_routing_snapshots as snapshot
          where snapshot.organization_id = inbox.organization_id
            and snapshot.session_id = inbox.session_id
            and snapshot.inbox_event_key = inbox.event_key
            and snapshot.snapshot->>'unlinked_capture_policy' = 'v1'
            and snapshot.snapshot->>'state' = 'unlinked'
            and (
              snapshot.snapshot->>'conversation_id' = v_conversation.id::text
              or (
                snapshot.snapshot->>'conversation_id' is null
                and (
                  snapshot.routing_key in (
                    'phone:' || coalesce(public.normalize_phone(
                      v_conversation.contact_phone
                    ), ''),
                    'jid:' || pg_catalog.lower(v_conversation.remote_jid)
                  )
                  or exists (
                    select 1 from public.whatsapp_messages as message
                    where message.organization_id = inbox.organization_id
                      and message.session_id = inbox.session_id
                      and message.conversation_id = v_conversation.id
                      and message.provider_message_id = snapshot.provider_message_id
                  )
                )
              )
            )
        )
        and private.whatsapp_unlinked_mixed_inbox_plan(
          inbox.id, v_conversation.id
        ) is not null
      order by inbox.created_at, inbox.id
      limit p_limit
      for update of inbox skip locked
    loop
      v_plan := private.whatsapp_unlinked_mixed_inbox_plan(
        v_inbox.id, v_conversation.id
      );
      if v_plan is null then
        continue;
      end if;
      v_payload := v_plan->'payload';
      for v_provider_id in
        select raw_id.value
        from pg_catalog.jsonb_array_elements_text(
          v_plan->'removed_provider_message_ids'
        ) as raw_id(value)
      loop
        select snapshot.* into v_route
        from public.whatsapp_webhook_routing_snapshots as snapshot
        where snapshot.organization_id = v_inbox.organization_id
          and snapshot.session_id = v_inbox.session_id
          and snapshot.inbox_event_key = v_inbox.event_key
          and snapshot.provider_message_id = v_provider_id;
        insert into public.whatsapp_webhook_routing_outcomes (
          organization_id, session_id, provider_message_id,
          ingress_sequence, completed_inbox_event_key
        ) values (
          v_route.organization_id, v_route.session_id,
          v_route.provider_message_id, v_route.ingress_sequence,
          v_route.inbox_event_key
        ) on conflict (organization_id, session_id, provider_message_id)
          do nothing;
      end loop;
      update public.whatsapp_webhook_inbox as inbox
      set payload = v_payload,
          status = case when v_plan->>'terminal' = 'true'
                         and inbox.status in ('pending', 'retry')
            then 'dead' else inbox.status end,
          dead_lettered_at = case when v_plan->>'terminal' = 'true'
                                 and inbox.status in ('pending', 'retry', 'dead')
            then coalesce(inbox.dead_lettered_at, pg_catalog.clock_timestamp())
            else inbox.dead_lettered_at end,
          last_error = case when v_plan->>'terminal' = 'true'
                            and inbox.status in ('pending', 'retry', 'dead')
            then 'expired_unlinked_epoch_terminalized'
            else inbox.last_error end,
          updated_at = pg_catalog.clock_timestamp()
      where inbox.id = v_inbox.id;
      v_partial_count := v_partial_count + 1;
      if v_plan->>'terminal' = 'true' then
        v_partial_terminal := v_partial_terminal + 1;
        if v_inbox.status in ('pending', 'retry') then
          v_new_terminal := v_new_terminal + 1;
        end if;
      end if;
      exit when v_partial_count +
        coalesce((v_exclusive->>'inbox_scrubbed')::integer, 0) >= p_limit;
    end loop;
    exit when v_partial_count +
      coalesce((v_exclusive->>'inbox_scrubbed')::integer, 0) >= p_limit;
  end loop;
  return v_exclusive || pg_catalog.jsonb_build_object(
    'inbox_scrubbed', coalesce((v_exclusive->>'inbox_scrubbed')::integer, 0)
                       + v_partial_count,
    'inbox_partial', v_partial_count - v_partial_terminal,
    'inbox_terminal', coalesce((v_exclusive->>'inbox_terminal')::integer, 0)
                      + v_partial_terminal,
    'inbox_newly_terminalized',
      coalesce((v_exclusive->>'inbox_newly_terminalized')::integer, 0)
      + v_new_terminal
  );
end;
$$;


ALTER FUNCTION private.scrub_expired_whatsapp_unlinked_inbox(p_limit integer) OWNER TO postgres;

--
-- Name: scrub_expired_whatsapp_unlinked_inbox_exclusive(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.scrub_expired_whatsapp_unlinked_inbox_exclusive(p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_count integer := 0;
  v_terminal integer := 0;
  v_new_terminal integer := 0;
  v_conversation public.whatsapp_conversations%rowtype;
begin
  if p_limit is null or p_limit < 1 or p_limit > 2000 then
    raise exception using errcode = '22023',
      message = 'whatsapp_unlinked_inbox_scrub_limit_invalid';
  end if;
  if exists (
    select 1 from pg_catalog.pg_constraint as constraint_state
    where constraint_state.conrelid = 'public.whatsapp_conversations'::regclass
      and constraint_state.conname = 'whatsapp_conversations_session_id_remote_jid_key'
  ) then
    return pg_catalog.jsonb_build_object(
      'inbox_scrubbed', 0, 'inbox_terminal', 0,
      'inbox_newly_terminalized', 0
    );
  end if;
  -- Human link, ingress snapshot capture, and canonical retention all lock
  -- this parent first. Holding it through inbox redaction makes the 7-day
  -- eligibility decision atomic with those writers.
  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.unlinked_retention_v1
    and conversation.lead_id is null
    and conversation.created_at <= pg_catalog.clock_timestamp() - interval '7 days'
    and conversation.unlinked_retention_scrubbed_at is null
    and coalesce(conversation.is_group, false) = false
    and not private.whatsapp_conversation_has_protected_history(
      conversation.id
    )
    and private.whatsapp_unlinked_has_unscrubbed_inbox(conversation.id)
  order by conversation.created_at, conversation.id
  for update of conversation skip locked
  limit 1;
  if not found then
    return pg_catalog.jsonb_build_object(
      'inbox_scrubbed', 0, 'inbox_terminal', 0,
      'inbox_newly_terminalized', 0
    );
  end if;
  with candidates as (
    select inbox.id, inbox.status as previous_status
    from public.whatsapp_webhook_inbox as inbox
    join public.whatsapp_webhook_routing_snapshots as snapshot
      on snapshot.organization_id = inbox.organization_id
     and snapshot.session_id = inbox.session_id
     and snapshot.inbox_event_key = inbox.event_key
    join public.whatsapp_conversations as conversation
      on conversation.organization_id = inbox.organization_id
     and conversation.session_id = inbox.session_id
     and conversation.id = v_conversation.id
     and (
       snapshot.snapshot->>'conversation_id' = conversation.id::text
       or (
         snapshot.snapshot->>'conversation_id' is null
         and (
           exists (
             select 1 from public.whatsapp_messages as message
             where message.organization_id = inbox.organization_id
               and message.session_id = inbox.session_id
               and message.conversation_id = conversation.id
               and message.provider_message_id = snapshot.provider_message_id
               and (message.capture_state = 'unlinked_ephemeral'
                    or message.unlinked_retention_scrubbed_at is not null)
           )
           or (
             conversation.created_at >= inbox.created_at
             and conversation.created_at < inbox.created_at + interval '7 days'
             and snapshot.routing_key in (
               'phone:' || coalesce(public.normalize_phone(conversation.contact_phone), ''),
               'jid:' || pg_catalog.lower(conversation.remote_jid)
             )
           )
         )
         and not exists (
           select 1 from public.whatsapp_conversations as other_epoch
           where other_epoch.organization_id = conversation.organization_id
             and other_epoch.session_id = conversation.session_id
             and other_epoch.remote_jid = conversation.remote_jid
             and other_epoch.id <> conversation.id
             and other_epoch.created_at >= inbox.created_at
             and other_epoch.created_at < conversation.created_at
         )
       )
     )
    where conversation.unlinked_retention_v1
      and conversation.lead_id is null
      and conversation.created_at <= pg_catalog.clock_timestamp() - interval '7 days'
      and coalesce(conversation.is_group, false) = false
      and snapshot.snapshot->>'unlinked_capture_policy' = 'v1'
      and snapshot.snapshot->>'state' = 'unlinked'
      and snapshot.snapshot->>'context_kind' = 'organic'
      and nullif(snapshot.snapshot->>'event_lead_id', '') is null
      and nullif(snapshot.snapshot->>'current_lead_id', '') is null
      and nullif(snapshot.snapshot->>'quarantine_reason', '') is null
      and inbox.created_at < conversation.created_at + interval '7 days'
      and (conversation.retired_at is null
           or inbox.created_at <= conversation.retired_at)
      and not private.whatsapp_conversation_has_protected_history(conversation.id)
      and not exists (
        select 1 from private.whatsapp_unlinked_history_links as link
        where link.conversation_id = conversation.id
      )
      and private.whatsapp_unlinked_inbox_batch_exclusive(
        inbox.id, conversation.id
      )
      and (
        inbox.status in ('pending', 'retry', 'dead', 'processed')
        or (inbox.status = 'processing'
            and inbox.locked_at < pg_catalog.clock_timestamp() - interval '10 minutes')
      )
      and (inbox.payload <>
             '{"__vimob_retention":"expired_unlinked_v1"}'::jsonb
           or inbox.status in ('pending', 'retry', 'processing'))
    order by inbox.created_at, inbox.id
    for update of inbox skip locked
    limit p_limit
  ), scrubbed as (
    update public.whatsapp_webhook_inbox as inbox
    set payload = '{"__vimob_retention":"expired_unlinked_v1"}'::jsonb,
        status = case when inbox.status in ('pending', 'retry', 'processing')
          then 'dead' else inbox.status end,
        dead_lettered_at = case when inbox.status in ('pending', 'retry', 'processing', 'dead')
          then coalesce(inbox.dead_lettered_at, pg_catalog.clock_timestamp())
          else inbox.dead_lettered_at end,
        locked_at = null,
        locked_by = null,
        last_error = case when inbox.status in ('pending', 'retry', 'processing', 'dead')
          then 'expired_unlinked_epoch_terminalized' else inbox.last_error end,
        updated_at = pg_catalog.clock_timestamp()
    from candidates
    where inbox.id = candidates.id
    returning (inbox.status = 'dead') as terminal,
              (candidates.previous_status in ('pending', 'retry', 'processing'))
                as newly_terminalized
  )
  select count(*)::integer,
         count(*) filter (where scrubbed.terminal)::integer,
         count(*) filter (where scrubbed.newly_terminalized)::integer
  into v_count, v_terminal, v_new_terminal
  from scrubbed;
  return pg_catalog.jsonb_build_object(
    'inbox_scrubbed', v_count,
    'inbox_terminal', v_terminal,
    'inbox_newly_terminalized', v_new_terminal
  );
end;
$$;


ALTER FUNCTION private.scrub_expired_whatsapp_unlinked_inbox_exclusive(p_limit integer) OWNER TO postgres;

--
-- Name: seed_whatsapp_inbound_push_waiting(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.seed_whatsapp_inbound_push_waiting(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_seed private.whatsapp_inbound_push_waiting_seed%rowtype; v_notification record; v_count integer:=0;
begin
  if p_limit is null or p_limit<1 or p_limit>100 then raise exception 'invalid WhatsApp waiting seed batch'; end if;
  select * into v_seed from private.whatsapp_inbound_push_waiting_seed
    where singleton and not completed for update skip locked;
  if not found then return 0; end if;
  for v_notification in
    select notification.id,notification.created_at from public.notifications notification
    where notification.metadata->>'event_key'='whatsapp_inbound_attendant'
      and notification.created_at>=v_seed.created_after and notification.created_at<=v_seed.created_until
      and (v_seed.cursor_created_at is null
        or (notification.created_at,notification.id)>(v_seed.cursor_created_at,v_seed.cursor_notification_id))
    order by notification.created_at,notification.id limit p_limit
  loop
    perform private.register_whatsapp_inbound_push_waiting(v_notification.id);
    v_seed.cursor_created_at:=v_notification.created_at;
    v_seed.cursor_notification_id:=v_notification.id;
    v_count:=v_count+1;
  end loop;
  update private.whatsapp_inbound_push_waiting_seed
    set cursor_created_at=v_seed.cursor_created_at,cursor_notification_id=v_seed.cursor_notification_id,
      completed=(v_count<p_limit) where singleton;
  return v_count;
end;
$$;


ALTER FUNCTION private.seed_whatsapp_inbound_push_waiting(p_limit integer) OWNER TO postgres;

--
-- Name: serialize_property_legacy_location_assignment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.serialize_property_legacy_location_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' then
    if old.city_id is null then
      perform private.lock_property_legacy_location_assignment_name(
        old.organization_id,
        'city',
        old.cidade
      );
    end if;
    if old.neighborhood_id is null then
      perform private.lock_property_legacy_location_assignment_name(
        old.organization_id,
        'neighborhood',
        old.bairro
      );
    end if;
  end if;

  if new.city_id is null then
    perform private.lock_property_legacy_location_assignment_name(
      new.organization_id,
      'city',
      new.cidade
    );
  end if;
  if new.neighborhood_id is null then
    perform private.lock_property_legacy_location_assignment_name(
      new.organization_id,
      'neighborhood',
      new.bairro
    );
  end if;
  return new;
end
$$;


ALTER FUNCTION private.serialize_property_legacy_location_assignment() OWNER TO postgres;

