--
-- Name: set_lead_creation_status_phase(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.set_lead_creation_status_phase(p_organization_id uuid, p_lead_id uuid, p_phase text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  request_role text := coalesce(nullif(pg_catalog.current_setting('role', true), 'none'), session_user);
begin
  if not (pg_catalog.pg_has_role(request_role, 'postgres', 'member')
    or pg_catalog.pg_has_role(request_role, 'service_role', 'member')) then
    raise exception using errcode = '42501', message = 'lead_creation_status_backend_only';
  end if;
  if p_organization_id is null or p_lead_id is null or p_phase is null
     or p_phase not in ('defer', 'apply', 'done') then
    raise exception using errcode = '22023', message = 'invalid_lead_creation_status_phase';
  end if;
  perform pg_catalog.set_config('vimob.lead_creation_status_scope',
    p_organization_id::text || '/' || p_lead_id::text, true);
  perform pg_catalog.set_config('vimob.lead_creation_status_phase', p_phase, true);
end;
$$;


ALTER FUNCTION private.set_lead_creation_status_phase(p_organization_id uuid, p_lead_id uuid, p_phase text) OWNER TO postgres;

--
-- Name: set_membership_generation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.set_membership_generation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' then
    -- The organization/user pair is the membership's logical identity. A
    -- move could reuse the destination pair's old participant generation.
    if old.organization_id is distinct from new.organization_id
       or old.user_id is distinct from new.user_id then
      raise exception using
        errcode = '23514',
        message = 'organization_members_identity_immutable';
    end if;
  end if;

  if tg_op = 'INSERT' then
    -- A legacy hard delete can leave queue/team participants behind. Their
    -- last epoch must not become current merely because the membership row
    -- was recreated. Both lookups use existing user-scoped indexes.
    select greatest(
      coalesce((
        select max(team_member.membership_generation)
        from public.team_members as team_member
        where team_member.organization_id = new.organization_id
          and team_member.user_id = new.user_id
      ), 0),
      coalesce((
        select max(queue_member.membership_generation)
        from public.round_robin_members as queue_member
        where queue_member.organization_id = new.organization_id
          and queue_member.user_id = new.user_id
      ), 0)
    ) + 1 into new.membership_generation;
  elsif old.deleted_at is not null and new.deleted_at is null then
    new.membership_generation := old.membership_generation + 1;
  else
    new.membership_generation := old.membership_generation;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.set_membership_generation() OWNER TO postgres;

