--
-- Name: stamp_schedule_event_outcome_recorded_at(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.stamp_schedule_event_outcome_recorded_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status in ('completed', 'cancelled', 'canceled', 'no_show')
       and new.outcome_recorded_at is null then
      new.outcome_recorded_at := statement_timestamp();
    end if;
    return new;
  end if;

  if new.status is distinct from old.status then
    if new.status = 'scheduled' then
      new.outcome_recorded_at := null;
    elsif new.status in ('completed', 'cancelled', 'canceled', 'no_show') then
      new.outcome_recorded_at := coalesce(new.outcome_recorded_at, statement_timestamp());
    end if;
  elsif new.outcome is distinct from old.outcome
        and new.status in ('completed', 'cancelled', 'canceled', 'no_show') then
    new.outcome_recorded_at := statement_timestamp();
  end if;

  return new;
end
$$;


ALTER FUNCTION private.stamp_schedule_event_outcome_recorded_at() OWNER TO postgres;

--
-- Name: start_notification_delivery(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.start_notification_delivery(p_delivery_id uuid, p_lease_token uuid, p_provider text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_delivery private.notification_deliveries%rowtype;
  v_attempt_number integer;
begin
  if p_delivery_id is null or p_lease_token is null
     or char_length(coalesce(p_provider, '')) > 100 then
    return false;
  end if;

  select * into v_delivery from private.notification_deliveries where id=p_delivery_id;
  if not found then return false; end if;
  if v_delivery.channel='push' and right(coalesce(v_delivery.leased_by,''),26)='|push_device_v3|wa_push_v2'
    and not private.lock_push_notification_recipient(v_delivery.organization_id,v_delivery.user_id,v_delivery.push_token_id) then
    update private.notification_deliveries set status='cancelled',next_attempt_at=null,
      lease_token=null,leased_by=null,lease_expires_at=null,dependency_key=null,blocked_at=null,terminal_at=now(),
      last_error_code='push_recipient_or_device_revoked',last_error_message='The account, membership or device was revoked before provider start.',
      last_error_at=now(),updated_at=now()
    where id=p_delivery_id and status='leased' and lease_token=p_lease_token;
    return false;
  end if;
  update private.notification_deliveries as delivery
  set status = 'sending',
      attempt_count = delivery.attempt_count + 1,
      provider = coalesce(nullif(btrim(p_provider), ''), delivery.provider),
      last_attempt_at = now(),
      updated_at = now()
  where delivery.id = p_delivery_id
    and delivery.status = 'leased'
    and delivery.lease_token = p_lease_token
    and delivery.lease_expires_at > now()
    and delivery.expires_at > now()
    and delivery.attempt_count < delivery.max_attempts
  returning delivery.* into v_delivery;

  if not found then
    return false;
  end if;

  select coalesce(max(attempt.attempt_number), 0) + 1
    into v_attempt_number
  from private.notification_delivery_attempts as attempt
  where attempt.delivery_id = v_delivery.id
    and attempt.event_type = 'send_attempt';

  insert into private.notification_delivery_attempts (
    delivery_id,
    event_type,
    attempt_number,
    lease_token,
    worker_id,
    from_status,
    outcome,
    provider,
    started_at,
    metadata
  )
  values (
    v_delivery.id,
    'send_attempt',
    v_attempt_number,
    p_lease_token,
    v_delivery.leased_by,
    'leased',
    'sending',
    v_delivery.provider,
    now(),
    '{}'::jsonb
  );

  return true;
end
$$;


ALTER FUNCTION private.start_notification_delivery(p_delivery_id uuid, p_lease_token uuid, p_provider text) OWNER TO postgres;

--
-- Name: stop_active_redistribution_on_stage_move(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.stop_active_redistribution_on_stage_move() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.stage_id is not distinct from old.stage_id
     and new.pipeline_id is not distinct from old.pipeline_id then
    return null;
  end if;

  update public.lead_redistribution_jobs
  set status = 'stopped',
      stopped_reason = 'stage_changed',
      stopped_at = now(),
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'stopped_by', 'lead_stage_change',
        'from_pipeline_id', old.pipeline_id,
        'to_pipeline_id', new.pipeline_id,
        'from_stage_id', old.stage_id,
        'to_stage_id', new.stage_id
      )
  where organization_id = new.organization_id
    and lead_id = new.id
    and status in ('pending', 'warning_sent');

  return null;
end;
$$;


ALTER FUNCTION private.stop_active_redistribution_on_stage_move() OWNER TO postgres;

