--
-- Name: sweep_stale_notification_deliveries(interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sweep_stale_notification_deliveries(p_acceptance_timeout interval DEFAULT '01:00:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_acceptance_timeout interval := coalesce(
    p_acceptance_timeout,
    interval '1 hour'
  );
  v_changed integer := 0;
  v_step integer := 0;
begin
  if v_acceptance_timeout < interval '5 minutes'
     or v_acceptance_timeout > interval '30 days' then
    raise exception 'invalid notification acceptance timeout';
  end if;

  with changed as (
    update private.notification_deliveries as delivery
    set status = 'dead_letter',
        next_attempt_at = null,
        lease_token = null,
        leased_by = null,
        lease_expires_at = null,
        dependency_key = null,
        blocked_at = null,
        terminal_at = now(),
        last_error_code = case
          when delivery.expires_at <= now() then 'delivery_ttl_expired'
          else 'delivery_attempt_budget_exhausted'
        end,
        last_error_message = case
          when delivery.expires_at <= now() then 'Notification delivery TTL expired.'
          else 'Notification delivery attempt budget was exhausted.'
        end,
        last_error_at = now(),
        updated_at = now()
    where delivery.status in (
      'queued', 'leased', 'sending', 'accepted', 'retry_wait', 'blocked_dependency'
    )
      and (
        delivery.expires_at <= now()
        or delivery.attempt_count >= delivery.max_attempts
      )
    returning delivery.id, delivery.lease_token
  ),
  attempt_updates as (
    update private.notification_delivery_attempts as attempt
    set outcome = 'dead_letter',
        completed_at = coalesce(attempt.completed_at, now()),
        error_code = 'delivery_swept_to_dead_letter',
        error_message = 'The delivery expired or exhausted its attempt budget.'
    from changed
    where attempt.delivery_id = changed.id
      and attempt.event_type = 'send_attempt'
      and attempt.outcome = 'sending'
    returning attempt.id
  ),
  audit as (
    insert into private.notification_delivery_attempts (
      delivery_id,
      event_type,
      attempt_number,
      from_status,
      outcome,
      completed_at,
      error_code,
      metadata
    )
    select
      changed.id,
      'sweep',
      null,
      null,
      'dead_letter',
      now(),
      'delivery_swept_to_dead_letter',
      jsonb_build_object('reason', 'ttl_or_attempt_budget')
    from changed
    returning id
  )
  select count(*)::integer into v_step from changed;
  v_changed := v_changed + v_step;

  with changed as (
    update private.notification_deliveries as delivery
    set status = 'retry_wait',
        next_attempt_at = now() + private.notification_delivery_retry_delay(
          greatest(delivery.attempt_count, 1)
        ),
        lease_token = null,
        leased_by = null,
        lease_expires_at = null,
        dependency_key = null,
        blocked_at = null,
        terminal_at = null,
        last_error_code = 'delivery_lease_expired',
        last_error_message = 'The delivery worker lease expired before completion.',
        last_error_at = now(),
        updated_at = now()
    where delivery.status in ('leased', 'sending')
      and delivery.lease_expires_at <= now()
      and delivery.expires_at > now()
      and delivery.attempt_count < delivery.max_attempts
    returning delivery.id, delivery.lease_token
  ),
  attempt_updates as (
    update private.notification_delivery_attempts as attempt
    set outcome = 'retry_wait',
        completed_at = coalesce(attempt.completed_at, now()),
        error_code = 'delivery_lease_expired',
        error_message = 'The delivery worker lease expired before completion.'
    from changed
    where attempt.delivery_id = changed.id
      and attempt.event_type = 'send_attempt'
      and attempt.outcome = 'sending'
    returning attempt.id
  ),
  audit as (
    insert into private.notification_delivery_attempts (
      delivery_id,
      event_type,
      attempt_number,
      from_status,
      outcome,
      completed_at,
      error_code,
      metadata
    )
    select
      changed.id,
      'sweep',
      null,
      null,
      'retry_wait',
      now(),
      'delivery_lease_expired',
      jsonb_build_object('reason', 'lease_expired')
    from changed
    returning id
  )
  select count(*)::integer into v_step from changed;
  v_changed := v_changed + v_step;

  -- HTTP acceptance is not proof of delivery. Once the reconciliation window
  -- expires, fence the row for assisted/provider reconciliation instead of
  -- issuing a blind duplicate.
  with changed as (
    update private.notification_deliveries as delivery
    set status = 'blocked_dependency',
        next_attempt_at = null,
        dependency_key = 'receipt_reconciliation_required',
        blocked_at = now(),
        terminal_at = null,
        last_error_code = 'provider_receipt_timeout',
        last_error_message = 'Provider acceptance has no terminal delivery receipt yet.',
        last_error_at = now(),
        updated_at = now()
    where delivery.status = 'accepted'
      and coalesce(delivery.accepted_at, delivery.updated_at)
        <= now() - v_acceptance_timeout
      and delivery.expires_at > now()
      and delivery.attempt_count < delivery.max_attempts
    returning delivery.id
  ),
  audit as (
    insert into private.notification_delivery_attempts (
      delivery_id,
      event_type,
      attempt_number,
      from_status,
      outcome,
      completed_at,
      error_code,
      metadata
    )
    select
      changed.id,
      'sweep',
      null,
      'accepted',
      'blocked_dependency',
      now(),
      'provider_receipt_timeout',
      jsonb_build_object('dependency_key', 'receipt_reconciliation_required')
    from changed
    returning id
  )
  select count(*)::integer into v_step from changed;
  v_changed := v_changed + v_step;

  return v_changed;
end
$$;


ALTER FUNCTION private.sweep_stale_notification_deliveries(p_acceptance_timeout interval) OWNER TO postgres;

--
-- Name: switch_lead_cadence(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.switch_lead_cadence(p_organization_id uuid, p_lead_id uuid, p_cadence_template_id uuid, p_actor_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_lead record;
  current_stage record;
  target_rule record;
  target_template record;
  enrollment_id uuid;
  task_snapshot jsonb;
  cadence_started_at timestamptz := now();
begin
  select lead.*
  into target_lead
  from public.leads lead
  where lead.organization_id = p_organization_id
    and lead.id = p_lead_id
  for update;

  if not found then
    raise exception 'cadence_lead_not_found';
  end if;

  if target_lead.deal_status <> 'open' then
    raise exception 'cadence_lead_not_open';
  end if;

  select
    cycle.id as stage_cycle_id,
    cycle.pipeline_id,
    cycle.stage_id,
    cycle.entered_at,
    cycle.metadata as stage_cycle_metadata,
    stage.stage_key,
    stage.name as stage_name
  into current_stage
  from public.lead_stage_cycles cycle
  join public.stages stage
    on stage.id = cycle.stage_id
   and stage.organization_id = cycle.organization_id
  where cycle.organization_id = p_organization_id
    and cycle.lead_id = p_lead_id
    and cycle.exited_at is null
    and cycle.pipeline_id = target_lead.pipeline_id
    and cycle.stage_id = target_lead.stage_id
  order by cycle.entered_at desc, cycle.id desc
  limit 1
  for share of stage;

  if not found then
    raise exception 'cadence_stage_cycle_not_found';
  end if;

  if coalesce(
    case lower(nullif(current_stage.stage_cycle_metadata->>'historical_backfill', ''))
      when 'true' then true
      when 'false' then false
      else null
    end,
    false
  ) then
    raise exception 'cadence_historical_cycle';
  end if;

  select rule.*
  into target_rule
  from public.stage_operational_configs rule
  where rule.organization_id = p_organization_id
    and rule.stage_id = current_stage.stage_id
  for share;

  if not found then
    raise exception 'cadence_stage_rule_disabled';
  end if;

  if target_rule.cadence_enabled is not true then
    raise exception 'cadence_stage_rule_disabled';
  end if;

  select template.*
  into target_template
  from public.cadence_templates template
  where template.organization_id = p_organization_id
    and template.id = p_cadence_template_id
    and template.is_active = true;

  if not found then
    raise exception 'cadence_template_not_found';
  end if;

  if not coalesce(
    target_template.stage_id = current_stage.stage_id
    or (
      target_template.stage_id is null
      and target_template.pipeline_id = current_stage.pipeline_id
      and target_template.stage_key = current_stage.stage_key
    )
    or (
      target_template.pipeline_id is null
      and target_template.stage_id is null
      and target_template.stage_key = current_stage.stage_key
    ),
    false
  ) then
    raise exception 'cadence_template_incompatible';
  end if;

  if not exists (
    select 1
    from public.cadence_tasks_template task
    where task.organization_id = p_organization_id
      and task.cadence_template_id = target_template.id
  ) then
    raise exception 'cadence_template_empty';
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'id', task.id,
      'position', task.position,
      'title', task.title,
      'description', task.description,
      'type', task.type,
      'observation', task.observation,
      'recommended_message', task.recommended_message,
      'message_template', task.message_template,
      'due_minutes', task.due_minutes,
      'warning_minutes', task.warning_minutes,
      'is_required', task.is_required,
      'outcome_required', task.outcome_required,
      'metadata', task.metadata
    )
    order by task.position, task.id
  )
  into task_snapshot
  from public.cadence_tasks_template task
  where task.organization_id = p_organization_id
    and task.cadence_template_id = target_template.id;

  update public.lead_tasks task
  set status = 'cancelled',
      updated_at = now(),
      metadata = coalesce(task.metadata, '{}'::jsonb) || jsonb_build_object(
        'cancel_reason', 'cadence_switched',
        'lifecycle_outcome', 'cadence_switched',
        'cancelled_at', now(),
        'replacement_template_id', target_template.id
      )
  where task.lead_id = p_lead_id
    and task.status = 'pending'
    and task.is_done = false
    and task.cadence_enrollment_id in (
      select enrollment.id
      from public.cadence_enrollments enrollment
      where enrollment.lead_id = p_lead_id
        and enrollment.status = 'active'
    );

  update public.cadence_enrollments enrollment
  set status = 'cancelled',
      cancelled_at = now(),
      cancel_reason = 'cadence_switched',
      updated_at = now(),
      metadata = coalesce(enrollment.metadata, '{}'::jsonb) || jsonb_build_object(
        'cancel_reason', 'cadence_switched',
        'cancelled_at', now(),
        'replacement_template_id', target_template.id,
        'actor_user_id', p_actor_user_id
      )
  where enrollment.lead_id = p_lead_id
    and enrollment.status = 'active';

  insert into public.cadence_enrollments (
    organization_id,
    lead_id,
    cadence_template_id,
    stage_cycle_id,
    assigned_user_id,
    started_at,
    template_snapshot,
    metadata
  ) values (
    p_organization_id,
    p_lead_id,
    target_template.id,
    current_stage.stage_cycle_id,
    target_lead.assigned_user_id,
    cadence_started_at,
    jsonb_build_object(
      'schema_version', 2,
      'captured_at', cadence_started_at,
      'template', jsonb_build_object(
        'id', target_template.id,
        'name', target_template.name,
        'description', target_template.description,
        'pipeline_id', target_template.pipeline_id,
        'stage_id', target_template.stage_id,
        'stage_key', target_template.stage_key,
        'is_active', target_template.is_active
      ),
      'operational_rule', jsonb_build_object(
        'id', target_rule.id,
        'stage_id', current_stage.stage_id,
        'cadence_enabled', target_rule.cadence_enabled,
        'attention_mode', target_rule.attention_mode,
        'first_outreach_minutes', target_rule.first_outreach_minutes,
        'first_effective_contact_minutes', target_rule.first_effective_contact_minutes,
        'stage_inactivity_minutes', target_rule.stage_inactivity_minutes,
        'stage_max_age_minutes', target_rule.stage_max_age_minutes,
        'warning_minutes', target_rule.warning_minutes,
        'escalation_minutes', target_rule.escalation_minutes,
        'business_hours_only', target_rule.business_hours_only
      ),
      'tasks', task_snapshot
    ),
    jsonb_build_object(
      'source', 'manual_switch',
      'actor_user_id', p_actor_user_id,
      'stage_name', current_stage.stage_name,
      'operational_rule_id', target_rule.id,
      'historical_backfill', coalesce(
        current_stage.stage_cycle_metadata->'historical_backfill',
        'false'::jsonb
      ),
      'has_materialized_obligations', true,
      'materialized_task_count', jsonb_array_length(task_snapshot)
    )
  )
  returning id into enrollment_id;

  insert into public.lead_tasks (
    organization_id,
    lead_id,
    assigned_user_id,
    title,
    description,
    type,
    day_offset,
    due_at,
    due_date,
    is_done,
    status,
    sequence,
    cadence_enrollment_id,
    cadence_template_task_id,
    metadata,
    created_by
  )
  select
    p_organization_id,
    p_lead_id,
    target_lead.assigned_user_id,
    task.title,
    coalesce(nullif(task.description, ''), nullif(task.metadata->>'description', '')),
    coalesce(nullif(task.type, ''), 'call'),
    task.due_minutes / 1440,
    cadence_started_at + make_interval(mins => task.due_minutes),
    (cadence_started_at + make_interval(mins => task.due_minutes))::date,
    false,
    'pending',
    task.position,
    enrollment_id,
    task.id,
    coalesce(task.metadata, '{}'::jsonb) || jsonb_build_object(
      'source', 'cadence',
      'cadence_template_id', target_template.id,
      'due_minutes', task.due_minutes,
      'warning_minutes', task.warning_minutes,
      'is_required', task.is_required,
      'outcome_required', task.outcome_required,
      'warning_at', case
        when task.warning_minutes > 0
          then cadence_started_at
            + make_interval(mins => task.due_minutes - task.warning_minutes)
        else null
      end,
      'message_template', coalesce(task.message_template, task.recommended_message),
      'template_task_snapshot', jsonb_build_object(
        'id', task.id,
        'position', task.position,
        'title', task.title,
        'description', task.description,
        'type', task.type,
        'observation', task.observation,
        'recommended_message', task.recommended_message,
        'message_template', task.message_template,
        'due_minutes', task.due_minutes,
        'warning_minutes', task.warning_minutes,
        'is_required', task.is_required,
        'outcome_required', task.outcome_required
      )
    ),
    p_actor_user_id
  from public.cadence_tasks_template task
  where task.organization_id = p_organization_id
    and task.cadence_template_id = target_template.id;

  insert into public.activities (
    organization_id,
    lead_id,
    user_id,
    type,
    content,
    metadata
  ) values (
    p_organization_id,
    p_lead_id,
    p_actor_user_id,
    'cadence_switched',
    'Cadencia alterada para: ' || target_template.name,
    jsonb_build_object(
      'cadence_enrollment_id', enrollment_id,
      'cadence_template_id', target_template.id,
      'stage_cycle_id', current_stage.stage_cycle_id
    )
  );

  return enrollment_id;
end;
$$;


ALTER FUNCTION private.switch_lead_cadence(p_organization_id uuid, p_lead_id uuid, p_cadence_template_id uuid, p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: sync_asaas_bank_slip_registration_state(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_asaas_bank_slip_registration_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_event_type text := upper(btrim(coalesce(new.raw_event ->> 'event', '')));
  v_is_new_cancellation_event boolean := false;
begin
  if v_event_type = 'PAYMENT_BANK_SLIP_CANCELLED' and new.due_date is not null then
    if tg_op = 'INSERT' then
      v_is_new_cancellation_event := true;
    else
      v_is_new_cancellation_event :=
        new.last_webhook_event_id is distinct from old.last_webhook_event_id
        or new.last_webhook_event_at is distinct from old.last_webhook_event_at;
    end if;
  end if;

  if v_is_new_cancellation_event then
    if tg_op = 'UPDATE' then
      new.bank_slip_registration_cancelled_at := coalesce(
        old.bank_slip_registration_cancelled_at,
        new.last_webhook_event_at,
        clock_timestamp()
      );
    else
      new.bank_slip_registration_cancelled_at := coalesce(
        new.last_webhook_event_at,
        clock_timestamp()
      );
    end if;
    new.bank_slip_registration_cancelled_due_date := new.due_date;
  elsif tg_op = 'UPDATE'
    and old.bank_slip_registration_cancelled_at is not null
    and new.due_date is not null
    and new.due_date is distinct from old.bank_slip_registration_cancelled_due_date then
    new.bank_slip_registration_cancelled_at := null;
    new.bank_slip_registration_cancelled_due_date := null;
  end if;

  return new;
end
$$;


ALTER FUNCTION private.sync_asaas_bank_slip_registration_state() OWNER TO postgres;

--
-- Name: sync_billing_payment_checkout_capability(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_billing_payment_checkout_capability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_snapshot record;
  v_issue_authorized boolean := false;
begin
  -- This trigger executes during migration backfills before the later cleanup
  -- claim table exists. The permanent tenant tombstone is therefore the
  -- dependency-free fence here; the cleanup claim sets is_active=false before
  -- freezing any provider inventory.
  if not exists (
    select 1
    from public.organizations as organization_row
    where organization_row.id = new.organization_id
      and organization_row.is_active = true
  ) then
    update public.billing_payment_checkout_capabilities
    set
      revoked_at = coalesce(revoked_at, clock_timestamp()),
      attempt_lease_id = null,
      attempt_lease_expires_at = null,
      updated_at = clock_timestamp()
    where payment_id = new.id;
    return new;
  end if;

  if private.billing_payment_checkout_is_actionable(new.status) then
    if tg_op = 'INSERT' then
      v_issue_authorized := true;
    else
      -- Provider polling commonly writes the same status repeatedly. A
      -- capability is an absolute-lived bearer, so ordinary polling and
      -- transitions inside the actionable set must never extend or revive it.
      -- A new lifetime is authorized only when the immutable payment identity
      -- changes or when the payment explicitly enters the actionable set.
      v_issue_authorized :=
        old.asaas_payment_id is distinct from new.asaas_payment_id
        or old.organization_id is distinct from new.organization_id
        or old.billing_intent_id is distinct from new.billing_intent_id
        or not private.billing_payment_checkout_is_actionable(old.status);
    end if;

    if not v_issue_authorized then
      return new;
    end if;

    select snapshot.*
    into v_snapshot
    from private.resolve_billing_payment_checkout_snapshot(
      new.id,
      false
    ) as snapshot
    limit 1;

    if found then
      insert into public.billing_payment_checkout_capabilities (
        payment_id,
        asaas_payment_id,
        organization_id,
        billing_intent_id,
        plan_id,
        billing_period_months,
        amount,
        snapshot_source,
        expires_at
      )
      values (
        new.id,
        new.asaas_payment_id,
        new.organization_id,
        new.billing_intent_id,
        v_snapshot.snapshot_plan_id,
        v_snapshot.snapshot_billing_period_months,
        v_snapshot.snapshot_amount,
        v_snapshot.snapshot_source,
        now() + interval '90 days'
      )
      on conflict (payment_id) do update
      set
        asaas_payment_id = excluded.asaas_payment_id,
        organization_id = excluded.organization_id,
        billing_intent_id = excluded.billing_intent_id,
        -- This conflict path is reachable only after the authorization gate
        -- above. Rotate the bearer and reset its absolute lifetime together.
        checkout_token = encode(extensions.gen_random_bytes(32), 'hex'),
        plan_id = excluded.plan_id,
        billing_period_months = excluded.billing_period_months,
        amount = excluded.amount,
        snapshot_source = excluded.snapshot_source,
        expires_at = now() + interval '90 days',
        revoked_at = null,
        attempt_lease_id = null,
        attempt_lease_expires_at = null,
        attempt_window_started_at = null,
        attempt_window_count = 0;
    else
      -- Legacy/provider rows without an immutable checkout tuple remain in the
      -- ledger, but never receive a public token that would resolve to a 404.
      update public.billing_payment_checkout_capabilities
      set
        revoked_at = coalesce(revoked_at, now()),
        attempt_lease_id = null,
        attempt_lease_expires_at = null
      where payment_id = new.id
        and revoked_at is null;
    end if;
  elsif private.billing_payment_checkout_is_paid(new.status) then
    -- Keep the already-issued link alive briefly so the payer can see the
    -- confirmation and immutable Vimob receipt after the webhook wins a race
    -- against the browser poll. No new capability is issued for paid rows.
    update public.billing_payment_checkout_capabilities
    set
      expires_at = least(expires_at, now() + interval '7 days'),
      attempt_lease_id = null,
      attempt_lease_expires_at = null
    where payment_id = new.id
      and revoked_at is null;
  elsif private.billing_payment_checkout_is_terminal(new.status) then
    update public.billing_payment_checkout_capabilities
    set
      revoked_at = coalesce(revoked_at, now()),
      attempt_lease_id = null,
      attempt_lease_expires_at = null
    where payment_id = new.id
      and revoked_at is null;
  end if;

  return new;
end
$$;


ALTER FUNCTION private.sync_billing_payment_checkout_capability() OWNER TO postgres;

--
-- Name: sync_billing_subscription_card_update_payment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_billing_subscription_card_update_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_now timestamptz := clock_timestamp();
begin
  if private.billing_payment_checkout_is_paid(new.status) then
    update private.billing_subscription_card_update_jobs as job
    set
      status = 'pending_update',
      next_attempt_at = v_now,
      last_error_code = null,
      updated_at = v_now
    where job.mode = 'settled_payment'
      and job.payment_id = new.id
      and job.organization_id = new.organization_id
      and job.provider_payment_id = new.asaas_payment_id
      and job.status = 'awaiting_payment'
      and job.provider_card_credential is not null
      and job.expires_at > v_now;
  elsif upper(btrim(coalesce(new.status, '')))
    = 'CREDIT_CARD_CAPTURE_REFUSED' then
    -- A definitive provider refusal proves payWithCreditCard did not settle.
    -- Clear the non-replayable capture marker with its sealed token so the
    -- public checkout may acquire a fresh lease and tokenize a new attempt.
    update private.billing_subscription_card_update_jobs as job
    set
      status = 'cancelled',
      provider_card_credential = null,
      card_last4 = null,
      credential_attempt_lease_id = null,
      capture_request_started_at = null,
      capture_attempt_lease_id = null,
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      last_error_code = 'credit_card_capture_refused',
      cancelled_at = v_now,
      updated_at = v_now
    where job.mode = 'settled_payment'
      and job.payment_id = new.id
      and job.organization_id = new.organization_id
      and job.provider_payment_id = new.asaas_payment_id
      and job.status in ('prepared', 'awaiting_payment')
      and job.provider_request_started_at is null;

    update public.billing_payment_checkout_capabilities
    set
      attempt_lease_id = null,
      attempt_lease_expires_at = null,
      updated_at = v_now
    where payment_id = new.id
      and organization_id = new.organization_id
      and asaas_payment_id = new.asaas_payment_id
      and revoked_at is null;
  elsif private.billing_payment_checkout_is_terminal(new.status) then
    -- Before PUT starts, a reversal can safely cancel and shred the token.
    -- After the durable PUT marker, provider outcome is ambiguous: never lie
    -- with `cancelled`, never let a stale success finalizer win, and surface
    -- an assisted-review event.
    update private.billing_subscription_card_update_jobs as job
    set
      status = 'cancelled',
      provider_card_credential = null,
      credential_attempt_lease_id = null,
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      last_error_code = 'payment_not_settled',
      cancelled_at = v_now,
      updated_at = v_now
    where job.mode = 'settled_payment'
      and job.payment_id = new.id
      and job.organization_id = new.organization_id
      and job.provider_payment_id = new.asaas_payment_id
      and job.status in (
        'prepared', 'awaiting_payment', 'pending_update', 'processing', 'retry'
      )
      and (
        job.provider_request_started_at is null
        or (
          job.status = 'retry'
          and job.provider_outcome_ambiguous_at is null
        )
      );

    update private.billing_subscription_card_update_jobs as job
    set
      status = 'dead',
      provider_card_credential = null,
      credential_attempt_lease_id = null,
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      last_error_code = 'payment_reversed_after_card_update_started',
      manual_review_at = v_now,
      dead_lettered_at = v_now,
      updated_at = v_now
    where job.mode = 'settled_payment'
      and job.payment_id = new.id
      and job.organization_id = new.organization_id
      and job.provider_payment_id = new.asaas_payment_id
      and job.status in (
        'awaiting_payment', 'pending_update', 'processing', 'retry'
      )
      and (
        job.provider_outcome_ambiguous_at is not null
        or job.status = 'processing'
      );

    if found then
      insert into public.error_events (
        organization_id,
        source,
        severity,
        fingerprint,
        message,
        category,
        error_code,
        component,
        metadata,
        occurred_at
      ) values (
        new.organization_id,
        'backend',
        'critical',
        'billing_subscription_card_update_manual:' || new.id::text,
        'Subscription card update requires assisted review',
        'billing',
        'billing_subscription_card_update_manual_review',
        'billing_subscription_card_update_worker',
        jsonb_build_object(
          'payment_id', new.asaas_payment_id,
          'payment_status', upper(btrim(coalesce(new.status, ''))),
          'reason', 'payment_reversed_after_card_update_started'
        ),
        v_now
      )
      on conflict do nothing;
    end if;
  end if;

  return null;
end
$$;


ALTER FUNCTION private.sync_billing_subscription_card_update_payment() OWNER TO postgres;

--
-- Name: sync_cadence_lifecycle(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_cadence_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  exit_reason text;
  terminal_exit boolean;
begin
  if tg_op = 'INSERT' then
    perform private.materialize_cadence_for_stage_cycle(new.id);
    return new;
  end if;

  if new.exited_at is null or old.exited_at is not null then
    return new;
  end if;

  exit_reason := coalesce(new.exited_reason, 'stage_changed');
  terminal_exit := exit_reason in ('won', 'lost');

  update public.lead_tasks task
  set status = case
        when terminal_exit then 'cancelled'
        when lower(coalesce(task.metadata->>'is_required', 'true'))
          not in ('false', 'f', '0', 'no', 'off') then 'skipped'
        else 'cancelled'
      end,
      updated_at = now(),
      metadata = coalesce(task.metadata, '{}'::jsonb) || jsonb_build_object(
        'cancel_reason', exit_reason,
        'stage_cycle_id', new.id,
        'stage_exited_at', new.exited_at,
        'lifecycle_outcome', case
          when terminal_exit then 'terminal_deal_cancelled'
          when lower(coalesce(task.metadata->>'is_required', 'true'))
            not in ('false', 'f', '0', 'no', 'off')
            then 'required_task_skipped'
          else 'optional_task_cancelled'
        end
      )
  where task.cadence_enrollment_id in (
      select enrollment.id
      from public.cadence_enrollments enrollment
      where enrollment.stage_cycle_id = new.id
    )
    and task.status = 'pending'
    and task.is_done = false;

  update public.cadence_enrollments enrollment
  set status = 'cancelled',
      cancelled_at = new.exited_at,
      cancel_reason = exit_reason,
      updated_at = now(),
      metadata = coalesce(enrollment.metadata, '{}'::jsonb) || jsonb_build_object(
        'cancel_reason', exit_reason,
        'stage_cycle_id', new.id,
        'stage_exited_at', new.exited_at,
        'has_skipped_required_tasks', exists (
          select 1
          from public.lead_tasks task
          where task.cadence_enrollment_id = enrollment.id
            and task.status = 'skipped'
        )
      )
  where enrollment.stage_cycle_id = new.id
    and enrollment.status in ('active', 'paused');

  return new;
end;
$$;


ALTER FUNCTION private.sync_cadence_lifecycle() OWNER TO postgres;

--
-- Name: sync_cadence_task_state(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_cadence_task_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.is_done then
    new.status := 'completed';
    new.done_at := coalesce(new.done_at, new.completed_at, now());
    new.completed_at := coalesce(new.completed_at, new.done_at, now());
  elsif new.status = 'completed' then
    new.status := 'pending';
    new.done_at := null;
    new.completed_at := null;
    new.done_by := null;
  end if;
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION private.sync_cadence_task_state() OWNER TO postgres;

--
-- Name: sync_invitation_token_hash(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_invitation_token_hash() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Compatibility for old and new API instances during the rolling deploy.
  -- New instances supply both values temporarily but use only token_hash for
  -- canonical lookups and never expose either value in an API response.
  if new.token is not null then
    if tg_op = 'INSERT' and new.token_hash is null then
      new.token_hash := encode(extensions.digest(new.token, 'sha256'), 'hex');
    elsif tg_op = 'UPDATE'
          and new.token is distinct from old.token
          and new.token_hash is not distinct from old.token_hash then
      new.token_hash := encode(extensions.digest(new.token, 'sha256'), 'hex');
    end if;
  end if;

  if new.token_hash is null then
    raise exception 'invitation token hash is required';
  end if;

  return new;
end
$$;


ALTER FUNCTION private.sync_invitation_token_hash() OWNER TO postgres;

--
-- Name: sync_lead_cadence_assignee(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_lead_cadence_assignee() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.assigned_user_id is distinct from old.assigned_user_id then
    update public.lead_tasks task
    set assigned_user_id = new.assigned_user_id,
        updated_at = now(),
        metadata = jsonb_set(
          coalesce(task.metadata, '{}'::jsonb),
          '{assignment_transfers}',
          (
            case
              when jsonb_typeof(task.metadata->'assignment_transfers') = 'array'
                then task.metadata->'assignment_transfers'
              else '[]'::jsonb
            end
          ) || jsonb_build_array(jsonb_build_object(
            'from', task.assigned_user_id,
            'to', new.assigned_user_id,
            'at', now(),
            'source', 'lead_reassignment'
          )),
          true
        )
    where task.organization_id = new.organization_id
      and task.lead_id = new.id
      and coalesce(
        task.status,
        case when coalesce(task.is_done, false) then 'completed' else 'pending' end
      ) = 'pending'
      and coalesce(task.is_done, false) = false;

    update public.cadence_enrollments enrollment
    set assigned_user_id = new.assigned_user_id,
        updated_at = now(),
        metadata = jsonb_set(
          coalesce(enrollment.metadata, '{}'::jsonb),
          '{assignment_transfers}',
          (
            case
              when jsonb_typeof(enrollment.metadata->'assignment_transfers') = 'array'
                then enrollment.metadata->'assignment_transfers'
              else '[]'::jsonb
            end
          ) || jsonb_build_array(jsonb_build_object(
            'from', old.assigned_user_id,
            'to', new.assigned_user_id,
            'at', now(),
            'source', 'lead_reassignment'
          )),
          true
        )
    where enrollment.organization_id = new.organization_id
      and enrollment.lead_id = new.id
      and enrollment.status = 'active';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.sync_lead_cadence_assignee() OWNER TO postgres;

--
-- Name: sync_linked_property_from_unit_price(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_linked_property_from_unit_price() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  old_table_active boolean := false;
  new_table_active boolean := false;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    select exists (
      select 1
      from public.property_development_price_tables as price_table
      where price_table.organization_id = old.organization_id
        and price_table.development_id = old.development_id
        and price_table.id = old.price_table_id
        and price_table.status = 'active'
    ) into old_table_active;

    if old_table_active then
      perform private.sync_linked_property_price_for_development_unit(
        old.organization_id,
        old.development_id,
        old.unit_id
      );
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    select exists (
      select 1
      from public.property_development_price_tables as price_table
      where price_table.organization_id = new.organization_id
        and price_table.development_id = new.development_id
        and price_table.id = new.price_table_id
        and price_table.status = 'active'
    ) into new_table_active;

    if new_table_active
       and (
         not old_table_active
         or new.organization_id is distinct from old.organization_id
         or new.development_id is distinct from old.development_id
         or new.unit_id is distinct from old.unit_id
       ) then
      perform private.sync_linked_property_price_for_development_unit(
        new.organization_id,
        new.development_id,
        new.unit_id
      );
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.sync_linked_property_from_unit_price() OWNER TO postgres;

--
-- Name: sync_linked_property_price_for_development_unit(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_linked_property_price_for_development_unit(source_organization_id uuid, source_development_id uuid, source_unit_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  active_list_price numeric;
begin
  select unit_price.list_price
    into active_list_price
  from public.property_development_price_tables as price_table
  join public.property_development_unit_prices as unit_price
    on unit_price.organization_id = price_table.organization_id
   and unit_price.development_id = price_table.development_id
   and unit_price.price_table_id = price_table.id
  where price_table.organization_id = source_organization_id
    and price_table.development_id = source_development_id
    and price_table.status = 'active'
    and unit_price.unit_id = source_unit_id
  order by price_table.version desc, price_table.id desc
  limit 1;

  -- A missing row in the active table is an explicit absence of a canonical
  -- price, not permission to keep advertising a stale amount. Assigning the
  -- nullable lookup result therefore also provides the DELETE fallback.
  update public.properties as property
  set preco = active_list_price
  from public.property_development_units as unit
  where unit.organization_id = source_organization_id
    and unit.development_id = source_development_id
    and unit.id = source_unit_id
    and unit.property_id = property.id
    and property.organization_id = source_organization_id
    and property.preco is distinct from active_list_price;
end;
$$;


ALTER FUNCTION private.sync_linked_property_price_for_development_unit(source_organization_id uuid, source_development_id uuid, source_unit_id uuid) OWNER TO postgres;

