-- Name: sync_meta_feedback_module_activation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_meta_feedback_module_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
begin
  if tg_op <> 'INSERT' then
    perform private.reconcile_meta_feedback_module_activation(
      old.organization_id
    );
  end if;

  if tg_op <> 'DELETE'
     and (
       tg_op = 'INSERT'
       or new.organization_id is distinct from old.organization_id
     ) then
    perform private.reconcile_meta_feedback_module_activation(
      new.organization_id
    );
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


