--
-- Name: sync_organization_billing_state(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_organization_billing_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.subscription_status = 'active' and new.plan_id is not null then
    if tg_op = 'INSERT' then
      perform private.sync_organization_plan_modules(new.id, new.plan_id);
    elsif old.subscription_status is distinct from new.subscription_status
          or old.plan_id is distinct from new.plan_id then
      perform private.sync_organization_plan_modules(new.id, new.plan_id);
    end if;
  end if;

  if tg_op = 'INSERT'
     or new.subscription_status is distinct from old.subscription_status then
    update public.subscriptions
    set
      status = new.subscription_status,
      plan_id = coalesce(new.plan_id, plan_id),
      provider_customer_id = coalesce(new.asaas_customer_id, provider_customer_id),
      provider_subscription_id = coalesce(
        new.asaas_subscription_id,
        provider_subscription_id
      ),
      trial_ends_at = coalesce(new.trial_ends_at, trial_ends_at),
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'billing_status_changed_at',
          new.billing_status_changed_at,
          'billing_grace_until',
          new.billing_grace_until,
          'billing_blocked_at',
          new.billing_blocked_at
        )
    where organization_id = new.id;

    insert into public.subscription_logs (
      organization_id,
      event_type,
      status,
      metadata
    )
    values (
      new.id,
      'billing_status_changed',
      new.subscription_status,
      jsonb_build_object(
        'previous_status',
        case when tg_op = 'UPDATE' then old.subscription_status else null end,
        'billing_status_changed_at',
        new.billing_status_changed_at,
        'billing_grace_until',
        new.billing_grace_until,
        'billing_blocked_at',
        new.billing_blocked_at
      )
    );
  end if;

  if nullif(btrim(new.asaas_subscription_id), '') is not null
     and new.subscription_status <> 'cancelled' then
    insert into private.asaas_reconciliation_jobs (
      organization_id,
      provider_subscription_id,
      status,
      next_attempt_at
    )
    values (
      new.id,
      btrim(new.asaas_subscription_id),
      'pending',
      now()
    )
    on conflict (organization_id) do update
    set
      provider_subscription_id = excluded.provider_subscription_id,
      status = case
        when private.asaas_reconciliation_jobs.provider_subscription_id
             is distinct from excluded.provider_subscription_id
          then 'pending'
        else private.asaas_reconciliation_jobs.status
      end,
      attempts = case
        when private.asaas_reconciliation_jobs.provider_subscription_id
             is distinct from excluded.provider_subscription_id
          then 0
        else private.asaas_reconciliation_jobs.attempts
      end,
      next_attempt_at = least(
        private.asaas_reconciliation_jobs.next_attempt_at,
        excluded.next_attempt_at
      ),
      locked_at = case
        when private.asaas_reconciliation_jobs.provider_subscription_id
             is distinct from excluded.provider_subscription_id
          then null
        else private.asaas_reconciliation_jobs.locked_at
      end,
      locked_by = case
        when private.asaas_reconciliation_jobs.provider_subscription_id
             is distinct from excluded.provider_subscription_id
          then null
        else private.asaas_reconciliation_jobs.locked_by
      end,
      last_error = case
        when private.asaas_reconciliation_jobs.provider_subscription_id
             is distinct from excluded.provider_subscription_id
          then null
        else private.asaas_reconciliation_jobs.last_error
      end,
      updated_at = now();
  elsif new.subscription_status = 'cancelled' then
    delete from private.asaas_reconciliation_jobs
    where organization_id = new.id;
  end if;

  return null;
end;
$$;


ALTER FUNCTION private.sync_organization_billing_state() OWNER TO postgres;

--
-- Name: sync_organization_checkout_capability(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_organization_checkout_capability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Compatibility bridge for the currently deployed API. The new API writes
  -- the capability table directly and reuses this value on conflict.
  if new.checkout_token is not null then
    insert into public.organization_checkout_capabilities (
      organization_id,
      checkout_token
    )
    values (new.id, new.checkout_token)
    on conflict (organization_id) do update
    set checkout_token = excluded.checkout_token;
  end if;

  return new;
end
$$;


ALTER FUNCTION private.sync_organization_checkout_capability() OWNER TO postgres;

--
-- Name: sync_organization_plan_modules(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_organization_plan_modules(p_organization_id uuid, p_plan_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_modules text[];
begin
  if p_organization_id is null or p_plan_id is null then
    return;
  end if;

  select array_agg(
    distinct case
      when lower(btrim(module_name)) in ('dashboard', 'leads', 'contacts', 'pipelines') then 'crm'
      else lower(btrim(module_name))
    end
  )
  into v_modules
  from public.admin_subscription_plans plan
  cross join lateral unnest(plan.modules) as module_name
  where plan.id = p_plan_id
    and nullif(btrim(module_name), '') is not null;

  if coalesce(cardinality(v_modules), 0) = 0 then
    v_modules := array['crm', 'agenda', 'whatsapp', 'round_robin']::text[];
  end if;

  select array_agg(distinct module_name)
  into v_modules
  from unnest(
    coalesce(v_modules, array[]::text[])
      || array['crm', 'whatsapp', 'round_robin']::text[]
  ) as required(module_name);

  insert into public.organization_modules (
    organization_id,
    module_name,
    is_enabled,
    updated_at
  )
  select
    p_organization_id,
    candidate.module_name,
    candidate.module_name = any(v_modules),
    now()
  from (
    select unnest(
      array[
        'crm',
        'properties',
        'financial',
        'whatsapp',
        'agenda',
        'cadences',
        'tags',
        'round_robin',
        'reports',
        'automations',
        'webhooks',
        'site',
        'campaigns',
        'api',
        'portals',
        'performance',
        'gamification'
      ]::text[]
    ) as module_name
    union
    select unnest(v_modules)
  ) as candidate
  on conflict (organization_id, module_name) do update
  set
    is_enabled = excluded.is_enabled,
    updated_at = excluded.updated_at;
end;
$$;


ALTER FUNCTION private.sync_organization_plan_modules(p_organization_id uuid, p_plan_id uuid) OWNER TO postgres;

