--
-- Name: sync_property_legacy_offers(public.properties); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_property_legacy_offers(target_property public.properties) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  previous_sync text := current_setting(
    'vimob.property_offer_compatibility_sync',
    true
  );
  deal_text text;
  legacy_status text;
  has_sale boolean;
  has_rent boolean;
  has_seasonal boolean;
  sale_price numeric;
  rent_price numeric;
  actor_id uuid;
begin
  if previous_sync = 'on' then
    return;
  end if;

  perform set_config('vimob.property_offer_compatibility_sync', 'on', true);

  deal_text := lower(
    concat_ws(
      ' ',
      nullif(btrim(target_property.finalidade), ''),
      nullif(btrim(target_property.tipo_de_negocio), '')
    )
  );
  legacy_status := lower(coalesce(target_property.status, ''));
  has_sale := deal_text like '%venda%'
    or deal_text like '%sale%'
    or deal_text like '%lanc%';
  has_rent := deal_text like '%alug%'
    or deal_text like '%loca%'
    or deal_text like '%rent%';
  has_seasonal := deal_text like '%temporada%'
    or deal_text like '%season%';
  sale_price := private.safe_legacy_property_offer_price(target_property.preco);
  rent_price := coalesce(
    private.safe_legacy_property_offer_price(target_property.valor_locacao),
    sale_price
  );
  actor_id := case
    when private.property_user_belongs_to_organization(
      target_property.organization_id,
      target_property.created_by
    ) then target_property.created_by
  end;

  if has_sale
     or (
       not has_sale
       and not has_rent
       and not has_seasonal
       and target_property.preco is not null
     ) then
    insert into public.property_offers as current_offer (
      organization_id,
      property_id,
      offer_type,
      status,
      price,
      currency,
      price_period,
      terms,
      created_by,
      updated_by,
      metadata
    )
    values (
      target_property.organization_id,
      target_property.id,
      'sale',
      case
        when legacy_status in ('sold', 'vendido') then 'completed'
        when legacy_status in ('reserved', 'reservado')
             and sale_price > 0 then 'reserved'
        when legacy_status in (
          'active', 'available', 'ativo', 'disponivel'
        ) and sale_price > 0 then 'active'
        when legacy_status in ('draft', 'rascunho') then 'draft'
        when legacy_status in (
          'inactive', 'archived', 'inativo', 'arquivado'
        ) then 'withdrawn'
        else 'paused'
      end,
      sale_price,
      'BRL',
      'total',
      jsonb_strip_nulls(jsonb_build_object(
        'payment_condition',
        nullif(btrim(target_property.condicao_pagamento), '')
      )),
      actor_id,
      actor_id,
      jsonb_build_object('compatibility_source', 'properties')
    )
    on conflict (property_id, offer_type) do update
    set price = excluded.price,
        price_period = coalesce(current_offer.price_period, excluded.price_period),
        terms = current_offer.terms || excluded.terms,
        status = case
          when current_offer.status = 'active'
               and (excluded.price is null or excluded.price <= 0)
            then 'paused'
          else current_offer.status
        end;
  end if;

  if has_rent and not has_seasonal then
    insert into public.property_offers as current_offer (
      organization_id,
      property_id,
      offer_type,
      status,
      price,
      currency,
      price_period,
      terms,
      created_by,
      updated_by,
      metadata
    )
    values (
      target_property.organization_id,
      target_property.id,
      'rent',
      case
        when legacy_status in ('rented', 'alugado', 'locado')
          then 'completed'
        when legacy_status in ('reserved', 'reservado')
             and rent_price > 0 then 'reserved'
        when legacy_status in (
          'active', 'available', 'ativo', 'disponivel'
        ) and rent_price > 0 then 'active'
        when legacy_status in ('draft', 'rascunho') then 'draft'
        when legacy_status in (
          'inactive', 'archived', 'inativo', 'arquivado'
        ) then 'withdrawn'
        else 'paused'
      end,
      rent_price,
      'BRL',
      'monthly',
      jsonb_strip_nulls(jsonb_build_object(
        'condominium_fee', target_property.condominio,
        'property_tax', target_property.iptu,
        'fire_insurance', target_property.seguro_incendio,
        'service_fee', target_property.taxa_de_servico,
        'guarantee_insurance', target_property.valor_seguro_fianca
      )),
      actor_id,
      actor_id,
      jsonb_build_object('compatibility_source', 'properties')
    )
    on conflict (property_id, offer_type) do update
    set price = excluded.price,
        price_period = coalesce(current_offer.price_period, excluded.price_period),
        terms = current_offer.terms || excluded.terms,
        status = case
          when current_offer.status = 'active'
               and (excluded.price is null or excluded.price <= 0)
            then 'paused'
          else current_offer.status
        end;
  end if;

  if has_seasonal then
    insert into public.property_offers as current_offer (
      organization_id,
      property_id,
      offer_type,
      status,
      price,
      currency,
      price_period,
      terms,
      created_by,
      updated_by,
      metadata
    )
    values (
      target_property.organization_id,
      target_property.id,
      'seasonal',
      case
        when legacy_status in ('rented', 'alugado', 'locado')
          then 'completed'
        when legacy_status in ('reserved', 'reservado')
             and rent_price > 0 then 'reserved'
        when legacy_status in (
          'active', 'available', 'ativo', 'disponivel'
        ) and rent_price > 0 then 'active'
        when legacy_status in ('draft', 'rascunho') then 'draft'
        when legacy_status in (
          'inactive', 'archived', 'inativo', 'arquivado'
        ) then 'withdrawn'
        else 'paused'
      end,
      rent_price,
      'BRL',
      'daily',
      jsonb_strip_nulls(jsonb_build_object(
        'condominium_fee', target_property.condominio,
        'property_tax', target_property.iptu,
        'fire_insurance', target_property.seguro_incendio,
        'service_fee', target_property.taxa_de_servico,
        'guarantee_insurance', target_property.valor_seguro_fianca
      )),
      actor_id,
      actor_id,
      jsonb_build_object('compatibility_source', 'properties')
    )
    on conflict (property_id, offer_type) do update
    set price = excluded.price,
        price_period = coalesce(current_offer.price_period, excluded.price_period),
        terms = current_offer.terms || excluded.terms,
        status = case
          when current_offer.status = 'active'
               and (excluded.price is null or excluded.price <= 0)
            then 'paused'
          else current_offer.status
        end;
  end if;

  perform set_config(
    'vimob.property_offer_compatibility_sync',
    coalesce(previous_sync, ''),
    true
  );
exception
  when others then
    perform set_config(
      'vimob.property_offer_compatibility_sync',
      coalesce(previous_sync, ''),
      true
    );
    raise;
end;
$$;


ALTER FUNCTION private.sync_property_legacy_offers(target_property public.properties) OWNER TO postgres;

--
-- Name: sync_property_legacy_offers_trigger(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_property_legacy_offers_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if current_setting(
       'vimob.property_offer_compatibility_sync',
       true
     ) = 'on' then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.preco is not distinct from old.preco
     and new.valor_locacao is not distinct from old.valor_locacao
     and new.finalidade is not distinct from old.finalidade
     and new.tipo_de_negocio is not distinct from old.tipo_de_negocio
     and new.status is not distinct from old.status
     and new.condicao_pagamento is not distinct from old.condicao_pagamento
     and new.condominio is not distinct from old.condominio
     and new.iptu is not distinct from old.iptu
     and new.seguro_incendio is not distinct from old.seguro_incendio
     and new.taxa_de_servico is not distinct from old.taxa_de_servico
     and new.valor_seguro_fianca is not distinct from old.valor_seguro_fianca then
    return new;
  end if;

  perform private.sync_property_legacy_offers(new);
  return new;
end;
$$;


ALTER FUNCTION private.sync_property_legacy_offers_trigger() OWNER TO postgres;

--
-- Name: sync_property_owner_details(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_property_owner_details() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.properties as property
  set owner_name = new.name,
      owner_phone_residential = new.phone_residential,
      owner_phone_commercial = new.phone_commercial,
      owner_cellphone = new.cellphone,
      owner_email = new.email,
      owner_media_source = new.media_source,
      origin_media = new.media_source,
      owner_notify_email = new.notify_email,
      updated_at = now()
  where property.organization_id = new.organization_id
    and property.owner_id = new.id
    and (property.owner_name, property.owner_phone_residential,
         property.owner_phone_commercial, property.owner_cellphone,
         property.owner_email, property.owner_media_source,
         property.origin_media, property.owner_notify_email)
      is distinct from
        (new.name, new.phone_residential, new.phone_commercial, new.cellphone,
         new.email, new.media_source, new.media_source, new.notify_email);
  return new;
end
$$;


ALTER FUNCTION private.sync_property_owner_details() OWNER TO postgres;

--
-- Name: sync_property_owner_from_ownership(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_property_owner_from_ownership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_previous_guard text := current_setting('vimob.property_owner_sync', true);
begin
  if v_previous_guard = 'on' then
    return coalesce(new, old);
  end if;
  perform pg_catalog.set_config('vimob.property_owner_sync', 'on', true);
  if tg_op in ('UPDATE', 'DELETE') then
    perform private.project_property_owner_from_ownership(old.organization_id, old.property_id);
  end if;
  if tg_op in ('INSERT', 'UPDATE')
     and (tg_op = 'INSERT' or (new.organization_id, new.property_id) is distinct from (old.organization_id, old.property_id)) then
    perform private.project_property_owner_from_ownership(new.organization_id, new.property_id);
  end if;
  perform pg_catalog.set_config('vimob.property_owner_sync', coalesce(v_previous_guard, ''), true);
  return coalesce(new, old);
exception when others then
  perform pg_catalog.set_config('vimob.property_owner_sync', coalesce(v_previous_guard, ''), true);
  raise;
end
$$;


ALTER FUNCTION private.sync_property_owner_from_ownership() OWNER TO postgres;

--
-- Name: sync_property_owner_to_ownership(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_property_owner_to_ownership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_previous_guard text := current_setting('vimob.property_owner_sync', true);
  v_count integer;
  v_current_id uuid;
  v_current_owner_id uuid;
  v_percentage numeric;
  v_primary boolean;
  v_valid_from date;
  v_next_valid_from date;
begin
  if v_previous_guard = 'on' then
    return new;
  end if;

  -- Legacy importers may still create an inline-only owner. The API converts
  -- this shape before INSERT; the database must not erase it if it arrives
  -- through an older trusted integration.
  if tg_op = 'INSERT' and new.owner_id is null then
    return new;
  end if;
  perform pg_catalog.set_config('vimob.property_owner_sync', 'on', true);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.id::text, 0));

  if new.owner_id is not null then
    perform 1
    from public.property_owners owner
    where owner.organization_id = new.organization_id
      and owner.id = new.owner_id
      and coalesce(owner.is_active, true)
    for key share;
    if not found then
      raise exception 'property owner is inactive or outside the organization'
        using errcode = '23514', constraint = 'property_owner_active_reference';
    end if;
  end if;

  select count(*) into v_count
  from public.property_ownerships ownership
  where ownership.organization_id = new.organization_id
    and ownership.property_id = new.id
    and ownership.valid_from <= current_date
    and (ownership.valid_to is null or current_date < ownership.valid_to);

  if v_count > 1 then
    raise exception 'legacy owner_id cannot replace co-ownership'
      using errcode = '23514', constraint = 'property_owner_projection_conflict';
  end if;

  if v_count = 1 then
    select ownership.id, ownership.owner_id, ownership.ownership_percentage,
           ownership.is_primary, ownership.valid_from
      into v_current_id, v_current_owner_id, v_percentage, v_primary, v_valid_from
    from public.property_ownerships ownership
    where ownership.organization_id = new.organization_id
      and ownership.property_id = new.id
      and ownership.valid_from <= current_date
      and (ownership.valid_to is null or current_date < ownership.valid_to)
    for update;
    if not v_primary or v_percentage <> 100 then
      raise exception 'legacy owner_id cannot replace a custom ownership share'
        using errcode = '23514', constraint = 'property_owner_projection_conflict';
    end if;
  end if;

  if v_count = 1 and v_current_owner_id is distinct from new.owner_id then
    if v_valid_from < current_date then
      update public.property_ownerships
      set valid_to = current_date, updated_at = now()
      where id = v_current_id;
    else
      delete from public.property_ownerships where id = v_current_id;
    end if;
    v_count := 0;
  end if;

  if new.owner_id is not null and v_count = 0 then
    select min(ownership.valid_from)
      into v_next_valid_from
    from public.property_ownerships ownership
    where ownership.organization_id = new.organization_id
      and ownership.property_id = new.id
      and ownership.valid_from > current_date;

    insert into public.property_ownerships (
      organization_id, property_id, owner_id, ownership_percentage,
      is_primary, valid_from, valid_to, created_by
    ) values (
      new.organization_id, new.id, new.owner_id, 100,
      true, current_date, v_next_valid_from, new.created_by
    );
  end if;

  perform private.project_property_owner_from_ownership(new.organization_id, new.id);
  perform pg_catalog.set_config('vimob.property_owner_sync', coalesce(v_previous_guard, ''), true);
  return new;
exception when others then
  perform pg_catalog.set_config('vimob.property_owner_sync', coalesce(v_previous_guard, ''), true);
  raise;
end
$$;


ALTER FUNCTION private.sync_property_owner_to_ownership() OWNER TO postgres;

--
-- Name: sync_resend_delivery_to_notification(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_resend_delivery_to_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_status text := lower(btrim(coalesce(new.status, '')));
  v_is_failure boolean := v_provider_status in (
    'failed', 'suppressed', 'bounced', 'complained'
  );
  v_is_delivered boolean := v_provider_status = 'delivered';
  v_is_permanent boolean := v_provider_status in (
    'suppressed', 'bounced', 'complained'
  );
  v_delivery_result jsonb;
  v_normalized_status text;
  v_legacy_status text;
  v_next_attempt_at text;
  v_changed integer := 0;
  v_fingerprint text;
begin
  if new.provider <> 'resend'
     or new.notification_id is null
     or nullif(btrim(coalesce(new.provider_message_id, '')), '') is null
     or (not v_is_failure and not v_is_delivered) then
    return new;
  end if;

  -- Keep the global lock order notification -> delivery. The materialization
  -- trigger follows the same order, avoiding a receipt/producer deadlock.
  perform 1
  from public.notifications as notification
  where notification.id = new.notification_id
    and notification.organization_id is not distinct from new.organization_id
  for update;
  if not found then
    return new;
  end if;

  v_delivery_result := private.apply_notification_delivery_receipt(
    new.notification_id,
    'email',
    'resend',
    new.provider_message_id,
    v_provider_status,
    v_is_delivered,
    v_is_permanent,
    coalesce(new.status_event_at, now())
  );
  v_normalized_status := coalesce(v_delivery_result ->> 'status', '');
  v_legacy_status := case
    when v_normalized_status = 'delivered' then 'delivered'
    when v_normalized_status in ('permanent_failed', 'dead_letter') then 'permanent_failed'
    when v_is_failure then 'failed'
    else 'delivered'
  end;
  v_next_attempt_at := case
    when v_legacy_status = 'failed'
      then coalesce(v_delivery_result ->> 'next_attempt_at', now()::text)
    else ''
  end;

  update public.notifications as notification
  set metadata = jsonb_set(
    jsonb_set(
      coalesce(notification.metadata, '{}'::jsonb),
      '{dispatch,email}',
      (
        coalesce(notification.metadata #> '{dispatch,email}', '{}'::jsonb)
        || jsonb_build_object(
          'status', v_legacy_status,
          'delivery_status', v_provider_status,
          'provider', 'resend',
          'message_id', new.provider_message_id,
          'delivery_event_at', new.status_event_at,
          'alert_required', v_is_failure,
          'next_attempt_at', v_next_attempt_at,
          'error', case
            when v_is_failure then 'provider_' || v_provider_status
            else ''
          end,
          'updated_at', now()
        )
      )
        - 'claim_token'
        - 'claimed_at',
      true
    ),
    '{email_delivery_reconciled_at}',
    to_jsonb(coalesce(new.status_event_at, now())),
    true
  )
  where notification.id = new.notification_id
    and notification.organization_id is not distinct from new.organization_id
    and coalesce(notification.metadata #>> '{dispatch,email,provider}', 'resend') = 'resend'
    and notification.metadata #>> '{dispatch,email,message_id}' = new.provider_message_id
    and coalesce(notification.metadata #>> '{dispatch,email,status}', '') in (
      'accepted', 'sent', 'processing', 'delivery_failed', 'failed',
      'permanent_failed'
    )
    and not (
      notification.metadata #>> '{dispatch,email,status}' = 'delivered'
      and v_is_failure
    );
  get diagnostics v_changed = row_count;

  if v_is_failure and v_changed = 1 then
    v_fingerprint := 'resend_delivery:' || new.notification_id::text || ':'
      || new.provider_message_id || ':' || v_provider_status || ':'
      || coalesce(new.status_event_at::text, 'unknown');
    insert into public.error_events (
      organization_id,
      user_id,
      source,
      severity,
      fingerprint,
      message,
      category,
      error_code,
      component,
      metadata,
      occurred_at
    )
    select
      new.organization_id,
      new.user_id,
      'backend',
      case when v_is_permanent then 'error' else 'warning' end,
      v_fingerprint,
      case
        when v_is_permanent then 'Transactional email delivery requires assisted review'
        else 'Transactional email delivery was requeued after provider failure'
      end,
      'notification_delivery',
      'resend_' || v_provider_status,
      'resend_webhook_reconciliation',
      jsonb_build_object(
        'notification_id', new.notification_id,
        'email_log_id', new.id,
        'provider_status', v_provider_status,
        'delivery_status', v_normalized_status
      ),
      coalesce(new.status_event_at, now())
    where not exists (
      select 1
      from public.error_events as existing
      where existing.fingerprint = v_fingerprint
    );
  end if;

  return new;
end
$$;


ALTER FUNCTION private.sync_resend_delivery_to_notification() OWNER TO postgres;

--
-- Name: FUNCTION sync_resend_delivery_to_notification(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.sync_resend_delivery_to_notification() IS 'Maps a verified Resend terminal delivery event to one exact notification/message CAS; failures become assisted alerts and never auto-loop.';


--
-- Name: sync_round_robin_contract(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_round_robin_contract() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  rules_stage_id uuid;
begin
  if tg_op = 'UPDATE' and old.deleted_at is not null then
    return new;
  end if;

  new.rules := coalesce(new.rules, '{}'::jsonb);

  if coalesce(new.rules->>'target_stage_id', '') ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    rules_stage_id := (new.rules->>'target_stage_id')::uuid;
  end if;

  if tg_op = 'INSERT' then
    new.target_pipeline_id := coalesce(new.target_pipeline_id, new.pipeline_id);
    new.pipeline_id := coalesce(new.pipeline_id, new.target_pipeline_id);
    new.target_stage_id := coalesce(new.target_stage_id, rules_stage_id);
    new.settings := coalesce(
      nullif(new.settings, '{}'::jsonb),
      new.rules->'settings',
      '{}'::jsonb
    );
    new.strategy := coalesce(
      nullif(new.strategy, ''),
      nullif(new.rules->>'strategy', ''),
      'simple'
    );
    new.reentry_behavior := coalesce(
      nullif(new.reentry_behavior, ''),
      nullif(new.rules->>'reentry_behavior', ''),
      'redistribute'
    );
  else
    if new.rules is distinct from old.rules then
      if new.target_stage_id is not distinct from old.target_stage_id then
        new.target_stage_id := rules_stage_id;
      end if;
      if new.settings is not distinct from old.settings then
        new.settings := coalesce(new.rules->'settings', '{}'::jsonb);
      end if;
      if new.strategy is not distinct from old.strategy then
        new.strategy := coalesce(
          nullif(new.rules->>'strategy', ''),
          'simple'
        );
      end if;
      if new.reentry_behavior is not distinct from old.reentry_behavior then
        new.reentry_behavior := coalesce(
          nullif(new.rules->>'reentry_behavior', ''),
          'redistribute'
        );
      end if;
    end if;
    new.target_pipeline_id := coalesce(new.target_pipeline_id, new.pipeline_id);
    new.pipeline_id := coalesce(new.pipeline_id, new.target_pipeline_id);
    new.settings := coalesce(new.settings, '{}'::jsonb);
    new.strategy := coalesce(nullif(new.strategy, ''), 'simple');
    new.reentry_behavior := coalesce(
      nullif(new.reentry_behavior, ''),
      'redistribute'
    );
  end if;

  new.rules := pg_catalog.jsonb_set(
    new.rules,
    '{strategy}',
    pg_catalog.to_jsonb(new.strategy),
    true
  );
  new.rules := pg_catalog.jsonb_set(
    new.rules,
    '{settings}',
    new.settings,
    true
  );
  new.rules := pg_catalog.jsonb_set(
    new.rules,
    '{reentry_behavior}',
    pg_catalog.to_jsonb(new.reentry_behavior),
    true
  );
  if new.target_stage_id is null then
    new.rules := new.rules - 'target_stage_id';
  else
    new.rules := pg_catalog.jsonb_set(
      new.rules,
      '{target_stage_id}',
      pg_catalog.to_jsonb(new.target_stage_id::text),
      true
    );
  end if;
  new.updated_at := pg_catalog.now();
  return new;
end;
$_$;


ALTER FUNCTION private.sync_round_robin_contract() OWNER TO postgres;

--
-- Name: FUNCTION sync_round_robin_contract(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.sync_round_robin_contract() IS 'round_robin_tombstone_aware_v1';


--
-- Name: touch_property_publication_source_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.touch_property_publication_source_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  old_organization_id uuid;
  old_property_id uuid;
  new_organization_id uuid;
  new_property_id uuid;
begin
  if tg_op <> 'INSERT' then
    old_organization_id := old.organization_id;
    old_property_id := old.property_id;
  end if;
  if tg_op <> 'DELETE' then
    new_organization_id := new.organization_id;
    new_property_id := new.property_id;
  end if;

  if old_property_id is not null
     and (
       new_property_id is null
       or old_organization_id is distinct from new_organization_id
       or old_property_id is distinct from new_property_id
     ) then
    update public.properties
    set updated_at = greatest(properties.updated_at + interval '1 microsecond', clock_timestamp())
    where organization_id = old_organization_id
      and id = old_property_id;
  end if;

  if new_property_id is not null then
    update public.properties
    set updated_at = greatest(properties.updated_at + interval '1 microsecond', clock_timestamp())
    where organization_id = new_organization_id
      and id = new_property_id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.touch_property_publication_source_revision() OWNER TO postgres;

--
-- Name: FUNCTION touch_property_publication_source_revision(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.touch_property_publication_source_revision() IS 'Advances the property publication revision after any normalized offer or asset mutation.';


