--
-- Name: unblock_notification_deliveries(uuid, text, text, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.unblock_notification_deliveries(p_organization_id uuid, p_dependency_key text, p_channel text DEFAULT NULL::text, p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 1000), 1), 5000);
  v_changed integer := 0;
begin
  if p_organization_id is null
     or nullif(btrim(coalesce(p_dependency_key, '')), '') is null
     or char_length(p_dependency_key) > 255
     or (p_channel is not null and p_channel not in ('whatsapp', 'push', 'email')) then
    return 0;
  end if;

  with candidates as (
    select delivery.id
    from private.notification_deliveries as delivery
    where delivery.organization_id = p_organization_id
      and delivery.status = 'blocked_dependency'
      and delivery.dependency_key = btrim(p_dependency_key)
      and (p_channel is null or delivery.channel = p_channel)
      and delivery.expires_at > now()
      and delivery.attempt_count < delivery.max_attempts
    order by delivery.priority desc, delivery.created_at asc, delivery.id asc
    limit v_limit
    for update skip locked
  ),
  changed as (
    update private.notification_deliveries as delivery
    set status = 'queued',
        next_attempt_at = now(),
        dependency_key = null,
        blocked_at = null,
        last_error_code = null,
        last_error_message = null,
        last_error_at = null,
        updated_at = now()
    from candidates
    where delivery.id = candidates.id
    returning delivery.id
  ),
  audit as (
    insert into private.notification_delivery_attempts (
      delivery_id,
      event_type,
      attempt_number,
      from_status,
      outcome,
      completed_at,
      metadata
    )
    select
      changed.id,
      'unblock',
      null,
      'blocked_dependency',
      'unblocked',
      now(),
      jsonb_build_object(
        'dependency_key', btrim(p_dependency_key),
        'source', 'dependency_recovered'
      )
    from changed
    returning id
  )
  select count(*)::integer into v_changed from changed;

  return v_changed;
end
$$;


ALTER FUNCTION private.unblock_notification_deliveries(p_organization_id uuid, p_dependency_key text, p_channel text, p_limit integer) OWNER TO postgres;

--
-- Name: update_whatsapp_conversation_routing_head(uuid, uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.update_whatsapp_conversation_routing_head(p_organization_id uuid, p_conversation_id uuid, p_provider_message_id text, p_lead_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_message_id text := nullif(pg_catalog.btrim(p_provider_message_id), '');
  v_session_id uuid;
  v_route_session_id uuid;
  v_routing_key text;
  v_ingress_sequence bigint;
  v_binding_eligible boolean;
begin
  select conversation.session_id
  into v_session_id
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id;

  if not found or v_session_id is null then
    raise exception using errcode = '23503', message = 'whatsapp_routing_head_conversation_not_found';
  end if;

  if v_provider_message_id is not null then
    select
      routing_snapshot.session_id,
      routing_snapshot.routing_key,
      routing_snapshot.ingress_sequence,
      routing_snapshot.binding_eligible
    into
      v_route_session_id,
      v_routing_key,
      v_ingress_sequence,
      v_binding_eligible
    from public.whatsapp_webhook_routing_snapshots as routing_snapshot
    where routing_snapshot.organization_id = p_organization_id
      and routing_snapshot.session_id = v_session_id
      and routing_snapshot.provider_message_id = v_provider_message_id;
  end if;

  if v_provider_message_id is null
     or not found
     or not coalesce(v_binding_eligible, false)
     or v_routing_key = '__session__'
     or v_route_session_id is distinct from v_session_id then
    delete from public.whatsapp_conversation_routing_heads as routing_head
    where routing_head.organization_id = p_organization_id
      and routing_head.conversation_id = p_conversation_id;
    return;
  end if;

  insert into public.whatsapp_conversation_routing_heads (
    organization_id,
    conversation_id,
    session_id,
    routing_key,
    provider_message_id,
    ingress_sequence,
    lead_id,
    updated_at
  ) values (
    p_organization_id,
    p_conversation_id,
    v_session_id,
    v_routing_key,
    v_provider_message_id,
    v_ingress_sequence,
    p_lead_id,
    clock_timestamp()
  )
  on conflict (conversation_id) do update
  set
    organization_id = excluded.organization_id,
    session_id = excluded.session_id,
    routing_key = excluded.routing_key,
    provider_message_id = excluded.provider_message_id,
    ingress_sequence = excluded.ingress_sequence,
    lead_id = excluded.lead_id,
    updated_at = excluded.updated_at
  where public.whatsapp_conversation_routing_heads.organization_id = excluded.organization_id
    and public.whatsapp_conversation_routing_heads.session_id = excluded.session_id
    and public.whatsapp_conversation_routing_heads.ingress_sequence < excluded.ingress_sequence;
end;
$$;


ALTER FUNCTION private.update_whatsapp_conversation_routing_head(p_organization_id uuid, p_conversation_id uuid, p_provider_message_id text, p_lead_id uuid) OWNER TO postgres;

