-- Name: user_has_organization(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.user_has_organization() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_super_admin()
    or exists (
      select 1
      from public.organization_members membership
      join public.users app_user on app_user.id = membership.user_id
      join public.organizations organization on organization.id = membership.organization_id
      where membership.user_id = (select auth.uid())
        and coalesce(membership.is_active, false) = true
        and membership.deleted_at is null
        and coalesce(app_user.is_active, false) = true
        and coalesce(organization.is_active, true) = true
    );
$$;


ALTER FUNCTION private.user_has_organization() OWNER TO postgres;

--
-- Name: user_has_permission(text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.user_has_permission(p_permission_key text, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.user_has_permission_in_organization(
    p_permission_key,
    p_user_id,
    (select app_user.organization_id from public.users as app_user where app_user.id = p_user_id)
  );
$$;


ALTER FUNCTION private.user_has_permission(p_permission_key text, p_user_id uuid) OWNER TO postgres;

--
-- Name: user_has_permission_in_organization(text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.user_has_permission_in_organization(p_permission_key text, p_user_id uuid, p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_super_admin()
    or (
      p_organization_id is not null
      and nullif(pg_catalog.btrim(p_permission_key), '') is not null
      and exists (
        select 1
        from public.users as app_user
        join public.organization_members as member
          on member.user_id = app_user.id
         and member.organization_id = p_organization_id
        join public.organizations as organization
          on organization.id = member.organization_id
        where app_user.id = p_user_id
          and coalesce(app_user.is_active, false) = true
          and coalesce(member.is_active, false) = true
          and member.deleted_at is null
          and coalesce(organization.is_active, true) = true
          and (
            member.role in ('owner', 'admin')
            or exists (
              select 1
              from public.user_organization_roles as assignment
              join public.organization_roles as role
                on role.id = assignment.role_id
               and role.organization_id = assignment.organization_id
              join public.organization_role_permissions as role_permission
                on role_permission.role_id = role.id
               and role_permission.organization_id = role.organization_id
              where assignment.user_id = app_user.id
                and assignment.organization_id = p_organization_id
                and coalesce(assignment.is_active, false) = true
                and coalesce(role.is_active, false) = true
                and pg_catalog.lower(pg_catalog.btrim(role_permission.permission_key))
                    = pg_catalog.lower(pg_catalog.btrim(p_permission_key))
            )
          )
      )
    );
$$;


ALTER FUNCTION private.user_has_permission_in_organization(p_permission_key text, p_user_id uuid, p_organization_id uuid) OWNER TO postgres;

--
-- Name: validate_managed_whatsapp_ctwa_ad(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_managed_whatsapp_ctwa_ad() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_role text := coalesce(auth.role(), '');
  v_trusted_writer boolean := false;
  v_new_automatic_marker boolean := false;
  v_old_automatic_marker boolean := false;
  v_protected_metadata_changed boolean := false;
  v_contract_version text;
  v_confirmation_method text;
  v_declared_confirmation_method text;
  v_contract_valid boolean := false;
begin
  v_trusted_writer := v_actor_role = 'service_role'
    or (
      v_actor_role = ''
      and session_user not in ('anon', 'authenticated', 'authenticator')
    );
  v_new_automatic_marker := btrim(coalesce(new.metadata->>'whatsapp_lead_creation_contract', '')) <> ''
    or btrim(coalesce(new.metadata->>'ctwa_confirmation_method', '')) <> ''
    or lower(btrim(coalesce(new.metadata->>'managed_whatsapp_message_distribution', 'false'))) in ('true', '1', 'yes')
    or lower(btrim(coalesce(new.metadata->>'ctwa_ad_confirmed', 'false'))) in ('true', '1', 'yes')
    or btrim(coalesce(new.metadata->>'whatsapp_initial_provider_event_id', '')) <> ''
    or btrim(coalesce(new.metadata->>'managed_whatsapp_initial_provider_event_id', '')) <> '';
  if tg_op = 'UPDATE' then
    v_old_automatic_marker := btrim(coalesce(old.metadata->>'whatsapp_lead_creation_contract', '')) <> ''
      or btrim(coalesce(old.metadata->>'ctwa_confirmation_method', '')) <> ''
      or lower(btrim(coalesce(old.metadata->>'managed_whatsapp_message_distribution', 'false'))) in ('true', '1', 'yes')
      or lower(btrim(coalesce(old.metadata->>'ctwa_ad_confirmed', 'false'))) in ('true', '1', 'yes')
      or btrim(coalesce(old.metadata->>'whatsapp_initial_provider_event_id', '')) <> ''
      or btrim(coalesce(old.metadata->>'managed_whatsapp_initial_provider_event_id', '')) <> '';
    v_protected_metadata_changed := jsonb_build_object(
      'contract', old.metadata->'whatsapp_lead_creation_contract',
      'confirmation_method', old.metadata->'ctwa_confirmation_method',
      'attribution', old.metadata->'whatsapp_attribution',
      'managed', old.metadata->'managed_whatsapp_message_distribution',
      'rule', old.metadata->'matched_rule_id',
      'session', old.metadata->'whatsapp_session_id',
      'queue', old.metadata->'target_round_robin_id',
      'initial_event', old.metadata->'whatsapp_initial_provider_event_id',
      'managed_initial_event', old.metadata->'managed_whatsapp_initial_provider_event_id',
      'confirmed', old.metadata->'ctwa_ad_confirmed'
    ) is distinct from jsonb_build_object(
      'contract', new.metadata->'whatsapp_lead_creation_contract',
      'confirmation_method', new.metadata->'ctwa_confirmation_method',
      'attribution', new.metadata->'whatsapp_attribution',
      'managed', new.metadata->'managed_whatsapp_message_distribution',
      'rule', new.metadata->'matched_rule_id',
      'session', new.metadata->'whatsapp_session_id',
      'queue', new.metadata->'target_round_robin_id',
      'initial_event', new.metadata->'whatsapp_initial_provider_event_id',
      'managed_initial_event', new.metadata->'managed_whatsapp_initial_provider_event_id',
      'confirmed', new.metadata->'ctwa_ad_confirmed'
    );
  end if;

  if not v_trusted_writer
     and (
       (tg_op = 'INSERT' and v_new_automatic_marker)
       or (tg_op = 'UPDATE' and (v_new_automatic_marker or v_old_automatic_marker) and v_protected_metadata_changed)
     ) then
    raise exception using
      errcode = '42501',
      message = 'trusted_whatsapp_lead_provenance_required';
  end if;

  v_contract_version := btrim(coalesce(new.metadata->>'whatsapp_lead_creation_contract', ''));
  if v_contract_version <> '' then
    v_confirmation_method := private.whatsapp_metadata_ctwa_confirmation_method(
      coalesce(new.metadata, '{}'::jsonb)
    );
    v_declared_confirmation_method := btrim(coalesce(new.metadata->>'ctwa_confirmation_method', ''));

    if v_contract_version = 'ctwa_ad_v1' then
      v_contract_valid := v_confirmation_method = 'entry_point_ctwa_ad'
        and v_declared_confirmation_method in ('', 'entry_point_ctwa_ad');
    elsif v_contract_version = 'ctwa_ad_v2' then
      v_contract_valid := v_confirmation_method in (
        'entry_point_ctwa_ad',
        'evolution_ctwa_clid_v1'
      ) and v_declared_confirmation_method = v_confirmation_method;
    end if;

    if not coalesce(v_contract_valid, false) then
      raise exception using
        errcode = '23514',
        message = 'managed_whatsapp_ctwa_ad_required';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.validate_managed_whatsapp_ctwa_ad() OWNER TO postgres;

--
-- Name: validate_managed_whatsapp_lead_insert(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_managed_whatsapp_lead_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_metadata jsonb := coalesce(new.metadata, '{}'::jsonb);
  v_marker boolean;
  v_rule_id uuid;
  v_session_id uuid;
  v_round_robin_id uuid;
begin
  v_marker := lower(btrim(coalesce(
    v_metadata->>'managed_whatsapp_message_distribution',
    'false'
  ))) in ('true', '1', 'yes');

  if not v_marker then
    return new;
  end if;

  begin
    v_rule_id := nullif(btrim(v_metadata->>'matched_rule_id'), '')::uuid;
    v_session_id := nullif(btrim(v_metadata->>'whatsapp_session_id'), '')::uuid;
    v_round_robin_id := nullif(btrim(v_metadata->>'target_round_robin_id'), '')::uuid;
  exception
    when invalid_text_representation then
      raise exception using
        errcode = '23514',
        message = 'managed_whatsapp_context_invalid';
  end;

  if new.organization_id is null
     or lower(btrim(coalesce(new.source, ''))) <> 'whatsapp'
     or new.source_session_id is distinct from v_session_id
     or v_rule_id is null
     or v_session_id is null
     or v_round_robin_id is null
     or not exists (
       select 1
       from public.whatsapp_inbound_rules as inbound_rule
       join public.round_robin_rules as round_robin_rule
         on round_robin_rule.organization_id = inbound_rule.organization_id
        and round_robin_rule.id = inbound_rule.id
        and round_robin_rule.round_robin_id = inbound_rule.target_round_robin_id
       join public.round_robins as queue
         on queue.organization_id = round_robin_rule.organization_id
        and queue.id = round_robin_rule.round_robin_id
       join public.whatsapp_sessions as whatsapp_session
         on whatsapp_session.organization_id = inbound_rule.organization_id
        and whatsapp_session.id = inbound_rule.session_id
       cross join lateral (
         select btrim(coalesce(
           nullif(round_robin_rule.match_value, ''),
           round_robin_rule.conditions->>'match_value',
           ''
         )) as keyword
       ) as normalized
       where inbound_rule.organization_id = new.organization_id
         and inbound_rule.id = v_rule_id
         and inbound_rule.session_id = v_session_id
         and inbound_rule.target_round_robin_id = v_round_robin_id
         and coalesce(queue.is_active, true) = true
         and coalesce(round_robin_rule.is_active, true) = true
         and coalesce(inbound_rule.is_active, true) = true
         and whatsapp_session.provider = 'evolution_go'
         and coalesce(whatsapp_session.is_active, true) = true
         and lower(btrim(coalesce(whatsapp_session.status, '')))
           not in ('deleted', 'disabled')
         and coalesce(
           nullif(round_robin_rule.match_type, ''),
           round_robin_rule.conditions->>'match_type',
           round_robin_rule.name,
           ''
         ) = 'whatsapp_message_contains'
         and coalesce(
           nullif(btrim(round_robin_rule.match->>'whatsapp_session_id'), ''),
           nullif(btrim(round_robin_rule.conditions->'match'->>'whatsapp_session_id'), '')
         ) = v_session_id::text
         and lower(btrim(coalesce(inbound_rule.match_type, ''))) = 'contains'
         and lower(btrim(coalesce(inbound_rule.match_field, 'message'))) = 'message'
         and normalized.keyword <> ''
         and lower(btrim(coalesce(inbound_rule.match_value, '')))
           = lower(normalized.keyword)
         and lower(btrim(coalesce(queue.settings->>'require_checkin', 'false')))
           not in ('true', '1', 'yes')
         and position(
           lower(normalized.keyword)
           in lower(coalesce(nullif(new.initial_message, ''), new.message, ''))
         ) > 0
     ) then
    raise exception using
      errcode = '23514',
      message = 'managed_whatsapp_context_invalid';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.validate_managed_whatsapp_lead_insert() OWNER TO postgres;

--
-- Name: validate_property_ownership_allocation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_property_ownership_allocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.property_id::text, 0)
  );

  if exists (
    select 1
    from public.property_ownerships as other
    where other.organization_id = new.organization_id
      and other.property_id = new.property_id
      and other.owner_id = new.owner_id
      and other.id <> new.id
      and other.valid_from < coalesce(new.valid_to, 'infinity'::date)
      and new.valid_from < coalesce(other.valid_to, 'infinity'::date)
  ) then
    raise exception using
      errcode = '23514',
      message = 'property_ownership_owner_period_overlap';
  end if;

  if exists (
    with boundaries as (
      select distinct ownership.valid_from as boundary_date
      from public.property_ownerships as ownership
      where ownership.property_id = new.property_id
    )
    select 1
    from boundaries
    where (
      select coalesce(sum(ownership.ownership_percentage), 0)
      from public.property_ownerships as ownership
      where ownership.property_id = new.property_id
        and ownership.valid_from <= boundaries.boundary_date
        and (
          ownership.valid_to is null
          or ownership.valid_to > boundaries.boundary_date
        )
    ) > 100
  ) then
    raise exception using
      errcode = '23514',
      message = 'property_ownership_allocation_exceeds_100';
  end if;

  if exists (
    with boundaries as (
      select distinct ownership.valid_from as boundary_date
      from public.property_ownerships as ownership
      where ownership.property_id = new.property_id
        and ownership.is_primary
    )
    select 1
    from boundaries
    where (
      select count(*)
      from public.property_ownerships as ownership
      where ownership.property_id = new.property_id
        and ownership.is_primary
        and ownership.valid_from <= boundaries.boundary_date
        and (
          ownership.valid_to is null
          or ownership.valid_to > boundaries.boundary_date
        )
    ) > 1
  ) then
    raise exception using
      errcode = '23514',
      message = 'property_ownership_primary_period_overlap';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.validate_property_ownership_allocation() OWNER TO postgres;

--
-- Name: validate_queue_operating_schedule_write(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_queue_operating_schedule_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare timeout_minutes integer; warning_minutes integer;
begin
  if new.settings ? 'operating_schedule' then
    if not private.queue_schedule_valid(new.settings->'operating_schedule') then
      raise exception using errcode='23514',message='invalid_queue_operating_schedule'; end if;
    timeout_minutes := coalesce((new.settings->>'redistribution_timeout_minutes')::integer,20);
    warning_minutes := coalesce((new.settings->>'redistribution_warning_minutes')::integer,0);
    if timeout_minutes not between 1 and 10080 or warning_minutes<0
      or (warning_minutes>0 and (timeout_minutes<=5 or warning_minutes>=timeout_minutes)) then
      raise exception using errcode='23514',message='invalid_queue_redistribution_warning'; end if;
    if new.settings ? 'redistribution_max_attempts' and (new.settings->>'redistribution_max_attempts')::integer not between 0 and 1000 then
      raise exception using errcode='23514',message='invalid_queue_redistribution_limit'; end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.validate_queue_operating_schedule_write() OWNER TO postgres;

--
-- Name: validate_whatsapp_worker_tenant_shape(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_whatsapp_worker_tenant_shape() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  shape_is_valid boolean := false;
begin
  if tg_table_name = 'whatsapp_webhook_inbox' then
    select exists (
      select 1
      from public.whatsapp_sessions as session
      where session.id = new.session_id
        and session.organization_id = new.organization_id
    ) into shape_is_valid;
  elsif tg_table_name = 'whatsapp_outbox' then
    select exists (
      select 1
      from public.whatsapp_sessions as session
      join public.whatsapp_conversations as conversation
        on conversation.id = new.conversation_id
       and conversation.organization_id = new.organization_id
       and conversation.session_id = new.session_id
      join public.whatsapp_messages as message
        on message.id = new.message_id
       and message.organization_id = new.organization_id
       and message.conversation_id = new.conversation_id
       and message.session_id = new.session_id
      where session.id = new.session_id
        and session.organization_id = new.organization_id
    ) into shape_is_valid;
  elsif tg_table_name = 'whatsapp_message_reactions' then
    select exists (
      select 1
      from public.whatsapp_sessions as session
      join public.whatsapp_conversations as conversation
        on conversation.id = new.conversation_id
       and conversation.organization_id = new.organization_id
       and conversation.session_id = new.session_id
      where session.id = new.session_id
        and session.organization_id = new.organization_id
        and (
          new.target_message_id is null
          or exists (
            select 1
            from public.whatsapp_messages as message
            where message.id = new.target_message_id
              and message.organization_id = new.organization_id
              and message.conversation_id = new.conversation_id
              and message.session_id = new.session_id
          )
        )
    ) into shape_is_valid;
  end if;

  if not shape_is_valid then
    raise exception using
      errcode = '23514',
      message = 'WhatsApp worker row crosses organization, session, conversation, or message boundaries';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.validate_whatsapp_worker_tenant_shape() OWNER TO postgres;

--
-- Name: vimob_can_access_whatsapp_session(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.vimob_can_access_whatsapp_session(p_session_id uuid, p_permission text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.whatsapp_sessions session
    where session.id = p_session_id
      and coalesce(session.is_active, true) = true
      and coalesce(session.status, '') <> 'deleted'
      and session.provider = 'evolution_go'
      and session.owner_user_id = (select auth.uid())
      and private.is_org_member(session.organization_id)
  );
$$;


ALTER FUNCTION private.vimob_can_access_whatsapp_session(p_session_id uuid, p_permission text) OWNER TO postgres;

--
-- Name: vimob_user_has_active_org_membership(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.vimob_user_has_active_org_membership(p_org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.organization_members membership
      join public.users app_user on app_user.id = membership.user_id
      join public.organizations organization on organization.id = membership.organization_id
      where membership.user_id = (select auth.uid())
        and membership.organization_id = p_org_id
        and coalesce(membership.is_active, false) = true
        and membership.deleted_at is null
        and coalesce(app_user.is_active, false) = true
        and coalesce(organization.is_active, true) = true
    );
$$;


ALTER FUNCTION private.vimob_user_has_active_org_membership(p_org_id uuid) OWNER TO postgres;

--
-- Name: vimob_users_share_active_org(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.vimob_users_share_active_org(p_target_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.organization_members caller
    join public.organization_members target
      on target.organization_id = caller.organization_id
    join public.users caller_user on caller_user.id = caller.user_id
    join public.organizations organization on organization.id = caller.organization_id
    where caller.user_id = (select auth.uid())
      and caller.organization_id = private.get_user_organization_id()
      and coalesce(caller.is_active, false) = true
      and caller.deleted_at is null
      and coalesce(caller_user.is_active, false) = true
      and coalesce(organization.is_active, true) = true
      and target.user_id = p_target_user_id
      and target.deleted_at is null
      and (
        coalesce(target.is_active, false) = true
        or caller.role in ('owner', 'admin')
        or private.is_super_admin()
      )
  );
$$;


ALTER FUNCTION private.vimob_users_share_active_org(p_target_user_id uuid) OWNER TO postgres;

--
-- Name: vista_delete_api_key(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.vista_delete_api_key() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'vault', 'private'
    AS $$
begin
  if old.api_key_secret_ref is not null then
    delete from vault.secrets where id = old.api_key_secret_ref;
  end if;
  return old;
end;
$$;


ALTER FUNCTION private.vista_delete_api_key() OWNER TO postgres;

--
-- Name: vista_store_api_key(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.vista_store_api_key() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'vault', 'private'
    AS $$
declare
  secret_value text := nullif(btrim(new.api_key), '');
  secret_id uuid := new.api_key_secret_ref;
  secret_name text := 'vimob_vista_api_key_' || new.organization_id::text;
begin
  if secret_id is null then
    select v.api_key_secret_ref
    into secret_id
    from public.vista_integrations v
    where v.organization_id = new.organization_id
    limit 1;
  end if;

  if secret_id is null then
    select s.id
    into secret_id
    from vault.secrets s
    where s.name = secret_name;
  end if;

  if secret_value is not null then
    if secret_id is null then
      secret_id := vault.create_secret(
        secret_value,
        secret_name,
        'Vista API key for organization ' || new.organization_id::text
      );
    else
      perform vault.update_secret(
        secret_id,
        secret_value,
        secret_name,
        'Vista API key for organization ' || new.organization_id::text
      );
    end if;
  end if;

  if secret_id is null then
    raise exception 'Vista API key is required';
  end if;

  new.api_key_secret_ref := secret_id;
  new.api_key := null;
  return new;
end;
$$;


ALTER FUNCTION private.vista_store_api_key() OWNER TO postgres;

--
-- Name: wake_notification_deliveries_after_whatsapp_connect(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.wake_notification_deliveries_after_whatsapp_connect() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_dependency_key text;
begin
  if new.status <> 'connected'
     or new.is_notification_session is not true
     or new.is_active is not true then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and old.status = 'connected'
     and old.is_notification_session is true
     and old.is_active is true then
    return new;
  end if;

  foreach v_dependency_key in array array[
    'whatsapp_session_disconnected'::text,
    'whatsapp_session_unavailable'::text,
    'whatsapp_session_reconnecting'::text,
    'whatsapp_qr_required'::text
  ]
  loop
    perform private.unblock_notification_deliveries(
      new.organization_id,
      v_dependency_key,
      'whatsapp',
      5000
    );
  end loop;

  return new;
end
$$;


ALTER FUNCTION private.wake_notification_deliveries_after_whatsapp_connect() OWNER TO postgres;

--
-- Name: whatsapp_actor_can_read_lead(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_actor_can_read_lead(p_organization_id uuid, p_lead_id uuid, p_actor_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.leads as lead
    join public.organization_members as membership
      on membership.organization_id = lead.organization_id
     and membership.user_id = p_actor_user_id
     and membership.is_active
     and membership.deleted_at is null
    join public.users as actor
      on actor.id = p_actor_user_id
     and actor.organization_id = lead.organization_id
     and coalesce(actor.is_active, false)
    where lead.id = p_lead_id
      and lead.organization_id = p_organization_id
      and (
        membership.role in ('owner', 'admin')
        or private.whatsapp_actor_has_lead_permission(
          p_organization_id, p_actor_user_id, 'lead_view_all'
        )
        or (lead.assigned_user_id = p_actor_user_id
            and private.whatsapp_actor_has_lead_permission(
              p_organization_id, p_actor_user_id, 'lead_view_own'
            ))
        or (
          private.whatsapp_actor_has_lead_permission(
            p_organization_id, p_actor_user_id, 'lead_view_team'
          )
          and exists (
            select 1
            from public.team_members as leader
            join public.organization_members as leader_membership
              on leader_membership.organization_id = leader.organization_id
             and leader_membership.user_id = leader.user_id
             and leader_membership.is_active = true
             and leader_membership.deleted_at is null
             and leader_membership.membership_generation = leader.membership_generation
            join public.teams as team
              on team.id = leader.team_id
             and team.organization_id = leader.organization_id
             and coalesce(team.is_active, true)
            where leader.organization_id = p_organization_id
              and leader.user_id = p_actor_user_id
              and leader.is_active and leader.is_leader
              and (
                (lead.assigned_user_id is null and team.id = lead.team_id)
                or (lead.assigned_user_id is not null
                  and exists (
                    select 1
                    from public.team_members as broker_member
                    join public.users as broker
                      on broker.id = broker_member.user_id
                     and coalesce(broker.is_active, false)
                    join public.organization_members as broker_org_member
                      on broker_org_member.organization_id = broker_member.organization_id
                     and broker_org_member.user_id = broker_member.user_id
                     and broker_org_member.is_active
                     and broker_org_member.deleted_at is null
                     and broker_org_member.membership_generation = broker_member.membership_generation
                    where broker_member.organization_id = p_organization_id
                      and broker_member.team_id = team.id
                      and broker_member.user_id = lead.assigned_user_id
                      and broker_member.is_active
                  ))
              )
          )
        )
      )
  );
$$;


ALTER FUNCTION private.whatsapp_actor_can_read_lead(p_organization_id uuid, p_lead_id uuid, p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_actor_has_lead_permission(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_actor_has_lead_permission(p_organization_id uuid, p_actor_user_id uuid, p_permission_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text;
  v_override boolean;
  v_default boolean := false;
  v_granted boolean := false;
begin
  if p_permission_key not in ('lead_view_all', 'lead_view_own', 'lead_view_team')
     or p_organization_id is null or p_actor_user_id is null then
    return false;
  end if;
  select member.role into v_role
  from public.organization_members as member
  join public.users as actor
    on actor.id = member.user_id
   and actor.organization_id = member.organization_id
   and coalesce(actor.is_active, false)
  where member.organization_id = p_organization_id
    and member.user_id = p_actor_user_id
    and member.is_active and member.deleted_at is null;
  if v_role is null then return false; end if;
  if v_role in ('owner', 'admin') then return true; end if;

  select override.allowed into v_override
  from public.user_permission_overrides as override
  where override.organization_id = p_organization_id
    and override.user_id = p_actor_user_id
    and pg_catalog.lower(pg_catalog.btrim(override.permission_key)) = p_permission_key
  limit 1;
  if found then return v_override; end if;

  v_default := p_permission_key = 'lead_view_own'
    or (p_permission_key = 'lead_view_all' and v_role = 'manager')
    or (p_permission_key = 'lead_view_team' and exists (
      select 1
      from public.team_members as leader
      join public.organization_members as leader_membership
        on leader_membership.organization_id = leader.organization_id
       and leader_membership.user_id = leader.user_id
       and leader_membership.is_active = true
       and leader_membership.deleted_at is null
       and leader_membership.membership_generation = leader.membership_generation
      join public.teams as team
        on team.id = leader.team_id
       and team.organization_id = leader.organization_id
       and coalesce(team.is_active, true)
      where leader.organization_id = p_organization_id
        and leader.user_id = p_actor_user_id
        and leader.is_active and leader.is_leader
    ));
  select exists (
    select 1
    from public.user_organization_roles as user_role
    join public.organization_roles as role_row
      on role_row.id = user_role.role_id
     and role_row.organization_id = user_role.organization_id
     and coalesce(role_row.is_active, false)
    join public.organization_role_permissions as role_permission
      on role_permission.role_id = user_role.role_id
     and role_permission.organization_id = user_role.organization_id
    join public.available_permissions as permission
      on permission.id = role_permission.permission_id
    where user_role.organization_id = p_organization_id
      and user_role.user_id = p_actor_user_id
      and user_role.is_active
      and (
        permission.key = p_permission_key
        or (p_permission_key = 'lead_view_all'
            and permission.key in ('lead_edit_all', 'lead_manage'))
        or (p_permission_key = 'lead_view_own'
            and permission.key = 'lead_edit_own')
      )
  ) into v_granted;
  return v_default or v_granted;
end;
$$;


ALTER FUNCTION private.whatsapp_actor_has_lead_permission(p_organization_id uuid, p_actor_user_id uuid, p_permission_key text) OWNER TO postgres;

--
-- Name: whatsapp_attendance_message_evidence_matches(text, text, jsonb, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_attendance_message_evidence_matches(p_capture_state text, p_content text, p_metadata jsonb, p_expected_fingerprint text, p_expected_content text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case
    when p_capture_state = 'suppressed' then
      p_expected_fingerprint ~ '^[0-9a-f]{64}$'
      and btrim(coalesce(
        p_metadata->'whatsapp_attendance_capture'->>'message_fingerprint',
        ''
      )) = p_expected_fingerprint
    else coalesce(p_content, '') is not distinct from coalesce(p_expected_content, '')
  end;
$_$;


ALTER FUNCTION private.whatsapp_attendance_message_evidence_matches(p_capture_state text, p_content text, p_metadata jsonb, p_expected_fingerprint text, p_expected_content text) OWNER TO postgres;

--
-- Name: whatsapp_contact_pn_reference(text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_contact_pn_reference(p_values text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(split_part(split_part(lower(btrim(value)), '@', 1), ':', 1), '[^0-9]', '', 'g')
  from unnest(coalesce(p_values, '{}'::text[])) with ordinality as supplied(value,ordinal)
  where split_part(lower(btrim(value)), '@', 2) in ('s.whatsapp.net','c.us')
    and length(regexp_replace(split_part(split_part(value, '@', 1), ':', 1), '[^0-9]', '', 'g')) between 8 and 15
  order by ordinal limit 1;
$$;


ALTER FUNCTION private.whatsapp_contact_pn_reference(p_values text[]) OWNER TO postgres;

--
-- Name: whatsapp_contact_pns_conflict(text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_contact_pns_conflict(p_values text[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_raw text;
  v_phone text;
  v_key text;
  v_reference_phone text;
begin
  -- A provider's explicit PN disambiguates its identical bare-digit hint,
  -- including NANP numbers whose length also resembles a Brazilian local PN.
  foreach v_raw in array coalesce(p_values, '{}'::text[]) loop
    v_raw := lower(btrim(coalesce(v_raw, '')));
    if strpos(v_raw, '@') > 0 and split_part(v_raw, '@', 2) in ('s.whatsapp.net', 'c.us') then
      v_reference_phone := regexp_replace(split_part(split_part(v_raw, '@', 1), ':', 1), '[^0-9]', '', 'g');
      if length(v_reference_phone) between 8 and 15 then exit; end if;
      v_reference_phone := null;
    end if;
  end loop;
  foreach v_raw in array coalesce(p_values, '{}'::text[]) loop
    v_raw := lower(btrim(coalesce(v_raw, '')));
    if strpos(v_raw, '@') > 0 then
      if split_part(v_raw, '@', 2) not in ('s.whatsapp.net', 'c.us') then
        continue;
      end if;
      v_phone := regexp_replace(split_part(split_part(v_raw, '@', 1), ':', 1), '[^0-9]', '', 'g');
    else
      v_phone := case when v_raw not like '+%' and v_raw not like '00%'
        and regexp_replace(v_raw, '[^0-9]', '', 'g') = v_reference_phone then v_reference_phone
        else public.normalize_phone(v_raw) end;
    end if;
    if coalesce(length(v_phone), 0) not between 8 and 15 then
      continue;
    end if;
    if left(v_phone, 2) = '55' and length(v_phone) = 13 and substring(v_phone, 5, 1) = '9' then
      v_phone := left(v_phone, 4) || substring(v_phone, 6);
    end if;
    if v_key is not null and v_key <> v_phone then
      return true;
    end if;
    v_key := v_phone;
  end loop;
  return false;
end;
$$;


ALTER FUNCTION private.whatsapp_contact_pns_conflict(p_values text[]) OWNER TO postgres;

--
-- Name: whatsapp_conversation_contact_pn_evidence(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_conversation_contact_pn_evidence(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select coalesce(pg_catalog.array_agg(distinct evidence.value)
    filter(where nullif(pg_catalog.btrim(evidence.value),'') is not null),'{}'::text[])
  from public.whatsapp_conversations conversation
  cross join lateral (
    select conversation.remote_jid value
    union all select conversation.contact_phone
    union all
    select item.value
    from public.whatsapp_contact_identity_aliases alias
    cross join lateral (
      select alias.alias_jid value where lower(alias.alias_jid) ~ '@(s[.]whatsapp[.]net|c[.]us)$'
      union all select alias.canonical_jid where lower(alias.canonical_jid) ~ '@(s[.]whatsapp[.]net|c[.]us)$'
      union all select alias.contact_phone
    ) item
    where alias.organization_id=conversation.organization_id
      and alias.session_id=conversation.session_id
      and (alias.alias_jid=conversation.remote_jid or alias.canonical_jid=conversation.remote_jid)
  ) evidence
  where conversation.id=p_conversation_id
    and conversation.organization_id=p_organization_id
    and conversation.session_id=p_session_id;
$_$;


ALTER FUNCTION private.whatsapp_conversation_contact_pn_evidence(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_conversation_has_protected_history(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_conversation_has_protected_history(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.whatsapp_conversation_lead_bindings as binding
    where binding.conversation_id = p_conversation_id
  ) or exists (
    select 1 from private.whatsapp_unlinked_history_links as link
    where link.conversation_id = p_conversation_id
  ) or exists (
    select 1 from public.whatsapp_attendance_entries as attendance
    where attendance.conversation_id = p_conversation_id
  ) or exists (
    select 1 from public.whatsapp_messages as message
    where message.conversation_id = p_conversation_id
      and (
        message.lead_id is not null
        or (
          (message.from_me or message.direction <> 'inbound')
          and message.capture_state is distinct from 'unlinked_ephemeral'
        )
      )
  ) or exists (
    select 1 from public.whatsapp_inbound_logs as inbound_log
    where inbound_log.conversation_id = p_conversation_id
      and inbound_log.lead_id is not null
  ) or exists (
    select 1 from public.whatsapp_conversation_routing_heads as routing_head
    where routing_head.conversation_id = p_conversation_id
  ) or exists (
    select 1 from public.whatsapp_outbox as outbox
    where outbox.conversation_id = p_conversation_id
  ) or exists (
    select 1 from public.outbox_messages as outbox
    where outbox.conversation_id = p_conversation_id
  ) or exists (
    select 1
    from public.lead_attachments as attachment
    join public.whatsapp_messages as message on message.id = attachment.message_id
    where message.conversation_id = p_conversation_id
  );
$$;


ALTER FUNCTION private.whatsapp_conversation_has_protected_history(p_conversation_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_inbound_push_is_unstarted(private.notification_deliveries); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_inbound_push_is_unstarted(p_delivery private.notification_deliveries) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_delivery.channel='push' and p_delivery.attempt_count=0
    and p_delivery.status in ('queued','leased','retry_wait','blocked_dependency')
    and exists (
      select 1 from public.notifications notification
      join public.whatsapp_messages message on message.organization_id=notification.organization_id
        and message.id=private.safe_uuid(notification.metadata->>'whatsapp_message_id')
      where notification.id=p_delivery.notification_id
        and notification.organization_id=p_delivery.organization_id
        and notification.metadata->>'event_key'='whatsapp_inbound_attendant'
        and coalesce(notification.metadata->>'whatsapp_inbound_provider_started','false') <> 'true'
        and message.capture_state='captured' and message.from_me is false
        and message.direction='inbound' and message.lead_id is not null
        and message.message_type not in ('reaction','system','deleted')
        and not exists (
          select 1 from public.notifications sibling
          where sibling.organization_id=notification.organization_id
            and sibling.metadata->>'event_key'='whatsapp_inbound_attendant'
            and sibling.metadata->>'whatsapp_message_id'=message.id::text
            and (sibling.metadata->>'whatsapp_inbound_provider_started'='true'
              or exists (select 1 from private.notification_deliveries attempted
                where attempted.notification_id=sibling.id and attempted.channel='push'
                  and (attempted.attempt_count>0 or attempted.status in ('sending','accepted','delivered'))))
        )
    )
$$;


ALTER FUNCTION private.whatsapp_inbound_push_is_unstarted(p_delivery private.notification_deliveries) OWNER TO postgres;

--
-- Name: whatsapp_inbound_push_needs_reassignment(private.notification_deliveries); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_inbound_push_needs_reassignment(p_delivery private.notification_deliveries) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.whatsapp_inbound_push_is_unstarted(p_delivery) and not exists (
    select 1 from public.notifications notification
    join public.whatsapp_messages message on message.organization_id=notification.organization_id
      and message.id=private.safe_uuid(notification.metadata->>'whatsapp_message_id')
    cross join lateral private.whatsapp_inbound_push_recipient(message.organization_id,message.id) recipient
    where notification.id=p_delivery.notification_id
      and notification.organization_id=p_delivery.organization_id
      and recipient.user_id=notification.user_id
      and recipient.attendance_entry_id::text=notification.metadata->>'attendance_entry_id'
      and recipient.binding_id::text=notification.metadata->>'binding_id'
      and coalesce(recipient.grant_id::text,'')=coalesce(notification.metadata->>'grant_id','')
  )
$$;


ALTER FUNCTION private.whatsapp_inbound_push_needs_reassignment(p_delivery private.notification_deliveries) OWNER TO postgres;

--
-- Name: whatsapp_inbound_push_recipient(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_inbound_push_recipient(p_organization_id uuid, p_message_id uuid) RETURNS TABLE(user_id uuid, attendance_entry_id uuid, binding_id uuid, grant_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select lead.assigned_user_id, entry.id, binding.id, access.id
  from public.whatsapp_messages message
  join public.whatsapp_sessions session
    on session.id = message.session_id and session.organization_id = message.organization_id
   and coalesce(session.is_active, true) and session.status not in ('disabled', 'deleted')
  join public.whatsapp_conversations conversation
    on conversation.id = message.conversation_id and conversation.organization_id = message.organization_id
   and conversation.session_id = session.id and conversation.lead_id = message.lead_id
   and conversation.deleted_at is null and conversation.retired_at is null
   and not coalesce(conversation.is_group, false)
  join public.leads lead on lead.id = message.lead_id and lead.organization_id = message.organization_id
  join public.users actor on actor.id = lead.assigned_user_id
   and actor.organization_id = message.organization_id and coalesce(actor.is_active, false)
  join public.organization_members member on member.user_id = actor.id
   and member.organization_id = message.organization_id and coalesce(member.is_active, false)
   and member.deleted_at is null
  join public.users owner_user on owner_user.id = session.owner_user_id
   and coalesce(owner_user.is_active, false)
  join public.organization_members owner_member on owner_member.user_id = owner_user.id
   and owner_member.organization_id = message.organization_id and coalesce(owner_member.is_active, false)
   and owner_member.deleted_at is null
  join public.whatsapp_conversation_lead_bindings binding
    on binding.organization_id = message.organization_id and binding.conversation_id = conversation.id
   and binding.session_id = session.id and binding.lead_id = lead.id
   and binding.active_to is null and not binding.stale
  join public.whatsapp_attendance_entries entry
    on entry.organization_id = message.organization_id and entry.conversation_id = conversation.id
   and entry.session_id = session.id and entry.lead_id = lead.id
   and entry.binding_id = binding.id and entry.user_id = lead.assigned_user_id
  left join public.whatsapp_session_access access
    on access.organization_id = message.organization_id and access.session_id = session.id
   and access.user_id = actor.id and access.granted_by = session.owner_user_id
   and access.access_mode = 'assigned_leads_only' and access.only_leads_access
   and access.can_view and access.can_read and access.can_send
   and access.grant_scope = 'organization' and access.grant_team_id is null
   and lower(btrim(owner_member.role)) in ('owner', 'admin')
  where message.organization_id = p_organization_id and message.id = p_message_id
    and message.capture_state = 'captured' and message.from_me is false
    and message.direction = 'inbound' and message.lead_id is not null
    and message.message_type not in ('reaction', 'system', 'deleted')
    and (actor.id = session.owner_user_id or access.id is not null)
    and private.whatsapp_actor_can_read_lead(message.organization_id, lead.id, actor.id)
  limit 1
$$;


ALTER FUNCTION private.whatsapp_inbound_push_recipient(p_organization_id uuid, p_message_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_ingress_routing_event_is_current(uuid, uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_ingress_routing_event_is_current(p_organization_id uuid, p_conversation_id uuid, p_provider_message_id text, p_lead_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when conversation.id is null then false
    when routing_snapshot.provider_message_id is null then true
    else exists (
      select 1
      from public.whatsapp_conversation_routing_heads as routing_head
      where routing_head.organization_id = p_organization_id
        and routing_head.conversation_id = p_conversation_id
        and routing_head.session_id = routing_snapshot.session_id
        and routing_head.routing_key = routing_snapshot.routing_key
        and routing_head.ingress_sequence >= routing_snapshot.ingress_sequence
        and routing_head.lead_id = p_lead_id
    )
  end
  from (values (1)) as singleton(value)
  left join public.whatsapp_conversations as conversation
    on conversation.organization_id = p_organization_id
   and conversation.id = p_conversation_id
  left join public.whatsapp_webhook_routing_snapshots as routing_snapshot
    on routing_snapshot.organization_id = p_organization_id
   and routing_snapshot.session_id = conversation.session_id
   and routing_snapshot.provider_message_id = nullif(pg_catalog.btrim(p_provider_message_id), '')
  limit 1
$$;


ALTER FUNCTION private.whatsapp_ingress_routing_event_is_current(p_organization_id uuid, p_conversation_id uuid, p_provider_message_id text, p_lead_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_webhook_routing_snapshots; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.whatsapp_webhook_routing_snapshots (
    organization_id uuid NOT NULL,
    session_id uuid NOT NULL,
    provider_message_id text NOT NULL,
    inbox_event_key text NOT NULL,
    processing_lane text NOT NULL,
    routing_key text NOT NULL,
    ingress_sequence bigint NOT NULL,
    predecessor_provider_message_id text,
    binding_eligible boolean NOT NULL,
    target_mode text NOT NULL,
    snapshot jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    processing_epoch integer DEFAULT 0 NOT NULL,
    CONSTRAINT whatsapp_webhook_routing_snapshot_event_key_check CHECK (((btrim(inbox_event_key) <> ''::text) AND (octet_length(inbox_event_key) <= 1024))),
    CONSTRAINT whatsapp_webhook_routing_snapshot_key_check CHECK (((btrim(routing_key) <> ''::text) AND (octet_length(routing_key) <= 256))),
    CONSTRAINT whatsapp_webhook_routing_snapshot_lane_check CHECK ((processing_lane = ANY (ARRAY['live'::text, 'backlog'::text]))),
    CONSTRAINT whatsapp_webhook_routing_snapshot_predecessor_check CHECK (((predecessor_provider_message_id IS NULL) OR (predecessor_provider_message_id <> provider_message_id))),
    CONSTRAINT whatsapp_webhook_routing_snapshot_provider_check CHECK (((btrim(provider_message_id) <> ''::text) AND (octet_length(provider_message_id) <= 512))),
    CONSTRAINT whatsapp_webhook_routing_snapshot_target_mode_check CHECK ((target_mode = ANY (ARRAY['snapshot'::text, 'inherit_predecessor'::text])))
);


ALTER TABLE public.whatsapp_webhook_routing_snapshots OWNER TO postgres;

--
-- Name: TABLE whatsapp_webhook_routing_snapshots; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.whatsapp_webhook_routing_snapshots IS 'Immutable pre-ACK provider routing provenance. binding_eligible rows form an exact predecessor chain per tenant/session/routing key and identify their durable inbox event.';


--
-- Name: COLUMN whatsapp_webhook_routing_snapshots.processing_epoch; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_webhook_routing_snapshots.processing_epoch IS 'Frozen routing generation; a predecessor must belong to this same generation.';


--
-- Name: whatsapp_inherited_predecessor_provenance_matches(public.whatsapp_webhook_routing_snapshots, public.whatsapp_webhook_routing_snapshots); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_inherited_predecessor_provenance_matches(p_route public.whatsapp_webhook_routing_snapshots, p_predecessor public.whatsapp_webhook_routing_snapshots) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(
    p_route.processing_epoch = p_predecessor.processing_epoch
    and coalesce(p_route.snapshot->>'processing_epoch', '0') = p_route.processing_epoch::text
    and coalesce(p_predecessor.snapshot->>'processing_epoch', '0') = p_predecessor.processing_epoch::text
    and p_route.snapshot->>'predecessor_provider_message_id' = p_predecessor.provider_message_id
    and p_route.snapshot->>'predecessor_inbox_event_key' = p_predecessor.inbox_event_key
    and p_route.snapshot->>'predecessor_processing_lane' = p_predecessor.processing_lane,
    false
  );
$$;


ALTER FUNCTION private.whatsapp_inherited_predecessor_provenance_matches(p_route public.whatsapp_webhook_routing_snapshots, p_predecessor public.whatsapp_webhook_routing_snapshots) OWNER TO postgres;

--
-- Name: whatsapp_managed_initial_proof_matches(uuid, uuid, uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_managed_initial_proof_matches(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_provider_event_id text, p_message_fingerprint text DEFAULT NULL::text, p_rule_id uuid DEFAULT NULL::uuid, p_target_round_robin_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from private.whatsapp_managed_message_proofs as proof
    where proof.organization_id = p_organization_id
      and proof.lead_id = p_lead_id
      and proof.session_id = p_session_id
      and proof.provider_event_id = btrim(coalesce(p_provider_event_id, ''))
      and (
        p_message_fingerprint is null
        or proof.message_fingerprint = p_message_fingerprint
      )
      and (p_rule_id is null or proof.rule_id = p_rule_id)
      and (
        p_target_round_robin_id is null
        or proof.target_round_robin_id = p_target_round_robin_id
      )
  );
$$;


ALTER FUNCTION private.whatsapp_managed_initial_proof_matches(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_provider_event_id text, p_message_fingerprint text, p_rule_id uuid, p_target_round_robin_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_message_conversation_session_matches(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_message_conversation_session_matches(p_conversation_id uuid, p_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.whatsapp_conversations wc
    join public.whatsapp_sessions ws
      on ws.id = wc.session_id
     and ws.organization_id = wc.organization_id
    where wc.id = p_conversation_id
      and wc.session_id = p_session_id
      and coalesce(ws.is_active, true) = true
      and coalesce(ws.status, '') <> 'deleted'
      and ws.provider = 'evolution_go'
  );
$$;


ALTER FUNCTION private.whatsapp_message_conversation_session_matches(p_conversation_id uuid, p_session_id uuid) OWNER TO postgres;

