--
-- Name: whatsapp_metadata_ctwa_confirmation_method(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_metadata_ctwa_confirmation_method(p_metadata jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_attribution jsonb;
  v_referral jsonb;
  v_entry_point_top text;
  v_entry_point_referral text;
  v_explicit_source_type_top text;
  v_explicit_source_type_referral text;
  v_ctwa_clid_top_json jsonb;
  v_ctwa_clid_referral_json jsonb;
  v_ctwa_clid_top text;
  v_ctwa_clid_referral text;
  v_ctwa_clid text;
  v_show_ad_attribution_top jsonb;
  v_show_ad_attribution_referral jsonb;
  v_proof_conflict_top jsonb;
  v_proof_conflict_referral jsonb;
  v_show_invalid_top jsonb;
  v_show_invalid_referral jsonb;
begin
  v_attribution := case
    when jsonb_typeof(v_metadata->'whatsapp_attribution') = 'object'
      then v_metadata->'whatsapp_attribution'
    else '{}'::jsonb
  end;
  v_referral := case
    when jsonb_typeof(v_attribution->'source_referral') = 'object'
      then v_attribution->'source_referral'
    else '{}'::jsonb
  end;

  v_entry_point_top := nullif(btrim(v_attribution->>'entry_point_conversion_source'), '');
  v_entry_point_referral := nullif(btrim(v_referral->>'entry_point_conversion_source'), '');
  v_explicit_source_type_top := nullif(lower(btrim(v_attribution->>'explicit_source_type')), '');
  v_explicit_source_type_referral := nullif(lower(btrim(v_referral->>'explicit_source_type')), '');
  v_ctwa_clid_top_json := v_attribution->'ctwa_clid';
  v_ctwa_clid_referral_json := v_referral->'ctwa_clid';
  v_show_ad_attribution_top := v_attribution->'show_ad_attribution';
  v_show_ad_attribution_referral := v_referral->'show_ad_attribution';
  v_proof_conflict_top := v_attribution->'ctwa_proof_conflict';
  v_proof_conflict_referral := v_referral->'ctwa_proof_conflict';
  v_show_invalid_top := v_attribution->'ctwa_show_ad_attribution_invalid';
  v_show_invalid_referral := v_referral->'ctwa_show_ad_attribution_invalid';

  -- Runtime parsers preserve contradictions found between the current
  -- message and its immediate envelope. Any non-false marker fails closed.
  if (v_proof_conflict_top is not null
      and v_proof_conflict_top <> 'null'::jsonb
      and v_proof_conflict_top <> 'false'::jsonb)
     or (v_proof_conflict_referral is not null
      and v_proof_conflict_referral <> 'null'::jsonb
      and v_proof_conflict_referral <> 'false'::jsonb) then
    return null;
  end if;

  if (v_show_invalid_top is not null
      and v_show_invalid_top <> 'null'::jsonb
      and v_show_invalid_top <> 'false'::jsonb)
     or (v_show_invalid_referral is not null
      and v_show_invalid_referral <> 'null'::jsonb
      and v_show_invalid_referral <> 'false'::jsonb) then
    return null;
  end if;

  if (v_show_ad_attribution_top is not null
      and v_show_ad_attribution_top <> 'null'::jsonb
      and jsonb_typeof(v_show_ad_attribution_top) <> 'boolean')
     or (v_show_ad_attribution_referral is not null
      and v_show_ad_attribution_referral <> 'null'::jsonb
      and jsonb_typeof(v_show_ad_attribution_referral) <> 'boolean') then
    return null;
  end if;

  if (v_ctwa_clid_top_json is not null
      and v_ctwa_clid_top_json <> 'null'::jsonb
      and jsonb_typeof(v_ctwa_clid_top_json) <> 'string')
     or (v_ctwa_clid_referral_json is not null
      and v_ctwa_clid_referral_json <> 'null'::jsonb
      and jsonb_typeof(v_ctwa_clid_referral_json) <> 'string') then
    return null;
  end if;

  -- Also reject directly observable top/referral disagreements so legacy or
  -- independently supplied metadata cannot bypass the runtime marker.
  if (v_entry_point_top is not null
      and v_entry_point_referral is not null
      and lower(v_entry_point_top) <> lower(v_entry_point_referral))
     or (v_explicit_source_type_top is not null
      and v_explicit_source_type_referral is not null
      and v_explicit_source_type_top <> v_explicit_source_type_referral)
     or (v_ctwa_clid_top_json is not null
      and v_ctwa_clid_top_json <> 'null'::jsonb
      and v_ctwa_clid_referral_json is not null
      and v_ctwa_clid_referral_json <> 'null'::jsonb
      and v_ctwa_clid_top_json <> v_ctwa_clid_referral_json)
     or (v_show_ad_attribution_top is not null
      and v_show_ad_attribution_top <> 'null'::jsonb
      and v_show_ad_attribution_referral is not null
      and v_show_ad_attribution_referral <> 'null'::jsonb
      and v_show_ad_attribution_top <> v_show_ad_attribution_referral) then
    return null;
  end if;

  -- A supplied entry point is authoritative. Conflicting or non-CTWA values
  -- must never fall through to the Evolution fallback.
  if v_entry_point_top is not null or v_entry_point_referral is not null then
    if (v_entry_point_top is null or lower(v_entry_point_top) = 'ctwa_ad')
       and (v_entry_point_referral is null or lower(v_entry_point_referral) = 'ctwa_ad')
       and (v_explicit_source_type_top is null or v_explicit_source_type_top = 'ad')
       and (v_explicit_source_type_referral is null or v_explicit_source_type_referral = 'ad') then
      return 'entry_point_ctwa_ad';
    end if;
    return null;
  end if;

  -- Only an explicitly received provider field may corroborate the opaque
  -- click id. source_referral.source_type is intentionally not consulted: it
  -- can be inferred by application normalizers from the click id itself.
  if coalesce(v_explicit_source_type_top, v_explicit_source_type_referral, '') <> 'ad'
     or (v_explicit_source_type_top is not null and v_explicit_source_type_top <> 'ad')
     or (v_explicit_source_type_referral is not null and v_explicit_source_type_referral <> 'ad') then
    return null;
  end if;

  v_ctwa_clid_top := nullif(btrim(v_attribution->>'ctwa_clid'), '');
  v_ctwa_clid_referral := nullif(btrim(v_referral->>'ctwa_clid'), '');
  if v_ctwa_clid_top is not null
     and v_ctwa_clid_referral is not null
     and v_ctwa_clid_top <> v_ctwa_clid_referral then
    return null;
  end if;
  v_ctwa_clid := coalesce(v_ctwa_clid_top, v_ctwa_clid_referral);
  if v_ctwa_clid is null
     or octet_length(v_ctwa_clid) not between 8 and 512
     or v_ctwa_clid ~ '[[:cntrl:]]' then
    return null;
  end if;

  -- Missing show_ad_attribution is a known Evolution shape. When supplied it
  -- must be the JSON boolean true; false or a stringly/truthy value blocks v2.
  if (v_show_ad_attribution_top is not null
      and v_show_ad_attribution_top <> 'null'::jsonb
      and v_show_ad_attribution_top <> 'true'::jsonb)
     or (v_show_ad_attribution_referral is not null
      and v_show_ad_attribution_referral <> 'null'::jsonb
      and v_show_ad_attribution_referral <> 'true'::jsonb) then
    return null;
  end if;

  return 'evolution_ctwa_clid_v1';
end;
$$;


ALTER FUNCTION private.whatsapp_metadata_ctwa_confirmation_method(p_metadata jsonb) OWNER TO postgres;

--
-- Name: FUNCTION whatsapp_metadata_ctwa_confirmation_method(p_metadata jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.whatsapp_metadata_ctwa_confirmation_method(p_metadata jsonb) IS 'Returns the provider-proof method for a strict Meta CTWA entry point or the closed Evolution explicit-ad plus opaque-ctwa-clid fallback.';


--
-- Name: whatsapp_metadata_is_ctwa_ad(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_metadata_is_ctwa_ad(p_metadata jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select private.whatsapp_metadata_ctwa_confirmation_method(
    coalesce(p_metadata, '{}'::jsonb)
  ) is not null;
$$;


ALTER FUNCTION private.whatsapp_metadata_is_ctwa_ad(p_metadata jsonb) OWNER TO postgres;

--
-- Name: whatsapp_owner_can_view_session(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_owner_can_view_session(p_organization_id uuid, p_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1 from public.whatsapp_sessions as session
      where session.id = p_session_id
        and session.organization_id = p_organization_id
        and session.owner_user_id = (select auth.uid())
        and session.provider = 'evolution_go'
        and coalesce(session.is_active, true)
        and coalesce(session.status, '') <> 'deleted'
        and private.is_org_member(session.organization_id)
    );
$$;


ALTER FUNCTION private.whatsapp_owner_can_view_session(p_organization_id uuid, p_session_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_unlinked_capture_resolution(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_unlinked_capture_resolution(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_provider_message_id text, p_inbox_event_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_snapshot public.whatsapp_webhook_routing_snapshots%rowtype;
  v_inbox public.whatsapp_webhook_inbox%rowtype;
  v_link private.whatsapp_unlinked_history_links%rowtype;
  v_expiry timestamptz;
begin
  if p_organization_id is null or p_session_id is null
     or p_conversation_id is null
     or nullif(pg_catalog.btrim(p_provider_message_id), '') is null
     or nullif(pg_catalog.btrim(p_inbox_event_key), '') is null then
    return pg_catalog.jsonb_build_object(
      'capture_state', 'suppressed', 'lead_id', null, 'reason', 'missing_proof'
    );
  end if;

  -- A transport tombstone has already discarded its content. Neither replay
  -- nor a later human link may turn it into a visible message.
  if exists (
    select 1 from public.whatsapp_messages as message
    where message.organization_id = p_organization_id
      and message.session_id = p_session_id
      and message.provider_message_id = p_provider_message_id
      and message.capture_state = 'suppressed'
  ) then
    return pg_catalog.jsonb_build_object(
      'capture_state', 'suppressed', 'lead_id', null, 'reason', 'already_suppressed'
    );
  end if;
  if exists (
    select 1 from public.whatsapp_outbox as outbox
    where outbox.organization_id = p_organization_id
      and outbox.session_id = p_session_id
      and outbox.provider_message_id = p_provider_message_id
  ) or exists (
    select 1 from public.outbox_messages as outbox
    where outbox.organization_id = p_organization_id
      and outbox.session_id = p_session_id
      and outbox.sent_message_id = p_provider_message_id
  ) then
    return pg_catalog.jsonb_build_object(
      'capture_state', 'suppressed', 'lead_id', null, 'reason', 'managed_outbound'
    );
  end if;

  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id
    and conversation.session_id = p_session_id;
  select snapshot.* into v_snapshot
  from public.whatsapp_webhook_routing_snapshots as snapshot
  where snapshot.organization_id = p_organization_id
    and snapshot.session_id = p_session_id
    and snapshot.provider_message_id = p_provider_message_id
    and snapshot.inbox_event_key = p_inbox_event_key;
  select inbox.* into v_inbox
  from public.whatsapp_webhook_inbox as inbox
  where inbox.organization_id = p_organization_id
    and inbox.session_id = p_session_id
    and inbox.event_key = p_inbox_event_key;

  if v_conversation.id is null or v_snapshot.provider_message_id is null
     or v_inbox.id is null or v_conversation.deleted_at is not null
     or coalesce(v_conversation.is_group, false)
     or v_conversation.unlinked_retention_scrubbed_at is not null
     or v_snapshot.snapshot->>'unlinked_capture_policy' is distinct from 'v1'
     or v_snapshot.snapshot->>'state' is distinct from 'unlinked'
     or v_snapshot.snapshot->>'context_kind' is distinct from 'organic'
     or nullif(v_snapshot.snapshot->>'quarantine_reason', '') is not null
     or nullif(v_snapshot.snapshot->>'event_lead_id', '') is not null
     or nullif(v_snapshot.snapshot->>'current_lead_id', '') is not null
     or not (
       v_snapshot.snapshot->>'conversation_id' = p_conversation_id::text
       or (
         v_snapshot.snapshot->>'conversation_id' is null
         and v_conversation.created_at >= v_inbox.created_at
         and v_conversation.created_at < v_inbox.created_at + interval '7 days'
         and v_snapshot.routing_key in (
           'phone:' || coalesce(public.normalize_phone(v_conversation.contact_phone), ''),
           'jid:' || pg_catalog.lower(v_conversation.remote_jid)
         )
         and not exists (
           select 1 from public.whatsapp_conversations as other_epoch
           where other_epoch.organization_id = p_organization_id
             and other_epoch.session_id = p_session_id
             and other_epoch.remote_jid = v_conversation.remote_jid
             and other_epoch.id <> p_conversation_id
             and other_epoch.created_at >= v_inbox.created_at
             and other_epoch.created_at < v_conversation.created_at
         )
       )
     )
     or v_snapshot.created_at > v_inbox.created_at + interval '5 minutes' then
    return pg_catalog.jsonb_build_object(
      'capture_state', 'suppressed', 'lead_id', null, 'reason', 'epoch_unproven'
    );
  end if;

  v_expiry := v_conversation.created_at + interval '7 days';
  if v_inbox.created_at >= v_expiry or v_snapshot.created_at >= v_expiry
     or (v_conversation.retired_at is not null
         and (v_inbox.created_at > v_conversation.retired_at
              or v_snapshot.created_at > v_conversation.retired_at)) then
    return pg_catalog.jsonb_build_object(
      'capture_state', 'suppressed', 'lead_id', null, 'reason', 'outside_epoch'
    );
  end if;

  select link.* into v_link
  from private.whatsapp_unlinked_history_links as link
  where link.conversation_id = p_conversation_id
    and link.organization_id = p_organization_id
    and link.session_id = p_session_id;
  if v_link.conversation_id is not null then
    if v_link.confirmed_at >= v_expiry
       or v_inbox.created_at > v_link.confirmed_at
       or v_snapshot.created_at > v_link.confirmed_at
       or not exists (
         select 1 from public.leads as lead
         where lead.id = v_link.lead_id
           and lead.organization_id = p_organization_id
       ) then
      return pg_catalog.jsonb_build_object(
        'capture_state', 'suppressed', 'lead_id', null, 'reason', 'link_fence'
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'capture_state', 'promoted_unlinked', 'lead_id', v_link.lead_id,
      'reason', 'human_history_link'
    );
  end if;

  if v_conversation.lead_id is not null
     or pg_catalog.clock_timestamp() >= v_expiry
     or (
       not v_conversation.unlinked_retention_v1
       and not (
         v_snapshot.snapshot->>'conversation_id' is null
         and v_conversation.created_at >= v_inbox.created_at
         and not private.whatsapp_conversation_has_protected_history(
           v_conversation.id
         )
       )
     ) then
    return pg_catalog.jsonb_build_object(
      'capture_state', 'suppressed', 'lead_id', null, 'reason', 'unlinked_closed'
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'capture_state', 'unlinked_ephemeral', 'lead_id', null,
    'reason', 'original_unlinked_epoch'
  );
end;
$$;


ALTER FUNCTION private.whatsapp_unlinked_capture_resolution(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_provider_message_id text, p_inbox_event_key text) OWNER TO postgres;

--
-- Name: whatsapp_unlinked_has_unscrubbed_inbox(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_unlinked_has_unscrubbed_inbox(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.whatsapp_conversations as conversation
    join public.whatsapp_webhook_inbox as inbox
      on inbox.organization_id = conversation.organization_id
     and inbox.session_id = conversation.session_id
    join public.whatsapp_webhook_routing_snapshots as snapshot
      on snapshot.organization_id = inbox.organization_id
     and snapshot.session_id = inbox.session_id
     and snapshot.inbox_event_key = inbox.event_key
    where conversation.id = p_conversation_id
      and conversation.unlinked_retention_v1
      and conversation.lead_id is null
      and inbox.payload <> '{"__vimob_retention":"expired_unlinked_v1"}'::jsonb
      and snapshot.snapshot->>'unlinked_capture_policy' = 'v1'
      and snapshot.snapshot->>'state' = 'unlinked'
      and snapshot.snapshot->>'context_kind' = 'organic'
      and nullif(snapshot.snapshot->>'event_lead_id', '') is null
      and nullif(snapshot.snapshot->>'current_lead_id', '') is null
      and nullif(snapshot.snapshot->>'quarantine_reason', '') is null
      and inbox.created_at < conversation.created_at + interval '7 days'
      and (conversation.retired_at is null
           or inbox.created_at <= conversation.retired_at)
      and (
        snapshot.snapshot->>'conversation_id' = conversation.id::text
        or (
          snapshot.snapshot->>'conversation_id' is null
          and (
            exists (
              select 1 from public.whatsapp_messages as message
              where message.organization_id = inbox.organization_id
                and message.session_id = inbox.session_id
                and message.conversation_id = conversation.id
                and message.provider_message_id = snapshot.provider_message_id
                and (message.capture_state = 'unlinked_ephemeral'
                     or message.unlinked_retention_scrubbed_at is not null)
            )
            or (
              snapshot.routing_key in (
                'phone:' || coalesce(public.normalize_phone(conversation.contact_phone), ''),
                'jid:' || pg_catalog.lower(conversation.remote_jid)
              )
              and not exists (
                select 1 from public.whatsapp_conversations as other_epoch
                where other_epoch.organization_id = conversation.organization_id
                  and other_epoch.session_id = conversation.session_id
                  and other_epoch.remote_jid = conversation.remote_jid
                  and other_epoch.id <> conversation.id
                  and other_epoch.created_at >= inbox.created_at
                  and other_epoch.created_at < conversation.created_at
              )
            )
          )
        )
      )
      and (
        inbox.payload #>> '{__vimob_retention,kind}'
          is distinct from 'partial_expired_unlinked_v1'
        or exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            case when pg_catalog.jsonb_typeof(
              inbox.payload #> '{data,messages}'
            ) = 'array' then inbox.payload #> '{data,messages}'
            else '[]'::jsonb end
          ) as raw_member(value)
          where snapshot.provider_message_id in (
            raw_member.value #>> '{key,id}',
            raw_member.value #>> '{Info,ID}'
          )
        )
      )
  );
$$;


ALTER FUNCTION private.whatsapp_unlinked_has_unscrubbed_inbox(p_conversation_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_unlinked_inbox_batch_exclusive(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_unlinked_inbox_batch_exclusive(p_inbox_id uuid, p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.whatsapp_webhook_inbox as inbox
    join public.whatsapp_conversations as conversation
      on conversation.id = p_conversation_id
     and conversation.organization_id = inbox.organization_id
     and conversation.session_id = inbox.session_id
    cross join lateral (
      select case when pg_catalog.jsonb_typeof(
        inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
      ) = 'array' then
        inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
      else '[]'::jsonb end as members
    ) as envelope
    where inbox.id = p_inbox_id
      and pg_catalog.jsonb_typeof(
        envelope.members
      ) = 'array'
      and pg_catalog.jsonb_array_length(
        envelope.members
      ) > 0
      and (
        select count(*)
        from public.whatsapp_webhook_routing_snapshots as snapshot
        where snapshot.organization_id = inbox.organization_id
          and snapshot.session_id = inbox.session_id
          and snapshot.inbox_event_key = inbox.event_key
      ) = pg_catalog.jsonb_array_length(
        envelope.members
      )
      and (
        select count(distinct member.value->>'provider_message_id')
        from pg_catalog.jsonb_array_elements(
          envelope.members
        ) as member(value)
      ) = pg_catalog.jsonb_array_length(
        envelope.members
      )
      and not exists (
        select 1
        from pg_catalog.jsonb_array_elements(
          envelope.members
        ) as member(value)
        where not exists (
          select 1
          from public.whatsapp_webhook_routing_snapshots as snapshot
          where snapshot.organization_id = inbox.organization_id
            and snapshot.session_id = inbox.session_id
            and snapshot.inbox_event_key = inbox.event_key
            and snapshot.provider_message_id = member.value->>'provider_message_id'
        )
      )
      and (
        select count(*)
        from (
          values
            (inbox.payload->'messages'), (inbox.payload->'Messages'),
            (inbox.payload->'message'), (inbox.payload->'Message'),
            (inbox.payload->'data'), (inbox.payload->'Data'),
            (inbox.payload #> '{data,messages}'),
            (inbox.payload #> '{data,Messages}'),
            (inbox.payload #> '{data,message}'),
            (inbox.payload #> '{data,Message}'),
            (inbox.payload #> '{Data,messages}'),
            (inbox.payload #> '{Data,Messages}'),
            (inbox.payload #> '{Data,message}'),
            (inbox.payload #> '{Data,Message}')
        ) as location(value)
        where case when pg_catalog.jsonb_typeof(location.value) = 'array'
          then pg_catalog.jsonb_array_length(location.value) else 0 end > 0
      ) <= 1
      and coalesce((
        select pg_catalog.jsonb_array_length(location.value)
        from (
          values
            (inbox.payload->'messages'), (inbox.payload->'Messages'),
            (inbox.payload->'message'), (inbox.payload->'Message'),
            (inbox.payload->'data'), (inbox.payload->'Data'),
            (inbox.payload #> '{data,messages}'),
            (inbox.payload #> '{data,Messages}'),
            (inbox.payload #> '{data,message}'),
            (inbox.payload #> '{data,Message}'),
            (inbox.payload #> '{Data,messages}'),
            (inbox.payload #> '{Data,Messages}'),
            (inbox.payload #> '{Data,message}'),
            (inbox.payload #> '{Data,Message}')
        ) as location(value)
        where case when pg_catalog.jsonb_typeof(location.value) = 'array'
          then pg_catalog.jsonb_array_length(location.value) else 0 end > 0
        limit 1
      ), 1) = pg_catalog.jsonb_array_length(
        envelope.members
      )
      and not exists (
        select 1
        from public.whatsapp_webhook_routing_snapshots as snapshot
        where snapshot.organization_id = inbox.organization_id
          and snapshot.session_id = inbox.session_id
          and snapshot.inbox_event_key = inbox.event_key
          and (
            snapshot.snapshot->>'unlinked_capture_policy' = 'v1'
            and snapshot.snapshot->>'state' = 'unlinked'
            and snapshot.snapshot->>'context_kind' = 'organic'
            and nullif(snapshot.snapshot->>'event_lead_id', '') is null
            and nullif(snapshot.snapshot->>'current_lead_id', '') is null
            and nullif(snapshot.snapshot->>'quarantine_reason', '') is null
            and (
              snapshot.snapshot->>'conversation_id' = conversation.id::text
              or (
                snapshot.snapshot->>'conversation_id' is null
                and (
                  exists (
                    select 1 from public.whatsapp_messages as message
                    where message.organization_id = inbox.organization_id
                      and message.session_id = inbox.session_id
                      and message.conversation_id = conversation.id
                      and message.provider_message_id = snapshot.provider_message_id
                      and (message.capture_state = 'unlinked_ephemeral'
                           or message.unlinked_retention_scrubbed_at is not null)
                  )
                  or (
                    conversation.created_at >= inbox.created_at
                    and conversation.created_at < inbox.created_at + interval '7 days'
                    and snapshot.routing_key in (
                      'phone:' || coalesce(public.normalize_phone(conversation.contact_phone), ''),
                      'jid:' || pg_catalog.lower(conversation.remote_jid)
                    )
                  )
                )
                and not exists (
                  select 1 from public.whatsapp_conversations as other_epoch
                  where other_epoch.organization_id = conversation.organization_id
                    and other_epoch.session_id = conversation.session_id
                    and other_epoch.remote_jid = conversation.remote_jid
                    and other_epoch.id <> conversation.id
                    and other_epoch.created_at >= inbox.created_at
                    and other_epoch.created_at < conversation.created_at
                )
              )
            )
          ) is not true
      )
  );
$$;


ALTER FUNCTION private.whatsapp_unlinked_inbox_batch_exclusive(p_inbox_id uuid, p_conversation_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_unlinked_media_gc_can_delete(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_unlinked_media_gc_can_delete(p_id uuid, p_worker_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gc private.whatsapp_unlinked_media_gc%rowtype;
begin
  -- Caller must keep this transaction open through Storage DELETE and
  -- complete_whatsapp_unlinked_media_gc. A fresh path attachment takes a
  -- conflicting FOR SHARE lock on the same queue row.
  select gc.* into v_gc
  from private.whatsapp_unlinked_media_gc as gc
  where gc.id = p_id
  for update;

  if not found or v_gc.status <> 'processing'
     or v_gc.locked_by is distinct from p_worker_id
     or v_gc.locked_at < pg_catalog.clock_timestamp() - interval '5 minutes'
     or v_gc.bucket_id <> 'whatsapp-media'
     or v_gc.object_path not like 'orgs/' || v_gc.organization_id::text || '/%'
     or pg_catalog.strpos(v_gc.object_path, '..') > 0
     or pg_catalog.strpos(v_gc.object_path, E'\\') > 0 then
    return false;
  end if;
  if exists (
    select 1
    from public.whatsapp_messages as message
    join public.whatsapp_conversations as conversation
      on conversation.id = message.conversation_id
     and conversation.organization_id = message.organization_id
    where message.organization_id = v_gc.organization_id
      and message.media_storage_path = v_gc.object_path
      and (
        conversation.retired_at is null
        or private.whatsapp_conversation_has_protected_history(conversation.id)
        or exists (
          select 1 from private.whatsapp_unlinked_history_links as link
          where link.conversation_id = conversation.id
            and link.organization_id = conversation.organization_id
        )
      )
  ) or exists (
    select 1
    from public.media_jobs as job
    join public.whatsapp_conversations as conversation
      on conversation.id = job.conversation_id
     and conversation.organization_id = job.organization_id
    where job.organization_id = v_gc.organization_id
      and (
        job.storage_path = v_gc.object_path
        or job.message_key->>'upload_intent_path' = v_gc.object_path
        or job.message_key->>'repair_storage_path' = v_gc.object_path
      )
      and (
        conversation.retired_at is null
        or private.whatsapp_conversation_has_protected_history(conversation.id)
        or exists (
          select 1 from private.whatsapp_unlinked_history_links as link
          where link.conversation_id = conversation.id
            and link.organization_id = conversation.organization_id
        )
      )
  ) or exists (
    select 1 from public.leads as lead
    where lead.organization_id = v_gc.organization_id
      and lead.whatsapp_avatar_storage_path = v_gc.object_path
  ) then
    return false;
  end if;

  return true;
end;
$$;


ALTER FUNCTION private.whatsapp_unlinked_media_gc_can_delete(p_id uuid, p_worker_id text) OWNER TO postgres;

--
-- Name: whatsapp_unlinked_mixed_inbox_plan(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_unlinked_mixed_inbox_plan(p_inbox_id uuid, p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_inbox public.whatsapp_webhook_inbox%rowtype;
  v_conversation public.whatsapp_conversations%rowtype;
  v_payload jsonb;
  v_data jsonb;
  v_ingress jsonb;
  v_envelope jsonb;
  v_members jsonb;
  v_snapshots jsonb;
  v_marker jsonb;
  v_member jsonb;
  v_embedded jsonb;
  v_route public.whatsapp_webhook_routing_snapshots%rowtype;
  v_provider_id text;
  v_key_id text;
  v_info_id text;
  v_removed_ids text[] := '{}'::text[];
  v_seen_ids text[] := '{}'::text[];
  v_kept_members jsonb := '[]'::jsonb;
  v_kept_snapshots jsonb := '[]'::jsonb;
  v_previous_count integer := 0;
  v_route_count integer;
  v_member_count integer;
  v_removed_count integer;
  v_index integer;
  v_result jsonb;
begin
  select inbox.* into v_inbox
  from public.whatsapp_webhook_inbox as inbox
  where inbox.id = p_inbox_id;
  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id;
  if v_inbox.id is null or v_conversation.id is null
     or v_inbox.organization_id <> v_conversation.organization_id
     or v_inbox.session_id <> v_conversation.session_id
     or v_inbox.event_type <> 'messages.upsert'
     or v_inbox.status not in ('pending', 'retry', 'dead', 'processed')
     or not v_conversation.unlinked_retention_v1
     or v_conversation.lead_id is not null
     or coalesce(v_conversation.is_group, false)
     or v_conversation.unlinked_retention_scrubbed_at is not null
     or v_conversation.created_at > pg_catalog.clock_timestamp() - interval '7 days'
     or v_inbox.created_at >= v_conversation.created_at + interval '7 days'
     or (v_conversation.retired_at is not null
         and v_inbox.created_at > v_conversation.retired_at)
     or private.whatsapp_conversation_has_protected_history(v_conversation.id)
     or exists (
       select 1 from private.whatsapp_unlinked_history_links as link
       where link.conversation_id = v_conversation.id
     ) then
    return null;
  end if;

  -- The provider decoder has several legacy shapes. Only this one canonical
  -- list is transformed. Every other shape stays byte-for-byte intact.
  v_payload := v_inbox.payload;
  v_data := v_payload->'data';
  v_ingress := v_payload->'__vimob_ingress';
  v_envelope := v_ingress->'routing_snapshot';
  v_members := v_data->'messages';
  v_snapshots := v_envelope->'messages';
  if pg_catalog.jsonb_typeof(v_payload) <> 'object'
     or pg_catalog.jsonb_typeof(v_data) <> 'object'
     or pg_catalog.jsonb_typeof(v_ingress) <> 'object'
     or pg_catalog.jsonb_typeof(v_envelope) <> 'object'
     or pg_catalog.jsonb_typeof(v_members) <> 'array'
     or pg_catalog.jsonb_typeof(v_snapshots) <> 'array'
     or (v_payload - 'data' - '__vimob_ingress' - '__vimob_retention' - 'event'
                   - 'instance' - 'instanceName' - 'instanceId') <> '{}'::jsonb
     or (v_data - 'messages') <> '{}'::jsonb
     or (v_ingress - 'routing_key' - 'epoch_capable'
                   - 'routing_snapshot') <> '{}'::jsonb
     or v_ingress->>'routing_key' <> '__session__'
     or v_ingress->'epoch_capable' is distinct from 'true'::jsonb
     or (v_envelope - 'version' - 'messages') <> '{}'::jsonb
     or v_envelope->'version' is distinct from '1'::jsonb then
    return null;
  end if;
  v_member_count := pg_catalog.jsonb_array_length(v_members);
  if v_member_count < 1
     or v_member_count <> pg_catalog.jsonb_array_length(v_snapshots) then
    return null;
  end if;
  v_marker := v_payload->'__vimob_retention';
  if v_marker is not null then
    if pg_catalog.jsonb_typeof(v_marker) <> 'object'
       or (v_marker - 'kind' - 'redacted_count') <> '{}'::jsonb
       or v_marker->>'kind' <> 'partial_expired_unlinked_v1'
       or coalesce(v_marker->>'redacted_count', '') !~ '^[1-9][0-9]{0,5}$' then
      return null;
    end if;
    v_previous_count := (v_marker->>'redacted_count')::integer;
  end if;
  select count(*)::integer into v_route_count
  from public.whatsapp_webhook_routing_snapshots as route
  where route.organization_id = v_inbox.organization_id
    and route.session_id = v_inbox.session_id
    and route.inbox_event_key = v_inbox.event_key;
  if v_route_count <> v_member_count + v_previous_count then
    return null;
  end if;

  for v_index in 0..v_member_count - 1 loop
    v_member := v_members->v_index;
    v_embedded := v_snapshots->v_index;
    if pg_catalog.jsonb_typeof(v_member) <> 'object'
       or pg_catalog.jsonb_typeof(v_embedded) <> 'object' then
      return null;
    end if;
    v_key_id := nullif(pg_catalog.btrim(v_member #>> '{key,id}'), '');
    v_info_id := nullif(pg_catalog.btrim(v_member #>> '{Info,ID}'), '');
    if (v_key_id is null) = (v_info_id is null) then
      return null;
    end if;
    v_provider_id := coalesce(v_key_id, v_info_id);
    if pg_catalog.length(v_provider_id) > 512
       or v_provider_id = any(v_seen_ids)
       or v_embedded->>'provider_message_id' is distinct from v_provider_id then
      return null;
    end if;
    v_seen_ids := pg_catalog.array_append(v_seen_ids, v_provider_id);
    select route.* into v_route
    from public.whatsapp_webhook_routing_snapshots as route
    where route.organization_id = v_inbox.organization_id
      and route.session_id = v_inbox.session_id
      and route.inbox_event_key = v_inbox.event_key
      and route.provider_message_id = v_provider_id;
    if not found or v_embedded is distinct from v_route.snapshot
       or v_route.processing_epoch <> v_inbox.processing_epoch then
      return null;
    end if;
    if (
         v_route.snapshot->>'conversation_id' = v_conversation.id::text
         or (
           v_route.snapshot->>'conversation_id' is null
           and (
             exists (
               select 1 from public.whatsapp_messages as message
               where message.organization_id = v_inbox.organization_id
                 and message.session_id = v_inbox.session_id
                 and message.conversation_id = v_conversation.id
                 and message.provider_message_id = v_provider_id
                 and (message.capture_state = 'unlinked_ephemeral'
                      or message.unlinked_retention_scrubbed_at is not null)
                 and not exists (
                   select 1 from public.whatsapp_messages as other_message
                   where other_message.organization_id = message.organization_id
                     and other_message.session_id = message.session_id
                     and other_message.provider_message_id = v_provider_id
                     and other_message.conversation_id is distinct from v_conversation.id
                 )
             )
             or (
               v_conversation.created_at >= v_inbox.created_at
               and v_conversation.created_at < v_inbox.created_at + interval '7 days'
               and v_route.routing_key in (
                 'phone:' || coalesce(public.normalize_phone(
                   v_conversation.contact_phone
                 ), ''),
                 'jid:' || pg_catalog.lower(v_conversation.remote_jid)
               )
               and not exists (
                 select 1 from public.whatsapp_conversations as other_epoch
                 where other_epoch.organization_id = v_conversation.organization_id
                   and other_epoch.session_id = v_conversation.session_id
                   and other_epoch.id <> v_conversation.id
                   and (other_epoch.retired_at is null
                        or other_epoch.retired_at >= v_inbox.created_at)
                   and (
                     other_epoch.remote_jid = v_conversation.remote_jid
                     or (
                       public.normalize_phone(v_conversation.contact_phone) is not null
                       and public.normalize_phone(other_epoch.contact_phone) =
                           public.normalize_phone(v_conversation.contact_phone)
                     )
                   )
               )
             )
           )
         )
       )
       and v_route.snapshot->>'unlinked_capture_policy' = 'v1'
       and v_route.snapshot->>'state' = 'unlinked'
       and v_route.snapshot->>'context_kind' = 'organic'
       and nullif(v_route.snapshot->>'event_lead_id', '') is null
       and nullif(v_route.snapshot->>'current_lead_id', '') is null
       and nullif(v_route.snapshot->>'quarantine_reason', '') is null then
      v_removed_ids := pg_catalog.array_append(v_removed_ids, v_provider_id);
    else
      v_kept_members := v_kept_members || pg_catalog.jsonb_build_array(v_member);
      v_kept_snapshots := v_kept_snapshots || pg_catalog.jsonb_build_array(v_embedded);
    end if;
  end loop;
  v_removed_count := pg_catalog.cardinality(v_removed_ids);
  if v_removed_count = 0
     or (v_removed_count = v_member_count and v_previous_count = 0)
     or exists (
       select 1 from public.whatsapp_webhook_routing_snapshots as successor
       where successor.organization_id = v_inbox.organization_id
         and successor.session_id = v_inbox.session_id
         and successor.predecessor_provider_message_id = any(v_removed_ids)
         and successor.provider_message_id <> all(v_removed_ids)
     )
     or exists (
       select 1 from public.whatsapp_conversation_routing_heads as head
       where head.organization_id = v_inbox.organization_id
         and head.session_id = v_inbox.session_id
         and head.provider_message_id = any(v_removed_ids)
     ) then
    return null;
  end if;

  if v_removed_count = v_member_count then
    v_result := '{"__vimob_retention":"expired_unlinked_v1"}'::jsonb;
  else
    v_result := pg_catalog.jsonb_set(v_payload, '{data,messages}', v_kept_members);
    v_result := pg_catalog.jsonb_set(
      v_result, '{__vimob_ingress,routing_snapshot,messages}', v_kept_snapshots
    );
    v_result := v_result || pg_catalog.jsonb_build_object(
      '__vimob_retention', pg_catalog.jsonb_build_object(
        'kind', 'partial_expired_unlinked_v1',
        'redacted_count', v_previous_count + v_removed_count
      )
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'payload', v_result,
    'removed_provider_message_ids', pg_catalog.to_jsonb(v_removed_ids),
    'redacted_count', v_removed_count,
    'terminal', v_removed_count = v_member_count
  );
end;
$_$;


ALTER FUNCTION private.whatsapp_unlinked_mixed_inbox_plan(p_inbox_id uuid, p_conversation_id uuid) OWNER TO postgres;

--
-- Name: whatsapp_messages; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.whatsapp_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid NOT NULL,
    session_id uuid,
    message_id text NOT NULL,
    content text,
    message_type text DEFAULT 'text'::text,
    from_me boolean DEFAULT false NOT NULL,
    status text DEFAULT 'sent'::text,
    media_url text,
    media_mime_type text,
    sent_at timestamp with time zone DEFAULT now() NOT NULL,
    delivered_at timestamp with time zone,
    read_at timestamp with time zone,
    media_status text,
    media_storage_path text,
    media_error text,
    media_size bigint,
    sender_jid text,
    sender_name text,
    client_message_id text,
    remote_jid text,
    reaction_to_message_id text,
    reaction_emoji text,
    reaction_sender_jid text,
    reaction_sender_name text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    received_at timestamp with time zone DEFAULT now(),
    organization_id uuid NOT NULL,
    lead_id uuid,
    sender_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    provider_message_id text,
    direction text DEFAULT 'inbound'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    capture_state text DEFAULT 'suppressed'::text,
    unlinked_retention_scrubbed_at timestamp with time zone
)
WITH (autovacuum_vacuum_scale_factor='0.02', autovacuum_analyze_scale_factor='0.01', autovacuum_vacuum_threshold='1000', autovacuum_analyze_threshold='1000', toast.autovacuum_vacuum_scale_factor='0.02', toast.autovacuum_vacuum_threshold='1000');


ALTER TABLE public.whatsapp_messages OWNER TO postgres;

--
-- Name: TABLE whatsapp_messages; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.whatsapp_messages IS 'Backend-only WhatsApp message and media metadata. Browser access must use the Go lead-authorization boundary and signed-media service.';


--
-- Name: COLUMN whatsapp_messages.capture_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_messages.capture_state IS 'captured keeps the current attendance business effects; suppressed has no visible content; unlinked_ephemeral is a seven-day owner-only inbound or proven external outbound observation; promoted_unlinked is human-attached history; observed_unattended is a lead observation without attendance or business effects.';


--
-- Name: whatsapp_unlinked_promotion_is_authorized(public.whatsapp_messages, public.whatsapp_messages); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.whatsapp_unlinked_promotion_is_authorized(p_old public.whatsapp_messages, p_new public.whatsapp_messages) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (p_old).capture_state = 'unlinked_ephemeral'
    and (p_old).lead_id is null
    and (p_new).capture_state = 'promoted_unlinked'
    and (p_new).lead_id is not null
    and (p_new).id is not distinct from (p_old).id
    and (p_new).organization_id is not distinct from (p_old).organization_id
    and (p_new).conversation_id is not distinct from (p_old).conversation_id
    and (p_new).session_id is not distinct from (p_old).session_id
    and (p_new).remote_jid is not distinct from (p_old).remote_jid
    and (p_new).provider_message_id is not distinct from (p_old).provider_message_id
    and (p_new).message_id is not distinct from (p_old).message_id
    and (p_new).from_me is not distinct from (p_old).from_me
    and (p_new).direction is not distinct from (p_old).direction
    and exists (
      select 1
      from private.whatsapp_unlinked_promotion_authorizations as authz
      where authz.backend_pid = pg_catalog.pg_backend_pid()
        and authz.transaction_id = pg_catalog.txid_current()
        and authz.organization_id = (p_old).organization_id
        and authz.conversation_id = (p_old).conversation_id
        and authz.lead_id = (p_new).lead_id
        and authz.promotion_active
    );
$$;


ALTER FUNCTION private.whatsapp_unlinked_promotion_is_authorized(p_old public.whatsapp_messages, p_new public.whatsapp_messages) OWNER TO postgres;

--
-- Name: write_audit_log_for_row(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.write_audit_log_for_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  row_old jsonb := case
    when tg_op in ('UPDATE', 'DELETE') then pg_catalog.to_jsonb(old)
    else null
  end;
  row_new jsonb := case
    when tg_op in ('INSERT', 'UPDATE') then pg_catalog.to_jsonb(new)
    else null
  end;
  row_diff jsonb := '{}'::jsonb;
  excluded_columns text[] := array['updated_at'];
  target_organization_id uuid;
  target_entity_id text;
  actor_user_id uuid;
  audit_action text;
  audit_entity_type text := coalesce(
    nullif(tg_argv[0], ''),
    tg_table_name
  );
  arg_index integer;
begin
  if tg_nargs > 1 then
    for arg_index in 1..(tg_nargs - 1) loop
      excluded_columns := excluded_columns || tg_argv[arg_index];
    end loop;
  end if;

  if tg_op = 'UPDATE' then
    row_diff := private.audit_jsonb_diff(
      row_old,
      row_new,
      excluded_columns
    );
    if row_diff = '{}'::jsonb then
      return null;
    end if;
  elsif tg_op = 'INSERT' then
    row_diff := private.audit_jsonb_diff(
      '{}'::jsonb,
      row_new,
      excluded_columns
    );
  elsif tg_op = 'DELETE' then
    row_diff := private.audit_jsonb_diff(
      row_old,
      '{}'::jsonb,
      excluded_columns
    );
  end if;

  target_organization_id := coalesce(
    private.safe_uuid(row_new ->> 'organization_id'),
    private.safe_uuid(row_old ->> 'organization_id')
  );
  target_entity_id := coalesce(
    row_new ->> 'id',
    row_old ->> 'id'
  );

  if tg_op = 'DELETE'
     and target_organization_id is not null
     and not exists (
       select 1
       from public.organizations as organization
       where organization.id = target_organization_id
     ) then
    return null;
  end if;

  actor_user_id := coalesce(
    private.current_audit_actor_id(),
    private.safe_uuid(row_new ->> 'created_by'),
    private.safe_uuid(row_old ->> 'created_by')
  );

  audit_action := case tg_op
    when 'INSERT' then 'create'
    when 'UPDATE' then 'update'
    when 'DELETE' then 'delete'
    else pg_catalog.lower(tg_op)
  end;

  insert into public.audit_logs (
    organization_id,
    user_id,
    action,
    entity_type,
    entity_id,
    old_data,
    new_data,
    diff,
    source,
    metadata
  )
  values (
    target_organization_id,
    actor_user_id,
    audit_action,
    audit_entity_type,
    target_entity_id,
    case when tg_op in ('UPDATE', 'DELETE') then row_old else null end,
    case when tg_op in ('INSERT', 'UPDATE') then row_new else null end,
    row_diff,
    'database_trigger',
    pg_catalog.jsonb_build_object(
      'schema', tg_table_schema,
      'table', tg_table_name,
      'operation', tg_op
    )
  );

  return null;
end;
$$;


ALTER FUNCTION private.write_audit_log_for_row() OWNER TO postgres;

--
-- Name: FUNCTION write_audit_log_for_row(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.write_audit_log_for_row() IS 'audit_org_cascade_safe_v1';


--
-- Name: abandon_billing_subscription_card_update_job(uuid, uuid, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abandon_billing_subscription_card_update_job(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_attempt_lease_id uuid, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_error_code text := lower(nullif(btrim(coalesce(p_error_code, '')), ''));
  v_hint private.billing_subscription_card_update_jobs%rowtype;
  v_job private.billing_subscription_card_update_jobs%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or p_generation is null
     or p_generation <= 0
     or v_error_code is null
     or v_error_code !~ '^[a-z0-9_]{1,80}$' then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_hint
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_hint.provider_payment_id,
    v_hint.provider_subscription_id
  );

  if v_hint.mode = 'settled_payment' then
    if p_attempt_lease_id is null then
      return jsonb_build_object('outcome', 'invalid_request');
    end if;
    select payment.*
    into v_payment
    from public.asaas_payments as payment
    where payment.id = v_hint.payment_id
      and payment.organization_id = p_organization_id
      and payment.asaas_payment_id = v_hint.provider_payment_id
    for update;
    if not found then
      return jsonb_build_object('outcome', 'payment_not_found');
    end if;

    select capability.*
    into v_capability
    from public.billing_payment_checkout_capabilities as capability
    where capability.payment_id = v_payment.id
      and capability.organization_id = p_organization_id
      and capability.asaas_payment_id = v_payment.asaas_payment_id
    for update;
    if not found
       or v_capability.attempt_lease_id is distinct from p_attempt_lease_id then
      return jsonb_build_object('outcome', 'lost_claim');
    end if;
  elsif p_attempt_lease_id is not null then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  if v_job.status in ('succeeded', 'cancelled', 'dead') then
    return jsonb_build_object(
      'outcome', 'already_finalized',
      'status', v_job.status,
      'last_error_code', v_job.last_error_code
    );
  end if;
  if v_job.status not in ('prepared', 'awaiting_payment')
     or v_job.capture_request_started_at is not null
     or v_job.provider_request_started_at is not null
     or v_job.lease_id is not null
     or (
       v_job.mode = 'settled_payment'
       and v_job.credential_attempt_lease_id is not null
       and v_job.credential_attempt_lease_id
         is distinct from p_attempt_lease_id
     ) then
    return jsonb_build_object('outcome', 'provider_mutation_started');
  end if;

  update private.billing_subscription_card_update_jobs
  set
    status = 'cancelled',
    provider_card_credential = null,
    card_last4 = null,
    credential_attempt_lease_id = null,
    lease_id = null,
    lease_owner = null,
    lease_started_at = null,
    lease_expires_at = null,
    last_error_code = v_error_code,
    cancelled_at = v_now,
    updated_at = v_now
  where id = v_job.id
    and generation = p_generation
    and status in ('prepared', 'awaiting_payment')
    and capture_request_started_at is null
    and provider_request_started_at is null
    and lease_id is null;
  if not found then
    return jsonb_build_object('outcome', 'state_changed');
  end if;

  if v_job.mode = 'settled_payment' then
    update public.billing_payment_checkout_capabilities
    set
      attempt_lease_id = null,
      attempt_lease_expires_at = null,
      updated_at = v_now
    where payment_id = v_job.payment_id
      and organization_id = p_organization_id
      and attempt_lease_id = p_attempt_lease_id
      and revoked_at is null;
  end if;

  return jsonb_build_object(
    'outcome', 'abandoned',
    'job_id', v_job.id,
    'last_error_code', v_error_code
  );
end
$_$;


ALTER FUNCTION public.abandon_billing_subscription_card_update_job(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_attempt_lease_id uuid, p_error_code text) OWNER TO postgres;

--
-- Name: ack_billing_organization_asaas_cleanup_resource(uuid, uuid, text, text, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ack_billing_organization_asaas_cleanup_resource(p_organization_id uuid, p_claim_token uuid, p_resource_kind text, p_resource_id text, p_attempt_token uuid, p_http_status integer, p_provider_response jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_resource_kind text := lower(btrim(coalesce(p_resource_kind, '')));
  v_resource_id text := nullif(btrim(coalesce(p_resource_id, '')), '');
  v_response jsonb := coalesce(p_provider_response, '{}'::jsonb);
  v_resource private.billing_organization_asaas_cleanup_resources%rowtype;
  v_exact_ack boolean := false;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_organization_id is null
     or p_claim_token is null
     or v_resource_kind not in ('payment', 'subscription', 'customer')
     or v_resource_id is null
     or char_length(v_resource_id) > 255
     or p_attempt_token is null
     or (p_http_status <> 0 and p_http_status not between 100 and 599)
     or jsonb_typeof(v_response) <> 'object'
     or pg_catalog.pg_column_size(v_response) > 16384 then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  perform private.lock_asaas_billing_resources(
    case when v_resource_kind = 'payment' then v_resource_id else null end,
    case when v_resource_kind = 'subscription' then v_resource_id else null end
  );

  select resource.*
  into v_resource
  from private.billing_organization_asaas_cleanup_resources as resource
  where resource.organization_id = p_organization_id
    and resource.claim_token = p_claim_token
    and resource.resource_kind = v_resource_kind
    and resource.resource_id = v_resource_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'resource_not_found');
  end if;
  if v_resource.status = 'succeeded' then
    return jsonb_build_object(
      'outcome', 'already_succeeded',
      'resource_kind', v_resource.resource_kind,
      'resource_id', v_resource.resource_id
    );
  end if;
  if v_resource.status = 'manual_review' then
    return jsonb_build_object(
      'outcome', 'manual_review',
      'reason', coalesce(
        v_resource.last_error_code,
        'provider_resource_delete_not_proven'
      )
    );
  end if;
  if v_resource.status <> 'processing'
     or v_resource.attempt_token is distinct from p_attempt_token then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  v_exact_ack := p_http_status = 200
    and jsonb_typeof(v_response -> 'id') = 'string'
    and v_response ->> 'id' = v_resource_id
    and jsonb_typeof(v_response -> 'deleted') = 'boolean'
    and v_response -> 'deleted' = 'true'::jsonb;

  if not v_exact_ack then
    update private.billing_organization_asaas_cleanup_resources as resource
    set
      status = 'manual_review',
      provider_http_status = nullif(p_http_status, 0),
      provider_response = v_response,
      manual_review_at = v_now,
      last_error_code = case
        when p_http_status = 0
          then 'provider_delete_transport_ambiguous'
        when p_http_status in (404, 410)
          then 'provider_resource_not_found_ambiguous'
        else 'provider_delete_response_not_proven'
      end,
      updated_at = v_now
    where resource.organization_id = p_organization_id
      and resource.claim_token = p_claim_token
      and resource.resource_kind = v_resource_kind
      and resource.resource_id = v_resource_id
      and resource.status = 'processing'
      and resource.attempt_token = p_attempt_token;

    return jsonb_build_object(
      'outcome', 'manual_review',
      'reason', case
        when p_http_status = 0
          then 'provider_delete_transport_ambiguous'
        when p_http_status in (404, 410)
          then 'provider_resource_not_found_ambiguous'
        else 'provider_delete_response_not_proven'
      end,
      'resource_kind', v_resource_kind,
      'resource_id', v_resource_id
    );
  end if;

  update private.billing_organization_asaas_cleanup_resources as resource
  set
    status = 'succeeded',
    provider_deleted_at = v_now,
    provider_http_status = 200,
    provider_response = v_response,
    last_error_code = null,
    updated_at = v_now
  where resource.organization_id = p_organization_id
    and resource.claim_token = p_claim_token
    and resource.resource_kind = v_resource_kind
    and resource.resource_id = v_resource_id
    and resource.status = 'processing'
    and resource.attempt_token = p_attempt_token;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  return jsonb_build_object(
    'outcome', 'succeeded',
    'resource_kind', v_resource_kind,
    'resource_id', v_resource_id
  );
end
$$;


ALTER FUNCTION public.ack_billing_organization_asaas_cleanup_resource(p_organization_id uuid, p_claim_token uuid, p_resource_kind text, p_resource_id text, p_attempt_token uuid, p_http_status integer, p_provider_response jsonb) OWNER TO postgres;

--
-- Name: activate_whatsapp_conversation_lead_binding(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.activate_whatsapp_conversation_lead_binding(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_active public.whatsapp_conversation_lead_bindings%rowtype;
  v_replay public.whatsapp_conversation_lead_bindings%rowtype;
  v_lead public.leads%rowtype;
  v_binding_id uuid;
  v_provider_message_id text := nullif(btrim(p_provider_message_id), '');
  v_previous_lead_id uuid;
  v_active_lead_id uuid;
  v_is_current boolean;
  v_switch_at timestamptz := clock_timestamp();
  v_changed boolean;
begin
  if p_organization_id is null
     or p_conversation_id is null
     or p_lead_id is null then
    raise exception using
      errcode = '22023',
      message = 'whatsapp_binding_required_argument_missing';
  end if;

  select conversation.*
  into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id
  for no key update;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_conversation_not_found';
  end if;

  select binding.*
  into v_active
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.conversation_id = p_conversation_id
    and binding.active_to is null
  for update;

  if found and v_conversation.lead_id is distinct from v_active.lead_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_binding_state_mismatch';
  end if;

  if v_provider_message_id is not null then
    select binding.*
    into v_replay
    from public.whatsapp_conversation_lead_bindings as binding
    where binding.organization_id = p_organization_id
      and binding.provider_message_id = v_provider_message_id
      and (
        (v_conversation.session_id is not null and binding.session_id = v_conversation.session_id)
        or (v_conversation.session_id is null and binding.conversation_id = p_conversation_id)
      )
    limit 1;

    if found then
      if v_replay.conversation_id <> p_conversation_id
         or v_replay.lead_id <> p_lead_id then
        raise exception using
          errcode = '23505',
          message = 'whatsapp_binding_provider_message_conflict';
      end if;

      v_active_lead_id := v_conversation.lead_id;
      v_is_current := not v_replay.stale
        and v_replay.lead_id is not distinct from v_active_lead_id
        and private.whatsapp_ingress_routing_event_is_current(
          p_organization_id,
          p_conversation_id,
          v_provider_message_id,
          v_replay.lead_id
        );

      return jsonb_build_object(
        'success', true,
        'changed', false,
        'conversation_id', v_replay.conversation_id,
        'lead_id', v_replay.lead_id,
        'previous_lead_id', v_replay.previous_lead_id,
        'binding_id', v_replay.id,
        'stale', v_replay.stale,
        'is_current', v_is_current,
        'active_lead_id', v_active_lead_id
      );
    end if;
  end if;

  -- Provider-event replay is resolved before dereferencing the lead. Binding
  -- history deliberately survives hard lead deletion, so a replay for a
  -- tombstoned lead can remain idempotent without reopening or reclassifying it.
  select lead.*
  into v_lead
  from public.leads as lead
  where lead.id = p_lead_id
    and lead.organization_id = p_organization_id;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_lead_not_found';
  end if;

  v_previous_lead_id := v_conversation.lead_id;
  v_changed := v_previous_lead_id is distinct from p_lead_id;

  if not v_changed then
    update public.whatsapp_conversations
    set assigned_user_id = v_lead.assigned_user_id,
        updated_at = clock_timestamp()
    where id = p_conversation_id;

    update public.whatsapp_contact_identity_aliases as identity_alias
    set
      lead_id = p_lead_id,
      last_seen_at = greatest(identity_alias.last_seen_at, v_switch_at)
    where identity_alias.organization_id = p_organization_id
      and identity_alias.session_id = v_conversation.session_id
      and (
        identity_alias.alias_jid = v_conversation.remote_jid
        or identity_alias.canonical_jid = v_conversation.remote_jid
        or (
          v_conversation.contact_phone is not null
          and public.normalize_phone(identity_alias.contact_phone) =
            public.normalize_phone(v_conversation.contact_phone)
        )
      );

    if v_active.id is null then
      insert into public.whatsapp_conversation_lead_bindings (
        organization_id,
        conversation_id,
        session_id,
        lead_id,
        previous_lead_id,
        assigned_user_id,
        provider_message_id,
        changed,
        active_from
      ) values (
        p_organization_id,
        p_conversation_id,
        v_conversation.session_id,
        p_lead_id,
        v_previous_lead_id,
        v_lead.assigned_user_id,
        v_provider_message_id,
        false,
        v_switch_at
      )
      returning id into v_binding_id;
    elsif v_provider_message_id is not null then
      insert into public.whatsapp_conversation_lead_bindings (
        organization_id,
        conversation_id,
        session_id,
        lead_id,
        previous_lead_id,
        assigned_user_id,
        provider_message_id,
        changed,
        active_from,
        active_to
      ) values (
        p_organization_id,
        p_conversation_id,
        v_conversation.session_id,
        p_lead_id,
        v_previous_lead_id,
        v_lead.assigned_user_id,
        v_provider_message_id,
        false,
        v_switch_at,
        v_switch_at
      )
      returning id into v_binding_id;
    else
      -- An explicit same-card relink is still an operator-visible binding
      -- epoch. Rotate the active row so a provider event accepted before this
      -- intervention cannot pass an unchanged binding-id CAS afterward.
      v_switch_at := greatest(
        v_switch_at,
        v_active.active_from + interval '1 microsecond'
      );
      update public.whatsapp_conversation_lead_bindings
      set active_to = v_switch_at
      where id = v_active.id;

      insert into public.whatsapp_conversation_lead_bindings (
        organization_id,
        conversation_id,
        session_id,
        lead_id,
        previous_lead_id,
        assigned_user_id,
        provider_message_id,
        changed,
        active_from
      ) values (
        p_organization_id,
        p_conversation_id,
        v_conversation.session_id,
        p_lead_id,
        v_previous_lead_id,
        v_lead.assigned_user_id,
        null,
        false,
        v_switch_at
      )
      returning id into v_binding_id;
    end if;

    perform private.update_whatsapp_conversation_routing_head(
      p_organization_id,
      p_conversation_id,
      v_provider_message_id,
      p_lead_id
    );

    return jsonb_build_object(
      'success', true,
      'changed', false,
      'conversation_id', p_conversation_id,
      'lead_id', p_lead_id,
      'previous_lead_id', v_previous_lead_id,
      'binding_id', v_binding_id,
      'stale', false,
      'is_current', true,
      'active_lead_id', p_lead_id
    );
  end if;

  -- A row already past the provider boundary cannot be cancelled safely. Abort
  -- the whole switch before closing the active binding; the caller may retry
  -- only after the worker has reconciled the in-flight outcome. Lock every
  -- cancelable/in-flight row first so a worker cannot cross the boundary
  -- between this check and the cancellation updates below.
  perform outbox.id
  from public.whatsapp_outbox as outbox
  where outbox.organization_id = p_organization_id
    and outbox.conversation_id = p_conversation_id
    and outbox.status in ('pending', 'retry', 'processing', 'failed')
  for update;

  perform legacy_outbox.id
  from public.outbox_messages as legacy_outbox
  where legacy_outbox.organization_id = p_organization_id
    and legacy_outbox.conversation_id = p_conversation_id
    and legacy_outbox.status in ('pending', 'processing')
  for update;

  perform job.id
  from public.ai_jobs as job
  where job.organization_id = p_organization_id
    and job.conversation_id = p_conversation_id
    and job.status in ('pending', 'processing')
  for update;

  -- The Go auto-reply worker uses public.jobs rather than public.ai_jobs.
  -- Lock it under the same conversation row so an enqueue that races this
  -- switch either commits before us (and is cancelled below) or observes the
  -- new binding and refuses to enqueue.
  perform job.id
  from public.jobs as job
  where job.organization_id = p_organization_id
    and job.job_type = 'whatsapp_ai_autoreply'
    and job.payload->>'conversationId' = p_conversation_id::text
    and job.status in ('queued', 'processing')
  for update;

  perform ai_outbox.id
  from public.ai_outbox_messages as ai_outbox
  where ai_outbox.organization_id = p_organization_id
    and ai_outbox.conversation_id = p_conversation_id
    and ai_outbox.status in ('draft', 'pending_approval', 'approved', 'sending')
  for update;

  -- A message_received event may still be waiting to create its execution.
  -- Lock the event itself before inspecting automation_executions so a worker
  -- cannot claim the previous lead context after the binding has moved.
  perform event_outbox.id
  from public.automation_event_outbox as event_outbox
  where event_outbox.organization_id = p_organization_id
    and event_outbox.conversation_id = p_conversation_id
    and event_outbox.status in ('pending', 'failed', 'processing')
  for update;

  perform execution.id
  from public.automation_executions as execution
  where execution.organization_id = p_organization_id
    and execution.conversation_id = p_conversation_id
    and execution.status in ('queued', 'waiting', 'running')
  for update;

  perform step.id
  from public.automation_execution_steps as step
  join public.automation_executions as execution
    on execution.id = step.execution_id
   and execution.organization_id = step.organization_id
  where execution.organization_id = p_organization_id
    and execution.conversation_id = p_conversation_id
    and step.status in ('running', 'waiting')
  for update of step;

  perform dispatch.id
  from public.automation_effect_dispatches as dispatch
  join public.automation_executions as execution
    on execution.id = dispatch.execution_id
   and execution.organization_id = dispatch.organization_id
  where execution.organization_id = p_organization_id
    and execution.conversation_id = p_conversation_id
    and dispatch.status = 'sending'
  for update of dispatch;

  if exists (
    select 1
    from public.whatsapp_outbox as outbox
    where outbox.organization_id = p_organization_id
      and outbox.conversation_id = p_conversation_id
      and (outbox.status = 'processing' or (outbox.status in ('pending', 'retry') and outbox.last_error = 'provider_accepted_finalization_pending'))
  ) or exists (
    select 1
    from public.outbox_messages as legacy_outbox
    where legacy_outbox.organization_id = p_organization_id
      and legacy_outbox.conversation_id = p_conversation_id
      and legacy_outbox.status = 'processing'
  ) or exists (
    select 1
    from public.ai_jobs as job
    where job.organization_id = p_organization_id
      and job.conversation_id = p_conversation_id
      and job.status = 'processing'
  ) or exists (
    select 1
    from public.jobs as job
    where job.organization_id = p_organization_id
      and job.job_type = 'whatsapp_ai_autoreply'
      and job.payload->>'conversationId' = p_conversation_id::text
      and job.status = 'processing'
  ) or exists (
    select 1
    from public.ai_outbox_messages as ai_outbox
    where ai_outbox.organization_id = p_organization_id
      and ai_outbox.conversation_id = p_conversation_id
      and ai_outbox.status = 'sending'
  ) or exists (
    select 1
    from public.automation_event_outbox as event_outbox
    where event_outbox.organization_id = p_organization_id
      and event_outbox.conversation_id = p_conversation_id
      and event_outbox.status = 'processing'
  ) or exists (
    select 1
    from public.automation_executions as execution
    where execution.organization_id = p_organization_id
      and execution.conversation_id = p_conversation_id
      and execution.status = 'running'
  ) or exists (
    select 1
    from public.automation_effect_dispatches as dispatch
    join public.automation_executions as execution
      on execution.id = dispatch.execution_id
     and execution.organization_id = dispatch.organization_id
    where execution.organization_id = p_organization_id
      and execution.conversation_id = p_conversation_id
      and dispatch.status = 'sending'
  ) then
    raise exception using
      errcode = '55000',
      message = 'whatsapp_binding_switch_delivery_in_flight';
  end if;

  if v_active.id is not null then
    v_switch_at := greatest(
      v_switch_at,
      v_active.active_from + interval '1 microsecond'
    );

    update public.whatsapp_conversation_lead_bindings
    set active_to = v_switch_at
    where id = v_active.id;
  end if;

  -- The physical WhatsApp thread is being handed to a different CRM card.
  -- Fail closed on every queued action that was computed with the previous
  -- lead context, and erase mutable summaries/memory before exposing the new
  -- binding. All changes occur under the locked conversation row.
  update public.whatsapp_outbox as outbox
  set
    status = 'dead',
    dead_lettered_at = coalesce(outbox.dead_lettered_at, v_switch_at),
    locked_at = null,
    locked_by = null,
    last_error = 'conversation_lead_binding_changed',
    updated_at = v_switch_at
  where outbox.organization_id = p_organization_id
    and outbox.conversation_id = p_conversation_id
    and outbox.status in ('pending', 'retry', 'failed');

  update public.outbox_messages as legacy_outbox
  set
    status = 'failed',
    processed_at = coalesce(legacy_outbox.processed_at, v_switch_at),
    error_message = 'conversation_lead_binding_changed'
  where legacy_outbox.organization_id = p_organization_id
    and legacy_outbox.conversation_id = p_conversation_id
    and legacy_outbox.status = 'pending';

  update public.ai_jobs as job
  set
    status = 'cancelled',
    error_message = 'conversation_lead_binding_changed',
    completed_at = coalesce(job.completed_at, v_switch_at)
  where job.organization_id = p_organization_id
    and job.conversation_id = p_conversation_id
    and job.status = 'pending';

  update public.jobs as job
  set
    status = 'cancelled',
    locked_at = null,
    last_error = 'conversation_lead_binding_changed',
    updated_at = v_switch_at
  where job.organization_id = p_organization_id
    and job.job_type = 'whatsapp_ai_autoreply'
    and job.payload->>'conversationId' = p_conversation_id::text
    and job.status = 'queued';

  update public.ai_outbox_messages as ai_outbox
  set
    status = 'cancelled',
    failure_reason = 'conversation_lead_binding_changed',
    updated_at = v_switch_at
  where ai_outbox.organization_id = p_organization_id
    and ai_outbox.conversation_id = p_conversation_id
    and ai_outbox.status in ('draft', 'pending_approval', 'approved');

  update public.automation_event_outbox as event_outbox
  set
    status = 'dead_letter',
    dead_lettered_at = coalesce(event_outbox.dead_lettered_at, v_switch_at),
    locked_at = null,
    locked_by = null,
    last_error = 'conversation_lead_binding_changed',
    updated_at = v_switch_at
  where event_outbox.organization_id = p_organization_id
    and event_outbox.conversation_id = p_conversation_id
    and event_outbox.status in ('pending', 'failed');

  update public.automation_executions as execution
  set
    status = 'cancelled',
    cancellation_requested_at = coalesce(
      execution.cancellation_requested_at,
      v_switch_at
    ),
    completed_at = coalesce(execution.completed_at, v_switch_at),
    error_message = 'conversation_lead_binding_changed',
    locked_at = null,
    locked_by = null,
    updated_at = v_switch_at
  where execution.organization_id = p_organization_id
    and execution.conversation_id = p_conversation_id
    and execution.status in ('queued', 'waiting');

  update public.automation_execution_steps as step
  set
    status = 'cancelled',
    completed_at = coalesce(step.completed_at, v_switch_at),
    error_message = 'conversation_lead_binding_changed'
  from public.automation_executions as execution
  where execution.id = step.execution_id
    and execution.organization_id = step.organization_id
    and execution.organization_id = p_organization_id
    and execution.conversation_id = p_conversation_id
    and execution.status = 'cancelled'
    and execution.error_message = 'conversation_lead_binding_changed'
    and step.status in ('running', 'waiting');

  delete from public.conversation_ai_state as ai_state
  where ai_state.organization_id = p_organization_id
    and ai_state.conversation_id = p_conversation_id;

  delete from public.ai_agent_conversations as agent_conversation
  where agent_conversation.conversation_id = p_conversation_id;

  delete from public.ai_conversation_states as control_state
  where control_state.organization_id = p_organization_id
    and control_state.conversation_id = p_conversation_id;

  delete from public.chatbot_conversation_state as chatbot_state
  where chatbot_state.organization_id = p_organization_id
    and chatbot_state.conversation_id = p_conversation_id::text;
  update public.whatsapp_conversations
  set
    lead_id = p_lead_id,
    assigned_user_id = v_lead.assigned_user_id,
    last_message = null,
    last_message_preview = null,
    last_message_at = null,
    last_message_received_at = null,
    unread_count = 0,
    archived_at = null,
    updated_at = v_switch_at
  where id = p_conversation_id;

  update public.whatsapp_contact_identity_aliases as identity_alias
  set
    lead_id = p_lead_id,
    last_seen_at = greatest(identity_alias.last_seen_at, v_switch_at)
  where identity_alias.organization_id = p_organization_id
    and identity_alias.session_id = v_conversation.session_id
    and (
      identity_alias.alias_jid = v_conversation.remote_jid
      or identity_alias.canonical_jid = v_conversation.remote_jid
      or (
        v_conversation.contact_phone is not null
        and public.normalize_phone(identity_alias.contact_phone) =
          public.normalize_phone(v_conversation.contact_phone)
      )
    );

  insert into public.whatsapp_conversation_lead_bindings (
    organization_id,
    conversation_id,
    session_id,
    lead_id,
    previous_lead_id,
    assigned_user_id,
    provider_message_id,
    changed,
    active_from
  ) values (
    p_organization_id,
    p_conversation_id,
    v_conversation.session_id,
    p_lead_id,
    v_previous_lead_id,
    v_lead.assigned_user_id,
    v_provider_message_id,
    true,
    v_switch_at
  )
  returning id into v_binding_id;

  perform private.update_whatsapp_conversation_routing_head(
    p_organization_id,
    p_conversation_id,
    v_provider_message_id,
    p_lead_id
  );

  return jsonb_build_object(
    'success', true,
    'changed', true,
    'conversation_id', p_conversation_id,
    'lead_id', p_lead_id,
    'previous_lead_id', v_previous_lead_id,
    'binding_id', v_binding_id,
    'stale', false,
    'is_current', true,
    'active_lead_id', p_lead_id
  );
end;
$$;


ALTER FUNCTION public.activate_whatsapp_conversation_lead_binding(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text) OWNER TO postgres;

--
-- Name: FUNCTION activate_whatsapp_conversation_lead_binding(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.activate_whatsapp_conversation_lead_binding(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text) IS 'Service-role-only, row-locked activation of one lead binding per WhatsApp conversation. Provider-message replay is idempotent and never reopens an older binding.';


--
-- Name: activate_whatsapp_conversation_lead_binding(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.activate_whatsapp_conversation_lead_binding(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text, p_expected_previous_lead_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_expected_previous_lead_id uuid;
  v_expected_snapshot text := pg_catalog.lower(
    pg_catalog.btrim(p_expected_previous_lead_id)
  );
begin
  if p_organization_id is null
     or p_conversation_id is null
     or p_lead_id is null
     or v_expected_snapshot is null
     or v_expected_snapshot = '' then
    raise exception using
      errcode = '22023',
      message = 'whatsapp_binding_expected_previous_lead_required';
  end if;

  if nullif(pg_catalog.btrim(p_provider_message_id), '') is not null then
    raise exception using
      errcode = '22023',
      message = 'whatsapp_binding_manual_cas_provider_message_forbidden';
  end if;

  if v_expected_snapshot = 'unlinked' then
    v_expected_previous_lead_id := null;
  else
    begin
      v_expected_previous_lead_id := v_expected_snapshot::uuid;
    exception
      when invalid_text_representation then
        raise exception using
          errcode = '22023',
          message = 'whatsapp_binding_expected_previous_lead_invalid';
    end;
  end if;

  select conversation.*
  into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id
  for no key update;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_conversation_not_found';
  end if;

  if v_conversation.lead_id is distinct from v_expected_previous_lead_id then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'changed', false,
      'conversation_id', p_conversation_id,
      'lead_id', p_lead_id,
      'previous_lead_id', v_conversation.lead_id,
      'binding_id', null,
      'stale', true,
      'is_current', false,
      'active_lead_id', v_conversation.lead_id
    );
  end if;

  return public.activate_whatsapp_conversation_lead_binding(
    p_organization_id,
    p_conversation_id,
    p_lead_id,
    null
  );
end;
$$;


ALTER FUNCTION public.activate_whatsapp_conversation_lead_binding(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text, p_expected_previous_lead_id text) OWNER TO postgres;

--
-- Name: FUNCTION activate_whatsapp_conversation_lead_binding(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text, p_expected_previous_lead_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.activate_whatsapp_conversation_lead_binding(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text, p_expected_previous_lead_id text) IS 'Service-role-only manual binding CAS. The expected previous lead is a UUID or the unlinked sentinel; stale browser snapshots return success=false without changing binding history.';


--
-- Name: activate_whatsapp_conversation_lead_binding_if_current(uuid, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.activate_whatsapp_conversation_lead_binding_if_current(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text, p_expected_active_binding_id uuid, p_expected_current_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_active public.whatsapp_conversation_lead_bindings%rowtype;
  v_expected public.whatsapp_conversation_lead_bindings%rowtype;
  v_replay public.whatsapp_conversation_lead_bindings%rowtype;
  v_predecessor_binding public.whatsapp_conversation_lead_bindings%rowtype;
  v_route public.whatsapp_webhook_routing_snapshots%rowtype;
  v_predecessor_route public.whatsapp_webhook_routing_snapshots%rowtype;
  v_routing_head public.whatsapp_conversation_routing_heads%rowtype;
  v_lead public.leads%rowtype;
  v_provider_message_id text := nullif(pg_catalog.btrim(p_provider_message_id), '');
  v_binding_id uuid;
  v_recorded_at timestamptz := clock_timestamp();
  v_is_current boolean;
  v_expected_matches boolean;
  v_route_allows_activation boolean := false;
  v_predecessor_processed boolean := false;
begin
  if p_organization_id is null
     or p_conversation_id is null
     or p_lead_id is null then
    raise exception using
      errcode = '22023',
      message = 'whatsapp_binding_required_argument_missing';
  end if;

  if v_provider_message_id is null then
    raise exception using
      errcode = '22023',
      message = 'whatsapp_binding_provider_message_required';
  end if;

  select conversation.*
  into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id
  for no key update;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_conversation_not_found';
  end if;

  select binding.*
  into v_active
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.conversation_id = p_conversation_id
    and binding.active_to is null
  for update;

  if v_active.id is not null
     and v_conversation.lead_id is distinct from v_active.lead_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_binding_state_mismatch';
  end if;

  select routing_snapshot.*
  into v_route
  from public.whatsapp_webhook_routing_snapshots as routing_snapshot
  where routing_snapshot.organization_id = p_organization_id
    and routing_snapshot.session_id = v_conversation.session_id
    and routing_snapshot.provider_message_id = v_provider_message_id;

  if v_route.provider_message_id is not null
     and v_route.binding_eligible
     and v_route.routing_key <> '__session__' then
    -- Lock order is conversation -> active binding -> applied route head. Every
    -- writer follows this order, so automation FK KEY SHARE and provider CAS
    -- cannot form the previous event/conversation inversion.
    select routing_head.*
    into v_routing_head
    from public.whatsapp_conversation_routing_heads as routing_head
    where routing_head.organization_id = p_organization_id
      and routing_head.conversation_id = p_conversation_id
    for update;

    if v_route.predecessor_provider_message_id is not null then
      select routing_snapshot.*
      into v_predecessor_route
      from public.whatsapp_webhook_routing_snapshots as routing_snapshot
      where routing_snapshot.organization_id = p_organization_id
        and routing_snapshot.session_id = v_conversation.session_id
        and routing_snapshot.provider_message_id = v_route.predecessor_provider_message_id;

      if v_predecessor_route.provider_message_id is null
         or not v_predecessor_route.binding_eligible
         or v_predecessor_route.routing_key is distinct from v_route.routing_key
         or v_predecessor_route.ingress_sequence >= v_route.ingress_sequence
          or not private.whatsapp_inherited_predecessor_provenance_matches(v_route, v_predecessor_route) then
        raise exception using
          errcode = '23514',
          message = 'whatsapp_ingress_predecessor_chain_invalid';
      end if;

      select v_predecessor_route.inbox_event_key = v_route.inbox_event_key
        or exists (
          select 1
          from public.whatsapp_webhook_inbox as predecessor_inbox
          where predecessor_inbox.organization_id = p_organization_id
            and predecessor_inbox.session_id = v_conversation.session_id
            and predecessor_inbox.event_key = v_predecessor_route.inbox_event_key
            and predecessor_inbox.status = 'processed'
        )
        or exists (
          select 1
          from public.whatsapp_webhook_routing_outcomes as predecessor_outcome
          where predecessor_outcome.organization_id = p_organization_id
            and predecessor_outcome.session_id = v_conversation.session_id
            and predecessor_outcome.provider_message_id = v_predecessor_route.provider_message_id
            and predecessor_outcome.ingress_sequence = v_predecessor_route.ingress_sequence
        )
        or exists (
          select 1
          from public.whatsapp_webhook_inbox as execution_inbox
          where execution_inbox.organization_id = p_organization_id
            and execution_inbox.session_id = v_conversation.session_id
            and execution_inbox.status = 'processing'
            and exists (
              select 1
              from pg_catalog.jsonb_array_elements(
                execution_inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
              ) as current_route(snapshot)
              where current_route.snapshot = v_route.snapshot
            )
            and exists (
              select 1
              from pg_catalog.jsonb_array_elements(
                execution_inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
              ) as predecessor_route(snapshot)
              where predecessor_route.snapshot = v_predecessor_route.snapshot
            )
        )
      into v_predecessor_processed;

      if not v_predecessor_processed then
        raise exception using
          errcode = '40001',
          message = 'whatsapp_ingress_predecessor_pending';
      end if;
    end if;
  end if;

  -- A provider replay is immutable and safe regardless of the caller's old
  -- expected version. Resolve it before evaluating the CAS pair.
  select binding.*
  into v_replay
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.provider_message_id = v_provider_message_id
    and (
      (v_conversation.session_id is not null
        and binding.session_id = v_conversation.session_id)
      or (v_conversation.session_id is null
        and binding.conversation_id = p_conversation_id)
    )
  limit 1;

  if v_replay.id is not null then
    if v_replay.conversation_id <> p_conversation_id
       or v_replay.lead_id <> p_lead_id then
      raise exception using
        errcode = '23505',
        message = 'whatsapp_binding_provider_message_conflict';
    end if;

    v_is_current := not v_replay.stale
      and v_replay.lead_id is not distinct from v_conversation.lead_id
      and private.whatsapp_ingress_routing_event_is_current(
        p_organization_id,
        p_conversation_id,
        v_provider_message_id,
        v_replay.lead_id
      );

    return jsonb_build_object(
      'success', true,
      'changed', false,
      'conversation_id', v_replay.conversation_id,
      'lead_id', v_replay.lead_id,
      'previous_lead_id', v_replay.previous_lead_id,
      'binding_id', v_replay.id,
      'stale', v_replay.stale,
      'is_current', v_is_current,
      'active_lead_id', v_conversation.lead_id
    );
  end if;

  if p_expected_active_binding_id is not null then
    select binding.*
    into v_expected
    from public.whatsapp_conversation_lead_bindings as binding
    where binding.id = p_expected_active_binding_id
      and binding.organization_id = p_organization_id
      and binding.conversation_id = p_conversation_id;

    if v_expected.id is null
       or v_expected.lead_id is distinct from p_expected_current_lead_id then
      raise exception using
        errcode = '23514',
        message = 'whatsapp_binding_expected_snapshot_invalid';
    end if;
  end if;

  v_expected_matches :=
    v_conversation.lead_id is not distinct from p_expected_current_lead_id
    and v_active.id is not distinct from p_expected_active_binding_id;

  if v_route.provider_message_id is null
     or not v_route.binding_eligible
     or v_route.routing_key = '__session__' then
    v_route_allows_activation := v_expected_matches;
  elsif v_route.target_mode = 'inherit_predecessor' then
    if v_route.predecessor_provider_message_id is null then
      raise exception using
        errcode = '23514',
        message = 'whatsapp_ingress_inherited_target_without_predecessor';
    end if;

    select binding.*
    into v_predecessor_binding
    from public.whatsapp_conversation_lead_bindings as binding
    where binding.organization_id = p_organization_id
      and binding.session_id = v_conversation.session_id
      and binding.provider_message_id = v_route.predecessor_provider_message_id
    limit 1;

    if v_predecessor_binding.id is null then
      raise exception using
        errcode = '23514',
        message = 'whatsapp_ingress_predecessor_not_applied';
    end if;
    if v_predecessor_binding.lead_id is distinct from p_lead_id then
      raise exception using
        errcode = '23505',
        message = 'whatsapp_ingress_inherited_target_conflict';
    end if;

    v_route_allows_activation :=
      v_routing_head.provider_message_id is not null
      and v_routing_head.session_id is not distinct from v_conversation.session_id
      and v_routing_head.routing_key is not distinct from v_route.routing_key
      and v_routing_head.provider_message_id = v_route.predecessor_provider_message_id
      and v_routing_head.ingress_sequence = v_predecessor_route.ingress_sequence
      and v_routing_head.lead_id = p_lead_id;
  else
    v_route_allows_activation := v_expected_matches;

    if not v_route_allows_activation
       and v_route.predecessor_provider_message_id is not null then
      v_route_allows_activation :=
        v_routing_head.provider_message_id is not null
        and v_routing_head.session_id is not distinct from v_conversation.session_id
        and v_routing_head.routing_key is not distinct from v_route.routing_key
        and v_routing_head.provider_message_id = v_route.predecessor_provider_message_id
        and v_routing_head.ingress_sequence = v_predecessor_route.ingress_sequence;
    end if;

    -- An older same-target event may finish after a newer accepted event. It is
    -- safe to retain its effects on that same card, but the monotonic head must
    -- never move backward. A missing head means an operator/legacy relink broke
    -- the chain and therefore cannot take this exception.
    if not v_route_allows_activation then
      v_route_allows_activation :=
        v_routing_head.provider_message_id is not null
        and v_routing_head.session_id is not distinct from v_conversation.session_id
        and v_routing_head.routing_key is not distinct from v_route.routing_key
        and v_routing_head.ingress_sequence >= v_route.ingress_sequence
        and v_routing_head.lead_id = p_lead_id
        and v_conversation.lead_id = p_lead_id;
    end if;
  end if;

  if v_route_allows_activation then
    return public.activate_whatsapp_conversation_lead_binding(
      p_organization_id,
      p_conversation_id,
      p_lead_id,
      v_provider_message_id
    );
  end if;

  select lead.*
  into v_lead
  from public.leads as lead
  where lead.id = p_lead_id
    and lead.organization_id = p_organization_id;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_binding_lead_not_found';
  end if;

  insert into public.whatsapp_conversation_lead_bindings (
    organization_id,
    conversation_id,
    session_id,
    lead_id,
    previous_lead_id,
    assigned_user_id,
    provider_message_id,
    changed,
    stale,
    active_from,
    active_to
  ) values (
    p_organization_id,
    p_conversation_id,
    v_conversation.session_id,
    p_lead_id,
    v_conversation.lead_id,
    v_lead.assigned_user_id,
    v_provider_message_id,
    false,
    true,
    v_recorded_at,
    v_recorded_at
  )
  returning id into v_binding_id;

  return jsonb_build_object(
    'success', true,
    'changed', false,
    'conversation_id', p_conversation_id,
    'lead_id', p_lead_id,
    'previous_lead_id', v_conversation.lead_id,
    'binding_id', v_binding_id,
    'stale', true,
    'is_current', false,
    'active_lead_id', v_conversation.lead_id
  );
end;
$$;


ALTER FUNCTION public.activate_whatsapp_conversation_lead_binding_if_current(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text, p_expected_active_binding_id uuid, p_expected_current_lead_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION activate_whatsapp_conversation_lead_binding_if_current(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text, p_expected_active_binding_id uuid, p_expected_current_lead_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.activate_whatsapp_conversation_lead_binding_if_current(p_organization_id uuid, p_conversation_id uuid, p_lead_id uuid, p_provider_message_id text, p_expected_active_binding_id uuid, p_expected_current_lead_id uuid) IS 'Service-role intake CAS. A provider event that loses to a newer conversation binding is recorded as stale closed history and never changes the active card or aliases.';


--
-- Name: admin_dashboard_feed(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_dashboard_feed(p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_super boolean;
  v_result jsonb;
BEGIN
  SELECT EXISTS (SELECT 1 FROM public.users WHERE id = auth.uid() AND role = 'super_admin') INTO v_is_super;
  IF NOT v_is_super THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT jsonb_agg(row_to_json(t) ORDER BY t.created_at DESC) INTO v_result FROM (SELECT pe.id, pe.organization_id, o.name AS organization_name, pe.type, pe.severity, pe.title, pe.description, pe.metadata, pe.created_at FROM public.platform_events pe LEFT JOIN public.organizations o ON o.id = pe.organization_id ORDER BY pe.created_at DESC LIMIT p_limit) t;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.admin_dashboard_feed(p_limit integer) OWNER TO postgres;

--
-- Name: admin_dashboard_pending_boards(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_dashboard_pending_boards() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_super boolean;
  v_overdue jsonb; v_idle jsonb; v_issues jsonb; v_trials jsonb;
BEGIN
  SELECT EXISTS (SELECT 1 FROM public.users WHERE id = auth.uid() AND role = 'super_admin') INTO v_is_super;
  IF NOT v_is_super THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT jsonb_agg(row_to_json(t)) INTO v_overdue FROM (SELECT o.id, o.name, MIN(fe.due_date) AS oldest_due, (current_date - MIN(fe.due_date))::int AS days_overdue, SUM(fe.amount) AS amount_due FROM public.organizations o JOIN public.financial_entries fe ON fe.organization_id = o.id WHERE fe.type='income' AND fe.status IN ('pending','overdue') AND fe.due_date < current_date GROUP BY o.id, o.name ORDER BY oldest_due ASC LIMIT 10) t;
  SELECT jsonb_agg(row_to_json(t)) INTO v_idle FROM (SELECT o.id, o.name, o.last_access_at, CASE WHEN o.last_access_at IS NULL THEN NULL ELSE (current_date - o.last_access_at::date)::int END AS days_idle FROM public.organizations o WHERE o.is_active = true AND (o.last_access_at IS NULL OR o.last_access_at < (now() - interval '14 days')) ORDER BY o.last_access_at NULLS FIRST LIMIT 10) t;
  SELECT jsonb_agg(row_to_json(t)) INTO v_issues FROM (SELECT pe.id, pe.organization_id, o.name AS organization_name, pe.type, pe.severity, pe.title, pe.description, pe.created_at FROM public.platform_events pe LEFT JOIN public.organizations o ON o.id = pe.organization_id WHERE pe.severity IN ('error','critical') AND pe.created_at >= (now() - interval '7 days') ORDER BY pe.created_at DESC LIMIT 10) t;
  SELECT jsonb_agg(row_to_json(t)) INTO v_trials FROM (SELECT o.id, o.name, o.trial_ends_at, GREATEST(0, (o.trial_ends_at::date - current_date))::int AS days_left, o.telefone, o.whatsapp, o.email FROM public.organizations o WHERE o.subscription_type='trial' AND o.is_active = true AND o.trial_ends_at IS NOT NULL AND o.trial_ends_at <= (now() + interval '10 days') ORDER BY o.trial_ends_at ASC LIMIT 10) t;

  RETURN jsonb_build_object('overdue', COALESCE(v_overdue, '[]'::jsonb), 'idle', COALESCE(v_idle, '[]'::jsonb), 'issues', COALESCE(v_issues, '[]'::jsonb), 'trials', COALESCE(v_trials, '[]'::jsonb));
END;
$$;


ALTER FUNCTION public.admin_dashboard_pending_boards() OWNER TO postgres;

--
-- Name: admin_list_organizations(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_organizations(p_search text DEFAULT ''::text, p_status text DEFAULT 'all'::text, p_segment text DEFAULT 'all'::text) RETURNS TABLE(id uuid, name text, logo_url text, is_active boolean, subscription_status text, subscription_type text, segment text, created_at timestamp with time zone, last_access_at timestamp with time zone, user_count bigint, lead_count bigint, automation_count bigint, mrr numeric, health_score integer, days_trial_left integer, overdue_amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_is_super boolean;
BEGIN
  SELECT EXISTS(SELECT 1 FROM public.users u WHERE u.id = auth.uid() AND u.role = 'super_admin') INTO v_is_super;
  IF NOT v_is_super THEN RAISE EXCEPTION 'forbidden'; END IF;

  RETURN QUERY
  SELECT o.id, o.name, o.logo_url, o.is_active, o.subscription_status, o.subscription_type,
    o.segment, o.created_at, o.last_access_at,
    (SELECT COUNT(*) FROM public.users u WHERE u.organization_id = o.id)::bigint,
    (SELECT COUNT(*) FROM public.leads l WHERE l.organization_id = o.id)::bigint,
    (SELECT COUNT(*) FROM public.automations a WHERE a.organization_id = o.id)::bigint,
    COALESCE(p.price,0)::numeric,
    CASE WHEN o.last_access_at >= now()-interval '3 days' THEN 100
         WHEN o.last_access_at >= now()-interval '7 days' THEN 70
         WHEN o.last_access_at >= now()-interval '14 days' THEN 40 ELSE 10 END,
    CASE WHEN o.subscription_type='trial' AND o.trial_ends_at IS NOT NULL
         THEN GREATEST(0,(o.trial_ends_at::date - current_date))::int ELSE 0 END,
    COALESCE((SELECT SUM(fe.amount) FROM public.financial_entries fe
              WHERE fe.organization_id=o.id AND fe.status IN ('pending','overdue')
              AND fe.type='income' AND fe.due_date < current_date),0)::numeric
  FROM public.organizations o
  LEFT JOIN public.admin_subscription_plans p ON p.id = o.plan_id
  WHERE (p_search='' OR o.name ILIKE '%'||p_search||'%' OR o.email ILIKE '%'||p_search||'%')
    AND (p_status='all' OR o.subscription_status=p_status OR (p_status='inactive' AND o.is_active=false))
    AND (p_segment='all' OR o.segment=p_segment)
  ORDER BY o.created_at DESC;
END; $$;


ALTER FUNCTION public.admin_list_organizations(p_search text, p_status text, p_segment text) OWNER TO postgres;

--
-- Name: apply_automation_internal_effect(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_automation_internal_effect(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_effect_key text, p_effect_type text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  effect_id uuid;
  target_lead_id uuid;
  target_status text;
  target_uuid uuid;
  target_pipeline_id uuid;
  actor_user_id uuid;
  old_lead jsonb;
  new_lead jsonb;
  effect_response jsonb := '{}'::jsonb;
begin
  select e.lead_id, fv.created_by, to_jsonb(l)
  into target_lead_id, actor_user_id, old_lead
  from public.automation_executions e
  join public.automation_flow_versions fv on fv.id = e.flow_version_id
  join public.leads l on l.id = e.lead_id and l.organization_id = e.organization_id
  join public.organization_modules om
    on om.organization_id = e.organization_id
   and lower(trim(om.module_name)) = 'automations'
   and coalesce(om.is_enabled, false) = true
  where e.id = p_execution_id
    and e.organization_id = p_organization_id
    and e.current_node_key = p_node_key
    and e.locked_by = p_lease_token
    and e.status = 'running'
    and e.cancellation_requested_at is null
  for update of e, l;

  if target_lead_id is null then
    return jsonb_build_object('ok', false, 'status', 'execution_not_running');
  end if;

  perform pg_catalog.set_config('vimob.automation_execution_id', p_execution_id::text, true);

  insert into public.automation_effect_dispatches (
    organization_id, execution_id, node_key, effect_key, effect_type, status, request
  ) values (
    p_organization_id, p_execution_id, p_node_key, p_effect_key, p_effect_type,
    'sending', coalesce(p_payload, '{}'::jsonb)
  ) on conflict (effect_key) do nothing
  returning id into effect_id;

  if effect_id is null then
    select status, response into target_status, effect_response
    from public.automation_effect_dispatches where effect_key = p_effect_key;
    return jsonb_build_object(
      'ok', target_status = 'succeeded',
      'status', coalesce(target_status, 'missing'),
      'response', coalesce(effect_response, '{}'::jsonb)
    );
  end if;

  begin
    case p_effect_type
      when 'add_tag' then
        target_uuid := nullif(p_payload->>'tag_id', '')::uuid;
        if not exists (
          select 1 from public.tags t
          where t.id = target_uuid and t.organization_id = p_organization_id
        ) then
          raise exception 'Tag does not belong to the organization.';
        end if;
        insert into public.lead_tags(organization_id, lead_id, tag_id)
        values (p_organization_id, target_lead_id, target_uuid)
        on conflict (lead_id, tag_id) do nothing;
      when 'remove_tag' then
        target_uuid := nullif(p_payload->>'tag_id', '')::uuid;
        delete from public.lead_tags
        where organization_id = p_organization_id
          and lead_id = target_lead_id
          and tag_id = target_uuid;
      when 'move_lead' then
        target_uuid := nullif(p_payload->>'stage_id', '')::uuid;
        target_pipeline_id := nullif(p_payload->>'pipeline_id', '')::uuid;
        effect_response := private.automation_move_lead_stage(
          p_organization_id, target_lead_id, target_uuid, target_pipeline_id
        );
      when 'assign_user' then
        target_uuid := nullif(p_payload->>'user_id', '')::uuid;
        effect_response := private.automation_assign_lead_user(
          p_organization_id, target_lead_id, target_uuid, actor_user_id,
          p_execution_id, p_node_key
        );
      when 'property_interest' then
        raise exception 'property_interest_requires_canonical_lead_command_service';
      when 'deal_status' then
        raise exception 'deal_status_requires_canonical_lead_service';
      else
        raise exception 'Unsupported internal automation effect.';
    end case;

    select to_jsonb(l) into new_lead
    from public.leads l
    where l.id = target_lead_id and l.organization_id = p_organization_id;

    insert into public.audit_logs (
      organization_id, user_id, action, entity_type, entity_id, old_data, new_data
    ) values (
      p_organization_id, actor_user_id, 'automation_' || p_effect_type,
      'lead', target_lead_id::text,
      jsonb_build_object(
        'stage_id', old_lead->'stage_id', 'pipeline_id', old_lead->'pipeline_id',
        'assigned_user_id', old_lead->'assigned_user_id',
        'interest_property_id', old_lead->'interest_property_id', 'deal_status', old_lead->'deal_status'
      ),
      jsonb_build_object(
        'stage_id', new_lead->'stage_id', 'pipeline_id', new_lead->'pipeline_id',
        'assigned_user_id', new_lead->'assigned_user_id',
        'interest_property_id', new_lead->'interest_property_id', 'deal_status', new_lead->'deal_status',
        'origin', 'automation', 'execution_id', p_execution_id,
        'node_key', p_node_key, 'effect_key', p_effect_key
      )
    );

    insert into public.activities (
      organization_id, lead_id, user_id, type, content, metadata
    ) values (
      p_organization_id, target_lead_id, actor_user_id,
      'automation_' || p_effect_type,
      'Acao executada pela automacao: ' || p_effect_type,
      jsonb_build_object(
        'origin', 'automation', 'execution_id', p_execution_id,
        'node_key', p_node_key, 'effect_key', p_effect_key
      ) || coalesce(effect_response, '{}'::jsonb)
    );

    update public.automation_effect_dispatches
    set status = 'succeeded', response = coalesce(effect_response, '{}'::jsonb), completed_at = now()
    where id = effect_id;

    return jsonb_build_object(
      'ok', true, 'status', 'succeeded', 'effect_id', effect_id,
      'response', coalesce(effect_response, '{}'::jsonb)
    );
  exception when others then
    update public.automation_effect_dispatches
    set status = 'failed', completed_at = now(), error_message = left(sqlerrm, 4000)
    where id = effect_id;
    return jsonb_build_object(
      'ok', false, 'status', 'failed', 'error', sqlerrm, 'effect_id', effect_id
    );
  end;
end;
$$;


ALTER FUNCTION public.apply_automation_internal_effect(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_effect_key text, p_effect_type text, p_payload jsonb) OWNER TO postgres;

--
-- Name: apply_whatsapp_provider_reaction(uuid, uuid, text, text, text, text, boolean, text, timestamp with time zone, text, integer, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_whatsapp_provider_reaction(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_target_provider_message_id text, p_actor_jid text, p_actor_name text, p_from_me boolean, p_emoji text, p_reacted_at timestamp with time zone, p_inbox_event_key text, p_processing_epoch integer, p_ingress_sequence bigint, p_execution_id uuid DEFAULT NULL::uuid, p_native_worker_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_targets uuid[]; v_events uuid[]; v_target public.whatsapp_messages%rowtype;
 v_existing public.whatsapp_messages%rowtype; v_conversation public.whatsapp_conversations%rowtype;
 v_route public.whatsapp_webhook_routing_snapshots%rowtype; v_inbox public.whatsapp_webhook_inbox%rowtype;
 v_binding uuid; v_capture text; v_message_id uuid; v_actor text:=btrim(p_actor_jid);
 v_emoji text:=nullif(p_emoji,''); v_phone text; v_epoch integer;
begin
  if p_organization_id is null or p_session_id is null or nullif(btrim(p_provider_message_id),'') is null
    or nullif(btrim(p_target_provider_message_id),'') is null or nullif(v_actor,'') is null
    or length(v_actor)>320 or length(coalesce(v_emoji,''))>64 or p_from_me is null or p_reacted_at is null then
    raise exception using errcode='22023',message='whatsapp_reaction_argument_invalid';
  end if;
  select regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') into v_phone
  from public.whatsapp_sessions where organization_id=p_organization_id and id=p_session_id
    and provider='evolution_go' and coalesce(is_active,true) and status not in ('disabled','deleted') for share;
  if not found then raise exception using errcode='23503',message='whatsapp_reaction_session_missing'; end if;
  if p_from_me then
    if v_phone ~ '^[0-9]{5,15}$' then v_actor:=v_phone||'@s.whatsapp.net';
    elsif v_actor !~ '^[0-9]{5,15}@s[.]whatsapp[.]net$' then
      raise exception using errcode='23514',message='whatsapp_reaction_self_identity_missing';
    end if;
  end if;
  select array_agg(id order by id) into v_targets from (
    select id from public.whatsapp_messages where organization_id=p_organization_id and session_id=p_session_id
      and (provider_message_id=p_target_provider_message_id or message_id=p_target_provider_message_id or client_message_id=p_target_provider_message_id)
    order by id limit 2
  ) targets;
  if coalesce(cardinality(v_targets),0)=0 then
    raise exception using errcode='40001',message='whatsapp_reaction_target_pending';
  end if;
  if cardinality(v_targets)<>1 then
    raise exception using errcode='23514',message='whatsapp_reaction_target_identity_conflict';
  end if;
  select * into v_target from public.whatsapp_messages where id=v_targets[1];
  select * into v_conversation from public.whatsapp_conversations
    where organization_id=p_organization_id and session_id=p_session_id and id=v_target.conversation_id for update;
  if not found then raise exception using errcode='23503',message='whatsapp_reaction_conversation_missing'; end if;
  select * into v_target from public.whatsapp_messages where id=v_targets[1] for update;
  if coalesce(nullif(v_target.provider_message_id,''),v_target.message_id)<>p_target_provider_message_id then
    raise exception using errcode='23514',message='whatsapp_reaction_target_identity_conflict';
  end if;
  if v_target.capture_state='suppressed' or v_target.message_type in ('reaction','system','deleted')
    or v_target.unlinked_retention_scrubbed_at is not null
    or v_conversation.retired_at is not null or v_conversation.deleted_at is not null
    or (v_target.capture_state='unlinked_ephemeral' and v_conversation.created_at<=clock_timestamp()-interval '7 days') then
    return jsonb_build_object('outcome','ignored','reason','target_unavailable');
  end if;
  select array_agg(id order by id) into v_events from (
    select id from public.whatsapp_messages where organization_id=p_organization_id and session_id=p_session_id
      and (provider_message_id=p_provider_message_id or message_id=p_provider_message_id or client_message_id=p_provider_message_id)
    order by id limit 2
  ) events;
  if coalesce(cardinality(v_events),0)>1 then
    raise exception using errcode='23514',message='whatsapp_reaction_event_identity_conflict';
  end if;
  if coalesce(cardinality(v_events),0)=1 then
    select * into v_existing from public.whatsapp_messages where id=v_events[1] for update;
    if v_existing.message_type<>'reaction' or v_existing.reaction_to_message_id<>p_target_provider_message_id
      or v_existing.conversation_id is distinct from v_target.conversation_id
      or v_existing.lead_id is distinct from v_target.lead_id or v_existing.from_me is distinct from p_from_me
      or v_existing.reaction_emoji is distinct from v_emoji or v_existing.reaction_sender_jid is distinct from v_actor
      or v_existing.capture_state is distinct from coalesce(nullif(v_target.capture_state,'legacy'),'captured') then
      raise exception using errcode='23514',message='whatsapp_reaction_event_identity_conflict';
    end if;
    return jsonb_build_object('outcome','duplicate','message_id',v_existing.id);
  end if;
  select * into v_route from public.whatsapp_webhook_routing_snapshots
    where organization_id=p_organization_id and session_id=p_session_id and provider_message_id=p_provider_message_id;
  select coalesce((select active_epoch from private.whatsapp_webhook_session_cutovers where session_id=p_session_id),0) into v_epoch;
  if v_route.provider_message_id is null or v_route.inbox_event_key is distinct from p_inbox_event_key
    or v_route.processing_epoch is distinct from p_processing_epoch or v_epoch is distinct from p_processing_epoch
    or v_route.ingress_sequence is distinct from p_ingress_sequence
    or coalesce(v_route.snapshot->>'processing_epoch','0')<>p_processing_epoch::text
    or v_route.snapshot->>'conversation_id' is distinct from v_target.conversation_id::text
    or v_route.snapshot->>'context_kind' is distinct from 'organic'
    or coalesce(v_route.snapshot->>'state','') in ('quarantine','provider_replay','contextual_intake','predecessor_inherit') then
    raise exception using errcode='23514',message='whatsapp_reaction_ingress_provenance_invalid';
  end if;
  select * into v_inbox from public.whatsapp_webhook_inbox where organization_id=p_organization_id
    and session_id=p_session_id and event_key=p_inbox_event_key and processing_epoch=p_processing_epoch for share;
  if not found or v_inbox.status<>'processing' or v_inbox.expires_at<=clock_timestamp()
    or v_inbox.locked_at is null or nullif(v_inbox.locked_by,'') is null
    or v_inbox.locked_at<=clock_timestamp()-interval '5 minutes'
    or not coalesce((
      (p_processing_epoch=0 and v_inbox.edge_execution_state='active'
        and p_execution_id is not null and v_inbox.edge_execution_id=p_execution_id
        and p_native_worker_id is null)
      or
      (p_processing_epoch in (0,1) and p_execution_id is null
        and v_inbox.edge_execution_id is null and v_inbox.edge_execution_state is null
        and p_native_worker_id is not null and v_inbox.locked_by=p_native_worker_id
        and p_native_worker_id like 'vimob-api-evolution-webhook-epoch1-%')
    ),false) then
    raise exception using errcode='23514',message='whatsapp_reaction_execution_provenance_invalid';
  end if;
  if v_target.lead_id is distinct from v_conversation.lead_id then
    return jsonb_build_object('outcome','ignored','reason','target_binding_changed');
  end if;
  if v_target.lead_id is null then
    if v_target.capture_state is distinct from 'unlinked_ephemeral' or v_route.snapshot->>'state' is distinct from 'unlinked'
      or v_route.snapshot->>'current_lead_id' is not null or v_route.snapshot->>'event_lead_id' is not null
      or v_route.snapshot->>'active_binding_id' is not null then
      return jsonb_build_object('outcome','ignored','reason','target_binding_changed');
    end if;
  else
    select id into v_binding from public.whatsapp_conversation_lead_bindings where organization_id=p_organization_id
      and conversation_id=v_conversation.id and session_id=p_session_id and lead_id=v_target.lead_id
      and active_to is null and not stale for share;
    if not found or v_route.snapshot->>'active_binding_id' is distinct from v_binding::text
      or coalesce(v_route.snapshot->>'event_lead_id',v_route.snapshot->>'current_lead_id') is distinct from v_target.lead_id::text then
      return jsonb_build_object('outcome','ignored','reason','target_binding_changed');
    end if;
  end if;
  v_capture:=coalesce(nullif(v_target.capture_state,'legacy'),'captured');
  if v_capture not in ('captured','observed_unattended','unlinked_ephemeral','promoted_unlinked') then
    raise exception using errcode='23514',message='whatsapp_reaction_capture_invalid';
  end if;
  perform pg_catalog.set_config('vimob.whatsapp_reaction_target_id',v_target.id::text,true);
  insert into public.whatsapp_messages (organization_id,conversation_id,session_id,lead_id,
    provider_message_id,message_id,from_me,direction,content,message_type,reaction_to_message_id,
    reaction_emoji,reaction_sender_jid,reaction_sender_name,remote_jid,sender_jid,sender_name,
    status,sent_at,received_at,metadata,capture_state)
  values(p_organization_id,v_target.conversation_id,p_session_id,v_target.lead_id,p_provider_message_id,p_provider_message_id,
    p_from_me,case when p_from_me then 'outbound' else 'inbound' end,v_emoji,'reaction',p_target_provider_message_id,
    v_emoji,v_actor,nullif(p_actor_name,''),v_target.remote_jid,v_actor,nullif(p_actor_name,''),
    case when p_from_me then 'sent' else 'received' end,p_reacted_at,v_inbox.created_at,
    jsonb_build_object('source','evolution_go_provider_reaction',
      'whatsapp_provider_reaction',jsonb_build_object('target_message_id',v_target.id,'ingress_sequence',v_route.ingress_sequence,'processing_epoch',v_route.processing_epoch),
      'evolution_go_webhook_effects',jsonb_build_object('version',1,'state','completed','provider_message_id',p_provider_message_id,'completed_at',clock_timestamp())),v_capture)
  returning id into v_message_id;
  insert into public.whatsapp_message_reactions (organization_id,session_id,conversation_id,target_message_id,
    target_provider_message_id,provider_reaction_message_id,actor_jid,actor_name,from_me,emoji,status,reacted_at,removed_at,provider_ingress_sequence)
  values(p_organization_id,p_session_id,v_target.conversation_id,v_target.id,p_target_provider_message_id,p_provider_message_id,
    v_actor,nullif(p_actor_name,''),p_from_me,v_emoji,case when v_emoji is null then 'removed' else 'active' end,
    p_reacted_at,case when v_emoji is null then p_reacted_at else null end,v_route.ingress_sequence)
  on conflict(organization_id,session_id,target_provider_message_id,actor_jid) do update set
    provider_reaction_message_id=excluded.provider_reaction_message_id,actor_name=coalesce(excluded.actor_name,whatsapp_message_reactions.actor_name),
    from_me=excluded.from_me,emoji=excluded.emoji,status=excluded.status,reacted_at=excluded.reacted_at,removed_at=excluded.removed_at,
    provider_ingress_sequence=excluded.provider_ingress_sequence,updated_at=now()
  where excluded.reacted_at>whatsapp_message_reactions.reacted_at or
    (excluded.reacted_at=whatsapp_message_reactions.reacted_at and excluded.provider_ingress_sequence>coalesce(whatsapp_message_reactions.provider_ingress_sequence,0));
  return jsonb_build_object('outcome','applied','message_id',v_message_id,'capture_state',v_capture,'lead_id',v_target.lead_id);
end;
$_$;


ALTER FUNCTION public.apply_whatsapp_provider_reaction(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_target_provider_message_id text, p_actor_jid text, p_actor_name text, p_from_me boolean, p_emoji text, p_reacted_at timestamp with time zone, p_inbox_event_key text, p_processing_epoch integer, p_ingress_sequence bigint, p_execution_id uuid, p_native_worker_id text) OWNER TO postgres;

--
-- Name: assign_neximob_lancamentos_webhook_lead(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_neximob_lancamentos_webhook_lead() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ declare v_org uuid := '2304ab86-4731-4e6e-9894-66e2bf953d9c'::uuid; v_webhook uuid := 'a59ef2cb-3fa6-40af-8d85-acf4e9ac19a9'::uuid; v_user uuid := 'd32c68bc-f6c5-4b53-924d-c728268b7a28'::uuid; v_round_robin uuid := 'b486d1e7-3019-46c1-aca4-8d17248b2372'::uuid; begin if NEW.organization_id = v_org and NEW.source_webhook_id = v_webhook and NEW.assigned_user_id is null then NEW.assigned_user_id := v_user; NEW.metadata := coalesce(NEW.metadata, '{}'::jsonb) || jsonb_build_object('assigned_by','neximob_webhook_round_robin','round_robin_id',v_round_robin::text); end if; return NEW; end $$;


ALTER FUNCTION public.assign_neximob_lancamentos_webhook_lead() OWNER TO postgres;

--
-- Name: auto_enter_whatsapp_ctwa_attendance(uuid, uuid, uuid, uuid, uuid, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_enter_whatsapp_ctwa_attendance(p_organization_id uuid, p_conversation_id uuid, p_session_id uuid, p_lead_id uuid, p_binding_id uuid, p_provider_message_id text, p_ingress_sequence bigint, p_provider_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner_user_id uuid;
  v_actor_name text;
  v_inbox_created_at timestamp with time zone;
  v_entry_id uuid;
  v_joined_at timestamp with time zone;
begin
  if p_organization_id is null
     or p_conversation_id is null
     or p_session_id is null
     or p_lead_id is null
     or p_binding_id is null
     or btrim(coalesce(p_provider_message_id, '')) = ''
     or p_ingress_sequence is null
     or p_ingress_sequence <= 0
     or p_provider_occurred_at is null then
    return null;
  end if;

  select origin.owner_user_id,
         left(coalesce(
           nullif(btrim(actor.name), ''),
           nullif(btrim(actor.email), ''),
           'Usuario'
         ), 180),
         inbox.created_at
  into v_owner_user_id, v_actor_name, v_inbox_created_at
  from private.whatsapp_ctwa_auto_origins as origin
  join public.leads as lead
    on lead.id = origin.lead_id
   and lead.organization_id = origin.organization_id
   and lead.source_session_id = origin.session_id
  join public.whatsapp_sessions as session
    on session.id = origin.session_id
   and session.organization_id = origin.organization_id
   and session.owner_user_id = origin.owner_user_id
   and session.provider = 'evolution_go'
   and session.status not in ('disabled', 'deleted')
   and coalesce(session.is_active, true) = true
  join public.users as actor
    on actor.id = origin.owner_user_id
   and actor.organization_id = origin.organization_id
   and coalesce(actor.is_active, false) = true
  join public.organization_members as member
    on member.organization_id = origin.organization_id
   and member.user_id = origin.owner_user_id
   and coalesce(member.is_active, true) = true
  join public.whatsapp_conversations as conversation
    on conversation.id = p_conversation_id
   and conversation.organization_id = origin.organization_id
   and conversation.session_id = origin.session_id
   and conversation.lead_id = origin.lead_id
   and conversation.deleted_at is null
  join public.whatsapp_conversation_lead_bindings as binding
    on binding.id = p_binding_id
   and binding.organization_id = origin.organization_id
   and binding.conversation_id = conversation.id
   and binding.session_id = origin.session_id
   and binding.lead_id = origin.lead_id
   and binding.provider_message_id = origin.provider_message_id
   and binding.active_to is null
   and binding.stale = false
  join public.whatsapp_webhook_routing_snapshots as route
    on route.organization_id = origin.organization_id
   and route.session_id = origin.session_id
   and route.provider_message_id = origin.provider_message_id
   and route.ingress_sequence = p_ingress_sequence
   and route.binding_eligible = true
   and route.snapshot->>'context_kind' = 'contextual_intake'
  join public.whatsapp_webhook_inbox as inbox
    on inbox.organization_id = route.organization_id
   and inbox.session_id = route.session_id
   and inbox.event_key = route.inbox_event_key
  where origin.organization_id = p_organization_id
    and origin.auto_entry_eligible = true
    and origin.session_id = p_session_id
    and origin.lead_id = p_lead_id
    and origin.provider_message_id = btrim(p_provider_message_id)
    and origin.provider_event_id = p_session_id::text || ':' || btrim(p_provider_message_id)
    and lead.metadata->>'whatsapp_initial_provider_event_id' = origin.provider_event_id
    and lead.metadata->>'whatsapp_lead_creation_contract' = 'ctwa_ad_v2'
    and lead.metadata->>'ctwa_ad_confirmed' = 'true'
    and p_provider_occurred_at <= inbox.created_at;

  if v_owner_user_id is null then
    return null;
  end if;

  insert into public.whatsapp_attendance_entries (
    organization_id,
    conversation_id,
    session_id,
    lead_id,
    binding_id,
    user_id,
    actor_name_snapshot,
    joined_at,
    ingress_sequence_cutoff,
    entry_source,
    bootstrap_provider_message_id,
    bootstrap_ingress_sequence,
    bootstrap_provider_occurred_at,
    bootstrap_inbox_created_at
  ) values (
    p_organization_id,
    p_conversation_id,
    p_session_id,
    p_lead_id,
    p_binding_id,
    v_owner_user_id,
    v_actor_name,
    clock_timestamp(),
    p_ingress_sequence,
    'ctwa_auto',
    btrim(p_provider_message_id),
    p_ingress_sequence,
    p_provider_occurred_at,
    v_inbox_created_at
  )
  on conflict on constraint whatsapp_attendance_entries_identity_key
    do nothing
  returning id, joined_at into v_entry_id, v_joined_at;

  if v_entry_id is null then
    select entry.id
    into v_entry_id
    from public.whatsapp_attendance_entries as entry
    where entry.organization_id = p_organization_id
      and entry.conversation_id = p_conversation_id
      and entry.session_id = p_session_id
      and entry.lead_id = p_lead_id
      and entry.binding_id = p_binding_id
      and entry.user_id = v_owner_user_id
      and entry.entry_source = 'ctwa_auto'
      and entry.bootstrap_provider_message_id = btrim(p_provider_message_id)
      and entry.bootstrap_ingress_sequence = p_ingress_sequence
      and entry.bootstrap_provider_occurred_at = p_provider_occurred_at
      and entry.bootstrap_inbox_created_at = v_inbox_created_at;
    return v_entry_id;
  end if;

  insert into public.lead_timeline_events (
    organization_id,
    lead_id,
    user_id,
    actor_user_id,
    event_type,
    title,
    description,
    event_at,
    metadata
  ) values (
    p_organization_id,
    p_lead_id,
    v_owner_user_id,
    v_owner_user_id,
    'whatsapp_attendance_joined',
    v_actor_name || ' entrou no atendimento',
    'Atendimento iniciado automaticamente pelo WhatsApp que recebeu o lead.',
    v_joined_at,
    pg_catalog.jsonb_build_object(
      'attendance_entry_id', v_entry_id,
      'conversation_id', p_conversation_id,
      'session_id', p_session_id,
      'binding_id', p_binding_id,
      'ingress_sequence_cutoff', p_ingress_sequence,
      'entry_source', 'ctwa_auto'
    )
  );

  return v_entry_id;
end;
$$;


ALTER FUNCTION public.auto_enter_whatsapp_ctwa_attendance(p_organization_id uuid, p_conversation_id uuid, p_session_id uuid, p_lead_id uuid, p_binding_id uuid, p_provider_message_id text, p_ingress_sequence bigint, p_provider_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION auto_enter_whatsapp_ctwa_attendance(p_organization_id uuid, p_conversation_id uuid, p_session_id uuid, p_lead_id uuid, p_binding_id uuid, p_provider_message_id text, p_ingress_sequence bigint, p_provider_occurred_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.auto_enter_whatsapp_ctwa_attendance(p_organization_id uuid, p_conversation_id uuid, p_session_id uuid, p_lead_id uuid, p_binding_id uuid, p_provider_message_id text, p_ingress_sequence bigint, p_provider_occurred_at timestamp with time zone) IS 'Atomically and idempotently auto-enters the receiving WhatsApp owner only for the proven first inbound event of a newly inserted CTWA lead/card.';


