--
-- Name: cancel_automations_on_stage_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_automations_on_stage_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.stage_id is distinct from old.stage_id then
    update public.automation_executions ae
       set status = 'cancelled',
           completed_at = now(),
           next_execution_at = null,
           error_message = 'Cancelado: lead mudou de estágio'
      from public.automations a
     where a.id = ae.automation_id
       and ae.lead_id = new.id
       and ae.status in ('running', 'waiting')
       and coalesce((a.trigger_config ->> 'cancel_on_stage_change')::boolean, false) = true;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.cancel_automations_on_stage_change() OWNER TO postgres;

--
-- Name: cancel_billing_checkout_intent(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_billing_checkout_intent(p_organization_id uuid, p_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment_id text := nullif(btrim(coalesce(p_payment_id, '')), '');
  v_payment_status text;
  v_updated integer := 0;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  if p_organization_id is null or v_payment_id is null then
    raise exception 'invalid billing cancellation request'
      using errcode = '22023';
  end if;

  select upper(btrim(coalesce(status, '')))
  into v_payment_status
  from public.asaas_payments
  where organization_id = p_organization_id
    and asaas_payment_id = v_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  if v_payment_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH') then
    return jsonb_build_object('outcome', 'already_paid');
  end if;

  update private.billing_checkout_intents
  set
    status = 'cancelled',
    cancelled_at = coalesce(cancelled_at, now()),
    last_error = 'payment_cancelled',
    updated_at = now()
  where organization_id = p_organization_id
    and provider_payment_id = v_payment_id
    and billing_method in ('PIX', 'BOLETO')
    and status in ('creating', 'pending');

  get diagnostics v_updated = row_count;

  update public.asaas_payments
  set
    status = 'CANCELED',
    raw_event = coalesce(raw_event, '{}'::jsonb) || jsonb_build_object(
      'local_cancellation',
      jsonb_build_object(
        'source', 'checkout',
        'recorded_at', now()
      )
    ),
    updated_at = now()
  where organization_id = p_organization_id
    and asaas_payment_id = v_payment_id
    and upper(btrim(coalesce(status, '')))
      not in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH');

  return jsonb_build_object(
    'outcome',
    case
      when v_updated = 1 then 'cancelled'
      when v_payment_status in ('CANCELED', 'CANCELLED', 'DELETED')
        then 'already_cancelled'
      else 'unchanged'
    end
  );
end;
$$;


ALTER FUNCTION public.cancel_billing_checkout_intent(p_organization_id uuid, p_payment_id text) OWNER TO postgres;

--
-- Name: cancel_billing_checkout_resource(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_billing_checkout_resource(p_organization_id uuid, p_intent_id uuid, p_payment_id text, p_subscription_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_intent private.billing_checkout_intents%rowtype;
  v_payment_id text := nullif(btrim(coalesce(p_payment_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_subscription_id, '')), '');
  v_has_paid_payment boolean := false;
  v_grace_until timestamptz;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  if p_organization_id is null or p_intent_id is null then
    raise exception 'invalid billing cancellation request'
      using errcode = '22023';
  end if;

  select intent.*
  into v_intent
  from private.billing_checkout_intents intent
  where intent.id = p_intent_id
    and intent.organization_id = p_organization_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  if v_payment_id is not null
    and v_intent.provider_payment_id is distinct from v_payment_id
    and not exists (
      select 1
      from public.asaas_payments payment
      where payment.organization_id = p_organization_id
        and payment.billing_intent_id = p_intent_id
        and payment.asaas_payment_id = v_payment_id
    ) then
    raise exception 'payment does not belong to billing intent'
      using errcode = '22023';
  end if;

  if v_subscription_id is not null
    and v_intent.provider_subscription_id is distinct from v_subscription_id then
    raise exception 'subscription does not belong to billing intent'
      using errcode = '22023';
  end if;

  if v_intent.status = 'confirmed' then
    return jsonb_build_object('outcome', 'already_paid');
  end if;

  select exists (
    select 1
    from public.asaas_payments payment
    where payment.organization_id = p_organization_id
      and payment.billing_intent_id = p_intent_id
      and upper(btrim(coalesce(payment.status, ''))) in (
        'CONFIRMED',
        'RECEIVED',
        'RECEIVED_IN_CASH'
      )
  )
  into v_has_paid_payment;

  if v_has_paid_payment then
    return jsonb_build_object('outcome', 'already_paid');
  end if;

  if v_intent.status in ('cancelled', 'failed') then
    return jsonb_build_object(
      'outcome',
      case when v_intent.status = 'cancelled'
        then 'already_cancelled'
        else 'already_failed'
      end,
      'payment_id', v_intent.provider_payment_id,
      'subscription_id', v_intent.provider_subscription_id
    );
  end if;

  if v_payment_id is null
     and v_subscription_id is null
     and (
       v_intent.provider_payment_id is not null
       or v_intent.provider_subscription_id is not null
       or v_intent.provider_checkout_id is not null
     ) then
    return jsonb_build_object(
      'outcome', 'resource_registered',
      'payment_id', v_intent.provider_payment_id,
      'subscription_id', v_intent.provider_subscription_id,
      'checkout_id', v_intent.provider_checkout_id
    );
  end if;

  -- A creating intent with no recorded Asaas resource can represent an HTTP
  -- timeout after Asaas accepted the request. Edge performs one final lookup by
  -- externalReference before calling this function. The row lock plus these
  -- predicates ensure that a concurrent provider registration wins the race.
  if v_intent.status = 'creating'
     and v_intent.provider_payment_id is null
     and v_intent.provider_subscription_id is null
     and v_intent.provider_checkout_id is null then
    v_grace_until := coalesce(
      v_intent.provider_request_started_at,
      v_intent.created_at
    ) + interval '5 minutes';

    if now() < v_grace_until then
      return jsonb_build_object(
        'outcome', 'retry_later',
        'retry_after_at', v_grace_until,
        'retry_after_seconds', greatest(
          1,
          ceil(extract(epoch from (v_grace_until - now())))::integer
        )
      );
    end if;
  end if;

  update private.billing_checkout_intents
  set
    status = 'cancelled',
    cancelled_at = coalesce(cancelled_at, now()),
    last_error = 'checkout_cancelled',
    updated_at = now()
  where id = p_intent_id
    and organization_id = p_organization_id
    and status in ('creating', 'pending')
    and (
      v_intent.status <> 'creating'
      or v_intent.provider_payment_id is not null
      or v_intent.provider_subscription_id is not null
      or v_intent.provider_checkout_id is not null
      or (
        provider_payment_id is null
        and provider_subscription_id is null
        and provider_checkout_id is null
        and coalesce(provider_request_started_at, created_at)
          <= now() - interval '5 minutes'
      )
    );

  if not found then
    return jsonb_build_object('outcome', 'retry_later');
  end if;

  update public.asaas_payments
  set
    status = 'CANCELED',
    raw_event = coalesce(raw_event, '{}'::jsonb) || jsonb_build_object(
      'local_cancellation',
      jsonb_build_object(
        'source', 'checkout_recovery',
        'recorded_at', now()
      )
    ),
    updated_at = now()
  where organization_id = p_organization_id
    and billing_intent_id = p_intent_id
    and upper(btrim(coalesce(status, ''))) not in (
      'CONFIRMED',
      'RECEIVED',
      'RECEIVED_IN_CASH'
    );

  update public.organizations
  set
    asaas_subscription_id = null,
    updated_at = now()
  where id = p_organization_id
    and v_intent.provider_subscription_id is not null
    and asaas_subscription_id = v_intent.provider_subscription_id
    and subscription_status is distinct from 'active';

  return jsonb_build_object(
    'outcome', 'cancelled',
    'payment_id', v_intent.provider_payment_id,
    'subscription_id', v_intent.provider_subscription_id
  );
end;
$$;


ALTER FUNCTION public.cancel_billing_checkout_resource(p_organization_id uuid, p_intent_id uuid, p_payment_id text, p_subscription_id text) OWNER TO postgres;

--
-- Name: FUNCTION cancel_billing_checkout_resource(p_organization_id uuid, p_intent_id uuid, p_payment_id text, p_subscription_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cancel_billing_checkout_resource(p_organization_id uuid, p_intent_id uuid, p_payment_id text, p_subscription_id text) IS 'Closes an unconfirmed billing intent. Provider-less creating intents remain locked for five minutes and must be externally recovered before this guarded RPC is called.';


--
-- Name: cancel_disabled_automation_runtime(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_disabled_automation_runtime(p_batch_size integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  execution_count integer := 0;
  event_count integer := 0;
  closed_step_count integer := 0;
begin
  with candidates as (
    select e.id
    from public.automation_executions e
    where e.status in ('queued', 'running', 'waiting')
      and not exists (
        select 1 from public.organization_modules om
        where om.organization_id = e.organization_id
          and lower(trim(om.module_name)) = 'automations'
          and coalesce(om.is_enabled, false) = true
      )
    order by e.started_at, e.id
    limit least(greatest(coalesce(p_batch_size, 100), 1), 500)
    for update skip locked
  )
  , cancelled as (
    update public.automation_executions e
    set status = 'cancelled',
        cancellation_requested_at = now(),
        completed_at = now(),
        error_message = 'module_disabled',
        locked_at = null,
        locked_by = null,
        updated_at = now()
    from candidates c
    where e.id = c.id
    returning e.id
  ), closed_steps as (
    update public.automation_execution_steps s
    set status = 'cancelled', completed_at = now(), error_message = 'module_disabled'
    where s.execution_id in (select id from cancelled)
      and s.status in ('running', 'waiting')
    returning s.id
  )
  select
    (select count(*) from cancelled),
    (select count(*) from closed_steps)
  into execution_count, closed_step_count;

  with candidates as (
    select o.id
    from public.automation_event_outbox o
    where o.status in ('pending', 'failed', 'processing')
      and not exists (
        select 1 from public.organization_modules om
        where om.organization_id = o.organization_id
          and lower(trim(om.module_name)) = 'automations'
          and coalesce(om.is_enabled, false) = true
      )
    order by o.created_at, o.id
    limit least(greatest(coalesce(p_batch_size, 100), 1), 500)
    for update skip locked
  )
  update public.automation_event_outbox o
  set status = 'dead_letter',
      dead_lettered_at = now(),
      last_error = 'module_disabled',
      locked_at = null,
      locked_by = null,
      updated_at = now()
  from candidates c
  where o.id = c.id;
  get diagnostics event_count = row_count;

  return jsonb_build_object(
    'executions_cancelled', execution_count,
    'steps_cancelled', closed_step_count,
    'events_dead_lettered', event_count
  );
end;
$$;


ALTER FUNCTION public.cancel_disabled_automation_runtime(p_batch_size integer) OWNER TO postgres;

--
-- Name: cancel_whatsapp_webhook_edge_execution(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_whatsapp_webhook_edge_execution(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_organization_id is null or p_session_id is null or p_inbox_id is null
    or p_execution_id is null
  then
    return false;
  end if;
  update public.whatsapp_webhook_inbox as inbox
  set edge_execution_id = null,
      edge_execution_state = null,
      edge_execution_reserved_at = null,
      edge_execution_started_at = null,
      updated_at = now()
  where inbox.id = p_inbox_id
    and inbox.organization_id = p_organization_id
    and inbox.session_id = p_session_id
    and inbox.processing_epoch = 0
    and inbox.edge_execution_id = p_execution_id
    and inbox.edge_execution_state = 'reserved';
  return found;
end;
$$;


ALTER FUNCTION public.cancel_whatsapp_webhook_edge_execution(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid) OWNER TO postgres;

--
-- Name: check_edge_rate_limit(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_edge_rate_limit(p_scope text, p_identifier_hash text, p_limit integer, p_window_seconds integer) RETURNS TABLE(allowed boolean, remaining integer, retry_after_seconds integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_window_start timestamptz;
  v_count integer;
  v_retry_after integer;
begin
  if p_scope is null or length(trim(p_scope)) = 0 then
    raise exception 'p_scope is required';
  end if;

  if p_identifier_hash is null or length(trim(p_identifier_hash)) = 0 then
    raise exception 'p_identifier_hash is required';
  end if;

  if p_limit <= 0 or p_window_seconds <= 0 then
    raise exception 'p_limit and p_window_seconds must be positive';
  end if;

  v_window_start := to_timestamp(
    floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds
  );

  insert into public.edge_rate_limits (
    scope,
    identifier_hash,
    window_start,
    window_seconds,
    request_count
  )
  values (
    p_scope,
    p_identifier_hash,
    v_window_start,
    p_window_seconds,
    1
  )
  on conflict (scope, identifier_hash, window_start)
  do update set
    request_count = public.edge_rate_limits.request_count + 1,
    updated_at = now()
  returning request_count into v_count;

  v_retry_after := greatest(
    1,
    ceil(extract(epoch from (v_window_start + (p_window_seconds * interval '1 second') - now())))::integer
  );

  return query
  select
    v_count <= p_limit,
    greatest(p_limit - v_count, 0),
    case when v_count > p_limit then v_retry_after else 0 end;
end;
$$;


ALTER FUNCTION public.check_edge_rate_limit(p_scope text, p_identifier_hash text, p_limit integer, p_window_seconds integer) OWNER TO postgres;

--
-- Name: check_ranking_overtake(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_ranking_overtake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_overtaken_user_id UUID;
    v_overtaker_name TEXT;
    v_overtaken_name TEXT;
BEGIN
    IF NEW.total_points > OLD.total_points THEN
        -- Busca quem estava na frente e agora ficou atrás
        SELECT user_id INTO v_overtaken_user_id
        FROM public.user_gamification_stats
        WHERE organization_id = NEW.organization_id
          AND total_points >= OLD.total_points
          AND total_points < NEW.total_points
          AND user_id != NEW.user_id
        ORDER BY total_points DESC LIMIT 1;

        IF v_overtaken_user_id IS NOT NULL THEN
            SELECT name INTO v_overtaker_name FROM public.users WHERE id = NEW.user_id;
            SELECT name INTO v_overtaken_name FROM public.users WHERE id = v_overtaken_user_id;

            -- Notifica quem caiu
            INSERT INTO public.notifications (user_id, organization_id, title, content, type)
            VALUES (v_overtaken_user_id, NEW.organization_id, '⚠️ Você foi ultrapassado!', v_overtaker_name || ' te passou no ranking!', 'gamification_overtake');

            -- Notifica quem subiu
            INSERT INTO public.notifications (user_id, organization_id, title, content, type)
            VALUES (NEW.user_id, NEW.organization_id, '🚀 Subiu no Ranking!', 'Você ultrapassou ' || v_overtaken_name || '!', 'gamification_overtake');
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_ranking_overtake() OWNER TO postgres;

--
-- Name: check_storage_org_access(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_storage_org_access(org_id_text text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  org_id uuid;
BEGIN
  -- Try to parse the text as UUID. If it fails, deny access.
  BEGIN
    org_id := org_id_text::uuid;
  EXCEPTION WHEN others THEN
    RETURN FALSE;
  END;

  RETURN EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = auth.uid()
    AND (
      u.organization_id = org_id
      OR u.role = 'super_admin'
      OR EXISTS (
        SELECT 1 FROM public.organization_members om
        WHERE om.user_id = u.id AND om.organization_id = org_id
      )
    )
  );
END;
$$;


ALTER FUNCTION public.check_storage_org_access(org_id_text text) OWNER TO postgres;

--
-- Name: check_whatsapp_conversation_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_whatsapp_conversation_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Se o organization_id não foi enviado, ou para garantir integridade,
  -- buscamos da sessão que o usuário já tem acesso.
  SELECT organization_id INTO NEW.organization_id
  FROM public.whatsapp_sessions
  WHERE id = NEW.session_id;

  RETURN NEW;
END;
$$;


