-- Name: create_notification(uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_notification(p_user_id uuid, p_organization_id uuid, p_title text, p_content text, p_type text DEFAULT 'info'::text, p_lead_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_notification_id uuid;
BEGIN
  INSERT INTO public.notifications (
    user_id,
    organization_id,
    title,
    content,
    type,
    lead_id,
    is_read
  ) VALUES (
    p_user_id,
    p_organization_id,
    p_title,
    p_content,
    p_type,
    p_lead_id,
    false
  )
  RETURNING id INTO v_notification_id;

  RETURN v_notification_id;
END;
$$;


