--
-- Name: enforce_whatsapp_message_session_match(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_whatsapp_message_session_match() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_source public.whatsapp_conversations%rowtype;
  v_session public.whatsapp_sessions%rowtype;
  v_target_id uuid;
  v_remote_jid text;
  v_contact_phone text;
begin
  select *
  into v_source
  from public.whatsapp_conversations
  where id = new.conversation_id;

  if not found then
    raise exception 'WhatsApp conversation % was not found', new.conversation_id
      using errcode = '23503';
  end if;

  if new.session_id is null then
    new.session_id := v_source.session_id;
  end if;

  if new.session_id = v_source.session_id then
    return new;
  end if;

  select *
  into v_session
  from public.whatsapp_sessions
  where id = new.session_id;

  if not found then
    raise exception 'WhatsApp message session_id % was not found', new.session_id
      using errcode = '23503';
  end if;

  v_remote_jid := coalesce(nullif(new.remote_jid, ''), nullif(v_source.remote_jid, ''));
  v_contact_phone := coalesce(
    nullif(v_source.contact_phone, ''),
    case
      when v_remote_jid is not null and v_remote_jid not like '%@g.us'
        then regexp_replace(v_remote_jid, '\D', '', 'g')
      else null
    end
  );

  select c.id
  into v_target_id
  from public.whatsapp_conversations c
  where c.organization_id = v_session.organization_id
    and c.session_id = new.session_id
    and (
      (v_remote_jid is not null and c.remote_jid = v_remote_jid)
      or (
        v_contact_phone is not null
        and regexp_replace(coalesce(c.contact_phone, c.remote_jid, ''), '\D', '', 'g') = v_contact_phone
      )
    )
  order by (c.deleted_at is null) desc, c.last_message_at desc nulls last, c.created_at desc
  limit 1;

  if v_target_id is not null then
    update public.whatsapp_conversations c
    set deleted_at = null,
        updated_at = now(),
        lead_id = case when c.deleted_at is not null then null else c.lead_id end,
        remote_jid = coalesce(nullif(c.remote_jid, ''), v_remote_jid),
        contact_phone = coalesce(nullif(c.contact_phone, ''), v_contact_phone),
        contact_name = coalesce(nullif(c.contact_name, ''), nullif(v_source.contact_name, '')),
        contact_picture = coalesce(nullif(c.contact_picture, ''), nullif(v_source.contact_picture, ''))
    where c.id = v_target_id;
  else
    insert into public.whatsapp_conversations (
      session_id,
      organization_id,
      lead_id,
      remote_jid,
      contact_name,
      contact_phone,
      contact_picture,
      is_group,
      last_message,
      last_message_at,
      unread_count,
      created_at,
      updated_at
    ) values (
      new.session_id,
      v_session.organization_id,
      null,
      v_remote_jid,
      v_source.contact_name,
      v_contact_phone,
      v_source.contact_picture,
      coalesce(v_source.is_group, false),
      null,
      null,
      0,
      now(),
      now()
    )
    on conflict (session_id, remote_jid) do update
      set deleted_at = null,
          updated_at = now(),
          lead_id = case when public.whatsapp_conversations.deleted_at is not null then null else public.whatsapp_conversations.lead_id end,
          contact_phone = coalesce(nullif(public.whatsapp_conversations.contact_phone, ''), excluded.contact_phone),
          contact_name = coalesce(nullif(public.whatsapp_conversations.contact_name, ''), excluded.contact_name),
          contact_picture = coalesce(nullif(public.whatsapp_conversations.contact_picture, ''), excluded.contact_picture)
    returning id into v_target_id;
  end if;

  new.conversation_id := v_target_id;
  return new;
end;
$$;


ALTER FUNCTION public.enforce_whatsapp_message_session_match() OWNER TO postgres;

--
-- Name: enforce_whatsapp_outbox_session_match(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_whatsapp_outbox_session_match() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_active_lead_id uuid;
  v_canonical_lead_id uuid;
begin
  select conversation.*
  into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = new.conversation_id
  for share;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_outbox_conversation_not_found';
  end if;

  if new.session_id is distinct from v_conversation.session_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_session_mismatch';
  end if;

  if new.organization_id is distinct from v_conversation.organization_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_organization_mismatch';
  end if;

  if tg_op = 'UPDATE'
     and old.lead_id is not null
     and new.lead_id is distinct from old.lead_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_lead_immutable';
  end if;

  if new.client_message_id is not null then
    select message.lead_id
    into v_canonical_lead_id
    from public.whatsapp_messages as message
    where message.organization_id = new.organization_id
      and message.session_id = new.session_id
      and message.conversation_id = new.conversation_id
      and message.client_message_id = new.client_message_id
      and message.lead_id is not null
    limit 1;
  end if;

  if new.lead_id is null then
    new.lead_id := coalesce(v_canonical_lead_id, v_conversation.lead_id);
  elsif v_canonical_lead_id is not null
        and new.lead_id is distinct from v_canonical_lead_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_canonical_lead_mismatch';
  end if;

  select binding.lead_id
  into v_active_lead_id
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.organization_id = new.organization_id
    and binding.conversation_id = new.conversation_id
    and binding.active_to is null;

  if found and v_active_lead_id is distinct from v_conversation.lead_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_binding_state_mismatch';
  end if;

  if new.lead_id is null then
    if v_conversation.lead_id is not null or v_active_lead_id is not null then
      raise exception using
        errcode = '23514',
        message = 'whatsapp_outbox_lead_snapshot_required';
    end if;

    return new;
  end if;

  if new.lead_id is distinct from v_conversation.lead_id
     or (v_active_lead_id is not null
         and new.lead_id is distinct from v_active_lead_id) then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_lead_binding_mismatch';
  end if;

  if not exists (
    select 1
    from public.leads as lead
    where lead.id = new.lead_id
      and lead.organization_id = new.organization_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'whatsapp_outbox_lead_tenant_mismatch';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.enforce_whatsapp_outbox_session_match() OWNER TO postgres;

--
-- Name: enqueue_automation_whatsapp_outbox(uuid, uuid, text, text, text, uuid, uuid, text, text, text, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_automation_whatsapp_outbox(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_effect_key text, p_conversation_id uuid, p_session_id uuid, p_client_message_id text, p_message_type text, p_content text, p_media_mime_type text, p_media_storage_path text, p_media_size bigint, p_filename text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  expected_effect_type text;
  clean_message_type text := lower(btrim(coalesce(p_message_type, '')));
  clean_content text := nullif(btrim(coalesce(p_content, '')), '');
  clean_media_mime_type text := nullif(btrim(coalesce(p_media_mime_type, '')), '');
  clean_media_storage_path text := nullif(btrim(coalesce(p_media_storage_path, '')), '');
  clean_filename text := nullif(btrim(coalesce(p_filename, '')), '');
  expected_media_prefix text;
  target_lead_id uuid;
  actor_user_id uuid;
  stored_remote_jid text;
  canonical_remote_jid text;
  destination text;
  provider_request_id text := upper(substr(encode(extensions.digest(btrim(p_client_message_id), 'sha256'), 'hex'), 1, 32));
  queued_message_key text;
  preview text;
  queued_at timestamptz := now();
  stored_message_id uuid;
  stored_outbox_id uuid;
  outbox_action text;
  outbox_body jsonb;
  outbox_payload jsonb;
  existing_message public.whatsapp_messages%rowtype;
  existing_outbox public.whatsapp_outbox%rowtype;
  locked_conversation public.whatsapp_conversations%rowtype;
  locked_binding public.whatsapp_conversation_lead_bindings%rowtype;
  locked_execution public.automation_executions%rowtype;
  locked_dispatch public.automation_effect_dispatches%rowtype;
  locked_flow public.automation_flow_versions%rowtype;
  effect_response jsonb;
begin
  expected_effect_type := case clean_message_type
    when 'text' then 'send_whatsapp'
    when 'image' then 'send_image'
    when 'audio' then 'send_audio'
    when 'video' then 'send_video'
    else null
  end;

  if expected_effect_type is null then
    raise exception using errcode = '22023', message = 'unsupported_automation_whatsapp_message_type';
  end if;
  if nullif(btrim(coalesce(p_node_key, '')), '') is null
     or nullif(btrim(coalesce(p_lease_token, '')), '') is null
     or nullif(btrim(coalesce(p_effect_key, '')), '') is null
     or length(p_effect_key) > 512
     or p_client_message_id is distinct from p_effect_key
     or p_effect_key <> 'automation:' || p_execution_id::text || ':' || p_node_key || ':' || expected_effect_type then
    raise exception using errcode = '22023', message = 'invalid_automation_whatsapp_effect_identity';
  end if;

  if clean_message_type = 'text' then
    if clean_content is null or length(clean_content) > 65536
       or clean_media_mime_type is not null
       or clean_media_storage_path is not null
       or p_media_size is not null then
      raise exception using errcode = '22023', message = 'invalid_automation_whatsapp_text_payload';
    end if;
  else
    expected_media_prefix := 'orgs/' || p_organization_id::text || '/sessions/' || p_session_id::text || '/outgoing/';
    if clean_media_mime_type is null
       or length(clean_media_mime_type) > 255
       or clean_media_storage_path is null
       or length(clean_media_storage_path) > 1024
       or left(clean_media_storage_path, length(expected_media_prefix)) <> expected_media_prefix
       or position('..' in clean_media_storage_path) > 0
       or position(E'\\' in clean_media_storage_path) > 0
       or p_media_size is null
       or p_media_size < 1
       or p_media_size > 10485760
       or (clean_content is not null and length(clean_content) > 4096)
       or (clean_filename is not null and length(clean_filename) > 255) then
      raise exception using errcode = '22023', message = 'invalid_or_cross_tenant_automation_whatsapp_media';
    end if;
  end if;

  -- Strict lock order: conversation -> active binding -> execution -> dispatch.
  select conversation.*
  into locked_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id
  for no key update;

  if not found
     or locked_conversation.session_id is distinct from p_session_id
     or locked_conversation.lead_id is null
     or locked_conversation.deleted_at is not null
     or coalesce(locked_conversation.is_group, false) then
    raise exception using errcode = '23514', message = 'automation_whatsapp_queue_context_mismatch';
  end if;

  target_lead_id := locked_conversation.lead_id;
  stored_remote_jid := locked_conversation.remote_jid;

  select binding.*
  into locked_binding
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.conversation_id = p_conversation_id
    and binding.active_to is null
  for share;

  if not found
     or locked_binding.organization_id is distinct from p_organization_id
     or locked_binding.session_id is distinct from p_session_id
     or locked_binding.lead_id is distinct from target_lead_id
     or locked_binding.stale is distinct from false then
    raise exception using errcode = '23514', message = 'automation_whatsapp_queue_binding_mismatch';
  end if;

  if not exists (
    select 1
    from public.whatsapp_attendance_entries as attendance
    where attendance.organization_id = p_organization_id
      and attendance.conversation_id = p_conversation_id
      and attendance.session_id = p_session_id
      and attendance.lead_id = target_lead_id
      and attendance.binding_id = locked_binding.id
  ) then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_attendance_required';
  end if;

  select execution.*
  into locked_execution
  from public.automation_executions as execution
  where execution.id = p_execution_id
    and execution.organization_id = p_organization_id
  for update;

  if not found
     or locked_execution.lead_id is distinct from target_lead_id
     or locked_execution.conversation_id is distinct from p_conversation_id
     or locked_execution.current_node_key is distinct from p_node_key
     or locked_execution.status is distinct from 'running'
     or locked_execution.locked_by is distinct from p_lease_token
     or locked_execution.cancellation_requested_at is not null then
    raise exception using errcode = '23514', message = 'automation_whatsapp_queue_context_mismatch';
  end if;

  select dispatch.*
  into locked_dispatch
  from public.automation_effect_dispatches as dispatch
  where dispatch.effect_key = p_effect_key
  for update;

  if not found
     or locked_dispatch.organization_id is distinct from p_organization_id
     or locked_dispatch.execution_id is distinct from p_execution_id
     or locked_dispatch.node_key is distinct from p_node_key
     or locked_dispatch.effect_type is distinct from expected_effect_type
     or locked_dispatch.status not in ('sending', 'succeeded')
     or locked_dispatch.request->>'delivery_contract' is distinct from 'canonical_whatsapp_outbox_v1'
     or locked_dispatch.request->>'session_id' is distinct from p_session_id::text then
    raise exception using errcode = '23514', message = 'automation_whatsapp_effect_fencing_conflict';
  end if;

  if not exists (
    select 1
    from public.whatsapp_sessions as session
    where session.id = p_session_id
      and session.organization_id = p_organization_id
      and session.provider = 'evolution_go'
      and session.status = 'connected'
      and coalesce(session.is_active, true)
  ) then
    raise exception using errcode = '23514', message = 'automation_whatsapp_queue_context_mismatch';
  end if;

  select flow.*
  into locked_flow
  from public.automation_flow_versions as flow
  where flow.id = locked_execution.flow_version_id
    and flow.organization_id = p_organization_id;

  if not found then
    raise exception using errcode = '23514', message = 'automation_whatsapp_queue_context_mismatch';
  end if;
  actor_user_id := locked_flow.created_by;

  if not exists (
    select 1
    from public.leads as lead
    where lead.id = target_lead_id
      and lead.organization_id = p_organization_id
  ) or not exists (
    select 1
    from public.organization_modules as module
    where module.organization_id = p_organization_id
      and lower(btrim(module.module_name)) = 'automations'
      and coalesce(module.is_enabled, false)
  ) or not exists (
    select 1
    from jsonb_array_elements(
      case
        when jsonb_typeof(locked_flow.graph->'nodes') = 'array'
          then locked_flow.graph->'nodes'
        else '[]'::jsonb
      end
    ) as graph_node(value)
    where graph_node.value->>'id' = p_node_key
      and graph_node.value->>'type' = 'action'
      and graph_node.value->>'action_type' = expected_effect_type
  ) then
    raise exception using errcode = '23514', message = 'automation_whatsapp_queue_context_mismatch';
  end if;

  select identity_alias.canonical_jid
  into canonical_remote_jid
  from public.whatsapp_contact_identity_aliases as identity_alias
  where identity_alias.organization_id = p_organization_id
    and identity_alias.session_id = p_session_id
    and identity_alias.lead_id = target_lead_id
    and identity_alias.alias_jid = stored_remote_jid
    and identity_alias.canonical_jid ~ '^[0-9]{10,15}@(s[.]whatsapp[.]net|c[.]us)$'
  order by identity_alias.last_seen_at desc, identity_alias.id
  limit 1;

  canonical_remote_jid := coalesce(canonical_remote_jid, stored_remote_jid);
  if canonical_remote_jid ~ '^[0-9]{10,15}@c[.]us$' then
    canonical_remote_jid := regexp_replace(canonical_remote_jid, '@c[.]us$', '@s.whatsapp.net');
  end if;
  if canonical_remote_jid !~ '^[0-9]{10,15}@s[.]whatsapp[.]net$' then
    raise exception using errcode = '22023', message = 'conversation_has_no_canonical_whatsapp_destination';
  end if;
  destination := split_part(canonical_remote_jid, '@', 1);

  preview := case
    when clean_content is not null then left(clean_content, 500)
    when clean_message_type = 'image' then '[Imagem]'
    when clean_message_type = 'audio' then '[Audio]'
    when clean_message_type = 'video' then '[Video]'
    else '[Midia]'
  end;
  queued_message_key := 'queued:' || md5(p_effect_key);

  if clean_message_type = 'text' then
    outbox_action := 'send.text';
    outbox_body := jsonb_build_object(
      'id', provider_request_id,
      'number', destination,
      'text', clean_content
    );
  else
    outbox_action := case
      when clean_message_type = 'audio' then 'send.audio'
      else 'send.media'
    end;
    outbox_body := jsonb_strip_nulls(jsonb_build_object(
      'id', provider_request_id,
      'number', destination,
      'type', clean_message_type,
      'mediatype', clean_message_type,
      'mediaType', clean_message_type,
      'caption', clean_content,
      'mimetype', clean_media_mime_type,
      'filename', clean_filename,
      'mediaStoragePath', clean_media_storage_path
    ));
  end if;
  outbox_payload := jsonb_build_object('action', outbox_action, 'body', outbox_body);

  insert into public.whatsapp_messages (
    organization_id, conversation_id, session_id, lead_id, sender_user_id,
    capture_state, provider_message_id, message_id, client_message_id, from_me, direction,
    message_type, content, media_url, media_mime_type, media_storage_path,
    media_status, media_size, remote_jid, status, sent_at, metadata
  ) values (
    p_organization_id, p_conversation_id, p_session_id, target_lead_id, actor_user_id,
    'captured', provider_request_id, queued_message_key, p_client_message_id, true, 'outbound',
    clean_message_type, clean_content, null, clean_media_mime_type, clean_media_storage_path,
    case when clean_media_storage_path is null then null else 'ready' end,
    p_media_size, canonical_remote_jid, 'queued', queued_at,
    jsonb_build_object(
      'origin', 'automation',
      'delivery', 'outbox',
      'execution_id', p_execution_id,
      'node_key', p_node_key,
      'automation_effect_key', p_effect_key
    )
  )
  on conflict (organization_id, session_id, client_message_id)
    where client_message_id is not null
  do nothing
  returning id into stored_message_id;

  if stored_message_id is null then
    select message.*
    into existing_message
    from public.whatsapp_messages as message
    where message.organization_id = p_organization_id
      and message.session_id = p_session_id
      and message.client_message_id = p_client_message_id
    limit 1;

    -- Reject a malicious cross-conversation idempotency collision before
    -- trying to lock that foreign message row. Same-conversation work is
    -- already serialized by the conversation lock held above.
    if existing_message.id is null
       or existing_message.conversation_id <> p_conversation_id
       or existing_message.lead_id is distinct from target_lead_id then
      raise exception using errcode = '23505', message = 'automation_whatsapp_message_idempotency_collision';
    end if;

    select message.*
    into existing_message
    from public.whatsapp_messages as message
    where message.id = existing_message.id
    for update;

    if existing_message.id is null
       or existing_message.conversation_id <> p_conversation_id
       or existing_message.lead_id is distinct from target_lead_id
       or existing_message.client_message_id is distinct from p_client_message_id
       or existing_message.message_id is distinct from queued_message_key
       or existing_message.from_me is distinct from true
       or existing_message.direction is distinct from 'outbound'
       or existing_message.sender_user_id is distinct from actor_user_id
       or existing_message.capture_state is distinct from 'captured'
       or existing_message.message_type <> clean_message_type
       or existing_message.content is distinct from clean_content
       or existing_message.media_mime_type is distinct from clean_media_mime_type
       or existing_message.media_storage_path is distinct from clean_media_storage_path
       or existing_message.media_size is distinct from p_media_size
       or existing_message.remote_jid is distinct from canonical_remote_jid
       or existing_message.provider_message_id is distinct from provider_request_id
       or existing_message.metadata->>'origin' is distinct from 'automation'
       or existing_message.metadata->>'delivery' is distinct from 'outbox'
       or existing_message.metadata->>'execution_id' is distinct from p_execution_id::text
       or existing_message.metadata->>'node_key' is distinct from p_node_key
       or existing_message.metadata->>'automation_effect_key' is distinct from p_effect_key then
      raise exception using errcode = '23505', message = 'automation_whatsapp_message_idempotency_collision';
    end if;
    stored_message_id := existing_message.id;
  end if;

  insert into public.whatsapp_outbox (
    organization_id, session_id, conversation_id, message_id,
    client_message_id, recipient_jid, message_type, payload,
    status, next_attempt_at
  ) values (
    p_organization_id, p_session_id, p_conversation_id, stored_message_id,
    p_client_message_id, canonical_remote_jid, clean_message_type, outbox_payload,
    'pending', queued_at
  )
  on conflict (organization_id, session_id, client_message_id) do nothing
  returning id into stored_outbox_id;

  if stored_outbox_id is null then
    select queued.*
    into existing_outbox
    from public.whatsapp_outbox as queued
    where queued.organization_id = p_organization_id
      and queued.session_id = p_session_id
      and queued.client_message_id = p_client_message_id
    limit 1;

    if existing_outbox.id is null
       or existing_outbox.conversation_id <> p_conversation_id then
      raise exception using errcode = '23505', message = 'automation_whatsapp_outbox_idempotency_collision';
    end if;

    select queued.*
    into existing_outbox
    from public.whatsapp_outbox as queued
    where queued.id = existing_outbox.id
    for update;

    if existing_outbox.id is null
       or existing_outbox.organization_id <> p_organization_id
       or existing_outbox.session_id <> p_session_id
       or existing_outbox.conversation_id <> p_conversation_id
       or existing_outbox.message_id <> stored_message_id
       or existing_outbox.client_message_id <> p_client_message_id
       or existing_outbox.recipient_jid <> canonical_remote_jid
       or existing_outbox.message_type <> clean_message_type
       or existing_outbox.provider_message_id is distinct from provider_request_id
       or existing_outbox.payload <> outbox_payload then
      raise exception using errcode = '23505', message = 'automation_whatsapp_outbox_idempotency_collision';
    end if;
    stored_outbox_id := existing_outbox.id;
  end if;

  update public.whatsapp_conversations as conversation
  set last_message = preview,
      last_message_preview = preview,
      last_message_at = greatest(coalesce(conversation.last_message_at, queued_at), queued_at),
      unread_count = 0,
      updated_at = queued_at
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id
    and conversation.session_id = p_session_id
    and conversation.lead_id = target_lead_id;

  if not found then
    raise exception using errcode = '23514', message = 'automation_whatsapp_queue_context_mismatch';
  end if;

  insert into public.lead_timeline_events (
    organization_id, lead_id, event_type, title, description,
    user_id, actor_user_id, metadata, event_at
  ) values (
    p_organization_id, target_lead_id,
    'whatsapp_message_queued',
    'Mensagem WhatsApp enfileirada pela automacao', preview,
    actor_user_id, actor_user_id,
    jsonb_build_object(
      'automation_effect_key', p_effect_key,
      'execution_id', p_execution_id,
      'node_key', p_node_key,
      'message_row_id', stored_message_id,
      'client_message_id', p_client_message_id,
      'message_type', clean_message_type,
      'session_id', p_session_id,
      'conversation_id', p_conversation_id,
      'outbox_id', stored_outbox_id,
      'delivery_status', 'queued'
    ),
    queued_at
  )
  on conflict ((metadata->>'automation_effect_key'))
    where metadata ? 'automation_effect_key'
  do nothing;

  effect_response := jsonb_build_object(
    'delivery', 'outbox',
    'status', 'queued',
    'message_id', stored_message_id,
    'outbox_id', stored_outbox_id
  );

  if locked_dispatch.status = 'succeeded'
     and locked_dispatch.response is distinct from effect_response then
    raise exception using
      errcode = '23505',
      message = 'automation_whatsapp_dispatch_idempotency_collision';
  end if;

  update public.automation_effect_dispatches as dispatch
  set status = 'succeeded',
      response = effect_response,
      provider_id = null,
      error_message = null,
      completed_at = coalesce(dispatch.completed_at, queued_at)
  where dispatch.id = locked_dispatch.id
    and dispatch.effect_key = p_effect_key
    and dispatch.organization_id = p_organization_id
    and dispatch.execution_id = p_execution_id
    and dispatch.node_key = p_node_key
    and dispatch.effect_type = expected_effect_type
    and dispatch.status in ('sending', 'succeeded')
    and dispatch.request->>'delivery_contract' = 'canonical_whatsapp_outbox_v1'
    and dispatch.request->>'session_id' = p_session_id::text;

  if not found then
    raise exception using errcode = '23514', message = 'automation_whatsapp_effect_fencing_conflict';
  end if;

  return jsonb_build_object(
    'ok', true,
    'status', 'queued',
    'message_id', stored_message_id,
    'outbox_id', stored_outbox_id
  );
end;
$_$;


ALTER FUNCTION public.enqueue_automation_whatsapp_outbox(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_effect_key text, p_conversation_id uuid, p_session_id uuid, p_client_message_id text, p_message_type text, p_content text, p_media_mime_type text, p_media_storage_path text, p_media_size bigint, p_filename text) OWNER TO postgres;

--
-- Name: FUNCTION enqueue_automation_whatsapp_outbox(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_effect_key text, p_conversation_id uuid, p_session_id uuid, p_client_message_id text, p_message_type text, p_content text, p_media_mime_type text, p_media_storage_path text, p_media_size bigint, p_filename text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.enqueue_automation_whatsapp_outbox(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_effect_key text, p_conversation_id uuid, p_session_id uuid, p_client_message_id text, p_message_type text, p_content text, p_media_mime_type text, p_media_storage_path text, p_media_size bigint, p_filename text) IS 'automation_whatsapp_binding_fence_v2: enqueues a canonical automation delivery under conversation, active-binding, execution, and dispatch locks; exact replay preserves message/outbox response ids.';


--
-- Name: enqueue_due_automation_inactivity(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_due_automation_inactivity(p_batch_size integer DEFAULT 100) RETURNS SETOF public.automation_event_outbox
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  with candidates as (
    select
      a.organization_id,
      fv.id as flow_version_id,
      l.id as lead_id,
      l.assigned_user_id,
      greatest(coalesce(l.last_contact_at, '-infinity'::timestamptz), l.updated_at, l.created_at) as last_activity_at
    from public.automations a
    join public.automation_flow_versions fv on fv.id = a.active_flow_version_id
    join public.organization_modules om
      on om.organization_id = a.organization_id
     and lower(trim(om.module_name)) = 'automations'
     and coalesce(om.is_enabled, false) = true
    join public.leads l on l.organization_id = a.organization_id
    where a.is_active = true
      and a.deleted_at is null
      and fv.trigger_type = 'inactivity'
      and fv.requires_review = false
      and l.operational_effects_suppressed = false
      and coalesce(fv.trigger_config->>'inactivity_value', '') ~ '^[0-9]+$'
      and fv.trigger_config->>'inactivity_unit' in ('hours', 'days')
      and (
        (fv.trigger_config->>'inactivity_unit' = 'hours' and (fv.trigger_config->>'inactivity_value')::integer between 1 and 8760)
        or (fv.trigger_config->>'inactivity_unit' = 'days' and (fv.trigger_config->>'inactivity_value')::integer between 1 and 365)
      )
      and greatest(coalesce(l.last_contact_at, '-infinity'::timestamptz), l.updated_at, l.created_at)
        <= now() - case
          when fv.trigger_config->>'inactivity_unit' = 'hours'
            then make_interval(hours => (fv.trigger_config->>'inactivity_value')::integer)
          else make_interval(days => (fv.trigger_config->>'inactivity_value')::integer)
        end
      and (
        nullif(fv.trigger_config->>'filter_user_id', '') is null
        or (fv.trigger_config->>'filter_user_id') = l.assigned_user_id::text
        or (
          fv.trigger_config->>'filter_user_id' = '__me__'
          and fv.created_by = l.assigned_user_id
        )
      )
      and not exists (
        select 1
        from public.automation_event_outbox o
        where o.dedupe_key = 'inactivity:' || fv.id::text || ':' || l.id::text || ':' ||
          greatest(coalesce(l.last_contact_at, '-infinity'::timestamptz), l.updated_at, l.created_at)::text
      )
    order by last_activity_at, fv.id, l.id
    limit least(greatest(coalesce(p_batch_size, 100), 1), 500)
  )
  insert into public.automation_event_outbox (
    organization_id, event_type, aggregate_type, aggregate_id,
    lead_id, dedupe_key, payload
  )
  select
    c.organization_id,
    'inactivity',
    'lead',
    c.lead_id,
    c.lead_id,
    'inactivity:' || c.flow_version_id::text || ':' || c.lead_id::text || ':' || c.last_activity_at::text,
    jsonb_build_object(
      'lead_id', c.lead_id,
      'assigned_user_id', c.assigned_user_id,
      'flow_version_id', c.flow_version_id,
      'last_activity_at', c.last_activity_at,
      'causal_depth', 0
    )
  from candidates c
  on conflict (dedupe_key) do nothing
  returning *;
$_$;


ALTER FUNCTION public.enqueue_due_automation_inactivity(p_batch_size integer) OWNER TO postgres;

--
-- Name: enqueue_due_automation_schedules(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_due_automation_schedules(p_batch_size integer DEFAULT 50) RETURNS SETOF public.automation_event_outbox
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with candidates as (
    select
      a.id as automation_id,
      a.organization_id,
      fv.id as flow_version_id,
      private.safe_automation_timestamptz(fv.trigger_config->>'scheduled_at') as scheduled_at,
      private.safe_uuid(fv.trigger_config->>'target_lead_id') as lead_id
    from public.automations a
    join public.automation_flow_versions fv on fv.id = a.active_flow_version_id
    join public.organization_modules om
      on om.organization_id = a.organization_id
     and lower(trim(om.module_name)) = 'automations'
     and coalesce(om.is_enabled, false) = true
    where a.is_active = true
      and a.deleted_at is null
      and fv.trigger_type = 'scheduled'
      and fv.requires_review = false
      and fv.trigger_config->>'target_type' = 'lead'
      and private.safe_automation_timestamptz(fv.trigger_config->>'scheduled_at') <= now()
      and exists (
        select 1 from public.leads l
        where l.id = private.safe_uuid(fv.trigger_config->>'target_lead_id')
          and l.organization_id = a.organization_id
      )
      and not exists (
        select 1 from public.automation_schedule_state s
        where s.flow_version_id = fv.id and s.completed_at is not null
      )
    order by private.safe_automation_timestamptz(fv.trigger_config->>'scheduled_at'), fv.id
    limit least(greatest(coalesce(p_batch_size, 50), 1), 100)
    for update of fv skip locked
  ), events as (
    insert into public.automation_event_outbox (
      organization_id, event_type, aggregate_type, aggregate_id,
      lead_id, dedupe_key, payload
    )
    select
      c.organization_id,
      'scheduled',
      'automation_flow_version',
      c.flow_version_id,
      c.lead_id,
      'scheduled:' || c.flow_version_id::text || ':' || c.scheduled_at::text,
      jsonb_build_object(
        'lead_id', c.lead_id,
        'flow_version_id', c.flow_version_id,
        'scheduled_at', c.scheduled_at,
        'causal_depth', 0
      )
    from candidates c
    on conflict (dedupe_key) do nothing
    returning *
  ), states as (
    insert into public.automation_schedule_state (
      flow_version_id, automation_id, organization_id, next_run_at,
      last_enqueued_at, completed_at, updated_at
    )
    select
      c.flow_version_id, c.automation_id, c.organization_id, c.scheduled_at,
      now(), now(), now()
    from candidates c
    on conflict (flow_version_id) do update
      set last_enqueued_at = coalesce(automation_schedule_state.last_enqueued_at, excluded.last_enqueued_at),
          completed_at = coalesce(automation_schedule_state.completed_at, excluded.completed_at),
          updated_at = now()
    returning flow_version_id
  )
  select events.* from events;
$$;


ALTER FUNCTION public.enqueue_due_automation_schedules(p_batch_size integer) OWNER TO postgres;

--
-- Name: enqueue_managed_whatsapp_distribution_auto_reply(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_managed_whatsapp_distribution_auto_reply(p_organization_id uuid, p_entry_event_id uuid, p_assigned_user_id uuid, p_distribution_event_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_now timestamptz := clock_timestamp();
  v_entry public.lead_entry_events%rowtype;
  v_round_robin_id uuid;
  v_session_id uuid;
  v_rule_id uuid;
  v_provider_message_id text;
  v_distribution_event_id text;
  v_reservation jsonb;
  v_context_active boolean;
  v_reply_message text;
  v_delay_seconds integer;
  v_conversation_id uuid;
  v_inbound_message_id uuid;
  v_inbound_remote_jid text;
  v_conversation_remote_jid text;
  v_contact_phone text;
  v_remote_jid text;
  v_destination text;
  v_client_message_id text;
  v_provider_request_id text;
  v_message_id uuid;
  v_existing_message public.whatsapp_messages%rowtype;
  v_outbox_id uuid;
  v_existing_outbox public.whatsapp_outbox%rowtype;
  v_was_queued boolean := false;
begin
  if p_organization_id is null
     or p_entry_event_id is null
     or p_assigned_user_id is null
     or nullif(btrim(coalesce(p_distribution_event_id, '')), '') is null then
    raise exception using
      errcode = '22023',
      message = 'managed_whatsapp_distribution_auto_reply_invalid_input';
  end if;

  v_distribution_event_id := btrim(p_distribution_event_id);

  select entry.*
    into v_entry
    from public.lead_entry_events as entry
   where entry.organization_id = p_organization_id
     and entry.id = p_entry_event_id
     and entry.entry_type = 'initial'
     and entry.provider = 'whatsapp'
     and entry.is_countable = true
     and lower(btrim(coalesce(
       entry.metadata->>'managed_whatsapp_message_distribution',
       'false'
     ))) in ('true', '1', 'yes')
   limit 1
   for update;

  if not found then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'managed_initial_entry_not_found'
    );
  end if;

  -- Lock order is entry row first, advisory key second. The entry trigger
  -- already owns the row lock, so every caller now follows the same order.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'managed-whatsapp-distribution-auto-reply:'
        || p_organization_id::text || ':' || p_entry_event_id::text,
      0
    )
  );

  begin
    v_round_robin_id := nullif(
      btrim(coalesce(
        v_entry.metadata->>'target_round_robin_id',
        v_entry.metadata->'intake_result'->>'round_robin_id',
        ''
      )),
      ''
    )::uuid;
    v_session_id := nullif(
      btrim(coalesce(v_entry.metadata->>'whatsapp_session_id', '')),
      ''
    )::uuid;
    v_rule_id := nullif(
      btrim(coalesce(v_entry.metadata->>'matched_rule_id', '')),
      ''
    )::uuid;
  exception
    when invalid_text_representation then
      return jsonb_build_object(
        'handled', true,
        'queued', false,
        'reason', 'managed_entry_context_invalid'
      );
  end;

  v_provider_message_id := btrim(coalesce(
    v_entry.metadata->>'provider_message_id',
    ''
  ));

  if v_round_robin_id is null
     or v_session_id is null
     or v_rule_id is null
     or v_provider_message_id = ''
     or v_entry.provider_event_id is distinct from (
       v_session_id::text || ':' || v_provider_message_id
     ) then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'managed_entry_context_invalid'
    );
  end if;

  -- The caller must present the immutable event emitted by the canonical
  -- distributor. A matching current owner alone is not sufficient proof: the
  -- lead may have been assigned manually after intake.
  if not exists (
    select 1
    from public.round_robin_logs as distribution_log
    where distribution_log.organization_id = p_organization_id
      and distribution_log.round_robin_id = v_round_robin_id
      and distribution_log.lead_id = v_entry.lead_id
      and distribution_log.assigned_user_id = p_assigned_user_id
      and distribution_log.metadata->>'distribution_event_id' = v_distribution_event_id
  ) then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'canonical_distribution_not_proven'
    );
  end if;

  v_client_message_id := 'managed-wa-distribution-reply:'
    || pg_catalog.encode(
      extensions.digest(p_entry_event_id::text, 'sha256'),
      'hex'
    );
  v_provider_request_id := upper(substr(
    pg_catalog.encode(
      extensions.digest(v_client_message_id, 'sha256'),
      'hex'
    ),
    1,
    32
  ));

  -- A retry remains idempotent even when the queue is later disabled or its
  -- message/delay is edited. Once accepted, the original durable outbox row is
  -- the source of truth for this entry event.
  select message.*
    into v_existing_message
    from public.whatsapp_messages as message
   where message.organization_id = p_organization_id
     and message.session_id = v_session_id
     and message.client_message_id = v_client_message_id
   limit 1
   for update;

  if found then
    if v_existing_message.lead_id is distinct from v_entry.lead_id
       or coalesce(v_existing_message.from_me, false) = false
       or lower(coalesce(v_existing_message.direction, '')) <> 'outbound'
       or lower(coalesce(v_existing_message.message_type, '')) <> 'text'
       or v_existing_message.remote_jid !~ '^[0-9]{10,15}@s[.]whatsapp[.]net$'
       or coalesce(
         v_existing_message.metadata->>'managed_whatsapp_entry_event_id',
         ''
       ) is distinct from p_entry_event_id::text
       or coalesce(
         v_existing_message.metadata->>'managed_whatsapp_distribution_event_id',
         ''
       ) is distinct from v_distribution_event_id then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_distribution_auto_reply_collision';
    end if;

    select queued.*
      into v_existing_outbox
      from public.whatsapp_outbox as queued
     where queued.organization_id = p_organization_id
       and queued.session_id = v_session_id
       and queued.client_message_id = v_client_message_id
     limit 1
     for update;

    if found then
      if v_existing_outbox.conversation_id is distinct from v_existing_message.conversation_id
         or v_existing_outbox.message_id is distinct from v_existing_message.id
         or v_existing_outbox.recipient_jid is distinct from v_existing_message.remote_jid
         or lower(coalesce(v_existing_outbox.message_type, '')) <> 'text'
         or v_existing_outbox.provider_message_id is distinct from v_provider_request_id
         or v_existing_outbox.payload->>'action' is distinct from 'send.text'
         or v_existing_outbox.payload->'body'->>'id' is distinct from v_provider_request_id
         or v_existing_outbox.payload->'body'->>'number'
              is distinct from split_part(v_existing_message.remote_jid, '@', 1)
         or v_existing_outbox.payload->'body'->>'text'
              is distinct from coalesce(v_existing_message.content, '') then
        raise exception using
          errcode = '23505',
          message = 'managed_whatsapp_distribution_auto_reply_outbox_collision';
      end if;

      return jsonb_build_object(
        'handled', true,
        'queued', false,
        'reason', 'already_queued',
        'entry_event_id', p_entry_event_id,
        'message_id', v_existing_message.id,
        'outbox_id', v_existing_outbox.id,
        'session_id', v_session_id,
        'conversation_id', v_existing_message.conversation_id,
        'next_attempt_at', v_existing_outbox.next_attempt_at
      );
    end if;

    -- Terminal outbox rows are eventually cleaned up, while the message row is
    -- retained as the permanent idempotency tombstone. Never recreate delivery.
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'already_processed',
      'entry_event_id', p_entry_event_id,
      'message_id', v_existing_message.id,
      'outbox_id', null,
      'session_id', v_session_id,
      'conversation_id', v_existing_message.conversation_id,
      'next_attempt_at', null
    );
  end if;

  if exists (
    select 1
    from public.whatsapp_outbox as queued
    where queued.organization_id = p_organization_id
      and queued.session_id = v_session_id
      and queued.client_message_id = v_client_message_id
  ) then
    raise exception using
      errcode = '23505',
      message = 'managed_whatsapp_distribution_auto_reply_orphan_outbox_collision';
  end if;

  select true
    into v_context_active
    from public.round_robins as queue
    join public.round_robin_rules as round_robin_rule
      on round_robin_rule.organization_id = queue.organization_id
     and round_robin_rule.round_robin_id = queue.id
     and round_robin_rule.id = v_rule_id
    join public.whatsapp_inbound_rules as inbound_rule
      on inbound_rule.organization_id = round_robin_rule.organization_id
     and inbound_rule.id = round_robin_rule.id
     and inbound_rule.target_round_robin_id = round_robin_rule.round_robin_id
     and inbound_rule.session_id = v_session_id
    join public.whatsapp_sessions as whatsapp_session
      on whatsapp_session.organization_id = queue.organization_id
     and whatsapp_session.id = v_session_id
   where queue.organization_id = p_organization_id
     and queue.id = v_round_robin_id
     and coalesce(queue.is_active, true) = true
     and coalesce(round_robin_rule.is_active, true) = true
     and coalesce(inbound_rule.is_active, true) = true
     and whatsapp_session.provider = 'evolution_go'
     and coalesce(whatsapp_session.is_active, true) = true
     and lower(btrim(coalesce(whatsapp_session.status, '')))
       not in ('deleted', 'disabled')
   limit 1
   for share of queue, round_robin_rule, inbound_rule, whatsapp_session;

  if not found or v_context_active is not true then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'managed_queue_context_inactive'
    );
  end if;

  -- The current owner is the proof that canonical distribution really
  -- completed. This deliberately excludes a pending/no-member outcome.
  if not exists (
    select 1
    from public.leads as lead
    where lead.organization_id = p_organization_id
      and lead.id = v_entry.lead_id
      and lead.assigned_user_id = p_assigned_user_id
  ) then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'lead_not_assigned_to_distribution_result'
    );
  end if;

  select
    conversation.id,
    inbound_message.id,
    nullif(btrim(inbound_message.remote_jid), ''),
    nullif(btrim(conversation.remote_jid), ''),
    nullif(btrim(conversation.contact_phone), ''),
    inbound_message.metadata
      ->'managed_whatsapp_distribution_auto_reply_reservation'
    into
      v_conversation_id,
      v_inbound_message_id,
      v_inbound_remote_jid,
      v_conversation_remote_jid,
      v_contact_phone,
      v_reservation
    from public.whatsapp_messages as inbound_message
    join public.whatsapp_conversations as conversation
      on conversation.organization_id = inbound_message.organization_id
     and conversation.id = inbound_message.conversation_id
     and conversation.session_id = inbound_message.session_id
     and conversation.lead_id = inbound_message.lead_id
     and conversation.deleted_at is null
     and coalesce(conversation.is_group, false) = false
   where inbound_message.organization_id = p_organization_id
     and inbound_message.session_id = v_session_id
     and inbound_message.lead_id = v_entry.lead_id
     and coalesce(inbound_message.from_me, false) = false
     and lower(coalesce(inbound_message.direction, 'inbound')) <> 'outbound'
     and (
       inbound_message.provider_message_id = v_provider_message_id
       or (
         inbound_message.provider_message_id is null
         and inbound_message.message_id = v_provider_message_id
       )
     )
   order by
     case when inbound_message.provider_message_id = v_provider_message_id then 0 else 1 end,
     inbound_message.created_at,
     inbound_message.id
   limit 1
   for share of inbound_message, conversation;

  if not found
     or v_conversation_id is null
     or v_inbound_message_id is null then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'inbound_transport_context_not_found'
    );
  end if;

  if not exists (
    select 1
    from public.whatsapp_messages as attended_message
    join public.whatsapp_conversation_lead_bindings as active_binding
      on active_binding.organization_id = attended_message.organization_id
     and active_binding.conversation_id = attended_message.conversation_id
     and active_binding.session_id = attended_message.session_id
     and active_binding.lead_id = attended_message.lead_id
     and active_binding.active_to is null
     and active_binding.stale = false
    join public.whatsapp_attendance_entries as attendance
      on attendance.organization_id = active_binding.organization_id
     and attendance.conversation_id = active_binding.conversation_id
     and attendance.session_id = active_binding.session_id
     and attendance.lead_id = active_binding.lead_id
     and attendance.binding_id = active_binding.id
     and attendance.id::text = coalesce(
       attended_message.metadata
         ->'whatsapp_attendance_capture'->>'attendance_entry_id',
       ''
     )
    where attended_message.organization_id = p_organization_id
      and attended_message.id = v_inbound_message_id
      and attended_message.conversation_id = v_conversation_id
      and attended_message.session_id = v_session_id
      and attended_message.lead_id = v_entry.lead_id
      and attended_message.capture_state = 'captured'
  ) then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'whatsapp_attendance_required'
    );
  end if;

  if jsonb_typeof(v_reservation) <> 'object'
     or coalesce(v_reservation->>'version', '') <> 'v1'
     or coalesce(v_reservation->>'entry_event_id', '')
          is distinct from p_entry_event_id::text
     or coalesce(v_reservation->>'round_robin_id', '')
          is distinct from v_round_robin_id::text
     or coalesce(v_reservation->>'rule_id', '')
          is distinct from v_rule_id::text
     or coalesce(v_reservation->>'session_id', '')
          is distinct from v_session_id::text
     or jsonb_typeof(v_reservation->'message') <> 'string'
     or jsonb_typeof(v_reservation->'delay_seconds') <> 'number'
     or coalesce(v_reservation->>'delay_seconds', '') !~ '^[0-9]{1,4}$' then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'auto_reply_not_reserved'
    );
  end if;

  v_reply_message := btrim(coalesce(v_reservation->>'message', ''));
  v_delay_seconds := (v_reservation->>'delay_seconds')::integer;
  if char_length(v_reply_message) not between 1 and 4000
     or octet_length(v_reply_message) > 16000
     or v_delay_seconds not between 1 and 3600 then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'auto_reply_reservation_invalid'
    );
  end if;

  select identity_alias.canonical_jid
    into v_remote_jid
    from public.whatsapp_contact_identity_aliases as identity_alias
   where identity_alias.organization_id = p_organization_id
     and identity_alias.session_id = v_session_id
     and identity_alias.lead_id = v_entry.lead_id
     and identity_alias.alias_jid in (
       v_inbound_remote_jid,
       v_conversation_remote_jid
     )
     and identity_alias.canonical_jid
       ~ '^[0-9]{10,15}@(s[.]whatsapp[.]net|c[.]us)$'
   order by
     case when identity_alias.alias_jid = v_inbound_remote_jid then 0 else 1 end,
     identity_alias.last_seen_at desc,
     identity_alias.id
   limit 1;

  if v_contact_phone is not null and position('@' in v_contact_phone) = 0 then
    v_destination := regexp_replace(v_contact_phone, '[^0-9]', '', 'g');
    if length(v_destination) not between 10 and 15 then
      v_destination := null;
    end if;
  end if;

  v_remote_jid := coalesce(
    v_remote_jid,
    case
      when v_inbound_remote_jid ~ '^[0-9]{10,15}@s[.]whatsapp[.]net$'
        then v_inbound_remote_jid
    end,
    case
      when v_conversation_remote_jid ~ '^[0-9]{10,15}@s[.]whatsapp[.]net$'
        then v_conversation_remote_jid
    end,
    case
      when v_inbound_remote_jid ~ '^[0-9]{10,15}@c[.]us$'
        then regexp_replace(v_inbound_remote_jid, '@c[.]us$', '@s.whatsapp.net')
    end,
    case
      when v_conversation_remote_jid ~ '^[0-9]{10,15}@c[.]us$'
        then regexp_replace(v_conversation_remote_jid, '@c[.]us$', '@s.whatsapp.net')
    end,
    case
      when v_destination is not null then v_destination || '@s.whatsapp.net'
    end
  );

  if v_remote_jid ~ '^[0-9]{10,15}@c[.]us$' then
    v_remote_jid := regexp_replace(v_remote_jid, '@c[.]us$', '@s.whatsapp.net');
  end if;
  if v_remote_jid !~ '^[0-9]{10,15}@s[.]whatsapp[.]net$' then
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'canonical_whatsapp_destination_not_found'
    );
  end if;
  v_destination := split_part(v_remote_jid, '@', 1);

  insert into public.whatsapp_messages (
    organization_id,
    conversation_id,
    session_id,
    lead_id,
    sender_user_id,
    capture_state,
    message_id,
    client_message_id,
    from_me,
    direction,
    content,
    message_type,
    remote_jid,
    status,
    sent_at,
    sender_name,
    metadata
  )
  values (
    p_organization_id,
    v_conversation_id,
    v_session_id,
    v_entry.lead_id,
    null,
    'captured',
    v_provider_request_id,
    v_client_message_id,
    true,
    'outbound',
    v_reply_message,
    'text',
    v_remote_jid,
    'queued',
    v_now,
    'Atendimento automático',
    jsonb_build_object(
      'delivery', 'outbox',
      'origin', 'automation',
      'is_automation', true,
      'managed_whatsapp_distribution_auto_reply', true,
      'managed_whatsapp_reply_to_message_id', v_inbound_message_id,
       'managed_whatsapp_entry_event_id', p_entry_event_id,
       'managed_whatsapp_distribution_event_id', v_distribution_event_id,
       'managed_whatsapp_round_robin_id', v_round_robin_id,
      'managed_whatsapp_assigned_user_id', p_assigned_user_id,
      'managed_whatsapp_delay_seconds', v_delay_seconds
    )
  )
  on conflict (organization_id, session_id, client_message_id)
    where client_message_id is not null
  do nothing
  returning id into v_message_id;

  if v_message_id is null then
    select message.*
      into v_existing_message
      from public.whatsapp_messages as message
     where message.organization_id = p_organization_id
       and message.session_id = v_session_id
       and message.client_message_id = v_client_message_id
     limit 1
     for update;

    if not found
       or v_existing_message.conversation_id is distinct from v_conversation_id
       or v_existing_message.lead_id is distinct from v_entry.lead_id
       or coalesce(v_existing_message.content, '') is distinct from v_reply_message
       or coalesce(
         v_existing_message.metadata->>'managed_whatsapp_reply_to_message_id',
         ''
       ) is distinct from v_inbound_message_id::text then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_distribution_auto_reply_collision';
    end if;
    v_message_id := v_existing_message.id;
  else
    v_was_queued := true;
  end if;

  insert into public.whatsapp_outbox (
    organization_id,
    session_id,
    conversation_id,
    message_id,
    client_message_id,
    recipient_jid,
    message_type,
    payload,
    provider_message_id,
    status,
    next_attempt_at
  )
  values (
    p_organization_id,
    v_session_id,
    v_conversation_id,
    v_message_id,
    v_client_message_id,
    v_remote_jid,
    'text',
    jsonb_build_object(
      'action', 'send.text',
      'body', jsonb_build_object(
        'id', v_provider_request_id,
        'number', v_destination,
        'text', v_reply_message,
        'mentions', jsonb_build_array()
      )
    ),
    v_provider_request_id,
    'pending',
    v_now + pg_catalog.make_interval(secs => v_delay_seconds)
  )
  on conflict (organization_id, session_id, client_message_id)
  do nothing
  returning id into v_outbox_id;

  if v_outbox_id is null then
    select queued.*
      into v_existing_outbox
      from public.whatsapp_outbox as queued
     where queued.organization_id = p_organization_id
       and queued.session_id = v_session_id
       and queued.client_message_id = v_client_message_id
     limit 1
     for update;

    if not found
       or v_existing_outbox.conversation_id is distinct from v_conversation_id
       or v_existing_outbox.message_id is distinct from v_message_id
       or v_existing_outbox.recipient_jid is distinct from v_remote_jid then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_distribution_auto_reply_outbox_collision';
    end if;
    v_outbox_id := v_existing_outbox.id;
  else
    v_was_queued := true;
  end if;

  update public.whatsapp_conversations as conversation
     set last_message = left(v_reply_message, 500),
         last_message_preview = left(v_reply_message, 500),
         last_message_at = greatest(
           coalesce(conversation.last_message_at, v_now),
           v_now
         ),
         updated_at = v_now
   where conversation.organization_id = p_organization_id
     and conversation.id = v_conversation_id
     and conversation.session_id = v_session_id
     and conversation.lead_id = v_entry.lead_id;

  return jsonb_build_object(
    'handled', true,
    'queued', v_was_queued,
    'reason', case when v_was_queued then 'queued' else 'already_queued' end,
    'entry_event_id', p_entry_event_id,
    'message_id', v_message_id,
    'outbox_id', v_outbox_id,
    'session_id', v_session_id,
    'conversation_id', v_conversation_id,
    'next_attempt_at', v_now + pg_catalog.make_interval(secs => v_delay_seconds)
  );
exception
  when sqlstate '22023' then
    raise;
  when others then
    -- The acknowledgement is optional. A collision or outbox-side failure is
    -- reported to the caller without reverting lead creation/distribution.
    return jsonb_build_object(
      'handled', true,
      'queued', false,
      'reason', 'auto_reply_enqueue_failed',
      'error_code', sqlstate
    );
end;
$_$;


ALTER FUNCTION public.enqueue_managed_whatsapp_distribution_auto_reply(p_organization_id uuid, p_entry_event_id uuid, p_assigned_user_id uuid, p_distribution_event_id text) OWNER TO postgres;

--
-- Name: FUNCTION enqueue_managed_whatsapp_distribution_auto_reply(p_organization_id uuid, p_entry_event_id uuid, p_assigned_user_id uuid, p_distribution_event_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.enqueue_managed_whatsapp_distribution_auto_reply(p_organization_id uuid, p_entry_event_id uuid, p_assigned_user_id uuid, p_distribution_event_id text) IS 'Accepts one opt-in acknowledgement for an initially distributed managed WhatsApp lead into the canonical delayed outbox. Service role only and idempotent by entry event.';


--
-- Name: enrich_whatsapp_lead_entry_attribution(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enrich_whatsapp_lead_entry_attribution(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_provider_message_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_message_id text := btrim(coalesce(p_provider_message_id, ''));
  v_provider_event_id text;
  v_message public.whatsapp_messages%rowtype;
  v_source jsonb;
  v_attribution jsonb;
  v_source_app text;
  v_confirmation_method text;
  v_entry_point_conversion_source text;
  v_ctwa_clid text;
  v_show_ad_attribution jsonb;
begin
  if p_organization_id is null
     or p_lead_id is null
     or p_session_id is null
     or length(v_provider_message_id) not between 1 and 500
     or p_provider_message_id <> v_provider_message_id then
    raise exception using
      errcode = '22023',
      message = 'whatsapp_entry_attribution_identity_required';
  end if;

  v_provider_event_id := p_session_id::text || ':' || v_provider_message_id;

  select message.*
    into v_message
    from public.whatsapp_messages as message
   where message.organization_id = p_organization_id
     and message.session_id = p_session_id
     and message.lead_id = p_lead_id
     and coalesce(message.from_me, false) = false
     and lower(coalesce(message.direction, 'inbound')) <> 'outbound'
     and (
       message.provider_message_id = v_provider_message_id
       or (
         message.provider_message_id is null
         and message.message_id = v_provider_message_id
       )
     )
   order by message.created_at, message.id
   limit 1;

  if not found then
    return false;
  end if;

  select coalesce(inbound_log.match_details->'whatsapp_attribution', '{}'::jsonb)
    into v_source
    from public.whatsapp_inbound_logs as inbound_log
   where inbound_log.organization_id = p_organization_id
     and inbound_log.session_id = p_session_id
     and inbound_log.conversation_id = v_message.conversation_id
     and inbound_log.lead_id = p_lead_id
     and inbound_log.match_details->>'message_id' = v_provider_message_id
     and lower(coalesce(
       inbound_log.match_details->>'managed_whatsapp_message_distribution',
       'false'
     )) in ('true', '1', 'yes')
   order by inbound_log.created_at, inbound_log.id
   limit 1;

  if not found or jsonb_typeof(v_source) <> 'object' then
    return false;
  end if;

  v_confirmation_method := private.whatsapp_metadata_ctwa_confirmation_method(
    jsonb_build_object('whatsapp_attribution', v_source)
  );
  if v_confirmation_method is null then
    return false;
  end if;

  v_entry_point_conversion_source := coalesce(
    nullif(btrim(v_source->>'entry_point_conversion_source'), ''),
    nullif(btrim(v_source->'source_referral'->>'entry_point_conversion_source'), '')
  );
  v_ctwa_clid := coalesce(
    nullif(btrim(v_source->>'ctwa_clid'), ''),
    nullif(btrim(v_source->'source_referral'->>'ctwa_clid'), '')
  );
  v_show_ad_attribution := coalesce(
    v_source->'show_ad_attribution',
    v_source->'source_referral'->'show_ad_attribution'
  );

  v_source_app := lower(coalesce(
    nullif(btrim(v_source->>'source_app'), ''),
    nullif(btrim(v_source->>'entry_point_conversion_app'), ''),
    nullif(btrim(v_source->'source_referral'->>'source_app'), ''),
    nullif(btrim(v_source->'source_referral'->>'entry_point_conversion_app'), ''),
    'meta'
  ));
  if v_source_app not in ('instagram', 'facebook') then
    v_source_app := 'meta';
  end if;

  v_attribution := jsonb_strip_nulls(jsonb_build_object(
    'source', 'whatsapp',
    'source_type', 'whatsapp_click_to_message',
    'channel', 'whatsapp',
    'platform', 'meta',
    'message_id', v_provider_message_id,
    'provider_event_id', v_provider_event_id,
    'whatsapp_session_id', p_session_id,
    'ctwa_confirmation_method', v_confirmation_method,
    'source_id', nullif(btrim(coalesce(v_source->>'source_id', v_source->>'ad_id', '')), ''),
    'ad_id', nullif(btrim(coalesce(v_source->>'ad_id', v_source->>'source_id', '')), ''),
    'ad_name', nullif(btrim(coalesce(v_source->>'ad_name', v_source->>'source_referral_title', '')), ''),
    'campaign_name', nullif(btrim(coalesce(v_source->>'campaign_name', v_source->>'source_referral_title', '')), ''),
    'creative_name', nullif(btrim(coalesce(v_source->>'creative_name', v_source->>'source_referral_title', '')), ''),
    'creative_link_url', nullif(btrim(coalesce(v_source->>'creative_link_url', v_source->>'source_url', '')), ''),
    'creative_destination_url', nullif(btrim(coalesce(v_source->>'creative_destination_url', v_source->>'source_url', '')), ''),
    'creative_instagram_url', case
      when v_source_app = 'instagram'
        then nullif(btrim(coalesce(v_source->>'source_url', v_source->>'creative_link_url', '')), '')
      else null
    end,
    'source_url', nullif(btrim(coalesce(v_source->>'source_url', v_source->>'creative_link_url', '')), ''),
    'source_app', v_source_app,
    'conversion_source', nullif(btrim(v_source->>'conversion_source'), ''),
    'entry_point_conversion_source', v_entry_point_conversion_source,
    'entry_point_conversion_app', nullif(btrim(v_source->>'entry_point_conversion_app'), ''),
    'ctwa_clid', v_ctwa_clid,
    'show_ad_attribution', v_show_ad_attribution,
    'source_referral', v_source->'source_referral',
    'utm_source', v_source_app,
    'utm_medium', 'click_to_whatsapp'
  ));

  update public.lead_entry_events as entry
     set source = 'whatsapp',
         provider = 'whatsapp',
         occurred_at = coalesce(v_message.sent_at, v_message.received_at, entry.occurred_at, entry.created_at),
         is_countable = true,
         source_detail = 'whatsapp_click_to_message',
         campaign_name = coalesce(nullif(v_attribution->>'campaign_name', ''), entry.campaign_name),
         ad_id = coalesce(nullif(v_attribution->>'ad_id', ''), entry.ad_id),
         ad_name = coalesce(nullif(v_attribution->>'ad_name', ''), entry.ad_name),
         utm_source = v_source_app,
         utm_medium = 'click_to_whatsapp',
         utm_campaign = coalesce(nullif(v_attribution->>'campaign_name', ''), entry.utm_campaign),
         metadata = coalesce(entry.metadata, '{}'::jsonb) || v_attribution,
         payload = coalesce(entry.payload, '{}'::jsonb)
           || jsonb_build_object('whatsapp_attribution', v_attribution)
   where entry.organization_id = p_organization_id
     and entry.lead_id = p_lead_id
     and entry.provider = 'whatsapp'
     and entry.provider_event_id = v_provider_event_id
     and entry.is_countable = true;

  return found;
end;
$$;


ALTER FUNCTION public.enrich_whatsapp_lead_entry_attribution(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_provider_message_id text) OWNER TO postgres;

--
-- Name: FUNCTION enrich_whatsapp_lead_entry_attribution(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_provider_message_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.enrich_whatsapp_lead_entry_attribution(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_provider_message_id text) IS 'Copies provider-derived CTWA v1/v2 attribution from the trusted managed inbound log without manufacturing a missing entry-point signal.';


--
-- Name: ensure_billing_payment_checkout_capability(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ensure_billing_payment_checkout_capability(p_payment_id uuid, p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment public.asaas_payments%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_snapshot record;
begin
  if p_payment_id is null or p_organization_id is null then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  -- Discover the immutable provider key without taking a row lock, then join
  -- the global provider-lock order before the row lock. Organization cleanup
  -- takes the same advisory key for every restorable payment, so exactly one
  -- side can cross its irreversible provider boundary.
  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_payment.asaas_payment_id,
    null
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  if private.billing_organization_cleanup_is_active(
    v_payment.organization_id,
    v_payment.asaas_subscription_id
  ) then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  if v_payment.organization_id is distinct from p_organization_id then
    return jsonb_build_object('outcome', 'organization_mismatch');
  end if;

  if not private.billing_payment_checkout_is_actionable(v_payment.status) then
    return jsonb_build_object(
      'outcome', 'payment_not_actionable',
      'organization_id', v_payment.organization_id,
      'payment_id', v_payment.id,
      'billing_intent_id', v_payment.billing_intent_id
    );
  end if;

  select snapshot.*
  into v_snapshot
  from private.resolve_billing_payment_checkout_snapshot(
    v_payment.id,
    false
  ) as snapshot
  limit 1;

  if not found then
    -- This is the explicit, non-secret outcome for legacy payments that lack
    -- an immutable intent or an exact persisted subscription snapshot. Do not
    -- mint a token that the public resolver would necessarily reject.
    update public.billing_payment_checkout_capabilities
    set
      revoked_at = coalesce(revoked_at, now()),
      attempt_lease_id = null,
      attempt_lease_expires_at = null
    where payment_id = v_payment.id
      and revoked_at is null;

    return jsonb_build_object(
      'outcome', 'payment_not_resolvable',
      'organization_id', v_payment.organization_id,
      'payment_id', v_payment.id,
      'billing_intent_id', v_payment.billing_intent_id
    );
  end if;

  insert into public.billing_payment_checkout_capabilities (
    payment_id,
    asaas_payment_id,
    organization_id,
    billing_intent_id,
    plan_id,
    billing_period_months,
    amount,
    snapshot_source,
    expires_at
  )
  values (
    v_payment.id,
    v_payment.asaas_payment_id,
    v_payment.organization_id,
    v_payment.billing_intent_id,
    v_snapshot.snapshot_plan_id,
    v_snapshot.snapshot_billing_period_months,
    v_snapshot.snapshot_amount,
    v_snapshot.snapshot_source,
    now() + interval '90 days'
  )
  on conflict (payment_id) do update
  set
    asaas_payment_id = excluded.asaas_payment_id,
    organization_id = excluded.organization_id,
    billing_intent_id = excluded.billing_intent_id,
    plan_id = excluded.plan_id,
    billing_period_months = excluded.billing_period_months,
    amount = excluded.amount,
    snapshot_source = excluded.snapshot_source,
    checkout_token = case
      when public.billing_payment_checkout_capabilities.revoked_at is not null
        or public.billing_payment_checkout_capabilities.expires_at <= now()
        or public.billing_payment_checkout_capabilities.asaas_payment_id
          is distinct from excluded.asaas_payment_id
        or public.billing_payment_checkout_capabilities.organization_id
          is distinct from excluded.organization_id
        or public.billing_payment_checkout_capabilities.billing_intent_id
          is distinct from excluded.billing_intent_id
        or public.billing_payment_checkout_capabilities.plan_id
          is distinct from excluded.plan_id
        or public.billing_payment_checkout_capabilities.billing_period_months
          is distinct from excluded.billing_period_months
        or public.billing_payment_checkout_capabilities.amount
          is distinct from excluded.amount
        or public.billing_payment_checkout_capabilities.snapshot_source
          is distinct from excluded.snapshot_source
      then encode(extensions.gen_random_bytes(32), 'hex')
      else public.billing_payment_checkout_capabilities.checkout_token
    end,
    expires_at = now() + interval '90 days',
    revoked_at = null,
    attempt_lease_id = case
      when public.billing_payment_checkout_capabilities.revoked_at is not null
        or public.billing_payment_checkout_capabilities.expires_at <= now()
        or public.billing_payment_checkout_capabilities.asaas_payment_id
          is distinct from excluded.asaas_payment_id
        or public.billing_payment_checkout_capabilities.organization_id
          is distinct from excluded.organization_id
        or public.billing_payment_checkout_capabilities.billing_intent_id
          is distinct from excluded.billing_intent_id
        or public.billing_payment_checkout_capabilities.plan_id
          is distinct from excluded.plan_id
        or public.billing_payment_checkout_capabilities.billing_period_months
          is distinct from excluded.billing_period_months
        or public.billing_payment_checkout_capabilities.amount
          is distinct from excluded.amount
        or public.billing_payment_checkout_capabilities.snapshot_source
          is distinct from excluded.snapshot_source
      then null
      else public.billing_payment_checkout_capabilities.attempt_lease_id
    end,
    attempt_lease_expires_at = case
      when public.billing_payment_checkout_capabilities.revoked_at is not null
        or public.billing_payment_checkout_capabilities.expires_at <= now()
        or public.billing_payment_checkout_capabilities.asaas_payment_id
          is distinct from excluded.asaas_payment_id
        or public.billing_payment_checkout_capabilities.organization_id
          is distinct from excluded.organization_id
        or public.billing_payment_checkout_capabilities.billing_intent_id
          is distinct from excluded.billing_intent_id
        or public.billing_payment_checkout_capabilities.plan_id
          is distinct from excluded.plan_id
        or public.billing_payment_checkout_capabilities.billing_period_months
          is distinct from excluded.billing_period_months
        or public.billing_payment_checkout_capabilities.amount
          is distinct from excluded.amount
        or public.billing_payment_checkout_capabilities.snapshot_source
          is distinct from excluded.snapshot_source
      then null
      else public.billing_payment_checkout_capabilities.attempt_lease_expires_at
    end,
    attempt_window_started_at = case
      when public.billing_payment_checkout_capabilities.revoked_at is not null
        or public.billing_payment_checkout_capabilities.expires_at <= now()
        or public.billing_payment_checkout_capabilities.asaas_payment_id
          is distinct from excluded.asaas_payment_id
        or public.billing_payment_checkout_capabilities.organization_id
          is distinct from excluded.organization_id
        or public.billing_payment_checkout_capabilities.billing_intent_id
          is distinct from excluded.billing_intent_id
        or public.billing_payment_checkout_capabilities.plan_id
          is distinct from excluded.plan_id
        or public.billing_payment_checkout_capabilities.billing_period_months
          is distinct from excluded.billing_period_months
        or public.billing_payment_checkout_capabilities.amount
          is distinct from excluded.amount
        or public.billing_payment_checkout_capabilities.snapshot_source
          is distinct from excluded.snapshot_source
      then null
      else public.billing_payment_checkout_capabilities.attempt_window_started_at
    end,
    attempt_window_count = case
      when public.billing_payment_checkout_capabilities.revoked_at is not null
        or public.billing_payment_checkout_capabilities.expires_at <= now()
        or public.billing_payment_checkout_capabilities.asaas_payment_id
          is distinct from excluded.asaas_payment_id
        or public.billing_payment_checkout_capabilities.organization_id
          is distinct from excluded.organization_id
        or public.billing_payment_checkout_capabilities.billing_intent_id
          is distinct from excluded.billing_intent_id
        or public.billing_payment_checkout_capabilities.plan_id
          is distinct from excluded.plan_id
        or public.billing_payment_checkout_capabilities.billing_period_months
          is distinct from excluded.billing_period_months
        or public.billing_payment_checkout_capabilities.amount
          is distinct from excluded.amount
        or public.billing_payment_checkout_capabilities.snapshot_source
          is distinct from excluded.snapshot_source
      then 0
      else public.billing_payment_checkout_capabilities.attempt_window_count
    end
  returning * into v_capability;

  return jsonb_build_object(
    'outcome', 'ready',
    'organization_id', v_capability.organization_id,
    'payment_id', v_capability.payment_id,
    'billing_intent_id', v_capability.billing_intent_id,
    'checkout_token', v_capability.checkout_token,
    'expires_at', v_capability.expires_at
  );
end
$$;


ALTER FUNCTION public.ensure_billing_payment_checkout_capability(p_payment_id uuid, p_organization_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ensure_billing_payment_checkout_capability(p_payment_id uuid, p_organization_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ensure_billing_payment_checkout_capability(p_payment_id uuid, p_organization_id uuid) IS 'Service-only issuance/rotation RPC. The BFF must authorize organization access before calling.';


--
-- Name: ensure_lead_has_pipeline(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ensure_lead_has_pipeline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se pipeline_id é NULL, buscar pipeline padrão da organização
  IF NEW.pipeline_id IS NULL THEN
    SELECT p.id, s.id INTO NEW.pipeline_id, NEW.stage_id
    FROM public.pipelines p
    JOIN public.stages s ON s.pipeline_id = p.id
    WHERE p.organization_id = NEW.organization_id
      AND p.is_default = true
    ORDER BY s.position ASC
    LIMIT 1;
  -- Se tem pipeline mas não tem stage, pegar primeiro stage
  ELSIF NEW.stage_id IS NULL THEN
    SELECT id INTO NEW.stage_id
    FROM public.stages
    WHERE pipeline_id = NEW.pipeline_id
    ORDER BY position ASC
    LIMIT 1;
  END IF;

  -- Garantir que stage_entered_at seja preenchido
  IF NEW.stage_entered_at IS NULL THEN
    NEW.stage_entered_at := NOW();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.ensure_lead_has_pipeline() OWNER TO postgres;

--
-- Name: ensure_organization_membership(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ensure_organization_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (user_id, organization_id, role, is_active)
    VALUES (NEW.id, NEW.organization_id, COALESCE(NEW.role, 'user'), true)
    ON CONFLICT (user_id, organization_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.ensure_organization_membership() OWNER TO postgres;

--
-- Name: ensure_single_notification_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ensure_single_notification_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_notification_session = true THEN
    UPDATE whatsapp_sessions
    SET is_notification_session = false
    WHERE organization_id = NEW.organization_id
      AND id != NEW.id
      AND is_notification_session = true;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.ensure_single_notification_session() OWNER TO postgres;

--
-- Name: enter_automation_delay_wait(uuid, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enter_automation_delay_wait(p_organization_id uuid, p_execution_id uuid, p_step_id uuid, p_node_key text, p_lease_token text, p_next_execution_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  changed_count integer;
begin
  if p_next_execution_at is null or p_next_execution_at <= now() then
    return false;
  end if;

  perform 1
  from public.automation_executions e
  where e.id = p_execution_id
    and e.organization_id = p_organization_id
    and e.current_node_key = p_node_key
    and e.status = 'running'
    and e.locked_by = p_lease_token
    and e.cancellation_requested_at is null
  for update;
  if not found then return false; end if;

  update public.automation_execution_steps s
  set status = 'waiting',
      output = coalesce(s.output, '{}'::jsonb) || jsonb_build_object(
        'next_execution_at', p_next_execution_at,
        'wait_started_at', s.started_at
      ),
      completed_at = null
  where s.id = p_step_id
    and s.execution_id = p_execution_id
    and s.organization_id = p_organization_id
    and s.node_key = p_node_key
    and s.status = 'running';
  get diagnostics changed_count = row_count;
  if changed_count <> 1 then return false; end if;

  update public.automation_executions e
  set status = 'waiting',
      next_execution_at = p_next_execution_at,
      locked_at = null,
      locked_by = null,
      updated_at = now()
  where e.id = p_execution_id
    and e.organization_id = p_organization_id
    and e.current_node_key = p_node_key
    and e.status = 'running'
    and e.locked_by = p_lease_token
    and e.cancellation_requested_at is null;
  get diagnostics changed_count = row_count;
  if changed_count <> 1 then
    raise exception 'automation_delay_wait_fencing_conflict';
  end if;
  return true;
end;
$$;


ALTER FUNCTION public.enter_automation_delay_wait(p_organization_id uuid, p_execution_id uuid, p_step_id uuid, p_node_key text, p_lease_token text, p_next_execution_at timestamp with time zone) OWNER TO postgres;

--
-- Name: evolution_go_reconcile_notification_receipt(uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.evolution_go_reconcile_notification_receipt(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_status text, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_notification_ids uuid[];
  v_sender_session_id text;
begin
  if session_user not in ('postgres', 'supabase_admin')
    and coalesce(current_setting('role', true), '') <> 'service_role' then
    raise exception 'Notification receipt backend role required' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.whatsapp_sessions as session
    where session.id = p_session_id
      and session.organization_id = p_organization_id
      and session.provider = 'evolution_go'
  ) then
    return jsonb_build_object('outcome', 'invalid_scope');
  end if;
  -- Authentication of a session does not bind a delivery to that sender.
  -- Resolve the same unique target as the existing reconciler, then require
  -- the persisted send result's session. An early or legacy receipt lacking
  -- this evidence stays pending; never infer a sender or resend the message.
  select array_agg(candidate.notification_id) into v_notification_ids
  from (
    select delivery.notification_id from private.notification_deliveries delivery
    where delivery.organization_id = p_organization_id and delivery.channel = 'whatsapp'
      and (delivery.provider_message_id = p_provider_message_id
        or delivery.metadata->>'expected_message_id' = p_provider_message_id)
    order by delivery.notification_id limit 2
  ) candidate;
  if coalesce(cardinality(v_notification_ids), 0) = 0 then
    select array_agg(candidate.id) into v_notification_ids
    from (
      select notification.id from public.notifications notification
      where notification.organization_id = p_organization_id
        and notification.metadata #>> '{dispatch,whatsapp,expected_message_id}' = p_provider_message_id
      order by notification.id limit 2
    ) candidate;
  end if;
  if coalesce(cardinality(v_notification_ids), 0) = 0 then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if cardinality(v_notification_ids) <> 1 then
    return jsonb_build_object('outcome', 'ambiguous');
  end if;
  select notification.metadata #>> '{dispatch,whatsapp,session_id}' into v_sender_session_id
  from public.notifications notification
  where notification.id = v_notification_ids[1] and notification.organization_id = p_organization_id
  for update;
  if nullif(btrim(v_sender_session_id), '') is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if v_sender_session_id <> p_session_id::text then
    return jsonb_build_object('outcome', 'invalid_scope');
  end if;
  return private.reconcile_notification_whatsapp_delivery(
    p_organization_id, p_provider_message_id, p_status, p_occurred_at
  );
end
$$;


ALTER FUNCTION public.evolution_go_reconcile_notification_receipt(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_status text, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION evolution_go_reconcile_notification_receipt(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_status text, p_occurred_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.evolution_go_reconcile_notification_receipt(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_status text, p_occurred_at timestamp with time zone) IS 'Service-only gateway for verified Evolution Go notification receipts in a resolved organization/session. No sends or queue replay.';


--
-- Name: execute_stage_automations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.execute_stage_automations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  automation record;
  action_config jsonb;
  next_status text;
  creation_scope text := pg_catalog.current_setting('vimob.lead_creation_status_scope', true);
  creation_phase text := pg_catalog.current_setting('vimob.lead_creation_status_phase', true);
  request_role text := coalesce(nullif(pg_catalog.current_setting('role', true), 'none'), session_user);
  scoped_creation boolean;
  apply_status boolean;
  target_user_text text;
  target_user_id uuid;
begin
  scoped_creation := creation_scope = new.organization_id::text || '/' || new.id::text
    and (pg_catalog.pg_has_role(request_role, 'postgres', 'member')
      or pg_catalog.pg_has_role(request_role, 'service_role', 'member'));
  apply_status := coalesce(scoped_creation and creation_phase = 'apply', false);
  if tg_op = 'INSERT' then
    if new.stage_id is null then
      return new;
    end if;
  elsif old.stage_id is not distinct from new.stage_id and not apply_status then
    return new;
  end if;

  for automation in
    select stage_automation.*
    from public.stage_automations stage_automation
    where stage_automation.stage_id = new.stage_id
      and stage_automation.organization_id = new.organization_id
      and coalesce(stage_automation.is_active, false) = true
      and stage_automation.trigger_type = 'on_enter'
    order by stage_automation.created_at, stage_automation.id
  loop
    action_config := coalesce(automation.action_config, '{}'::jsonb);

    if automation.automation_type = 'change_deal_status_on_enter' then
      if scoped_creation and creation_phase = 'defer' then continue; end if;
      next_status := lower(btrim(action_config->>'deal_status'));
      if next_status in ('open', 'won', 'lost') then
        new.deal_status := next_status;
        if next_status = 'won' then
          if tg_op = 'INSERT' then
            new.won_at := now();
          elsif old.deal_status is distinct from 'won' then
            new.won_at := now();
          else
            new.won_at := coalesce(old.won_at, new.won_at, now());
          end if;
          new.lost_at := null;
          new.lost_reason := null;
        elsif next_status = 'lost' then
          if tg_op = 'INSERT' then
            new.lost_at := now();
          elsif old.deal_status is distinct from 'lost' then
            new.lost_at := now();
          else
            new.lost_at := coalesce(old.lost_at, new.lost_at, now());
          end if;
          new.won_at := null;
        else
          new.won_at := null;
          new.lost_at := null;
          new.lost_reason := null;
        end if;
      end if;
    elsif automation.automation_type = 'change_assignee_on_enter' then
      if apply_status then continue; end if; -- Already applied on actual INSERT/stage entry.
      target_user_text := btrim(coalesce(action_config->>'target_user_id', ''));
      target_user_id := null;
      if target_user_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        target_user_id := target_user_text::uuid;
      end if;

      if target_user_id is not null and exists (
        select 1
        from public.organization_members member
        join public.users app_user on app_user.id = member.user_id
        where member.organization_id = new.organization_id
          and member.user_id = target_user_id
          and coalesce(member.is_active, false) = true
          and coalesce(app_user.is_active, false) = true
          and member.deleted_at is null
          and (new.team_id is null or exists (
            select 1 from public.team_members tm
            where tm.organization_id = new.organization_id
              and tm.team_id = new.team_id and tm.user_id = target_user_id
              and coalesce(tm.is_active, true) = true
              and tm.membership_generation = member.membership_generation
          ))
      ) then
        new.assigned_user_id := target_user_id;
      end if;
    end if;
  end loop;

  return new;
end;
$_$;


ALTER FUNCTION public.execute_stage_automations() OWNER TO postgres;

--
-- Name: execute_stage_operational_actions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.execute_stage_operational_actions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  v_config public.stage_operational_configs%rowtype;
  v_request_item jsonb;
begin
  select *
  into v_config
  from public.stage_operational_configs
  where stage_id = new.stage_id
    and organization_id = new.organization_id;

  if v_config.id is null
     or jsonb_typeof(coalesce(v_config.automatic_operational_requests, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(v_config.automatic_operational_requests, '[]'::jsonb)) = 0 then
    return new;
  end if;

  for v_request_item in
    select *
    from jsonb_array_elements(v_config.automatic_operational_requests)
  loop
    insert into public.operational_requests (
      organization_id,
      lead_id,
      type,
      title,
      description,
      priority,
      due_date
    )
    values (
      new.organization_id,
      new.id,
      coalesce(v_request_item->>'type', v_config.operation_context),
      v_request_item->>'title',
      v_request_item->>'description',
      coalesce(v_request_item->>'priority', 'medium'),
      now() + (
        coalesce((v_request_item->>'due_days')::integer, 1)
        * interval '1 day'
      )
    );
  end loop;

  insert into public.operational_timelines (
    organization_id,
    lead_id,
    event_type,
    title,
    description
  )
  values (
    new.organization_id,
    new.id,
    'stage_operational_entry',
    'Gatilho Ativado: ' || v_config.operation_context,
    'Lead movido para ' || (
      select name
      from public.stages
      where id = new.stage_id
    )
  );

  return new;
end;
$$;


ALTER FUNCTION public.execute_stage_operational_actions() OWNER TO postgres;

--
-- Name: fail_automation_event(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_automation_event(p_event_id uuid, p_worker_id text, p_error text, p_retry_seconds integer DEFAULT 30) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with changed as (
    update public.automation_event_outbox
    set status = case when attempts >= max_attempts then 'dead_letter' else 'failed' end,
        dead_lettered_at = case when attempts >= max_attempts then now() else null end,
        available_at = now() + make_interval(secs => least(greatest(coalesce(p_retry_seconds, 30), 1), 3600)),
        locked_at = null,
        locked_by = null,
        last_error = left(coalesce(p_error, 'unknown error'), 4000),
        updated_at = now()
    where id = p_event_id and status = 'processing' and locked_by = left(coalesce(p_worker_id, 'worker'), 200)
    returning id
  ) select exists(select 1 from changed);
$$;


ALTER FUNCTION public.fail_automation_event(p_event_id uuid, p_worker_id text, p_error text, p_retry_seconds integer) OWNER TO postgres;

--
-- Name: fail_billing_card_recurrence(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_error text := left(nullif(btrim(coalesce(p_error, '')), ''), 2000);
  v_payment public.asaas_payments%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
begin
  if p_payment_id is null
     or p_lease_id is null
     or v_provider_payment_id is null
     or v_error is null
     or char_length(v_provider_payment_id) > 255 then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
    and provision.provider_payment_id = v_payment.asaas_payment_id
  for update;

  if not found
     or v_provision.status <> 'creating'
     or v_provision.lease_id is distinct from p_lease_id then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  update private.billing_card_recurrence_provisions
  set
    status = 'failed',
    provider_card_credential = null,
    card_last4 = null,
    lease_id = null,
    lease_expires_at = null,
    failed_at = clock_timestamp(),
    last_error = v_error,
    updated_at = clock_timestamp()
  where payment_id = v_provision.payment_id;

  return jsonb_build_object(
    'outcome', 'failed',
    'payment_id', v_provision.payment_id
  );
end
$$;


ALTER FUNCTION public.fail_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_error text) OWNER TO postgres;

--
-- Name: FUNCTION fail_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_error text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fail_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_error text) IS 'Records a deterministic provider rejection, preserving bounded manual retry eligibility.';


--
-- Name: fail_billing_card_recurrence_job(uuid, text, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_billing_card_recurrence_job(p_payment_id uuid, p_worker_id text, p_job_lease_id uuid, p_failure_class text, p_error_code text, p_retry_after_seconds integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_worker_id text := nullif(btrim(coalesce(p_worker_id, '')), '');
  v_failure_class text := lower(nullif(btrim(coalesce(p_failure_class, '')), ''));
  v_error_code text := lower(nullif(btrim(coalesce(p_error_code, '')), ''));
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_now timestamptz := clock_timestamp();
  v_retry_after_seconds integer;
  v_next_attempt_at timestamptz;
  v_dead boolean;
begin
  if p_payment_id is null
     or v_worker_id is null
     or char_length(v_worker_id) > 128
     or v_worker_id !~ '^[A-Za-z0-9._:-]+$'
     or p_job_lease_id is null
     or v_failure_class not in ('deterministic', 'ambiguous', 'permanent')
     or v_error_code is null
     or v_error_code !~ '^[a-z0-9_]{1,80}$'
     or (
       p_retry_after_seconds is not null
       and p_retry_after_seconds not between 30 and 86400
     ) then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = p_payment_id
    and provision.job_status = 'processing'
    and provision.job_locked_by = v_worker_id
    and provision.job_lease_id = p_job_lease_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  if v_provision.job_action = 'create'
     and v_failure_class = 'ambiguous'
     and v_provision.provider_request_started_at is null then
    return jsonb_build_object('outcome', 'provider_request_not_started');
  end if;

  v_dead := v_failure_class = 'permanent'
    or v_provision.job_attempts >= v_provision.job_max_attempts;
  v_retry_after_seconds := coalesce(
    p_retry_after_seconds,
    least(
      21600,
      (
        300 * power(
          2,
          least(greatest(v_provision.job_attempts - 1, 0), 6)
        )
      )::integer
    )
  );
  v_next_attempt_at := v_now + make_interval(secs => v_retry_after_seconds);

  update private.billing_card_recurrence_provisions as provision
  set
    status = case
      when provision.job_action = 'create' and v_dead then 'failed'
      when provision.job_action = 'create'
        and v_failure_class = 'ambiguous' then 'recovering'
      when provision.job_action = 'create' then 'prepared'
      else provision.status
    end,
    provider_card_credential = case
      when provision.job_action = 'create' and v_dead then null
      else provision.provider_card_credential
    end,
    card_last4 = case
      when provision.job_action = 'create' and v_dead then null
      else provision.card_last4
    end,
    lease_id = null,
    lease_expires_at = null,
    provider_request_started_at = provision.provider_request_started_at,
    recovering_at = case
      when provision.job_action = 'create'
        and v_failure_class = 'ambiguous'
      then coalesce(provision.recovering_at, v_now)
      when provision.job_action = 'create' and not v_dead then null
      else provision.recovering_at
    end,
    failed_at = case
      when provision.job_action = 'create' and v_dead
        then coalesce(provision.failed_at, v_now)
      else provision.failed_at
    end,
    last_error = v_error_code,
    job_status = case when v_dead then 'dead' else 'retry' end,
    job_next_attempt_at = case
      when v_dead then provision.job_next_attempt_at
      else v_next_attempt_at
    end,
    job_locked_at = null,
    job_lock_expires_at = null,
    job_locked_by = null,
    job_lease_id = null,
    job_dead_lettered_at = case
      when v_dead then coalesce(provision.job_dead_lettered_at, v_now)
      else null
    end,
    job_last_error_code = v_error_code,
    updated_at = v_now
  where provision.payment_id = v_provision.payment_id
    and provision.job_status = 'processing'
    and provision.job_locked_by = v_worker_id
    and provision.job_lease_id = p_job_lease_id;

  if not found then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  if v_dead then
    insert into public.error_events (
      organization_id,
      source,
      severity,
      fingerprint,
      message,
      category,
      error_code,
      component,
      metadata,
      occurred_at
    )
    values (
      v_provision.organization_id,
      'backend',
      'critical',
      'billing_card_recurrence_dead:' || v_provision.payment_id::text,
      'Billing card recurrence job entered the dead letter state',
      'billing',
      'billing_card_recurrence_job_dead',
      'billing_card_recurrence_worker',
      jsonb_build_object(
        'payment_id', v_provision.payment_id,
        'action', v_provision.job_action,
        'attempts', v_provision.job_attempts,
        'failure_class', v_failure_class,
        'error_code', v_error_code
      ),
      v_now
    );
  end if;

  return jsonb_build_object(
    'outcome', case when v_dead then 'dead' else 'retry' end,
    'payment_id', v_provision.payment_id,
    'action', v_provision.job_action,
    'failure_class', v_failure_class,
    'error_code', v_error_code,
    'next_attempt_at', case when v_dead then null else v_next_attempt_at end
  );
end
$_$;


ALTER FUNCTION public.fail_billing_card_recurrence_job(p_payment_id uuid, p_worker_id text, p_job_lease_id uuid, p_failure_class text, p_error_code text, p_retry_after_seconds integer) OWNER TO postgres;

--
-- Name: fail_billing_checkout_intent(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_billing_checkout_intent(p_intent_id uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_updated integer := 0;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  update private.billing_checkout_intents
  set
    status = 'failed',
    failed_at = now(),
    last_error = left(coalesce(nullif(btrim(p_error), ''), 'provider_rejected'), 1000),
    updated_at = now()
  where id = p_intent_id
    and status = 'creating'
    and provider_payment_id is null
    and provider_subscription_id is null;

  get diagnostics v_updated = row_count;
  return jsonb_build_object(
    'outcome',
    case when v_updated = 1 then 'failed' else 'unchanged' end
  );
end;
$$;


ALTER FUNCTION public.fail_billing_checkout_intent(p_intent_id uuid, p_error text) OWNER TO postgres;

--
-- Name: fail_billing_payment_checkout_cancellation(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_billing_payment_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_failure_class text, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_failure_class text := lower(nullif(btrim(coalesce(p_failure_class, '')), ''));
  v_error_code text := lower(nullif(btrim(coalesce(p_error_code, '')), ''));
  v_claim private.billing_payment_checkout_cancellations%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_manual_review boolean;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_organization_id is null
     or p_intent_id is null
     or p_claim_token is null
     or v_failure_class not in ('retryable', 'permanent')
     or v_error_code is null
     or v_error_code !~ '^[a-z0-9_]{1,80}$' then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select cancellation.*
  into v_claim
  from private.billing_payment_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  perform private.lock_asaas_billing_resources(
    v_claim.provider_payment_id,
    null
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = v_claim.payment_id
    and payment.organization_id = p_organization_id
    and payment.billing_intent_id = p_intent_id
    and payment.asaas_payment_id = v_claim.provider_payment_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  select capability.*
  into v_capability
  from public.billing_payment_checkout_capabilities as capability
  where capability.payment_id = v_payment.id
    and capability.asaas_payment_id = v_payment.asaas_payment_id
    and capability.organization_id = v_payment.organization_id
    and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  select cancellation.*
  into v_claim
  from private.billing_payment_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id
  for update;
  if not found
     or v_claim.claim_token is distinct from p_claim_token then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;
  if v_claim.finalized_at is not null then
    return jsonb_build_object(
      'outcome', 'already_finalized',
      'final_outcome', v_claim.final_outcome,
      'last_error_code', v_claim.last_error_code
    );
  end if;

  if private.billing_payment_checkout_is_paid(v_payment.status) then
    update private.billing_payment_checkout_cancellations
    set
      finalized_at = now(),
      final_outcome = 'paid_before_delete',
      paid_won_at = now(),
      manual_review_at = null,
      updated_at = now()
    where intent_id = p_intent_id
      and finalized_at is null;

    update public.billing_payment_checkout_capabilities
    set
      revoked_at = coalesce(revoked_at, v_now),
      attempt_lease_id = null,
      attempt_lease_expires_at = null,
      updated_at = v_now
    where payment_id = v_payment.id;

    return jsonb_build_object(
      'outcome', 'paid_before_delete',
      'payment_id', v_payment.asaas_payment_id
    );
  end if;

  v_manual_review := v_failure_class = 'permanent'
    or v_claim.claim_attempts >= v_claim.max_attempts;

  update private.billing_payment_checkout_cancellations
  set
    lease_expires_at = case
      when v_manual_review then lease_expires_at
      else greatest(v_now, claimed_at + interval '1 microsecond')
    end,
    finalized_at = case when v_manual_review then now() else null end,
    final_outcome = case when v_manual_review then 'manual_review' else null end,
    manual_review_at = case when v_manual_review then now() else null end,
    last_error_code = v_error_code,
    updated_at = now()
  where intent_id = p_intent_id
    and finalized_at is null
    and claim_token = p_claim_token;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  if v_manual_review then
    update public.billing_payment_checkout_capabilities
    set
      revoked_at = coalesce(revoked_at, v_now),
      attempt_lease_id = null,
      attempt_lease_expires_at = null,
      updated_at = v_now
    where payment_id = v_payment.id;

    insert into public.error_events (
      organization_id,
      source,
      severity,
      fingerprint,
      message,
      category,
      error_code,
      component,
      metadata,
      occurred_at
    ) values (
      p_organization_id,
      'backend',
      'critical',
      'billing_payment_cancellation_manual:' || p_intent_id::text,
      'Billing payment cancellation requires assisted review',
      'billing',
      'billing_payment_cancellation_manual_review',
      'billing_payment_cancellation_worker',
      jsonb_build_object(
        'billing_intent_id', p_intent_id,
        'payment_id', v_claim.provider_payment_id,
        'attempts', v_claim.claim_attempts,
        'error_code', v_error_code
      ),
      v_now
    )
    on conflict do nothing;
  end if;

  return jsonb_build_object(
    'outcome', case when v_manual_review then 'manual_review' else 'retry' end,
    'payment_id', v_claim.provider_payment_id,
    'attempts', v_claim.claim_attempts,
    'max_attempts', v_claim.max_attempts,
    'error_code', v_error_code
  );
end
$_$;


ALTER FUNCTION public.fail_billing_payment_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_failure_class text, p_error_code text) OWNER TO postgres;

--
-- Name: fail_billing_subscription_card_update_capture(uuid, uuid, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_billing_subscription_card_update_capture(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_attempt_lease_id uuid, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_error_code text := lower(nullif(btrim(coalesce(p_error_code, '')), ''));
  v_hint private.billing_subscription_card_update_jobs%rowtype;
  v_job private.billing_subscription_card_update_jobs%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or p_generation is null
     or p_generation <= 0
     or p_attempt_lease_id is null
     or v_error_code is null
     or v_error_code !~ '^[a-z0-9_]{1,80}$' then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_hint
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_hint.provider_payment_id,
    v_hint.provider_subscription_id
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = v_hint.payment_id
    and payment.organization_id = p_organization_id
    and payment.asaas_payment_id = v_hint.provider_payment_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  if v_job.status in ('succeeded', 'cancelled', 'dead') then
    return jsonb_build_object(
      'outcome', 'already_finalized',
      'status', v_job.status,
      'last_error_code', v_job.last_error_code
    );
  end if;
  if v_job.mode <> 'settled_payment'
     or v_job.status <> 'awaiting_payment'
     or v_job.capture_request_started_at is null
     or v_job.capture_attempt_lease_id is distinct from p_attempt_lease_id
     or v_job.credential_attempt_lease_id is distinct from p_attempt_lease_id
     or v_job.provider_request_started_at is not null then
    return jsonb_build_object('outcome', 'lost_capture');
  end if;
  if private.billing_payment_checkout_is_paid(v_payment.status) then
    return jsonb_build_object('outcome', 'payment_already_paid');
  end if;
  if private.billing_payment_checkout_is_processing(v_payment.status)
     or private.billing_payment_checkout_is_reversal(v_payment.status) then
    return jsonb_build_object('outcome', 'capture_outcome_ambiguous');
  end if;

  update private.billing_subscription_card_update_jobs
  set
    status = 'cancelled',
    provider_card_credential = null,
    card_last4 = null,
    credential_attempt_lease_id = null,
    capture_request_started_at = null,
    capture_attempt_lease_id = null,
    capture_manual_review_at = null,
    lease_id = null,
    lease_owner = null,
    lease_started_at = null,
    lease_expires_at = null,
    last_error_code = v_error_code,
    cancelled_at = v_now,
    updated_at = v_now
  where id = v_job.id
    and generation = p_generation
    and status = 'awaiting_payment'
    and capture_attempt_lease_id = p_attempt_lease_id;
  if not found then
    return jsonb_build_object('outcome', 'lost_capture');
  end if;

  update public.billing_payment_checkout_capabilities
  set
    attempt_lease_id = null,
    attempt_lease_expires_at = null,
    updated_at = v_now
  where payment_id = v_payment.id
    and organization_id = p_organization_id
    and attempt_lease_id = p_attempt_lease_id
    and revoked_at is null;

  return jsonb_build_object(
    'outcome', 'capture_refused',
    'job_id', v_job.id,
    'payment_id', v_payment.id,
    'provider_payment_id', v_payment.asaas_payment_id,
    'last_error_code', v_error_code
  );
end
$_$;


ALTER FUNCTION public.fail_billing_subscription_card_update_capture(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_attempt_lease_id uuid, p_error_code text) OWNER TO postgres;

--
-- Name: fail_billing_subscription_card_update_job(uuid, uuid, bigint, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_billing_subscription_card_update_job(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_job_lease_id uuid, p_failure_class text, p_error_code text, p_retry_after_seconds integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_failure_class text := lower(nullif(
    btrim(coalesce(p_failure_class, '')),
    ''
  ));
  v_error_code text := lower(nullif(btrim(coalesce(p_error_code, '')), ''));
  v_hint private.billing_subscription_card_update_jobs%rowtype;
  v_job private.billing_subscription_card_update_jobs%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_local_removed boolean := false;
  v_has_marker boolean := false;
  v_retry boolean := false;
  v_manual boolean := false;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or p_generation is null
     or p_generation <= 0
     or p_job_lease_id is null
     or v_failure_class not in (
       'retryable', 'permanent', 'not_found', 'ambiguous'
     )
     or v_error_code is null
     or v_error_code !~ '^[a-z0-9_]{1,80}$'
     or p_retry_after_seconds not between 1 and 3600 then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_hint
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_hint.provider_payment_id,
    v_hint.provider_subscription_id
  );

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
  for update;
  if not found then
    v_local_removed := true;
  end if;

  select subscription.*
  into v_subscription
  from public.subscriptions as subscription
  where subscription.id = v_hint.subscription_id
  for update;
  if not found then
    v_local_removed := true;
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  if v_job.status in ('succeeded', 'cancelled', 'dead') then
    return jsonb_build_object(
      'outcome', 'already_finalized',
      'status', v_job.status,
      'last_error_code', v_job.last_error_code
    );
  end if;
  if v_job.status <> 'processing'
     or v_job.lease_id is distinct from p_job_lease_id then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;
  -- Historical markers belong to prior leases and mean the same token must be
  -- replayed. They must not prevent the fresh worker from reporting a
  -- decrypt/identity-preflight failure before marking its own PUT.
  v_has_marker := v_job.provider_request_started_at is not null
    and v_job.provider_request_lease_id = p_job_lease_id;

  v_local_removed := v_local_removed
    or v_org.asaas_subscription_id
      is distinct from v_job.provider_subscription_id
    or v_subscription.provider_subscription_id
      is distinct from v_job.provider_subscription_id
    or lower(coalesce(v_subscription.status, ''))
      in ('cancelled', 'canceled', 'deleted');

  if v_failure_class in ('retryable', 'ambiguous')
     and v_job.expires_at > v_now
     and v_job.attempts < v_job.max_attempts then
    v_retry := true;
  elsif v_failure_class = 'not_found' and v_local_removed then
    v_retry := false;
    v_manual := false;
  elsif v_failure_class = 'permanent' then
    v_retry := false;
    v_manual := v_job.provider_outcome_ambiguous_at is not null;
  elsif v_failure_class = 'retryable' then
    v_retry := false;
    v_manual := v_job.provider_outcome_ambiguous_at is not null;
  elsif v_failure_class = 'ambiguous' then
    v_retry := false;
    v_manual := v_has_marker
      or v_job.provider_outcome_ambiguous_at is not null;
  else
    v_retry := false;
    v_manual := true;
  end if;

  if v_retry then
    update private.billing_subscription_card_update_jobs
    set
      status = 'retry',
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      next_attempt_at = v_now
        + make_interval(secs => p_retry_after_seconds),
      provider_outcome_ambiguous_at = case
        when v_has_marker and v_failure_class = 'ambiguous'
          then coalesce(provider_outcome_ambiguous_at, v_now)
        else provider_outcome_ambiguous_at
      end,
      last_error_code = v_error_code,
      updated_at = v_now
    where id = v_job.id
      and status = 'processing'
      and lease_id = p_job_lease_id;
    if not found then
      return jsonb_build_object('outcome', 'lost_claim');
    end if;

    return jsonb_build_object(
      'outcome', 'retry',
      'job_id', v_job.id,
      'attempts', v_job.attempts,
      'max_attempts', v_job.max_attempts,
      'next_attempt_at', v_now + make_interval(secs => p_retry_after_seconds),
      'replay_same_credential', true
    );
  end if;

  update private.billing_subscription_card_update_jobs
  set
    status = case
      when v_failure_class = 'not_found' and v_local_removed
        then 'cancelled'
      else 'dead'
    end,
    provider_card_credential = null,
    credential_attempt_lease_id = null,
    lease_id = null,
    lease_owner = null,
    lease_started_at = null,
    lease_expires_at = null,
    provider_outcome_ambiguous_at = case
      when v_has_marker and v_failure_class = 'ambiguous'
        then coalesce(provider_outcome_ambiguous_at, v_now)
      else provider_outcome_ambiguous_at
    end,
    last_error_code = v_error_code,
    cancelled_at = case
      when v_failure_class = 'not_found' and v_local_removed then v_now
      else null
    end,
    manual_review_at = case when v_manual then v_now else null end,
    dead_lettered_at = case
      when v_failure_class = 'not_found' and v_local_removed then null
      else v_now
    end,
    updated_at = v_now
  where id = v_job.id
    and status = 'processing'
    and lease_id = p_job_lease_id;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  if v_manual then
    insert into public.error_events (
      organization_id,
      source,
      severity,
      fingerprint,
      message,
      category,
      error_code,
      component,
      metadata,
      occurred_at
    ) values (
      p_organization_id,
      'backend',
      'critical',
      'billing_subscription_card_update_manual:' || p_job_id::text,
      'Subscription card update requires assisted review',
      'billing',
      'billing_subscription_card_update_manual_review',
      'billing_subscription_card_update_worker',
      jsonb_build_object(
        'job_id', p_job_id,
        'generation', p_generation,
        'subscription_id', v_job.provider_subscription_id,
        'failure_class', v_failure_class,
        'error_code', v_error_code,
        'provider_request_attempts', v_job.provider_request_attempts
      ),
      v_now
    )
    on conflict do nothing;
  end if;

  return jsonb_build_object(
    'outcome', case
      when v_failure_class = 'not_found' and v_local_removed then 'cancelled'
      when v_manual then 'manual_review'
      else 'failed'
    end,
    'job_id', v_job.id,
    'last_error_code', v_error_code
  );
end
$_$;


ALTER FUNCTION public.fail_billing_subscription_card_update_job(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_job_lease_id uuid, p_failure_class text, p_error_code text, p_retry_after_seconds integer) OWNER TO postgres;

--
-- Name: fail_billing_subscription_checkout_cancellation(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_billing_subscription_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_failure_class text, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_failure_class text := lower(btrim(coalesce(p_failure_class, '')));
  v_error_code text := lower(btrim(coalesce(p_error_code, '')));
  v_hint private.billing_subscription_checkout_cancellations%rowtype;
  v_claim private.billing_subscription_checkout_cancellations%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_organization_id is null
     or p_intent_id is null
     or p_claim_token is null
     or v_failure_class not in ('retryable', 'permanent', 'ambiguous')
     or v_error_code !~ '^[a-z0-9_]{1,80}$' then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select cancellation.*
  into v_hint
  from private.billing_subscription_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'claim_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_hint.provider_payment_id,
    v_hint.provider_subscription_id
  );

  select cancellation.*
  into v_claim
  from private.billing_subscription_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'claim_not_found');
  end if;
  if v_claim.finalized_at is not null then
    return jsonb_build_object(
      'outcome', case
        when v_claim.final_outcome = 'manual_review' then 'manual_review'
        else 'already_finalized'
      end,
      'final_outcome', v_claim.final_outcome,
      'error_code', v_claim.last_error_code
    );
  end if;
  if v_claim.claim_token is distinct from p_claim_token then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  if v_failure_class = 'retryable'
     and v_claim.claim_attempts < v_claim.max_attempts then
    update private.billing_subscription_checkout_cancellations as cancellation
    set last_error_code = v_error_code, updated_at = v_now
    where cancellation.intent_id = p_intent_id
      and cancellation.organization_id = p_organization_id
      and cancellation.claim_token = p_claim_token
      and cancellation.finalized_at is null;

    return jsonb_build_object(
      'outcome', 'retry',
      'attempts', v_claim.claim_attempts,
      'max_attempts', v_claim.max_attempts,
      'retry_after_seconds', greatest(
        1,
        case
          when v_claim.lease_expires_at > v_now
            then ceil(extract(epoch from (
              v_claim.lease_expires_at - v_now
            )))::integer
          else 1
        end
      )
    );
  end if;

  update private.billing_subscription_checkout_cancellations as cancellation
  set
    finalized_at = v_now,
    final_outcome = 'manual_review',
    last_error_code = v_error_code,
    manual_review_at = v_now,
    updated_at = v_now
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id
    and cancellation.claim_token = p_claim_token
    and cancellation.finalized_at is null;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  update public.billing_payment_checkout_capabilities as capability
  set
    revoked_at = coalesce(capability.revoked_at, v_now),
    attempt_lease_id = null,
    attempt_lease_expires_at = null,
    updated_at = v_now
  where capability.organization_id = p_organization_id
    and capability.billing_intent_id = p_intent_id;

  insert into public.error_events (
    organization_id, source, severity, fingerprint, message, category,
    error_code, component, metadata, occurred_at
  ) values (
    p_organization_id,
    'backend',
    'critical',
    'billing_subscription_cancellation_manual:' || p_intent_id::text,
    'Subscription deletion could not be proven against the bound provider tuple',
    'billing',
    'billing_subscription_cancellation_manual_review',
    'billing_subscription_cancellation_worker',
    jsonb_build_object(
      'intent_id', p_intent_id,
      'subscription_id', v_claim.provider_subscription_id,
      'failure_class', v_failure_class,
      'error_code', v_error_code,
      'attempts', v_claim.claim_attempts,
      'max_attempts', v_claim.max_attempts
    ),
    v_now
  );

  return jsonb_build_object(
    'outcome', 'manual_review',
    'final_outcome', 'manual_review',
    'error_code', v_error_code,
    'attempts', v_claim.claim_attempts,
    'max_attempts', v_claim.max_attempts
  );
end
$_$;


ALTER FUNCTION public.fail_billing_subscription_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_failure_class text, p_error_code text) OWNER TO postgres;

--
-- Name: fail_prepared_billing_card_recurrence(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_prepared_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_payment public.asaas_payments%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if p_payment_id is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255 then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  -- Preserve the recurrence lock order used by every sibling RPC: payment,
  -- then exact provision. A provider id mismatch reveals no adjacent row.
  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
    and provision.provider_payment_id = v_payment.asaas_payment_id
    and provision.organization_id = v_payment.organization_id
    and provision.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'provision_not_found');
  end if;

  if v_provision.status = 'completed' then
    return jsonb_build_object(
      'outcome', 'already_completed',
      'subscription_id', v_provision.provider_subscription_id
    );
  end if;

  if v_provision.status = 'failed' then
    return jsonb_build_object('outcome', 'already_failed');
  end if;

  if v_provision.status <> 'prepared'
     or v_provision.lease_id is not null
     or v_provision.lease_expires_at is not null then
    return jsonb_build_object('outcome', 'state_not_terminalizable');
  end if;

  update private.billing_card_recurrence_provisions as provision
  set
    status = 'failed',
    provider_card_credential = null,
    card_last4 = null,
    lease_id = null,
    lease_expires_at = null,
    failed_at = v_now,
    last_error = 'prepared_recurrence_not_created',
    updated_at = v_now
  where provision.payment_id = v_provision.payment_id
    and provision.provider_payment_id = v_provision.provider_payment_id
    and provision.status = 'prepared'
    and provision.lease_id is null
    and provision.lease_expires_at is null;

  if not found then
    return jsonb_build_object('outcome', 'state_changed');
  end if;

  return jsonb_build_object(
    'outcome', 'failed',
    'payment_id', v_provision.payment_id
  );
end
$$;


ALTER FUNCTION public.fail_prepared_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text) OWNER TO postgres;

--
-- Name: FUNCTION fail_prepared_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fail_prepared_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text) IS 'Service-only fail-closed terminalization for an exact recurrence provision that is still prepared and has no lease; accepts no sensitive provider payload.';


--
-- Name: finalize_billing_organization_asaas_cleanup(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_billing_organization_asaas_cleanup(p_organization_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_claim private.billing_organization_asaas_cleanup_claims%rowtype;
  v_now timestamptz := clock_timestamp();
  v_remaining_count integer := 0;
  v_inventory_issue text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_organization_id is null or p_claim_token is null then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select cleanup.*
  into v_claim
  from private.billing_organization_asaas_cleanup_claims as cleanup
  where cleanup.organization_id = p_organization_id
    and cleanup.claim_token = p_claim_token;
  if not found then
    return jsonb_build_object('outcome', 'claim_not_found');
  end if;

  perform private.lock_asaas_cleanup_inventory(
    v_claim.provider_payment_ids,
    case when v_claim.provider_subscription_id is null then '{}'::text[]
      else array[v_claim.provider_subscription_id] end,
    case when v_claim.provider_customer_id is null then '{}'::text[]
      else array[v_claim.provider_customer_id] end
  );

  perform organization_row.id
  from public.organizations as organization_row
  where organization_row.id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;

  select cleanup.*
  into v_claim
  from private.billing_organization_asaas_cleanup_claims as cleanup
  where cleanup.organization_id = p_organization_id
    and cleanup.claim_token = p_claim_token
  for update;
  if not found then
    return jsonb_build_object('outcome', 'claim_not_found');
  end if;

  v_inventory_issue := private.billing_organization_cleanup_inventory_issue(
    p_organization_id,
    p_claim_token
  );
  if v_inventory_issue is not null then
    return jsonb_build_object(
      'outcome', 'manual_review',
      'reason', v_inventory_issue
    );
  end if;

  if v_claim.completed_at is not null then
    return jsonb_build_object('outcome', 'already_completed');
  end if;

  if exists (
    select 1
    from private.billing_organization_asaas_cleanup_resources as resource
    where resource.organization_id = p_organization_id
      and resource.claim_token = p_claim_token
      and resource.status = 'manual_review'
  ) then
    return jsonb_build_object(
      'outcome', 'manual_review',
      'reason', 'provider_resource_delete_not_proven'
    );
  end if;

  select count(*)::integer
  into v_remaining_count
  from private.billing_organization_asaas_cleanup_resources as resource
  where resource.organization_id = p_organization_id
    and resource.claim_token = p_claim_token
    and resource.status <> 'succeeded';
  if v_remaining_count > 0 then
    return jsonb_build_object(
      'outcome', 'resources_pending',
      'remaining_count', v_remaining_count
    );
  end if;

  update private.billing_organization_asaas_cleanup_claims
  set completed_at = v_now, updated_at = v_now
  where organization_id = p_organization_id
    and claim_token = p_claim_token
    and completed_at is null;

  return jsonb_build_object(
    'outcome', 'completed',
    'organization_id', p_organization_id
  );
end
$$;


ALTER FUNCTION public.finalize_billing_organization_asaas_cleanup(p_organization_id uuid, p_claim_token uuid) OWNER TO postgres;

--
-- Name: finalize_billing_payment_checkout_cancellation(uuid, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_billing_payment_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_provider_payment_id text, p_provider_delete_result text, p_provider_deleted_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(
    btrim(coalesce(p_provider_payment_id, '')),
    ''
  );
  v_delete_result text := lower(btrim(coalesce(p_provider_delete_result, '')));
  v_claim private.billing_payment_checkout_cancellations%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_org public.organizations%rowtype;
  v_intent private.billing_checkout_intents%rowtype;
  v_paid boolean := false;
  v_customer_id text;
  v_billing_type text;
  v_payment_status text;
  v_manual_reason text;
  v_confirmation jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_organization_id is null
     or p_intent_id is null
     or p_claim_token is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255
     or v_delete_result not in ('deleted', 'not_found', 'paid')
     or (
       v_delete_result = 'paid'
       and p_provider_deleted_at is not null
     )
     or (
       v_delete_result in ('deleted', 'not_found')
       and p_provider_deleted_at is null
     )
     or p_provider_deleted_at > v_now + interval '5 minutes' then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select cancellation.*
  into v_claim
  from private.billing_payment_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;
  if v_claim.provider_payment_id is distinct from v_provider_payment_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'payment'
    );
  end if;

  perform private.lock_asaas_billing_resources(v_provider_payment_id, null);

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = v_claim.payment_id
    and payment.organization_id = p_organization_id
    and payment.billing_intent_id = p_intent_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  select capability.*
  into v_capability
  from public.billing_payment_checkout_capabilities as capability
  where capability.payment_id = v_payment.id
    and capability.asaas_payment_id = v_payment.asaas_payment_id
    and capability.organization_id = v_payment.organization_id
    and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  select cancellation.*
  into v_claim
  from private.billing_payment_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;
  if v_claim.provider_payment_id is distinct from v_provider_payment_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'payment'
    );
  end if;
  if v_claim.finalized_at is not null then
    return jsonb_build_object(
      'outcome', 'already_finalized',
      'final_outcome', v_claim.final_outcome,
      'provider_delete_result', v_claim.provider_delete_result
    );
  end if;
  if v_claim.claim_token is distinct from p_claim_token then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;
  if v_delete_result = 'deleted'
     and v_claim.provider_delete_started_at is null then
    return jsonb_build_object('outcome', 'delete_not_started');
  end if;
  if v_delete_result = 'deleted'
     and p_provider_deleted_at < v_claim.provider_delete_started_at then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  select intent.*
  into v_intent
  from private.billing_checkout_intents as intent
  where intent.id = p_intent_id
    and intent.organization_id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  v_paid := v_intent.status = 'confirmed'
    or private.billing_payment_checkout_is_paid(v_payment.status);

  if v_delete_result = 'paid' and not v_paid then
    return jsonb_build_object('outcome', 'payment_not_paid');
  end if;

  -- Paid evidence wins first. Otherwise, never use a provider DELETE/404 ack
  -- to cancel a mutable intent that now points at another payment tuple.
  -- Processing after the provider boundary is ambiguous (not a safe retry),
  -- while the provider's cancelled trio is an idempotent terminal success.
  if not v_paid then
    v_customer_id := nullif(btrim(coalesce(
      v_intent.provider_customer_id,
      v_org.asaas_customer_id,
      v_payment.asaas_customer_id,
      ''
    )), '');
    v_billing_type := upper(btrim(coalesce(v_intent.billing_method, '')));
    v_payment_status := upper(btrim(coalesce(v_payment.status, '')));

    if private.billing_payment_checkout_is_processing(v_payment.status) then
      v_manual_reason := 'payment_processing_after_delete_ack';
    elsif (
      (
        v_intent.provider_payment_id is not null
        and v_intent.provider_payment_id
          is distinct from v_claim.provider_payment_id
      )
      or v_intent.provider_subscription_id is not null
      or v_payment.asaas_subscription_id is not null
      or v_customer_id is distinct from v_claim.provider_customer_id
      or (
        v_org.asaas_customer_id is not null
        and btrim(v_org.asaas_customer_id)
          is distinct from v_claim.provider_customer_id
      )
      or (
        v_payment.asaas_customer_id is not null
        and btrim(v_payment.asaas_customer_id)
          is distinct from v_claim.provider_customer_id
      )
      or btrim(coalesce(v_intent.external_reference, ''))
        is distinct from v_claim.external_reference
      or round(v_intent.amount::numeric, 2)
        is distinct from round(v_claim.amount::numeric, 2)
      or round(v_payment.value::numeric, 2)
        is distinct from round(v_claim.amount::numeric, 2)
      or v_billing_type is distinct from v_claim.billing_type
      or upper(btrim(coalesce(v_payment.billing_type, '')))
        is distinct from v_claim.billing_type
      or v_payment.due_date is distinct from v_claim.due_date
      or v_intent.status not in ('creating', 'pending', 'cancelled')
      or (
        not private.billing_payment_checkout_is_actionable(v_payment.status)
        and v_payment_status not in ('CANCELED', 'CANCELLED', 'DELETED')
      )
    ) then
      v_manual_reason := 'cancellation_frozen_snapshot_mismatch';
    end if;

    if v_manual_reason is not null then
      update private.billing_payment_checkout_cancellations
      set
        finalized_at = v_now,
        final_outcome = 'manual_review',
        manual_review_at = v_now,
        last_error_code = v_manual_reason,
        provider_deleted_at = case
          when v_delete_result = 'paid' then provider_deleted_at
          else least(p_provider_deleted_at, v_now)
        end,
        provider_delete_result = nullif(v_delete_result, 'paid'),
        updated_at = v_now
      where intent_id = p_intent_id
        and organization_id = p_organization_id
        and claim_token = p_claim_token
        and finalized_at is null;

      update public.billing_payment_checkout_capabilities
      set
        revoked_at = coalesce(revoked_at, v_now),
        attempt_lease_id = null,
        attempt_lease_expires_at = null,
        updated_at = v_now
      where payment_id = v_payment.id
        and organization_id = p_organization_id;

      insert into public.error_events (
        organization_id,
        source,
        severity,
        fingerprint,
        message,
        category,
        error_code,
        component,
        metadata,
        occurred_at
      ) values (
        p_organization_id,
        'backend',
        'critical',
        'billing_payment_cancellation_manual:' || p_intent_id::text,
        'Billing payment cancellation requires assisted review',
        'billing',
        'billing_payment_cancellation_manual_review',
        'billing_payment_cancellation_worker',
        jsonb_build_object(
          'billing_intent_id', p_intent_id,
          'payment_id', v_claim.provider_payment_id,
          'stage', 'finalize_frozen_snapshot',
          'error_code', v_manual_reason,
          'provider_delete_result', v_delete_result
        ),
        v_now
      )
      on conflict do nothing;

      return jsonb_build_object(
        'outcome', 'manual_review',
        'last_error_code', v_manual_reason,
        'provider_delete_result', nullif(v_delete_result, 'paid')
      );
    end if;
  end if;

  if v_paid then
    if v_intent.status <> 'confirmed' then
      v_confirmation := private.confirm_billing_checkout_intent(
        v_payment.asaas_payment_id,
        null,
        v_payment.status,
        v_payment.value
      );
    end if;

    update private.billing_payment_checkout_cancellations
    set
      provider_deleted_at = case
        when v_delete_result = 'paid' then null
        else least(p_provider_deleted_at, v_now)
      end,
      provider_delete_result = case
        when v_delete_result = 'paid' then null
        else v_delete_result
      end,
      finalized_at = v_now,
      final_outcome = case
        when v_delete_result = 'paid' then 'paid_before_delete'
        else 'paid_after_delete'
      end,
      paid_won_at = v_now,
      updated_at = v_now
    where intent_id = p_intent_id;
  else
    update private.billing_checkout_intents
    set
      status = 'cancelled',
      cancelled_at = coalesce(cancelled_at, v_now),
      last_error = 'provider_payment_cancelled_after_claim',
      updated_at = v_now
    where id = p_intent_id
      and organization_id = p_organization_id
      and status <> 'confirmed';

    if not found then
      return jsonb_build_object('outcome', 'lost_claim');
    end if;

    update public.asaas_payments
    set
      status = 'CANCELED',
      raw_event = coalesce(raw_event, '{}'::jsonb) || jsonb_build_object(
        'local_cancellation', jsonb_build_object(
          'source', 'claimed_payment_checkout_cancellation',
          'provider_delete_result', v_delete_result,
          'recorded_at', v_now
        )
      ),
      updated_at = v_now
    where id = v_payment.id
      and organization_id = p_organization_id
      and billing_intent_id = p_intent_id
      and asaas_payment_id = v_provider_payment_id
      and not private.billing_payment_checkout_is_paid(status);

    update private.billing_payment_checkout_cancellations
    set
      provider_deleted_at = least(p_provider_deleted_at, v_now),
      provider_delete_result = v_delete_result,
      finalized_at = v_now,
      final_outcome = 'cancelled',
      paid_won_at = null,
      updated_at = v_now
    where intent_id = p_intent_id;
  end if;

  update public.billing_payment_checkout_capabilities
  set
    revoked_at = coalesce(revoked_at, v_now),
    attempt_lease_id = null,
    attempt_lease_expires_at = null,
    updated_at = v_now
  where payment_id = v_payment.id
    and organization_id = p_organization_id
    and billing_intent_id = p_intent_id;

  insert into public.subscription_logs (
    organization_id, event_type, status, metadata
  ) values (
    p_organization_id,
    'provider_payment_checkout_cancelled',
    case when v_paid then 'active' else 'cancelled' end,
    jsonb_build_object(
      'billing_intent_id', p_intent_id,
      'payment_id', v_provider_payment_id,
      'provider_deleted_at', case
        when v_delete_result = 'paid' then null
        else least(p_provider_deleted_at, v_now)
      end,
      'provider_delete_result', nullif(v_delete_result, 'paid'),
      'outcome', case
        when v_paid and v_delete_result = 'paid' then 'paid_before_delete'
        when v_paid then 'paid_after_delete'
        else 'cancelled'
      end
    )
  );

  return jsonb_build_object(
    'outcome', case
      when v_paid and v_delete_result = 'paid' then 'paid_before_delete'
      when v_paid then 'paid_after_delete'
      else 'cancelled'
    end,
    'payment_id', v_provider_payment_id,
    'provider_delete_result', nullif(v_delete_result, 'paid')
  );
end
$$;


ALTER FUNCTION public.finalize_billing_payment_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_provider_payment_id text, p_provider_delete_result text, p_provider_deleted_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION finalize_billing_payment_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_provider_payment_id text, p_provider_delete_result text, p_provider_deleted_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.finalize_billing_payment_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_provider_payment_id text, p_provider_delete_result text, p_provider_deleted_at timestamp with time zone) IS 'Finalizes an exact claimed one-off mutation after Edge proves a matching deleted response, provider 404, or a reconciled paid snapshot; paid state always wins.';


--
-- Name: finalize_billing_subscription_checkout_cancellation(uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_billing_subscription_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_subscription_id text, p_provider_deleted_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_subscription_id text := nullif(btrim(coalesce(p_subscription_id, '')), '');
  v_claim private.billing_subscription_checkout_cancellations%rowtype;
  v_intent private.billing_checkout_intents%rowtype;
  v_org public.organizations%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_payment_found boolean := false;
  v_lock_payment_id text;
  v_paid boolean := false;
  v_confirmation jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_organization_id is null
     or p_intent_id is null
     or p_claim_token is null
     or v_subscription_id is null
     or char_length(v_subscription_id) > 255
     or p_provider_deleted_at is null
     or p_provider_deleted_at > now() + interval '5 minutes' then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select cancellation.*
  into v_claim
  from private.billing_subscription_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  v_lock_payment_id := v_claim.provider_payment_id;
  if v_lock_payment_id is null then
    select payment.asaas_payment_id
    into v_lock_payment_id
    from public.asaas_payments as payment
    where payment.organization_id = p_organization_id
      and payment.billing_intent_id = p_intent_id
      and payment.asaas_subscription_id = v_claim.provider_subscription_id
    order by
      case when private.billing_payment_checkout_is_paid(payment.status)
        then 0 else 1 end,
      payment.updated_at desc,
      payment.id desc
    limit 1;
  end if;

  perform private.lock_asaas_billing_resources(
    v_lock_payment_id,
    v_claim.provider_subscription_id
  );

  -- Match claim/checkout ordering after provider advisory keys: payment ->
  -- capability -> cancellation -> organization -> intent. The preliminary claim read only
  -- discovers immutable provider keys and takes no row lock.
  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.organization_id = p_organization_id
    and payment.billing_intent_id = p_intent_id
    and (
      (
        v_claim.provider_payment_id is not null
        and payment.asaas_payment_id = v_claim.provider_payment_id
      )
      or (
        v_claim.provider_payment_id is null
        and payment.asaas_subscription_id = v_claim.provider_subscription_id
      )
    )
  order by
    case when private.billing_payment_checkout_is_paid(payment.status)
      then 0 else 1 end,
    coalesce(
      greatest(
        payment.last_webhook_event_at,
        payment.last_provider_observed_at
      ),
      payment.updated_at,
      payment.created_at
    ) desc,
    payment.id desc
  limit 1
  for update;
  v_payment_found := found;

  if v_payment_found then
    select capability.*
    into v_capability
    from public.billing_payment_checkout_capabilities as capability
    where capability.payment_id = v_payment.id
      and capability.asaas_payment_id = v_payment.asaas_payment_id
      and capability.organization_id = v_payment.organization_id
      and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
    for update;
  end if;

  select cancellation.*
  into v_claim
  from private.billing_subscription_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  if v_claim.provider_subscription_id is distinct from v_subscription_id then
    return jsonb_build_object('outcome', 'identifier_mismatch', 'field', 'subscription');
  end if;
  if v_claim.finalized_at is not null then
    return jsonb_build_object(
      'outcome', 'already_finalized',
      'final_outcome', v_claim.final_outcome,
      'needs_payment_method_update', v_claim.needs_payment_method_update
    );
  end if;
  if v_claim.claim_token is distinct from p_claim_token then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  select intent.*
  into v_intent
  from private.billing_checkout_intents as intent
  where intent.id = p_intent_id
    and intent.organization_id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  v_paid := v_intent.status = 'confirmed'
    or (
      v_payment_found
      and private.billing_payment_checkout_is_paid(v_payment.status)
    );

  if v_paid then
    if v_intent.status <> 'confirmed' and v_payment.id is not null then
      v_confirmation := private.confirm_billing_checkout_intent(
        v_payment.asaas_payment_id,
        v_claim.provider_subscription_id,
        v_payment.status,
        v_payment.value
      );
    end if;

    update private.billing_subscription_checkout_cancellations
    set
      provider_deleted_at = least(p_provider_deleted_at, now()),
      finalized_at = now(),
      final_outcome = 'paid_without_recurrence',
      needs_payment_method_update = true,
      paid_won_at = now(),
      updated_at = now()
    where intent_id = p_intent_id;
  else
    update private.billing_checkout_intents
    set
      status = 'cancelled',
      cancelled_at = coalesce(cancelled_at, now()),
      last_error = 'provider_subscription_cancelled_after_claim',
      updated_at = now()
    where id = p_intent_id
      and organization_id = p_organization_id
      and status in ('creating', 'pending', 'cancelled');

    if not found then
      return jsonb_build_object('outcome', 'lost_claim');
    end if;

    update public.asaas_payments
    set
      status = 'CANCELED',
      raw_event = coalesce(raw_event, '{}'::jsonb) || jsonb_build_object(
        'local_cancellation', jsonb_build_object(
          'source', 'claimed_subscription_checkout_cancellation',
          'recorded_at', now()
        )
      ),
      updated_at = now()
    where organization_id = p_organization_id
      and billing_intent_id = p_intent_id
      and (
        (
          v_claim.provider_payment_id is not null
          and asaas_payment_id = v_claim.provider_payment_id
        )
        or (
          v_claim.provider_payment_id is null
          and asaas_subscription_id = v_claim.provider_subscription_id
        )
      )
      and not private.billing_payment_checkout_is_paid(status);

    update private.billing_subscription_checkout_cancellations
    set
      provider_deleted_at = least(p_provider_deleted_at, now()),
      finalized_at = now(),
      final_outcome = 'cancelled',
      needs_payment_method_update = false,
      paid_won_at = null,
      updated_at = now()
    where intent_id = p_intent_id;
  end if;

  -- Finalization is a terminal fence for every checkout bearer tied to the
  -- exact intent, including legacy rows that predate the cancellation flow.
  update public.billing_payment_checkout_capabilities
  set
    revoked_at = coalesce(revoked_at, now()),
    attempt_lease_id = null,
    attempt_lease_expires_at = null,
    updated_at = now()
  where organization_id = p_organization_id
    and billing_intent_id = p_intent_id;

  update public.organizations
  set asaas_subscription_id = null, updated_at = now()
  where id = p_organization_id
    and asaas_subscription_id = v_claim.provider_subscription_id;

  update public.subscriptions
  set
    provider_subscription_id = null,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'recurrence', jsonb_build_object(
        'status', 'provider_subscription_removed',
        'needs_payment_method_update', v_paid,
        'removed_at', least(p_provider_deleted_at, now()),
        'billing_intent_id', p_intent_id
      )
    ),
    updated_at = now()
  where organization_id = p_organization_id
    and provider_subscription_id = v_claim.provider_subscription_id;

  update private.billing_card_recurrence_provisions
  set
    status = case when status = 'completed' then 'cancelled' else 'failed' end,
    provider_card_credential = null,
    card_last4 = null,
    lease_id = null,
    lease_expires_at = null,
    provider_cancelled_at = case
      when status = 'completed' then least(p_provider_deleted_at, now())
      else null
    end,
    failed_at = case when status = 'completed' then failed_at else now() end,
    last_error = 'provider_subscription_removed_during_checkout_cancellation',
    job_status = 'cancelled',
    job_locked_at = null,
    job_lock_expires_at = null,
    job_locked_by = null,
    job_lease_id = null,
    updated_at = now()
  where organization_id = p_organization_id
    and billing_intent_id = p_intent_id
    and (
      provider_payment_id = v_claim.provider_payment_id
      or (
        v_claim.provider_payment_id is null
        and provider_subscription_id = v_claim.provider_subscription_id
      )
    );

  insert into public.subscription_logs (
    organization_id, event_type, status, metadata
  ) values (
    p_organization_id,
    'provider_subscription_checkout_cancelled',
    case when v_paid then 'active' else 'cancelled' end,
    jsonb_build_object(
      'billing_intent_id', p_intent_id,
      'payment_id', v_claim.provider_payment_id,
      'subscription_id', v_claim.provider_subscription_id,
      'provider_deleted_at', least(p_provider_deleted_at, now()),
      'outcome', case
        when v_paid then 'paid_without_recurrence'
        else 'cancelled'
      end,
      'needs_payment_method_update', v_paid
    )
  );

  return jsonb_build_object(
    'outcome', case
      when v_paid then 'paid_without_recurrence'
      else 'cancelled'
    end,
    'payment_id', v_claim.provider_payment_id,
    'subscription_id', v_claim.provider_subscription_id,
    'needs_payment_method_update', v_paid
  );
end
$$;


ALTER FUNCTION public.finalize_billing_subscription_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_subscription_id text, p_provider_deleted_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION finalize_billing_subscription_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_subscription_id text, p_provider_deleted_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.finalize_billing_subscription_checkout_cancellation(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_subscription_id text, p_provider_deleted_at timestamp with time zone) IS 'Finalizes a claimed provider subscription deletion; a concurrent or late paid payment retains its purchased period and is durably marked without recurrence.';


--
-- Name: find_duplicate_lead_by_phone(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_duplicate_lead_by_phone(p_phone text) RETURNS TABLE(lead_id uuid, lead_name text, responsible_user_id uuid, responsible_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_organization_id uuid;
  v_phone_key text;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT organization_id
  INTO v_organization_id
  FROM public.users
  WHERE id = v_user_id;

  IF v_organization_id IS NULL THEN
    RETURN;
  END IF;

  v_phone_key := public.normalize_phone(p_phone);

  IF v_phone_key IS NULL OR v_phone_key = '' THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    l.id AS lead_id,
    l.name AS lead_name,
    l.assigned_user_id AS responsible_user_id,
    COALESCE(u.name, 'Sem responsável') AS responsible_name
  FROM public.leads l
  LEFT JOIN public.users u ON u.id = l.assigned_user_id
  WHERE l.organization_id = v_organization_id
    AND public.normalize_phone(l.phone) = v_phone_key
  ORDER BY l.created_at ASC, l.id ASC
  LIMIT 1;
END;
$$;


ALTER FUNCTION public.find_duplicate_lead_by_phone(p_phone text) OWNER TO postgres;

--
-- Name: find_lead_by_normalized_phone(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_lead_by_normalized_phone(p_organization_id uuid, p_phone text) RETURNS TABLE(id uuid, name text, assigned_user_id uuid, whatsapp_avatar_url text, property_code text, property_id uuid, interest_property_id uuid, source_detail text, metadata jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_phone_key text := coalesce(public.normalize_phone(p_phone), '');
  v_match_count integer;
begin
  if p_organization_id is null or v_phone_key = '' then
    return;
  end if;

  select count(*)::integer
  into v_match_count
  from (
    select lead.id
    from public.leads as lead
    where lead.organization_id = p_organization_id
      and lead.phone is not null
      and btrim(lead.phone) <> ''
      and public.normalize_phone(lead.phone) = v_phone_key
    limit 2
  ) as matches;

  if v_match_count > 1 then
    raise exception using
      errcode = '23505',
      message = 'whatsapp_lead_phone_ambiguous';
  end if;

  return query
  select
    lead.id,
    lead.name,
    lead.assigned_user_id,
    lead.whatsapp_avatar_url,
    lead.property_code,
    lead.property_id,
    lead.interest_property_id,
    lead.source_detail,
    lead.metadata
  from public.leads as lead
  where lead.organization_id = p_organization_id
    and lead.phone is not null
    and btrim(lead.phone) <> ''
    and public.normalize_phone(lead.phone) = v_phone_key
  limit 1;
end;
$$;


ALTER FUNCTION public.find_lead_by_normalized_phone(p_organization_id uuid, p_phone text) OWNER TO postgres;

--
-- Name: FUNCTION find_lead_by_normalized_phone(p_organization_id uuid, p_phone text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.find_lead_by_normalized_phone(p_organization_id uuid, p_phone text) IS 'Returns the single organization-scoped lead matching the indexed normalized phone and rejects ambiguous historical duplicates.';


--
-- Name: find_lead_by_normalized_phone(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_lead_by_normalized_phone(p_organization_id uuid, p_phone text, p_origin_round_robin_id uuid) RETURNS TABLE(id uuid, name text, assigned_user_id uuid, whatsapp_avatar_url text, property_code text, property_id uuid, interest_property_id uuid, source_detail text, metadata jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_phone_key text := coalesce(public.normalize_phone(p_phone), '');
  v_scope_key text;
  v_match_count integer;
begin
  if p_origin_round_robin_id is null then
    raise exception using
      errcode = '22023',
      message = 'lead_origin_round_robin_required';
  end if;

  if v_phone_key = '' then
    return;
  end if;

  v_scope_key := private.lead_intake_scope_for_queue(
    p_organization_id,
    p_origin_round_robin_id
  );

  select count(*)::integer
  into v_match_count
  from (
    select lead.id
    from public.leads as lead
    where lead.organization_id = p_organization_id
      and lead.intake_scope_key = v_scope_key
      and lead.phone is not null
      and btrim(lead.phone) <> ''
      and public.normalize_phone(lead.phone) = v_phone_key
    limit 2
  ) as matches;

  if v_match_count > 1 then
    raise exception using
      errcode = '23505',
      message = 'lead_queue_phone_ambiguous';
  end if;

  return query
  select
    lead.id,
    lead.name,
    lead.assigned_user_id,
    lead.whatsapp_avatar_url,
    lead.property_code,
    lead.property_id,
    lead.interest_property_id,
    lead.source_detail,
    lead.metadata
  from public.leads as lead
  where lead.organization_id = p_organization_id
    and lead.intake_scope_key = v_scope_key
    and lead.phone is not null
    and btrim(lead.phone) <> ''
    and public.normalize_phone(lead.phone) = v_phone_key
  limit 1;
end;
$$;


ALTER FUNCTION public.find_lead_by_normalized_phone(p_organization_id uuid, p_phone text, p_origin_round_robin_id uuid) OWNER TO postgres;

--
-- Name: find_orphan_rr_members(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_orphan_rr_members() RETURNS TABLE(member_id uuid, round_robin_id uuid, user_id uuid, queue_name text, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    rrm.id,
    rrm.round_robin_id,
    rrm.user_id,
    rr.name,
    CASE
      WHEN u.id IS NULL THEN 'user_deleted'
      WHEN u.organization_id IS NULL THEN 'user_no_org'
      WHEN u.organization_id != rr.organization_id THEN 'org_mismatch'
    END::text
  FROM round_robin_members rrm
  JOIN round_robins rr ON rrm.round_robin_id = rr.id
  LEFT JOIN users u ON rrm.user_id = u.id
  WHERE u.id IS NULL
     OR u.organization_id IS NULL
     OR u.organization_id != rr.organization_id;
END;
$$;


ALTER FUNCTION public.find_orphan_rr_members() OWNER TO postgres;

--
-- Name: find_orphan_team_members(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_orphan_team_members() RETURNS TABLE(member_id uuid, team_id uuid, user_id uuid, team_name text, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    tm.id,
    tm.team_id,
    tm.user_id,
    t.name,
    CASE
      WHEN u.id IS NULL THEN 'user_deleted'
      WHEN u.organization_id IS NULL THEN 'user_no_org'
      WHEN u.organization_id != t.organization_id THEN 'org_mismatch'
    END::text
  FROM team_members tm
  JOIN teams t ON tm.team_id = t.id
  LEFT JOIN users u ON tm.user_id = u.id
  WHERE u.id IS NULL
     OR u.organization_id IS NULL
     OR u.organization_id != t.organization_id;
END;
$$;


ALTER FUNCTION public.find_orphan_team_members() OWNER TO postgres;

--
-- Name: finish_automation_external_effect(text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_automation_external_effect(p_effect_key text, p_status text, p_response jsonb DEFAULT '{}'::jsonb, p_provider_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with changed as (
    update public.automation_effect_dispatches
    set status = p_status,
        response = coalesce(p_response, '{}'::jsonb),
        provider_id = nullif(p_provider_id, ''),
        error_message = nullif(left(coalesce(p_error, ''), 4000), ''),
        completed_at = now()
    where effect_key = p_effect_key
      and status = 'sending'
      and p_status in ('succeeded', 'failed', 'unknown')
    returning id
  ) select exists(select 1 from changed);
$$;


ALTER FUNCTION public.finish_automation_external_effect(p_effect_key text, p_status text, p_response jsonb, p_provider_id text, p_error text) OWNER TO postgres;

--
-- Name: finish_whatsapp_webhook_edge_execution(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_whatsapp_webhook_edge_execution(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_organization_id is null or p_session_id is null or p_inbox_id is null
    or p_execution_id is null
  then
    return false;
  end if;
  update public.whatsapp_webhook_inbox as inbox
  set edge_execution_id = null,
      edge_execution_state = null,
      edge_execution_reserved_at = null,
      edge_execution_started_at = null,
      updated_at = now()
  where inbox.id = p_inbox_id
    and inbox.organization_id = p_organization_id
    and inbox.session_id = p_session_id
    and inbox.processing_epoch = 0
    and inbox.edge_execution_id = p_execution_id
    and inbox.edge_execution_state = 'active';
  return found;
end;
$$;


ALTER FUNCTION public.finish_whatsapp_webhook_edge_execution(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid) OWNER TO postgres;

--
-- Name: fn_update_construction_financial_progress(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_update_construction_financial_progress() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_project_id UUID;
    v_total_budget DECIMAL;
    v_total_spent DECIMAL;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_project_id := OLD.project_id;
    ELSE
        v_project_id := NEW.project_id;
    END IF;

    -- Busca o orçamento estimado da obra
    SELECT budget_estimated INTO v_total_budget
    FROM public.construction_projects
    WHERE id = v_project_id;

    -- Soma todos os pedidos de compra aprovados/pagos
    SELECT COALESCE(SUM(net_amount), 0) INTO v_total_spent
    FROM public.construction_purchase_orders
    WHERE project_id = v_project_id AND status IN ('paid', 'approved');

    -- Atualiza o progresso financeiro (gasto real vs estimado)
    UPDATE public.construction_projects
    SET
        budget_actual = v_total_spent,
        financial_progress_percent = CASE
            WHEN v_total_budget > 0 THEN LEAST((v_total_spent / v_total_budget) * 100, 100)
            ELSE 0
        END,
        updated_at = now()
    WHERE id = v_project_id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_update_construction_financial_progress() OWNER TO postgres;

--
-- Name: fn_update_construction_project_progress(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_update_construction_project_progress() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    total_weight DECIMAL;
    completed_weight DECIMAL;
    v_project_id UUID;
BEGIN
    v_project_id := COALESCE(NEW.project_id, OLD.project_id);
    SELECT SUM(weight) INTO total_weight FROM public.construction_milestones WHERE project_id = v_project_id;
    SELECT SUM(weight) INTO completed_weight FROM public.construction_milestones WHERE project_id = v_project_id AND status = 'completed';
    UPDATE public.construction_projects
    SET physical_progress_percent = CASE WHEN total_weight > 0 THEN (completed_weight / total_weight) * 100 ELSE 0 END,
        updated_at = now()
    WHERE id = v_project_id;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_update_construction_project_progress() OWNER TO postgres;

--
-- Name: gamification_level_for_xp(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gamification_level_for_xp(p_xp integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE v_level int := 1;
BEGIN
  IF p_xp IS NULL OR p_xp <= 0 THEN RETURN 1; END IF;
  WHILE public.gamification_xp_for_level(v_level + 1) <= p_xp LOOP
    v_level := v_level + 1;
    IF v_level > 200 THEN EXIT; END IF;
  END LOOP;
  RETURN v_level;
END; $$;


ALTER FUNCTION public.gamification_level_for_xp(p_xp integer) OWNER TO postgres;

--
-- Name: gamification_rank_tier(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gamification_rank_tier(p_level integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_level <= 3  THEN 'Bronze I'
    WHEN p_level <= 6  THEN 'Bronze II'
    WHEN p_level <= 10 THEN 'Prata I'
    WHEN p_level <= 15 THEN 'Prata II'
    WHEN p_level <= 20 THEN 'Ouro I'
    WHEN p_level <= 30 THEN 'Ouro II'
    WHEN p_level <= 45 THEN 'Platina'
    ELSE 'Diamante'
  END;
$$;


ALTER FUNCTION public.gamification_rank_tier(p_level integer) OWNER TO postgres;

--
-- Name: gamification_xp_for_level(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gamification_xp_for_level(p_level integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_level <= 1 THEN 0
    WHEN p_level = 2 THEN 100
    WHEN p_level = 3 THEN 250
    WHEN p_level = 4 THEN 500
    WHEN p_level = 5 THEN 900
    ELSE (100 * (p_level - 1) * (p_level - 1))::int
  END;
$$;


ALTER FUNCTION public.gamification_xp_for_level(p_level integer) OWNER TO postgres;

--
-- Name: generate_commissions_for_contract(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_commissions_for_contract() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_broker RECORD;
  v_base   numeric;
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.status IN ('active','signed'))
     OR (TG_OP = 'UPDATE' AND NEW.status IN ('active','signed') AND COALESCE(OLD.status,'') <> NEW.status) THEN

    v_base := COALESCE(NEW.value, 0);
    IF v_base <= 0 THEN RETURN NEW; END IF;

    IF EXISTS (SELECT 1 FROM public.commissions WHERE contract_id = NEW.id) THEN
      RETURN NEW;
    END IF;

    FOR v_broker IN
      SELECT user_id, commission_percentage
      FROM public.contract_brokers
      WHERE contract_id = NEW.id
    LOOP
      INSERT INTO public.commissions (
        organization_id, contract_id, lead_id, property_id,
        user_id, percentage, base_value, amount, calculated_value,
        status, forecast_date, notes
      ) VALUES (
        NEW.organization_id, NEW.id, NEW.lead_id, NEW.property_id,
        v_broker.user_id,
        COALESCE(v_broker.commission_percentage, NEW.commission_percentage, 0),
        v_base,
        ROUND(v_base * COALESCE(v_broker.commission_percentage, NEW.commission_percentage, 0) / 100.0, 2),
        ROUND(v_base * COALESCE(v_broker.commission_percentage, NEW.commission_percentage, 0) / 100.0, 2),
        'forecast',
        COALESCE(NEW.closing_date, NEW.signing_date, CURRENT_DATE),
        'Comissão prevista gerada automaticamente ao ativar contrato'
      );
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.generate_commissions_for_contract() OWNER TO postgres;

--
-- Name: generate_organization_api_key(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_organization_api_key(p_name text, p_organization_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_api_key TEXT;
    v_key_prefix TEXT := 'vk_';
    v_random_part TEXT;
BEGIN
    -- Verificar se o usuário é admin da organização ou super admin
    IF NOT EXISTS (
        SELECT 1 FROM public.organization_members
        WHERE user_id = auth.uid()
        AND organization_id = p_organization_id
        AND role = 'admin'
    ) AND NOT EXISTS (
        SELECT 1 FROM public.users
        WHERE id = auth.uid()
        AND role = 'super_admin'
    ) THEN
        RAISE EXCEPTION 'Acesso negado. Apenas administradores podem criar chaves de API.';
    END IF;

    -- Gerar a chave aleatória
    v_random_part := encode(gen_random_bytes(24), 'base64');
    v_random_part := replace(replace(replace(v_random_part, '/', ''), '+', ''), '=', '');
    v_api_key := v_key_prefix || v_random_part;

    -- Salvar o hash da chave para segurança
    INSERT INTO public.organization_api_keys (
        organization_id,
        name,
        key_hash,
        created_by
    ) VALUES (
        p_organization_id,
        p_name,
        crypt(v_api_key, gen_salt('bf')),
        auth.uid()
    );

    RETURN v_api_key;
END;
$$;


ALTER FUNCTION public.generate_organization_api_key(p_name text, p_organization_id uuid) OWNER TO postgres;

--
-- Name: get_billing_card_recurrence_reversal_target(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_billing_card_recurrence_reversal_target(p_provider_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_preliminary_subscription_id text;
  v_had_preliminary_provision boolean := false;
  v_payment public.asaas_payments%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_payment_status text;
begin
  if v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255 then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  -- A preliminary read discovers the provider subscription advisory key. The
  -- exact payment/provision tuple is re-read under globally ordered advisory
  -- and row locks; a concurrent completion therefore produces state_changed
  -- and a safe retry instead of an incompletely locked cancellation target.
  select provision.provider_subscription_id
  into v_preliminary_subscription_id
  from private.billing_card_recurrence_provisions as provision
  where provision.provider_payment_id = v_provider_payment_id;
  v_had_preliminary_provision := found;

  perform private.lock_asaas_billing_resources(
    v_provider_payment_id,
    v_preliminary_subscription_id
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
    and provision.provider_payment_id = v_payment.asaas_payment_id
    and provision.organization_id = v_payment.organization_id
    and provision.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  if not found then
    return jsonb_build_object(
      'outcome', 'recurrence_not_found',
      'payment_id', v_payment.id
    );
  end if;

  if not v_had_preliminary_provision
     or v_provision.provider_subscription_id
       is distinct from v_preliminary_subscription_id then
    return jsonb_build_object(
      'outcome', 'state_changed',
      'payment_id', v_payment.id
    );
  end if;

  if v_provision.status <> 'completed' then
    return jsonb_build_object(
      'outcome', 'recurrence_not_completed',
      'payment_id', v_payment.id,
      'recurrence_status', v_provision.status
    );
  end if;

  v_payment_status := upper(btrim(coalesce(v_payment.status, '')));
  if not private.billing_payment_checkout_is_reversal(v_payment_status) then
    return jsonb_build_object(
      'outcome', 'payment_not_reversed',
      'payment_id', v_payment.id,
      'payment_status', v_payment_status
    );
  end if;

  if v_provision.provider_subscription_id is null
     or nullif(btrim(v_provision.provider_customer_id), '') is null
     or nullif(btrim(v_provision.external_reference), '') is null
     or v_provision.amount is null
     or v_provision.amount <= 0
     or v_provision.billing_period_months not in (1, 6, 12)
     or v_provision.next_due_date is null then
    return jsonb_build_object(
      'outcome', 'target_invalid',
      'payment_id', v_payment.id
    );
  end if;

  return jsonb_build_object(
    'outcome', 'target',
    'payment_id', v_provision.payment_id,
    'provider_payment_id', v_provision.provider_payment_id,
    'organization_id', v_provision.organization_id,
    'billing_intent_id', v_provision.billing_intent_id,
    'provider_subscription_id', v_provision.provider_subscription_id,
    'provider_customer_id', v_provision.provider_customer_id,
    'external_reference', v_provision.external_reference,
    'amount', v_provision.amount,
    'billing_period_months', v_provision.billing_period_months,
    'next_due_date', v_provision.next_due_date,
    'payment_status', v_payment_status
  );
end
$$;


ALTER FUNCTION public.get_billing_card_recurrence_reversal_target(p_provider_payment_id text) OWNER TO postgres;

--
-- Name: FUNCTION get_billing_card_recurrence_reversal_target(p_provider_payment_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_billing_card_recurrence_reversal_target(p_provider_payment_id text) IS 'Service-only, idempotent resolver for the exact completed future subscription linked to a locally reversed initial payment; provider GET validation and DELETE remain backend responsibilities.';


--
-- Name: get_billing_checkout_state(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_billing_checkout_state(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_intent private.billing_checkout_intents%rowtype;
  v_payment jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_organization_id is null then
    raise exception 'organization is required' using errcode = '22023';
  end if;

  select intent.*
  into v_intent
  from private.billing_checkout_intents as intent
  where intent.organization_id = p_organization_id
    and intent.status in ('creating', 'pending')
  order by intent.created_at desc
  limit 1;

  if not found then
    return null;
  end if;

  select jsonb_build_object(
    'id', payment.asaas_payment_id,
    'status', payment.status,
    'billing_type', payment.billing_type,
    'value', payment.value,
    'due_date', payment.due_date,
    'payment_date', payment.payment_date,
    'invoice_url', payment.invoice_url,
    'bank_slip_registration_cancelled', (
      payment.bank_slip_registration_cancelled_at is not null
      and payment.bank_slip_registration_cancelled_due_date
        is not distinct from payment.due_date
    ),
    'bank_slip_registration_cancelled_due_date', case
      when payment.bank_slip_registration_cancelled_at is not null
        and payment.bank_slip_registration_cancelled_due_date
          is not distinct from payment.due_date
      then payment.bank_slip_registration_cancelled_due_date
      else null
    end,
    'updated_at', payment.updated_at
  )
  into v_payment
  from public.asaas_payments as payment
  where payment.organization_id = p_organization_id
    and payment.billing_intent_id = v_intent.id
  order by payment.updated_at desc nulls last,
    payment.created_at desc nulls last
  limit 1;

  return jsonb_build_object(
    'intent_id', v_intent.id,
    'organization_id', v_intent.organization_id,
    'plan_id', v_intent.pending_plan_id,
    'billing_method', v_intent.billing_method,
    'status', v_intent.status,
    'billing_period_months', v_intent.billing_period_months,
    'amount', v_intent.amount,
    'external_reference', v_intent.external_reference,
    'provider_customer_id', v_intent.provider_customer_id,
    'provider_payment_id', v_intent.provider_payment_id,
    'provider_subscription_id', v_intent.provider_subscription_id,
    'provider_checkout_id', v_intent.provider_checkout_id,
    'provider_request_started_at', v_intent.provider_request_started_at,
    'provider_status', coalesce(
      v_payment ->> 'status',
      nullif(v_intent.provider_response ->> 'status', '')
    ),
    'card_last4', case
      when coalesce(v_intent.provider_response ->> 'cardLast4', '') ~ '^[0-9]{4}$'
        then v_intent.provider_response ->> 'cardLast4'
      else null
    end,
    'has_error', v_intent.last_error is not null,
    'payment', v_payment,
    'created_at', v_intent.created_at,
    'updated_at', v_intent.updated_at
  );
end
$_$;


ALTER FUNCTION public.get_billing_checkout_state(p_organization_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_billing_checkout_state(p_organization_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_billing_checkout_state(p_organization_id uuid) IS 'Service-only active checkout state with safe boleto-registration cancellation flags; raw provider events remain private.';


--
-- Name: get_billing_subscription_card_update_status(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_billing_subscription_card_update_status(p_job_id uuid, p_organization_id uuid, p_expected_payment_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_job private.billing_subscription_card_update_jobs%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null or p_organization_id is null then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;
  if (
       v_job.mode = 'settled_payment'
       and (
         p_expected_payment_id is null
         or v_job.payment_id is distinct from p_expected_payment_id
       )
     )
     or (v_job.mode = 'saved_only' and p_expected_payment_id is not null) then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'outcome', 'found',
    'job_id', v_job.id,
    'generation', v_job.generation,
    'mode', v_job.mode,
    'state', case
      when v_job.status = 'succeeded' then 'succeeded'
      when v_job.status = 'cancelled' then 'cancelled'
      when v_job.status = 'dead' and v_job.manual_review_at is not null
        then 'manual_review'
      when v_job.status = 'dead' then 'failed'
      else 'queued'
    end,
    'status', v_job.status,
    'card_last4', v_job.card_last4,
    'last_error_code', v_job.last_error_code,
    'next_attempt_at', case
      when v_job.status in ('retry', 'pending_update')
        then v_job.next_attempt_at
      else null
    end,
    'created_at', v_job.created_at,
    'updated_at', v_job.updated_at,
    'completed_at', v_job.completed_at,
    'cancelled_at', v_job.cancelled_at,
    'manual_review_at', v_job.manual_review_at
  ));
end
$$;


ALTER FUNCTION public.get_billing_subscription_card_update_status(p_job_id uuid, p_organization_id uuid, p_expected_payment_id uuid) OWNER TO postgres;

--
-- Name: get_dashboard_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_dashboard_stats() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_user_id UUID;
  v_is_admin BOOLEAN;
  v_result JSON;
  v_total_leads BIGINT;
  v_in_progress BIGINT;
  v_closed BIGINT;
  v_lost BIGINT;
  v_prev_total BIGINT;
  v_prev_closed BIGINT;
BEGIN
  -- Get current user's organization and check admin status
  SELECT u.organization_id, u.id, (u.role = 'admin')
  INTO v_org_id, v_user_id, v_is_admin
  FROM users u
  WHERE u.id = auth.uid();

  IF v_org_id IS NULL THEN
    RETURN json_build_object(
      'totalLeads', 0,
      'leadsInProgress', 0,
      'leadsClosed', 0,
      'leadsLost', 0,
      'leadsTrend', 0,
      'closedTrend', 0
    );
  END IF;

  -- Current period stats (last 30 days)
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE deal_status = 'open' OR deal_status IS NULL),
    COUNT(*) FILTER (WHERE deal_status = 'won'),
    COUNT(*) FILTER (WHERE deal_status = 'lost')
  INTO v_total_leads, v_in_progress, v_closed, v_lost
  FROM leads l
  WHERE l.organization_id = v_org_id
    AND (v_is_admin OR l.assigned_user_id = v_user_id)
    AND l.created_at >= NOW() - INTERVAL '30 days';

  -- Previous period stats (30-60 days ago)
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE deal_status = 'won')
  INTO v_prev_total, v_prev_closed
  FROM leads l
  WHERE l.organization_id = v_org_id
    AND (v_is_admin OR l.assigned_user_id = v_user_id)
    AND l.created_at >= NOW() - INTERVAL '60 days'
    AND l.created_at < NOW() - INTERVAL '30 days';

  v_result := json_build_object(
    'totalLeads', COALESCE(v_total_leads, 0),
    'leadsInProgress', COALESCE(v_in_progress, 0),
    'leadsClosed', COALESCE(v_closed, 0),
    'leadsLost', COALESCE(v_lost, 0),
    'leadsTrend', CASE WHEN v_prev_total > 0 THEN ROUND(((v_total_leads - v_prev_total)::NUMERIC / v_prev_total) * 100) ELSE 0 END,
    'closedTrend', CASE WHEN v_prev_closed > 0 THEN ROUND(((v_closed - v_prev_closed)::NUMERIC / v_prev_closed) * 100) ELSE 0 END
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_dashboard_stats() OWNER TO postgres;

--
-- Name: get_dashboard_team_lead_ids(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_dashboard_team_lead_ids(p_team_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(lead_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_org_id uuid := public.get_user_organization_id();
  v_can_view_all boolean := false;
  v_can_view_team boolean := false;
  v_team_allowed boolean := false;
  v_visible_user_ids uuid[] := ARRAY[]::uuid[];
  v_visible_pipeline_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF v_caller_id IS NULL OR p_team_id IS NULL THEN
    RETURN;
  END IF;

  v_can_view_all := public.is_super_admin()
    OR public.is_admin()
    OR public.user_has_permission('lead_view_all', v_caller_id)
    OR public.user_has_permission('lead_edit_all', v_caller_id);

  v_can_view_team := public.user_has_permission('lead_view_team', v_caller_id)
    OR public.user_has_permission('lead_edit_team', v_caller_id);

  IF v_can_view_all THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.teams t
      WHERE t.id = p_team_id
        AND (public.is_super_admin() OR t.organization_id = v_org_id)
    )
    INTO v_team_allowed;
  ELSE
    SELECT EXISTS (
      SELECT 1
      FROM public.team_members tm
      WHERE tm.team_id = p_team_id
        AND tm.user_id = v_caller_id
        AND (tm.is_leader OR v_can_view_team)
    )
    OR p_team_id IN (SELECT led_team_id FROM public.get_user_led_team_ids() AS led_team_id)
    INTO v_team_allowed;
  END IF;

  IF NOT v_team_allowed THEN
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT tm.user_id), ARRAY[]::uuid[])
    INTO v_visible_user_ids
  FROM public.team_members tm
  WHERE tm.team_id IN (
    SELECT p_team_id
    UNION
    SELECT led_team_id FROM public.get_user_led_team_ids() AS led_team_id
    UNION
    SELECT own_tm.team_id
    FROM public.team_members own_tm
    WHERE own_tm.user_id = v_caller_id
      AND v_can_view_team
  );

  v_visible_user_ids := array_append(v_visible_user_ids, v_caller_id);

  SELECT COALESCE(array_agg(DISTINCT pipeline_id), ARRAY[]::uuid[])
    INTO v_visible_pipeline_ids
  FROM public.get_user_led_pipeline_ids() AS p(pipeline_id);

  RETURN QUERY
  WITH fallback_members AS (
    SELECT tm.user_id
    FROM public.team_members tm
    WHERE tm.team_id = p_team_id
  )
  SELECT DISTINCT l.id AS lead_id
  FROM public.leads l
  WHERE (public.is_super_admin() OR l.organization_id = v_org_id)
    AND (p_date_from IS NULL OR l.created_at >= p_date_from)
    AND (p_date_to IS NULL OR l.created_at <= p_date_to)
    AND (
      EXISTS (
        SELECT 1
        FROM public.round_robin_logs rrl
        JOIN public.round_robin_members rrm ON rrm.id = rrl.member_id
        WHERE rrl.lead_id = l.id
          AND rrm.team_id = p_team_id
      )
      OR (
        NOT EXISTS (
          SELECT 1
          FROM public.round_robin_logs rrl
          JOIN public.round_robin_members rrm ON rrm.id = rrl.member_id
          WHERE rrl.lead_id = l.id
            AND rrm.team_id IS NOT NULL
        )
        AND l.assigned_user_id IN (SELECT user_id FROM fallback_members)
      )
    )
    AND (
      v_can_view_all
      OR l.assigned_user_id = ANY(v_visible_user_ids)
      OR l.pipeline_id = ANY(v_visible_pipeline_ids)
    );
END;
$$;


ALTER FUNCTION public.get_dashboard_team_lead_ids(p_team_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone) OWNER TO postgres;

--
-- Name: get_funnel_data(timestamp with time zone, timestamp with time zone, uuid, uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_funnel_data(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_team_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text, p_pipeline_id uuid DEFAULT NULL::uuid, p_tag_id uuid DEFAULT NULL::uuid, p_deal_status text DEFAULT NULL::text) RETURNS TABLE(stage_id uuid, stage_name text, stage_key text, stage_order integer, lead_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_org_id uuid := public.get_user_organization_id();
  v_pipeline_id uuid;
  v_can_view_all boolean := false;
  v_can_view_team boolean := false;
  v_visible_user_ids uuid[] := ARRAY[]::uuid[];
  v_visible_pipeline_ids uuid[] := ARRAY[]::uuid[];
  v_pipeline_allowed boolean := false;
  v_user_allowed boolean := false;
  v_team_lead_ids uuid[] := NULL;
BEGIN
  IF v_org_id IS NULL AND NOT public.is_super_admin() THEN
    RETURN;
  END IF;

  v_can_view_all := public.is_super_admin()
    OR public.is_admin()
    OR public.user_has_permission('lead_view_all', v_caller_id)
    OR public.user_has_permission('lead_edit_all', v_caller_id);

  v_can_view_team := public.user_has_permission('lead_view_team', v_caller_id)
    OR public.user_has_permission('lead_edit_team', v_caller_id);

  SELECT COALESCE(array_agg(DISTINCT tm.user_id), ARRAY[]::uuid[])
    INTO v_visible_user_ids
  FROM public.team_members tm
  WHERE tm.team_id IN (
      SELECT led_team_id FROM public.get_user_led_team_ids() AS led_team_id
      UNION
      SELECT own_tm.team_id
      FROM public.team_members own_tm
      WHERE own_tm.user_id = v_caller_id
        AND v_can_view_team
    );

  v_visible_user_ids := array_append(v_visible_user_ids, v_caller_id);

  SELECT COALESCE(array_agg(DISTINCT pipeline_id), ARRAY[]::uuid[])
    INTO v_visible_pipeline_ids
  FROM public.get_user_led_pipeline_ids() AS p(pipeline_id);

  IF p_pipeline_id IS NOT NULL THEN
    SELECT p.id INTO v_pipeline_id
    FROM public.pipelines p
    WHERE p.id = p_pipeline_id
      AND (public.is_super_admin() OR p.organization_id = v_org_id);

    IF v_pipeline_id IS NULL THEN
      RETURN;
    END IF;
  ELSE
    SELECT p.id INTO v_pipeline_id
    FROM public.pipelines p
    WHERE (public.is_super_admin() OR p.organization_id = v_org_id)
    ORDER BY p.is_default DESC NULLS LAST, p.created_at ASC
    LIMIT 1;
  END IF;

  IF v_pipeline_id IS NULL THEN
    RETURN;
  END IF;

  IF p_user_id IS NOT NULL THEN
    v_user_allowed := v_can_view_all
      OR p_user_id = v_caller_id
      OR p_user_id = ANY(v_visible_user_ids);

    IF NOT v_user_allowed THEN
      RETURN;
    END IF;
  END IF;

  IF p_team_id IS NOT NULL THEN
    SELECT array_agg(ids.lead_id)
      INTO v_team_lead_ids
    FROM public.get_dashboard_team_lead_ids(p_team_id, p_date_from, p_date_to) ids;

    IF v_team_lead_ids IS NULL OR array_length(v_team_lead_ids, 1) IS NULL THEN
      v_team_lead_ids := ARRAY[]::uuid[];
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    s.id AS stage_id,
    s.name AS stage_name,
    COALESCE(s.stage_key, s.name) AS stage_key,
    s.position AS stage_order,
    COUNT(l.id) AS lead_count
  FROM public.stages s
  LEFT JOIN public.leads l ON l.stage_id = s.id
    AND (public.is_super_admin() OR l.organization_id = v_org_id)
    AND (p_date_from IS NULL OR l.created_at >= p_date_from)
    AND (p_date_to IS NULL OR l.created_at <= p_date_to)
    AND (p_team_id IS NULL OR l.id = ANY(v_team_lead_ids))
    AND (p_user_id IS NULL OR l.assigned_user_id = p_user_id)
    AND (p_source IS NULL OR p_source = 'all' OR l.source::text = p_source)
    AND (p_deal_status IS NULL OR p_deal_status = '' OR l.deal_status = p_deal_status)
    AND (p_tag_id IS NULL OR EXISTS (
      SELECT 1 FROM public.lead_tags lt WHERE lt.lead_id = l.id AND lt.tag_id = p_tag_id
    ))
    AND (
      v_can_view_all
      OR l.assigned_user_id = ANY(v_visible_user_ids)
      OR l.pipeline_id = ANY(v_visible_pipeline_ids)
    )
  WHERE s.pipeline_id = v_pipeline_id
  GROUP BY s.id, s.name, s.stage_key, s.position
  ORDER BY s.position;
END;
$$;


ALTER FUNCTION public.get_funnel_data(p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_team_id uuid, p_user_id uuid, p_source text, p_pipeline_id uuid, p_tag_id uuid, p_deal_status text) OWNER TO postgres;

--
-- Name: get_gamification_points(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_gamification_points(p_org_id uuid, p_action_type text) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_points integer;
BEGIN
  SELECT points INTO v_points
  FROM public.gamification_rules
  WHERE organization_id = p_org_id
    AND lower(action_type) = lower(p_action_type)
    AND is_active = true
  LIMIT 1;

  RETURN COALESCE(v_points, 0);
END;
$$;


ALTER FUNCTION public.get_gamification_points(p_org_id uuid, p_action_type text) OWNER TO postgres;

--
-- Name: get_lead_sources_data(timestamp with time zone, timestamp with time zone, uuid, uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_lead_sources_data(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_team_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text, p_pipeline_id uuid DEFAULT NULL::uuid, p_tag_id uuid DEFAULT NULL::uuid, p_deal_status text DEFAULT NULL::text) RETURNS TABLE(source_name text, lead_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_org_id uuid := public.get_user_organization_id();
  v_can_view_all boolean := false;
  v_can_view_team boolean := false;
  v_visible_user_ids uuid[] := ARRAY[]::uuid[];
  v_visible_pipeline_ids uuid[] := ARRAY[]::uuid[];
  v_pipeline_allowed boolean := false;
  v_user_allowed boolean := false;
  v_team_lead_ids uuid[] := NULL;
BEGIN
  IF v_org_id IS NULL AND NOT public.is_super_admin() THEN
    RETURN;
  END IF;

  v_can_view_all := public.is_super_admin()
    OR public.is_admin()
    OR public.user_has_permission('lead_view_all', v_caller_id)
    OR public.user_has_permission('lead_edit_all', v_caller_id);

  v_can_view_team := public.user_has_permission('lead_view_team', v_caller_id)
    OR public.user_has_permission('lead_edit_team', v_caller_id);

  SELECT COALESCE(array_agg(DISTINCT tm.user_id), ARRAY[]::uuid[])
    INTO v_visible_user_ids
  FROM public.team_members tm
  WHERE tm.team_id IN (
      SELECT led_team_id FROM public.get_user_led_team_ids() AS led_team_id
      UNION
      SELECT own_tm.team_id
      FROM public.team_members own_tm
      WHERE own_tm.user_id = v_caller_id
        AND v_can_view_team
    );

  v_visible_user_ids := array_append(v_visible_user_ids, v_caller_id);

  SELECT COALESCE(array_agg(DISTINCT pipeline_id), ARRAY[]::uuid[])
    INTO v_visible_pipeline_ids
  FROM public.get_user_led_pipeline_ids() AS p(pipeline_id);

  IF p_pipeline_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.pipelines p
      WHERE p.id = p_pipeline_id
        AND (public.is_super_admin() OR p.organization_id = v_org_id)
    )
    INTO v_pipeline_allowed;

    IF NOT v_pipeline_allowed THEN
      RETURN;
    END IF;
  END IF;

  IF p_user_id IS NOT NULL THEN
    v_user_allowed := v_can_view_all
      OR p_user_id = v_caller_id
      OR p_user_id = ANY(v_visible_user_ids);

    IF NOT v_user_allowed THEN
      RETURN;
    END IF;
  END IF;

  IF p_team_id IS NOT NULL THEN
    SELECT array_agg(ids.lead_id)
      INTO v_team_lead_ids
    FROM public.get_dashboard_team_lead_ids(p_team_id, p_date_from, p_date_to) ids;

    IF v_team_lead_ids IS NULL OR array_length(v_team_lead_ids, 1) IS NULL THEN
      v_team_lead_ids := ARRAY[]::uuid[];
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    COALESCE(l.source::text, 'manual') AS source_name,
    COUNT(*) AS lead_count
  FROM public.leads l
  WHERE (public.is_super_admin() OR l.organization_id = v_org_id)
    AND (p_pipeline_id IS NULL OR l.stage_id IN (
      SELECT s.id FROM public.stages s WHERE s.pipeline_id = p_pipeline_id
    ))
    AND (p_date_from IS NULL OR l.created_at >= p_date_from)
    AND (p_date_to IS NULL OR l.created_at <= p_date_to)
    AND (p_team_id IS NULL OR l.id = ANY(v_team_lead_ids))
    AND (p_user_id IS NULL OR l.assigned_user_id = p_user_id)
    AND (p_source IS NULL OR p_source = 'all' OR l.source::text = p_source)
    AND (p_deal_status IS NULL OR p_deal_status = '' OR l.deal_status = p_deal_status)
    AND (p_tag_id IS NULL OR EXISTS (
      SELECT 1 FROM public.lead_tags lt WHERE lt.lead_id = l.id AND lt.tag_id = p_tag_id
    ))
    AND (
      v_can_view_all
      OR l.assigned_user_id = ANY(v_visible_user_ids)
      OR l.pipeline_id = ANY(v_visible_pipeline_ids)
    )
  GROUP BY l.source
  ORDER BY lead_count DESC;
END;
$$;


ALTER FUNCTION public.get_lead_sources_data(p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_team_id uuid, p_user_id uuid, p_source text, p_pipeline_id uuid, p_tag_id uuid, p_deal_status text) OWNER TO postgres;

