--
-- Name: get_sla_pending_leads(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_sla_pending_leads() RETURNS TABLE(lead_id uuid, organization_id uuid, pipeline_id uuid, assigned_user_id uuid, lead_name text, sla_start_at timestamp with time zone, current_sla_status text, warn_after_seconds integer, overdue_after_seconds integer, notify_assignee boolean, notify_manager boolean, sla_notified_warning_at timestamp with time zone, sla_notified_overdue_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  select
    l.id as lead_id,
    l.organization_id,
    l.pipeline_id,
    l.assigned_user_id,
    l.name as lead_name,
    public.get_sla_start_at(l.id) as sla_start_at,
    coalesce(l.sla_status, 'ok') as current_sla_status,
    greatest(coalesce(pss.warning_hours, 24), 1) * 3600 as warn_after_seconds,
    greatest(coalesce(pss.critical_hours, 48), 1) * 3600 as overdue_after_seconds,
    true as notify_assignee,
    true as notify_manager,
    l.sla_notified_warning_at,
    l.sla_notified_overdue_at
  from public.leads l
  join lateral (
    select pss.*
    from public.pipeline_sla_settings pss
    where pss.pipeline_id = l.pipeline_id
      and (pss.stage_id = l.stage_id or pss.stage_id is null)
    order by case when pss.stage_id = l.stage_id then 0 else 1 end
    limit 1
  ) pss on true
  where l.pipeline_id is not null
    and l.operational_effects_suppressed = false
    and l.first_response_at is null
    and coalesce(l.deal_status, 'open') not in ('won', 'lost')
    and (l.sla_last_checked_at is null or l.sla_last_checked_at < now() - interval '1 minute')
    and public.get_sla_start_at(l.id) is not null;
end;
$$;


ALTER FUNCTION public.get_sla_pending_leads() OWNER TO postgres;

--
-- Name: get_sla_start_at(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_sla_start_at(p_lead_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lead public.leads%rowtype;
  v_pipeline_start text;
  v_setting_start text;
  v_start_mode text;
begin
  select * into v_lead
  from public.leads
  where id = p_lead_id;

  if not found then
    return null;
  end if;

  select first_response_start into v_pipeline_start
  from public.pipelines
  where id = v_lead.pipeline_id;

  select pss.sla_start_field into v_setting_start
  from public.pipeline_sla_settings pss
  where pss.pipeline_id = v_lead.pipeline_id
    and (pss.stage_id = v_lead.stage_id or pss.stage_id is null)
  order by case when pss.stage_id = v_lead.stage_id then 0 else 1 end
  limit 1;

  v_start_mode := coalesce(v_setting_start, v_pipeline_start, 'created_at');

  if v_start_mode in ('stage_entered', 'stage_entered_at') then
    return coalesce(v_lead.stage_entered_at, v_lead.created_at);
  elsif v_start_mode in ('lead_assigned', 'assigned_at') then
    return coalesce(v_lead.assigned_at, v_lead.created_at);
  else
    return v_lead.created_at;
  end if;
end;
$$;


ALTER FUNCTION public.get_sla_start_at(p_lead_id uuid) OWNER TO postgres;

