--
-- Name: get_user_organization_role(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_organization_role(p_user_id uuid DEFAULT auth.uid()) RETURNS TABLE(role_id uuid, role_name text, role_color text, permissions text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    r.id as role_id,
    r.name as role_name,
    r.color as role_color,
    ARRAY_AGG(orp.permission_key) as permissions
  FROM public.user_organization_roles uor
  JOIN public.organization_roles r ON r.id = uor.organization_role_id
  LEFT JOIN public.organization_role_permissions orp ON orp.organization_role_id = r.id
  WHERE uor.user_id = p_user_id
  GROUP BY r.id, r.name, r.color;
END;
$$;


