--
-- Name: google_calendar_save_token_secret(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.google_calendar_save_token_secret(p_existing_secret_ref uuid, p_secret text, p_name text, p_description text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare secret_id uuid := p_existing_secret_ref;
begin
  perform private.google_calendar_require_backend();
  if nullif(btrim(p_secret), '') is null then raise exception 'Google token required'; end if;
  if secret_id is null then
    secret_id := vault.create_secret(p_secret, p_name, p_description);
  else
    perform vault.update_secret(secret_id, p_secret, p_name, p_description);
  end if;
  return secret_id;
end
$$;


ALTER FUNCTION public.google_calendar_save_token_secret(p_existing_secret_ref uuid, p_secret text, p_name text, p_description text) OWNER TO postgres;

--
-- Name: google_calendar_store_refreshed_token(uuid, bigint, uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.google_calendar_store_refreshed_token(p_connection_id uuid, p_expected_revision bigint, p_expected_secret_ref uuid, p_token jsonb, p_allow_disconnecting boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare connection public.google_calendar_tokens;
begin
  perform private.google_calendar_require_backend();
  perform private.google_calendar_validate_oauth_token(p_token);
  select * into connection from public.google_calendar_tokens where id = p_connection_id for update;
  if connection.id is null or connection.disconnected_at is not null
     or (connection.disconnecting_at is not null and not coalesce(p_allow_disconnecting,false))
     or p_expected_revision is null or connection.credential_revision <> p_expected_revision
     or connection.token_secret_ref is distinct from p_expected_secret_ref
     or connection.token_secret_ref is null
     or not exists(select 1 from vault.secrets where id = connection.token_secret_ref) then
    raise exception 'Google credential changed; discard stale refresh' using errcode = '40001';
  end if;
  perform vault.update_secret(connection.token_secret_ref, p_token::text,
    'google-calendar-' || connection.organization_id::text || '-' || connection.user_id::text || '-' || connection.account_email,
    'Vimob CRM Google Calendar OAuth token');
  -- Access-token rotation does not invalidate a consent/lifecycle snapshot.
  update public.google_calendar_tokens token set expires_at = nullif(p_token->>'expires_at','')::timestamptz
    where token.id = connection.id returning token.* into connection;
  return to_jsonb(connection);
end
$$;


ALTER FUNCTION public.google_calendar_store_refreshed_token(p_connection_id uuid, p_expected_revision bigint, p_expected_secret_ref uuid, p_token jsonb, p_allow_disconnecting boolean) OWNER TO postgres;

--
-- Name: google_calendar_verify_cron_secret(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.google_calendar_verify_cron_secret(p_secret text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform private.google_calendar_require_backend();
  return coalesce(p_secret = (select decrypted_secret from vault.decrypted_secrets
    where name = 'google_calendar_cron_secret' limit 1), false);
end
$$;


ALTER FUNCTION public.google_calendar_verify_cron_secret(p_secret text) OWNER TO postgres;

--
-- Name: handle_deal_status_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_deal_status_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.deal_status = 'won' THEN
    NEW.won_at := COALESCE(NEW.won_at, now());
    NEW.lost_at := NULL;
    NEW.lost_reason := NULL;
  ELSIF NEW.deal_status = 'lost' THEN
    NEW.lost_at := COALESCE(NEW.lost_at, now());
    NEW.won_at := NULL;
  ELSE
    NEW.won_at := NULL;
    NEW.lost_at := NULL;
    NEW.lost_reason := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_deal_status_change() OWNER TO postgres;

--
-- Name: handle_gamification_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_gamification_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_points INTEGER := 0;
    v_action_type TEXT;
    v_org_id UUID;
    v_user_id UUID := NEW.user_id;
BEGIN
    -- Busca organization_id
    SELECT organization_id INTO v_org_id FROM public.users WHERE id = v_user_id;
    IF v_org_id IS NULL THEN
        BEGIN v_org_id := NEW.organization_id; EXCEPTION WHEN others THEN v_org_id := NULL; END;
    END IF;
    IF v_org_id IS NULL THEN RETURN NEW; END IF;

    -- Mapeamento de Tipos
    IF TG_TABLE_NAME = 'activities' THEN
        IF NEW.type IN ('call', 'call_made') THEN v_action_type := 'call_made';
        ELSIF NEW.type = 'sale_closed' THEN v_action_type := 'sale_closed';
        ELSIF NEW.type = 'proposal_sent' THEN v_action_type := 'proposal_sent';
        ELSIF NEW.type IN ('stage_change', 'status_change') THEN
            IF NEW.metadata->>'new_status' = 'won' OR NEW.metadata->>'new_stage_name' ILIKE ANY (ARRAY['%Venda%', '%Ganh%', '%Won%'])
            THEN v_action_type := 'sale_closed';
            ELSE RETURN NEW; END IF;
        ELSE RETURN NEW; END IF;
    ELSIF TG_TABLE_NAME = 'prospecting_reports' THEN
        v_action_type := 'prospecting_report';
        v_points := (COALESCE(NEW.calls, 0) * 1) + (COALESCE(NEW.visits, 0) * 15) + (COALESCE(NEW.property_capturing, 0) * 10) + (COALESCE(NEW.proposals_sent, 0) * 10);
    ELSE RETURN NEW; END IF;

    -- Pontos padrão se não for relatório
    IF v_action_type != 'prospecting_report' THEN
        CASE v_action_type
            WHEN 'sale_closed' THEN v_points := 100;
            WHEN 'proposal_sent' THEN v_points := 20;
            WHEN 'call_made' THEN v_points := 1;
            ELSE v_points := 1;
        END CASE;
    END IF;

    -- Registra Logs e Ranking
    INSERT INTO public.gamification_activity_logs (user_id, organization_id, action_type, points_earned, reference_id, metadata)
    VALUES (v_user_id, v_org_id, v_action_type, v_points, NEW.id, COALESCE(NEW.metadata, '{}'::jsonb));

    INSERT INTO public.user_gamification_stats (user_id, organization_id, total_points, updated_at)
    VALUES (v_user_id, v_org_id, v_points, now())
    ON CONFLICT (user_id) DO UPDATE SET total_points = public.user_gamification_stats.total_points + EXCLUDED.total_points, updated_at = now();

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_gamification_event() OWNER TO postgres;

--
-- Name: handle_lead_intake(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_lead_intake(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_lead RECORD;
  v_org_id uuid;
  v_queue RECORD;
  v_next_user_id uuid;
  v_matched_queue_id uuid;
  v_next_user_name text;
  v_member RECORD;
  v_availability RECORD;
  v_is_available boolean;
  v_current_day integer;
  v_current_time time;
  v_matched_member_id uuid;
  v_log_reason text;
  v_source_label text;
  v_actor_role text;
  v_ignore_availability boolean;
BEGIN
  v_actor_role := COALESCE(auth.role(), '');
  v_current_day := EXTRACT(DOW FROM (NOW() AT TIME ZONE 'America/Sao_Paulo'))::int;
  v_current_time := (NOW() AT TIME ZONE 'America/Sao_Paulo')::time;

  SELECT * INTO v_lead FROM public.leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'lead_not_found');
  END IF;

  v_org_id := v_lead.organization_id;

  IF v_actor_role <> 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.users u
      WHERE u.id = auth.uid()
        AND u.organization_id = v_org_id
        AND COALESCE(u.is_active, true) = true
    ) AND NOT private.is_super_admin() THEN
      RETURN jsonb_build_object('success', false, 'error', 'forbidden');
    END IF;
  END IF;

  v_source_label := CASE v_lead.source
    WHEN 'meta' THEN 'Meta Ads'
    WHEN 'meta_ads' THEN 'Meta Ads'
    WHEN 'whatsapp' THEN 'WhatsApp'
    WHEN 'webhook' THEN 'Webhook'
    WHEN 'website' THEN 'Site'
    WHEN 'site' THEN 'Site'
    WHEN 'manual' THEN 'Manual'
    ELSE COALESCE(v_lead.source, 'manual')
  END;

  IF NOT EXISTS (
    SELECT 1 FROM public.lead_timeline_events
    WHERE lead_id = p_lead_id AND event_type = 'lead_created'
  ) THEN
    INSERT INTO public.lead_timeline_events (
      lead_id, organization_id, user_id, event_type, title, description, metadata
    ) VALUES (
      p_lead_id, v_org_id, NULL, 'lead_created',
      'Lead criado',
      'Lead recebido no sistema',
      jsonb_build_object(
        'source', v_lead.source,
        'source_label', v_source_label,
        'utm_source', v_lead.utm_source,
        'source_webhook_id', v_lead.source_webhook_id,
        'source_session_id', v_lead.source_session_id
      )
    );
  END IF;

  IF v_lead.assigned_user_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'assigned_user_id', v_lead.assigned_user_id,
      'reason', 'already_assigned'
    );
  END IF;

  v_matched_queue_id := public.pick_round_robin_for_lead(p_lead_id);

  IF v_matched_queue_id IS NOT NULL THEN
    SELECT * INTO v_queue
    FROM public.round_robins
    WHERE id = v_matched_queue_id AND is_active = true;
  END IF;

  IF v_queue IS NULL THEN
    INSERT INTO public.round_robin_logs (organization_id, lead_id, reason)
    VALUES (v_org_id, p_lead_id, 'no_matching_queue');

    INSERT INTO public.lead_timeline_events (
      lead_id, organization_id, user_id, event_type, title, description, metadata
    ) VALUES (
      p_lead_id, v_org_id, NULL, 'lead_assigned',
      'Aguardando distribuicao',
      'Nenhuma fila de distribuicao ativa encontrada para as regras deste lead.',
      jsonb_build_object('destination', 'pool', 'reason', 'no_matching_queue')
    );

    RETURN jsonb_build_object('success', false, 'reason', 'no_matching_queue');
  END IF;

  v_ignore_availability := COALESCE(v_queue.settings->>'ignore_availability', 'false') = 'true';

  FOR v_member IN
    SELECT rrm.*, u.name AS user_name, u.is_active AS user_active
    FROM public.round_robin_members rrm
    JOIN public.users u ON u.id = rrm.user_id
    WHERE rrm.round_robin_id = v_queue.id
      AND u.organization_id = v_org_id
      AND COALESCE(rrm.is_active, true) = true
    ORDER BY
      CASE
        WHEN COALESCE(v_queue.strategy, 'simple') = 'weighted'
          THEN (COALESCE(rrm.leads_count, 0)::numeric / GREATEST(COALESCE(rrm.weight, 1), 1))
        ELSE COALESCE(rrm.leads_count, 0)::numeric
      END ASC,
      rrm.position ASC
    FOR UPDATE OF rrm SKIP LOCKED
  LOOP
    CONTINUE WHEN NOT v_member.user_active;

    IF v_ignore_availability THEN
      v_is_available := true;
      v_log_reason := 'queue_ignores_availability';
    ELSE
      SELECT * INTO v_availability
      FROM public.is_user_available_for_distribution(
        v_member.user_id,
        v_member.team_id,
        v_current_day,
        v_current_time
      );

      v_is_available := COALESCE(v_availability.is_available, false);
      v_log_reason := COALESCE(v_availability.reason, 'availability_unknown');
    END IF;

    IF v_is_available THEN
      v_next_user_id := v_member.user_id;
      v_next_user_name := v_member.user_name;
      v_matched_member_id := v_member.id;
      EXIT;
    END IF;
  END LOOP;

  IF v_next_user_id IS NULL THEN
    INSERT INTO public.round_robin_logs (organization_id, round_robin_id, lead_id, reason)
    VALUES (v_org_id, v_queue.id, p_lead_id, 'no_available_members');

    INSERT INTO public.lead_timeline_events (
      lead_id, organization_id, user_id, event_type, title, description, metadata
    ) VALUES (
      p_lead_id, v_org_id, NULL, 'lead_assigned',
      'Aguardando distribuicao',
      'Fila "' || v_queue.name || '" sem membros disponiveis no momento.',
      jsonb_build_object(
        'destination', 'pool',
        'queue_name', v_queue.name,
        'distribution_queue_name', v_queue.name,
        'queue_id', v_queue.id,
        'distribution_queue_id', v_queue.id,
        'reason', 'no_available_members'
      )
    );

    RETURN jsonb_build_object('success', false, 'reason', 'no_available_members', 'round_robin_id', v_queue.id);
  END IF;

  UPDATE public.leads
  SET assigned_user_id = v_next_user_id,
      pipeline_id = COALESCE(v_queue.target_pipeline_id, pipeline_id),
      stage_id = COALESCE(v_queue.target_stage_id, stage_id),
      assigned_at = now(),
      updated_at = now()
  WHERE id = p_lead_id;

  UPDATE public.round_robin_members
  SET leads_count = COALESCE(leads_count, 0) + 1
  WHERE id = v_matched_member_id;

  INSERT INTO public.assignments_log (lead_id, organization_id, round_robin_id, assigned_user_id, reason)
  VALUES (p_lead_id, v_org_id, v_queue.id, v_next_user_id, 'round_robin_auto');

  INSERT INTO public.round_robin_logs (
    organization_id, round_robin_id, lead_id, assigned_user_id, member_id, reason
  ) VALUES (
    v_org_id, v_queue.id, p_lead_id, v_next_user_id, v_matched_member_id,
    jsonb_build_object(
      'type', CASE WHEN v_member.team_id IS NULL THEN 'direct' ELSE 'team' END,
      'availability_check', v_log_reason,
      'queue_name', v_queue.name,
      'strategy', COALESCE(v_queue.strategy, 'simple')
    )::text
  );

  INSERT INTO public.lead_timeline_events (
    lead_id, organization_id, user_id, event_type, title, description, metadata
  ) VALUES (
    p_lead_id, v_org_id, v_next_user_id, 'lead_assigned',
    'Distribuido via "' || v_queue.name || '"',
    'Atribuido a ' || COALESCE(v_next_user_name, 'usuario') || ' pela fila "' || v_queue.name || '"',
    jsonb_build_object(
      'source', v_lead.source,
      'source_label', v_source_label,
      'queue_name', v_queue.name,
      'distribution_queue_name', v_queue.name,
      'queue_id', v_queue.id,
      'distribution_queue_id', v_queue.id,
      'assigned_user_id', v_next_user_id,
      'assigned_user_name', v_next_user_name,
      'to_user_id', v_next_user_id,
      'to_user_name', v_next_user_name,
      'is_initial_distribution', true,
      'distribution_type', 'round_robin'
    )
  );

  IF to_regprocedure('public.notify_whatsapp_on_lead(text, uuid, text, uuid)') IS NOT NULL THEN
    EXECUTE (
      'select ' || quote_ident('public') || '.' || quote_ident('notify_whatsapp_on_lead') ||
      '($1::text, $2::uuid, $3::text, $4::uuid)'
    )
    USING v_lead.name, v_org_id, v_lead.source, v_next_user_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'assigned_user_id', v_next_user_id,
    'assigned_user_name', v_next_user_name,
    'round_robin_id', v_queue.id,
    'round_robin_name', v_queue.name,
    'member_id', v_matched_member_id
  );
END;
$_$;


ALTER FUNCTION public.handle_lead_intake(p_lead_id uuid) OWNER TO postgres;

--
-- Name: handle_managed_whatsapp_message_lead(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_managed_whatsapp_message_lead(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_lead public.leads%rowtype;
  v_marker boolean;
  v_rule_id_text text;
  v_rule_id uuid;
  v_session_id_text text;
  v_session_id uuid;
  v_target_queue_id_text text;
  v_target_queue_id uuid;
  v_resolved_queue_id uuid;
  v_keyword text;
  v_result jsonb;
begin
  select lead.*
    into v_lead
    from public.leads as lead
   where lead.id = p_lead_id
   for update;

  if not found then
    return jsonb_build_object('handled', false, 'success', false, 'reason', 'lead_not_found');
  end if;

  v_marker := lower(btrim(coalesce(
    v_lead.metadata->>'managed_whatsapp_message_distribution',
    'false'
  ))) in ('true', '1', 'yes');

  if not v_marker then
    return jsonb_build_object('handled', false, 'reason', 'not_managed');
  end if;

  insert into public.lead_timeline_events (
    lead_id, organization_id, user_id, event_type, title, description, metadata
  )
  select
    v_lead.id,
    v_lead.organization_id,
    null,
    'lead_created',
    'Lead criado',
    'Lead recebido no sistema',
    jsonb_build_object(
      'source', v_lead.source,
      'source_label', 'WhatsApp',
      'source_session_id', v_lead.source_session_id,
      'matched_rule_id', v_lead.metadata->>'matched_rule_id'
    )
  where not exists (
    select 1
      from public.lead_timeline_events as timeline
     where timeline.organization_id = v_lead.organization_id
       and timeline.lead_id = v_lead.id
       and timeline.event_type = 'lead_created'
  );

  if not public.whatsapp_webhook_has_lead_creation_context(
    coalesce(v_lead.metadata, '{}'::jsonb)
  ) then
    return jsonb_build_object(
      'handled', true,
      'success', false,
      'reason', 'managed_whatsapp_session_invalid'
    );
  end if;

  v_rule_id_text := btrim(coalesce(v_lead.metadata->>'matched_rule_id', ''));
  v_session_id_text := btrim(coalesce(v_lead.metadata->>'whatsapp_session_id', ''));
  v_target_queue_id_text := btrim(coalesce(v_lead.metadata->>'target_round_robin_id', ''));

  if v_rule_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or v_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or v_target_queue_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return jsonb_build_object(
      'handled', true,
      'success', false,
      'reason', 'managed_whatsapp_context_invalid'
    );
  end if;

  v_rule_id := v_rule_id_text::uuid;
  v_session_id := v_session_id_text::uuid;
  v_target_queue_id := v_target_queue_id_text::uuid;

  select
    queue.id,
    normalized.keyword
    into v_resolved_queue_id, v_keyword
    from public.round_robin_rules as round_robin_rule
    join public.whatsapp_inbound_rules as inbound_rule
      on inbound_rule.organization_id = round_robin_rule.organization_id
     and inbound_rule.id = round_robin_rule.id
     and inbound_rule.target_round_robin_id = round_robin_rule.round_robin_id
    join public.whatsapp_sessions as whatsapp_session
      on whatsapp_session.organization_id = inbound_rule.organization_id
     and whatsapp_session.id = inbound_rule.session_id
    join public.round_robins as queue
      on queue.organization_id = round_robin_rule.organization_id
     and queue.id = round_robin_rule.round_robin_id
    cross join lateral (
      select btrim(coalesce(
        nullif(round_robin_rule.match_value, ''),
        round_robin_rule.conditions->>'match_value',
        ''
      )) as keyword
    ) as normalized
   where round_robin_rule.organization_id = v_lead.organization_id
     and round_robin_rule.id = v_rule_id
     and round_robin_rule.round_robin_id = v_target_queue_id
     and inbound_rule.session_id = v_session_id
     and v_lead.source_session_id = v_session_id
     and lower(btrim(coalesce(v_lead.source, ''))) = 'whatsapp'
     and coalesce(queue.is_active, true) = true
     and coalesce(round_robin_rule.is_active, true) = true
     and coalesce(inbound_rule.is_active, true) = true
     and whatsapp_session.provider = 'evolution_go'
     and coalesce(whatsapp_session.is_active, true) = true
     and lower(btrim(coalesce(whatsapp_session.status, ''))) not in ('deleted', 'disabled')
     and coalesce(
       nullif(round_robin_rule.match_type, ''),
       round_robin_rule.conditions->>'match_type',
       round_robin_rule.name,
       ''
     ) = 'whatsapp_message_contains'
     and coalesce(
       nullif(btrim(round_robin_rule.match->>'whatsapp_session_id'), ''),
       nullif(btrim(round_robin_rule.conditions->'match'->>'whatsapp_session_id'), '')
     ) = v_session_id::text
     and lower(btrim(coalesce(inbound_rule.match_type, ''))) = 'contains'
     and lower(btrim(coalesce(inbound_rule.match_field, 'message'))) = 'message'
     and normalized.keyword <> ''
     and lower(btrim(coalesce(inbound_rule.match_value, ''))) = lower(normalized.keyword)
     and lower(btrim(coalesce(queue.settings->>'require_checkin', 'false')))
       not in ('true', '1', 'yes')
     and private.whatsapp_managed_initial_proof_matches(
       v_lead.organization_id,
       v_lead.id,
       v_session_id,
       btrim(coalesce(
         v_lead.metadata->>'managed_whatsapp_initial_provider_event_id',
         ''
       )),
       null,
       v_rule_id,
       v_target_queue_id
     )
   limit 1;

  if not found then
    insert into public.round_robin_logs (
      organization_id, round_robin_id, lead_id, rule_matched, reason, metadata
    ) values (
      v_lead.organization_id,
      v_target_queue_id,
      v_lead.id,
      v_rule_id,
      'managed_whatsapp_rule_mismatch',
      jsonb_build_object(
        'managed_whatsapp_message_distribution', true,
        'whatsapp_session_id', v_session_id
      )
    );

    return jsonb_build_object(
      'handled', true,
      'success', false,
      'reason', 'managed_whatsapp_rule_mismatch',
      'round_robin_id', v_target_queue_id
    );
  end if;

  v_result := private.distribute_lead(
    v_lead.organization_id,
    v_lead.id,
    'managed-whatsapp:' || v_lead.id::text || ':' || v_rule_id::text,
    v_resolved_queue_id,
    true,
    'whatsapp',
    coalesce(v_lead.created_at, clock_timestamp())
  );

  update public.round_robin_logs as distribution_log
     set rule_matched = coalesce(distribution_log.rule_matched, v_rule_id),
         metadata = coalesce(distribution_log.metadata, '{}'::jsonb) || jsonb_build_object(
           'managed_whatsapp_message_distribution', true,
           'matched_rule_id', v_rule_id,
           'whatsapp_session_id', v_session_id,
           'keyword', v_keyword
         )
   where distribution_log.organization_id = v_lead.organization_id
     and distribution_log.round_robin_id = v_resolved_queue_id
     and distribution_log.lead_id = v_lead.id
     and distribution_log.metadata->>'distribution_event_id' = v_result->>'distribution_event_id';

  return jsonb_build_object(
    'handled', true,
    'matched_rule_id', v_rule_id,
    'keyword', v_keyword
  ) || coalesce(v_result, '{}'::jsonb);
end;
$_$;


