--
-- Name: handle_routed_lead_intake(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_routed_lead_intake(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_lead public.leads%rowtype;
  v_target_round_robin_id_text text;
  v_target_round_robin_id uuid;
begin
  select lead.*
    into v_lead
    from public.leads lead
   where lead.id = p_lead_id;

  if not found then
    return jsonb_build_object('handled', false, 'success', false, 'reason', 'lead_not_found');
  end if;

  if lower(btrim(coalesce(v_lead.metadata->>'managed_whatsapp_message_distribution', 'false')))
       in ('true', '1', 'yes') then
    -- Never fall through to generic distribution for a lead explicitly marked
    -- as campaign-managed, even if its rule or queue is unavailable.
    if not public.whatsapp_webhook_has_lead_creation_context(
      coalesce(v_lead.metadata, '{}'::jsonb)
    ) then
      return jsonb_build_object(
        'handled', true,
        'success', false,
        'reason', 'managed_whatsapp_session_invalid'
      );
    end if;
    return public.handle_managed_whatsapp_message_lead(p_lead_id);
  end if;

  if lower(btrim(coalesce(v_lead.metadata->>'distribution_deferred', 'false')))
       in ('true', '1', 'yes') then
    return jsonb_build_object(
      'handled', false,
      'success', false,
      'reason', 'distribution_deferred'
    );
  end if;

  v_target_round_robin_id_text := btrim(coalesce(v_lead.metadata->>'target_round_robin_id', ''));
  if v_target_round_robin_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_target_round_robin_id := v_target_round_robin_id_text::uuid;
  end if;

  return private.distribute_lead(
    v_lead.organization_id,
    v_lead.id,
    'trigger:' || v_lead.id::text,
    v_target_round_robin_id,
    true,
    v_lead.source,
    coalesce(v_lead.created_at, clock_timestamp())
  );
end;
$_$;


