    AS $$ BEGIN INSERT INTO public.financial_categories (organization_id, name, type, category_group) VALUES (p_org_id, 'Venda de Imóveis', 'income', 'revenue'), (p_org_id, 'Comissões Recebidas', 'income', 'revenue'), (p_org_id, 'Aluguéis', 'income', 'revenue'), (p_org_id, 'Outras Receitas', 'income', 'revenue'), (p_org_id, 'Impostos sobre Vendas', 'expense', 'tax_deduction'), (p_org_id, 'Cancelamentos/Devoluções', 'expense', 'tax_deduction'), (p_org_id, 'Comissões Pagas (Corretores)', 'expense', 'variable_cost'), (p_org_id, 'Marketing e Leads', 'expense', 'variable_cost'), (p_org_id, 'Taxas de Franquia', 'expense', 'variable_cost'), (p_org_id, 'Custos de Obra/Reforma', 'expense', 'variable_cost'), (p_org_id, 'Aluguel Escritório', 'expense', 'fixed_cost'), (p_org_id, 'Salários e Encargos', 'expense', 'fixed_cost'), (p_org_id, 'Softwares e Tecnologia', 'expense', 'fixed_cost'), (p_org_id, 'Energia/Água/Internet', 'expense', 'fixed_cost'), (p_org_id, 'Material de Escritório', 'expense', 'fixed_cost') ON CONFLICT (organization_id, name) DO NOTHING; END; $$;


