--
-- Name: list_all_organizations_admin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_all_organizations_admin() RETURNS TABLE(id uuid, name text, logo_url text, is_active boolean, subscription_status text, max_users integer, admin_notes text, created_at timestamp with time zone, last_access_at timestamp with time zone, user_count bigint, lead_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Verificar se é super_admin
  IF NOT is_super_admin() THEN
    RAISE EXCEPTION 'Acesso negado: apenas super admins podem acessar esta função';
  END IF;

  RETURN QUERY
  SELECT
    o.id,
    o.name,
    o.logo_url,
    COALESCE(o.is_active, true) as is_active,
    COALESCE(o.subscription_status, 'trial') as subscription_status,
    COALESCE(o.max_users, 10) as max_users,
    o.admin_notes,
    o.created_at,
    o.last_access_at,
    (SELECT COUNT(*) FROM public.users u WHERE u.organization_id = o.id)::bigint as user_count,
    (SELECT COUNT(*) FROM public.leads l WHERE l.organization_id = o.id)::bigint as lead_count
  FROM public.organizations o
  ORDER BY o.created_at DESC;
END;
$$;


ALTER FUNCTION public.list_all_organizations_admin() OWNER TO postgres;

--
-- Name: list_all_users_admin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_all_users_admin() RETURNS TABLE(id uuid, name text, email text, role text, organization_id uuid, organization_name text, avatar_url text, is_active boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Verificar se é super_admin
  IF NOT is_super_admin() THEN
    RAISE EXCEPTION 'Acesso negado: apenas super admins podem acessar esta função';
  END IF;

  RETURN QUERY
  SELECT
    u.id,
    u.name,
    u.email,
    u.role,
    u.organization_id,
    o.name as organization_name,
    u.avatar_url,
    u.is_active,
    u.created_at
  FROM public.users u
  LEFT JOIN public.organizations o ON o.id = u.organization_id
  ORDER BY u.created_at DESC;
END;
$$;


ALTER FUNCTION public.list_all_users_admin() OWNER TO postgres;

--
-- Name: list_contacts_paginated(text, uuid, uuid, uuid, uuid, boolean, uuid, text, text, text, text, text, text, integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_contacts_paginated(p_search text DEFAULT NULL::text, p_team_id uuid DEFAULT NULL::uuid, p_pipeline_id uuid DEFAULT NULL::uuid, p_stage_id uuid DEFAULT NULL::uuid, p_assignee_id uuid DEFAULT NULL::uuid, p_unassigned boolean DEFAULT false, p_tag_id uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text, p_deal_status text DEFAULT NULL::text, p_created_from text DEFAULT NULL::text, p_created_to text DEFAULT NULL::text, p_sort_by text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text, p_page integer DEFAULT 1, p_limit integer DEFAULT 25, p_campaign_id text DEFAULT NULL::text, p_adset_id text DEFAULT NULL::text, p_ad_id text DEFAULT NULL::text) RETURNS TABLE(id uuid, name text, phone text, email text, whatsapp_avatar_url text, pipeline_id uuid, stage_id uuid, stage_name text, stage_color text, assigned_user_id uuid, assignee_name text, assignee_avatar text, source text, created_at timestamp with time zone, sla_status text, last_interaction_at timestamp with time zone, last_interaction_preview text, last_interaction_channel text, tags jsonb, total_count bigint, deal_status text, lost_reason text, last_entry_at timestamp with time zone, reentry_count integer, pipeline_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_user_role text;
  v_can_view_all boolean := false;
  v_can_view_team boolean := false;
  v_team_member_ids uuid[] := ARRAY[]::uuid[];
  v_filter_team_member_ids uuid[] := NULL;
  v_led_pipeline_ids uuid[] := ARRAY[]::uuid[];
  v_page integer := GREATEST(COALESCE(p_page, 1), 1);
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 10000);
  v_offset integer := 0;
  v_total bigint := 0;
  v_search_digits text := regexp_replace(COALESCE(p_search, ''), '\\D', '', 'g');
BEGIN
  v_offset := (v_page - 1) * v_limit;

  SELECT u.organization_id, u.role
  INTO v_org_id, v_user_role
  FROM public.users u
  WHERE u.id = v_user_id
  LIMIT 1;

  IF v_org_id IS NULL THEN
    RETURN;
  END IF;

  IF p_team_id IS NOT NULL THEN
    SELECT COALESCE(ARRAY(
      SELECT DISTINCT tm.user_id
      FROM public.team_members tm
      JOIN public.teams t ON t.id = tm.team_id
      WHERE tm.team_id = p_team_id
        AND t.organization_id = v_org_id
    ), ARRAY[]::uuid[])
    INTO v_filter_team_member_ids;
  END IF;

  IF v_user_role IN ('admin', 'super_admin') THEN
    v_can_view_all := true;
    v_can_view_team := true;
  ELSE
    SELECT
      EXISTS (
        SELECT 1
        FROM public.user_organization_roles uor
        JOIN public.organization_role_permissions orp
          ON orp.organization_role_id = uor.organization_role_id
        WHERE uor.user_id = v_user_id
          AND orp.permission_key = 'lead_view_all'
      ),
      EXISTS (
        SELECT 1
        FROM public.user_organization_roles uor
        JOIN public.organization_role_permissions orp
          ON orp.organization_role_id = uor.organization_role_id
        WHERE uor.user_id = v_user_id
          AND orp.permission_key = 'lead_view_team'
      )
    INTO v_can_view_all, v_can_view_team;
  END IF;

  IF v_can_view_team AND NOT v_can_view_all THEN
    SELECT COALESCE(
      ARRAY(
        SELECT DISTINCT tm.user_id
        FROM public.team_members tm
        WHERE tm.team_id IN (
          SELECT tm_self.team_id
          FROM public.team_members tm_self
          WHERE tm_self.user_id = v_user_id
        )
      ),
      ARRAY[]::uuid[]
    )
    INTO v_team_member_ids;

    SELECT COALESCE(
      ARRAY(SELECT public.get_user_led_pipeline_ids()),
      ARRAY[]::uuid[]
    )
    INTO v_led_pipeline_ids;

    IF NOT (v_user_id = ANY(v_team_member_ids)) THEN
      v_team_member_ids := array_append(v_team_member_ids, v_user_id);
    END IF;
  END IF;

  SELECT COUNT(*)
  INTO v_total
  FROM public.leads l
  WHERE l.organization_id = v_org_id
    AND (
      v_can_view_all
      OR (
        v_can_view_team
        AND (
          l.assigned_user_id = ANY(v_team_member_ids)
          OR l.pipeline_id = ANY(v_led_pipeline_ids)
        )
      )
      OR l.assigned_user_id = v_user_id
    )
    AND (p_team_id IS NULL OR l.assigned_user_id = ANY(v_filter_team_member_ids))
    AND (
      p_search IS NULL OR p_search = ''
      OR l.name ILIKE '%' || p_search || '%'
      OR l.phone ILIKE '%' || p_search || '%'
      OR l.email ILIKE '%' || p_search || '%'
      OR (
        v_search_digits <> ''
        AND length(regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g')) >= 8
        AND (
          regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g') LIKE '%' || v_search_digits || '%'
          OR v_search_digits LIKE '%' || regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g') || '%'
          OR (length(v_search_digits) >= 8 AND right(regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g'), 8) = right(v_search_digits, 8))
          OR (length(v_search_digits) >= 9 AND right(regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g'), 9) = right(v_search_digits, 9))
        )
      )
    )
    AND (p_pipeline_id IS NULL OR l.pipeline_id = p_pipeline_id)
    AND (p_stage_id IS NULL OR l.stage_id = p_stage_id)
    AND (NOT p_unassigned OR l.assigned_user_id IS NULL)
    AND (p_unassigned OR p_assignee_id IS NULL OR l.assigned_user_id = p_assignee_id)
    AND (p_source IS NULL OR p_source = '' OR l.source = p_source)
    AND (p_deal_status IS NULL OR p_deal_status = '' OR l.deal_status = p_deal_status)
    AND (p_created_from IS NULL OR p_created_from = '' OR l.created_at >= p_created_from::timestamptz)
    AND (p_created_to IS NULL OR p_created_to = '' OR l.created_at < (p_created_to::date + interval '1 day'))
    AND (
      p_tag_id IS NULL
      OR EXISTS (
        SELECT 1
        FROM public.lead_tags lt
        WHERE lt.lead_id = l.id
          AND lt.tag_id = p_tag_id
      )
    )
    AND (
      p_campaign_id IS NULL OR p_campaign_id = ''
      OR EXISTS (
        SELECT 1
        FROM public.lead_meta lm
        WHERE lm.lead_id = l.id
          AND (lm.campaign_id = p_campaign_id OR lm.campaign_name = p_campaign_id)
      )
    )
    AND (
      p_adset_id IS NULL OR p_adset_id = ''
      OR EXISTS (
        SELECT 1
        FROM public.lead_meta lm
        WHERE lm.lead_id = l.id
          AND (lm.adset_id = p_adset_id OR lm.adset_name = p_adset_id)
      )
    )
    AND (
      p_ad_id IS NULL OR p_ad_id = ''
      OR EXISTS (
        SELECT 1
        FROM public.lead_meta lm
        WHERE lm.lead_id = l.id
          AND (lm.ad_id = p_ad_id OR lm.ad_name = p_ad_id)
      )
    );

  RETURN QUERY
  SELECT
    l.id,
    l.name,
    l.phone,
    l.email,
    l.whatsapp_avatar_url,
    l.pipeline_id,
    l.stage_id,
    s.name AS stage_name,
    s.color AS stage_color,
    l.assigned_user_id,
    u.name AS assignee_name,
    u.avatar_url AS assignee_avatar,
    l.source,
    l.created_at,
    NULL::text AS sla_status,
    COALESCE(l.last_entry_at, l.created_at) AS last_interaction_at,
    NULL::text AS last_interaction_preview,
    NULL::text AS last_interaction_channel,
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', t.id,
            'name', t.name,
            'color', t.color
          )
        )
        FROM public.lead_tags lt
        JOIN public.tags t ON t.id = lt.tag_id
        WHERE lt.lead_id = l.id
      ),
      '[]'::jsonb
    ) AS tags,
    v_total AS total_count,
    l.deal_status,
    l.lost_reason,
    l.last_entry_at,
    l.reentry_count,
    p.name AS pipeline_name
  FROM public.leads l
  LEFT JOIN public.stages s ON s.id = l.stage_id
  LEFT JOIN public.pipelines p ON p.id = l.pipeline_id
  LEFT JOIN public.users u ON u.id = l.assigned_user_id
  WHERE l.organization_id = v_org_id
    AND (
      v_can_view_all
      OR (
        v_can_view_team
        AND (
          l.assigned_user_id = ANY(v_team_member_ids)
          OR l.pipeline_id = ANY(v_led_pipeline_ids)
        )
      )
      OR l.assigned_user_id = v_user_id
    )
    AND (p_team_id IS NULL OR l.assigned_user_id = ANY(v_filter_team_member_ids))
    AND (
      p_search IS NULL OR p_search = ''
      OR l.name ILIKE '%' || p_search || '%'
      OR l.phone ILIKE '%' || p_search || '%'
      OR l.email ILIKE '%' || p_search || '%'
      OR (
        v_search_digits <> ''
        AND length(regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g')) >= 8
        AND (
          regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g') LIKE '%' || v_search_digits || '%'
          OR v_search_digits LIKE '%' || regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g') || '%'
          OR (length(v_search_digits) >= 8 AND right(regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g'), 8) = right(v_search_digits, 8))
          OR (length(v_search_digits) >= 9 AND right(regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g'), 9) = right(v_search_digits, 9))
        )
      )
    )
    AND (p_pipeline_id IS NULL OR l.pipeline_id = p_pipeline_id)
    AND (p_stage_id IS NULL OR l.stage_id = p_stage_id)
    AND (NOT p_unassigned OR l.assigned_user_id IS NULL)
    AND (p_unassigned OR p_assignee_id IS NULL OR l.assigned_user_id = p_assignee_id)
    AND (p_source IS NULL OR p_source = '' OR l.source = p_source)
    AND (p_deal_status IS NULL OR p_deal_status = '' OR l.deal_status = p_deal_status)
    AND (p_created_from IS NULL OR p_created_from = '' OR l.created_at >= p_created_from::timestamptz)
    AND (p_created_to IS NULL OR p_created_to = '' OR l.created_at < (p_created_to::date + interval '1 day'))
    AND (
      p_tag_id IS NULL
      OR EXISTS (
        SELECT 1
        FROM public.lead_tags lt
        WHERE lt.lead_id = l.id
          AND lt.tag_id = p_tag_id
      )
    )
    AND (
      p_campaign_id IS NULL OR p_campaign_id = ''
      OR EXISTS (
        SELECT 1
        FROM public.lead_meta lm
        WHERE lm.lead_id = l.id
          AND (lm.campaign_id = p_campaign_id OR lm.campaign_name = p_campaign_id)
      )
    )
    AND (
      p_adset_id IS NULL OR p_adset_id = ''
      OR EXISTS (
        SELECT 1
        FROM public.lead_meta lm
        WHERE lm.lead_id = l.id
          AND (lm.adset_id = p_adset_id OR lm.adset_name = p_adset_id)
      )
    )
    AND (
      p_ad_id IS NULL OR p_ad_id = ''
      OR EXISTS (
        SELECT 1
        FROM public.lead_meta lm
        WHERE lm.lead_id = l.id
          AND (lm.ad_id = p_ad_id OR lm.ad_name = p_ad_id)
      )
    )
  ORDER BY
    CASE WHEN p_sort_by = 'created_at' AND p_sort_dir = 'desc' THEN l.created_at END DESC,
    CASE WHEN p_sort_by = 'created_at' AND p_sort_dir = 'asc' THEN l.created_at END ASC,
    CASE WHEN p_sort_by = 'last_interaction_at' AND p_sort_dir = 'desc' THEN COALESCE(l.last_entry_at, l.created_at) END DESC,
    CASE WHEN p_sort_by = 'last_interaction_at' AND p_sort_dir = 'asc' THEN COALESCE(l.last_entry_at, l.created_at) END ASC,
    CASE WHEN p_sort_by = 'name' AND p_sort_dir = 'desc' THEN l.name END DESC,
    CASE WHEN p_sort_by = 'name' AND p_sort_dir = 'asc' THEN l.name END ASC,
    CASE WHEN p_sort_by = 'stage' AND p_sort_dir = 'desc' THEN s.position END DESC,
    CASE WHEN p_sort_by = 'stage' AND p_sort_dir = 'asc' THEN s.position END ASC,
    COALESCE(l.last_entry_at, l.created_at) DESC
  LIMIT v_limit
  OFFSET v_offset;
END;
$$;


ALTER FUNCTION public.list_contacts_paginated(p_search text, p_team_id uuid, p_pipeline_id uuid, p_stage_id uuid, p_assignee_id uuid, p_unassigned boolean, p_tag_id uuid, p_source text, p_deal_status text, p_created_from text, p_created_to text, p_sort_by text, p_sort_dir text, p_page integer, p_limit integer, p_campaign_id text, p_adset_id text, p_ad_id text) OWNER TO postgres;

--
-- Name: log_commission_lead_activity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_commission_lead_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_id uuid;
BEGIN
  IF NEW.lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_actor_id := COALESCE(NEW.approved_by, NEW.paid_by, auth.uid(), NEW.user_id);

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.activities (lead_id, user_id, type, content, metadata)
    VALUES (
      NEW.lead_id,
      v_actor_id,
      'commission_created',
      'Comissão registrada',
      jsonb_build_object(
        'commission_id', NEW.id,
        'status', NEW.status,
        'amount', NEW.amount,
        'base_value', NEW.base_value,
        'percentage', NEW.percentage
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND (
       OLD.status IS DISTINCT FROM NEW.status OR
       OLD.amount IS DISTINCT FROM NEW.amount OR
       OLD.base_value IS DISTINCT FROM NEW.base_value OR
       OLD.percentage IS DISTINCT FROM NEW.percentage
     ) THEN
    INSERT INTO public.activities (lead_id, user_id, type, content, metadata)
    VALUES (
      NEW.lead_id,
      v_actor_id,
      'commission_updated',
      'Comissão atualizada',
      jsonb_build_object(
        'commission_id', NEW.id,
        'old_status', OLD.status,
        'new_status', NEW.status,
        'old_amount', OLD.amount,
        'new_amount', NEW.amount,
        'old_base_value', OLD.base_value,
        'new_base_value', NEW.base_value,
        'old_percentage', OLD.percentage,
        'new_percentage', NEW.percentage
      )
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.log_commission_lead_activity() OWNER TO postgres;

--
-- Name: log_commission_status_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_commission_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.commission_history (commission_id, organization_id, old_status, new_status, changed_by, notes)
    VALUES (NEW.id, NEW.organization_id, NULL, NEW.status, auth.uid(), 'Criação da comissão');
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND COALESCE(OLD.status,'') <> COALESCE(NEW.status,'') THEN
    INSERT INTO public.commission_history (commission_id, organization_id, old_status, new_status, changed_by, notes)
    VALUES (
      NEW.id,
      NEW.organization_id,
      OLD.status,
      NEW.status,
      COALESCE(NEW.approved_by, NEW.paid_by, auth.uid()),
      CASE
        WHEN NEW.status = 'pending'   THEN 'Liberada após pagamento do contrato'
        WHEN NEW.status = 'approved'  THEN 'Comissão aprovada'
        WHEN NEW.status = 'paid'      THEN 'Pagamento registrado'
        WHEN NEW.status = 'cancelled' THEN COALESCE(NEW.notes, 'Comissão cancelada')
        ELSE NULL
      END
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.log_commission_status_change() OWNER TO postgres;

--
-- Name: log_lead_activity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_lead_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_stage_name text;
  v_new_stage_name text;
  v_old_assignee_name text;
  v_new_assignee_name text;
  v_actor_id uuid;
  v_changed_fields text[];
BEGIN
  v_actor_id := auth.uid();

  IF v_actor_id IS NULL THEN
    v_actor_id := NEW.assigned_user_id;
  END IF;

  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.stage_id IS DISTINCT FROM NEW.stage_id THEN
      SELECT name INTO v_old_stage_name FROM public.stages WHERE id = OLD.stage_id;
      SELECT name INTO v_new_stage_name FROM public.stages WHERE id = NEW.stage_id;

      INSERT INTO public.activities (lead_id, user_id, type, content, metadata)
      VALUES (
        NEW.id,
        v_actor_id,
        'stage_change',
        'Movido de "' || COALESCE(v_old_stage_name, 'Desconhecido') || '" para "' || COALESCE(v_new_stage_name, 'Desconhecido') || '"',
        jsonb_build_object(
          'from_stage', v_old_stage_name,
          'to_stage', v_new_stage_name,
          'from_stage_id', OLD.stage_id,
          'to_stage_id', NEW.stage_id,
          'actor_id', v_actor_id
        )
      );
    END IF;

    IF OLD.assigned_user_id IS DISTINCT FROM NEW.assigned_user_id THEN
      SELECT name INTO v_old_assignee_name FROM public.users WHERE id = OLD.assigned_user_id;
      SELECT name INTO v_new_assignee_name FROM public.users WHERE id = NEW.assigned_user_id;

      INSERT INTO public.activities (lead_id, user_id, type, content, metadata)
      VALUES (
        NEW.id,
        v_actor_id,
        'assignee_changed',
        CASE
          WHEN NEW.assigned_user_id IS NULL THEN 'Responsável removido'
          WHEN OLD.assigned_user_id IS NULL THEN 'Atribuído para ' || COALESCE(v_new_assignee_name, 'Desconhecido')
          ELSE 'Responsável alterado de ' || COALESCE(v_old_assignee_name, 'Desconhecido') || ' para ' || COALESCE(v_new_assignee_name, 'Desconhecido')
        END,
        jsonb_build_object(
          'from_user_id', OLD.assigned_user_id,
          'to_user_id', NEW.assigned_user_id,
          'from_user_name', v_old_assignee_name,
          'to_user_name', v_new_assignee_name,
          'actor_id', v_actor_id
        )
      );
    END IF;

    IF OLD.deal_status IS DISTINCT FROM NEW.deal_status THEN
      INSERT INTO public.activities (lead_id, user_id, type, content, metadata)
      VALUES (
        NEW.id,
        v_actor_id,
        'status_change',
        CASE NEW.deal_status
          WHEN 'won' THEN 'Status alterado para Ganho'
          WHEN 'lost' THEN 'Status alterado para Perdido'
          ELSE 'Status alterado para Aberto'
        END,
        jsonb_build_object(
          'from_status', OLD.deal_status,
          'to_status', NEW.deal_status,
          'actor_id', v_actor_id
        )
      );
    END IF;

    v_changed_fields := array_remove(ARRAY[
      CASE WHEN OLD.name IS DISTINCT FROM NEW.name THEN 'name' END,
      CASE WHEN OLD.phone IS DISTINCT FROM NEW.phone THEN 'phone' END,
      CASE WHEN OLD.email IS DISTINCT FROM NEW.email THEN 'email' END,
      CASE WHEN OLD.cargo IS DISTINCT FROM NEW.cargo THEN 'cargo' END,
      CASE WHEN OLD.empresa IS DISTINCT FROM NEW.empresa THEN 'empresa' END,
      CASE WHEN OLD.endereco IS DISTINCT FROM NEW.endereco THEN 'endereco' END,
      CASE WHEN OLD.numero IS DISTINCT FROM NEW.numero THEN 'numero' END,
      CASE WHEN OLD.complemento IS DISTINCT FROM NEW.complemento THEN 'complemento' END,
      CASE WHEN OLD.bairro IS DISTINCT FROM NEW.bairro THEN 'bairro' END,
      CASE WHEN OLD.cidade IS DISTINCT FROM NEW.cidade THEN 'cidade' END,
      CASE WHEN OLD.uf IS DISTINCT FROM NEW.uf THEN 'uf' END,
      CASE WHEN OLD.cep IS DISTINCT FROM NEW.cep THEN 'cep' END,
      CASE WHEN OLD.message IS DISTINCT FROM NEW.message THEN 'message' END,
      CASE WHEN OLD.valor_interesse IS DISTINCT FROM NEW.valor_interesse THEN 'valor_interesse' END,
      CASE WHEN OLD.property_id IS DISTINCT FROM NEW.property_id THEN 'property_id' END,
      CASE WHEN OLD.property_code IS DISTINCT FROM NEW.property_code THEN 'property_code' END,
      CASE WHEN OLD.commission_percentage IS DISTINCT FROM NEW.commission_percentage THEN 'commission_percentage' END,
      CASE WHEN OLD.feedback IS DISTINCT FROM NEW.feedback THEN 'feedback' END,
      CASE WHEN OLD.renda_familiar IS DISTINCT FROM NEW.renda_familiar THEN 'renda_familiar' END,
      CASE WHEN OLD.profissao IS DISTINCT FROM NEW.profissao THEN 'profissao' END,
      CASE WHEN OLD.faixa_valor_imovel IS DISTINCT FROM NEW.faixa_valor_imovel THEN 'faixa_valor_imovel' END
    ], NULL);

    IF array_length(v_changed_fields, 1) > 0 THEN
      INSERT INTO public.activities (lead_id, user_id, type, content, metadata)
      VALUES (
        NEW.id,
        v_actor_id,
        'contact_updated',
        'Informações do lead atualizadas',
        jsonb_build_object(
          'fields_updated', v_changed_fields,
          'actor_id', v_actor_id
        )
      );
    END IF;

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.log_lead_activity() OWNER TO postgres;

--
-- Name: log_platform_event_org_created(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_platform_event_org_created() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.platform_events (organization_id, type, severity, title, description, metadata)
  VALUES (
    NEW.id,
    'organization_created',
    'success',
    'Nova organização criada',
    NEW.name,
    jsonb_build_object('subscription_type', NEW.subscription_type, 'plan_id', NEW.plan_id)
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.log_platform_event_org_created() OWNER TO postgres;

--
-- Name: log_platform_event_payment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_platform_event_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'paid' AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    INSERT INTO public.platform_events (organization_id, type, severity, title, description, metadata)
    VALUES (
      NEW.organization_id,
      'payment_received',
      'success',
      'Pagamento recebido',
      COALESCE(NEW.description, 'Pagamento confirmado'),
      jsonb_build_object('amount', NEW.paid_amount, 'entry_id', NEW.id)
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.log_platform_event_payment() OWNER TO postgres;

--
-- Name: lookup_managed_whatsapp_lead_entry(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lookup_managed_whatsapp_lead_entry(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_message text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_provider_message_id text := btrim(coalesce(p_provider_message_id, ''));
  v_provider_event_id text;
  v_message_fingerprint text;
  v_existing_entry public.lead_entry_events%rowtype;
  v_pending_lead public.leads%rowtype;
  v_pending_log public.whatsapp_inbound_logs%rowtype;
  v_legacy_log public.whatsapp_inbound_logs%rowtype;
  v_legacy_message public.whatsapp_messages%rowtype;
  v_intake_result jsonb := '{}'::jsonb;
  v_rule_id_text text;
  v_round_robin_id_text text;
  v_session_id_text text;
  v_log_message_fingerprint text;
  v_has_persisted_message boolean := false;
begin
  -- This lookup runs for every inbound payload, including media without text.
  -- Missing identity is simply not a managed ledger hit and must not create an
  -- endless webhook retry.
  if p_organization_id is null
     or p_session_id is null
     or length(v_provider_message_id) not between 1 and 500
     or p_provider_message_id <> v_provider_message_id then
    return jsonb_build_object('handled', false, 'pending', false);
  end if;

  v_provider_event_id := p_session_id::text || ':' || v_provider_message_id;
  v_message_fingerprint := private.managed_whatsapp_message_fingerprint(
    p_organization_id,
    p_session_id,
    v_provider_message_id,
    p_message
  );

  select entry.*
    into v_existing_entry
    from public.lead_entry_events as entry
   where entry.organization_id = p_organization_id
     and entry.provider = 'whatsapp'
     and entry.provider_event_id = v_provider_event_id
     and entry.is_countable = true
   limit 1;

  if found then
    if coalesce(v_existing_entry.metadata->>'message_fingerprint', '')
         is distinct from v_message_fingerprint
       or not exists (
         select 1
         from public.leads as ledger_lead
         where ledger_lead.organization_id = p_organization_id
           and ledger_lead.id = v_existing_entry.lead_id
       ) then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_provider_message_collision';
    end if;

    if jsonb_typeof(v_existing_entry.metadata->'intake_result') = 'object' then
      v_intake_result := v_existing_entry.metadata->'intake_result';
    else
      -- The provider ledger remains authoritative even if a legacy/corrupt row
      -- is missing the cached response. Never manufacture a successful outcome.
      v_intake_result := jsonb_build_object(
        'success', false,
        'reason', 'managed_whatsapp_ledger_result_missing'
      );
    end if;

    return v_intake_result || jsonb_build_object(
      'handled', true,
      'pending', false,
      'duplicate_retry', true,
      'lead_id', v_existing_entry.lead_id,
      'entry_event_id', v_existing_entry.id,
      'matched_rule_id', nullif(v_existing_entry.metadata->>'matched_rule_id', ''),
      'target_round_robin_id', nullif(coalesce(
        v_existing_entry.metadata->>'target_round_robin_id',
        v_intake_result->>'round_robin_id'
      ), ''),
      'provider_event_id', v_provider_event_id
    );
  end if;

  select lead.*
    into v_pending_lead
    from public.leads as lead
   where lead.organization_id = p_organization_id
     and lower(btrim(coalesce(lead.source, ''))) = 'whatsapp'
     and lead.source_session_id = p_session_id
     and lower(btrim(coalesce(
       lead.metadata->>'managed_whatsapp_message_distribution',
       'false'
     ))) in ('true', '1', 'yes')
     and btrim(coalesce(
       lead.metadata->>'managed_whatsapp_initial_provider_event_id',
       ''
     )) = v_provider_event_id
   order by lead.created_at, lead.id
   limit 1;

  if found then
    if exists (
      select 1
      from public.leads as conflicting_lead
      where conflicting_lead.organization_id = p_organization_id
        and conflicting_lead.id <> v_pending_lead.id
        and lower(btrim(coalesce(conflicting_lead.source, ''))) = 'whatsapp'
        and conflicting_lead.source_session_id = p_session_id
        and lower(btrim(coalesce(
          conflicting_lead.metadata->>'managed_whatsapp_message_distribution',
          'false'
        ))) in ('true', '1', 'yes')
        and btrim(coalesce(
          conflicting_lead.metadata->>'managed_whatsapp_initial_provider_event_id',
          ''
        )) = v_provider_event_id
    )
       or not private.whatsapp_managed_initial_proof_matches(
         p_organization_id,
         v_pending_lead.id,
         p_session_id,
         v_provider_event_id,
         v_message_fingerprint,
         null,
         null
       ) then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_provider_message_collision';
    end if;

    v_rule_id_text := btrim(coalesce(v_pending_lead.metadata->>'matched_rule_id', ''));
    v_round_robin_id_text := btrim(coalesce(
      v_pending_lead.metadata->>'target_round_robin_id',
      ''
    ));
    v_session_id_text := btrim(coalesce(
      v_pending_lead.metadata->>'whatsapp_session_id',
      ''
    ));

    if v_rule_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or v_round_robin_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or v_session_id_text is distinct from p_session_id::text then
      raise exception using
        errcode = '23514',
        message = 'managed_whatsapp_pending_context_invalid';
    end if;

    return jsonb_build_object(
      'handled', false,
      'pending', true,
      'reason', 'managed_whatsapp_intake_pending',
      'lead_id', v_pending_lead.id,
      'matched_rule_id', v_rule_id_text,
      'target_round_robin_id', v_round_robin_id_text,
      'managed_whatsapp_message_distribution', true,
      'provider_event_id', v_provider_event_id
    );
  end if;

  -- Existing leads do not receive a new immutable provider marker. For them,
  -- the inbound log is the pre-ledger provenance: runtimes persist the managed
  -- marker, chosen queue and content fingerprint before calling the intake RPC.
  select inbound_log.*
    into v_pending_log
    from public.whatsapp_inbound_logs as inbound_log
   where inbound_log.organization_id = p_organization_id
     and inbound_log.session_id = p_session_id
     and inbound_log.match_details->>'message_id' = v_provider_message_id
     and lower(btrim(coalesce(
       inbound_log.match_details->>'managed_whatsapp_message_distribution',
       'false'
     ))) in ('true', '1', 'yes')
   order by inbound_log.created_at, inbound_log.id
   limit 1;

  if not found then
    -- A legacy/non-managed log is also an immutable consumption marker. If
    -- its following message write never completed, quarantine the retry before
    -- today's rules can promote the old delivery into managed distribution.
    select inbound_log.*
      into v_legacy_log
      from public.whatsapp_inbound_logs as inbound_log
     where inbound_log.organization_id = p_organization_id
       and inbound_log.session_id = p_session_id
       and inbound_log.match_details->>'message_id' = v_provider_message_id
       and lower(btrim(coalesce(
         inbound_log.match_details->>'managed_whatsapp_message_distribution',
         'false'
       ))) not in ('true', '1', 'yes')
     order by inbound_log.created_at, inbound_log.id
     limit 1;

    if found and exists (
      select 1
      from public.whatsapp_inbound_logs as conflicting_legacy_log
      where conflicting_legacy_log.organization_id = p_organization_id
        and conflicting_legacy_log.session_id = p_session_id
        and conflicting_legacy_log.id <> v_legacy_log.id
        and conflicting_legacy_log.match_details->>'message_id' = v_provider_message_id
        and lower(btrim(coalesce(
          conflicting_legacy_log.match_details->>'managed_whatsapp_message_distribution',
          'false'
        ))) not in ('true', '1', 'yes')
        and (
          conflicting_legacy_log.lead_id is distinct from v_legacy_log.lead_id
          or conflicting_legacy_log.conversation_id
               is distinct from v_legacy_log.conversation_id
          or conflicting_legacy_log.matched_rule_id
               is distinct from v_legacy_log.matched_rule_id
          or btrim(coalesce(
            conflicting_legacy_log.match_details->>'message_fingerprint',
            ''
          )) is distinct from btrim(coalesce(
            v_legacy_log.match_details->>'message_fingerprint',
            ''
          ))
        )
    ) then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_provider_message_collision';
    end if;

    -- A delivery persisted by the legacy/non-managed path is already consumed.
    -- Resolve it before consulting current rules so a later configuration edit
    -- cannot retroactively turn an old inbound message into a managed entry.
    select message.*
      into v_legacy_message
      from public.whatsapp_messages as message
     where message.organization_id = p_organization_id
       and message.session_id = p_session_id
       and (
         message.provider_message_id = v_provider_message_id
         or (
           message.provider_message_id is null
           and message.message_id = v_provider_message_id
         )
       )
     order by message.created_at, message.id
     limit 1;

    if not found then
      if v_legacy_log.id is not null then
        return jsonb_build_object(
          'handled', false,
          'pending', false,
          'quarantined', true,
          'reason', 'legacy_whatsapp_intake_incomplete',
          'lead_id', v_legacy_log.lead_id,
          'matched_rule_id', null,
          'target_round_robin_id', null,
          'provider_event_id', v_provider_event_id
        );
      end if;

      return jsonb_build_object('handled', false, 'pending', false);
    end if;

    if not private.whatsapp_attendance_message_evidence_matches(
         v_legacy_message.capture_state,
         v_legacy_message.content,
         v_legacy_message.metadata,
         v_message_fingerprint,
         p_message
       )
       or coalesce(v_legacy_message.from_me, false) = true
       or lower(coalesce(v_legacy_message.direction, 'inbound')) = 'outbound'
       or (
         v_legacy_log.id is not null
         and (
           v_legacy_log.lead_id is distinct from v_legacy_message.lead_id
           or v_legacy_log.conversation_id
                is distinct from v_legacy_message.conversation_id
         )
       )
       or exists (
         select 1
         from public.whatsapp_messages as conflicting_legacy_message
         where conflicting_legacy_message.organization_id = p_organization_id
           and conflicting_legacy_message.session_id = p_session_id
           and (
             conflicting_legacy_message.provider_message_id = v_provider_message_id
             or (
               conflicting_legacy_message.provider_message_id is null
               and conflicting_legacy_message.message_id = v_provider_message_id
             )
           )
           and (
             not private.whatsapp_attendance_message_evidence_matches(
               conflicting_legacy_message.capture_state,
               conflicting_legacy_message.content,
               conflicting_legacy_message.metadata,
               v_message_fingerprint,
               p_message
             )
             or coalesce(conflicting_legacy_message.from_me, false) = true
             or lower(coalesce(
               conflicting_legacy_message.direction,
               'inbound'
             )) = 'outbound'
             or conflicting_legacy_message.lead_id
                  is distinct from v_legacy_message.lead_id
             or conflicting_legacy_message.conversation_id
                  is distinct from v_legacy_message.conversation_id
           )
       ) then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_provider_message_collision';
    end if;

    return jsonb_build_object(
      'handled', true,
      'pending', false,
      'duplicate_retry', true,
      'legacy_non_managed_retry', true,
      'reason', 'legacy_whatsapp_message_already_persisted',
      'lead_id', v_legacy_message.lead_id,
      'matched_rule_id', null,
      'target_round_robin_id', null,
      'provider_event_id', v_provider_event_id
    );
  end if;

  if exists (
    select 1
    from public.whatsapp_inbound_logs as conflicting_log
    where conflicting_log.organization_id = p_organization_id
      and conflicting_log.session_id = p_session_id
      and conflicting_log.id <> v_pending_log.id
      and conflicting_log.match_details->>'message_id' = v_provider_message_id
      and lower(btrim(coalesce(
        conflicting_log.match_details->>'managed_whatsapp_message_distribution',
        'false'
      ))) in ('true', '1', 'yes')
      and (
        conflicting_log.lead_id is distinct from v_pending_log.lead_id
        or conflicting_log.matched_rule_id is distinct from v_pending_log.matched_rule_id
        or btrim(coalesce(
          conflicting_log.match_details->>'target_round_robin_id',
          ''
        )) is distinct from btrim(coalesce(
          v_pending_log.match_details->>'target_round_robin_id',
          ''
        ))
        or btrim(coalesce(
          conflicting_log.match_details->>'message_fingerprint',
          ''
        )) is distinct from btrim(coalesce(
          v_pending_log.match_details->>'message_fingerprint',
          ''
        ))
      )
  ) then
    raise exception using
      errcode = '23505',
      message = 'managed_whatsapp_provider_message_collision';
  end if;

  v_rule_id_text := btrim(coalesce(v_pending_log.matched_rule_id::text, ''));
  v_round_robin_id_text := btrim(coalesce(
    v_pending_log.match_details->>'target_round_robin_id',
    ''
  ));
  v_log_message_fingerprint := btrim(coalesce(
    v_pending_log.match_details->>'message_fingerprint',
    ''
  ));

  if v_pending_log.lead_id is null
     or v_rule_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or v_round_robin_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or not exists (
       select 1
       from public.leads as lead
       where lead.organization_id = p_organization_id
         and lead.id = v_pending_log.lead_id
     ) then
    raise exception using
      errcode = '23514',
      message = 'managed_whatsapp_pending_context_invalid';
  end if;

  if v_log_message_fingerprint <> ''
     and v_log_message_fingerprint is distinct from v_message_fingerprint then
    raise exception using
      errcode = '23505',
      message = 'managed_whatsapp_provider_message_collision';
  end if;

  select exists (
    select 1
    from public.whatsapp_messages as message
    where message.organization_id = p_organization_id
      and message.session_id = p_session_id
      and message.lead_id = v_pending_log.lead_id
      and message.conversation_id = v_pending_log.conversation_id
      and (
        message.provider_message_id = v_provider_message_id
        or (
          message.provider_message_id is null
          and message.message_id = v_provider_message_id
        )
      )
      and coalesce(message.from_me, false) = false
      and lower(coalesce(message.direction, 'inbound')) <> 'outbound'
      and private.whatsapp_attendance_message_evidence_matches(
        message.capture_state,
        message.content,
        message.metadata,
        v_message_fingerprint,
        p_message
      )
  ) into v_has_persisted_message;

  if exists (
    select 1
    from public.whatsapp_messages as conflicting_message
    where conflicting_message.organization_id = p_organization_id
      and conflicting_message.session_id = p_session_id
      and (
        conflicting_message.provider_message_id = v_provider_message_id
        or (
          conflicting_message.provider_message_id is null
          and conflicting_message.message_id = v_provider_message_id
        )
      )
      and (
        conflicting_message.lead_id is distinct from v_pending_log.lead_id
        or conflicting_message.conversation_id
             is distinct from v_pending_log.conversation_id
        or not private.whatsapp_attendance_message_evidence_matches(
             conflicting_message.capture_state,
             conflicting_message.content,
             conflicting_message.metadata,
             v_message_fingerprint,
             p_message
           )
        or coalesce(conflicting_message.from_me, false) = true
        or lower(coalesce(conflicting_message.direction, 'inbound')) = 'outbound'
      )
  ) then
    raise exception using
      errcode = '23505',
      message = 'managed_whatsapp_provider_message_collision';
  end if;

  if v_log_message_fingerprint = '' and not v_has_persisted_message then
    raise exception using
      errcode = '23514',
      message = 'managed_whatsapp_pending_message_evidence_missing';
  end if;

  return jsonb_build_object(
    'handled', false,
    'pending', true,
    'reason', 'managed_whatsapp_intake_pending',
    'lead_id', v_pending_log.lead_id,
    'matched_rule_id', v_rule_id_text,
    'target_round_robin_id', v_round_robin_id_text,
    'managed_whatsapp_message_distribution', true,
    'provider_event_id', v_provider_event_id
  );
end;
$_$;


ALTER FUNCTION public.lookup_managed_whatsapp_lead_entry(p_organization_id uuid, p_session_id uuid, p_provider_message_id text, p_message text) OWNER TO postgres;

--
-- Name: mark_billing_card_capture_request_started(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_billing_card_capture_request_started(p_payment_id uuid, p_provider_payment_id text, p_attempt_lease_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(
    btrim(coalesce(p_provider_payment_id, '')),
    ''
  );
  v_payment public.asaas_payments%rowtype;
  v_org public.organizations%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if p_payment_id is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255
     or p_attempt_lease_id is null then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  perform private.lock_asaas_billing_resources(v_provider_payment_id, null);

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select capability.*
  into v_capability
  from public.billing_payment_checkout_capabilities as capability
  where capability.payment_id = v_payment.id
    and capability.asaas_payment_id = v_payment.asaas_payment_id
    and capability.organization_id = v_payment.organization_id
    and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;
  if not found
     or v_capability.revoked_at is not null
     or v_capability.expires_at <= v_now
     or v_capability.attempt_lease_id is distinct from p_attempt_lease_id
     or v_capability.attempt_lease_expires_at <= v_now then
    return jsonb_build_object('outcome', 'attempt_lease_not_found');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
    and provision.provider_payment_id = v_payment.asaas_payment_id
    and provision.organization_id = v_payment.organization_id
    and provision.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'not_prepared');
  end if;

  -- Hold the tenant tombstone through the durable capture marker. Cleanup can
  -- therefore never deactivate the organization between this check and the
  -- worker's authorization to call payWithCreditCard.
  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = v_payment.organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;
  if not v_org.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  if v_provision.capture_request_started_at is not null then
    return jsonb_build_object(
      'outcome', case
        when v_provision.capture_attempt_lease_id = p_attempt_lease_id
          then 'already_started'
        else 'recover_only'
      end,
      'payment_id', v_provision.payment_id,
      'capture_request_started_at', v_provision.capture_request_started_at
    );
  end if;
  if v_provision.provider_card_credential is null
     or v_provision.card_last4 is null
     or v_provision.credential_attempt_lease_id
       is distinct from p_attempt_lease_id then
    return jsonb_build_object('outcome', 'credential_not_stored');
  end if;
  if not private.billing_payment_checkout_is_actionable(v_payment.status) then
    return jsonb_build_object(
      'outcome', 'payment_not_actionable',
      'payment_status', upper(btrim(coalesce(v_payment.status, '')))
    );
  end if;

  update private.billing_card_recurrence_provisions as provision
  set
    capture_request_started_at = v_now,
    capture_attempt_lease_id = p_attempt_lease_id,
    updated_at = v_now
  where provision.payment_id = v_provision.payment_id
    and provision.provider_payment_id = v_provision.provider_payment_id
    and provision.capture_request_started_at is null
    and provision.provider_card_credential is not null
    and provision.credential_attempt_lease_id = p_attempt_lease_id;

  if not found then
    return jsonb_build_object('outcome', 'state_changed');
  end if;

  return jsonb_build_object(
    'outcome', 'started',
    'payment_id', v_provision.payment_id,
    'provider_payment_id', v_provision.provider_payment_id,
    'capture_request_started_at', v_now
  );
end
$$;


ALTER FUNCTION public.mark_billing_card_capture_request_started(p_payment_id uuid, p_provider_payment_id text, p_attempt_lease_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION mark_billing_card_capture_request_started(p_payment_id uuid, p_provider_payment_id text, p_attempt_lease_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.mark_billing_card_capture_request_started(p_payment_id uuid, p_provider_payment_id text, p_attempt_lease_id uuid) IS 'Durable exact-lease marker committed immediately before payWithCreditCard; after it exists every retry is GET/reconcile-only and no second POST is authorized.';


--
-- Name: mark_billing_card_recurrence_provider_request_started(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_billing_card_recurrence_provider_request_started(p_payment_id uuid, p_worker_id text, p_job_lease_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_worker_id text := nullif(btrim(coalesce(p_worker_id, '')), '');
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_org public.organizations%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if p_payment_id is null
     or v_worker_id is null
     or char_length(v_worker_id) > 128
     or v_worker_id !~ '^[A-Za-z0-9._:-]+$'
     or p_job_lease_id is null then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = p_payment_id
    and provision.job_status = 'processing'
    and provision.job_action = 'create'
    and provision.status = 'creating'
    and provision.job_locked_by = v_worker_id
    and provision.job_lease_id = p_job_lease_id
    and provision.lease_id = p_job_lease_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = v_provision.organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;
  if not v_org.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  if private.billing_organization_cleanup_is_active(
    v_provision.organization_id,
    v_provision.provider_subscription_id
  ) then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  if v_provision.provider_request_started_at is not null then
    return jsonb_build_object(
      'outcome', 'already_started',
      'payment_id', v_provision.payment_id,
      'provider_request_started_at', v_provision.provider_request_started_at
    );
  end if;

  update private.billing_card_recurrence_provisions as provision
  set
    provider_request_started_at = v_now,
    updated_at = v_now
  where provision.payment_id = v_provision.payment_id
    and provision.job_status = 'processing'
    and provision.job_action = 'create'
    and provision.status = 'creating'
    and provision.job_locked_by = v_worker_id
    and provision.job_lease_id = p_job_lease_id
    and provision.lease_id = p_job_lease_id
    and provision.provider_request_started_at is null;

  if not found then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  return jsonb_build_object(
    'outcome', 'started',
    'payment_id', v_provision.payment_id,
    'provider_request_started_at', v_now
  );
end
$_$;


ALTER FUNCTION public.mark_billing_card_recurrence_provider_request_started(p_payment_id uuid, p_worker_id text, p_job_lease_id uuid) OWNER TO postgres;

--
-- Name: mark_billing_card_recurrence_recovering(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_billing_card_recurrence_recovering(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_error text := left(nullif(btrim(coalesce(p_error, '')), ''), 2000);
  v_payment public.asaas_payments%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
begin
  if p_payment_id is null
     or p_lease_id is null
     or v_provider_payment_id is null
     or v_error is null
     or char_length(v_provider_payment_id) > 255 then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
    and provision.provider_payment_id = v_payment.asaas_payment_id
  for update;

  if not found
     or v_provision.status <> 'creating'
     or v_provision.lease_id is distinct from p_lease_id then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  update private.billing_card_recurrence_provisions
  set
    status = 'recovering',
    provider_card_credential = null,
    card_last4 = null,
    lease_id = null,
    lease_expires_at = null,
    recovering_at = coalesce(recovering_at, clock_timestamp()),
    last_error = v_error,
    updated_at = clock_timestamp()
  where payment_id = v_provision.payment_id;

  return jsonb_build_object(
    'outcome', 'recovering',
    'action', 'recover_only',
    'external_reference', v_provision.external_reference
  );
end
$$;


ALTER FUNCTION public.mark_billing_card_recurrence_recovering(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_error text) OWNER TO postgres;

--
-- Name: FUNCTION mark_billing_card_recurrence_recovering(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_error text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.mark_billing_card_recurrence_recovering(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid, p_error text) IS 'Marks an ambiguous provider result as recover-only and prevents an unsafe duplicate subscription POST.';


--
-- Name: mark_billing_payment_checkout_cancellation_delete_started(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_billing_payment_checkout_cancellation_delete_started(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_provider_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(
    btrim(coalesce(p_provider_payment_id, '')),
    ''
  );
  v_payment public.asaas_payments%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_claim private.billing_payment_checkout_cancellations%rowtype;
  v_org public.organizations%rowtype;
  v_intent private.billing_checkout_intents%rowtype;
  v_customer_id text;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_organization_id is null
     or p_intent_id is null
     or p_claim_token is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255 then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  perform private.lock_asaas_billing_resources(v_provider_payment_id, null);

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.organization_id = p_organization_id
    and payment.billing_intent_id = p_intent_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  select capability.*
  into v_capability
  from public.billing_payment_checkout_capabilities as capability
  where capability.payment_id = v_payment.id
    and capability.asaas_payment_id = v_payment.asaas_payment_id
    and capability.organization_id = v_payment.organization_id
    and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  select cancellation.*
  into v_claim
  from private.billing_payment_checkout_cancellations as cancellation
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id
    and cancellation.payment_id = v_payment.id
    and cancellation.provider_payment_id = v_provider_payment_id
  for update;
  if not found or v_claim.claim_token is distinct from p_claim_token then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;
  if not v_org.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  select intent.*
  into v_intent
  from private.billing_checkout_intents as intent
  where intent.id = p_intent_id
    and intent.organization_id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  if v_claim.finalized_at is not null then
    if v_claim.final_outcome in ('paid_before_delete', 'paid_after_delete') then
      return jsonb_build_object(
        'outcome', 'paid_before_delete',
        'final_outcome', v_claim.final_outcome
      );
    end if;
    if v_claim.final_outcome = 'manual_review' then
      return jsonb_build_object(
        'outcome', 'manual_review',
        'last_error_code', v_claim.last_error_code
      );
    end if;
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  -- Paid evidence always wins before the irreversible provider boundary.
  if v_intent.status = 'confirmed'
     or private.billing_payment_checkout_is_paid(v_payment.status) then
    update private.billing_payment_checkout_cancellations
    set
      finalized_at = v_now,
      final_outcome = 'paid_before_delete',
      paid_won_at = v_now,
      manual_review_at = null,
      updated_at = v_now
    where intent_id = p_intent_id
      and finalized_at is null;

    update public.billing_payment_checkout_capabilities
    set
      revoked_at = coalesce(revoked_at, v_now),
      attempt_lease_id = null,
      attempt_lease_expires_at = null,
      updated_at = v_now
    where payment_id = v_payment.id;

    return jsonb_build_object(
      'outcome', 'paid_before_delete',
      'payment_id', v_provider_payment_id
    );
  end if;

  if v_claim.provider_delete_started_at is not null then
    return jsonb_build_object(
      'outcome', 'already_started',
      'payment_id', v_provider_payment_id,
      'provider_delete_started_at', v_claim.provider_delete_started_at
    );
  end if;

  if v_claim.lease_expires_at <= v_now then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  v_customer_id := nullif(btrim(coalesce(
    v_intent.provider_customer_id,
    v_org.asaas_customer_id,
    v_payment.asaas_customer_id,
    ''
  )), '');

  if v_claim.payment_id is distinct from v_payment.id
     or (
       v_intent.provider_payment_id is not null
       and v_intent.provider_payment_id
         is distinct from v_claim.provider_payment_id
     )
     or v_customer_id is distinct from v_claim.provider_customer_id
     or (
       v_org.asaas_customer_id is not null
       and btrim(v_org.asaas_customer_id)
         is distinct from v_claim.provider_customer_id
     )
     or (
       v_payment.asaas_customer_id is not null
       and btrim(v_payment.asaas_customer_id)
         is distinct from v_claim.provider_customer_id
     )
     or btrim(coalesce(v_intent.external_reference, ''))
       is distinct from v_claim.external_reference
     or round(v_intent.amount::numeric, 2)
       is distinct from round(v_claim.amount::numeric, 2)
     or round(v_payment.value::numeric, 2)
       is distinct from round(v_claim.amount::numeric, 2)
     or upper(btrim(coalesce(v_payment.billing_type, '')))
       is distinct from v_claim.billing_type
     or upper(btrim(coalesce(v_intent.billing_method, '')))
       is distinct from v_claim.billing_type
     or v_payment.due_date is distinct from v_claim.due_date
     or v_intent.provider_subscription_id is not null
     or v_payment.asaas_subscription_id is not null
     or (
       not private.billing_payment_checkout_is_actionable(v_payment.status)
       and not private.billing_payment_checkout_is_processing(v_payment.status)
       and upper(btrim(coalesce(v_payment.status, ''))) not in (
         'CANCELED', 'CANCELLED', 'DELETED'
       )
     )
     or v_intent.status not in ('creating', 'pending', 'cancelled') then
    update private.billing_payment_checkout_cancellations
    set
      finalized_at = v_now,
      final_outcome = 'manual_review',
      manual_review_at = v_now,
      last_error_code = 'cancellation_frozen_snapshot_mismatch',
      updated_at = v_now
    where intent_id = p_intent_id
      and organization_id = p_organization_id
      and payment_id = v_payment.id
      and claim_token = p_claim_token
      and finalized_at is null;

    update public.billing_payment_checkout_capabilities
    set
      revoked_at = coalesce(revoked_at, v_now),
      attempt_lease_id = null,
      attempt_lease_expires_at = null,
      updated_at = v_now
    where payment_id = v_payment.id;

    insert into public.error_events (
      organization_id,
      source,
      severity,
      fingerprint,
      message,
      category,
      error_code,
      component,
      metadata,
      occurred_at
    ) values (
      p_organization_id,
      'backend',
      'critical',
      'billing_payment_cancellation_manual:' || p_intent_id::text,
      'Billing payment cancellation requires assisted review',
      'billing',
      'billing_payment_cancellation_manual_review',
      'billing_payment_cancellation_worker',
      jsonb_build_object(
        'billing_intent_id', p_intent_id,
        'payment_id', v_claim.provider_payment_id,
        'stage', 'delete_marker_frozen_snapshot',
        'error_code', 'cancellation_frozen_snapshot_mismatch'
      ),
      v_now
    )
    on conflict do nothing;

    return jsonb_build_object(
      'outcome', 'manual_review',
      'reason', 'frozen_snapshot_mismatch',
      'last_error_code', 'cancellation_frozen_snapshot_mismatch'
    );
  end if;

  if private.billing_payment_checkout_is_processing(v_payment.status) then
    update private.billing_payment_checkout_cancellations
    set
      lease_expires_at = greatest(
        lease_expires_at,
        v_now + interval '10 minutes'
      ),
      updated_at = v_now
    where intent_id = p_intent_id
      and organization_id = p_organization_id
      and claim_token = p_claim_token
      and finalized_at is null
      and provider_delete_started_at is null;

    return jsonb_build_object(
      'outcome', 'busy',
      'busy_reason', 'payment_processing',
      'retry_after_seconds', 600,
      'payment_status', upper(btrim(v_payment.status))
    );
  end if;

  if upper(btrim(coalesce(v_payment.status, ''))) in (
    'CANCELED', 'CANCELLED', 'DELETED'
  ) then
    update private.billing_checkout_intents
    set
      status = 'cancelled',
      cancelled_at = coalesce(cancelled_at, v_now),
      last_error = 'provider_payment_already_cancelled',
      updated_at = v_now
    where id = p_intent_id
      and organization_id = p_organization_id
      and status <> 'confirmed';

    update private.billing_payment_checkout_cancellations
    set
      provider_deleted_at = v_now,
      provider_delete_result = 'not_found',
      finalized_at = v_now,
      final_outcome = 'cancelled',
      paid_won_at = null,
      manual_review_at = null,
      updated_at = v_now
    where intent_id = p_intent_id
      and organization_id = p_organization_id
      and claim_token = p_claim_token
      and finalized_at is null;

    update public.billing_payment_checkout_capabilities
    set
      revoked_at = coalesce(revoked_at, v_now),
      attempt_lease_id = null,
      attempt_lease_expires_at = null,
      updated_at = v_now
    where payment_id = v_payment.id;

    return jsonb_build_object(
      'outcome', 'already_cancelled',
      'final_outcome', 'cancelled',
      'payment_id', v_provider_payment_id,
      'payment_status', upper(btrim(v_payment.status))
    );
  end if;

  update private.billing_payment_checkout_cancellations as cancellation
  set
    provider_delete_started_at = v_now,
    provider_delete_claim_token = p_claim_token,
    updated_at = v_now
  where cancellation.intent_id = p_intent_id
    and cancellation.organization_id = p_organization_id
    and cancellation.payment_id = v_payment.id
    and cancellation.provider_payment_id = v_provider_payment_id
    and cancellation.claim_token = p_claim_token
    and cancellation.finalized_at is null
    and cancellation.provider_delete_started_at is null
    and cancellation.lease_expires_at > v_now;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  -- The public payment bearer cannot race an in-flight provider DELETE.
  update public.billing_payment_checkout_capabilities
  set
    revoked_at = coalesce(revoked_at, v_now),
    attempt_lease_id = null,
    attempt_lease_expires_at = null,
    updated_at = v_now
  where payment_id = v_payment.id;

  return jsonb_build_object(
    'outcome', 'proceed',
    'payment_id', v_provider_payment_id,
    'provider_delete_started_at', v_now
  );
end
$$;


ALTER FUNCTION public.mark_billing_payment_checkout_cancellation_delete_started(p_organization_id uuid, p_intent_id uuid, p_claim_token uuid, p_provider_payment_id text) OWNER TO postgres;

--
-- Name: mark_billing_subscription_card_update_capture_started(uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_billing_subscription_card_update_capture_started(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_attempt_lease_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_job_hint private.billing_subscription_card_update_jobs%rowtype;
  v_job private.billing_subscription_card_update_jobs%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or p_generation is null
     or p_generation <= 0
     or p_attempt_lease_id is null then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_job_hint
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;
  if v_job_hint.mode <> 'settled_payment'
     or v_job_hint.payment_id is null
     or v_job_hint.provider_payment_id is null then
    return jsonb_build_object('outcome', 'invalid_mode');
  end if;

  perform private.lock_asaas_billing_resources(
    v_job_hint.provider_payment_id,
    v_job_hint.provider_subscription_id
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = v_job_hint.payment_id
    and payment.organization_id = p_organization_id
    and payment.asaas_payment_id = v_job_hint.provider_payment_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select capability.*
  into v_capability
  from public.billing_payment_checkout_capabilities as capability
  where capability.payment_id = v_payment.id
    and capability.organization_id = v_payment.organization_id
    and capability.asaas_payment_id = v_payment.asaas_payment_id
    and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  select subscription.*
  into v_subscription
  from public.subscriptions as subscription
  where subscription.id = v_job_hint.subscription_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  if not v_org.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  if v_job.status in ('succeeded', 'cancelled', 'dead') then
    return jsonb_build_object(
      'outcome', case
        when v_job.status = 'dead' then 'manual_review'
        else 'payment_not_actionable'
      end,
      'status', v_job.status,
      'last_error_code', v_job.last_error_code
    );
  end if;
  if private.billing_payment_checkout_is_paid(v_payment.status)
     or not private.billing_payment_checkout_is_actionable(v_payment.status) then
    return jsonb_build_object(
      'outcome', 'payment_not_actionable',
      'payment_status', upper(btrim(coalesce(v_payment.status, '')))
    );
  end if;

  if v_job.capture_request_started_at is not null then
    return jsonb_build_object(
      'outcome', case
        when v_job.capture_attempt_lease_id = p_attempt_lease_id
          then 'already_started'
        else 'recover_only'
      end,
      'job_id', v_job.id,
      'capture_request_started_at', v_job.capture_request_started_at
    );
  end if;

  if v_capability.payment_id is null
     or v_capability.revoked_at is not null
     or v_capability.expires_at <= v_now
     or v_capability.attempt_lease_id is distinct from p_attempt_lease_id
     or v_capability.attempt_lease_expires_at <= v_now then
    return jsonb_build_object('outcome', 'attempt_lease_not_found');
  end if;
  if v_job.status <> 'awaiting_payment'
     or v_job.provider_card_credential is null
     or v_job.credential_attempt_lease_id
       is distinct from p_attempt_lease_id then
    return jsonb_build_object('outcome', 'credential_not_stored');
  end if;
  if v_org.asaas_subscription_id
       is distinct from v_job.provider_subscription_id
     or v_org.asaas_customer_id is distinct from v_job.provider_customer_id
     or not v_org.is_active
     or lower(btrim(coalesce(v_org.subscription_status, ''))) <> 'active'
     or v_subscription.organization_id is distinct from p_organization_id
     or v_subscription.provider_subscription_id
       is distinct from v_job.provider_subscription_id
     or v_subscription.provider_customer_id
       is distinct from v_job.provider_customer_id
     or lower(v_subscription.status) <> 'active'
     or exists (
       select 1
       from private.billing_plan_changes as plan_change
       where plan_change.organization_id = p_organization_id
         and plan_change.provider_subscription_id
           = v_job.provider_subscription_id
         and plan_change.status in ('provider_updating', 'applying')
     )
     or exists (
       select 1
       from private.billing_payment_checkout_cancellations as cancellation
       where cancellation.payment_id = v_payment.id
         and cancellation.finalized_at is null
     )
     or exists (
       select 1
       from private.billing_subscription_checkout_cancellations as cancellation
       where cancellation.organization_id = p_organization_id
         and cancellation.provider_subscription_id
           = v_job.provider_subscription_id
         and cancellation.finalized_at is null
     )
     or private.billing_card_recurrence_cancel_state(
       p_organization_id,
       v_job.provider_subscription_id
     ) is not null
     or private.billing_organization_cleanup_is_active(
       p_organization_id,
       v_job.provider_subscription_id
     ) then
    update private.billing_subscription_card_update_jobs
    set
      status = 'cancelled',
      provider_card_credential = null,
      card_last4 = null,
      credential_attempt_lease_id = null,
      last_error_code = 'capture_target_mismatch',
      cancelled_at = v_now,
      updated_at = v_now
    where id = v_job.id
      and status = 'awaiting_payment';
    return jsonb_build_object(
      'outcome', 'cancelled',
      'last_error_code', 'capture_target_mismatch'
    );
  end if;

  update private.billing_subscription_card_update_jobs as job
  set
    capture_request_started_at = v_now,
    capture_attempt_lease_id = p_attempt_lease_id,
    updated_at = v_now
  where job.id = v_job.id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
    and job.status = 'awaiting_payment'
    and job.capture_request_started_at is null
    and job.provider_card_credential is not null
    and job.credential_attempt_lease_id = p_attempt_lease_id;
  if not found then
    return jsonb_build_object('outcome', 'state_changed');
  end if;

  return jsonb_build_object(
    'outcome', 'proceed',
    'job_id', v_job.id,
    'payment_id', v_payment.id,
    'provider_payment_id', v_payment.asaas_payment_id,
    'capture_request_started_at', v_now
  );
end
$$;


ALTER FUNCTION public.mark_billing_subscription_card_update_capture_started(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_attempt_lease_id uuid) OWNER TO postgres;

--
-- Name: mark_billing_subscription_card_update_provider_request_started(uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_billing_subscription_card_update_provider_request_started(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_job_lease_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_hint private.billing_subscription_card_update_jobs%rowtype;
  v_job private.billing_subscription_card_update_jobs%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_now timestamptz := clock_timestamp();
  v_conflict boolean := false;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or p_generation is null
     or p_generation <= 0
     or p_job_lease_id is null then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_hint
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_hint.provider_payment_id,
    v_hint.provider_subscription_id
  );

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
  for update;
  if not found then
    v_conflict := true;
  end if;
  if found and not v_org.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  select subscription.*
  into v_subscription
  from public.subscriptions as subscription
  where subscription.id = v_hint.subscription_id
  for update;
  if not found then
    v_conflict := true;
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  if v_job.status in ('succeeded', 'cancelled', 'dead') then
    return jsonb_build_object(
      'outcome', case
        when v_job.status = 'succeeded' then 'already_succeeded'
        when v_job.manual_review_at is not null then 'manual_review'
        else 'already_finalized'
      end,
      'status', v_job.status,
      'last_error_code', v_job.last_error_code
    );
  end if;
  if v_job.expires_at <= v_now then
    update private.billing_subscription_card_update_jobs
    set
      status = case
        when provider_outcome_ambiguous_at is null then 'cancelled'
        else 'dead'
      end,
      provider_card_credential = null,
      credential_attempt_lease_id = null,
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      last_error_code = 'credential_expired',
      cancelled_at = case
        when provider_outcome_ambiguous_at is null then v_now else null
      end,
      manual_review_at = case
        when provider_outcome_ambiguous_at is null then null else v_now
      end,
      dead_lettered_at = case
        when provider_outcome_ambiguous_at is null then null else v_now
      end,
      updated_at = v_now
    where id = v_job.id
      and status = 'processing'
      and lease_id = p_job_lease_id;
    return jsonb_build_object(
      'outcome', case
        when v_job.provider_outcome_ambiguous_at is null then 'cancelled'
        else 'manual_review'
      end,
      'last_error_code', 'credential_expired'
    );
  end if;
  if v_job.status <> 'processing'
     or v_job.lease_id is distinct from p_job_lease_id
     or v_job.lease_expires_at <= v_now
     or v_job.provider_card_credential is null then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;
  if v_job.provider_request_lease_id = p_job_lease_id then
    return jsonb_build_object(
      'outcome', 'already_started',
      'provider_request_started_at', v_job.provider_request_started_at,
      'provider_request_attempts', v_job.provider_request_attempts
    );
  end if;

  v_conflict := v_conflict
    or not coalesce(v_org.is_active, false)
    or lower(btrim(coalesce(v_org.subscription_status, ''))) <> 'active'
    or v_org.asaas_subscription_id
      is distinct from v_job.provider_subscription_id
    or v_org.asaas_customer_id is distinct from v_job.provider_customer_id
    or v_subscription.organization_id is distinct from p_organization_id
    or v_subscription.provider_subscription_id
      is distinct from v_job.provider_subscription_id
    or v_subscription.provider_customer_id
      is distinct from v_job.provider_customer_id
    or lower(coalesce(v_subscription.status, '')) <> 'active'
    or exists (
      select 1
      from private.billing_subscription_checkout_cancellations as cancellation
      where cancellation.organization_id = p_organization_id
        and cancellation.provider_subscription_id
          = v_job.provider_subscription_id
        and (
          cancellation.finalized_at is null
          or cancellation.final_outcome = 'manual_review'
        )
    )
    or private.billing_card_recurrence_cancel_state(
      p_organization_id,
      v_job.provider_subscription_id
    ) is not null
    or private.billing_organization_cleanup_is_active(
      p_organization_id,
      v_job.provider_subscription_id
    )
    or exists (
      select 1
      from private.billing_plan_changes as plan_change
      where plan_change.organization_id = p_organization_id
        and plan_change.provider_subscription_id
          = v_job.provider_subscription_id
        and plan_change.status in ('provider_updating', 'applying')
    );

  if v_conflict then
    update private.billing_subscription_card_update_jobs
    set
      status = case
        when provider_outcome_ambiguous_at is null then 'cancelled'
        else 'dead'
      end,
      provider_card_credential = null,
      credential_attempt_lease_id = null,
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      last_error_code = 'provider_update_target_changed',
      cancelled_at = case
        when provider_outcome_ambiguous_at is null then v_now else null
      end,
      manual_review_at = case
        when provider_outcome_ambiguous_at is null then null else v_now
      end,
      dead_lettered_at = case
        when provider_outcome_ambiguous_at is null then null else v_now
      end,
      updated_at = v_now
    where id = v_job.id
      and status = 'processing'
      and lease_id = p_job_lease_id;

    return jsonb_build_object(
      'outcome', case
        when v_job.provider_outcome_ambiguous_at is null then 'cancelled'
        else 'manual_review'
      end,
      'last_error_code', 'provider_update_target_changed'
    );
  end if;

  update private.billing_subscription_card_update_jobs
  set
    provider_request_started_at = coalesce(provider_request_started_at, v_now),
    provider_request_last_started_at = v_now,
    provider_request_lease_id = p_job_lease_id,
    provider_request_attempts = provider_request_attempts + 1,
    updated_at = v_now
  where id = v_job.id
    and status = 'processing'
    and lease_id = p_job_lease_id
    and lease_expires_at > v_now
    and provider_request_lease_id is distinct from p_job_lease_id;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  return jsonb_build_object(
    'outcome', 'proceed',
    'job_id', v_job.id,
    'generation', v_job.generation,
    'subscription_id', v_job.provider_subscription_id,
    'provider_request_started_at', coalesce(
      v_job.provider_request_started_at,
      v_now
    ),
    'provider_request_attempts', v_job.provider_request_attempts + 1
  );
end
$$;


ALTER FUNCTION public.mark_billing_subscription_card_update_provider_request_started(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_job_lease_id uuid) OWNER TO postgres;

--
-- Name: mark_lead_owner_activity_for_redistribution(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_lead_owner_activity_for_redistribution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_id uuid;
  v_owner_touched boolean;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF OLD.assigned_user_id IS DISTINCT FROM NEW.assigned_user_id THEN
    NEW.owner_last_activity_at := NULL;
    NEW.owner_last_activity_user_id := NULL;
    NEW.redistribution_warning_sent_at := NULL;
  END IF;

  v_actor_id := auth.uid();

  v_owner_touched :=
    v_actor_id IS NOT NULL
    AND OLD.assigned_user_id IS NOT NULL
    AND v_actor_id = OLD.assigned_user_id
    AND NEW.assigned_user_id IS NOT DISTINCT FROM OLD.assigned_user_id
    AND (
      OLD.stage_id IS DISTINCT FROM NEW.stage_id
      OR OLD.stage_entered_at IS DISTINCT FROM NEW.stage_entered_at
      OR OLD.deal_status IS DISTINCT FROM NEW.deal_status
      OR OLD.name IS DISTINCT FROM NEW.name
      OR OLD.phone IS DISTINCT FROM NEW.phone
      OR OLD.email IS DISTINCT FROM NEW.email
      OR OLD.message IS DISTINCT FROM NEW.message
      OR OLD.feedback IS DISTINCT FROM NEW.feedback
      OR OLD.property_id IS DISTINCT FROM NEW.property_id
      OR OLD.property_code IS DISTINCT FROM NEW.property_code
    );

  IF v_owner_touched THEN
    NEW.owner_last_activity_at := now();
    NEW.owner_last_activity_user_id := v_actor_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.mark_lead_owner_activity_for_redistribution() OWNER TO postgres;

--
-- Name: mark_overdue_financial_entries(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_overdue_financial_entries() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.financial_entries
     SET status = 'overdue',
         updated_at = now()
   WHERE status = 'pending'
     AND due_date IS NOT NULL
     AND due_date < CURRENT_DATE;
END;
$$;


ALTER FUNCTION public.mark_overdue_financial_entries() OWNER TO postgres;

