    stage_id uuid,
    assigned_user_id uuid,
    property_id uuid,
    name text NOT NULL,
    email text,
    phone text,
    message text,
    property_code text,
    stage_entered_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source text DEFAULT 'manual'::text,
    deal_status text DEFAULT 'open'::text,
    valor_interesse numeric DEFAULT 0,
    won_at timestamp with time zone,
    lost_at timestamp with time zone,
    lost_reason text,
    assigned_at timestamp with time zone,
    first_touch_at timestamp with time zone,
    redistribution_count integer DEFAULT 0,
    interest_property_id uuid,
    interest_plan_id uuid,
    source_webhook_id uuid,
    source_session_id uuid,
    commission_percentage numeric,
    first_response_at timestamp with time zone,
    first_response_seconds integer,
    first_response_channel text,
    first_response_actor_user_id uuid,
    first_response_is_automation boolean DEFAULT false,
    first_touch_seconds integer,
    first_touch_channel text,
    first_touch_actor_user_id uuid,
    meta_lead_id text,
    meta_form_id text,
    cargo text,
    empresa text,
    endereco text,
    numero text,
    complemento text,
    bairro text,
    cidade text,
    uf text,
    cep text,
    renda_familiar text,
    trabalha boolean DEFAULT false,
    profissao text,
    faixa_valor_imovel text,
    finalidade_compra text,
    procura_financiamento boolean DEFAULT false,
    visitor_session_id text,
    last_entry_at timestamp with time zone,
    reentry_count integer DEFAULT 0 NOT NULL,
    feedback text,
    is_own_resource boolean DEFAULT false,
    meta_campaign_id text,
    meta_adset_id text,
    meta_ad_id text,
    meta_click_id text,
    utm_source text,
    utm_medium text,
    utm_campaign text,
    utm_content text,
    utm_term text,
    initial_message text,
    whatsapp_avatar_url text,
    whatsapp_avatar_synced_at timestamp with time zone,
    whatsapp_verified boolean DEFAULT false,
    owner_last_activity_at timestamp with time zone,
    owner_last_activity_user_id uuid,
    redistribution_warning_sent_at timestamp with time zone,
    last_redistributed_at timestamp with time zone,
    sla_status text,
    sla_seconds_elapsed integer,
    sla_last_checked_at timestamp with time zone,
    sla_notified_warning_at timestamp with time zone,
    sla_notified_overdue_at timestamp with time zone,
    status text DEFAULT 'new'::text,
    priority text DEFAULT 'normal'::text,
    last_contact_at timestamp with time zone,
    next_follow_up_at timestamp with time zone,
    created_by uuid,
    source_detail text,
    metadata jsonb DEFAULT '{}'::jsonb,
    board_order_at timestamp with time zone,
    attention_eligible boolean DEFAULT false NOT NULL,
    attention_enrolled_at timestamp with time zone,
    team_id uuid,
    intake_scope_key text DEFAULT 'unscoped'::text NOT NULL,
    origin_round_robin_id uuid,
    whatsapp_avatar_storage_path text,
    external_source text,
    external_source_id text,
    operational_effects_suppressed boolean DEFAULT false NOT NULL,
    historical_imported_at timestamp with time zone,
    CONSTRAINT leads_deal_status_check CHECK ((deal_status = ANY (ARRAY['open'::text, 'won'::text, 'lost'::text]))),
    CONSTRAINT leads_external_identity_shape_check_v2 CHECK ((((external_source IS NULL) AND (external_source_id IS NULL)) OR ((external_source IS NOT NULL) AND (external_source_id IS NOT NULL) AND (external_source = lower(btrim(external_source))) AND (external_source ~ '^[a-z0-9][a-z0-9._-]{0,63}$'::text) AND ((length(external_source_id) >= 1) AND (length(external_source_id) <= 256)) AND (external_source_id = btrim(external_source_id)) AND (external_source_id !~ '[[:cntrl:]]'::text) AND (origin_round_robin_id IS NULL)))),
    CONSTRAINT leads_historical_effect_suppression_shape_check CHECK ((((operational_effects_suppressed = false) AND (historical_imported_at IS NULL)) OR ((operational_effects_suppressed = true) AND (historical_imported_at IS NOT NULL) AND (external_source IS NOT NULL) AND (external_source_id IS NOT NULL)))),
    CONSTRAINT leads_intake_scope_key_check CHECK (((intake_scope_key = 'unscoped'::text) OR (intake_scope_key ~ '^queue:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) OR (((length(intake_scope_key) >= 12) AND (length(intake_scope_key) <= 400)) AND (intake_scope_key ~ '^external:[a-z0-9][a-z0-9._-]{0,63}:.+$'::text) AND (intake_scope_key !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT leads_whatsapp_avatar_storage_path_scope_check CHECK (((whatsapp_avatar_storage_path IS NULL) OR (whatsapp_avatar_storage_path ~ (((('^orgs/'::text || (organization_id)::text) || '/profile-pictures/'::text) || (id)::text) || '/[0-9a-f]{64}[.](jpg|png|webp)$'::text))))
);


