--
-- Name: move_lead_stage(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.move_lead_stage(p_lead_id uuid, p_stage_id uuid, p_is_own_resource boolean DEFAULT NULL::boolean) RETURNS public.leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_org_id uuid;
  v_lead public.leads%rowtype;
  v_target_stage record;
  v_updated_lead public.leads%rowtype;
  v_is_privileged boolean := false;
  v_is_leader_allowed boolean := false;
  v_has_pipeline_lock boolean := false;
begin
  if v_actor_id is null then
    raise exception 'Usuario nao autenticado';
  end if;

  select organization_id into v_actor_org_id
  from public.users
  where id = v_actor_id;

  if v_actor_org_id is null then
    raise exception 'Organizacao do usuario nao encontrada';
  end if;

  select * into v_lead
  from public.leads
  where id = p_lead_id;

  if not found then
    raise exception 'Lead nao encontrado';
  end if;

  if v_lead.organization_id <> v_actor_org_id and not public.is_super_admin() then
    raise exception 'Lead pertence a outra organizacao';
  end if;

  select s.id, s.pipeline_id, p.organization_id, s.name
    into v_target_stage
  from public.stages s
  join public.pipelines p on p.id = s.pipeline_id
  where s.id = p_stage_id;

  if not found then
    raise exception 'Etapa nao encontrada';
  end if;

  if v_target_stage.organization_id <> v_lead.organization_id then
    raise exception 'Etapa pertence a outra organizacao';
  end if;

  v_is_privileged :=
    public.is_super_admin()
    or public.is_admin()
    or public.user_has_permission('lead_edit_all', v_actor_id)
    or public.user_has_permission('settings_pipelines', v_actor_id);

  if public.is_team_leader(v_actor_id) then
    v_is_leader_allowed :=
      coalesce(v_lead.pipeline_id = any(array(select public.get_user_led_pipeline_ids())), false)
      or coalesce(v_target_stage.pipeline_id = any(array(select public.get_user_led_pipeline_ids())), false)
      or coalesce(v_lead.assigned_user_id in (
        select tm.user_id
        from public.team_members tm
        where tm.team_id in (select public.get_user_led_team_ids())
      ), false);
  end if;

  v_has_pipeline_lock := public.user_has_permission('pipeline_lock', v_actor_id);

  if v_has_pipeline_lock and not v_is_privileged then
    raise exception 'Usuario sem permissao para mover leads no pipeline';
  end if;

  if not (
    v_is_privileged
    or v_is_leader_allowed
    or v_lead.assigned_user_id = v_actor_id
  ) then
    raise exception 'Sem permissao para mover este lead';
  end if;

  update public.leads
     set stage_id = p_stage_id,
         pipeline_id = v_target_stage.pipeline_id,
         stage_entered_at = case
           when stage_id is distinct from p_stage_id then now()
           else stage_entered_at
         end,
         is_own_resource = coalesce(p_is_own_resource, is_own_resource),
         updated_at = now()
   where id = p_lead_id
   returning * into v_updated_lead;

  return v_updated_lead;
end;
$$;


ALTER FUNCTION public.move_lead_stage(p_lead_id uuid, p_stage_id uuid, p_is_own_resource boolean) OWNER TO postgres;

--
-- Name: move_lead_stage(uuid, uuid, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.move_lead_stage(p_lead_id uuid, p_stage_id uuid, p_is_own_resource boolean DEFAULT NULL::boolean, p_stage_entered_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_org_id uuid;
  v_is_admin boolean := false;
  v_has_privileged_permission boolean := false;
  v_is_team_leader boolean := false;
  v_has_pipeline_lock boolean := false;
  v_lead public.leads;
  v_stage record;
  v_result public.leads;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT organization_id, role IN ('admin', 'super_admin')
  INTO v_user_org_id, v_is_admin
  FROM public.users
  WHERE id = v_user_id;

  IF v_user_org_id IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  SELECT *
  INTO v_lead
  FROM public.leads
  WHERE id = p_lead_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead not found';
  END IF;

  IF v_lead.organization_id IS DISTINCT FROM v_user_org_id AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Lead is outside the user organization';
  END IF;

  SELECT s.id, s.pipeline_id, p.organization_id
  INTO v_stage
  FROM public.stages s
  JOIN public.pipelines p ON p.id = s.pipeline_id
  WHERE s.id = p_stage_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Target stage not found';
  END IF;

  IF v_stage.organization_id IS DISTINCT FROM v_lead.organization_id THEN
    RAISE EXCEPTION 'Target stage belongs to another organization';
  END IF;

  v_has_privileged_permission :=
    public.user_has_permission('lead_edit_all', v_user_id)
    OR public.user_has_permission('settings_pipelines', v_user_id);

  v_has_pipeline_lock := public.user_has_permission('pipeline_lock', v_user_id);

  SELECT public.is_team_leader(v_user_id) AND (
    COALESCE(v_lead.pipeline_id = ANY(ARRAY(SELECT public.get_user_led_pipeline_ids())), false)
    OR COALESCE(v_stage.pipeline_id = ANY(ARRAY(SELECT public.get_user_led_pipeline_ids())), false)
    OR EXISTS (
      SELECT 1
      FROM public.team_members tm
      WHERE tm.user_id = v_lead.assigned_user_id
        AND tm.team_id IN (SELECT public.get_user_led_team_ids())
    )
  )
  INTO v_is_team_leader;

  IF NOT (
    v_is_admin
    OR v_has_privileged_permission
    OR v_is_team_leader
    OR v_lead.assigned_user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'User cannot move this lead';
  END IF;

  IF v_has_pipeline_lock AND NOT (v_is_admin OR v_has_privileged_permission OR v_is_team_leader) THEN
    RAISE EXCEPTION 'User is locked from moving pipeline cards';
  END IF;

  UPDATE public.leads
  SET
    stage_id = p_stage_id,
    pipeline_id = v_stage.pipeline_id,
    stage_entered_at = COALESCE(
      p_stage_entered_at,
      CASE
        WHEN stage_id IS DISTINCT FROM p_stage_id THEN now()
        ELSE stage_entered_at
      END
    ),
    is_own_resource = COALESCE(p_is_own_resource, is_own_resource),
    updated_at = now()
  WHERE id = p_lead_id
  RETURNING *
  INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.move_lead_stage(p_lead_id uuid, p_stage_id uuid, p_is_own_resource boolean, p_stage_entered_at timestamp with time zone) OWNER TO postgres;

--
-- Name: normalize_phone(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalize_phone(phone_input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  raw_input text;
  cleaned text;
begin
  raw_input := btrim(phone_input);
  if phone_input is null or raw_input = '' then
    return null;
  end if;

  cleaned := regexp_replace(raw_input, '[^0-9]', '', 'g');
  if cleaned = '' then
    return null;
  end if;

  -- E.164 entered with "+" must not be reinterpreted as a Brazilian local
  -- number merely because its total length happens to be 10 or 11 digits.
  if raw_input ~ '^\+' then
    return cleaned;
  end if;

  -- Accept the standard international dial-out prefix as an alias for "+".
  if raw_input ~ '^00' then
    cleaned := substring(cleaned from 3);
    return nullif(cleaned, '');
  end if;

  -- Keep the historical Brazilian storage formats compatible.
  if length(cleaned) > 11 and substring(cleaned, 1, 2) = '55' then
    return cleaned;
  end if;

  if length(cleaned) between 10 and 11 then
    return '55' || cleaned;
  end if;

  return cleaned;
end;
$$;


ALTER FUNCTION public.normalize_phone(phone_input text) OWNER TO postgres;

--
-- Name: FUNCTION normalize_phone(phone_input text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.normalize_phone(phone_input text) IS 'Normalizes lead/contact phones for matching: explicit +/00 is international; unprefixed 10/11 digit values default to Brazil.';


--
-- Name: notify_commission_pending(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_commission_pending() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'pending') OR (TG_OP = 'INSERT' AND NEW.status = 'pending') THEN INSERT INTO public.notifications (organization_id, user_id, type, title, content) SELECT NEW.organization_id, u.id, 'financial', 'Comissão Liberada', 'Uma nova comissão está aguardando sua aprovação para pagamento.' FROM public.users u JOIN public.user_roles ur ON ur.user_id = u.id WHERE u.organization_id = NEW.organization_id AND ur.role IN ('admin','super_admin'); END IF; RETURN NEW; END; $$;


ALTER FUNCTION public.notify_commission_pending() OWNER TO postgres;

--
-- Name: notify_feature_request_response(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_feature_request_response() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status_label TEXT;
BEGIN
  -- Only notify when status changes and admin_response is added
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.user_id IS NOT NULL THEN
    v_status_label := CASE NEW.status
      WHEN 'approved' THEN 'aprovada'
      WHEN 'rejected' THEN 'não aprovada'
      WHEN 'analyzing' THEN 'em análise'
      ELSE NEW.status
    END;

    PERFORM public.create_notification(
      NEW.user_id,
      NEW.organization_id,
      '💡 Resposta à sua sugestão',
      'Sua sugestão "' || NEW.title || '" foi marcada como ' || v_status_label || '.' ||
      CASE WHEN NEW.admin_response IS NOT NULL THEN ' Verifique a resposta na Central de Ajuda.' ELSE '' END,
      'info',
      NULL
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_feature_request_response() OWNER TO postgres;

--
-- Name: notify_financial_entries(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_financial_entries() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_entry RECORD;
  v_admin RECORD;
  v_today DATE := CURRENT_DATE;
  v_type_label TEXT;
  v_formatted_amount TEXT;
BEGIN
  -- A) Contas que vencem HOJE
  FOR v_entry IN
    SELECT fe.id, fe.organization_id, fe.type, fe.description, fe.amount, fe.due_date
    FROM public.financial_entries fe
    WHERE fe.due_date = v_today
    AND fe.status = 'pending'
  LOOP
    v_type_label := CASE v_entry.type WHEN 'payable' THEN 'A Pagar' ELSE 'A Receber' END;
    v_formatted_amount := 'R$ ' || TRIM(to_char(v_entry.amount, '999G999G990D00'));

    -- Notify all admins of the organization
    FOR v_admin IN
      SELECT id FROM public.users WHERE organization_id = v_entry.organization_id AND role = 'admin'
    LOOP
      -- Check if already notified today
      IF NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.user_id = v_admin.id
        AND n.title LIKE '%vence hoje%'
        AND n.content LIKE '%' || v_entry.description || '%'
        AND n.created_at::date = v_today
      ) THEN
        PERFORM public.create_notification(
          v_admin.id,
          v_entry.organization_id,
          '⚠️ Conta vence hoje!',
          v_type_label || ': ' || v_entry.description || ' - ' || v_formatted_amount,
          'commission',
          NULL::uuid
        );
      END IF;
    END LOOP;
  END LOOP;

  -- B) Contas VENCIDAS (atrasadas)
  FOR v_entry IN
    SELECT fe.id, fe.organization_id, fe.type, fe.description, fe.amount, fe.due_date
    FROM public.financial_entries fe
    WHERE fe.due_date < v_today
    AND fe.status = 'pending'
  LOOP
    v_type_label := CASE v_entry.type WHEN 'payable' THEN 'A Pagar' ELSE 'A Receber' END;
    v_formatted_amount := 'R$ ' || TRIM(to_char(v_entry.amount, '999G999G990D00'));

    FOR v_admin IN
      SELECT id FROM public.users WHERE organization_id = v_entry.organization_id AND role = 'admin'
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.user_id = v_admin.id
        AND n.title LIKE '%atrasad%'
        AND n.content LIKE '%' || v_entry.description || '%'
        AND n.created_at::date = v_today
      ) THEN
        PERFORM public.create_notification(
          v_admin.id,
          v_entry.organization_id,
          '🚨 Conta em atraso!',
          v_type_label || ': ' || v_entry.description || ' - ' || v_formatted_amount || ' (vencida em ' || to_char(v_entry.due_date, 'DD/MM') || ')',
          'commission',
          NULL::uuid
        );
      END IF;
    END LOOP;
  END LOOP;

  -- C) Contas que vencem em 3 dias
  FOR v_entry IN
    SELECT fe.id, fe.organization_id, fe.type, fe.description, fe.amount, fe.due_date
    FROM public.financial_entries fe
    WHERE fe.due_date = v_today + INTERVAL '3 days'
    AND fe.status = 'pending'
  LOOP
    v_type_label := CASE v_entry.type WHEN 'payable' THEN 'A Pagar' ELSE 'A Receber' END;
    v_formatted_amount := 'R$ ' || TRIM(to_char(v_entry.amount, '999G999G990D00'));

    FOR v_admin IN
      SELECT id FROM public.users WHERE organization_id = v_entry.organization_id AND role = 'admin'
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.user_id = v_admin.id
        AND n.title LIKE '%vence em 3 dias%'
        AND n.content LIKE '%' || v_entry.description || '%'
        AND n.created_at::date = v_today
      ) THEN
        PERFORM public.create_notification(
          v_admin.id,
          v_entry.organization_id,
          '📅 Conta vence em 3 dias',
          v_type_label || ': ' || v_entry.description || ' - ' || v_formatted_amount,
          'commission',
          NULL::uuid
        );
      END IF;
    END LOOP;
  END LOOP;
END;
$_$;


ALTER FUNCTION public.notify_financial_entries() OWNER TO postgres;

