--
-- Name: prepare_billing_card_recurrence(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_payment public.asaas_payments%rowtype;
  v_intent private.billing_checkout_intents%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_has_provision boolean := false;
  v_external_reference text;
  v_next_due_date date;
begin
  if p_payment_id is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255 then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  -- Every recurrence RPC takes locks in this order: payment, an existing
  -- provision when present, immutable intent, organization, public
  -- subscription. A first prepare simply has no provision row to lock yet.
  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  if not (
    private.billing_payment_checkout_is_actionable(v_payment.status)
    or private.billing_payment_checkout_is_paid(v_payment.status)
  ) then
    return jsonb_build_object(
      'outcome', 'payment_not_eligible',
      'payment_status', upper(btrim(coalesce(v_payment.status, '')))
    );
  end if;

  if v_payment.asaas_subscription_id is not null then
    return jsonb_build_object('outcome', 'payment_already_recurring');
  end if;

  if v_payment.billing_intent_id is null
     or nullif(btrim(coalesce(v_payment.asaas_customer_id, '')), '') is null then
    return jsonb_build_object('outcome', 'immutable_tuple_unavailable');
  end if;

  -- Preserve the global recurrence lock order even on an idempotent prepare:
  -- payment, existing provision (when present), then immutable intent.
  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
  for update;

  v_has_provision := found;
  if v_has_provision and (
    v_provision.provider_payment_id is distinct from v_payment.asaas_payment_id
    or v_provision.organization_id is distinct from v_payment.organization_id
    or v_provision.billing_intent_id is distinct from v_payment.billing_intent_id
  ) then
    return jsonb_build_object('outcome', 'immutable_tuple_mismatch');
  end if;

  select intent.*
  into v_intent
  from private.billing_checkout_intents as intent
  where intent.id = v_payment.billing_intent_id
    and intent.organization_id = v_payment.organization_id
  for update;

  if not found
     or v_intent.provider_payment_id is distinct from v_payment.asaas_payment_id
     or v_intent.provider_customer_id is distinct from v_payment.asaas_customer_id
     or v_intent.pending_plan_id is null
     or v_intent.billing_period_months not in (1, 6, 12)
     or v_intent.amount is null
     or v_intent.amount <= 0
     or v_payment.value is null
     or abs(v_intent.amount - v_payment.value) > 0.01 then
    return jsonb_build_object('outcome', 'immutable_tuple_mismatch');
  end if;

  v_external_reference :=
    private.billing_card_recurrence_external_reference(v_payment.id);
  v_next_due_date := (
    greatest(
      current_date,
      coalesce(v_payment.due_date, current_date)
    ) + make_interval(months => v_intent.billing_period_months)
  )::date;

  if not v_has_provision then
    insert into private.billing_card_recurrence_provisions (
      payment_id,
      provider_payment_id,
      organization_id,
      billing_intent_id,
      plan_id,
      billing_period_months,
      amount,
      provider_customer_id,
      next_due_date,
      external_reference
    )
    values (
      v_payment.id,
      v_payment.asaas_payment_id,
      v_payment.organization_id,
      v_payment.billing_intent_id,
      v_intent.pending_plan_id,
      v_intent.billing_period_months,
      v_intent.amount,
      v_payment.asaas_customer_id,
      v_next_due_date,
      v_external_reference
    )
    on conflict (payment_id) do nothing;

    select provision.*
    into v_provision
    from private.billing_card_recurrence_provisions as provision
    where provision.payment_id = v_payment.id
    for update;
  end if;

  if not found
     or v_provision.provider_payment_id is distinct from v_payment.asaas_payment_id
     or v_provision.organization_id is distinct from v_payment.organization_id
     or v_provision.billing_intent_id is distinct from v_payment.billing_intent_id
     or v_provision.plan_id is distinct from v_intent.pending_plan_id
     or v_provision.billing_period_months is distinct from v_intent.billing_period_months
     or abs(v_provision.amount - v_intent.amount) > 0.01
     or v_provision.provider_customer_id is distinct from v_payment.asaas_customer_id
     or v_provision.external_reference is distinct from v_external_reference then
    return jsonb_build_object('outcome', 'immutable_tuple_mismatch');
  end if;

  return jsonb_build_object(
    'outcome', case
      when v_provision.status = 'completed' then 'already_completed'
      else 'prepared'
    end,
    'payment_id', v_provision.payment_id,
    'status', v_provision.status,
    'credential_stored', v_provision.provider_card_credential is not null,
    'capture_request_started', v_provision.capture_request_started_at is not null,
    'capture_request_started_at', v_provision.capture_request_started_at,
    'external_reference', v_provision.external_reference,
    'provider_subscription_id', v_provision.provider_subscription_id
  );
end
$$;


ALTER FUNCTION public.prepare_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text) OWNER TO postgres;

--
-- Name: FUNCTION prepare_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.prepare_billing_card_recurrence(p_payment_id uuid, p_provider_payment_id text) IS 'Freezes the exact intent tuple before recurrence creation; idempotent for the same one-off payment and reports whether a sealed credential already exists.';


--
-- Name: prepare_billing_subscription_card_update(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_billing_subscription_card_update(p_job_id uuid, p_organization_id uuid, p_mode text, p_payment_id uuid, p_provider_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_mode text := lower(nullif(btrim(coalesce(p_mode, '')), ''));
  v_provider_payment_id text := nullif(
    btrim(coalesce(p_provider_payment_id, '')),
    ''
  );
  v_org_hint public.organizations%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_existing private.billing_subscription_card_update_jobs%rowtype;
  v_generation bigint;
  v_provider_subscription_id text;
  v_provider_customer_id text;
  v_existing_payment_status text;
  v_recurrence_cancel_state text;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or v_mode not in ('settled_payment', 'saved_only')
     or (
       v_mode = 'saved_only'
       and (p_payment_id is not null or v_provider_payment_id is not null)
     )
     or (
       v_mode = 'settled_payment'
       and (p_payment_id is null or v_provider_payment_id is null)
     )
     or char_length(coalesce(v_provider_payment_id, '')) > 255 then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select organization.*
  into v_org_hint
  from public.organizations as organization
  where organization.id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;
  if not v_org_hint.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  v_provider_subscription_id := nullif(
    btrim(coalesce(v_org_hint.asaas_subscription_id, '')),
    ''
  );
  v_provider_customer_id := nullif(
    btrim(coalesce(v_org_hint.asaas_customer_id, '')),
    ''
  );
  if v_provider_subscription_id is null or v_provider_customer_id is null then
    return jsonb_build_object('outcome', 'subscription_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_provider_payment_id,
    v_provider_subscription_id
  );

  if v_mode = 'settled_payment' then
    select payment.*
    into v_payment
    from public.asaas_payments as payment
    where payment.id = p_payment_id
      and payment.organization_id = p_organization_id
      and payment.asaas_payment_id = v_provider_payment_id
    for update;
    if not found then
      return jsonb_build_object('outcome', 'payment_not_found');
    end if;
  end if;

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
    and organization.is_active
    and lower(btrim(coalesce(organization.subscription_status, '')))
      = 'active'
    and nullif(btrim(coalesce(organization.asaas_subscription_id, '')), '')
      = v_provider_subscription_id
    and nullif(btrim(coalesce(organization.asaas_customer_id, '')), '')
      = v_provider_customer_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;
  if not v_org.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  select subscription.*
  into v_subscription
  from public.subscriptions as subscription
  where subscription.organization_id = p_organization_id
    and subscription.provider_subscription_id = v_provider_subscription_id
    and subscription.provider_customer_id = v_provider_customer_id
    and lower(subscription.status) = 'active'
    and lower(coalesce(subscription.provider, 'asaas')) = 'asaas'
  order by subscription.updated_at desc, subscription.id desc
  limit 1
  for update;
  if not found then
    return jsonb_build_object('outcome', 'subscription_not_found');
  end if;

  if exists (
    select 1
    from private.billing_subscription_checkout_cancellations as cancellation
    where cancellation.organization_id = p_organization_id
      and cancellation.provider_subscription_id = v_provider_subscription_id
      and cancellation.finalized_at is null
  ) then
    return jsonb_build_object(
      'outcome', 'busy',
      'busy_reason', 'subscription_cancellation'
    );
  end if;

  v_recurrence_cancel_state :=
    private.billing_card_recurrence_cancel_state(
      p_organization_id,
      v_provider_subscription_id
    );
  if v_recurrence_cancel_state is not null then
    return jsonb_build_object(
      'outcome', 'busy',
      'busy_reason', 'legacy_recurrence_cancellation',
      'cancellation_state', v_recurrence_cancel_state
    );
  end if;

  if private.billing_organization_cleanup_is_active(
    p_organization_id,
    v_provider_subscription_id
  ) then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  if exists (
    select 1
    from private.billing_plan_changes as plan_change
    where plan_change.organization_id = p_organization_id
      and plan_change.provider_subscription_id = v_provider_subscription_id
      and plan_change.status in ('provider_updating', 'applying')
  ) then
    return jsonb_build_object(
      'outcome', 'busy',
      'busy_reason', 'managed_plan_change'
    );
  end if;

  if v_mode = 'settled_payment' and (
       upper(btrim(coalesce(v_payment.billing_type, ''))) <> 'CREDIT_CARD'
       or nullif(btrim(coalesce(v_payment.asaas_customer_id, '')), '')
         is distinct from v_provider_customer_id
       or (
         v_payment.asaas_subscription_id is not null
         and btrim(v_payment.asaas_subscription_id)
           is distinct from v_provider_subscription_id
       )
       or not (
         private.billing_payment_checkout_is_actionable(v_payment.status)
         or private.billing_payment_checkout_is_processing(v_payment.status)
         or private.billing_payment_checkout_is_paid(v_payment.status)
       )
       or exists (
         select 1
         from private.billing_payment_checkout_cancellations as cancellation
         where cancellation.payment_id = v_payment.id
           and cancellation.finalized_at is null
       )
     ) then
    return jsonb_build_object('outcome', 'payment_not_eligible');
  end if;

  select job.*
  into v_existing
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
  for update;
  if found then
    if v_existing.organization_id is distinct from p_organization_id
       or v_existing.subscription_id is distinct from v_subscription.id
       or v_existing.provider_subscription_id
         is distinct from v_provider_subscription_id
       or v_existing.provider_customer_id is distinct from v_provider_customer_id
       or v_existing.mode is distinct from v_mode
       or v_existing.payment_id is distinct from p_payment_id
       or v_existing.provider_payment_id
         is distinct from v_provider_payment_id then
      return jsonb_build_object('outcome', 'identifier_mismatch');
    end if;

    return jsonb_strip_nulls(jsonb_build_object(
      'outcome', 'already_prepared',
      'job_id', v_existing.id,
      'subscription_row_id', v_existing.subscription_id,
      'subscription_id', v_existing.provider_subscription_id,
      'customer_id', v_existing.provider_customer_id,
      'generation', v_existing.generation,
      'mode', v_existing.mode,
      'state', case
        when v_existing.status = 'succeeded' then 'succeeded'
        when v_existing.status = 'cancelled' then 'cancelled'
        when v_existing.status = 'dead'
          and v_existing.manual_review_at is not null then 'manual_review'
        when v_existing.status = 'dead' then 'failed'
        else 'queued'
      end,
      'status', v_existing.status,
      'manual_review_at', v_existing.manual_review_at,
      'payment_id', v_existing.payment_id,
      'provider_payment_id', v_existing.provider_payment_id,
      'payment_status', case
        when v_existing.mode = 'settled_payment' then upper(v_payment.status)
        else null
      end,
      'aad', 'vimob:billing-subscription-card:' || v_existing.id::text
        || ':' || v_existing.provider_subscription_id
    ));
  end if;

  select job.*
  into v_existing
  from private.billing_subscription_card_update_jobs as job
  where job.subscription_id = v_subscription.id
    and job.status in (
      'prepared', 'awaiting_payment', 'pending_update', 'processing', 'retry'
    )
  for update;
  if found then
    if v_existing.status = 'prepared'
       and v_existing.provider_card_credential is null
       and v_existing.mode = v_mode
       and v_existing.payment_id is not distinct from p_payment_id
       and v_existing.provider_payment_id
         is not distinct from v_provider_payment_id then
      return jsonb_strip_nulls(jsonb_build_object(
        'outcome', 'resume_prepared',
        'job_id', v_existing.id,
        'subscription_row_id', v_existing.subscription_id,
        'subscription_id', v_existing.provider_subscription_id,
        'customer_id', v_existing.provider_customer_id,
        'generation', v_existing.generation,
        'mode', v_existing.mode,
        'state', 'queued',
        'status', v_existing.status,
        'payment_id', v_existing.payment_id,
        'provider_payment_id', v_existing.provider_payment_id,
        'payment_status', case
          when v_existing.mode = 'settled_payment' then upper(v_payment.status)
          else null
        end,
        'aad', 'vimob:billing-subscription-card:' || v_existing.id::text
          || ':' || v_existing.provider_subscription_id
      ));
    end if;

    v_existing_payment_status := null;
    if v_existing.mode = 'settled_payment' then
      select upper(btrim(payment.status))
      into v_existing_payment_status
      from public.asaas_payments as payment
      where payment.id = v_existing.payment_id
        and payment.organization_id = p_organization_id
        and payment.asaas_payment_id = v_existing.provider_payment_id;
    end if;

    return jsonb_strip_nulls(jsonb_build_object(
      'outcome', 'active_job_conflict',
      'job_id', v_existing.id,
      'state', 'queued',
      'status', v_existing.status,
      'generation', v_existing.generation,
      'mode', v_existing.mode,
      'payment_id', v_existing.payment_id,
      'provider_payment_id', v_existing.provider_payment_id,
      'payment_status', v_existing_payment_status
    ));
  end if;

  select coalesce(max(job.generation), 0) + 1
  into v_generation
  from private.billing_subscription_card_update_jobs as job
  where job.subscription_id = v_subscription.id;

  insert into private.billing_subscription_card_update_jobs (
    id,
    organization_id,
    subscription_id,
    provider_subscription_id,
    provider_customer_id,
    generation,
    mode,
    payment_id,
    provider_payment_id,
    status,
    next_attempt_at,
    expires_at,
    created_at,
    updated_at
  ) values (
    p_job_id,
    p_organization_id,
    v_subscription.id,
    v_provider_subscription_id,
    v_provider_customer_id,
    v_generation,
    v_mode,
    p_payment_id,
    v_provider_payment_id,
    'prepared',
    v_now,
    v_now + interval '24 hours',
    v_now,
    v_now
  );

  return jsonb_strip_nulls(jsonb_build_object(
    'outcome', 'prepared',
    'job_id', p_job_id,
    'subscription_row_id', v_subscription.id,
    'subscription_id', v_provider_subscription_id,
    'customer_id', v_provider_customer_id,
    'generation', v_generation,
    'mode', v_mode,
    'state', 'queued',
    'status', 'prepared',
    'payment_id', p_payment_id,
    'provider_payment_id', v_provider_payment_id,
    'payment_status', case
      when v_mode = 'settled_payment' then upper(v_payment.status)
      else null
    end,
    'aad', 'vimob:billing-subscription-card:' || p_job_id::text
      || ':' || v_provider_subscription_id
  ));
end
$$;


ALTER FUNCTION public.prepare_billing_subscription_card_update(p_job_id uuid, p_organization_id uuid, p_mode text, p_payment_id uuid, p_provider_payment_id text) OWNER TO postgres;

--
-- Name: prevent_property_code_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_property_code_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.code IS DISTINCT FROM OLD.code
     AND coalesce(auth.role(), '') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Property code cannot be changed after creation'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.prevent_property_code_change() OWNER TO postgres;

--
-- Name: process_automation_inbound_message(uuid, uuid, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_automation_inbound_message(p_organization_id uuid, p_lead_id uuid, p_conversation_id uuid, p_message_id uuid, p_message_type text, p_content text, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  candidate record;
  wait_step record;
  normalized_type text := lower(trim(coalesce(p_message_type, 'text')));
  normalized_content text := lower(trim(coalesce(p_content, '')));
  expected_keywords jsonb;
  keyword text;
  keyword_matched boolean;
  handoff_reason text;
  burst_limit integer;
  recent_message_count integer;
  resume_result jsonb;
  resumed_ids uuid[] := array[]::uuid[];
  cancelled_ids uuid[] := array[]::uuid[];
  target_user_id uuid;
  target_lead_name text;
  preview text;
begin
  if p_organization_id is null or p_lead_id is null or p_message_id is null or p_occurred_at is null then
    return jsonb_build_object('ok', false, 'status', 'invalid_input');
  end if;

  preview := left(coalesce(nullif(trim(p_content), ''), '[' || normalized_type || ']'), 300);

  for candidate in
    select
      e.id,
      e.conversation_id,
      e.current_node_key,
      e.next_execution_at,
      fv.created_by,
      coalesce((
        select node->'config'
        from jsonb_array_elements(coalesce(fv.graph->'nodes', '[]'::jsonb)) node
        where node->>'id' = e.current_node_key and node->>'type' = 'delay'
        limit 1
      ), '{}'::jsonb) as wait_config,
      l.assigned_user_id,
      l.name as lead_name
    from public.automation_executions e
    join public.automation_flow_versions fv
      on fv.id = e.flow_version_id
     and fv.organization_id = e.organization_id
     and fv.requires_review = false
    join public.leads l
      on l.id = e.lead_id and l.organization_id = e.organization_id
    where e.organization_id = p_organization_id
      and e.lead_id = p_lead_id
      and e.status = 'waiting'
      and e.cancellation_requested_at is null
      and (e.conversation_id is null or p_conversation_id is null or e.conversation_id = p_conversation_id)
    order by e.started_at, e.id
  loop
    if not coalesce((candidate.wait_config->>'stop_on_reply')::boolean, false) then
      continue;
    end if;

    select s.id, s.started_at
    into wait_step
    from public.automation_execution_steps s
    where s.organization_id = p_organization_id
      and s.execution_id = candidate.id
      and s.node_key = candidate.current_node_key
      and s.status = 'waiting'
    order by s.attempt desc, s.started_at desc
    limit 1;

    if wait_step.id is null
       or p_occurred_at < wait_step.started_at
       or candidate.next_execution_at is null
       or p_occurred_at > candidate.next_execution_at then
      continue;
    end if;

    handoff_reason := null;
    burst_limit := greatest(coalesce(nullif(candidate.wait_config->>'handoff_after_message_burst', '')::integer, 3), 0);

    if normalized_type not in ('text', 'conversation', 'extendedtextmessage')
       and coalesce((candidate.wait_config->>'handoff_on_non_text')::boolean, true) then
      handoff_reason := 'automation_handoff_non_text:' || normalized_type;
    end if;

    if handoff_reason is null and burst_limit > 0 then
      select count(*)
      into recent_message_count
      from public.whatsapp_messages m
      where m.organization_id = p_organization_id
        and m.lead_id = p_lead_id
        and coalesce(m.from_me, false) = false
        and m.direction = 'inbound'
        and coalesce(m.received_at, m.created_at) >= p_occurred_at - interval '2 minutes'
        and coalesce(m.received_at, m.created_at) <= p_occurred_at + interval '2 minutes';
      if recent_message_count >= burst_limit then
        handoff_reason := 'automation_handoff_message_burst';
      end if;
    end if;

    if handoff_reason is null
       and normalized_type in ('text', 'conversation', 'extendedtextmessage')
       and lower(coalesce(candidate.wait_config->>'reply_match_mode', 'any_text')) = 'keywords' then
      expected_keywords := coalesce(candidate.wait_config->'expected_reply_keywords', '[]'::jsonb);
      keyword_matched := false;
      if jsonb_typeof(expected_keywords) = 'array' then
        for keyword in select lower(trim(value)) from jsonb_array_elements_text(expected_keywords)
        loop
          if keyword <> '' and position(keyword in normalized_content) > 0 then
            keyword_matched := true;
            exit;
          end if;
        end loop;
      end if;
      if not keyword_matched
         and coalesce((candidate.wait_config->>'handoff_on_unmatched_reply')::boolean, true) then
        handoff_reason := 'automation_handoff_unmatched_reply';
      end if;
    end if;

    target_user_id := coalesce(candidate.assigned_user_id, candidate.created_by);
    target_lead_name := coalesce(nullif(candidate.lead_name, ''), 'Lead');

    if handoff_reason is not null then
      if (select count(*) from unnest(private.cancel_lead_automation_executions(
        p_organization_id, p_lead_id, handoff_reason, p_conversation_id
      ))) > 0 then
        cancelled_ids := array_append(cancelled_ids, candidate.id);
        perform private.notify_automation_attention(
          p_organization_id,
          p_lead_id,
          target_user_id,
          'Automacao pausada: atendimento humano necessario',
          target_lead_name || ' enviou uma resposta fora do fluxo (' || preview || ').',
          'automation_handoff',
          'automation_handoff:' || p_message_id::text || ':' || target_user_id::text,
          jsonb_build_object(
            'reason', handoff_reason,
            'message_id', p_message_id,
            'conversation_id', p_conversation_id,
            'execution_id', candidate.id
          )
        );

        insert into public.lead_timeline_events (
          organization_id, lead_id, event_type, title, description,
          user_id, actor_user_id, metadata, event_at
        ) values (
          p_organization_id, p_lead_id,
          'automation_handoff',
          'Automacao pausada para atendimento humano', preview,
          target_user_id, target_user_id,
          jsonb_build_object(
            'reason', handoff_reason,
            'message_id', p_message_id,
            'conversation_id', p_conversation_id,
            'execution_id', candidate.id
          ),
          p_occurred_at
        );
      end if;
      exit;
    end if;

    resume_result := public.resume_automation_delay(
      p_organization_id,
      candidate.id,
      'replied',
      p_occurred_at,
      jsonb_build_object(
        'message_id', p_message_id,
        'message_type', normalized_type,
        'content', p_content,
        'conversation_id', p_conversation_id
      ),
      p_lead_id,
      p_conversation_id
    );

    if coalesce((resume_result->>'ok')::boolean, false) then
      resumed_ids := array_append(resumed_ids, candidate.id);
      perform private.notify_automation_attention(
        p_organization_id,
        p_lead_id,
        target_user_id,
        'Lead respondeu a automacao',
        target_lead_name || ' respondeu: ' || preview,
        'automation_reply',
        'automation_reply:' || p_message_id::text || ':' || target_user_id::text,
        jsonb_build_object(
          'message_id', p_message_id,
          'conversation_id', p_conversation_id,
          'execution_id', candidate.id
        )
      );
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'status', 'processed',
    'resumed_execution_ids', to_jsonb(resumed_ids),
    'cancelled_execution_ids', to_jsonb(cancelled_ids)
  );
end;
$$;


ALTER FUNCTION public.process_automation_inbound_message(p_organization_id uuid, p_lead_id uuid, p_conversation_id uuid, p_message_id uuid, p_message_type text, p_content text, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: process_managed_whatsapp_lead_entry(uuid, uuid, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_managed_whatsapp_lead_entry(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_rule_id uuid, p_provider_message_id text, p_message text, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_now timestamptz := clock_timestamp();
  v_occurred_at timestamptz;
  v_provider_message_id text := btrim(coalesce(p_provider_message_id, ''));
  v_provider_event_id text;
  v_distribution_key text;
  v_message_fingerprint text;
  v_effective_rule_id uuid := p_rule_id;
  v_pending_context jsonb := '{}'::jsonb;
  v_pending_round_robin_id uuid;
  v_has_pending_context boolean := false;
  v_lead public.leads%rowtype;
  v_existing_entry public.lead_entry_events%rowtype;
  v_initial_entry public.lead_entry_events%rowtype;
  v_entry_id uuid;
  v_initial_entry_id uuid;
  v_round_robin_id uuid;
  v_keyword text;
  v_reentry_behavior text;
  v_initial_provider_event_id text;
  v_last_provider_event_id text;
  v_is_initial boolean := false;
  v_should_apply_state boolean := true;
  v_previous_job public.lead_redistribution_jobs%rowtype;
  v_had_previous_job boolean := false;
  v_previous_assigned_user_id uuid;
  v_assigned_user_id uuid;
  v_same_assignee_redistribution boolean := false;
  v_pending_job_id uuid;
  v_pending_queue_settings jsonb;
  v_pending_timeout_minutes integer;
  v_pending_warning_minutes integer;
  v_pending_max_attempts integer;
  v_tags_applied integer := 0;
  v_initial_distribution_result jsonb;
  v_distribution_result jsonb := '{}'::jsonb;
  v_intake_result jsonb;
  v_event_metadata jsonb;
begin
  if p_organization_id is null
     or p_lead_id is null
     or p_session_id is null
     or length(v_provider_message_id) not between 1 and 500
     or p_provider_message_id <> v_provider_message_id
     or nullif(btrim(coalesce(p_message, '')), '') is null
     or octet_length(p_message) > 65536 then
    raise exception using
      errcode = '22023',
      message = 'managed_whatsapp_entry_invalid_input';
  end if;

  v_occurred_at := least(
    coalesce(p_occurred_at, v_now),
    v_now + interval '5 minutes'
  );
  v_provider_event_id := p_session_id::text || ':' || v_provider_message_id;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'managed-whatsapp-entry:'
        || p_organization_id::text || ':' || v_provider_event_id,
      0
    )
  );

  select lead.*
    into v_lead
    from public.leads as lead
   where lead.organization_id = p_organization_id
     and lead.id = p_lead_id
   for no key update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'managed_whatsapp_entry_lead_not_found';
  end if;

  -- The immutable provider message is the idempotency boundary. Resolve it
  -- before checking mutable rule/queue state, so a later configuration change
  -- cannot turn an already committed delivery into an endless retry.
  v_message_fingerprint := private.managed_whatsapp_message_fingerprint(
    p_organization_id,
    p_session_id,
    v_provider_message_id,
    p_message
  );
  v_distribution_key := 'managed-whatsapp-entry:' || pg_catalog.encode(
    extensions.digest(v_provider_event_id, 'sha256'),
    'hex'
  );

  select entry.*
    into v_existing_entry
    from public.lead_entry_events as entry
   where entry.organization_id = p_organization_id
     and entry.provider = 'whatsapp'
     and entry.provider_event_id = v_provider_event_id
     and entry.is_countable = true
   limit 1
   for update;

  if found then
    if v_existing_entry.lead_id is distinct from p_lead_id
       or coalesce(v_existing_entry.metadata->>'message_fingerprint', '')
          is distinct from v_message_fingerprint
       or coalesce(v_existing_entry.metadata->>'whatsapp_session_id', '')
          is distinct from p_session_id::text then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_provider_message_collision';
    end if;

    return (
      case
        when jsonb_typeof(v_existing_entry.metadata->'intake_result') = 'object'
          then v_existing_entry.metadata->'intake_result'
        else jsonb_build_object(
          'success', false,
          'reason', 'managed_whatsapp_ledger_result_missing'
        )
      end
    ) || jsonb_build_object(
      'handled', true,
      'pending', false,
      'duplicate_retry', true,
      'lead_id', v_existing_entry.lead_id,
      'entry_event_id', v_existing_entry.id,
      'matched_rule_id', nullif(v_existing_entry.metadata->>'matched_rule_id', ''),
      'target_round_robin_id', nullif(coalesce(
        v_existing_entry.metadata->>'target_round_robin_id',
        v_existing_entry.metadata->'intake_result'->>'round_robin_id'
      ), '')
    );
  end if;

  -- A new lifecycle event must correspond to the inbound message already
  -- persisted by the authenticated webhook path. Exact retries returned above
  -- remain valid even if old message history is later archived.
  if not exists (
    select 1
    from public.whatsapp_messages as message
    where message.organization_id = p_organization_id
      and message.session_id = p_session_id
      and message.lead_id = p_lead_id
      and (
        message.provider_message_id = v_provider_message_id
        or (
          message.provider_message_id is null
          and message.message_id = v_provider_message_id
        )
      )
      and coalesce(message.from_me, false) = false
      and lower(coalesce(message.direction, 'inbound')) <> 'outbound'
      and private.whatsapp_attendance_message_evidence_matches(
        message.capture_state,
        message.content,
        message.metadata,
        v_message_fingerprint,
        p_message
      )
  ) then
    raise exception using
      errcode = '23514',
      message = 'managed_whatsapp_entry_message_not_persisted';
  end if;

  -- Bind an unfinished delivery to the immutable context captured before the
  -- ledger write. This intentionally runs before any current rule lookup. A
  -- caller may omit p_rule_id on retry; if it supplies one, it must be the
  -- original rule recovered from lead/log provenance.
  v_pending_context := public.lookup_managed_whatsapp_lead_entry(
    p_organization_id,
    p_session_id,
    v_provider_message_id,
    p_message
  );
  v_has_pending_context := lower(coalesce(v_pending_context->>'pending', 'false'))
    in ('true', '1', 'yes');

  if v_has_pending_context then
    if coalesce(v_pending_context->>'lead_id', '') is distinct from p_lead_id::text then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_provider_message_collision';
    end if;

    begin
      v_effective_rule_id := nullif(
        btrim(v_pending_context->>'matched_rule_id'),
        ''
      )::uuid;
      v_pending_round_robin_id := nullif(
        btrim(v_pending_context->>'target_round_robin_id'),
        ''
      )::uuid;
    exception
      when invalid_text_representation then
        raise exception using
          errcode = '23514',
          message = 'managed_whatsapp_pending_context_invalid';
    end;

    if v_effective_rule_id is null
       or v_pending_round_robin_id is null
       or (
         p_rule_id is not null
         and p_rule_id is distinct from v_effective_rule_id
       ) then
      raise exception using
        errcode = '23514',
        message = 'managed_whatsapp_pending_context_invalid';
    end if;
  elsif p_rule_id is null then
    raise exception using
      errcode = '22023',
      message = 'managed_whatsapp_entry_invalid_input';
  end if;

  if v_has_pending_context then
    select
      queue.id,
      case
        when lower(btrim(coalesce(queue.reentry_behavior, 'redistribute')))
          = 'keep_assignee' then 'keep_assignee'
        else 'redistribute'
      end,
      ''::text
      into v_round_robin_id, v_reentry_behavior, v_keyword
      from public.round_robins as queue
      join public.whatsapp_sessions as whatsapp_session
        on whatsapp_session.organization_id = queue.organization_id
       and whatsapp_session.id = p_session_id
     where queue.organization_id = p_organization_id
       and queue.id = v_pending_round_robin_id
       and coalesce(queue.is_active, true) = true
       and whatsapp_session.provider = 'evolution_go'
       and coalesce(whatsapp_session.is_active, true) = true
       and lower(btrim(coalesce(whatsapp_session.status, '')))
         not in ('deleted', 'disabled')
     limit 1
     for no key update of queue;
  else
    select
      queue.id,
      case
        when lower(btrim(coalesce(queue.reentry_behavior, 'redistribute')))
          = 'keep_assignee' then 'keep_assignee'
        else 'redistribute'
      end,
      normalized.keyword
      into v_round_robin_id, v_reentry_behavior, v_keyword
      from public.round_robin_rules as round_robin_rule
      join public.whatsapp_inbound_rules as inbound_rule
        on inbound_rule.organization_id = round_robin_rule.organization_id
       and inbound_rule.id = round_robin_rule.id
       and inbound_rule.target_round_robin_id = round_robin_rule.round_robin_id
      join public.round_robins as queue
        on queue.organization_id = round_robin_rule.organization_id
       and queue.id = round_robin_rule.round_robin_id
      join public.whatsapp_sessions as whatsapp_session
        on whatsapp_session.organization_id = inbound_rule.organization_id
       and whatsapp_session.id = inbound_rule.session_id
      cross join lateral (
        select btrim(coalesce(
          nullif(round_robin_rule.match_value, ''),
          round_robin_rule.conditions->>'match_value',
          ''
        )) as keyword
      ) as normalized
     where round_robin_rule.organization_id = p_organization_id
       and round_robin_rule.id = v_effective_rule_id
       and inbound_rule.session_id = p_session_id
       and coalesce(round_robin_rule.is_active, true) = true
       and coalesce(inbound_rule.is_active, true) = true
       and coalesce(queue.is_active, true) = true
       and whatsapp_session.provider = 'evolution_go'
       and coalesce(whatsapp_session.is_active, true) = true
       and lower(btrim(coalesce(whatsapp_session.status, '')))
         not in ('deleted', 'disabled')
       and coalesce(
         nullif(round_robin_rule.match_type, ''),
         round_robin_rule.conditions->>'match_type',
         round_robin_rule.name,
         ''
       ) = 'whatsapp_message_contains'
       and coalesce(
         nullif(btrim(round_robin_rule.match->>'whatsapp_session_id'), ''),
         nullif(btrim(round_robin_rule.conditions->'match'->>'whatsapp_session_id'), '')
       ) = p_session_id::text
       and lower(btrim(coalesce(inbound_rule.match_type, ''))) = 'contains'
       and lower(btrim(coalesce(inbound_rule.match_field, 'message'))) = 'message'
       and normalized.keyword <> ''
       and lower(btrim(coalesce(inbound_rule.match_value, '')))
         = lower(normalized.keyword)
       and lower(btrim(coalesce(queue.settings->>'require_checkin', 'false')))
         not in ('true', '1', 'yes')
       and position(lower(normalized.keyword) in lower(p_message)) > 0
     limit 1
     for no key update of queue;
  end if;

  if not found then
    raise exception using
      errcode = '23514',
      message = 'managed_whatsapp_entry_context_invalid';
  end if;

  v_initial_provider_event_id := btrim(coalesce(
    v_lead.metadata->>'managed_whatsapp_initial_provider_event_id',
    ''
  ));
  v_last_provider_event_id := btrim(coalesce(
    v_lead.metadata->>'last_whatsapp_provider_event_id',
    ''
  ));
  v_is_initial := v_initial_provider_event_id = v_provider_event_id;

  select entry.*
    into v_initial_entry
    from public.lead_entry_events as entry
   where entry.organization_id = p_organization_id
     and entry.lead_id = p_lead_id
     and entry.entry_type = 'initial'
   order by entry.created_at, entry.id
   limit 1
   for update;
  if found then
    v_initial_entry_id := v_initial_entry.id;
  end if;

  -- Compatibility for managed leads created by the previous image: the
  -- provider id was not persisted yet, but its original timestamp/message can
  -- still identify a replay without turning it into a false reentry.
  if not v_is_initial
     and v_initial_provider_event_id = ''
     and lower(btrim(coalesce(v_lead.source, ''))) = 'whatsapp'
     and v_lead.source_session_id = p_session_id
     and lower(btrim(coalesce(
       v_lead.metadata->>'managed_whatsapp_message_distribution',
       'false'
     ))) in ('true', '1', 'yes')
     and coalesce(v_lead.metadata->>'whatsapp_session_id', '') = p_session_id::text
     and coalesce(v_lead.metadata->>'matched_rule_id', '') = v_effective_rule_id::text
     and coalesce(v_lead.metadata->>'target_round_robin_id', '') = v_round_robin_id::text
     and (
       btrim(coalesce(v_lead.initial_message, '')) = btrim(p_message)
       or private.whatsapp_managed_initial_proof_matches(
         p_organization_id,
         p_lead_id,
         p_session_id,
         v_provider_event_id,
         v_message_fingerprint,
         v_effective_rule_id,
         v_round_robin_id
       )
     )
     and abs(extract(epoch from (v_lead.created_at - v_occurred_at))) <= 600
     and v_initial_entry_id is not null
     and coalesce(v_initial_entry.provider, 'whatsapp') = 'whatsapp'
     and (
       v_initial_entry.provider_event_id is null
       or v_initial_entry.provider_event_id in (
         v_provider_event_id,
         v_provider_message_id
       )
     )
     and not exists (
       select 1
       from public.lead_entry_events as prior_reentry
       where prior_reentry.organization_id = p_organization_id
         and prior_reentry.lead_id = p_lead_id
         and prior_reentry.entry_type = 'reentry'
         and prior_reentry.is_countable = true
     ) then
    v_is_initial := true;
  end if;

  v_event_metadata := jsonb_build_object(
    'managed_whatsapp_message_distribution', true,
    'whatsapp_session_id', p_session_id,
    'matched_rule_id', v_effective_rule_id,
    'target_round_robin_id', v_round_robin_id,
    'provider_message_id', v_provider_message_id,
    'message_fingerprint', v_message_fingerprint,
    'keyword', v_keyword
  );

  if v_is_initial then
    if v_initial_entry_id is null then
      raise exception using
        errcode = '55000',
        message = 'managed_whatsapp_initial_entry_missing';
    end if;

    -- Establish the same chronological projection used by later reentries,
    -- without incrementing reentry_count. A newer provider event may already
    -- have won while the first webhook was between its database calls; in that
    -- case only the monotonic contact/entry timestamps are retained.
    v_should_apply_state :=
      v_lead.last_entry_at is null
      or v_occurred_at > v_lead.last_entry_at
      or (
        v_occurred_at = v_lead.last_entry_at
        and v_provider_event_id > v_last_provider_event_id
      );

    update public.leads as lead
       set message = case
             when v_should_apply_state then p_message
             else lead.message
           end,
           last_contact_at = greatest(
             coalesce(lead.last_contact_at, v_occurred_at),
             v_occurred_at
           ),
           last_entry_at = greatest(
             coalesce(lead.last_entry_at, v_occurred_at),
             v_occurred_at
           ),
           metadata = case
             when v_should_apply_state then
               coalesce(lead.metadata, '{}'::jsonb) || jsonb_build_object(
                 'last_whatsapp_session_id', p_session_id,
                 'last_whatsapp_provider_event_id', v_provider_event_id,
                 'last_whatsapp_entry_event_id', v_initial_entry_id
               )
             else coalesce(lead.metadata, '{}'::jsonb)
           end,
           updated_at = v_now
     where lead.organization_id = p_organization_id
       and lead.id = p_lead_id;

    v_assigned_user_id := v_lead.assigned_user_id;

    -- Initial assignment was performed by the lead INSERT trigger. Read its
    -- canonical ledger instead of reporting a fixed success that could hide a
    -- no-available-members outcome. Both keys cover the known canonical and
    -- managed routing entrypoints used by the production baseline.
    select distribution_event.result
      into v_initial_distribution_result
      from private.lead_distribution_events as distribution_event
     where distribution_event.organization_id = p_organization_id
       and distribution_event.lead_id = p_lead_id
       and distribution_event.idempotency_key in (
         'managed-whatsapp:' || p_lead_id::text || ':' || v_effective_rule_id::text,
         'trigger:' || p_lead_id::text
       )
       and distribution_event.outcome <> 'processing'
     order by
       case
         when distribution_event.idempotency_key =
            'managed-whatsapp:' || p_lead_id::text || ':' || v_effective_rule_id::text
           then 0
         else 1
       end,
       distribution_event.completed_at desc nulls last,
       distribution_event.created_at desc,
       distribution_event.id desc
     limit 1;

    if v_initial_distribution_result is null
       or jsonb_typeof(v_initial_distribution_result) <> 'object'
       or not (v_initial_distribution_result ? 'success') then
      v_initial_distribution_result := jsonb_build_object(
        'success', v_assigned_user_id is not null,
        'reason', case
          when v_assigned_user_id is not null then 'assigned_state_observed'
          else 'initial_distribution_result_missing'
        end,
        'lead_id', p_lead_id,
        'round_robin_id', v_round_robin_id,
        'assigned_user_id', v_assigned_user_id
      );
    end if;

    v_tags_applied := private.apply_round_robin_auto_tags(
      p_organization_id,
      v_round_robin_id,
      p_lead_id
    );

    -- Only the chronologically current initial event may create a pending
    -- distribution job. If a newer message already assigned the lead, replaying
    -- the initial webhook must not supersede that newer lifecycle state.
    v_pending_job_id := null;
    if v_should_apply_state and v_assigned_user_id is null then
      select job.id
        into v_pending_job_id
        from public.lead_redistribution_jobs as job
       where job.organization_id = p_organization_id
         and job.lead_id = p_lead_id
         and job.status in ('pending', 'warning_sent')
       order by job.created_at, job.id
       limit 1
       for update;

      if v_pending_job_id is null then
        v_pending_job_id := private.enqueue_managed_whatsapp_initial_distribution(
          p_organization_id,
          v_round_robin_id,
          p_lead_id,
          v_initial_entry_id,
          v_now
        );
      end if;

      if v_pending_job_id is null then
        raise exception using
          errcode = '55000',
          message = 'managed_whatsapp_pending_distribution_job_missing';
      end if;
    end if;

    v_intake_result := jsonb_build_object(
      'handled', true,
      'initial_distribution_result', v_initial_distribution_result
    ) || v_initial_distribution_result || jsonb_build_object(
      'handled', true,
      'entry_type', 'initial',
      'lead_id', p_lead_id,
      'entry_event_id', v_initial_entry_id,
      'round_robin_id', v_round_robin_id,
      'assigned_user_id', v_assigned_user_id,
      'applied_to_current_state', v_should_apply_state,
      'tags_applied', v_tags_applied
    );

    if v_pending_job_id is not null then
      v_intake_result := v_intake_result || jsonb_build_object(
        'distribution_pending', true,
        'pending_distribution_job_id', v_pending_job_id
      );
    end if;

    update public.lead_entry_events as entry
       set source = 'whatsapp',
           provider = 'whatsapp',
           provider_event_id = v_provider_event_id,
           occurred_at = v_occurred_at,
           is_countable = true,
           source_detail = coalesce(nullif(entry.source_detail, ''), 'managed_whatsapp_message'),
           metadata = coalesce(entry.metadata, '{}'::jsonb)
             || v_event_metadata
             || jsonb_build_object('intake_result', v_intake_result)
     where entry.id = v_initial_entry_id
       and (
         entry.provider_event_id is null
         or entry.provider_event_id in (
           v_provider_event_id,
           v_provider_message_id
         )
       );

    if not found then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_initial_provider_message_conflict';
    end if;

    update public.whatsapp_conversations as conversation
       set assigned_user_id = v_assigned_user_id,
           updated_at = v_now
     where conversation.organization_id = p_organization_id
       and conversation.session_id = p_session_id
       and conversation.lead_id = p_lead_id;

    update public.whatsapp_inbound_logs as inbound_log
       set lead_id = p_lead_id,
           matched_rule_id = v_effective_rule_id,
           assigned_user_id = v_assigned_user_id,
           match_details = coalesce(inbound_log.match_details, '{}'::jsonb)
             || jsonb_build_object(
               'entry_event_id', v_initial_entry_id,
               'intake_outcome', v_intake_result->>'reason',
               'distribution_pending', v_pending_job_id is not null,
               'pending_distribution_job_id', v_pending_job_id
             )
     where inbound_log.organization_id = p_organization_id
       and inbound_log.session_id = p_session_id
       and inbound_log.match_details->>'message_id' = v_provider_message_id;

    return v_intake_result;
  end if;

  insert into public.lead_entry_events (
    organization_id,
    lead_id,
    source,
    provider,
    provider_event_id,
    occurred_at,
    is_countable,
    source_detail,
    entry_type,
    pipeline_id,
    stage_id,
    metadata
  )
  values (
    p_organization_id,
    p_lead_id,
    'whatsapp',
    'whatsapp',
    v_provider_event_id,
    v_occurred_at,
    true,
    'managed_whatsapp_message',
    'reentry',
    v_lead.pipeline_id,
    v_lead.stage_id,
    v_event_metadata
  )
  on conflict (organization_id, provider, provider_event_id)
    where provider_event_id is not null and is_countable = true
  do nothing
  returning id into v_entry_id;

  if v_entry_id is null then
    select entry.*
      into v_existing_entry
      from public.lead_entry_events as entry
     where entry.organization_id = p_organization_id
       and entry.provider = 'whatsapp'
       and entry.provider_event_id = v_provider_event_id
       and entry.is_countable = true
     limit 1;

    if not found
       or v_existing_entry.lead_id is distinct from p_lead_id
       or coalesce(v_existing_entry.metadata->>'message_fingerprint', '')
          is distinct from v_message_fingerprint then
      raise exception using
        errcode = '23505',
        message = 'managed_whatsapp_provider_message_collision';
    end if;

    return (
      case
        when jsonb_typeof(v_existing_entry.metadata->'intake_result') = 'object'
          then v_existing_entry.metadata->'intake_result'
        else jsonb_build_object(
          'success', false,
          'reason', 'managed_whatsapp_ledger_result_missing'
        )
      end
    ) || jsonb_build_object(
      'handled', true,
      'pending', false,
      'duplicate_retry', true,
      'lead_id', v_existing_entry.lead_id,
      'entry_event_id', v_existing_entry.id,
      'matched_rule_id', nullif(v_existing_entry.metadata->>'matched_rule_id', ''),
      'target_round_robin_id', nullif(coalesce(
        v_existing_entry.metadata->>'target_round_robin_id',
        v_existing_entry.metadata->'intake_result'->>'round_robin_id'
      ), '')
    );
  end if;

  v_should_apply_state :=
    v_lead.last_entry_at is null
    or v_occurred_at > v_lead.last_entry_at
    or (
      v_occurred_at = v_lead.last_entry_at
      and v_provider_event_id > v_last_provider_event_id
    );

  update public.leads as lead
     set message = case
           when v_should_apply_state then p_message
           else lead.message
         end,
         last_contact_at = greatest(
           coalesce(lead.last_contact_at, v_occurred_at),
           v_occurred_at
         ),
         last_entry_at = greatest(
           coalesce(lead.last_entry_at, v_occurred_at),
           v_occurred_at
         ),
         reentry_count = coalesce(lead.reentry_count, 0) + 1,
         metadata = case
           when v_should_apply_state then
             coalesce(lead.metadata, '{}'::jsonb) || jsonb_build_object(
               'last_whatsapp_session_id', p_session_id,
               'last_whatsapp_provider_event_id', v_provider_event_id,
               'last_whatsapp_entry_event_id', v_entry_id
             )
           else coalesce(lead.metadata, '{}'::jsonb)
         end,
         updated_at = v_now
   where lead.organization_id = p_organization_id
     and lead.id = p_lead_id;

  insert into public.lead_timeline_events (
    organization_id,
    lead_id,
    event_type,
    title,
    description,
    metadata,
    event_at
  )
  values (
    p_organization_id,
    p_lead_id,
    'lead_reentry',
    'Lead reentrou pelo WhatsApp',
    'Uma nova mensagem compatível com a fila iniciou uma nova entrada.',
    v_event_metadata || jsonb_build_object(
      'entry_event_id', v_entry_id,
      'reentry_behavior', v_reentry_behavior,
      'applied_to_current_state', v_should_apply_state
    ),
    v_occurred_at
  );

  if not v_should_apply_state then
    v_tags_applied := private.apply_round_robin_auto_tags(
      p_organization_id,
      v_round_robin_id,
      p_lead_id
    );
    v_intake_result := jsonb_build_object(
      'handled', true,
      'success', true,
      'reason', 'stale_reentry_recorded',
      'entry_type', 'reentry',
      'lead_id', p_lead_id,
      'entry_event_id', v_entry_id,
      'round_robin_id', v_round_robin_id,
      'tags_applied', v_tags_applied
    );

    update public.lead_entry_events
       set metadata = metadata || jsonb_build_object('intake_result', v_intake_result)
     where id = v_entry_id;
    return v_intake_result;
  end if;

  select job.*
    into v_previous_job
    from public.lead_redistribution_jobs as job
   where job.organization_id = p_organization_id
     and job.lead_id = p_lead_id
     and job.status in ('pending', 'warning_sent')
   limit 1
   for update;
  v_had_previous_job := found;
  v_previous_assigned_user_id := v_lead.assigned_user_id;

  if v_had_previous_job then
    update public.lead_redistribution_jobs
       set status = 'stopped',
           stopped_at = v_now,
           stopped_reason = 'superseded_by_whatsapp_reentry',
           metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
             'superseded_by_entry_event_id', v_entry_id,
             'superseded_by_provider_event_id', v_provider_event_id
           ),
           updated_at = v_now
     where id = v_previous_job.id;
  end if;

  v_distribution_result := private.distribute_lead(
    p_organization_id,
    p_lead_id,
    v_distribution_key,
    v_round_robin_id,
    v_reentry_behavior = 'keep_assignee',
    'whatsapp',
    v_now
  );

  select lead.assigned_user_id
    into v_assigned_user_id
    from public.leads as lead
   where lead.organization_id = p_organization_id
     and lead.id = p_lead_id;

  v_same_assignee_redistribution :=
    v_reentry_behavior = 'redistribute'
    and v_assigned_user_id is not distinct from v_previous_assigned_user_id;

  if v_same_assignee_redistribution then
    v_distribution_result := coalesce(v_distribution_result, '{}'::jsonb)
      || jsonb_build_object(
        'success', false,
        'reason', case
          when lower(coalesce(v_distribution_result->>'success', 'false'))
            in ('true', '1', 'yes')
            then 'redistribution_pending_same_assignee'
          else coalesce(
            nullif(v_distribution_result->>'reason', ''),
            'redistribution_pending_same_assignee'
          )
        end,
        'assigned_user_id', v_assigned_user_id
      );
  end if;

  v_pending_job_id := null;

  if v_reentry_behavior = 'keep_assignee'
     and v_assigned_user_id is not null
     and coalesce(v_distribution_result->>'reason', '') = 'already_assigned' then
    insert into public.round_robin_logs (
      organization_id,
      round_robin_id,
      lead_id,
      assigned_user_id,
      rule_matched,
      reason,
      metadata,
      created_at
    )
    values (
      p_organization_id,
      v_round_robin_id,
      p_lead_id,
      v_assigned_user_id,
      v_effective_rule_id,
      'managed_whatsapp_reentry_keep_assignee',
      jsonb_build_object(
        'source', 'whatsapp',
        'entry_event_id', v_entry_id,
        'provider_event_id', v_provider_event_id,
        'distribution_event_id', v_distribution_result->>'distribution_event_id'
      ),
      v_now
    );
  elsif lower(coalesce(v_distribution_result->>'success', 'false'))
          not in ('true', '1', 'yes')
        and v_had_previous_job then
    -- Restore the prior timer only when the canonical distributor did not
    -- create a replacement active job. Otherwise the unique active-job index
    -- would reject this restore; the pending block below will lock, accelerate
    -- and rebind that canonical job to this managed queue.
    update public.lead_redistribution_jobs as previous_job
       set status = v_previous_job.status,
           stopped_at = v_previous_job.stopped_at,
           stopped_reason = v_previous_job.stopped_reason,
           metadata = v_previous_job.metadata,
           updated_at = v_now
     where previous_job.organization_id = p_organization_id
       and previous_job.lead_id = p_lead_id
       and previous_job.id = v_previous_job.id
       and not exists (
         select 1
         from public.lead_redistribution_jobs as canonical_active_job
         where canonical_active_job.organization_id = p_organization_id
           and canonical_active_job.lead_id = p_lead_id
           and canonical_active_job.id <> v_previous_job.id
           and canonical_active_job.status in ('pending', 'warning_sent')
       );
    if found then
      v_pending_job_id := v_previous_job.id;
    end if;
  end if;

  -- A queue miss must remain retryable. An unassigned lead uses the initial
  -- distribution mode. A redistribute reentry that kept the same assignee is
  -- never reported as complete: accelerate an active timer or create the same
  -- durable job with the explicit assigned-retry mode.
  if v_assigned_user_id is null
     or v_same_assignee_redistribution then
    select job.id
      into v_pending_job_id
      from public.lead_redistribution_jobs as job
     where job.organization_id = p_organization_id
       and job.lead_id = p_lead_id
       and job.status in ('pending', 'warning_sent')
     order by job.created_at, job.id
       limit 1
       for update;

    if v_pending_job_id is not null then
      select coalesce(queue.settings, '{}'::jsonb)
        into v_pending_queue_settings
        from public.round_robins as queue
       where queue.organization_id = p_organization_id
         and queue.id = v_round_robin_id
         and coalesce(queue.is_active, true) = true;

      if not found then
        raise exception using
          errcode = '23514',
          message = 'managed_whatsapp_entry_context_invalid';
      end if;

      v_pending_timeout_minutes := least(10080, greatest(1, coalesce(
        case
          when coalesce(
            v_pending_queue_settings->>'redistribution_timeout_minutes',
            ''
          ) ~ '^[0-9]{1,9}$'
            then (v_pending_queue_settings->>'redistribution_timeout_minutes')::integer
        end,
        20
      )));
      v_pending_warning_minutes := greatest(0, coalesce(
        case
          when coalesce(
            v_pending_queue_settings->>'redistribution_warning_minutes',
            ''
          ) ~ '^[0-9]{1,9}$'
            then (v_pending_queue_settings->>'redistribution_warning_minutes')::integer
        end,
        5
      ));
      v_pending_warning_minutes := least(
        v_pending_warning_minutes,
        v_pending_timeout_minutes - 1
      );
      v_pending_max_attempts := least(1000, greatest(0, coalesce(
        case
          when coalesce(
            v_pending_queue_settings->>'redistribution_max_attempts',
            ''
          ) ~ '^[0-9]{1,9}$'
            then (v_pending_queue_settings->>'redistribution_max_attempts')::integer
        end,
        10
      )));

      update public.lead_redistribution_jobs as pending_job
         set round_robin_id = v_round_robin_id,
             original_assigned_user_id = v_assigned_user_id,
             current_assigned_user_id = v_assigned_user_id,
             attempt_count = 0,
             max_attempts = v_pending_max_attempts,
             timeout_minutes = v_pending_timeout_minutes,
             warning_minutes = v_pending_warning_minutes,
             enrolled_at = v_now,
             status = 'pending',
             due_at = v_now,
             warning_due_at = null,
             warning_sent_at = null,
             last_redistributed_at = null,
             stopped_at = null,
             stopped_reason = null,
             metadata = (
               coalesce(pending_job.metadata, '{}'::jsonb)
                 - 'waiting_for_available_member'
                 - 'next_candidate_check_at'
             )
               || jsonb_build_object(
                 'source', 'managed_whatsapp',
                 'initial_distribution_pending', true,
                 'allow_assigned_redistribution', v_assigned_user_id is not null,
                 'entry_event_id', v_entry_id
               ),
             updated_at = v_now
       where pending_job.organization_id = p_organization_id
         and pending_job.lead_id = p_lead_id
         and pending_job.id = v_pending_job_id;
      if not found then
        v_pending_job_id := null;
      end if;
    else
      v_pending_job_id := private.enqueue_managed_whatsapp_initial_distribution(
        p_organization_id,
        v_round_robin_id,
        p_lead_id,
        v_entry_id,
        v_now,
        v_assigned_user_id is not null
      );
    end if;

    if v_pending_job_id is null then
      raise exception using
        errcode = '55000',
        message = 'managed_whatsapp_pending_distribution_job_missing';
    end if;
  end if;

  v_tags_applied := private.apply_round_robin_auto_tags(
    p_organization_id,
    v_round_robin_id,
    p_lead_id
  );

  update public.whatsapp_conversations as conversation
     set assigned_user_id = v_assigned_user_id,
         updated_at = v_now
   where conversation.organization_id = p_organization_id
     and conversation.session_id = p_session_id
     and conversation.lead_id = p_lead_id;

  v_intake_result := jsonb_build_object(
    'handled', true,
    'entry_type', 'reentry',
    'lead_id', p_lead_id,
    'entry_event_id', v_entry_id,
    'round_robin_id', v_round_robin_id,
    'reentry_behavior', v_reentry_behavior,
    'tags_applied', v_tags_applied
  ) || coalesce(v_distribution_result, '{}'::jsonb);

  if v_pending_job_id is not null then
    v_intake_result := v_intake_result || jsonb_build_object(
      'distribution_pending', true,
      'pending_distribution_job_id', v_pending_job_id,
      'distribution_result', v_distribution_result
    );
  end if;

  update public.lead_entry_events
     set metadata = metadata || jsonb_build_object('intake_result', v_intake_result)
   where id = v_entry_id;

  update public.whatsapp_inbound_logs as inbound_log
     set lead_id = p_lead_id,
         matched_rule_id = v_effective_rule_id,
         assigned_user_id = v_assigned_user_id,
         match_details = coalesce(inbound_log.match_details, '{}'::jsonb)
           || jsonb_build_object(
             'entry_event_id', v_entry_id,
             'intake_outcome', v_intake_result->>'reason'
           )
   where inbound_log.organization_id = p_organization_id
     and inbound_log.session_id = p_session_id
     and inbound_log.match_details->>'message_id' = v_provider_message_id;

  return v_intake_result;
end;
$_$;


ALTER FUNCTION public.process_managed_whatsapp_lead_entry(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_rule_id uuid, p_provider_message_id text, p_message text, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION process_managed_whatsapp_lead_entry(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_rule_id uuid, p_provider_message_id text, p_message text, p_occurred_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.process_managed_whatsapp_lead_entry(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_rule_id uuid, p_provider_message_id text, p_message text, p_occurred_at timestamp with time zone) IS 'Records one managed WhatsApp intake per session/provider message id and applies reentry distribution atomically; exact provider retries are side-effect free.';


--
-- Name: process_managed_whatsapp_lead_entry_attendance(uuid, uuid, uuid, uuid, text, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_managed_whatsapp_lead_entry_attendance(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_rule_id uuid, p_provider_message_id text, p_message text, p_occurred_at timestamp with time zone, p_suppress_lead_message boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_previous_capture_setting text := pg_catalog.current_setting(
    'vimob.whatsapp_attendance_capture',
    true
  );
  v_result jsonb;
begin
  if p_suppress_lead_message is null then
    raise exception using
      errcode = '22023',
      message = 'whatsapp_attendance_suppression_flag_required';
  end if;

  perform pg_catalog.set_config(
    'vimob.whatsapp_attendance_capture',
    case when p_suppress_lead_message then 'suppressed' else 'captured' end,
    true
  );

  v_result := public.process_managed_whatsapp_lead_entry(
    p_organization_id,
    p_lead_id,
    p_session_id,
    p_rule_id,
    p_provider_message_id,
    p_message,
    p_occurred_at
  );

  perform pg_catalog.set_config(
    'vimob.whatsapp_attendance_capture',
    coalesce(v_previous_capture_setting, ''),
    true
  );
  return v_result;
exception
  when others then
    perform pg_catalog.set_config(
      'vimob.whatsapp_attendance_capture',
      coalesce(v_previous_capture_setting, ''),
      true
    );
    raise;
end;
$$;


ALTER FUNCTION public.process_managed_whatsapp_lead_entry_attendance(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_rule_id uuid, p_provider_message_id text, p_message text, p_occurred_at timestamp with time zone, p_suppress_lead_message boolean) OWNER TO postgres;

--
-- Name: FUNCTION process_managed_whatsapp_lead_entry_attendance(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_rule_id uuid, p_provider_message_id text, p_message text, p_occurred_at timestamp with time zone, p_suppress_lead_message boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.process_managed_whatsapp_lead_entry_attendance(p_organization_id uuid, p_lead_id uuid, p_session_id uuid, p_rule_id uuid, p_provider_message_id text, p_message text, p_occurred_at timestamp with time zone, p_suppress_lead_message boolean) IS 'Backend-only managed intake wrapper. It retains message fingerprint semantics while suppressing leads.message projection before attendance.';


--
-- Name: process_whatsapp_lead_reentry_from_backend(uuid, uuid, text, uuid, text, text, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_whatsapp_lead_reentry_from_backend(p_organization_id uuid, p_lead_id uuid, p_provider_event_id text, p_conversation_id uuid, p_source text DEFAULT 'whatsapp'::text, p_entry_subtype text DEFAULT 'whatsapp_reentry'::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_lead_meta jsonb DEFAULT NULL::jsonb, p_occurred_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_registration jsonb;
  v_event_id uuid;
  v_event public.lead_entry_events%rowtype;
  v_inserted boolean;
  v_existing_result jsonb;
  v_conversation_lead_id uuid;
  v_existing_meta public.lead_meta%rowtype;
  v_lead_meta_applied boolean := false;
  v_lead_meta_skipped_newer boolean := false;
  v_result jsonb;
begin
  p_occurred_at := coalesce(p_occurred_at, clock_timestamp());
  p_metadata := coalesce(p_metadata, '{}'::jsonb);

  if p_organization_id is null
     or p_lead_id is null
     or nullif(btrim(coalesce(p_provider_event_id, '')), '') is null
     or length(btrim(p_provider_event_id)) > 200 then
    raise exception using
      errcode = '22023',
      message = 'invalid_whatsapp_lead_reentry_request';
  end if;

  -- The provider identity and immutable event are the only facts needed to
  -- acknowledge a completed retry. In particular, do not lock or validate the
  -- lead/conversation first: either may have been legitimately changed or
  -- removed after the original transaction committed.
  select event.*
  into v_event
  from public.lead_entry_events as event
  where event.organization_id = p_organization_id
    and event.provider = 'evolution_whatsapp'
    and event.provider_event_id = btrim(p_provider_event_id)
    and event.is_countable = true;

  if found then
    if v_event.lead_id <> p_lead_id then
      raise exception using
        errcode = '23505',
        message = 'lead_reentry_idempotency_conflict';
    end if;

    v_existing_result := v_event.metadata
      #> '{edge_reentry_processing,result}';

    if v_existing_result is not null then
      return v_existing_result || jsonb_build_object(
        'inserted', false,
        'replayed', true
      );
    end if;
  end if;

  if p_conversation_id is null
     or jsonb_typeof(p_metadata) <> 'object'
     or (
       p_lead_meta is not null
       and jsonb_typeof(p_lead_meta) <> 'object'
     ) then
    raise exception using
      errcode = '22023',
      message = 'invalid_whatsapp_lead_reentry_request';
  end if;

  if p_lead_meta is not null and exists (
    select 1
    from jsonb_object_keys(p_lead_meta) as supplied(key)
    where supplied.key <> all (array[
      'campaign_id',
      'campaign_name',
      'ad_id',
      'ad_name',
      'adset_id',
      'adset_name',
      'platform',
      'source_type',
      'utm_source',
      'utm_medium',
      'utm_campaign',
      'utm_content',
      'utm_term',
      'raw_payload'
    ]::text[])
  ) then
    raise exception using
      errcode = '22023',
      message = 'invalid_whatsapp_lead_meta_projection';
  end if;

  -- This row lock makes a concurrent provider retry wait for the complete
  -- transaction, never for an intermediate registration state.
  perform 1
  from public.leads as lead
  where lead.id = p_lead_id
    and lead.organization_id = p_organization_id
  for no key update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'whatsapp_lead_reentry_target_not_found';
  end if;

  v_registration := public.register_lead_reentry_from_backend(
    p_organization_id,
    p_lead_id,
    'evolution_whatsapp',
    btrim(p_provider_event_id),
    p_source,
    p_entry_subtype,
    null,
    null,
    p_metadata,
    p_occurred_at
  );

  if not coalesce((v_registration->>'success')::boolean, false)
     or nullif(v_registration->>'event_id', '') is null then
    raise exception using
      errcode = 'P0001',
      message = 'whatsapp_lead_reentry_registration_incomplete';
  end if;

  v_event_id := (v_registration->>'event_id')::uuid;
  v_inserted := coalesce((v_registration->>'inserted')::boolean, false);

  select event.*
  into v_event
  from public.lead_entry_events as event
  where event.id = v_event_id
    and event.organization_id = p_organization_id
    and event.lead_id = p_lead_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'whatsapp_lead_reentry_event_not_found';
  end if;

  v_existing_result := v_event.metadata
    #> '{edge_reentry_processing,result}';

  if not v_inserted and v_existing_result is not null then
    -- No writes on a completed replay: the lead, conversation and attribution
    -- may all have legitimately changed after the original delivery.
    return v_existing_result || jsonb_build_object(
      'inserted', false,
      'replayed', true
    );
  end if;

  select conversation.lead_id
  into v_conversation_lead_id
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'whatsapp_lead_reentry_conversation_not_found';
  end if;

  if v_conversation_lead_id is not null
     and v_conversation_lead_id <> p_lead_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_lead_reentry_conversation_conflict';
  end if;

  update public.whatsapp_conversations as conversation
  set lead_id = p_lead_id,
      updated_at = clock_timestamp()
  where conversation.id = p_conversation_id
    and conversation.organization_id = p_organization_id
    and (
      conversation.lead_id is null
      or conversation.lead_id = p_lead_id
    );

  if not found then
    raise exception using
      errcode = '40001',
      message = 'whatsapp_lead_reentry_conversation_changed';
  end if;

  if p_lead_meta is not null and p_lead_meta <> '{}'::jsonb then
    select meta.*
    into v_existing_meta
    from public.lead_meta as meta
    where meta.lead_id = p_lead_id
    for update;

    if found
       and not v_inserted
       and v_existing_meta.updated_at > v_event.created_at then
      -- Recovery of a legacy half-processed event must not replace attribution
      -- written after that event was accepted.
      v_lead_meta_skipped_newer := true;
    elsif found then
      update public.lead_meta as meta
      set campaign_id = case
            when p_lead_meta ? 'campaign_id' then p_lead_meta->>'campaign_id'
            else meta.campaign_id
          end,
          campaign_name = case
            when p_lead_meta ? 'campaign_name' then p_lead_meta->>'campaign_name'
            else meta.campaign_name
          end,
          ad_id = case
            when p_lead_meta ? 'ad_id' then p_lead_meta->>'ad_id'
            else meta.ad_id
          end,
          ad_name = case
            when p_lead_meta ? 'ad_name' then p_lead_meta->>'ad_name'
            else meta.ad_name
          end,
          adset_id = case
            when p_lead_meta ? 'adset_id' then p_lead_meta->>'adset_id'
            else meta.adset_id
          end,
          adset_name = case
            when p_lead_meta ? 'adset_name' then p_lead_meta->>'adset_name'
            else meta.adset_name
          end,
          platform = case
            when p_lead_meta ? 'platform' then p_lead_meta->>'platform'
            else meta.platform
          end,
          source_type = case
            when p_lead_meta ? 'source_type' then p_lead_meta->>'source_type'
            else meta.source_type
          end,
          utm_source = case
            when p_lead_meta ? 'utm_source' then p_lead_meta->>'utm_source'
            else meta.utm_source
          end,
          utm_medium = case
            when p_lead_meta ? 'utm_medium' then p_lead_meta->>'utm_medium'
            else meta.utm_medium
          end,
          utm_campaign = case
            when p_lead_meta ? 'utm_campaign' then p_lead_meta->>'utm_campaign'
            else meta.utm_campaign
          end,
          utm_content = case
            when p_lead_meta ? 'utm_content' then p_lead_meta->>'utm_content'
            else meta.utm_content
          end,
          utm_term = case
            when p_lead_meta ? 'utm_term' then p_lead_meta->>'utm_term'
            else meta.utm_term
          end,
          raw_payload = case
            when p_lead_meta ? 'raw_payload' then p_lead_meta->'raw_payload'
            else meta.raw_payload
          end,
          updated_at = clock_timestamp()
      where meta.lead_id = p_lead_id;

      v_lead_meta_applied := true;
    else
      insert into public.lead_meta (
        lead_id,
        organization_id,
        campaign_id,
        campaign_name,
        ad_id,
        ad_name,
        adset_id,
        adset_name,
        platform,
        source_type,
        utm_source,
        utm_medium,
        utm_campaign,
        utm_content,
        utm_term,
        raw_payload,
        updated_at
      )
      values (
        p_lead_id,
        p_organization_id,
        p_lead_meta->>'campaign_id',
        p_lead_meta->>'campaign_name',
        p_lead_meta->>'ad_id',
        p_lead_meta->>'ad_name',
        p_lead_meta->>'adset_id',
        p_lead_meta->>'adset_name',
        p_lead_meta->>'platform',
        p_lead_meta->>'source_type',
        p_lead_meta->>'utm_source',
        p_lead_meta->>'utm_medium',
        p_lead_meta->>'utm_campaign',
        p_lead_meta->>'utm_content',
        p_lead_meta->>'utm_term',
        p_lead_meta->'raw_payload',
        clock_timestamp()
      );

      v_lead_meta_applied := true;
    end if;
  end if;

  v_result := jsonb_build_object(
    'success', true,
    'lead_id', p_lead_id,
    'event_id', v_event_id,
    'inserted', v_inserted,
    'replayed', not v_inserted,
    'recovered_legacy_event', not v_inserted,
    'conversation_id', p_conversation_id,
    'conversation_linked', true,
    'lead_meta_applied', v_lead_meta_applied,
    'lead_meta_skipped_newer', v_lead_meta_skipped_newer
  );

  update public.lead_entry_events as event
  set metadata = coalesce(event.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'edge_reentry_processing',
      jsonb_build_object(
        'version', 1,
        'status', 'completed',
        'completed_at', clock_timestamp(),
        'result', v_result
      )
    )
  where event.id = v_event_id
    and event.organization_id = p_organization_id
    and event.lead_id = p_lead_id;

  if not found then
    raise exception using
      errcode = '40001',
      message = 'whatsapp_lead_reentry_completion_not_recorded';
  end if;

  return v_result;
end;
$$;


