-- Name: FUNCTION process_whatsapp_lead_reentry_from_backend(p_organization_id uuid, p_lead_id uuid, p_provider_event_id text, p_conversation_id uuid, p_source text, p_entry_subtype text, p_metadata jsonb, p_lead_meta jsonb, p_occurred_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
