    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid,
    lead_id uuid,
    remote_jid text NOT NULL,
    contact_name text,
    contact_phone text,
    contact_picture text,
    is_group boolean DEFAULT false,
