    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    archived_at timestamp with time zone,
    contact_presence text,
    presence_updated_at timestamp with time zone,
    organization_id uuid,
    last_message_received_at timestamp with time zone,
    assigned_user_id uuid,
    last_message_preview text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    retired_at timestamp with time zone,
    unlinked_retention_v1 boolean DEFAULT false NOT NULL,
    unlinked_retention_scrubbed_at timestamp with time zone
)
WITH (autovacuum_vacuum_scale_factor='0.03', autovacuum_analyze_scale_factor='0.02', autovacuum_vacuum_threshold='500', autovacuum_analyze_threshold='500');


