--
-- Name: rebind_whatsapp_conversation_session(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rebind_whatsapp_conversation_session(p_conversation_id uuid, p_session_id uuid) RETURNS public.whatsapp_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_conversation public.whatsapp_conversations%ROWTYPE;
  v_session public.whatsapp_sessions%ROWTYPE;
  v_can_send boolean := false;
  v_can_access_lead boolean := false;
BEGIN
  SELECT *
  INTO v_conversation
  FROM public.whatsapp_conversations
  WHERE id = p_conversation_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversa WhatsApp não encontrada';
  END IF;

  SELECT *
  INTO v_session
  FROM public.whatsapp_sessions
  WHERE id = p_session_id
    AND status = 'connected';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sessão WhatsApp conectada não encontrada';
  END IF;

  IF v_conversation.organization_id IS NOT NULL
     AND v_session.organization_id IS NOT NULL
     AND v_conversation.organization_id <> v_session.organization_id THEN
    RAISE EXCEPTION 'Conversa e sessão pertencem a organizações diferentes';
  END IF;

  v_can_send :=
    public.is_super_admin()
    OR v_session.owner_user_id = auth.uid()
    OR EXISTS (
      SELECT 1
      FROM public.whatsapp_session_access access
      WHERE access.session_id = v_session.id
        AND access.user_id = auth.uid()
        AND access.can_send = true
    );

  IF NOT v_can_send THEN
    RAISE EXCEPTION 'Usuário sem permissão para enviar por esta sessão';
  END IF;

  IF v_conversation.lead_id IS NOT NULL THEN
    v_can_access_lead := public.can_access_lead(v_conversation.lead_id, auth.uid());
  END IF;

  IF v_conversation.session_id IS NOT NULL
     AND v_conversation.session_id <> p_session_id
     AND NOT v_can_access_lead
     AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Usuário sem permissão para religar esta conversa';
  END IF;

  UPDATE public.whatsapp_conversations
  SET
    session_id = p_session_id,
    organization_id = v_session.organization_id,
    updated_at = now()
  WHERE id = p_conversation_id
  RETURNING * INTO v_conversation;

  RETURN v_conversation;
END;
$$;


ALTER FUNCTION public.rebind_whatsapp_conversation_session(p_conversation_id uuid, p_session_id uuid) OWNER TO postgres;

--
-- Name: rebind_whatsapp_conversation_session(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rebind_whatsapp_conversation_session(p_conversation_id uuid, p_session_id uuid, p_remote_jid text DEFAULT NULL::text) RETURNS public.whatsapp_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_source public.whatsapp_conversations%ROWTYPE;
  v_target public.whatsapp_conversations%ROWTYPE;
  v_session public.whatsapp_sessions%ROWTYPE;
  v_result public.whatsapp_conversations%ROWTYPE;
  v_can_send boolean := false;
  v_can_access_lead boolean := false;
  v_remote_jid text;
  v_phone_digits text;
  v_phone_local text;
  v_phone_without_country text;
  v_phone_without_ninth text;
  v_phone_with_ninth text;
  v_is_group boolean := false;
  v_is_lid boolean := false;
  v_is_newsletter boolean := false;
  v_has_real_phone boolean := false;
  v_matched_lead_id uuid;
BEGIN
  SELECT *
  INTO v_source
  FROM public.whatsapp_conversations
  WHERE id = p_conversation_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WhatsApp conversation not found';
  END IF;

  SELECT *
  INTO v_session
  FROM public.whatsapp_sessions
  WHERE id = p_session_id
    AND status = 'connected';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Connected WhatsApp session not found';
  END IF;

  IF v_source.organization_id IS NOT NULL
     AND v_session.organization_id IS NOT NULL
     AND v_source.organization_id <> v_session.organization_id THEN
    RAISE EXCEPTION 'Conversation and session belong to different organizations';
  END IF;

  v_can_send :=
    public.is_super_admin()
    OR v_session.owner_user_id = auth.uid()
    OR EXISTS (
      SELECT 1
      FROM public.whatsapp_session_access access
      WHERE access.session_id = v_session.id
        AND access.user_id = auth.uid()
        AND access.can_send = true
    );

  IF NOT v_can_send THEN
    RAISE EXCEPTION 'User cannot send through this WhatsApp session';
  END IF;

  IF v_source.lead_id IS NOT NULL THEN
    v_can_access_lead := public.can_access_lead(v_source.lead_id, auth.uid());
  END IF;

  IF v_source.session_id IS NOT NULL
     AND v_source.session_id <> p_session_id
     AND NOT v_can_access_lead
     AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'User cannot rebind this conversation';
  END IF;

  v_remote_jid := COALESCE(NULLIF(p_remote_jid, ''), v_source.remote_jid);
  v_is_group := COALESCE(v_source.is_group, false) OR v_remote_jid LIKE '%@g.us';
  v_is_lid := v_remote_jid LIKE '%@lid';
  v_is_newsletter := v_remote_jid LIKE '%@newsletter';
  v_phone_digits := regexp_replace(COALESCE(v_source.contact_phone, v_remote_jid, ''), '\D', '', 'g');
  v_phone_without_country := CASE
    WHEN v_phone_digits LIKE '55%' AND length(v_phone_digits) >= 12 THEN substring(v_phone_digits from 3)
    ELSE v_phone_digits
  END;
  v_phone_local := v_phone_without_country;
  v_phone_without_ninth := CASE
    WHEN length(v_phone_local) = 11 AND substring(v_phone_local from 3 for 1) = '9'
      THEN substring(v_phone_local from 1 for 2) || substring(v_phone_local from 4)
    ELSE NULL
  END;
  v_phone_with_ninth := CASE
    WHEN length(v_phone_local) = 10
      THEN substring(v_phone_local from 1 for 2) || '9' || substring(v_phone_local from 3)
    ELSE NULL
  END;
  v_has_real_phone := NOT v_is_group
    AND NOT v_is_lid
    AND NOT v_is_newsletter
    AND length(v_phone_digits) BETWEEN 10 AND 13;

  IF NOT v_is_group THEN
    IF v_source.lead_id IS NOT NULL THEN
      v_matched_lead_id := v_source.lead_id;
    ELSIF v_has_real_phone THEN
      SELECT l.id
      INTO v_matched_lead_id
      FROM public.leads l
      WHERE l.organization_id = v_session.organization_id
        AND l.phone IS NOT NULL
        AND (
          regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g') IN (
            v_phone_digits,
            v_phone_without_country,
            '55' || v_phone_without_country,
            COALESCE(v_phone_without_ninth, ''),
            CASE WHEN v_phone_without_ninth IS NOT NULL THEN '55' || v_phone_without_ninth ELSE '' END,
            COALESCE(v_phone_with_ninth, ''),
            CASE WHEN v_phone_with_ninth IS NOT NULL THEN '55' || v_phone_with_ninth ELSE '' END
          )
          OR right(regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g'), 8) = right(v_phone_digits, 8)
        )
      ORDER BY l.updated_at DESC NULLS LAST, l.created_at DESC
      LIMIT 1;
    END IF;
  END IF;

  SELECT c.*
  INTO v_target
  FROM public.whatsapp_conversations c
  WHERE c.organization_id = v_session.organization_id
    AND c.deleted_at IS NULL
    AND c.id <> p_conversation_id
    AND COALESCE(c.is_group, false) = v_is_group
    AND (
      (NOT v_is_group AND v_matched_lead_id IS NOT NULL AND c.lead_id = v_matched_lead_id)
      OR (
        NOT v_is_group
        AND v_has_real_phone
        AND (
          regexp_replace(COALESCE(c.contact_phone, c.remote_jid, ''), '\D', '', 'g') IN (
            v_phone_digits,
            v_phone_without_country,
            '55' || v_phone_without_country,
            COALESCE(v_phone_without_ninth, ''),
            CASE WHEN v_phone_without_ninth IS NOT NULL THEN '55' || v_phone_without_ninth ELSE '' END,
            COALESCE(v_phone_with_ninth, ''),
            CASE WHEN v_phone_with_ninth IS NOT NULL THEN '55' || v_phone_with_ninth ELSE '' END
          )
          OR right(regexp_replace(COALESCE(c.contact_phone, c.remote_jid, ''), '\D', '', 'g'), 8) = right(v_phone_digits, 8)
        )
      )
      OR (
        c.session_id = p_session_id
        AND c.remote_jid = v_remote_jid
      )
    )
  ORDER BY
    CASE WHEN NOT v_is_group AND v_matched_lead_id IS NOT NULL AND c.lead_id = v_matched_lead_id THEN 0 ELSE 1 END,
    CASE WHEN c.session_id = p_session_id THEN 0 ELSE 1 END,
    c.last_message_at DESC NULLS LAST,
    c.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.whatsapp_messages m
    SET conversation_id = v_target.id
    WHERE m.conversation_id = v_source.id
      AND NOT EXISTS (
        SELECT 1
        FROM public.whatsapp_messages existing
        WHERE existing.conversation_id = v_target.id
          AND existing.message_id = m.message_id
          AND existing.message_id IS NOT NULL
      );

    DELETE FROM public.whatsapp_messages m
    WHERE m.conversation_id = v_source.id
      AND EXISTS (
        SELECT 1
        FROM public.whatsapp_messages existing
        WHERE existing.conversation_id = v_target.id
          AND existing.message_id = m.message_id
          AND existing.message_id IS NOT NULL
          AND existing.id <> m.id
      );

    UPDATE public.whatsapp_conversations
    SET
      session_id = NULL,
      deleted_at = now(),
      updated_at = now()
    WHERE id = v_source.id;

    UPDATE public.whatsapp_conversations
    SET
      organization_id = COALESCE(v_target.organization_id, v_session.organization_id),
      session_id = p_session_id,
      lead_id = CASE
        WHEN v_is_group THEN NULL
        ELSE COALESCE(v_target.lead_id, v_source.lead_id, v_matched_lead_id)
      END,
      remote_jid = CASE
        WHEN v_is_group THEN v_remote_jid
        WHEN v_is_lid OR v_is_newsletter THEN v_target.remote_jid
        ELSE COALESCE(NULLIF(v_target.remote_jid, ''), v_remote_jid)
      END,
      contact_name = COALESCE(NULLIF(v_target.contact_name, ''), NULLIF(v_source.contact_name, ''), v_target.contact_name),
      contact_phone = CASE
        WHEN v_is_group THEN NULL
        WHEN v_has_real_phone THEN COALESCE(NULLIF(v_target.contact_phone, ''), v_phone_digits)
        ELSE v_target.contact_phone
      END,
      contact_picture = COALESCE(v_target.contact_picture, v_source.contact_picture),
      last_message = CASE
        WHEN v_target.last_message_at IS NULL THEN v_source.last_message
        WHEN v_source.last_message_at IS NULL THEN v_target.last_message
        WHEN v_source.last_message_at > v_target.last_message_at THEN v_source.last_message
        ELSE v_target.last_message
      END,
      last_message_at = GREATEST(v_target.last_message_at, v_source.last_message_at),
      updated_at = now()
    WHERE id = v_target.id
    RETURNING * INTO v_result;

    RETURN v_result;
  END IF;

  UPDATE public.whatsapp_conversations
  SET
    session_id = p_session_id,
    organization_id = v_session.organization_id,
    remote_jid = v_remote_jid,
    lead_id = CASE
      WHEN v_is_group THEN NULL
      ELSE COALESCE(lead_id, v_matched_lead_id)
    END,
    contact_phone = CASE
      WHEN v_is_group THEN NULL
      WHEN v_has_real_phone THEN COALESCE(NULLIF(contact_phone, ''), v_phone_digits)
      ELSE NULLIF(contact_phone, v_phone_digits)
    END,
    updated_at = now()
  WHERE id = p_conversation_id
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.rebind_whatsapp_conversation_session(p_conversation_id uuid, p_session_id uuid, p_remote_jid text) OWNER TO postgres;

--
-- Name: reconcile_asaas_billing_snapshot(uuid, text, text, text, text, date, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_billing_snapshot(p_organization_id uuid, p_provider_customer_id text DEFAULT NULL::text, p_provider_subscription_id text DEFAULT NULL::text, p_provider_subscription_status text DEFAULT NULL::text, p_latest_payment_status text DEFAULT NULL::text, p_next_billing_date date DEFAULT NULL::date, p_observed_at timestamp with time zone DEFAULT now(), p_source text DEFAULT 'edge_poll'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  return private.apply_asaas_billing_snapshot(
    p_organization_id,
    p_provider_customer_id,
    p_provider_subscription_id,
    p_provider_subscription_status,
    p_latest_payment_status,
    p_next_billing_date,
    p_observed_at,
    p_source
  );
end;
$$;


ALTER FUNCTION public.reconcile_asaas_billing_snapshot(p_organization_id uuid, p_provider_customer_id text, p_provider_subscription_id text, p_provider_subscription_status text, p_latest_payment_status text, p_next_billing_date date, p_observed_at timestamp with time zone, p_source text) OWNER TO postgres;

--
-- Name: reconcile_asaas_checkout_webhook_with_intent(text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_checkout_webhook_with_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_checkout jsonb, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_event_id text := nullif(btrim(coalesce(p_event_id, '')), '');
  v_event_type text := upper(btrim(coalesce(p_event_type, '')));
  v_event_at timestamptz := coalesce(p_event_at, now());
  v_checkout_id text := nullif(btrim(coalesce(p_checkout ->> 'id', '')), '');
  v_intent private.billing_checkout_intents%rowtype;
  v_inserted integer := 0;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  if v_event_id is null
     or char_length(v_event_id) > 512
     or v_checkout_id is null
     or char_length(v_checkout_id) > 255
     or v_event_type not in (
       'CHECKOUT_CREATED',
       'CHECKOUT_CANCELED',
       'CHECKOUT_EXPIRED',
       'CHECKOUT_PAID'
     )
     or p_payload is null
     or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'invalid Asaas checkout webhook'
      using errcode = '22023';
  end if;

  select *
  into v_intent
  from private.billing_checkout_intents
  where provider_checkout_id = v_checkout_id
    or (
      provider_checkout_id is null
      and external_reference = nullif(
        btrim(coalesce(p_checkout ->> 'externalReference', '')),
        ''
      )
    )
  order by created_at desc, id desc
  limit 1
  for update;

  if not found then
    insert into private.asaas_webhook_events (
      event_id,
      event_type,
      resource_type,
      resource_id,
      organization_id,
      provider_event_at,
      outcome,
      payload
    )
    values (
      v_event_id,
      v_event_type,
      'checkout',
      v_checkout_id,
      null,
      v_event_at,
      'unmatched',
      p_payload
    )
    on conflict (event_id) do nothing;

    get diagnostics v_inserted = row_count;

    return jsonb_build_object(
      'outcome', case when v_inserted = 0 then 'duplicate' else 'unmatched' end,
      'event_id', v_event_id,
      'checkout_id', v_checkout_id
    );
  end if;

  insert into private.asaas_webhook_events (
    event_id,
    event_type,
    resource_type,
    resource_id,
    organization_id,
    provider_event_at,
    outcome,
    payload
  )
  values (
    v_event_id,
    v_event_type,
    'checkout',
    v_checkout_id,
    v_intent.organization_id,
    v_event_at,
    'processed',
    p_payload
  )
  on conflict (event_id) do update
  set
    organization_id = excluded.organization_id,
    provider_event_at = excluded.provider_event_at,
    outcome = 'processed',
    payload = excluded.payload,
    processed_at = now()
  where private.asaas_webhook_events.outcome = 'unmatched'
    and private.asaas_webhook_events.event_type = excluded.event_type
    and private.asaas_webhook_events.resource_type = excluded.resource_type
    and private.asaas_webhook_events.resource_id = excluded.resource_id;

  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    return jsonb_build_object(
      'outcome', 'duplicate',
      'event_id', v_event_id,
      'checkout_id', v_checkout_id,
      'intent_id', v_intent.id,
      'organization_id', v_intent.organization_id
    );
  end if;

  update private.billing_checkout_intents
  set
    status = case
      when v_event_type in ('CHECKOUT_CANCELED', 'CHECKOUT_EXPIRED')
        and status in ('creating', 'pending')
        then 'cancelled'
      else status
    end,
    cancelled_at = case
      when v_event_type in ('CHECKOUT_CANCELED', 'CHECKOUT_EXPIRED')
        and status in ('creating', 'pending')
        then coalesce(cancelled_at, v_event_at)
      else cancelled_at
    end,
    provider_checkout_id = coalesce(provider_checkout_id, v_checkout_id),
    provider_response = coalesce(provider_response, '{}'::jsonb)
      || p_checkout
      || jsonb_build_object(
        'checkout', p_checkout,
        'checkout_event', v_event_type,
        'checkout_event_at', v_event_at
      ),
    last_error = case
      when v_event_type = 'CHECKOUT_EXPIRED' then 'hosted_checkout_expired'
      when v_event_type = 'CHECKOUT_CANCELED' then 'hosted_checkout_cancelled'
      else last_error
    end,
    updated_at = now()
  where id = v_intent.id;

  return jsonb_build_object(
    'outcome', 'processed',
    'event_id', v_event_id,
    'checkout_id', v_checkout_id,
    'intent_id', v_intent.id,
    'organization_id', v_intent.organization_id,
    'checkout_status', v_event_type
  );
end;
$$;


ALTER FUNCTION public.reconcile_asaas_checkout_webhook_with_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_checkout jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: reconcile_asaas_payment_method_change(uuid, uuid, uuid, text, text, text, text, numeric, text, text, date, text, text, date, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_payment_method_change(p_payment_id uuid, p_organization_id uuid, p_billing_intent_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_external_reference text, p_payment_amount numeric, p_expected_old_billing_type text, p_expected_old_status text, p_expected_old_due_date date, p_new_billing_type text, p_new_status text, p_new_due_date date, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_provider_customer_id text := nullif(btrim(coalesce(p_provider_customer_id, '')), '');
  v_provider_subscription_id text := nullif(
    btrim(coalesce(p_provider_subscription_id, '')),
    ''
  );
  v_external_reference text := nullif(btrim(coalesce(p_external_reference, '')), '');
  v_old_billing_type text := upper(nullif(
    btrim(coalesce(p_expected_old_billing_type, '')),
    ''
  ));
  v_old_status text := upper(nullif(
    btrim(coalesce(p_expected_old_status, '')),
    ''
  ));
  v_new_billing_type text := upper(nullif(
    btrim(coalesce(p_new_billing_type, '')),
    ''
  ));
  v_new_status text := upper(nullif(btrim(coalesce(p_new_status, '')), ''));
  v_payment public.asaas_payments%rowtype;
  v_org public.organizations%rowtype;
  v_intent private.billing_checkout_intents%rowtype;
  v_reconcile jsonb;
  v_persisted integer := 0;
begin
  if p_payment_id is null
     or p_organization_id is null
     or v_provider_payment_id is null
     or v_provider_customer_id is null
     or char_length(v_provider_payment_id) > 255
     or char_length(v_provider_customer_id) > 255
     or char_length(coalesce(v_provider_subscription_id, '')) > 255
     or char_length(coalesce(v_external_reference, '')) > 160
     or p_payment_amount is null
     or p_payment_amount::text in ('NaN', 'Infinity', '-Infinity')
     or p_payment_amount <= 0
     or p_expected_old_due_date is null
     or p_new_due_date is null
     or p_observed_at is null
     or p_observed_at > now() + interval '5 minutes' then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  if v_old_billing_type not in ('PIX', 'BOLETO', 'CREDIT_CARD')
     or v_new_billing_type not in ('PIX', 'BOLETO', 'CREDIT_CARD')
     or v_old_billing_type = v_new_billing_type
     or not (
       private.billing_payment_checkout_is_actionable(v_old_status)
       or private.billing_payment_checkout_is_processing(v_old_status)
     )
     or not (
       private.billing_payment_checkout_is_actionable(v_new_status)
       or private.billing_payment_checkout_is_processing(v_new_status)
       or v_new_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH')
     ) then
    return jsonb_build_object('outcome', 'unsupported_transition');
  end if;

  -- Use the same global provider lock order as webhook and polling writers.
  perform private.lock_asaas_billing_resources(
    v_provider_payment_id,
    v_provider_subscription_id
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  if v_payment.organization_id is distinct from p_organization_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'organization'
    );
  end if;
  if nullif(btrim(coalesce(v_payment.asaas_customer_id, '')), '')
       is distinct from v_provider_customer_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'customer'
    );
  end if;
  if nullif(btrim(coalesce(v_payment.asaas_subscription_id, '')), '')
       is distinct from v_provider_subscription_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'subscription'
    );
  end if;
  if v_payment.billing_intent_id is distinct from p_billing_intent_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'billing_intent'
    );
  end if;
  if v_payment.value is null
     or abs(v_payment.value - p_payment_amount) > 0.01 then
    return jsonb_build_object(
      'outcome', 'amount_mismatch'
    );
  end if;

  if v_payment.billing_intent_id is not null then
    select intent.*
    into v_intent
    from private.billing_checkout_intents as intent
    where intent.id = v_payment.billing_intent_id
      and intent.organization_id = v_payment.organization_id
    for update;

    if not found
       or v_intent.provider_payment_id is distinct from v_provider_payment_id
       or v_intent.provider_customer_id is distinct from v_provider_customer_id
       or v_intent.external_reference is distinct from v_external_reference
       or abs(v_intent.amount - p_payment_amount) > 0.01 then
      return jsonb_build_object(
        'outcome', 'identifier_mismatch',
        'field', 'billing_intent_snapshot'
      );
    end if;
  elsif p_billing_intent_id is not null or v_external_reference is not null then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'billing_intent_snapshot'
    );
  end if;

  select organization_row.*
  into v_org
  from public.organizations as organization_row
  where organization_row.id = v_payment.organization_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;
  if nullif(btrim(coalesce(v_org.asaas_customer_id, '')), '') is not null
     and nullif(btrim(v_org.asaas_customer_id), '')
       is distinct from v_provider_customer_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'organization_customer'
    );
  end if;
  -- Idempotent success is accepted only when the complete provider snapshot
  -- already matches, never merely because the method happens to match. Check
  -- this before the monotonic cursor so a delayed retry of an applied snapshot
  -- is a harmless success without weakening stale, non-matching transitions.
  if upper(btrim(coalesce(v_payment.billing_type, ''))) = v_new_billing_type
     and upper(btrim(coalesce(v_payment.status, ''))) = v_new_status
     and v_payment.due_date is not distinct from p_new_due_date then
    if v_new_billing_type = 'CREDIT_CARD'
       and private.billing_payment_checkout_is_paid(v_new_status) then
      -- The status transition may have been applied while the old method was
      -- still Pix/boleto. Queue only after the exact method snapshot is known
      -- to be CREDIT_CARD, including recovery of a lost successful response.
      update private.billing_card_recurrence_provisions as provision
      set
        status = case
          when provision.status = 'failed' then 'prepared'
          else provision.status
        end,
        job_action = 'create',
        job_status = 'pending',
        job_attempts = 0,
        job_next_attempt_at = clock_timestamp(),
        job_locked_at = null,
        job_lock_expires_at = null,
        job_locked_by = null,
        job_lease_id = null,
        job_dead_lettered_at = null,
        job_last_error_code = null,
        failed_at = null,
        last_error = null,
        updated_at = clock_timestamp()
      where provision.payment_id = v_payment.id
        and provision.provider_payment_id = v_provider_payment_id
        and provision.organization_id = p_organization_id
        and provision.billing_intent_id is not distinct from p_billing_intent_id
        and provision.provider_subscription_id is null
        and provision.status in ('prepared', 'failed')
        and provision.provider_card_credential is not null;
    end if;

    if v_old_billing_type = 'CREDIT_CARD'
       and v_new_billing_type in ('PIX', 'BOLETO') then
      -- A card credential is scoped to the exact method attempt. Replaying an
      -- already-applied non-card snapshot must also close an abandoned
      -- credential left by a response lost before this migration completed.
      update private.billing_card_recurrence_provisions as provision
      set
        status = 'failed',
        provider_card_credential = null,
        card_last4 = null,
        lease_id = null,
        lease_expires_at = null,
        failed_at = coalesce(provision.failed_at, clock_timestamp()),
        last_error = 'payment_method_changed_non_card',
        job_action = 'create',
        job_status = 'cancelled',
        job_locked_at = null,
        job_lock_expires_at = null,
        job_locked_by = null,
        job_lease_id = null,
        job_dead_lettered_at = null,
        job_last_error_code = 'payment_method_changed_non_card',
        updated_at = clock_timestamp()
      where provision.payment_id = v_payment.id
        and provision.provider_payment_id = v_provider_payment_id
        and provision.organization_id = p_organization_id
        and provision.billing_intent_id is not distinct from p_billing_intent_id
        and provision.provider_subscription_id is null
        and (
          provision.status in ('prepared', 'failed')
          or (
            provision.status = 'creating'
            and provision.provider_request_started_at is null
          )
        );
    end if;

    return jsonb_build_object(
      'outcome', 'already_updated',
      'payment_id', v_payment.id,
      'billing_type', v_new_billing_type
    );
  end if;

  if coalesce(
       greatest(v_payment.last_webhook_event_at, v_payment.last_provider_observed_at),
       '-infinity'::timestamptz
     ) > p_observed_at
     or coalesce(
       greatest(v_org.billing_last_reconciled_at, v_org.asaas_last_event_at),
       '-infinity'::timestamptz
     ) > p_observed_at then
    return jsonb_build_object('outcome', 'stale_snapshot');
  end if;

  if upper(btrim(coalesce(v_payment.billing_type, ''))) <> v_old_billing_type then
    return jsonb_build_object(
      'outcome', 'snapshot_mismatch',
      'field', 'billing_type'
    );
  end if;
  if upper(btrim(coalesce(v_payment.status, ''))) <> v_old_status then
    return jsonb_build_object(
      'outcome', 'snapshot_mismatch',
      'field', 'status'
    );
  end if;
  if v_payment.due_date is distinct from p_expected_old_due_date then
    return jsonb_build_object(
      'outcome', 'snapshot_mismatch',
      'field', 'due_date'
    );
  end if;

  v_reconcile := private.apply_asaas_billing_snapshot_with_payment(
    p_organization_id,
    v_provider_customer_id,
    v_provider_subscription_id,
    null::text,
    v_provider_payment_id,
    v_new_status,
    p_payment_amount,
    p_new_due_date,
    null::date,
    p_observed_at,
    'edge_payment_method_change'
  );

  if coalesce(v_reconcile ->> 'outcome', '') <> 'applied' then
    raise exception 'payment method reconciliation failed: %', v_reconcile
      using errcode = '40001';
  end if;

  update public.asaas_payments as payment
  set
    billing_type = v_new_billing_type,
    raw_event = jsonb_set(
      coalesce(payment.raw_event, '{}'::jsonb),
      '{last_provider_snapshot}',
      coalesce(payment.raw_event -> 'last_provider_snapshot', '{}'::jsonb)
        || jsonb_build_object(
          'billing_type', v_new_billing_type,
          'previous_billing_type', v_old_billing_type
        ),
      true
    ),
    updated_at = now()
  where payment.id = v_payment.id
    and payment.organization_id = p_organization_id
    and payment.asaas_payment_id = v_provider_payment_id
    and payment.asaas_customer_id = v_provider_customer_id
    and nullif(btrim(coalesce(payment.asaas_subscription_id, '')), '')
      is not distinct from v_provider_subscription_id
    and payment.billing_intent_id is not distinct from p_billing_intent_id
    and abs(payment.value - p_payment_amount) <= 0.01
    and upper(btrim(coalesce(payment.status, ''))) = v_new_status
    and payment.due_date is not distinct from p_new_due_date
    and upper(btrim(coalesce(payment.billing_type, ''))) = v_old_billing_type;

  get diagnostics v_persisted = row_count;
  if v_persisted <> 1 then
    raise exception 'payment method snapshot lost its compare-and-set race'
      using errcode = '40001';
  end if;

  if v_new_billing_type = 'CREDIT_CARD'
     and private.billing_payment_checkout_is_paid(v_new_status) then
    -- `apply_asaas_billing_snapshot_with_payment` runs before the billing-type
    -- CAS, so its status trigger correctly refuses to enqueue while the old
    -- method is non-card. Enqueue now that both fields won the exact CAS.
    update private.billing_card_recurrence_provisions as provision
    set
      status = case
        when provision.status = 'failed' then 'prepared'
        else provision.status
      end,
      job_action = 'create',
      job_status = 'pending',
      job_attempts = 0,
      job_next_attempt_at = clock_timestamp(),
      job_locked_at = null,
      job_lock_expires_at = null,
      job_locked_by = null,
      job_lease_id = null,
      job_dead_lettered_at = null,
      job_last_error_code = null,
      failed_at = null,
      last_error = null,
      updated_at = clock_timestamp()
    where provision.payment_id = v_payment.id
      and provision.provider_payment_id = v_provider_payment_id
      and provision.organization_id = p_organization_id
      and provision.billing_intent_id is not distinct from p_billing_intent_id
      and provision.provider_subscription_id is null
      and provision.status in ('prepared', 'failed')
      and provision.provider_card_credential is not null;
  end if;

  if v_old_billing_type = 'CREDIT_CARD'
     and v_new_billing_type in ('PIX', 'BOLETO') then
    -- This runs in the same transaction and under the same exact payment CAS
    -- as the provider snapshot. A token sealed for the abandoned card attempt
    -- can therefore never become a future subscription after Pix/boleto wins.
    update private.billing_card_recurrence_provisions as provision
    set
      status = 'failed',
      provider_card_credential = null,
      card_last4 = null,
      lease_id = null,
      lease_expires_at = null,
      failed_at = coalesce(provision.failed_at, clock_timestamp()),
      last_error = 'payment_method_changed_non_card',
      job_action = 'create',
      job_status = 'cancelled',
      job_locked_at = null,
      job_lock_expires_at = null,
      job_locked_by = null,
      job_lease_id = null,
      job_dead_lettered_at = null,
      job_last_error_code = 'payment_method_changed_non_card',
      updated_at = clock_timestamp()
    where provision.payment_id = v_payment.id
      and provision.provider_payment_id = v_provider_payment_id
      and provision.organization_id = p_organization_id
      and provision.billing_intent_id is not distinct from p_billing_intent_id
      and provision.provider_subscription_id is null
      and (
        provision.status in ('prepared', 'failed')
        or (
          provision.status = 'creating'
          and provision.provider_request_started_at is null
        )
      );
  end if;

  return jsonb_build_object(
    'outcome', 'updated',
    'payment_id', v_payment.id,
    'billing_type', v_new_billing_type,
    'payment_status', v_new_status,
    'payment_due_date', p_new_due_date
  );
end
$$;


ALTER FUNCTION public.reconcile_asaas_payment_method_change(p_payment_id uuid, p_organization_id uuid, p_billing_intent_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_external_reference text, p_payment_amount numeric, p_expected_old_billing_type text, p_expected_old_status text, p_expected_old_due_date date, p_new_billing_type text, p_new_status text, p_new_due_date date, p_observed_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_asaas_payment_method_change(p_payment_id uuid, p_organization_id uuid, p_billing_intent_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_external_reference text, p_payment_amount numeric, p_expected_old_billing_type text, p_expected_old_status text, p_expected_old_due_date date, p_new_billing_type text, p_new_status text, p_new_due_date date, p_observed_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reconcile_asaas_payment_method_change(p_payment_id uuid, p_organization_id uuid, p_billing_intent_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_external_reference text, p_payment_amount numeric, p_expected_old_billing_type text, p_expected_old_status text, p_expected_old_due_date date, p_new_billing_type text, p_new_status text, p_new_due_date date, p_observed_at timestamp with time zone) IS 'Service-only exact compare-and-set for provider payment method changes; accepts paid card results and never trusts tenant, customer, subscription, intent, or amount from the caller.';


--
-- Name: reconcile_asaas_payment_snapshot(uuid, text, text, text, text, numeric, date, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_payment_snapshot(p_organization_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_payment_status text, p_payment_amount numeric, p_payment_due_date date, p_observed_at timestamp with time zone, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_customer_id text := nullif(btrim(coalesce(p_provider_customer_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_provider_subscription_id, '')), '');
  v_status text := upper(nullif(btrim(coalesce(p_payment_status, '')), ''));
  v_source text := lower(nullif(btrim(coalesce(p_source, '')), ''));
  v_payment public.asaas_payments%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_plan public.admin_subscription_plans%rowtype;
  v_plan_change private.billing_plan_changes%rowtype;
  v_expected_amount numeric;
  v_period integer;
  v_cursor timestamptz;
  v_effective_observed_at timestamptz := p_observed_at;
  v_effective_paid_status text;
  v_result jsonb;
  v_new_organization_status text;
  v_refund_denied_reactivates boolean := false;
begin
  if p_organization_id is null
     or v_payment_id is null
     or v_customer_id is null
     or char_length(v_payment_id) > 255
     or char_length(v_customer_id) > 255
     or char_length(coalesce(v_subscription_id, '')) > 255 then
    return jsonb_build_object('outcome', 'invalid_identity');
  end if;

  if v_status is null or v_status not in (
    'CREATED',
    'PENDING',
    'AWAITING_RISK_ANALYSIS',
    'AUTHORIZED',
    'PROCESSING',
    'CONFIRMED',
    'RECEIVED',
    'RECEIVED_IN_CASH',
    'OVERDUE',
    'DUNNING_REQUESTED',
    'DUNNING_RECEIVED',
    'CREDIT_CARD_CAPTURE_REFUSED',
    'CANCELED',
    'CANCELLED',
    'DELETED',
    'BANK_SLIP_CANCELLED',
    'REFUNDED',
    'REFUND_REQUESTED',
    'REFUND_IN_PROGRESS',
    'REFUND_DENIED',
    'PARTIALLY_REFUNDED',
    'RECEIVED_IN_CASH_UNDONE',
    'REPROVED_BY_RISK_ANALYSIS',
    'CHARGEBACK',
    'CHARGEBACK_REQUESTED',
    'CHARGEBACK_DISPUTE',
    'AWAITING_CHARGEBACK_REVERSAL'
  ) then
    return jsonb_build_object('outcome', 'unsupported_status');
  end if;

  if p_payment_amount is null
     or p_payment_amount::text in ('NaN', 'Infinity', '-Infinity')
     or p_payment_amount <= 0
     or p_payment_due_date is null then
    return jsonb_build_object('outcome', 'invalid_payment_snapshot');
  end if;

  if p_observed_at is null or p_observed_at > now() + interval '5 minutes' then
    return jsonb_build_object('outcome', 'invalid_observed_at');
  end if;

  if v_source is null
     or char_length(v_source) > 80
     or v_source !~ '^[a-z0-9][a-z0-9_:-]*$' then
    return jsonb_build_object('outcome', 'invalid_source');
  end if;

  -- Match webhook/provider reconciliation ordering: advisory provider locks
  -- always precede the payment row lock. The nested apply helper reacquires
  -- these transaction-scoped locks safely and cannot invert the order.
  perform private.lock_asaas_billing_resources(
    v_payment_id,
    v_subscription_id
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.asaas_payment_id = v_payment_id
  for update;

  if not found then
    -- Polling can discover a recurring invoice whose webhook was lost. Bootstrap
    -- only an exact, already-linked org/customer/subscription/plan/period tuple;
    -- no customer-only or fuzzy tenant resolution is allowed.
    if v_subscription_id is null then
      return jsonb_build_object('outcome', 'payment_not_found');
    end if;

    select organization_row.*
    into v_org
    from public.organizations as organization_row
    where organization_row.id = p_organization_id
      and nullif(btrim(coalesce(organization_row.asaas_customer_id, '')), '')
        = v_customer_id
      and nullif(btrim(coalesce(organization_row.asaas_subscription_id, '')), '')
        = v_subscription_id
    for update;

    if not found then
      return jsonb_build_object(
        'outcome', 'identifier_mismatch',
        'field', 'recurring_organization'
      );
    end if;
    select subscription.*
    into v_subscription
    from public.subscriptions as subscription
    where subscription.organization_id = p_organization_id
      and lower(btrim(coalesce(subscription.provider, ''))) = 'asaas'
      and subscription.provider_customer_id = v_customer_id
      and subscription.provider_subscription_id = v_subscription_id
      and lower(btrim(coalesce(subscription.status, ''))) not in (
        'cancelled', 'canceled', 'inactive', 'expired'
      )
    for update;

    if not found
       or v_subscription.plan_id is null
       or v_org.plan_id is distinct from v_subscription.plan_id then
      return jsonb_build_object(
        'outcome', 'identifier_mismatch',
        'field', 'recurring_subscription'
      );
    end if;

    -- A provider-updating/scheduled plan change is an immutable commercial
    -- commitment even if the catalog target was hidden afterwards. Match it
    -- only by the exact organization+subscription+amount+period boundary;
    -- an earlier invoice at the current-plan amount keeps the current plan.
    select plan_change.*
    into v_plan_change
    from private.billing_plan_changes as plan_change
    where plan_change.organization_id = p_organization_id
      and plan_change.provider_subscription_id = v_subscription_id
      and plan_change.status in ('provider_updating', 'scheduled', 'applying')
      and plan_change.from_plan_id = v_org.plan_id
      and plan_change.amount = p_payment_amount
      and (
        plan_change.effective_on is null
        or p_payment_due_date >= plan_change.effective_on
      )
    order by plan_change.created_at desc, plan_change.id desc
    limit 1
    for update;

    if found then
      v_period := v_plan_change.billing_period_months;
      v_expected_amount := v_plan_change.amount;
      select plan.*
      into v_plan
      from public.admin_subscription_plans as plan
      where plan.id = v_plan_change.target_plan_id
      for share;
    else
      v_period := coalesce(
        v_subscription.billing_period_months,
        v_org.subscription_billing_period_months
      );
      if v_period not in (1, 6, 12) then
        return jsonb_build_object('outcome', 'invalid_billing_period');
      end if;

      select plan.*
      into v_plan
      from public.admin_subscription_plans as plan
      where plan.id = v_subscription.plan_id
        and plan.is_active
      for share;
      if found then
        v_expected_amount := round(v_plan.price * v_period, 2);
      end if;
    end if;

    if v_plan.id is null then
      return jsonb_build_object('outcome', 'plan_not_found');
    end if;
    if v_expected_amount is distinct from p_payment_amount then
      return jsonb_build_object('outcome', 'amount_mismatch');
    end if;

    insert into public.asaas_payments (
      organization_id,
      asaas_payment_id,
      asaas_customer_id,
      asaas_subscription_id,
      status,
      value,
      due_date,
      raw_event
    ) values (
      p_organization_id,
      v_payment_id,
      v_customer_id,
      v_subscription_id,
      'PENDING',
      p_payment_amount,
      p_payment_due_date,
      jsonb_build_object(
        'vimob_recurring_invoice_bootstrap', jsonb_build_object(
          'source', v_source,
          'observed_at', p_observed_at,
          'plan_id', v_plan.id,
          'billing_period_months', v_period,
          'billing_plan_change_id', v_plan_change.id
        )
      )
    )
    on conflict (asaas_payment_id) do nothing
    returning * into v_payment;

    if not found then
      select payment.*
      into v_payment
      from public.asaas_payments as payment
      where payment.asaas_payment_id = v_payment_id
      for update;
    end if;

    if not found then
      return jsonb_build_object('outcome', 'bootstrap_race_lost');
    end if;
  end if;

  if v_payment.organization_id is distinct from p_organization_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'organization'
    );
  end if;

  if v_payment.asaas_customer_id is not null
     and btrim(v_payment.asaas_customer_id) <> v_customer_id then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'customer'
    );
  end if;

  if v_payment.asaas_subscription_id is not null
     and (
       v_subscription_id is null
       or btrim(v_payment.asaas_subscription_id) <> v_subscription_id
     ) then
    return jsonb_build_object(
      'outcome', 'identifier_mismatch',
      'field', 'subscription'
    );
  end if;

  if v_payment.billing_intent_id is not null then
    select intent.amount
    into v_expected_amount
    from private.billing_checkout_intents as intent
    where intent.id = v_payment.billing_intent_id
      and intent.organization_id = p_organization_id;

    if not found or abs(v_expected_amount - p_payment_amount) > 0.01 then
      return jsonb_build_object('outcome', 'amount_mismatch');
    end if;
  end if;

  select organization_row.*
  into v_org
  from public.organizations as organization_row
  where organization_row.id = p_organization_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;

  v_cursor := greatest(
    v_payment.last_webhook_received_at,
    v_payment.last_webhook_event_at,
    v_payment.last_provider_observed_at,
    v_org.billing_last_reconciled_at,
    v_org.asaas_last_event_received_at,
    v_org.asaas_last_event_at
  );
  if v_cursor > p_observed_at
     or (
       v_cursor = p_observed_at
       and private.asaas_payment_status_precedence(v_status)
         <= private.asaas_payment_status_precedence(v_payment.status)
     ) then
    return jsonb_build_object(
      'outcome', 'stale_snapshot',
      'payment_status', upper(btrim(coalesce(v_payment.status, '')))
    );
  elsif v_cursor = p_observed_at then
    v_effective_observed_at := least(v_cursor, now());
  end if;

  if v_status = 'REFUND_DENIED' then
    v_effective_paid_status := case
      when private.billing_payment_checkout_is_paid(v_payment.status)
        and upper(btrim(v_payment.status)) <> 'REFUND_DENIED'
      then upper(btrim(v_payment.status))
      when upper(coalesce(
        v_payment.raw_event #>> '{vimob_ordering,effective_paid_status_before_adverse}',
        ''
      )) in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH')
      then upper(v_payment.raw_event #>> '{vimob_ordering,effective_paid_status_before_adverse}')
      else null
    end;

    if v_effective_paid_status is null then
      select case event.event_type
        when 'PAYMENT_RECEIVED' then 'RECEIVED'
        when 'PAYMENT_RECEIVED_IN_CASH' then 'RECEIVED_IN_CASH'
        else 'CONFIRMED'
      end
      into v_effective_paid_status
      from private.asaas_webhook_events as event
      where event.resource_type = 'payment'
        and event.resource_id = v_payment_id
        and event.event_type in (
          'PAYMENT_CONFIRMED',
          'PAYMENT_RECEIVED',
          'PAYMENT_RECEIVED_IN_CASH'
        )
        and event.outcome = 'processed'
      order by event.provider_event_at desc, event.received_at desc
      limit 1;
    end if;

    if v_effective_paid_status is null
       and (
         v_payment.payment_date is not null
         or exists (
           select 1
           from private.billing_checkout_intents as intent
           where intent.id = v_payment.billing_intent_id
             and intent.organization_id = v_payment.organization_id
             and intent.status = 'confirmed'
         )
       ) then
      v_effective_paid_status := 'CONFIRMED';
    end if;

    v_effective_paid_status := coalesce(v_effective_paid_status, 'REFUND_DENIED');

    update public.asaas_payments as payment
    set
      status = v_effective_paid_status,
      raw_event = jsonb_set(
        coalesce(payment.raw_event, '{}'::jsonb),
        '{vimob_refund_denied}',
        jsonb_build_object(
          'provider_status', 'REFUND_DENIED',
          'source', v_source,
          'observed_at', p_observed_at,
          'effective_status', v_effective_paid_status
        ),
        true
      ),
      last_provider_observed_at = greatest(
        payment.last_provider_observed_at,
        p_observed_at
      ),
      updated_at = now()
    where payment.id = v_payment.id;

    -- A refund request may have queued cancellation before Asaas denied it.
    -- Cancel only jobs whose provider DELETE has not started (pending/retry);
    -- an in-flight cancellation is surfaced for assisted repair.
    update private.billing_card_recurrence_provisions as provision
    set
      job_action = 'create',
      job_status = 'succeeded',
      job_locked_at = null,
      job_lock_expires_at = null,
      job_locked_by = null,
      job_lease_id = null,
      job_last_error_code = null,
      updated_at = now()
    where provision.payment_id = v_payment.id
      and provision.status = 'completed'
      and provision.job_action = 'cancel'
      and provision.job_status in ('pending', 'retry');

    v_new_organization_status := private.reconcile_billing_payment_access_proof(
      v_org.id,
      v_payment_id,
      v_org.subscription_status,
      'REFUND_DENIED'
    );
    v_refund_denied_reactivates :=
      v_new_organization_status = 'active'
      and lower(btrim(coalesce(v_org.subscription_status, ''))) not in (
        'active', 'trial'
      );

    if lower(btrim(coalesce(v_org.subscription_status, ''))) not in (
      'cancelled', 'canceled'
    ) then
      update public.organizations
      set subscription_status = v_new_organization_status, updated_at = now()
      where id = v_org.id
        and lower(btrim(coalesce(subscription_status, ''))) not in (
          'cancelled', 'canceled'
        );
      update public.subscriptions
      set status = v_new_organization_status, updated_at = now()
      where organization_id = v_org.id
        and provider_subscription_id is not distinct from v_subscription_id
        and lower(btrim(coalesce(status, ''))) not in ('cancelled', 'canceled');

    end if;

    insert into public.subscription_logs (
      organization_id, event_type, status, metadata
    ) values (
      v_org.id,
      'asaas_refund_denied_observed',
      coalesce(v_effective_paid_status, v_payment.status),
      jsonb_build_object(
        'provider_payment_id', v_payment_id,
        'source', v_source,
        'observed_at', p_observed_at,
        'effective_status_preserved', true,
        'access_reactivated', v_refund_denied_reactivates,
        'access_status', v_new_organization_status
      )
    );

    return jsonb_build_object(
      'outcome', 'applied',
      'payment_id', v_payment_id,
      'provider_status', 'REFUND_DENIED',
      'payment_status', v_effective_paid_status,
      'effective_status_preserved', true,
      'access_reactivated', v_refund_denied_reactivates,
      'subscription_status', v_new_organization_status
    );
  end if;

  v_result := private.apply_asaas_billing_snapshot_with_payment(
    p_organization_id,
    v_customer_id,
    v_subscription_id,
    null::text,
    v_payment_id,
    v_status,
    p_payment_amount,
    p_payment_due_date,
    null::date,
    v_effective_observed_at,
    v_source
  );

  if coalesce(v_result ->> 'outcome', '') = 'applied' then
    update public.asaas_payments as payment
    set raw_event = jsonb_set(
      coalesce(payment.raw_event, '{}'::jsonb),
      '{vimob_ordering}',
      coalesce(payment.raw_event -> 'vimob_ordering', '{}'::jsonb)
        || jsonb_build_object(
          'provider_observed_at', p_observed_at,
          'ordering_observed_at', v_effective_observed_at,
          'source', v_source,
          'effective_paid_status_before_adverse', case
            when private.billing_payment_checkout_is_paid(v_payment.status)
              and private.asaas_payment_status_precedence(v_status) >= 450
            then upper(btrim(v_payment.status))
            else payment.raw_event #>> '{vimob_ordering,effective_paid_status_before_adverse}'
          end
        ),
      true
    )
    where payment.id = v_payment.id;
  end if;

  return v_result;
end
$_$;


ALTER FUNCTION public.reconcile_asaas_payment_snapshot(p_organization_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_payment_status text, p_payment_amount numeric, p_payment_due_date date, p_observed_at timestamp with time zone, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_asaas_payment_snapshot(p_organization_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_payment_status text, p_payment_amount numeric, p_payment_due_date date, p_observed_at timestamp with time zone, p_source text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reconcile_asaas_payment_snapshot(p_organization_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_payment_status text, p_payment_amount numeric, p_payment_due_date date, p_observed_at timestamp with time zone, p_source text) IS 'Service-only exact-payment polling reconciler; payment due_date is persisted and next_billing_date is never inferred.';


--
-- Name: reconcile_asaas_payment_webhook(text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_payment_webhook(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_event_id text := btrim(coalesce(p_event_id, ''));
  v_event_type text := upper(btrim(coalesce(p_event_type, '')));
  v_payment_id text := btrim(coalesce(p_payment ->> 'id', ''));
  v_customer_id text := nullif(btrim(coalesce(p_payment ->> 'customer', '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_payment ->> 'subscription', '')), '');
  v_external_reference text := nullif(
    btrim(coalesce(p_payment ->> 'externalReference', '')),
    ''
  );
  v_status text := private.asaas_payment_status_from_event(
    p_event_type,
    p_payment ->> 'status'
  );
  v_event_at timestamptz := coalesce(
    private.correct_asaas_naive_event_timestamp(p_payload),
    p_event_at,
    clock_timestamp()
  );
  v_received_at timestamptz := clock_timestamp();
  v_payment public.asaas_payments%rowtype;
  v_prior_payment_status text;
  v_prior_org_status text;
  v_organization_id uuid;
  v_cursor timestamptz;
  v_is_stale boolean := false;
  v_inserted integer := 0;
  v_effective_paid_status text;
  v_new_org_status text;
  v_result jsonb;
  v_refund_denied_reactivates boolean := false;
  v_payment_applied boolean := false;
  v_override_suspended_stale boolean := false;
begin
  if char_length(v_event_id) not between 1 and 512 then
    raise exception 'Invalid Asaas webhook event id'
      using errcode = '22023';
  end if;
  if left(v_event_type, 8) <> 'PAYMENT_' then
    raise exception 'Unsupported Asaas webhook event type'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_payment) is distinct from 'object'
     or char_length(v_payment_id) not between 1 and 255 then
    raise exception 'Invalid Asaas webhook payment payload'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_payload) is distinct from 'object'
     or v_status is null then
    raise exception 'Invalid Asaas payment webhook'
      using errcode = '22023';
  end if;

  -- Every webhook/poller writer takes the same provider-key lock before a row
  -- lock. This serializes equal-second deliveries without a global bottleneck.
  perform private.lock_asaas_billing_resources(v_payment_id, v_subscription_id);

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.asaas_payment_id = v_payment_id
  for update;

  if found then
    if v_customer_id is not null
       and v_payment.asaas_customer_id is not null
       and v_customer_id <> v_payment.asaas_customer_id then
      raise exception 'Asaas customer does not match the existing payment'
        using errcode = '22023';
    end if;
    if v_subscription_id is not null
       and v_payment.asaas_subscription_id is not null
       and v_subscription_id <> v_payment.asaas_subscription_id then
      raise exception 'Asaas subscription does not match the existing payment'
        using errcode = '22023';
    end if;

    v_organization_id := v_payment.organization_id;
    v_prior_payment_status := upper(btrim(coalesce(v_payment.status, '')));
    v_cursor := greatest(
      v_payment.last_webhook_event_at,
      v_payment.last_provider_observed_at
    );

    -- Provider chronology remains authoritative. For the only ambiguous case
    -- (the same second), a strictly stronger semantic state wins and equal or
    -- weaker delivery is a harmless no-op.
    v_is_stale := v_cursor is not null and (
      v_event_at < v_cursor
      or (
        v_event_at = v_cursor
        and private.asaas_payment_status_precedence(v_status)
          <= private.asaas_payment_status_precedence(v_prior_payment_status)
      )
    );
  end if;

  if v_organization_id is null
     and v_external_reference ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    select organization_row.id
    into v_organization_id
    from public.organizations as organization_row
    where organization_row.id = v_external_reference::uuid
      and (
        organization_row.asaas_customer_id is null
        or v_customer_id is null
        or organization_row.asaas_customer_id = v_customer_id
      )
      and (
        organization_row.asaas_subscription_id is null
        or v_subscription_id is null
        or organization_row.asaas_subscription_id = v_subscription_id
      );
  end if;

  if v_organization_id is null and v_subscription_id is not null then
    select case when count(*) = 1 then min(id::text)::uuid end
    into v_organization_id
    from public.organizations
    where asaas_subscription_id = v_subscription_id;
  end if;

  if v_organization_id is null
     and v_subscription_id is null
     and v_customer_id is not null then
    select case when count(*) = 1 then min(id::text)::uuid end
    into v_organization_id
    from public.organizations
    where asaas_customer_id = v_customer_id;
  end if;

  -- Inbound provider evidence must still reconcile for an inactive tenant:
  -- PAID/refund/cancellation can materially change which remote deletion is
  -- safe. Hold the tenant row while the exact provider advisory keys are held
  -- so cleanup observes either the complete state before this event or the
  -- complete state after it. Outbound provider markers are fenced separately.
  if v_organization_id is not null then
    perform organization_row.id
    from public.organizations as organization_row
    where organization_row.id = v_organization_id
    for update;
  end if;

  if v_is_stale then
    insert into private.asaas_webhook_events (
      event_id, event_type, resource_type, resource_id, organization_id,
      provider_event_at, outcome, payload
    ) values (
      v_event_id, v_event_type, 'payment', v_payment_id, v_organization_id,
      v_event_at, 'stale', p_payload
    )
    on conflict (event_id) do nothing;
    get diagnostics v_inserted = row_count;
    return jsonb_build_object(
      'outcome', case when v_inserted = 0 then 'duplicate' else 'stale' end,
      'event_id', v_event_id,
      'payment_id', v_payment_id,
      'payment_status', v_prior_payment_status,
      'organization_id', v_organization_id,
      'subscription_status', (
        select organization_row.subscription_status
        from public.organizations as organization_row
        where organization_row.id = v_organization_id
      )
    );
  end if;

  -- REFUND_DENIED is an observation about a failed refund, not a payment
  -- reversal. Preserve the last proven paid state and access. If the paid
  -- event itself was missed, REFUND_DENIED is provider proof that funds had
  -- settled and is therefore a valid paid fallback.
  if v_status = 'REFUND_DENIED' and v_payment.id is not null then
    insert into private.asaas_webhook_events (
      event_id, event_type, resource_type, resource_id, organization_id,
      provider_event_at, outcome, payload
    ) values (
      v_event_id, v_event_type, 'payment', v_payment_id, v_organization_id,
      v_event_at, 'processed', p_payload
    )
    on conflict (event_id) do nothing;
    get diagnostics v_inserted = row_count;
    if v_inserted = 0 then
      return jsonb_build_object(
        'outcome', 'duplicate',
        'event_id', v_event_id,
        'payment_id', v_payment_id,
        'organization_id', v_organization_id
      );
    end if;

    if private.billing_payment_checkout_is_paid(v_prior_payment_status)
       and v_prior_payment_status <> 'REFUND_DENIED' then
      v_effective_paid_status := v_prior_payment_status;
    elsif upper(coalesce(
      v_payment.raw_event #>> '{vimob_ordering,effective_paid_status_before_adverse}',
      ''
    )) in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH') then
      v_effective_paid_status := upper(
        v_payment.raw_event #>> '{vimob_ordering,effective_paid_status_before_adverse}'
      );
    elsif v_payment.payment_date is not null then
      v_effective_paid_status := 'CONFIRMED';
    else
      select case event.event_type
        when 'PAYMENT_RECEIVED' then 'RECEIVED'
        when 'PAYMENT_RECEIVED_IN_CASH' then 'RECEIVED_IN_CASH'
        else 'CONFIRMED'
      end
      into v_effective_paid_status
      from private.asaas_webhook_events as event
      where event.resource_type = 'payment'
        and event.resource_id = v_payment_id
        and event.event_type in (
          'PAYMENT_CONFIRMED', 'PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH'
        )
        and event.outcome = 'processed'
      order by event.provider_event_at desc, event.received_at desc
      limit 1;
    end if;

    v_effective_paid_status := coalesce(v_effective_paid_status, 'REFUND_DENIED');

    update public.asaas_payments as payment
    set
      status = v_effective_paid_status,
      raw_event = jsonb_set(
        coalesce(payment.raw_event, '{}'::jsonb),
        '{vimob_refund_denied}',
        jsonb_build_object(
          'provider_status', 'REFUND_DENIED',
          'event_id', v_event_id,
          'observed_at', v_event_at,
          'effective_status', v_effective_paid_status
        ),
        true
      ),
      last_webhook_event_id = v_event_id,
      last_webhook_event_at = greatest(payment.last_webhook_event_at, v_event_at),
      last_webhook_received_at = v_received_at,
      updated_at = now()
    where payment.id = v_payment.id;

    select organization_row.subscription_status
    into v_prior_org_status
    from public.organizations as organization_row
    where organization_row.id = v_organization_id
    for update;

    v_new_org_status := private.reconcile_billing_payment_access_proof(
      v_organization_id,
      v_payment_id,
      v_prior_org_status,
      'REFUND_DENIED'
    );
    v_refund_denied_reactivates :=
      v_new_org_status = 'active'
      and lower(btrim(coalesce(v_prior_org_status, ''))) not in ('active', 'trial');

    if lower(btrim(coalesce(v_prior_org_status, ''))) not in (
         'cancelled', 'canceled'
       ) then
      update public.organizations
      set
        subscription_status = v_new_org_status,
        asaas_last_event_id = case
          when v_refund_denied_reactivates
            or lower(btrim(coalesce(v_prior_org_status, ''))) in ('active', 'trial')
          then v_event_id
          else asaas_last_event_id
        end,
        asaas_last_event_at = case
          when v_refund_denied_reactivates
            or lower(btrim(coalesce(v_prior_org_status, ''))) in ('active', 'trial')
          then greatest(asaas_last_event_at, v_event_at)
          else asaas_last_event_at
        end,
        asaas_last_event_received_at = case
          when v_refund_denied_reactivates
            or lower(btrim(coalesce(v_prior_org_status, ''))) in ('active', 'trial')
          then v_received_at
          else asaas_last_event_received_at
        end,
        updated_at = now()
      where id = v_organization_id;
      update public.subscriptions
      set status = v_new_org_status, updated_at = now()
      where organization_id = v_organization_id
        and provider_subscription_id is not distinct from v_subscription_id
        and lower(btrim(coalesce(status, ''))) not in ('cancelled', 'canceled');

      if lower(btrim(coalesce(v_prior_org_status, ''))) in (
           'pending_payment', 'overdue', 'past_due', 'blocked', 'suspended'
         )
         and not v_refund_denied_reactivates then
        insert into public.error_events (
          organization_id,
          source,
          severity,
          fingerprint,
          message,
          category,
          error_code,
          component,
          metadata,
          occurred_at
        )
        select
          v_organization_id,
          'backend',
          'warning',
          'billing_refund_denied_conflict:' || v_organization_id::text || ':'
            || v_payment_id || ':' || v_event_id,
          'Refund denial preserved an unrelated billing restriction',
          'billing_reconciliation',
          'refund_denied_unrelated_suspension',
          'asaas_webhook_reconciliation',
          jsonb_build_object(
            'denied_refund_payment_id', v_payment_id,
            'remaining_causes', coalesce((
              select jsonb_agg(
                jsonb_build_object(
                  'provider_payment_id', cause.provider_payment_id,
                  'payment_status', cause.payment_status
                )
                order by cause.observed_at, cause.provider_payment_id
              )
              from private.billing_organization_access_causes as cause
              where cause.organization_id = v_organization_id
            ), '[]'::jsonb),
            'event_id', v_event_id
          ),
          v_received_at
        where not exists (
          select 1
          from public.error_events as existing
          where existing.fingerprint =
            'billing_refund_denied_conflict:' || v_organization_id::text || ':'
              || v_payment_id || ':' || v_event_id
        );
      end if;

      -- A denied refund only cancels a not-yet-started recurrence cancellation
      -- for this exact payment. An unrelated tenant suspension is untouched.
      update private.billing_card_recurrence_provisions as provision
      set
        job_action = 'create',
        job_status = 'succeeded',
        job_locked_at = null,
        job_lock_expires_at = null,
        job_locked_by = null,
        job_lease_id = null,
        job_last_error_code = null,
        updated_at = now()
      where provision.payment_id = v_payment.id
        and provision.status = 'completed'
        and provision.job_action = 'cancel'
        and provision.job_status in ('pending', 'retry');
    end if;

    return jsonb_build_object(
      'outcome', 'processed',
      'event_id', v_event_id,
      'payment_id', v_payment_id,
      'payment_status', v_effective_paid_status,
      'organization_id', v_organization_id,
      'subscription_status', v_new_org_status,
      'access_reactivated', v_refund_denied_reactivates
    );
  end if;

  if v_organization_id is not null then
    select organization_row.subscription_status
    into v_prior_org_status
    from public.organizations as organization_row
    where organization_row.id = v_organization_id;
  end if;

  v_result := private.reconcile_asaas_payment_webhook_unordered_legacy(
    v_event_id,
    v_event_type,
    v_event_at,
    p_payment || jsonb_build_object('status', v_status),
    p_payload
  );

  if coalesce(v_result ->> 'organization_id', '') ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    v_organization_id := (v_result ->> 'organization_id')::uuid;

    if v_prior_org_status is null then
      select organization_row.subscription_status
      into v_prior_org_status
      from public.organizations as organization_row
      where organization_row.id = v_organization_id;
    end if;

    select exists (
      select 1
      from public.asaas_payments as payment
      where payment.asaas_payment_id = v_payment_id
        and payment.organization_id = v_organization_id
        and payment.last_webhook_event_id = v_event_id
        and payment.last_webhook_event_at = v_event_at
    ) into v_payment_applied;

    -- The legacy implementation intentionally froze every already-suspended
    -- tenant. Still reconcile each accepted payment into the private set of
    -- open restrictions: paid proof resolves only its own cause, while a new
    -- adverse observation adds a cause without loosening suspended access.
    v_override_suspended_stale :=
      coalesce(v_result ->> 'outcome', '') = 'stale'
      and v_payment_applied
      and lower(btrim(coalesce(v_prior_org_status, ''))) = 'suspended'
      and (
        private.billing_payment_checkout_is_paid(v_status)
        or private.billing_payment_checkout_is_reversal(v_status)
        or v_status in (
          'CREATED', 'PENDING', 'AWAITING_RISK_ANALYSIS', 'AUTHORIZED',
          'PROCESSING', 'OVERDUE', 'DUNNING_REQUESTED', 'DUNNING_RECEIVED',
          'BANK_SLIP_CANCELLED', 'CREDIT_CARD_CAPTURE_REFUSED',
          'REPROVED_BY_RISK_ANALYSIS'
        )
      );

    if coalesce(v_result ->> 'outcome', '') = 'processed'
       or v_override_suspended_stale then
    v_new_org_status := private.asaas_organization_status_from_payment(
      v_prior_org_status,
      v_status
    );

    if private.billing_payment_checkout_is_paid(v_status) then
      v_new_org_status := private.reconcile_billing_payment_access_proof(
        v_organization_id,
        v_payment_id,
        v_prior_org_status,
        v_status
      );
    elsif v_override_suspended_stale then
      v_new_org_status := 'suspended';
    end if;

    update public.organizations
    set
      subscription_status = v_new_org_status,
      asaas_last_event_id = v_event_id,
      asaas_last_event_at = greatest(asaas_last_event_at, v_event_at),
      asaas_last_event_received_at = v_received_at,
      updated_at = now()
    where id = v_organization_id;

    update public.subscriptions
    set
      status = case
        when lower(btrim(coalesce(status, ''))) in ('cancelled', 'canceled')
          then status
        else v_new_org_status
      end,
      updated_at = now()
    where organization_id = v_organization_id
      and (
        v_subscription_id is null
        or provider_subscription_id is null
        or provider_subscription_id = v_subscription_id
      );

    if lower(btrim(coalesce(v_new_org_status, ''))) in (
         'pending_payment', 'overdue', 'past_due', 'blocked', 'suspended'
       )
       and not private.billing_payment_checkout_is_paid(v_status) then
      insert into private.billing_organization_access_causes (
        organization_id,
        provider_payment_id,
        payment_status,
        observed_at,
        source
      ) values (
        v_organization_id,
        v_payment_id,
        v_status,
        v_event_at,
        'webhook'
      )
      on conflict (organization_id, provider_payment_id) do update
      set
        payment_status = excluded.payment_status,
        observed_at = excluded.observed_at,
        source = excluded.source,
        updated_at = now()
      where excluded.observed_at > private.billing_organization_access_causes.observed_at
         or (
           excluded.observed_at = private.billing_organization_access_causes.observed_at
           and private.asaas_payment_status_precedence(excluded.payment_status)
             > private.asaas_payment_status_precedence(
               private.billing_organization_access_causes.payment_status
             )
         );
    end if;

    update public.asaas_payments
    set last_webhook_received_at = v_received_at
    where asaas_payment_id = v_payment_id;

    if v_override_suspended_stale then
      update private.asaas_webhook_events
      set outcome = 'processed'
      where event_id = v_event_id;
    end if;

    v_result := v_result || jsonb_build_object(
      'outcome', 'processed',
      'payment_status', v_status,
      'subscription_status', v_new_org_status
    );
    end if;
  end if;

  return v_result;
end
$_$;


ALTER FUNCTION public.reconcile_asaas_payment_webhook(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_asaas_payment_webhook(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reconcile_asaas_payment_webhook(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) IS 'Service-only ordered Asaas payment webhook. Exact provider locks plus semantic precedence make adverse equal-second delivery monotonic; REFUND_DENIED preserves settled access.';


--
-- Name: reconcile_asaas_payment_webhook_with_intent(text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_payment_webhook_with_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment jsonb := p_payment;
  v_organization_id uuid;
  v_intent_id uuid;
  v_result jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  perform private.lock_asaas_billing_resources(
    p_payment ->> 'id',
    p_payment ->> 'subscription'
  );

  select intent.id, intent.organization_id
  into v_intent_id, v_organization_id
  from private.billing_checkout_intents intent
  where (
      intent.external_reference = nullif(
        btrim(coalesce(p_payment ->> 'externalReference', '')),
        ''
      )
      or intent.provider_checkout_id = nullif(
        btrim(coalesce(p_payment ->> 'checkoutSession', '')),
        ''
      )
    )
    and (
      intent.provider_customer_id is null
      or nullif(btrim(coalesce(p_payment ->> 'customer', '')), '') is null
      or intent.provider_customer_id = btrim(p_payment ->> 'customer')
    )
    and (
      intent.provider_subscription_id is null
      or nullif(btrim(coalesce(p_payment ->> 'subscription', '')), '') is null
      or intent.provider_subscription_id = btrim(p_payment ->> 'subscription')
    )
  order by intent.created_at desc, intent.id desc
  limit 1
  for update;

  if v_organization_id is null then
    v_organization_id :=
      private.billing_checkout_organization_from_reference(
        p_payment ->> 'externalReference',
        p_payment ->> 'customer',
        p_payment ->> 'subscription'
      );
  end if;

  if v_organization_id is not null then
    v_payment := jsonb_set(
      p_payment,
      '{externalReference}',
      to_jsonb(v_organization_id::text),
      true
    );
  end if;

  v_result := public.reconcile_asaas_payment_webhook(
    p_event_id,
    p_event_type,
    p_event_at,
    v_payment,
    p_payload
  );

  if v_intent_id is not null then
    update private.billing_checkout_intents
    set
      status = case when status = 'creating' then 'pending' else status end,
      provider_customer_id = coalesce(
        nullif(btrim(p_payment ->> 'customer'), ''),
        provider_customer_id
      ),
      provider_payment_id = coalesce(
        nullif(btrim(p_payment ->> 'id'), ''),
        provider_payment_id
      ),
      provider_subscription_id = coalesce(
        nullif(btrim(p_payment ->> 'subscription'), ''),
        provider_subscription_id
      ),
      provider_registered_at = coalesce(provider_registered_at, now()),
      updated_at = now()
    where id = v_intent_id;

    update public.organizations
    set
      asaas_customer_id = coalesce(
        nullif(btrim(p_payment ->> 'customer'), ''),
        asaas_customer_id
      ),
      asaas_subscription_id = coalesce(
        nullif(btrim(p_payment ->> 'subscription'), ''),
        asaas_subscription_id
      ),
      updated_at = now()
    where id = v_organization_id;

    update public.subscriptions
    set
      provider = 'asaas',
      provider_customer_id = coalesce(
        nullif(btrim(p_payment ->> 'customer'), ''),
        provider_customer_id
      ),
      provider_subscription_id = coalesce(
        nullif(btrim(p_payment ->> 'subscription'), ''),
        provider_subscription_id
      ),
      updated_at = now()
    where organization_id = v_organization_id;

    update public.asaas_payments
    set
      billing_intent_id = v_intent_id,
      updated_at = now()
    where asaas_payment_id = p_payment ->> 'id'
      and organization_id = v_organization_id
      and billing_intent_id is distinct from v_intent_id;
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION public.reconcile_asaas_payment_webhook_with_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: reconcile_asaas_payment_webhook_with_period_intent(text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_payment_webhook_with_period_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_result jsonb;
  v_confirmation jsonb;
  v_status text := upper(btrim(coalesce(p_payment ->> 'status', '')));
  v_amount numeric;
  v_intent private.billing_checkout_intents%rowtype;
  v_organization_id uuid;
  v_plan_id uuid;
  v_billing_period_months integer;
  v_billing_cycle text;
  v_charged_amount numeric;
  v_is_recurring boolean := false;
  v_period_anchor date;
  v_period_start timestamptz;
  v_period_end timestamptz;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  v_result := public.reconcile_asaas_payment_webhook_with_intent(
    p_event_id,
    p_event_type,
    p_event_at,
    p_payment,
    p_payload
  );

  if upper(btrim(coalesce(p_event_type, ''))) = 'PAYMENT_CONFIRMED' then
    v_status := 'CONFIRMED';
  elsif upper(btrim(coalesce(p_event_type, ''))) = 'PAYMENT_RECEIVED' then
    v_status := 'RECEIVED';
  elsif upper(btrim(coalesce(p_event_type, ''))) = 'PAYMENT_RECEIVED_IN_CASH' then
    v_status := 'RECEIVED_IN_CASH';
  end if;

  if jsonb_typeof(p_payment -> 'value') = 'number' then
    v_amount := (p_payment ->> 'value')::numeric;
  end if;

  if coalesce(v_result ->> 'outcome', '') = 'processed'
     and v_status in ('CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH') then
    v_confirmation := private.confirm_billing_checkout_intent(
      p_payment ->> 'id',
      p_payment ->> 'subscription',
      v_status,
      v_amount
    );

    if coalesce(v_confirmation ->> 'outcome', '') not in (
      'confirmed',
      'already_confirmed',
      'intent_not_found',
      'terminal_state'
    ) then
      raise exception 'billing intent confirmation failed: %', v_confirmation
        using errcode = '23514';
    end if;

    if coalesce(v_confirmation ->> 'outcome', '') in (
      'confirmed',
      'already_confirmed'
    ) then
      select intent.*
      into v_intent
      from private.billing_checkout_intents intent
      where intent.status = 'confirmed'
        and intent.id = (v_confirmation ->> 'intent_id')::uuid
      for update;

      if found then
        v_organization_id := v_intent.organization_id;
        v_plan_id := v_intent.pending_plan_id;
        v_billing_period_months := v_intent.billing_period_months;
        v_billing_cycle := v_intent.billing_cycle;
        v_charged_amount := coalesce(v_amount, v_intent.amount);
        v_is_recurring := v_intent.billing_method = 'CREDIT_CARD'
          or nullif(btrim(coalesce(p_payment ->> 'subscription', '')), '') is not null;
      end if;
    elsif coalesce(v_confirmation ->> 'outcome', '') = 'intent_not_found'
       and coalesce(v_result ->> 'organization_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      select
        organization_row.id,
        organization_row.plan_id,
        case
          when subscription_row.billing_period_months in (1, 6, 12)
            then subscription_row.billing_period_months
          when organization_row.subscription_billing_period_months in (1, 6, 12)
            then organization_row.subscription_billing_period_months
          else 1
        end
      into
        v_organization_id,
        v_plan_id,
        v_billing_period_months
      from public.organizations organization_row
      left join lateral (
        select candidate.billing_period_months
        from public.subscriptions candidate
        where candidate.organization_id = organization_row.id
          and candidate.plan_id = organization_row.plan_id
          and (
            nullif(btrim(coalesce(p_payment ->> 'subscription', '')), '') is null
            or candidate.provider_subscription_id is null
            or candidate.provider_subscription_id = btrim(p_payment ->> 'subscription')
          )
        order by
          case
            when candidate.provider_subscription_id = nullif(
              btrim(coalesce(p_payment ->> 'subscription', '')),
              ''
            ) then 0
            else 1
          end,
          case when candidate.status = 'active' then 0 else 1 end,
          candidate.updated_at desc nulls last,
          candidate.id desc
        limit 1
      ) subscription_row on true
      where organization_row.id = (v_result ->> 'organization_id')::uuid
      for update of organization_row;

      v_billing_cycle := case v_billing_period_months
        when 6 then 'semiannual'
        when 12 then 'yearly'
        else 'monthly'
      end;
      v_charged_amount := v_amount;
      v_is_recurring := nullif(
        btrim(coalesce(p_payment ->> 'subscription', '')),
        ''
      ) is not null;
    end if;

    if v_organization_id is not null
       and v_plan_id is not null
       and v_billing_period_months in (1, 6, 12) then
      if v_is_recurring then
        if coalesce(p_payment ->> 'dueDate', '') ~ '^\d{4}-\d{2}-\d{2}$' then
          v_period_anchor := (p_payment ->> 'dueDate')::date;
          v_period_start := v_period_anchor::timestamptz;
        end if;
      else
        if coalesce(p_payment ->> 'paymentDate', '') ~ '^\d{4}-\d{2}-\d{2}$' then
          v_period_anchor := (p_payment ->> 'paymentDate')::date;
        elsif coalesce(p_payment ->> 'dueDate', '') ~ '^\d{4}-\d{2}-\d{2}$' then
          v_period_anchor := (p_payment ->> 'dueDate')::date;
        else
          v_period_anchor := coalesce(p_event_at, now())::date;
        end if;
        v_period_start := v_period_anchor::timestamptz;
      end if;

      if v_period_anchor is not null then
        v_period_end := (
          v_period_anchor + make_interval(months => v_billing_period_months)
        )::timestamptz;

        update public.organizations
        set
          subscription_billing_period_months = v_billing_period_months,
          next_billing_date = greatest(
            coalesce(next_billing_date, '-infinity'::date),
            v_period_end::date
          ),
          updated_at = now()
        where id = v_organization_id
          and plan_id = v_plan_id
          and subscription_status = 'active';

        update public.subscriptions
        set
          billing_period_months = v_billing_period_months,
          current_period_start = case
            when current_period_end is null or v_period_end > current_period_end
              then v_period_start
            else current_period_start
          end,
          current_period_end = greatest(
            coalesce(current_period_end, '-infinity'::timestamptz),
            v_period_end
          ),
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
            'billing_period_months', v_billing_period_months,
            'billing_cycle', v_billing_cycle,
            'charged_amount', v_charged_amount,
            'period_anchor', v_period_anchor
          ),
          updated_at = now()
        where organization_id = v_organization_id
          and plan_id = v_plan_id
          and (
            nullif(btrim(coalesce(p_payment ->> 'subscription', '')), '') is null
            or provider_subscription_id is null
            or provider_subscription_id = btrim(p_payment ->> 'subscription')
          );
      end if;
    end if;
  end if;

  return v_result;
end;
$_$;


ALTER FUNCTION public.reconcile_asaas_payment_webhook_with_period_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_payment jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: reconcile_asaas_subscription_webhook(text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_subscription_webhook(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_subscription jsonb, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_event_id text := btrim(coalesce(p_event_id, ''));
  v_event_type text := upper(btrim(coalesce(p_event_type, '')));
  v_event_at timestamptz := coalesce(p_event_at, now());
  v_subscription_id text := btrim(coalesce(p_subscription ->> 'id', ''));
  v_customer_id text := nullif(btrim(coalesce(p_subscription ->> 'customer', '')), '');
  v_external_reference text := nullif(
    btrim(coalesce(p_subscription ->> 'externalReference', '')),
    ''
  );
  v_provider_status text := upper(
    nullif(btrim(coalesce(p_subscription ->> 'status', '')), '')
  );
  v_next_due_date date;
  v_external_organization_id uuid;
  v_exact_organization_id uuid;
  v_organization_id uuid;
  v_current_organization_status text;
  v_current_customer_id text;
  v_current_subscription_id text;
  v_current_event_at timestamptz;
  v_new_organization_status text;
  v_event_is_stale boolean := false;
  v_should_advance_org_event boolean := false;
  v_inserted integer := 0;
begin
  if char_length(v_event_id) not between 1 and 512 then
    raise exception using
      errcode = '22023',
      message = 'Invalid Asaas webhook event id';
  end if;

  if left(v_event_type, 13) <> 'SUBSCRIPTION_' then
    raise exception using
      errcode = '22023',
      message = 'Unsupported Asaas subscription webhook event type';
  end if;

  if jsonb_typeof(p_subscription) is distinct from 'object'
    or char_length(v_subscription_id) not between 1 and 255
    or char_length(coalesce(v_customer_id, '')) not between 1 and 255
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid Asaas webhook subscription payload';
  end if;

  if jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception using
      errcode = '22023',
      message = 'Invalid Asaas webhook payload';
  end if;

  if coalesce(p_subscription ->> 'nextDueDate', '') ~ '^\d{4}-\d{2}-\d{2}$' then
    v_next_due_date := (p_subscription ->> 'nextDueDate')::date;
  end if;

  select case when count(*) = 1 then min(id::text)::uuid end
  into v_exact_organization_id
  from public.organizations
  where asaas_subscription_id = v_subscription_id
    and (asaas_customer_id is null or asaas_customer_id = v_customer_id);

  if v_external_reference ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    select id
    into v_external_organization_id
    from public.organizations
    where id = v_external_reference::uuid
      and (asaas_customer_id is null or asaas_customer_id = v_customer_id)
      and (asaas_subscription_id is null or asaas_subscription_id = v_subscription_id);
  end if;

  if v_exact_organization_id is not null
    and v_external_organization_id is not null
    and v_exact_organization_id <> v_external_organization_id
  then
    raise exception using
      errcode = '22023',
      message = 'Asaas subscription reference does not match the existing organization';
  end if;

  v_organization_id := coalesce(
    v_exact_organization_id,
    v_external_organization_id
  );

  if v_organization_id is null then
    select case when count(*) = 1 then min(id::text)::uuid end
    into v_organization_id
    from public.organizations
    where asaas_customer_id = v_customer_id
      and (asaas_subscription_id is null or asaas_subscription_id = v_subscription_id);
  end if;

  if v_organization_id is null then
    insert into private.asaas_webhook_events (
      event_id,
      event_type,
      resource_type,
      resource_id,
      organization_id,
      provider_event_at,
      outcome,
      payload
    )
    values (
      v_event_id,
      v_event_type,
      'subscription',
      v_subscription_id,
      null,
      v_event_at,
      'unmatched',
      p_payload
    )
    on conflict (event_id) do nothing;

    get diagnostics v_inserted = row_count;

    return jsonb_build_object(
      'outcome', case when v_inserted = 0 then 'duplicate' else 'unmatched' end,
      'event_id', v_event_id,
      'subscription_id', v_subscription_id
    );
  end if;

  insert into private.asaas_webhook_events (
    event_id,
    event_type,
    resource_type,
    resource_id,
    organization_id,
    provider_event_at,
    outcome,
    payload
  )
  values (
    v_event_id,
    v_event_type,
    'subscription',
    v_subscription_id,
    v_organization_id,
    v_event_at,
    'processed',
    p_payload
  )
  on conflict (event_id) do nothing;

  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    return jsonb_build_object(
      'outcome', 'duplicate',
      'event_id', v_event_id,
      'subscription_id', v_subscription_id,
      'organization_id', v_organization_id
    );
  end if;

  select
    subscription_status,
    asaas_customer_id,
    asaas_subscription_id,
    asaas_last_event_at
  into
    v_current_organization_status,
    v_current_customer_id,
    v_current_subscription_id,
    v_current_event_at
  from public.organizations
  where id = v_organization_id
  for update;

  if not found then
    update private.asaas_webhook_events
    set outcome = 'unmatched', organization_id = null
    where event_id = v_event_id;

    return jsonb_build_object(
      'outcome', 'unmatched',
      'event_id', v_event_id,
      'subscription_id', v_subscription_id
    );
  end if;

  v_event_is_stale :=
    (v_current_event_at is not null and v_event_at < v_current_event_at)
    or (
      v_current_customer_id is not null
      and v_current_customer_id <> v_customer_id
    )
    or (
      v_current_subscription_id is not null
      and v_current_subscription_id <> v_subscription_id
    );

  v_new_organization_status := v_current_organization_status;

  if not v_event_is_stale then
    if v_event_type in ('SUBSCRIPTION_INACTIVATED', 'SUBSCRIPTION_DELETED') then
      v_new_organization_status := 'cancelled';
    elsif v_event_type = 'SUBSCRIPTION_SPLIT_DIVERGENCE_BLOCK' then
      v_new_organization_status := 'suspended';
    elsif v_event_type = 'SUBSCRIPTION_SPLIT_DIVERGENCE_BLOCK_FINISHED'
      and v_current_organization_status = 'suspended'
    then
      v_new_organization_status := 'pending_payment';
    end if;
  end if;

  v_should_advance_org_event :=
    not v_event_is_stale
    and v_event_type in (
      'SUBSCRIPTION_INACTIVATED',
      'SUBSCRIPTION_DELETED',
      'SUBSCRIPTION_SPLIT_DIVERGENCE_BLOCK',
      'SUBSCRIPTION_SPLIT_DIVERGENCE_BLOCK_FINISHED'
    );

  if v_event_is_stale then
    update private.asaas_webhook_events
    set outcome = 'stale'
    where event_id = v_event_id;
  end if;

  update public.organizations
  set
    asaas_customer_id = case
      when not v_event_is_stale then coalesce(asaas_customer_id, v_customer_id)
      else asaas_customer_id
    end,
    asaas_subscription_id = case
      when not v_event_is_stale then coalesce(asaas_subscription_id, v_subscription_id)
      else asaas_subscription_id
    end,
    subscription_status = v_new_organization_status,
    next_billing_date = case
      when not v_event_is_stale
        and v_next_due_date is not null
        and v_event_type in ('SUBSCRIPTION_CREATED', 'SUBSCRIPTION_UPDATED')
        then v_next_due_date
      else next_billing_date
    end,
    asaas_last_event_id = case
      when v_should_advance_org_event then v_event_id
      else asaas_last_event_id
    end,
    asaas_last_event_at = case
      when v_should_advance_org_event then v_event_at
      else asaas_last_event_at
    end,
    updated_at = now()
  where id = v_organization_id;

  update public.subscriptions
  set
    status = case
      when not v_event_is_stale then v_new_organization_status
      else status
    end,
    provider = 'asaas',
    provider_customer_id = case
      when not v_event_is_stale
        then coalesce(provider_customer_id, v_customer_id)
      else provider_customer_id
    end,
    provider_subscription_id = case
      when not v_event_is_stale
        then coalesce(provider_subscription_id, v_subscription_id)
      else provider_subscription_id
    end,
    canceled_at = case
      when not v_event_is_stale and v_new_organization_status = 'cancelled'
        then coalesce(canceled_at, now())
      else canceled_at
    end,
    metadata = case
      when not v_event_is_stale
        then coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'asaas_last_event_id', v_event_id,
          'asaas_last_event_type', v_event_type,
          'asaas_last_event_at', v_event_at,
          'asaas_subscription_status', v_provider_status
        )
      else metadata
    end,
    updated_at = now()
  where organization_id = v_organization_id
    and (
      provider_subscription_id is null
      or provider_subscription_id = v_subscription_id
    );

  return jsonb_build_object(
    'outcome', case when v_event_is_stale then 'stale' else 'processed' end,
    'event_id', v_event_id,
    'subscription_id', v_subscription_id,
    'provider_status', v_provider_status,
    'organization_id', v_organization_id,
    'subscription_status', v_new_organization_status
  );
end;
$_$;


ALTER FUNCTION public.reconcile_asaas_subscription_webhook(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_subscription jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: reconcile_asaas_subscription_webhook_with_intent(text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_subscription_webhook_with_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_subscription jsonb, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_subscription jsonb := p_subscription;
  v_organization_id uuid;
  v_intent_id uuid;
  v_result jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  perform private.lock_asaas_billing_resources(
    null,
    p_subscription ->> 'id'
  );

  select intent.id, intent.organization_id
  into v_intent_id, v_organization_id
  from private.billing_checkout_intents intent
  where intent.external_reference = nullif(
      btrim(coalesce(p_subscription ->> 'externalReference', '')),
      ''
    )
    and (
      intent.provider_customer_id is null
      or nullif(btrim(coalesce(p_subscription ->> 'customer', '')), '') is null
      or intent.provider_customer_id = btrim(p_subscription ->> 'customer')
    )
    and (
      intent.provider_subscription_id is null
      or intent.provider_subscription_id = nullif(
        btrim(coalesce(p_subscription ->> 'id', '')),
        ''
      )
    )
  order by intent.created_at desc, intent.id desc
  limit 1
  for update;

  if v_organization_id is null then
    v_organization_id :=
      private.billing_checkout_organization_from_reference(
        p_subscription ->> 'externalReference',
        p_subscription ->> 'customer',
        p_subscription ->> 'id'
      );
  end if;

  if v_organization_id is not null then
    v_subscription := jsonb_set(
      p_subscription,
      '{externalReference}',
      to_jsonb(v_organization_id::text),
      true
    );
  end if;

  v_result := public.reconcile_asaas_subscription_webhook(
    p_event_id,
    p_event_type,
    p_event_at,
    v_subscription,
    p_payload
  );

  if v_intent_id is not null then
    update private.billing_checkout_intents
    set
      status = case when status = 'creating' then 'pending' else status end,
      provider_customer_id = coalesce(
        nullif(btrim(p_subscription ->> 'customer'), ''),
        provider_customer_id
      ),
      provider_subscription_id = coalesce(
        nullif(btrim(p_subscription ->> 'id'), ''),
        provider_subscription_id
      ),
      provider_registered_at = coalesce(provider_registered_at, now()),
      updated_at = now()
    where id = v_intent_id;

    update public.organizations
    set
      asaas_customer_id = coalesce(
        nullif(btrim(p_subscription ->> 'customer'), ''),
        asaas_customer_id
      ),
      asaas_subscription_id = coalesce(
        nullif(btrim(p_subscription ->> 'id'), ''),
        asaas_subscription_id
      ),
      updated_at = now()
    where id = v_organization_id;

    update public.subscriptions
    set
      provider = 'asaas',
      provider_customer_id = coalesce(
        nullif(btrim(p_subscription ->> 'customer'), ''),
        provider_customer_id
      ),
      provider_subscription_id = coalesce(
        nullif(btrim(p_subscription ->> 'id'), ''),
        provider_subscription_id
      ),
      updated_at = now()
    where organization_id = v_organization_id;

    update public.asaas_payments
    set
      billing_intent_id = v_intent_id,
      updated_at = now()
    where organization_id = v_organization_id
      and asaas_subscription_id = p_subscription ->> 'id'
      and billing_intent_id is distinct from v_intent_id;
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION public.reconcile_asaas_subscription_webhook_with_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_subscription jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: reconcile_asaas_subscription_webhook_with_period_intent(text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_asaas_subscription_webhook_with_period_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_subscription jsonb, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_result jsonb;
  v_organization_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  v_result := public.reconcile_asaas_subscription_webhook_with_intent(
    p_event_id,
    p_event_type,
    p_event_at,
    p_subscription,
    p_payload
  );

  if coalesce(v_result ->> 'outcome', '') = 'processed'
     and upper(btrim(coalesce(p_event_type, ''))) in (
       'SUBSCRIPTION_CREATED',
       'SUBSCRIPTION_UPDATED'
     )
     and coalesce(v_result ->> 'organization_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    v_organization_id := (v_result ->> 'organization_id')::uuid;

    -- SUBSCRIPTION_CREATED can arrive after PAYMENT_CONFIRMED carrying the
    -- checkout's first due date. Never let that older provider snapshot move
    -- the organization behind the paid period already persisted locally.
    update public.organizations organization_row
    set
      next_billing_date = coalesce(
        greatest(
          organization_row.next_billing_date,
          (
          select max(subscription_row.current_period_end::date)
          from public.subscriptions subscription_row
          where subscription_row.organization_id = organization_row.id
            and (
              nullif(btrim(coalesce(p_subscription ->> 'id', '')), '') is null
              or subscription_row.provider_subscription_id is null
              or subscription_row.provider_subscription_id = btrim(
                p_subscription ->> 'id'
              )
            )
          )
        ),
        organization_row.next_billing_date
      ),
      updated_at = now()
    where organization_row.id = v_organization_id;
  end if;

  return v_result;
end;
$_$;


ALTER FUNCTION public.reconcile_asaas_subscription_webhook_with_period_intent(p_event_id text, p_event_type text, p_event_at timestamp with time zone, p_subscription jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: reconcile_billing_card_recurrence_subscription(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_billing_card_recurrence_subscription(p_subscription jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_external_reference text;
  v_payment_id uuid;
  v_provider_payment_id text;
begin
  if p_subscription is null or jsonb_typeof(p_subscription) <> 'object' then
    return jsonb_build_object('outcome', 'not_applicable');
  end if;

  v_external_reference := p_subscription ->> 'externalReference';
  if v_external_reference is null or v_external_reference !~ (
    '^vimob:billing-card-recurrence:'
    || '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    return jsonb_build_object('outcome', 'not_applicable');
  end if;

  begin
    v_payment_id := replace(
      v_external_reference,
      'vimob:billing-card-recurrence:',
      ''
    )::uuid;
  exception
    when invalid_text_representation then
      return jsonb_build_object('outcome', 'not_applicable');
  end;

  select provision.provider_payment_id
  into v_provider_payment_id
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment_id
    and provision.external_reference = v_external_reference;

  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  return private.complete_billing_card_recurrence_locked(
    v_payment_id,
    v_provider_payment_id,
    null,
    p_subscription,
    false
  );
end
$_$;


ALTER FUNCTION public.reconcile_billing_card_recurrence_subscription(p_subscription jsonb) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_billing_card_recurrence_subscription(p_subscription jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reconcile_billing_card_recurrence_subscription(p_subscription jsonb) IS 'Webhook recovery path for an exact deterministic recurrence externalReference; never creates a provider subscription.';


--
-- Name: reconcile_imported_property_photos(uuid, uuid, text, text[], text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_imported_property_photos(p_organization_id uuid, p_property_id uuid, p_provider text, p_photo_urls text[], p_primary_url text DEFAULT NULL::text, p_gallery_complete boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_provider text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_provider, '')));
  v_raw_url text;
  v_url text;
  v_urls text[] := '{}'::text[];
  v_requested_primary text := nullif(pg_catalog.btrim(p_primary_url), '');
  v_hidden_urls jsonb;
  v_imoview_code text;
  v_vista_code text;
  v_existing_photo_count integer;
  v_activation_photo_count integer;
  v_total_photo_count integer;
  v_managed_photo_count integer;
  v_retired_photo_count integer;
  v_retired_in_run integer := 0;
  v_detached_in_run integer := 0;
  v_requested_primary_asset_id uuid;
  v_current_primary_asset_id uuid;
  v_current_primary_replaceable boolean := false;
  v_legacy_urls text[] := '{}'::text[];
  v_legacy_primary text;
begin
  if p_organization_id is null or p_property_id is null then
    raise exception 'organization and property are required'
      using errcode = '22023';
  end if;

  if v_provider not in ('imoview', 'vista') then
    raise exception 'unsupported property media provider'
      using errcode = '22023';
  end if;

  if coalesce(pg_catalog.cardinality(p_photo_urls), 0) > 20 then
    raise exception 'a provider gallery can have at most 20 photos'
      using errcode = '23514', constraint = 'property_assets_photo_capacity';
  end if;

  select
    coalesce(property.metadata->'hidden_site_image_urls', '[]'::jsonb),
    nullif(pg_catalog.btrim(property.imoview_codigo), ''),
    nullif(pg_catalog.btrim(property.vista_codigo), '')
    into v_hidden_urls, v_imoview_code, v_vista_code
  from public.properties as property
  where property.organization_id = p_organization_id
    and property.id = p_property_id
  for update;

  if not found then
    raise exception 'property does not belong to organization'
      using errcode = '23503', constraint = 'property_assets_property_fkey';
  end if;

  if (v_provider = 'imoview' and v_imoview_code is null)
     or (v_provider = 'vista' and v_vista_code is null) then
    raise exception 'property is not linked to media provider'
      using errcode = '23514', constraint = 'property_assets_provider_reference_check';
  end if;

  foreach v_raw_url in array coalesce(p_photo_urls, '{}'::text[])
  loop
    v_url := pg_catalog.btrim(coalesce(v_raw_url, ''));
    if v_url = ''
       or pg_catalog.length(v_url) > 2048
       or v_url !~* '^https://[^[:space:]]+$' then
      raise exception 'provider photo URLs must be HTTPS and at most 2048 characters'
        using errcode = '22023';
    end if;
    if not (v_url = any(v_urls)) then
      v_urls := pg_catalog.array_append(v_urls, v_url);
    end if;
  end loop;

  if v_requested_primary is not null then
    if pg_catalog.length(v_requested_primary) > 2048
       or v_requested_primary !~* '^https://[^[:space:]]+$'
       or not (v_requested_primary = any(v_urls)) then
      raise exception 'primary provider photo must be part of the gallery'
        using errcode = '22023';
    end if;
  end if;

  -- Only a complete upstream gallery may remove this provider from absent
  -- rows. Shared rows keep the other active provider and remain live; sole
  -- ownership becomes a logical tombstone with the same id and locator.
  if p_gallery_complete is true then
    with provider_absences as (
      select
        asset.id,
        private.property_asset_integration_providers(asset.metadata) - v_provider
          as remaining_providers
      from public.property_assets as asset
      where asset.organization_id = p_organization_id
        and asset.property_id = p_property_id
        and asset.asset_type = 'photo'
        and asset.external_url is not null
        and not (asset.external_url = any(v_urls))
        and coalesce(asset.metadata->>'integration_managed', 'false') = 'true'
        and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true'
        and private.property_asset_integration_providers(asset.metadata) ? v_provider
      for update
    ), detached as (
      update public.property_assets as asset
      set metadata = case
            when pg_catalog.jsonb_array_length(absence.remaining_providers) = 0 then
              (coalesce(asset.metadata, '{}'::jsonb)
                - 'integration_provider'
                - 'integration_retired')
                || pg_catalog.jsonb_build_object(
                  'integration_managed', true,
                  'integration_providers', '[]'::jsonb,
                  'integration_retired', true
                )
            else
              (coalesce(asset.metadata, '{}'::jsonb)
                - 'integration_provider'
                - 'integration_retired')
                || pg_catalog.jsonb_build_object(
                  'integration_managed', true,
                  'integration_providers', absence.remaining_providers
                )
          end,
          is_primary = case
            when pg_catalog.jsonb_array_length(absence.remaining_providers) = 0
              then false
            else asset.is_primary
          end,
          updated_at = pg_catalog.now()
      from provider_absences as absence
      where asset.id = absence.id
      returning pg_catalog.jsonb_array_length(absence.remaining_providers) = 0
        as retired
    )
    select
      pg_catalog.count(*) filter (where detached.retired)::integer,
      pg_catalog.count(*)::integer
      into v_retired_in_run, v_detached_in_run
    from detached;
  end if;

  select pg_catalog.count(*)::integer
    into v_existing_photo_count
  from public.property_assets as asset
  where asset.organization_id = p_organization_id
    and asset.property_id = p_property_id
    and asset.asset_type = 'photo'
    and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true';

  -- Reappearing managed URLs count as activations even though their locator row
  -- already exists. The whole function is one transaction, so a capacity error
  -- also rolls back any retirement performed above.
  select pg_catalog.count(*)::integer
    into v_activation_photo_count
  from pg_catalog.unnest(v_urls) as source(url)
  where not exists (
    select 1
    from public.property_assets as asset
    where asset.organization_id = p_organization_id
      and asset.property_id = p_property_id
      and asset.asset_type = 'photo'
      and asset.external_url = source.url
      and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true'
  );

  if v_existing_photo_count + v_activation_photo_count > 20 then
    raise exception 'property_media_capacity_exhausted_append_only'
      using errcode = '23514',
        constraint = 'property_assets_photo_capacity',
        detail = 'The active canonical gallery would exceed 20 photos; retired provider rows do not consume capacity.';
  end if;

  -- Add this provider to current managed rows, adopt a matching row created by
  -- the legacy compatibility mirror, and reactivate a matching retired row in
  -- place. An unmarked/manual row that happens to share the URL is deliberately
  -- not adopted. Locator, checksum/hash, visibility and the legacy_mirror source
  -- marker are left untouched so frozen snapshots keep resolving the same row.
  update public.property_assets as asset
  set metadata = (coalesce(asset.metadata, '{}'::jsonb)
          - 'integration_provider'
          - 'integration_retired')
        || pg_catalog.jsonb_build_object(
          'integration_managed', true,
          'integration_providers',
            private.property_asset_integration_providers(asset.metadata)
              || pg_catalog.jsonb_build_array(v_provider),
          'access_model', 'external_origin_uncontrolled'
        ),
      updated_at = pg_catalog.now()
  where asset.organization_id = p_organization_id
    and asset.property_id = p_property_id
    and asset.asset_type = 'photo'
    and asset.external_url = any(v_urls)
    and (
      coalesce(asset.metadata->>'integration_managed', 'false') = 'true'
      or coalesce(asset.metadata->>'legacy_mirror', 'false') = 'true'
    )
    and (
      coalesce(asset.metadata->>'integration_retired', 'false') = 'true'
      or not (private.property_asset_integration_providers(asset.metadata) ? v_provider)
    );

  insert into public.property_assets (
    organization_id,
    property_id,
    asset_type,
    visibility,
    external_url,
    sort_order,
    is_primary,
    metadata,
    created_at,
    updated_at
  )
  select
    p_organization_id,
    p_property_id,
    'photo',
    case when v_hidden_urls ? source.url then 'internal' else 'public' end,
    source.url,
    10 + source.position::integer - 1,
    false,
    pg_catalog.jsonb_build_object(
      'integration_managed', true,
      'integration_providers', pg_catalog.jsonb_build_array(v_provider),
      'access_model', 'external_origin_uncontrolled'
    ),
    pg_catalog.now(),
    pg_catalog.now()
  from pg_catalog.unnest(v_urls) with ordinality as source(url, position)
  where not exists (
    select 1
    from public.property_assets as asset
    where asset.organization_id = p_organization_id
      and asset.property_id = p_property_id
      and asset.asset_type = 'photo'
      and asset.external_url = source.url
  );

  -- A provider may rotate only its own sole-owned primary. Manual and shared
  -- primaries are preserved, and no retired row can be selected or promoted.
  select candidate.id
    into v_requested_primary_asset_id
  from public.property_assets as candidate
  where candidate.organization_id = p_organization_id
    and candidate.property_id = p_property_id
    and candidate.asset_type = 'photo'
    and candidate.visibility = 'public'
    and candidate.external_url = v_requested_primary
    and coalesce(candidate.metadata->>'integration_retired', 'false') <> 'true'
    and coalesce(candidate.metadata->>'integration_managed', 'false') = 'true'
    and private.property_asset_integration_providers(candidate.metadata) ? v_provider
  order by candidate.created_at, candidate.id
  limit 1;

  select
    current_primary.id,
    coalesce(current_primary.metadata->>'integration_managed', 'false') = 'true'
      and coalesce(current_primary.metadata->>'integration_retired', 'false') <> 'true'
      and private.property_asset_integration_providers(current_primary.metadata) ? v_provider
      and pg_catalog.jsonb_array_length(
        private.property_asset_integration_providers(current_primary.metadata)
      ) = 1
    into v_current_primary_asset_id, v_current_primary_replaceable
  from public.property_assets as current_primary
  where current_primary.organization_id = p_organization_id
    and current_primary.property_id = p_property_id
    and current_primary.asset_type = 'photo'
    and current_primary.is_primary
    and coalesce(current_primary.metadata->>'integration_retired', 'false') <> 'true'
  order by current_primary.created_at, current_primary.id
  limit 1;

  if v_requested_primary_asset_id is not null
     and v_current_primary_asset_id is distinct from v_requested_primary_asset_id
     and (v_current_primary_asset_id is null or v_current_primary_replaceable) then
    if v_current_primary_asset_id is not null then
      update public.property_assets as current_primary
      set is_primary = false,
          updated_at = pg_catalog.now()
      where current_primary.organization_id = p_organization_id
        and current_primary.property_id = p_property_id
        and current_primary.id = v_current_primary_asset_id
        and current_primary.asset_type = 'photo'
        and current_primary.is_primary
        and coalesce(current_primary.metadata->>'integration_retired', 'false') <> 'true'
        and coalesce(current_primary.metadata->>'integration_managed', 'false') = 'true'
        and private.property_asset_integration_providers(current_primary.metadata) ? v_provider
        and pg_catalog.jsonb_array_length(
          private.property_asset_integration_providers(current_primary.metadata)
        ) = 1;
    end if;

    update public.property_assets as asset
    set is_primary = true,
        updated_at = pg_catalog.now()
    where asset.organization_id = p_organization_id
      and asset.property_id = p_property_id
      and asset.id = v_requested_primary_asset_id
      and asset.asset_type = 'photo'
      and asset.visibility = 'public'
      and asset.external_url = v_requested_primary
      and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true'
      and not exists (
        select 1
        from public.property_assets as preserved_primary
        where preserved_primary.organization_id = p_organization_id
          and preserved_primary.property_id = p_property_id
          and preserved_primary.asset_type = 'photo'
          and preserved_primary.is_primary
          and coalesce(preserved_primary.metadata->>'integration_retired', 'false') <> 'true'
          and preserved_primary.id <> v_requested_primary_asset_id
      );
  end if;

  -- Compatibility columns contain only the active public external gallery.
  -- Retired locators remain reachable only through immutable version asset ids.
  select
    coalesce(
      pg_catalog.array_agg(asset.external_url order by asset.is_primary desc, asset.sort_order, asset.created_at, asset.id),
      '{}'::text[]
    )
    into v_legacy_urls
  from public.property_assets as asset
  where asset.organization_id = p_organization_id
    and asset.property_id = p_property_id
    and asset.asset_type = 'photo'
    and asset.visibility = 'public'
    and asset.external_url is not null
    and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true';

  select asset.external_url
    into v_legacy_primary
  from public.property_assets as asset
  where asset.organization_id = p_organization_id
    and asset.property_id = p_property_id
    and asset.asset_type = 'photo'
    and asset.visibility = 'public'
    and asset.is_primary
    and asset.external_url is not null
    and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true'
  limit 1;

  update public.properties as property
  set imagem_principal = v_legacy_primary,
      image_urls = v_legacy_urls,
      fotos = pg_catalog.to_jsonb(v_legacy_urls)
  where property.organization_id = p_organization_id
    and property.id = p_property_id;

  select pg_catalog.count(*)::integer
    into v_total_photo_count
  from public.property_assets as asset
  where asset.organization_id = p_organization_id
    and asset.property_id = p_property_id
    and asset.asset_type = 'photo'
    and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true';

  select pg_catalog.count(*)::integer
    into v_managed_photo_count
  from public.property_assets as asset
  where asset.organization_id = p_organization_id
    and asset.property_id = p_property_id
    and asset.asset_type = 'photo'
    and coalesce(asset.metadata->>'integration_retired', 'false') <> 'true'
    and coalesce(asset.metadata->>'integration_managed', 'false') = 'true'
    and private.property_asset_integration_providers(asset.metadata) ? v_provider;

  select pg_catalog.count(*)::integer
    into v_retired_photo_count
  from public.property_assets as asset
  where asset.organization_id = p_organization_id
    and asset.property_id = p_property_id
    and asset.asset_type = 'photo'
    and coalesce(asset.metadata->>'integration_managed', 'false') = 'true'
    and coalesce(asset.metadata->>'integration_retired', 'false') = 'true';

  return pg_catalog.jsonb_build_object(
    'provider', v_provider,
    'property_id', p_property_id,
    'photo_count', v_total_photo_count,
    'managed_photo_count', v_managed_photo_count,
    'retired_photo_count', v_retired_photo_count,
    'retired_in_run', v_retired_in_run,
    'provider_ownerships_removed', v_detached_in_run,
    'gallery_complete', p_gallery_complete is true,
    'primary_url', v_legacy_primary
  );
end;
$_$;


ALTER FUNCTION public.reconcile_imported_property_photos(p_organization_id uuid, p_property_id uuid, p_provider text, p_photo_urls text[], p_primary_url text, p_gallery_complete boolean) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_imported_property_photos(p_organization_id uuid, p_property_id uuid, p_provider text, p_photo_urls text[], p_primary_url text, p_gallery_complete boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reconcile_imported_property_photos(p_organization_id uuid, p_property_id uuid, p_provider text, p_photo_urls text[], p_primary_url text, p_gallery_complete boolean) IS 'Service-role-only reconciliation for Imoview/Vista photos. Complete galleries logically retire missing sole-owned rows; partial galleries are additive, and reappearing locators reactivate their original asset id.';


--
-- Name: record_resend_email_event(text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_resend_email_event(p_provider_event_id text, p_provider_message_id text, p_event_type text, p_occurred_at timestamp with time zone, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_event_id text;
  v_provider_message_id text;
  v_event_type text;
  v_email_log_id uuid;
  v_organization_id uuid;
  v_user_id uuid;
  v_event_id uuid;
begin
  if nullif(btrim(p_provider_event_id), '') is null
     or nullif(btrim(p_provider_message_id), '') is null
     or p_event_type not like 'email.%'
     or jsonb_typeof(coalesce(p_payload, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid Resend email event';
  end if;

  v_provider_event_id := left(btrim(p_provider_event_id), 255);
  v_provider_message_id := left(btrim(p_provider_message_id), 255);
  v_event_type := left(btrim(p_event_type), 80);

  -- The API worker takes the same message-scoped lock before attaching the
  -- provider id to email_logs. Serializing both sides closes the commit-order
  -- race where each transaction could otherwise miss the other's new row.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('resend:' || v_provider_message_id, 0)
  );

  select logs.id, logs.organization_id, logs.user_id
    into v_email_log_id, v_organization_id, v_user_id
  from public.email_logs logs
  where logs.provider = 'resend'
    and logs.provider_message_id = v_provider_message_id
  limit 1
  for update;

  insert into public.email_delivery_events (
    email_log_id,
    organization_id,
    user_id,
    provider,
    provider_event_id,
    provider_message_id,
    event_type,
    occurred_at,
    payload,
    reconciled_at
  )
  values (
    v_email_log_id,
    v_organization_id,
    v_user_id,
    'resend',
    v_provider_event_id,
    v_provider_message_id,
    v_event_type,
    coalesce(p_occurred_at, now()),
    coalesce(p_payload, '{}'::jsonb),
    case when v_email_log_id is not null then now() else null end
  )
  on conflict (provider, provider_event_id) do nothing
  returning id into v_event_id;

  if v_email_log_id is not null then
    perform private.reconcile_resend_email_events_for_log(v_email_log_id);
  end if;

  return v_event_id is not null;
end;
$$;


ALTER FUNCTION public.record_resend_email_event(p_provider_event_id text, p_provider_message_id text, p_event_type text, p_occurred_at timestamp with time zone, p_payload jsonb) OWNER TO postgres;

--
-- Name: record_whatsapp_webhook_contact_pn_quarantine(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_whatsapp_webhook_contact_pn_quarantine(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid, p_provider_message_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_event_key text;
begin
  select inbox.event_key into v_event_key from public.whatsapp_webhook_inbox inbox
  where inbox.id=p_inbox_id and inbox.organization_id=p_organization_id and inbox.session_id=p_session_id
    and inbox.status='processing' and inbox.edge_execution_id=p_execution_id
    and inbox.edge_execution_state='active' and p_execution_id is not null
    and inbox.processing_epoch=coalesce((select cutover.active_epoch from private.whatsapp_webhook_session_cutovers cutover
      where cutover.session_id=inbox.session_id),0)
    and exists(select 1 from pg_catalog.jsonb_array_elements(
      case when pg_catalog.jsonb_typeof(inbox.payload#>'{__vimob_ingress,routing_snapshot,messages}')='array'
        then inbox.payload#>'{__vimob_ingress,routing_snapshot,messages}' else '[]'::jsonb end
    ) route(snapshot_value) where route.snapshot_value->>'provider_message_id'=p_provider_message_id
      and exists(select 1 from public.whatsapp_webhook_routing_snapshots snapshot
        where snapshot.organization_id=inbox.organization_id and snapshot.session_id=inbox.session_id
          and snapshot.processing_epoch=inbox.processing_epoch and snapshot.provider_message_id=p_provider_message_id
          and snapshot.snapshot=route.snapshot_value))
  for update of inbox;
  if v_event_key is null then
    raise exception using errcode='42501',message='whatsapp_contact_pn_quarantine_scope_invalid';
  end if;
  insert into private.whatsapp_webhook_ignored_events(organization_id,session_id,event_key,reason)
    values(p_organization_id,p_session_id,v_event_key,'whatsapp_contact_pn_route_conflict')
    on conflict(organization_id,session_id,event_key) do update set reason=excluded.reason;
  return true;
end;
$$;


ALTER FUNCTION public.record_whatsapp_webhook_contact_pn_quarantine(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid, p_provider_message_id text) OWNER TO postgres;

--
-- Name: recover_stuck_executions(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recover_stuck_executions(p_stale_minutes integer DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_count INT;
BEGIN
    WITH stuck AS (
        UPDATE public.automation_executions
        SET
            status = 'failed',
            error_message = 'Execução interrompida ou timeout (recuperado automaticamente)',
            completed_at = now(),
            lock_token = NULL,
            locked_at = NULL
        WHERE status = 'running'
          AND (
            (locked_at IS NOT NULL AND locked_at < now() - (p_stale_minutes || ' minutes')::interval)
            OR (locked_at IS NULL AND started_at < now() - (p_stale_minutes || ' minutes')::interval)
          )
        RETURNING id
    )
    SELECT count(*) INTO v_count FROM stuck;

    RETURN v_count;
END;
$$;


ALTER FUNCTION public.recover_stuck_executions(p_stale_minutes integer) OWNER TO postgres;

--
-- Name: redistribute_lead_from_pool(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.redistribute_lead_from_pool(p_lead_id uuid, p_reason text DEFAULT 'timeout'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead public.leads%ROWTYPE;
  v_pipeline public.pipelines%ROWTYPE;
  v_assignment record;
  v_assignment_at timestamptz;
  v_old_user_id uuid;
  v_result jsonb;
  v_history_id uuid;
  v_has_blocking_activity boolean;
BEGIN
  SELECT * INTO v_lead
  FROM public.leads
  WHERE id = p_lead_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'reason', 'lead_not_found');
  END IF;

  v_old_user_id := v_lead.assigned_user_id;

  IF v_old_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'lead_without_owner');
  END IF;

  IF lower(COALESCE(v_lead.deal_status, 'open')) IN ('won', 'ganho', 'lost', 'perdido', 'closed', 'fechado') THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'closed_deal_status');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stages s
    WHERE s.id = v_lead.stage_id
      AND (COALESCE(s.is_won, false) OR COALESCE(s.is_lost, false))
  ) THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'closed_stage');
  END IF;

  SELECT * INTO v_pipeline
  FROM public.pipelines p
  WHERE p.id = v_lead.pipeline_id
    AND COALESCE(p.pool_enabled, false) = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'pool_disabled_for_pipeline');
  END IF;

  SELECT al.* INTO v_assignment
  FROM public.assignments_log al
  WHERE al.lead_id = p_lead_id
    AND al.assigned_user_id = v_old_user_id
    AND al.round_robin_id IS NOT NULL
    AND COALESCE(al.reason, '') IN ('round_robin_auto', 'round_robin')
  ORDER BY COALESCE(al.assigned_at, al.created_at) DESC, al.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'lead_not_assigned_by_distribution_queue');
  END IF;

  v_assignment_at := COALESCE(v_assignment.assigned_at, v_assignment.created_at, v_lead.assigned_at, v_lead.created_at);

  IF v_pipeline.pool_enabled_at IS NOT NULL AND v_assignment_at < v_pipeline.pool_enabled_at THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'lead_assigned_before_pool_enabled');
  END IF;

  v_has_blocking_activity := false;

  IF v_lead.first_response_at IS NOT NULL AND v_lead.first_response_at >= v_assignment_at - interval '5 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_lead.first_touch_at IS NOT NULL AND v_lead.first_touch_at >= v_assignment_at - interval '5 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_lead.owner_last_activity_at IS NOT NULL AND v_lead.owner_last_activity_at >= v_assignment_at - interval '5 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_lead.last_contact_at IS NOT NULL AND v_lead.last_contact_at >= v_assignment_at - interval '5 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_lead.stage_entered_at IS NOT NULL AND v_lead.stage_entered_at > v_assignment_at + interval '10 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.lead_timeline_events e
    WHERE e.lead_id = p_lead_id
      AND e.created_at >= v_assignment_at - interval '5 seconds'
      AND e.event_type NOT IN ('lead_created', 'lead_assigned')
  ) THEN
    v_has_blocking_activity := true;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.whatsapp_messages wm
    WHERE wm.lead_id = p_lead_id
      AND wm.created_at >= v_assignment_at - interval '5 seconds'
      AND (COALESCE(wm.from_me, false) = true OR wm.sender_user_id IS NOT NULL)
  ) THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_has_blocking_activity THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'lead_has_activity_after_distribution');
  END IF;

  INSERT INTO public.lead_pool_history (lead_id, organization_id, from_user_id, reason)
  VALUES (p_lead_id, v_lead.organization_id, v_old_user_id, p_reason)
  RETURNING id INTO v_history_id;

  UPDATE public.leads
  SET assigned_user_id = NULL,
      assigned_at = NULL,
      redistribution_count = COALESCE(redistribution_count, 0) + 1,
      last_redistributed_at = now(),
      redistribution_warning_sent_at = NULL,
      updated_at = now()
  WHERE id = p_lead_id;

  SELECT public.handle_lead_intake(p_lead_id) INTO v_result;

  IF v_result->>'assigned_user_id' IS NOT NULL THEN
    UPDATE public.lead_pool_history
    SET to_user_id = (v_result->>'assigned_user_id')::uuid
    WHERE id = v_history_id;
  END IF;

  IF v_old_user_id IS NOT NULL THEN
    PERFORM public.create_notification(
      v_old_user_id,
      v_lead.organization_id,
      'Lead redistribuído',
      'O lead "' || COALESCE(v_lead.name, 'sem nome') || '" foi redistribuído por inatividade.',
      'warning',
      p_lead_id
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'lead_id', p_lead_id,
    'from_user_id', v_old_user_id,
    'to_user_id', v_result->>'assigned_user_id',
    'redistribution_count', COALESCE(v_lead.redistribution_count, 0) + 1
  );
END;
$$;


ALTER FUNCTION public.redistribute_lead_from_pool(p_lead_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: redistribute_lead_from_pool_backend(uuid, uuid, text, uuid, uuid, timestamp with time zone, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.redistribute_lead_from_pool_backend(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid, p_expected_assigned_user_id uuid, p_expected_assigned_at timestamp with time zone, p_expected_redistribution_count integer, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lead public.leads%rowtype;
  v_pipeline public.pipelines%rowtype;
  v_assignment record;
  v_existing_event private.lead_distribution_events%rowtype;
  v_result jsonb;
  v_event_id uuid;
  v_assigned_user_id uuid;
  v_assignment_at timestamptz;
  v_has_blocking_activity boolean := false;
  v_recover_existing boolean := false;
  v_counter_applied boolean := false;
  v_counter_rows integer := 0;
begin
  p_now := coalesce(p_now, clock_timestamp());

  if p_organization_id is null
     or p_lead_id is null
     or p_round_robin_id is null
     or p_expected_assigned_user_id is null
     or p_expected_assigned_at is null
     or p_expected_redistribution_count is null
     or p_expected_redistribution_count < 0
     or p_idempotency_key is null
     or length(btrim(p_idempotency_key)) not between 1 and 200
     or p_idempotency_key <> btrim(p_idempotency_key) then
    raise exception using
      errcode = '22023',
      message = 'invalid_pool_redistribution_request';
  end if;

  select event.*
  into v_existing_event
  from private.lead_distribution_events as event
  where event.organization_id = p_organization_id
    and event.idempotency_key = p_idempotency_key;

  if found then
    if v_existing_event.lead_id <> p_lead_id then
      return jsonb_build_object(
        'success', false,
        'reason', 'idempotency_key_conflict',
        'lead_id', p_lead_id
      );
    end if;

    if coalesce((v_existing_event.result->>'pool_finalized')::boolean, false)
       or coalesce((v_existing_event.result->>'success')::boolean, false) = false then
      return v_existing_event.result || jsonb_build_object('replayed', true);
    end if;

    v_result := v_existing_event.result;
    v_recover_existing := true;
  end if;

  select lead.*
  into v_lead
  from public.leads as lead
  where lead.id = p_lead_id
    and lead.organization_id = p_organization_id
  for update;

  if not found then
    return jsonb_build_object(
      'success', false,
      'skipped', true,
      'reason', 'lead_not_found',
      'lead_id', p_lead_id
    );
  end if;

  -- A concurrent request may have committed while this transaction waited for
  -- the lead lock. Always re-read the durable event, including recovery calls
  -- that already observed an unfinished event before waiting. Otherwise two
  -- recoveries can both finalize the same ledger row and the loser can replace
  -- the successful result with a stale `pool_counter_applied = false` value.
  select event.*
  into v_existing_event
  from private.lead_distribution_events as event
  where event.organization_id = p_organization_id
    and event.idempotency_key = p_idempotency_key;

  if found then
    if v_existing_event.lead_id <> p_lead_id then
      return jsonb_build_object(
        'success', false,
        'reason', 'idempotency_key_conflict',
        'lead_id', p_lead_id
      );
    end if;

    if coalesce((v_existing_event.result->>'pool_finalized')::boolean, false)
       or coalesce((v_existing_event.result->>'success')::boolean, false) = false then
      return v_existing_event.result || jsonb_build_object('replayed', true);
    end if;

    v_result := v_existing_event.result;
    v_recover_existing := true;
  else
    v_result := null;
    v_recover_existing := false;
  end if;

  if not v_recover_existing then
    if v_lead.assigned_user_id is distinct from p_expected_assigned_user_id
       or v_lead.assigned_at is distinct from p_expected_assigned_at
       or coalesce(v_lead.redistribution_count, 0) <> p_expected_redistribution_count then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'stale_pool_candidate',
        'lead_id', p_lead_id
      );
    end if;

    if lower(coalesce(v_lead.deal_status, 'open')) in (
      'won', 'ganho', 'lost', 'perdido', 'closed', 'fechado'
    ) then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'closed_deal_status',
        'lead_id', p_lead_id
      );
    end if;

    if exists (
      select 1
      from public.stages as stage
      where stage.id = v_lead.stage_id
        and stage.organization_id = p_organization_id
        and (coalesce(stage.is_won, false) or coalesce(stage.is_lost, false))
    ) then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'closed_stage',
        'lead_id', p_lead_id
      );
    end if;

    select pipeline.*
    into v_pipeline
    from public.pipelines as pipeline
    where pipeline.id = v_lead.pipeline_id
      and pipeline.organization_id = p_organization_id
      and coalesce(pipeline.pool_enabled, false) = true;

    if not found then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'pool_disabled_for_pipeline',
        'lead_id', p_lead_id
      );
    end if;

    select assignment.*
    into v_assignment
    from public.assignments_log as assignment
    where assignment.organization_id = p_organization_id
      and assignment.lead_id = p_lead_id
      and assignment.assigned_user_id = p_expected_assigned_user_id
      and assignment.round_robin_id = p_round_robin_id
      and coalesce(assignment.reason, '') in (
        'round_robin_auto',
        'round_robin',
        'canonical_round_robin'
      )
    order by
      coalesce(assignment.assigned_at, assignment.created_at) desc,
      assignment.created_at desc,
      assignment.id desc
    limit 1;

    if not found then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'lead_not_assigned_by_distribution_queue',
        'lead_id', p_lead_id
      );
    end if;

    v_assignment_at := coalesce(
      v_assignment.assigned_at,
      v_assignment.created_at,
      v_lead.assigned_at,
      v_lead.created_at
    );

    if v_pipeline.pool_enabled_at is not null
       and v_assignment_at < v_pipeline.pool_enabled_at then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'lead_assigned_before_pool_enabled',
        'lead_id', p_lead_id
      );
    end if;

    if coalesce(v_pipeline.pool_max_redistributions, 3) > 0
       and p_expected_redistribution_count >= v_pipeline.pool_max_redistributions then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'pool_redistribution_limit_reached',
        'lead_id', p_lead_id
      );
    end if;

    if v_assignment_at >= p_now
      - make_interval(mins => greatest(coalesce(v_pipeline.pool_timeout_minutes, 10), 1)) then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'pool_timeout_not_reached',
        'lead_id', p_lead_id
      );
    end if;

    v_has_blocking_activity :=
      (v_lead.first_response_at is not null and v_lead.first_response_at >= v_assignment_at - interval '5 seconds')
      or (v_lead.first_touch_at is not null and v_lead.first_touch_at >= v_assignment_at - interval '5 seconds')
      or (v_lead.owner_last_activity_at is not null and v_lead.owner_last_activity_at >= v_assignment_at - interval '5 seconds')
      or (v_lead.last_contact_at is not null and v_lead.last_contact_at >= v_assignment_at - interval '5 seconds')
      or (v_lead.stage_entered_at is not null and v_lead.stage_entered_at > v_assignment_at + interval '10 seconds');

    if not v_has_blocking_activity then
      select exists (
        select 1
        from public.lead_timeline_events as timeline
        where timeline.organization_id = p_organization_id
          and timeline.lead_id = p_lead_id
          and timeline.created_at >= v_assignment_at - interval '5 seconds'
          and timeline.event_type = any (array[
            'whatsapp_message_sent',
            'first_response',
            'call_initiated',
            'call_completed',
            'note_created',
            'stage_changed',
            'agenda_created',
            'agenda_rescheduled',
            'agenda_completed',
            'agenda_cancelled',
            'schedule_comment'
          ]::text[])
      )
      into v_has_blocking_activity;
    end if;

    if not v_has_blocking_activity then
      select exists (
        select 1
        from public.whatsapp_messages as message
        where message.organization_id = p_organization_id
          and message.lead_id = p_lead_id
          and message.created_at >= v_assignment_at - interval '5 seconds'
          and (coalesce(message.from_me, false) = true or message.sender_user_id is not null)
      )
      into v_has_blocking_activity;
    end if;

    if v_has_blocking_activity then
      return jsonb_build_object(
        'success', false,
        'skipped', true,
        'reason', 'lead_has_activity_after_distribution',
        'lead_id', p_lead_id
      );
    end if;

    v_result := private.distribute_lead(
      p_organization_id,
      p_lead_id,
      p_idempotency_key,
      p_round_robin_id,
      false,
      'pool',
      p_now
    );

    if coalesce((v_result->>'success')::boolean, false) = false then
      return v_result;
    end if;
  end if;

  v_event_id := nullif(v_result->>'distribution_event_id', '')::uuid;
  v_assigned_user_id := nullif(v_result->>'assigned_user_id', '')::uuid;

  if v_event_id is null or v_assigned_user_id is null then
    raise exception using
      errcode = '55000',
      message = 'canonical_pool_distribution_result_incomplete';
  end if;

  if v_recover_existing then
    update public.leads as lead
    set redistribution_count = p_expected_redistribution_count + 1,
        last_redistributed_at = case
          when lead.last_redistributed_at is null
            or lead.last_redistributed_at < coalesce(v_existing_event.completed_at, p_now)
          then coalesce(v_existing_event.completed_at, p_now)
          else lead.last_redistributed_at
        end,
        redistribution_warning_sent_at = case
          when lead.assigned_user_id = v_assigned_user_id then null
          else lead.redistribution_warning_sent_at
        end,
        updated_at = clock_timestamp()
    where lead.id = p_lead_id
      and lead.organization_id = p_organization_id
      and coalesce(lead.redistribution_count, 0) = p_expected_redistribution_count;

    get diagnostics v_counter_rows = row_count;
    v_counter_applied := v_counter_rows > 0;

    if not v_counter_applied then
      select coalesce(lead.redistribution_count, 0) >=
        p_expected_redistribution_count + 1
      into v_counter_applied
      from public.leads as lead
      where lead.id = p_lead_id
        and lead.organization_id = p_organization_id;
    end if;

    if not coalesce(v_counter_applied, false) then
      raise exception using
        errcode = '40001',
        message = 'legacy_pool_counter_reconciliation_failed';
    end if;
  else
    update public.leads as lead
    set redistribution_count = coalesce(lead.redistribution_count, 0) + 1,
        last_redistributed_at = p_now,
        redistribution_warning_sent_at = null,
        updated_at = p_now
    where lead.id = p_lead_id
      and lead.organization_id = p_organization_id;

    v_counter_applied := true;
  end if;

  insert into public.lead_pool_history (
    id,
    lead_id,
    organization_id,
    from_user_id,
    to_user_id,
    reason,
    redistributed_at
  )
  values (
    v_event_id,
    p_lead_id,
    p_organization_id,
    p_expected_assigned_user_id,
    v_assigned_user_id,
    'timeout',
    coalesce(v_existing_event.completed_at, p_now)
  )
  on conflict (id) do nothing;

  insert into public.notifications (
    id,
    organization_id,
    user_id,
    lead_id,
    type,
    title,
    content,
    is_read,
    metadata,
    channel,
    target_url,
    created_at
  )
  values (
    v_event_id,
    p_organization_id,
    p_expected_assigned_user_id,
    p_lead_id,
    'lead_redistributed',
    'Lead redistribuído',
    'O lead "' || coalesce(nullif(v_lead.name, ''), 'sem nome')
      || '" foi redistribuído por inatividade.',
    false,
    jsonb_build_object(
      'event_key', 'lead_redistributed',
      'dedupe_key', 'lead_redistributed:' || v_event_id::text,
      'distribution_event_id', v_event_id,
      'from_user_id', p_expected_assigned_user_id,
      'to_user_id', v_assigned_user_id
    ),
    'in_app',
    '/crm/pipelines?lead=' || p_lead_id::text,
    coalesce(v_existing_event.completed_at, p_now)
  )
  on conflict do nothing;

  v_result := v_result || jsonb_build_object(
    'pool_finalized', true,
    'pool_counter_applied', v_counter_applied,
    'replayed', v_recover_existing,
    'from_user_id', p_expected_assigned_user_id,
    'to_user_id', v_assigned_user_id,
    'redistribution_count', p_expected_redistribution_count + 1
  );

  update private.lead_distribution_events as event
  set result = v_result
  where event.id = v_event_id
    and event.organization_id = p_organization_id
    and event.lead_id = p_lead_id;

  if not found then
    raise exception using
      errcode = '55000',
      message = 'canonical_pool_distribution_event_not_found';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION public.redistribute_lead_from_pool_backend(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid, p_expected_assigned_user_id uuid, p_expected_assigned_at timestamp with time zone, p_expected_redistribution_count integer, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION redistribute_lead_from_pool_backend(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid, p_expected_assigned_user_id uuid, p_expected_assigned_at timestamp with time zone, p_expected_redistribution_count integer, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.redistribute_lead_from_pool_backend(p_organization_id uuid, p_lead_id uuid, p_idempotency_key text, p_round_robin_id uuid, p_expected_assigned_user_id uuid, p_expected_assigned_at timestamp with time zone, p_expected_redistribution_count integer, p_now timestamp with time zone) IS 'Backend-only atomic pool redistribution through private.distribute_lead, including counter, history and former-owner notification.';


--
-- Name: redistribute_lead_round_robin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.redistribute_lead_round_robin(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_previous_assigned_user_id uuid;
  v_transfer_result public.leads;
  v_distribution_result jsonb;
BEGIN
  SELECT assigned_user_id
  INTO v_previous_assigned_user_id
  FROM public.leads
  WHERE id = p_lead_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead not found';
  END IF;

  SELECT *
  INTO v_transfer_result
  FROM public.transfer_lead_assignee(p_lead_id, NULL);

  SELECT public.handle_lead_intake(p_lead_id)
  INTO v_distribution_result;

  RETURN jsonb_build_object(
    'previous_assigned_user_id', v_previous_assigned_user_id,
    'lead_id', p_lead_id,
    'distribution_result', v_distribution_result
  );
END;
$$;


ALTER FUNCTION public.redistribute_lead_round_robin(p_lead_id uuid) OWNER TO postgres;

--
-- Name: refresh_help_article_search_vector(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_help_article_search_vector() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  accent_chars constant text := 'áàâãäéèêëíìîïóòôõöúùûüçñ';
  plain_chars constant text := 'aaaaaeeeeiiiiooooouuuucn';
  title_text text := coalesce(new.title, '');
  summary_keywords_text text := coalesce(new.summary, '') || ' ' ||
    coalesce(pg_catalog.array_to_string(new.search_keywords, ' '), '');
  content_text text := coalesce(new.category, '') || ' ' ||
    coalesce(new.content, '') || ' ' || coalesce(new.steps::text, '');
begin
  new.search_vector :=
    pg_catalog.setweight(
      pg_catalog.to_tsvector(
        'portuguese'::pg_catalog.regconfig,
        title_text || ' ' ||
        pg_catalog.translate(pg_catalog.lower(title_text), accent_chars, plain_chars)
      ),
      'A'
    )
    ||
    pg_catalog.setweight(
      pg_catalog.to_tsvector(
        'portuguese'::pg_catalog.regconfig,
        summary_keywords_text || ' ' ||
        pg_catalog.translate(
          pg_catalog.lower(summary_keywords_text),
          accent_chars,
          plain_chars
        )
      ),
      'B'
    )
    ||
    pg_catalog.setweight(
      pg_catalog.to_tsvector(
        'portuguese'::pg_catalog.regconfig,
        content_text || ' ' ||
        pg_catalog.translate(pg_catalog.lower(content_text), accent_chars, plain_chars)
      ),
      'C'
    );
  return new;
end;
$$;


ALTER FUNCTION public.refresh_help_article_search_vector() OWNER TO postgres;

--
-- Name: register_billing_checkout_provider(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_billing_checkout_provider(p_intent_id uuid, p_customer_id text, p_payment_id text DEFAULT NULL::text, p_subscription_id text DEFAULT NULL::text, p_provider_response jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_intent private.billing_checkout_intents%rowtype;
  v_customer_id text := nullif(btrim(coalesce(p_customer_id, '')), '');
  v_payment_id text := nullif(btrim(coalesce(p_payment_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_subscription_id, '')), '');
  v_existing_customer_id text;
  v_existing_subscription_id text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  if p_intent_id is null or v_customer_id is null
     or jsonb_typeof(coalesce(p_provider_response, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid billing provider registration'
      using errcode = '22023';
  end if;

  perform private.lock_asaas_billing_resources(
    v_payment_id,
    v_subscription_id
  );

  select *
  into v_intent
  from private.billing_checkout_intents
  where id = p_intent_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  if (v_intent.billing_method in ('PIX', 'BOLETO') and v_payment_id is null)
     or (v_intent.billing_method = 'CREDIT_CARD' and v_subscription_id is null) then
    raise exception 'provider resource does not match billing method'
      using errcode = '22023';
  end if;

  if v_intent.provider_payment_id is not null
     and v_payment_id is distinct from v_intent.provider_payment_id then
    raise exception 'billing intent already has a different payment'
      using errcode = '22023';
  end if;

  if v_intent.provider_subscription_id is not null
     and v_subscription_id is distinct from v_intent.provider_subscription_id then
    raise exception 'billing intent already has a different subscription'
      using errcode = '22023';
  end if;

  if v_intent.status not in ('creating', 'pending', 'confirmed') then
    return jsonb_build_object('outcome', 'intent_not_registerable');
  end if;

  select asaas_customer_id, asaas_subscription_id
  into v_existing_customer_id, v_existing_subscription_id
  from public.organizations
  where id = v_intent.organization_id
  for update;

  if v_existing_customer_id is not null
     and btrim(v_existing_customer_id) <> v_customer_id then
    raise exception 'organization already has a different Asaas customer'
      using errcode = '22023';
  end if;

  if v_subscription_id is not null
     and v_existing_subscription_id is not null
     and btrim(v_existing_subscription_id) <> v_subscription_id then
    raise exception 'organization already has a different Asaas subscription'
      using errcode = '22023';
  end if;

  update private.billing_checkout_intents
  set
    status = case when status = 'confirmed' then status else 'pending' end,
    provider_customer_id = v_customer_id,
    provider_payment_id = coalesce(v_payment_id, provider_payment_id),
    provider_subscription_id = coalesce(v_subscription_id, provider_subscription_id),
    provider_response = coalesce(p_provider_response, '{}'::jsonb),
    provider_registered_at = coalesce(provider_registered_at, now()),
    last_error = null,
    updated_at = now()
  where id = p_intent_id;

  update public.organizations
  set
    asaas_customer_id = coalesce(asaas_customer_id, v_customer_id),
    asaas_subscription_id = coalesce(asaas_subscription_id, v_subscription_id),
    updated_at = now()
  where id = v_intent.organization_id;

  update public.subscriptions
  set
    provider = 'asaas',
    provider_customer_id = coalesce(provider_customer_id, v_customer_id),
    provider_subscription_id = coalesce(provider_subscription_id, v_subscription_id),
    updated_at = now()
  where organization_id = v_intent.organization_id;

  -- A fast webhook can persist the paid invoice before the Edge Function has
  -- stored the provider id on this intent. Binding the already-seen invoice
  -- re-fires the confirmation trigger and closes that race atomically.
  update public.asaas_payments
  set
    billing_intent_id = p_intent_id,
    updated_at = now()
  where organization_id = v_intent.organization_id
    and (
      (v_payment_id is not null and asaas_payment_id = v_payment_id)
      or (
        v_subscription_id is not null
        and asaas_subscription_id = v_subscription_id
      )
    )
    and billing_intent_id is distinct from p_intent_id;

  return jsonb_build_object(
    'outcome',
    case when v_intent.status = 'pending' then 'reused' else 'registered' end,
    'intent_id', p_intent_id,
    'organization_id', v_intent.organization_id,
    'provider_payment_id', v_payment_id,
    'provider_subscription_id', v_subscription_id
  );
end;
$$;


ALTER FUNCTION public.register_billing_checkout_provider(p_intent_id uuid, p_customer_id text, p_payment_id text, p_subscription_id text, p_provider_response jsonb) OWNER TO postgres;

--
-- Name: register_billing_hosted_checkout(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_billing_hosted_checkout(p_intent_id uuid, p_checkout_id text, p_provider_response jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_intent private.billing_checkout_intents%rowtype;
  v_checkout_id text := nullif(btrim(coalesce(p_checkout_id, '')), '');
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  if p_intent_id is null
     or v_checkout_id is null
     or jsonb_typeof(coalesce(p_provider_response, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid hosted checkout registration'
      using errcode = '22023';
  end if;

  select *
  into v_intent
  from private.billing_checkout_intents
  where id = p_intent_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  if v_intent.billing_method <> 'CREDIT_CARD' then
    raise exception 'hosted checkout requires credit card billing intent'
      using errcode = '22023';
  end if;

  if v_intent.provider_checkout_id is not null
     and v_intent.provider_checkout_id <> v_checkout_id then
    raise exception 'billing intent already has a different checkout'
      using errcode = '22023';
  end if;

  if v_intent.status not in ('creating', 'pending', 'confirmed') then
    return jsonb_build_object('outcome', 'intent_not_registerable');
  end if;

  update private.billing_checkout_intents
  set
    status = case when status = 'confirmed' then status else 'pending' end,
    provider_checkout_id = v_checkout_id,
    provider_response = coalesce(p_provider_response, '{}'::jsonb),
    provider_registered_at = coalesce(provider_registered_at, now()),
    last_error = null,
    updated_at = now()
  where id = p_intent_id;

  return jsonb_build_object(
    'outcome',
    case when v_intent.status = 'pending' then 'reused' else 'registered' end,
    'intent_id', p_intent_id,
    'organization_id', v_intent.organization_id,
    'provider_checkout_id', v_checkout_id
  );
end;
$$;


ALTER FUNCTION public.register_billing_hosted_checkout(p_intent_id uuid, p_checkout_id text, p_provider_response jsonb) OWNER TO postgres;

--
-- Name: register_lead_reentry(uuid, uuid, text, text, text, text, text, text, uuid, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_lead_reentry(p_lead_id uuid, p_org_id uuid, p_entry_type text DEFAULT 'reentry'::text, p_source text DEFAULT NULL::text, p_campaign_name text DEFAULT NULL::text, p_utm_source text DEFAULT NULL::text, p_utm_medium text DEFAULT NULL::text, p_utm_campaign text DEFAULT NULL::text, p_property_id uuid DEFAULT NULL::uuid, p_valor_interesse numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
begin
  if not exists (
    select 1
    from public.leads
    where id = p_lead_id
      and organization_id = p_org_id
  ) then
    raise exception 'lead does not belong to organization';
  end if;

  insert into public.lead_entry_events (
    lead_id,
    organization_id,
    entry_type,
    source,
    provider,
    occurred_at,
    campaign_id,
    campaign_name,
    adset_id,
    adset_name,
    ad_id,
    ad_name,
    form_id,
    form_name,
    page_id,
    page_name,
    utm_source,
    utm_medium,
    utm_campaign,
    utm_content,
    utm_term,
    property_id,
    valor_interesse,
    metadata
  )
  values (
    p_lead_id,
    p_org_id,
    p_entry_type,
    p_source,
    coalesce(nullif(lower(p_metadata->>'provider'), ''), 'manual'),
    now(),
    nullif(p_metadata->>'campaign_id', ''),
    coalesce(nullif(p_campaign_name, ''), nullif(p_metadata->>'campaign_name', '')),
    nullif(p_metadata->>'adset_id', ''),
    nullif(p_metadata->>'adset_name', ''),
    nullif(p_metadata->>'ad_id', ''),
    nullif(p_metadata->>'ad_name', ''),
    nullif(p_metadata->>'form_id', ''),
    nullif(p_metadata->>'form_name', ''),
    nullif(p_metadata->>'page_id', ''),
    nullif(p_metadata->>'page_name', ''),
    p_utm_source,
    p_utm_medium,
    p_utm_campaign,
    nullif(p_metadata->>'utm_content', ''),
    nullif(p_metadata->>'utm_term', ''),
    p_property_id,
    p_valor_interesse,
    coalesce(p_metadata, '{}'::jsonb)
  );

  update public.leads
  set
    reentry_count = coalesce(reentry_count, 0) + 1,
    last_entry_at = now(),
    source = coalesce(source, p_source),
    interest_property_id = coalesce(p_property_id, interest_property_id),
    valor_interesse = coalesce(p_valor_interesse, valor_interesse),
    updated_at = now()
  where id = p_lead_id
    and organization_id = p_org_id;
end;
$$;


ALTER FUNCTION public.register_lead_reentry(p_lead_id uuid, p_org_id uuid, p_entry_type text, p_source text, p_campaign_name text, p_utm_source text, p_utm_medium text, p_utm_campaign text, p_property_id uuid, p_valor_interesse numeric, p_metadata jsonb) OWNER TO postgres;

--
-- Name: register_lead_reentry_from_backend(uuid, uuid, text, text, text, text, uuid, numeric, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_lead_reentry_from_backend(p_organization_id uuid, p_lead_id uuid, p_provider text, p_provider_event_id text DEFAULT NULL::text, p_source text DEFAULT NULL::text, p_entry_subtype text DEFAULT 'reentry'::text, p_property_id uuid DEFAULT NULL::uuid, p_valor_interesse numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb, p_occurred_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lead public.leads%rowtype;
  v_provider text;
  v_provider_event_id text;
  v_event_id uuid;
  v_existing_lead_id uuid;
  v_inserted boolean := false;
  v_metadata jsonb;
begin
  p_occurred_at := coalesce(p_occurred_at, clock_timestamp());
  v_provider := regexp_replace(
    lower(btrim(coalesce(p_provider, ''))),
    '[^a-z0-9_-]+',
    '_',
    'g'
  );
  v_provider_event_id := nullif(btrim(coalesce(p_provider_event_id, '')), '');

  if p_organization_id is null
     or p_lead_id is null
     or length(v_provider) not between 1 and 64
     or (
       v_provider_event_id is not null
       and length(v_provider_event_id) > 200
     ) then
    raise exception using
      errcode = '22023',
      message = 'invalid_lead_reentry_request';
  end if;

  select lead.*
  into v_lead
  from public.leads as lead
  where lead.id = p_lead_id
    and lead.organization_id = p_organization_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'lead_reentry_target_not_found';
  end if;

  v_metadata := coalesce(p_metadata, '{}'::jsonb)
    || jsonb_strip_nulls(jsonb_build_object(
      'entry_subtype', coalesce(nullif(btrim(p_entry_subtype), ''), 'reentry'),
      'provider_event_id', v_provider_event_id
    ));

  if v_provider_event_id is null then
    insert into public.lead_entry_events (
      lead_id,
      organization_id,
      entry_type,
      source,
      provider,
      occurred_at,
      pipeline_id,
      stage_id,
      campaign_id,
      campaign_name,
      adset_id,
      adset_name,
      ad_id,
      ad_name,
      form_id,
      form_name,
      page_id,
      page_name,
      utm_source,
      utm_medium,
      utm_campaign,
      utm_content,
      utm_term,
      property_id,
      valor_interesse,
      metadata
    )
    values (
      p_lead_id,
      p_organization_id,
      'reentry',
      p_source,
      v_provider,
      p_occurred_at,
      v_lead.pipeline_id,
      v_lead.stage_id,
      nullif(v_metadata->>'campaign_id', ''),
      nullif(v_metadata->>'campaign_name', ''),
      nullif(v_metadata->>'adset_id', ''),
      nullif(v_metadata->>'adset_name', ''),
      nullif(v_metadata->>'ad_id', ''),
      nullif(v_metadata->>'ad_name', ''),
      nullif(v_metadata->>'form_id', ''),
      nullif(v_metadata->>'form_name', ''),
      nullif(v_metadata->>'page_id', ''),
      nullif(v_metadata->>'page_name', ''),
      nullif(v_metadata->>'utm_source', ''),
      nullif(v_metadata->>'utm_medium', ''),
      nullif(v_metadata->>'utm_campaign', ''),
      nullif(v_metadata->>'utm_content', ''),
      nullif(v_metadata->>'utm_term', ''),
      p_property_id,
      p_valor_interesse,
      v_metadata
    )
    returning id into v_event_id;

    v_inserted := true;
  else
    insert into public.lead_entry_events (
      lead_id,
      organization_id,
      entry_type,
      source,
      provider,
      provider_event_id,
      occurred_at,
      pipeline_id,
      stage_id,
      campaign_id,
      campaign_name,
      adset_id,
      adset_name,
      ad_id,
      ad_name,
      form_id,
      form_name,
      page_id,
      page_name,
      utm_source,
      utm_medium,
      utm_campaign,
      utm_content,
      utm_term,
      property_id,
      valor_interesse,
      metadata
    )
    values (
      p_lead_id,
      p_organization_id,
      'reentry',
      p_source,
      v_provider,
      v_provider_event_id,
      p_occurred_at,
      v_lead.pipeline_id,
      v_lead.stage_id,
      nullif(v_metadata->>'campaign_id', ''),
      nullif(v_metadata->>'campaign_name', ''),
      nullif(v_metadata->>'adset_id', ''),
      nullif(v_metadata->>'adset_name', ''),
      nullif(v_metadata->>'ad_id', ''),
      nullif(v_metadata->>'ad_name', ''),
      nullif(v_metadata->>'form_id', ''),
      nullif(v_metadata->>'form_name', ''),
      nullif(v_metadata->>'page_id', ''),
      nullif(v_metadata->>'page_name', ''),
      nullif(v_metadata->>'utm_source', ''),
      nullif(v_metadata->>'utm_medium', ''),
      nullif(v_metadata->>'utm_campaign', ''),
      nullif(v_metadata->>'utm_content', ''),
      nullif(v_metadata->>'utm_term', ''),
      p_property_id,
      p_valor_interesse,
      v_metadata
    )
    on conflict (organization_id, provider, provider_event_id)
      where provider_event_id is not null and is_countable = true
    do nothing
    returning id into v_event_id;

    if v_event_id is null then
      select event.id, event.lead_id
      into v_event_id, v_existing_lead_id
      from public.lead_entry_events as event
      where event.organization_id = p_organization_id
        and event.provider = v_provider
        and event.provider_event_id = v_provider_event_id
        and event.is_countable = true;

      if v_event_id is null then
        raise exception using
          errcode = '40001',
          message = 'lead_reentry_idempotency_lookup_failed';
      end if;

      if v_existing_lead_id <> p_lead_id then
        raise exception using
          errcode = '23505',
          message = 'lead_reentry_idempotency_conflict';
      end if;
    else
      v_inserted := true;
    end if;
  end if;

  if v_inserted then
    update public.leads as lead
    set reentry_count = coalesce(lead.reentry_count, 0) + 1,
        last_entry_at = p_occurred_at,
        source = coalesce(lead.source, p_source),
        interest_property_id = coalesce(p_property_id, lead.interest_property_id),
        valor_interesse = coalesce(p_valor_interesse, lead.valor_interesse),
        updated_at = clock_timestamp()
    where lead.id = p_lead_id
      and lead.organization_id = p_organization_id;
  end if;

  return jsonb_build_object(
    'success', true,
    'event_id', v_event_id,
    'inserted', v_inserted,
    'replayed', not v_inserted
  );
end;
$$;


ALTER FUNCTION public.register_lead_reentry_from_backend(p_organization_id uuid, p_lead_id uuid, p_provider text, p_provider_event_id text, p_source text, p_entry_subtype text, p_property_id uuid, p_valor_interesse numeric, p_metadata jsonb, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION register_lead_reentry_from_backend(p_organization_id uuid, p_lead_id uuid, p_provider text, p_provider_event_id text, p_source text, p_entry_subtype text, p_property_id uuid, p_valor_interesse numeric, p_metadata jsonb, p_occurred_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.register_lead_reentry_from_backend(p_organization_id uuid, p_lead_id uuid, p_provider text, p_provider_event_id text, p_source text, p_entry_subtype text, p_property_id uuid, p_valor_interesse numeric, p_metadata jsonb, p_occurred_at timestamp with time zone) IS 'Backend-only lead reentry registrar. It returns the immutable entry-event ID and replays provider-key retries without incrementing reentry_count twice.';


--
-- Name: register_pending_asaas_subscription(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_pending_asaas_subscription(p_organization_id uuid, p_customer_id text, p_subscription_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_customer_id text := nullif(btrim(coalesce(p_customer_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_subscription_id, '')), '');
  v_updated integer := 0;
begin
  if p_organization_id is null or v_customer_id is null or v_subscription_id is null then
    raise exception using
      errcode = '22023',
      message = 'Organization, Asaas customer and subscription are required';
  end if;

  update public.organizations
  set
    subscription_status = case
      when asaas_customer_id = v_customer_id
        and asaas_subscription_id = v_subscription_id
        and asaas_last_event_id is not null
        then subscription_status
      else 'pending_payment'
    end,
    asaas_customer_id = v_customer_id,
    asaas_subscription_id = v_subscription_id,
    updated_at = now()
  where id = p_organization_id;

  get diagnostics v_updated = row_count;
  if v_updated = 0 then
    raise exception using
      errcode = 'P0002',
      message = 'Organization not found for Asaas subscription';
  end if;

  update public.subscriptions
  set
    status = case
      when provider_customer_id = v_customer_id
        and provider_subscription_id = v_subscription_id
        and coalesce(metadata, '{}'::jsonb) ? 'asaas_last_event_id'
        then status
      else 'pending_payment'
    end,
    provider = 'asaas',
    provider_customer_id = v_customer_id,
    provider_subscription_id = v_subscription_id,
    updated_at = now()
  where organization_id = p_organization_id;

  return jsonb_build_object(
    'outcome', 'registered',
    'organization_id', p_organization_id,
    'customer_id', v_customer_id,
    'subscription_id', v_subscription_id
  );
end;
$$;


ALTER FUNCTION public.register_pending_asaas_subscription(p_organization_id uuid, p_customer_id text, p_subscription_id text) OWNER TO postgres;

--
-- Name: release_billing_payment_checkout_attempt(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_billing_payment_checkout_attempt(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_released_payment_id uuid;
begin
  if p_payment_id is null
     or p_lease_id is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255 then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  -- The exact lease id prevents a late request from releasing a newer lease.
  update public.billing_payment_checkout_capabilities as capability
  set
    attempt_lease_id = null,
    attempt_lease_expires_at = null
  where capability.payment_id = p_payment_id
    and capability.asaas_payment_id = v_provider_payment_id
    and capability.attempt_lease_id = p_lease_id
  returning capability.payment_id into v_released_payment_id;

  if not found then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  return jsonb_build_object(
    'outcome', 'released',
    'payment_id', v_released_payment_id
  );
end
$$;


ALTER FUNCTION public.release_billing_payment_checkout_attempt(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION release_billing_payment_checkout_attempt(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.release_billing_payment_checkout_attempt(p_payment_id uuid, p_provider_payment_id text, p_lease_id uuid) IS 'Releases only the exact active card-attempt lease; rate-limit counters remain intact.';


--
-- Name: release_commissions_on_payment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_commissions_on_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.type = 'receivable'
     AND NEW.status = 'paid'
     AND COALESCE(OLD.status,'') <> 'paid'
     AND NEW.contract_id IS NOT NULL THEN

    UPDATE public.commissions
       SET status = 'pending',
           updated_at = now()
     WHERE contract_id = NEW.contract_id
       AND status = 'forecast';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.release_commissions_on_payment() OWNER TO postgres;

--
-- Name: release_due_automation_delays(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_due_automation_delays(p_batch_size integer DEFAULT 25) RETURNS SETOF public.automation_executions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  candidate record;
  resume_result jsonb;
begin
  for candidate in
    select e.id, e.organization_id
    from public.automation_executions e
    where e.status = 'waiting'
      and e.flow_version_id is not null
      and e.cancellation_requested_at is null
      and e.next_execution_at <= now()
      and exists (
        select 1 from public.organization_modules om
        where om.organization_id = e.organization_id
          and lower(trim(om.module_name)) = 'automations'
          and coalesce(om.is_enabled, false) = true
      )
    order by e.next_execution_at, e.id
    limit least(greatest(coalesce(p_batch_size, 25), 1), 100)
    for update skip locked
  loop
    resume_result := public.resume_automation_delay(
      candidate.organization_id,
      candidate.id,
      'elapsed',
      null,
      '{}'::jsonb,
      null,
      null
    );
    if coalesce((resume_result->>'ok')::boolean, false) then
      return query select e.* from public.automation_executions e where e.id = candidate.id;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION public.release_due_automation_delays(p_batch_size integer) OWNER TO postgres;

