-- Name: release_execution_step_lock(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_execution_step_lock(p_execution_id uuid, p_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
    UPDATE public.automation_executions
    SET
        lock_token = NULL,
        locked_at = NULL
    WHERE id = p_execution_id AND lock_token = p_token;
END;
$$;


