--
-- Name: reorder_stages(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reorder_stages(p_stages jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pipeline_id uuid;
  v_organization_id uuid;
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_stages is null or jsonb_typeof(p_stages) <> 'array' or jsonb_array_length(p_stages) = 0 then
    raise exception 'Stages payload must be a non-empty array';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_stages) as stage_item
    where nullif(stage_item->>'id', '') is null
      or nullif(stage_item->>'pipeline_id', '') is null
      or nullif(btrim(stage_item->>'name'), '') is null
      or nullif(stage_item->>'position', '') is null
  ) then
    raise exception 'Each stage requires id, pipeline_id, name, and position';
  end if;

  select distinct (stage_item->>'pipeline_id')::uuid
    into v_pipeline_id
  from jsonb_array_elements(p_stages) as stage_item;

  if v_pipeline_id is null then
    raise exception 'Pipeline id is required';
  end if;

  if (
    select count(distinct stage_item->>'pipeline_id')
    from jsonb_array_elements(p_stages) as stage_item
  ) <> 1 then
    raise exception 'All stages must belong to the same pipeline';
  end if;

  select p.organization_id
    into v_organization_id
  from public.pipelines p
  where p.id = v_pipeline_id
    and p.organization_id = public.get_user_organization_id();

  if v_organization_id is null then
    raise exception 'Pipeline not found';
  end if;

  if not (
    public.is_admin()
    or public.user_has_permission('settings_pipelines', v_user_id)
    or (
      public.is_team_leader(v_user_id)
      and public.is_pipeline_in_led_team(v_pipeline_id, v_user_id)
    )
  ) then
    raise exception 'Insufficient permission to manage pipeline stages';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_stages) as stage_item
    group by (stage_item->>'position')::int
    having count(*) > 1
  ) then
    raise exception 'Stage positions must be unique';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_stages) as stage_item
    join public.stages s on s.id = (stage_item->>'id')::uuid
    where s.pipeline_id <> v_pipeline_id
  ) then
    raise exception 'Cannot move stages between pipelines';
  end if;

  with parked as (
    select
      id,
      (-1000000000 - row_number() over (order by position, id))::integer as temporary_position
    from public.stages
    where pipeline_id = v_pipeline_id
  )
  update public.stages s
  set position = parked.temporary_position
  from parked
  where s.id = parked.id;

  insert into public.stages (
    id,
    pipeline_id,
    organization_id,
    name,
    color,
    position,
    stage_key
  )
  select
    (stage_item->>'id')::uuid,
    v_pipeline_id,
    v_organization_id,
    nullif(btrim(stage_item->>'name'), ''),
    coalesce(nullif(stage_item->>'color', ''), '#6b7280'),
    (stage_item->>'position')::int,
    coalesce(
      nullif(btrim(stage_item->>'stage_key'), ''),
      regexp_replace(
        lower(nullif(btrim(stage_item->>'name'), '')),
        '[^a-z0-9]+',
        '_',
        'g'
      )
    )
  from jsonb_array_elements(p_stages) as stage_item
  on conflict (id) do update set
    pipeline_id = excluded.pipeline_id,
    organization_id = excluded.organization_id,
    name = excluded.name,
    color = excluded.color,
    position = excluded.position,
    stage_key = excluded.stage_key;
end;
$$;


ALTER FUNCTION public.reorder_stages(p_stages jsonb) OWNER TO postgres;

--
-- Name: reserve_automation_external_effect(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_automation_external_effect(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_effect_key text, p_effect_type text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  effect_id uuid;
  current_status text;
begin
  if not exists (
    select 1 from public.automation_executions e
    join public.organization_modules om
      on om.organization_id = e.organization_id
     and lower(trim(om.module_name)) = 'automations'
     and coalesce(om.is_enabled, false) = true
    where e.id = p_execution_id
      and e.organization_id = p_organization_id
      and e.current_node_key = p_node_key
      and e.locked_by = p_lease_token
      and e.status = 'running'
      and e.cancellation_requested_at is null
  ) then
    return jsonb_build_object('ok', false, 'execute', false, 'status', 'execution_not_running');
  end if;

  insert into public.automation_effect_dispatches (
    organization_id, execution_id, node_key, effect_key, effect_type, status, request
  ) values (
    p_organization_id, p_execution_id, p_node_key, p_effect_key, p_effect_type, 'sending', coalesce(p_request, '{}'::jsonb)
  ) on conflict (effect_key) do nothing
  returning id into effect_id;

  if effect_id is not null then
    return jsonb_build_object('ok', true, 'execute', true, 'status', 'sending', 'effect_id', effect_id);
  end if;

  select status into current_status
  from public.automation_effect_dispatches
  where effect_key = p_effect_key;
  return jsonb_build_object(
    'ok', current_status = 'succeeded',
    'execute', false,
    'status', coalesce(current_status, 'missing')
  );
end;
$$;


ALTER FUNCTION public.reserve_automation_external_effect(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_effect_key text, p_effect_type text, p_request jsonb) OWNER TO postgres;

