    1
  );
$$;


ALTER FUNCTION public.reserve_billing_checkout_intent(p_organization_id uuid, p_billing_method text) OWNER TO postgres;

--
-- Name: reserve_billing_checkout_intent(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_billing_checkout_intent(p_organization_id uuid, p_billing_method text, p_billing_period_months integer) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.reserve_billing_checkout_intent(
    p_organization_id,
