    null
  );
$$;


ALTER FUNCTION public.reserve_billing_checkout_intent(p_organization_id uuid, p_billing_method text, p_billing_period_months integer) OWNER TO postgres;

--
-- Name: reserve_billing_checkout_intent(uuid, text, integer, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_billing_checkout_intent(p_organization_id uuid, p_billing_method text, p_billing_period_months integer, p_expected_plan_id uuid, p_expected_monthly_price numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_method text := upper(btrim(coalesce(p_billing_method, '')));
  v_period integer := coalesce(p_billing_period_months, 1);
  v_org public.organizations%rowtype;
  v_plan public.admin_subscription_plans%rowtype;
  v_target_plan_id uuid;
  v_cycle text;
  v_amount numeric(10, 2);
  v_intent private.billing_checkout_intents%rowtype;
  v_intent_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  if p_organization_id is null
     or v_method not in ('PIX', 'BOLETO', 'CREDIT_CARD')
     or v_period not in (1, 6, 12) then
    raise exception 'invalid billing checkout request'
      using errcode = '22023';
  end if;

  select *
  into v_org
  from public.organizations
  where id = p_organization_id
    and is_active = true
  for update;

  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;

  v_target_plan_id := coalesce(
    v_org.pending_plan_id,
    case
      when v_org.subscription_status = 'pending_payment' then v_org.plan_id
      else null
    end
  );

  if v_target_plan_id is null then
    return jsonb_build_object(
      'outcome',
      case
        when v_org.subscription_type = 'paid'
          and v_org.subscription_status = 'active'
          then 'already_active'
        else 'plan_not_staged'
      end
    );
  end if;

  select *
  into v_plan
  from public.admin_subscription_plans
  where id = v_target_plan_id
    and coalesce(is_active, true) = true;

  if not found
     or coalesce(v_plan.price, 0) <= 0
     or not (v_period = any(coalesce(v_plan.billing_periods, array[1]))) then
    return jsonb_build_object('outcome', 'invalid_plan');
  end if;

  if (p_expected_plan_id is not null and p_expected_plan_id <> v_plan.id)
     or (
       p_expected_monthly_price is not null
       and abs(p_expected_monthly_price - v_plan.price) > 0.01
     ) then
    return jsonb_build_object(
      'outcome', 'quote_changed',
      'plan_id', v_plan.id,
      'monthly_price', v_plan.price
    );
  end if;

  v_cycle := case v_period
    when 6 then 'semiannual'
    when 12 then 'yearly'
    else 'monthly'
  end;
  v_amount := round(v_plan.price * v_period, 2);

  select *
  into v_intent
  from private.billing_checkout_intents
  where organization_id = p_organization_id
    and status in ('creating', 'pending')
  order by created_at desc, id desc
  limit 1
  for update;

  if found then
    if v_intent.pending_plan_id is distinct from v_target_plan_id
       or v_intent.amount is distinct from v_amount
       or v_intent.billing_cycle is distinct from v_cycle
       or v_intent.billing_period_months is distinct from v_period
       or v_intent.billing_method is distinct from v_method then
      return jsonb_build_object(
        'outcome', 'active_intent_conflict',
        'intent_id', v_intent.id,
        'plan_id', v_intent.pending_plan_id,
        'amount', v_intent.amount,
        'billing_cycle', v_intent.billing_cycle,
        'billing_period_months', v_intent.billing_period_months,
        'billing_method', v_intent.billing_method,
        'status', v_intent.status,
        'provider_payment_id', v_intent.provider_payment_id,
        'provider_subscription_id', v_intent.provider_subscription_id,
        'last_error', v_intent.last_error
      );
    end if;

    return jsonb_build_object(
      'outcome',
      case
        when v_intent.status = 'pending' then 'reuse'
        when v_intent.provider_request_started_at is null
          or v_intent.provider_request_started_at <= now() - interval '45 seconds'
          then 'recover'
        else 'in_progress'
      end,
      'intent_id', v_intent.id,
      'external_reference', v_intent.external_reference,
      'plan_id', v_intent.pending_plan_id,
      'plan_name', v_plan.name,
      'amount', v_intent.amount,
      'billing_cycle', v_intent.billing_cycle,
      'billing_period_months', v_intent.billing_period_months,
      'billing_method', v_intent.billing_method,
      'status', v_intent.status,
      'provider_customer_id', v_intent.provider_customer_id,
      'provider_checkout_id', v_intent.provider_checkout_id,
      'provider_payment_id', v_intent.provider_payment_id,
      'provider_subscription_id', v_intent.provider_subscription_id,
      'provider_response', v_intent.provider_response,
      'last_error', v_intent.last_error
    );
  end if;

  v_intent_id := gen_random_uuid();
  insert into private.billing_checkout_intents (
    id,
    organization_id,
    pending_plan_id,
    amount,
    billing_cycle,
    billing_period_months,
    billing_method,
    status,
    external_reference,
    provider_request_started_at
  )
  values (
    v_intent_id,
    p_organization_id,
    v_target_plan_id,
    v_amount,
    v_cycle,
    v_period,
    v_method,
    'creating',
    v_intent_id::text,
    now()
  );

  return jsonb_build_object(
    'outcome', 'create',
    'intent_id', v_intent_id,
    'external_reference', v_intent_id::text,
    'plan_id', v_target_plan_id,
    'plan_name', v_plan.name,
    'amount', v_amount,
    'billing_cycle', v_cycle,
    'billing_period_months', v_period,
    'billing_method', v_method,
    'status', 'creating'
  );
end;
$$;


ALTER FUNCTION public.reserve_billing_checkout_intent(p_organization_id uuid, p_billing_method text, p_billing_period_months integer, p_expected_plan_id uuid, p_expected_monthly_price numeric) OWNER TO postgres;

--
-- Name: reserve_whatsapp_webhook_edge_execution(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_whatsapp_webhook_edge_execution(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_worker_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_execution_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_organization_id is null or p_session_id is null or p_inbox_id is null
    or coalesce(p_worker_id, '') not like 'vimob-api-evolution-webhook-epoch1-%'
  then
    return null;
  end if;

  perform 1 from public.whatsapp_sessions as session
  where session.id = p_session_id
    and session.organization_id = p_organization_id
    and session.provider = 'evolution_go'
  for key share;
  if not found or exists (
    select 1 from private.whatsapp_webhook_session_cutovers as cutover
    where cutover.session_id = p_session_id
  ) then
    return null;
  end if;

  update public.whatsapp_webhook_inbox as inbox
  set edge_execution_id = v_execution_id,
      edge_execution_state = 'reserved',
      edge_execution_reserved_at = clock_timestamp(),
      edge_execution_started_at = null,
      updated_at = now()
  where inbox.id = p_inbox_id
    and inbox.organization_id = p_organization_id
    and inbox.session_id = p_session_id
    and inbox.provider = 'evolution_go'
    and inbox.processing_epoch = 0
    and inbox.status = 'processing'
    and inbox.locked_by = p_worker_id
    and inbox.edge_execution_id is null;
  if not found then
    return null;
  end if;
  return v_execution_id;
end;
$$;


ALTER FUNCTION public.reserve_whatsapp_webhook_edge_execution(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_worker_id text) OWNER TO postgres;

--
-- Name: reset_gamification_season(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reset_gamification_season(p_organization_id uuid, p_season_name text, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_org uuid;
  v_new_season uuid;
  v_user record;
BEGIN
  SELECT role, organization_id INTO v_caller_role, v_caller_org
  FROM public.users WHERE id = auth.uid();

  IF v_caller_role NOT IN ('admin','super_admin') THEN
    RAISE EXCEPTION 'Apenas administradores podem reiniciar temporadas';
  END IF;

  IF v_caller_role <> 'super_admin' AND v_caller_org <> p_organization_id THEN
    RAISE EXCEPTION 'Sem permissão para esta organização';
  END IF;

  UPDATE public.gamification_seasons
     SET is_active = false, ended_at = now()
   WHERE organization_id = p_organization_id AND is_active = true;

  INSERT INTO public.gamification_seasons (
    organization_id, name, start_date, end_date, is_active,
    started_at, created_by, reset_reason
  ) VALUES (
    p_organization_id, COALESCE(NULLIF(trim(p_season_name),''), 'Nova Temporada'),
    CURRENT_DATE, CURRENT_DATE + INTERVAL '90 days', true,
    now(), auth.uid(), p_reason
  ) RETURNING id INTO v_new_season;

  UPDATE public.user_gamification_stats SET
    total_points     = 0,
    xp               = 0,
    xp_total         = 0,
    current_level    = 1,
    xp_current_level = 0,
    xp_next_level    = 100,
    rank_tier        = 'Bronze I',
    current_rank     = 'Bronze I',
    streak_days      = 0,
    season_id        = v_new_season,
    updated_at       = now()
  WHERE organization_id = p_organization_id;

  UPDATE public.user_mission_progress p SET
    current_count = 0,
    is_completed  = false,
    completed_at  = NULL,
    reset_at      = now(),
    updated_at    = now()
  FROM public.gamification_missions m
  WHERE p.mission_id = m.id
    AND m.organization_id = p_organization_id;

  FOR v_user IN
    SELECT id FROM public.users
    WHERE organization_id = p_organization_id AND COALESCE(is_active, true) = true
  LOOP
    INSERT INTO public.notifications (organization_id, user_id, type, title, content, is_read)
    VALUES (
      p_organization_id, v_user.id, 'gamification',
      '🏁 Nova temporada iniciada: ' || COALESCE(NULLIF(trim(p_season_name),''), 'Nova Temporada'),
      'Os níveis foram reiniciados. Hora de começar do zero e dominar o ranking!',
      false
    );
  END LOOP;

  RETURN v_new_season;
END;
$$;


ALTER FUNCTION public.reset_gamification_season(p_organization_id uuid, p_season_name text, p_reason text) OWNER TO postgres;

--
-- Name: resolve_automation_whatsapp_conversation(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_automation_whatsapp_conversation(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_initial_execution public.automation_executions%rowtype;
  v_locked_execution public.automation_executions%rowtype;
  v_conversation public.whatsapp_conversations%rowtype;
  v_active_binding public.whatsapp_conversation_lead_bindings%rowtype;
  v_binding_result jsonb;
  v_target_lead_id uuid;
  v_preferred_conversation_id uuid;
  v_conversation_id uuid;
  v_target_name text;
  v_assigned_user_id uuid;
  v_raw_phone text;
  v_phone_digits text;
  v_canonical_phone text;
  v_canonical_jid text;
  v_alias_lead_id uuid;
begin
  if p_organization_id is null
     or p_execution_id is null
     or p_session_id is null
     or nullif(pg_catalog.btrim(coalesce(p_node_key, '')), '') is null
     or nullif(pg_catalog.btrim(coalesce(p_lease_token, '')), '') is null then
    raise exception using
      errcode = '22023',
      message = 'automation_whatsapp_resolution_argument_missing';
  end if;

  -- Discovery is intentionally lock-free. The execution is authoritatively
  -- re-read under FOR UPDATE only after the conversation and binding locks.
  select execution.*
  into v_initial_execution
  from public.automation_executions as execution
  where execution.id = p_execution_id
    and execution.organization_id = p_organization_id;

  if not found then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_execution_unavailable';
  end if;

  v_target_lead_id := v_initial_execution.lead_id;
  v_preferred_conversation_id := v_initial_execution.conversation_id;

  select lead.name, lead.assigned_user_id, nullif(lead.phone, '')
  into v_target_name, v_assigned_user_id, v_raw_phone
  from public.leads as lead
  where lead.id = v_target_lead_id
    and lead.organization_id = p_organization_id;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'automation_whatsapp_lead_unavailable';
  end if;

  if not exists (
    select 1
    from public.whatsapp_sessions as session
    where session.id = p_session_id
      and session.organization_id = p_organization_id
      and session.provider = 'evolution_go'
      and session.status = 'connected'
      and coalesce(session.is_active, true)
  ) then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_session_unavailable';
  end if;

  v_phone_digits := pg_catalog.regexp_replace(
    coalesce(v_raw_phone, ''),
    '[^0-9]',
    '',
    'g'
  );
  if pg_catalog.length(v_phone_digits) between 10 and 15 then
    v_canonical_phone := case
      when pg_catalog.left(v_phone_digits, 2) = '55' then v_phone_digits
      when pg_catalog.length(v_phone_digits) in (10, 11) then '55' || v_phone_digits
      else v_phone_digits
    end;
    v_canonical_jid := v_canonical_phone || '@s.whatsapp.net';
  end if;

  -- Prefer an already-bound conversation for this lead, but do not lock it in
  -- this discovery query. The next query acquires the first mutation lock.
  select conversation.id
  into v_conversation_id
  from public.whatsapp_conversations as conversation
  where conversation.organization_id = p_organization_id
    and conversation.lead_id = v_target_lead_id
    and conversation.session_id = p_session_id
    and conversation.deleted_at is null
    and coalesce(conversation.is_group, false) = false
  order by
    case when conversation.id = v_preferred_conversation_id then 0 else 1 end,
    conversation.last_message_at desc nulls last,
    conversation.created_at desc,
    conversation.id
  limit 1;

  if v_conversation_id is null then
    if v_canonical_jid is null then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'status', 'lead_has_no_valid_whatsapp_phone'
      );
    end if;

    -- A new physical thread is deliberately born unlinked. The binding RPC
    -- below is the only operation allowed to attach it to a CRM card.
    insert into public.whatsapp_conversations (
      organization_id,
      session_id,
      lead_id,
      assigned_user_id,
      remote_jid,
      contact_name,
      contact_phone,
      is_group,
      unread_count,
      metadata
    ) values (
      p_organization_id,
      p_session_id,
      null,
      null,
      v_canonical_jid,
      coalesce(nullif(v_target_name, ''), v_canonical_phone),
      v_canonical_phone,
      false,
      0,
      pg_catalog.jsonb_build_object(
        'origin', 'automation',
        'execution_id', p_execution_id
      )
    )
    on conflict (session_id, remote_jid) do nothing
    returning id into v_conversation_id;

    if v_conversation_id is null then
      select conversation.id
      into v_conversation_id
      from public.whatsapp_conversations as conversation
      where conversation.organization_id = p_organization_id
        and conversation.session_id = p_session_id
        and conversation.remote_jid = v_canonical_jid
      limit 1;
    end if;
  end if;

  if v_conversation_id is null then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_conversation_resolution_failed';
  end if;

  -- Canonical lock order begins here: conversation, active binding, execution.
  select conversation.*
  into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = v_conversation_id
    and conversation.organization_id = p_organization_id
  for no key update;

  if not found
     or v_conversation.session_id is distinct from p_session_id
     or coalesce(v_conversation.is_group, false)
     or (
       v_conversation.lead_id is not null
       and v_conversation.lead_id is distinct from v_target_lead_id
     ) then
    raise exception using
      errcode = '23505',
      message = 'whatsapp_identity_belongs_to_another_lead';
  end if;

  update public.whatsapp_conversations as conversation
  set contact_name = coalesce(
        nullif(conversation.contact_name, ''),
        nullif(v_target_name, ''),
        v_canonical_phone
      ),
      contact_phone = coalesce(
        nullif(conversation.contact_phone, ''),
        v_canonical_phone
      ),
      deleted_at = null,
      archived_at = null,
      updated_at = pg_catalog.now()
  where conversation.id = v_conversation_id;

  select binding.*
  into v_active_binding
  from public.whatsapp_conversation_lead_bindings as binding
  where binding.conversation_id = v_conversation_id
    and binding.active_to is null
  for update;

  if v_active_binding.id is not null
     and (
       v_active_binding.organization_id is distinct from p_organization_id
       or v_active_binding.session_id is distinct from p_session_id
       or v_active_binding.lead_id is distinct from v_target_lead_id
       or v_conversation.lead_id is distinct from v_active_binding.lead_id
     ) then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_binding_context_mismatch';
  end if;

  if v_conversation.lead_id is null or v_active_binding.id is null then
    v_binding_result := public.activate_whatsapp_conversation_lead_binding(
      p_organization_id,
      v_conversation_id,
      v_target_lead_id,
      null
    );

    if coalesce((v_binding_result->>'success')::boolean, false) is not true
       or coalesce((v_binding_result->>'is_current')::boolean, false) is not true
       or (v_binding_result->>'active_lead_id')::uuid is distinct from v_target_lead_id then
      raise exception using
        errcode = '23514',
        message = 'automation_whatsapp_binding_activation_failed';
    end if;

    select conversation.*
    into v_conversation
    from public.whatsapp_conversations as conversation
    where conversation.id = v_conversation_id
      and conversation.organization_id = p_organization_id;

    select binding.*
    into v_active_binding
    from public.whatsapp_conversation_lead_bindings as binding
    where binding.conversation_id = v_conversation_id
      and binding.active_to is null
    for update;
  end if;

  if v_conversation.lead_id is distinct from v_target_lead_id
     or v_active_binding.id is null
     or v_active_binding.organization_id is distinct from p_organization_id
     or v_active_binding.session_id is distinct from p_session_id
     or v_active_binding.lead_id is distinct from v_target_lead_id then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_binding_context_mismatch';
  end if;

  -- The execution may have changed while conversation identity was resolved.
  -- Revalidate every lease/context field while holding its row lock.
  select execution.*
  into v_locked_execution
  from public.automation_executions as execution
  where execution.id = p_execution_id
    and execution.organization_id = p_organization_id
  for update;

  if not found
     or v_locked_execution.lead_id is distinct from v_target_lead_id
     or v_locked_execution.current_node_key is distinct from p_node_key
     or v_locked_execution.status is distinct from 'running'
     or v_locked_execution.locked_by is distinct from p_lease_token
     or v_locked_execution.cancellation_requested_at is not null
     or (
       v_locked_execution.conversation_id is not null
       and v_locked_execution.conversation_id is distinct from v_conversation_id
     ) then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_execution_fencing_conflict';
  end if;

  if not exists (
    select 1
    from public.whatsapp_sessions as session
    where session.id = p_session_id
      and session.organization_id = p_organization_id
      and session.provider = 'evolution_go'
      and session.status = 'connected'
      and coalesce(session.is_active, true)
  ) then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_session_unavailable';
  end if;

  insert into public.whatsapp_contact_identity_aliases (
    organization_id,
    session_id,
    alias_jid,
    canonical_jid,
    contact_phone,
    lead_id,
    is_group,
    last_seen_at,
    metadata
  ) values (
    p_organization_id,
    p_session_id,
    v_conversation.remote_jid,
    coalesce(v_canonical_jid, v_conversation.remote_jid),
    coalesce(v_canonical_phone, v_conversation.contact_phone),
    v_target_lead_id,
    false,
    pg_catalog.now(),
    pg_catalog.jsonb_build_object(
      'origin', 'automation',
      'execution_id', p_execution_id
    )
  )
  on conflict (organization_id, session_id, alias_jid) do update
    set canonical_jid = case
          when public.whatsapp_contact_identity_aliases.canonical_jid like '%@s.whatsapp.net'
            then public.whatsapp_contact_identity_aliases.canonical_jid
          else excluded.canonical_jid
        end,
        contact_phone = coalesce(
          excluded.contact_phone,
          public.whatsapp_contact_identity_aliases.contact_phone
        ),
        lead_id = excluded.lead_id,
        last_seen_at = pg_catalog.now(),
        metadata = public.whatsapp_contact_identity_aliases.metadata || excluded.metadata
    where public.whatsapp_contact_identity_aliases.lead_id is null
       or public.whatsapp_contact_identity_aliases.lead_id = excluded.lead_id
  returning lead_id into v_alias_lead_id;

  if not found or v_alias_lead_id is distinct from v_target_lead_id then
    raise exception using
      errcode = '23505',
      message = 'automation_whatsapp_alias_belongs_to_another_lead';
  end if;

  update public.automation_executions as execution
  set conversation_id = v_conversation_id,
      updated_at = pg_catalog.now()
  where execution.id = p_execution_id
    and execution.organization_id = p_organization_id
    and execution.lead_id = v_target_lead_id
    and execution.current_node_key = p_node_key
    and execution.status = 'running'
    and execution.locked_by = p_lease_token
    and execution.cancellation_requested_at is null
    and (
      execution.conversation_id is null
      or execution.conversation_id = v_conversation_id
    );

  if not found then
    raise exception using
      errcode = '23514',
      message = 'automation_whatsapp_execution_fencing_conflict';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'status', 'resolved',
    'id', v_conversation.id,
    'session_id', v_conversation.session_id,
    'lead_id', v_target_lead_id,
    'remote_jid', coalesce((
      select identity_alias.canonical_jid
      from public.whatsapp_contact_identity_aliases as identity_alias
      where identity_alias.organization_id = p_organization_id
        and identity_alias.session_id = p_session_id
        and identity_alias.alias_jid = v_conversation.remote_jid
        and identity_alias.lead_id = v_target_lead_id
        and identity_alias.canonical_jid like '%@s.whatsapp.net'
      order by identity_alias.last_seen_at desc, identity_alias.id
      limit 1
    ), v_conversation.remote_jid),
    'is_group', v_conversation.is_group
  );
end;
$$;


ALTER FUNCTION public.resolve_automation_whatsapp_conversation(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_session_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION resolve_automation_whatsapp_conversation(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_session_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.resolve_automation_whatsapp_conversation(p_organization_id uuid, p_execution_id uuid, p_node_key text, p_lease_token text, p_session_id uuid) IS 'automation_whatsapp_binding_fence_v2: resolves an unlinked physical conversation, establishes the canonical lead binding, then revalidates the execution lease in conversation-first lock order.';


--
-- Name: resolve_billing_payment_checkout_capability(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_billing_payment_checkout_capability(p_checkout_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_checkout_token text := lower(btrim(coalesce(p_checkout_token, '')));
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_plan_id uuid;
  v_billing_period_months integer;
  v_amount numeric;
  v_card_recurrence_status text;
begin
  if v_checkout_token !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  select capability.*
  into v_capability
  from public.billing_payment_checkout_capabilities as capability
  join public.asaas_payments as payment
    on payment.id = capability.payment_id
    and payment.asaas_payment_id = capability.asaas_payment_id
    and payment.organization_id = capability.organization_id
    and payment.billing_intent_id is not distinct from capability.billing_intent_id
  join public.organizations as organization_row
    on organization_row.id = capability.organization_id
    and organization_row.is_active = true
  where capability.checkout_token = v_checkout_token
    and capability.revoked_at is null
    and capability.expires_at > now()
    and (
      private.billing_payment_checkout_is_actionable(payment.status)
      or private.billing_payment_checkout_is_processing(payment.status)
      or private.billing_payment_checkout_is_paid(payment.status)
    )
    and private.billing_payment_checkout_is_resolvable(payment.id)
  limit 1;

  if not found then
    -- Expired, revoked and unknown tokens are intentionally indistinguishable.
    return jsonb_build_object('outcome', 'not_found');
  end if;

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = v_capability.payment_id
    and payment.asaas_payment_id = v_capability.asaas_payment_id
    and payment.organization_id = v_capability.organization_id;

  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  -- The public token resolves only the tuple frozen when it was issued. Never
  -- reconstruct a historical price from today's intent, subscription or plan.
  v_plan_id := v_capability.plan_id;
  v_billing_period_months := v_capability.billing_period_months;
  v_amount := v_capability.amount;

  select provision.status
  into v_card_recurrence_status
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_capability.payment_id
    and provision.provider_payment_id = v_capability.asaas_payment_id
    and provision.organization_id = v_capability.organization_id
    and provision.billing_intent_id is not distinct from v_capability.billing_intent_id
  limit 1;

  if v_plan_id is null
     or v_billing_period_months not in (1, 6, 12)
     or v_amount is null
     or v_amount <= 0 then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  return jsonb_build_object(
    'outcome', 'resolved',
    'organization_id', v_capability.organization_id,
    'payment_id', v_capability.payment_id,
    'billing_intent_id', v_capability.billing_intent_id,
    'plan_id', v_plan_id,
    'billing_period_months', v_billing_period_months,
    'amount', v_amount,
    'snapshot_source', v_capability.snapshot_source,
    'card_recurrence_status', v_card_recurrence_status,
    'bank_slip_registration_cancelled',
      v_payment.bank_slip_registration_cancelled_at is not null,
    'bank_slip_registration_cancelled_at',
      v_payment.bank_slip_registration_cancelled_at,
    'bank_slip_registration_cancelled_due_date',
      v_payment.bank_slip_registration_cancelled_due_date
  );
end
$_$;


ALTER FUNCTION public.resolve_billing_payment_checkout_capability(p_checkout_token text) OWNER TO postgres;

--
-- Name: FUNCTION resolve_billing_payment_checkout_capability(p_checkout_token text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.resolve_billing_payment_checkout_capability(p_checkout_token text) IS 'Service-only capability resolver. Never returns the raw checkout token.';


--
-- Name: resolve_billing_subscription_card_update_manual_review(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_billing_subscription_card_update_manual_review(p_job_id uuid, p_organization_id uuid, p_resolution text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_resolution text := lower(nullif(btrim(coalesce(p_resolution, '')), ''));
  v_job private.billing_subscription_card_update_jobs%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or v_resolution not in (
       'provider_card_confirmed',
       'provider_card_not_applied',
       'subscription_removed'
     ) then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_job.provider_payment_id,
    v_job.provider_subscription_id
  );

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id
  for update;
  if v_job.status <> 'dead' or v_job.manual_review_at is null then
    return jsonb_build_object(
      'outcome', 'not_in_manual_review',
      'status', v_job.status
    );
  end if;

  if v_resolution = 'provider_card_confirmed' and not exists (
    select 1
    from public.subscriptions as subscription
    where subscription.id = v_job.subscription_id
      and subscription.organization_id = p_organization_id
      and subscription.provider_subscription_id
        = v_job.provider_subscription_id
      and lower(subscription.status) = 'active'
  ) then
    return jsonb_build_object('outcome', 'subscription_not_active');
  end if;

  update private.billing_subscription_card_update_jobs
  set
    status = case
      when v_resolution = 'provider_card_confirmed' then 'succeeded'
      else 'cancelled'
    end,
    provider_card_credential = null,
    credential_attempt_lease_id = null,
    lease_id = null,
    lease_owner = null,
    lease_started_at = null,
    lease_expires_at = null,
    provider_snapshot = provider_snapshot || jsonb_build_object(
      'assisted_resolution', v_resolution,
      'resolved_at', v_now
    ),
    last_error_code = null,
    manual_review_at = null,
    completed_at = case
      when v_resolution = 'provider_card_confirmed' then v_now else null
    end,
    cancelled_at = case
      when v_resolution = 'provider_card_confirmed' then null else v_now
    end,
    dead_lettered_at = null,
    updated_at = v_now
  where id = v_job.id
    and status = 'dead'
    and manual_review_at is not null;

  if v_resolution = 'provider_card_confirmed' then
    update public.subscriptions
    set
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'billing_card', jsonb_build_object(
          'last4', v_job.card_last4,
          'updated_at', v_now,
          'generation', v_job.generation,
          'job_id', v_job.id,
          'assisted', true
        )
      ),
      updated_at = v_now
    where id = v_job.subscription_id
      and organization_id = p_organization_id
      and provider_subscription_id = v_job.provider_subscription_id;
  end if;

  return jsonb_build_object(
    'outcome', 'resolved',
    'resolution', v_resolution,
    'status', case
      when v_resolution = 'provider_card_confirmed' then 'succeeded'
      else 'cancelled'
    end
  );
end
$$;


ALTER FUNCTION public.resolve_billing_subscription_card_update_manual_review(p_job_id uuid, p_organization_id uuid, p_resolution text) OWNER TO postgres;

--
-- Name: resolve_site_domain(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_site_domain(p_domain text) RETURNS TABLE(organization_id uuid, site_config jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_site organization_sites%ROWTYPE;
  v_org organizations%ROWTYPE;
  v_clean text;
  v_bare text;
BEGIN
  v_clean := lower(trim(p_domain));
  v_bare := regexp_replace(v_clean, '^www\.', '');

  SELECT * INTO v_site
  FROM organization_sites
  WHERE custom_domain IN (v_clean, v_bare, 'www.' || v_bare)
    AND domain_verified = true
    AND is_active = true
  LIMIT 1;

  IF v_site.id IS NULL THEN
    SELECT * INTO v_site
    FROM organization_sites
    WHERE subdomain = split_part(v_bare, '.', 1)
      AND is_active = true
    LIMIT 1;
  END IF;

  IF v_site.id IS NULL THEN
    RETURN;
  END IF;

  SELECT * INTO v_org FROM organizations WHERE id = v_site.organization_id;

  RETURN QUERY SELECT
    v_site.organization_id,
    jsonb_build_object(
      'id', v_site.id,
      'is_active', v_site.is_active,
      'subdomain', v_site.subdomain,
      'custom_domain', v_site.custom_domain,
      'site_title', COALESCE(v_site.site_title, v_org.name),
      'site_description', v_site.site_description,
      'logo_url', COALESCE(v_site.logo_url, v_org.logo_url),
      'footer_logo_url', v_site.footer_logo_url,
      'favicon_url', v_site.favicon_url,
      'primary_color', v_site.primary_color,
      'secondary_color', v_site.secondary_color,
      'accent_color', v_site.accent_color,
      'site_theme', COALESCE(v_site.site_theme, 'dark'),
      'background_color', COALESCE(v_site.background_color, '#0D0D0D'),
      'text_color', COALESCE(v_site.text_color, '#FFFFFF'),
      'card_color', COALESCE(v_site.card_color, '#FFFFFF'),
      'whatsapp', v_site.whatsapp,
      'phone', v_site.phone,
      'email', v_site.email,
      'address', v_site.address,
      'city', v_site.city,
      'state', v_site.state,
      'instagram', v_site.instagram,
      'facebook', v_site.facebook,
      'youtube', v_site.youtube,
      'linkedin', v_site.linkedin,
      'about_title', v_site.about_title,
      'about_text', v_site.about_text,
      'about_image_url', v_site.about_image_url,
      'seo_title', v_site.seo_title,
      'seo_description', v_site.seo_description,
      'seo_keywords', v_site.seo_keywords,
      'google_analytics_id', v_site.google_analytics_id,
      'hero_image_url', v_site.hero_image_url,
      'hero_title', v_site.hero_title,
      'hero_subtitle', v_site.hero_subtitle,
      'page_banner_url', v_site.page_banner_url,
      'logo_width', COALESCE(v_site.logo_width, 160),
      'logo_height', COALESCE(v_site.logo_height, 50),
      'watermark_enabled', COALESCE(v_site.watermark_enabled, false),
      'watermark_opacity', COALESCE(v_site.watermark_opacity, 20),
      'watermark_logo_url', v_site.watermark_logo_url,
      'watermark_size', COALESCE(v_site.watermark_size, 80),
      'watermark_position', COALESCE(v_site.watermark_position, 'bottom-right'),
      'organization_name', v_org.name
    );
END;
$$;


ALTER FUNCTION public.resolve_site_domain(p_domain text) OWNER TO postgres;

