ALTER FUNCTION public.resolve_whatsapp_unlinked_history_capture(p_organization_id uuid, p_session_id uuid, p_conversation_id uuid, p_provider_message_id text, p_inbox_event_key text) OWNER TO postgres;

--
-- Name: resolve_whatsapp_webhook_inherited_routing_target(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_whatsapp_webhook_inherited_routing_target(p_organization_id uuid, p_session_id uuid, p_provider_message_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_message_id text := nullif(pg_catalog.btrim(p_provider_message_id), '');
  v_route public.whatsapp_webhook_routing_snapshots%rowtype;
  v_predecessor public.whatsapp_webhook_routing_snapshots%rowtype;
  v_predecessor_processed boolean;
  v_result jsonb;
begin
  if p_organization_id is null or p_session_id is null or v_provider_message_id is null then
    raise exception using errcode = '22023', message = 'whatsapp_inherited_target_argument_missing';
  end if;

  select routing_snapshot.*
  into v_route
  from public.whatsapp_webhook_routing_snapshots as routing_snapshot
  where routing_snapshot.organization_id = p_organization_id
    and routing_snapshot.session_id = p_session_id
    and routing_snapshot.provider_message_id = v_provider_message_id;

  if not found
     or not v_route.binding_eligible
     or v_route.routing_key = '__session__'
     or v_route.target_mode <> 'inherit_predecessor'
     or v_route.predecessor_provider_message_id is null then
    raise exception using errcode = '23514', message = 'whatsapp_inherited_target_route_invalid';
  end if;

  select routing_snapshot.*
  into v_predecessor
  from public.whatsapp_webhook_routing_snapshots as routing_snapshot
  where routing_snapshot.organization_id = p_organization_id
    and routing_snapshot.session_id = p_session_id
    and routing_snapshot.provider_message_id = v_route.predecessor_provider_message_id;

  if not found
     or not v_predecessor.binding_eligible
     or v_predecessor.routing_key is distinct from v_route.routing_key
     or v_predecessor.ingress_sequence >= v_route.ingress_sequence
      or not private.whatsapp_inherited_predecessor_provenance_matches(v_route, v_predecessor) then
    raise exception using errcode = '23514', message = 'whatsapp_ingress_predecessor_chain_invalid';
  end if;

  select v_predecessor.inbox_event_key = v_route.inbox_event_key
    or exists (
      select 1
      from public.whatsapp_webhook_inbox as predecessor_inbox
      where predecessor_inbox.organization_id = p_organization_id
        and predecessor_inbox.session_id = p_session_id
        and predecessor_inbox.event_key = v_predecessor.inbox_event_key
        and predecessor_inbox.status = 'processed'
    )
    or exists (
      select 1
      from public.whatsapp_webhook_routing_outcomes as predecessor_outcome
      where predecessor_outcome.organization_id = p_organization_id
        and predecessor_outcome.session_id = p_session_id
        and predecessor_outcome.provider_message_id = v_predecessor.provider_message_id
        and predecessor_outcome.ingress_sequence = v_predecessor.ingress_sequence
    )
    or exists (
      select 1
      from public.whatsapp_webhook_inbox as execution_inbox
      where execution_inbox.organization_id = p_organization_id
        and execution_inbox.session_id = p_session_id
        and execution_inbox.status = 'processing'
        and exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            execution_inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
          ) as current_route(snapshot)
          where current_route.snapshot = v_route.snapshot
        )
        and exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            execution_inbox.payload #> '{__vimob_ingress,routing_snapshot,messages}'
          ) as predecessor_route(snapshot)
          where predecessor_route.snapshot = v_predecessor.snapshot
        )
    ) into v_predecessor_processed;

  if not v_predecessor_processed then
    raise exception using errcode = '40001', message = 'whatsapp_ingress_predecessor_pending';
  end if;

  -- This single MVCC statement returns only the predecessor result that is
  -- simultaneously the current conversation/binding/head. The activation CAS
  -- repeats the proof under conversation -> binding -> head row locks.
  select pg_catalog.jsonb_build_object(
    'ready', true,
    'terminal', false,
    'conversation_id', conversation.id,
    'lead_id', routing_head.lead_id,
    'active_binding_id', binding.id,
    'predecessor_provider_message_id', routing_head.provider_message_id,
    'predecessor_ingress_sequence', routing_head.ingress_sequence
  )
  into v_result
  from public.whatsapp_conversation_routing_heads as routing_head
  join public.whatsapp_conversations as conversation
    on conversation.id = routing_head.conversation_id
   and conversation.organization_id = routing_head.organization_id
   and conversation.session_id = routing_head.session_id
  join public.whatsapp_conversation_lead_bindings as binding
    on binding.organization_id = conversation.organization_id
   and binding.conversation_id = conversation.id
   and binding.active_to is null
  where routing_head.organization_id = p_organization_id
    and routing_head.session_id = p_session_id
    and routing_head.routing_key = v_route.routing_key
    and routing_head.provider_message_id = v_route.predecessor_provider_message_id
    and routing_head.ingress_sequence = v_predecessor.ingress_sequence
    and binding.session_id is not distinct from p_session_id
    and binding.lead_id is not distinct from conversation.lead_id
    and routing_head.lead_id is not distinct from conversation.lead_id
  limit 1;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ready', false,
      'terminal', true,
      'reason', 'whatsapp_ingress_predecessor_head_invalidated'
    );
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION public.resolve_whatsapp_webhook_inherited_routing_target(p_organization_id uuid, p_session_id uuid, p_provider_message_id text) OWNER TO postgres;

--
-- Name: resume_automation_delay(uuid, uuid, text, timestamp with time zone, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resume_automation_delay(p_organization_id uuid, p_execution_id uuid, p_branch text, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reply_payload jsonb DEFAULT '{}'::jsonb, p_lead_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_execution public.automation_executions%rowtype;
  target_graph jsonb;
  target_node jsonb;
  target_step_id uuid;
  wait_started_at timestamptz;
  target_node_key text;
  outgoing_count integer;
  is_reply_aware boolean;
  next_data jsonb;
  final_status text;
begin
  if p_branch not in ('replied', 'elapsed') then
    return jsonb_build_object('ok', false, 'status', 'invalid_branch');
  end if;

  select e.*
  into target_execution
  from public.automation_executions e
  join public.automation_flow_versions fv
    on fv.id = e.flow_version_id
   and fv.organization_id = e.organization_id
   and fv.requires_review = false
  where e.id = p_execution_id
    and e.organization_id = p_organization_id
    and e.status = 'waiting'
    and e.cancellation_requested_at is null
  for update of e;
  if not found then
    return jsonb_build_object('ok', false, 'status', 'not_waiting');
  end if;
  select fv.graph
  into target_graph
  from public.automation_flow_versions fv
  where fv.id = target_execution.flow_version_id
    and fv.organization_id = target_execution.organization_id
    and fv.requires_review = false;

  select node
  into target_node
  from jsonb_array_elements(coalesce(target_graph->'nodes', '[]'::jsonb)) node
  where node->>'id' = target_execution.current_node_key
    and node->>'type' = 'delay'
  limit 1;
  if target_node is null then
    raise exception 'waiting_execution_delay_node_missing';
  end if;
  is_reply_aware := coalesce((target_node->'config'->>'stop_on_reply')::boolean, false);

  select s.id, s.started_at
  into target_step_id, wait_started_at
  from public.automation_execution_steps s
  where s.execution_id = target_execution.id
    and s.organization_id = target_execution.organization_id
    and s.node_key = target_execution.current_node_key
    and s.status = 'waiting'
  order by s.attempt desc, s.started_at desc
  limit 1
  for update;
  if target_step_id is null then
    raise exception 'waiting_execution_step_missing';
  end if;

  if p_branch = 'replied' then
    if not is_reply_aware
       or (p_lead_id is not null and p_lead_id <> target_execution.lead_id)
       or (p_conversation_id is not null and target_execution.conversation_id is not null
         and p_conversation_id <> target_execution.conversation_id)
       or p_occurred_at is null
       or p_occurred_at < wait_started_at
       or p_occurred_at > target_execution.next_execution_at then
      return jsonb_build_object('ok', false, 'status', 'reply_outside_wait_window');
    end if;
  else
    if target_execution.next_execution_at is null or target_execution.next_execution_at > now() then
      return jsonb_build_object('ok', false, 'status', 'not_due');
    end if;
    -- A reply durably captured before the deadline wins even if the timeout
    -- worker races the event consumer. The event consumer will resume it.
    if is_reply_aware and exists (
      select 1
      from public.automation_event_outbox o
      where o.organization_id = target_execution.organization_id
        and o.lead_id = target_execution.lead_id
        and o.event_type = 'message_received'
        and o.status in ('pending', 'processing', 'failed')
        and (target_execution.conversation_id is null or o.conversation_id = target_execution.conversation_id)
        and private.safe_automation_timestamptz(o.payload->>'occurred_at') >= wait_started_at
        and private.safe_automation_timestamptz(o.payload->>'occurred_at') <= target_execution.next_execution_at
    ) then
      return jsonb_build_object('ok', false, 'status', 'reply_pending');
    end if;
  end if;

  select count(*)
  into outgoing_count
  from jsonb_array_elements(coalesce(target_graph->'connections', '[]'::jsonb)) edge
  where edge->>'source' = target_execution.current_node_key;

  select edge->>'target'
  into target_node_key
  from jsonb_array_elements(coalesce(target_graph->'connections', '[]'::jsonb)) edge
  where edge->>'source' = target_execution.current_node_key
    and (
      (is_reply_aware and coalesce(nullif(edge->>'condition_branch', ''), nullif(edge->>'source_handle', '')) =
        case when p_branch = 'replied' then 'replied' else 'no_reply' end)
      or (
        not is_reply_aware
        and coalesce(
          nullif(edge->>'condition_branch', ''),
          nullif(edge->>'source_handle', ''),
          'default'
        ) = 'default'
      )
    )
  limit 1;
  if outgoing_count > 0 and target_node_key is null then
    raise exception 'delay_branch_target_missing';
  end if;

  next_data := coalesce(target_execution.execution_data, '{}'::jsonb) - 'resume_branch';
  if p_branch = 'replied' then
    next_data := jsonb_set(next_data, '{reply_payload}', coalesce(p_reply_payload, '{}'::jsonb), true);
  end if;
  final_status := case when target_node_key is null then 'completed' else 'queued' end;

  update public.automation_execution_steps s
  set status = 'succeeded',
      output = coalesce(s.output, '{}'::jsonb) || jsonb_build_object(
        'branch', case when is_reply_aware then case when p_branch = 'replied' then 'replied' else 'no_reply' end else null end,
        'resume_reason', p_branch,
        'occurred_at', p_occurred_at,
        'next_node_key', target_node_key
      ),
      completed_at = now()
  where s.id = target_step_id and s.status = 'waiting';

  update public.automation_executions e
  set status = final_status,
      current_node_key = target_node_key,
      conversation_id = case
        when p_branch = 'replied' then coalesce(e.conversation_id, p_conversation_id)
        else e.conversation_id
      end,
      execution_data = next_data,
      next_execution_at = null,
      completed_at = case when final_status = 'completed' then now() else null end,
      locked_at = null,
      locked_by = null,
      updated_at = now()
  where e.id = target_execution.id and e.status = 'waiting';

  return jsonb_build_object(
    'ok', true,
    'status', final_status,
    'branch', case when is_reply_aware then case when p_branch = 'replied' then 'replied' else 'no_reply' end else null end,
    'next_node_key', target_node_key
  );
end;
$$;


ALTER FUNCTION public.resume_automation_delay(p_organization_id uuid, p_execution_id uuid, p_branch text, p_occurred_at timestamp with time zone, p_reply_payload jsonb, p_lead_id uuid, p_conversation_id uuid) OWNER TO postgres;

--
-- Name: retire_whatsapp_unlinked_conversation_epoch(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retire_whatsapp_unlinked_conversation_epoch(p_organization_id uuid, p_session_id uuid, p_expected_conversation_id uuid, p_remote_jid text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_retired_at timestamptz;
begin
  if p_organization_id is null or p_session_id is null
     or p_expected_conversation_id is null
     or nullif(pg_catalog.btrim(p_remote_jid), '') is null then
    raise exception using errcode = '22023',
      message = 'whatsapp_unlinked_epoch_arguments_required';
  end if;

  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_expected_conversation_id
    and conversation.organization_id = p_organization_id
    and conversation.session_id = p_session_id
    and conversation.remote_jid = p_remote_jid
  for update;

  if not found then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', p_expected_conversation_id,
      'reason', 'not_found'
    );
  end if;
  if v_conversation.retired_at is not null then
    return pg_catalog.jsonb_build_object(
      'retired', true, 'conversation_id', v_conversation.id,
      'reason', 'already_retired'
    );
  end if;
  if not v_conversation.unlinked_retention_v1 then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'not_unlinked_v1'
    );
  end if;
  if v_conversation.lead_id is not null
     or private.whatsapp_conversation_has_protected_history(v_conversation.id) then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'lead_bound'
    );
  end if;
  if coalesce(v_conversation.is_group, false)
     or v_conversation.deleted_at is not null then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'route_inactive'
    );
  end if;
  if v_conversation.created_at > pg_catalog.clock_timestamp() - interval '7 days' then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'not_due'
    );
  end if;

  if exists (
    select 1 from pg_catalog.pg_constraint as constraint_state
    where constraint_state.conrelid = 'public.whatsapp_conversations'::regclass
      and constraint_state.conname = 'whatsapp_conversations_session_id_remote_jid_key'
  ) or not exists (
    select 1 from pg_catalog.pg_index as index_state
    join pg_catalog.pg_class as index_class on index_class.oid = index_state.indexrelid
    where index_state.indrelid = 'public.whatsapp_conversations'::regclass
      and index_class.relname = 'whatsapp_conversations_active_session_remote_jid_uidx'
      and index_state.indisunique and index_state.indisvalid
  ) then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'cutover_required'
    );
  end if;

  v_retired_at := pg_catalog.clock_timestamp();
  update public.whatsapp_conversations
  set retired_at = v_retired_at,
      unlinked_retention_v1 = true,
      updated_at = v_retired_at
  where id = v_conversation.id;

  return pg_catalog.jsonb_build_object(
    'retired', true, 'conversation_id', v_conversation.id,
    'reason', 'expired'
  );
end;
$$;


ALTER FUNCTION public.retire_whatsapp_unlinked_conversation_epoch(p_organization_id uuid, p_session_id uuid, p_expected_conversation_id uuid, p_remote_jid text) OWNER TO postgres;

--
-- Name: retire_whatsapp_unlinked_conversation_for_lead_intake(uuid, uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retire_whatsapp_unlinked_conversation_for_lead_intake(p_organization_id uuid, p_session_id uuid, p_expected_conversation_id uuid, p_remote_jid text, p_provider_message_id text, p_inbox_event_key text, p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
  v_snapshot public.whatsapp_webhook_routing_snapshots%rowtype;
  v_inbox public.whatsapp_webhook_inbox%rowtype;
  v_state text;
  v_context_proof text;
  v_intake_id uuid;
  v_old_snapshot_id uuid;
  v_snapshot_lead_id uuid;
  v_retired_at timestamptz;
begin
  if p_organization_id is null or p_session_id is null
     or p_expected_conversation_id is null
     or nullif(pg_catalog.btrim(p_remote_jid), '') is null
     or nullif(pg_catalog.btrim(p_provider_message_id), '') is null
     or nullif(pg_catalog.btrim(p_inbox_event_key), '') is null then
    raise exception using errcode = '22023',
      message = 'whatsapp_intake_split_arguments_required';
  end if;

  -- Preserve the same lock order as other binding writers: conversation
  -- before message/alias state. Session and inbox are stable reads here.
  select conversation.* into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_expected_conversation_id
    and conversation.organization_id = p_organization_id
    and conversation.session_id = p_session_id
    and conversation.remote_jid = p_remote_jid
  for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', p_expected_conversation_id,
      'reason', 'not_found'
    );
  end if;
  select snapshot.* into v_snapshot
  from public.whatsapp_webhook_routing_snapshots as snapshot
  where snapshot.organization_id = p_organization_id
    and snapshot.session_id = p_session_id
    and snapshot.provider_message_id = p_provider_message_id
    and snapshot.inbox_event_key = p_inbox_event_key;
  select inbox.* into v_inbox
  from public.whatsapp_webhook_inbox as inbox
  where inbox.organization_id = p_organization_id
    and inbox.session_id = p_session_id
    and inbox.event_key = p_inbox_event_key;

  v_state := v_snapshot.snapshot->>'state';
  v_context_proof := v_snapshot.snapshot->>'context_proof';
  v_intake_id := nullif(v_snapshot.snapshot->>'intake_unlinked_conversation_id', '')::uuid;
  v_old_snapshot_id := nullif(v_snapshot.snapshot->>'conversation_id', '')::uuid;
  v_snapshot_lead_id := nullif(v_snapshot.snapshot->>'event_lead_id', '')::uuid;

  if v_snapshot.provider_message_id is null or v_inbox.id is null
     or v_snapshot.snapshot->>'unlinked_capture_policy' is distinct from 'v1'
     or nullif(v_snapshot.snapshot->>'quarantine_reason', '') is not null
     or (v_snapshot.snapshot->>'current_lead_id') is not null
     or (v_snapshot.snapshot->>'active_binding_id') is not null
     or not coalesce(v_snapshot.binding_eligible, false)
     or (v_intake_id is distinct from p_expected_conversation_id
         and v_old_snapshot_id is distinct from p_expected_conversation_id)
     or (v_intake_id is not null
         and v_snapshot.snapshot->>'intake_unlinked_remote_jid'
             is distinct from p_remote_jid)
     or not (
       (v_state = 'lead_match'
        and p_lead_id is not null
        and v_snapshot_lead_id = p_lead_id
        and exists (
          select 1 from public.leads as lead
          where lead.organization_id = p_organization_id
            and lead.id = p_lead_id
        ))
       or (v_state = 'contextual_intake'
           and (v_context_proof in ('managed_rule', 'provider_event_ledger')
                or v_context_proof like 'canonical_intake_v1:%')
           and (p_lead_id is null
                or (v_snapshot_lead_id = p_lead_id
                    and exists (
                      select 1 from public.leads as lead
                      where lead.organization_id = p_organization_id
                        and lead.id = p_lead_id
                    )))
       )
     ) then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'snapshot_unproven'
    );
  end if;

  if not v_conversation.unlinked_retention_v1 then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'not_unlinked_v1'
    );
  end if;
  if v_conversation.lead_id is not null
     or private.whatsapp_conversation_has_protected_history(v_conversation.id) then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'lead_bound'
    );
  end if;
  if coalesce(v_conversation.is_group, false)
     or v_conversation.deleted_at is not null
     or v_conversation.unlinked_retention_scrubbed_at is not null then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'route_inactive'
    );
  end if;
  if v_conversation.retired_at is not null then
    return pg_catalog.jsonb_build_object(
      'retired', true, 'conversation_id', v_conversation.id,
      'reason', 'already_retired'
    );
  end if;

  if exists (
    select 1 from pg_catalog.pg_constraint as constraint_state
    where constraint_state.conrelid = 'public.whatsapp_conversations'::regclass
      and constraint_state.conname = 'whatsapp_conversations_session_id_remote_jid_key'
  ) or not exists (
    select 1 from pg_catalog.pg_index as index_state
    join pg_catalog.pg_class as index_class
      on index_class.oid = index_state.indexrelid
    where index_state.indrelid = 'public.whatsapp_conversations'::regclass
      and index_class.relname = 'whatsapp_conversations_active_session_remote_jid_uidx'
      and index_state.indisunique and index_state.indisvalid
  ) then
    return pg_catalog.jsonb_build_object(
      'retired', false, 'conversation_id', v_conversation.id,
      'reason', 'cutover_required'
    );
  end if;

  v_retired_at := pg_catalog.clock_timestamp();
  update public.whatsapp_conversations
  set retired_at = v_retired_at,
      updated_at = v_retired_at
  where id = v_conversation.id;
  return pg_catalog.jsonb_build_object(
    'retired', true, 'conversation_id', v_conversation.id,
    'reason', 'intake_split', 'retired_at', v_retired_at
  );
end;
$$;


ALTER FUNCTION public.retire_whatsapp_unlinked_conversation_for_lead_intake(p_organization_id uuid, p_session_id uuid, p_expected_conversation_id uuid, p_remote_jid text, p_provider_message_id text, p_inbox_event_key text, p_lead_id uuid) OWNER TO postgres;

--
-- Name: sanitize_whatsapp_message_metadata(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sanitize_whatsapp_message_metadata() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.metadata is not null then
    new.metadata = new.metadata - 'raw';

    if jsonb_typeof(new.metadata -> 'deletion_event') = 'object' then
      new.metadata = jsonb_set(
        new.metadata,
        '{deletion_event}',
        (new.metadata -> 'deletion_event') - 'raw',
        true
      );
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.sanitize_whatsapp_message_metadata() OWNER TO postgres;

--
-- Name: send_pool_redistribution_warning_from_backend(uuid, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.send_pool_redistribution_warning_from_backend(p_organization_id uuid, p_lead_id uuid, p_round_robin_id uuid, p_expected_assigned_user_id uuid, p_expected_lead_assigned_at timestamp with time zone, p_expected_distribution_assignment_at timestamp with time zone, p_expected_redistribution_count integer, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lead public.leads%rowtype;
  v_pipeline public.pipelines%rowtype;
  v_assignment record;
  v_assignment_at timestamptz;
  v_timeout_minutes integer;
  v_warning_minutes integer;
  v_has_blocking_activity boolean := false;
  v_notification_id uuid := gen_random_uuid();
begin
  p_now := coalesce(p_now, clock_timestamp());

  if p_organization_id is null
     or p_lead_id is null
     or p_round_robin_id is null
     or p_expected_assigned_user_id is null
     or p_expected_lead_assigned_at is null
     or p_expected_distribution_assignment_at is null
     or p_expected_redistribution_count is null
     or p_expected_redistribution_count < 0 then
    raise exception using
      errcode = '22023',
      message = 'invalid_pool_warning_request';
  end if;

  select lead.*
  into v_lead
  from public.leads as lead
  where lead.id = p_lead_id
    and lead.organization_id = p_organization_id
  for update;

  if not found then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'lead_not_found',
      'lead_id', p_lead_id
    );
  end if;

  if v_lead.assigned_user_id is distinct from p_expected_assigned_user_id
     or v_lead.assigned_at is distinct from p_expected_lead_assigned_at
     or coalesce(v_lead.redistribution_count, 0) <>
       p_expected_redistribution_count then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'stale_pool_candidate',
      'lead_id', p_lead_id
    );
  end if;

  if v_lead.redistribution_warning_sent_at is not null then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'replayed', true,
      'reason', 'warning_already_sent',
      'lead_id', p_lead_id
    );
  end if;

  if lower(coalesce(v_lead.deal_status, 'open')) in (
    'won', 'ganho', 'lost', 'perdido', 'closed', 'fechado'
  ) then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'closed_deal_status',
      'lead_id', p_lead_id
    );
  end if;

  if exists (
    select 1
    from public.stages as stage
    where stage.id = v_lead.stage_id
      and stage.organization_id = p_organization_id
      and (coalesce(stage.is_won, false) or coalesce(stage.is_lost, false))
  ) then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'closed_stage',
      'lead_id', p_lead_id
    );
  end if;

  select pipeline.*
  into v_pipeline
  from public.pipelines as pipeline
  where pipeline.id = v_lead.pipeline_id
    and pipeline.organization_id = p_organization_id
    and coalesce(pipeline.pool_enabled, false) = true;

  if not found then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'pool_disabled_for_pipeline',
      'lead_id', p_lead_id
    );
  end if;

  v_timeout_minutes := greatest(coalesce(v_pipeline.pool_timeout_minutes, 10), 1);
  v_warning_minutes := greatest(
    0,
    least(coalesce(v_pipeline.pool_warning_minutes, 2), v_timeout_minutes - 1)
  );

  if v_warning_minutes = 0 then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'pool_warning_disabled',
      'lead_id', p_lead_id
    );
  end if;

  select assignment.*
  into v_assignment
  from public.assignments_log as assignment
  where assignment.organization_id = p_organization_id
    and assignment.lead_id = p_lead_id
    and assignment.assigned_user_id = p_expected_assigned_user_id
    and coalesce(assignment.reason, '') in (
      'round_robin_auto',
      'round_robin',
      'canonical_round_robin'
    )
    and assignment.round_robin_id is not null
  order by
    coalesce(assignment.assigned_at, assignment.created_at) desc,
    assignment.created_at desc,
    assignment.id desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'lead_not_assigned_by_distribution_queue',
      'lead_id', p_lead_id
    );
  end if;

  v_assignment_at := coalesce(
    v_assignment.assigned_at,
    v_assignment.created_at,
    v_lead.assigned_at,
    v_lead.created_at
  );

  if v_assignment.round_robin_id is distinct from p_round_robin_id
     or v_assignment_at is distinct from
       p_expected_distribution_assignment_at then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'stale_distribution_assignment',
      'lead_id', p_lead_id
    );
  end if;

  if v_pipeline.pool_enabled_at is not null
     and v_assignment_at < v_pipeline.pool_enabled_at then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'lead_assigned_before_pool_enabled',
      'lead_id', p_lead_id
    );
  end if;

  if coalesce(v_pipeline.pool_max_redistributions, 3) > 0
     and p_expected_redistribution_count >=
       v_pipeline.pool_max_redistributions then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'pool_redistribution_limit_reached',
      'lead_id', p_lead_id
    );
  end if;

  if v_assignment_at >= p_now - make_interval(
       mins => v_timeout_minutes - v_warning_minutes
     ) then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'pool_warning_not_due',
      'lead_id', p_lead_id
    );
  end if;

  if v_assignment_at <= p_now - make_interval(mins => v_timeout_minutes) then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'pool_timeout_already_due',
      'lead_id', p_lead_id
    );
  end if;

  v_has_blocking_activity :=
    (v_lead.first_response_at is not null and v_lead.first_response_at >= v_assignment_at - interval '5 seconds')
    or (v_lead.first_touch_at is not null and v_lead.first_touch_at >= v_assignment_at - interval '5 seconds')
    or (v_lead.owner_last_activity_at is not null and v_lead.owner_last_activity_at >= v_assignment_at - interval '5 seconds')
    or (v_lead.last_contact_at is not null and v_lead.last_contact_at >= v_assignment_at - interval '5 seconds')
    or (v_lead.stage_entered_at is not null and v_lead.stage_entered_at > v_assignment_at + interval '10 seconds');

  if not v_has_blocking_activity then
    select exists (
      select 1
      from public.lead_timeline_events as timeline
      where timeline.organization_id = p_organization_id
        and timeline.lead_id = p_lead_id
        and timeline.created_at >= v_assignment_at - interval '5 seconds'
        and timeline.event_type = any (array[
          'whatsapp_message_sent',
          'first_response',
          'call_initiated',
          'call_completed',
          'note_created',
          'stage_changed',
          'agenda_created',
          'agenda_rescheduled',
          'agenda_completed',
          'agenda_cancelled',
          'schedule_comment'
        ]::text[])
    ) into v_has_blocking_activity;
  end if;

  if not v_has_blocking_activity then
    select exists (
      select 1
      from public.whatsapp_messages as message
      where message.organization_id = p_organization_id
        and message.lead_id = p_lead_id
        and message.created_at >= v_assignment_at - interval '5 seconds'
        and (coalesce(message.from_me, false) = true or message.sender_user_id is not null)
    ) into v_has_blocking_activity;
  end if;

  if v_has_blocking_activity then
    return jsonb_build_object(
      'success', true,
      'warning_sent', false,
      'skipped', true,
      'reason', 'lead_has_activity_after_distribution',
      'lead_id', p_lead_id
    );
  end if;

  insert into public.notifications (
    id,
    organization_id,
    user_id,
    lead_id,
    type,
    title,
    content,
    is_read,
    metadata,
    channel,
    target_url,
    created_at
  )
  values (
    v_notification_id,
    p_organization_id,
    p_expected_assigned_user_id,
    p_lead_id,
    'lead_redistribution_warning',
    'Lead aguardando atendimento',
    'O lead "' || coalesce(nullif(v_lead.name, ''), 'sem nome')
      || '" ainda não teve contato nem movimentação sua. Ele será redistribuído em aproximadamente '
      || v_warning_minutes::text || ' min se continuar parado.',
    false,
    jsonb_build_object(
      'event_key', 'lead_redistribution_warning',
      'dedupe_key', 'lead_redistribution_warning:' || p_lead_id::text
        || ':' || extract(epoch from v_assignment_at)::bigint::text,
      'round_robin_id', p_round_robin_id,
      'assignment_at', v_assignment_at
    ),
    'in_app',
    '/crm/pipelines?lead=' || p_lead_id::text,
    p_now
  );

  update public.leads as lead
  set redistribution_warning_sent_at = p_now,
      updated_at = p_now
  where lead.id = p_lead_id
    and lead.organization_id = p_organization_id
    and lead.assigned_user_id = p_expected_assigned_user_id
    and lead.assigned_at = p_expected_lead_assigned_at
    and lead.redistribution_warning_sent_at is null;

  if not found then
    raise exception using
      errcode = '40001',
      message = 'pool_warning_marker_not_recorded';
  end if;

  return jsonb_build_object(
    'success', true,
    'warning_sent', true,
    'skipped', false,
    'lead_id', p_lead_id,
    'notification_id', v_notification_id,
    'warning_sent_at', p_now
  );
end;
$$;


ALTER FUNCTION public.send_pool_redistribution_warning_from_backend(p_organization_id uuid, p_lead_id uuid, p_round_robin_id uuid, p_expected_assigned_user_id uuid, p_expected_lead_assigned_at timestamp with time zone, p_expected_distribution_assignment_at timestamp with time zone, p_expected_redistribution_count integer, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION send_pool_redistribution_warning_from_backend(p_organization_id uuid, p_lead_id uuid, p_round_robin_id uuid, p_expected_assigned_user_id uuid, p_expected_lead_assigned_at timestamp with time zone, p_expected_distribution_assignment_at timestamp with time zone, p_expected_redistribution_count integer, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.send_pool_redistribution_warning_from_backend(p_organization_id uuid, p_lead_id uuid, p_round_robin_id uuid, p_expected_assigned_user_id uuid, p_expected_lead_assigned_at timestamp with time zone, p_expected_distribution_assignment_at timestamp with time zone, p_expected_redistribution_count integer, p_now timestamp with time zone) IS 'Backend-only pool warning aggregate. It revalidates the assignment and commits the notification and warning marker atomically.';


--
-- Name: set_lead_assigned_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_lead_assigned_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se está sendo atribuído (antes era NULL ou mudou de usuário)
  IF NEW.assigned_user_id IS NOT NULL
     AND (OLD.assigned_user_id IS NULL OR OLD.assigned_user_id != NEW.assigned_user_id) THEN
    NEW.assigned_at := NOW();
    -- Limpar first_touch_at para novo ciclo de redistribuição
    NEW.first_touch_at := NULL;
  END IF;

  -- Se foi removido o responsável, limpar assigned_at
  IF NEW.assigned_user_id IS NULL AND OLD.assigned_user_id IS NOT NULL THEN
    NEW.assigned_at := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_lead_assigned_at() OWNER TO postgres;

--
-- Name: set_lead_assigned_at_on_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_lead_assigned_at_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.assigned_user_id IS NOT NULL THEN
    NEW.assigned_at := NOW();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_lead_assigned_at_on_insert() OWNER TO postgres;

