-- Name: set_round_robin_member_organization_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_round_robin_member_organization_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.organization_id is null and new.round_robin_id is not null then
    select rr.organization_id
      into new.organization_id
      from public.round_robins rr
     where rr.id = new.round_robin_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.set_round_robin_member_organization_id() OWNER TO postgres;

--
-- Name: set_stage_organization_id_from_pipeline(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_stage_organization_id_from_pipeline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_pipeline_organization_id uuid;
begin
  if new.pipeline_id is null then
    return new;
  end if;

  select p.organization_id
    into v_pipeline_organization_id
  from public.pipelines p
  where p.id = new.pipeline_id;

  if v_pipeline_organization_id is null then
    raise exception 'Pipeline % not found for stage organization assignment', new.pipeline_id
      using errcode = 'foreign_key_violation';
  end if;

  if new.organization_id is null then
    new.organization_id := v_pipeline_organization_id;
  elsif new.organization_id <> v_pipeline_organization_id then
    raise exception 'Stage organization_id must match pipeline organization_id'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.set_stage_organization_id_from_pipeline() OWNER TO postgres;

--
-- Name: set_whatsapp_message_context(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_whatsapp_message_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  conversation_org_id uuid;
  conversation_lead_id uuid;
  conversation_session_id uuid;
  conversation_remote_jid text;
  session_org_id uuid;
begin
  if new.conversation_id is not null then
    select
      wc.organization_id,
      wc.lead_id,
      wc.session_id,
      wc.remote_jid
    into
      conversation_org_id,
      conversation_lead_id,
      conversation_session_id,
      conversation_remote_jid
    from public.whatsapp_conversations wc
    where wc.id = new.conversation_id;

    if conversation_org_id is null then
      raise exception 'whatsapp_messages.conversation_id_not_found';
    end if;

    if tg_op = 'UPDATE'
       and new.conversation_id is not distinct from old.conversation_id
       and new.session_id is not distinct from old.session_id then
      new.organization_id := old.organization_id;
      new.session_id := old.session_id;
    else
      new.organization_id := conversation_org_id;
      if new.session_id is null then
        new.session_id := conversation_session_id;
      end if;
    end if;

    if new.lead_id is null then
      new.lead_id := conversation_lead_id;
    end if;

    if new.remote_jid is null then
      new.remote_jid := conversation_remote_jid;
    end if;
  elsif new.organization_id is null and new.session_id is not null then
    select ws.organization_id
    into session_org_id
    from public.whatsapp_sessions ws
    where ws.id = new.session_id;

    new.organization_id := session_org_id;
  end if;

  if new.organization_id is null then
    raise exception 'whatsapp_messages.organization_id_required';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.set_whatsapp_message_context() OWNER TO postgres;

--
-- Name: FUNCTION set_whatsapp_message_context(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.set_whatsapp_message_context() IS 'Derives safe WhatsApp message context while preserving immutable historical session provenance on non-transport updates.';


