--
-- Name: start_automation_execution_from_event(uuid, uuid, uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_automation_execution_from_event(p_event_id uuid, p_automation_id uuid, p_flow_version_id uuid, p_lead_id uuid, p_conversation_id uuid, p_first_node_key text, p_execution_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_row public.automation_event_outbox%rowtype;
  execution_id uuid;
  recent_count integer;
  causal_depth integer := coalesce((p_execution_data->>'causal_depth')::integer, 0);
begin
  select * into event_row
  from public.automation_event_outbox
  where id = p_event_id and status = 'processing'
  for update;

  if event_row.id is null or event_row.lead_id is distinct from p_lead_id or causal_depth < 0 then
    return jsonb_build_object('ok', false, 'status', 'invalid_event');
  end if;
  if causal_depth > 10 then
    update public.automation_event_outbox
    set status = 'dead_letter', dead_lettered_at = now(),
        last_error = 'causal_depth_exceeded', locked_at = null, locked_by = null, updated_at = now()
    where id = p_event_id;
    return jsonb_build_object('ok', false, 'status', 'causal_depth_exceeded');
  end if;

  if not exists (
    select 1
    from public.automations a
    join public.automation_flow_versions fv on fv.id = a.active_flow_version_id
    join public.organization_modules om
      on om.organization_id = a.organization_id
     and lower(trim(om.module_name)) = 'automations'
     and coalesce(om.is_enabled, false) = true
    where a.id = p_automation_id
      and a.organization_id = event_row.organization_id
      and a.is_active = true
      and a.deleted_at is null
      and fv.id = p_flow_version_id
      and fv.requires_review = false
      and fv.first_node_key = p_first_node_key
  ) then
    return jsonb_build_object('ok', false, 'status', 'automation_inactive');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_automation_id::text || ':' || p_lead_id::text, 0)
  );

  select count(*) into recent_count
  from public.automation_executions e
  where e.automation_id = p_automation_id
    and e.lead_id = p_lead_id
    and e.flow_version_id is not null
    and e.started_at >= now() - interval '1 hour';

  if recent_count >= 10 then
    insert into public.automation_circuit_breakers (
      organization_id, automation_id, lead_id, window_started_at,
      execution_count, open_until, reason, updated_at
    ) values (
      event_row.organization_id, p_automation_id, p_lead_id, now() - interval '1 hour',
      recent_count, now() + interval '1 hour', 'max_10_executions_per_hour', now()
    ) on conflict (automation_id, lead_id) do update
      set execution_count = excluded.execution_count,
          open_until = excluded.open_until,
          reason = excluded.reason,
          updated_at = now();
    update public.automation_event_outbox
    set payload = jsonb_set(
          coalesce(payload, '{}'::jsonb),
          '{runtime_decisions}',
          coalesce(payload->'runtime_decisions', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
            'type', 'circuit_open',
            'automation_id', p_automation_id,
            'flow_version_id', p_flow_version_id,
            'recent_count', recent_count,
            'recorded_at', now()
          )),
          true
        ),
        last_error = 'circuit_open',
        updated_at = now()
    where id = p_event_id;
    return jsonb_build_object('ok', false, 'status', 'circuit_open', 'recent_count', recent_count);
  end if;

  begin
    insert into public.automation_executions (
      automation_id, flow_version_id, trigger_event_id, lead_id,
      conversation_id, organization_id, current_node_key, status,
      started_at, execution_data
    ) values (
      p_automation_id, p_flow_version_id, p_event_id, p_lead_id,
      p_conversation_id, event_row.organization_id, p_first_node_key, 'queued',
      now(), coalesce(p_execution_data, '{}'::jsonb)
    ) returning id into execution_id;
  exception when unique_violation then
    update public.automation_event_outbox
    set payload = jsonb_set(
          coalesce(payload, '{}'::jsonb),
          '{runtime_decisions}',
          coalesce(payload->'runtime_decisions', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
            'type', 'duplicate_or_already_active',
            'automation_id', p_automation_id,
            'flow_version_id', p_flow_version_id,
            'recorded_at', now()
          )),
          true
        ),
        last_error = 'duplicate_or_already_active',
        updated_at = now()
    where id = p_event_id;
    return jsonb_build_object('ok', true, 'status', 'duplicate_or_already_active');
  end;

  insert into public.automation_circuit_breakers (
    organization_id, automation_id, lead_id, window_started_at,
    execution_count, open_until, reason, updated_at
  ) values (
    event_row.organization_id, p_automation_id, p_lead_id, now(),
    1, null, null, now()
  ) on conflict (automation_id, lead_id) do update
    set window_started_at = case
          when automation_circuit_breakers.window_started_at < now() - interval '1 hour' then now()
          else automation_circuit_breakers.window_started_at
        end,
        execution_count = recent_count + 1,
        open_until = null,
        reason = null,
        updated_at = now();

  return jsonb_build_object('ok', true, 'status', 'queued', 'execution_id', execution_id);
end;
$$;


ALTER FUNCTION public.start_automation_execution_from_event(p_event_id uuid, p_automation_id uuid, p_flow_version_id uuid, p_lead_id uuid, p_conversation_id uuid, p_first_node_key text, p_execution_data jsonb) OWNER TO postgres;

--
-- Name: start_whatsapp_webhook_edge_execution(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_whatsapp_webhook_edge_execution(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_organization_id is null or p_session_id is null or p_inbox_id is null
    or p_execution_id is null
  then
    return false;
  end if;

  perform 1 from public.whatsapp_sessions as session
  where session.id = p_session_id
    and session.organization_id = p_organization_id
    and session.provider = 'evolution_go'
  for key share;
  if not found or exists (
    select 1 from private.whatsapp_webhook_session_cutovers as cutover
    where cutover.session_id = p_session_id
  ) then
    return false;
  end if;

  update public.whatsapp_webhook_inbox as inbox
  set edge_execution_state = 'active',
      edge_execution_started_at = clock_timestamp(),
      updated_at = now()
  where inbox.id = p_inbox_id
    and inbox.organization_id = p_organization_id
    and inbox.session_id = p_session_id
    and inbox.provider = 'evolution_go'
    and inbox.processing_epoch = 0
    and inbox.status = 'processing'
    and inbox.edge_execution_id = p_execution_id
    and inbox.edge_execution_state = 'reserved';
  return found;
end;
$$;


ALTER FUNCTION public.start_whatsapp_webhook_edge_execution(p_organization_id uuid, p_session_id uuid, p_inbox_id uuid, p_execution_id uuid) OWNER TO postgres;

--
-- Name: store_billing_card_recurrence_credential(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.store_billing_card_recurrence_credential(p_payment_id uuid, p_provider_payment_id text, p_credential_ciphertext text, p_card_last4 text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.store_billing_card_recurrence_credential(
    p_payment_id,
    p_provider_payment_id,
    null::uuid,
    p_credential_ciphertext,
    p_card_last4
  );
$$;


ALTER FUNCTION public.store_billing_card_recurrence_credential(p_payment_id uuid, p_provider_payment_id text, p_credential_ciphertext text, p_card_last4 text) OWNER TO postgres;

--
-- Name: store_billing_card_recurrence_credential(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.store_billing_card_recurrence_credential(p_payment_id uuid, p_provider_payment_id text, p_attempt_lease_id uuid, p_credential_ciphertext text, p_card_last4 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_credential text := nullif(btrim(coalesce(p_credential_ciphertext, '')), '');
  v_card_last4 text := btrim(coalesce(p_card_last4, ''));
  v_payment public.asaas_payments%rowtype;
  v_org public.organizations%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if p_payment_id is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255
     or v_credential is null
     or char_length(v_credential) < 35
     or char_length(v_credential) > 4096
     or v_credential !~ '^v1[.][A-Za-z0-9._-]+$'
     or v_card_last4 !~ '^[0-9]{4}$' then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  perform private.lock_asaas_billing_resources(v_provider_payment_id, null);

  -- The ciphertext is an Edge-owned AES-GCM envelope whose AAD binds both the
  -- canonical local payment UUID and immutable provider payment id. SQL never
  -- receives token, remoteIp, PAN or CVV.
  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = v_payment.organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'organization_not_found');
  end if;
  if not v_org.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  select capability.*
  into v_capability
  from public.billing_payment_checkout_capabilities as capability
  where capability.payment_id = v_payment.id
    and capability.asaas_payment_id = v_payment.asaas_payment_id
    and capability.organization_id = v_payment.organization_id
    and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  if not private.billing_payment_checkout_is_paid(v_payment.status)
     and (
       p_attempt_lease_id is null
       or v_capability.payment_id is null
       or v_capability.revoked_at is not null
       or v_capability.expires_at <= v_now
       or v_capability.attempt_lease_id is distinct from p_attempt_lease_id
       or v_capability.attempt_lease_expires_at <= v_now
     ) then
    return jsonb_build_object('outcome', 'attempt_lease_not_found');
  end if;
  if not (
    private.billing_payment_checkout_is_actionable(v_payment.status)
    or private.billing_payment_checkout_is_processing(v_payment.status)
    or private.billing_payment_checkout_is_paid(v_payment.status)
  ) then
    return jsonb_build_object(
      'outcome', 'payment_not_eligible',
      'payment_status', upper(btrim(coalesce(v_payment.status, '')))
    );
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
    and provision.provider_payment_id = v_payment.asaas_payment_id
    and provision.organization_id = v_payment.organization_id
    and provision.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'not_prepared');
  end if;
  if v_provision.status = 'completed' then
    return jsonb_build_object('outcome', 'already_completed');
  end if;
  if v_provision.status not in ('prepared', 'failed')
     or v_provision.lease_id is not null
     or v_provision.lease_expires_at is not null then
    return jsonb_build_object('outcome', 'state_not_storable');
  end if;

  if v_provision.provider_card_credential is not null then
    if v_provision.provider_card_credential = v_credential
       and v_provision.card_last4 = v_card_last4
       and v_provision.credential_attempt_lease_id
         is not distinct from p_attempt_lease_id then
      return jsonb_build_object(
        'outcome', 'already_stored',
        'payment_id', v_provision.payment_id
      );
    end if;
    return jsonb_build_object('outcome', 'credential_conflict');
  end if;

  update private.billing_card_recurrence_provisions as provision
  set
    status = 'prepared',
    provider_card_credential = v_credential,
    card_last4 = v_card_last4,
    credential_attempt_lease_id = p_attempt_lease_id,
    job_action = 'create',
    job_status = case
      when private.billing_payment_checkout_is_paid(v_payment.status)
        then 'pending'
      else 'waiting'
    end,
    job_attempts = 0,
    job_next_attempt_at = v_now,
    job_locked_at = null,
    job_lock_expires_at = null,
    job_locked_by = null,
    job_lease_id = null,
    job_dead_lettered_at = null,
    job_last_error_code = null,
    failed_at = null,
    last_error = null,
    updated_at = v_now
  where provision.payment_id = v_provision.payment_id
    and provision.provider_payment_id = v_provision.provider_payment_id
    and provision.status in ('prepared', 'failed')
    and provision.provider_card_credential is null
    and provision.lease_id is null
    and provision.lease_expires_at is null;

  if not found then
    return jsonb_build_object('outcome', 'state_changed');
  end if;

  return jsonb_build_object(
    'outcome', 'stored',
    'payment_id', v_provision.payment_id,
    'card_last4', v_card_last4
  );
end
$_$;


ALTER FUNCTION public.store_billing_card_recurrence_credential(p_payment_id uuid, p_provider_payment_id text, p_attempt_lease_id uuid, p_credential_ciphertext text, p_card_last4 text) OWNER TO postgres;

--
-- Name: FUNCTION store_billing_card_recurrence_credential(p_payment_id uuid, p_provider_payment_id text, p_attempt_lease_id uuid, p_credential_ciphertext text, p_card_last4 text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.store_billing_card_recurrence_credential(p_payment_id uuid, p_provider_payment_id text, p_attempt_lease_id uuid, p_credential_ciphertext text, p_card_last4 text) IS 'Stores one opaque v1 AES-GCM recurrence credential under the exact live payment-attempt lease; SQL never receives provider token, remoteIp, PAN or CVV separately.';


--
-- Name: store_billing_checkout_payment(uuid, uuid, text, text, text, text, text, numeric, numeric, date, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.store_billing_checkout_payment(p_intent_id uuid, p_organization_id uuid, p_payment_id text, p_customer_id text DEFAULT NULL::text, p_subscription_id text DEFAULT NULL::text, p_billing_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_value numeric DEFAULT NULL::numeric, p_net_value numeric DEFAULT NULL::numeric, p_due_date date DEFAULT NULL::date, p_payment_date date DEFAULT NULL::date, p_invoice_url text DEFAULT NULL::text, p_raw_event jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_intent private.billing_checkout_intents%rowtype;
  v_existing public.asaas_payments%rowtype;
  v_payment_id text := nullif(btrim(coalesce(p_payment_id, '')), '');
  v_customer_id text := nullif(btrim(coalesce(p_customer_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_subscription_id, '')), '');
  v_billing_type text := upper(nullif(btrim(coalesce(p_billing_type, '')), ''));
  v_status text := upper(nullif(btrim(coalesce(p_status, '')), ''));
  v_stored_status text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required'
      using errcode = '42501';
  end if;

  if p_intent_id is null
     or p_organization_id is null
     or v_payment_id is null
     or jsonb_typeof(coalesce(p_raw_event, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid billing payment persistence'
      using errcode = '22023';
  end if;

  perform private.lock_asaas_billing_resources(
    v_payment_id,
    v_subscription_id
  );

  select *
  into v_intent
  from private.billing_checkout_intents
  where id = p_intent_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'intent_not_found');
  end if;

  if v_intent.organization_id is distinct from p_organization_id then
    raise exception 'billing intent belongs to a different organization'
      using errcode = '22023';
  end if;

  if v_intent.status not in ('creating', 'pending', 'confirmed') then
    return jsonb_build_object('outcome', 'intent_not_storeable');
  end if;

  if v_intent.provider_customer_id is not null
     and v_customer_id is not null
     and v_intent.provider_customer_id <> v_customer_id then
    raise exception 'payment customer does not match billing intent'
      using errcode = '22023';
  end if;

  if v_intent.provider_subscription_id is not null
     and v_subscription_id is not null
     and v_intent.provider_subscription_id <> v_subscription_id then
    raise exception 'payment subscription does not match billing intent'
      using errcode = '22023';
  end if;

  if v_intent.billing_method in ('PIX', 'BOLETO')
     and v_intent.provider_payment_id is not null
     and v_intent.provider_payment_id <> v_payment_id then
    raise exception 'payment does not match one-off billing intent'
      using errcode = '22023';
  end if;

  if v_billing_type is not null
     and v_billing_type <> v_intent.billing_method then
    raise exception 'payment method does not match billing intent'
      using errcode = '22023';
  end if;

  select *
  into v_existing
  from public.asaas_payments
  where asaas_payment_id = v_payment_id
  for update;

  if found then
    if v_existing.organization_id is distinct from p_organization_id then
      raise exception 'provider payment belongs to a different organization'
        using errcode = '22023';
    end if;

    if v_existing.billing_intent_id is not null
       and v_existing.billing_intent_id is distinct from p_intent_id then
      raise exception 'provider payment belongs to a different billing intent'
        using errcode = '22023';
    end if;
  end if;

  insert into public.asaas_payments (
    organization_id,
    billing_intent_id,
    asaas_payment_id,
    asaas_customer_id,
    asaas_subscription_id,
    status,
    billing_type,
    value,
    net_value,
    due_date,
    payment_date,
    invoice_url,
    raw_event
  )
  values (
    p_organization_id,
    p_intent_id,
    v_payment_id,
    coalesce(v_customer_id, v_intent.provider_customer_id),
    coalesce(v_subscription_id, v_intent.provider_subscription_id),
    v_status,
    coalesce(v_billing_type, v_intent.billing_method),
    p_value,
    p_net_value,
    p_due_date,
    p_payment_date,
    nullif(btrim(coalesce(p_invoice_url, '')), ''),
    coalesce(p_raw_event, '{}'::jsonb)
  )
  on conflict (asaas_payment_id) do update
  set
    billing_intent_id = excluded.billing_intent_id,
    asaas_customer_id = coalesce(
      public.asaas_payments.asaas_customer_id,
      excluded.asaas_customer_id
    ),
    asaas_subscription_id = coalesce(
      public.asaas_payments.asaas_subscription_id,
      excluded.asaas_subscription_id
    ),
    status = case
      when public.asaas_payments.last_webhook_event_at is not null
        then public.asaas_payments.status
      else coalesce(excluded.status, public.asaas_payments.status)
    end,
    billing_type = coalesce(
      public.asaas_payments.billing_type,
      excluded.billing_type
    ),
    value = case
      when public.asaas_payments.last_webhook_event_at is not null
        then public.asaas_payments.value
      else coalesce(excluded.value, public.asaas_payments.value)
    end,
    net_value = case
      when public.asaas_payments.last_webhook_event_at is not null
        then public.asaas_payments.net_value
      else coalesce(excluded.net_value, public.asaas_payments.net_value)
    end,
    due_date = case
      when public.asaas_payments.last_webhook_event_at is not null
        then public.asaas_payments.due_date
      else coalesce(excluded.due_date, public.asaas_payments.due_date)
    end,
    payment_date = case
      when public.asaas_payments.last_webhook_event_at is not null
        then public.asaas_payments.payment_date
      else coalesce(excluded.payment_date, public.asaas_payments.payment_date)
    end,
    invoice_url = case
      when public.asaas_payments.last_webhook_event_at is not null
        then public.asaas_payments.invoice_url
      else coalesce(excluded.invoice_url, public.asaas_payments.invoice_url)
    end,
    raw_event = case
      when public.asaas_payments.last_webhook_event_at is not null
        then public.asaas_payments.raw_event
      else excluded.raw_event
    end,
    updated_at = now()
  returning status into v_stored_status;

  return jsonb_build_object(
    'outcome', 'stored',
    'intent_id', p_intent_id,
    'payment_id', v_payment_id,
    'status', v_stored_status
  );
end;
$$;


ALTER FUNCTION public.store_billing_checkout_payment(p_intent_id uuid, p_organization_id uuid, p_payment_id text, p_customer_id text, p_subscription_id text, p_billing_type text, p_status text, p_value numeric, p_net_value numeric, p_due_date date, p_payment_date date, p_invoice_url text, p_raw_event jsonb) OWNER TO postgres;

--
-- Name: store_billing_subscription_card_update_credential(uuid, uuid, bigint, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.store_billing_subscription_card_update_credential(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_attempt_lease_id uuid, p_credential_ciphertext text, p_card_last4 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_credential text := nullif(
    btrim(coalesce(p_credential_ciphertext, '')),
    ''
  );
  v_card_last4 text := btrim(coalesce(p_card_last4, ''));
  v_job_hint private.billing_subscription_card_update_jobs%rowtype;
  v_job private.billing_subscription_card_update_jobs%rowtype;
  v_payment public.asaas_payments%rowtype;
  v_capability public.billing_payment_checkout_capabilities%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_now timestamptz := clock_timestamp();
  v_next_status text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or p_generation is null
     or p_generation <= 0
     or v_credential is null
     or char_length(v_credential) not between 35 and 4096
     or v_credential !~ '^v1[.][A-Za-z0-9._-]+$'
     or v_card_last4 !~ '^[0-9]{4}$' then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_job_hint
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_job_hint.provider_payment_id,
    v_job_hint.provider_subscription_id
  );

  if v_job_hint.mode = 'settled_payment' then
    select payment.*
    into v_payment
    from public.asaas_payments as payment
    where payment.id = v_job_hint.payment_id
      and payment.organization_id = p_organization_id
      and payment.asaas_payment_id = v_job_hint.provider_payment_id
    for update;
    if not found then
      return jsonb_build_object('outcome', 'payment_not_found');
    end if;

    select capability.*
    into v_capability
    from public.billing_payment_checkout_capabilities as capability
    where capability.payment_id = v_payment.id
      and capability.organization_id = v_payment.organization_id
      and capability.asaas_payment_id = v_payment.asaas_payment_id
      and capability.billing_intent_id is not distinct from v_payment.billing_intent_id
    for update;
  end if;

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;
  if not v_org.is_active then
    return jsonb_build_object('outcome', 'organization_inactive');
  end if;

  select subscription.*
  into v_subscription
  from public.subscriptions as subscription
  where subscription.id = v_job_hint.subscription_id
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  if v_job.status in ('succeeded', 'cancelled', 'dead') then
    return jsonb_build_object(
      'outcome', 'already_finalized',
      'status', v_job.status,
      'last_error_code', v_job.last_error_code
    );
  end if;
  if v_job.expires_at <= v_now then
    update private.billing_subscription_card_update_jobs
    set
      status = 'dead',
      provider_card_credential = null,
      credential_attempt_lease_id = null,
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      last_error_code = 'credential_expired',
      dead_lettered_at = v_now,
      updated_at = v_now
    where id = v_job.id;
    return jsonb_build_object('outcome', 'expired');
  end if;
  if v_job.status <> 'prepared' then
    if v_job.provider_card_credential = v_credential
       and v_job.card_last4 = v_card_last4
       and v_job.credential_attempt_lease_id
         is not distinct from p_attempt_lease_id then
      return jsonb_build_object(
        'outcome', 'already_stored',
        'job_id', v_job.id,
        'status', v_job.status
      );
    end if;
    return jsonb_build_object('outcome', 'state_not_storable');
  end if;

  if v_org.asaas_subscription_id
       is distinct from v_job.provider_subscription_id
     or v_org.asaas_customer_id is distinct from v_job.provider_customer_id
     or not v_org.is_active
     or lower(btrim(coalesce(v_org.subscription_status, ''))) <> 'active'
     or v_subscription.organization_id is distinct from p_organization_id
     or v_subscription.provider_subscription_id
       is distinct from v_job.provider_subscription_id
     or v_subscription.provider_customer_id
       is distinct from v_job.provider_customer_id
     or lower(v_subscription.status) <> 'active'
     or exists (
       select 1
       from private.billing_plan_changes as plan_change
       where plan_change.organization_id = p_organization_id
         and plan_change.provider_subscription_id
           = v_job.provider_subscription_id
         and plan_change.status in ('provider_updating', 'applying')
     )
     or exists (
       select 1
       from private.billing_subscription_checkout_cancellations as cancellation
       where cancellation.organization_id = p_organization_id
         and cancellation.provider_subscription_id
           = v_job.provider_subscription_id
         and (
           cancellation.finalized_at is null
           or cancellation.final_outcome = 'manual_review'
         )
     )
     or private.billing_card_recurrence_cancel_state(
       p_organization_id,
       v_job.provider_subscription_id
     ) is not null
     or private.billing_organization_cleanup_is_active(
       p_organization_id,
       v_job.provider_subscription_id
     ) then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  if v_job.mode = 'saved_only' and p_attempt_lease_id is not null then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  if v_job.mode = 'settled_payment' then
    if upper(btrim(coalesce(v_payment.billing_type, ''))) <> 'CREDIT_CARD'
       or v_payment.asaas_customer_id
         is distinct from v_job.provider_customer_id
       or not (
         private.billing_payment_checkout_is_actionable(v_payment.status)
         or private.billing_payment_checkout_is_processing(v_payment.status)
         or private.billing_payment_checkout_is_paid(v_payment.status)
       ) then
      return jsonb_build_object('outcome', 'payment_not_eligible');
    end if;

    if exists (
      select 1
      from private.billing_payment_checkout_cancellations as cancellation
      where cancellation.payment_id = v_payment.id
        and (
          cancellation.finalized_at is null
          or cancellation.final_outcome = 'manual_review'
        )
    ) then
      return jsonb_build_object(
        'outcome', 'busy',
        'busy_reason', 'payment_cancellation'
      );
    end if;

    if not private.billing_payment_checkout_is_paid(v_payment.status) and (
         p_attempt_lease_id is null
         or v_capability.payment_id is null
         or v_capability.revoked_at is not null
         or v_capability.expires_at <= v_now
         or v_capability.attempt_lease_id is distinct from p_attempt_lease_id
         or v_capability.attempt_lease_expires_at <= v_now
       ) then
      return jsonb_build_object('outcome', 'attempt_lease_not_found');
    end if;

    if private.billing_payment_checkout_is_paid(v_payment.status)
       and p_attempt_lease_id is not null
       and (
         v_capability.payment_id is null
         or v_capability.attempt_lease_id is distinct from p_attempt_lease_id
         or v_capability.attempt_lease_expires_at <= v_now
       ) then
      return jsonb_build_object('outcome', 'attempt_lease_not_found');
    end if;
  end if;

  v_next_status := case
    when v_job.mode = 'saved_only' then 'pending_update'
    when private.billing_payment_checkout_is_paid(v_payment.status)
      then 'pending_update'
    else 'awaiting_payment'
  end;

  update private.billing_subscription_card_update_jobs as job
  set
    status = v_next_status,
    provider_card_credential = v_credential,
    card_last4 = v_card_last4,
    credential_attempt_lease_id = p_attempt_lease_id,
    credential_stored_at = v_now,
    next_attempt_at = v_now,
    last_error_code = null,
    updated_at = v_now
  where job.id = v_job.id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
    and job.status = 'prepared'
    and job.provider_card_credential is null;
  if not found then
    return jsonb_build_object('outcome', 'state_changed');
  end if;

  return jsonb_build_object(
    'outcome', 'stored',
    'job_id', v_job.id,
    'generation', v_job.generation,
    'status', v_next_status,
    'card_last4', v_card_last4
  );
end
$_$;


ALTER FUNCTION public.store_billing_subscription_card_update_credential(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_attempt_lease_id uuid, p_credential_ciphertext text, p_card_last4 text) OWNER TO postgres;

--
-- Name: succeed_billing_card_recurrence_job(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.succeed_billing_card_recurrence_job(p_payment_id uuid, p_provider_payment_id text, p_worker_id text, p_job_lease_id uuid, p_provider_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_provider_payment_id text := nullif(btrim(coalesce(p_provider_payment_id, '')), '');
  v_worker_id text := nullif(btrim(coalesce(p_worker_id, '')), '');
  v_preliminary_subscription_id text;
  v_result_subscription_id text;
  v_result_outcome text;
  v_payment public.asaas_payments%rowtype;
  v_provision private.billing_card_recurrence_provisions%rowtype;
  v_complete jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_payment_id is null
     or v_provider_payment_id is null
     or char_length(v_provider_payment_id) > 255
     or v_worker_id is null
     or char_length(v_worker_id) > 128
     or v_worker_id !~ '^[A-Za-z0-9._:-]+$'
     or p_job_lease_id is null
     or p_provider_result is null
     or jsonb_typeof(p_provider_result) <> 'object' then
    return jsonb_build_object('outcome', 'invalid_input');
  end if;

  select provision.provider_subscription_id
  into v_preliminary_subscription_id
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = p_payment_id
    and provision.provider_payment_id = v_provider_payment_id;

  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  v_result_subscription_id := nullif(btrim(coalesce(
    p_provider_result ->> 'id',
    p_provider_result ->> 'subscription_id',
    ''
  )), '');
  perform private.lock_asaas_billing_resources(
    v_provider_payment_id,
    coalesce(v_preliminary_subscription_id, v_result_subscription_id)
  );

  select payment.*
  into v_payment
  from public.asaas_payments as payment
  where payment.id = p_payment_id
    and payment.asaas_payment_id = v_provider_payment_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'payment_not_found');
  end if;

  select provision.*
  into v_provision
  from private.billing_card_recurrence_provisions as provision
  where provision.payment_id = v_payment.id
    and provision.provider_payment_id = v_payment.asaas_payment_id
    and provision.organization_id = v_payment.organization_id
    and provision.billing_intent_id is not distinct from v_payment.billing_intent_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  v_result_outcome := lower(nullif(btrim(coalesce(
    p_provider_result ->> 'outcome',
    ''
  )), ''));

  -- A committed success can lose its HTTP response. Replaying that exact
  -- acknowledgement is idempotent even after the lease fields were cleared.
  -- Creation reuses the full immutable provider-snapshot validator; cancelled
  -- jobs require the exact stored subscription id and terminal delete result.
  if v_provision.status = 'completed'
     and v_result_subscription_id is not null
     and p_provider_result ? 'customer' then
    v_complete := private.complete_billing_card_recurrence_locked(
      v_payment.id,
      v_payment.asaas_payment_id,
      null,
      p_provider_result,
      false
    );
    return v_complete || jsonb_build_object(
      'job_action', 'create',
      'worker_id', v_worker_id
    );
  end if;

  if v_provision.status = 'cancelled'
     and v_provision.job_status = 'succeeded'
     and v_result_subscription_id
       is not distinct from v_provision.provider_subscription_id
     and v_result_outcome in ('deleted', 'already_absent') then
    return jsonb_build_object(
      'outcome', 'already_succeeded',
      'job_action', 'cancel',
      'payment_id', v_provision.payment_id,
      'provider_subscription_id', v_provision.provider_subscription_id,
      'provider_outcome', v_result_outcome
    );
  end if;

  if v_provision.job_status <> 'processing'
     or v_provision.job_locked_by is distinct from v_worker_id
     or v_provision.job_lease_id is distinct from p_job_lease_id then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  if v_provision.job_action = 'create' then
    if v_provision.lease_id is distinct from p_job_lease_id then
      return jsonb_build_object('outcome', 'lease_not_found');
    end if;

    v_complete := private.complete_billing_card_recurrence_locked(
      v_payment.id,
      v_payment.asaas_payment_id,
      p_job_lease_id,
      p_provider_result,
      true
    );
    return v_complete || jsonb_build_object(
      'job_action', 'create',
      'worker_id', v_worker_id
    );
  end if;

  if v_provision.job_action <> 'cancel'
     or v_provision.status <> 'completed'
     or not private.billing_payment_checkout_is_reversal(v_payment.status) then
    return jsonb_build_object('outcome', 'state_not_succeedable');
  end if;

  if v_result_subscription_id is distinct from v_provision.provider_subscription_id
     or v_result_outcome not in ('deleted', 'already_absent') then
    return jsonb_build_object('outcome', 'invalid_provider_result');
  end if;

  update private.billing_card_recurrence_provisions as provision
  set
    status = 'cancelled',
    provider_card_credential = null,
    card_last4 = null,
    lease_id = null,
    lease_expires_at = null,
    provider_cancelled_at = coalesce(provision.provider_cancelled_at, v_now),
    job_status = 'succeeded',
    job_locked_at = null,
    job_lock_expires_at = null,
    job_locked_by = null,
    job_lease_id = null,
    job_dead_lettered_at = null,
    job_last_error_code = null,
    updated_at = v_now
  where provision.payment_id = v_provision.payment_id
    and provision.job_status = 'processing'
    and provision.job_action = 'cancel'
    and provision.job_locked_by = v_worker_id
    and provision.job_lease_id = p_job_lease_id;

  if not found then
    return jsonb_build_object('outcome', 'lease_not_found');
  end if;

  update public.organizations as organization_row
  set
    asaas_subscription_id = null,
    next_billing_date = null,
    updated_at = v_now
  where organization_row.id = v_provision.organization_id
    and organization_row.asaas_subscription_id
      is not distinct from v_provision.provider_subscription_id;

  update public.subscriptions as subscription
  set
    status = 'cancelled',
    metadata = coalesce(subscription.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'card_recurrence_cancelled_at', v_now,
        'card_recurrence_cancel_outcome', v_result_outcome
      ),
    updated_at = v_now
  where subscription.organization_id = v_provision.organization_id
    and subscription.provider_subscription_id
      = v_provision.provider_subscription_id;

  delete from private.asaas_reconciliation_jobs as reconciliation_job
  where reconciliation_job.organization_id = v_provision.organization_id
    and reconciliation_job.provider_subscription_id
      = v_provision.provider_subscription_id;

  insert into public.subscription_logs (
    organization_id,
    event_type,
    status,
    metadata
  )
  values (
    v_provision.organization_id,
    'billing_card_recurrence_cancelled',
    'cancelled',
    jsonb_build_object(
      'payment_id', v_provision.payment_id,
      'billing_intent_id', v_provision.billing_intent_id,
      'provider_subscription_id', v_provision.provider_subscription_id,
      'provider_outcome', v_result_outcome
    )
  );

  return jsonb_build_object(
    'outcome', 'cancelled',
    'job_action', 'cancel',
    'payment_id', v_provision.payment_id,
    'provider_subscription_id', v_provision.provider_subscription_id,
    'provider_outcome', v_result_outcome
  );
end
$_$;


ALTER FUNCTION public.succeed_billing_card_recurrence_job(p_payment_id uuid, p_provider_payment_id text, p_worker_id text, p_job_lease_id uuid, p_provider_result jsonb) OWNER TO postgres;

--
-- Name: succeed_billing_subscription_card_update_job(uuid, uuid, bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.succeed_billing_subscription_card_update_job(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_job_lease_id uuid, p_provider_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_hint private.billing_subscription_card_update_jobs%rowtype;
  v_job private.billing_subscription_card_update_jobs%rowtype;
  v_org public.organizations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_sanitized jsonb;
  v_now timestamptz := clock_timestamp();
  v_target_valid boolean := true;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_job_id is null
     or p_organization_id is null
     or p_generation is null
     or p_generation <= 0
     or p_job_lease_id is null
     or jsonb_typeof(p_provider_snapshot) is distinct from 'object' then
    return jsonb_build_object('outcome', 'invalid_request');
  end if;

  select job.*
  into v_hint
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id;
  if not found then
    return jsonb_build_object('outcome', 'job_not_found');
  end if;

  perform private.lock_asaas_billing_resources(
    v_hint.provider_payment_id,
    v_hint.provider_subscription_id
  );

  select organization.*
  into v_org
  from public.organizations as organization
  where organization.id = p_organization_id
  for update;
  if not found then
    v_target_valid := false;
  end if;

  select subscription.*
  into v_subscription
  from public.subscriptions as subscription
  where subscription.id = v_hint.subscription_id
  for update;
  if not found then
    v_target_valid := false;
  end if;

  select job.*
  into v_job
  from private.billing_subscription_card_update_jobs as job
  where job.id = p_job_id
    and job.organization_id = p_organization_id
    and job.generation = p_generation
  for update;
  if not found then
    return jsonb_build_object('outcome', 'identifier_mismatch');
  end if;

  if v_job.status = 'succeeded' then
    return jsonb_build_object(
      'outcome', 'already_succeeded',
      'job_id', v_job.id,
      'card_last4', v_job.card_last4,
      'completed_at', v_job.completed_at
    );
  end if;
  if v_job.status in ('cancelled', 'dead') then
    return jsonb_build_object(
      'outcome', case
        when v_job.manual_review_at is not null then 'manual_review'
        else 'already_finalized'
      end,
      'status', v_job.status,
      'last_error_code', v_job.last_error_code
    );
  end if;
  if v_job.status <> 'processing'
     or v_job.lease_id is distinct from p_job_lease_id
     or v_job.lease_expires_at <= v_now
     or v_job.provider_request_lease_id is distinct from p_job_lease_id
     or v_job.provider_request_started_at is null then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  if nullif(btrim(coalesce(p_provider_snapshot ->> 'id', '')), '')
       is distinct from v_job.provider_subscription_id
     or nullif(btrim(coalesce(p_provider_snapshot ->> 'customer', '')), '')
       is distinct from v_job.provider_customer_id
     or upper(btrim(coalesce(p_provider_snapshot ->> 'status', '')))
       <> 'ACTIVE' then
    return jsonb_build_object('outcome', 'provider_snapshot_mismatch');
  end if;

  v_target_valid := v_target_valid
    and coalesce(v_org.is_active, false)
    and lower(btrim(coalesce(v_org.subscription_status, ''))) = 'active'
    and v_org.asaas_subscription_id = v_job.provider_subscription_id
    and v_org.asaas_customer_id = v_job.provider_customer_id
    and v_subscription.organization_id = p_organization_id
    and v_subscription.provider_subscription_id
      = v_job.provider_subscription_id
    and v_subscription.provider_customer_id = v_job.provider_customer_id
    and lower(v_subscription.status) = 'active';

  if not v_target_valid then
    update private.billing_subscription_card_update_jobs
    set
      status = 'dead',
      provider_card_credential = null,
      credential_attempt_lease_id = null,
      lease_id = null,
      lease_owner = null,
      lease_started_at = null,
      lease_expires_at = null,
      last_error_code = 'provider_update_succeeded_after_target_changed',
      manual_review_at = v_now,
      dead_lettered_at = v_now,
      updated_at = v_now
    where id = v_job.id
      and status = 'processing'
      and lease_id = p_job_lease_id;
    return jsonb_build_object(
      'outcome', 'manual_review',
      'last_error_code', 'provider_update_succeeded_after_target_changed'
    );
  end if;

  v_sanitized := jsonb_strip_nulls(jsonb_build_object(
    'id', v_job.provider_subscription_id,
    'customer', v_job.provider_customer_id,
    'status', 'ACTIVE',
    'cycle', nullif(btrim(coalesce(p_provider_snapshot ->> 'cycle', '')), ''),
    'nextDueDate', nullif(
      btrim(coalesce(p_provider_snapshot ->> 'nextDueDate', '')),
      ''
    )
  ));

  update private.billing_subscription_card_update_jobs
  set
    status = 'succeeded',
    provider_card_credential = null,
    credential_attempt_lease_id = null,
    lease_id = null,
    lease_owner = null,
    lease_started_at = null,
    lease_expires_at = null,
    provider_snapshot = v_sanitized,
    last_error_code = null,
    manual_review_at = null,
    completed_at = v_now,
    updated_at = v_now
  where id = v_job.id
    and status = 'processing'
    and lease_id = p_job_lease_id
    and provider_request_lease_id = p_job_lease_id;
  if not found then
    return jsonb_build_object('outcome', 'lost_claim');
  end if;

  update public.subscriptions
  set
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'billing_card', jsonb_build_object(
        'last4', v_job.card_last4,
        'updated_at', v_now,
        'generation', v_job.generation,
        'job_id', v_job.id
      )
    ),
    updated_at = v_now
  where id = v_job.subscription_id
    and organization_id = p_organization_id
    and provider_subscription_id = v_job.provider_subscription_id;

  return jsonb_build_object(
    'outcome', 'succeeded',
    'job_id', v_job.id,
    'generation', v_job.generation,
    'card_last4', v_job.card_last4,
    'completed_at', v_now
  );
end
$$;


ALTER FUNCTION public.succeed_billing_subscription_card_update_job(p_job_id uuid, p_organization_id uuid, p_generation bigint, p_job_lease_id uuid, p_provider_snapshot jsonb) OWNER TO postgres;

--
-- Name: sync_commission_rule_percentage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_commission_rule_percentage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.commission_type = 'percentage' then
    new.percentage := coalesce(new.commission_value, new.percentage, 0);
  elsif new.percentage is null then
    new.percentage := 0;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.sync_commission_rule_percentage() OWNER TO postgres;

--
-- Name: sync_historical_commissions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_historical_commissions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  lead_record RECORD;
  commission_percentage numeric;
  commission_amount numeric;
  created_count integer := 0;
  skipped_count integer := 0;
BEGIN
  -- Buscar todos os leads won sem comissão
  FOR lead_record IN
    SELECT l.id, l.organization_id, l.assigned_user_id, l.property_id,
           l.valor_interesse, l.commission_percentage as lead_commission,
           p.commission_percentage as property_commission,
           o.default_commission_percentage as org_commission
    FROM leads l
    LEFT JOIN properties p ON p.id = l.property_id
    LEFT JOIN organizations o ON o.id = l.organization_id
    LEFT JOIN commissions c ON c.lead_id = l.id
    WHERE l.deal_status = 'won'
      AND l.valor_interesse > 0
      AND c.id IS NULL
  LOOP
    -- Determinar percentual de comissão (lead -> property -> organization -> default 5%)
    commission_percentage := COALESCE(
      NULLIF(lead_record.lead_commission, 0),
      NULLIF(lead_record.property_commission, 0),
      NULLIF(lead_record.org_commission, 0),
      5.0
    );

    commission_amount := lead_record.valor_interesse * (commission_percentage / 100);

    -- Pular se não tem user atribuído
    IF lead_record.assigned_user_id IS NULL THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;

    -- Criar comissão
    INSERT INTO commissions (
      organization_id,
      lead_id,
      user_id,
      property_id,
      base_value,
      amount,
      percentage,
      status,
      notes
    ) VALUES (
      lead_record.organization_id,
      lead_record.id,
      lead_record.assigned_user_id,
      lead_record.property_id,
      lead_record.valor_interesse,
      commission_amount,
      commission_percentage,
      'forecast',
      'Comissão gerada automaticamente (migração)'
    );

    created_count := created_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'created', created_count,
    'skipped', skipped_count,
    'message', format('Criadas %s comissões, %s ignoradas (sem responsável)', created_count, skipped_count)
  );
END;
$$;


ALTER FUNCTION public.sync_historical_commissions() OWNER TO postgres;

--
-- Name: sync_lead_seller_to_customer(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_lead_seller_to_customer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Quando assigned_user_id do lead muda, atualizar o seller_id do telecom_customer correspondente
  IF NEW.assigned_user_id IS NOT NULL AND
     (OLD.assigned_user_id IS NULL OR OLD.assigned_user_id != NEW.assigned_user_id) THEN

    UPDATE telecom_customers
    SET seller_id = NEW.assigned_user_id
    WHERE organization_id = NEW.organization_id
      AND name = NEW.name;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_lead_seller_to_customer() OWNER TO postgres;

--
-- Name: sync_telecom_customer_plan_value(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_telecom_customer_plan_value() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan_price numeric;
BEGIN
  -- Se plan_id foi definido/alterado e plan_value não foi informado, preencher com o preço do plano
  IF NEW.plan_id IS NOT NULL AND (NEW.plan_value IS NULL OR TG_OP = 'INSERT' OR OLD.plan_id IS DISTINCT FROM NEW.plan_id) THEN
    -- Se o plan_id mudou, atualiza o plan_value com o preço do plano
    IF TG_OP = 'INSERT' OR OLD.plan_id IS DISTINCT FROM NEW.plan_id THEN
      SELECT price INTO v_plan_price
      FROM service_plans
      WHERE id = NEW.plan_id;

      IF v_plan_price IS NOT NULL AND NEW.plan_value IS NULL THEN
        NEW.plan_value := v_plan_price;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_telecom_customer_plan_value() OWNER TO postgres;

--
-- Name: sync_telecom_customer_seller_on_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_telecom_customer_seller_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead_assigned_user_id uuid;
BEGIN
  -- Se seller_id não foi definido, buscar do lead correspondente pelo nome
  IF NEW.seller_id IS NULL THEN
    SELECT assigned_user_id INTO v_lead_assigned_user_id
    FROM leads
    WHERE organization_id = NEW.organization_id
      AND name = NEW.name
      AND assigned_user_id IS NOT NULL
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_lead_assigned_user_id IS NOT NULL THEN
      NEW.seller_id := v_lead_assigned_user_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_telecom_customer_seller_on_insert() OWNER TO postgres;

--
-- Name: sync_user_roles(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_user_roles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, NEW.role)
    ON CONFLICT (user_id, role) DO NOTHING;
  ELSIF TG_OP = 'UPDATE' AND OLD.role IS DISTINCT FROM NEW.role THEN
    DELETE FROM public.user_roles WHERE user_id = NEW.id AND role = OLD.role;
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, NEW.role)
    ON CONFLICT (user_id, role) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_user_roles() OWNER TO postgres;

--
-- Name: sync_whatsapp_groups_compat_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_whatsapp_groups_compat_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.remote_jid := coalesce(nullif(new.remote_jid, ''), nullif(new.group_jid, ''));
  new.group_jid := coalesce(nullif(new.group_jid, ''), nullif(new.remote_jid, ''));
  new.name := coalesce(nullif(new.name, ''), nullif(new.subject, ''), 'Grupo WhatsApp');
  new.subject := coalesce(nullif(new.subject, ''), nullif(new.name, ''), 'Grupo WhatsApp');
  new.metadata := coalesce(new.metadata, '{}'::jsonb);
  return new;
end;
$$;


ALTER FUNCTION public.sync_whatsapp_groups_compat_columns() OWNER TO postgres;

