--
-- Name: touch_whatsapp_conversation_received_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.touch_whatsapp_conversation_received_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.whatsapp_conversations
  SET last_message_received_at = GREATEST(
        COALESCE(last_message_received_at, '-infinity'::timestamp with time zone),
        NEW.received_at
      )
  WHERE id = NEW.conversation_id
    AND (
      last_message_received_at IS NULL
      OR last_message_received_at < NEW.received_at
    );

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.touch_whatsapp_conversation_received_at() OWNER TO postgres;

--
-- Name: transfer_lead_assignee(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_lead_assignee(p_lead_id uuid, p_assigned_user_id uuid) RETURNS public.leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_org_id uuid;
  v_target_org_id uuid;
  v_lead public.leads%rowtype;
  v_updated_lead public.leads%rowtype;
  v_is_privileged boolean := false;
  v_is_leader_allowed boolean := false;
begin
  if v_actor_id is null then
    raise exception 'Usuario nao autenticado';
  end if;

  select organization_id
    into v_actor_org_id
  from public.users
  where id = v_actor_id;

  if v_actor_org_id is null then
    raise exception 'Organizacao do usuario nao encontrada';
  end if;

  select *
    into v_lead
  from public.leads
  where id = p_lead_id;

  if not found then
    raise exception 'Lead nao encontrado';
  end if;

  if v_lead.organization_id <> v_actor_org_id then
    raise exception 'Lead pertence a outra organizacao';
  end if;

  if p_assigned_user_id is not null then
    select organization_id
      into v_target_org_id
    from public.users
    where id = p_assigned_user_id
      and coalesce(is_active, true) = true;

    if v_target_org_id is null then
      raise exception 'Responsavel nao encontrado ou inativo';
    end if;

    if v_target_org_id <> v_lead.organization_id then
      raise exception 'Responsavel pertence a outra organizacao';
    end if;
  end if;

  v_is_privileged :=
    public.is_super_admin()
    or public.is_admin()
    or public.user_has_permission('lead_transfer', v_actor_id)
    or public.user_has_permission('lead_edit_all', v_actor_id)
    or public.user_has_permission('settings_teams', v_actor_id)
    or public.user_has_permission('settings_users', v_actor_id);

  if public.is_team_leader(v_actor_id) then
    v_is_leader_allowed :=
      (
        v_lead.pipeline_id in (select public.get_user_led_pipeline_ids())
        or v_lead.assigned_user_id in (
          select tm.user_id
          from public.team_members tm
          where tm.team_id in (select public.get_user_led_team_ids())
        )
      )
      and (
        p_assigned_user_id is null
        or p_assigned_user_id in (
          select tm.user_id
          from public.team_members tm
          where tm.team_id in (select public.get_user_led_team_ids())
        )
      );
  end if;

  if not (v_is_privileged or v_is_leader_allowed) then
    raise exception 'Sem permissao para transferir este lead';
  end if;

  update public.leads
     set assigned_user_id = p_assigned_user_id,
         assigned_at = case when p_assigned_user_id is null then null else now() end,
         updated_at = now()
   where id = p_lead_id
   returning * into v_updated_lead;

  return v_updated_lead;
end;
$$;


ALTER FUNCTION public.transfer_lead_assignee(p_lead_id uuid, p_assigned_user_id uuid) OWNER TO postgres;

--
-- Name: trigger_handle_lead_intake(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trigger_handle_lead_intake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.assigned_user_id is null
     and (
       lower(btrim(coalesce(new.metadata->>'managed_whatsapp_message_distribution', 'false')))
         in ('true', '1', 'yes')
       or lower(btrim(coalesce(new.metadata->>'distribution_deferred', 'false')))
         not in ('true', '1', 'yes')
     ) then
    perform public.handle_routed_lead_intake(new.id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.trigger_handle_lead_intake() OWNER TO postgres;

--
-- Name: try_acquire_execution_step_lock(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.try_acquire_execution_step_lock(p_execution_id uuid, p_max_lock_age_seconds integer DEFAULT 300) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_token TEXT;
    v_now TIMESTAMPTZ := now();
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.automation_executions
        WHERE id = p_execution_id AND status IN ('completed', 'failed', 'cancelled')
    ) THEN
        RETURN NULL;
    END IF;

    v_token := gen_random_uuid()::text;

    UPDATE public.automation_executions
    SET
        lock_token = v_token,
        locked_at = v_now,
        status = 'running'
    WHERE id = p_execution_id
      AND (
        lock_token IS NULL
        OR locked_at < v_now - (p_max_lock_age_seconds || ' seconds')::interval
      )
      AND status NOT IN ('completed', 'failed', 'cancelled');

    IF FOUND THEN
        RETURN v_token;
    ELSE
        RETURN NULL;
    END IF;
END;
$$;


ALTER FUNCTION public.try_acquire_execution_step_lock(p_execution_id uuid, p_max_lock_age_seconds integer) OWNER TO postgres;

