    last_succeeded_at timestamp with time zone,
    last_error text,
    last_provider_status text,
    last_payment_status text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT asaas_reconciliation_jobs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT asaas_reconciliation_jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 30))),
    CONSTRAINT asaas_reconciliation_jobs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'retry'::text, 'dead'::text])))
);


ALTER TABLE private.asaas_reconciliation_jobs OWNER TO postgres;

