--
-- Name: asaas_webhook_events; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.asaas_webhook_events (
    event_id text NOT NULL,
    event_type text NOT NULL,
    resource_type text NOT NULL,
    resource_id text NOT NULL,
    organization_id uuid,
    provider_event_at timestamp with time zone NOT NULL,
    outcome text NOT NULL,
    payload jsonb NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT asaas_webhook_events_event_id_check CHECK (((char_length(btrim(event_id)) >= 1) AND (char_length(btrim(event_id)) <= 512))),
    CONSTRAINT asaas_webhook_events_event_type_check CHECK ((("left"(event_type, 8) = 'PAYMENT_'::text) OR ("left"(event_type, 13) = 'SUBSCRIPTION_'::text) OR ("left"(event_type, 9) = 'CHECKOUT_'::text))),
    CONSTRAINT asaas_webhook_events_outcome_check CHECK ((outcome = ANY (ARRAY['processed'::text, 'stale'::text, 'unmatched'::text]))),
    CONSTRAINT asaas_webhook_events_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT asaas_webhook_events_resource_id_check CHECK (((char_length(btrim(resource_id)) >= 1) AND (char_length(btrim(resource_id)) <= 255))),
    CONSTRAINT asaas_webhook_events_resource_type_check CHECK ((resource_type = ANY (ARRAY['payment'::text, 'subscription'::text, 'checkout'::text])))
);


ALTER TABLE private.asaas_webhook_events OWNER TO postgres;

