--
-- Name: billing_card_recurrence_provisions; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.billing_card_recurrence_provisions (
    payment_id uuid NOT NULL,
    provider_payment_id text NOT NULL,
    organization_id uuid NOT NULL,
    billing_intent_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    billing_period_months integer NOT NULL,
    amount numeric(10,2) NOT NULL,
    provider_customer_id text NOT NULL,
    next_due_date date NOT NULL,
    external_reference text NOT NULL,
    status text DEFAULT 'prepared'::text NOT NULL,
    provider_subscription_id text,
    provider_subscription_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    provider_card_credential text,
    card_last4 text,
    credential_attempt_lease_id uuid,
    capture_request_started_at timestamp with time zone,
    capture_attempt_lease_id uuid,
    capture_manual_review_at timestamp with time zone,
    lease_id uuid,
    lease_expires_at timestamp with time zone,
    attempt_window_started_at timestamp with time zone,
    attempt_window_count integer DEFAULT 0 NOT NULL,
    provider_request_started_at timestamp with time zone,
    recovering_at timestamp with time zone,
    completed_at timestamp with time zone,
    provider_cancelled_at timestamp with time zone,
    failed_at timestamp with time zone,
    last_error text,
    job_action text DEFAULT 'create'::text NOT NULL,
    job_status text DEFAULT 'waiting'::text NOT NULL,
    job_attempts integer DEFAULT 0 NOT NULL,
    job_max_attempts integer DEFAULT 8 NOT NULL,
    job_next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    job_locked_at timestamp with time zone,
    job_lock_expires_at timestamp with time zone,
    job_locked_by text,
    job_lease_id uuid,
    job_last_attempt_at timestamp with time zone,
    job_dead_lettered_at timestamp with time zone,
    job_last_error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_card_recurrence_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT billing_card_recurrence_attempt_window_check CHECK ((((attempt_window_count >= 0) AND (attempt_window_count <= 5)) AND ((attempt_window_started_at IS NOT NULL) OR (attempt_window_count = 0)))),
    CONSTRAINT billing_card_recurrence_capture_marker_check CHECK ((((capture_request_started_at IS NULL) AND (capture_attempt_lease_id IS NULL)) OR ((capture_request_started_at IS NOT NULL) AND (capture_attempt_lease_id IS NOT NULL) AND (capture_request_started_at >= created_at)))),
    CONSTRAINT billing_card_recurrence_capture_review_check CHECK (((capture_manual_review_at IS NULL) OR ((capture_request_started_at IS NOT NULL) AND (capture_manual_review_at >= capture_request_started_at)))),
    CONSTRAINT billing_card_recurrence_completion_check CHECK ((((status = 'completed'::text) AND (provider_subscription_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (lease_id IS NULL) AND (lease_expires_at IS NULL)) OR ((status = 'cancelled'::text) AND (provider_subscription_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (provider_cancelled_at IS NOT NULL) AND (lease_id IS NULL) AND (lease_expires_at IS NULL)) OR (status <> ALL (ARRAY['completed'::text, 'cancelled'::text])))),
    CONSTRAINT billing_card_recurrence_external_reference_check CHECK ((external_reference = ('vimob:billing-card-recurrence:'::text || (payment_id)::text))),
    CONSTRAINT billing_card_recurrence_job_action_check CHECK ((job_action = ANY (ARRAY['create'::text, 'cancel'::text]))),
    CONSTRAINT billing_card_recurrence_job_attempts_check CHECK (((job_attempts >= 0) AND ((job_max_attempts >= 1) AND (job_max_attempts <= 30)))),
    CONSTRAINT billing_card_recurrence_job_error_code_check CHECK (((job_last_error_code IS NULL) OR (job_last_error_code ~ '^[a-z0-9_]{1,80}$'::text))),
    CONSTRAINT billing_card_recurrence_job_lock_check CHECK ((((job_status = 'processing'::text) AND (job_locked_at IS NOT NULL) AND (job_lock_expires_at IS NOT NULL) AND (job_locked_by IS NOT NULL) AND (job_lease_id IS NOT NULL)) OR ((job_status <> 'processing'::text) AND (job_locked_at IS NULL) AND (job_lock_expires_at IS NULL) AND (job_locked_by IS NULL) AND (job_lease_id IS NULL)))),
    CONSTRAINT billing_card_recurrence_job_status_check CHECK ((job_status = ANY (ARRAY['waiting'::text, 'pending'::text, 'processing'::text, 'retry'::text, 'succeeded'::text, 'cancelled'::text, 'dead'::text]))),
    CONSTRAINT billing_card_recurrence_lease_check CHECK ((((lease_id IS NULL) AND (lease_expires_at IS NULL)) OR ((lease_id IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT billing_card_recurrence_period_check CHECK ((billing_period_months = ANY (ARRAY[1, 6, 12]))),
    CONSTRAINT billing_card_recurrence_provider_cancelled_check CHECK (((provider_cancelled_at IS NULL) OR (status = 'cancelled'::text))),
    CONSTRAINT billing_card_recurrence_provider_request_timestamp_check CHECK (((provider_request_started_at IS NULL) OR (provider_request_started_at >= created_at))),
    CONSTRAINT billing_card_recurrence_provider_snapshot_check CHECK ((jsonb_typeof(provider_subscription_snapshot) = 'object'::text)),
    CONSTRAINT billing_card_recurrence_sealed_credential_check CHECK ((((provider_card_credential IS NULL) AND (card_last4 IS NULL)) OR ((provider_card_credential ~ '^v1[.][A-Za-z0-9._-]+$'::text) AND (char_length(provider_card_credential) >= 35) AND (char_length(provider_card_credential) <= 4096) AND (card_last4 ~ '^[0-9]{4}$'::text)))),
    CONSTRAINT billing_card_recurrence_status_check CHECK ((status = ANY (ARRAY['prepared'::text, 'creating'::text, 'recovering'::text, 'completed'::text, 'cancelled'::text, 'failed'::text]))),
    CONSTRAINT billing_card_recurrence_timestamps_check CHECK ((updated_at >= created_at))
);


ALTER TABLE private.billing_card_recurrence_provisions OWNER TO postgres;

--
-- Name: TABLE billing_card_recurrence_provisions; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON TABLE private.billing_card_recurrence_provisions IS 'Service-only durable state machine for creating one future card recurrence from one paid, one-off payment.';


--
-- Name: COLUMN billing_card_recurrence_provisions.external_reference; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.billing_card_recurrence_provisions.external_reference IS 'Deterministic provider correlation key: vimob:billing-card-recurrence:<canonical payment UUID>.';


--
-- Name: COLUMN billing_card_recurrence_provisions.provider_card_credential; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.billing_card_recurrence_provisions.provider_card_credential IS 'Short-lived Edge AES-GCM envelope (AAD = payment UUID) containing only provider token plus required remoteIp; never plaintext card data or raw IP.';


--
