    CONSTRAINT billing_organization_access_causes_source_check CHECK (((btrim(source) = source) AND ((char_length(source) >= 1) AND (char_length(source) <= 80)) AND (source ~ '^[a-z0-9][a-z0-9_:-]*$'::text))),
