--
-- Name: billing_organization_asaas_cleanup_claims; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.billing_organization_asaas_cleanup_claims (
    organization_id uuid NOT NULL,
    provider_customer_id text,
    provider_subscription_id text,
    provider_payment_ids text[] DEFAULT '{}'::text[] NOT NULL,
    claim_token uuid NOT NULL,
    lease_owner text NOT NULL,
    claimed_at timestamp with time zone NOT NULL,
    lease_expires_at timestamp with time zone NOT NULL,
    claim_attempts integer DEFAULT 1 NOT NULL,
    max_attempts integer DEFAULT 20 NOT NULL,
    provider_cleanup_started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    last_error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_organization_cleanup_attempts_check CHECK ((((claim_attempts >= 1) AND (claim_attempts <= 30)) AND ((max_attempts >= 1) AND (max_attempts <= 30)))),
    CONSTRAINT billing_organization_cleanup_customer_check CHECK (((provider_customer_id IS NULL) OR ((provider_customer_id = btrim(provider_customer_id)) AND ((char_length(provider_customer_id) >= 1) AND (char_length(provider_customer_id) <= 255))))),
    CONSTRAINT billing_organization_cleanup_error_check CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z0-9_]{1,80}$'::text))),
    CONSTRAINT billing_organization_cleanup_lease_check CHECK (((lease_owner = btrim(lease_owner)) AND ((char_length(lease_owner) >= 1) AND (char_length(lease_owner) <= 100)) AND (lease_expires_at > claimed_at))),
    CONSTRAINT billing_organization_cleanup_payments_check CHECK (((array_position(provider_payment_ids, NULL::text) IS NULL) AND (cardinality(provider_payment_ids) <= 10000))),
    CONSTRAINT billing_organization_cleanup_subscription_check CHECK (((provider_subscription_id IS NULL) OR ((provider_subscription_id = btrim(provider_subscription_id)) AND ((char_length(provider_subscription_id) >= 1) AND (char_length(provider_subscription_id) <= 255))))),
    CONSTRAINT billing_organization_cleanup_timeline_check CHECK (((provider_cleanup_started_at >= created_at) AND ((completed_at IS NULL) OR (completed_at >= provider_cleanup_started_at))))
);


ALTER TABLE private.billing_organization_asaas_cleanup_claims OWNER TO postgres;

--
-- Name: billing_organization_asaas_cleanup_resources; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.billing_organization_asaas_cleanup_resources (
    organization_id uuid NOT NULL,
    claim_token uuid NOT NULL,
    resource_kind text NOT NULL,
    resource_id text NOT NULL,
    delete_order smallint NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt_token uuid,
    lease_owner text,
    lease_started_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    provider_delete_started_at timestamp with time zone,
    provider_deleted_at timestamp with time zone,
    provider_http_status integer,
    provider_response jsonb DEFAULT '{}'::jsonb NOT NULL,
    manual_review_at timestamp with time zone,
    last_error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_organization_cleanup_resource_attempt_check CHECK ((((status = 'pending'::text) AND (attempt_token IS NULL) AND (lease_owner IS NULL) AND (lease_started_at IS NULL) AND (lease_expires_at IS NULL) AND (provider_delete_started_at IS NULL)) OR ((status = 'processing'::text) AND (attempt_token IS NOT NULL) AND (lease_owner IS NOT NULL) AND (lease_started_at IS NOT NULL) AND (lease_expires_at > lease_started_at) AND (provider_delete_started_at = lease_started_at)) OR ((status = ANY (ARRAY['succeeded'::text, 'manual_review'::text])) AND (attempt_token IS NOT NULL) AND (lease_owner IS NOT NULL) AND (lease_started_at IS NOT NULL) AND (lease_expires_at > lease_started_at) AND (provider_delete_started_at = lease_started_at)))),
    CONSTRAINT billing_organization_cleanup_resource_error_check CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z0-9_]{1,80}$'::text))),
    CONSTRAINT billing_organization_cleanup_resource_id_check CHECK (((resource_id = btrim(resource_id)) AND ((char_length(resource_id) >= 1) AND (char_length(resource_id) <= 255)))),
    CONSTRAINT billing_organization_cleanup_resource_kind_check CHECK ((resource_kind = ANY (ARRAY['payment'::text, 'subscription'::text, 'customer'::text]))),
    CONSTRAINT billing_organization_cleanup_resource_order_check CHECK ((((resource_kind = 'payment'::text) AND (delete_order = 10)) OR ((resource_kind = 'subscription'::text) AND (delete_order = 20)) OR ((resource_kind = 'customer'::text) AND (delete_order = 30)))),
    CONSTRAINT billing_organization_cleanup_resource_review_check CHECK ((((status = 'manual_review'::text) AND (manual_review_at IS NOT NULL)) OR ((status <> 'manual_review'::text) AND (manual_review_at IS NULL)))),
    CONSTRAINT billing_organization_cleanup_resource_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'succeeded'::text, 'manual_review'::text]))),
    CONSTRAINT billing_organization_cleanup_resource_success_check CHECK ((((status = 'succeeded'::text) AND (provider_deleted_at IS NOT NULL) AND (provider_http_status = 200) AND (jsonb_typeof((provider_response -> 'id'::text)) = 'string'::text) AND ((provider_response ->> 'id'::text) = resource_id) AND (jsonb_typeof((provider_response -> 'deleted'::text)) = 'boolean'::text) AND ((provider_response -> 'deleted'::text) = 'true'::jsonb) AND (manual_review_at IS NULL)) OR (status <> 'succeeded'::text))),
    CONSTRAINT billing_organization_cleanup_resource_timeline_check CHECK (((updated_at >= created_at) AND ((provider_delete_started_at IS NULL) OR (provider_delete_started_at >= created_at)) AND ((provider_deleted_at IS NULL) OR (provider_deleted_at >= provider_delete_started_at)) AND ((manual_review_at IS NULL) OR (manual_review_at >= provider_delete_started_at))))
);


ALTER TABLE private.billing_organization_asaas_cleanup_resources OWNER TO postgres;

