    CONSTRAINT billing_org_card_attempt_counts_check CHECK (((short_window_count >= 1) AND (daily_window_count >= 1))),
    CONSTRAINT billing_org_card_attempt_timestamps_check CHECK (((short_window_started_at <= last_attempt_at) AND (daily_window_started_at <= last_attempt_at) AND (expires_at > last_attempt_at)))
);


ALTER TABLE private.billing_organization_checkout_card_attempt_limits OWNER TO postgres;

