-- Name: billing_payment_checkout_cancellations; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.billing_payment_checkout_cancellations (
    intent_id uuid NOT NULL,
    payment_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    provider_payment_id text NOT NULL,
    provider_customer_id text NOT NULL,
    external_reference text NOT NULL,
    amount numeric(10,2) NOT NULL,
    billing_type text NOT NULL,
    due_date date NOT NULL,
    claim_token uuid NOT NULL,
    lease_owner text NOT NULL,
    claimed_at timestamp with time zone NOT NULL,
    lease_expires_at timestamp with time zone NOT NULL,
    claim_attempts integer DEFAULT 1 NOT NULL,
    max_attempts integer DEFAULT 8 NOT NULL,
    last_error_code text,
    provider_delete_started_at timestamp with time zone,
    provider_delete_claim_token uuid,
    provider_deleted_at timestamp with time zone,
    provider_delete_result text,
    finalized_at timestamp with time zone,
    final_outcome text,
    paid_won_at timestamp with time zone,
    manual_review_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_payment_checkout_cancellations_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT billing_payment_checkout_cancellations_attempts_check CHECK ((((claim_attempts >= 1) AND (claim_attempts <= 30)) AND ((max_attempts >= 1) AND (max_attempts <= 30)))),
    CONSTRAINT billing_payment_checkout_cancellations_billing_type_check CHECK ((billing_type = ANY (ARRAY['PIX'::text, 'BOLETO'::text]))),
    CONSTRAINT billing_payment_checkout_cancellations_customer_id_check CHECK (((provider_customer_id = btrim(provider_customer_id)) AND ((char_length(provider_customer_id) >= 1) AND (char_length(provider_customer_id) <= 255)))),
    CONSTRAINT billing_payment_checkout_cancellations_delete_marker_check CHECK ((((provider_delete_started_at IS NULL) AND (provider_delete_claim_token IS NULL)) OR ((provider_delete_started_at IS NOT NULL) AND (provider_delete_claim_token = claim_token) AND (provider_delete_started_at >= created_at)))),
    CONSTRAINT billing_payment_checkout_cancellations_delete_result_check CHECK (((provider_delete_result IS NULL) OR (provider_delete_result = ANY (ARRAY['deleted'::text, 'not_found'::text])))),
    CONSTRAINT billing_payment_checkout_cancellations_delete_timeline_check CHECK (((provider_deleted_at IS NULL) OR (provider_delete_started_at IS NULL) OR (provider_deleted_at >= provider_delete_started_at))),
    CONSTRAINT billing_payment_checkout_cancellations_error_code_check CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z0-9_]{1,80}$'::text))),
    CONSTRAINT billing_payment_checkout_cancellations_final_state_check CHECK ((((finalized_at IS NULL) AND (provider_deleted_at IS NULL) AND (provider_delete_result IS NULL) AND (final_outcome IS NULL) AND (paid_won_at IS NULL) AND (manual_review_at IS NULL)) OR ((finalized_at IS NOT NULL) AND (final_outcome IS NOT NULL) AND (((final_outcome = 'paid_before_delete'::text) AND (provider_deleted_at IS NULL) AND (provider_delete_result IS NULL) AND (paid_won_at IS NOT NULL) AND (manual_review_at IS NULL)) OR ((final_outcome = 'manual_review'::text) AND (paid_won_at IS NULL) AND (manual_review_at IS NOT NULL) AND (((provider_deleted_at IS NULL) AND (provider_delete_result IS NULL)) OR ((provider_deleted_at IS NOT NULL) AND (provider_delete_result IS NOT NULL)))) OR ((provider_deleted_at IS NOT NULL) AND (provider_delete_result IS NOT NULL) AND (((final_outcome = 'cancelled'::text) AND (paid_won_at IS NULL)) OR ((final_outcome = 'paid_after_delete'::text) AND (paid_won_at IS NOT NULL))) AND (manual_review_at IS NULL)))))),
    CONSTRAINT billing_payment_checkout_cancellations_lease_check CHECK (((lease_owner = btrim(lease_owner)) AND ((char_length(lease_owner) >= 1) AND (char_length(lease_owner) <= 100)) AND (lease_expires_at > claimed_at))),
    CONSTRAINT billing_payment_checkout_cancellations_outcome_check CHECK (((final_outcome IS NULL) OR (final_outcome = ANY (ARRAY['cancelled'::text, 'paid_before_delete'::text, 'paid_after_delete'::text, 'manual_review'::text])))),
    CONSTRAINT billing_payment_checkout_cancellations_payment_id_check CHECK (((provider_payment_id = btrim(provider_payment_id)) AND ((char_length(provider_payment_id) >= 1) AND (char_length(provider_payment_id) <= 255)))),
    CONSTRAINT billing_payment_checkout_cancellations_reference_check CHECK (((external_reference = btrim(external_reference)) AND ((char_length(external_reference) >= 1) AND (char_length(external_reference) <= 255))))
);


