--
-- Name: billing_subscription_card_update_jobs; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.billing_subscription_card_update_jobs (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    provider_subscription_id text NOT NULL,
    provider_customer_id text NOT NULL,
    generation bigint NOT NULL,
    mode text NOT NULL,
    payment_id uuid,
    provider_payment_id text,
    status text DEFAULT 'prepared'::text NOT NULL,
    provider_card_credential text,
    card_last4 text,
    credential_attempt_lease_id uuid,
    credential_stored_at timestamp with time zone,
    capture_request_started_at timestamp with time zone,
    capture_attempt_lease_id uuid,
    capture_manual_review_at timestamp with time zone,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 8 NOT NULL,
    lease_id uuid,
    lease_owner text,
    lease_started_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    provider_request_started_at timestamp with time zone,
    provider_request_last_started_at timestamp with time zone,
    provider_request_lease_id uuid,
    provider_request_attempts integer DEFAULT 0 NOT NULL,
    provider_outcome_ambiguous_at timestamp with time zone,
    provider_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_error_code text,
    manual_review_at timestamp with time zone,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    dead_lettered_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_subscription_card_update_attempts_check CHECK ((((attempts >= 0) AND (attempts <= 30)) AND ((max_attempts >= 1) AND (max_attempts <= 30)) AND ((provider_request_attempts >= 0) AND (provider_request_attempts <= 30)))),
    CONSTRAINT billing_subscription_card_update_capture_marker_check CHECK ((((capture_request_started_at IS NULL) AND (capture_attempt_lease_id IS NULL)) OR ((capture_request_started_at IS NOT NULL) AND (capture_attempt_lease_id IS NOT NULL) AND (capture_request_started_at >= created_at)))),
    CONSTRAINT billing_subscription_card_update_capture_review_check CHECK (((capture_manual_review_at IS NULL) OR ((capture_request_started_at IS NOT NULL) AND (capture_manual_review_at >= capture_request_started_at)))),
    CONSTRAINT billing_subscription_card_update_credential_check CHECK (((provider_card_credential IS NULL) OR ((provider_card_credential ~ '^v1[.][A-Za-z0-9._-]+$'::text) AND ((char_length(provider_card_credential) >= 35) AND (char_length(provider_card_credential) <= 4096))))),
    CONSTRAINT billing_subscription_card_update_customer_id_check CHECK (((provider_customer_id = btrim(provider_customer_id)) AND ((char_length(provider_customer_id) >= 1) AND (char_length(provider_customer_id) <= 255)))),
    CONSTRAINT billing_subscription_card_update_error_check CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z0-9_]{1,80}$'::text))),
    CONSTRAINT billing_subscription_card_update_expiry_check CHECK ((expires_at > created_at)),
    CONSTRAINT billing_subscription_card_update_generation_check CHECK ((generation > 0)),
    CONSTRAINT billing_subscription_card_update_last4_check CHECK (((card_last4 IS NULL) OR (card_last4 ~ '^[0-9]{4}$'::text))),
    CONSTRAINT billing_subscription_card_update_lease_check CHECK ((((lease_id IS NULL) AND (lease_owner IS NULL) AND (lease_started_at IS NULL) AND (lease_expires_at IS NULL)) OR ((lease_id IS NOT NULL) AND (lease_owner = btrim(lease_owner)) AND ((char_length(lease_owner) >= 1) AND (char_length(lease_owner) <= 100)) AND (lease_started_at IS NOT NULL) AND (lease_expires_at > lease_started_at)))),
    CONSTRAINT billing_subscription_card_update_manual_review_check CHECK (((manual_review_at IS NULL) OR (status = 'dead'::text))),
    CONSTRAINT billing_subscription_card_update_mode_check CHECK ((mode = ANY (ARRAY['settled_payment'::text, 'saved_only'::text]))),
    CONSTRAINT billing_subscription_card_update_payment_mode_check CHECK ((((mode = 'saved_only'::text) AND (payment_id IS NULL) AND (provider_payment_id IS NULL) AND (credential_attempt_lease_id IS NULL)) OR ((mode = 'settled_payment'::text) AND (payment_id IS NOT NULL) AND (provider_payment_id = btrim(provider_payment_id)) AND ((char_length(provider_payment_id) >= 1) AND (char_length(provider_payment_id) <= 255))))),
    CONSTRAINT billing_subscription_card_update_provider_ambiguity_check CHECK (((provider_outcome_ambiguous_at IS NULL) OR ((provider_request_started_at IS NOT NULL) AND (provider_outcome_ambiguous_at >= provider_request_started_at)))),
    CONSTRAINT billing_subscription_card_update_provider_marker_check CHECK ((((provider_request_started_at IS NULL) AND (provider_request_last_started_at IS NULL) AND (provider_request_lease_id IS NULL) AND (provider_request_attempts = 0)) OR ((provider_request_started_at IS NOT NULL) AND (provider_request_last_started_at >= provider_request_started_at) AND (provider_request_lease_id IS NOT NULL) AND (provider_request_attempts > 0)))),
    CONSTRAINT billing_subscription_card_update_snapshot_check CHECK ((jsonb_typeof(provider_snapshot) = 'object'::text)),
    CONSTRAINT billing_subscription_card_update_state_check CHECK ((((status = 'prepared'::text) AND (provider_card_credential IS NULL) AND (card_last4 IS NULL) AND (credential_stored_at IS NULL) AND (lease_id IS NULL) AND (completed_at IS NULL) AND (cancelled_at IS NULL) AND (dead_lettered_at IS NULL)) OR ((status = ANY (ARRAY['awaiting_payment'::text, 'pending_update'::text, 'retry'::text])) AND (provider_card_credential IS NOT NULL) AND (card_last4 IS NOT NULL) AND (credential_stored_at IS NOT NULL) AND (lease_id IS NULL) AND (completed_at IS NULL) AND (cancelled_at IS NULL) AND (dead_lettered_at IS NULL)) OR ((status = 'processing'::text) AND (provider_card_credential IS NOT NULL) AND (card_last4 IS NOT NULL) AND (credential_stored_at IS NOT NULL) AND (lease_id IS NOT NULL) AND (completed_at IS NULL) AND (cancelled_at IS NULL) AND (dead_lettered_at IS NULL)) OR ((status = 'succeeded'::text) AND (provider_card_credential IS NULL) AND (card_last4 IS NOT NULL) AND (lease_id IS NULL) AND (completed_at IS NOT NULL) AND (cancelled_at IS NULL) AND (dead_lettered_at IS NULL)) OR ((status = 'cancelled'::text) AND (provider_card_credential IS NULL) AND (lease_id IS NULL) AND (completed_at IS NULL) AND (cancelled_at IS NOT NULL) AND (dead_lettered_at IS NULL)) OR ((status = 'dead'::text) AND (provider_card_credential IS NULL) AND (lease_id IS NULL) AND (completed_at IS NULL) AND (dead_lettered_at IS NOT NULL)))),
    CONSTRAINT billing_subscription_card_update_status_check CHECK ((status = ANY (ARRAY['prepared'::text, 'awaiting_payment'::text, 'pending_update'::text, 'processing'::text, 'retry'::text, 'succeeded'::text, 'cancelled'::text, 'dead'::text]))),
    CONSTRAINT billing_subscription_card_update_subscription_id_check CHECK (((provider_subscription_id = btrim(provider_subscription_id)) AND ((char_length(provider_subscription_id) >= 1) AND (char_length(provider_subscription_id) <= 255))))
);


