--
-- Name: public_signup_attempt_claims; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.public_signup_attempt_claims (
    attempt_id uuid NOT NULL,
    normalized_email text NOT NULL,
    status text DEFAULT 'retryable'::text NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    auth_user_id uuid,
    organization_id uuid,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recovery_email text,
    recovery_token_hash text,
    recovery_expires_at timestamp with time zone,
    recovery_started_at timestamp with time zone,
    CONSTRAINT public_signup_attempt_claims_email_check CHECK (((normalized_email = lower(btrim(normalized_email))) AND (btrim(normalized_email) <> ''::text))),
    CONSTRAINT public_signup_attempt_claims_recovery_email_check CHECK (((recovery_email IS NULL) OR ((recovery_email = lower(btrim(recovery_email))) AND (btrim(recovery_email) <> ''::text)))),
    CONSTRAINT public_signup_attempt_claims_recovery_token_hash_check CHECK (((recovery_token_hash IS NULL) OR (recovery_token_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT public_signup_attempt_claims_state_check CHECK ((((status = 'retryable'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL) AND (organization_id IS NULL) AND (completed_at IS NULL) AND (recovery_email IS NULL) AND (recovery_token_hash IS NULL) AND (recovery_expires_at IS NULL) AND (recovery_started_at IS NULL)) OR ((status = ANY (ARRAY['processing'::text, 'compensating'::text])) AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (organization_id IS NULL) AND (completed_at IS NULL) AND (recovery_email IS NULL) AND (recovery_token_hash IS NULL) AND (recovery_expires_at IS NULL) AND (recovery_started_at IS NULL)) OR ((status = 'completed'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL) AND (organization_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (recovery_email IS NULL) AND (recovery_token_hash IS NULL) AND (recovery_expires_at IS NULL) AND (recovery_started_at IS NULL)) OR ((status = 'recovering'::text) AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (auth_user_id IS NOT NULL) AND (organization_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (recovery_email IS NOT NULL) AND (recovery_token_hash IS NOT NULL) AND (recovery_expires_at IS NOT NULL) AND (recovery_started_at IS NOT NULL) AND (recovery_expires_at > recovery_started_at)))),
    CONSTRAINT public_signup_attempt_claims_status_check CHECK ((status = ANY (ARRAY['retryable'::text, 'processing'::text, 'compensating'::text, 'completed'::text, 'recovering'::text])))
);


ALTER TABLE private.public_signup_attempt_claims OWNER TO postgres;

