    CONSTRAINT home_publications_body_length_check CHECK (((char_length(btrim(body)) >= 2) AND (char_length(btrim(body)) <= 1000))),
    CONSTRAINT home_publications_card_size_check CHECK ((card_size = ANY (ARRAY['wide'::text, 'half'::text, 'compact'::text]))),
    CONSTRAINT home_publications_cta_href_internal_check CHECK ((cta_href = ANY (ARRAY['/dashboard'::text, '/crm/pipelines'::text, '/crm/contacts'::text, '/crm/conversas'::text, '/agenda'::text, '/automations'::text, '/automations?tab=automations'::text, '/automations?tab=templates'::text, '/automations?tab=history'::text, '/properties'::text, '/gamificacao'::text, '/notifications'::text, '/settings'::text, '/suporte'::text]))),
    CONSTRAINT home_publications_cta_label_length_check CHECK (((char_length(btrim(cta_label)) >= 2) AND (char_length(btrim(cta_label)) <= 40))),
    CONSTRAINT home_publications_display_order_check CHECK (((display_order >= 0) AND (display_order <= 10000))),
    CONSTRAINT home_publications_image_pair_check CHECK (((image_url IS NULL) = (image_storage_path IS NULL))),
    CONSTRAINT home_publications_schedule_check CHECK (((starts_at IS NULL) OR (ends_at IS NULL) OR (ends_at > starts_at))),
    CONSTRAINT home_publications_target_roles_check CHECK ((target_roles <@ ARRAY['admin'::text, 'user'::text])),
    CONSTRAINT home_publications_target_shape_check CHECK ((((target_type = 'all'::text) AND (cardinality(target_organization_ids) = 0) AND (cardinality(target_user_ids) = 0) AND (cardinality(target_roles) = 0)) OR ((target_type = 'organizations'::text) AND (cardinality(target_organization_ids) > 0) AND (cardinality(target_user_ids) = 0) AND (cardinality(target_roles) = 0)) OR ((target_type = 'users'::text) AND (cardinality(target_user_ids) > 0) AND (cardinality(target_organization_ids) = 0) AND (cardinality(target_roles) = 0)) OR ((target_type = 'roles'::text) AND (cardinality(target_roles) > 0) AND (cardinality(target_organization_ids) = 0) AND (cardinality(target_user_ids) = 0)))),
    CONSTRAINT home_publications_target_type_check CHECK ((target_type = ANY (ARRAY['all'::text, 'organizations'::text, 'users'::text, 'roles'::text]))),
