    sync_log jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    api_key_secret_ref uuid NOT NULL,
    status text DEFAULT 'connected'::text NOT NULL,
    last_error text,
    created_by uuid,
    CONSTRAINT imoview_integrations_api_key_write_only_check CHECK ((api_key IS NULL)),
    CONSTRAINT imoview_integrations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'connected'::text, 'syncing'::text, 'error'::text, 'disabled'::text]))),
    CONSTRAINT imoview_integrations_total_synced_check CHECK ((total_synced >= 0))
);


ALTER TABLE public.imoview_integrations OWNER TO postgres;

--
-- Name: COLUMN imoview_integrations.api_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.imoview_integrations.api_key IS 'Write-only compatibility input. A BEFORE trigger moves values to Vault and stores NULL.';


--
-- Name: COLUMN imoview_integrations.api_key_secret_ref; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.imoview_integrations.api_key_secret_ref IS 'Reference to the encrypted Imoview API key in Supabase Vault.';


--
-- Name: imoview_integrations_service; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.imoview_integrations_service WITH (security_invoker='true') AS
 SELECT i.id,
    i.organization_id,
    secrets.decrypted_secret AS api_key,
    i.is_active,
    i.status,
    i.last_sync_at,
    i.last_error,
    i.total_synced,
    i.sync_log,
    i.created_by,
    i.created_at,
    i.updated_at
   FROM (public.imoview_integrations i
     JOIN vault.decrypted_secrets secrets ON ((secrets.id = i.api_key_secret_ref)));


ALTER VIEW public.imoview_integrations_service OWNER TO postgres;

--
-- Name: VIEW imoview_integrations_service; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.imoview_integrations_service IS 'Service-role-only Imoview integration projection with the Vault secret decrypted at query time.';


