    CONSTRAINT marketing_performance_nonnegative_check CHECK (((spend >= (0)::numeric) AND (impressions >= 0) AND (reach >= 0) AND (clicks >= 0) AND (link_clicks >= 0) AND (leads_reported >= 0) AND (conversations_reported >= 0) AND (conversions_reported >= 0) AND (video_views >= 0) AND (video_three_second_views >= 0) AND (video_thruplays >= 0))),
    CONSTRAINT marketing_performance_provider_check CHECK ((provider = ANY (ARRAY['meta'::text, 'google'::text, 'tiktok'::text, 'linkedin'::text])))
