--
-- Name: meta_crm_event_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.meta_crm_event_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    funnel_event_id uuid NOT NULL,
    lead_id uuid NOT NULL,
    lead_entry_event_id uuid NOT NULL,
    integration_id uuid,
    dataset_id text NOT NULL,
    leadgen_id text NOT NULL,
    event_kind text NOT NULL,
    event_sequence smallint GENERATED ALWAYS AS (
CASE event_kind
    WHEN 'initial'::text THEN 1
    WHEN 'qualified'::text THEN 2
    WHEN 'converted'::text THEN 3
    ELSE NULL::integer
END) STORED,
    event_name text NOT NULL,
    event_id text NOT NULL,
    event_time timestamp with time zone NOT NULL,
    test_event_code text,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 20 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    last_error_code text,
    last_error_message text,
    provider_trace_id text,
    provider_events_received integer,
    sent_at timestamp with time zone,
    dead_lettered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT meta_crm_event_outbox_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT meta_crm_event_outbox_dataset_id_check CHECK ((dataset_id ~ '^[0-9]{5,30}$'::text)),
    CONSTRAINT meta_crm_event_outbox_event_kind_check CHECK ((event_kind = ANY (ARRAY['initial'::text, 'qualified'::text, 'converted'::text]))),
    CONSTRAINT meta_crm_event_outbox_event_name_check CHECK ((event_name = ANY (ARRAY['VimobInitialLead'::text, 'VimobQualifiedLead'::text, 'VimobConvertedLead'::text]))),
    CONSTRAINT meta_crm_event_outbox_leadgen_id_check CHECK ((leadgen_id ~ '^[0-9]{15,17}$'::text)),
    CONSTRAINT meta_crm_event_outbox_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT meta_crm_event_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'retry'::text, 'sent'::text, 'dead'::text]))),
    CONSTRAINT meta_crm_event_outbox_test_event_code_check CHECK (((test_event_code IS NULL) OR (((length(test_event_code) >= 1) AND (length(test_event_code) <= 255)) AND (test_event_code = btrim(test_event_code)) AND (test_event_code !~ '[[:cntrl:]]'::text))))
);

ALTER TABLE ONLY public.meta_crm_event_outbox FORCE ROW LEVEL SECURITY;


