    granted_scopes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    subscribed_fields jsonb DEFAULT '["leadgen"]'::jsonb NOT NULL,
    subscription_reconciled_at timestamp with time zone,
    crm_dataset_id text,
