    CONSTRAINT meta_integrations_access_token_vault_check CHECK (((COALESCE(is_connected, false) = false) OR (access_token_secret_ref IS NOT NULL))),
    CONSTRAINT meta_integrations_conversion_feedback_ready_check CHECK (((NOT conversion_feedback_enabled) OR ((crm_dataset_id IS NOT NULL) AND (crm_dataset_access_token_secret_ref IS NOT NULL)))),
    CONSTRAINT meta_integrations_conversion_feedback_status_check CHECK ((conversion_feedback_status = ANY (ARRAY['not_configured'::text, 'active'::text, 'paused'::text, 'error'::text]))),
    CONSTRAINT meta_integrations_crm_dataset_id_check CHECK (((crm_dataset_id IS NULL) OR (btrim(crm_dataset_id) ~ '^[0-9]{5,30}$'::text))),
    CONSTRAINT meta_integrations_subscribed_fields_check CHECK (((jsonb_typeof(subscribed_fields) = 'array'::text) AND (subscribed_fields <@ '["leadgen", "messages", "messaging_postbacks"]'::jsonb) AND (subscribed_fields @> '["leadgen"]'::jsonb)))
);


