    about_image_url text,
    seo_title text,
    seo_description text,
    seo_keywords text,
    google_analytics_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    hero_image_url text,
    hero_title text,
    hero_subtitle text,
    page_banner_url text,
    logo_width integer DEFAULT 160,
    logo_height integer DEFAULT 50,
    watermark_enabled boolean DEFAULT false,
    watermark_opacity integer DEFAULT 20,
    watermark_logo_url text,
    site_theme text DEFAULT 'dark'::text NOT NULL,
    background_color text DEFAULT '#0D0D0D'::text NOT NULL,
    text_color text DEFAULT '#FFFFFF'::text NOT NULL,
    card_color text DEFAULT '#FFFFFF'::text NOT NULL,
