    about_subtitle text,
    about_stats jsonb DEFAULT '[{"label": "Imóveis Vendidos", "value": "500+"}, {"label": "Clientes Satisfeitos", "value": "98%"}, {"label": "Anos de Experiência", "value": "15+"}, {"label": "Parceiros", "value": "50+"}]'::jsonb,
    about_checkmarks jsonb DEFAULT '["Atendimento personalizado", "Imóveis verificados", "Suporte completo"]'::jsonb,
    about_features jsonb DEFAULT '[{"icon": "building", "title": "Imóveis Selecionados", "description": "Curadoria dos melhores imóveis da região com critérios rigorosos de qualidade"}, {"icon": "users", "title": "Atendimento Personalizado", "description": "Equipe dedicada e treinada para encontrar o imóvel ideal para você"}, {"icon": "award", "title": "Experiência no Mercado", "description": "Anos de experiência e centenas de clientes satisfeitos no setor imobiliário"}, {"icon": "heart", "title": "Compromisso", "description": "Seu sonho é a nossa prioridade e trabalhamos para realizá-lo"}]'::jsonb,
