    CONSTRAINT organization_sites_google_search_console_verification_check CHECK (((google_search_console_verification IS NULL) OR (google_search_console_verification ~ '^[A-Za-z0-9_-]{10,255}$'::text))),
    CONSTRAINT organization_sites_maintenance_message_length CHECK (((maintenance_message IS NULL) OR (char_length(maintenance_message) <= 500))),
    CONSTRAINT organization_sites_subdomain_format CHECK (((subdomain IS NULL) OR (((char_length(subdomain) >= 3) AND (char_length(subdomain) <= 63)) AND (subdomain = lower(subdomain)) AND (subdomain ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'::text)))),
    CONSTRAINT watermark_opacity_range CHECK (((watermark_opacity >= 5) AND (watermark_opacity <= 50)))
);


