--
-- Name: property_assets; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.property_assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    property_id uuid NOT NULL,
    asset_type text NOT NULL,
    visibility text DEFAULT 'internal'::text NOT NULL,
    storage_path text,
    external_url text,
    title text,
    description text,
    file_name text,
    mime_type text,
    file_size_bytes bigint,
    checksum_sha256 text,
    sort_order integer DEFAULT 0 NOT NULL,
    is_primary boolean DEFAULT false NOT NULL,
    document_category text,
    expires_at date,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT property_assets_checksum_check CHECK (((checksum_sha256 IS NULL) OR (checksum_sha256 ~ '^[0-9a-fA-F]{64}$'::text))),
    CONSTRAINT property_assets_document_category_check CHECK (((asset_type = 'document'::text) OR (document_category IS NULL))),
    CONSTRAINT property_assets_expiration_check CHECK (((asset_type = 'document'::text) OR (expires_at IS NULL))),
    CONSTRAINT property_assets_integration_archive_shape_check CHECK (((NOT (metadata ? 'integration_provider'::text)) AND
CASE
    WHEN (NOT (metadata ? 'integration_managed'::text)) THEN true
    ELSE (jsonb_typeof((metadata -> 'integration_managed'::text)) = 'boolean'::text)
END AND
CASE
    WHEN (NOT (metadata ? 'integration_providers'::text)) THEN true
    WHEN (jsonb_typeof((metadata -> 'integration_providers'::text)) <> 'array'::text) THEN false
    ELSE (((metadata -> 'integration_providers'::text) <@ '["imoview", "vista"]'::jsonb) AND (jsonb_array_length((metadata -> 'integration_providers'::text)) = (
    CASE
        WHEN ((metadata -> 'integration_providers'::text) ? 'imoview'::text) THEN 1
        ELSE 0
    END +
    CASE
        WHEN ((metadata -> 'integration_providers'::text) ? 'vista'::text) THEN 1
        ELSE 0
    END)) AND ((jsonb_array_length((metadata -> 'integration_providers'::text)) = 0) OR ((COALESCE((metadata ->> 'integration_managed'::text), 'false'::text) = 'true'::text) AND (asset_type = 'photo'::text) AND (external_url IS NOT NULL))))
END AND
CASE
    WHEN (NOT (metadata ? 'integration_retired'::text)) THEN true
    WHEN (jsonb_typeof((metadata -> 'integration_retired'::text)) <> 'boolean'::text) THEN false
    WHEN ((metadata -> 'integration_retired'::text) = 'false'::jsonb) THEN true
    ELSE ((COALESCE((metadata ->> 'integration_managed'::text), 'false'::text) = 'true'::text) AND (NOT is_primary) AND (asset_type = 'photo'::text) AND (external_url IS NOT NULL) AND
    CASE
        WHEN (NOT (metadata ? 'integration_providers'::text)) THEN false
        WHEN (jsonb_typeof((metadata -> 'integration_providers'::text)) = 'array'::text) THEN (jsonb_array_length((metadata -> 'integration_providers'::text)) = 0)
        ELSE false
    END)
END)),
    CONSTRAINT property_assets_locator_check CHECK ((num_nonnulls(NULLIF(btrim(storage_path), ''::text), NULLIF(btrim(external_url), ''::text)) = 1)),
    CONSTRAINT property_assets_metadata_object_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT property_assets_primary_active_check CHECK (((NOT is_primary) OR (COALESCE((metadata ->> 'integration_retired'::text), 'false'::text) <> 'true'::text))),
    CONSTRAINT property_assets_primary_photo_check CHECK (((NOT is_primary) OR (asset_type = 'photo'::text))),
    CONSTRAINT property_assets_primary_public_check CHECK (((NOT is_primary) OR ((asset_type = 'photo'::text) AND (visibility = 'public'::text)))),
    CONSTRAINT property_assets_size_check CHECK (((file_size_bytes IS NULL) OR (file_size_bytes >= 0))),
    CONSTRAINT property_assets_sort_order_check CHECK ((sort_order >= 0)),
    CONSTRAINT property_assets_type_check CHECK ((asset_type = ANY (ARRAY['photo'::text, 'video'::text, 'virtual_tour'::text, 'floor_plan'::text, 'document'::text]))),
    CONSTRAINT property_assets_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'internal'::text, 'confidential'::text])))
);


ALTER TABLE public.property_assets OWNER TO postgres;

