-- Name: property_channel_publications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.property_channel_publications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    property_id uuid NOT NULL,
    channel text NOT NULL,
    channel_account_key text DEFAULT 'default'::text NOT NULL,
    desired_state text DEFAULT 'unpublished'::text NOT NULL,
    observed_state text DEFAULT 'draft'::text NOT NULL,
