    published_at timestamp with time zone,
    unpublished_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT property_channel_publications_account_check CHECK (((channel_account_key = btrim(channel_account_key)) AND ((char_length(channel_account_key) >= 1) AND (char_length(channel_account_key) <= 160)) AND (channel_account_key ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]*$'::text))),
    CONSTRAINT property_channel_publications_channel_check CHECK (((channel = lower(channel)) AND ((char_length(channel) >= 1) AND (char_length(channel) <= 64)) AND (channel ~ '^[a-z][a-z0-9_.-]*$'::text))),
    CONSTRAINT property_channel_publications_desired_check CHECK ((desired_state = ANY (ARRAY['published'::text, 'paused'::text, 'unpublished'::text]))),
    CONSTRAINT property_channel_publications_error_code_check CHECK (((last_error_code IS NULL) OR ((char_length(last_error_code) >= 1) AND (char_length(last_error_code) <= 160)))),
    CONSTRAINT property_channel_publications_error_message_check CHECK (((last_error_message IS NULL) OR ((char_length(last_error_message) >= 1) AND (char_length(last_error_message) <= 4000)))),
    CONSTRAINT property_channel_publications_observed_check CHECK ((observed_state = ANY (ARRAY['draft'::text, 'queued'::text, 'publishing'::text, 'published'::text, 'pausing'::text, 'paused'::text, 'unpublishing'::text, 'unpublished'::text, 'error'::text]))),
    CONSTRAINT property_channel_publications_provider_id_check CHECK (((provider_listing_id IS NULL) OR ((char_length(btrim(provider_listing_id)) >= 1) AND (char_length(btrim(provider_listing_id)) <= 512)))),
    CONSTRAINT property_channel_publications_provider_revision_check CHECK (((provider_revision IS NULL) OR ((char_length(btrim(provider_revision)) >= 1) AND (char_length(btrim(provider_revision)) <= 512)))),
    CONSTRAINT property_channel_publications_public_url_check CHECK (((public_url IS NULL) OR (((char_length(public_url) >= 8) AND (char_length(public_url) <= 2048)) AND (public_url ~* '^https?://'::text)))),
    CONSTRAINT property_channel_publications_published_state_check CHECK (((observed_state <> 'published'::text) OR (published_version IS NOT NULL))),
    CONSTRAINT property_channel_publications_readiness_check CHECK ((readiness_state = ANY (ARRAY['unknown'::text, 'ready'::text, 'blocked'::text]))),
    CONSTRAINT property_channel_publications_validation_errors_check CHECK ((jsonb_typeof(validation_errors) = 'array'::text)),
    CONSTRAINT property_channel_publications_versions_check CHECK (((current_version >= 0) AND ((published_version IS NULL) OR ((published_version >= 1) AND (published_version <= current_version)))))
);

