    price numeric(16,2),
    currency text DEFAULT 'BRL'::text NOT NULL,
    price_period text,
    terms jsonb DEFAULT '{}'::jsonb NOT NULL,
    available_from date,
    available_until date,
    published_at timestamp with time zone,
    completed_at timestamp with time zone,
