    CONSTRAINT property_offers_active_commercial_check CHECK (((status <> 'active'::text) OR ((price IS NOT NULL) AND (price > (0)::numeric) AND (price_period IS NOT NULL)))),
    CONSTRAINT property_offers_availability_check CHECK (((available_until IS NULL) OR (available_from IS NULL) OR (available_until >= available_from))),
    CONSTRAINT property_offers_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT property_offers_metadata_object_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT property_offers_price_check CHECK (((price IS NULL) OR (price >= (0)::numeric))),
    CONSTRAINT property_offers_price_period_check CHECK (((price_period IS NULL) OR (price_period = ANY (ARRAY['total'::text, 'daily'::text, 'weekly'::text, 'monthly'::text, 'yearly'::text])))),
    CONSTRAINT property_offers_sale_period_check CHECK (((offer_type <> 'sale'::text) OR (price_period IS NULL) OR (price_period = 'total'::text))),
    CONSTRAINT property_offers_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'paused'::text, 'reserved'::text, 'completed'::text, 'withdrawn'::text, 'expired'::text]))),
    CONSTRAINT property_offers_terms_object_check CHECK ((jsonb_typeof(terms) = 'object'::text)),
    CONSTRAINT property_offers_type_check CHECK ((offer_type = ANY (ARRAY['sale'::text, 'rent'::text, 'seasonal'::text])))
);


