--
-- Name: schedule_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.schedule_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    lead_id uuid,
    property_id uuid,
    title text NOT NULL,
    description text,
    event_type text DEFAULT 'meeting'::text,
    start_time timestamp with time zone NOT NULL,
    end_time timestamp with time zone NOT NULL,
    location text,
    is_all_day boolean DEFAULT false,
    reminder_minutes integer DEFAULT 30,
    google_event_id text,
    status text DEFAULT 'scheduled'::text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    completed_by uuid,
    completed_at timestamp with time zone,
    recurrence_parent_id uuid,
    recurrence_rule text,
    recurrence_until timestamp with time zone,
    recurrence_count integer,
    visibility text DEFAULT 'default'::text NOT NULL,
    google_calendar_connection_id uuid,
    google_calendar_id text,
    google_sync_status text,
    google_last_synced_at timestamp with time zone,
    google_sync_error text,
    created_by uuid,
    team_id uuid,
    lead_source_snapshot text,
    outcome text,
    outcome_notes text,
    performed_by uuid,
    outcome_recorded_at timestamp with time zone,
    rescheduled_from_event_id uuid,
    rescheduled_to_event_id uuid,
    CONSTRAINT schedule_events_outcome_check CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['contacted'::text, 'activity_completed'::text, 'qualified'::text, 'proposal'::text, 'visit_completed'::text, 'meeting_completed'::text, 'follow_up'::text, 'no_show'::text, 'rescheduled'::text, 'cancelled'::text, 'other'::text])))),
    CONSTRAINT schedule_events_outcome_notes_length_check CHECK (((outcome_notes IS NULL) OR ((char_length(btrim(outcome_notes)) >= 1) AND (char_length(btrim(outcome_notes)) <= 2000)))),
    CONSTRAINT schedule_events_outcome_state_check CHECK (COALESCE((
CASE
    WHEN (status = 'scheduled'::text) THEN ((outcome IS NULL) AND (rescheduled_to_event_id IS NULL))
    WHEN ((status = 'completed'::text) AND (lower(btrim(event_type)) = 'visit'::text)) THEN (outcome = 'visit_completed'::text)
    WHEN ((status = 'completed'::text) AND (lower(btrim(event_type)) = 'meeting'::text)) THEN (outcome = 'meeting_completed'::text)
    WHEN ((status = 'completed'::text) AND (lower(btrim(event_type)) = ANY (ARRAY['call'::text, 'email'::text, 'message'::text]))) THEN ((outcome IS NULL) OR (outcome = ANY (ARRAY['contacted'::text, 'activity_completed'::text])))
    WHEN (status = 'completed'::text) THEN ((outcome IS NULL) OR (outcome = 'activity_completed'::text))
    WHEN (status = 'no_show'::text) THEN ((lower(btrim(event_type)) = ANY (ARRAY['visit'::text, 'meeting'::text])) AND (outcome = 'no_show'::text))
    WHEN ((status = ANY (ARRAY['cancelled'::text, 'canceled'::text])) AND (outcome = 'rescheduled'::text)) THEN ((lower(btrim(event_type)) = ANY (ARRAY['visit'::text, 'meeting'::text])) AND (rescheduled_to_event_id IS NOT NULL))
    WHEN (status = ANY (ARRAY['cancelled'::text, 'canceled'::text])) THEN ((outcome IS NULL) OR (outcome = 'cancelled'::text))
    ELSE false
END AND ((rescheduled_from_event_id IS NULL) OR ((lower(btrim(event_type)) = ANY (ARRAY['visit'::text, 'meeting'::text])) AND (rescheduled_from_event_id <> id))) AND ((rescheduled_to_event_id IS NULL) OR ((lower(btrim(event_type)) = ANY (ARRAY['visit'::text, 'meeting'::text])) AND (rescheduled_to_event_id <> id)))), false)),
    CONSTRAINT schedule_events_recurrence_rule_check CHECK (((recurrence_rule IS NULL) OR (recurrence_rule = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text, 'yearly'::text])))),
    CONSTRAINT schedule_events_reminder_minutes_supported_check CHECK (((reminder_minutes IS NULL) OR ((reminder_minutes >= 0) AND (reminder_minutes <= 120)))),
    CONSTRAINT schedule_events_status_check CHECK (((status IS NOT NULL) AND (status = ANY (ARRAY['scheduled'::text, 'completed'::text, 'cancelled'::text, 'canceled'::text, 'no_show'::text])))),
    CONSTRAINT schedule_events_visibility_check CHECK ((visibility = ANY (ARRAY['default'::text, 'public'::text, 'private'::text])))
);


ALTER TABLE public.schedule_events OWNER TO postgres;

--
-- Name: TABLE schedule_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.schedule_events IS 'Agenda events: browser access is blocked; reads and mutations use the tenant-scoped Go API or trusted service workers.';


