--

COMMENT ON COLUMN public.schedule_events.performed_by IS 'Auth user who performed the scheduled activity.';


--
-- Name: COLUMN schedule_events.outcome_recorded_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.schedule_events.outcome_recorded_at IS 'Timestamp when the outcome was recorded.';


--
-- Name: COLUMN schedule_events.rescheduled_from_event_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.schedule_events.rescheduled_from_event_id IS 'Previous finalized visit or meeting replaced by this event. Unique for retry-safe rescheduling.';


