--

CREATE TABLE public.stage_operational_configs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    stage_id uuid NOT NULL,
    operation_context text NOT NULL,
    responsible_sector text,
    sla_hours integer DEFAULT 24,
    automatic_tasks jsonb DEFAULT '[]'::jsonb,
    automatic_notifications jsonb DEFAULT '[]'::jsonb,
    automatic_operational_requests jsonb DEFAULT '[]'::jsonb,
    checklist_template jsonb DEFAULT '[]'::jsonb,
    approval_flow jsonb DEFAULT '{}'::jsonb,
    dashboard_destination text,
    visibility_rules jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    cadence_enabled boolean DEFAULT false NOT NULL,
    revision bigint DEFAULT 0 NOT NULL,
    attention_mode text DEFAULT 'disabled'::text NOT NULL,
    first_outreach_minutes integer,
    first_effective_contact_minutes integer,
    stage_inactivity_minutes integer,
    stage_max_age_minutes integer,
    warning_minutes integer DEFAULT 0 NOT NULL,
    escalation_minutes integer,
    business_hours_only boolean DEFAULT false NOT NULL,
    CONSTRAINT stage_operational_configs_attention_mode_check CHECK ((attention_mode = ANY (ARRAY['disabled'::text, 'shadow'::text, 'enabled'::text]))),
    CONSTRAINT stage_operational_configs_escalation_check CHECK (((escalation_minutes IS NULL) OR (escalation_minutes > 0))),
    CONSTRAINT stage_operational_configs_first_effective_contact_check CHECK (((first_effective_contact_minutes IS NULL) OR (first_effective_contact_minutes > 0))),
    CONSTRAINT stage_operational_configs_first_outreach_check CHECK (((first_outreach_minutes IS NULL) OR (first_outreach_minutes > 0))),
    CONSTRAINT stage_operational_configs_stage_inactivity_check CHECK (((stage_inactivity_minutes IS NULL) OR (stage_inactivity_minutes > 0))),
    CONSTRAINT stage_operational_configs_stage_max_age_check CHECK (((stage_max_age_minutes IS NULL) OR (stage_max_age_minutes > 0))),
    CONSTRAINT stage_operational_configs_warning_check CHECK ((warning_minutes >= 0)),
    CONSTRAINT stage_operational_configs_warning_coherence_check CHECK (((warning_minutes = 0) OR (((first_outreach_minutes IS NULL) OR (warning_minutes < first_outreach_minutes)) AND ((first_effective_contact_minutes IS NULL) OR (warning_minutes < first_effective_contact_minutes)) AND ((stage_inactivity_minutes IS NULL) OR (warning_minutes < stage_inactivity_minutes)) AND ((stage_max_age_minutes IS NULL) OR (warning_minutes < stage_max_age_minutes)))))
);


