--
-- Name: vista_integrations_service; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_integrations_service WITH (security_invoker='true') AS
 SELECT v.id,
    v.organization_id,
    v.api_url,
    secrets.decrypted_secret AS api_key,
    v.is_active,
    v.import_inactive,
    v.status,
    v.last_sync_at,
    v.last_error,
    v.total_synced,
    v.sync_log,
    v.created_by,
    v.created_at,
    v.updated_at
   FROM (public.vista_integrations v
     JOIN vault.decrypted_secrets secrets ON ((secrets.id = v.api_key_secret_ref)));


ALTER VIEW public.vista_integrations_service OWNER TO postgres;

--
-- Name: VIEW vista_integrations_service; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.vista_integrations_service IS 'Service-role-only Vista integration projection with the Vault secret decrypted at query time.';


