    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


ALTER TABLE public.webhooks OWNER TO postgres;

--
-- Name: webhooks_integrations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.webhooks_integrations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    type text DEFAULT 'incoming'::text NOT NULL,
    api_token text DEFAULT encode(extensions.gen_random_bytes(32), 'hex'::text) NOT NULL,
    webhook_url text,
    target_pipeline_id uuid,
    target_team_id uuid,
    target_stage_id uuid,
    target_tag_ids uuid[] DEFAULT '{}'::uuid[],
    target_property_id uuid,
    field_mapping jsonb DEFAULT '{}'::jsonb,
    is_active boolean DEFAULT true NOT NULL,
    leads_received integer DEFAULT 0 NOT NULL,
    last_lead_at timestamp with time zone,
    last_triggered_at timestamp with time zone,
    trigger_events text[] DEFAULT '{}'::text[],
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT webhooks_integrations_outgoing_contract_check CHECK (((type <> 'outgoing'::text) OR ((webhook_url IS NOT NULL) AND (webhook_url ~ '^https://[^[:space:]]+$'::text) AND (trigger_events IS NOT NULL) AND ((cardinality(trigger_events) >= 1) AND (cardinality(trigger_events) <= 2)) AND (trigger_events <@ ARRAY['lead.created'::text, 'lead.reentered'::text])))),
    CONSTRAINT webhooks_integrations_type_check CHECK ((type = ANY (ARRAY['incoming'::text, 'outgoing'::text])))
);


ALTER TABLE public.webhooks_integrations OWNER TO postgres;

--
-- Name: TABLE webhooks_integrations; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.webhooks_integrations IS 'Webhooks para integração de leads (entrada) e eventos (saída)';


--
-- Name: whatsapp_attendance_entries; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.whatsapp_attendance_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    session_id uuid NOT NULL,
    lead_id uuid NOT NULL,
    binding_id uuid NOT NULL,
    user_id uuid NOT NULL,
    actor_name_snapshot text NOT NULL,
    joined_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    ingress_sequence_cutoff bigint NOT NULL,
    entry_source text DEFAULT 'manual'::text NOT NULL,
    bootstrap_provider_message_id text,
    bootstrap_ingress_sequence bigint,
    bootstrap_provider_occurred_at timestamp with time zone,
    bootstrap_inbox_created_at timestamp with time zone,
    CONSTRAINT whatsapp_attendance_entries_actor_name_check CHECK ((btrim(actor_name_snapshot) <> ''::text)),
    CONSTRAINT whatsapp_attendance_entries_ingress_cutoff_check CHECK ((ingress_sequence_cutoff >= 0)),
    CONSTRAINT whatsapp_attendance_entries_source_check CHECK ((((entry_source = 'manual'::text) AND (bootstrap_provider_message_id IS NULL) AND (bootstrap_ingress_sequence IS NULL) AND (bootstrap_provider_occurred_at IS NULL) AND (bootstrap_inbox_created_at IS NULL)) OR ((entry_source = 'ctwa_auto'::text) AND (btrim(COALESCE(bootstrap_provider_message_id, ''::text)) <> ''::text) AND (bootstrap_ingress_sequence IS NOT NULL) AND (bootstrap_ingress_sequence > 0) AND (ingress_sequence_cutoff = bootstrap_ingress_sequence) AND (bootstrap_provider_occurred_at IS NOT NULL) AND (bootstrap_inbox_created_at IS NOT NULL) AND (bootstrap_provider_occurred_at <= bootstrap_inbox_created_at))))
);


ALTER TABLE public.whatsapp_attendance_entries OWNER TO postgres;

--
-- Name: TABLE whatsapp_attendance_entries; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.whatsapp_attendance_entries IS 'Append-only backend ledger proving either explicit user confirmation or verified automatic CTWA entry for one lead/card, WhatsApp session and then-active conversation binding.';


--
-- Name: COLUMN whatsapp_attendance_entries.organization_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.organization_id IS 'Tenant snapshot validated against the conversation and active binding when the entry is inserted.';


--
-- Name: COLUMN whatsapp_attendance_entries.conversation_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.conversation_id IS 'Physical WhatsApp conversation through which this user entered the attendance.';


--
-- Name: COLUMN whatsapp_attendance_entries.session_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.session_id IS 'Immutable WhatsApp session UUID snapshot. It intentionally remains an audit tombstone if the session is later deleted.';


--
-- Name: COLUMN whatsapp_attendance_entries.lead_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.lead_id IS 'Immutable lead/card UUID snapshot. It intentionally remains an audit tombstone if the lead is later deleted or transferred.';


--
-- Name: COLUMN whatsapp_attendance_entries.binding_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.binding_id IS 'Conversation-to-lead binding ledger row that was active when the user confirmed entry.';


--
-- Name: COLUMN whatsapp_attendance_entries.user_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.user_id IS 'Immutable user UUID snapshot for the actor who confirmed entry.';


--
-- Name: COLUMN whatsapp_attendance_entries.actor_name_snapshot; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.actor_name_snapshot IS 'Display-name snapshot used by the immutable system event even if the user is later renamed or removed.';


--
-- Name: COLUMN whatsapp_attendance_entries.joined_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.joined_at IS 'Database timestamp at which the trusted backend recorded explicit confirmation or verified automatic entry; auto capture uses the separate immutable first-event boundary.';


--
-- Name: COLUMN whatsapp_attendance_entries.ingress_sequence_cutoff; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.ingress_sequence_cutoff IS 'Manual entries use an exclusive provider-ingress fence. Automatic CTWA entries store the exact first ingress sequence here and in bootstrap_ingress_sequence.';


--
-- Name: COLUMN whatsapp_attendance_entries.entry_source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.entry_source IS 'manual means explicit user confirmation; ctwa_auto means database-verified entry by the owner of the receiving WhatsApp when a new CTWA card is created.';


--
-- Name: COLUMN whatsapp_attendance_entries.bootstrap_provider_message_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.bootstrap_provider_message_id IS 'Exact first CTWA provider message authorized for automatic capture; NULL for manual entry.';


--
-- Name: COLUMN whatsapp_attendance_entries.bootstrap_ingress_sequence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.whatsapp_attendance_entries.bootstrap_ingress_sequence IS 'First CTWA routing ingress sequence. Later messages require a greater sequence and must not predate the first provider/inbox timestamps.';


