--

COMMENT ON COLUMN public.whatsapp_conversation_lead_bindings.lead_id IS 'Immutable lead UUID tombstone. No FK by design: hard deletion must not erase provider-event replay/idempotency history.';


--
-- Name: COLUMN whatsapp_conversation_lead_bindings.previous_lead_id; Type: COMMENT; Schema: public; Owner: postgres
