    completed_inbox_event_key text NOT NULL,
    completed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT whatsapp_webhook_routing_outcome_event_key_check CHECK (((btrim(completed_inbox_event_key) <> ''::text) AND (octet_length(completed_inbox_event_key) <= 1024)))
);


