--
-- Name: whatsapp_outbox_fast_due_head_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX whatsapp_outbox_fast_due_head_idx ON public.whatsapp_outbox USING btree (conversation_id, created_at, id) INCLUDE (next_attempt_at) WHERE ((status = ANY (ARRAY['pending'::text, 'retry'::text])) AND ((attempts < max_attempts) OR (last_error = 'provider_accepted_finalization_pending'::text)) AND (NOT ((lower(COALESCE((payload ->> 'action'::text), ''::text)) = ANY (ARRAY['send.media'::text, 'send.audio'::text, 'send.sticker'::text])) OR (lower(COALESCE(message_type, ''::text)) = ANY (ARRAY['image'::text, 'audio'::text, 'video'::text, 'document'::text, 'sticker'::text])))));


--
-- Name: INDEX whatsapp_outbox_fast_due_head_idx; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON INDEX public.whatsapp_outbox_fast_due_head_idx IS 'Literal fast-lane FIFO heads, including provider-accepted local finalization.';


--
-- Name: whatsapp_outbox_media_due_head_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX whatsapp_outbox_media_due_head_idx ON public.whatsapp_outbox USING btree (conversation_id, created_at, id) INCLUDE (next_attempt_at) WHERE ((status = ANY (ARRAY['pending'::text, 'retry'::text])) AND ((attempts < max_attempts) OR (last_error = 'provider_accepted_finalization_pending'::text)) AND ((lower(COALESCE((payload ->> 'action'::text), ''::text)) = ANY (ARRAY['send.media'::text, 'send.audio'::text, 'send.sticker'::text])) OR (lower(COALESCE(message_type, ''::text)) = ANY (ARRAY['image'::text, 'audio'::text, 'video'::text, 'document'::text, 'sticker'::text]))));


--
-- Name: INDEX whatsapp_outbox_media_due_head_idx; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON INDEX public.whatsapp_outbox_media_due_head_idx IS 'Literal media-lane FIFO heads, isolated from high-throughput text claims.';


