-- Name: construction_daily_reports Acesso por organização daily_reports; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Acesso por organização daily_reports" ON public.construction_daily_reports USING ((organization_id IN ( SELECT organization_members.organization_id
   FROM public.organization_members
  WHERE (organization_members.user_id = ( SELECT auth.uid() AS uid)))));


