--
-- Name: meta_form_configs Admins can delete form configs; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can delete form configs" ON public.meta_form_configs FOR DELETE USING ((organization_id IN ( SELECT users.organization_id
   FROM public.users
  WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.role = 'admin'::text)))));


--
-- Name: meta_form_configs Admins can insert form configs; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can insert form configs" ON public.meta_form_configs FOR INSERT WITH CHECK ((organization_id IN ( SELECT users.organization_id
   FROM public.users
  WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.role = 'admin'::text)))));


--
-- Name: email_templates Admins can manage email templates; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can manage email templates" ON public.email_templates USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.id = ( SELECT auth.uid() AS uid)) AND ((u.role = 'admin'::text) OR (u.role = 'super_admin'::text))))));


--
-- Name: notification_settings Admins can manage own org notification settings; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can manage own org notification settings" ON public.notification_settings TO authenticated USING ((public.is_super_admin() OR ((organization_id = private.get_user_organization_id()) AND private.is_admin()))) WITH CHECK ((public.is_super_admin() OR ((organization_id = private.get_user_organization_id()) AND private.is_admin())));


--
-- Name: meta_form_configs Admins can update form configs; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can update form configs" ON public.meta_form_configs FOR UPDATE USING ((organization_id IN ( SELECT users.organization_id
   FROM public.users
  WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.role = 'admin'::text)))));


--
-- Name: meta_webhook_events Admins can view their own meta_webhook_events; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can view their own meta_webhook_events" ON public.meta_webhook_events FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.users
  WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.organization_id = meta_webhook_events.organization_id) AND ((users.role = 'admin'::text) OR (users.role = 'super_admin'::text))))));


--
-- Name: permissions Anyone can read permissions; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Anyone can read permissions" ON public.permissions FOR SELECT USING (true);


--
-- Name: available_permissions Anyone can view available permissions; Type: POLICY; Schema: public; Owner: postgres
--

