--
-- Name: lead_events Public sites can insert validated lead events; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Public sites can insert validated lead events" ON public.lead_events FOR INSERT TO authenticated, anon WITH CHECK (((organization_id IS NOT NULL) AND (event_type = ANY (ARRAY['pageview'::text, 'favorite'::text, 'form_submit'::text, 'whatsapp_click'::text, 'cta_click'::text])) AND ((length(COALESCE(page_path, ''::text)) >= 1) AND (length(COALESCE(page_path, ''::text)) <= 2048)) AND (length(COALESCE(page_title, ''::text)) <= 500) AND (length(COALESCE(referrer, ''::text)) <= 2048) AND (length(COALESCE(session_id, ''::text)) <= 200) AND (length(COALESCE(utm_source, ''::text)) <= 500) AND (length(COALESCE(utm_medium, ''::text)) <= 500) AND (length(COALESCE(utm_campaign, ''::text)) <= 500) AND (pg_column_size(COALESCE(metadata, '{}'::jsonb)) <= 32768) AND ((COALESCE(screen_width, 0) >= 0) AND (COALESCE(screen_width, 0) <= 100000)) AND ((COALESCE(screen_height, 0) >= 0) AND (COALESCE(screen_height, 0) <= 100000)) AND private.can_track_public_site(organization_id)));


