--
-- Name: announcements users read targeted active announcements; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "users read targeted active announcements" ON public.announcements FOR SELECT TO authenticated USING (((EXISTS ( SELECT 1
   FROM public.users super_admin_user
  WHERE ((super_admin_user.id = ( SELECT auth.uid() AS uid)) AND (super_admin_user.role = 'super_admin'::text)))) OR ((is_active = true) AND ((starts_at IS NULL) OR (starts_at <= now())) AND ((ends_at IS NULL) OR (ends_at >= now())) AND ((target_type = 'all'::text) OR ((target_type = 'specific'::text) AND (( SELECT auth.uid() AS uid) = ANY (target_user_ids))) OR ((target_type = 'organizations'::text) AND (EXISTS ( SELECT 1
   FROM public.organization_members om
  WHERE ((om.user_id = ( SELECT auth.uid() AS uid)) AND (om.is_active = true) AND (om.organization_id = ANY (announcements.target_organization_ids)))))) OR ((target_type = 'admins'::text) AND (EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.id = ( SELECT auth.uid() AS uid)) AND (u.role = ANY (ARRAY['admin'::text, 'super_admin'::text])))))) OR ((target_type = 'brokers'::text) AND (EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.id = ( SELECT auth.uid() AS uid)) AND (u.is_active = true) AND (lower(COALESCE(u.role, ''::text)) = ANY (ARRAY['corretor'::text, 'broker'::text, 'agent'::text, 'user'::text]))))))))));


