CREATE POLICY vimob_active_membership_guard ON public.automation_nodes AS RESTRICTIVE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.automations automation
  WHERE ((automation.id = automation_nodes.automation_id) AND private.is_org_member(automation.organization_id))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.automations automation
  WHERE ((automation.id = automation_nodes.automation_id) AND private.is_org_member(automation.organization_id)))));


