--

CREATE POLICY whatsapp_messages_select_owner_only ON public.whatsapp_messages FOR SELECT TO authenticated USING (((capture_state IS DISTINCT FROM 'suppressed'::text) AND private.whatsapp_message_epoch_matches(organization_id, conversation_id, session_id) AND (((lead_id IS NOT NULL) AND private.whatsapp_actor_can_read_lead(organization_id, lead_id, ( SELECT auth.uid() AS uid))) OR ((lead_id IS NULL) AND (EXISTS ( SELECT 1
   FROM public.whatsapp_conversations conversation
  WHERE ((conversation.id = whatsapp_messages.conversation_id) AND (conversation.organization_id = whatsapp_messages.organization_id) AND (conversation.session_id = whatsapp_messages.session_id) AND (conversation.lead_id IS NULL) AND (conversation.deleted_at IS NULL) AND (conversation.created_at > (now() - '7 days'::interval)) AND ((conversation.retired_at IS NULL) OR (conversation.unlinked_retention_v1 AND (conversation.unlinked_retention_scrubbed_at IS NULL))) AND private.whatsapp_owner_can_view_session(conversation.organization_id, conversation.session_id))))))));


